B.a96=s(["\uac1c\ubcc4\uad50\uc12d\uacfc \uc57d\uad00 \ud574\ub2f9\uc131"],t.s)
B.bBp=new A.a("gen_ai_def_2","economic_law","\uc57d\uad00 \ud574\uc11d\xb7\ucd1d\uce59","\uc57d\uad00\uc758 \uc815\uc758\xb7\uc801\uc6a9\ub300\uc0c1(\uc81c2\uc870)",'\uacc4\uc57d\ub2f9\uc0ac\uc790\uac00 \ud2b9\uc815 \uc870\ud56d\uc5d0 \uad00\ud558\uc5ec \uac1c\ubcc4\uc801\uc73c\ub85c \uad50\uc12d\ud558\uc5ec \uacc4\uc57d\ub0b4\uc6a9\uc5d0 \ubc18\uc601\ud55c \uacbd\uc6b0, \uadf8 \uc870\ud56d\uc774 \uc57d\uad00\ubc95\uc758 \uaddc\uc728 \ub300\uc0c1\uc778 "\uc57d\uad00"\uc5d0 \ud574\ub2f9\ud558\ub294\uc9c0\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?',B.a9f,0,'\uc57d\uad00\uc740 \uc0ac\uc5c5\uc790\uac00 \ub2e4\uc218\uc758 \uc0c1\ub300\ubc29\uc744 \uc0c1\ub300\ub85c "\ubbf8\ub9ac" \ub9c8\ub828\ud574 \ub454 \uc815\ud615\uc801 \uacc4\uc57d\ub0b4\uc6a9\uc744 \uaddc\uc728 \ub300\uc0c1\uc73c\ub85c \ud558\ubbc0\ub85c, \ub2f9\uc0ac\uc790\uac00 \ud2b9\uc815 \uc870\ud56d\uc5d0 \uad00\ud574 \uc2e4\uc9c8\uc801\uc73c\ub85c \uac1c\ubcc4\uad50\uc12d\uc744 \uac70\uccd0 \uacc4\uc57d\ub0b4\uc6a9\uc73c\ub85c \ubc18\uc601\ud55c \uacbd\uc6b0\uc5d0\ub294 \uadf8 \uc870\ud56d\uc774 \ub354 \uc774\uc0c1 \uc77c\ubc29\uc801\uc73c\ub85c \ubbf8\ub9ac \ub9c8\ub828\ub41c \uc57d\uad00\uc73c\ub85c \ubcf4\uae30 \uc5b4\ub824\uc6cc \uc57d\uad00\ubc95\uc758 \uaddc\uc728 \ub300\uc0c1\uc5d0\uc11c \ubc97\uc5b4\ub098\ub294 \uac83\uc774 \uc77c\ubc18\uc801\uc774\ub2e4.',B.bbq,B.a96,null)
B.aaA=s([u.zc,"\uc57d\uad00\ubc95\uc740 \uc624\uc9c1 \uc18c\ube44\uc790\uc640\uc758 \uacc4\uc57d\uc5d0\ub9cc \uc801\uc6a9\ub418\uace0 \uc0ac\uc5c5\uc790 \uac04 \uacc4\uc57d\uc5d0\ub294 \uc804\ud600 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4","\uc57d\uad00\ubc95\uc740 \uad6d\ub0b4 \uacc4\uc57d\uc5d0\ub9cc \uc801\uc6a9\ub418\uace0 \uad6d\uc81c\uacc4\uc57d\uc5d0\ub294 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4","\uc57d\uad00\ubc95\uc740 \uc11c\uba74\uacc4\uc57d\uc5d0\ub9cc \uc801\uc6a9\ub418\uace0 \uc804\uc790\uc801 \ud615\ud0dc\uc758 \uc57d\uad00\uc5d0\ub294 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4","\uc57d\uad00\ubc95\uc740 \ubb34\uc0c1\uacc4\uc57d\uc5d0\ub294 \uc804\ud600 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.b7v=s([u.zc],t.s)
B.Vm=s(["\uc57d\uad00\ubc95\uc758 \uc801\uc6a9\ub300\uc0c1"],t.s)
B.bvd=new A.a("gen_ai_def_3","economic_law","\uc57d\uad00 \ud574\uc11d\xb7\ucd1d\uce59","\uc57d\uad00\uc758 \uc815\uc758\xb7\uc801\uc6a9\ub300\uc0c1(\uc81c2\uc870)","\uc57d\uad00\ubc95\uc758 \uc801\uc6a9\ub300\uc0c1\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aaA,0,"\uc57d\uad00\ubc95\uc740 \uc18c\ube44\uc790\uc640\uc758 \uacc4\uc57d\ubfd0 \uc544\ub2c8\ub77c \uc0ac\uc5c5\uc790 \uac04 \uacc4\uc57d\uc5d0\uc11c \uc0ac\uc6a9\ub418\ub294 \uc57d\uad00\uc5d0\ub3c4 \uc6d0\uce59\uc801\uc73c\ub85c \uc801\uc6a9\ub420 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \uad6d\uc81c\uc801\uc73c\ub85c \ud1b5\uc6a9\ub418\ub294 \uc57d\uad00\uc774\ub098 \ub2e4\ub978 \ubc95\ub960\uc5d0 \ub530\ub77c \uc778\uac00\xb7\uc2b9\uc778\ubc1b\uc740 \uc57d\uad00 \ub4f1 \uc77c\ubd80 \uc608\uc678\uac00 \uc778\uc815\ub420 \uc218 \uc788\uc73c\ub098, \uc11c\uba74\xb7\uc804\uc790\uc801 \ud615\ud0dc\ub098 \uc720\uc0c1\xb7\ubb34\uc0c1 \uc5ec\ubd80\ub9cc\uc73c\ub85c \uc801\uc6a9 \uc790\uccb4\uac00 \ubc30\uc81c\ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4.",B.b7v,B.Vm,null)
B.bfv=s([u.nK,"\uace0\uac1d\uc740 \ubc18\ub4dc\uc2dc \uac1c\uc778(\uc790\uc5f0\uc778) \uc18c\ube44\uc790\ub9cc\uc744 \uc758\ubbf8\ud55c\ub2e4","\uc0ac\uc5c5\uc790\ub294 \ubc18\ub4dc\uc2dc \ub300\uae30\uc5c5\ub9cc\uc744 \uc758\ubbf8\ud55c\ub2e4","\uace0\uac1d\uc774 \ub420 \uc218 \uc788\ub294 \uc790\ub294 \ubc95\ub960\uc0c1 \ud2b9\ubcc4\ud788 \uc81c\ud55c\ub418\uc5b4 \uc788\uc9c0 \uc54a\uc740 \uc0c1\ub300\ubc29\uc744 \uc758\ubbf8\ud558\uc9c0 \uc54a\ub294\ub2e4","\uc0ac\uc5c5\uc790\uc640 \uace0\uac1d\uc758 \uad6c\ubcc4\uc740 \uacc4\uc57d\uae08\uc561\uc758 \ud06c\uae30\ub85c\ub9cc \uacb0\uc815\ub41c\ub2e4"],t.s)
B.aij=s([u.nK],t.s)
B.Y3=s(["\uc0ac\uc5c5\uc790\xb7\uace0\uac1d\uc758 \uc815\uc758"],t.s)
B.byg=new A.a("gen_ai_def_4","economic_law","\uc57d\uad00 \ud574\uc11d\xb7\ucd1d\uce59","\uc57d\uad00\uc758 \uc815\uc758\xb7\uc801\uc6a9\ub300\uc0c1(\uc81c2\uc870)",'\uc57d\uad00\ubc95\uc0c1 "\uc0ac\uc5c5\uc790"\uc640 "\uace0\uac1d"\uc758 \uad00\uacc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?',B.bfv,0,'\uc57d\uad00\ubc95\uc0c1 "\uc0ac\uc5c5\uc790"\ub294 \uc57d\uad00\uc744 \ubbf8\ub9ac \ub9c8\ub828\ud558\uc5ec \uc0c1\ub300\ubc29\uc5d0\uac8c \uacc4\uc57d\ub0b4\uc6a9\uc73c\ub85c \uc81c\uc2dc\ud558\ub294 \ub2f9\uc0ac\uc790\ub97c \ub9d0\ud558\uace0, "\uace0\uac1d"\uc740 \uadf8 \uc0c1\ub300\ubc29\uc744 \uc758\ubbf8\ud55c\ub2e4. \uace0\uac1d\uc740 \ubc18\ub4dc\uc2dc \uac1c\uc778 \uc18c\ube44\uc790\uc5d0 \ud55c\uc815\ub418\uc9c0 \uc54a\uace0 \ub2e4\ub978 \uc0ac\uc5c5\uc790\ub3c4 \uace0\uac1d\uc758 \uc9c0\uc704\uc5d0 \uc788\uc744 \uc218 \uc788\uc73c\uba70, \uc0ac\uc5c5\uc790 \uc5ed\uc2dc \uae30\uc5c5 \uaddc\ubaa8\uc640 \ubb34\uad00\ud558\uac8c \uc57d\uad00\uc744 \ub9c8\ub828\ud558\uc5ec \uc81c\uc2dc\ud558\ub294 \uc790\ub77c\uba74 \ud574\ub2f9\ud560 \uc218 \uc788\ub2e4.',B.aij,B.Y3,null)
B.Xf=s([u.BJ,"\uc804\uc790\uc801\uc73c\ub85c \ud45c\uc2dc\ub41c \uc57d\uad00\uc740 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \uc57d\uad00\ubc95\uc758 \uaddc\uc728 \ub300\uc0c1\uc774 \uc544\ub2c8\ub2e4","\uc628\ub77c\uc778 \uc774\uc6a9\uc57d\uad00\uc740 \uc0ac\uc5c5\uc790\uac00 \uc6d0\ud558\ub294 \uacbd\uc6b0\uc5d0\ub9cc \uc57d\uad00\uc73c\ub85c \ucde8\uae09\ub41c\ub2e4","\uc628\ub77c\uc778 \uc774\uc6a9\uc57d\uad00\uc740 \ubc18\ub4dc\uc2dc \ubcc4\ub3c4 \ubc95\ub960\ub85c\ub9cc \uaddc\uc728\ub418\uace0 \uc57d\uad00\ubc95\uacfc\ub294 \ubb34\uad00\ud558\ub2e4","\uc774\uc6a9\uc57d\uad00\uc740 \uace0\uac1d\uc774 \ud074\ub9ad\ud558\uc9c0 \uc54a\uc73c\uba74 \uc874\uc7ac \uc790\uccb4\uac00 \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.aWA=s([u.BJ],t.s)
B.aRm=s(["\uc804\uc790\uc57d\uad00\uc758 \uc57d\uad00\uc131"],t.s)
B.bR8=new A.a("gen_ai_def_5","economic_law","\uc57d\uad00 \ud574\uc11d\xb7\ucd1d\uce59","\uc57d\uad00\uc758 \uc815\uc758\xb7\uc801\uc6a9\ub300\uc0c1(\uc81c2\uc870)",'\uc628\ub77c\uc778 \uc11c\ube44\uc2a4 \uac00\uc785 \uc2dc \ud654\uba74\uc5d0 \ub178\ucd9c\ub418\ub294 \uc774\uc6a9\uc57d\uad00\uc774 \uc57d\uad00\ubc95\uc0c1 "\uc57d\uad00"\uc5d0 \ud574\ub2f9\ud558\ub294\uc9c0\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?',B.Xf,0,"\uc57d\uad00\uc758 \uc815\uc758\ub294 \uba85\uce6d\xb7\ud615\ud0dc\uc640 \ubb34\uad00\ud558\uac8c \ub2e4\uc218 \uc0c1\ub300\ubc29\uc5d0\uac8c \ubbf8\ub9ac \ub9c8\ub828\ub418\uc5b4 \uc81c\uc2dc\ub418\ub294 \uc815\ud615\uc801 \uacc4\uc57d\ub0b4\uc6a9\uc778\uc9c0\ub97c \uae30\uc900\uc73c\ub85c \ud558\ubbc0\ub85c, \uc628\ub77c\uc778 \uc11c\ube44\uc2a4 \uac00\uc785 \uc2dc \ub178\ucd9c\ub418\ub294 \uc774\uc6a9\uc57d\uad00\ub3c4 \uc774\ub7ec\ud55c \uc694\uac74\uc744 \ucda9\uc871\ud558\uba74 \uc57d\uad00\ubc95\uc0c1 \uc57d\uad00\uc5d0 \ud574\ub2f9\ud560 \uc218 \uc788\ub2e4. \uc11c\uba74\uc774 \uc544\ub2cc \uc804\uc790\uc801 \ud615\ud0dc\ub77c\ub294 \uc0ac\uc815\ub9cc\uc73c\ub85c \uaddc\uc728 \ub300\uc0c1\uc5d0\uc11c \uc81c\uc678\ub418\uc9c0 \uc54a\ub294\ub2e4.",B.aWA,B.aRm,null)
B.Zu=s(["\ubc18\ub4dc\uc2dc \uad00\ud560 \ud589\uc815\uccad\uc758 \uc0ac\uc804 \uc778\uac00\ub97c \ubc1b\uc544\uc57c \ud55c\ub2e4","\ub2e4\uc218\uc758 \uc0c1\ub300\ubc29\uc744 \ub300\uc0c1\uc73c\ub85c \ud560 \uac83\uc744 \uc608\uc815\ud558\uace0 \uc788\uc744 \uac83","\uacc4\uc57d\uccb4\uacb0 \uc804\uc5d0 \ubbf8\ub9ac \ub9c8\ub828\ub418\uc5b4 \uc788\uc744 \uac83","\uc77c\uc815\ud55c \ud615\uc2dd\uc73c\ub85c \uc815\ud615\ud654\ub418\uc5b4 \uc788\uc744 \uac83","\ud55c\ucabd \ub2f9\uc0ac\uc790\uac00 \uc774\ub97c \uacc4\uc57d\ub0b4\uc6a9\uc73c\ub85c \uc81c\uc2dc\ud560 \uac83"],t.s)
B.bca=s(["\ubc18\ub4dc\uc2dc \uad00\ud560 \ud589\uc815\uccad\uc758 \uc0ac\uc804 \uc778\uac00\ub97c \ubc1b\uc544\uc57c \ud55c\ub2e4"],t.s)
B.abH=s(["\uc57d\uad00\uc758 \uc131\ub9bd\uc694\uac74"],t.s)
B.bF7=new A.a("gen_ai_def_6","economic_law","\uc57d\uad00 \ud574\uc11d\xb7\ucd1d\uce59","\uc57d\uad00\uc758 \uc815\uc758\xb7\uc801\uc6a9\ub300\uc0c1(\uc81c2\uc870)",'\uc57d\uad00\ubc95\uc774 \uaddc\uc728\ud558\ub294 "\uc57d\uad00"\uc5d0 \ud574\ub2f9\ud558\uae30 \uc704\ud55c \uc694\uac74\uc73c\ub85c \ubcf4\uae30 \uc5b4\ub824\uc6b4 \uac83\uc740?',B.Zu,0,'\uc57d\uad00\uc5d0 \ud574\ub2f9\ud558\uae30 \uc704\ud574\uc11c\ub294 \ub2e4\uc218 \uc0c1\ub300\ubc29\uc744 \ub300\uc0c1\uc73c\ub85c \uc608\uc815\ud560 \uac83, \uacc4\uc57d\uccb4\uacb0 \uc804 \ubbf8\ub9ac \ub9c8\ub828\ub418\uc5b4 \uc788\uc744 \uac83, \uc77c\uc815\ud55c \ud615\uc2dd\uc73c\ub85c \uc815\ud615\ud654\ub418\uc5b4 \uc788\uc744 \uac83, \ud55c\ucabd \ub2f9\uc0ac\uc790\uac00 \uc774\ub97c \uacc4\uc57d\ub0b4\uc6a9\uc73c\ub85c \uc81c\uc2dc\ud560 \uac83 \ub4f1\uc758 \uc694\uc18c\uac00 \uc694\uad6c\ub41c\ub2e4. \ubc18\uba74 "\uad00\ud560 \ud589\uc815\uccad\uc758 \uc0ac\uc804 \uc778\uac00"\ub294 \uc57d\uad00 \ud574\ub2f9\uc131 \ud310\ub2e8\uacfc \ubb34\uad00\ud55c \uc694\uc18c\ub85c, \uc778\uac00 \uc5ec\ubd80\uc640 \uad00\uacc4\uc5c6\uc774 \uc57d\uad00\uc5d0 \ud574\ub2f9\ud560 \uc218 \uc788\ub2e4.',B.bca,B.abH,null)
B.a5O=s([u.ah,"\uc57d\uad00\uc740 \uac1c\ubcc4\uc57d\uc815\ubcf4\ub2e4 \ud56d\uc0c1 \uc6b0\uc120\ud558\uc5ec \uc801\uc6a9\ub41c\ub2e4","\uac1c\ubcc4\uc57d\uc815\uc740 \ubc18\ub4dc\uc2dc \uc11c\uba74\uc73c\ub85c\ub9cc \uc778\uc815\ub41c\ub2e4","\uac1c\ubcc4\uc57d\uc815\uacfc \uc57d\uad00\uc774 \ub2e4\ub974\uba74 \ud56d\uc0c1 \uc57d\uad00 \ub0b4\uc6a9\ub300\ub85c \uacc4\uc57d\uc774 \uc131\ub9bd\ud55c\ub2e4","\uac1c\ubcc4\uc57d\uc815 \uc6b0\uc120\uc758 \uc6d0\uce59\uc740 \uc0ac\uc5c5\uc790\uc5d0\uac8c\ub9cc \uc720\ub9ac\ud558\uac8c \uc801\uc6a9\ub41c\ub2e4"],t.s)
