B.bwD=new A.a("gen_ai_contra_4","economic_law","\uc57d\uad00 \ud574\uc11d\xb7\ucd1d\uce59","\uc791\uc131\uc790\ubd88\uc774\uc775\uc758 \uc6d0\uce59(\uc81c5\uc870 \uc81c2\ud56d)","\ubcf4\ud5d8\uc57d\uad00\uacfc \uac19\uc774 \uc804\ubb38\uc801\uc774\uace0 \ubcf5\uc7a1\ud55c \uc57d\uad00\uc5d0\uc11c \uc791\uc131\uc790\ubd88\uc774\uc775\uc758 \uc6d0\uce59\uc774 \ud2b9\ud788 \uc790\uc8fc \ubb38\uc81c\ub418\ub294 \uc774\uc720\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.aVH,0,"\ubcf4\ud5d8\uc57d\uad00\uc740 \ubcf4\uc7a5\ubc94\uc704\xb7\uba74\ucc45\uc0ac\uc720 \ub4f1\uc744 \uc815\ud558\ub294 \uc804\ubb38\uc801\uc774\uace0 \ubcf5\uc7a1\ud55c \uc870\ud56d\uc774 \ub9ce\uc544, \ubb38\uc5b8\uc758 \ub2e4\uc758\uc801 \ud574\uc11d \uac00\ub2a5\uc131\uc774 \uc0c1\ub300\uc801\uc73c\ub85c \ud06c\uac8c \ub098\ud0c0\ub098\ub294 \uacbd\ud5a5\uc774 \uc788\ub2e4. \uc774 \ub54c\ubb38\uc5d0 \uc2e4\ubb34\uc0c1 \ubcf4\ud5d8\uc57d\uad00 \uad00\ub828 \ubd84\uc7c1\uc5d0\uc11c \uc791\uc131\uc790\ubd88\uc774\uc775\uc758 \uc6d0\uce59\uc774 \uc790\uc8fc \ubb38\uc81c\ub418\uace0 \ud65c\uc6a9\ub41c\ub2e4.",B.bhs,B.awJ,null)
B.V_=s(['\uc791\uc131\uc790\ubd88\uc774\uc775\uc758 \uc6d0\ufffd\uce59\uc740 "\ud574\uc11d"\uc758 \ubb38\uc81c\uc774\uace0, \ubb34\ud6a8 \ubc95\ub9ac\ub294 \ud574\uc11d\uc744 \uac70\uccd0 \ud655\uc815\ub41c \uc870\ud56d "\ub0b4\uc6a9"\uc758 \ud6a8\ub825 \ubb38\uc81c\ub85c \uc11c\ub85c \ub2e8\uacc4\uac00 \ub2e4\ub974\ub2e4',"\ub450 \ubc95\ub9ac\ub294 \uc644\uc804\ud788 \ub3d9\uc77c\ud558\uc5ec \uad6c\ubcc4\ud560 \uc2e4\uc775\uc774 \uc5c6\ub2e4","\uc791\uc131\uc790\ubd88\uc774\uc775\uc758 \uc6d0\uce59\uc774 \uc801\uc6a9\ub418\uba74 \uadf8 \uc870\ud56d\uc740 \ud56d\uc0c1 \uc790\ub3d9\uc73c\ub85c \ubb34\ud6a8\uac00 \ub41c\ub2e4","\ubb34\ud6a8 \ubc95\ub9ac\uac00 \uc801\uc6a9\ub418\uba74 \ud574\uc11d\uc758 \ubb38\uc81c\ub294 \uc544\uc608 \ubc1c\uc0dd\ud558\uc9c0 \uc54a\ub294\ub2e4","\ub450 \ubc95\ub9ac\ub294 \uc11c\ub85c \uc591\ub9bd\ud560 \uc218 \uc5c6\ub294 \ubaa8\uc21c \uad00\uacc4\uc5d0 \uc788\ub2e4"],t.s)
B.aNI=s(['\uc791\uc131\uc790\ubd88\uc774\uc775\uc758 \uc6d0\uce59\uc740 "\ud574\uc11d"\uc758 \ubb38\uc81c\uc774\uace0, \ubb34\ud6a8 \ubc95\ub9ac\ub294 \ud574\uc11d\uc744 \uac70\uccd0 \ud655\uc815\ub41c \uc870\ud56d "\ub0b4\uc6a9"\uc758 \ud6a8\ub825 \ubb38\uc81c\ub85c \uc11c\ub85c \ub2e8\uacc4\uac00 \ub2e4\ub974\ub2e4'],t.s)
