B.bEY=new A.a("gen_ai_contra_5","economic_law","\uc57d\uad00 \ud574\uc11d\xb7\ucd1d\uce59","\uc791\uc131\uc790\ubd88\uc774\uc775\uc758 \uc6d0\uce59(\uc81c5\uc870 \uc81c2\ud56d)","\uc791\uc131\uc790\ubd88\uc774\uc775\uc758 \uc6d0\uce59\uacfc \ubd88\uacf5\uc815\uc57d\uad00\uc870\ud56d \ubb34\ud6a8 \ubc95\ub9ac\uc758 \uad00\uacc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.V_,0,'\uc791\uc131\uc790\ubd88\uc774\uc775\uc758 \uc6d0\uce59\uc740 \uc870\ud56d\uc758 \ub73b\uc774 \uba85\ubc31\ud558\uc9c0 \uc54a\uc744 \ub54c "\uc5b4\ub5bb\uac8c \ud574\uc11d\ud560 \uac83\uc778\uac00"\uc758 \ubb38\uc81c\uc778 \ubc18\uba74, \ubb34\ud6a8 \ubc95\ub9ac(\uc81c6\uc870~\uc81c14\uc870)\ub294 \ud574\uc11d\uc744 \ud1b5\ud574 \ud655\uc815\ub41c \uc870\ud56d\uc758 "\ub0b4\uc6a9" \uc790\uccb4\uac00 \ubd88\uacf5\uc815\ud558\uc5ec \ud6a8\ub825\uc744 \uc778\uc815\ud560 \uc218 \uc5c6\ub294\uc9c0\uc758 \ubb38\uc81c\uc774\ub2e4. \ub450 \ubc95\ub9ac\ub294 \uc21c\ucc28\uc801\uc73c\ub85c \uac80\ud1a0\ub420 \uc218 \uc788\ub294 \uc11c\ub85c \ub2e4\ub978 \ub2e8\uacc4\uc758 \uc7c1\uc810\uc774\ub2e4.',B.aNI,B.a4D,null)
B.Tp=s([u.q2,"\uc774\ub7ec\ud55c \uacb0\uacfc\ub294 \ud56d\uc0c1 \ubd80\ub2f9\ud558\ubbc0\ub85c \ubc95\uc6d0\uc774 \ubc18\ub4dc\uc2dc \uc0ac\uc5c5\uc790\uc5d0\uac8c \uc720\ub9ac\ud558\uac8c \uc7ac\ud574\uc11d\ud574\uc57c \ud55c\ub2e4","\uc774 \uacbd\uc6b0 \uacc4\uc57d \uc790\uccb4\uac00 \ucc98\uc74c\ubd80\ud130 \ubb34\ud6a8\uac00 \ub41c\ub2e4","\uc774 \uacbd\uc6b0 \uace0\uac1d\uc774 \uc624\ud788\ub824 \uc190\ud574\ubc30\uc0c1\ucc45\uc784\uc744 \uc9c4\ub2e4","\uc774 \uc6d0\uce59\uc774 \uc801\uc6a9\ub41c \uacb0\uacfc\ub294 \ud56d\uc0c1 \uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704\ub85c \ub2e4\ub8e8\uc5b4\uc9c4\ub2e4"],t.s)
