B.bIv=new A.a("gen_ai_case_1","economic_law","\uc57d\uad00 \ud574\uc11d\xb7\ucd1d\uce59","\uc57d\uad00 \ud574\uc11d \uc885\ud569\xb7\uc0ac\ub840",'\ubcf4\ud5d8\uc57d\uad00\uc0c1 \uba74\ucc45\uc870\ud56d\uc758 \ubb38\uc5b8\uc774 "\ucc9c\uc7ac\uc9c0\ubcc0\uc73c\ub85c \uc778\ud55c \uc190\ud574"\ub77c\uace0\ub9cc \ub418\uc5b4 \uc788\uc5b4 \ud2b9\uc815 \uc790\uc5f0\uc7ac\ud574\uac00 \uc774\uc5d0 \ud3ec\ud568\ub418\ub294\uc9c0 \ub2e4\ud22c\uc5b4\uc9c0\ub294 \uacbd\uc6b0, \ud574\uc11d \ubc29\ubc95\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?',B.ajC,0,"\uc57d\uad00 \uc870\ud56d\uc758 \ud574\uc11d\uc740 \uc6b0\uc120 \ubb38\uc5b8\xb7\ubaa9\uc801\xb7\uccb4\uacc4 \ub4f1\uc744 \uace0\ub824\ud55c \ud1b5\uc0c1\uc758 \ud574\uc11d\ubc29\ubc95\uacfc \uc2e0\uc758\uc131\uc2e4\uc758 \uc6d0\uce59\uc5d0 \ub530\ub77c \uacf5\uc815\ud558\uace0 \ud1b5\uc77c\uc801\uc73c\ub85c \uc774\ub8e8\uc5b4\uc838\uc57c \ud558\uba70, \uadf8\ub7fc\uc5d0\ub3c4 \uc870\ud56d\uc758 \uc758\ubbf8\uac00 \uba85\ubc31\ud788 \ud655\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4\uba74 \ubcf4\ucda9\uc801\uc73c\ub85c \uc791\uc131\uc790\ubd88\uc774\uc775\uc758 \uc6d0\uce59\uc5d0 \ub530\ub77c \uace0\uac1d\uc5d0\uac8c \uc720\ub9ac\ud558\uac8c \ud574\uc11d\ud558\ub294 \uc21c\uc11c\ub85c \uc811\uadfc\ud558\ub294 \uac83\uc774 \uc77c\ubc18\uc801\uc774\ub2e4.",B.anY,B.a1e,null)
B.aHJ=s([u.cN,"\uac01 \uace0\uac1d\uc774 \uc6d0\ud558\ub294 \ud574\uc11d\uc744 \uadf8\ub300\ub85c \uc778\uc815\ud574\uc57c \ud55c\ub2e4","\uba3c\uc800 \uc18c\ub97c \uc81c\uae30\ud55c \uace0\uac1d\uc758 \ud574\uc11d\uc774 \ud56d\uc0c1 \uc6b0\uc120\ud55c\ub2e4","\uc0ac\uc5c5\uc790\uac00 \uc81c\uc2dc\ud558\ub294 \ud574\uc11d\uc774 \ud56d\uc0c1 \ucd5c\uc885\uc801\uc73c\ub85c \uc778\uc815\ub41c\ub2e4","\uc774 \uacbd\uc6b0 \uc57d\uad00 \uc790\uccb4\uac00 \uc790\ub3d9\uc73c\ub85c \uc804\ubd80 \ubb34\ud6a8\uac00 \ub41c\ub2e4"],t.s)
B.akc=s([u.cN],t.s)
B.aTw=s(["\ubcf5\uc218 \uace0\uac1d \uac04 \ud574\uc11d \ub2e4\ud23c"],t.s)
B.bs3=new A.a("gen_ai_case_2","economic_law","\uc57d\uad00 \ud574\uc11d\xb7\ucd1d\uce59","\uc57d\uad00 \ud574\uc11d \uc885\ud569\xb7\uc0ac\ub840","\ub3d9\uc77c\ud55c \uc774\ub3d9\ud1b5\uc2e0 \uc11c\ube44\uc2a4 \uc57d\uad00 \uc870\ud56d\uc5d0 \ub300\ud574 \uc11c\ub85c \ub2e4\ub978 \uace0\uac1d\uc774 \uc0c1\ubc18\ub41c \ud574\uc11d\uc744 \uc8fc\uc7a5\ud558\ub294 \uacbd\uc6b0, \uc57d\uad00 \ud574\uc11d\uc758 \uc811\uadfc \ubc29\ubc95\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aHJ,0,"\uc57d\uad00\uc740 \ub2e4\uc218\uc758 \uace0\uac1d\uc5d0\uac8c \ub3d9\uc77c\ud558\uac8c \uc801\uc6a9\ub418\ub294 \uac83\uc744 \uc804\uc81c\ub85c \ud558\ubbc0\ub85c, \ud2b9\uc815 \uace0\uac1d\uc758 \uc8fc\uad00\uc801 \uc0ac\uc815\uc774\ub098 \uc120\ud638\uac00 \uc544\ub2c8\ub77c \ud3c9\uade0\uc801\uc774\uace0 \ud569\ub9ac\uc801\uc778 \uace0\uac1d\uc744 \uae30\uc900\uc73c\ub85c \ud55c \uac1d\uad00\uc801\xb7\ud1b5\uc77c\uc801 \ud574\uc11d\uc744 \uc2dc\ub3c4\ud558\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub2e4. \uc774\ub294 \uc57d\uad00 \ud574\uc11d\uc5d0\uc11c \uc77c\uad00\ub418\uac8c \uac15\uc870\ub418\ub294 \uc811\uadfc\ubc29\ubc95\uc774\ub2e4.",B.akc,B.aTw,null)
B.a1U=s([u.jn,"\ubb38\uc5b8\uc774 \uba85\ud655\ud558\uba74 \uadf8 \uacb0\uacfc\uac00 \uc544\ubb34\ub9ac \uac00\ud639\ud574\ub3c4 \uc5b4\ub5a0\ud55c \ud1b5\uc81c\ub3c4 \ubc1b\uc9c0 \uc54a\ub294\ub2e4","\ubb38\uc5b8\uc774 \uba85\ud655\ud558\uba74 \ud56d\uc0c1 \uc791\uc131\uc790\ubd88\uc774\uc775\uc758 \uc6d0\uce59\uc774 \uc801\uc6a9\ub418\uc5b4 \uace0\uac1d\uc5d0\uac8c \uc720\ub9ac\ud558\uac8c \ub4a4\uc9d1\ud78c\ub2e4","\uc774 \uacbd\uc6b0 \uacc4\uc57d \uc790\uccb4\uac00 \uc790\ub3d9\uc73c\ub85c \ud574\uc81c\ub41c\ub2e4","\uc774 \uacbd\uc6b0 \uace0\uac1d\uc740 \uc5b4\ub5a0\ud55c \uad6c\uc81c\uc218\ub2e8\ub3c4 \uac00\uc9c8 \uc218 \uc5c6\ub2e4"],t.s)
B.aGg=s([u.jn],t.s)
B.bg1=s(["\uba85\ud655\ud55c \ubb38\uc5b8\uacfc \ub0b4\uc6a9\ud1b5\uc81c\uc758 \uad00\uacc4"],t.s)
B.bpr=new A.a("gen_ai_case_3","economic_law","\uc57d\uad00 \ud574\uc11d\xb7\ucd1d\uce59","\uc57d\uad00 \ud574\uc11d \uc885\ud569\xb7\uc0ac\ub840","\uc57d\uad00 \uc870\ud56d\uc758 \ubb38\uc5b8 \uc790\uccb4\ub294 \uba85\ud655\ud558\uc9c0\ub9cc \uadf8 \ubb38\uc5b8\ub300\ub85c \uc801\uc6a9\ud558\uba74 \uace0\uac1d\uc5d0\uac8c \uc9c0\ub098\uce58\uac8c \uac00\ud639\ud55c \uacb0\uacfc\uac00 \ubc1c\uc0dd\ud558\ub294 \uacbd\uc6b0\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.a1U,0,'\uc791\uc131\uc790\ubd88\uc774\uc775\uc758 \uc6d0\uce59\uc740 \ubb38\uc5b8\uc774 \ubd88\uba85\ud655\ud55c \uacbd\uc6b0\uc5d0 \uc801\uc6a9\ub418\ub294 "\ud574\uc11d"\uc758 \ubcf4\ucda9\uc6d0\uce59\uc774\ubbc0\ub85c, \ubb38\uc5b8 \uc790\uccb4\uac00 \uba85\ud655\ud558\ub2e4\uba74 \uc774 \uc6d0\ufffd\uc9c8\uc774 \uac1c\uc785\ud560 \uc5ec\uc9c0\ub294 \uc5c6\ub2e4. \ub2e4\ub9cc \ubb38\uc5b8\uc774 \uba85\ud655\ud558\ub354\ub77c\ub3c4 \uadf8 \ub0b4\uc6a9 \uc790\uccb4\uac00 \uace0\uac1d\uc5d0\uac8c \ubd80\ub2f9\ud558\uac8c \ubd88\ub9ac\ud558\ub2e4\uba74, \ubcc4\ub3c4\ub85c \uc81c6\uc870~\uc81c14\uc870\uc758 \ubb34\ud6a8\uc0ac\uc720\uc5d0 \ud574\ub2f9\ud558\ub294\uc9c0\uac00 \uac80\ud1a0\ub420 \uc218 \uc788\uc5b4 \uace0\uac1d\uc774 \uc804\ud600 \uad6c\uc81c\ubc1b\uc9c0 \ubabb\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4.',B.aGg,B.bg1,null)
B.ZQ=s([u.eX,"\ud648\ud398\uc774\uc9c0 \uc548\ub0b4\ubb38\uad6c\ub294 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \uc57d\uad00 \ud574\uc11d\uacfc \ubb34\uad00\ud558\ub2e4","\ud648\ud398\uc774\uc9c0 \uc548\ub0b4\ubb38\uad6c\uac00 \uc788\uc73c\uba74 \uc57d\uad00\uc740 \uc790\ub3d9\uc73c\ub85c \ubb34\ud6a8\uac00 \ub41c\ub2e4","\ud648\ud398\uc774\uc9c0 \uc548\ub0b4\ubb38\uad6c\ub294 \ubc18\ub4dc\uc2dc \uc57d\uad00\ubcf4\ub2e4 \uc6b0\uc120\ud558\uc5ec \uc808\ub300\uc801\uc73c\ub85c \uc801\uc6a9\ub41c\ub2e4","\ud648\ud398\uc774\uc9c0 \uc548\ub0b4\ubb38\uad6c\ub294 \uc0ac\uc5c5\uc790\uac00 \uc6d0\ud560 \ub54c\ub9cc \ud6a8\ub825\uc774 \uc788\ub2e4"],t.s)
B.aE2=s([u.eX],t.s)
B.aFe=s(["\ubd80\uc218\uc801 \uc548\ub0b4\uc790\ub8cc\uc640 \ud574\uc11d"],t.s)
B.bHb=new A.a("gen_ai_case_4","economic_law","\uc57d\uad00 \ud574\uc11d\xb7\ucd1d\uce59","\uc57d\uad00 \ud574\uc11d \uc885\ud569\xb7\uc0ac\ub840","\uc0ac\uc5c5\uc790\uac00 \uc57d\uad00\uacfc \ubcc4\ub3c4\ub85c \ud648\ud398\uc774\uc9c0\uc5d0 \uac8c\uc2dc\ud55c \uc548\ub0b4\ubb38\uad6c\uac00 \uc57d\uad00 \ud574\uc11d\uc5d0 \ucc38\uace0\ub420 \uc218 \uc788\ub294\uc9c0\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.ZQ,0,"\uc57d\uad00 \uc870\ud56d\uc758 \uc758\ubbf8\ub97c \ud655\uc815\ud560 \ub54c\ub294 \uacc4\uc57d \uccb4\uacb0\uc758 \uacbd\uc704, \uac70\ub798\uad00\ud589, \uad00\ub828\ud558\uc5ec \uc0ac\uc5c5\uc790\uac00 \uace0\uac1d\uc5d0\uac8c \uc81c\uacf5\ud55c \uc548\ub0b4\uc790\ub8cc \ub4f1 \uc5ec\ub7ec \uc0ac\uc815\uc774 \ud568\uaed8 \uace0\ub824\ub420 \uc218 \uc788\ub2e4. \ud648\ud398\uc774\uc9c0 \uc548\ub0b4\ubb38\uad6c\uac00 \uc57d\uad00\uacfc \ub2e4\ub978 \ub0b4\uc6a9\uc774\ub77c\uba74 \uadf8 \uc790\uccb4\ub85c \uac1c\ubcc4\uc57d\uc815\uc5d0 \uc900\ud558\ub294 \uc758\ubbf8\ub97c \uac00\uc9c8 \uc218\ub3c4 \uc788\uc5b4, \uc870\ud56d \ud574\uc11d\uc5d0 \ucc38\uace0\uc790\ub8cc\ub85c \ud65c\uc6a9\ub420 \uc218 \uc788\ub2e4.",B.aE2,B.aFe,null)
B.b7q=s([u.re,"\ubb34\ud6a8\uc0ac\uc720\ubd80\ud130 \uac80\ud1a0\ud558\uace0 \uadf8 \ub2e4\uc74c\uc5d0 \uc57d\uad00 \ud574\ub2f9\uc131\uc744 \ud655\uc778\ud55c\ub2e4","\uc791\uc131\uc790\ubd88\uc774\uc775\uc758 \uc6d0\uce59\uc744 \uac00\uc7a5 \uba3c\uc800 \uc801\uc6a9\ud558\uace0 \uadf8 \ub2e4\uc74c \uc57d\uad00 \ud574\ub2f9\uc131\uc744 \uac80\ud1a0\ud55c\ub2e4","\uac1c\ubcc4\uc57d\uc815 \uc874\ubd80\ub294 \uc804\ud600 \uac80\ud1a0\ud560 \ud544\uc694\uac00 \uc5c6\ub2e4","\uc774\ub7ec\ud55c \uac80\ud1a0 \uc21c\uc11c\ub294 \ubc95\ub960\uc0c1 \uc815\ud574\uc9c4 \ubc14\uac00 \uc5c6\uc5b4 \uc0ac\uc5c5\uc790\uac00 \uc784\uc758\ub85c \uc815\ud55c\ub2e4"],t.s)
B.b8O=s([u.re],t.s)
B.bhD=s(["\uc57d\uad00 \ubd84\uc7c1 \uac80\ud1a0\uc758 \uc77c\ubc18\uc801 \uc21c\uc11c"],t.s)
B.bql=new A.a("gen_ai_case_5","economic_law","\uc57d\uad00 \ud574\uc11d\xb7\ucd1d\uce59","\uc57d\uad00 \ud574\uc11d \uc885\ud569\xb7\uc0ac\ub840","\uc57d\uad00 \ud574\uc11d\xb7\ucd1d\uce59 \uad00\ub828 \uc870\ubb38\ub4e4\uc744 \uc885\ud569\ud560 \ub54c, \uc57d\uad00 \ubd84\uc7c1\uc744 \uac80\ud1a0\ud558\ub294 \uc77c\ubc18\uc801 \uc21c\uc11c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.b7q,0,"\uc57d\uad00 \ubd84\uc7c1\uc740 \ud1b5\uc0c1 \u2460 \ubb38\uc81c\ub41c \uc870\ud56d\uc774 \uc57d\uad00\uc5d0 \ud574\ub2f9\ud558\ub294\uc9c0, \u2461 \uac1c\ubcc4\uc57d\uc815\uc73c\ub85c \ubcfc \uc0ac\uc815\uc774 \uc788\ub294\uc9c0, \u2462 \uc2e0\uc758\uc131\uc2e4\xb7\ud1b5\uc77c\uc801 \ud574\uc11d\uc744 \ud1b5\ud574 \uc870\ud56d\uc758 \uc758\ubbf8\ub97c \ud655\uc815\ud558\uace0, \u2463 \uadf8\ub798\ub3c4 \ubd88\uba85\ud655\ud558\uba74 \uc791\uc131\uc790\ubd88\uc774\uc775\uc758 \uc6d0\uce59\uc744 \uc801\uc6a9\ud558\uba70, \u2464 \uc774\ub807\uac8c \ud655\uc815\ub41c \ub0b4\uc6a9\uc774 \uc81c6\uc870~\uc81c14\uc870\uc758 \ubb34\ud6a8\uc0ac\uc720\uc5d0 \ud574\ub2f9\ud558\ub294\uc9c0\ub97c \uac80\ud1a0\ud558\ub294 \uc21c\uc11c\ub85c \ub17c\ub9ac\ub97c \uc804\uac1c\ud558\ub294 \uac83\uc774 \uc77c\ubc18\uc801\uc774\ub2e4.",B.b8O,B.bhD,null)
B.aRb=s([u.kD,"\uc0ac\uc5c5\uc790\uc758 \uc774\uc724 \uadf9\ub300\ud654\ub9cc\uc744 \uc720\uc77c\ud55c \ubaa9\ud45c\ub85c \ud55c\ub2e4","\uace0\uac1d\uc774 \ud56d\uc0c1 \ubb34\uc870\uac74 \uc2b9\uc18c\ud558\ub3c4\ub85d \ud558\ub294 \uac83\uc774 \ubaa9\ud45c\uc774\ub2e4","\uc57d\uad00 \uc790\uccb4\uc758 \uc0ac\uc6a9\uc744 \uc804\uba74 \uae08\uc9c0\ud558\ub824\ub294 \uac83\uc774 \ubaa9\ud45c\uc774\ub2e4","\ubc95\uc6d0\uc758 \uc7ac\ud310 \ubd80\ub2f4\uc744 \uc904\uc774\ub294 \uac83\uc774 \uc720\uc77c\ud55c \ubaa9\ud45c\uc774\ub2e4"],t.s)
B.aLg=s([u.kD],t.s)
B.aiY=s(["\uc57d\uad00 \ud574\uc11d\xb7\ucd1d\uce59 \uaddc\uc815\uc758 \ubaa9\uc801"],t.s)
B.bEN=new A.a("gen_ai_case_6","economic_law","\uc57d\uad00 \ud574\uc11d\xb7\ucd1d\uce59","\uc57d\uad00 \ud574\uc11d \uc885\ud569\xb7\uc0ac\ub840","\uc57d\uad00 \ud574\uc11d\xb7\ucd1d\uce59 \uad00\ub828 \uaddc\uc815\ub4e4\uc774 \uad81\uadf9\uc801\uc73c\ub85c \ucd94\uad6c\ud558\ub294 \uac00\uce58\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.aRb,0,"\uc57d\uad00 \ud574\uc11d\xb7\ucd1d\uce59 \uaddc\uc815\ub4e4\uc740 \ub2e4\uc218\uc758 \uace0\uac1d\uc5d0\uac8c \ud68d\uc77c\uc801\uc73c\ub85c \uc801\uc6a9\ub418\ub294 \uc57d\uad00 \uac70\ub798\uc758 \ud2b9\uc131\uc744 \uace0\ub824\ud558\uc5ec, \ud574\uc11d\uc758 \uacf5\uc815\uc131\uacfc \uc608\uce21\uac00\ub2a5\uc131\uc744 \ud655\ubcf4\ud558\uace0 \uace0\uac1d\uc774 \ubd80\ub2f9\ud558\uac8c \ubd88\ub9ac\ud55c \uc9c0\uc704\uc5d0 \ub193\uc774\uc9c0 \uc54a\ub3c4\ub85d \ud558\ub824\ub294 \uacf5\ud1b5\ub41c \uac00\uce58\ub97c \ucd94\uad6c\ud55c\ub2e4. \uc774\ub294 \uc0ac\uc5c5\uc790\uc758 \uc774\uc775\ub9cc\uc744 \uc704\ud55c \uac83\ub3c4, \uace0\uac1d\uc758 \ubb34\uc870\uac74\uc801 \uc2b9\ub9ac\ub97c \ubcf4\uc7a5\ud558\ub824\ub294 \uac83\ub3c4 \uc544\ub2cc \uade0\ud615\uc7a1\ud78c \uc811\uadfc\uc774\ub2e4.",B.aLg,B.aiY,null)
B.aO_=s(["\uc0ac\uc5c5\uc790 \ubc0f \uc0ac\uc5c5\uc790\ub2e8\uccb4\ub294 \ud45c\uc900\uc774 \ub420 \uc57d\uad00\uc744 \ub9c8\ub828\ud558\uc5ec \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uc5d0 \uadf8 \uc2ec\uc0ac\ub97c \uccad\uad6c\ud560 \uc218 \uc788\ub2e4","\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\ub294 \uc18c\ube44\uc790\ub2e8\uccb4 \ub4f1\uc758 \uc694\uccad\uc774 \uc788\ub294 \uacbd\uc6b0 \ud45c\uc900\uc57d\uad00\uc758 \uc81c\uc815\xb7\uac1c\uc815\uc548\uc744 \ub9c8\ub828\ud558\uc5ec \uc2ec\uc0ac\uccad\uad6c\ud560 \uac83\uc744 \uad8c\uace0\ud560 \uc218 \uc788\ub2e4","\ud45c\uc900\uc57d\uad00 \ud45c\uc9c0\ub97c \uc0ac\uc6a9\ud558\ub294 \uc0ac\uc5c5\uc790\ub294 \ud45c\uc900\uc57d\uad00\uacfc \ub2e4\ub974\uac8c \uc815\ud55c \uc8fc\uc694 \ub0b4\uc6a9\uc774 \uc788\uc73c\uba74 \ud45c\uc900\uc57d\uad00\ubcf4\ub2e4 \uace0\uac1d\uc5d0\uac8c \ub354 \ubd88\ub9ac\ud55c \ub0b4\uc6a9\ub3c4 \uc790\uc720\ub86d\uac8c \uc0ac\uc6a9\ud560 \uc218 \uc788\ub2e4","\ud45c\uc900\uc57d\uad00\uacfc \ub2e4\ub974\uac8c \uc815\ud55c \uc8fc\uc694 \ub0b4\uc6a9\uc740 \uace0\uac1d\uc774 \uc54c\uae30 \uc27d\uac8c \ud45c\uc2dc\ud558\uc5ec\uc57c \ud55c\ub2e4","\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\ub294 \ud45c\uc900\uc57d\uad00\uc758 \uc0ac\uc6a9\uc744 \ud65c\uc131\ud654\ud558\uae30 \uc704\ud558\uc5ec \ud45c\uc900\uc57d\uad00 \ud45c\uc9c0\ub97c \uc815\ud560 \uc218 \uc788\ub2e4"],t.s)
B.aiT=s(["\uadf8\ub7f0 \ubd88\ub9ac\ud55c \ub0b4\uc6a9\uc740 \ubcc4\ub3c4\ub85c \uc54c\uae30 \uc27d\uac8c \ud45c\uc2dc\ud558\uc9c0 \uc54a\ub294 \ud55c \ud6a8\ub825\uc774 \uc81c\ud55c\ub41c\ub2e4"],t.s)
B.ab1=s(["\ud45c\uc900\uc57d\uad00","\ud45c\uc900\uc57d\uad00 \ud45c\uc9c0"],t.s)
B.bI5=new A.a("gen_al_2","economic_law","\ud45c\uc900\uc57d\uad00",null,"\uc57d\uad00\uc758 \uaddc\uc81c\uc5d0 \uad00\ud55c \ubc95\ub960\uc0c1 \ud45c\uc900\uc57d\uad00 \uc81c\ub3c4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aO_,2,'\uc57d\uad00\ubc95 \uc81c19\uc870\uc7583\uc740 \uc0ac\uc5c5\uc790 \ubc0f \uc0ac\uc5c5\uc790\ub2e8\uccb4\uac00 \ud45c\uc900\uc57d\uad00\uacfc \ub2e4\ub978 \ub0b4\uc6a9\uc758 \uc57d\uad00\uc744 \uc0ac\uc6a9\ud558\uba74\uc11c \ud45c\uc900\uc57d\uad00 \ud45c\uc9c0\ub97c \uc0ac\uc6a9\ud558\ub294 \uacbd\uc6b0, \ud45c\uc900\uc57d\uad00\ubcf4\ub2e4 \uace0\uac1d\uc5d0\uac8c \ubd88\ub9ac\ud55c \ub0b4\uc6a9\uc740 \uba85\uc2dc\uc801\uc73c\ub85c \ud45c\uc2dc\ud558\uc9c0 \uc54a\uc73c\uba74 \ud45c\uc900\uc57d\uad00\uacfc \uac19\uc740 \ub0b4\uc6a9\uc73c\ub85c \ud569\uc758\ub41c \uac83\uc73c\ub85c \ubcf8\ub2e4\ub294 \ucde8\uc9c0\uc758 \uaddc\uc815\uc744 \ub450\uc5b4 \uace0\uac1d \ubcf4\ud638\ub97c \uaf80\ud558\uace0 \uc788\ub2e4. \uc989 \ud45c\uc900\uc57d\uad00 \ud45c\uc9c0\ub97c \uc0ac\uc6a9\ud558\uba74\uc11c \uace0\uac1d\uc5d0\uac8c \ubd88\ub9ac\ud55c \ub0b4\uc6a9\uc744 "\uc790\uc720\ub86d\uac8c" \uc815\ud560 \uc218 \uc788\ub2e4\ub294 \uc124\uba85\uc740 \uc633\uc9c0 \uc54a\uc73c\uba70, \uc624\ud788\ub824 \uadf8\ub7f0 \ubd88\ub9ac\ud55c \ub0b4\uc6a9\uc740 \ubcc4\ub3c4\ub85c \uc54c\uae30 \uc27d\uac8c \ud45c\uc2dc\ud558\uc9c0 \uc54a\ub294 \ud55c \ud6a8\ub825\uc774 \uc81c\ud55c\ub41c\ub2e4. \ub098\uba38\uc9c0 \uc120\ud0dd\uc9c0\ub4e4, \uc989 \uc0ac\uc5c5\uc790\ub2e8\uccb4\uc758 \uc2ec\uc0ac\uccad\uad6c\uad8c, \uacf5\uc815\uc704\uc758 \ud45c\uc900\uc57d\uad00 \uad8c\uace0\uad8c, \ud45c\uc900\uc57d\uad00 \ud45c\uc9c0 \uc81c\uc815\uad8c\uc740 \ubaa8\ub450 \ubc95\uc5d0 \uaddc\uc815\ub41c \uc815\ud655\ud55c \ub0b4\uc6a9\uc774\ub2e4.',B.aiT,B.ab1,null)
B.bdG=s([u.ne,"\ubaa8\ub4e0 \uc0ac\uc5c5\uc790\uc5d0\uac8c \ub3d9\uc77c\ud55c \uac00\uaca9\uc744 \uac15\uc81c\ud558\uae30 \uc704\ud55c \uc81c\ub3c4","\uc0ac\uc5c5\uc790 \uac04\uc758 \ub2f4\ud569\uc744 \uacf5\uc2dd\uc801\uc73c\ub85c \ud5c8\uc6a9\ud558\ub294 \uc81c\ub3c4","\uc18c\ube44\uc790\uc5d0\uac8c\ub9cc \uc77c\ubc29\uc801\uc73c\ub85c \ubd88\ub9ac\ud55c \uc57d\uad00\uc744 \ub9cc\ub4dc\ub294 \uc81c\ub3c4","\ud45c\uc900\uc57d\uad00\uc740 \uc624\uc9c1 \ud615\uc0ac\ucc98\ubc8c\uc744 \uc704\ud55c \ucc38\uace0\uc790\ub8cc\uc5d0 \ubd88\uacfc\ud558\ub2e4"],t.s)
