B.bo8=new A.a("gen_std_intro_1","economic_law","\ud45c\uc900\uc57d\uad00","\ud45c\uc900\uc57d\uad00\uc758 \uc758\uc758\xb7\uc81c\uc815 \uc808\ucc28","\ud45c\uc900\uc57d\uad00 \uc81c\ub3c4\uc758 \uc758\uc758\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.bdG,0,"\ud45c\uc900\uc57d\uad00 \uc81c\ub3c4\ub294 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uc758 \uc2ec\uc0ac\ub97c \uac70\uccd0 \ubd88\uacf5\uc815 \uc18c\uc9c0\ub97c \uc904\uc778 \ud45c\uc900\uc801\uc778 \ub0b4\uc6a9\uc758 \uc57d\uad00\uc744 \ub9c8\ub828\ud558\uace0, \uc0ac\uc5c5\uc790\ub4e4\uc774 \uc774\ub97c \uc0ac\uc6a9\ud558\ub3c4\ub85d \uc720\ub3c4\ud568\uc73c\ub85c\uc368 \uc57d\uad00\uc73c\ub85c \uc778\ud55c \ubd84\uc7c1\uc744 \uc608\ubc29\ud558\uace0 \uac70\ub798\uc758 \uacf5\uc815\uc131\uc744 \ub192\uc774\ub824\ub294 \uc81c\ub3c4\uc774\ub2e4.",B.a2o,B.agd,null)
B.b4j=s(["\uc0ac\uc5c5\uc790 \ubc0f \uc0ac\uc5c5\uc790\ub2e8\uccb4","\uc624\uc9c1 \uac1c\ubcc4 \uc18c\ube44\uc790 1\uc778\ub9cc \uac00\ub2a5\ud558\ub2e4","\uc624\uc9c1 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c \uc704\uc6d0\uc7a5 \ubcf8\uc778\ub9cc \uac00\ub2a5\ud558\ub2e4","\uc624\uc9c1 \uad6d\ud68c\uc758\uc6d0\ub9cc \uac00\ub2a5\ud558\ub2e4","\uc624\uc9c1 \ubc95\uc6d0\ub9cc \uac00\ub2a5\ud558\ub2e4"],t.s)
