B.bv7=new A.a("gen_std_effect_3","economic_law","\ud45c\uc900\uc57d\uad00","\ud45c\uc900\uc57d\uad00 \ud45c\uc9c0 \uc0ac\uc6a9\uc758 \ud6a8\uacfc","\ud45c\uc900\uc57d\uad00 \ud45c\uc9c0\ub97c \ud5c8\uc704\ub85c \uc0ac\uc6a9\ud558\ub294 \ud589\uc704\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aF3,0,"\ud45c\uc900\uc57d\uad00 \ud45c\uc9c0\ub97c \uc0ac\uc6a9\ud558\uba74\uc11c \uc2e4\uc81c\ub85c\ub294 \ud45c\uc900\uc57d\uad00\uacfc \ub2e4\ub978, \uace0\uac1d\uc5d0\uac8c \ubd88\ub9ac\ud55c \ub0b4\uc6a9\uc744 \uc54c\uae30 \uc27d\uac8c \ud45c\uc2dc\ud558\uc9c0 \uc54a\uace0 \uc0ac\uc6a9\ud558\ub294 \uac83\uc740 \uace0\uac1d\uc758 \uc2e0\ub8b0\ub97c \uc800\ubc84\ub9ac\ub294 \ud589\uc704\ub85c\uc11c \ubb38\uc81c\ub420 \uc218 \uc788\uc73c\uba70, \uc774 \uacbd\uc6b0 \ubc95\uc740 \uadf8 \ubd88\ub9ac\ud55c \ub0b4\uc6a9\uc744 \ud45c\uc900\uc57d\uad00\uacfc \uac19\uc740 \ub0b4\uc6a9\uc73c\ub85c \ud569\uc758\ub41c \uac83\uc73c\ub85c \ubcf4\uc544 \uace0\uac1d\uc744 \ubcf4\ud638\ud55c\ub2e4.",B.ava,B.adH,null)
B.aAl=s(["\uadf8 \uc704\uc57d\uae08 \uc870\ud56d\uc740 \ud45c\uc900\uc57d\uad00\uacfc \uac19\uc740 \ub0b4\uc6a9\uc73c\ub85c \ud569\uc758\ub41c \uac83\uc73c\ub85c \ucde8\uae09\ub420 \uc218 \uc788\ub2e4","\uac00\ub9f9\ubcf8\ubd80\uac00 \uc815\ud55c \uc704\uc57d\uae08 \uc870\ud56d\uc774 \uadf8\ub300\ub85c \uc720\ud6a8\ud558\uac8c \uc801\uc6a9\ub41c\ub2e4","\ud45c\uc900\uc57d\uad00 \ud45c\uc9c0 \uc0ac\uc6a9 \uc5ec\ubd80\ub294 \uc704\uc57d\uae08 \uc870\ud56d\uc758 \ud6a8\ub825\uacfc \uc804\ud600 \ubb34\uad00\ud558\ub2e4","\uac00\ub9f9\uc810\uc740 \uc774\uc5d0 \ub300\ud574 \uc5b4\ub5a0\ud55c \uad6c\uc81c\uc218\ub2e8\ub3c4 \uac16\uc9c0 \ubabb\ud55c\ub2e4","\uc774 \uacbd\uc6b0 \uac00\ub9f9\uacc4\uc57d \uc804\uccb4\uac00 \uc790\ub3d9\uc73c\ub85c \ubb34\ud6a8\uac00 \ub41c\ub2e4"],t.s)
B.bbf=s(["\uadf8 \uc704\uc57d\uae08 \uc870\ud56d\uc740 \ud45c\uc900\uc57d\uad00\uacfc \uac19\uc740 \ub0b4\uc6a9\uc73c\ub85c \ud569\uc758\ub41c \uac83\uc73c\ub85c \ucde8\uae09\ub420 \uc218 \uc788\ub2e4"],t.s)
