B.bHp=new A.a("gen_std_effect_4","economic_law","\ud45c\uc900\uc57d\uad00","\ud45c\uc900\uc57d\uad00 \ud45c\uc9c0 \uc0ac\uc6a9\uc758 \ud6a8\uacfc","\uac00\ub9f9\ubcf8\ubd80\uac00 \ud45c\uc900\uc57d\uad00 \ud45c\uc9c0\ub97c \uc0ac\uc6a9\ud558\uba74\uc11c \uc2e4\uc81c \uac00\ub9f9\uacc4\uc57d\uc11c\uc5d0\ub294 \ud45c\uc900\uc57d\uad00\ubcf4\ub2e4 \uac00\ub9f9\uc810\uc5d0 \ubd88\ub9ac\ud55c \uc704\uc57d\uae08 \uc870\ud56d\uc744 \uc54c\uae30 \uc27d\uac8c \ud45c\uc2dc\ud558\uc9c0 \uc54a\uace0 \ub123\uc740 \uacbd\uc6b0\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.aAl,0,"\uac00\ub9f9\ubcf8\ubd80\uac00 \ud45c\uc900\uc57d\uad00 \ud45c\uc9c0\ub97c \uc0ac\uc6a9\ud558\uba74\uc11c \uc2e4\uc81c\ub85c\ub294 \ud45c\uc900\uc57d\uad00\ubcf4\ub2e4 \uac00\ub9f9\uc810\uc5d0 \ubd88\ub9ac\ud55c \uc704\uc57d\uae08 \uc870\ud56d\uc744 \uc54c\uae30 \uc27d\uac8c \ud45c\uc2dc\ud558\uc9c0 \uc54a\uc740 \uacbd\uc6b0, \uadf8 \uc704\uc57d\uae08 \uc870\ud56d\uc740 \ud45c\uc900\uc57d\uad00\uacfc \uac19\uc740 \ub0b4\uc6a9\uc73c\ub85c \ud569\uc758\ub41c \uac83\uc73c\ub85c \ucde8\uae09\ub418\uc5b4 \uac00\ub9f9\uc810\uc774 \ubcf4\ud638\ubc1b\uc744 \uc218 \uc788\ub2e4.",B.bbf,B.a6t,null)
B.a4V=s([u.wV,"\ud45c\uc900\uc57d\uad00\uc740 \uac00\ub9f9\uac70\ub798\uc0ac \uc2e4\ubb34\uc640 \uc804\ud600 \uad00\ub828\uc774 \uc5c6\ub2e4","\ud45c\uc900\uc57d\uad00\uc740 \uc624\uc9c1 \ud559\ubb38\uc801 \ub17c\uc758 \ub300\uc0c1\uc77c \ubfd0 \uc2e4\ubb34\uc801 \uc758\ubbf8\uac00 \uc5c6\ub2e4","\ud45c\uc900\uc57d\uad00\uc740 \uac00\ub9f9\uac70\ub798\uc0ac\uc758 \uc5c5\ubb34 \ubc94\uc704\ub97c \ucd95\uc18c\uc2dc\ud0a4\uae30\ub9cc \ud55c\ub2e4","\ud45c\uc900\uc57d\uad00\uc740 \uac00\ub9f9\uacc4\uc57d\uc11c \uc791\uc131\uc744 \uc624\ud788\ub824 \uc5b4\ub835\uac8c \ub9cc\ub4e0\ub2e4"],t.s)
