B.bs7=new A.a("gen_iv_method_4","economic_law","\uc870\uc0ac\uc808\ucc28","\uc870\uc0ac\ubc29\ubc95\xb7\uc870\uc0ac\uad8c\ud55c","\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uac00 \uc0ac\uc5c5\uc790\uc5d0\uac8c \uc790\ub8cc \uc81c\ucd9c\uc744 \uc694\uad6c\ud560 \uc218 \uc788\ub294 \ubc94\uc704\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.b8J,0,"\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uc758 \uc790\ub8cc \uc81c\ucd9c \uc694\uad6c\ub294 \ubb34\uc81c\ud55c\uc801\uc778 \uac83\uc774 \uc544\ub2c8\ub77c, \uc870\uc0ac\uc758 \ubaa9\uc801\uc744 \ub2ec\uc131\ud558\uae30 \uc704\ud574 \ud544\uc694\ud55c \ubc94\uc704 \ub0b4\uc5d0\uc11c \uc774\ub8e8\uc5b4\uc9c0\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub2e4. \uc774\ub294 \uc870\uc0ac \ub300\uc0c1\uc790\uc758 \uacfc\ub3c4\ud55c \ubd80\ub2f4\uc774\ub098 \uc0ac\uc0dd\ud65c\xb7\uc601\uc5c5\ube44\ubc00 \uce68\ud574\ub97c \ubc29\uc9c0\ud558\uae30 \uc704\ud55c \ud569\ub9ac\uc801 \uc81c\ud55c\uc774\ub2e4.",B.ajT,B.aA0,null)
B.ala=s(["\uc870\uc0ac \ubaa9\uc801\uc744 \ub2ec\uc131\ud55c \ud6c4\uc5d0\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \uc790\ub8cc\ub97c \ubc18\ud658\ud558\ub294 \uac83\uc774 \ubc14\ub78c\uc9c1\ud558\ub2e4","\uc870\uc0ac \uacfc\uc815\uc5d0\uc11c \ud655\ubcf4\ud55c \uc790\ub8cc\ub294 \uc601\uad6c\uc801\uc73c\ub85c \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uac00 \ubcf4\uc720\ud55c\ub2e4","\uc790\ub8cc\ub294 \uc870\uc0ac \uc885\ub8cc \uc5ec\ubd80\uc640 \ubb34\uad00\ud558\uac8c \ubc18\ud658\ud560 \ud544\uc694\uac00 \uc804\ud600 \uc5c6\ub2e4","\uc790\ub8cc \ubc18\ud658\uc740 \uc0ac\uc5c5\uc790\uac00 \uc18c\uc1a1\uc744 \uc81c\uae30\ud574\uc57c\ub9cc \uac00\ub2a5\ud558\ub2e4","\uc790\ub8cc\ub294 \uc870\uc0ac \uac1c\uc2dc\uc640 \ub3d9\uc2dc\uc5d0 \uc790\ub3d9\uc73c\ub85c \ud3d0\uae30\ub418\uc5b4\uc57c \ud55c\ub2e4"],t.s)
B.awE=s(["\uc870\uc0ac \ubaa9\uc801\uc744 \ub2ec\uc131\ud55c \ud6c4\uc5d0\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \uc790\ub8cc\ub97c \ubc18\ud658\ud558\ub294 \uac83\uc774 \ubc14\ub78c\uc9c1\ud558\ub2e4"],t.s)
