B.bEQ=new A.a("gen_iv_method_5","economic_law","\uc870\uc0ac\uc808\ucc28","\uc870\uc0ac\ubc29\ubc95\xb7\uc870\uc0ac\uad8c\ud55c","\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c \uc870\uc0ac \uacfc\uc815\uc5d0\uc11c \ud655\ubcf4\ud55c \uc790\ub8cc\uc758 \ubcf4\uad00\xb7\ubc18\ud658\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.ala,0,"\uc870\uc0ac \uacfc\uc815\uc5d0\uc11c \uc0ac\uc5c5\uc790\ub85c\ubd80\ud130 \uc81c\ucd9c\ubc1b\uac70\ub098 \ud655\ubcf4\ud55c \uc790\ub8cc\ub294 \uc870\uc0ac \ubaa9\uc801 \ub2ec\uc131\uc5d0 \ud544\uc694\ud55c \ubc94\uc704\uc5d0\uc11c\ub9cc \ud65c\uc6a9\ub418\uc5b4\uc57c \ud558\uba70, \uadf8 \ubaa9\uc801\uc744 \ub2ec\uc131\ud55c \uc774\ud6c4\uc5d0\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \uc774\ub97c \ubc18\ud658\ud558\ub294 \uac83\uc774 \ubc14\ub78c\uc9c1\ud558\ub2e4\ub294 \uac83\uc774 \uc77c\ubc18\uc801\uc778 \uc808\ucc28\uc801 \uc6d0\uce59\uc73c\ub85c \uc774\ud574\ub41c\ub2e4.",B.awE,B.aBk,null)
B.aNZ=s([u.vW,"\uc870\uc0ac \uacfc\uc815\uc5d0\uc11c \uc54c\uac8c \ub41c \uc601\uc5c5\ube44\ubc00\uc740 \uc544\ubb34\ub7f0 \uc81c\ud55c \uc5c6\uc774 \uacf5\uac1c\ud560 \uc218 \uc788\ub2e4","\uc601\uc5c5\ube44\ubc00\uc740 \uc870\uc0ac \ub300\uc0c1\uc5d0\uc11c \ub2f9\uc5f0\ud788 \uc81c\uc678\ub418\uc5b4 \ud655\uc778 \uc790\uccb4\uac00 \ubd88\uac00\ub2a5\ud558\ub2e4","\uc601\uc5c5\ube44\ubc00\uc744 \uc54c\uac8c \ub418\uba74 \ubc18\ub4dc\uc2dc \uc5b8\ub860\uc5d0 \uacf5\ud45c\ud574\uc57c \ud55c\ub2e4","\uc601\uc5c5\ube44\ubc00 \ubcf4\ud638\ub294 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uc758 \uc870\uc0ac\uc640 \uc804\ud600 \uad00\ub828\uc774 \uc5c6\ub294 \ubb38\uc81c\uc774\ub2e4"],t.s)
