B.aQa=s(["\uc2ec\uc0ac\ubcf4\uace0\uc11c\uc5d0 \ub300\ud55c \uc758\uacac\uc81c\ucd9c\uad8c"],t.s)
B.bHl=new A.a("gen_iv_right_4","economic_law","\uc870\uc0ac\uc808\ucc28","\ud53c\uc870\uc0ac\uc790\uc758 \uad8c\ub9ac\xb7\uc758\ubb34","\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c \uc2ec\uc0ac\uad00\uc774 \uc870\uc0ac \uacb0\uacfc \uc791\uc131\ud558\ub294 \uc2ec\uc0ac\ubcf4\uace0\uc11c\uc5d0 \ub300\ud574 \ud53c\uc2ec\uc778\uc774 \uac16\ub294 \uc808\ucc28\uc801 \uad8c\ub9ac\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.b0p,0,"\uc2ec\uc0ac\uad00\uc774 \uc870\uc0ac\ub97c \ub9c8\uce58\uace0 \uc2ec\uc0ac\ubcf4\uace0\uc11c\ub97c \uc791\uc131\ud558\uba74, \ud53c\uc2ec\uc778(\uc870\uc0ac\ub300\uc0c1 \uc0ac\uc5c5\uc790)\uc740 \uadf8 \ub0b4\uc6a9\uc5d0 \ub300\ud574 \uc758\uacac\uc744 \uc81c\ucd9c\ud558\uace0 \uc804\uc6d0\ud68c\uc758\xb7\uc18c\ud68c\uc758 \ub4f1 \uc2ec\uc758 \uacfc\uc815\uc5d0\uc11c \uc758\uacac\uc744 \uc9c4\uc220\ud560 \uae30\ud68c\ub97c \uac00\uc9c8 \uc218 \uc788\ub2e4. \uc774\ub294 \ucc98\ubd84\uc5d0 \uc55e\uc11c \ud53c\uc2ec\uc778\uc758 \ubc29\uc5b4\uad8c\uc744 \ubcf4\uc7a5\ud558\uae30 \uc704\ud55c \ud575\uc2ec\uc801\uc778 \uc808\ucc28\uc774\ub2e4.",B.tD,B.aQa,null)
B.aHU=s(["\uc815\ub2f9\ud55c \uc774\uc720 \uc5c6\uc774 \uc870\uc0ac\ub97c \uac70\ubd80\xb7\ubc29\ud574\ud558\uac70\ub098 \uc790\ub8cc\ub97c \uc740\ub2c9\xb7\uc778\uba78\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4","\ud53c\uc870\uc0ac\uc778\uc740 \uc870\uc0ac\uc5d0 \uc5b4\ub5a0\ud55c \ud611\uc870\uc758\ubb34\ub3c4 \ubd80\ub2f4\ud558\uc9c0 \uc54a\ub294\ub2e4","\uc790\ub8cc \uc740\ub2c9\xb7\uc778\uba78\uc740 \uc544\ubb34\ub7f0 \ubd88\uc774\uc775 \uc5c6\uc774 \uc790\uc720\ub86d\uac8c \ud560 \uc218 \uc788\ub2e4","\ud611\uc870\uc758\ubb34\ub294 \uc624\uc9c1 \uc0ac\uc5c5\uc790\ub2e8\uccb4\uc5d0\uac8c\ub9cc \ubd80\uacfc\ub41c\ub2e4","\ud611\uc870\uc758\ubb34\ub294 \uc870\uc0ac\uac00 \uac1c\uc2dc\ub418\uae30 \uc804\uc5d0\ub9cc \uc874\uc7ac\ud55c\ub2e4"],t.s)
B.b09=s(["\uc815\ub2f9\ud55c \uc774\uc720 \uc5c6\uc774 \uc870\uc0ac\ub97c \uac70\ubd80\xb7\ubc29\ud574\ud558\uac70\ub098 \uc790\ub8cc\ub97c \uc740\ub2c9\xb7\uc778\uba78\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4"],t.s)
B.aX6=s(["\ud53c\uc870\uc0ac\uc778\uc758 \ud611\uc870\uc758\ubb34"],t.s)
B.bs0=new A.a("gen_iv_right_5","economic_law","\uc870\uc0ac\uc808\ucc28","\ud53c\uc870\uc0ac\uc790\uc758 \uad8c\ub9ac\xb7\uc758\ubb34","\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c \uc870\uc0ac \uacfc\uc815\uc5d0\uc11c \ud53c\uc870\uc0ac\uc778\uc774 \ubd80\ub2f4\ud558\ub294 \ud611\uc870\uc758\ubb34\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aHU,0,"\uc870\uc0ac\ub97c \ubc1b\ub294 \uc0ac\uc5c5\uc790\ub294 \uc815\ub2f9\ud55c \uc774\uc720 \uc5c6\uc774 \uc870\uc0ac\ub97c \uac70\ubd80\xb7\ubc29\ud574\ud558\uac70\ub098 \uad00\ub828 \uc790\ub8cc\ub97c \uc740\ub2c9\xb7\uc778\uba78\ud574\uc11c\ub294 \uc548 \ub418\ub294 \ud611\uc870\uc758\ubb34\ub97c \ubd80\ub2f4\ud55c\ub2e4. \uc774\ub97c \uc704\ubc18\ud558\uba74 \uc870\uc0ac\ubc29\ud574\uc5d0 \ud574\ub2f9\ud558\uc5ec \ubcc4\ub3c4\uc758 \uc81c\uc7ac \ub300\uc0c1\uc774 \ub420 \uc218 \uc788\ub2e4.",B.b09,B.aX6,null)
B.aiO=s([u.BI,"\uc601\uc5c5\ube44\ubc00\uc744 \uc774\uc720\ub85c \ub4e4\uba74 \uc5b4\ub5a0\ud55c \uc790\ub8cc\ub3c4 \uc81c\ucd9c\ud560 \ud544\uc694\uac00 \uc5c6\ub2e4","\uc601\uc5c5\ube44\ubc00 \uc5ec\ubd80\ub294 \uc870\uc0ac\uc640 \uc544\ubb34\ub7f0 \uad00\ub828\uc774 \uc5c6\ub294 \ubb38\uc81c\uc774\ub2e4","\uc601\uc5c5\ube44\ubc00 \uc790\ub8cc\ub294 \uc808\ub300 \uc870\uc0ac \ub300\uc0c1\uc774 \ub420 \uc218 \uc5c6\ub2e4\ub294 \uac83\uc774 \ubc95\ub960\uc0c1 \uba85\ubb38\uc73c\ub85c \uc815\ud574\uc838 \uc788\ub2e4","\uc601\uc5c5\ube44\ubc00\uc744 \uc774\uc720\ub85c \uac70\ubd80\ud558\uba74 \uc870\uc0ac\ubc29\ud574\uc8c4\uac00 \uc131\ub9bd\ud558\uc9c0 \uc54a\ub294\ub2e4\ub294 \uac83\uc774 \ud655\ub9bd\ub41c \uc608\uc678\uc774\ub2e4"],t.s)
B.aEv=s([u.BI],t.s)
B.a6G=s(["\uc601\uc5c5\ube44\ubc00\uacfc \uc790\ub8cc\uc81c\ucd9c\uc758\ubb34"],t.s)
B.bBV=new A.a("gen_iv_right_6","economic_law","\uc870\uc0ac\uc808\ucc28","\ud53c\uc870\uc0ac\uc790\uc758 \uad8c\ub9ac\xb7\uc758\ubb34","\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c \uc870\uc0ac \ub300\uc0c1\uc774 \ub41c \uc0ac\uc5c5\uc790\uac00 \uc790\ub8cc\uc81c\ucd9c\uc694\uad6c\uc5d0 \ub300\ud574 \uc601\uc5c5\ube44\ubc00\uc744 \uc774\uc720\ub85c \uc81c\ucd9c\uc744 \uac70\ubd80\ud560 \uc218 \uc788\ub294\uc9c0\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aiO,0,"\uc601\uc5c5\ube44\ubc00\uc5d0 \ud574\ub2f9\ud55c\ub2e4\ub294 \uc0ac\uc815\ub9cc\uc73c\ub85c \uc815\ub2f9\ud55c \uc870\uc0ac\uc5d0 \ub300\ud55c \uc790\ub8cc\uc81c\ucd9c\uc744 \uc804\uba74 \uac70\ubd80\ud560 \uc218 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\uba70, \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uac00 \uc870\uc0ac \uacfc\uc815\uc5d0\uc11c \uc54c\uac8c \ub41c \ube44\ubc00\uc744 \ub204\uc124\ud558\uc9c0 \uc54a\uc744 \uc758\ubb34\ub97c \uc9c0\ub294 \uac83\uacfc \uac19\uc740 \ubcf4\ud638\uc7a5\uce58 \ud558\uc5d0\uc11c \ud544\uc694\ud55c \ubc94\uc704\uc758 \uc790\ub8cc \uc81c\ucd9c\uc774 \uc694\uad6c\ub420 \uc218 \uc788\ub2e4.",B.aEv,B.a6G,null)
B.a46=s(["\uc870\uc0ac\ubc29\ud574\ud589\uc704\ub85c\uc11c \ubcc4\ub3c4\uc758 \uc81c\uc7ac(\uacfc\ud0dc\ub8cc \ub4f1) \ub300\uc0c1\uc774 \ub420 \uc218 \uc788\ub2e4","\uc870\uc0ac\uac70\ubd80\ub294 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \uc544\ubb34\ub7f0 \ubd88\uc774\uc775\uc774 \uc5c6\ub2e4","\uc870\uc0ac\uac70\ubd80\ub294 \uc624\ud788\ub824 \ud53c\uc870\uc0ac\uc778\uc5d0\uac8c \ud56d\uc0c1 \uc720\ub9ac\ud558\uac8c \uc791\uc6a9\ud55c\ub2e4","\uc870\uc0ac\uac70\ubd80\ub294 \ud615\uc0ac\ucc98\ubc8c \ub300\uc0c1\uc774 \ub420 \uc218 \uc5c6\uace0 \uc5b4\ub5a0\ud55c \uc81c\uc7ac\ub3c4 \uc5c6\ub2e4","\uc870\uc0ac\uac70\ubd80\ub294 \uc0ac\uc5c5\uc790\ub2e8\uccb4\uc5d0\uac8c\ub9cc \ubb38\uc81c\uac00 \ub41c\ub2e4"],t.s)
B.a44=s(["\uc870\uc0ac\ubc29\ud574\ud589\uc704\ub85c\uc11c \ubcc4\ub3c4\uc758 \uc81c\uc7ac(\uacfc\ud0dc\ub8cc \ub4f1) \ub300\uc0c1\uc774 \ub420 \uc218 \uc788\ub2e4"],t.s)
B.aZg=s(["\uc870\uc0ac\uac70\ubd80\xb7\ubc29\ud574\xb7\uae30\ud53c\uc5d0 \ub300\ud55c \uc81c\uc7ac"],t.s)
B.bGV=new A.a("gen_iv_obstruct_1","economic_law","\uc870\uc0ac\uc808\ucc28","\uc870\uc0ac\ubc29\ud574\uc5d0 \ub300\ud55c \uc81c\uc7ac","\uc815\ub2f9\ud55c \uc774\uc720 \uc5c6\uc774 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uc758 \ud604\uc7a5\uc870\uc0ac\ub97c \uac70\ubd80\xb7\ubc29\ud574\xb7\uae30\ud53c\ud558\ub294 \ud589\uc704\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.a46,0,"\uc815\ub2f9\ud55c \uc774\uc720 \uc5c6\uc774 \uc870\uc0ac\ub97c \uac70\ubd80\xb7\ubc29\ud574\xb7\uae30\ud53c\ud558\ub294 \ud589\uc704\ub294 \uc870\uc0ac\ubc29\ud574\ud589\uc704\ub85c\uc11c \ubcc4\ub3c4\uc758 \uacfc\ud0dc\ub8cc \ub4f1 \uc81c\uc7ac \ub300\uc0c1\uc774 \ub420 \uc218 \uc788\ub2e4. \uc774\ub294 \uc784\uc758\uc870\uc0ac \uc6d0\uce59 \ud558\uc5d0\uc11c\ub3c4 \uc2e4\ud6a8\uc801\uc778 \uc870\uc0ac\uac00 \uc774\ub8e8\uc5b4\uc9c8 \uc218 \uc788\ub3c4\ub85d \ud558\ub294 \uc720\uc778 \uc7a5\uce58\ub85c \uae30\ub2a5\ud55c\ub2e4.",B.a44,B.aZg,null)
B.aM6=s(["\uc870\uc0ac\ubc29\ud574\uc5d0 \ud574\ub2f9\ud558\uc5ec \ud1b5\uc0c1\uc758 \ud611\uc870 \uc704\ubc18\ubcf4\ub2e4 \ub354 \uc911\ud558\uac8c \ucde8\uae09\ub420 \uc218 \uc788\ub2e4","\uc790\ub8cc \uc704\uc870\xb7\ubcc0\uc870\ub294 \uc870\uc0ac\ubc29\ud574\uc5d0 \ud574\ub2f9\ud558\uc9c0 \uc54a\ub294\ub2e4","\uc790\ub8cc\ub97c \uc704\uc870\ud574\ub3c4 \uc81c\ucd9c\ub9cc \ud558\uba74 \ud56d\uc0c1 \ubb38\uc81c\uc5c6\ub2e4","\uc704\uc870\ub41c \uc790\ub8cc \uc81c\ucd9c\uc740 \uc624\ud788\ub824 \uac10\uacbd\uc0ac\uc720\ub85c \uc778\uc815\ub41c\ub2e4","\uc790\ub8cc \uc704\uc870\xb7\ubcc0\uc870\ub294 \uc870\uc0ac\uc808\ucc28\uc640 \ubb34\uad00\ud55c \ubb38\uc81c\uc774\ub2e4"],t.s)
B.a9z=s(["\uc870\uc0ac\ubc29\ud574\uc5d0 \ud574\ub2f9\ud558\uc5ec \ud1b5\uc0c1\uc758 \ud611\uc870 \uc704\ubc18\ubcf4\ub2e4 \ub354 \uc911\ud558\uac8c \ucde8\uae09\ub420 \uc218 \uc788\ub2e4"],t.s)
B.a5J=s(["\uc790\ub8cc \uc704\uc870\xb7\ubcc0\uc870\uc758 \uc81c\uc7ac"],t.s)
B.bD6=new A.a("gen_iv_obstruct_2","economic_law","\uc870\uc0ac\uc808\ucc28","\uc870\uc0ac\ubc29\ud574\uc5d0 \ub300\ud55c \uc81c\uc7ac","\uc870\uc0ac \uacfc\uc815\uc5d0\uc11c \uc790\ub8cc\ub97c \uc740\ub2c9\ud558\uac70\ub098 \uc704\uc870\xb7\ubcc0\uc870\ud558\uc5ec \uc81c\ucd9c\ud558\ub294 \ud589\uc704\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aM6,0,"\ub2e8\uc21c\ud788 \uc790\ub8cc\uc81c\ucd9c\uc744 \uc9c0\uc5f0\ud558\uac70\ub098 \uc18c\uadf9\uc801\uc73c\ub85c \ud611\uc870\ud558\uc9c0 \uc54a\ub294 \uac83\uc744 \ub118\uc5b4, \uc790\ub8cc\ub97c \uc740\ub2c9\ud558\uac70\ub098 \uc704\uc870\xb7\ubcc0\uc870\ud558\uc5ec \uc81c\ucd9c\ud558\ub294 \ud589\uc704\ub294 \uc870\uc0ac\uc758 \uc2e4\ud6a8\uc131\uc744 \uadfc\ubcf8\uc801\uc73c\ub85c \ud6fc\uc190\ud558\ub294 \uac83\uc73c\ub85c\uc11c \ud1b5\uc0c1\uc758 \ud611\uc870 \uc704\ubc18\ubcf4\ub2e4 \ub354 \ubb34\uac81\uac8c \ud3c9\uac00\ub418\uc5b4 \uc81c\uc7ac\ub098 \uac00\uc911\uc0ac\uc720\ub85c \uace0\ub824\ub420 \uc218 \uc788\ub2e4.",B.a9z,B.a5J,null)
B.aBN=s(["\uc870\uc0ac \ubc29\ud574\ub098 \ube44\ud611\uc870 \uc0ac\uc2e4\uc740 \uacfc\uc9d5\uae08 \uac00\uc911\uc0ac\uc720\ub85c \uace0\ub824\ub420 \uc218 \uc788\ub2e4","\uc870\uc0ac\ubc29\ud574 \uc5ec\ubd80\ub294 \uacfc\uc9d5\uae08 \uc0b0\uc815\uacfc \uc804\ud600 \ubb34\uad00\ud558\ub2e4","\uc870\uc0ac\ubc29\ud574\ub97c \ud558\uba74 \uc624\ud788\ub824 \uacfc\uc9d5\uae08\uc774 \uc790\ub3d9\uc73c\ub85c \uac10\uacbd\ub41c\ub2e4","\uc870\uc0ac\ubc29\ud574 \uc5ec\ubd80\ub294 \uc624\uc9c1 \ud615\uc0ac\ucc98\ubc8c\uc5d0\uc11c\ub9cc \uace0\ub824\ub418\uace0 \uacfc\uc9d5\uae08\uacfc\ub294 \ubb34\uad00\ud558\ub2e4","\uc870\uc0ac\ubc29\ud574\ub294 \ud56d\uc0c1 \uacfc\uc9d5\uae08 \ubd80\uacfc \uc790\uccb4\ub97c \ubb34\ud6a8\ub85c \ub9cc\ub4e0\ub2e4"],t.s)
B.b9l=s(["\uc870\uc0ac \ubc29\ud574\ub098 \ube44\ud611\uc870 \uc0ac\uc2e4\uc740 \uacfc\uc9d5\uae08 \uac00\uc911\uc0ac\uc720\ub85c \uace0\ub824\ub420 \uc218 \uc788\ub2e4"],t.s)
