B.bE0=new A.a("gen_pc_sales_5","economic_law","\uacfc\uc9d5\uae08","\uad00\ub828\ub9e4\ucd9c\uc561 \uc0b0\uc815","\uad00\ub828\ub9e4\ucd9c\uc561\uc5d0 \ubd80\uac00\uac00\uce58\uc138\uac00 \ud3ec\ud568\ub418\ub294\uc9c0\uc5d0 \uad00\ud55c \uc77c\ubc18\uc801\uc778 \uc0b0\uc815 \ubc29\uc2dd\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.b85,0,"\uad00\ub828\ub9e4\ucd9c\uc561\uc744 \uc0b0\uc815\ud560 \ub54c\ub294 \ud1b5\uc0c1 \ubd80\uac00\uac00\uce58\uc138\uc640 \uac19\uc774 \ucd5c\uc885\uc18c\ube44\uc790\uac00 \ubd80\ub2f4\ud558\ub294 \uc138\uae08 \uc131\uaca9\uc758 \uae08\uc561\uc744 \uc81c\uc678\ud55c \uc21c\ub9e4\ucd9c\uc561\uc744 \uae30\uc900\uc73c\ub85c \ud558\ub294 \uac83\uc774 \uc77c\ubc18\uc801\uc778 \uc0b0\uc815 \ubc29\uc2dd\uc73c\ub85c \uc774\ud574\ub41c\ub2e4. \uc774\ub294 \uc0ac\uc5c5\uc790\uac00 \uc2e4\uc81c\ub85c \uc5bb\uc740 \ub9e4\ucd9c \uaddc\ubaa8\ub97c \ubcf4\ub2e4 \uc815\ud655\ud558\uac8c \ubc18\uc601\ud558\uae30 \uc704\ud568\uc774\ub2e4.",B.aqu,B.aFE,null)
B.Sa=s([u.Et,"\uad00\ub828\ub9e4\ucd9c\uc561\uc740 \ud615\uc0ac\ucc98\ubc8c\uc758 \ud615\ub7c9 \uc0b0\uc815\uc5d0\ub9cc \uc0ac\uc6a9\ub418\uace0 \uacfc\uc9d5\uae08\uacfc\ub294 \ubb34\uad00\ud558\uae30 \ub54c\ubb38\uc774\ub2e4","\uad00\ub828\ub9e4\ucd9c\uc561\uc740 \uc624\uc9c1 \uc138\ubb34\ub2f9\uad6d\uc758 \uc138\uae08 \ubd80\uacfc\ub97c \uc704\ud55c \uc790\ub8cc\uc77c \ubfd0\uc774\uae30 \ub54c\ubb38\uc774\ub2e4","\uad00\ub828\ub9e4\ucd9c\uc561\uc740 \uc0ac\uc5c5\uc790\ub2e8\uccb4\uc5d0\ub9cc \uc801\uc6a9\ub418\uace0 \uac1c\ubcc4 \uc0ac\uc5c5\uc790\uc5d0\ub294 \uc801\uc6a9\ub418\uc9c0 \uc54a\uae30 \ub54c\ubb38\uc774\ub2e4","\uad00\ub828\ub9e4\ucd9c\uc561\uc740 \uc18c\ube44\uc790 \ud53c\ud574\uad6c\uc81c \uc808\ucc28\uc5d0\uc11c\ub9cc \uc0ac\uc6a9\ub418\uae30 \ub54c\ubb38\uc774\ub2e4"],t.s)
