B.byc=new A.a("gen_pc_sales_6","economic_law","\uacfc\uc9d5\uae08","\uad00\ub828\ub9e4\ucd9c\uc561 \uc0b0\uc815","\uad00\ub828\ub9e4\ucd9c\uc561 \uc0b0\uc815\uc774 \uacfc\uc9d5\uae08 \uc81c\ub3c4\uc5d0\uc11c \uc911\uc694\ud55c \uc774\uc720\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.Sa,0,"\uad00\ub828\ub9e4\ucd9c\uc561\uc740 \uc704\ubc18\ud589\uc704\uc640 \uad00\ub828\ub41c \uc0ac\uc5c5 \uaddc\ubaa8\ub97c \ubc18\uc601\ud558\uc5ec \uacfc\uc9d5\uae08\uc758 \uc0c1\ud55c\uacfc \uae30\ubcf8 \uc0b0\uc815\uae30\uc900\uc744 \uc815\ud558\ub294 \ud575\uc2ec\uc801\uc778 \uae30\ucd08\uc790\ub8cc\ub85c \ud65c\uc6a9\ub41c\ub2e4. \uc704\ubc18\ud589\uc704\uc758 \uacbd\uc81c\uc801 \uaddc\ubaa8\uc5d0 \ube44\ub840\ud558\uc5ec \uc81c\uc7ac \uc218\uc900\uc744 \uc815\ud568\uc73c\ub85c\uc368 \uacfc\uc9d5\uae08 \uc81c\ub3c4\uc758 \ud615\ud3c9\uc131\uacfc \uc2e4\ud6a8\uc131\uc744 \ud655\ubcf4\ud558\ub824\ub294 \ucde8\uc9c0\uac00 \ub2f4\uaca8 \uc788\ub2e4.",B.aky,B.aLr,null)
B.aRs=s([u.rU,"\uc5b4\ub5a0\ud55c \uc808\ucc28\ub3c4 \uac70\uce58\uc9c0 \uc54a\uace0 \uc989\uc2dc \uacfc\uc9d5\uae08\uc744 \ubd80\uacfc\ud55c\ub2e4","\uacfc\uc9d5\uae08 \ubd80\uacfc\ub294 \ubc95\uc6d0\uc758 \uc7ac\ud310\uc744 \ud1b5\ud574\uc11c\ub9cc \uacb0\uc815\ub41c\ub2e4","\uacfc\uc9d5\uae08 \ubd80\uacfc\ub294 \uad6d\ud68c\uc758 \uc0ac\uc804 \uc2b9\uc778\uc744 \uac70\uccd0\uc57c\ub9cc \uac00\ub2a5\ud558\ub2e4","\uacfc\uc9d5\uae08 \ubd80\uacfc\ub294 \uc0ac\uc5c5\uc790\uc758 \uc0ac\uc804 \ub3d9\uc758\uac00 \uc788\uc5b4\uc57c\ub9cc \uac00\ub2a5\ud558\ub2e4"],t.s)
