B.buz=new A.a("gen_pc_proc_2","economic_law","\uacfc\uc9d5\uae08","\ubd80\uacfc\uc808\ucc28\xb7\uac10\uba74","\uacfc\uc9d5\uae08 \ub0a9\ubd80\uae30\ud55c\uc758 \uc5f0\uc7a5\uc774\ub098 \ubd84\ud560\ub0a9\ubd80\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aFj,0,"\uacfc\uc9d5\uae08 \ub0a9\ubd80\uc758\ubb34\uc790\ub294 \uc7ac\ud574\ub098 \uc0ac\uc5c5\uc5ec\uac74\uc758 \uc545\ud654 \ub4f1 \uc77c\uc815\ud55c \uc0ac\uc720\uac00 \uc788\ub294 \uacbd\uc6b0, \uc815\ud574\uc9c4 \uae30\ud55c \ub0b4\uc5d0 \ub0a9\ubd80\uae30\ud55c\uc758 \uc5f0\uc7a5\uc774\ub098 \ubd84\ud560\ub0a9\ubd80\ub97c \uc2e0\uccad\ud560 \uc218 \uc788\uace0, \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uac00 \uc774\ub97c \uc2ec\uc0ac\ud558\uc5ec \uc2b9\uc778 \uc5ec\ubd80\ub97c \uacb0\uc815\ud55c\ub2e4. \uc774\ub294 \uc77c\uc2dc\ub0a9\ubd80\ub85c \uc778\ud55c \uacfc\ub3c4\ud55c \ubd80\ub2f4\uc744 \uc644\ud654\ud558\uae30 \uc704\ud55c \uc81c\ub3c4\uc774\ub2e4.",B.apX,B.alr,null)
B.akK=s([u.r8,"\uc870\uc0ac \ud611\uc870 \uc5ec\ubd80\ub294 \uacfc\uc9d5\uae08 \uc0b0\uc815\uc5d0 \uc5b4\ub5a0\ud55c \uc601\ud5a5\ub3c4 \ubbf8\uce58\uc9c0 \uc54a\ub294\ub2e4","\uc790\uc9c4\uc2dc\uc815\uc740 \uc624\ud788\ub824 \uac00\uc911\uc0ac\uc720\ub85c \uc791\uc6a9\ud55c\ub2e4","\uac10\uacbd\uc740 \uc624\uc9c1 \ub300\uae30\uc5c5\uc5d0\uac8c\ub9cc \uc778\uc815\ub41c\ub2e4","\uac10\uacbd \uc5ec\ubd80\ub294 \uc0ac\uc5c5\uc790\uc758 \ub85c\ube44 \ud65c\ub3d9\uc5d0 \ub530\ub77c \uacb0\uc815\ub41c\ub2e4"],t.s)
