B.bEC=new A.a("gen_appeal_exam_2","economic_law","\uc774\uc758\uc2e0\uccad\xb7\ubd88\ubcf5\uc808\ucc28","\uc2dc\ud5d8 \ud3ec\uc778\ud2b8\xb7\uc2e4\ubb34 \uc801\uc6a9","\uc774\uc758\uc2e0\uccad\xb7\ubd88\ubcf5\uc808\ucc28 \uad00\ub828 \ubb38\uc81c\uc5d0\uc11c \uc790\uc8fc \ucd9c\uc81c\ub418\ub294 \ud568\uc815 \uc720\ud615\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.b5Q,0,"\uc774\uc758\uc2e0\uccad\xb7\ubd88\ubcf5\uc808\ucc28 \ubb38\uc81c\uc5d0\uc11c\ub294 \uc774\uc758\uc2e0\uccad\uc744 \ud544\uc218\uc801 \uc804\uce58\uc808\ucc28\ub85c \uc11c\uc220\ud558\uc5ec \uc774\ub97c \uac70\uce58\uc9c0 \uc54a\uc73c\uba74 \ud589\uc815\uc18c\uc1a1\uc744 \uc81c\uae30\ud560 \uc218 \uc5c6\ub2e4\uace0 \uc624\ub3c4\ud558\ub294 \uc120\ud0dd\uc9c0\uac00 \ud568\uc815\uc73c\ub85c \uc790\uc8fc \ucd9c\uc81c\ub418\ubbc0\ub85c, \uc774\uc758\uc2e0\uccad\uc774 \uc784\uc758\uc801 \uc808\ucc28\ub77c\ub294 \uc810\uc744 \uc815\ud655\ud788 \uad6c\ubcc4\ud574 \ub450\uc5b4\uc57c \ud55c\ub2e4.",B.aj5,B.dE,null)
