B.bAa=new A.a("gen_appeal_exam_4","economic_law","\uc774\uc758\uc2e0\uccad\xb7\ubd88\ubcf5\uc808\ucc28","\uc2dc\ud5d8 \ud3ec\uc778\ud2b8\xb7\uc2e4\ubb34 \uc801\uc6a9","\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c \ucc98\ubd84\uc5d0 \ub300\ud55c \ubd88\ubcf5\uc808\ucc28\uac00 \uc2e0\uc18d\ud558\uac8c \uc815\ube44\ub418\uc5b4\uc57c \ud558\ub294 \uc815\ucc45\uc801 \uc774\uc720\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.aMd,0,"\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uc758 \uc2dc\uc815\uc870\uce58\xb7\uacfc\uc9d5\uae08 \ub4f1 \ucc98\ubd84\uc740 \uc0ac\uc5c5\uc790\uc758 \uc601\uc5c5\ud65c\ub3d9\uacfc \uc2dc\uc7a5\uc5d0\uc11c\uc758 \uc9c0\uc704\uc5d0 \uc0c1\ub2f9\ud55c \uc601\ud5a5\uc744 \ubbf8\uce60 \uc218 \uc788\uc73c\ubbc0\ub85c, \ucc98\ubd84\uc5d0 \ubd88\ubcf5\ud558\ub294 \uc0ac\uc5c5\uc790\uac00 \uc2e0\uc18d\ud558\uace0 \uc2e4\ud6a8\uc801\uc73c\ub85c \uad8c\ub9ac\ub97c \uad6c\uc81c\ubc1b\uc744 \uc218 \uc788\ub3c4\ub85d \uc774\uc758\uc2e0\uccad\xb7\ud589\uc815\uc18c\uc1a1 \ub4f1\uc758 \ubd88\ubcf5\uc808\ucc28\ub97c \uccb4\uacc4\uc801\uc73c\ub85c \uc815\ube44\ud560 \ud544\uc694\uac00 \uc788\ub2e4\ub294 \uac83\uc774 \uc815\ucc45\uc801 \uc774\uc720\uc774\ub2e4.",B.alz,B.aT1,null)
B.aM2=s([u.u4,"\ub450 \ud30c\ud2b8\ub294 \uc644\uc804\ud788 \ub3d9\uc77c\ud55c \ub0b4\uc6a9\uc744 \ub2e4\ub8e8\uc5b4 \uad6c\ubcc4\ud560 \uc2e4\uc775\uc774 \uc5c6\ub2e4","\uc774\uc758\uc2e0\uccad\xb7\ubd88\ubcf5\uc808\ucc28\ub294 \uc870\uc0ac\uc808\ucc28\uc640 \uc804\ud600 \ubb34\uad00\ud55c \ubcc4\uac1c\uc758 \ubc95\ub960\uc5d0 \uadfc\uac70\ud55c\ub2e4","\uc870\uc0ac\uc808\ucc28\ub9cc \uc2dc\ud5d8\uc5d0 \ucd9c\uc81c\ub418\uace0 \uc774\uc758\uc2e0\uccad\xb7\ubd88\ubcf5\uc808\ucc28\ub294 \ucd9c\uc81c\ub418\uc9c0 \uc54a\ub294\ub2e4","\uc774\uc758\uc2e0\uccad\xb7\ubd88\ubcf5\uc808\ucc28\ub294 \ud615\uc0ac\uc808\ucc28\ub9cc\uc744 \ub2e4\ub8e8\ub294 \ud30c\ud2b8\uc774\ub2e4"],t.s)
