B.a8h=s([u.a8,"\ub450 \uc720\ud615 \ubaa8\ub450 \uc624\uc9c1 \uc18c\ube44\uc790\ub9cc\uc744 \ub300\uc0c1\uc73c\ub85c \ud558\ub294 \ud589\uc704\uc774\ub2e4","\ub450 \uc720\ud615 \ubaa8\ub450 \uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\uc758 \ud558\uc704 \uc720\ud615\uc774\ub2e4","\ub450 \uc720\ud615 \ubaa8\ub450 \ub2f4\ud569\uc744 \uc804\uc81c\ub85c \ud574\uc57c\ub9cc \uc131\ub9bd\ud55c\ub2e4","\ub450 \uc720\ud615\uc740 \uc11c\ub85c \uc815\ubc18\ub300\uc758 \uac1c\ub150\uc73c\ub85c \uc804\ud600 \uad00\ub828\uc774 \uc5c6\ub2e4"],t.s)
