B.brd=new A.a("gen_predatory_exam_1","economic_law","\ubd80\ub2f9\uc5fc\ub9e4\xb7\uacbd\uc7c1\uc0ac\uc5c5\uc790\ubc30\uc81c","\ubd80\ub2f9\uc131 \ud310\ub2e8\xb7\uc2dc\ud5d8 \ud3ec\uc778\ud2b8","\ubd80\ub2f9\uc5fc\ub9e4\uc758 \ubd80\ub2f9\uc131 \ud310\ub2e8\uc5d0\uc11c \uc99d\uba85\ucc45\uc784\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.a9D,0,"\ubd80\ub2f9\uc5fc\ub9e4 \uc0ac\uac74\uc5d0\uc11c \uadf8 \ubd80\ub2f9\uc131(\ube44\uc6a9 \uc774\ud558 \uac00\uaca9, \uacc4\uc18d\uc131, \uacbd\uc7c1\uc81c\ud55c \uc6b0\ub824 \ub4f1)\uc5d0 \ub300\ud55c \uc99d\uba85\ucc45\uc784\uc740 \uc6d0\uce59\uc801\uc73c\ub85c \uc774\ub97c \uc8fc\uc7a5\ud558\uba70 \uc81c\uc7ac\ub97c \ud558\ub824\ub294 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uac00 \ubd80\ub2f4\ud558\ub294 \uac83\uc774 \ud589\uc815\ucc98\ubd84\uc758 \uc77c\ubc18 \uc6d0\uce59\uc5d0 \ubd80\ud569\ud55c\ub2e4.",B.b6p,B.a_C,null)
B.awm=s([u.Dm,"\uacc4\uc18d\uac70\ub798\uc0c1\uc758 \ubd80\ub2f9\uc5fc\ub9e4\ub294 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ubd80\ub2f9\uc131\uc774 \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4","\uacc4\uc18d\uac70\ub798\uc0c1\uc758 \ubd80\ub2f9\uc5fc\ub9e4\ub294 \ubd80\ub2f9\uc131 \ud310\ub2e8 \uc790\uccb4\uac00 \ud544\uc694 \uc5c6\ub294 \uc720\ud615\uc774\ub2e4","\uacc4\uc18d\uac70\ub798\uc0c1\uc758 \ubd80\ub2f9\uc5fc\ub9e4\ub294 \uc624\uc9c1 \ud615\uc0ac\ucc98\ubc8c\ub85c\ub9cc \ub2e4\ub8e8\uc5b4\uc9c4\ub2e4","\uacc4\uc18d\uac70\ub798\uc0c1\uc758 \ubd80\ub2f9\uc5fc\ub9e4\ub294 \uc18c\ube44\uc790 \ubcf4\ud638\uc640 \uc804\ud600 \ubb34\uad00\ud558\ub2e4"],t.s)
