B.bMR=new A.a("gen_predatory_exam_2","economic_law","\ubd80\ub2f9\uc5fc\ub9e4\xb7\uacbd\uc7c1\uc0ac\uc5c5\uc790\ubc30\uc81c","\ubd80\ub2f9\uc131 \ud310\ub2e8\xb7\uc2dc\ud5d8 \ud3ec\uc778\ud2b8","\uacc4\uc18d\uac70\ub798\uc0c1\uc758 \ubd80\ub2f9\uc5fc\ub9e4\uc758 \uacbd\uc6b0 \ubd80\ub2f9\uc131 \ud310\ub2e8\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.awm,0,"\uacc4\uc18d\uac70\ub798\uc0c1\uc758 \ubd80\ub2f9\uc5fc\ub9e4\ub294 \uc0c1\ub2f9\ud55c \uae30\uac04\uc5d0 \uac78\uccd0 \ube44\uc6a9 \uc774\ud558\uc758 \uac00\uaca9\uc73c\ub85c \uacf5\uae09\ud558\ub294 \uc0ac\uc815\uc774 \uc778\uc815\ub418\uba74, \uadf8 \uc790\uccb4\ub85c \uacbd\uc7c1\uc81c\ud55c \uc6b0\ub824\uac00 \ud06c\ub2e4\uace0 \ubcf4\uc544 \ubd80\ub2f9\uc131\uc774 \uc0ac\uc2e4\uc0c1 \ucd94\uc815\ub418\ub294 \uacbd\ud5a5\uc774 \uc788\ub2e4\ub294 \uc810\uc5d0\uc11c \uc77c\ud68c\uc801\uc778 \uc5fc\ub9e4\ubcf4\ub2e4 \uc5c4\uaca9\ud558\uac8c \ucde8\uae09\ub41c\ub2e4.",B.XN,B.aAQ,null)
B.aHO=s([u.C_,"\uc624\uc9c1 \uc0ac\uc5c5\uc790 \ub300\ud45c\uc758 \uac1c\uc778 \uc2e0\uc0c1 \uc815\ubcf4\ub9cc \ucd9c\uc81c\ub41c\ub2e4","\ubd80\ub2f9\uc5fc\ub9e4\uc640 \ubb34\uad00\ud55c \uc138\ubc95 \uaddc\uc815\ub9cc \ucd9c\uc81c\ub41c\ub2e4","\ubd80\ub2f9\uc5fc\ub9e4 \uad00\ub828 \ubb38\uc81c\ub294 \uc804\ud600 \ucd9c\uc81c\ub418\uc9c0 \uc54a\ub294\ub2e4","\uc624\uc9c1 \uc0c1\ud488\uc758 \uc0c9\uae54\ub9cc \ubb3b\ub294 \ubb38\uc81c\ub9cc \ucd9c\uc81c\ub41c\ub2e4"],t.s)
