B.bMC=new A.a("gen_refuse_judge_1","economic_law","\uac70\ub798\uac70\uc808","\ubd80\ub2f9\uc131 \ud310\ub2e8\xb7\uc815\ub2f9\ud654 \uc0ac\uc720","\ub2e8\ub3c5\uc758 \uac70\ub798\uac70\uc808\uc774 \ubd80\ub2f9\ud558\ub2e4\uace0 \uc778\uc815\ub418\uae30 \uc704\ud55c \ud310\ub2e8\uae30\uc900\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.ahu,0,"\ub2e8\ub3c5\uc758 \uac70\ub798\uac70\uc808\uc774 \ubd80\ub2f9\ud558\ub2e4\uace0 \uc778\uc815\ub418\ub824\uba74, \ub2e8\uc21c\ud788 \uac70\ub798\ub97c \uac70\uc808\ud588\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c\ub294 \ubd80\uc871\ud558\uace0, \uadf8 \uac70\uc808\uc774 \uacbd\uc7c1\uc0ac\uc5c5\uc790\ub97c \uc2dc\uc7a5\uc5d0\uc11c \ubc30\uc81c\ud558\ub824\ub294 \ubaa9\uc801\uc774\ub098 \ud6a8\uacfc\ub97c \uac00\uc9c0\ub294\uc9c0, \uac70\ub798\uac70\uc808\ub85c \uc778\ud574 \uc0c1\ub300\ubc29\uc758 \uc0ac\uc5c5\ud65c\ub3d9\uc774 \uc2ec\ud788 \uace4\ub780\ud574\uc9c0\ub294\uc9c0 \ub4f1\uc744 \uc885\ud569\uc801\uc73c\ub85c \uace0\ub824\ud558\uc5ec \ud310\ub2e8\ud558\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub2e4.",B.aQk,B.aZw,null)
B.a2R=s([u.oh,"\uc774\uc720\ub97c \ubd88\ubb38\ud558\uace0 \ud56d\uc0c1 \ubd80\ub2f9\ud55c \uac70\ub798\uac70\uc808\uc5d0 \ud574\ub2f9\ud55c\ub2e4","\uc2e0\uc6a9\ubd88\ub7c9\uc774\ub098 \uacc4\uc57d \uc704\ubc18\uc740 \uac70\ub798\uac70\uc808\uacfc \uc804\ud600 \ubb34\uad00\ud55c \uc0ac\uc720\uc774\ub2e4","\uc774\ub7ec\ud55c \uac70\ub798\uac70\uc808\uc740 \uc624\uc9c1 \ud615\uc0ac\ucc98\ubc8c \ub300\uc0c1\uc774 \ub41c\ub2e4","\uc774\ub7ec\ud55c \uac70\ub798\uac70\uc808\uc740 \ubc18\ub4dc\uc2dc \uc0ac\uc5c5\uc790\ub2e8\uccb4\ub97c \ud1b5\ud574\uc11c\ub9cc \uc774\ub8e8\uc5b4\uc838\uc57c \ud55c\ub2e4"],t.s)
B.axq=s([u.oh],t.s)
B.WF=s(["\uc815\ub2f9\ud55c \uc0ac\uc720\uc5d0 \uc758\ud55c \uac70\ub798\uac70\uc808"],t.s)
B.bQh=new A.a("gen_refuse_judge_2","economic_law","\uac70\ub798\uac70\uc808","\ubd80\ub2f9\uc131 \ud310\ub2e8\xb7\uc815\ub2f9\ud654 \uc0ac\uc720","\uac70\ub798\uc0c1\ub300\ubc29\uc758 \uc2e0\uc6a9\ubd88\ub7c9\uc774\ub098 \uacc4\uc57d \uc704\ubc18\uc744 \uc774\uc720\ub85c \ud55c \uac70\ub798\uac70\uc808\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.a2R,0,"\uac70\ub798\uc0c1\ub300\ubc29\uc758 \uc2e0\uc6a9\ubd88\ub7c9, \ub300\uae08 \ubbf8\uc9c0\uae09, \uacc4\uc57d \uc704\ubc18 \ub4f1 \ud569\ub9ac\uc801\uc774\uace0 \uc815\ub2f9\ud55c \uc0ac\uc720\uc5d0 \uae30\ucd08\ud55c \uac70\ub798\uac70\uc808\uc740, \uc0ac\uc5c5\uc790\uac00 \uc790\uc2e0\uc758 \uc815\ub2f9\ud55c \uc774\uc775\uc744 \ubcf4\ud638\ud558\uae30 \uc704\ud55c \ud589\uc704\ub85c\uc11c \uc6d0\uce59\uc801\uc73c\ub85c \ubd80\ub2f9\ud55c \uac70\ub798\uac70\uc808\uc5d0 \ud574\ub2f9\ud558\uc9c0 \uc54a\ub294\ub2e4.",B.axq,B.WF,null)
