B.buQ=new A.a("gen_leniency_intro_1","economic_law","\uc790\uc9c4\uc2e0\uace0\uc790 \uac10\uba74","\uc81c\ub3c4\uc758 \ucde8\uc9c0\xb7\uac10\uba74 \uc694\uac74","\uc790\uc9c4\uc2e0\uace0\uc790 \uac10\uba74\uc81c\ub3c4(\ub9ac\ub2c8\uc5b8\uc2dc)\uc758 \ub3c4\uc785 \ucde8\uc9c0\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.b0N,0,"\uc790\uc9c4\uc2e0\uace0\uc790 \uac10\uba74\uc81c\ub3c4\ub294 \ub2f4\ud569\uc5d0 \uac00\ub2f4\ud55c \uc0ac\uc5c5\uc790\uac00 \uc790\uc9c4\uc2e0\uace0\ub97c \ud1b5\ud574 \uac10\uba74 \ud61c\ud0dd\uc744 \ubc1b\uc744 \uc218 \uc788\ub3c4\ub85d \ud568\uc73c\ub85c\uc368, \ub2f4\ud569 \ucc38\uc5ec \uc0ac\uc5c5\uc790\ub4e4 \uc0ac\uc774\uc5d0 \ubc30\uc2e0\uc5d0 \ub300\ud55c \ubd88\uc548\uc744 \uc870\uc131\ud558\uc5ec \ub2f4\ud569\uc758 \uc740\ubc00\uc131\uc744 \uae68\ub728\ub9ac\uace0 \uc801\ubc1c\ub960\uc744 \ub192\uc5ec \ub2f4\ud569\uc744 \uc0ac\uc804\uc5d0 \uc5b5\uc9c0\ud558\ub824\ub294 \uc815\ucc45\uc801 \ucde8\uc9c0\ub97c \uac16\ub294\ub2e4.",B.a3O,B.aaX,null)
B.aIj=s([u.k8,"\ub2e8\uc21c\ud788 \ub2f4\ud569\uc5d0 \ucc38\uc5ec\ud588\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \uc790\ub3d9\uc73c\ub85c \uc804\ubd80 \uba74\uc81c\ub41c\ub2e4","\uac00\uc7a5 \ub9c8\uc9c0\ub9c9\uc73c\ub85c \uc2e0\uace0\ud55c \uc0ac\uc5c5\uc790\uac00 \ud56d\uc0c1 \uc804\ubd80 \uba74\uc81c\ub97c \ubc1b\ub294\ub2e4","\uc790\uc9c4\uc2e0\uace0\uc790\ub294 \uc5b4\ub5a0\ud55c \uc694\uac74\ub3c4 \uc5c6\uc774 \uc804\ubd80 \uba74\uc81c\ub97c \ubc1b\ub294\ub2e4","\uc804\ubd80 \uba74\uc81c\ub294 \uc624\uc9c1 \ub300\uae30\uc5c5\uc5d0\uac8c\ub9cc \uc778\uc815\ub41c\ub2e4"],t.s)
B.aAq=s([u.k8],t.s)
B.auB=s(["\uc804\ubd80 \uba74\uc81c \uc694\uac74"],t.s)
B.bMm=new A.a("gen_leniency_intro_2","economic_law","\uc790\uc9c4\uc2e0\uace0\uc790 \uac10\uba74","\uc81c\ub3c4\uc758 \ucde8\uc9c0\xb7\uac10\uba74 \uc694\uac74","\uc790\uc9c4\uc2e0\uace0\uc790\ub85c\uc11c \uc2dc\uc815\uc870\uce58\xb7\uacfc\uc9d5\uae08\uc744 \uc804\ubd80 \uba74\uc81c\ubc1b\uae30 \uc704\ud55c \uc77c\ubc18\uc801 \uc694\uac74\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.aIj,0,"\uc790\uc9c4\uc2e0\uace0\uc790\uac00 \uc2dc\uc815\uc870\uce58\ub098 \uacfc\uc9d5\uae08\uc744 \uc804\ubd80 \uba74\uc81c\ubc1b\uae30 \uc704\ud574\uc11c\ub294 \ud1b5\uc0c1 \ud574\ub2f9 \uacf5\ub3d9\ud589\uc704 \uc0ac\uc2e4\uc744 \uc785\uc99d\ud558\ub294 \ucd5c\ucd08\uc758 \uc99d\uac70\ub97c \uc81c\uacf5\ud558\uace0, \uc870\uc0ac\uac00 \ub05d\ub0a0 \ub54c\uae4c\uc9c0 \uc131\uc2e4\ud558\uac8c \ud611\uc870\ud558\uba70, \ub2e4\ub978 \uc0ac\uc5c5\uc790\uc5d0\uac8c \uc790\uc9c4\uc2e0\uace0 \uc0ac\uc2e4\uc744 \ub204\uc124\ud558\uc9c0 \uc54a\ub294 \ub4f1\uc758 \uc694\uac74\uc744 \ucda9\uc871\ud558\uc5ec\uc57c \ud55c\ub2e4.",B.aAq,B.auB,null)
B.bax=s([u.J,"2\uc21c\uc704 \uc790\uc9c4\uc2e0\uace0\uc790\ub294 \uc5b4\ub5a0\ud55c \ud61c\ud0dd\ub3c4 \ubc1b\uc744 \uc218 \uc5c6\ub2e4","2\uc21c\uc704 \uc790\uc9c4\uc2e0\uace0\uc790\ub294 1\uc21c\uc704\uc640 \uc644\uc804\ud788 \ub3d9\uc77c\ud55c \uc804\ubd80 \uba74\uc81c\ub97c \ubc1b\ub294\ub2e4","2\uc21c\uc704 \uc790\uc9c4\uc2e0\uace0\uc790\ub294 \uc624\ud788\ub824 \uac00\uc911\ucc98\ubc8c\uc744 \ubc1b\ub294\ub2e4","2\uc21c\uc704 \uc790\uc9c4\uc2e0\uace0\uc790\uc5d0 \ub300\ud55c \uac10\uba74\uc740 \ubc95\ub960\uc0c1 \uc804\ud600 \uaddc\uc815\ub418\uc5b4 \uc788\uc9c0 \uc54a\ub2e4"],t.s)
B.bcr=s([u.J],t.s)
B.ayw=s(["2\uc21c\uc704 \uc790\uc9c4\uc2e0\uace0\uc790\uc758 \uac10\uba74 \uc218\uc900"],t.s)
B.bCy=new A.a("gen_leniency_intro_3","economic_law","\uc790\uc9c4\uc2e0\uace0\uc790 \uac10\uba74","\uc81c\ub3c4\uc758 \ucde8\uc9c0\xb7\uac10\uba74 \uc694\uac74","2\uc21c\uc704 \uc790\uc9c4\uc2e0\uace0\uc790(\uc870\uc0ac \ud611\uc870\uc790)\uc5d0\uac8c \uc778\uc815\ub418\ub294 \uac10\uba74 \ud61c\ud0dd\uc758 \uc77c\ubc18\uc801 \uc218\uc900\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.bax,0,"\ud574\ub2f9 \uacf5\ub3d9\ud589\uc704\ub97c \uc785\uc99d\ud558\ub294 \ub370 \ud544\uc694\ud55c \uc99d\uac70\ub97c 2\ubc88\uc9f8\ub85c \uc81c\uacf5\ud558\uace0 \uc870\uc0ac\uc5d0 \ud611\uc870\ud558\ub294 \ub4f1 \uc694\uac74\uc744 \uac16\ucd98 \uc0ac\uc5c5\uc790\uc5d0\uac8c\ub294, 1\uc21c\uc704 \uc790\uc9c4\uc2e0\uace0\uc790(\uc804\ubd80 \uba74\uc81c)\ubcf4\ub2e4\ub294 \ub0ae\uc740 \uc218\uc900\uc774\uc9c0\ub9cc \uc77c\uc815 \ube44\uc728(\uc608: \uacfc\uc9d5\uae08 \uc77c\ubd80 \uac10\uacbd)\uc758 \uac10\uba74 \ud61c\ud0dd\uc774 \uc778\uc815\ub420 \uc218 \uc788\ub2e4.",B.bcr,B.ayw,null)
B.b4a=s([u.mz,"\uc870\uc0ac \ucd08\uae30\uc5d0\ub9cc \ud611\uc870\ud558\uace0 \uc774\ud6c4\uc5d0\ub294 \ud611\uc870\ud558\uc9c0 \uc54a\uc544\ub3c4 \ub418\ub294 \uac83","\uc870\uc0ac\uad00\uacfc \uac1c\uc778\uc801\uc778 \uce5c\ubd84\uc744 \uc313\ub294 \uac83","\uc870\uc0ac\uc640 \ubb34\uad00\ud55c \uc790\ub8cc\ub97c \ub300\ub7c9\uc73c\ub85c \uc81c\ucd9c\ud558\ub294 \uac83","\uc870\uc0ac\uc5d0 \ud611\uc870\ud55c\ub2e4\ub294 \ub9d0\ub9cc \ud558\uace0 \uc2e4\uc81c \ud589\ub3d9\uc740 \ud558\uc9c0 \uc54a\ub294 \uac83"],t.s)
B.aun=s([u.mz],t.s)
