B.bN9=new A.a("gen_collusion_type_limit_3","economic_law","\ubd80\ub2f9\uacf5\ub3d9\ud589\uc704 \uc720\ud615","\uc0dd\uc0b0\xb7\uc2dc\uc7a5\xb7\uac70\ub798\uc0c1\ub300\ubc29 \uc81c\ud55c \uc720\ud615",'\ubd80\ub2f9\uacf5\ub3d9\ud589\uc704 \uc720\ud615 \uc911 "\uc124\ube44\uc758 \uc2e0\uc124\xb7\uc99d\uc124\uc774\ub098 \uc7a5\ube44\uc758 \ub3c4\uc785\uc744 \ubc29\ud574\xb7\uc81c\ud55c\ud558\ub294 \ud589\uc704"\uc758 \uc758\ubbf8\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?',B.aRH,0,'"\uc124\ube44\uc758 \uc2e0\uc124\xb7\uc99d\uc124\uc774\ub098 \uc7a5\ube44\uc758 \ub3c4\uc785\uc744 \ubc29\ud574\xb7\uc81c\ud55c\ud558\ub294 \ud589\uc704"\ub294 \uc0ac\uc5c5\uc790\ub4e4\uc774 \uacf5\ub3d9\uc73c\ub85c \ud569\uc758\ud558\uc5ec \uc0dd\uc0b0\ub2a5\ub825 \ud655\ucda9\uc744 \uc704\ud55c \uc124\ube44 \ud22c\uc790\ub098 \uc7a5\ube44 \ub3c4\uc785 \uc790\uccb4\ub97c \uc5b5\uc81c\ud568\uc73c\ub85c\uc368, \uc7a5\ub798\uc758 \uacf5\uae09 \ud655\ub300\ub098 \uacbd\uc7c1 \uc2ec\ud654 \uac00\ub2a5\uc131\uc744 \ubbf8\ub9ac \ucc28\ub2e8\ud558\ub294 \ub2f4\ud569 \uc720\ud615\uc744 \uc758\ubbf8\ud55c\ub2e4.',B.a1C,B.anx,null)
B.aUk=s([u.cn,"\uc0ac\uc5c5\uc790\uac00 \ud45c\uc900\ud654 \uae30\uad6c\ub97c \ud1b5\ud574 \uc815\ub2f9\ud55c \uc808\ucc28\ub85c \uaddc\uaca9\uc744 \ud1b5\uc77c\ud558\ub294 \ud589\uc704","\uc0ac\uc5c5\uc790\uac00 \uc2a4\uc2a4\ub85c \ud310\ub2e8\ud558\uc5ec \ud2b9\uc815 \uaddc\uaca9\uc758 \uc0c1\ud488\ub9cc \uc0dd\uc0b0\ud558\uae30\ub85c \uacb0\uc815\ud558\ub294 \ud589\uc704","\uc815\ubd80\uac00 \uc548\uc804\uae30\uc900\uc5d0 \ub530\ub77c \uaddc\uaca9\uc744 \uc815\ud558\ub294 \ud589\uc704","\uc0ac\uc5c5\uc790\uac00 \uc18c\ube44\uc790 \uc694\uad6c\uc5d0 \ub9de\ucd94\uc5b4 \ub2e4\uc591\ud55c \uaddc\uaca9\uc758 \uc0c1\ud488\uc744 \uac1c\ubc1c\ud558\ub294 \ud589\uc704"],t.s)
