B.bwB=new A.a("gen_collusion_type_limit_6","economic_law","\ubd80\ub2f9\uacf5\ub3d9\ud589\uc704 \uc720\ud615","\uc0dd\uc0b0\xb7\uc2dc\uc7a5\xb7\uac70\ub798\uc0c1\ub300\ubc29 \uc81c\ud55c \uc720\ud615","\uc785\ucc30\ub2f4\ud569\uc774 \ubd80\ub2f9\uacf5\ub3d9\ud589\uc704 \uc720\ud615 \uc911 \uc5b4\ub514\uc5d0 \ud574\ub2f9\ud558\ub294\uc9c0\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.ayZ,0,"\uc785\ucc30\ub2f4\ud569\uc740 \ub099\ucc30\uc608\uc815\uc790\ub97c \uc0ac\uc804\uc5d0 \uc815\ud558\uace0 \ud22c\ucc30\uac00\uaca9\uc744 \ud569\uc758\ud558\ub294 \ub4f1 \uc2e4\uc9c8\uc801\uc73c\ub85c \uac00\uaca9 \uacb0\uc815, \uac70\ub798\uc0c1\ub300\ubc29 \uc81c\ud55c \ub4f1 \ubd80\ub2f9\uacf5\ub3d9\ud589\uc704\uc758 \uc5ec\ub7ec \ubc95\uc815 \uc720\ud615\uc774 \uacb0\ud569\ub418\uc5b4 \ub098\ud0c0\ub098\ub294 \ub300\ud45c\uc801\uc778 \ub2f4\ud569 \ud615\ud0dc\ub85c \uc774\ud574\ub418\uba70, \uadf8 \uad6c\uccb4\uc801 \ud569\uc758 \ub0b4\uc6a9\uc5d0 \ub530\ub77c \ud574\ub2f9\ud558\ub294 \uc720\ud615\uc774 \ubcf5\ud569\uc801\uc73c\ub85c \uc778\uc815\ub420 \uc218 \uc788\ub2e4.",B.US,B.bii,null)
B.RV=s([u.on,"\uacbd\uc7c1\uc0ac\uc5c5\uc790\uac00 \uc790\ubc1c\uc801\uc73c\ub85c \uc0ac\uc5c5\uc744 \ucd95\uc18c\ud558\ub294 \ud589\uc704","\uc0ac\uc5c5\uc790\uac00 \ub2e8\ub3c5\uc73c\ub85c \uc2e0\uaddc \uc0ac\uc5c5\uc5d0 \uc9c4\ucd9c\ud558\ub294 \ud589\uc704","\uc815\ubd80\uac00 \ud2b9\uc815 \uc0ac\uc5c5\uc790\uc758 \uc778\ud5c8\uac00\ub97c \ucde8\uc18c\ud558\ub294 \ud589\uc704","\uc0ac\uc5c5\uc790\uac00 \uc815\ub2f9\ud55c \uacbd\uc7c1\uc744 \ud1b5\ud574 \uc2dc\uc7a5\uc810\uc720\uc728\uc744 \ud655\ub300\ud558\ub294 \ud589\uc704"],t.s)
B.aaS=s([u.on],t.s)
B.b1W=s(["\ub2e4\ub978 \uc0ac\uc5c5\uc790 \uc0ac\uc5c5\ud65c\ub3d9 \ubc29\ud574 \ub2f4\ud569\uc758 \uc758\ubbf8"],t.s)
B.bP9=new A.a("gen_collusion_type_info_1","economic_law","\ubd80\ub2f9\uacf5\ub3d9\ud589\uc704 \uc720\ud615","\uc815\ubcf4\uad50\ud658\xb7\ub2e4\ub978 \uc0ac\uc5c5\uc790 \uc0ac\uc5c5\ud65c\ub3d9 \ubc29\ud574 \uc720\ud615",'\ubd80\ub2f9\uacf5\ub3d9\ud589\uc704 \uc720\ud615 \uc911 "\ub2e4\ub978 \uc0ac\uc5c5\uc790\uc758 \uc0ac\uc5c5\ud65c\ub3d9 \ub610\ub294 \uc0ac\uc5c5\ub0b4\uc6a9\uc744 \ubc29\ud574\xb7\uc81c\ud55c\ud558\ub294 \ud589\uc704"\uc758 \uc758\ubbf8\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?',B.RV,0,'"\ub2e4\ub978 \uc0ac\uc5c5\uc790\uc758 \uc0ac\uc5c5\ud65c\ub3d9 \ub610\ub294 \uc0ac\uc5c5\ub0b4\uc6a9\uc744 \ubc29\ud574\xb7\uc81c\ud55c\ud558\ub294 \ud589\uc704"\ub294 \ub2f4\ud569\uc5d0 \ucc38\uc5ec\ud558\uc9c0 \uc54a\uac70\ub098 \ub2f4\ud569 \ub0b4\uc6a9\uc744 \ub530\ub974\uc9c0 \uc54a\ub294 \uc0ac\uc5c5\uc790(\uc774\ub978\ubc14 \uc544\uc6c3\uc0ac\uc774\ub354)\uc758 \uc815\uc0c1\uc801\uc778 \uc0ac\uc5c5\ud65c\ub3d9\uc744, \ub2f4\ud569 \ucc38\uc5ec \uc0ac\uc5c5\uc790\ub4e4\uc774 \uacf5\ub3d9\uc73c\ub85c \ubc29\ud574\ud558\uac70\ub098 \uc81c\ud55c\ud568\uc73c\ub85c\uc368 \ub2f4\ud569\uc758 \uc2e4\ud6a8\uc131\uc744 \ud655\ubcf4\ud558\ub824\ub294 \uc720\ud615\uc744 \uc758\ubbf8\ud55c\ub2e4.',B.aaS,B.b1W,null)
B.biu=s([u.L,"\uacf5\uac1c\ub41c \ud1b5\uacc4\uc790\ub8cc\ub97c \ub2e8\uc21c\ud788 \uc5f4\ub78c\ud558\ub294 \ud589\uc704","\uc0ac\uc5c5\uc790\uac00 \uc2dc\uc7a5\uc870\uc0ac\uae30\uad00\uc758 \uacf5\uac1c \ubcf4\uace0\uc11c\ub97c \ucc38\uace0\ud558\ub294 \ud589\uc704","\uc18c\ube44\uc790\uac00 \uc0c1\ud488 \uc815\ubcf4\ub97c \uc778\ud130\ub137\uc5d0\uc11c \uac80\uc0c9\ud558\ub294 \ud589\uc704","\uc0ac\uc5c5\uc790\uac00 \uc790\uc0ac\uc758 \uc7ac\ubb34\uc81c\ud45c\ub97c \uacf5\uc2dc\ud558\ub294 \ud589\uc704"],t.s)
B.aRj=s([u.L],t.s)
B.Yc=s(["\uc815\ubcf4\uad50\ud658 \ub2f4\ud569\uc758 \uc758\ubbf8"],t.s)
B.bO6=new A.a("gen_collusion_type_info_2","economic_law","\ubd80\ub2f9\uacf5\ub3d9\ud589\uc704 \uc720\ud615","\uc815\ubcf4\uad50\ud658\xb7\ub2e4\ub978 \uc0ac\uc5c5\uc790 \uc0ac\uc5c5\ud65c\ub3d9 \ubc29\ud574 \uc720\ud615",'\ubd80\ub2f9\uacf5\ub3d9\ud589\uc704 \uc720\ud615 \uc911 "\uc815\ubcf4\ub97c \uc8fc\uace0\ubc1b\uc74c\uc73c\ub85c\uc368 \uc2e4\uc9c8\uc801\uc73c\ub85c \uacbd\uc7c1\uc744 \uc81c\ud55c\ud558\ub294 \ud589\uc704"\uc758 \uc758\ubbf8\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?',B.biu,0,'"\uc815\ubcf4\uad50\ud658\uc744 \ud1b5\ud55c \uacbd\uc7c1\uc81c\ud55c" \uc720\ud615\uc740 \uc0ac\uc5c5\uc790\ub4e4\uc774 \uac00\uaca9, \uc0dd\uc0b0\ub7c9, \uc6d0\uac00 \ub4f1 \uacbd\uc7c1\uc5d0 \ubbfc\uac10\ud55c \uc815\ubcf4\ub97c \uc11c\ub85c \uad50\ud658\ud558\uace0 \uc774\ub97c \ubc14\ud0d5\uc73c\ub85c \uc0ac\uc5c5\ud65c\ub3d9\uc744 \uc0ac\uc2e4\uc0c1 \uc870\uc728\ud568\uc73c\ub85c\uc368, \uba85\uc2dc\uc801\uc778 \uac00\uaca9\xb7\ubb3c\ub7c9 \ud569\uc758\uac00 \uc5c6\ub354\ub77c\ub3c4 \uc2e4\uc9c8\uc801\uc73c\ub85c \uacbd\uc7c1\uc744 \uc81c\ud55c\ud558\ub294 \ud6a8\uacfc\ub97c \uac00\uc838\uc624\ub294 \ub2f4\ud569 \uc720\ud615\uc73c\ub85c, \ucd5c\uadfc \uc815\ubcf4\uad50\ud658 \ub2f4\ud569\uc5d0 \ub300\ud55c \uaddc\uc81c\uac00 \uba85\uc2dc\uc801\uc73c\ub85c \uac15\ud654\ub41c \ub300\ud45c\uc801\uc778 \ubd84\uc57c\uc774\ub2e4.',B.aRj,B.Yc,null)
B.afX=s([u.zx,"\uc815\ubcf4\uad50\ud658 \ub2f4\ud569\uc740 \uc560\ucd08\uc5d0 \uaddc\uc81c \ub300\uc0c1\uc774 \uc544\ub2c8\uae30 \ub54c\ubb38\uc774\ub2e4","\uc815\ubcf4\uad50\ud658\uc740 \ud56d\uc0c1 \uacf5\uac1c\ub41c \ubc29\uc2dd\uc73c\ub85c\ub9cc \uc774\ub8e8\uc5b4\uc9c0\uae30 \ub54c\ubb38\uc774\ub2e4","\uc815\ubcf4\uad50\ud658 \ub2f4\ud569\uc740 \uc99d\uba85\ucc45\uc784\uc774 \uc0ac\uc5c5\uc790\uc5d0\uac8c \uc788\uae30 \ub54c\ubb38\uc774\ub2e4","\uc815\ubcf4\uad50\ud658 \ub2f4\ud569\uc740 \ud615\uc0ac\ucc98\ubc8c \ub300\uc0c1\uc774 \uc544\ub2c8\uae30 \ub54c\ubb38\uc774\ub2e4"],t.s)
B.aM3=s([u.zx],t.s)
B.a41=s(["\uc815\ubcf4\uad50\ud658 \ub2f4\ud569 \uc785\uc99d\uc758 \uc5b4\ub824\uc6c0"],t.s)
B.bNp=new A.a("gen_collusion_type_info_3","economic_law","\ubd80\ub2f9\uacf5\ub3d9\ud589\uc704 \uc720\ud615","\uc815\ubcf4\uad50\ud658\xb7\ub2e4\ub978 \uc0ac\uc5c5\uc790 \uc0ac\uc5c5\ud65c\ub3d9 \ubc29\ud574 \uc720\ud615","\uc815\ubcf4\uad50\ud658 \ub2f4\ud569\uc774 \uba85\uc2dc\uc801\uc778 \uac00\uaca9 \ud569\uc758\ubcf4\ub2e4 \uc785\uc99d\uc774 \uc5b4\ub824\uc6b4 \uc774\uc720\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.afX,0,"\uc815\ubcf4\uad50\ud658 \ub2f4\ud569\uc740 \uac00\uaca9\uc774\ub098 \ubb3c\ub7c9\uc744 \uc9c1\uc811 \ud569\uc758\ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uc815\ubcf4\ub97c \uad50\ud658\ud558\ub294 \uac04\uc811\uc801\uc778 \ubc29\uc2dd\uc73c\ub85c \uc774\ub8e8\uc5b4\uc9c0\uae30 \ub54c\ubb38\uc5d0, \uadf8\ub7ec\ud55c \uc815\ubcf4\uad50\ud658\uc774 \uc2e4\uc81c\ub85c \uacbd\uc7c1\uc81c\ud55c\uc758 \uc758\ub3c4\ub97c \uac00\uc9c0\uace0 \uc774\ub8e8\uc5b4\uc84c\ub294\uc9c0\uc640 \uc2e4\uc9c8\uc801\uc73c\ub85c \uacbd\uc7c1\uc81c\ud55c \ud6a8\uacfc\ub97c \ub0b3\uc558\ub294\uc9c0\ub97c \ubcc4\ub3c4\ub85c \uc99d\uba85\ud574\uc57c \ud558\ub294 \uc5b4\ub824\uc6c0\uc774 \uc788\ub2e4.",B.aM3,B.a41,null)
B.aeX=s([u.A_,"\ud611\uc758\uccb4 \ud65c\ub3d9\uc774\ubbc0\ub85c \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \uc801\ubc95\ud558\ub2e4","\uac00\ub9f9\uc810 \ubaa8\uc9d1 \ubc29\ud574\ub294 \ub2f4\ud569 \uaddc\uc81c\uc640 \uc804\ud600 \ubb34\uad00\ud558\ub2e4","\uc774\ub7ec\ud55c \ud589\uc704\ub294 \ud56d\uc0c1 \uc18c\ube44\uc790 \ubcf4\ud638\ub97c \uc704\ud55c \uac83\uc73c\ub85c \uc815\ub2f9\ud654\ub41c\ub2e4","\uc774\ub7ec\ud55c \ud589\uc704\ub294 \uc624\uc9c1 \uc0ac\uc5c5\ud65c\ub3d9\ubc29\ud574\ub85c\ub9cc \ud3c9\uac00\ub418\uace0 \ub2f4\ud569\uacfc\ub294 \ubb34\uad00\ud558\ub2e4"],t.s)
B.abf=s([u.A_],t.s)
B.UI=s(["\uac00\ub9f9\ubcf8\ubd80 \ud611\uc758\uccb4\uc758 \uc2e0\uaddc\uc9c4\uc785 \ubc29\ud574"],t.s)
B.bLu=new A.a("gen_collusion_type_info_4","economic_law","\ubd80\ub2f9\uacf5\ub3d9\ud589\uc704 \uc720\ud615","\uc815\ubcf4\uad50\ud658\xb7\ub2e4\ub978 \uc0ac\uc5c5\uc790 \uc0ac\uc5c5\ud65c\ub3d9 \ubc29\ud574 \uc720\ud615","\uac00\ub9f9\ubcf8\ubd80 \ud611\uc758\uccb4\uac00 \ube44\ud68c\uc6d0 \uc2e0\uaddc \ube0c\ub79c\ub4dc\uc758 \uac00\ub9f9\uc810 \ubaa8\uc9d1\uc744 \uc870\uc9c1\uc801\uc73c\ub85c \ubc29\ud574\ud558\ub294 \uacbd\uc6b0\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.aeX,0,"\uae30\uc874 \uac00\ub9f9\ubcf8\ubd80\ub4e4\uc758 \ud611\uc758\uccb4\uac00 \uc2e0\uaddc \uc9c4\uc785 \ube0c\ub79c\ub4dc\uc758 \uac00\ub9f9\uc810 \ubaa8\uc9d1 \ud65c\ub3d9\uc744 \uc870\uc9c1\uc801\uc73c\ub85c \ubc29\ud574\ud558\ub294 \ud589\uc704\ub294, \ub2e4\ub978 \uc0ac\uc5c5\uc790\uc758 \uc0ac\uc5c5\ud65c\ub3d9\uc744 \ubc29\ud574\xb7\uc81c\ud55c\ud558\ub294 \ubd80\ub2f9\uacf5\ub3d9\ud589\uc704 \uc720\ud615\uc5d0 \ud574\ub2f9\ud560 \uc18c\uc9c0\uac00 \uc788\uc73c\uba70, \uc774\ub294 \uc2e0\uaddc \uc9c4\uc785\uc744 \ubd09\uc1c4\ud558\uc5ec \uae30\uc874 \uc0ac\uc5c5\uc790\ub4e4\uc758 \uacbd\uc7c1\uc744 \uc778\uc704\uc801\uc73c\ub85c \uc81c\ud55c\ud558\ub294 \uacb0\uacfc\ub97c \uac00\uc838\uc62c \uc218 \uc788\ub2e4.",B.abf,B.UI,null)
B.aSX=s([u.eK,"\uc720\ud615\uc744 \ud3ed\ub113\uac8c \uaddc\uc815\ud558\uba74 \uc624\ud788\ub824 \ub2f4\ud569 \uaddc\uc81c\uac00 \uc57d\ud654\ub418\uae30 \ub54c\ubb38\uc774\ub2e4","\ubc95\uc815 \uc720\ud615\uc740 \uc2e4\ubb34\uc0c1 \uc804\ud600 \ud65c\uc6a9\ub418\uc9c0 \uc54a\uae30 \ub54c\ubb38\uc774\ub2e4","\ubc95\uc815 \uc720\ud615\uc774 \ub9ce\uc744\uc218\ub85d \uc0ac\uc5c5\uc790\uc5d0\uac8c \uc720\ub9ac\ud558\uae30 \ub54c\ubb38\uc774\ub2e4","\ubc95\uc815 \uc720\ud615\uc740 \ud615\uc2dd\uc801 \ub098\uc5f4\uc5d0 \ubd88\uacfc\ud558\uc5ec \uc2e4\uc9c8\uc801 \uc758\ubbf8\uac00 \uc5c6\ub2e4"],t.s)
B.bhM=s([u.eK],t.s)
B.aiL=s(["\ubc95\uc815 \uc720\ud615\uc774 \ud3ed\ub113\uac8c \uaddc\uc815\ub41c \uc774\uc720"],t.s)
B.bH3=new A.a("gen_collusion_type_info_5","economic_law","\ubd80\ub2f9\uacf5\ub3d9\ud589\uc704 \uc720\ud615","\uc815\ubcf4\uad50\ud658\xb7\ub2e4\ub978 \uc0ac\uc5c5\uc790 \uc0ac\uc5c5\ud65c\ub3d9 \ubc29\ud574 \uc720\ud615","\ubd80\ub2f9\uacf5\ub3d9\ud589\uc704\uc758 \ubc95\uc815 \uc720\ud615\uc774 \uc608\uc2dc\uc801\uc73c\ub85c \ud3ed\ub113\uac8c \uaddc\uc815\ub418\uc5b4 \uc788\ub294 \uc774\uc720\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.aSX,0,"\uacf5\uc815\uac70\ub798\ubc95\uc774 \ubd80\ub2f9\ud55c \uacf5\ub3d9\ud589\uc704\uc758 \uc720\ud615\uc744 \uac00\uaca9, \uac70\ub798\uc870\uac74, \uc0dd\uc0b0\xb7\ucd9c\uace0 \uc81c\ud55c, \uc2dc\uc7a5\ubd84\ud560, \uc124\ube44\uc81c\ud55c, \uc0c1\ud488 \uaddc\uaca9 \uc81c\ud55c, \ud68c\uc0ac \uc124\ub9bd, \uc0ac\uc5c5\ud65c\ub3d9 \ubc29\ud574, \uc815\ubcf4\uad50\ud658 \ub4f1\uc73c\ub85c \ud3ed\ub113\uac8c \uc608\uc2dc\uc801\uc73c\ub85c \uaddc\uc815\ud558\uace0 \uc788\ub294 \uac83\uc740, \uc0ac\uc5c5\uc790\ub4e4\uc774 \ucde8\ud560 \uc218 \uc788\ub294 \ub2f4\ud569\uc758 \ubc29\uc2dd\uc774 \ub9e4\uc6b0 \ub2e4\uc591\ud558\uace0 \uacc4\uc18d \uc9c4\ud654\ud558\ubbc0\ub85c \uc0c8\ub85c\uc6b4 \ud615\ud0dc\uc758 \uacbd\uc7c1\uc81c\ud55c \ud569\uc758\ub3c4 \uaddc\uc728\ud560 \uc218 \uc788\ub3c4\ub85d \ud558\uae30 \uc704\ud568\uc774\ub2e4.",B.bhM,B.aiL,null)
B.WI=s([u.H,"\uc624\uc9c1 \uc0ac\uc5c5\uc790 \ub300\ud45c\uc758 \uac1c\uc778 \uc2e0\uc0c1 \uc815\ubcf4\ub9cc \ucd9c\uc81c\ub41c\ub2e4","\ubd80\ub2f9\uacf5\ub3d9\ud589\uc704 \uc720\ud615\uacfc \ubb34\uad00\ud55c \uc138\ubc95 \uaddc\uc815\ub9cc \ucd9c\uc81c\ub41c\ub2e4","\uc774 \ud30c\ud2b8 \uad00\ub828 \ubb38\uc81c\ub294 \uc804\ud600 \ucd9c\uc81c\ub418\uc9c0 \uc54a\ub294\ub2e4","\uc624\uc9c1 \ub2f4\ud569 \ud68c\uc758 \uc7a5\uc18c\uc758 \uc8fc\uc18c\ub9cc \ubb3b\ub294 \ubb38\uc81c\ub9cc \ucd9c\uc81c\ub41c\ub2e4"],t.s)
B.aGh=s([u.H],t.s)
B.bRF=new A.a("gen_collusion_type_info_6","economic_law","\ubd80\ub2f9\uacf5\ub3d9\ud589\uc704 \uc720\ud615","\uc815\ubcf4\uad50\ud658\xb7\ub2e4\ub978 \uc0ac\uc5c5\uc790 \uc0ac\uc5c5\ud65c\ub3d9 \ubc29\ud574 \uc720\ud615","\uac00\ub9f9\uac70\ub798\uc0ac \uc2dc\ud5d8\uc5d0\uc11c \ubd80\ub2f9\uacf5\ub3d9\ud589\uc704 \uc720\ud615 \uad00\ub828 \ubb38\uc81c\uac00 \uc790\uc8fc \ub2e4\ub8e8\ub294 \ud575\uc2ec \ud3ec\uc778\ud2b8\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.WI,0,"\ubd80\ub2f9\uacf5\ub3d9\ud589\uc704 \uc720\ud615 \uad00\ub828 \ubb38\uc81c\ub294 \uac00\uaca9\xb7\uac70\ub798\uc870\uac74\uc5d0 \uad00\ud55c \uc720\ud615, \uc0dd\uc0b0\xb7\uc2dc\uc7a5\ubd84\ud560\xb7\uc124\ube44\uc81c\ud55c \ub4f1 \uc2dc\uc7a5\uad6c\uc870\uc5d0 \uad00\ud55c \uc720\ud615, \uc815\ubcf4\uad50\ud658\xb7\ub2e4\ub978 \uc0ac\uc5c5\uc790 \uc0ac\uc5c5\ud65c\ub3d9\ubc29\ud574 \uc720\ud615\uc774\ub77c\ub294 \uc138 \uac08\ub798\uc758 \uad6c\ubcc4\uacfc, \uac01 \uc720\ud615\uc5d0 \ud574\ub2f9\ud558\ub294 \uad6c\uccb4\uc801\uc778 \ud589\uc704 \uc608\uc2dc\ub97c \uc815\ud655\ud788 \uad6c\ubd84\ud558\ub294 \uac83\uc744 \uc911\uc2ec\uc73c\ub85c \ucd9c\uc81c\ub418\ub294 \uacbd\ud5a5\uc774 \uc788\ub2e4.",B.aGh,B.bZ,null)
B.azn=s(["\uc2dc\uc7a5\uc810\uc720\uc728 55%\uc778 \ub2e8\uc77c \uc0ac\uc5c5\uc790 A","\uc2dc\uc7a5\uc810\uc720\uc728 40%\uc778 B\uc640 \uc2dc\uc7a5\uc810\uc720\uc728 15%\uc778 C\uc758 \ud569\uc0b0 \uc810\uc720\uc728\uc774 3\uc704 \uc0ac\uc5c5\uc790\uc758 \uc2dc\uc7a5\uc810\uc720\uc728\ubcf4\ub2e4 \ud070 \uacbd\uc6b0\uc758 B, C","\uc2dc\uc7a5\uc810\uc720\uc728 12%\uc5d0 \ubd88\uacfc\ud558\uace0 \uc2dc\uc7a5\uc810\uc720\uc728 \uc21c\uc704\uac00 3\uc704 \uc774\ud558\uc778 D","\uc2dc\uc7a5\uc810\uc720\uc728\uc774 \uac01\uac01 35%, 20%\uc778 3 \uc774\ud558\uc758 \uc0ac\uc5c5\uc790 \uc911 \ud558\ub098\uc778 E","\uacc4\uc5f4\ud68c\uc0ac \ud569\uc0b0 \uc810\uc720\uc728\uc774 40%\uc778 F"],t.s)
B.aQm=s(["\uc21c\uc704\ub3c4 3\uc704 \ubc16\uc778 \uc0ac\uc5c5\uc790\ub294 \uc704 \ub450 \uc694\uac74 \uc911 \uc5b4\ub290 \uac83\ub3c4 \ucda9\uc871\ud558\uc9c0 \ubabb\ud558\ubbc0\ub85c \ucd94\uc815 \ub300\uc0c1\uc5d0\uc11c \uc81c\uc678"],t.s)
B.aPK=s(["\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc0ac\uc5c5\uc790 \ucd94\uc815"],t.s)
B.bw_=new A.a("gen_md_1","economic_law","\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9","\uc2dc\uc7a5\uc810\uc720\uc728","\ub3c5\uc810\uaddc\uc81c \ubc0f \uacf5\uc815\uac70\ub798\uc5d0 \uad00\ud55c \ubc95\ub960\uc0c1 \uc2dc\uc7a5\uc9c0\ubc30\uc801\uc0ac\uc5c5\uc790\ub85c \ucd94\uc815\ub418\uc9c0 \uc54a\ub294 \uacbd\uc6b0\ub294? (\uacc4\uc5f4\uad00\uacc4\ub294 \uc5c6\ub2e4\uace0 \uac00\uc815\ud558\uba70, \uc2dc\uc7a5\uc810\uc720\uc728\uc740 \uc5f0\uac04 \ub9e4\ucd9c\uc561 \uae30\uc900)",B.azn,2,"\uacf5\uc815\uac70\ub798\ubc95 \uc81c6\uc870\ub294 \uc77c\uc815\ud55c \uac70\ub798\ubd84\uc57c\uc5d0\uc11c \u2460 \uc2dc\uc7a5\uc810\uc720\uc728\uc774 1\uc704\uc778 \uc0ac\uc5c5\uc790\uc758 \uc810\uc720\uc728\uc774 50% \uc774\uc0c1\uc774\uac70\ub098, \u2461 \uc2dc\uc7a5\uc810\uc720\uc728 \uc0c1\uc704 3\uac1c \uc774\ud558 \uc0ac\uc5c5\uc790\uc758 \ud569\uc0b0 \uc810\uc720\uc728\uc774 75% \uc774\uc0c1\uc778 \uacbd\uc6b0(\ub2e4\ub9cc \uc810\uc720\uc728\uc774 10% \ubbf8\ub9cc\uc778 \uc0ac\uc5c5\uc790\ub294 \uc81c\uc678)\uc5d0 \uc2dc\uc7a5\uc9c0\ubc30\uc801\uc0ac\uc5c5\uc790\ub85c \ucd94\uc815\ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc774 \uae30\uc900\uc744 \uc801\uc6a9\ud558\uba74 A(55%)\ub294 \u2460\uc5d0 \ud574\ub2f9\ud558\uace0, B(23%)\xb7C(70%)\xb7D(4%)\xb7E(6%)\xb7F(40%) \uac19\uc740 \uc0ac\ub840\uc5d0\uc11c\ub3c4 \uc0c1\uc704 3\uac1c \ud569\uc0b0 \uc810\uc720\uc728\uacfc 10% \ubbf8\ub9cc \uc81c\uc678 \uaddc\uc815\uc744 \uc801\uc6a9\ud574 \ud310\ub2e8\ud574\uc57c \ud55c\ub2e4. \uc2dc\uc7a5\uc810\uc720\uc728\uc774 \ub0ae\uace0(\uc608: 12%) \uc21c\uc704\ub3c4 3\uc704 \ubc16\uc778 \uc0ac\uc5c5\uc790\ub294 \uc704 \ub450 \uc694\uac74 \uc911 \uc5b4\ub290 \uac83\ub3c4 \ucda9\uc871\ud558\uc9c0 \ubabb\ud558\ubbc0\ub85c \ucd94\uc815 \ub300\uc0c1\uc5d0\uc11c \uc81c\uc678\ub41c\ub2e4\ub294 \uc810\uc774 \uc774 \ubb38\uc81c\uc758 \ud575\uc2ec\uc774\ub2e4.",B.aQm,B.aPK,null)
B.aIW=s(["\uac70\ub798\uc758 \uac1d\uccb4\ubcc4\ub85c \uac70\ub798\ub418\ub294 \uc0c1\ud488\uc758 \uc885\ub958 \ubc0f \uc131\uc9c8\uc5d0 \ub530\ub77c \uad6c\ubd84\ub420 \uc218 \uc788\ub294 \uac70\ub798\ubd84\uc57c\ub97c \ub9d0\ud55c\ub2e4","\uc218\uc694\uc790\uac00 \uac00\uaca9 \uc778\uc0c1\uc5d0 \ub300\uc751\ud574 \ub2e4\ub978 \uc0c1\ud488\uc73c\ub85c \ub300\uccb4\ud560 \uc218 \uc788\ub294 \uc815\ub3c4(\uc218\uc694\ub300\uccb4\uc131)\ub97c \uc8fc\uc694 \ud310\ub2e8\uae30\uc900\uc73c\ub85c \uc0bc\ub294\ub2e4","\uacf5\uae09\uc790\uc758 \uc0dd\uc0b0\uc124\ube44 \uc804\ud658 \uac00\ub2a5\uc131 \ub4f1 \uacf5\uae09\ub300\uccb4\uc131\ub3c4 \uc2dc\uc7a5 \ud68d\uc815\uc5d0\uc11c \ud568\uaed8 \uace0\ub824\ub420 \uc218 \uc788\ub2e4","\uac70\ub798\uc758 \uc9c0\ub9ac\uc801 \ubc94\uc704\ub294 \uad00\ub828\uc2dc\uc7a5 \ud68d\uc815\uacfc \ubb34\uad00\ud558\uba70 \uc624\uc9c1 \uc0c1\ud488\uc758 \uc885\ub958\ub9cc\uc73c\ub85c \uc2dc\uc7a5\uc744 \ud68d\uc815\ud55c\ub2e4","\uc77c\uc815\ud55c \uac70\ub798\ubd84\uc57c\ub294 \uac70\ub798\uc758 \uac1d\uccb4\xb7\ub2e8\uacc4\xb7\uc9c0\uc5ed\ubcc4\ub85c \ub2e4\ub974\uac8c \ub098\ud0c0\ub0a0 \uc218 \uc788\ub2e4"],t.s)
B.aRD=s(["\uc9c0\ub9ac\uc801 \ubc94\uc704\ub294 \uad00\ub828\uc2dc\uc7a5 \ud68d\uc815\uacfc \ubb34\uad00"],t.s)
B.adC=s(["\uc77c\uc815\ud55c \uac70\ub798\ubd84\uc57c","\uad00\ub828\uc2dc\uc7a5 \ud68d\uc815"],t.s)
B.bKu=new A.a("gen_md_share_2","economic_law","\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9","\uc2dc\uc7a5\uc810\uc720\uc728",'\ub3c5\uc810\uaddc\uc81c \ubc0f \uacf5\uc815\uac70\ub798\uc5d0 \uad00\ud55c \ubc95\ub960\uc0c1 "\uc77c\uc815\ud55c \uac70\ub798\ubd84\uc57c"(\uad00\ub828\uc2dc\uc7a5) \ud68d\uc815\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?',B.aIW,3,'\uad00\ub828\uc2dc\uc7a5(\uc77c\uc815\ud55c \uac70\ub798\ubd84\uc57c) \ud68d\uc815\uc740 \uc0c1\ud488\uc2dc\uc7a5\ubfd0 \uc544\ub2c8\ub77c \uc9c0\ub9ac\uc801 \uc2dc\uc7a5\ub3c4 \ud568\uaed8 \uace0\ub824\ud558\uc5ec \uc774\ub8e8\uc5b4\uc9c4\ub2e4. \uc218\uc694\uc790\uac00 \ub2e4\ub978 \uc9c0\uc5ed\uc758 \uacf5\uae09\uc790\ub85c\ubd80\ud130 \uc0c1\ud488\uc744 \uc870\ub2ec\ud560 \uc218 \uc788\ub294\uc9c0(\uc9c0\ub9ac\uc801 \ub300\uccb4\uac00\ub2a5\uc131) \uc5ed\uc2dc \uc2dc\uc7a5\uc9c0\ubc30\ub825 \ud310\ub2e8\uc5d0 \uc911\uc694\ud55c \uc694\uc18c\uc774\ubbc0\ub85c, "\uc9c0\ub9ac\uc801 \ubc94\uc704\ub294 \ubb34\uad00\ud558\ub2e4"\ub294 \uc124\uba85\uc740 \uc633\uc9c0 \uc54a\ub2e4. \uc2e4\ubb34\uc0c1 \uad00\ub828\uc2dc\uc7a5\uc740 \uc0c1\ud488\uc2dc\uc7a5\uacfc \uc9c0\uc5ed\uc2dc\uc7a5\uc744 \ud568\uaed8 \ud68d\uc815\ud55c \ub4a4 \uadf8 \uad50\uc9d1\ud569\uc744 \uae30\uc900\uc73c\ub85c \uc2dc\uc7a5\uc9c0\ubc30\uc801 \uc9c0\uc704 \uc5ec\ubd80\ub97c \ud310\ub2e8\ud55c\ub2e4.',B.aRD,B.adC,null)
B.b40=s(["\uc2dc\uc7a5\uc810\uc720\uc728\uc774 10% \ubbf8\ub9cc\uc778 \uc0ac\uc5c5\uc790\ub294 \uc0c1\uc704 3\uac1c \uc0ac\uc5c5\uc790 \ud569\uc0b0 \uc810\uc720\uc728 \uacc4\uc0b0\uc5d0\uc11c \uc81c\uc678\ub41c\ub2e4","\uc2dc\uc7a5\uc810\uc720\uc728 1\uc704 \uc0ac\uc5c5\uc790\uc758 \uc810\uc720\uc728\uc774 40%\uc774\uba74 \uadf8 \uc790\uccb4\ub9cc\uc73c\ub85c \uc2dc\uc7a5\uc9c0\ubc30\uc801\uc0ac\uc5c5\uc790\ub85c \ucd94\uc815\ub41c\ub2e4","\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc0ac\uc5c5\uc790 \ucd94\uc815\uc740 \ud55c\ubc88 \uc131\ub9bd\ud558\uba74 \ubc18\uc99d\uc744 \ud1b5\ud574\uc11c\ub3c4 \ubc88\ubcf5\ud560 \uc218 \uc5c6\ub2e4","\uc5f0\uac04 \ub9e4\ucd9c\uc561 \ub610\ub294 \uacf5\uae09\ub7c9 \uae30\uc900 \uc911 \uc5b4\ub290 \ud558\ub098\ub9cc \uc0ac\uc6a9\ud560 \uc218 \uc788\uace0 \ubcd1\ud589 \uc0ac\uc6a9\uc740 \ud5c8\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4","\ucd94\uc815 \uc694\uac74\uc744 \ucda9\uc871\ud558\ub294 \uc0ac\uc5c5\uc790\uac00 \ub2e4\uc218\uc778 \uacbd\uc6b0 \uadf8\uc911 1\uac1c \uc0ac\uc5c5\uc790\ub9cc \uc9c0\ubc30\uc801\uc0ac\uc5c5\uc790\ub85c \uc9c0\uc815\ub41c\ub2e4"],t.s)
B.aDs=s(["\uc2dc\uc7a5\uc810\uc720\uc728\uc774 10% \ubbf8\ub9cc\uc778 \uc0ac\uc5c5\uc790\ub294 \uadf8 \uc0b0\uc815\uc5d0\uc11c \uc81c\uc678"],t.s)
B.b8l=s(["\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc0ac\uc5c5\uc790 \ucd94\uc815","10% \ubbf8\ub9cc \uc81c\uc678"],t.s)
B.bP1=new A.a("gen_md_share_3","economic_law","\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9","\uc2dc\uc7a5\uc810\uc720\uc728","\ub3c5\uc810\uaddc\uc81c \ubc0f \uacf5\uc815\uac70\ub798\uc5d0 \uad00\ud55c \ubc95\ub960\uc0c1 \uc2dc\uc7a5\uc9c0\ubc30\uc801\uc0ac\uc5c5\uc790 \ucd94\uc815\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740? (\uacc4\uc5f4\uad00\uacc4 \uc5c6\uc74c\uc744 \uc804\uc81c)",B.b40,0,"\uacf5\uc815\uac70\ub798\ubc95 \uc2dc\ud589\ub839\uc740 \uc2dc\uc7a5\uc810\uc720\uc728 \uc0c1\uc704 3\uac1c \uc774\ud558 \uc0ac\uc5c5\uc790\uc758 \ud569\uc0b0 \uc810\uc720\uc728\uc774 75% \uc774\uc0c1\uc778 \uacbd\uc6b0\ub97c \ucd94\uc815 \uc694\uac74\uc73c\ub85c \uc0bc\ub418, \uc774\ub54c \uc2dc\uc7a5\uc810\uc720\uc728\uc774 10% \ubbf8\ub9cc\uc778 \uc0ac\uc5c5\uc790\ub294 \uadf8 \uc0b0\uc815\uc5d0\uc11c \uc81c\uc678\ud558\ub3c4\ub85d \uc815\ud558\uace0 \uc788\ub2e4. 1\uc704 \uc0ac\uc5c5\uc790\uc758 \uc810\uc720\uc728\uc774 50% \ubbf8\ub9cc(\uc608: 40%)\uc774\uba74 \ub2e8\ub3c5 \ucd94\uc815 \uc694\uac74(50% \uc774\uc0c1)\uc744 \ucda9\uc871\ud558\uc9c0 \ubabb\ud558\ubbc0\ub85c \uadf8 \uc790\uccb4\ub9cc\uc73c\ub85c \ucd94\uc815\ub418\uc9c0 \uc54a\uc73c\uba70, \ucd94\uc815\uc740 \ubc95\ub960\uc0c1 \ucd94\uc815\uc73c\ub85c\uc11c \ubc18\uc99d\uc744 \ud1b5\ud574 \ubc88\ubcf5\ub420 \uc218 \uc788\ub2e4. \ub9e4\ucd9c\uc561\xb7\uacf5\uae09\ub7c9 \uae30\uc900\uc740 \uc0ac\uc5c5\uc758 \ud2b9\uc131\uc5d0 \ub530\ub77c \uc801\uc808\ud788 \uc120\ud0dd\ub418\ub294 \uac83\uc774\uc9c0 \ubcd1\ud589 \uc0ac\uc6a9\uc774 \uae08\uc9c0\ub418\ub294 \uac83\ub3c4 \uc544\ub2c8\ub2e4.",B.aDs,B.b8l,null)
B.aHq=s(["\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc0ac\uc5c5\uc790 \uc5ec\ubd80\ub97c \ud310\ub2e8\ud560 \ub54c \uacc4\uc5f4\ud68c\uc0ac\uc758 \uc2dc\uc7a5\uc810\uc720\uc728\uc740 \uc6d0\uce59\uc801\uc73c\ub85c \ud569\uc0b0\ud558\uc5ec \uace0\ub824\ud55c\ub2e4","\uacc4\uc5f4\ud68c\uc0ac \uad00\uacc4\ub294 \uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ud310\ub2e8\uacfc \uc804\ud600 \uad00\ub828\uc774 \uc5c6\ub2e4","\uacc4\uc5f4\ud68c\uc0ac\uac00 \uba87 \uac1c\uc774\ub4e0 \ud569\uc0b0 \uc810\uc720\uc728\uc740 \ud56d\uc0c1 \ub2e8\ub3c5 \uc0ac\uc5c5\uc790\uc758 \uc810\uc720\uc728\ubcf4\ub2e4 \ub0ae\uac8c \uacc4\uc0b0\ub41c\ub2e4","\uacc4\uc5f4\ud68c\uc0ac \ud569\uc0b0\uc740 \ubd80\ub2f9\ud55c \uacf5\ub3d9\ud589\uc704 \ud310\ub2e8\uc5d0\uc11c\ub9cc \uc801\uc6a9\ub418\uace0 \uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ud310\ub2e8\uc5d0\ub294 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4","\uacc4\uc5f4\ud68c\uc0ac \uc5ec\ubd80\uc640 \ubb34\uad00\ud558\uac8c \uac1c\ubcc4 \ubc95\uc778\uc758 \uc810\uc720\uc728\ub9cc \ub3c5\ub9bd\uc801\uc73c\ub85c \ud310\ub2e8\ud55c\ub2e4"],t.s)
B.aUi=s(["\uacc4\uc5f4\ud68c\uc0ac\uc758 \uc2dc\uc7a5\uc810\uc720\uc728\uc740 \uc6d0\uce59\uc801\uc73c\ub85c \ud569\uc0b0\ud558\uc5ec \uace0\ub824\ud55c\ub2e4"],t.s)
B.b4l=s(["\uacc4\uc5f4\ud68c\uc0ac \ud569\uc0b0","\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc0ac\uc5c5\uc790 \ud310\ub2e8"],t.s)
B.bt2=new A.a("gen_md_share_4","economic_law","\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9","\uc2dc\uc7a5\uc810\uc720\uc728","\ub3c5\uc810\uaddc\uc81c \ubc0f \uacf5\uc815\uac70\ub798\uc5d0 \uad00\ud55c \ubc95\ub960\uc0c1 \uacc4\uc5f4\ud68c\uc0ac\uc758 \uc2dc\uc7a5\uc810\uc720\uc728 \ud569\uc0b0\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aHq,0,"\uacf5\uc815\uac70\ub798\ubc95\uc0c1 \uc2dc\uc7a5\uc9c0\ubc30\uc801\uc0ac\uc5c5\uc790 \uc5ec\ubd80\ub97c \ud310\ub2e8\ud560 \ub54c\ub294 \uc0ac\uc5c5\uc790\uac00 \uc18d\ud55c \uae30\uc5c5\uc9d1\ub2e8\uc758 \uacc4\uc5f4\ud68c\uc0ac \uc2dc\uc7a5\uc810\uc720\uc728\uc744 \ud569\uc0b0\ud558\uc5ec \uace0\ub824\ud558\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub2e4. \uc774\ub294 \ud615\uc2dd\uc801\uc73c\ub85c\ub294 \ubcc4\uac1c \ubc95\uc778\uc774\ub354\ub77c\ub3c4 \uc2e4\uc9c8\uc801\uc73c\ub85c \ub3d9\uc77c\ud55c \uc9c0\ubc30\ub825 \uc544\ub798 \uc788\ub294 \uacc4\uc5f4\ud68c\uc0ac\ub4e4\uc758 \uc2dc\uc7a5\uc810\uc720\uc728\uc744 \uac1c\ubcc4\uc801\uc73c\ub85c\ub9cc \ubcf4\uba74 \uc2e4\uc81c \uc2dc\uc7a5\uc9c0\ubc30\ub825\uc744 \uacfc\uc18c\ud3c9\uac00\ud560 \uc704\ud5d8\uc774 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \ub530\ub77c\uc11c \uacc4\uc5f4\uad00\uacc4\uac00 \uc788\ub294 \uacbd\uc6b0 \ud569\uc0b0 \uc810\uc720\uc728\uc744 \uae30\uc900\uc73c\ub85c \ucd94\uc815 \uc694\uac74 \ucda9\uc871 \uc5ec\ubd80\ub97c \ud310\ub2e8\ud574\uc57c \ud55c\ub2e4.",B.aUi,B.b4l,null)
B.SM=s(["\ucd94\uc815 \uaddc\uc815\uc740 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uc758 \uc785\uc99d \ubd80\ub2f4\uc744 \uc644\ud654\ud558\uae30 \uc704\ud55c \uac83\uc774\ub2e4","\ucd94\uc815\uc744 \ubc1b\uc740 \uc0ac\uc5c5\uc790\ub294 \uc2e4\uc81c\ub85c\ub294 \uc2dc\uc7a5\uc9c0\ubc30\ub825\uc774 \uc5c6\ub2e4\ub294 \uc810\uc744 \ubc18\uc99d\ud558\uc5ec \ucd94\uc815\uc744 \ubc88\ubcf5\ud560 \uc218 \uc788\ub2e4","\ucd94\uc815 \uc694\uac74\uc740 \uc2dc\uc7a5\uc810\uc720\uc728\ub9cc\uc744 \uae30\uc900\uc73c\ub85c \ud558\uba70 \uc9c4\uc785\uc7a5\ubcbd\xb7\uacbd\uc7c1\uc0ac\uc5c5\uc790 \uc218 \ub4f1 \ub2e4\ub978 \uc0ac\uc815\uc740 \uc804\ud600 \uace0\ub824\ub418\uc9c0 \uc54a\ub294\ub2e4","\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc0ac\uc5c5\uc790\uc5d0\ub294 \uc0c1\ud488\uc774\ub098 \uc6a9\uc5ed\uc744 \uacf5\uae09\ud558\ub294 \uc0ac\uc5c5\uc790\ubfd0 \uc544\ub2c8\ub77c \uc218\uc694\uc790\uc758 \uc9c0\uc704\uc5d0 \uc788\ub294 \uc0ac\uc5c5\uc790\ub3c4 \ud3ec\ud568\ub420 \uc218 \uc788\ub2e4","\ucd94\uc815\uc744 \ubc1b\uc9c0 \uc54a\uc740 \uc0ac\uc5c5\uc790\ub3c4 \ub2e4\ub978 \uc0ac\uc815\uc744 \uadfc\uac70\ub85c \uc2dc\uc7a5\uc9c0\ubc30\uc801\uc0ac\uc5c5\uc790\ub85c \uc778\uc815\ub420 \uc218 \uc788\ub2e4"],t.s)
B.bfb=s(["\uc9c4\uc785\uc7a5\ubcbd\uc758 \uc874\uc7ac, \uacbd\uc7c1\uc0ac\uc5c5\uc790\uc758 \uc218\uc640 \uaddc\ubaa8, \uc720\uc0ac\ud488\xb7\uc778\uc811\uc2dc\uc7a5\uc758 \uc874\uc7ac \uc5ec\ubd80 \ub4f1 \ub2e4\uc591\ud55c \uc0ac\uc815\uc774 \ud568\uaed8 \uace0\ub824"],t.s)
B.SJ=s(["\uc2dc\uc7a5\uc9c0\ubc30\ub825 \uc2e4\uc9c8\ud310\ub2e8","\ucd94\uc815\uc758 \uc131\uaca9"],t.s)
B.bys=new A.a("gen_md_share_5","economic_law","\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9","\uc2dc\uc7a5\uc810\uc720\uc728","\ub3c5\uc810\uaddc\uc81c \ubc0f \uacf5\uc815\uac70\ub798\uc5d0 \uad00\ud55c \ubc95\ub960\uc0c1 \uc2dc\uc7a5\uc9c0\ubc30\uc801\uc0ac\uc5c5\uc790 \ucd94\uc815\uacfc \uad00\ub828\ud558\uc5ec \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.SM,2,'\uc2dc\uc7a5\uc810\uc720\uc728\uc5d0 \uc758\ud55c \ucd94\uc815\uc740 \uc2dc\uc7a5\uc9c0\ubc30\uc801\uc0ac\uc5c5\uc790 \ud310\ub2e8\uc744 \uc6a9\uc774\ud558\uac8c \ud558\uae30 \uc704\ud55c \ubc95\ub960\uc0c1 \ucd94\uc815\uc5d0 \ubd88\uacfc\ud558\uba70, \uc2e4\uc81c \uc2dc\uc7a5\uc9c0\ubc30\ub825 \uc720\ubb34\ub97c \ucd5c\uc885\uc801\uc73c\ub85c \ud310\ub2e8\ud560 \ub54c\ub294 \uc9c4\uc785\uc7a5\ubcbd\uc758 \uc874\uc7ac, \uacbd\uc7c1\uc0ac\uc5c5\uc790\uc758 \uc218\uc640 \uaddc\ubaa8, \uc720\uc0ac\ud488\xb7\uc778\uc811\uc2dc\uc7a5\uc758 \uc874\uc7ac \uc5ec\ubd80 \ub4f1 \ub2e4\uc591\ud55c \uc0ac\uc815\uc774 \ud568\uaed8 \uace0\ub824\ub41c\ub2e4. \ub530\ub77c\uc11c "\uc2dc\uc7a5\uc810\uc720\uc728\ub9cc\uc744 \uae30\uc900\uc73c\ub85c \ud558\uba70 \ub2e4\ub978 \uc0ac\uc815\uc740 \uc804\ud600 \uace0\ub824\ub418\uc9c0 \uc54a\ub294\ub2e4"\ub294 \uc124\uba85\uc740 \uc633\uc9c0 \uc54a\ub2e4. \ucd94\uc815\uc744 \ubc1b\uc9c0 \ubabb\ud55c \uc0ac\uc5c5\uc790\ub77c\ub3c4 \uc774\ub7ec\ud55c \uc2e4\uc9c8\uc801 \uc0ac\uc815\uc5d0 \ub530\ub77c \uc9c0\ubc30\uc801\uc0ac\uc5c5\uc790\ub85c \uc778\uc815\ub420 \uc218 \uc788\uace0, \ubc18\ub300\ub85c \ucd94\uc815\ub41c \uc0ac\uc5c5\uc790\ub3c4 \ubc18\uc99d\uc73c\ub85c \uc774\ub97c \ubc88\ubcf5\ud560 \uc218 \uc788\ub2e4.',B.bfb,B.SJ,null)
B.aQg=s(["\uc6d0\uce59\uc801\uc73c\ub85c \ucd5c\uadfc \uc0ac\uc5c5\uc5f0\ub3c4\uc758 \uad6d\ub0b4 \uacf5\uae09\ub41c \uc0c1\ud488\xb7\uc6a9\uc5ed\uc758 \ub9e4\ucd9c\uc561 \ub610\ub294 \ub9e4\ucd9c\uc561 \ube44\uc728\ub85c \uc0b0\uc815\ud55c\ub2e4","\uc2dc\uc7a5\uc810\uc720\uc728\uc740 \uc624\uc9c1 \uc218\ucd9c\uc561\ub9cc\uc744 \uae30\uc900\uc73c\ub85c \uc0b0\uc815\ud55c\ub2e4","\uc6a9\uc5ed\uc5c5\uc758 \uacbd\uc6b0 \uc2dc\uc7a5\uc810\uc720\uc728 \uc0b0\uc815 \uc790\uccb4\uac00 \ubd88\uac00\ub2a5\ud558\ub2e4","\ub9e4\ucd9c\uc561 \uc0b0\uc815\uc774 \uace4\ub780\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \uacf5\uae09\ub7c9 \ub4f1 \uad00\ub828 \uc790\ub8cc\ub97c \uc0ac\uc6a9\ud560 \uc218 \uc5c6\ub2e4","\uc2dc\uc7a5\uc810\uc720\uc728\uc740 \ud56d\uc0c1 \uc804\uc138\uacc4 \ub9e4\ucd9c\uc561\uc744 \uae30\uc900\uc73c\ub85c \uc0b0\uc815\ud55c\ub2e4"],t.s)
B.awN=s(["\ucd5c\uadfc \uc0ac\uc5c5\uc5f0\ub3c4\uc758 \uad6d\ub0b4 \uacf5\uae09\ub41c \uc0c1\ud488\xb7\uc6a9\uc5ed\uc758 \ub9e4\ucd9c\uc561 \ub610\ub294 \ub9e4\ucd9c\uc561 \ube44\uc728\ub85c \uc0b0\uc815"],t.s)
B.ag8=s(["\uc2dc\uc7a5\uc810\uc720\uc728 \uc0b0\uc815\uae30\uc900"],t.s)
B.btz=new A.a("gen_md_share_6","economic_law","\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9","\uc2dc\uc7a5\uc810\uc720\uc728","\ub3c5\uc810\uaddc\uc81c \ubc0f \uacf5\uc815\uac70\ub798\uc5d0 \uad00\ud55c \ubc95\ub960\uc0c1 \uc2dc\uc7a5\uc810\uc720\uc728 \uc0b0\uc815 \uae30\uc900\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aQg,0,"\uc2dc\uc7a5\uc810\uc720\uc728\uc740 \uc6d0\uce59\uc801\uc73c\ub85c \ud574\ub2f9 \uc0ac\uc5c5\uc790\uac00 \ucd5c\uadfc \uc0ac\uc5c5\uc5f0\ub3c4\uc5d0 \uad6d\ub0b4\uc5d0\uc11c \uacf5\uae09\ud55c \uc0c1\ud488\xb7\uc6a9\uc5ed\uc758 \ub9e4\ucd9c\uc561(\ub610\ub294 \ub9e4\ucd9c\uc561 \ube44\uc728)\uc744 \uae30\uc900\uc73c\ub85c \uc0b0\uc815\ud55c\ub2e4. \ub9e4\ucd9c\uc561 \uc0b0\uc815\uc774 \uace4\ub780\ud55c \uacbd\uc6b0\uc5d0\ub294 \uacf5\uae09\ub7c9, \uc0dd\uc0b0\ub2a5\ub825, \uc790\uc0b0\ucd1d\uc561 \ub4f1 \uad00\ub828 \uc790\ub8cc\ub97c \ud65c\uc6a9\ud574 \uc0b0\uc815\ud560 \uc218 \uc788\ub3c4\ub85d \ud558\uace0 \uc788\uc73c\uba70, \uc774\ub294 \uc0c1\ud488\uc5c5\ubfd0 \uc544\ub2c8\ub77c \uc6a9\uc5ed\uc5c5\uc5d0\ub3c4 \ub3d9\uc77c\ud558\uac8c \uc801\uc6a9\ub41c\ub2e4. \uad6d\ub0b4\uc2dc\uc7a5\uc744 \ub300\uc0c1\uc73c\ub85c \ud558\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ubbc0\ub85c \uc218\ucd9c\uc561\uc774\ub098 \uc804\uc138\uacc4 \ub9e4\ucd9c\uc561\uc744 \uae30\uc900\uc73c\ub85c \ud558\uc9c0 \uc54a\ub294\ub2e4.",B.awN,B.ag8,null)
B.aur=s(["\u3131, \u3134","\u3131, \u3137","\u3134, \u3137","\u3134, \u3139","\u3137, \u3139"],t.s)
B.ayU=s(["\uc2e0\uaddc \uacbd\uc7c1\uc0ac\uc5c5\uc790\uc5d0\uac8c \ud544\uc218\uc801\uc778 \uc694\uc18c(\uc124\ube44\xb7\uae30\uc220 \ub4f1)\uc758 \uc0ac\uc6a9\xb7\uc811\uadfc\uc744 \uac70\uc808\ud558\ub294 \ud589\uc704(\u3137)\uac00 \ub300\ud45c\uc801"],t.s)
B.a18=s(["\uc2dc\uc7a5\ucc38\uac00 \ubc29\ud574\ud589\uc704"],t.s)
B.bw9=new A.a("gen_md_2","economic_law","\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9","\ud589\uc704 \uc720\ud615","\ub3c5\uc810\uaddc\uc81c \ubc0f \uacf5\uc815\uac70\ub798\uc5d0 \uad00\ud55c \ubc95\ub960\uc0c1 \uc2dc\uc7a5\uc9c0\ubc30\uc801\uc0ac\uc5c5\uc790\uc758 \uc9c0\uc704\ub0a8\uc6a9 \ud589\uc704 \uc720\ud615 \uc911 \uc0c8\ub85c\uc6b4 \uacbd\uc7c1\uc0ac\uc5c5\uc790\uc758 \uc2dc\uc7a5\ucc38\uac00 \ubc29\ud574\ud589\uc704\uc5d0 \ud574\ub2f9\ud558\ub294 \uac83\uc744 \ubaa8\ub450 \uace0\ub978 \uac83\uc740?\n\n\u3131. \uc815\ub2f9\ud55c \uc774\uc720 \uc5c6\uc774 \uac70\ub798\ud558\ub294 \uc720\ud1b5\uc0ac\uc5c5\uc790\uc640 \ubc30\ud0c0\uc801 \uac70\ub798\uacc4\uc57d\uc744 \uccb4\uacb0\ud558\ub294 \ud589\uc704\n\u3134. \uc815\ub2f9\ud55c \uc774\uc720 \uc5c6\uc774 \ub2e4\ub978 \uc0ac\uc5c5\uc790\uc758 \uc0ac\uc5c5\ud65c\ub3d9\uc744 \ubc29\ud574\ud558\uae30 \uc704\ud574 \uc800\uac00\ub85c \uc0c1\ud488\uc744 \ud310\ub9e4\ud558\ub294 \ud589\uc704\n\u3137. \uc815\ub2f9\ud55c \uc774\uc720 \uc5c6\uc774 \uc0c8\ub85c\uc6b4 \uacbd\uc7c1\uc0ac\uc5c5\uc790\uc758 \uc0c1\ud488 \uc0dd\uc0b0\uc5d0 \ud544\uc218\uc801\uc778 \uc694\uc18c\uc758 \uc0ac\uc6a9\uc744 \uac70\uc808\ud558\ub294 \ud589\uc704\n\u3139. \uc18c\ube44\uc790\uc758 \uc774\uc775\uc744 \ud604\uc800\ud788 \uc800\ud574\ud560 \uc6b0\ub824\uac00 \uc788\ub294 \uac00\uaca9\uc744 \uacb0\uc815\ud558\ub294 \ud589\uc704",B.aur,1,'\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9\ud589\uc704 \uc911 "\uc2e0\uaddc \uacbd\uc7c1\uc0ac\uc5c5\uc790\uc758 \uc2dc\uc7a5\ucc38\uac00 \ubc29\ud574\ud589\uc704"\ub294 \uc0c8\ub85c\uc6b4 \uc0ac\uc5c5\uc790\uac00 \uc2dc\uc7a5\uc5d0 \uc9c4\uc785\ud558\ub294 \uac83 \uc790\uccb4\ub97c \uc5b4\ub835\uac8c \ub9cc\ub4dc\ub294 \ud589\uc704\ub97c \uaddc\uc81c\ud558\ub294 \uc720\ud615\uc73c\ub85c, \uc815\ub2f9\ud55c \uc774\uc720 \uc5c6\ub294 \ubc30\ud0c0\uc801 \uac70\ub798\uacc4\uc57d \uccb4\uacb0(\u3131)\uacfc \uc2e0\uaddc \uacbd\uc7c1\uc0ac\uc5c5\uc790\uc5d0\uac8c \ud544\uc218\uc801\uc778 \uc694\uc18c(\uc124\ube44\xb7\uae30\uc220 \ub4f1)\uc758 \uc0ac\uc6a9\xb7\uc811\uadfc\uc744 \uac70\uc808\ud558\ub294 \ud589\uc704(\u3137)\uac00 \ub300\ud45c\uc801\uc774\ub2e4. \ubc18\uba74 \u3134(\uc800\uac00 \ud310\ub9e4\ub85c \uc0ac\uc5c5\ud65c\ub3d9 \ubc29\ud574)\uc740 \uc774\ubbf8 \uc2dc\uc7a5\uc5d0 \uc874\uc7ac\ud558\ub294 \uc0ac\uc5c5\uc790\ub97c \uaca8\ub0e5\ud55c "\ub2e4\ub978 \uc0ac\uc5c5\uc790\uc758 \uc0ac\uc5c5\ud65c\ub3d9 \ubc29\ud574" \uc720\ud615\uc774\uace0, \u3139(\uc18c\ube44\uc790\uc774\uc775\uc744 \uc800\ud574\ud560 \uc6b0\ub824\uac00 \uc788\ub294 \uac00\uaca9 \uacb0\uc815)\uc740 \ubcc4\ub3c4\uc758 \ub3c5\uc790\uc801\uc778 \ub0a8\uc6a9\ud589\uc704 \uc720\ud615(\uc18c\ube44\uc790\uc774\uc775 \uc800\ud574\ud589\uc704)\uc73c\ub85c \ubd84\ub958\ub41c\ub2e4. \ub2e4\uc12f \uac00\uc9c0 \ub0a8\uc6a9\ud589\uc704 \uc720\ud615\uc744 \uc11c\ub85c \uad6c\ubd84\ud574\uc11c \uc554\uae30\ud558\ub294 \uac83\uc774 \uc774 \ucc55\ud130\uc758 \ud575\uc2ec\uc774\ub2e4.',B.ayU,B.a18,null)
B.a9m=s(["\uc0c1\ud488\uc758 \uac00\uaca9\uc744 \uc815\ub2f9\ud55c \uc774\uc720 \uc5c6\uc774 \ubd80\ub2f9\ud558\uac8c \uacb0\uc815\xb7\uc720\uc9c0 \ub610\ub294 \ubcc0\uacbd\ud558\ub294 \ud589\uc704\ub97c \ub9d0\ud55c\ub2e4","\uc6d0\uac00 \uc0c1\uc2b9 \ub4f1 \uc815\ub2f9\ud55c \uc0ac\uc720\uac00 \uc788\ub294 \uac00\uaca9 \uc778\uc0c1\uc740 \uc6d0\uce59\uc801\uc73c\ub85c \uac00\uaca9\ub0a8\uc6a9\uc5d0 \ud574\ub2f9\ud558\uc9c0 \uc54a\ub294\ub2e4","\uac00\uaca9\ubfd0\ub9cc \uc544\ub2c8\ub77c \uc6a9\uc5ed\uc758 \ub300\uac00\ub3c4 \uaddc\uc81c \ub300\uc0c1\uc5d0 \ud3ec\ud568\ub41c\ub2e4","\uac00\uaca9\uc758 \uc778\uc0c1\ubfd0\ub9cc \uc544\ub2c8\ub77c \ubd80\ub2f9\ud55c \uc778\ud558\ub3c4 \uaddc\uc81c \ub300\uc0c1\uc774 \ub420 \uc218 \uc788\ub2e4","\uac00\uaca9\ub0a8\uc6a9\uc5d0 \ud574\ub2f9\ud558\ub824\uba74 \ubc18\ub4dc\uc2dc \uc2e4\uc81c\ub85c \uacbd\uc7c1\uc0ac\uc5c5\uc790\uac00 \uc2dc\uc7a5\uc5d0\uc11c \ud1f4\ucd9c\ub418\uc5b4\uc57c \ud55c\ub2e4"],t.s)
B.ajF=s(["\uadf8\ub85c \uc778\ud574 \uacbd\uc7c1\uc0ac\uc5c5\uc790\uac00 \uc2e4\uc81c\ub85c \uc2dc\uc7a5\uc5d0\uc11c \ud1f4\ucd9c\ub418\ub294 \uacb0\uacfc\uae4c\uc9c0 \uc694\uad6c\ud558\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.aVY=s(["\uac00\uaca9\ub0a8\uc6a9"],t.s)
B.bsj=new A.a("gen_md_type_2","economic_law","\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9","\ud589\uc704 \uc720\ud615",'\ub3c5\uc810\uaddc\uc81c \ubc0f \uacf5\uc815\uac70\ub798\uc5d0 \uad00\ud55c \ubc95\ub960\uc0c1 \uc2dc\uc7a5\uc9c0\ubc30\uc801\uc0ac\uc5c5\uc790\uc758 "\uac00\uaca9\ub0a8\uc6a9" \ud589\uc704\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?',B.a9m,4,"\uac00\uaca9\ub0a8\uc6a9\uc740 \uc2dc\uc7a5\uc9c0\ubc30\uc801\uc0ac\uc5c5\uc790\uac00 \uc815\ub2f9\ud55c \uc774\uc720 \uc5c6\uc774 \uac00\uaca9(\ub610\ub294 \uc6a9\uc5ed\uc758 \ub300\uac00)\uc744 \ubd80\ub2f9\ud558\uac8c \uacb0\uc815\xb7\uc720\uc9c0\xb7\ubcc0\uacbd\ud558\ub294 \ud589\uc704 \uc790\uccb4\ub97c \uaddc\uc81c\ud558\ub294 \uac83\uc73c\ub85c, \uadf8\ub85c \uc778\ud574 \uacbd\uc7c1\uc0ac\uc5c5\uc790\uac00 \uc2e4\uc81c\ub85c \uc2dc\uc7a5\uc5d0\uc11c \ud1f4\ucd9c\ub418\ub294 \uacb0\uacfc\uae4c\uc9c0 \uc694\uad6c\ud558\uc9c0 \uc54a\ub294\ub2e4. \ubd80\ub2f9\uc131 \ud310\ub2e8\uc740 \uc6d0\uac00 \ubcc0\ub3d9 \uc694\uc778, \uc720\uc0ac \uc2dc\uc7a5\uc758 \uac00\uaca9 \uc218\uc900, \uc774\uc724 \ud3ed\uc758 \ubcc0\ud654 \ub4f1\uc744 \uc885\ud569\uc801\uc73c\ub85c \uace0\ub824\ud558\uba70, \uc778\uc0c1\ubfd0 \uc544\ub2c8\ub77c \ubd80\ub2f9\ud55c \uc778\ud558(\uc6d0\uac00 \uc774\ud558 \ud310\ub9e4\ub97c \ud1b5\ud55c \uacbd\uc7c1\uc81c\ud55c \ub4f1)\ub3c4 \uaddc\uc81c \ub300\uc0c1\uc774 \ub420 \uc218 \uc788\ub2e4.",B.ajF,B.aVY,null)
B.ar1=s(["\uc815\ub2f9\ud55c \uc774\uc720 \uc5c6\uc774 \uc0c1\ud488\uc758 \uacf5\uae09\ub7c9\uc744 \ucd5c\uadfc\uc758 \ucd94\uc138\uc5d0 \ube44\ucd94\uc5b4 \ud604\uc800\ud788 \uac10\uc18c\uc2dc\ud0a4\ub294 \ud589\uc704","\uc2e0\uaddc \uacbd\uc7c1\uc0ac\uc5c5\uc790\uc640 \ubc30\ud0c0\uc801 \uac70\ub798\uacc4\uc57d\uc744 \uccb4\uacb0\ud558\ub294 \ud589\uc704","\uac70\ub798\uc0c1\ub300\ubc29\uc5d0\uac8c \ubd80\ub2f9\ud558\uac8c \uc774\uc775\uc744 \uc81c\uacf5\ud558\ub3c4\ub85d \uac15\uc694\ud558\ub294 \ud589\uc704","\uacbd\uc7c1\uc0ac\uc5c5\uc790\ub97c \ubc30\uc81c\ud558\uae30 \uc704\ud558\uc5ec \uc815\uc0c1\uac70\ub798\uad00\ud589\uc5d0 \ube44\ucd94\uc5b4 \uc774\ub840\uc801\uc778 \uc870\uac74\uc73c\ub85c \uac70\ub798\ud558\ub294 \ud589\uc704","\ub2e4\ub978 \uc0ac\uc5c5\uc790\uc758 \uc0ac\uc5c5\ud65c\ub3d9\uc744 \ubd80\ub2f9\ud558\uac8c \ubc29\ud574\ud558\ub294 \ud589\uc704"],t.s)
B.bdZ=s(["\uc0c1\ud488\uc758 \uc0dd\uc0b0\xb7\ucd9c\uace0\xb7\ud310\ub9e4\ub97c \ucd5c\uadfc\uc758 \ucd94\uc138\uc5d0 \ube44\ucd94\uc5b4 \ud604\uc800\ud788 \uac10\uc18c\uc2dc\ud0a4\uac70\ub098 \uc99d\uac00\uc2dc\ucf1c"],t.s)
B.b7A=s(["\ucd9c\uace0\uc870\uc808"],t.s)
B.bHe=new A.a("gen_md_type_3","economic_law","\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9","\ud589\uc704 \uc720\ud615",'\ub3c5\uc810\uaddc\uc81c \ubc0f \uacf5\uc815\uac70\ub798\uc5d0 \uad00\ud55c \ubc95\ub960\uc0c1 "\ucd9c\uace0\uc870\uc808" \ud589\uc704\uc5d0 \ud574\ub2f9\ud558\ub294 \uac83\uc740?',B.ar1,0,"\ucd9c\uace0\uc870\uc808\uc740 \uc2dc\uc7a5\uc9c0\ubc30\uc801\uc0ac\uc5c5\uc790\uac00 \uc815\ub2f9\ud55c \uc774\uc720 \uc5c6\uc774 \uc0c1\ud488\uc758 \uc0dd\uc0b0\xb7\ucd9c\uace0\xb7\ud310\ub9e4\ub97c \ucd5c\uadfc\uc758 \ucd94\uc138\uc5d0 \ube44\ucd94\uc5b4 \ud604\uc800\ud788 \uac10\uc18c\uc2dc\ud0a4\uac70\ub098 \uc99d\uac00\uc2dc\ucf1c \uc0c1\ud488 \uc218\uae09\uc5d0 \uc778\uc704\uc801 \uc601\ud5a5\uc744 \ubbf8\uce58\ub294 \ud589\uc704\ub97c \ub9d0\ud55c\ub2e4. \uc774\ub294 \uc2dc\uc7a5\uc758 \uc218\uae09\uc744 \uc778\uc704\uc801\uc73c\ub85c \uc870\uc791\ud558\uc5ec \uac00\uaca9\uc774\ub098 \uac70\ub798\uc870\uac74\uc5d0 \ubd80\ub2f9\ud55c \uc601\ud5a5\uc744 \ubbf8\uce58\ub824\ub294 \ud589\uc704\ub85c\uc11c, \ubc30\ud0c0\uc870\uac74\ubd80\uac70\ub798\xb7\uc774\uc775\uc81c\uacf5\uac15\uc694\xb7\uacbd\uc7c1\uc0ac\uc5c5\uc790 \ubc30\uc81c\xb7\uc0ac\uc5c5\ud65c\ub3d9\ubc29\ud574\uc640\ub294 \uad6c\ubcc4\ub418\ub294 \ub3c5\uc790\uc801\uc778 \ub0a8\uc6a9\ud589\uc704 \uc720\ud615\uc774\ub2e4.",B.bdZ,B.b7A,null)
B.bbg=s(["\u3131, \u3134","\u3131, \u3137","\u3134, \u3137","\u3131, \u3134, \u3137","\u3134\ub9cc"],t.s)
B.bb0=s(["\ud544\uc218\uc694\uc18c \uc0ac\uc6a9 \uac70\uc808(\u3131), \uc6d0\uc7ac\ub8cc \uad6c\ub9e4 \ubc29\ud574(\u3134), \uc778\ub825 \ucc44\uc6a9 \ubc29\ud574 \ub4f1\uc774 \ub300\ud45c\uc801 \uc720\ud615"],t.s)
B.aRG=s(["\uc0ac\uc5c5\ud65c\ub3d9 \ubc29\ud574\ud589\uc704"],t.s)
B.bta=new A.a("gen_md_type_4","economic_law","\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9","\ud589\uc704 \uc720\ud615",'\ub3c5\uc810\uaddc\uc81c \ubc0f \uacf5\uc815\uac70\ub798\uc5d0 \uad00\ud55c \ubc95\ub960\uc0c1 \uc2dc\uc7a5\uc9c0\ubc30\uc801\uc0ac\uc5c5\uc790\uc758 "\ub2e4\ub978 \uc0ac\uc5c5\uc790\uc758 \uc0ac\uc5c5\ud65c\ub3d9 \ubc29\ud574\ud589\uc704"\uc5d0 \ud574\ub2f9\ud558\ub294 \uac83\uc744 \ubaa8\ub450 \uace0\ub978 \uac83\uc740?\n\n\u3131. \uc815\ub2f9\ud55c \uc774\uc720 \uc5c6\uc774 \ub2e4\ub978 \uc0ac\uc5c5\uc790\uc758 \uc0c1\ud488 \uc0dd\uc0b0\xb7\ud310\ub9e4\uc5d0 \ud544\uc218\uc801\uc778 \uc694\uc18c\uc758 \uc0ac\uc6a9\uc744 \uac70\uc808\ud558\ub294 \ud589\uc704\n\u3134. \uc815\ub2f9\ud55c \uc774\uc720 \uc5c6\uc774 \ub2e4\ub978 \uc0ac\uc5c5\uc790\uc758 \uc6d0\uc7ac\ub8cc \uad6c\ub9e4\ub97c \ubc29\ud574\ud558\ub294 \ud589\uc704\n\u3137. \uc18c\ube44\uc790\uc758 \uc774\uc775\uc744 \ud604\uc800\ud788 \uc800\ud574\ud560 \uc6b0\ub824\uac00 \uc788\ub294 \uc0c1\ud488 \ud310\ub9e4\ub97c \ud558\ub294 \ud589\uc704',B.bbg,0,'"\ub2e4\ub978 \uc0ac\uc5c5\uc790\uc758 \uc0ac\uc5c5\ud65c\ub3d9 \ubc29\ud574\ud589\uc704"\ub294 \uc774\ubbf8 \uc2dc\uc7a5\uc5d0 \uc874\uc7ac\ud558\ub294 \uacbd\uc7c1\uc0ac\uc5c5\uc790\uc758 \uc815\uc0c1\uc801\uc778 \uc601\uc5c5\ud65c\ub3d9\uc744 \ubd80\ub2f9\ud558\uac8c \uc5b4\ub835\uac8c \ub9cc\ub4dc\ub294 \ud589\uc704\ub85c, \ud544\uc218\uc694\uc18c \uc0ac\uc6a9 \uac70\uc808(\u3131), \uc6d0\uc7ac\ub8cc \uad6c\ub9e4 \ubc29\ud574(\u3134), \uc778\ub825 \ucc44\uc6a9 \ubc29\ud574 \ub4f1\uc774 \ub300\ud45c\uc801 \uc720\ud615\uc774\ub2e4. \ubc18\uba74 \u3137(\uc18c\ube44\uc790\uc774\uc775 \uc800\ud574 \uc6b0\ub824\uac00 \uc788\ub294 \uc0c1\ud488 \ud310\ub9e4)\uc740 \ubcc4\ub3c4\ub85c \ubd84\ub958\ub418\ub294 "\uc18c\ube44\uc790\uc774\uc775 \uc800\ud574\ud589\uc704" \uc720\ud615\uc5d0 \ud574\ub2f9\ud558\ubbc0\ub85c \uc0ac\uc5c5\ud65c\ub3d9 \ubc29\ud574\ud589\uc704\uc640 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4.',B.bb0,B.aRG,null)
B.aZW=s(["\ubd80\ub2f9\ud558\uac8c \uc18c\ube44\uc790\uc758 \uc774\uc775\uc744 \ud604\uc800\ud788 \uc800\ud574\ud560 \uc6b0\ub824\uac00 \uc788\ub294 \ud589\uc704\ub85c\uc11c \ub2e4\ub978 4\uac00\uc9c0 \ub0a8\uc6a9\ud589\uc704 \uc720\ud615\uacfc\ub294 \ubcc4\ub3c4\ub85c \uaddc\uc815\ub41c \ubcf4\ucda9\uc801 \uc720\ud615\uc774\ub2e4","\uc18c\ube44\uc790\uc774\uc775 \uc800\ud574\ud589\uc704\ub294 \ubc18\ub4dc\uc2dc \uac00\uaca9 \uc778\uc0c1\uc744 \uc218\ubc18\ud558\uc5ec\uc57c \uc131\ub9bd\ud55c\ub2e4","\uc18c\ube44\uc790\uc774\uc775 \uc800\ud574\ud589\uc704\ub294 \uc2e0\uaddc \uacbd\uc7c1\uc0ac\uc5c5\uc790\uc758 \uc2dc\uc7a5\ucc38\uac00 \ubc29\ud574\ud589\uc704\uc758 \ud558\uc704 \uc720\ud615\uc774\ub2e4","\uc18c\ube44\uc790\uc774\uc775 \uc800\ud574\ud589\uc704\ub294 \uc0ac\uc5c5\uc790\ub2e8\uccb4\uc5d0\uac8c\ub9cc \uc801\uc6a9\ub41c\ub2e4","\uc18c\ube44\uc790\uc774\uc775 \uc800\ud574\ud589\uc704\uac00 \uc131\ub9bd\ud558\ub824\uba74 \uc2e4\uc81c \uc18c\ube44\uc790 \ud53c\ud574\uac00 \ud655\uc815\uc801\uc73c\ub85c \ubc1c\uc0dd\ud574\uc57c \ud55c\ub2e4"],t.s)
B.ahO=s(["\ub2e4\ub978 4\uac00\uc9c0 \ub0a8\uc6a9\ud589\uc704 \uc720\ud615\uacfc\ub294 \ubcc4\ub3c4\ub85c \uaddc\uc815\ub41c \ubcf4\ucda9\uc801 \uc720\ud615"],t.s)
B.aBK=s(["\uc18c\ube44\uc790\uc774\uc775 \uc800\ud574\ud589\uc704"],t.s)
B.bvW=new A.a("gen_md_type_5","economic_law","\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9","\ud589\uc704 \uc720\ud615",'\ub3c5\uc810\uaddc\uc81c \ubc0f \uacf5\uc815\uac70\ub798\uc5d0 \uad00\ud55c \ubc95\ub960\uc0c1 \uc2dc\uc7a5\uc9c0\ubc30\uc801\uc0ac\uc5c5\uc790\uc758 "\uc18c\ube44\uc790\uc774\uc775 \uc800\ud574\ud589\uc704"\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?',B.aZW,0,'\uc18c\ube44\uc790\uc774\uc775 \uc800\ud574\ud589\uc704\ub294 \ubd80\ub2f9\ud558\uac8c \uc18c\ube44\uc790\uc758 \uc774\uc775\uc744 \ud604\uc800\ud788 \uc800\ud574\ud560 \uc6b0\ub824\uac00 \uc788\ub294 \ud589\uc704\ub97c \uaddc\uc81c\ud558\ub294 \uc720\ud615\uc73c\ub85c, \uac00\uaca9\ub0a8\uc6a9\xb7\ucd9c\uace0\uc870\uc808\xb7\uc0ac\uc5c5\ud65c\ub3d9\ubc29\ud574\xb7\uc2dc\uc7a5\ucc38\uac00\ubc29\ud574\xb7\uacbd\uc7c1\uc0ac\uc5c5\uc790\ubc30\uc81c\ub77c\ub294 \ub2e4\ub978 \uc720\ud615\uc5d0 \ud574\ub2f9\ud558\uc9c0 \uc54a\ub354\ub77c\ub3c4 \uc18c\ube44\uc790 \uc774\uc775\uc744 \ud604\uc800\ud788 \uce68\ud574\ud560 \uc6b0\ub824\uac00 \uc788\ub2e4\uba74 \uaddc\uc81c\ud560 \uc218 \uc788\ub3c4\ub85d \ub9c8\ub828\ub41c \ubcf4\ucda9\uc801\xb7\ud3ec\uad04\uc801 \uc131\uaca9\uc758 \uc720\ud615\uc774\ub2e4. "\uc6b0\ub824\uac00 \uc788\ub294" \ud589\uc704\ub97c \uaddc\uc81c \ub300\uc0c1\uc73c\ub85c \ud558\ubbc0\ub85c \uc2e4\uc81c \ud53c\ud574\uac00 \ud655\uc815\uc801\uc73c\ub85c \ubc1c\uc0dd\ud560 \uac83\uae4c\uc9c0 \uc694\uad6c\ud558\uc9c0 \uc54a\uc73c\uba70, \uac00\uaca9 \uc778\uc0c1\uc744 \ubc18\ub4dc\uc2dc \uc218\ubc18\ud574\uc57c \ud558\ub294 \uac83\ub3c4 \uc544\ub2c8\ub2e4.',B.ahO,B.aBK,null)
B.aSY=s(["\uac00\uaca9\ub0a8\uc6a9 \u2013 \ucd9c\uace0\uc870\uc808 \u2013 \uc0ac\uc5c5\ud65c\ub3d9\ubc29\ud574 \u2013 \uc2dc\uc7a5\ucc38\uac00\ubc29\ud574 \u2013 \uacbd\uc7c1\uc0ac\uc5c5\uc790\ubc30\uc81c\xb7\uc18c\ube44\uc790\uc774\uc775\uc800\ud574","\uac00\uaca9\ub0a8\uc6a9 \u2013 \ubd80\ub2f9\uc5fc\ub9e4 \u2013 \uac70\ub798\uac70\uc808 \u2013 \uad6c\uc18d\uc870\uac74\ubd80\uac70\ub798 \u2013 \uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704","\uac00\uaca9\ub0a8\uc6a9 \u2013 \uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0 \u2013 \ubd80\ub2f9\uc9c0\uc6d0\ud589\uc704 \u2013 \uc0ac\uc5c5\ud65c\ub3d9\ubc29\ud574 \u2013 \uc2dc\uc7a5\ucc38\uac00\ubc29\ud574","\ucd9c\uace0\uc870\uc808 \u2013 \ub2f4\ud569 \u2013 \uac70\ub798\uc0c1\uc9c0\uc704\ub0a8\uc6a9 \u2013 \uc2dc\uc7a5\ucc38\uac00\ubc29\ud574 \u2013 \uacbd\uc7c1\uc0ac\uc5c5\uc790\ubc30\uc81c","\uac00\uaca9\ub0a8\uc6a9 \u2013 \ucd9c\uace0\uc870\uc808 \u2013 \ubd80\ub2f9\uc9c0\uc6d0\ud589\uc704 \u2013 \uad6c\uc18d\uc870\uac74\ubd80\uac70\ub798 \u2013 \uc18c\ube44\uc790\uc774\uc775\uc800\ud574"],t.s)
B.b3f=s(["\uac00\uaca9\ub0a8\uc6a9, \u2461 \ucd9c\uace0\uc870\uc808, \u2462 \ub2e4\ub978 \uc0ac\uc5c5\uc790\uc758 \uc0ac\uc5c5\ud65c\ub3d9 \ubc29\ud574, \u2463 \uc2e0\uaddc \uacbd\uc7c1\uc0ac\uc5c5\uc790\uc758 \uc2dc\uc7a5\ucc38\uac00 \ubc29\ud574, \u2464 \uacbd\uc7c1\uc0ac\uc5c5\uc790\ub97c \ubc30\uc81c"],t.s)
B.a6y=s(["\ub0a8\uc6a9\ud589\uc704 5\uc720\ud615 \ucd1d\uc815\ub9ac"],t.s)
B.bFo=new A.a("gen_md_type_6","economic_law","\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9","\ud589\uc704 \uc720\ud615","\ub3c5\uc810\uaddc\uc81c \ubc0f \uacf5\uc815\uac70\ub798\uc5d0 \uad00\ud55c \ubc95\ub960\uc0c1 \uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9\ud589\uc704 5\uac00\uc9c0 \uc720\ud615\uc744 \uc62c\ubc14\ub974\uac8c \uc5f0\uacb0\ud55c \uac83\uc740?",B.aSY,0,"\uacf5\uc815\uac70\ub798\ubc95 \uc81c5\uc870\uac00 \uc815\ud558\ub294 \uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9\ud589\uc704\uc758 5\uac00\uc9c0 \uc720\ud615\uc740 \u2460 \uac00\uaca9\ub0a8\uc6a9, \u2461 \ucd9c\uace0\uc870\uc808, \u2462 \ub2e4\ub978 \uc0ac\uc5c5\uc790\uc758 \uc0ac\uc5c5\ud65c\ub3d9 \ubc29\ud574, \u2463 \uc2e0\uaddc \uacbd\uc7c1\uc0ac\uc5c5\uc790\uc758 \uc2dc\uc7a5\ucc38\uac00 \ubc29\ud574, \u2464 \uacbd\uc7c1\uc0ac\uc5c5\uc790\ub97c \ubc30\uc81c\ud558\uae30 \uc704\ud55c \uac70\ub798 \ub610\ub294 \uc18c\ube44\uc790\uc758 \uc774\uc775\uc744 \ud604\uc800\ud788 \uc800\ud574\ud560 \uc6b0\ub824\uac00 \uc788\ub294 \ud589\uc704\uc774\ub2e4. \ubd80\ub2f9\uc5fc\ub9e4\xb7\uac70\ub798\uac70\uc808\xb7\uad6c\uc18d\uc870\uac74\ubd80\uac70\ub798\xb7\ubd80\ub2f9\uc9c0\uc6d0\ud589\uc704\xb7\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\xb7\ub2f4\ud569\xb7\uac70\ub798\uc0c1\uc9c0\uc704\ub0a8\uc6a9 \ub4f1\uc740 \ubaa8\ub450 \ubd88\uacf5\uc815\uac70\ub798\ud589\uc704\ub098 \ubd80\ub2f9\uacf5\ub3d9\ud589\uc704 \ub4f1 \ub2e4\ub978 \ub300\ubd84\ub958\uc5d0 \uc18d\ud558\ub294 \uac1c\ub150\uc774\ubbc0\ub85c \uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9\ud589\uc704 \uc720\ud615\uacfc \ud63c\ub3d9\ud558\uc9c0 \uc54a\uc544\uc57c \ud55c\ub2e4.",B.b3f,B.a6y,null)
B.biv=s(["\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc0ac\uc5c5\uc790\ub85c\uc11c\uc758 \uc9c0\uc704\ub97c \ubcf4\uc720\ud558\ub294 \uac83 \uc790\uccb4\ub294 \uc704\ubc95\ud558\uc9c0 \uc54a\uace0, \uadf8 \uc9c0\uc704\ub97c \ub0a8\uc6a9\ud558\ub294 \ud589\uc704\ub9cc \uaddc\uc81c \ub300\uc0c1\uc774\ub2e4","\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc0ac\uc5c5\uc790\ub85c \ucd94\uc815\ub418\uba74 \uadf8 \uc0ac\uc5c5\uc790\uc758 \ubaa8\ub4e0 \uac00\uaca9 \uacb0\uc815 \ud589\uc704\ub294 \uc608\uc678 \uc5c6\uc774 \uc704\ubc95\ud558\ub2e4","\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9\ud589\uc704 \uaddc\uc81c\ub294 \uc911\uc18c\uae30\uc5c5\uc5d0\uac8c\ub9cc \uc801\uc6a9\ub41c\ub2e4","\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc0ac\uc5c5\uc790\uac00 \uc544\ub2cc \uc0ac\uc5c5\uc790\uc758 \ud589\uc704\ub294 \uc5b4\ub5a4 \uacbd\uc6b0\uc5d0\ub3c4 \uacf5\uc815\uac70\ub798\ubc95\uc758 \uaddc\uc81c\ub97c \ubc1b\uc9c0 \uc54a\ub294\ub2e4","\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9\ud589\uc704\ub294 \uc0ac\uc5c5\uc790\ub2e8\uccb4\uc5d0\uac8c\ub9cc \uc801\uc6a9\ub418\ub294 \uaddc\uc81c\uc774\ub2e4"],t.s)
B.a9K=s(["\uc9c0\uc704\ub97c \ubcf4\uc720\ud558\ub294 \uac83 \uc790\uccb4\ub294 \uc704\ubc95\ud558\uc9c0 \uc54a\uace0, \uadf8 \uc9c0\uc704\ub97c \ub0a8\uc6a9\ud558\ub294 \ud589\uc704\ub9cc \uaddc\uc81c \ub300\uc0c1"],t.s)
B.aE1=s(["\ub0a8\uc6a9\ud589\uc704 \uaddc\uc81c\uc758 \uc131\uaca9"],t.s)
B.bnA=new A.a("gen_md_criteria_1","economic_law","\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9","\ubd80\ub2f9\uc131 \ud310\ub2e8\uae30\uc900","\ub3c5\uc810\uaddc\uc81c \ubc0f \uacf5\uc815\uac70\ub798\uc5d0 \uad00\ud55c \ubc95\ub960\uc0c1 \uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9\ud589\uc704 \uaddc\uc81c\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.biv,0,'\uacf5\uc815\uac70\ub798\ubc95\uc740 \uc2dc\uc7a5\uc5d0\uc11c \uc9c0\ubc30\uc801 \uc9c0\uc704\ub97c \uac16\ub294 \uac83 \uc790\uccb4\ub97c \uae08\uc9c0\ud558\uc9c0 \uc54a\ub294\ub2e4. \uaddc\uc81c \ub300\uc0c1\uc740 \uadf8\ub7ec\ud55c \uc9c0\uc704\ub97c "\ub0a8\uc6a9"\ud558\uc5ec \uacbd\uc7c1\uc744 \uc81c\ud55c\ud558\uac70\ub098 \uc18c\ube44\uc790 \uc774\uc775\uc744 \uce68\ud574\ud558\ub294 \ud589\uc704\uc774\ub2e4. \ub530\ub77c\uc11c \uc9c0\ubc30\uc801\uc0ac\uc5c5\uc790\uc758 \uac00\uaca9 \uacb0\uc815\uc774\ub77c\ub3c4 \uc815\ub2f9\ud55c \uc774\uc720\uac00 \uc788\uc73c\uba74 \uc704\ubc95\ud558\uc9c0 \uc54a\uc744 \uc218 \uc788\uace0, \uc774 \uaddc\uc81c\ub294 \uc911\uc18c\uae30\uc5c5\uc774\ub098 \uc0ac\uc5c5\uc790\ub2e8\uccb4\uc5d0 \ud55c\uc815\ub418\uc9c0 \uc54a\uc73c\uba70, \uc2dc\uc7a5\uc9c0\ubc30\uc801\uc0ac\uc5c5\uc790\uac00 \uc544\ub2cc \uc0ac\uc5c5\uc790\uc758 \ud589\uc704\ub3c4 \ubd88\uacf5\uc815\uac70\ub798\ud589\uc704 \ub4f1 \ub2e4\ub978 \uaddc\uc815\uc73c\ub85c \uaddc\uc81c\ub420 \uc218 \uc788\ub2e4.',B.a9K,B.aE1,null)
B.Td=s(["\ud574\ub2f9 \ud589\uc704\ub85c \uc778\ud55c \uacbd\uc7c1\uc81c\ud55c\ud6a8\uacfc\uc640 \ud6a8\uc728\uc131 \uc99d\ub300\ud6a8\uacfc \ub4f1\uc744 \ube44\uad50\ud615\ub7c9\ud558\uc5ec \uc885\ud569\uc801\uc73c\ub85c \ud310\ub2e8\ud558\ub294 \uac83\uc774 \uc77c\ubc18\uc801\uc774\ub2e4","\ubd80\ub2f9\uc131\uc740 \uc624\uc9c1 \ud589\uc704\uc790\uc758 \uc8fc\uad00\uc801 \uc545\uc758 \uc720\ubb34\ub9cc\uc73c\ub85c \ud310\ub2e8\ud55c\ub2e4","\uacbd\uc7c1\uc81c\ud55c\ud6a8\uacfc\uac00 \uc804\ud600 \uc5c6\uc5b4\ub3c4 \uc2dc\uc7a5\uc9c0\ubc30\uc801\uc0ac\uc5c5\uc790\uc758 \ud589\uc704\ub77c\uba74 \ud56d\uc0c1 \ubd80\ub2f9\ud558\ub2e4\uace0 \ubcf8\ub2e4","\ud6a8\uc728\uc131 \uc99d\ub300\ud6a8\uacfc\ub294 \ubd80\ub2f9\uc131 \ud310\ub2e8\uc5d0\uc11c \uc804\ud600 \uace0\ub824\ub418\uc9c0 \uc54a\ub294\ub2e4","\ubd80\ub2f9\uc131 \ud310\ub2e8\uc740 \ud589\uc704\uc758 \ud615\uc2dd\ub9cc \ubcf4\uace0 \uc2e4\uc9c8\uc801 \ud6a8\uacfc\ub294 \uace0\ub824\ud558\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.avB=s(["\uacbd\uc7c1\uc81c\ud55c\ud6a8\uacfc\uc640 \ud6a8\uc728\uc131 \uc99d\ub300\ud6a8\uacfc \ub4f1\uc744 \ube44\uad50\ud615\ub7c9\ud558\uc5ec \uc885\ud569\uc801\uc73c\ub85c \ud310\ub2e8"],t.s)
B.bgu=s(["\ubd80\ub2f9\uc131 \ud310\ub2e8 \ubc29\ubc95"],t.s)
B.bR3=new A.a("gen_md_criteria_2","economic_law","\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9","\ubd80\ub2f9\uc131 \ud310\ub2e8\uae30\uc900","\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9\ud589\uc704\uc758 \ubd80\ub2f9\uc131(\uc704\ubc95\uc131) \ud310\ub2e8\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.Td,0,"\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9\ud589\uc704\uc758 \ubd80\ub2f9\uc131\uc740 \ud574\ub2f9 \ud589\uc704\ub85c \uc778\ud574 \ubc1c\uc0dd\ud558\ub294 \uacbd\uc7c1\uc81c\ud55c\ud6a8\uacfc(\uc9c4\uc785\uc7a5\ubcbd \uac15\ud654, \uacbd\uc7c1\uc0ac\uc5c5\uc790 \ubc30\uc81c \ub4f1)\uc640 \ud6a8\uc728\uc131 \uc99d\ub300\ud6a8\uacfc(\ube44\uc6a9\uc808\uac10, \ud488\uc9c8\ud5a5\uc0c1 \ub4f1)\ub97c \ube44\uad50\ud615\ub7c9\ud574 \uc885\ud569\uc801\uc73c\ub85c \ud310\ub2e8\ud558\ub294 \uac83\uc774 \uc77c\ubc18\uc801 \uc811\uadfc\uc774\ub2e4. \ub2e8\uc21c\ud788 \uc8fc\uad00\uc801 \uc545\uc758 \uc720\ubb34\ub098 \ud589\uc704\uc758 \ud615\uc2dd\ub9cc\uc73c\ub85c \ud310\ub2e8\ud558\uc9c0 \uc54a\uc73c\uba70, \uacbd\uc7c1\uc81c\ud55c\ud6a8\uacfc\uac00 \uc5c6\uac70\ub098 \ubbf8\ubbf8\ud55c \uacbd\uc6b0\uc5d0\ub294 \ub0a8\uc6a9\uc73c\ub85c \uc778\uc815\ub418\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4.",B.avB,B.bgu,null)
B.akz=s(["\ucc29\ucde8\ub0a8\uc6a9\uc740 \uc8fc\ub85c \uac70\ub798\uc0c1\ub300\ubc29\uc774\ub098 \uc18c\ube44\uc790\ub85c\ubd80\ud130 \ubd80\ub2f9\ud55c \uc774\uc775\uc744 \ucde8\ud558\ub294 \uc720\ud615\uc774\ub2e4","\ubc30\uc81c\ub0a8\uc6a9\uc740 \uc8fc\ub85c \uacbd\uc7c1\uc0ac\uc5c5\uc790\ub97c \uc2dc\uc7a5\uc5d0\uc11c \ubab0\uc544\ub0b4\uac70\ub098 \uc0c8\ub85c\uc6b4 \uc9c4\uc785\uc744 \ub9c9\ub294 \uc720\ud615\uc774\ub2e4","\uac00\uaca9\ub0a8\uc6a9\uc740 \ub300\ud45c\uc801\uc778 \ucc29\ucde8\ub0a8\uc6a9 \uc720\ud615\uc73c\ub85c \ubd84\ub958\ub41c\ub2e4","\uc774 \uad6c\ubd84\uc740 \ud559\ubb38\uc801\xb7\uc2e4\ubb34\uc801\uc73c\ub85c \ub0a8\uc6a9\ud589\uc704\uc758 \uc131\uaca9\uc744 \uc774\ud574\ud558\ub294 \ub370 \ud65c\uc6a9\ub418\uc9c0\ub9cc, \ubc95 \uc870\ubb38\uc774 \uc774 \uba85\uce6d\uc744 \uc9c1\uc811 \uc0ac\uc6a9\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4",u.aN],t.s)
B.auo=s([u.aN],t.s)
B.ap7=s(["\ucc29\ucde8\ub0a8\uc6a9\xb7\ubc30\uc81c\ub0a8\uc6a9 \uad6c\ubd84"],t.s)
B.bGh=new A.a("gen_md_criteria_3","economic_law","\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9","\ubd80\ub2f9\uc131 \ud310\ub2e8\uae30\uc900","\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9\ud589\uc704 \uc911 \ucc29\ucde8\ub0a8\uc6a9(\uac00\uaca9\ub0a8\uc6a9\xb7\uc18c\ube44\uc790\uc774\uc775\uc800\ud574\ud589\uc704 \ub4f1)\uacfc \ubc30\uc81c\ub0a8\uc6a9(\uc0ac\uc5c5\ud65c\ub3d9\ubc29\ud574\xb7\uc2dc\uc7a5\ucc38\uac00\ubc29\ud574 \ub4f1)\uc758 \uad6c\ubd84\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.akz,4,"\ucc29\ucde8\ub0a8\uc6a9\uacfc \ubc30\uc81c\ub0a8\uc6a9\uc740 \ub0a8\uc6a9\ud589\uc704\uc758 \uc131\uaca9\uc744 \uc124\uba85\ud558\uae30 \uc704\ud574 \uac15\ud559\uc0c1 \uc0ac\uc6a9\ub418\ub294 \ubd84\ub958\ub85c, \uacf5\uc815\uac70\ub798\ubc95 \uc870\ubb38\uc774 \uc9c1\uc811 \uadf8 \uba85\uce6d\uc744 \uaddc\uc815\ud558\uace0 \uc788\uc9c0\ub294 \uc54a\ub2e4. \ucc29\ucde8\ub0a8\uc6a9\uc740 \uac70\ub798\uc0c1\ub300\ubc29\xb7\uc18c\ube44\uc790\ub85c\ubd80\ud130 \ubd80\ub2f9\ud55c \uc774\uc775\uc744 \ucde8\ud558\ub294 \uc720\ud615(\uac00\uaca9\ub0a8\uc6a9 \ub4f1), \ubc30\uc81c\ub0a8\uc6a9\uc740 \uacbd\uc7c1\uc0ac\uc5c5\uc790\ub97c \ubc30\uc81c\ud558\uac70\ub098 \uc2e0\uaddc\uc9c4\uc785\uc744 \ub9c9\ub294 \uc720\ud615\uc744 \uac00\ub9ac\ud0a4\uc9c0\ub9cc, \uc2e4\uc81c \uc0ac\uc548\uc5d0\uc11c\ub294 \ud558\ub098\uc758 \ud589\uc704\uac00 \ub450 \uc131\uaca9\uc744 \ud568\uaed8 \uac00\uc9c8 \uc218\ub3c4 \uc788\uc5b4 \uc644\uc804\ud788 \ubc30\ud0c0\uc801\uc774\ub77c\uace0 \ub2e8\uc815\ud560 \uc218 \uc5c6\ub2e4.",B.auo,B.ap7,null)
B.aln=s(["\uc6d0\uac00 \uc0c1\uc2b9 \ub4f1 \uac1d\uad00\uc801 \uc694\uc778\uc5d0 \ub530\ub978 \ud569\ub9ac\uc801\uc778 \uac00\uaca9 \uc870\uc815","\uae30\uc220\ud601\uc2e0\uc774\ub098 \ud6a8\uc728\uc131 \uc99d\ub300\ub97c \uc704\ud55c \ubd88\uac00\ud53c\ud55c \uc870\uce58","\uc18c\ube44\uc790 \ud6c4\uc0dd \uc99d\ub300\uc5d0 \uc2e4\uc9c8\uc801\uc73c\ub85c \uae30\uc5ec\ud558\ub294 \uac70\ub798\uc870\uac74 \ubcc0\uacbd","\uc624\ub85c\uc9c0 \uacbd\uc7c1\uc0ac\uc5c5\uc790\ub97c \uc2dc\uc7a5\uc5d0\uc11c \ubc30\uc81c\ud560 \ubaa9\uc801\uc73c\ub85c \uc124\uacc4\ub41c \uc870\uce58","\uc548\uc804\uc774\ub098 \ud488\uc9c8\uad00\ub9ac\ub97c \uc704\ud574 \ud569\ub9ac\uc801\uc73c\ub85c \ud544\uc694\ud55c \ubc94\uc704\uc758 \uac70\ub798\uc870\uac74 \uc124\uc815"],t.s)
B.amU=s(["\uc624\ub85c\uc9c0 \uacbd\uc7c1\uc0ac\uc5c5\uc790\ub97c \uc2dc\uc7a5\uc5d0\uc11c \ubc30\uc81c\ud560 \ubaa9\uc801\uc73c\ub85c \uc124\uacc4\ub41c \uc870\uce58"],t.s)
B.aau=s(["\uc815\ub2f9\ud55c \uc774\uc720","\uc704\ubc95\uc131 \uc870\uac01"],t.s)
B.bAI=new A.a("gen_md_criteria_4","economic_law","\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9","\ubd80\ub2f9\uc131 \ud310\ub2e8\uae30\uc900",'\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc0ac\uc5c5\uc790\uc758 \ud589\uc704\uac00 "\uc815\ub2f9\ud55c \uc774\uc720"\uac00 \uc788\uc5b4 \uc704\ubc95\uc131\uc774 \uc870\uac01\ub420 \uc218 \uc788\ub294 \uc0ac\uc815\uc73c\ub85c \ubcf4\uae30 \uc5b4\ub824\uc6b4 \uac83\uc740?',B.aln,3,"\uc815\ub2f9\ud55c \uc774\uc720\ub294 \uc6d0\uac00 \uc694\uc778, \ud6a8\uc728\uc131\xb7\uae30\uc220\ud601\uc2e0, \uc18c\ube44\uc790 \ud6c4\uc0dd, \ud569\ub9ac\uc801\uc778 \ud488\uc9c8\xb7\uc548\uc804\uad00\ub9ac \ud544\uc694\uc131 \ub4f1 \uac1d\uad00\uc801\uc774\uace0 \ud569\ub9ac\uc801\uc778 \uc0ac\uc720\ub97c \uac00\ub9ac\ud0a8\ub2e4. \ubc18\uba74 \uc624\ub85c\uc9c0 \uacbd\uc7c1\uc0ac\uc5c5\uc790 \ubc30\uc81c\ub9cc\uc744 \ubaa9\uc801\uc73c\ub85c \uc124\uacc4\ub41c \uc870\uce58\ub294 \uc815\ub2f9\ud55c \uc774\uc720\ub85c \uc778\uc815\ub418\uae30 \uc5b4\ub835\uace0 \uc624\ud788\ub824 \ubc30\uc81c\ub0a8\uc6a9\uc758 \uc804\ud615\uc801\uc778 \uc9d5\ud45c\ub85c \ud3c9\uac00\ub41c\ub2e4.",B.amU,B.aau,null)
B.Sz=s(["\ud589\uc704 \uc8fc\uccb4\uac00 \ud574\ub2f9 \uac70\ub798\ubd84\uc57c\uc758 \uc2dc\uc7a5\uc9c0\ubc30\uc801\uc0ac\uc5c5\uc790\uc5ec\uc57c \ud55c\ub2e4","\ubb38\uc81c\ub41c \ud589\uc704\uac00 \ubc95\uc774 \uc815\ud55c \ub0a8\uc6a9\ud589\uc704 \uc720\ud615 \uc911 \ud558\ub098\uc5d0 \ud574\ub2f9\ud574\uc57c \ud55c\ub2e4","\uadf8 \ud589\uc704\uc5d0 \ubd80\ub2f9\uc131(\uc704\ubc95\uc131)\uc774 \uc778\uc815\ub418\uc5b4\uc57c \ud55c\ub2e4","\ud589\uc704\ub85c \uc778\ud55c \uacbd\uc7c1\uc81c\ud55c\ud6a8\uacfc\ub098 \uc18c\ube44\uc790\uc774\uc775 \uce68\ud574 \uc6b0\ub824\uac00 \uc804\ud600 \uc5c6\uc5b4\ub3c4 \ud56d\uc0c1 \ub0a8\uc6a9\ud589\uc704\uac00 \uc131\ub9bd\ud55c\ub2e4","\uac1c\ubcc4 \uc0ac\uc548\uc758 \uc2dc\uc7a5\uad6c\uc870, \uac70\ub798\uad00\ud589 \ub4f1 \uad6c\uccb4\uc801 \uc0ac\uc815\uc774 \ud568\uaed8 \uace0\ub824\ub41c\ub2e4"],t.s)
B.a9o=s(["\uacbd\uc7c1\uc81c\ud55c\ud6a8\uacfc\ub098 \uc18c\ube44\uc790\uc774\uc775 \uce68\ud574 \uc6b0\ub824\uac00 \uc804\ud600 \uc5c6\uc5b4\ub3c4 \ud56d\uc0c1 \ub0a8\uc6a9\ud589\uc704\uac00 \uc131\ub9bd\ud55c\ub2e4"],t.s)
B.aHd=s(["\ub0a8\uc6a9\ud589\uc704 \uc131\ub9bd\uc694\uac74"],t.s)
B.bE1=new A.a("gen_md_criteria_5","economic_law","\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9","\ubd80\ub2f9\uc131 \ud310\ub2e8\uae30\uc900","\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9\ud589\uc704\uc758 \uc131\ub9bd\uc694\uac74\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.Sz,3,"\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9\ud589\uc704\uac00 \uc131\ub9bd\ud558\ub824\uba74 \u2460 \ud589\uc704\uc790\uac00 \uc2dc\uc7a5\uc9c0\ubc30\uc801\uc0ac\uc5c5\uc790\uc77c \uac83, \u2461 \ubc95\uc815 \ub0a8\uc6a9\ud589\uc704 \uc720\ud615\uc5d0 \ud574\ub2f9\ud560 \uac83, \u2462 \ubd80\ub2f9\uc131(\uacbd\uc7c1\uc81c\ud55c\ud6a8\uacfc\ub098 \uc18c\ube44\uc790\uc774\uc775 \uce68\ud574 \uc6b0\ub824 \ub4f1)\uc774 \uc778\uc815\ub420 \uac83\uc774\ub77c\ub294 \uc694\uac74\uc774 \ubaa8\ub450 \ucda9\uc871\ub418\uc5b4\uc57c \ud55c\ub2e4. \uacbd\uc7c1\uc81c\ud55c\ud6a8\uacfc\ub098 \uc18c\ube44\uc790\uc774\uc775 \uce68\ud574 \uc6b0\ub824\uac00 \uc804\ud600 \uc5c6\ub2e4\uba74 \ubd80\ub2f9\uc131 \uc694\uac74\uc774 \ud760\uacb0\ub418\uc5b4 \ub0a8\uc6a9\ud589\uc704\uac00 \uc131\ub9bd\ud558\uc9c0 \uc54a\ub294\ub2e4.",B.a9o,B.aHd,null)
B.aAx=s(["\ub3d9\uc77c\ud558\uac70\ub098 \uc720\uc0ac\ud55c \uc678\ud615\uc758 \ud589\uc704\ub77c\ub3c4 \ud589\uc704 \uc8fc\uccb4\uac00 \uc2dc\uc7a5\uc9c0\ubc30\uc801\uc0ac\uc5c5\uc790\uc778\uc9c0\uc5d0 \ub530\ub77c \ub0a8\uc6a9\ud589\uc704 \ub610\ub294 \ubd88\uacf5\uc815\uac70\ub798\ud589\uc704\ub85c \uac01\uac01 \uaddc\uc728\ub420 \uc218 \uc788\ub2e4","\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9\ud589\uc704\uc640 \ubd88\uacf5\uc815\uac70\ub798\ud589\uc704\ub294 \uc644\uc804\ud788 \ub3d9\uc77c\ud55c \uac1c\ub150\uc774\ub77c \uc911\ubcf5 \uaddc\uc815\uc5d0 \ubd88\uacfc\ud558\ub2e4","\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc0ac\uc5c5\uc790\uc758 \ud589\uc704\ub294 \ubd88\uacf5\uc815\uac70\ub798\ud589\uc704 \uaddc\uc815\uc73c\ub85c\ub294 \uc804\ud600 \uaddc\uc728\ub420 \uc218 \uc5c6\ub2e4","\ubd88\uacf5\uc815\uac70\ub798\ud589\uc704\ub294 \uc2dc\uc7a5\uc9c0\ubc30\uc801\uc0ac\uc5c5\uc790\uc5d0\uac8c\ub9cc \uc801\uc6a9\ub418\ub294 \uaddc\uc815\uc774\ub2e4","\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9\ud589\uc704\ub294 \uc0ac\uc5c5\uc790 \uaddc\ubaa8\uc640 \ubb34\uad00\ud558\uac8c \ubaa8\ub4e0 \uc0ac\uc5c5\uc790\uc5d0\uac8c \ub3d9\uc77c\ud558\uac8c \uc801\uc6a9\ub41c\ub2e4"],t.s)
B.aPD=s(["\ud589\uc704 \uc8fc\uccb4\uac00 \uc2dc\uc7a5\uc9c0\ubc30\uc801\uc0ac\uc5c5\uc790\uc778\uc9c0\uc5d0 \ub530\ub77c \ub0a8\uc6a9\ud589\uc704 \ub610\ub294 \ubd88\uacf5\uc815\uac70\ub798\ud589\uc704\ub85c \uac01\uac01 \uaddc\uc728\ub420 \uc218 \uc788\ub2e4"],t.s)
B.a5Z=s(["\ub0a8\uc6a9\ud589\uc704\uc640 \ubd88\uacf5\uc815\uac70\ub798\ud589\uc704\uc758 \uad00\uacc4"],t.s)
B.byb=new A.a("gen_md_criteria_6","economic_law","\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9","\ubd80\ub2f9\uc131 \ud310\ub2e8\uae30\uc900","\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9\ud589\uc704\uc640 \ubd88\uacf5\uc815\uac70\ub798\ud589\uc704(\uacf5\uc815\uac70\ub798\ubc95\uc0c1 \ubcc4\ub3c4\uc758 \ub300\ubd84\ub958)\uc758 \uad00\uacc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aAx,0,"\uc0ac\uc5c5\ud65c\ub3d9\ubc29\ud574\xb7\uac70\ub798\uac70\uc808\ucc98\ub7fc \uc678\ud615\uc774 \ube44\uc2b7\ud55c \ud589\uc704\ub77c\ub3c4, \ud589\uc704\uc790\uac00 \uc2dc\uc7a5\uc9c0\ubc30\uc801\uc0ac\uc5c5\uc790\uc5d0 \ud574\ub2f9\ud558\uba74 \ub0a8\uc6a9\ud589\uc704\ub85c, \uadf8\ub807\uc9c0 \uc54a\uc73c\uba74 \ubd88\uacf5\uc815\uac70\ub798\ud589\uc704 \ub4f1 \ub2e4\ub978 \uaddc\uc815\uc73c\ub85c \uaddc\uc728\ub420 \uc218 \uc788\ub2e4. \ub450 \uc81c\ub3c4\ub294 \uaddc\uc81c \ucde8\uc9c0\uc640 \uc694\uac74\uc774 \ub2e4\ub974\uba70 \uc0c1\ud638 \ubc30\ud0c0\uc801\uc73c\ub85c \ub300\uccb4\ub418\ub294 \uad00\uacc4\uac00 \uc544\ub2c8\ub77c, \uc0ac\uc548\uc5d0 \ub530\ub77c \ud568\uaed8 \uac80\ud1a0\ub420 \uc218\ub3c4 \uc788\ub2e4. \uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9\ud589\uc704\ub294 \uadf8 \uc815\uc758\uc0c1 \uc2dc\uc7a5\uc9c0\ubc30\uc801\uc0ac\uc5c5\uc790\uc5d0\uac8c\ub9cc \uc801\uc6a9\ub418\ub294 \uaddc\uc81c\ub77c\ub294 \uc810\uc774 \ud575\uc2ec\uc774\ub2e4.",B.aPD,B.a5Z,null)
B.aoU=s(["\ud574\ub2f9 \ud589\uc704\uc758 \uc911\uc9c0\ub97c \uba85\ud558\ub294 \uc2dc\uc815\uc870\uce58","\uc704\ubc18\ud589\uc704 \uc0ac\uc2e4\uc758 \uacf5\ud45c \ub4f1 \ud544\uc694\ud55c \uc2dc\uc815\uc870\uce58","\uad00\ub828\ub9e4\ucd9c\uc561\uc744 \uae30\uc900\uc73c\ub85c \ud55c \uacfc\uc9d5\uae08 \ubd80\uacfc","\ud53c\ud574\ub97c \uc785\uc740 \uc18c\ube44\uc790\uc5d0 \ub300\ud55c \ud615\uc0ac \uad6c\uc18d\uc601\uc7a5 \uccad\uad6c","\uac00\uaca9 \uc778\ud558 \ub4f1 \uc704\ubc18\uc0c1\ud0dc\ub97c \uc2dc\uc815\ud558\uae30 \uc704\ud55c \uc870\uce58"],t.s)
B.aji=s(["\ud615\uc0ac \uad6c\uc18d\uc601\uc7a5 \uccad\uad6c"],t.s)
B.aOs=s(["\uc2dc\uc815\uc870\uce58 \uc885\ub958"],t.s)
B.bJr=new A.a("gen_md_sanction_1","economic_law","\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9","\uc81c\uc7ac\xb7\uc2dc\uc815\uc870\uce58","\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uac00 \uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9\ud589\uc704\uc5d0 \ub300\ud574 \ucde8\ud560 \uc218 \uc788\ub294 \uc870\uce58\ub85c \ubcf4\uae30 \uc5b4\ub824\uc6b4 \uac83\uc740?",B.aoU,3,'\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\ub294 \uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9\ud589\uc704\uc5d0 \ub300\ud574 \ud589\uc704 \uc911\uc9c0\uba85\ub839, \uc2dc\uc815\uc870\uce58, \uc704\ubc18\uc0ac\uc2e4 \uacf5\ud45c, \uad00\ub828\ub9e4\ucd9c\uc561 \uae30\uc900 \uacfc\uc9d5\uae08 \ubd80\uacfc \ub4f1 \ud589\uc815\uc801 \uc81c\uc7ac\ub97c \ud560 \uc218 \uc788\ub2e4. \ub2e4\ub9cc "\ud615\uc0ac \uad6c\uc18d\uc601\uc7a5 \uccad\uad6c"\ub294 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uc758 \ud589\uc815 \uc81c\uc7ac \uc218\ub2e8\uc774 \uc544\ub2c8\ub77c \ud615\uc0ac\uc18c\uc1a1\uc808\ucc28\uc5d0\uc11c \uac80\uc0ac\xb7\ubc95\uc6d0\uc774 \uad00\uc5ec\ud558\ub294 \uc601\uc5ed\uc73c\ub85c, \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uac00 \uc9c1\uc811 \uc18c\ube44\uc790\ub97c \ub300\uc0c1\uc73c\ub85c \ud589\ud558\ub294 \uc870\uce58\uac00 \uc544\ub2c8\ub2e4.',B.aji,B.aOs,null)
B.adR=s(["\uad00\ub828\ub9e4\ucd9c\uc561\uc744 \uae30\uc900\uc73c\ub85c \uc77c\uc815 \ube44\uc728 \uc774\ub0b4\uc5d0\uc11c \uacfc\uc9d5\uae08\uc744 \ubd80\uacfc\ud560 \uc218 \uc788\ub2e4","\uacfc\uc9d5\uae08\uc740 \uc704\ubc18\ud589\uc704\uc640 \ubb34\uad00\ud558\uac8c \ud56d\uc0c1 \ub3d9\uc77c\ud55c \uc815\uc561\uc73c\ub85c \ubd80\uacfc\ub41c\ub2e4","\ub9e4\ucd9c\uc561 \uc0b0\uc815\uc774 \uace4\ub780\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \uacfc\uc9d5\uae08 \uc0c1\ud55c\uc740 \uc815\uc561\uc73c\ub85c \uace0\uc815\ub418\uc9c0 \uc54a\uace0 \ubcc4\ub3c4 \uae30\uc900\uc774 \uc801\uc6a9\ub420 \uc218 \uc788\ub2e4","\uacfc\uc9d5\uae08 \ubd80\uacfc\ub294 \ubc18\ub4dc\uc2dc \ubc95\uc6d0\uc758 \uc7ac\ud310\uc744 \ud1b5\ud574\uc11c\ub9cc \uac00\ub2a5\ud558\ub2e4","\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9\ud589\uc704\uc5d0\ub294 \uacfc\uc9d5\uae08 \uc81c\ub3c4\uac00 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.a7U=s(["\uad00\ub828\ub9e4\ucd9c\uc561\uc744 \uae30\uc900\uc73c\ub85c \uc77c\uc815 \ube44\uc728 \uc774\ub0b4\uc5d0\uc11c \uacfc\uc9d5\uae08\uc744 \ubd80\uacfc"],t.s)
B.rd=s(["\uacfc\uc9d5\uae08 \uc0b0\uc815\uae30\uc900"],t.s)
B.bFG=new A.a("gen_md_sanction_2","economic_law","\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9","\uc81c\uc7ac\xb7\uc2dc\uc815\uc870\uce58","\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9\ud589\uc704\uc5d0 \ub300\ud55c \uacfc\uc9d5\uae08\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.adR,0,"\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9\ud589\uc704\uc5d0 \ub300\ud55c \uacfc\uc9d5\uae08\uc740 \uc704\ubc18\ud589\uc704 \uad00\ub828 \ub9e4\ucd9c\uc561\uc744 \uae30\uc900\uc73c\ub85c \ubc95\ub839\uc774 \uc815\ud55c \ube44\uc728 \uc774\ub0b4\uc5d0\uc11c \ubd80\uacfc\ub418\ub294 \uac83\uc774 \uc6d0\uce59\uc774\uba70, \ub9e4\ucd9c\uc561 \uc0b0\uc815\uc774 \uace4\ub780\ud55c \uacbd\uc6b0\ub97c \ub300\ube44\ud55c \ubcc4\ub3c4\uc758 \uc815\uc561 \uae30\uc900(\uacfc\uc9d5\uae08 \uc0c1\ud55c\uc561)\ub3c4 \ud568\uaed8 \ub9c8\ub828\ub418\uc5b4 \uc788\ub2e4. \uacfc\uc9d5\uae08 \ubd80\uacfc\ub294 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uc758 \ud589\uc815\ucc98\ubd84\uc73c\ub85c \uc774\ub8e8\uc5b4\uc9c0\uba70 \ubc95\uc6d0\uc758 \uc7ac\ud310\uc744 \uac70\uccd0\uc57c\ub9cc \uac00\ub2a5\ud55c \uac83\uc740 \uc544\ub2c8\uace0(\ubd88\ubcf5 \uc2dc \uc0ac\ud6c4\uc801\uc73c\ub85c \ud589\uc815\uc18c\uc1a1\uc774 \uac00\ub2a5\ud560 \ubfd0), \uc704\ubc18\ud589\uc704\uc758 \ub0b4\uc6a9\xb7\uc815\ub3c4\uc5d0 \ub530\ub77c \uae08\uc561\uc774 \ub2ec\ub77c\uc9c4\ub2e4.",B.a7U,B.rd,null)
B.bau=s(["\ucc98\ubd84\uc5d0 \uc774\uc758\uac00 \uc788\ub294 \uc0ac\uc5c5\uc790\ub294 \uc774\uc758\uc2e0\uccad\uc774\ub098 \ud589\uc815\uc18c\uc1a1 \ub4f1\uc744 \ud1b5\ud574 \ub2e4\ud234 \uc218 \uc788\ub2e4","\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uc758 \ucc98\ubd84\uc740 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ubd88\ubcf5\uc774 \ubd88\uac00\ub2a5\ud558\ub2e4","\ubd88\ubcf5\uc740 \uc624\uc9c1 \ud5cc\ubc95\uc18c\uc6d0\uc744 \ud1b5\ud574\uc11c\ub9cc \uac00\ub2a5\ud558\ub2e4","\uc774\uc758\uc2e0\uccad \uc808\ucc28 \uc5c6\uc774 \ud615\uc0ac\uc7ac\ud310\uc73c\ub85c\ub9cc \ub2e4\ud234 \uc218 \uc788\ub2e4","\ucc98\ubd84\uc5d0 \ub300\ud55c \ubd88\ubcf5\uc740 \uc18c\ube44\uc790\ub9cc \uc81c\uae30\ud560 \uc218 \uc788\ub2e4"],t.s)
B.ayf=s(["\uc774\uc758\uc2e0\uccad\uc774\ub098 \ud589\uc815\uc18c\uc1a1 \ub4f1\uc744 \ud1b5\ud574 \ub2e4\ud234 \uc218 \uc788\ub2e4"],t.s)
B.tQ=s(["\ubd88\ubcf5\uc808\ucc28"],t.s)
B.bRm=new A.a("gen_md_sanction_3","economic_law","\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9","\uc81c\uc7ac\xb7\uc2dc\uc815\uc870\uce58","\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9\ud589\uc704\uc5d0 \ub300\ud55c \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uc758 \ucc98\ubd84\uc5d0 \ubd88\ubcf5\ud558\ub294 \uc808\ucc28\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.bau,0,"\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uc758 \uc2dc\uc815\uc870\uce58\xb7\uacfc\uc9d5\uae08 \ub4f1 \ucc98\ubd84\uc5d0 \uc774\uc758\uac00 \uc788\ub294 \uc0ac\uc5c5\uc790\ub294 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uc5d0 \ub300\ud55c \uc774\uc758\uc2e0\uccad\uc774\ub098 \ubc95\uc6d0\uc5d0 \ub300\ud55c \ud589\uc815\uc18c\uc1a1\uc744 \ud1b5\ud574 \ucc98\ubd84\uc758 \ucde8\uc18c\xb7\ubcc0\uacbd\uc744 \uad6c\ud560 \uc218 \uc788\ub2e4. \uc774\ub294 \ub2e4\ub978 \ud589\uc815\ucc98\ubd84\uc5d0 \ub300\ud55c \ubd88\ubcf5 \uad6c\uc870\uc640 \uc720\uc0ac\ud558\uba70, \ud615\uc0ac\uc7ac\ud310\uc774\ub098 \ud5cc\ubc95\uc18c\uc6d0\ub9cc\uc774 \uc720\uc77c\ud55c \ubd88\ubcf5 \uc218\ub2e8\uc740 \uc544\ub2c8\ub2e4.",B.ayf,B.tQ,null)
B.awI=s(["\uc704\ubc18\ud589\uc704\ub97c \uc911\uc9c0\uc2dc\ucf1c \uacbd\uc7c1\uc9c8\uc11c\ub97c \ud68c\ubcf5\ud558\ub294 \uac83","\uc704\ubc18\uc0ac\uc5c5\uc790\uc5d0\uac8c \uc7a5\ub798\uc758 \uc720\uc0ac\ud589\uc704 \uc7ac\ubc1c\uc744 \ubc29\uc9c0\ud558\ub3c4\ub85d \ud558\ub294 \uac83","\ud53c\ud574\ub97c \uc785\uc740 \uacbd\uc7c1\uc0ac\uc5c5\uc790\xb7\uc18c\ube44\uc790\uc758 \uc774\uc775\uc744 \ubcf4\ud638\ud558\ub294 \ub370 \uae30\uc5ec\ud558\ub294 \uac83","\uc704\ubc18\uc0ac\uc5c5\uc790\uc758 \uc2dc\uc7a5 \ud1f4\ucd9c \uc790\uccb4\ub97c \ubaa9\ud45c\ub85c \ud558\ub294 \uac83","\uacbd\uc7c1\uc9c8\uc11c\ub97c \uc800\ud574\ud55c \uc0c1\ud0dc\ub97c \uc2dc\uc815\ud558\uc5ec \uc815\uc0c1\uc801\uc778 \uc2dc\uc7a5\uae30\ub2a5\uc744 \ud68c\ubcf5\ud558\ub294 \uac83"],t.s)
B.TF=s(["\uc704\ubc18\uc0ac\uc5c5\uc790\uc758 \uc2dc\uc7a5 \ud1f4\ucd9c \uc790\uccb4\ub97c \ubaa9\ud45c\ub85c \ud558\ub294 \uac83"],t.s)
B.aB6=s(["\uc2dc\uc815\uc870\uce58\uc758 \ubaa9\uc801"],t.s)
B.brZ=new A.a("gen_md_sanction_4","economic_law","\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9","\uc81c\uc7ac\xb7\uc2dc\uc815\uc870\uce58","\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9\ud589\uc704\uc5d0 \ub300\ud55c \uc2dc\uc815\uc870\uce58\uc758 \ubaa9\uc801\uc73c\ub85c \uac00\uc7a5 \uac70\ub9ac\uac00 \uba3c \uac83\uc740?",B.awI,3,"\uc2dc\uc815\uc870\uce58\ub294 \uc704\ubc18\ud589\uc704\ub97c \uc911\uc9c0\uc2dc\ud0a4\uace0 \uacbd\uc7c1\uc9c8\uc11c\uc640 \uc2dc\uc7a5\uae30\ub2a5\uc744 \uc815\uc0c1\uc801\uc73c\ub85c \ud68c\ubcf5\uc2dc\ud0a4\uba70, \uc7ac\ubc1c\uc744 \ubc29\uc9c0\ud558\uace0 \uad00\ub828 \uc0ac\uc5c5\uc790\xb7\uc18c\ube44\uc790\uc758 \uc774\uc775\uc744 \ubcf4\ud638\ud558\ub294 \ub370 \ubaa9\uc801\uc774 \uc788\ub2e4. \uc704\ubc18\uc0ac\uc5c5\uc790\ub97c \uc2dc\uc7a5\uc5d0\uc11c \ud1f4\ucd9c\uc2dc\ud0a4\ub294 \uac83 \uc790\uccb4\uac00 \uc2dc\uc815\uc870\uce58\uc758 \ubaa9\uc801\uc740 \uc544\ub2c8\uba70, \uc5b4\ub514\uae4c\uc9c0\ub098 \uc704\ubc18\uc0c1\ud0dc\ub97c \uc2dc\uc815\ud558\ub294 \ub370 \ucd08\uc810\uc774 \uc788\ub2e4.",B.TF,B.aB6,null)
B.bi3=s(["\uc77c\uc815\ud55c \uacbd\uc6b0 \ud615\uc0ac\ucc98\ubc8c \uaddc\uc815\uc774 \ud568\uaed8 \uc801\uc6a9\ub420 \uc218 \uc788\uc5b4 \ud589\uc815\uc81c\uc7ac\uc640 \ud615\uc0ac\uc81c\uc7ac\uac00 \ubcd1\uc874\ud560 \uc218 \uc788\ub2e4","\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9\ud589\uc704\ub294 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ud615\uc0ac\ucc98\ubc8c \ub300\uc0c1\uc774 \ub418\uc9c0 \uc54a\ub294\ub2e4","\ud615\uc0ac\ucc98\ubc8c\uc774 \ud655\uc815\ub418\uba74 \uacfc\uc9d5\uae08 \ub4f1 \ud589\uc815\uc81c\uc7ac\ub294 \uc790\ub3d9\uc73c\ub85c \uc804\ubd80 \ucde8\uc18c\ub41c\ub2e4","\ud615\uc0ac\ucc98\ubc8c\uc740 \uc624\uc9c1 \uc0ac\uc5c5\uc790\ub2e8\uccb4\uc5d0\uac8c\ub9cc \uc801\uc6a9\ub41c\ub2e4","\ud615\uc0ac\ucc98\ubc8c \uc5ec\ubd80\ub294 \uc18c\ube44\uc790\uc758 \uac1c\ubcc4 \ub3d9\uc758\uc5d0 \ub530\ub77c \uacb0\uc815\ub41c\ub2e4"],t.s)
B.aHa=s(["\ud589\uc815\uc81c\uc7ac\uc640 \ud615\uc0ac\uc81c\uc7ac\uac00 \ubcd1\uc874\ud560 \uc218 \uc788\ub2e4"],t.s)
B.akB=s(["\ud615\uc0ac\ucc98\ubc8c \ubcd1\uacfc \uac00\ub2a5\uc131"],t.s)
B.bFI=new A.a("gen_md_sanction_5","economic_law","\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9","\uc81c\uc7ac\xb7\uc2dc\uc815\uc870\uce58","\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9\ud589\uc704\uac00 \ud615\uc0ac\ucc98\ubc8c \ub300\uc0c1\uc774 \ub420 \uc218 \uc788\ub294\uc9c0\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.bi3,0,"\uacf5\uc815\uac70\ub798\ubc95\uc740 \uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9\ud589\uc704 \ub4f1 \uc8fc\uc694 \uc704\ubc18\ud589\uc704\uc5d0 \ub300\ud574 \ud589\uc815\uc81c\uc7ac(\uc2dc\uc815\uc870\uce58\xb7\uacfc\uc9d5\uae08)\uc640 \ubcc4\ub3c4\ub85c \ud615\uc0ac\ucc98\ubc8c \uaddc\uc815\uc744 \ub450\uace0 \uc788\uc5b4, \uc0ac\uc548\uc5d0 \ub530\ub77c \ud589\uc815\uc81c\uc7ac\uc640 \ud615\uc0ac\uc81c\uc7ac\uac00 \ud568\uaed8 \uc801\uc6a9\ub420 \uc218 \uc788\ub2e4. \ud615\uc0ac\ucc98\ubc8c \uc5ec\ubd80\uc640 \uacfc\uc9d5\uae08 \ub4f1 \ud589\uc815\uc81c\uc7ac\ub294 \ubcc4\uac1c\uc758 \uc808\ucc28\uc640 \uc694\uac74\uc5d0 \ub530\ub77c \ud310\ub2e8\ub418\ubbc0\ub85c, \ud558\ub098\uac00 \ud655\uc815\ub418\uc5c8\ub2e4\uace0 \ub2e4\ub978 \ud558\ub098\uac00 \uc790\ub3d9\uc73c\ub85c \uc18c\uba78\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4.",B.aHa,B.akB,null)
B.bfa=s(["\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\ub294 \uc9c1\uad8c\uc73c\ub85c \uc870\uc0ac\ub97c \uac1c\uc2dc\ud560 \uc218 \uc788\ub2e4","\uc774\ud574\uad00\uacc4\uc778\uc758 \uc2e0\uace0\ub97c \uacc4\uae30\ub85c \uc870\uc0ac\uac00 \uc2dc\uc791\ub420 \uc218\ub3c4 \uc788\ub2e4","\uc870\uc0ac \uacb0\uacfc\uc5d0 \ub530\ub77c \uc2dc\uc815\uc870\uce58\ub098 \uacfc\uc9d5\uae08 \ub4f1 \ucc98\ubd84\uc774 \ub0b4\ub824\uc9c8 \uc218 \uc788\ub2e4","\uc870\uc0ac\uc640 \ucc98\ubd84 \uacfc\uc815\uc5d0\uc11c \uc0ac\uc5c5\uc790\uc5d0\uac8c \uc758\uacac\uc9c4\uc220 \uae30\ud68c\uac00 \uc804\ud600 \ubd80\uc5ec\ub418\uc9c0 \uc54a\ub294\ub2e4","\ucc98\ubd84 \uc804 \uc2ec\uc758 \ub4f1 \uc808\ucc28\uc801 \ub2e8\uacc4\ub97c \uac70\uce58\ub294 \uac83\uc774 \uc77c\ubc18\uc801\uc774\ub2e4"],t.s)
B.avQ=s(["\uc758\uacac\uc9c4\uc220 \uae30\ud68c\uac00 \uc804\ud600 \ubd80\uc5ec\ub418\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.abZ=s(["\uc870\uc0ac\xb7\ucc98\ubd84 \uc808\ucc28"],t.s)
B.brW=new A.a("gen_md_sanction_6","economic_law","\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9","\uc81c\uc7ac\xb7\uc2dc\uc815\uc870\uce58","\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9\ud589\uc704 \uc870\uc0ac \ubc0f \ucc98\ubd84 \uc808\ucc28\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.bfa,3,'\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\ub294 \uc9c1\uad8c \ub610\ub294 \uc2e0\uace0\ub97c \uacc4\uae30\ub85c \uc870\uc0ac\ub97c \uac1c\uc2dc\ud560 \uc218 \uc788\uace0, \uc870\uc0ac \uacb0\uacfc\uc5d0 \ub530\ub77c \uc2ec\uc758 \ub4f1 \uc808\ucc28\ub97c \uac70\uccd0 \uc2dc\uc815\uc870\uce58\xb7\uacfc\uc9d5\uae08 \ub4f1 \ucc98\ubd84\uc744 \ub0b4\ub9b0\ub2e4. \uc774 \uacfc\uc815\uc5d0\uc11c \ud53c\uc2ec\uc778(\uc0ac\uc5c5\uc790)\uc5d0\uac8c\ub294 \uc758\uacac\uc9c4\uc220 \uae30\ud68c \ub4f1 \ubc29\uc5b4\uad8c\uc774 \ubcf4\uc7a5\ub418\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ubbc0\ub85c, "\uc758\uacac\uc9c4\uc220 \uae30\ud68c\uac00 \uc804\ud600 \ubd80\uc5ec\ub418\uc9c0 \uc54a\ub294\ub2e4"\ub294 \uc124\uba85\uc740 \uc633\uc9c0 \uc54a\ub2e4.',B.avQ,B.abZ,null)
B.aH4=s(["\uc2e0\uaddc \uacbd\uc7c1\uc0ac\uc5c5\uc790\uc758 \uc2dc\uc7a5\ucc38\uac00 \ubc29\ud574\ud589\uc704 \ub610\ub294 \ub2e4\ub978 \uc0ac\uc5c5\uc790\uc758 \uc0ac\uc5c5\ud65c\ub3d9 \ubc29\ud574\ud589\uc704","\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704","\ubd80\ub2f9\ud55c \uacf5\ub3d9\ud589\uc704","\uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704","\ud2b9\uc218\uad00\uacc4\uc778\uc5d0 \ub300\ud55c \ubd80\ub2f9\uc774\uc775\uc81c\uacf5\ud589\uc704"],t.s)
B.bgP=s(["\uc2e0\uaddc \uacbd\uc7c1\uc0ac\uc5c5\uc790\uc758 \uc2dc\uc7a5\ucc38\uac00 \ubc29\ud574\ud589\uc704 \ub610\ub294 \ub2e4\ub978 \uc0ac\uc5c5\uc790\uc758 \uc0ac\uc5c5\ud65c\ub3d9 \ubc29\ud574\ud589\uc704"],t.s)
B.a2c=s(["\ud544\uc218\uc694\uc18c \uac70\uc808 \uc0ac\ub840"],t.s)
B.bEm=new A.a("gen_md_case_1","economic_law","\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9","\ud310\ub840\xb7\uc0ac\ub840","\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc0ac\uc5c5\uc790\uc778 A\uc0ac\uac00 \uacbd\uc7c1\uc0ac\uc5c5\uc790 B\uc0ac\uc758 \uc2e0\uc81c\ud488 \ucd9c\uc2dc\ub97c \ubc29\ud574\ud560 \ubaa9\uc801\uc73c\ub85c, \uc790\uc0ac \uc720\ud1b5\ub9dd\uc5d0\ub9cc \uacf5\uae09\ud558\ub294 \ud544\uc218\ubd80\ud488\uc758 \ud310\ub9e4\ub97c B\uc0ac\uc5d0\uac8c \uc815\ub2f9\ud55c \uc774\uc720 \uc5c6\uc774 \uac70\uc808\ud55c \uacbd\uc6b0 \ud574\ub2f9\ud558\ub294 \ub0a8\uc6a9\ud589\uc704 \uc720\ud615\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.aH4,0,'\ud544\uc218\uc801\uc778 \uc694\uc18c(\ubd80\ud488\xb7\uc124\ube44 \ub4f1)\uc758 \uc0ac\uc6a9\uc744 \uc815\ub2f9\ud55c \uc774\uc720 \uc5c6\uc774 \uac70\uc808\ud574 \uacbd\uc7c1\uc0ac\uc5c5\uc790\uc758 \uc2dc\uc7a5 \uc9c4\uc785\uc774\ub098 \uc0ac\uc5c5\ud65c\ub3d9\uc744 \uc5b4\ub835\uac8c \ub9cc\ub4dc\ub294 \ud589\uc704\ub294 \uc0ac\uc548\uc5d0 \ub530\ub77c "\uc2e0\uaddc \uacbd\uc7c1\uc0ac\uc5c5\uc790\uc758 \uc2dc\uc7a5\ucc38\uac00 \ubc29\ud574\ud589\uc704" \ub610\ub294 "\ub2e4\ub978 \uc0ac\uc5c5\uc790\uc758 \uc0ac\uc5c5\ud65c\ub3d9 \ubc29\ud574\ud589\uc704"\ub85c \ud3ec\uc12d\ub420 \uc218 \uc788\ub294 \ub300\ud45c\uc801\uc778 \ubc30\uc81c\ub0a8\uc6a9 \uc0ac\ub840\uc774\ub2e4. \uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\xb7\ubd80\ub2f9\uacf5\ub3d9\ud589\uc704\xb7\uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704\xb7\ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5\uc740 \ubaa8\ub450 \uc774 \uc0ac\ub840\uc758 \uc0ac\uc2e4\uad00\uacc4\uc640 \ubb34\uad00\ud55c \ubcc4\uac1c\uc758 \uaddc\uc81c \uc720\ud615\uc774\ub2e4.',B.bgP,B.a2c,null)
B.ayh=s([u.pv,"\uc2dc\uc7a5\uc810\uc720\uc728\uc774 \uc5bc\ub9c8\uc774\ub4e0 \uac00\uaca9\uc744 \uc62c\ub9ac\ub294 \ud589\uc704\ub294 \ud56d\uc0c1 \ud569\ubc95\uc774\ub2e4","\uc774 \uacbd\uc6b0\ub294 \uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\uc5d0 \ud574\ub2f9\ud55c\ub2e4","\uc774 \uacbd\uc6b0\ub294 \uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704\uc5d0 \ud574\ub2f9\ud55c\ub2e4","\uac00\uaca9 \uc778\uc0c1\uc740 \ud56d\uc0c1 \uc18c\ube44\uc790\uc774\uc775 \uc800\ud574\ud589\uc704\uc640 \ubb34\uad00\ud558\uac8c \ud310\ub2e8\ub41c\ub2e4"],t.s)
B.aa_=s([u.pv],t.s)
B.a8f=s(["\uac00\uaca9\ub0a8\uc6a9 \uc0ac\ub840"],t.s)
B.bvZ=new A.a("gen_md_case_2","economic_law","\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9","\ud310\ub840\xb7\uc0ac\ub840","\uc2dc\uc7a5\uc810\uc720\uc728 70%\uc778 \uc2dc\uc7a5\uc9c0\ubc30\uc801\uc0ac\uc5c5\uc790 A\uc0ac\uac00 \uc6d0\uac00 \uc0c1\uc2b9 \uc694\uc778\uc774 \uc804\ud600 \uc5c6\uc74c\uc5d0\ub3c4 \ud2b9\ubcc4\ud55c \uc774\uc720 \uc5c6\uc774 \uc790\uc0ac \uc81c\ud488 \uac00\uaca9\uc744 \ud070 \ud3ed\uc73c\ub85c \uc778\uc0c1\ud55c \uacbd\uc6b0, \uc774\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.ayh,0,"\uc6d0\uac00 \uc0c1\uc2b9 \ub4f1 \uac1d\uad00\uc801\uc774\uace0 \ud569\ub9ac\uc801\uc778 \uadfc\uac70 \uc5c6\uc774 \uc2dc\uc7a5\uc9c0\ubc30\uc801\uc0ac\uc5c5\uc790\uac00 \uac00\uaca9\uc744 \ubd80\ub2f9\ud558\uac8c \uc778\uc0c1\ud558\ub294 \uac83\uc740 \uac00\uaca9\ub0a8\uc6a9\uc758 \uc804\ud615\uc801\uc778 \uc0ac\ub840\ub85c \ud3c9\uac00\ub420 \uc218 \uc788\ub2e4. \uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\ub294 \uc790\uc0ac \uc0c1\ud488\uc744 \uac70\ub798\ud558\ub294 \uc720\ud1b5\uc5c5\uc790\uc5d0\uac8c \ud310\ub9e4\uac00\uaca9\uc744 \uac15\uc81c\ud558\ub294 \ud589\uc704\ub85c \uc774 \uc0ac\ub840\uc640 \ub2e4\ub974\uace0, \uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704\ub294 \uc0ac\uc5c5\uc790\ub2e8\uccb4\uac00 \uc8fc\uccb4\uac00 \ub418\uc5b4\uc57c \ud558\ubbc0\ub85c \uc5ed\uc2dc \ud574\ub2f9\ud558\uc9c0 \uc54a\ub294\ub2e4.",B.aa_,B.a8f,null)
B.T6=s(["\ucd9c\uace0\uc870\uc808","\uac70\ub798\uc0c1\uc9c0\uc704\ub0a8\uc6a9","\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704","\uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704","\ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5"],t.s)
B.b21=s(["\uc0dd\uc0b0\xb7\ucd9c\uace0\ub7c9\uc744 \ucd5c\uadfc \ucd94\uc138\ubcf4\ub2e4 \ud604\uc800\ud788 \uac10\uc18c\uc2dc\ucf1c \uc218\uae09\uc5d0 \uc778\uc704\uc801 \uc601\ud5a5\uc744 \ubbf8\uce58\ub294 \ud589\uc704\ub294 \ucd9c\uace0\uc870\uc808"],t.s)
B.aTn=s(["\ucd9c\uace0\uc870\uc808 \uc0ac\ub840"],t.s)
B.bns=new A.a("gen_md_case_3","economic_law","\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9","\ud310\ub840\xb7\uc0ac\ub840","\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc0ac\uc5c5\uc790 A\uc0ac\uac00 \ubc18\ub3c4\uccb4 \uc218\uc694 \uae09\uc99d \uc0c1\ud669\uc5d0\uc11c \uc815\ub2f9\ud55c \uc774\uc720 \uc5c6\uc774 \uc0dd\uc0b0\ub7c9\uc744 \uc885\uc804 \ub300\ube44 \ud604\uc800\ud788 \uc904\uc5ec \uc2dc\uc7a5\uc5d0 \uc778\uc704\uc801\uc778 \ud488\uadc0 \ud604\uc0c1\uc744 \uc77c\uc73c\ud0a8 \uacbd\uc6b0 \ud574\ub2f9\ud560 \uc218 \uc788\ub294 \ub0a8\uc6a9\ud589\uc704 \uc720\ud615\uc740?",B.T6,0,"\uc815\ub2f9\ud55c \uc774\uc720 \uc5c6\uc774 \uc0dd\uc0b0\xb7\ucd9c\uace0\ub7c9\uc744 \ucd5c\uadfc \ucd94\uc138\ubcf4\ub2e4 \ud604\uc800\ud788 \uac10\uc18c\uc2dc\ucf1c \uc218\uae09\uc5d0 \uc778\uc704\uc801 \uc601\ud5a5\uc744 \ubbf8\uce58\ub294 \ud589\uc704\ub294 \ucd9c\uace0\uc870\uc808\uc758 \uc804\ud615\uc801 \uc0ac\ub840\uc774\ub2e4. \uac70\ub798\uc0c1\uc9c0\uc704\ub0a8\uc6a9\xb7\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\xb7\uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704\xb7\ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5\uc740 \uac01\uac01 \ub2e4\ub978 \uc694\uac74\uacfc \uc8fc\uccb4\ub97c \uc804\uc81c\ub85c \ud558\ub294 \ubcc4\uac1c\uc758 \uaddc\uc81c \uc720\ud615\uc73c\ub85c, \uc774 \uc0ac\ub840\uc640\ub294 \uc131\uaca9\uc774 \ub2e4\ub974\ub2e4.",B.b21,B.aTn,null)
B.aK9=s([u.cL,"\uc2e0\uaddc \uc9c4\uc785\uc744 \ub9c9\ub294 \ud589\uc704\ub294 \uc774\uc720\ub97c \ubd88\ubb38\ud558\uace0 \ud56d\uc0c1 \uc704\ubc95\ud558\ub2e4","\uc548\uc804\uae30\uc900\uc744 \uc774\uc720\ub85c \ub4e0 \uacbd\uc6b0\ub294 \ud56d\uc0c1 \ud615\uc2dd\uc801 \ud56d\ubcc0\uc73c\ub85c \ucde8\uae09\ub418\uc5b4 \uace0\ub824\ub418\uc9c0 \uc54a\ub294\ub2e4","\uc774 \uacbd\uc6b0 \ubc18\ub4dc\uc2dc \ubd80\ub2f9\ud55c \uacf5\ub3d9\ud589\uc704\ub85c \uc758\uc728\ud574\uc57c \ud55c\ub2e4","\uc774 \uacbd\uc6b0\ub294 \uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704\ub85c\ub9cc \uaddc\uc728\ub420 \uc218 \uc788\ub2e4"],t.s)
B.aWi=s([u.cL],t.s)
B.aU9=s(["\uc815\ub2f9\ud55c \uc774\uc720 \ud56d\ubcc0 \uc0ac\ub840"],t.s)
B.bxy=new A.a("gen_md_case_4","economic_law","\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9","\ud310\ub840\xb7\uc0ac\ub840","\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc0ac\uc5c5\uc790 A\uc0ac\uac00 \uc2e0\uaddc \uc9c4\uc785\uc744 \uc2dc\ub3c4\ud558\ub294 B\uc0ac\uc5d0\uac8c \ud544\uc218\uc801\uc778 \uc720\ud1b5\ub9dd \uc811\uadfc\uc744 \uac70\uc808\ud558\uba74\uc11c, \ub3d9\uc2dc\uc5d0 \uadf8 \uac70\uc808\uc774 \uc548\uc804\uae30\uc900 \ubbf8\ub2ec\uc744 \uc774\uc720\ub85c \ud55c \ud569\ub9ac\uc801 \uc870\uce58\uc600\uc74c\uc774 \uac1d\uad00\uc801\uc73c\ub85c \uc785\uc99d\ub41c \uacbd\uc6b0\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aK9,0,'\ub0a8\uc6a9\ud589\uc704\uc5d0 \ud574\ub2f9\ud558\ub294 \uac83\ucc98\ub7fc \ubcf4\uc774\ub294 \ud589\uc704\ub77c\ub3c4, \uc548\uc804\xb7\ud488\uc9c8\uad00\ub9ac \ub4f1 \uac1d\uad00\uc801\uc774\uace0 \ud569\ub9ac\uc801\uc778 "\uc815\ub2f9\ud55c \uc774\uc720"\uac00 \uc2e4\uc81c\ub85c \uc785\uc99d\ub41c\ub2e4\uba74 \uc704\ubc95\uc131\uc774 \uc870\uac01\ub418\uc5b4 \ub0a8\uc6a9\ud589\uc704\uac00 \uc131\ub9bd\ud558\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \uc774\ub7ec\ud55c \ud56d\ubcc0\uc740 \ud615\uc2dd\uc801 \uc8fc\uc7a5\ub9cc\uc73c\ub85c\ub294 \uc778\uc815\ub418\uc9c0 \uc54a\uace0 \uac1d\uad00\uc801 \uadfc\uac70\uac00 \ub4b7\ubc1b\uce68\ub418\uc5b4\uc57c \ud558\uba70, \uc774 \uc0ac\ub840\ub294 \ubd80\ub2f9\uacf5\ub3d9\ud589\uc704\ub098 \uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704\uc640\ub294 \ubb34\uad00\ud55c \ub2e8\ub3c5\ud589\uc704 \uc0ac\uc548\uc774\ub2e4.',B.aWi,B.aU9,null)
B.ahj=s(["\ub2e4\ub978 \uc0ac\uc5c5\uc790\uc758 \uc0ac\uc5c5\ud65c\ub3d9 \ubc29\ud574\ud589\uc704","\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704","\ubd80\ub2f9\ud55c \uacf5\ub3d9\ud589\uc704","\uacbd\uc81c\ub825\uc9d1\uc911 \uc5b5\uc81c \uc704\ubc18","\ud2b9\uc218\uad00\uacc4\uc778\uc5d0 \ub300\ud55c \ubd80\ub2f9\uc774\uc775\uc81c\uacf5\ud589\uc704"],t.s)
B.aHF=s(["\ub2e4\ub978 \uc0ac\uc5c5\uc790\uc758 \uc0ac\uc5c5\ud65c\ub3d9 \ubc29\ud574\ud589\uc704"],t.s)
B.bhE=s(["\uc0ac\uc5c5\ud65c\ub3d9 \ubc29\ud574\ud589\uc704 \uc0ac\ub840"],t.s)
B.brP=new A.a("gen_md_case_5","economic_law","\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9","\ud310\ub840\xb7\uc0ac\ub840","\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc0ac\uc5c5\uc790 A\uc0ac\uac00 \uc790\uc0ac\uc640 \uacbd\uc7c1 \uad00\uacc4\uc5d0 \uc788\ub294 B\uc0ac\uc5d0 \ub300\ud574\uc11c\ub9cc \ub9e4\uc6b0 \ubd88\ub9ac\ud55c \uac70\ub798\uc870\uac74\uc744 \uc81c\uc2dc\ud558\uc5ec B\uc0ac\uc758 \uc815\uc0c1\uc801\uc778 \uc0ac\uc5c5\ud65c\ub3d9\uc744 \ud604\uc800\ud788 \uc5b4\ub835\uac8c \ub9cc\ub4e4\uc5c8\ub2e4\uba74, \uc774\ub294 \ub2e4\uc74c \uc911 \uc5b4\ub290 \uc720\ud615\uc73c\ub85c \ud3ec\uc12d\ub420 \uac00\ub2a5\uc131\uc774 \uac00\uc7a5 \ud070\uac00?",B.ahj,0,'\uacbd\uc7c1\uc0ac\uc5c5\uc790\uc5d0\uac8c\ub9cc \ubd88\ub9ac\ud55c \uac70\ub798\uc870\uac74\uc744 \uc81c\uc2dc\ud558\uc5ec \uc815\uc0c1\uc801\uc778 \uc0ac\uc5c5\ud65c\ub3d9\uc744 \ud604\uc800\ud788 \uc5b4\ub835\uac8c \ub9cc\ub4dc\ub294 \ud589\uc704\ub294 "\ub2e4\ub978 \uc0ac\uc5c5\uc790\uc758 \uc0ac\uc5c5\ud65c\ub3d9 \ubc29\ud574\ud589\uc704"\uc5d0 \ud574\ub2f9\ud560 \uc218 \uc788\ub294 \uc804\ud615\uc801 \uc0ac\ub840\uc774\ub2e4. \uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\xb7\ubd80\ub2f9\uacf5\ub3d9\ud589\uc704\xb7\uacbd\uc81c\ub825\uc9d1\uc911 \uc5b5\uc81c\xb7\ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5\uc740 \uac01\uac01 \ubcc4\ub3c4\uc758 \uc694\uac74(\uc720\ud1b5\uc5c5\uc790\uc5d0 \ub300\ud55c \uac00\uaca9 \uac15\uc81c, \uc0ac\uc5c5\uc790 \uac04 \ud569\uc758, \uae30\uc5c5\uc9d1\ub2e8 \uaddc\uc81c, \ud2b9\uc218\uad00\uacc4\uc778 \uac70\ub798 \ub4f1)\uc744 \uc804\uc81c\ub85c \ud558\ubbc0\ub85c \uc774 \uc0ac\ub840\uc640\ub294 \ubd80\ud569\ud558\uc9c0 \uc54a\ub294\ub2e4.',B.aHF,B.bhE,null)
B.bbO=s(["\ud589\uc704\uc790\uac00 \ud574\ub2f9 \uac70\ub798\ubd84\uc57c\uc5d0\uc11c \uc2dc\uc7a5\uc9c0\ubc30\uc801\uc0ac\uc5c5\uc790\uc5d0 \ud574\ub2f9\ud558\ub294\uc9c0","\ubb38\uc81c\ub41c \ud589\uc704\uac00 \ubc95\uc815 \ub0a8\uc6a9\ud589\uc704 \uc720\ud615 \uc911 \uc5b4\ub514\uc5d0 \ud574\ub2f9\ud558\ub294\uc9c0","\ud589\uc704\uc758 \ubd80\ub2f9\uc131(\uacbd\uc7c1\uc81c\ud55c\ud6a8\uacfc\xb7\uc18c\ube44\uc790\uc774\uc775 \uce68\ud574 \uc6b0\ub824 \ub4f1)\uc774 \uc778\uc815\ub418\ub294\uc9c0","\ud589\uc704\uc790\uc758 \uac1c\uc778\uc801 \uce5c\ubd84\uad00\uacc4\ub098 \uc0ac\uc801\uc778 \ud3c9\ud310\uc774 \uc5b4\ub5a0\ud55c\uc9c0","\uc815\ub2f9\ud55c \uc774\uc720 \ub4f1 \uc704\ubc95\uc131 \uc870\uac01\uc0ac\uc720\uac00 \uc874\uc7ac\ud558\ub294\uc9c0"],t.s)
B.aAA=s(["\ud589\uc704\uc790\uc758 \uac1c\uc778\uc801 \uce5c\ubd84\uad00\uacc4\ub098 \uc0ac\uc801\uc778 \ud3c9\ud310\uc774 \uc5b4\ub5a0\ud55c\uc9c0"],t.s)
B.bcf=s(["\uc0ac\ub840\ubd84\uc11d \uccb4\ud06c\ub9ac\uc2a4\ud2b8"],t.s)
B.bDt=new A.a("gen_md_case_6","economic_law","\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9","\ud310\ub840\xb7\uc0ac\ub840","\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9\ud589\uc704 \uc0ac\ub840\ub97c \ubd84\uc11d\ud560 \ub54c \uac80\ud1a0\ud574\uc57c \ud560 \uc0ac\ud56d\uc73c\ub85c \uac00\uc7a5 \uac70\ub9ac\uac00 \uba3c \uac83\uc740?",B.bbO,3,"\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9\ud589\uc704 \uc0ac\ub840 \ubd84\uc11d\uc740 \ud589\uc704\uc790\uc758 \uc2dc\uc7a5\uc9c0\ubc30\uc801\uc0ac\uc5c5\uc790 \ud574\ub2f9 \uc5ec\ubd80, \ubc95\uc815 \ub0a8\uc6a9\ud589\uc704 \uc720\ud615 \ud574\ub2f9\uc131, \ubd80\ub2f9\uc131 \uc778\uc815 \uc5ec\ubd80, \uc815\ub2f9\ud55c \uc774\uc720 \ub4f1 \uc704\ubc95\uc131 \uc870\uac01\uc0ac\uc720 \uc874\ubd80\ub97c \uc911\uc2ec\uc73c\ub85c \uc774\ub8e8\uc5b4\uc9c4\ub2e4. \ud589\uc704\uc790\uc758 \uac1c\uc778\uc801 \uce5c\ubd84\uad00\uacc4\ub098 \uc0ac\uc801 \ud3c9\ud310\uc740 \ubc95\uc801 \ud310\ub2e8 \uc694\uc18c\uac00 \uc544\ub2c8\ubbc0\ub85c \uac80\ud1a0 \ub300\uc0c1\uc774 \uc544\ub2c8\ub2e4.",B.aAA,B.bcf,null)
B.aMC=s(["\uad6d\uc678\uc5d0\uc11c \uc774\ub8e8\uc5b4\uc9c4 \ud589\uc704\ub77c\ub3c4 \uadf8 \ud589\uc704\ub85c \uc778\ud55c \uc601\ud5a5\uc774 \uad6d\ub0b4\uc2dc\uc7a5\uc5d0 \ubbf8\uce58\ub294 \uacbd\uc6b0 \uc774 \ubc95\uc774 \uc801\uc6a9\ub420 \uc218 \uc788\ub2e4","\uc678\uad6d\uc0ac\uc5c5\uc790\uc758 \ud589\uc704\uac00 \uad6d\ub0b4\uc2dc\uc7a5\uc5d0 \uc601\ud5a5\uc744 \ubbf8\uce58\ub294\uc9c0 \uc5ec\ubd80\ub294 \uc9c1\uc811\uc801\uc774\uace0 \uc0c1\ub2f9\ud558\uba70 \ud569\ub9ac\uc801\uc73c\ub85c \uc608\uce21 \uac00\ub2a5\ud55c \uc601\ud5a5\uc744 \uae30\uc900\uc73c\ub85c \uc81c\ud55c \ud574\uc11d\ud55c\ub2e4","\uc678\uad6d\uc0ac\uc5c5\uc790\uc758 \uad6d\uc678\ud589\uc704\uac00 \uc678\uad6d \ubc95\ub960\uc0c1 \uc801\ubc95\ud558\ub2e4\uba74 \uadf8\ub7ec\ud55c \uc0ac\uc815\ub9cc\uc73c\ub85c \ub2f9\uc5f0\ud788 \uc774 \ubc95\uc758 \uc801\uc6a9\uc774 \ubc30\uc81c\ub41c\ub2e4","\uc815\ubd80\ub294 \ub300\ud55c\ubbfc\uad6d\uc758 \ubc95\ub960 \ubc0f \uc774\uc775\uc5d0 \ubc18\ud558\uc9c0 \uc544\ub2c8\ud558\ub294 \ubc94\uc704\uc5d0\uc11c \uc678\uad6d\uc815\ubd80\uc640 \uc774 \ubc95 \uc9d1\ud589\uc744 \uc704\ud55c \ud611\uc815\uc744 \uccb4\uacb0\ud560 \uc218 \uc788\ub2e4","\uc5ed\uc678\uc801\uc6a9\uc5d0 \uad00\ud55c \uadfc\uac70 \uc870\ubb38\uc740 \uc774 \ubc95 \uc81c\uc815 \ub2f9\uc2dc\ubd80\ud130 \uc874\uc7ac\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4"],t.s)
B.azq=s(["\uadf8\ub7ec\ud55c \uc0ac\uc815\ub9cc\uc73c\ub85c \ub2f9\uc5f0\ud788 \uc6b0\ub9ac\ub098\ub77c \uacf5\uc815\uac70\ub798\ubc95\uc758 \uc801\uc6a9\uc774 \ubc30\uc81c\ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub77c\uace0 \ud310\uc2dc"],t.s)
B.aHn=s(["\uc5ed\uc678\uc801\uc6a9"],t.s)
B.bso=new A.a("gen_gn_1","economic_law","\ubaa9\uc801\xb7\ucd1d\uce59",null,"\ub3c5\uc810\uaddc\uc81c \ubc0f \uacf5\uc815\uac70\ub798\uc5d0 \uad00\ud55c \ubc95\ub960\uc758 \uc5ed\uc678\uc801\uc6a9\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740? (\ub2e4\ud23c\uc774 \uc788\uc73c\uba74 \ud310\ub840\uc5d0 \ub530\ub984)",B.aMC,2,'\uacf5\uc815\uac70\ub798\ubc95 \uc81c3\uc870\ub294 \uad6d\uc678\uc5d0\uc11c \uc774\ub8e8\uc5b4\uc9c4 \ud589\uc704\ub77c\ub3c4 \uadf8 \ud6a8\uacfc\uac00 \uad6d\ub0b4\uc2dc\uc7a5\uc5d0 \uc601\ud5a5\uc744 \ubbf8\uce58\ub294 \uacbd\uc6b0\uc5d0\ub294 \uc774 \ubc95\uc744 \uc801\uc6a9\ud55c\ub2e4\ub294 \uc5ed\uc678\uc801\uc6a9 \uc6d0\uce59\uc744 \uba85\uc2dc\ud558\uace0 \uc788\ub2e4. \ub300\ubc95\uc6d0 \ud310\ub840(\ud751\uc5f0\uc804\uadf9\ubd09 \uc0ac\uac74 \ub4f1)\ub294 \uc774\ub54c "\uad6d\ub0b4\uc2dc\uc7a5\uc5d0 \uc601\ud5a5\uc744 \ubbf8\uce58\ub294 \uacbd\uc6b0"\ub97c \ubb38\uc81c\ub41c \uad6d\uc678\ud589\uc704\ub85c \uc778\ud574 \uc9c1\uc811\uc801\xb7\uc0c1\ub2f9\ud558\uace0 \ud569\ub9ac\uc801\uc73c\ub85c \uc608\uce21 \uac00\ub2a5\ud55c \uc601\ud5a5\uc774 \uad6d\ub0b4\uc2dc\uc7a5\uc5d0 \ubbf8\uce58\ub294 \uacbd\uc6b0\ub85c \uc81c\ud55c \ud574\uc11d\ud558\ub418, \uc678\uad6d\uc0ac\uc5c5\uc790\uc758 \uad6d\uc678\ud589\uc704\uac00 \uadf8 \uc678\uad6d \ubc95\ub960\uc0c1\uc73c\ub85c\ub294 \uc801\ubc95\ud55c \ud589\uc704\uc600\ub2e4 \ud558\ub354\ub77c\ub3c4 \uadf8\ub7ec\ud55c \uc0ac\uc815\ub9cc\uc73c\ub85c \ub2f9\uc5f0\ud788 \uc6b0\ub9ac\ub098\ub77c \uacf5\uc815\uac70\ub798\ubc95\uc758 \uc801\uc6a9\uc774 \ubc30\uc81c\ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub77c\uace0 \ud310\uc2dc\ud558\uc600\ub2e4. \uc989 "\uc678\uad6d\uc5d0\uc11c \uc801\ubc95 = \uad6d\ub0b4\ubc95 \uc801\uc6a9 \ubc30\uc81c"\ub77c\ub294 \ub4f1\uc2dd\uc740 \uc131\ub9bd\ud558\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc810\uc774 \uc774 \ubb38\uc81c\uc758 \ud575\uc2ec\uc774\uba70, \uad6d\uac00 \uac04 \ud611\uc815 \uccb4\uacb0 \uadfc\uac70(\uc81c56\uc870)\ub098 \uc5ed\uc678\uc801\uc6a9 \uc870\ubb38\uc758 \uc2e0\uc124 \uc5f0\ud601\ub3c4 \ud568\uaed8 \uc54c\uc544\ub450\uc5b4\uc57c \ud55c\ub2e4.',B.azq,B.aHn,null)
B.aZv=s(["\uacf5\uc815\ud558\uace0 \uc790\uc720\ub85c\uc6b4 \uacbd\uc7c1\uc744 \ucd09\uc9c4\ud558\ub294 \uac83","\ucc3d\uc758\uc801\uc778 \uae30\uc5c5\ud65c\ub3d9\uc744 \uc870\uc7a5\ud558\ub294 \uac83","\uc18c\ube44\uc790\ub97c \ubcf4\ud638\ud558\ub294 \uac83","\uad6d\ubbfc\uacbd\uc81c\uc758 \uade0\ud615\uc788\ub294 \ubc1c\uc804\uc744 \ub3c4\ubaa8\ud558\ub294 \uac83","\ud2b9\uc815 \uc0b0\uc5c5 \ubd84\uc57c\uc758 \uad6d\ub0b4 \uae30\uc5c5\uc744 \uc678\uad6d \uae30\uc5c5\uacfc\uc758 \uacbd\uc7c1\uc73c\ub85c\ubd80\ud130 \ubcf4\ud638\ud558\ub294 \uac83"],t.s)
B.aEk=s(["\ud2b9\uc815 \uc0b0\uc5c5 \ubd84\uc57c\uc758 \uad6d\ub0b4 \uae30\uc5c5\uc744 \uc678\uad6d \uae30\uc5c5\uacfc\uc758 \uacbd\uc7c1\uc73c\ub85c\ubd80\ud130 \ubcf4\ud638\ud558\ub294 \uac83"],t.s)
B.av0=s(["\ubc95\uc758 \ubaa9\uc801"],t.s)
B.bEf=new A.a("gen_gn_purpose_1","economic_law","\ubaa9\uc801\xb7\ucd1d\uce59","\ubaa9\uc801\xb7\uae30\ubcf8\uc774\ub150","\ub3c5\uc810\uaddc\uc81c \ubc0f \uacf5\uc815\uac70\ub798\uc5d0 \uad00\ud55c \ubc95\ub960 \uc81c1\uc870\uac00 \uba85\uc2dc\ud558\ub294 \ubaa9\uc801\uc73c\ub85c \ubcfc \uc218 \uc5c6\ub294 \uac83\uc740?",B.aZv,4,"\uacf5\uc815\uac70\ub798\ubc95 \uc81c1\uc870\ub294 \uc2dc\uc7a5\uc9c0\ubc30\uc801 \uc9c0\uc704\uc758 \ub0a8\uc6a9\uacfc \uacfc\ub3c4\ud55c \uacbd\uc81c\ub825 \uc9d1\uc911\uc744 \ubc29\uc9c0\ud558\uace0 \ubd80\ub2f9\ud55c \uacf5\ub3d9\ud589\uc704 \ubc0f \ubd88\uacf5\uc815\uac70\ub798\ud589\uc704\ub97c \uaddc\uc81c\ud558\uc5ec \uacf5\uc815\ud558\uace0 \uc790\uc720\ub85c\uc6b4 \uacbd\uc7c1\uc744 \ucd09\uc9c4\ud568\uc73c\ub85c\uc368 \ucc3d\uc758\uc801\uc778 \uae30\uc5c5\ud65c\ub3d9\uc744 \uc870\uc7a5\ud558\uace0 \uc18c\ube44\uc790\ub97c \ubcf4\ud638\ud568\uacfc \uc544\uc6b8\ub7ec \uad6d\ubbfc\uacbd\uc81c\uc758 \uade0\ud615\uc788\ub294 \ubc1c\uc804\uc744 \ub3c4\ubaa8\ud568\uc744 \ubaa9\uc801\uc73c\ub85c \ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ud2b9\uc815 \uc0b0\uc5c5\uc758 \uad6d\ub0b4 \uae30\uc5c5\uc744 \uc678\uad6d \uacbd\uc7c1\uc73c\ub85c\ubd80\ud130 \ubcf4\ud638\ud558\ub294 \uac83\uc740 \uc774 \ubc95\uc758 \ubaa9\uc801\uc774 \uc544\ub2c8\uba70, \uc624\ud788\ub824 \uacbd\uc7c1 \ucd09\uc9c4\uc774 \ud575\uc2ec \ubaa9\uc801\uc774\ub2e4.",B.aEk,B.av0,null)
B.baU=s(["\uc790\uc720\ub85c\uc6b4 \uc2dc\uc7a5 \uc9c4\uc785\xb7\uacbd\uc7c1\uc758 \ubcf4\uc7a5(\uc790\uc720\uacbd\uc7c1)\uacfc \ubd80\ub2f9\ud55c \ubc29\ubc95\uc5d0 \uc758\ud55c \uacbd\uc7c1 \ubc30\uc81c \uae08\uc9c0(\uacf5\uc815\uacbd\uc7c1)\ub97c \ud568\uaed8 \ucd94\uad6c\ud558\ub294 \uac1c\ub150\uc774\ub2e4","\uc790\uc720\uacbd\uc7c1\ub9cc\uc744 \ucd94\uad6c\ud560 \ubfd0 \uacf5\uc815\uc131\uc740 \uace0\ub824\ud558\uc9c0 \uc54a\ub294\ub2e4","\uacf5\uc815\uacbd\uc7c1\ub9cc\uc744 \ucd94\uad6c\ud560 \ubfd0 \uc9c4\uc785\uc758 \uc790\uc720\ub294 \ubcf4\uc7a5\ud558\uc9c0 \uc54a\ub294\ub2e4","\uacbd\uc7c1\uc758 \uc790\uc720\uc640 \uacf5\uc815\uc131\uc740 \uc11c\ub85c \uc591\ub9bd\ud560 \uc218 \uc5c6\ub294 \uac1c\ub150\uc774\ub2e4","\uc774 \uac1c\ub150\uc740 \uc624\uc9c1 \ub300\uae30\uc5c5\uc5d0\uac8c\ub9cc \uc801\uc6a9\ub41c\ub2e4"],t.s)
B.aru=s(["\uc790\uc720\ub85c\uc6b4 \uc2dc\uc7a5 \uc9c4\uc785\xb7\uacbd\uc7c1\uc758 \ubcf4\uc7a5(\uc790\uc720\uacbd\uc7c1)\uacfc \ubd80\ub2f9\ud55c \ubc29\ubc95\uc5d0 \uc758\ud55c \uacbd\uc7c1 \ubc30\uc81c \uae08\uc9c0(\uacf5\uc815\uacbd\uc7c1)\ub97c \ud568\uaed8 \ucd94\uad6c"],t.s)
B.XI=s(["\uc790\uc720\uacbd\uc7c1\uacfc \uacf5\uc815\uacbd\uc7c1"],t.s)
B.bJY=new A.a("gen_gn_purpose_2","economic_law","\ubaa9\uc801\xb7\ucd1d\uce59","\ubaa9\uc801\xb7\uae30\ubcf8\uc774\ub150",'\uacf5\uc815\uac70\ub798\ubc95\uc774 \ucd94\uad6c\ud558\ub294 "\uacf5\uc815\ud558\uace0 \uc790\uc720\ub85c\uc6b4 \uacbd\uc7c1"\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?',B.baU,0,'"\uacf5\uc815\ud558\uace0 \uc790\uc720\ub85c\uc6b4 \uacbd\uc7c1"\uc740 \ub204\uad6c\ub098 \uc2dc\uc7a5\uc5d0 \uc790\uc720\ub86d\uac8c \uc9c4\uc785\ud558\uc5ec \uacbd\uc7c1\ud560 \uc218 \uc788\uc5b4\uc57c \ud55c\ub2e4\ub294 \uc790\uc720\uacbd\uc7c1\uc758 \uce21\uba74\uacfc, \ubd80\ub2f9\ud55c \ubc29\ubc95\uc73c\ub85c \uacbd\uc7c1\uc790\ub97c \ubc30\uc81c\ud558\uac70\ub098 \uac70\ub798\uc0c1\ub300\ubc29\uc5d0\uac8c \ubd88\uc774\uc775\uc744 \uc8fc\ub294 \ud589\uc704\ub294 \ud5c8\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4\ub294 \uacf5\uc815\uacbd\uc7c1\uc758 \uce21\uba74\uc744 \ud568\uaed8 \ud3ec\ud568\ud558\ub294 \uac1c\ub150\uc774\ub2e4. \ub450 \uce21\uba74\uc740 \ub300\ub9bd\ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uc0c1\ud638 \ubcf4\uc644\uc801\uc73c\ub85c \uc791\ub3d9\ud558\uba70, \uc0ac\uc5c5\uc790 \uaddc\ubaa8\uc640 \ubb34\uad00\ud558\uac8c \uc801\uc6a9\ub41c\ub2e4.',B.aru,B.XI,null)
B.aIf=s(["\uacf5\uc815\ud55c \uacbd\uc7c1\ud658\uacbd\uc744 \uc870\uc131\ud568\uc73c\ub85c\uc368 \uc0ac\uc5c5\uc790\ub4e4\uc774 \ud601\uc2e0\uacfc \ud6a8\uc728\uc131 \ud5a5\uc0c1\uc744 \ud1b5\ud574 \uacbd\uc7c1\ud558\ub3c4\ub85d \uc720\uc778\ud558\ub824\ub294 \uac83\uc774\ub2e4","\ud2b9\uc815 \uae30\uc5c5\uc5d0\uac8c \ub3c5\uc810\uc801 \uc9c0\uc704\ub97c \ubcf4\uc7a5\ud574 \uc548\uc815\uc801\uc778 \uc0ac\uc5c5\ud65c\ub3d9\uc744 \ub3d5\uae30 \uc704\ud55c \uac83\uc774\ub2e4","\ubaa8\ub4e0 \uae30\uc5c5\uc758 \uc2e0\uc81c\ud488 \uac1c\ubc1c\uc744 \uc815\ubd80\uac00 \uc9c1\uc811 \uc9c0\uc6d0\ud558\uaca0\ub2e4\ub294 \uc758\ubbf8\uc774\ub2e4","\ucc3d\uc758\uc801 \uae30\uc5c5\ud65c\ub3d9\uc740 \ubc95\uc758 \ubaa9\uc801\uacfc \ubb34\uad00\ud55c \ubd80\uc218\uc801 \ubb38\uad6c\uc5d0 \ubd88\uacfc\ud558\ub2e4","\ucc3d\uc758\uc801 \uae30\uc5c5\ud65c\ub3d9 \uc870\uc7a5\uc740 \ub300\uae30\uc5c5\uc5d0\ub9cc \ud574\ub2f9\ub418\ub294 \ubaa9\uc801\uc774\ub2e4"],t.s)
B.a_A=s(["\uacf5\uc815\ud55c \uacbd\uc7c1\ud658\uacbd\uc744 \uc870\uc131\ud568\uc73c\ub85c\uc368 \uc0ac\uc5c5\uc790\ub4e4\uc774 \ud601\uc2e0\uacfc \ud6a8\uc728\uc131 \ud5a5\uc0c1\uc744 \ud1b5\ud574 \uacbd\uc7c1\ud558\ub3c4\ub85d \uc720\uc778"],t.s)
B.aKg=s(["\ucc3d\uc758\uc801 \uae30\uc5c5\ud65c\ub3d9 \uc870\uc7a5"],t.s)
B.bv3=new A.a("gen_gn_purpose_3","economic_law","\ubaa9\uc801\xb7\ucd1d\uce59","\ubaa9\uc801\xb7\uae30\ubcf8\uc774\ub150",'\uacf5\uc815\uac70\ub798\ubc95\uc774 "\ucc3d\uc758\uc801\uc778 \uae30\uc5c5\ud65c\ub3d9\uc744 \uc870\uc7a5"\ud55c\ub2e4\uace0 \uaddc\uc815\ud55c \ucde8\uc9c0\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?',B.aIf,0,"\uacbd\uc7c1\uc774 \ud65c\ubc1c\ud55c \uc2dc\uc7a5\uc5d0\uc11c\ub294 \uc0ac\uc5c5\uc790\ub4e4\uc774 \uc0b4\uc544\ub0a8\uae30 \uc704\ud574 \ube44\uc6a9\uc808\uac10\xb7\ud488\uc9c8\uac1c\uc120\xb7\uae30\uc220\ud601\uc2e0 \ub4f1 \ucc3d\uc758\uc801\uc778 \ub178\ub825\uc744 \uae30\uc6b8\uc774\uac8c \ub41c\ub2e4. \uacf5\uc815\uac70\ub798\ubc95\uc740 \uc2dc\uc7a5\uc9c0\ubc30\ub825 \ub0a8\uc6a9\uc774\ub098 \ubd80\ub2f9\ud55c \ub2f4\ud569\xb7\ubd88\uacf5\uc815\uac70\ub798\ud589\uc704 \ub4f1 \uacbd\uc7c1\uc744 \uc65c\uace1\ud558\ub294 \ud589\uc704\ub97c \uaddc\uc81c\ud568\uc73c\ub85c\uc368 \uc774\ub7ec\ud55c \ucc3d\uc758\uc801 \uae30\uc5c5\ud65c\ub3d9\uc774 \uc774\ub8e8\uc5b4\uc9c8 \uc218 \uc788\ub294 \ud658\uacbd\uc744 \uc870\uc131\ud558\ub824\ub294 \ucde8\uc9c0\ub97c \uac16\ub294\ub2e4.",B.a_A,B.aKg,null)
B.b49=s(["\uac1c\ubcc4 \uc18c\ube44\uc790\ud53c\ud574\uc758 \uc0ac\ud6c4\uc801 \uad6c\uc81c\ubcf4\ub2e4\ub294 \uacbd\uc7c1 \ucd09\uc9c4\uc744 \ud1b5\ud574 \uc18c\ube44\uc790\ud6c4\uc0dd\uc744 \uc99d\uc9c4\ud558\ub294 \uac04\uc811\uc801\xb7\uad6c\uc870\uc801 \ubcf4\ud638\uc5d0 \uac00\uae5d\ub2e4","\uacf5\uc815\uac70\ub798\ubc95\uc740 \uc18c\ube44\uc790\uae30\ubcf8\ubc95\uc744 \uc644\uc804\ud788 \ub300\uccb4\ud558\ub294 \uc18c\ube44\uc790\ud53c\ud574 \uad6c\uc81c \uc804\ub2f4 \ubc95\ub960\uc774\ub2e4","\uc18c\ube44\uc790 \ubcf4\ud638\ub294 \uc774 \ubc95\uc758 \ubaa9\uc801\uc5d0 \uc804\ud600 \ud3ec\ud568\ub418\uc9c0 \uc54a\ub294\ub2e4","\uc18c\ube44\uc790 \ubcf4\ud638\ub294 \uc0ac\uc5c5\uc790\ub2e8\uccb4\uc5d0\uac8c\ub9cc \uc801\uc6a9\ub418\ub294 \ubaa9\uc801\uc774\ub2e4","\uc18c\ube44\uc790 \ubcf4\ud638\ub294 \uc624\uc9c1 \ud615\uc0ac\ucc98\ubc8c\uc744 \ud1b5\ud574\uc11c\ub9cc \ub2ec\uc131\ub41c\ub2e4"],t.s)
B.aQ0=s(["\uacbd\uc7c1 \ucd09\uc9c4\uc744 \ud1b5\ud574 \uc18c\ube44\uc790\ud6c4\uc0dd\uc744 \uc99d\uc9c4\ud558\ub294 \uac04\uc811\uc801\xb7\uad6c\uc870\uc801 \ubcf4\ud638\uc5d0 \uac00\uae5d\ub2e4"],t.s)
B.al0=s(["\uc18c\ube44\uc790\ubcf4\ud638\uc758 \uc131\uaca9"],t.s)
B.bPm=new A.a("gen_gn_purpose_4","economic_law","\ubaa9\uc801\xb7\ucd1d\uce59","\ubaa9\uc801\xb7\uae30\ubcf8\uc774\ub150",'\uacf5\uc815\uac70\ub798\ubc95\uc5d0 \uc758\ud55c "\uc18c\ube44\uc790 \ubcf4\ud638"\uc758 \uc131\uaca9\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?',B.b49,0,"\uacf5\uc815\uac70\ub798\ubc95\uc740 \uac1c\ubcc4 \uc18c\ube44\uc790\uc758 \ud53c\ud574\ub97c \uc9c1\uc811 \uad6c\uc81c\ud558\ub294 \uc808\ucc28(\uc608: \uc18c\ube44\uc790\ubd84\uc7c1\uc870\uc815)\ub97c \uc8fc\ub41c \uc218\ub2e8\uc73c\ub85c \ud558\uae30\ubcf4\ub2e4\ub294, \uacbd\uc7c1\uc744 \ucd09\uc9c4\ud558\uc5ec \uac00\uaca9 \uc778\ud558\xb7\ud488\uc9c8 \ud5a5\uc0c1 \ub4f1 \uc18c\ube44\uc790\ud6c4\uc0dd \uc99d\uc9c4 \ud6a8\uacfc\uac00 \uc2dc\uc7a5 \uc804\ubc18\uc5d0 \ubbf8\uce58\ub3c4\ub85d \ud558\ub294 \uad6c\uc870\uc801\xb7\uac04\uc811\uc801 \ubc29\uc2dd\uc73c\ub85c \uc18c\ube44\uc790\ub97c \ubcf4\ud638\ud558\ub294 \uc131\uaca9\uc774 \uac15\ud558\ub2e4. \uac1c\ubcc4 \ud53c\ud574\uad6c\uc81c\ub294 \uc18c\ube44\uc790\uae30\ubcf8\ubc95 \ub4f1 \ub2e4\ub978 \ubc95\ub960\uc758 \uc601\uc5ed\uacfc \ud568\uaed8 \uc791\ub3d9\ud55c\ub2e4.",B.aQ0,B.al0,null)
B.am2=s(["\uacfc\ub3c4\ud55c \uacbd\uc81c\ub825\uc9d1\uc911 \uc5b5\uc81c\ub97c \uc704\ud55c \uae30\uc5c5\uc9d1\ub2e8 \uad00\ub828 \uaddc\uc81c","\uac1c\ubcc4 \uc18c\ube44\uc790\uc5d0 \ub300\ud55c \uc190\ud574\ubc30\uc0c1 \uc18c\uc1a1 \uc808\ucc28","\ud615\uc0ac\uc18c\uc1a1\ubc95\uc0c1 \uc99d\uac70\uc7ac\ud310\uc8fc\uc758","\ubbfc\ubc95\uc0c1 \uacc4\uc57d\uc790\uc720\uc758 \uc6d0\uce59","\ub178\ub3d9\ubc95\uc0c1 \uadfc\ub85c\uc2dc\uac04 \uaddc\uc81c"],t.s)
B.b_f=s(["\uacfc\ub3c4\ud55c \uacbd\uc81c\ub825\uc9d1\uc911 \uc5b5\uc81c\ub97c \uc704\ud55c \uae30\uc5c5\uc9d1\ub2e8 \uad00\ub828 \uaddc\uc81c"],t.s)
B.aSN=s(["\uad6d\ubbfc\uacbd\uc81c \uade0\ud615\ubc1c\uc804","\uacbd\uc81c\ub825\uc9d1\uc911 \uc5b5\uc81c"],t.s)
B.bCU=new A.a("gen_gn_purpose_5","economic_law","\ubaa9\uc801\xb7\ucd1d\uce59","\ubaa9\uc801\xb7\uae30\ubcf8\uc774\ub150",'\uacf5\uc815\uac70\ub798\ubc95\uc774 "\uad6d\ubbfc\uacbd\uc81c\uc758 \uade0\ud615\uc788\ub294 \ubc1c\uc804"\uc744 \ubaa9\uc801\uc73c\ub85c \uaddc\uc815\ud55c \uac83\uacfc \uac00\uc7a5 \ubc00\uc811\ud558\uac8c \uad00\ub828\ub41c \uc81c\ub3c4\ub294?',B.am2,0,"\uad6d\ubbfc\uacbd\uc81c\uc758 \uade0\ud615\uc788\ub294 \ubc1c\uc804\uc774\ub77c\ub294 \ubaa9\uc801\uc740 \ud2b9\uc815 \uae30\uc5c5\uc9d1\ub2e8\uc73c\ub85c \uacbd\uc81c\ub825\uc774 \uacfc\ub3c4\ud558\uac8c \uc9d1\uc911\ub418\ub294 \uac83\uc744 \uc5b5\uc81c\ud558\uae30 \uc704\ud55c \uc9c0\uc8fc\ud68c\uc0ac \uaddc\uc81c, \uc0c1\ud638\ucd9c\uc790\xb7\uc21c\ud658\ucd9c\uc790 \uc81c\ud55c, \ucc44\ubb34\ubcf4\uc99d \uc81c\ud55c \ub4f1 \uae30\uc5c5\uc9d1\ub2e8 \uad00\ub828 \uaddc\uc81c\uc640 \uac00\uc7a5 \ubc00\uc811\ud558\uac8c \uad00\ub828\ub41c\ub2e4. \uc774\ub294 \uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9\uc774\ub098 \ubd88\uacf5\uc815\uac70\ub798\ud589\uc704 \uaddc\uc81c\uc640\ub294 \ubcc4\ub3c4\ub85c \uad6d\ubbfc\uacbd\uc81c \uc804\uccb4\uc758 \uade0\ud615\uc744 \uace0\ub824\ud558\ub294 \ucde8\uc9c0\uc758 \uaddc\uc815\uc774\ub2e4.",B.b_f,B.aSN,null)
B.aI9=s([u.zL,"\uacbd\uc7c1\ubc95\uc758 \uc720\uc77c\ud55c \ubaa9\uc801\uc740 \ud2b9\uc815 \uacbd\uc7c1\uc0ac\uc5c5\uc790 \uac1c\uc778\uc758 \ub9e4\ucd9c\uc744 \ubcf4\uc7a5\ud558\ub294 \uac83\uc774\ub2e4","\uacbd\uc7c1\ubc95\uc740 \uacbd\uc7c1\uc790\uc758 \uc2dc\uc7a5 \ud1f4\ucd9c\uc744 \ubc29\uc9c0\ud558\ub294 \uac83\uc744 \ucd5c\uc6b0\uc120 \ubaa9\uc801\uc73c\ub85c \ud55c\ub2e4","\uacbd\uc7c1\ubc95\uc740 \uc18c\ube44\uc790\ubcf4\ub2e4 \uc0ac\uc5c5\uc790\uc758 \uc774\uc775\uc744 \uc6b0\uc120\ud55c\ub2e4","\uacbd\uc7c1\ubc95\uc758 \ubcf4\ud638\ubc95\uc775\uc740 \uc2dc\ub300\uc640 \ubb34\uad00\ud558\uac8c \uace0\uc815\ub418\uc5b4 \uc788\uc73c\uba70 \ud559\uc124\uc0c1 \ub2e4\ud23c\uc774 \uc5c6\ub2e4"],t.s)
B.bc8=s([u.zL],t.s)
B.aHP=s(["\uacbd\uc7c1\uc758 \ubcf4\ud638 vs \uacbd\uc7c1\uc790\uc758 \ubcf4\ud638"],t.s)
B.bOC=new A.a("gen_gn_purpose_6","economic_law","\ubaa9\uc801\xb7\ucd1d\uce59","\ubaa9\uc801\xb7\uae30\ubcf8\uc774\ub150","\uacbd\uc7c1\ubc95\uc758 \ubcf4\ud638\ubc95\uc775\uc5d0 \uad00\ud55c \uc77c\ubc18\uc801 \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aI9,0,'\uacbd\uc7c1\ubc95 \uc774\ub860\uc0c1 \ub110\ub9ac \ubc1b\uc544\ub4e4\uc5ec\uc9c0\ub294 \uad00\uc810\uc740 "\uacbd\uc7c1\uc758 \ubcf4\ud638\uc774\uc9c0 \uacbd\uc7c1\uc790\uc758 \ubcf4\ud638\uac00 \uc544\ub2c8\ub2e4"\ub77c\ub294 \uba85\uc81c\ub85c \uc694\uc57d\ub41c\ub2e4. \uc989 \ud2b9\uc815 \uacbd\uc7c1\uc0ac\uc5c5\uc790 \uac1c\uc778\uc758 \uc874\uc18d\uc774\ub098 \uc774\uc775 \uc790\uccb4\ub97c \ubcf4\uc7a5\ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub77c, \uc5ec\ub7ec \uc0ac\uc5c5\uc790\uac00 \uc790\uc720\ub86d\uace0 \uacf5\uc815\ud558\uac8c \uacbd\uc7c1\ud560 \uc218 \uc788\ub294 \uc2dc\uc7a5\uc758 \uad6c\uc870\uc640 \uacfc\uc815\uc744 \ubcf4\ud638\ud558\ub294 \uac83\uc774 \ud575\uc2ec \ubcf4\ud638\ubc95\uc775\uc774\ub77c\ub294 \uac83\uc774\ub2e4. \uc774 \uad00\uc810\uc5d0\uc11c\ub294 \uacbd\uc7c1\uc758 \uacb0\uacfc\ub85c \ube44\ud6a8\uc728\uc801\uc778 \uc0ac\uc5c5\uc790\uac00 \uc2dc\uc7a5\uc5d0\uc11c \ud1f4\ucd9c\ub418\ub294 \uac83 \uc790\uccb4\ub294 \ubb38\uc81c\ub418\uc9c0 \uc54a\ub294\ub2e4.',B.bc8,B.aHP,null)
B.aHG=s(["\uc81c\uc870\uc5c5\xb7\uc11c\ube44\uc2a4\uc5c5 \ub610\ub294 \uadf8 \ubc16\uc758 \uc0ac\uc5c5\uc744 \ud558\ub294 \uc790\ub85c\uc11c, \ubc95\uc778\xb7\uac1c\uc778\uc744 \ubd88\ubb38\ud55c\ub2e4","\uc790\ubcf8\uae08 \uc77c\uc815 \uaddc\ubaa8 \uc774\uc0c1\uc778 \ubc95\uc778\ub9cc\uc744 \uc758\ubbf8\ud55c\ub2e4","\uc0c1\uc7a5\uae30\uc5c5\ub9cc\uc744 \uc0ac\uc5c5\uc790\ub85c \ubcf8\ub2e4","\uc624\uc9c1 \uc601\ub9ac\ub97c \ubaa9\uc801\uc73c\ub85c \uc124\ub9bd\ub41c \ubc95\uc778\ub9cc \uc0ac\uc5c5\uc790\uc5d0 \ud574\ub2f9\ud55c\ub2e4","\uacf5\uacf5\uae30\uad00\uc740 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \uc0ac\uc5c5\uc790\uc5d0 \ud574\ub2f9\ud558\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.aAe=s(["\ubc95\uc778\xb7\uac1c\uc778\uc744 \ubd88\ubb38\ud55c\ub2e4"],t.s)
B.azk=s(["\uc0ac\uc5c5\uc790\uc758 \uc815\uc758"],t.s)
B.bt4=new A.a("gen_gn_def_1","economic_law","\ubaa9\uc801\xb7\ucd1d\uce59","\uc8fc\uc694 \uc6a9\uc5b4\uc758 \uc815\uc758",'\ub3c5\uc810\uaddc\uc81c \ubc0f \uacf5\uc815\uac70\ub798\uc5d0 \uad00\ud55c \ubc95\ub960\uc0c1 "\uc0ac\uc5c5\uc790"\uc758 \uc815\uc758\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?',B.aHG,0,'\uacf5\uc815\uac70\ub798\ubc95\uc0c1 "\uc0ac\uc5c5\uc790"\ub294 \uc81c\uc870\uc5c5\xb7\uc11c\ube44\uc2a4\uc5c5 \ub610\ub294 \uadf8 \ubc16\uc758 \uc0ac\uc5c5\uc744 \ud558\ub294 \uc790\ub97c \ub9d0\ud558\uba70, \ubc95\uc778\uc778\uc9c0 \uac1c\uc778\uc778\uc9c0, \uc601\ub9ac\xb7\ube44\uc601\ub9ac\ub97c \ubd88\ubb38\ud558\uace0 \uc0ac\uc5c5\ud65c\ub3d9\uc744 \ud558\ub294 \uc774\uc0c1 \uc0ac\uc5c5\uc790\uc5d0 \ud574\ub2f9\ud560 \uc218 \uc788\ub2e4. \uc790\ubcf8\uae08 \uaddc\ubaa8\ub098 \uc0c1\uc7a5 \uc5ec\ubd80\ub294 \uc0ac\uc5c5\uc790\uc131 \ud310\ub2e8\uc758 \uae30\uc900\uc774 \uc544\ub2c8\uba70, \uacf5\uacf5\uae30\uad00\ub3c4 \uc0ac\uacbd\uc81c \uc8fc\uccb4\ub85c\uc11c \uc0ac\uc5c5\ud65c\ub3d9\uc744 \ud558\ub294 \uacbd\uc6b0\uc5d0\ub294 \uc0ac\uc5c5\uc790\ub85c \ucde8\uae09\ub420 \uc218 \uc788\ub2e4.',B.aAe,B.azk,null)
B.aZU=s(["\uadf8 \ud615\ud0dc\ub97c \ubd88\ubb38\ud558\uace0 2 \uc774\uc0c1\uc758 \uc0ac\uc5c5\uc790\uac00 \uacf5\ub3d9\uc758 \uc774\uc775\uc744 \uc99d\uc9c4\ud560 \ubaa9\uc801\uc73c\ub85c \uc870\uc9c1\ud55c \uacb0\ud569\uccb4 \ub610\ub294 \uc5f0\ud569\uccb4","\ub3d9\uc77c\ud55c \uc9c0\uc5ed\uc5d0 \uc18c\uc7ac\ud55c \uc0ac\uc5c5\uc790\ub4e4\uc758 \uce5c\ubaa9 \ubaa8\uc784","\ub2e8 1\uac1c\uc758 \uc0ac\uc5c5\uc790\ub85c \uad6c\uc131\ub41c \ub2e8\uccb4","\uc815\ubd80\uac00 \uc124\ub9bd\uc744 \uac15\uc81c\ud55c \ubc95\uc815\ub2e8\uccb4\ub9cc\uc744 \uc758\ubbf8\ud55c\ub2e4","\uc678\uad6d\uc0ac\uc5c5\uc790\ub85c\ub9cc \uad6c\uc131\ub41c \ub2e8\uccb4\ub97c \uc758\ubbf8\ud55c\ub2e4"],t.s)
B.aAa=s(["2 \uc774\uc0c1\uc758 \uc0ac\uc5c5\uc790\uac00 \uacf5\ub3d9\uc758 \uc774\uc775\uc744 \uc99d\uc9c4\ud560 \ubaa9\uc801\uc73c\ub85c \uc870\uc9c1\ud55c \uacb0\ud569\uccb4 \ub610\ub294 \uc5f0\ud569\uccb4"],t.s)
B.b5y=s(["\uc0ac\uc5c5\uc790\ub2e8\uccb4\uc758 \uc815\uc758"],t.s)
B.bo1=new A.a("gen_gn_def_2","economic_law","\ubaa9\uc801\xb7\ucd1d\uce59","\uc8fc\uc694 \uc6a9\uc5b4\uc758 \uc815\uc758",'\ub3c5\uc810\uaddc\uc81c \ubc0f \uacf5\uc815\uac70\ub798\uc5d0 \uad00\ud55c \ubc95\ub960\uc0c1 "\uc0ac\uc5c5\uc790\ub2e8\uccb4"\uc758 \uc815\uc758\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?',B.aZU,0,"\uc0ac\uc5c5\uc790\ub2e8\uccb4\ub294 \uc870\ud569\xb7\ud611\ud68c \ub4f1 \uba85\uce6d\uc774\ub098 \ubc95\uc801 \ud615\ud0dc\uc640 \uad00\uacc4\uc5c6\uc774, 2 \uc774\uc0c1\uc758 \uc0ac\uc5c5\uc790\uac00 \uacf5\ub3d9\uc758 \uc774\uc775\uc744 \uc99d\uc9c4\ud560 \ubaa9\uc801\uc73c\ub85c \uc870\uc9c1\ud55c \uacb0\ud569\uccb4 \ub610\ub294 \uc5f0\ud569\uccb4\ub97c \uc758\ubbf8\ud55c\ub2e4. \ub2e8\uc21c \uce5c\ubaa9 \ubaa8\uc784\uc774\ub77c\ub3c4 \uc2e4\uc9c8\uc801\uc73c\ub85c \uc0ac\uc5c5\uc790 \uacf5\ub3d9\uc758 \uc774\uc775 \uc99d\uc9c4\uc744 \ubaa9\uc801\uc73c\ub85c \ud55c\ub2e4\uba74 \uc0ac\uc5c5\uc790\ub2e8\uccb4\ub85c \uc778\uc815\ub420 \uc218 \uc788\uc73c\uba70, \ubc18\ub4dc\uc2dc \ubc95\uc815\ub2e8\uccb4\uc774\uac70\ub098 \uc815\ubd80\uac00 \uc124\ub9bd\uc744 \uac15\uc81c\ud55c \ub2e8\uccb4\uc77c \ud544\uc694\ub294 \uc5c6\ub2e4.",B.aAa,B.b5y,null)
B.aht=s(["2 \uc774\uc0c1\uc758 \ud68c\uc0ac\uac00 \ub3d9\uc77c\ud55c \uae30\uc5c5\uc9d1\ub2e8\uc5d0 \uc18d\ud558\ub294 \uacbd\uc6b0 \uc11c\ub85c\ub97c \uacc4\uc5f4\ud68c\uc0ac\ub77c \ud55c\ub2e4","\uacc4\uc5f4\ud68c\uc0ac\ub294 \ubc18\ub4dc\uc2dc \ub3d9\uc77c \uc5c5\uc885\uc744 \uc601\uc704\ud558\ub294 \ud68c\uc0ac\ub9cc\uc744 \uac00\ub9ac\ud0a8\ub2e4","\uacc4\uc5f4\ud68c\uc0ac\ub294 \uc678\uad6d\uc5d0 \ubcf8\uc0ac\ub97c \ub454 \ud68c\uc0ac\uc5d0\ub9cc \uc801\uc6a9\ub418\ub294 \uac1c\ub150\uc774\ub2e4","\uacc4\uc5f4\ud68c\uc0ac \uc5ec\ubd80\ub294 \ub9e4\ucd9c\uc561 \uaddc\ubaa8\ub85c\ub9cc \ud310\ub2e8\ud55c\ub2e4","\uacc4\uc5f4\ud68c\uc0ac\ub294 \uc0c1\uc7a5 \uc5ec\ubd80\uc5d0 \ub530\ub77c \uacb0\uc815\ub41c\ub2e4"],t.s)
B.aED=s(["2 \uc774\uc0c1\uc758 \ud68c\uc0ac\uac00 \ub3d9\uc77c\ud55c \uae30\uc5c5\uc9d1\ub2e8\uc5d0 \uc18d\ud558\ub294 \uacbd\uc6b0 \uc11c\ub85c\ub97c \uacc4\uc5f4\ud68c\uc0ac\ub77c \ud55c\ub2e4"],t.s)
B.b7k=s(["\uacc4\uc5f4\ud68c\uc0ac\uc758 \uc815\uc758"],t.s)
B.bqp=new A.a("gen_gn_def_3","economic_law","\ubaa9\uc801\xb7\ucd1d\uce59","\uc8fc\uc694 \uc6a9\uc5b4\uc758 \uc815\uc758",'\ub3c5\uc810\uaddc\uc81c \ubc0f \uacf5\uc815\uac70\ub798\uc5d0 \uad00\ud55c \ubc95\ub960\uc0c1 "\uacc4\uc5f4\ud68c\uc0ac"\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?',B.aht,0,"\uacc4\uc5f4\ud68c\uc0ac\ub294 2 \uc774\uc0c1\uc758 \ud68c\uc0ac\uac00 \ub3d9\uc77c\ud55c \uae30\uc5c5\uc9d1\ub2e8\uc5d0 \uc18d\ud558\ub294 \uacbd\uc6b0 \uadf8 \uc0c1\ud638\uac04\uc758 \uad00\uacc4\ub97c \uac00\ub9ac\ud0a4\ub294 \uac1c\ub150\uc774\ub2e4. \ub3d9\uc77c \uc5c5\uc885 \uc5ec\ubd80, \uc0c1\uc7a5 \uc5ec\ubd80, \ub9e4\ucd9c\uc561 \uaddc\ubaa8\uc640\ub294 \ubb34\uad00\ud558\uba70, \ub3d9\uc77c\ud55c \uc9c0\ubc30\ub825 \uc544\ub798 \uc788\ub294 \uae30\uc5c5\uc9d1\ub2e8 \uc18c\uc18d \uc5ec\ubd80\uac00 \ud575\uc2ec \ud310\ub2e8\uae30\uc900\uc774\ub2e4. \uc2dc\uc7a5\uc9c0\ubc30\uc801\uc0ac\uc5c5\uc790 \ud310\ub2e8\uc774\ub098 \ubd80\ub2f9\uc9c0\uc6d0\ud589\uc704 \ub4f1 \uc5ec\ub7ec \uaddc\uc815\uc5d0\uc11c \uacc4\uc5f4\ud68c\uc0ac \uad00\uacc4\uac00 \uc911\uc694\ud55c \uace0\ub824\uc694\uc18c\ub85c \uc791\uc6a9\ud55c\ub2e4.",B.aED,B.b7k,null)
B.alh=s(["\uc8fc\uc2dd(\uc9c0\ubd84)\uc758 \uc18c\uc720\ub97c \ud1b5\ud558\uc5ec \ub2e4\ub978 \ud68c\uc0ac\uc758 \uc0ac\uc5c5\ud65c\ub3d9\uc744 \uc9c0\ubc30\ud558\ub294 \uac83\uc744 \uc8fc\ub41c \uc0ac\uc5c5\uc73c\ub85c \ud558\ub294 \ud68c\uc0ac\ub97c \ub9d0\ud55c\ub2e4","\uc9c0\uc8fc\ud68c\uc0ac\ub294 \ubc18\ub4dc\uc2dc \uc81c\uc870\uc5c5\uc744 \uc9c1\uc811 \uc601\uc704\ud574\uc57c \ud55c\ub2e4","\uc9c0\uc8fc\ud68c\uc0ac\ub294 \ub2e4\ub978 \ud68c\uc0ac\uc758 \uc8fc\uc2dd\uc744 \uc804\ud600 \ubcf4\uc720\ud558\uc9c0 \uc54a\ub294 \ud68c\uc0ac\ub97c \uc758\ubbf8\ud55c\ub2e4","\uc9c0\uc8fc\ud68c\uc0ac \uc81c\ub3c4\ub294 \uacf5\uc815\uac70\ub798\ubc95\uc0c1 \uc804\uba74\uc801\uc73c\ub85c \uae08\uc9c0\ub41c\ub2e4","\uc9c0\uc8fc\ud68c\uc0ac\ub294 \uc0ac\uc5c5\uc790\ub2e8\uccb4\uc758 \ud55c \uc720\ud615\uc73c\ub85c \ubd84\ub958\ub41c\ub2e4"],t.s)
B.aPl=s(["\uc8fc\uc2dd(\uc9c0\ubd84)\uc758 \uc18c\uc720\ub97c \ud1b5\ud558\uc5ec \ub2e4\ub978 \ud68c\uc0ac\uc758 \uc0ac\uc5c5\ud65c\ub3d9\uc744 \uc9c0\ubc30\ud558\ub294 \uac83\uc744 \uc8fc\ub41c \uc0ac\uc5c5\uc73c\ub85c \ud558\ub294 \ud68c\uc0ac"],t.s)
B.Sb=s(["\uc9c0\uc8fc\ud68c\uc0ac\uc758 \uc815\uc758"],t.s)
B.bsH=new A.a("gen_gn_def_4","economic_law","\ubaa9\uc801\xb7\ucd1d\uce59","\uc8fc\uc694 \uc6a9\uc5b4\uc758 \uc815\uc758",'\ub3c5\uc810\uaddc\uc81c \ubc0f \uacf5\uc815\uac70\ub798\uc5d0 \uad00\ud55c \ubc95\ub960\uc0c1 "\uc9c0\uc8fc\ud68c\uc0ac"\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?',B.alh,0,"\uc9c0\uc8fc\ud68c\uc0ac\ub294 \uc8fc\uc2dd(\uc9c0\ubd84) \uc18c\uc720\ub97c \ud1b5\ud574 \ub2e4\ub978 \ud68c\uc0ac\uc758 \uc0ac\uc5c5\ud65c\ub3d9\uc744 \uc9c0\ubc30\ud558\ub294 \uac83\uc744 \uc8fc\ub41c \uc0ac\uc5c5\uc73c\ub85c \ud558\ub294 \ud68c\uc0ac\ub97c \ub9d0\ud55c\ub2e4. \uacf5\uc815\uac70\ub798\ubc95\uc740 \uc9c0\uc8fc\ud68c\uc0ac \uc790\uccb4\ub97c \uc804\uba74 \uae08\uc9c0\ud558\uc9c0 \uc54a\uace0, \ubd80\ucc44\ube44\uc728 \uc81c\ud55c\uc774\ub098 \uc790\ud68c\uc0ac \uc9c0\ubd84\uc728 \uc694\uac74 \ub4f1 \uc77c\uc815\ud55c \ud589\uc704\uaddc\uc81c\ub97c \ud1b5\ud574 \uad00\ub9ac\ud558\ub294 \ubc29\uc2dd\uc744 \ucde8\ud55c\ub2e4. \uc9c0\uc8fc\ud68c\uc0ac\ub294 \uc0ac\uc5c5\uc790\ub2e8\uccb4\uac00 \uc544\ub2c8\ub77c \ud68c\uc0ac(\uc0ac\uc5c5\uc790)\uc758 \ud55c \ud615\ud0dc\uc774\ub2e4.",B.aPl,B.Sb,null)
B.b6S=s(['\uc0ac\uc5c5\uc790\ub2e8\uccb4\uc758 \uacbd\uc7c1\uc81c\ud55c\uc801 \ud589\uc704\ub294 \uac1c\ubcc4 \uc0ac\uc5c5\uc790\uc758 \ud589\uc704\uc640 \ubcc4\ub3c4\ub85c "\uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704"\ub77c\ub294 \ub3c5\uc790\uc801\uc778 \uaddc\uc815\uc73c\ub85c \uaddc\uc728\ub41c\ub2e4',"\uc0ac\uc5c5\uc790\ub2e8\uccb4\ub294 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \uacf5\uc815\uac70\ub798\ubc95\uc758 \uaddc\uc728 \ub300\uc0c1\uc774 \ub418\uc9c0 \uc54a\ub294\ub2e4","\uc0ac\uc5c5\uc790\ub2e8\uccb4\uc640 \uac1c\ubcc4 \uc0ac\uc5c5\uc790\ub294 \ubc95\ub960\uc0c1 \uc644\uc804\ud788 \ub3d9\uc77c\ud558\uac8c \ucde8\uae09\ub418\uc5b4 \uad6c\ubcc4\ud560 \uc2e4\uc775\uc774 \uc5c6\ub2e4","\uc0ac\uc5c5\uc790\ub2e8\uccb4\uc5d0\ub294 \uc2dc\uc815\uc870\uce58\ub098 \uacfc\uc9d5\uae08\uc774 \ubd80\uacfc\ub420 \uc218 \uc5c6\ub2e4","\uc0ac\uc5c5\uc790\ub2e8\uccb4\ub294 \uc624\uc9c1 \ud615\uc0ac\ucc98\ubc8c\ub9cc \ubc1b\uc744 \uc218 \uc788\ub2e4"],t.s)
B.b0t=s(['\uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704"\ub77c\ub294 \ub3c5\uc790\uc801\uc778 \uaddc\uc815\uc73c\ub85c \uaddc\uc728\ub41c\ub2e4'],t.s)
B.baE=s(["\uc0ac\uc5c5\uc790\ub2e8\uccb4 \uaddc\uc728\uc758 \ub3c5\uc790\uc131"],t.s)
B.bsQ=new A.a("gen_gn_def_5","economic_law","\ubaa9\uc801\xb7\ucd1d\uce59","\uc8fc\uc694 \uc6a9\uc5b4\uc758 \uc815\uc758","\uc0ac\uc5c5\uc790\ub2e8\uccb4\uc640 \uac1c\ubcc4 \uc0ac\uc5c5\uc790\ub97c \uad6c\ubcc4\ud558\ub294 \uc2e4\uc775\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.b6S,0,'\uacf5\uc815\uac70\ub798\ubc95\uc740 \uc0ac\uc5c5\uc790\ub2e8\uccb4\uac00 \uad6c\uc131\uc0ac\uc5c5\uc790\uc758 \uc0ac\uc5c5\ud65c\ub3d9\uc744 \uc81c\ud55c\ud558\uac70\ub098 \uacbd\uc7c1\uc744 \uc81c\ud55c\ud558\ub294 \ud589\uc704 \ub4f1\uc744 "\uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704"\ub77c\ub294 \ubcc4\ub3c4\uc758 \uc7a5(\u7ae0)\uc5d0\uc11c \uaddc\uc728\ud558\uace0 \uc788\uc5b4, \uac1c\ubcc4 \uc0ac\uc5c5\uc790\uc758 \ubd80\ub2f9\uacf5\ub3d9\ud589\uc704\xb7\ubd88\uacf5\uc815\uac70\ub798\ud589\uc704 \ub4f1\uacfc\ub294 \uad6c\ubd84\ub418\ub294 \ub3c5\uc790\uc801\uc778 \uaddc\uc81c \uccb4\uacc4\ub97c \uac16\ub294\ub2e4. \uc0ac\uc5c5\uc790\ub2e8\uccb4\uc5d0\ub3c4 \uc2dc\uc815\uc870\uce58\xb7\uacfc\uc9d5\uae08 \ub4f1 \uc81c\uc7ac\uac00 \ubd80\uacfc\ub420 \uc218 \uc788\ub2e4.',B.b0t,B.baE,null)
B.aaf=s(["\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9, \uae30\uc5c5\uacb0\ud569, \ubd80\ub2f9\uacf5\ub3d9\ud589\uc704 \ub4f1 \uc5ec\ub7ec \uaddc\uc815\uc5d0\uc11c \uacf5\ud1b5\uc801\uc73c\ub85c \uc0ac\uc6a9\ub418\ub294 \uae30\ucd08 \uac1c\ub150\uc774\uae30 \ub54c\ubb38\uc774\ub2e4","\ud574\ub2f9 \uc815\uc758\ub294 \uc624\uc9c1 \uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704\uc5d0\ub9cc \uc801\uc6a9\ub418\uae30 \ub54c\ubb38\uc774\ub2e4","\ud574\ub2f9 \uc815\uc758\ub294 \ud615\uc0ac\ucc98\ubc8c \uaddc\uc815\uc5d0\uc11c\ub9cc \uc0ac\uc6a9\ub418\uae30 \ub54c\ubb38\uc774\ub2e4","\ud574\ub2f9 \uc815\uc758\ub294 \ubc95 \uc2dc\ud589 \uc774\ud6c4 \uc0ad\uc81c\ub420 \uc608\uc815\uc774\uae30 \ub54c\ubb38\uc774\ub2e4","\ud574\ub2f9 \uc815\uc758\ub294 \uc678\uad6d\uc0ac\uc5c5\uc790\uc5d0\uac8c\ub9cc \uc801\uc6a9\ub418\uae30 \ub54c\ubb38\uc774\ub2e4"],t.s)
B.aQI=s(["\uc5ec\ub7ec \uaddc\uc815\uc5d0\uc11c \uacf5\ud1b5\uc801\uc73c\ub85c \uc0ac\uc6a9\ub418\ub294 \uae30\ucd08 \uac1c\ub150\uc774\uae30 \ub54c\ubb38\uc774\ub2e4"],t.s)
B.a6D=s(["\uc77c\uc815\ud55c \uac70\ub798\ubd84\uc57c \uc815\uc758\uc758 \uc704\uce58"],t.s)
B.bMu=new A.a("gen_gn_def_6","economic_law","\ubaa9\uc801\xb7\ucd1d\uce59","\uc8fc\uc694 \uc6a9\uc5b4\uc758 \uc815\uc758",'"\uc77c\uc815\ud55c \uac70\ub798\ubd84\uc57c"(\uad00\ub828\uc2dc\uc7a5) \uc815\uc758\uaddc\uc815\uc774 \ubc95\ub960 \ucd1d\uce59\uc5d0 \uc704\uce58\ud558\ub294 \uc774\uc720\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?',B.aaf,0,'"\uc77c\uc815\ud55c \uac70\ub798\ubd84\uc57c"(\uad00\ub828\uc2dc\uc7a5)\ub294 \uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9 \uc5ec\ubd80, \uae30\uc5c5\uacb0\ud569\uc758 \uacbd\uc7c1\uc81c\ud55c\uc131, \ubd80\ub2f9\ud55c \uacf5\ub3d9\ud589\uc704\uc758 \uc131\ub9bd \ub4f1 \uacf5\uc815\uac70\ub798\ubc95\uc758 \uc5ec\ub7ec \ud575\uc2ec \uaddc\uc815\uc5d0\uc11c \uacf5\ud1b5\uc801\uc73c\ub85c \uc804\uc81c\ub418\ub294 \uae30\ucd08 \uac1c\ub150\uc774\ub2e4. \uc774 \ub54c\ubb38\uc5d0 \uac1c\ubcc4 \uc7a5(\u7ae0)\uc774 \uc544\ub2c8\ub77c \ubc95\ub960 \ucd1d\uce59(\uc815\uc758\uaddc\uc815)\uc5d0\uc11c \ud1b5\uc77c\uc801\uc73c\ub85c \uaddc\uc815\ud558\uc5ec \uc5ec\ub7ec \uaddc\uc815\uc5d0 \uc77c\uad00\ub418\uac8c \uc801\uc6a9\ub420 \uc218 \uc788\ub3c4\ub85d \ud558\uace0 \uc788\ub2e4.',B.aQI,B.a6D,null)
B.ajt=s(["\ud2b9\ud5c8\uad8c\xb7\uc2e4\uc6a9\uc2e0\uc548\uad8c\xb7\ub514\uc790\uc778\uad8c\xb7\uc0c1\ud45c\uad8c\xb7\uc800\uc791\uad8c\uc758 \uc815\ub2f9\ud55c \ud589\uc0ac\ub77c\uace0 \uc778\uc815\ub418\ub294 \ud589\uc704\uc5d0\ub294 \uc774 \ubc95\uc744 \uc801\uc6a9\ud558\uc9c0 \uc544\ub2c8\ud55c\ub2e4","\ubb34\uccb4\uc7ac\uc0b0\uad8c\uc740 \uc774 \ubc95\uc758 \uc801\uc6a9\ub300\uc0c1\uc5d0\uc11c \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \uc644\uc804\ud788 \ubc30\uc81c\ub418\uc9c0 \uc54a\ub294\ub2e4","\ubb34\uccb4\uc7ac\uc0b0\uad8c \ud589\uc0ac\ub294 \uadf8 \ubaa9\uc801\uacfc \ubb34\uad00\ud558\uac8c \ud56d\uc0c1 \uc801\uc6a9\uc81c\uc678\ub41c\ub2e4","\ubb34\uccb4\uc7ac\uc0b0\uad8c \uc801\uc6a9\uc81c\uc678\ub294 \uc0c1\ud45c\uad8c\uc5d0\ub9cc \ud55c\uc815\ub41c\ub2e4","\ubb34\uccb4\uc7ac\uc0b0\uad8c \uc801\uc6a9\uc81c\uc678\ub294 \uc678\uad6d\uc5d0 \ub4f1\ub85d\ub41c \uad8c\ub9ac\uc5d0\ub9cc \uc801\uc6a9\ub41c\ub2e4"],t.s)
B.atB=s(["\uc815\ub2f9\ud55c \ud589\uc0ac\ub77c\uace0 \uc778\uc815\ub418\ub294 \ud589\uc704\uc5d0\ub294 \uc774 \ubc95\uc744 \uc801\uc6a9\ud558\uc9c0 \uc544\ub2c8\ud55c\ub2e4"],t.s)
B.aXX=s(["\ubb34\uccb4\uc7ac\uc0b0\uad8c \uc801\uc6a9\uc81c\uc678"],t.s)
B.bxz=new A.a("gen_gn_scope_1","economic_law","\ubaa9\uc801\xb7\ucd1d\uce59","\uc801\uc6a9\ubc94\uc704\xb7\uc801\uc6a9\uc81c\uc678","\ub3c5\uc810\uaddc\uc81c \ubc0f \uacf5\uc815\uac70\ub798\uc5d0 \uad00\ud55c \ubc95\ub960\uc0c1 \ubb34\uccb4\uc7ac\uc0b0\uad8c\uc758 \ud589\uc0ac\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.ajt,0,'\uacf5\uc815\uac70\ub798\ubc95\uc740 \ud2b9\ud5c8\uad8c\xb7\uc2e4\uc6a9\uc2e0\uc548\uad8c\xb7\ub514\uc790\uc778\uad8c\xb7\uc0c1\ud45c\uad8c\xb7\uc800\uc791\uad8c \ub4f1 \ubb34\uccb4\uc7ac\uc0b0\uad8c\uc758 "\uc815\ub2f9\ud55c" \ud589\uc0ac\ub77c\uace0 \uc778\uc815\ub418\ub294 \ud589\uc704\uc5d0\ub294 \uc774 \ubc95\uc744 \uc801\uc6a9\ud558\uc9c0 \uc54a\ub294\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ub2e4\ub9cc \uc774\ub294 \uc815\ub2f9\ud55c \uad8c\ub9ac\ud589\uc0ac\uc758 \ubc94\uc704 \ub0b4\uc5d0\uc11c\ub9cc \uc778\uc815\ub418\ub294 \uc81c\ud55c\uc801 \uc801\uc6a9\uc81c\uc678\uc774\uba70, \uad8c\ub9ac\ub97c \ube59\uc790\ud558\uc5ec \ubd80\ub2f9\ud558\uac8c \uacbd\uc7c1\uc744 \uc81c\ud55c\ud558\ub294 \ud589\uc704\uae4c\uc9c0 \ubcf4\ud638\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4.',B.atB,B.aXX,null)
B.av1=s([u.E7,"\ud2b9\ud5c8\uad8c \ud589\uc0ac\ub77c\ub294 \uc774\uc720\ub9cc\uc73c\ub85c \ud56d\uc0c1 \uc801\uc6a9\uc81c\uc678\uac00 \uc778\uc815\ub41c\ub2e4","\uc774 \uacbd\uc6b0\ub294 \ubc18\ub4dc\uc2dc \ud615\uc0ac\ucc98\ubc8c\ub9cc \uac00\ub2a5\ud558\uace0 \ud589\uc815\uc81c\uc7ac\ub294 \ubd88\uac00\ub2a5\ud558\ub2e4","\ud2b9\ud5c8\uad8c\uc744 \uc774\uc720\ub85c \ud55c \ud589\uc704\ub294 \uacf5\uc815\uac70\ub798\ubc95\uc0c1 \uc2ec\uc0ac \ub300\uc0c1 \uc790\uccb4\uac00 \ub418\uc9c0 \uc54a\ub294\ub2e4","\uc774 \uacbd\uc6b0\ub294 \uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704\ub85c\ub9cc \ub2e4\ub8e8\uc5b4\uc9c4\ub2e4"],t.s)
B.awu=s([u.E7],t.s)
B.a7B=s(["\ubb34\uccb4\uc7ac\uc0b0\uad8c \uc801\uc6a9\uc81c\uc678\uc758 \ud55c\uacc4"],t.s)
B.bOm=new A.a("gen_gn_scope_2","economic_law","\ubaa9\uc801\xb7\ucd1d\uce59","\uc801\uc6a9\ubc94\uc704\xb7\uc801\uc6a9\uc81c\uc678","\ud2b9\ud5c8\uad8c\uc790\uc778 \uc2dc\uc7a5\uc9c0\ubc30\uc801\uc0ac\uc5c5\uc790\uac00 \ud2b9\ud5c8\uad8c\uc744 \ube59\uc790\ud558\uc5ec \uc815\ub2f9\ud55c \uc774\uc720 \uc5c6\uc774 \uacbd\uc7c1\uc0ac\uc5c5\uc790\uc640\uc758 \uac70\ub798\ub97c \uac70\uc808\ud558\uace0 \uc2dc\uc7a5\uc5d0\uc11c \ubc30\uc81c\ud558\ub824 \ud55c \uacbd\uc6b0\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.av1,0,'\ubb34\uccb4\uc7ac\uc0b0\uad8c \uc801\uc6a9\uc81c\uc678\ub294 "\uc815\ub2f9\ud55c" \uad8c\ub9ac\ud589\uc0ac\uc5d0 \ud55c\uc815\ub41c\ub2e4. \ud2b9\ud5c8\uad8c\uc744 \uba85\ubaa9\uc73c\ub85c \ub0b4\uc138\uc6b0\ub354\ub77c\ub3c4 \uc2e4\uc9c8\uc801\uc73c\ub85c \uacbd\uc7c1\uc744 \ubd80\ub2f9\ud558\uac8c \uc81c\ud55c\ud558\ub824\ub294 \ubaa9\uc801\uc758 \ud589\uc704(\uc608: \uc815\ub2f9\ud55c \uc774\uc720 \uc5c6\ub294 \uac70\ub798\uac70\uc808\uc744 \ud1b5\ud55c \ubc30\uc81c)\ub294 \uc815\ub2f9\ud55c \uad8c\ub9ac\ud589\uc0ac\ub85c \ubcf4\uae30 \uc5b4\ub824\uc6cc \uc801\uc6a9\uc81c\uc678\uac00 \uc778\uc815\ub418\uc9c0 \uc54a\uace0, \uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9 \ub4f1 \ud1b5\uc0c1\uc801\uc778 \uc2ec\uc0ac \ub300\uc0c1\uc774 \ub420 \uc218 \uc788\ub2e4.',B.awu,B.a7B,null)
B.b4Q=s(["\uc18c\uaddc\ubaa8 \uc0ac\uc5c5\uc790 \ub610\ub294 \uc18c\ube44\uc790\uc758 \uc0c1\ud638\ubd80\uc870\ub97c \ubaa9\uc801\uc73c\ub85c \ud558\uace0 \uc784\uc758\uc124\ub9bd\xb7\ud0c8\ud1f4\uc758 \uc790\uc720\xb7\uc758\uacb0\uad8c \ud3c9\ub4f1 \ub4f1 \uc694\uac74\uc744 \uac16\ucd98 \uc870\ud569\uc758 \ud589\uc704\ub294 \uc801\uc6a9\uc774 \uc81c\uc678\ub420 \uc218 \uc788\ub2e4","\uc870\ud569\uc774\ub77c\ub294 \uba85\uce6d\uc744 \uc0ac\uc6a9\ud558\uae30\ub9cc \ud558\uba74 \uc694\uac74\uacfc \uad00\uacc4\uc5c6\uc774 \ud56d\uc0c1 \uc801\uc6a9\uc81c\uc678\ub41c\ub2e4","\uc870\ud569\uc758 \ud589\uc704\ub294 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \uc801\uc6a9\uc81c\uc678 \ub300\uc0c1\uc774 \ub420 \uc218 \uc5c6\ub2e4","\uc870\ud569\uc758 \uc801\uc6a9\uc81c\uc678\ub294 \ub300\uae30\uc5c5\uc73c\ub85c \uad6c\uc131\ub41c \uc870\ud569\uc5d0\ub3c4 \ub3d9\uc77c\ud558\uac8c \uc778\uc815\ub41c\ub2e4","\uc870\ud569\uc758 \uc801\uc6a9\uc81c\uc678 \uc5ec\ubd80\ub294 \uc870\ud569\uc758 \uc124\ub9bd\uc5f0\ub3c4\ub9cc\uc73c\ub85c \ud310\ub2e8\ud55c\ub2e4"],t.s)
B.avw=s(["\uc784\uc758\uc124\ub9bd\xb7\ud0c8\ud1f4\uc758 \uc790\uc720\xb7\uc758\uacb0\uad8c \ud3c9\ub4f1 \ub4f1 \uc694\uac74\uc744 \uac16\ucd98 \uc870\ud569\uc758 \ud589\uc704\ub294 \uc801\uc6a9\uc774 \uc81c\uc678\ub420 \uc218 \uc788\ub2e4"],t.s)
B.aYW=s(["\uc870\ud569\uc758 \uc801\uc6a9\uc81c\uc678 \uc694\uac74"],t.s)
B.bQ7=new A.a("gen_gn_scope_3","economic_law","\ubaa9\uc801\xb7\ucd1d\uce59","\uc801\uc6a9\ubc94\uc704\xb7\uc801\uc6a9\uc81c\uc678","\ub3c5\uc810\uaddc\uc81c \ubc0f \uacf5\uc815\uac70\ub798\uc5d0 \uad00\ud55c \ubc95\ub960\uc0c1 \uc77c\uc815\ud55c \uc694\uac74\uc744 \uac16\ucd98 \uc870\ud569\uc758 \ud589\uc704\uc5d0 \ub300\ud55c \uc801\uc6a9\uc81c\uc678\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.b4Q,0,'\uacf5\uc815\uac70\ub798\ubc95\uc740 \uc18c\uaddc\ubaa8 \uc0ac\uc5c5\uc790 \ub610\ub294 \uc18c\ube44\uc790\uc758 \uc0c1\ud638\ubd80\uc870\ub97c \ubaa9\uc801\uc73c\ub85c \ud558\uba70 \uc784\uc758\ub85c \uc124\ub9bd\ub418\uace0 \uc870\ud569\uc6d0\uc758 \uac00\uc785\xb7\ud0c8\ud1f4\uac00 \uc790\uc720\ub86d\uace0 \uc758\uacb0\uad8c\uc774 \ud3c9\ub4f1\ud55c \ub4f1 \uc77c\uc815\ud55c \uc694\uac74\uc744 \uac16\ucd98 \uc870\ud569\uc758 \ud589\uc704\uc5d0 \ub300\ud574 \uc801\uc6a9\uc744 \uc81c\uc678\ud560 \uc218 \uc788\ub3c4\ub85d \ud558\uace0 \uc788\ub2e4. \ub2e4\ub9cc \uc774\ub294 \uc694\uac74 \ucda9\uc871 \uc5ec\ubd80\uc5d0 \ub530\ub77c \ud310\ub2e8\ub418\ub294 \uac83\uc774\uc9c0, \ub2e8\uc21c\ud788 "\uc870\ud569"\uc774\ub77c\ub294 \uba85\uce6d \uc0ac\uc6a9\ub9cc\uc73c\ub85c \uc778\uc815\ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4.',B.avw,B.aYW,null)
B.WH=s(["\uc870\ud569\uc774 \ubd88\uacf5\uc815\ud55c \uac70\ub798\ubc29\ubc95\uc744 \uc0ac\uc6a9\ud558\uac70\ub098 \ubd80\ub2f9\ud558\uac8c \uacbd\uc7c1\uc744 \uc81c\ud55c\ud558\uc5ec \uac00\uaca9\uc744 \uc778\uc0c1\ud558\ub294 \uacbd\uc6b0","\uc870\ud569\uc6d0\uc758 \uc218\uac00 5\uc778\uc744 \ucd08\uacfc\ud558\ub294 \uacbd\uc6b0","\uc870\ud569\uc758 \uc124\ub9bd \ubaa9\uc801\uc774 \uc0c1\ud638\ubd80\uc870\uc778 \uacbd\uc6b0","\uc870\ud569\uc6d0\uc758 \uac00\uc785\uacfc \ud0c8\ud1f4\uac00 \uc790\uc720\ub85c\uc6b4 \uacbd\uc6b0","\uc870\ud569\uc758 \uc758\uacb0\uad8c\uc774 \ud3c9\ub4f1\ud558\uac8c \ubcf4\uc7a5\ub418\ub294 \uacbd\uc6b0"],t.s)
B.YA=s(["\ubd88\uacf5\uc815\ud55c \uac70\ub798\ubc29\ubc95\uc744 \uc0ac\uc6a9\ud558\uac70\ub098 \ubd80\ub2f9\ud558\uac8c \uacbd\uc7c1\uc744 \uc81c\ud55c\ud558\uc5ec \uac00\uaca9\uc744 \uc778\uc0c1\ud558\ub294 \uacbd\uc6b0"],t.s)
B.b11=s(["\uc870\ud569 \uc801\uc6a9\uc81c\uc678\uc758 \ud55c\uacc4"],t.s)
B.bEn=new A.a("gen_gn_scope_4","economic_law","\ubaa9\uc801\xb7\ucd1d\uce59","\uc801\uc6a9\ubc94\uc704\xb7\uc801\uc6a9\uc81c\uc678","\uc801\uc6a9\uc81c\uc678 \uc694\uac74\uc744 \uac16\ucd98 \uc870\ud569\uc774\ub77c \ud558\ub354\ub77c\ub3c4 \uacf5\uc815\uac70\ub798\ubc95\uc758 \uaddc\uc728\uc744 \ubc1b\uc744 \uc218 \uc788\ub294 \uacbd\uc6b0\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.WH,0,"\uc801\uc6a9\uc81c\uc678 \uc694\uac74\uc744 \uac16\ucd98 \uc870\ud569\uc774\ub77c\ub3c4 \uadf8 \uc870\ud569\uc774 \ubd88\uacf5\uc815\ud55c \uac70\ub798\ubc29\ubc95\uc744 \uc0ac\uc6a9\ud558\uac70\ub098 \ubd80\ub2f9\ud558\uac8c \uacbd\uc7c1\uc744 \uc81c\ud55c\ud558\uc5ec \uac00\uaca9\uc744 \uc778\uc0c1\ud558\ub294 \ub4f1\uc758 \ud589\uc704\ub97c \ud558\ub294 \uacbd\uc6b0\uc5d0\ub294 \uacf5\uc815\uac70\ub798\ubc95\uc758 \uc801\uc6a9\uc81c\uc678\uac00 \uc778\uc815\ub418\uc9c0 \uc54a\uace0 \uaddc\uc728\uc744 \ubc1b\uc744 \uc218 \uc788\ub2e4. \uc870\ud569\uc6d0 \uc218, \uc124\ub9bd\ubaa9\uc801, \uac00\uc785\xb7\ud0c8\ud1f4\uc758 \uc790\uc720, \uc758\uacb0\uad8c \ud3c9\ub4f1 \ub4f1\uc740 \uc624\ud788\ub824 \uc801\uc6a9\uc81c\uc678\uac00 \uc778\uc815\ub418\uae30 \uc704\ud55c \uc694\uac74\uc5d0 \ud574\ub2f9\ud558\ub294 \uc0ac\ud56d\ub4e4\uc774\ub2e4.",B.YA,B.b11,null)
B.biD=s(["\uad6d\ub0b4\uc5d0\uc11c \uc0ac\uc5c5\uc744 \uc601\uc704\ud558\ub294 \uc0ac\uc5c5\uc790\uc5d0\uac8c \uc6d0\uce59\uc801\uc73c\ub85c \uc801\uc6a9\ub418\uba70, \uad6d\uac00\xb7\uc9c0\ubc29\uc790\uce58\ub2e8\uccb4\ub3c4 \uc0ac\uacbd\uc81c \uc8fc\uccb4\ub85c\uc11c \uc0ac\uc5c5\ud65c\ub3d9\uc744 \ud558\ub294 \uacbd\uc6b0 \uc0ac\uc5c5\uc790\uc5d0 \ud3ec\ud568\ub420 \uc218 \uc788\ub2e4","\uc774 \ubc95\uc740 \ubbfc\uac04 \uc0ac\uc5c5\uc790\uc5d0\uac8c\ub9cc \uc801\uc6a9\ub418\uace0 \uad6d\uac00\xb7\uc9c0\ubc29\uc790\uce58\ub2e8\uccb4\uc5d0\ub294 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4","\uc774 \ubc95\uc740 \uc678\uad6d\uc0ac\uc5c5\uc790\uc5d0\uac8c\ub294 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4","\uc774 \ubc95\uc740 \uac1c\uc778\uc0ac\uc5c5\uc790\uc5d0\uac8c\ub294 \uc801\uc6a9\ub418\uc9c0 \uc54a\uace0 \ubc95\uc778\uc5d0\uac8c\ub9cc \uc801\uc6a9\ub41c\ub2e4","\uc774 \ubc95\uc758 \uc778\uc801 \uc801\uc6a9\ubc94\uc704\ub294 \ub9e4\ucd9c\uc561 \uaddc\ubaa8\ub85c\ub9cc \uacb0\uc815\ub41c\ub2e4"],t.s)
B.beB=s(["\uad6d\uac00\xb7\uc9c0\ubc29\uc790\uce58\ub2e8\uccb4\ub3c4 \uc0ac\uacbd\uc81c \uc8fc\uccb4\ub85c\uc11c \uc0ac\uc5c5\ud65c\ub3d9\uc744 \ud558\ub294 \uacbd\uc6b0 \uc0ac\uc5c5\uc790\uc5d0 \ud3ec\ud568\ub420 \uc218 \uc788\ub2e4"],t.s)
B.awz=s(["\uc778\uc801 \uc801\uc6a9\ubc94\uc704"],t.s)
B.bOy=new A.a("gen_gn_scope_5","economic_law","\ubaa9\uc801\xb7\ucd1d\uce59","\uc801\uc6a9\ubc94\uc704\xb7\uc801\uc6a9\uc81c\uc678","\uacf5\uc815\uac70\ub798\ubc95\uc758 \uc778\uc801 \uc801\uc6a9\ubc94\uc704\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.biD,0,"\uacf5\uc815\uac70\ub798\ubc95\uc740 \uad6d\ub0b4\uc5d0\uc11c \uc0ac\uc5c5\uc744 \uc601\uc704\ud558\ub294 \uc0ac\uc5c5\uc790\uc5d0\uac8c \uc6d0\uce59\uc801\uc73c\ub85c \uc801\uc6a9\ub418\uba70, \ubc95\uc778\xb7\uac1c\uc778\uc744 \ubd88\ubb38\ud55c\ub2e4. \uad6d\uac00\ub098 \uc9c0\ubc29\uc790\uce58\ub2e8\uccb4\ub3c4 \uacf5\uad8c\ub825 \ud589\uc0ac \uc8fc\uccb4\uac00 \uc544\ub2c8\ub77c \uc0ac\uacbd\uc81c \uc8fc\uccb4\ub85c\uc11c \uc0ac\uc5c5\ud65c\ub3d9\uc744 \ud558\ub294 \uacbd\uc6b0\uc5d0\ub294 \uc0ac\uc5c5\uc790\uc5d0 \ud574\ub2f9\ud560 \uc218 \uc788\uace0, \uc5ed\uc678\uc801\uc6a9 \ubc95\ub9ac\uc5d0 \ub530\ub77c \uad6d\ub0b4\uc2dc\uc7a5\uc5d0 \uc601\ud5a5\uc744 \ubbf8\uce58\ub294 \uc678\uad6d\uc0ac\uc5c5\uc790\uc758 \ud589\uc704\uc5d0\ub3c4 \uc801\uc6a9\ub420 \uc218 \uc788\ub2e4.",B.beB,B.awz,null)
B.UU=s([u.eq,"\ub2e4\ub978 \ubc95\ub839\uc758 \uc874\uc7ac\ub9cc\uc73c\ub85c \ud56d\uc0c1 \uc790\ub3d9\uc73c\ub85c \uacf5\uc815\uac70\ub798\ubc95 \uc801\uc6a9\uc774 \uc804\uba74 \ubc30\uc81c\ub41c\ub2e4","\ub2e4\ub978 \ubc95\ub839\uc5d0 \ub530\ub978 \ud589\uc704\ub294 \uadf8 \ub0b4\uc6a9\uc744 \ubd88\ubb38\ud558\uace0 \ubaa8\ub450 \uc801\uc6a9\uc81c\uc678 \ub300\uc0c1\uc774\ub2e4","\ub2e4\ub978 \ubc95\ub839\uacfc\uc758 \uad00\uacc4\ub294 \uc774 \ubc95\uc5d0\uc11c \uc804\ud600 \uace0\ub824\ub418\uc9c0 \uc54a\ub294\ub2e4","\ub2e4\ub978 \ubc95\ub839\uc5d0 \ub530\ub978 \ud589\uc704\ub294 \ubc18\ub4dc\uc2dc \ud615\uc0ac\ucc98\ubc8c \ub300\uc0c1\uc5d0\uc11c \uc81c\uc678\ub41c\ub2e4\ub294 \uc758\ubbf8\uc774\ub2e4"],t.s)
B.amS=s([u.eq],t.s)
B.aDj=s(["\ub2e4\ub978 \ubc95\ub839\uc5d0 \ub530\ub978 \uc815\ub2f9\ud589\uc704"],t.s)
B.bHq=new A.a("gen_gn_scope_6","economic_law","\ubaa9\uc801\xb7\ucd1d\uce59","\uc801\uc6a9\ubc94\uc704\xb7\uc801\uc6a9\uc81c\uc678","\ub2e4\ub978 \ubc95\ub839\uc5d0 \ub530\ub978 \uc815\ub2f9\ud55c \ud589\uc704\uc640 \uacf5\uc815\uac70\ub798\ubc95 \uc801\uc6a9\uc81c\uc678\uc758 \uad00\uacc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.UU,0,"\ub2e4\ub978 \ubc95\ub839\uc5d0 \ub530\ub77c \ud589\ud558\ub294 \uc815\ub2f9\ud55c \ud589\uc704\uc5d0 \ub300\ud55c \uc801\uc6a9\uc81c\uc678\ub294 \uadf8 \ubc95\ub839\uc5d0 \uba85\uc2dc\uc801\uc774\uace0 \uad6c\uccb4\uc801\uc778 \uadfc\uac70\uac00 \uc788\ub294 \uacbd\uc6b0\uc5d0 \ud55c\ud574 \uc81c\ud55c\uc801\uc73c\ub85c \uc778\uc815\ub418\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub2e4. \ub2e8\uc21c\ud788 \ub2e4\ub978 \ubc95\ub839\uc774 \uc874\uc7ac\ud55c\ub2e4\ub294 \uc0ac\uc815\ub9cc\uc73c\ub85c \uacf5\uc815\uac70\ub798\ubc95 \uc801\uc6a9\uc774 \uc790\ub3d9\uc73c\ub85c \uc804\uba74 \ubc30\uc81c\ub418\ub294 \uac83\uc740 \uc544\ub2c8\uba70, \uadf8 \ud589\uc704\uac00 \uc2e4\uc9c8\uc801\uc73c\ub85c \uacbd\uc7c1\uc744 \ubd80\ub2f9\ud558\uac8c \uc81c\ud55c\ud558\ub294\uc9c0 \uc5ec\ubd80\uac00 \ud568\uaed8 \uac80\ud1a0\ub41c\ub2e4.",B.amS,B.aDj,null)
B.ahc=s(["\uacf5\uc815\uac70\ub798\ubc95\uc740 \uc77c\ubc18\ubc95\uc801 \uc9c0\uc704\ub97c \uac00\uc9c0\uba70, \uac1c\ubcc4 \ubc95\ub960\uc740 \ud2b9\uc815 \uac70\ub798\ubd84\uc57c\uc5d0 \ud2b9\ud654\ub41c \ud2b9\ubcc4\ubc95\uc73c\ub85c\uc11c \uc6b0\uc120 \uc801\uc6a9\ub418\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub2e4","\uac1c\ubcc4 \ubc95\ub960\uc740 \uacf5\uc815\uac70\ub798\ubc95\uacfc \uc544\ubb34\ub7f0 \uad00\ub828\uc774 \uc5c6\ub294 \ubcc4\uac1c\uc758 \ub3c5\ub9bd\ub41c \ubc95\uccb4\uacc4\uc774\ub2e4","\uac1c\ubcc4 \ubc95\ub960\uc774 \uc788\uc73c\uba74 \uacf5\uc815\uac70\ub798\ubc95\uc740 \ud574\ub2f9 \ubd84\uc57c\uc5d0\uc11c \uc644\uc804\ud788 \ud6a8\ub825\uc744 \uc0c1\uc2e4\ud55c\ub2e4","\uacf5\uc815\uac70\ub798\ubc95\uc774 \ud56d\uc0c1 \uac1c\ubcc4 \ubc95\ub960\uc5d0 \uc6b0\uc120\ud558\uc5ec \uc801\uc6a9\ub41c\ub2e4","\uac1c\ubcc4 \ubc95\ub960\uacfc \uacf5\uc815\uac70\ub798\ubc95\uc740 \ub3d9\uc2dc\uc5d0 \uc801\uc6a9\ub420 \uc218 \uc5c6\ub2e4"],t.s)
B.a49=s(["\uac1c\ubcc4 \ubc95\ub960\uc740 \ud2b9\uc815 \uac70\ub798\ubd84\uc57c\uc5d0 \ud2b9\ud654\ub41c \ud2b9\ubcc4\ubc95\uc73c\ub85c\uc11c \uc6b0\uc120 \uc801\uc6a9\ub418\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub2e4"],t.s)
B.b_J=s(["\uc77c\ubc18\ubc95\xb7\ud2b9\ubcc4\ubc95 \uad00\uacc4"],t.s)
B.bMT=new A.a("gen_gn_system_1","economic_law","\ubaa9\uc801\xb7\ucd1d\uce59","\ubc95 \uccb4\uacc4\xb7\ub2e4\ub978 \ubc95\ub960\uacfc\uc758 \uad00\uacc4","\uac00\ub9f9\uc0ac\uc5c5\uac70\ub798\uc758 \uacf5\uc815\ud654\uc5d0 \uad00\ud55c \ubc95\ub960, \ud558\ub3c4\uae09\uac70\ub798 \uacf5\uc815\ud654\uc5d0 \uad00\ud55c \ubc95\ub960 \ub4f1 \uac1c\ubcc4 \ubc95\ub960\uacfc \uacf5\uc815\uac70\ub798\ubc95\uc758 \uad00\uacc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.ahc,0,"\uac00\ub9f9\uc0ac\uc5c5\ubc95\xb7\ud558\ub3c4\uae09\ubc95 \ub4f1\uc740 \ud2b9\uc815 \uac70\ub798\ubd84\uc57c(\uac00\ub9f9, \ud558\ub3c4\uae09 \ub4f1)\uc758 \ud2b9\uc131\uc744 \ubc18\uc601\ud574 \uacf5\uc815\uac70\ub798\ubc95\uc758 \uae30\ubcf8 \uc774\ub150 \uc544\ub798 \ub9c8\ub828\ub41c \ud2b9\ubcc4\ubc95\uc73c\ub85c, \ud574\ub2f9 \ubd84\uc57c\uc5d0\uc11c\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \ud2b9\ubcc4\ubc95\uc774 \uc6b0\uc120 \uc801\uc6a9\ub41c\ub2e4. \ub2e4\ub9cc \uc774\ub4e4 \ubc95\ub960\ub3c4 \uad81\uadf9\uc801\uc73c\ub85c\ub294 \uacf5\uc815\uac70\ub798\ubc95\uc774 \ucd94\uad6c\ud558\ub294 \uacf5\uc815\ud558\uace0 \uc790\uc720\ub85c\uc6b4 \uacbd\uc7c1 \ucd09\uc9c4\uc774\ub77c\ub294 \uc774\ub150\uc744 \uacf5\uc720\ud558\uba70, \ub450 \ubc95\ub960\uc774 \uc0c1\ud638 \ubc30\ud0c0\uc801\uc73c\ub85c \ub2e8\uc808\ub41c \uac83\uc740 \uc544\ub2c8\ub2e4.",B.a49,B.b_J,null)
B.aTB=s(["\uc57d\uad00\ubc95\uc740 \ubd88\uacf5\uc815\uc57d\uad00 \uc2ec\uc0ac\ub97c \ubcc4\ub3c4\ub85c \uaddc\uc728\ud558\ub294 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c \uc18c\uad00\uc758 \uac1c\ubcc4 \ubc95\ub960\ub85c\uc11c \uacf5\uc815\uac70\ub798\ubc95\uacfc \ud568\uaed8 \uc791\ub3d9\ud55c\ub2e4","\uc57d\uad00\ubc95\uc740 \uacf5\uc815\uac70\ub798\ubc95\uacfc \uc804\ud600 \uad00\ub828 \uc5c6\ub294 \ub2e4\ub978 \uc815\ubd80\ubd80\ucc98 \uc18c\uad00 \ubc95\ub960\uc774\ub2e4","\uc57d\uad00\ubc95\uc774 \uc2dc\ud589\ub418\uba74 \uacf5\uc815\uac70\ub798\ubc95\uc0c1 \ubd88\uacf5\uc815\uac70\ub798\ud589\uc704 \uaddc\uc815\uc740 \uc804\ubd80 \ud3d0\uc9c0\ub41c\ub2e4","\uc57d\uad00\ubc95\uc740 \uc0ac\uc5c5\uc790\ub2e8\uccb4\uc5d0\uac8c\ub9cc \uc801\uc6a9\ub41c\ub2e4","\uc57d\uad00\uc5d0 \uad00\ud55c \uc0ac\ud56d\uc740 \uc624\uc9c1 \ubbfc\ubc95\uc73c\ub85c\ub9cc \uaddc\uc728\ub418\uace0 \uc57d\uad00\ubc95\uc740 \uc874\uc7ac\ud558\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.aoT=s(["\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c \uc18c\uad00\uc758 \uac1c\ubcc4 \ubc95\ub960\ub85c\uc11c \uacf5\uc815\uac70\ub798\ubc95\uacfc \ud568\uaed8 \uc791\ub3d9\ud55c\ub2e4"],t.s)
B.a65=s(["\uc57d\uad00\ubc95\uacfc \uacf5\uc815\uac70\ub798\ubc95\uc758 \uad00\uacc4"],t.s)
B.btB=new A.a("gen_gn_system_2","economic_law","\ubaa9\uc801\xb7\ucd1d\uce59","\ubc95 \uccb4\uacc4\xb7\ub2e4\ub978 \ubc95\ub960\uacfc\uc758 \uad00\uacc4","\uc57d\uad00\uc758 \uaddc\uc81c\uc5d0 \uad00\ud55c \ubc95\ub960\uacfc \uacf5\uc815\uac70\ub798\ubc95\uc758 \uad00\uacc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aTB,0,"\uc57d\uad00\uc758 \uaddc\uc81c\uc5d0 \uad00\ud55c \ubc95\ub960\uc740 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uac00 \uc18c\uad00\ud558\ub294 \uac1c\ubcc4 \ubc95\ub960\ub85c\uc11c, \uc0ac\uc5c5\uc790\uac00 \ubbf8\ub9ac \ub9c8\ub828\ud55c \uc57d\uad00 \uc870\ud56d\uc758 \ubd88\uacf5\uc815\uc131\uc744 \uc2ec\uc0ac\xb7\uaddc\uc81c\ud558\ub294 \uac83\uc744 \ubaa9\uc801\uc73c\ub85c \ud55c\ub2e4. \uacf5\uc815\uac70\ub798\ubc95\uacfc\ub294 \uaddc\uc728 \ub300\uc0c1\uacfc \uc694\uac74\uc774 \ub2e4\ub974\uc9c0\ub9cc, \uac19\uc740 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c \uccb4\uacc4 \uc548\uc5d0\uc11c \uc0c1\ud638 \ubcf4\uc644\uc801\uc73c\ub85c \uc791\ub3d9\ud558\ub294 \uad00\uacc4\uc5d0 \uc788\ub2e4.",B.aoT,B.a65,null)
B.aUY=s(["\ub450 \ubc95\ub960\uc740 \ubaa9\uc801\uacfc \ubcf4\ud638\ubc95\uc775\uc758 \uac15\uc870\uc810\uc774 \ub2e4\ub974\uc9c0\ub9cc \uc18c\ube44\uc790 \ud6c4\uc0dd \uc99d\uc9c4\uc774\ub77c\ub294 \uce21\uba74\uc5d0\uc11c \uc0c1\ud638 \ubcf4\uc644\uc801\uc73c\ub85c \uae30\ub2a5\ud55c\ub2e4","\uc18c\ube44\uc790\uae30\ubcf8\ubc95\uc774 \uc2dc\ud589\ub41c \uc774\ud6c4 \uacf5\uc815\uac70\ub798\ubc95\uc740 \ud3d0\uc9c0\ub418\uc5c8\ub2e4","\ub450 \ubc95\ub960\uc740 \uc644\uc804\ud788 \ub3d9\uc77c\ud55c \ub0b4\uc6a9\uc744 \uaddc\uc815\ud558\uace0 \uc788\uc5b4 \ud558\ub098\ub9cc \uc874\uc7ac\ud574\ub3c4 \ubb34\ubc29\ud558\ub2e4","\uc18c\ube44\uc790\uae30\ubcf8\ubc95\uc740 \uc0ac\uc5c5\uc790\uc5d0\uac8c\ub9cc \uc801\uc6a9\ub418\uace0 \uc18c\ube44\uc790\uc5d0\uac8c\ub294 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4","\uacf5\uc815\uac70\ub798\ubc95\uc740 \uc18c\ube44\uc790 \uad00\ub828 \uc0ac\ud56d\uc744 \uc804\ud600 \ub2e4\ub8e8\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.aEX=s(["\uc18c\ube44\uc790 \ud6c4\uc0dd \uc99d\uc9c4\uc774\ub77c\ub294 \uce21\uba74\uc5d0\uc11c \uc0c1\ud638 \ubcf4\uc644\uc801\uc73c\ub85c \uae30\ub2a5\ud55c\ub2e4"],t.s)
B.avX=s(["\uc18c\ube44\uc790\uae30\ubcf8\ubc95\uacfc\uc758 \uad00\uacc4"],t.s)
B.bKy=new A.a("gen_gn_system_3","economic_law","\ubaa9\uc801\xb7\ucd1d\uce59","\ubc95 \uccb4\uacc4\xb7\ub2e4\ub978 \ubc95\ub960\uacfc\uc758 \uad00\uacc4","\uc18c\ube44\uc790\uae30\ubcf8\ubc95\uacfc \uacf5\uc815\uac70\ub798\ubc95\uc758 \uad00\uacc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aUY,0,"\uc18c\ube44\uc790\uae30\ubcf8\ubc95\uc740 \uc18c\ube44\uc790\uc758 \uad8c\uc775 \uc99d\uc9c4\uacfc \ud53c\ud574\uad6c\uc81c\ub97c \uc9c1\uc811\uc801 \ubaa9\uc801\uc73c\ub85c \ud558\ub294 \ubc18\uba74, \uacf5\uc815\uac70\ub798\ubc95\uc740 \uacbd\uc7c1 \ucd09\uc9c4\uc744 \ud1b5\ud55c \uad6c\uc870\uc801\xb7\uac04\uc811\uc801 \uc18c\ube44\uc790\ud6c4\uc0dd \uc99d\uc9c4\uc5d0 \ubc29\uc810\uc774 \uc788\ub2e4. \ub450 \ubc95\ub960\uc740 \uac15\uc870\uc810\uc774 \ub2e4\ub974\uc9c0\ub9cc \uad81\uadf9\uc801\uc73c\ub85c \uc18c\ube44\uc790 \ud6c4\uc0dd \uc99d\uc9c4\uc774\ub77c\ub294 \uacf5\ud1b5\uc758 \uc9c0\ud5a5\uc810\uc744 \uac00\uc9c0\uace0 \uc0c1\ud638 \ubcf4\uc644\uc801\uc73c\ub85c \uae30\ub2a5\ud55c\ub2e4.",B.aEX,B.avX,null)
B.bf1=s(["\ub3d9\uc77c\ud55c \uc0ac\uc548\uc5d0 \ub300\ud574 \ud2b9\ubcc4\ubc95\uc5d0 \ubcc4\ub3c4\uc758 \uaddc\uc815\uc774 \uc788\uc73c\uba74 \uadf8 \ud2b9\ubcc4\ubc95 \uaddc\uc815\uc774 \uc77c\ubc18\ubc95\ubcf4\ub2e4 \uc6b0\uc120\ud558\uc5ec \uc801\uc6a9\ub41c\ub2e4","\ud2b9\ubcc4\ubc95\uacfc \uc77c\ubc18\ubc95\uc774 \ucda9\ub3cc\ud558\uba74 \ud56d\uc0c1 \uc77c\ubc18\ubc95\uc774 \uc6b0\uc120\ud55c\ub2e4","\ud2b9\ubcc4\ubc95 \uc6b0\uc120\uc758 \uc6d0\uce59\uc740 \uacf5\uc815\uac70\ub798\ubc95 \uccb4\uacc4\uc5d0\ub294 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4","\ud2b9\ubcc4\ubc95\uc774 \uc788\uc73c\uba74 \uc77c\ubc18\ubc95\uc740 \uadf8 \uc989\uc2dc \uc804\uccb4\uac00 \ud3d0\uc9c0\ub41c \uac83\uc73c\ub85c \ubcf8\ub2e4","\ud2b9\ubcc4\ubc95 \uc6b0\uc120\uc758 \uc6d0\uce59\uc740 \ud615\ubc95\uc5d0\ub9cc \uc801\uc6a9\ub418\uace0 \ud589\uc815\ubc95 \ubd84\uc57c\uc5d0\ub294 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.b6z=s(["\ud2b9\ubcc4\ubc95\uc5d0 \ubcc4\ub3c4\uc758 \uaddc\uc815\uc774 \uc788\uc73c\uba74 \uadf8 \ud2b9\ubcc4\ubc95 \uaddc\uc815\uc774 \uc77c\ubc18\ubc95\ubcf4\ub2e4 \uc6b0\uc120\ud558\uc5ec \uc801\uc6a9\ub41c\ub2e4"],t.s)
B.aCJ=s(["\ud2b9\ubcc4\ubc95 \uc6b0\uc120\uc758 \uc6d0\uce59"],t.s)
B.bvG=new A.a("gen_gn_system_4","economic_law","\ubaa9\uc801\xb7\ucd1d\uce59","\ubc95 \uccb4\uacc4\xb7\ub2e4\ub978 \ubc95\ub960\uacfc\uc758 \uad00\uacc4",'"\ud2b9\ubcc4\ubc95 \uc6b0\uc120\uc758 \uc6d0\uce59"\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?',B.bf1,0,'"\ud2b9\ubcc4\ubc95\uc740 \uc77c\ubc18\ubc95\uc5d0 \uc6b0\uc120\ud55c\ub2e4"\ub294 \ubc95 \uc801\uc6a9\uc758 \uc77c\ubc18\uc6d0\uce59\uc73c\ub85c, \ub3d9\uc77c\ud55c \uc0ac\ud56d\uc5d0 \ub300\ud574 \ud2b9\ubcc4\ubc95\uc5d0 \ubcc4\ub3c4\uc758 \uaddc\uc815\uc774 \uc788\ub294 \uacbd\uc6b0\uc5d0\ub294 \uadf8 \ud2b9\ubcc4\ubc95\uc774 \uc77c\ubc18\ubc95\ubcf4\ub2e4 \uc6b0\uc120\ud558\uc5ec \uc801\uc6a9\ub41c\ub2e4. \uacf5\uc815\uac70\ub798\ubc95\uacfc \uac00\ub9f9\uc0ac\uc5c5\ubc95\xb7\ud558\ub3c4\uae09\ubc95 \ub4f1\uc758 \uad00\uacc4\uc5d0\uc11c\ub3c4 \uc774 \uc6d0\ufffd\ub9ac\uc774 \uc801\uc6a9\ub418\uc5b4, \ud574\ub2f9 \ud2b9\ubcc4\ubc95\uc774 \uaddc\uc728\ud558\ub294 \uc0ac\ud56d\uc5d0\ub294 \ud2b9\ubcc4\ubc95\uc774 \uba3c\uc800 \uc801\uc6a9\ub41c\ub2e4.',B.b6z,B.aCJ,null)
B.b5t=s(["\ud53c\ud574\uc790\ub294 \uacf5\uc815\uac70\ub798\ubc95 \ubc0f \ubbfc\ubc95\uc0c1 \uc190\ud574\ubc30\uc0c1 \uad00\ub828 \uaddc\uc815 \ub4f1\uc744 \ud1b5\ud574 \uac00\ud574 \uc0ac\uc5c5\uc790\ub97c \uc0c1\ub300\ub85c \uc190\ud574\ubc30\uc0c1\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4","\uacf5\uc815\uac70\ub798\ubc95 \uc704\ubc18\uc5d0 \ub300\ud574\uc11c\ub294 \uc5b4\ub5a0\ud55c \ubbfc\uc0ac\uc801 \uad6c\uc81c\uc218\ub2e8\ub3c4 \uc874\uc7ac\ud558\uc9c0 \uc54a\ub294\ub2e4","\ubbfc\uc0ac\uc801 \uad6c\uc81c\ub294 \ubc18\ub4dc\uc2dc \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uc758 \uc0ac\uc804 \ucc98\ubd84\uc774 \uc788\uc5b4\uc57c\ub9cc \uac00\ub2a5\ud558\ub2e4","\uc190\ud574\ubc30\uc0c1\uccad\uad6c\uad8c\uc740 \uc0ac\uc5c5\uc790\ub2e8\uccb4\uc5d0\uac8c\ub9cc \uc778\uc815\ub41c\ub2e4","\uacf5\uc815\uac70\ub798\ubc95 \uc704\ubc18 \ud53c\ud574\uc790\ub294 \ud615\uc0ac\uace0\uc18c\ub9cc \uac00\ub2a5\ud558\uace0 \ubbfc\uc0ac\uc18c\uc1a1\uc740 \uc81c\uae30\ud560 \uc218 \uc5c6\ub2e4"],t.s)
B.alR=s(["\uacf5\uc815\uac70\ub798\ubc95 \ubc0f \ubbfc\ubc95\uc0c1 \uc190\ud574\ubc30\uc0c1 \uad00\ub828 \uaddc\uc815 \ub4f1\uc744 \ud1b5\ud574 \uac00\ud574 \uc0ac\uc5c5\uc790\ub97c \uc0c1\ub300\ub85c \uc190\ud574\ubc30\uc0c1\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.bif=s(["\ubbfc\uc0ac\uc801 \uc190\ud574\ubc30\uc0c1\uccad\uad6c"],t.s)
B.bOL=new A.a("gen_gn_system_5","economic_law","\ubaa9\uc801\xb7\ucd1d\uce59","\ubc95 \uccb4\uacc4\xb7\ub2e4\ub978 \ubc95\ub960\uacfc\uc758 \uad00\uacc4","\uacf5\uc815\uac70\ub798\ubc95 \uc704\ubc18\ud589\uc704\ub85c \ud53c\ud574\ub97c \uc785\uc740 \uc790\uc758 \ubbfc\uc0ac\uc801 \uad6c\uc81c\uc218\ub2e8\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.b5t,0,"\uacf5\uc815\uac70\ub798\ubc95 \uc704\ubc18\ud589\uc704\ub85c \uc190\ud574\ub97c \uc785\uc740 \uc790\ub294 \uacf5\uc815\uac70\ub798\ubc95 \ubc0f \ubbfc\ubc95\uc758 \ubd88\ubc95\ud589\uc704 \uad00\ub828 \uaddc\uc815 \ub4f1\uc5d0 \uadfc\uac70\ud558\uc5ec \uac00\ud574 \uc0ac\uc5c5\uc790\ub97c \uc0c1\ub300\ub85c \uc190\ud574\ubc30\uc0c1\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4. \uc774\ub7ec\ud55c \ubbfc\uc0ac\uc801 \uad6c\uc81c\uc218\ub2e8\uc740 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uc758 \ud589\uc815\ucc98\ubd84\uacfc\ub294 \ubcc4\uac1c\ub85c \uc778\uc815\ub418\ub294 \uac83\uc774 \uc6d0\uce59\uc774\uba70, \uc0ac\uc5c5\uc790\ub2e8\uccb4 \uc5ec\ubd80\uc640 \ubb34\uad00\ud558\uac8c \ud53c\ud574\ub97c \uc785\uc740 \uc790\ub77c\uba74 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4.",B.alR,B.bif,null)
B.aal=s(["\uad6d\uc678\uc5d0\uc11c \uc774\ub8e8\uc5b4\uc9c4 \ud589\uc704\ub77c\ub3c4 \uadf8 \ud6a8\uacfc\uac00 \uad6d\ub0b4\uc2dc\uc7a5\uc5d0 \uc601\ud5a5\uc744 \ubbf8\uce58\ub294 \uacbd\uc6b0\uc5d0\ub294 \uc774 \ubc95\uc744 \uc801\uc6a9\ud560 \uc218 \uc788\ub3c4\ub85d \ud558\ub824\ub294 \uac83\uc774\ub2e4","\uc678\uad6d\uc5d0\uc11c \ubc1c\uc0dd\ud55c \ud589\uc704\ub294 \uadf8 \uc5b4\ub5a4 \uacbd\uc6b0\uc5d0\ub3c4 \uc774 \ubc95\uc758 \uaddc\uc728 \ub300\uc0c1\uc774 \ub420 \uc218 \uc5c6\ub3c4\ub85d \ud558\ub824\ub294 \uac83\uc774\ub2e4","\uc5ed\uc678\uc801\uc6a9\uc740 \uad6d\ub0b4\uc0ac\uc5c5\uc790\uc5d0\uac8c\ub9cc \uc801\uc6a9\ub418\uace0 \uc678\uad6d\uc0ac\uc5c5\uc790\uc5d0\uac8c\ub294 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4","\uc5ed\uc678\uc801\uc6a9 \uaddc\uc815\uc740 \ud615\uc0ac\ucc98\ubc8c\ub9cc\uc744 \ubaa9\uc801\uc73c\ub85c \ub9c8\ub828\ub41c \uac83\uc774\ub2e4","\uc5ed\uc678\uc801\uc6a9\uc740 \uad6d\ub0b4\uc2dc\uc7a5\uc5d0 \ubbf8\uce58\ub294 \uc601\ud5a5\uacfc \ubb34\uad00\ud558\uac8c \ubaa8\ub4e0 \uad6d\uc678\ud589\uc704\uc5d0 \uc801\uc6a9\ub41c\ub2e4"],t.s)
B.asL=s(["\uadf8 \ud6a8\uacfc\uac00 \uad6d\ub0b4\uc2dc\uc7a5\uc5d0 \uc601\ud5a5\uc744 \ubbf8\uce58\ub294 \uacbd\uc6b0\uc5d0\ub294 \uc774 \ubc95\uc744 \uc801\uc6a9\ud560 \uc218 \uc788\ub3c4\ub85d \ud558\ub824\ub294 \uac83\uc774\ub2e4"],t.s)
B.au0=s(["\uc5ed\uc678\uc801\uc6a9\uc758 \ucde8\uc9c0"],t.s)
B.bES=new A.a("gen_gn_extra_1","economic_law","\ubaa9\uc801\xb7\ucd1d\uce59","\uc5ed\uc678\uc801\uc6a9\xb7\uad6d\uc81c\ud611\ub825","\uacf5\uc815\uac70\ub798\ubc95\uc0c1 \uc5ed\uc678\uc801\uc6a9 \uaddc\uc815\uc758 \ucde8\uc9c0\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aal,0,"\uc5ed\uc678\uc801\uc6a9 \uaddc\uc815\uc740 \uad6d\uc678\uc5d0\uc11c \uc774\ub8e8\uc5b4\uc9c4 \ud589\uc704\ub77c\ub3c4 \uadf8\ub85c \uc778\ud55c \ud6a8\uacfc\uac00 \uad6d\ub0b4\uc2dc\uc7a5\uc5d0 \uc601\ud5a5\uc744 \ubbf8\uce58\ub294 \uacbd\uc6b0\uc5d0\ub294 \uacf5\uc815\uac70\ub798\ubc95\uc744 \uc801\uc6a9\ud560 \uc218 \uc788\ub3c4\ub85d \ud568\uc73c\ub85c\uc368, \uad6d\uacbd\uc744 \ub118\uc5b4 \uc774\ub8e8\uc5b4\uc9c0\ub294 \uad6d\uc81c\uce74\ub974\ud154 \ub4f1\uc73c\ub85c\ubd80\ud130 \uad6d\ub0b4\uc2dc\uc7a5\uc758 \uacbd\uc7c1\uc9c8\uc11c\ub97c \ubcf4\ud638\ud558\ub824\ub294 \ucde8\uc9c0\ub97c \uac16\ub294\ub2e4. \ub2e4\ub9cc \ubaa8\ub4e0 \uad6d\uc678\ud589\uc704\uc5d0 \ubb34\uc81c\ud55c \uc801\uc6a9\ub418\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uad6d\ub0b4\uc2dc\uc7a5\uc5d0 \ubbf8\uce58\ub294 \uc601\ud5a5\uc744 \uc694\uac74\uc73c\ub85c \ud55c\ub2e4.",B.asL,B.au0,null)
B.bgY=s(["\ubb38\uc81c\ub41c \uad6d\uc678\ud589\uc704\ub85c \uc778\ud574 \uc9c1\uc811\uc801\uc774\uace0 \uc0c1\ub2f9\ud558\uba70 \ud569\ub9ac\uc801\uc73c\ub85c \uc608\uce21 \uac00\ub2a5\ud55c \uc601\ud5a5\uc774 \uad6d\ub0b4\uc2dc\uc7a5\uc5d0 \ubbf8\uce58\ub294\uc9c0\ub97c \uae30\uc900\uc73c\ub85c \ud310\ub2e8\ud55c\ub2e4","\uc678\uad6d\uc0ac\uc5c5\uc790\uc758 \ub9e4\ucd9c\uc561 \uaddc\ubaa8\ub9cc\uc744 \uae30\uc900\uc73c\ub85c \ud310\ub2e8\ud55c\ub2e4","\uc678\uad6d\uc0ac\uc5c5\uc790\uc758 \uad6d\uc801\ub9cc\uc744 \uae30\uc900\uc73c\ub85c \ud310\ub2e8\ud55c\ub2e4","\uc5ed\uc678\uc801\uc6a9 \uc5ec\ubd80\ub294 \uc804\uc801\uc73c\ub85c \uc678\uad6d \uc815\ubd80\uc758 \ub3d9\uc758 \uc5ec\ubd80\uc5d0 \ub2ec\ub824 \uc788\ub2e4","\uc5ed\uc678\uc801\uc6a9 \uc5ec\ubd80\ub294 \ud589\uc704\uac00 \uc774\ub8e8\uc5b4\uc9c4 \uc2dc\uac01(\ub0ae/\ubc24)\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc9c4\ub2e4"],t.s)
B.Vh=s(["\uc9c1\uc811\uc801\uc774\uace0 \uc0c1\ub2f9\ud558\uba70 \ud569\ub9ac\uc801\uc73c\ub85c \uc608\uce21 \uac00\ub2a5\ud55c \uc601\ud5a5\uc774 \uad6d\ub0b4\uc2dc\uc7a5\uc5d0 \ubbf8\uce58\ub294\uc9c0\ub97c \uae30\uc900\uc73c\ub85c \ud310\ub2e8\ud55c\ub2e4"],t.s)
B.aSG=s(["\uc5ed\uc678\uc801\uc6a9 \ud310\ub2e8\uae30\uc900"],t.s)
B.bS6=new A.a("gen_gn_extra_2","economic_law","\ubaa9\uc801\xb7\ucd1d\uce59","\uc5ed\uc678\uc801\uc6a9\xb7\uad6d\uc81c\ud611\ub825","\uc5ed\uc678\uc801\uc6a9 \uc5ec\ubd80\ub97c \ud310\ub2e8\ud558\ub294 \uae30\uc900\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.bgY,0,'\ud310\ub840\ub294 \uc5ed\uc678\uc801\uc6a9\uc758 \uc694\uac74\uc774 \ub418\ub294 "\uad6d\ub0b4\uc2dc\uc7a5\uc5d0 \ub300\ud55c \uc601\ud5a5"\uc744 \ubb38\uc81c\ub41c \uad6d\uc678\ud589\uc704\ub85c \uc778\ud574 \uc9c1\uc811\uc801\uc774\uace0 \uc0c1\ub2f9\ud558\uba70 \ud569\ub9ac\uc801\uc73c\ub85c \uc608\uce21 \uac00\ub2a5\ud55c \uc601\ud5a5\uc774 \uad6d\ub0b4\uc2dc\uc7a5\uc5d0 \ubbf8\uce58\ub294 \uacbd\uc6b0\ub85c \uc81c\ud55c \ud574\uc11d\ud55c\ub2e4. \uc774\ub294 \ubb34\ubd84\ubcc4\ud55c \uc5ed\uc678\uc801\uc6a9\uc744 \ubc29\uc9c0\ud558\uba74\uc11c\ub3c4 \uc2e4\uc9c8\uc801\uc73c\ub85c \uad6d\ub0b4 \uacbd\uc7c1\uc9c8\uc11c\uc5d0 \uc601\ud5a5\uc744 \ubbf8\uce58\ub294 \ud589\uc704\ub294 \uaddc\uc728\ud560 \uc218 \uc788\ub3c4\ub85d \ud558\ub294 \uade0\ud615\uc810 \uc5ed\ud560\uc744 \ud55c\ub2e4.',B.Vh,B.aSG,null)
B.a2d=s(["\uc815\ubd80\ub294 \ub300\ud55c\ubbfc\uad6d\uc758 \ubc95\ub960 \ubc0f \uc774\uc775\uc5d0 \ubc18\ud558\uc9c0 \uc54a\ub294 \ubc94\uc704\uc5d0\uc11c \uc678\uad6d\uc815\ubd80\uc640 \uc774 \ubc95\uc758 \uc9d1\ud589\uc744 \uc704\ud55c \ud611\uc815\uc744 \uccb4\uacb0\ud560 \uc218 \uc788\ub2e4","\uad6d\uc81c\ud611\ub825 \uaddc\uc815\uc740 \uc774 \ubc95\uc5d0 \uc874\uc7ac\ud558\uc9c0 \uc54a\ub294\ub2e4","\uc678\uad6d\uc815\ubd80\uc640\uc758 \ud611\uc815\uc740 \ubc18\ub4dc\uc2dc \uad6d\ud68c\uc758 \uac1c\ubcc4 \uc0ac\uac74\ubcc4 \ub3d9\uc758\ub97c \uac70\uccd0\uc57c\ub9cc \uccb4\uacb0\ud560 \uc218 \uc788\ub2e4","\uad6d\uc81c\ud611\ub825\uc740 \uc624\uc9c1 \ubbfc\uac04\uae30\uc5c5 \uac04\uc758 \uacc4\uc57d\uc744 \ud1b5\ud574\uc11c\ub9cc \uc774\ub8e8\uc5b4\uc9c4\ub2e4","\uc678\uad6d\uc815\ubd80\uc640\uc758 \ud611\uc815 \uccb4\uacb0\uc740 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uac00 \uc544\ub2cc \ubc95\uc6d0\uc758 \uad8c\ud55c\uc774\ub2e4"],t.s)
B.aly=s(["\uc678\uad6d\uc815\ubd80\uc640 \uc774 \ubc95\uc758 \uc9d1\ud589\uc744 \uc704\ud55c \ud611\uc815\uc744 \uccb4\uacb0\ud560 \uc218 \uc788\ub2e4"],t.s)
B.aFG=s(["\uad6d\uc81c\ud611\ub825 \uadfc\uac70"],t.s)
B.bJp=new A.a("gen_gn_extra_3","economic_law","\ubaa9\uc801\xb7\ucd1d\uce59","\uc5ed\uc678\uc801\uc6a9\xb7\uad6d\uc81c\ud611\ub825","\uacf5\uc815\uac70\ub798\ubc95 \uc9d1\ud589\uc744 \uc704\ud55c \uad6d\uc81c\ud611\ub825\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.a2d,0,"\uacf5\uc815\uac70\ub798\ubc95\uc740 \uc815\ubd80\uac00 \ub300\ud55c\ubbfc\uad6d\uc758 \ubc95\ub960 \ubc0f \uc774\uc775\uc5d0 \ubc18\ud558\uc9c0 \uc544\ub2c8\ud558\ub294 \ubc94\uc704\uc5d0\uc11c \uc678\uad6d\uc815\ubd80\uc640 \uc774 \ubc95\uc758 \uc9d1\ud589\uc744 \uc704\ud55c \ud611\uc815\uc744 \uccb4\uacb0\ud560 \uc218 \uc788\ub2e4\ub294 \uadfc\uac70\ub97c \ub450\uc5b4, \uad6d\uacbd\uc744 \ub118\ub294 \uacbd\uc7c1\uc81c\ud55c\ud589\uc704\uc5d0 \ub300\uc751\ud558\uae30 \uc704\ud55c \uad6d\uc81c\ud611\ub825\uc758 \uadfc\uac70\ub97c \ub9c8\ub828\ud558\uace0 \uc788\ub2e4. \uc774\ub294 \uac1c\ubcc4 \uc0ac\uac74\ub9c8\ub2e4 \uad6d\ud68c \ub3d9\uc758\ub97c \uc694\ud558\ub294 \uc808\ucc28\uac00 \uc544\ub2c8\ub77c \uc815\ubd80 \uac04 \ud611\ub825\uccb4\uacc4 \uad6c\ucd95\uc744 \uc704\ud55c \uc77c\ubc18\uc801 \uadfc\uac70 \uaddc\uc815\uc774\ub2e4.",B.aly,B.aFG,null)
B.aAS=s([u.vy,"\uad6d\ub0b4\uc5d0\uc11c\ub9cc \uc601\uc5c5\ud558\ub294 \uc18c\uaddc\ubaa8 \uac1c\uc778\uc0ac\uc5c5\uc790 \uac04\uc758 \uc21c\uc218\ud55c \uad6d\ub0b4 \uac70\ub798\ubd84\uc7c1","\uad6d\ub0b4 \uc18c\ube44\uc790 \uac1c\uc778 \uac04\uc758 \uc911\uace0\ubb3c\ud488 \uac70\ub798","\uc21c\uc218\ud558\uac8c \uad6d\ub0b4 \uacf5\uacf5\uae30\uad00 \ub0b4\ubd80\uc758 \uc778\uc0ac \ubb38\uc81c","\uad6d\ub0b4 \ud559\uad50\uc758 \uad50\uc721\uacfc\uc815 \ud3b8\uc131 \ubb38\uc81c"],t.s)
