B.aKR=s([u.mK,"\ub450 \uc720\ud615\uc740 \uad6c\ubcc4\ud560 \uc2e4\uc775\uc774 \uc804\ud600 \uc5c6\ub2e4","\uad6c\ubcc4 \uae30\uc900\uc740 \uc624\uc9c1 \ud589\uc704\uac00 \ubc1c\uc0dd\ud55c \uc9c0\uc5ed\uc5d0 \ub2ec\ub824 \uc788\ub2e4","\uad6c\ubcc4 \uae30\uc900\uc740 \uc0ac\uc5c5\uc790\ub2e8\uccb4\uc758 \uc124\ub9bd\uc5f0\ub3c4\uc774\ub2e4","\uad6c\ubcc4 \uae30\uc900\uc740 \uc0ac\uc5c5\uc790\ub2e8\uccb4\uc758 \ud68c\uc6d0 \uc218\ub9cc\uc73c\ub85c \uacb0\uc815\ub41c\ub2e4"],t.s)
