B.buM=new A.a("gen_ta_distinct_1","economic_law","\uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704","\uae08\uc9c0\ud589\uc704\uc640 \uac1c\ubcc4\uc0ac\uc5c5\uc790 \ud589\uc704\uc758 \uad6c\ubcc4","\uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704\uc640 \uac1c\ubcc4 \uc0ac\uc5c5\uc790\uc758 \ubd88\uacf5\uc815\uac70\ub798\ud589\uc704\ub97c \uad6c\ubcc4\ud558\ub294 \uae30\uc900\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aKR,0,"\uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704\ub294 \uc0ac\uc5c5\uc790\ub2e8\uccb4 \uc790\uccb4\uac00 \ud589\uc704\uc8fc\uccb4\uac00 \ub418\uc5b4 \uad6c\uc131\uc0ac\uc5c5\uc790\uc758 \uc0ac\uc5c5\ub0b4\uc6a9\uc744 \uc81c\ud55c\ud558\uac70\ub098 \uacbd\uc7c1\uc744 \uc81c\ud55c\ud558\ub294 \uacbd\uc6b0\uc5d0 \ubb38\uc81c\ub418\ub294 \ubc18\uba74, \uac1c\ubcc4 \uc0ac\uc5c5\uc790\uc758 \ubd88\uacf5\uc815\uac70\ub798\ud589\uc704\ub294 \uac1c\ubcc4 \uc0ac\uc5c5\uc790 \uc790\uc2e0\uc774 \uac70\ub798\uc0c1\ub300\ubc29\uc5d0 \ub300\ud574 \ud589\ud558\ub294 \ud589\uc704\ub97c \uaddc\uc728\ud55c\ub2e4. \ud589\uc704 \uc8fc\uccb4\uac00 \ub204\uad6c\uc778\uc9c0\uac00 \ub450 \uc720\ud615\uc744 \uad6c\ubcc4\ud558\ub294 \uc77c\ucc28\uc801 \uae30\uc900\uc774 \ub41c\ub2e4.",B.SF,B.bc3,null)
B.anG=s([u.EI,"\uc774\ub294 \uc0ac\uc5c5\uc790\ub2e8\uccb4\uac00 \uc8fc\uccb4\uac00 \ub418\uc5b4\uc57c\ub9cc \uc131\ub9bd\ud558\ub294 \ud589\uc704\uc774\ub2e4","\uc774 \uacbd\uc6b0 \uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704 \uaddc\uc815\uc774 \uc6b0\uc120 \uc801\uc6a9\ub41c\ub2e4","\uc774\ub7ec\ud55c \ud589\uc704\ub294 \uc5b4\ub5a0\ud55c \ubc95\ub960\ub85c\ub3c4 \uaddc\uc728\ub418\uc9c0 \uc54a\ub294\ub2e4","\uc774 \ud589\uc704\ub294 \ubc18\ub4dc\uc2dc \ud615\uc0ac\ucc98\ubc8c\ub9cc \uac00\ub2a5\ud558\ub2e4"],t.s)
