B.bOd=new A.a("gen_rpm_type_6","economic_law","\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704","\ucd5c\uace0\xb7\ucd5c\uc800 \uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\uc758 \uad6c\ubcc4","\uac00\ub9f9\ubcf8\ubd80\uac00 \uac00\ub9f9\uc810\uc5d0 \ub300\ud574 \ucd5c\uc800\ud310\ub9e4\uac00\uaca9\uc744 \uc9c0\uc815\ud558\uace0 \uc774\ub97c \ub530\ub974\uc9c0 \uc54a\uc73c\uba74 \uacf5\uae09\uc744 \uc911\ub2e8\ud558\uaca0\ub2e4\uace0 \ud1b5\ubcf4\ud55c \uacbd\uc6b0\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.aSj,0,"\uac00\ub9f9\ubcf8\ubd80\uac00 \uac00\ub9f9\uc810\uc5d0 \ub300\ud574 \ucd5c\uc800\ud310\ub9e4\uac00\uaca9\uc744 \uc9c0\uc815\ud558\uace0 \uc774\ub97c \ub530\ub974\uc9c0 \uc54a\uc744 \uacbd\uc6b0 \uacf5\uae09\uc744 \uc911\ub2e8\ud558\uaca0\ub2e4\uace0 \ud1b5\ubcf4\ud558\ub294 \ud589\uc704\ub294 \uad6c\uc18d\ub825\uc744 \uac16\ucd98 \ucd5c\uc800\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\uc5d0 \ud574\ub2f9\ud560 \uc18c\uc9c0\uac00 \uc788\uc73c\uba70, \uc815\ub2f9\ud55c \uc774\uc720\uac00 \uc778\uc815\ub418\uc9c0 \uc54a\ub294 \ud55c \uc704\ubc95\ud55c \ud589\uc704\ub85c \ud3c9\uac00\ub420 \uc218 \uc788\ub2e4.",B.a4P,B.a6B,null)
B.beU=s(["\ud574\ub2f9 \ud589\uc704\uc5d0 \uc815\ub2f9\ud55c \uc774\uc720\uac00 \uc788\ub2e4\uace0 \uc778\uc815\ub418\ub294 \uacbd\uc6b0","\uc0ac\uc5c5\uc790\uac00 \uc6d0\ud55c\ub2e4\uace0 \ub9d0\ud558\uae30\ub9cc \ud558\uba74 \ud56d\uc0c1 \ud5c8\uc6a9\ub41c\ub2e4","\uac70\ub798\uc0c1\ub300\ubc29\uc774 \ub300\uae30\uc5c5\uc778 \uacbd\uc6b0\uc5d0\ub9cc \ud5c8\uc6a9\ub41c\ub2e4","\uac00\uaca9\uc774 \ub9e4\uc6b0 \uc800\ub834\ud55c \uacbd\uc6b0\uc5d0\ub9cc \ud5c8\uc6a9\ub41c\ub2e4","\uc628\ub77c\uc778 \uac70\ub798\uc778 \uacbd\uc6b0\uc5d0\ub9cc \ud56d\uc0c1 \ud5c8\uc6a9\ub41c\ub2e4"],t.s)
B.Wn=s(["\ud574\ub2f9 \ud589\uc704\uc5d0 \uc815\ub2f9\ud55c \uc774\uc720\uac00 \uc788\ub2e4\uace0 \uc778\uc815\ub418\ub294 \uacbd\uc6b0"],t.s)
B.agl=s(["\uc815\ub2f9\ud55c \uc774\uc720\uc5d0 \uc758\ud55c \uc608\uc678"],t.s)
B.bxF=new A.a("gen_rpm_exception_1","economic_law","\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704","\uc815\ub2f9\ud55c \uc774\uc720\xb7\uc608\uc678","\ucd5c\uc800\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\uac00 \uc608\uc678\uc801\uc73c\ub85c \ud5c8\uc6a9\ub420 \uc218 \uc788\ub294 \uacbd\uc6b0\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.beU,0,"\ucd5c\uc800\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \uae08\uc9c0\ub418\uc9c0\ub9cc, \ud574\ub2f9 \ud589\uc704\uc5d0 \uc815\ub2f9\ud55c \uc774\uc720\uac00 \uc788\ub2e4\uace0 \uc778\uc815\ub418\ub294 \uacbd\uc6b0\uc5d0\ub294 \uc608\uc678\uc801\uc73c\ub85c \ud5c8\uc6a9\ub420 \uc218 \uc788\ub2e4\ub294 \uac83\uc774 \ubc95\ub9ac\ub85c \uc778\uc815\ub41c\ub2e4. \uc815\ub2f9\ud55c \uc774\uc720\ub294 \uac1c\ubcc4 \uc0ac\uc548\uc758 \uad6c\uccb4\uc801 \uc0ac\uc815\uc744 \uc885\ud569\ud558\uc5ec \ud310\ub2e8\ub41c\ub2e4.",B.Wn,B.agl,null)
B.al3=s([u.tu,"\uc800\uc791\ubb3c\uc740 \uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704 \uaddc\uc81c\uc640 \uc804\ud600 \ubb34\uad00\ud558\uae30 \ub54c\ubb38\uc774\ub2e4","\uc800\uc791\ubb3c\uc740 \ud56d\uc0c1 \uac00\uaca9\uc744 \ubb34\ub8cc\ub85c \ud574\uc57c \ud558\uae30 \ub54c\ubb38\uc774\ub2e4","\uc800\uc791\uad8c\uc790\ub97c \ucc98\ubc8c\ud558\uae30 \uc704\ud55c \uaddc\uc815\uc774\ub2e4","\uc800\uc791\ubb3c \uc720\ud1b5\uc5c5\uc790\ub97c \ud56d\uc0c1 \ubd88\ub9ac\ud558\uac8c \ud558\uae30 \uc704\ud55c \uaddc\uc815\uc774\ub2e4"],t.s)
