B.Y_=s(["\uc800\uc791\ubb3c \uc608\uc678 \uaddc\uc815\uc758 \ucde8\uc9c0"],t.s)
B.bJT=new A.a("gen_rpm_exception_2","economic_law","\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704","\uc815\ub2f9\ud55c \uc774\uc720\xb7\uc608\uc678","\uc800\uc791\uad8c\ubc95\uc0c1 \uc800\uc791\ubb3c\uc5d0 \ub300\ud55c \uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704 \uc608\uc678 \uaddc\uc815\uc758 \ucde8\uc9c0\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.al3,0,"\u300c\uc800\uc791\uad8c\ubc95\u300d\uc0c1 \uc800\uc791\ubb3c(\uc608: \ucd9c\ud310\ubb3c) \uc911 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uac00 \uace0\uc2dc\ud558\ub294 \uac83\uc5d0 \ub300\ud574 \uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\ub97c \uc608\uc678\uc801\uc73c\ub85c \ud5c8\uc6a9\ud558\ub294 \uac83\uc740, \ucd9c\ud310\ubb3c\uacfc \uac19\uc740 \ubb38\ud654\uc0c1\ud488\uc758 \uc720\ud1b5 \ud2b9\uc131\uc774\ub098 \ub2e4\uc591\uc131 \ubcf4\ud638 \ub4f1 \uc815\ucc45\uc801 \uace0\ub824\ub97c \ubc18\uc601\ud55c \ud2b9\ubcc4 \uc608\uc678 \uaddc\uc815\uc73c\ub85c \uc774\ud574\ub41c\ub2e4.",B.abQ,B.Y_,null)
B.aq8=s([u.v5,"\uc624\uc9c1 \uc0ac\uc5c5\uc790\uc758 \ub9e4\ucd9c \uaddc\ubaa8\ub9cc \uace0\ub824\ud55c\ub2e4","\uc624\uc9c1 \uc0ac\uc5c5\uc790 \ub300\ud45c\uc758 \uac1c\uc778\uc801 \uc758\uacac\ub9cc \uace0\ub824\ud55c\ub2e4","\uc624\uc9c1 \uac70\ub798\uc0c1\ub300\ubc29\uc758 \uad6d\uc801\ub9cc \uace0\ub824\ud55c\ub2e4","\uc815\ub2f9\ud55c \uc774\uc720 \ud310\ub2e8\uc5d0\ub294 \uc5b4\ub5a0\ud55c \uae30\uc900\ub3c4 \uc874\uc7ac\ud558\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.auw=s([u.v5],t.s)
B.aI7=s(["\uc815\ub2f9\ud55c \uc774\uc720 \ud310\ub2e8 \uc694\uc18c"],t.s)
B.bCa=new A.a("gen_rpm_exception_3","economic_law","\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704","\uc815\ub2f9\ud55c \uc774\uc720\xb7\uc608\uc678",'\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\uc758 "\uc815\ub2f9\ud55c \uc774\uc720" \uc720\ubb34\ub97c \ud310\ub2e8\ud560 \ub54c \uace0\ub824\ub418\ub294 \uc694\uc18c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?',B.aq8,0,'\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\uc758 "\uc815\ub2f9\ud55c \uc774\uc720" \uc720\ubb34\ub97c \ud310\ub2e8\ud560 \ub54c\uc5d0\ub294 \uadf8 \ud589\uc704\ub85c \uc778\ud55c \uacbd\uc7c1\uc81c\ud55c \ud6a8\uacfc\uc640 \ud568\uaed8, \ube0c\ub79c\ub4dc \ub0b4 \uc11c\ube44\uc2a4 \uacbd\uc7c1 \ucd09\uc9c4, \ubb34\uc784\uc2b9\ucc28 \ubc29\uc9c0, \ud6a8\uc728\uc131 \uc99d\ub300\ub098 \uc18c\ube44\uc790 \ud6c4\uc0dd \uc99d\ub300 \ud6a8\uacfc \ub4f1\uc744 \uc885\ud569\uc801\uc73c\ub85c \ube44\uad50\ud615\ub7c9\ud558\uc5ec \ud310\ub2e8\ud558\ub294 \uac83\uc774 \uc77c\ubc18\uc801\uc774\ub2e4.',B.auw,B.aI7,null)
B.ai7=s([u.mI,"\uc815\ub2f9\ud55c \uc774\uc720\uc758 \uc99d\uba85\ucc45\uc784\uc740 \ud56d\uc0c1 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uac00 \ubd80\ub2f4\ud55c\ub2e4","\uc815\ub2f9\ud55c \uc774\uc720\ub294 \uc99d\uba85\ud560 \ud544\uc694\uac00 \uc804\ud600 \uc5c6\ub294 \uac1c\ub150\uc774\ub2e4","\uc815\ub2f9\ud55c \uc774\uc720\uc758 \uc99d\uba85\ucc45\uc784\uc740 \uc18c\ube44\uc790\ub2e8\uccb4\uac00 \ubd80\ub2f4\ud55c\ub2e4","\uc815\ub2f9\ud55c \uc774\uc720\ub294 \ubc95\uc6d0\uc774 \uc9c1\uad8c\uc73c\ub85c\ub9cc \ud310\ub2e8\ud55c\ub2e4"],t.s)
