B.amL=s(["\uc815\ub2f9\ud55c \uc774\uc720\uc758 \uc99d\uba85\ucc45\uc784"],t.s)
B.bO9=new A.a("gen_rpm_exception_4","economic_law","\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704","\uc815\ub2f9\ud55c \uc774\uc720\xb7\uc608\uc678","\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\uc5d0 \uad00\ud55c \uc815\ub2f9\ud55c \uc774\uc720\uc758 \uc99d\uba85\ucc45\uc784\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.ai7,0,"\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\uc5d0 \uc815\ub2f9\ud55c \uc774\uc720\uac00 \uc788\ub2e4\ub294 \uc0ac\uc815\uc740 \uadf8 \ud589\uc704\uc758 \uc704\ubc95\uc131\uc744 \uc870\uac01\ud558\uae30 \uc704\ud55c \ud56d\ubcc0\uc0ac\uc720\uc758 \uc131\uaca9\uc744 \uac00\uc9c0\ubbc0\ub85c, \uc774\ub97c \uc8fc\uc7a5\ud558\ub294 \uc0ac\uc5c5\uc790 \uce21\uc774 \uc99d\uba85\ud558\ub294 \uac83\uc774 \uc77c\ubc18\uc801\uc778 \uc99d\uba85\ucc45\uc784 \ubc30\ubd84 \uc6d0\uce59\uc5d0 \ubd80\ud569\ud55c\ub2e4.",B.adF,B.amL,null)
B.aBl=s([u.wP,"\ubb34\uc784\uc2b9\ucc28 \ubb38\uc81c\ub294 \uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\uc640 \uc804\ud600 \ubb34\uad00\ud558\ub2e4","\ubb34\uc784\uc2b9\ucc28 \ubc29\uc9c0\ub294 \uc624\uc9c1 \ucd5c\uace0\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\uc5d0\uc11c\ub9cc \ub17c\uc758\ub41c\ub2e4","\ubb34\uc784\uc2b9\ucc28 \ubc29\uc9c0\ub294 \uc5b8\uc81c\ub098 \uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\ub97c \uc815\ub2f9\ud654\ud558\ub294 \uc808\ub300\uc801 \uc0ac\uc720\uc774\ub2e4","\ubb34\uc784\uc2b9\ucc28\ub294 \uc18c\ube44\uc790\uc5d0\uac8c\ub9cc \ucc45\uc784\uc774 \uc788\ub294 \ubb38\uc81c\uc774\ub2e4"],t.s)
B.amd=s([u.wP],t.s)
B.YJ=s(["\ubb34\uc784\uc2b9\ucc28 \ubc29\uc9c0\uc640 \uc815\ub2f9\ud654 \uc0ac\uc720"],t.s)
B.bpI=new A.a("gen_rpm_exception_5","economic_law","\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704","\uc815\ub2f9\ud55c \uc774\uc720\xb7\uc608\uc678","\ube0c\ub79c\ub4dc \ub0b4 \uc11c\ube44\uc2a4 \uacbd\uc7c1(\ubb34\uc784\uc2b9\ucc28 \ubc29\uc9c0)\uc774 \uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\uc758 \uc815\ub2f9\ud654 \uc0ac\uc720\ub85c \ub17c\uc758\ub418\ub294 \ub9e5\ub77d\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.aBl,0,"\uc77c\ubd80 \uc720\ud1b5\uc5c5\uc790\uac00 \ud310\ub9e4 \uc804 \uc0c1\ub2f4\xb7\uc804\uc2dc \ub4f1 \uc11c\ube44\uc2a4\uc5d0 \ud22c\uc790\ud558\uc9c0 \uc54a\uace0 \uac00\uaca9\ub9cc \ub0ae\ucdb0 \ud310\ub9e4\ud568\uc73c\ub85c\uc368, \uc11c\ube44\uc2a4\ub97c \uc81c\uacf5\ud558\ub294 \ub2e4\ub978 \uc720\ud1b5\uc5c5\uc790\uc758 \ub178\ub825\uc5d0 \ubb34\uc784\uc2b9\ucc28\ud558\ub294 \ubb38\uc81c\ub97c \ubc29\uc9c0\ud558\uae30 \uc704\ud55c \ubaa9\uc801\uc774 \ucd5c\uc800\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\uc758 \uc815\ub2f9\ud654 \uc0ac\uc720\ub85c \ub17c\uc758\ub418\ub294 \ub300\ud45c\uc801\uc778 \ub9e5\ub77d\uc774\ub2e4. \ub2e4\ub9cc \uc774\uac83\uc774 \ud56d\uc0c1 \uc808\ub300\uc801\uc73c\ub85c \uc815\ub2f9\ud654\ub418\ub294 \uac83\uc740 \uc544\ub2c8\uace0 \uc885\ud569\uc801 \ud615\ub7c9\uc758 \ud55c \uc694\uc18c\ub85c \uace0\ub824\ub41c\ub2e4.",B.amd,B.YJ,null)
B.ay8=s([u.DJ,"\uc9c0\uc815 \uc808\ucc28 \uc5c6\uc774 \uc800\uc791\uad8c\uc790\uac00 \uc784\uc758\ub85c \uc815\ud558\uba74 \uadf8\ub300\ub85c \uc778\uc815\ub41c\ub2e4","\uc9c0\uc815 \uc808\ucc28\ub294 \ubc95\uc6d0\uc758 \ud310\uacb0\ub85c\ub9cc \uc774\ub8e8\uc5b4\uc9c4\ub2e4","\uc9c0\uc815 \uc808\ucc28\uc5d0\ub294 \uc5b4\ub5a0\ud55c \ud589\uc815\uae30\uad00\ub3c4 \uad00\uc5ec\ud558\uc9c0 \uc54a\ub294\ub2e4","\uc9c0\uc815 \uc808\ucc28\ub294 \uad6d\ud68c\uc758 \ubc95\ub960 \uac1c\uc815\uc73c\ub85c\ub9cc \uac00\ub2a5\ud558\ub2e4"],t.s)
