B.bNg=new A.a("gen_rpm_extra_2","economic_law","\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704","\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704 \uc885\ud569 \uc0ac\ub840","\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\uac00 \uc608\uc678\uc801\uc73c\ub85c \ud5c8\uc6a9\ub420 \uc218 \uc788\ub294 \uacbd\uc6b0\ub85c \uc633\uc740 \uac83\uc740?",B.aU8,0,"\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \uae08\uc9c0\ub418\uc9c0\ub9cc, \uc800\uc791\uad8c\ubc95\uc5d0 \ub530\ub978 \uc800\uc791\ubb3c \ub4f1 \ubc95\ub839\uc5d0\uc11c \ud2b9\ubcc4\ud788 \uc608\uc678\ub97c \uc778\uc815\ud558\ub294 \uc77c\ubd80 \ud488\ubaa9\uc5d0 \ub300\ud574\uc11c\ub294 \uc608\uc678\uc801\uc73c\ub85c \ud5c8\uc6a9\ub420 \uc218 \uc788\ub2e4.",B.aQv,B.aZa,null)
B.a5I=s(["\ucd5c\uc800\uac00\uaca9\uc720\uc9c0\ud589\uc704\ubcf4\ub2e4 \uc0c1\ub300\uc801\uc73c\ub85c \uc18c\ube44\uc790\uc5d0\uac8c \uc720\ub9ac\ud558\uac8c \uc791\uc6a9\ud560 \uac00\ub2a5\uc131\uc774 \uc788\uc5b4 \uc704\ubc95\uc131 \ud310\ub2e8\uc774 \ub2e4\ub974\uac8c \ucde8\uae09\ub41c\ub2e4","\ucd5c\uace0\uac00\uaca9\uc720\uc9c0\ud589\uc704\uc640 \ucd5c\uc800\uac00\uaca9\uc720\uc9c0\ud589\uc704\ub294 \uc704\ubc95\uc131 \ud310\ub2e8\uc774 \uc644\uc804\ud788 \ub3d9\uc77c\ud558\ub2e4","\ucd5c\uace0\uac00\uaca9\uc720\uc9c0\ud589\uc704\ub294 \ud56d\uc0c1 \ubb34\uc870\uac74 \uc801\ubc95\ud558\ub2e4","\ucd5c\uace0\uac00\uaca9\uc720\uc9c0\ud589\uc704\ub294 \uc18c\ube44\uc790\uc5d0\uac8c \ud56d\uc0c1 \ubd88\ub9ac\ud558\uac8c\ub9cc \uc791\uc6a9\ud55c\ub2e4"],t.s)
B.arK=s(["\uc720\ud1b5\uc5c5\uc790\uac00 \uac00\uaca9\uc744 \uc9c0\ub098\uce58\uac8c \ub192\uac8c \ub9e4\uae30\ub294 \uac83\uc744 \ub9c9\uc544 \uc624\ud788\ub824 \uc18c\ube44\uc790\uac00\uaca9 \uc778\ud558 \ud6a8\uacfc\ub97c \ub0bc \uac00\ub2a5\uc131\uc774 \uc788\uc5b4 \uc704\ubc95\uc131 \ud310\ub2e8\uc774 \ub2e4\ub974\uac8c \ucde8\uae09"],t.s)
B.a5Q=s(["\ucd5c\uace0\uac00\uaca9\uc720\uc9c0\ud589\uc704\uc640 \ucd5c\uc800\uac00\uaca9\uc720\uc9c0\ud589\uc704\uc758 \uad6c\ubcc4"],t.s)
B.bwY=new A.a("gen_rpm_extra_3","economic_law","\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704","\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704 \uc885\ud569 \uc0ac\ub840","\ucd5c\uace0\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704(\uac00\uaca9\uc0c1\ud55c \uc9c0\uc815)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.a5I,0,"\ucd5c\uace0\uac00\uaca9\uc720\uc9c0\ud589\uc704(\uac00\uaca9\uc0c1\ud55c \uc9c0\uc815)\ub294 \uc720\ud1b5\uc5c5\uc790\uac00 \uac00\uaca9\uc744 \uc9c0\ub098\uce58\uac8c \ub192\uac8c \ub9e4\uae30\ub294 \uac83\uc744 \ub9c9\uc544 \uc624\ud788\ub824 \uc18c\ube44\uc790\uac00\uaca9 \uc778\ud558 \ud6a8\uacfc\ub97c \ub0bc \uac00\ub2a5\uc131\uc774 \uc788\uc5b4, \uc6d0\uce59\uc801\uc73c\ub85c \uc704\ubc95\ud55c \ucd5c\uc800\uac00\uaca9\uc720\uc9c0\ud589\uc704\uc640\ub294 \uc704\ubc95\uc131 \ud310\ub2e8\uc774 \ub2e4\ub974\uac8c \ucde8\uae09\ub418\ub294 \uacbd\ud5a5\uc774 \uc788\ub2e4.",B.arK,B.a5Q,null)
B.aQO=s(["\uac15\uc81c\uc131 \uc5c6\uc774 \ucc38\uace0\uc6a9\uc73c\ub85c \uad8c\uc7a5\ud558\ub294 \uac83\uc5d0 \uadf8\uce5c\ub2e4\uba74 \uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\uc5d0 \ud574\ub2f9\ud558\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4","\uad8c\uc7a5\uac00\uaca9 \uc81c\uc2dc\ub294 \uadf8 \uc790\uccb4\ub85c \ud56d\uc0c1 \uc704\ubc95\ud55c \uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\uc5d0 \ud574\ub2f9\ud55c\ub2e4","\uad8c\uc7a5\uac00\uaca9\uc740 \ubc18\ub4dc\uc2dc \ubc95\uc73c\ub85c \uae08\uc9c0\ub418\uc5b4 \uc788\ub2e4","\uad8c\uc7a5\uac00\uaca9\uc744 \uc81c\uc2dc\ud558\uba74 \uc790\ub3d9\uc73c\ub85c \ud615\uc0ac\ucc98\ubc8c \ub300\uc0c1\uc774 \ub41c\ub2e4"],t.s)
B.ZT=s(["\uadf8 \uc900\uc218\ub97c \uac15\uc81c\ud558\ub294 \uc2e4\uc9c8\uc801\uc778 \uad6c\uc18d\ub825\uc774\ub098 \uc81c\uc7ac \uc218\ub2e8\uc774 \uc218\ubc18\ub418\uc9c0 \uc54a\ub294\ub2e4\uba74, \uac00\uaca9 \uc900\uc218\uc758 \uac15\uc81c\uc5d0 \ud574\ub2f9\ud558\uc9c0 \uc54a\uc544 \uc704\ubc95\ud558\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4"],t.s)
B.axv=s(["\ub2e8\uc21c \uad8c\uc7a5\uac00\uaca9 \uc81c\uc2dc\uc640 \uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\uc758 \uad6c\ubcc4"],t.s)
B.bJq=new A.a("gen_rpm_extra_4","economic_law","\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704","\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704 \uc885\ud569 \uc0ac\ub840","\uc81c\uc870\uc5c5\uccb4\uac00 \uc720\ud1b5\uc5c5\uc790\uc5d0\uac8c \uad8c\uc7a5\uc18c\ube44\uc790\uac00\uaca9(\uad8c\uc7a5\uac00\uaca9)\uc744 \ub2e8\uc21c\ud788 \uc81c\uc2dc\ud558\ub294 \ud589\uc704\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.aQO,0,'\ub2e8\uc21c\ud788 \ucc38\uace0\uc6a9\uc73c\ub85c \uad8c\uc7a5\uc18c\ube44\uc790\uac00\uaca9\uc744 \uc81c\uc2dc\ud558\ub294 \ub370 \uadf8\uce58\uace0 \uadf8 \uc900\uc218\ub97c \uac15\uc81c\ud558\ub294 \uc2e4\uc9c8\uc801\uc778 \uad6c\uc18d\ub825\uc774\ub098 \uc81c\uc7ac \uc218\ub2e8\uc774 \uc218\ubc18\ub418\uc9c0 \uc54a\ub294\ub2e4\uba74, \uc774\ub294 \uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\uc758 \ud575\uc2ec \uc694\uac74\uc778 "\uac00\uaca9 \uc900\uc218\uc758 \uac15\uc81c"\uc5d0 \ud574\ub2f9\ud558\uc9c0 \uc54a\uc544 \uc704\ubc95\ud558\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4.',B.ZT,B.axv,null)
B.asI=s(["\uac00\uaca9\uc744 \uc900\uc218\ud558\uc9c0 \uc54a\uc744 \uacbd\uc6b0 \uacf5\uae09 \uc911\ub2e8, \uacc4\uc57d \ud574\uc9c0 \ub4f1 \uc2e4\uc9c8\uc801\uc778 \ubd88\uc774\uc775\uc774 \uc608\uc815\ub418\uc5b4 \uc788\uc5b4\uc57c \ud55c\ub2e4","\ub2e8\uc21c\ud788 \uac00\uaca9\uc5d0 \ub300\ud55c \uc815\ubcf4\ub97c \uc81c\uacf5\ud558\uae30\ub9cc \ud558\uba74 \ucda9\ubd84\ud558\ub2e4","\uc720\ud1b5\uc5c5\uc790\uac00 \uc790\uc720\uc758\uc0ac\ub85c \uac00\uaca9\uc744 \uacb0\uc815\ud560 \uc218 \uc788\ub294 \uacbd\uc6b0\uc5d0\ub3c4 \uad6c\uc18d\uc870\uac74\uc774 \uc778\uc815\ub41c\ub2e4","\uad6c\uc18d\uc870\uac74\uc740 \ubc18\ub4dc\uc2dc \uc11c\uba74\uacc4\uc57d\uc73c\ub85c\ub9cc \uc778\uc815\ub420 \uc218 \uc788\ub2e4"],t.s)
B.aGR=s(["\uac00\uaca9\uc744 \uc900\uc218\ud558\uc9c0 \uc54a\uc744 \uacbd\uc6b0 \uacf5\uae09 \uc911\ub2e8, \uacc4\uc57d \ud574\uc9c0 \ub4f1 \uc2e4\uc9c8\uc801\uc778 \ubd88\uc774\uc775\uc774 \uc608\uc815\ub418\uc5b4 \uc788\uc5b4\uc57c \uad6c\uc18d\uc870\uac74\uc774 \uc778\uc815\ub41c\ub2e4"],t.s)
B.a_I=s(["\uad6c\uc18d\uc870\uac74\uc758 \uc778\uc815 \uc694\uc18c"],t.s)
B.br4=new A.a("gen_rpm_extra_5","economic_law","\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704","\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704 \uc885\ud569 \uc0ac\ub840",'\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\uc640 \uad00\ub828\ud558\uc5ec "\uad6c\uc18d\uc870\uac74"\uc774 \uc778\uc815\ub418\uae30 \uc704\ud55c \uc694\uc18c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?',B.asI,0,"\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\uac00 \uc131\ub9bd\ud558\ub824\uba74 \uc9c0\uc815\ub41c \uac00\uaca9\uc744 \uc900\uc218\ud558\uc9c0 \uc54a\uc744 \uacbd\uc6b0 \uacf5\uae09 \uc911\ub2e8\uc774\ub098 \uacc4\uc57d \ud574\uc9c0 \ub4f1 \uc2e4\uc9c8\uc801\uc778 \ubd88\uc774\uc775\uc774 \uc608\uc815\ub418\uc5b4 \uc788\ub294 \ub4f1, \uc720\ud1b5\uc5c5\uc790\uc758 \uac00\uaca9 \uacb0\uc815\uc758 \uc790\uc720\ub97c \uc0ac\uc2e4\uc0c1 \uad6c\uc18d\ud558\ub294 \uc870\uac74\uc774 \uc778\uc815\ub418\uc5b4\uc57c \ud55c\ub2e4.",B.aGR,B.a_I,null)
B.a55=s(["\uc815\ub2f9\ud55c \uc774\uc720 \uc5c6\uc774 \ucd5c\uc800\ud310\ub9e4\uac00\uaca9\uc744 \uac15\uc81c\ud558\uba74 \uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\ub85c \ubb38\uc81c\ub420 \uc218 \uc788\uc5b4 \uc2e0\uc911\ud55c \uac80\ud1a0\uac00 \ud544\uc694\ud558\ub2e4","\uac00\ub9f9\ubcf8\ubd80\ub294 \uac00\ub9f9\uc810\uc758 \ud310\ub9e4\uac00\uaca9\uc744 \uc544\ubb34\ub7f0 \uc81c\uc57d \uc5c6\uc774 \uac15\uc81c\ud560 \uc218 \uc788\ub2e4","\uac00\ub9f9\uacc4\uc57d\uc5d0\uc11c\ub294 \uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704 \uaddc\uc81c\uac00 \uc804\ud600 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4","\uac00\ub9f9\uc810\uc774 \uc790\uc728\uc801\uc73c\ub85c \uac00\uaca9\uc744 \uc815\ud558\ub294 \uac83\uc740 \ud56d\uc0c1 \uc704\ubc95\ud558\ub2e4"],t.s)
B.a6H=s(["\uc815\ub2f9\ud55c \uc774\uc720 \uc5c6\uc774 \uac00\ub9f9\uc810\uc5d0 \ucd5c\uc800\ud310\ub9e4\uac00\uaca9 \uc900\uc218\ub97c \uac15\uc81c\ud558\ub294 \uac83\uc740 \uc704\ubc95 \uc18c\uc9c0\uac00 \uc788\uc5b4 \uc2e0\uc911\ud558\uac8c \uac80\ud1a0\ud574\uc57c \ud560 \uc0ac\ud56d"],t.s)
B.b1S=s(["\uac00\ub9f9\uac70\ub798\uc5d0\uc11c\uc758 \uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704 \uc720\uc758\uc0ac\ud56d"],t.s)
B.bQo=new A.a("gen_rpm_extra_6","economic_law","\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704","\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704 \uc885\ud569 \uc0ac\ub840","\uac00\ub9f9\uc0ac\uc5c5(\ud504\ub79c\ucc28\uc774\uc988) \uad00\uacc4\uc5d0\uc11c \uac00\ub9f9\ubcf8\ubd80\uac00 \uac00\ub9f9\uc810\uc758 \ud310\ub9e4\uac00\uaca9\uc744 \ud1b5\uc81c\ud558\ub824 \ud560 \ub54c \uc8fc\uc758\ud560 \uc810\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.a55,0,"\uac00\ub9f9\ubcf8\ubd80\uc640 \uac00\ub9f9\uc810 \uc0ac\uc774\uc758 \uac70\ub798\uc5d0\ub3c4 \uacf5\uc815\uac70\ub798\ubc95\uc0c1 \uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704 \uaddc\uc81c\uac00 \uadf8\ub300\ub85c \uc801\uc6a9\ub420 \uc218 \uc788\uc73c\ubbc0\ub85c, \uc815\ub2f9\ud55c \uc774\uc720 \uc5c6\uc774 \uac00\ub9f9\uc810\uc5d0 \ucd5c\uc800\ud310\ub9e4\uac00\uaca9 \uc900\uc218\ub97c \uac15\uc81c\ud558\ub294 \uac83\uc740 \uc704\ubc95 \uc18c\uc9c0\uac00 \uc788\uc5b4 \uac00\ub9f9\uac70\ub798\uc0ac\uac00 \uc790\ubb38 \uc2dc \uc2e0\uc911\ud558\uac8c \uac80\ud1a0\ud574\uc57c \ud560 \uc0ac\ud56d\uc774\ub2e4.",B.a6H,B.b1S,null)
B.WG=s(["\uc0c1\ub2f9\ud788 \uc720\ub9ac\ud55c \uc870\uac74\uc73c\ub85c \uc790\uae08\uc744 \uac70\ub798\ud558\uc5ec \ud2b9\uc218\uad00\uacc4\uc778\uc5d0\uac8c \ubd80\ub2f9\ud55c \uc774\uc775\uc744 \uadc0\uc18d\uc2dc\ud0a4\ub294 \ud589\uc704","\uc0c1\ub2f9\ud788 \uc720\ub9ac\ud55c \uc870\uac74\uc73c\ub85c \uc790\uc0b0\xb7\uc0c1\ud488\xb7\uc6a9\uc5ed\uc744 \uac70\ub798\ud558\uc5ec \ud2b9\uc218\uad00\uacc4\uc778\uc5d0\uac8c \ubd80\ub2f9\ud55c \uc774\uc775\uc744 \uadc0\uc18d\uc2dc\ud0a4\ub294 \ud589\uc704","\uc0ac\uc5c5\uae30\ud68c\ub97c \uc81c\uacf5\ud558\uc5ec \ud2b9\uc218\uad00\uacc4\uc778\uc5d0\uac8c \uc774\uc775\uc744 \uadc0\uc18d\uc2dc\ud0a4\ub294 \ud589\uc704","\ud569\ub9ac\uc801 \uace0\ub824\ub098 \ube44\uad50 \uc5c6\uc774 \uc0c1\ub2f9\ud55c \uaddc\ubaa8\ub85c \uac70\ub798\ud558\uc5ec \ud2b9\uc218\uad00\uacc4\uc778\uc5d0\uac8c \uc774\uc775\uc744 \uadc0\uc18d\uc2dc\ud0a4\ub294 \ud589\uc704","\uc2dc\uc7a5\uac00\uaca9\ubcf4\ub2e4 \ub0ae\uc740 \uac00\uaca9\uc73c\ub85c \uc77c\ubc18 \uc18c\ube44\uc790\uc5d0\uac8c \ud310\ub9e4\ucd09\uc9c4 \ud560\uc778\uc744 \uc81c\uacf5\ud558\ub294 \ud589\uc704"],t.s)
B.ajO=s(["\uc77c\ubc18 \uc18c\ube44\uc790\ub97c \ub300\uc0c1\uc73c\ub85c \ud55c \ud1b5\uc0c1\uc801\uc778 \ud310\ub9e4\ucd09\uc9c4 \ud560\uc778\ucc98\ub7fc \ud2b9\uc218\uad00\uacc4\uc778\uacfc \ubb34\uad00\ud55c \uac70\ub798\ub294 \uc560\ucd08\uc5d0 \uaddc\uc81c \ub300\uc0c1 \ubc94\uc704\uc5d0 \ud3ec\ud568\ub418\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.an4=s(["\ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5","\uc77c\uac10\ubab0\uc544\uc8fc\uae30"],t.s)
B.bFl=new A.a("gen_sp_1","economic_law","\ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5",null,"\ub3c5\uc810\uaddc\uc81c \ubc0f \uacf5\uc815\uac70\ub798\uc5d0 \uad00\ud55c \ubc95\ub960\uc0c1 \ud2b9\uc218\uad00\uacc4\uc778\uc5d0 \ub300\ud55c \ubd80\ub2f9\ud55c \uc774\uc775\uc81c\uacf5\ud589\uc704(\uc0ac\uc775\ud3b8\ucde8)\uc5d0 \ud574\ub2f9\ud558\uc9c0 \uc54a\ub294 \uac83\uc740?",B.WG,4,'\uacf5\uc815\uac70\ub798\ubc95 \uc81c47\uc870(\ud2b9\uc218\uad00\uacc4\uc778\uc5d0 \ub300\ud55c \ubd80\ub2f9\ud55c \uc774\uc775\uc81c\uacf5 \ub4f1 \uae08\uc9c0, \uc774\ub978\ubc14 "\uc77c\uac10\ubab0\uc544\uc8fc\uae30" \uaddc\uc81c)\ub294 \uc0c1\ub2f9\ud788 \uc720\ub9ac\ud55c \uc870\uac74\uc758 \uc790\uae08\xb7\uc790\uc0b0\xb7\uc0c1\ud488\xb7\uc6a9\uc5ed\xb7\uc778\ub825 \uac70\ub798, \uc0ac\uc5c5\uae30\ud68c \uc81c\uacf5, \ud569\ub9ac\uc801 \uace0\ub824 \uc5c6\ub294 \uc0c1\ub2f9\ud55c \uaddc\ubaa8\uc758 \uac70\ub798\ub97c \ud1b5\ud574 \ud2b9\uc218\uad00\uacc4\uc778\uc5d0\uac8c \ubd80\ub2f9\ud55c \uc774\uc775\uc744 \uadc0\uc18d\uc2dc\ud0a4\ub294 \ud589\uc704\ub97c \uae08\uc9c0 \ub300\uc0c1\uc73c\ub85c \uaddc\uc815\ud55c\ub2e4. \uc774 \uaddc\uc81c\uc758 \ubaa9\uc801\uc740 \ub300\uae30\uc5c5\uc9d1\ub2e8 \ucd1d\uc218 \uc77c\uac00\ub098 \uacc4\uc5f4\ud68c\uc0ac \ub4f1 "\ud2b9\uc218\uad00\uacc4\uc778"\uc5d0\uac8c \ubd80\ub97c \ubd80\ub2f9\ud558\uac8c \uc774\uc804\uc2dc\ud0a4\ub294 \uac83\uc744 \ub9c9\ub294 \ub370 \uc788\uc73c\ubbc0\ub85c, \uc77c\ubc18 \uc18c\ube44\uc790\ub97c \ub300\uc0c1\uc73c\ub85c \ud55c \ud1b5\uc0c1\uc801\uc778 \ud310\ub9e4\ucd09\uc9c4 \ud560\uc778\ucc98\ub7fc \ud2b9\uc218\uad00\uacc4\uc778\uacfc \ubb34\uad00\ud55c \uac70\ub798\ub294 \uc560\ucd08\uc5d0 \uaddc\uc81c \ub300\uc0c1 \ubc94\uc704\uc5d0 \ud3ec\ud568\ub418\uc9c0 \uc54a\ub294\ub2e4.',B.ajO,B.an4,null)
B.acU=s([u.wc,"\uac70\ub798\uc640 \uc804\ud600 \ubb34\uad00\ud55c \uc77c\ubc18 \uc18c\ube44\uc790","\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c \uc18c\uc18d \uacf5\ubb34\uc6d0","\ud574\ub2f9 \uc0ac\uc5c5\uc790\uc758 \ubaa8\ub4e0 \uc784\uc9c1\uc6d0 \uc804\uccb4","\ud574\ub2f9 \uc0ac\uc5c5\uc790\uc640 \uac70\ub798\ud55c \uc801 \uc5c6\ub294 \uc81c3\uc758 \uc0ac\uc5c5\uc790"],t.s)
B.ao8=s([u.wc],t.s)
