B.bLQ=new A.a("gen_sp_type_1","economic_law","\ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5","\uaddc\uc81c \ub300\uc0c1\xb7\ud589\uc704 \uc720\ud615",'\ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5 \uaddc\uc81c\uc5d0\uc11c "\ud2b9\uc218\uad00\uacc4\uc778"\uc5d0 \ud574\ub2f9\ud558\ub294 \uc790\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?',B.acU,0,'\ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5 \uaddc\uc81c\uc5d0\uc11c "\ud2b9\uc218\uad00\uacc4\uc778"\uc740 \ub300\uae30\uc5c5\uc9d1\ub2e8\uc758 \ub3d9\uc77c\uc778(\ucd1d\uc218)\uacfc \uadf8 \uce5c\uc871, \uadf8\ub9ac\uace0 \ub3d9\uc77c\uc778\uc774 \uc0ac\uc2e4\uc0c1 \uc9c0\ubc30\ud558\ub294 \uacc4\uc5f4\ud68c\uc0ac \ub4f1 \uc77c\uc815\ud55c \uc9c0\ubc30\xb7\uc885\uc18d \uad00\uacc4\uc5d0 \uc788\ub294 \uc790\ub97c \uc758\ubbf8\ud558\uba70, \uac70\ub798\uc640 \ubb34\uad00\ud55c \uc77c\ubc18 \uc18c\ube44\uc790\ub098 \uc81c3\uc758 \uc0ac\uc5c5\uc790\ub294 \uc774\uc5d0 \ud574\ub2f9\ud558\uc9c0 \uc54a\ub294\ub2e4.',B.ao8,B.Tf,null)
B.aS1=s([u.at,"\uc2dc\uc7a5\uac00\uaca9\uacfc \ub3d9\uc77c\ud55c \uc870\uac74\uc73c\ub85c \uac70\ub798\ud558\ub294 \ud589\uc704","\uacf5\uac1c\uacbd\uc7c1\uc785\ucc30\uc744 \ud1b5\ud574 \uc815\ub2f9\ud558\uac8c \uac70\ub798\ud558\ub294 \ud589\uc704","\ud2b9\uc218\uad00\uacc4\uc778\uc774 \uc544\ub2cc \uc790\uc640 \uc815\uc0c1\uc801\uc73c\ub85c \uac70\ub798\ud558\ub294 \ud589\uc704","\uac70\ub798\uc0c1\ub300\ubc29\uc5d0\uac8c \uc815\ub2f9\ud55c \ub300\uac00\ub97c \uc9c0\uae09\ud558\ub294 \ud589\uc704"],t.s)
