B.Yr=s([u.g6,"\uc5ec\ub7ec \uc0ac\uc5c5\uc790\uc640 \uacf5\uc815\ud55c \uc785\ucc30\uc744 \uac70\uccd0 \ucd5c\uc801\uc758 \uac70\ub798\ucc98\ub97c \uc120\uc815\ud558\ub294 \ud589\uc704","\uac70\ub798 \uaddc\ubaa8\uc640 \ubb34\uad00\ud558\uac8c \ud56d\uc0c1 \ucd5c\uc800\uac00 \uc785\ucc30\uc790\uc640 \uac70\ub798\ud558\ub294 \ud589\uc704","\ud2b9\uc218\uad00\uacc4\uc778\uc774 \uc544\ub2cc \ud68c\uc0ac\uc640 \ub300\uaddc\ubaa8\ub85c \uac70\ub798\ud558\ub294 \ud589\uc704","\uac70\ub798 \uaddc\ubaa8\ub97c \uc810\uc9c4\uc801\uc73c\ub85c \ucd95\uc18c\ud558\ub294 \ud589\uc704"],t.s)
