B.bxf=new A.a("gen_sp_type_4","economic_law","\ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5","\uaddc\uc81c \ub300\uc0c1\xb7\ud589\uc704 \uc720\ud615",'\ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5\uc758 \ud558\uc704 \uc720\ud615 \uc911 "\ud569\ub9ac\uc801 \uace0\ub824\ub098 \ube44\uad50 \uc5c6\uc774 \uc0c1\ub2f9\ud55c \uaddc\ubaa8\ub85c \uac70\ub798"\ud558\ub294 \ud589\uc704(\uc77c\uac10\ubab0\uc544\uc8fc\uae30)\uc758 \uc758\ubbf8\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?',B.Yr,0,'\uc774\ub978\ubc14 "\uc77c\uac10\ubab0\uc544\uc8fc\uae30"\ub85c \ubd88\ub9ac\ub294 \uc774 \uc720\ud615\uc740, \ub2e4\ub978 \uc0ac\uc5c5\uc790\uc640\uc758 \uac00\uaca9\xb7\ud488\uc9c8\xb7\uae30\uc220\ub825 \ub4f1\uc5d0 \ub300\ud55c \ud569\ub9ac\uc801\uc778 \ube44\uad50\xb7\uac80\ud1a0 \uc5c6\uc774 \ud2b9\uc218\uad00\uacc4\uc778\uc774 \uc9c0\ubc30\ud558\ub294 \ud68c\uc0ac\uc5d0 \uc0c1\ub2f9\ud55c \uaddc\ubaa8\uc758 \uac70\ub798\ub97c \ubab0\uc544\uc90c\uc73c\ub85c\uc368 \uadf8 \ud68c\uc0ac\uc5d0 \ubd80\ub2f9\ud55c \uc774\uc775\uc744 \uadc0\uc18d\uc2dc\ud0a4\ub294 \ud589\uc704\ub97c \uc758\ubbf8\ud55c\ub2e4.',B.a1Q,B.b_Q,null)
B.a34=s([u.bN,"\ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5 \uaddc\uc81c\ub294 \ub300\uae30\uc5c5\uc758 \uc815\uc0c1\uc801\uc778 \uacc4\uc5f4\uc0ac \uac04 \uac70\ub798 \uc790\uccb4\ub97c \uc804\uba74 \uae08\uc9c0\ud558\uae30 \uc704\ud55c \uac83\uc774\ub2e4","\uc774 \uaddc\uc81c\ub294 \uc18c\uc561\uc8fc\uc8fc\uc758 \uc774\uc775\uacfc \uc804\ud600 \ubb34\uad00\ud55c \ubb38\uc81c\uc774\ub2e4","\uc774 \uaddc\uc81c\ub294 \uc624\uc9c1 \ud615\uc0ac\ucc98\ubc8c\ub9cc\uc744 \ubaa9\uc801\uc73c\ub85c \ud55c\ub2e4","\uc774 \uaddc\uc81c\ub294 \uc911\uc18c\uae30\uc5c5\uc5d0\uac8c\ub9cc \uc801\uc6a9\ub418\ub294 \uaddc\uc81c\uc774\ub2e4"],t.s)
