B.bup=new A.a("gen_consent_start_1","economic_law","\ub3d9\uc758\uc758\uacb0","\ub3d9\uc758\uc758\uacb0\uc758 \uc2e0\uccad\xb7\uac1c\uc2dc \uc694\uac74","\ub3d9\uc758\uc758\uacb0 \uc81c\ub3c4\uc758 \uc758\uc758\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.ak2,0,"\ub3d9\uc758\uc758\uacb0 \uc81c\ub3c4\ub294 \uc870\uc0ac\xb7\uc2ec\uc758\ub97c \ubc1b\ub294 \uc0ac\uc5c5\uc790\uac00 \uc2a4\uc2a4\ub85c \uc18c\ube44\uc790 \ud53c\ud574\uad6c\uc81c, \uac70\ub798\uc9c8\uc11c \uac1c\uc120 \ub4f1 \uc2dc\uc815\ubc29\uc548\uc744 \uc81c\uc2dc\ud558\uace0 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uac00 \uc774\ub97c \ud0c0\ub2f9\ud558\ub2e4\uace0 \uc778\uc815\ud558\ub294 \uacbd\uc6b0, \uc704\ubc95\uc131 \uc5ec\ubd80\ub97c \ud655\uc815\uc801\uc73c\ub85c \ud310\ub2e8\ud558\uc9c0 \uc54a\uace0 \uc2e0\uc18d\ud558\uac8c \uc0ac\uac74\uc744 \uc885\uacb0\ud558\ub294 \uc81c\ub3c4\uc774\ub2e4.",B.b0Y,B.avE,null)
B.SW=s(["\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uc758 \uc870\uc0ac\ub098 \uc2ec\uc758\ub97c \ubc1b\uace0 \uc788\ub294 \uc0ac\uc5c5\uc790 \ub610\ub294 \uc0ac\uc5c5\uc790\ub2e8\uccb4","\uc624\uc9c1 \uc2e0\uace0\uc778(\ud53c\ud574\uc790)\ub9cc \uc2e0\uccad\ud560 \uc218 \uc788\ub2e4","\uc624\uc9c1 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c \uc704\uc6d0\uc7a5\ub9cc \uc2e0\uccad\ud560 \uc218 \uc788\ub2e4","\uc624\uc9c1 \uad6d\ud68c\uc758\uc6d0\ub9cc \uc2e0\uccad\ud560 \uc218 \uc788\ub2e4","\uc624\uc9c1 \ubc95\uc6d0\ub9cc \uc2e0\uccad\ud560 \uc218 \uc788\ub2e4"],t.s)
B.aGX=s(["\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uc758 \uc870\uc0ac\ub098 \uc2ec\uc758\ub97c \ubc1b\uace0 \uc788\ub294 \uc0ac\uc5c5\uc790 \ub610\ub294 \uc0ac\uc5c5\uc790\ub2e8\uccb4"],t.s)
B.b6X=s(["\ub3d9\uc758\uc758\uacb0 \uc2e0\uccad\uad8c\uc790"],t.s)
B.bEI=new A.a("gen_consent_start_2","economic_law","\ub3d9\uc758\uc758\uacb0","\ub3d9\uc758\uc758\uacb0\uc758 \uc2e0\uccad\xb7\uac1c\uc2dc \uc694\uac74","\ub3d9\uc758\uc758\uacb0\uc744 \uc2e0\uccad\ud560 \uc218 \uc788\ub294 \uc790\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.SW,0,"\ub3d9\uc758\uc758\uacb0\uc740 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uc758 \uc870\uc0ac\ub098 \uc2ec\uc758\ub97c \ubc1b\uace0 \uc788\ub294 \uc0ac\uc5c5\uc790 \ub610\ub294 \uc0ac\uc5c5\uc790\ub2e8\uccb4\uac00 \uc2a4\uc2a4\ub85c \uc2dc\uc815\ubc29\uc548\uc744 \uc81c\ucd9c\ud558\uba70 \uc2e0\uccad\ud558\ub294 \uc81c\ub3c4\ub85c, \uc2e0\uace0\uc778\uc774\ub098 \uc81c3\uc790\uac00 \uc544\ub2c8\ub77c \uc870\uc0ac\xb7\uc2ec\uc758\uc758 \ub300\uc0c1\uc774 \ub418\ub294 \uc0ac\uc5c5\uc790 \ubcf8\uc778\uc774 \uc2e0\uccad\uad8c\uc790\uac00 \ub41c\ub2e4.",B.aGX,B.b6X,null)
B.abz=s([u.a2,"\ubaa8\ub4e0 \uc720\ud615\uc758 \uc0ac\uac74\uc5d0 \uc608\uc678 \uc5c6\uc774 \ub3d9\uc758\uc758\uacb0\uc774 \ud5c8\uc6a9\ub41c\ub2e4","\ub3d9\uc758\uc758\uacb0 \ub300\uc0c1\uc5d0\uc11c \ubc30\uc81c\ub418\ub294 \uc0ac\uac74 \uc720\ud615\uc740 \uc804\ud600 \uc874\uc7ac\ud558\uc9c0 \uc54a\ub294\ub2e4","\uc624\uc9c1 \ud45c\uc900\uc57d\uad00 \uc0ac\uac74\ub9cc \ub3d9\uc758\uc758\uacb0 \ub300\uc0c1\uc5d0\uc11c \ubc30\uc81c\ub41c\ub2e4","\uc624\uc9c1 \uc18c\ube44\uc790\ub2e8\uccb4\uac00 \uc2e0\uace0\ud55c \uc0ac\uac74\ub9cc \ubc30\uc81c\ub41c\ub2e4"],t.s)
