B.aQS=s([u.p3,"\uac00\ub9f9\uc0ac\uc5c5\ubc95\uacfc \uacf5\uc815\uac70\ub798\ubc95\uc740 \uc11c\ub85c \uc644\uc804\ud788 \ubb34\uad00\ud55c \ubc95\ub960\uc774\ub2e4","\uac00\ub9f9\uc0ac\uc5c5\uc5d0\ub294 \uacf5\uc815\uac70\ub798\ubc95\uc774 \uc804\ud600 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4","\uac00\ub9f9\uc0ac\uc5c5\ubc95\uc774 \uc81c\uc815\ub418\uba74\uc11c \uacf5\uc815\uac70\ub798\ubc95\uc758 \uac70\ub798\uc0c1\uc9c0\uc704\ub0a8\uc6a9 \uaddc\uc815\uc740 \ud3d0\uc9c0\ub418\uc5c8\ub2e4","\ub450 \ubc95\ub960\uc740 \ud56d\uc0c1 \uc11c\ub85c \ubaa8\uc21c\ub418\ub294 \ub0b4\uc6a9\uc744 \uaddc\uc815\ud55c\ub2e4"],t.s)
B.a92=s([u.p3],t.s)
B.asE=s(["\uac00\ub9f9\uc0ac\uc5c5\ubc95\uacfc \uacf5\uc815\uac70\ub798\ubc95\uc758 \uad00\uacc4"],t.s)
B.byV=new A.a("gen_super_sanction_4","economic_law","\uac70\ub798\uc0c1\uc9c0\uc704\ub0a8\uc6a9","\ubd80\ub2f9\uc131 \ud310\ub2e8\xb7\uc81c\uc7ac","\uac00\ub9f9\uc0ac\uc5c5\ubc95\uacfc \uacf5\uc815\uac70\ub798\ubc95\uc774 \uac70\ub798\uc0c1 \uc9c0\uc704\ub0a8\uc6a9\uc744 \ud568\uaed8 \uaddc\uc81c\ud558\ub294 \uac83\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.aQS,0,"\uac00\ub9f9\uc0ac\uc5c5\ubc95\uc740 \uac00\ub9f9\ubcf8\ubd80\uc640 \uac00\ub9f9\uc810 \uac04\uc758 \ud2b9\uc218\ud55c \uac70\ub798\uad00\uacc4 \ud2b9\uc131\uc744 \ubc18\uc601\ud558\uc5ec \uac70\ub798\uc0c1 \uc9c0\uc704\ub0a8\uc6a9\uc5d0 \ud574\ub2f9\ud560 \uc218 \uc788\ub294 \ud589\uc704 \uc720\ud615(\ubd80\ub2f9\ud55c \uc601\uc5c5\uc9c0\uc5ed \uce68\ud574, \ubd80\ub2f9\ud55c \uacc4\uc57d\ud574\uc9c0 \ub4f1)\uc744 \ubcf4\ub2e4 \uad6c\uccb4\ud654\ud558\uc5ec \uaddc\uc815\ud558\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc73c\uba70, \uc774\ub294 \uacf5\uc815\uac70\ub798\ubc95\uc758 \uc77c\ubc18\uc801\uc778 \uac70\ub798\uc0c1\uc9c0\uc704\ub0a8\uc6a9 \uaddc\uc81c\uc640 \ud568\uaed8 \uac00\ub9f9\ubd84\uc57c\uc758 \ud2b9\uc218\uc131\uc744 \ubcf4\uc644\ud558\ub294 \uc5ed\ud560\uc744 \ud55c\ub2e4.",B.a92,B.asE,null)
B.awA=s(["\uac70\ub798\uc0c1\uc9c0\uc704\ub0a8\uc6a9\uc740 \ud589\uc704\uc790\uac00 \uc2dc\uc7a5 \uc804\uccb4\ub97c \uc9c0\ubc30\ud558\ub294 \uc9c0\uc704\uc5d0 \uc788\uc9c0 \uc54a\ub354\ub77c\ub3c4 \ud2b9\uc815 \uac70\ub798\uc0c1\ub300\ubc29\uc5d0 \ub300\ud574 \uc6b0\uc6d4\ud55c \uc9c0\uc704\ub9cc \uc788\uc73c\uba74 \uc131\ub9bd\ud560 \uc218 \uc788\ub2e4","\uac70\ub798\uc0c1\uc9c0\uc704\ub0a8\uc6a9\ub3c4 \uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9\uacfc \ub9c8\ucc2c\uac00\uc9c0\ub85c \uc2dc\uc7a5\uc810\uc720\uc728 \uc694\uac74\uc774 \ubc18\ub4dc\uc2dc \ud544\uc694\ud558\ub2e4","\ub450 \uc81c\ub3c4\ub294 \uc644\uc804\ud788 \ub3d9\uc77c\ud55c \uc694\uac74\uacfc \ud6a8\uacfc\ub97c \uac16\ub294\ub2e4","\uac70\ub798\uc0c1\uc9c0\uc704\ub0a8\uc6a9\uc740 \uc2dc\uc7a5\uc9c0\ubc30\uc801\uc0ac\uc5c5\uc790\uc5d0\uac8c\ub9cc \uc801\uc6a9\ub418\ub294 \uaddc\uc81c\uc774\ub2e4"],t.s)
B.a37=s(["\uc2dc\uc7a5 \uc804\uccb4\ub97c \uc9c0\ubc30\ud558\uc9c0 \uc54a\ub354\ub77c\ub3c4 \ud2b9\uc815 \uac70\ub798\uc0c1\ub300\ubc29\uacfc\uc758 \uad00\uacc4\uc5d0\uc11c \uc0c1\ub300\uc801\uc73c\ub85c \uc6b0\uc6d4\ud55c \uc9c0\uc704\ub9cc \uc788\uc73c\uba74 \uc131\ub9bd\ud560 \uc218 \uc788\ub2e4"],t.s)
B.aYF=s(["\uac70\ub798\uc0c1\uc9c0\uc704\ub0a8\uc6a9\uacfc \uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9\uc758 \ucc28\uc774"],t.s)
B.bBh=new A.a("gen_super_extra_1","economic_law","\uac70\ub798\uc0c1\uc9c0\uc704\ub0a8\uc6a9","\uac70\ub798\uc0c1\uc9c0\uc704\ub0a8\uc6a9 \uc885\ud569 \uc0ac\ub840","\uac70\ub798\uc0c1\uc9c0\uc704\ub0a8\uc6a9\uacfc \uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9\uc758 \uac00\uc7a5 \ud575\uc2ec\uc801\uc778 \ucc28\uc774\uc810\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.awA,0,"\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9\uc740 \uc2dc\uc7a5 \uc804\uccb4\uc5d0 \ub300\ud55c \uc9c0\ubc30\ub825\uc744 \uc804\uc81c\ub85c \ud558\ub294 \ubc18\uba74, \uac70\ub798\uc0c1\uc9c0\uc704\ub0a8\uc6a9(\ubd88\uacf5\uc815\uac70\ub798\ud589\uc704\uc758 \ud55c \uc720\ud615)\uc740 \uc2dc\uc7a5 \uc804\uccb4\ub97c \uc9c0\ubc30\ud558\uc9c0 \uc54a\ub354\ub77c\ub3c4 \ud2b9\uc815 \uac70\ub798\uc0c1\ub300\ubc29\uacfc\uc758 \uad00\uacc4\uc5d0\uc11c \uc0c1\ub300\uc801\uc73c\ub85c \uc6b0\uc6d4\ud55c \uc9c0\uc704(\uac70\ub798\uc758\uc874\ub3c4 \ub4f1)\ub9cc \uc788\uc73c\uba74 \uc131\ub9bd\ud560 \uc218 \uc788\ub2e4\ub294 \uc810\uc5d0\uc11c \uaddc\uc81c\uc758 \ucc29\uc548\uc810\uc774 \ub2e4\ub974\ub2e4.",B.a37,B.aYF,null)
B.aPU=s(["\uac70\ub798\uc0c1\ub300\ubc29\uc5d0 \ub300\ud55c \uac70\ub798\uc758\uc874\ub3c4, \uac70\ub798\ucc98 \uc804\ud658\uac00\ub2a5\uc131 \ub4f1\uc744 \uc885\ud569\uc801\uc73c\ub85c \uace0\ub824\ud558\uc5ec \ud310\ub2e8\ud55c\ub2e4","\uac70\ub798\uc0c1 \uc9c0\uc704\ub294 \ubc18\ub4dc\uc2dc \uc808\ub300\uc801\uc778 \uc2dc\uc7a5\uc810\uc720\uc728\uc744 \uae30\uc900\uc73c\ub85c\ub9cc \ud310\ub2e8\ud55c\ub2e4","\uacc4\uc18d\uc801 \uac70\ub798\uad00\uacc4\uc5d0\uc11c \uc0c1\ub300\ubc29\uc774 \ub2e4\ub978 \uac70\ub798\ucc98\ub85c \uc27d\uac8c \uc804\ud658\ud558\uae30 \uc5b4\ub824\uc6b4 \uc0ac\uc815\ub3c4 \uace0\ub824\uc694\uc18c\uac00 \ub41c\ub2e4","\uc790\uae08\ub825, \uc778\ub825, \uc815\ubcf4\ub825 \ub4f1 \uc0ac\uc5c5\ub2a5\ub825\uc758 \uaca9\ucc28\ub3c4 \ud310\ub2e8\uc5d0 \uace0\ub824\ub420 \uc218 \uc788\ub2e4"],t.s)
B.bcJ=s(["\uc2dc\uc7a5\uc810\uc720\uc728 \uac19\uc740 \uc808\ub300\uc801 \uc9c0\ud45c\ub9cc\uc73c\ub85c \ud310\ub2e8\ud558\uc9c0 \uc54a\uace0, \uac70\ub798\uc758\uc874\ub3c4\xb7\uac70\ub798\ucc98 \uc804\ud658\uc758 \uc6a9\uc774\uc131 \ub4f1\uc744 \uc885\ud569\uc801\uc73c\ub85c \uace0\ub824"],t.s)
B.aeD=s(["\uac70\ub798\uc0c1 \uc9c0\uc704\uc758 \ud310\ub2e8 \uae30\uc900"],t.s)
B.bQL=new A.a("gen_super_extra_2","economic_law","\uac70\ub798\uc0c1\uc9c0\uc704\ub0a8\uc6a9","\uac70\ub798\uc0c1\uc9c0\uc704\ub0a8\uc6a9 \uc885\ud569 \uc0ac\ub840","\uac70\ub798\uc0c1 \uc9c0\uc704\uc758 \ud310\ub2e8 \uae30\uc900\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aPU,1,"\uac70\ub798\uc0c1 \uc9c0\uc704\ub294 \uc2dc\uc7a5\uc810\uc720\uc728 \uac19\uc740 \uc808\ub300\uc801 \uc9c0\ud45c\ub9cc\uc73c\ub85c \ud310\ub2e8\ud558\uc9c0 \uc54a\uace0, \uac70\ub798\uc758\uc874\ub3c4, \uac70\ub798\ucc98 \uc804\ud658\uc758 \uc6a9\uc774\uc131, \uc790\uae08\ub825\xb7\uc815\ubcf4\ub825 \ub4f1 \ub2f9\uc0ac\uc790 \uac04 \uc0ac\uc5c5\ub2a5\ub825\uc758 \uaca9\ucc28\ub97c \uc885\ud569\uc801\uc73c\ub85c \uace0\ub824\ud558\uc5ec \uc0c1\ub300\uc801\uc73c\ub85c \ud310\ub2e8\ud55c\ub2e4.",B.bcJ,B.aeD,null)
B.b1k=s(["\uac70\ub798\uc0c1 \uc6b0\uc6d4\ud55c \uc9c0\uc704\ub97c \uc774\uc6a9\ud574 \uc0c1\ub300\ubc29\uc5d0\uac8c \uc77c\ubc29\uc801\uc73c\ub85c \ubd88\ub9ac\ud55c \uac70\ub798\uc870\uac74\uc744 \uc124\uc815\ud558\uac70\ub098 \ubcc0\uacbd\ud558\ub294 \ud589\uc704","\uac70\ub798\uc0c1\ub300\ubc29\uacfc \ub300\ub4f1\ud55c \uc9c0\uc704\uc5d0\uc11c \ud611\uc0c1\uc744 \uac70\uccd0 \uacc4\uc57d\uc870\uac74\uc744 \uc815\ud558\ub294 \ud589\uc704","\uc2dc\uc7a5 \uc804\uccb4\uc758 \uac00\uaca9\uc744 \uacb0\uc815\ud558\ub294 \ud589\uc704","\uacbd\uc7c1\uc0ac\uc5c5\uc790\ub97c \uc2dc\uc7a5\uc5d0\uc11c \ubc30\uc81c\ud558\ub294 \ud589\uc704"],t.s)
B.aFV=s(["\uac70\ub798\uc0c1 \uc6b0\uc6d4\ud55c \uc9c0\uc704\uc5d0 \uc788\ub294 \uc0ac\uc5c5\uc790\uac00 \uadf8 \uc9c0\uc704\ub97c \uc774\uc6a9\ud574 \uac70\ub798\uc0c1\ub300\ubc29\uc5d0\uac8c \uc77c\ubc29\uc801\uc73c\ub85c \ubd88\ub9ac\ud55c \uac70\ub798\uc870\uac74\uc744 \uc124\uc815\ud558\uac70\ub098 \ub300\uae08 \uc9c0\uae09\uc744 \uc9c0\uc5f0\ud558\ub294 \ub4f1 \ubd80\ub2f9\ud558\uac8c \ubd88\uc774\uc775\uc744 \uc8fc\ub294 \ud589\uc704"],t.s)
B.bbp=s(["\ubd88\uc774\uc775\uc81c\uacf5\uc758 \uac1c\ub150"],t.s)
B.bJ_=new A.a("gen_super_extra_3","economic_law","\uac70\ub798\uc0c1\uc9c0\uc704\ub0a8\uc6a9","\uac70\ub798\uc0c1\uc9c0\uc704\ub0a8\uc6a9 \uc885\ud569 \uc0ac\ub840",'\uac70\ub798\uc0c1\uc9c0\uc704\ub0a8\uc6a9 \ud589\uc704 \uc720\ud615 \uc911 "\ubd88\uc774\uc775\uc81c\uacf5"\uc5d0 \ud574\ub2f9\ud558\ub294 \uc0ac\ub840\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?',B.b1k,0,"\ubd88\uc774\uc775\uc81c\uacf5\uc740 \uac70\ub798\uc0c1 \uc6b0\uc6d4\ud55c \uc9c0\uc704\uc5d0 \uc788\ub294 \uc0ac\uc5c5\uc790\uac00 \uadf8 \uc9c0\uc704\ub97c \uc774\uc6a9\ud574 \uac70\ub798\uc0c1\ub300\ubc29\uc5d0\uac8c \uc77c\ubc29\uc801\uc73c\ub85c \ubd88\ub9ac\ud55c \uac70\ub798\uc870\uac74\uc744 \uc124\uc815\ud558\uac70\ub098 \ub300\uae08 \uc9c0\uae09\uc744 \uc9c0\uc5f0\ud558\ub294 \ub4f1 \ubd80\ub2f9\ud558\uac8c \ubd88\uc774\uc775\uc744 \uc8fc\ub294 \ud589\uc704\ub97c \ub9d0\ud558\uba70, \uac70\ub798\uc0c1\uc9c0\uc704\ub0a8\uc6a9\uc758 \ub300\ud45c\uc801\uc778 \uc138\ubd80 \uc720\ud615 \uc911 \ud558\ub098\uc774\ub2e4.",B.aFV,B.bbp,null)
B.anM=s(["\uac00\ub9f9\ubcf8\ubd80\uac00 \uc6b0\uc6d4\ud55c \uc9c0\uc704\ub97c \uc774\uc6a9\ud574 \uac00\ub9f9\uc810\uc5d0 \ubd88\ud544\uc694\ud55c \ubb3c\ud488 \uad6c\uc785\uc744 \uac15\uc81c\ud558\ub294 \uacbd\uc6b0","\uac00\ub9f9\uc810\uc774 \uc790\ubc1c\uc801\uc73c\ub85c \ubcf8\ubd80\uc758 \ud488\uc9c8\uae30\uc900\uc744 \uc900\uc218\ud558\uae30\ub85c \uacc4\uc57d\ud55c \uacbd\uc6b0","\uac00\ub9f9\ubcf8\ubd80\uc640 \uac00\ub9f9\uc810\uc774 \ub300\ub4f1\ud55c \ud611\uc0c1\uc744 \ud1b5\ud574 \ud569\ub9ac\uc801\uc778 \uacc4\uc57d\uc870\uac74\uc5d0 \ud569\uc758\ud55c \uacbd\uc6b0","\uac00\ub9f9\uc810\uc774 \uc790\ubc1c\uc801\uc73c\ub85c \uc778\ud14c\ub9ac\uc5b4 \uc5c5\uccb4\ub97c \uc790\uc720\ub86d\uac8c \uc120\uc815\ud55c \uacbd\uc6b0"],t.s)
B.bbt=s(["\uac00\ub9f9\ubcf8\ubd80\uac00 \uac70\ub798\uc0c1 \uc6b0\uc6d4\ud55c \uc9c0\uc704\ub97c \uc774\uc6a9\ud558\uc5ec \uac00\ub9f9\uc810\uc5d0 \ubd88\ud544\uc694\ud55c \ubb3c\ud488\uc774\ub098 \uc6a9\uc5ed\uc758 \uad6c\uc785\uc744 \uac15\uc81c\ud558\ub294 \ud589\uc704\ub294 \uad6c\uc785\uac15\uc81c\uc5d0 \ud574\ub2f9\ud560 \uc218 \uc788\ub2e4"],t.s)
B.avD=s(["\uac00\ub9f9\uac70\ub798\uc5d0\uc11c\uc758 \uac70\ub798\uc0c1\uc9c0\uc704\ub0a8\uc6a9 \uc0ac\ub840"],t.s)
B.bxN=new A.a("gen_super_extra_4","economic_law","\uac70\ub798\uc0c1\uc9c0\uc704\ub0a8\uc6a9","\uac70\ub798\uc0c1\uc9c0\uc704\ub0a8\uc6a9 \uc885\ud569 \uc0ac\ub840","\uac00\ub9f9\uac70\ub798(\ud504\ub79c\ucc28\uc774\uc988) \uad00\uacc4\uc5d0\uc11c \uac70\ub798\uc0c1\uc9c0\uc704\ub0a8\uc6a9\uc774 \ubb38\uc81c\ub420 \uc218 \uc788\ub294 \uc0c1\ud669\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.anM,0,"\uac00\ub9f9\ubcf8\ubd80\uac00 \uac70\ub798\uc0c1 \uc6b0\uc6d4\ud55c \uc9c0\uc704\ub97c \uc774\uc6a9\ud558\uc5ec \uac00\ub9f9\uc810\uc5d0 \ubd88\ud544\uc694\ud55c \ubb3c\ud488\uc774\ub098 \uc6a9\uc5ed\uc758 \uad6c\uc785\uc744 \uac15\uc81c\ud558\ub294 \ud589\uc704\ub294 \uad6c\uc785\uac15\uc81c(\uac70\ub798\uc0c1\uc9c0\uc704\ub0a8\uc6a9\uc758 \ub300\ud45c\uc801 \uc720\ud615)\uc5d0 \ud574\ub2f9\ud560 \uc218 \uc788\uc5b4 \uacf5\uc815\uac70\ub798\ubc95\xb7\uac00\ub9f9\uc0ac\uc5c5\ubc95\uc0c1 \uaddc\uc81c \ub300\uc0c1\uc774 \ub420 \uc218 \uc788\ub2e4.",B.bbt,B.avD,null)
B.aAg=s(["\ud574\ub2f9 \ubd88\uacf5\uc815\uac70\ub798\ud589\uc704\uc758 \uc911\uc9c0\uba85\ub839","\uacc4\uc57d\uc870\ud56d\uc758 \uc0ad\uc81c\xb7\uc218\uc815\uba85\ub839","\uc2dc\uc815\uba85\ub839\uc744 \ubc1b\uc740 \uc0ac\uc2e4\uc758 \uacf5\ud45c\uba85\ub839","\ud53c\ud574 \uac70\ub798\uc0c1\ub300\ubc29\uc5d0 \ub300\ud55c \ud615\uc0ac\ucc98\ubc8c \uba85\ub839"],t.s)
