B.bvX=new A.a("gen_collusion_restrict_4","economic_law","\ub2f4\ud569\uc758 \uc131\ub9bd\uc694\uac74","\uacbd\uc7c1\uc81c\ud55c\uc131 \ud310\ub2e8","\uacf5\ub3d9\ud589\uc704\uac00 \ud6a8\uc728\uc131 \uc99d\ub300 \ud6a8\uacfc\ub97c \uac00\uc838\uc624\ub294 \uacbd\uc6b0 \uacbd\uc7c1\uc81c\ud55c\uc131 \ud310\ub2e8\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.ahL,0,"\uacf5\ub3d9\ud589\uc704\uac00 \uacbd\uc7c1\uc81c\ud55c \ud6a8\uacfc\uc640 \ud568\uaed8 \uc0c1\ub2f9\ud55c \ud6a8\uc728\uc131 \uc99d\ub300 \ud6a8\uacfc(\uacf5\ub3d9 \uc5f0\uad6c\uac1c\ubc1c, \ube44\uc6a9 \uc808\uac10 \ub4f1)\ub97c \uac00\uc838\uc624\ub294 \uacbd\uc6b0\uc5d0\ub294, \ub450 \ud6a8\uacfc\ub97c \ube44\uad50\ud615\ub7c9\ud558\uc5ec \uadf8 \uacf5\ub3d9\ud589\uc704\uc758 \ubd80\ub2f9\uc131 \uc5ec\ubd80\ub97c \ud310\ub2e8\ud560 \uc218 \uc788\ub2e4\ub294 \uac83\uc774 \ub17c\uc758\ub41c\ub2e4. \ud6a8\uc728\uc131 \uc99d\ub300 \ud6a8\uacfc\uac00 \uc788\ub2e4\uace0 \ud558\uc5ec \uc790\ub3d9\uc73c\ub85c \uc704\ubc95\uc131\uc774 \uc870\uac01\ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4.",B.aGF,B.ags,null)
B.aeC=s([u.dY,"\uad00\ub828\uc2dc\uc7a5 \ud68d\uc815\uc740 \ubd80\ub2f9\ud55c \uacf5\ub3d9\ud589\uc704 \uc0ac\uac74\uacfc \uc804\ud600 \ubb34\uad00\ud558\ub2e4","\uad00\ub828\uc2dc\uc7a5\uc740 \ud56d\uc0c1 \uc804 \uc138\uacc4 \uc2dc\uc7a5\uc73c\ub85c \ud68d\uc815\ud574\uc57c \ud55c\ub2e4","\uad00\ub828\uc2dc\uc7a5 \ud68d\uc815\uc740 \uc0ac\uc5c5\uc790\uac00 \uc784\uc758\ub85c \uc815\ud558\uba74 \uadf8\ub300\ub85c \uc778\uc815\ub41c\ub2e4","\uad00\ub828\uc2dc\uc7a5 \ud68d\uc815\uc740 \uc624\uc9c1 \uc0c1\ud45c\uad8c \ubd84\uc7c1\uc5d0\uc11c\ub9cc \ubb38\uc81c\ub41c\ub2e4"],t.s)
