B.bxG=new A.a("gen_dmg_proc_6","economic_law","\uc190\ud574\ubc30\uc0c1\ucc45\uc784","\uc790\ub8cc\uc81c\ucd9c\uba85\ub839\xb7\uae30\ub85d\uc1a1\ubd80\uc694\uad6c \ub4f1 \uc808\ucc28","\uacf5\uc815\uac70\ub798\ubc95\uc0c1 \uc190\ud574\ubc30\uc0c1\ucc45\uc784 \uad00\ub828 \uc808\ucc28 \uc804\ubc18\uc5d0 \uad00\ud55c \uc885\ud569\uc801 \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.bgp,0,"\uacf5\uc815\uac70\ub798\ubc95\uc0c1 \uc190\ud574\ubc30\uc0c1\uc81c\ub3c4\ub294 \uace0\uc758\xb7\uacfc\uc2e4 \uc785\uc99d\ucc45\uc784\uc758 \uc804\ud658, \uc190\ud574\uc561 \uc778\uc815\uc5d0 \uad00\ud55c \ud2b9\uce59, \uc790\ub8cc\uc81c\ucd9c\uba85\ub839\xb7\uc0ac\uac74\uae30\ub85d \uc1a1\ubd80\uc694\uad6c\xb7\ube44\ubc00\uc720\uc9c0\uba85\ub839\uacfc \uac19\uc740 \uc808\ucc28\uc801 \ub4b7\ubc1b\uce68\uc774 \uc720\uae30\uc801\uc73c\ub85c \uacb0\ud569\ud558\uc5ec, \uc815\ubcf4 \ube44\ub300\uce6d \uc0c1\ud0dc\uc5d0 \uc788\ub294 \ud53c\ud574\uc790\uac00 \uc2e4\ud6a8\uc801\uc73c\ub85c \uc190\ud574\ubc30\uc0c1\uc744 \ubc1b\uc744 \uc218 \uc788\ub3c4\ub85d \ud558\ub294 \uc885\ud569\uc801\uc778 \uc81c\ub3c4\ub85c \uc774\ud574\ud560 \uc218 \uc788\ub2e4.",B.aG4,B.aJn,null)
B.a8M=s([u.fq,"\uacbd\uc7c1\uc0ac\uc5c5\uc790\ub97c \uc800\uac00\ub85c \uacf5\uaca9\ud558\uc5ec \uc2dc\uc7a5\uc5d0\uc11c \ubab0\uc544\ub0b4\ub294 \ud589\uc704","\uac70\ub798\uc0c1\ub300\ubc29\uc5d0\uac8c \uc790\uae30 \uc0c1\ud488\uc758 \uad6c\uc785\uc744 \uac15\uc81c\ud558\ub294 \ud589\uc704","\uc0ac\uc5c5\uc790\uac00 \uc18c\ube44\uc790\uc5d0\uac8c \ubd80\ub2f9\ud55c \ud45c\uc2dc\xb7\uad11\uace0\ub97c \ud558\ub294 \ud589\uc704","\uc0ac\uc5c5\uc790\ub2e8\uccb4\uac00 \uad6c\uc131\uc0ac\uc5c5\uc790 \uc218\ub97c \uc81c\ud55c\ud558\ub294 \ud589\uc704"],t.s)
