B.brL=new A.a("gen_sup_compare_1","economic_law","\ubd80\ub2f9\uc9c0\uc6d0\ud589\uc704","\uad00\ub828 \uc81c\ub3c4\uc640\uc758 \uad6c\ubcc4","\ubd80\ub2f9\uc9c0\uc6d0\ud589\uc704\uc640 \ud2b9\uc218\uad00\uacc4\uc778\uc5d0 \ub300\ud55c \ubd80\ub2f9\ud55c \uc774\uc775\uc81c\uacf5\ud589\uc704(\uc0ac\uc775\ud3b8\ucde8, \uc81c47\uc870)\uc758 \uad00\uacc4\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.a9v,0,"\ubd80\ub2f9\uc9c0\uc6d0\ud589\uc704(\ubd88\uacf5\uc815\uac70\ub798\ud589\uc704\uc758 \ud55c \uc720\ud615)\uc640 \ud2b9\uc218\uad00\uacc4\uc778\uc5d0 \ub300\ud55c \ubd80\ub2f9\ud55c \uc774\uc775\uc81c\uacf5\ud589\uc704(\uc81c47\uc870, \uc774\ub978\ubc14 \uc0ac\uc775\ud3b8\ucde8 \uaddc\uc81c)\ub294 \ubaa8\ub450 \ud2b9\uc218\uad00\uacc4\uc778 \ub4f1\uc5d0 \ub300\ud55c \ubd80\ub2f9\ud55c \uc774\uc775 \uadc0\uc18d\uc744 \ubb38\uc81c \uc0bc\ub294\ub2e4\ub294 \uc810\uc5d0\uc11c \uc720\uc0ac\ud558\uc9c0\ub9cc, \uc801\uc6a9\uc694\uac74\uacfc \uc785\ubc95\ucde8\uc9c0, \uaddc\uc81c\uc5f0\ud601\uc774 \ub2ec\ub77c \uc11c\ub85c \uad6c\ubcc4\ub418\ub294 \ubcc4\uac1c\uc758 \uc81c\ub3c4\ub85c \ubcd1\uc874\ud55c\ub2e4.",B.aFU,B.aCA,null)
B.aLq=s([u.B_,"\ub450 \uc81c\ub3c4\ub294 \uc644\uc804\ud788 \ub3d9\uc77c\ud55c \uac1c\ub150\uc73c\ub85c \uad6c\ubcc4\ud560 \ud544\uc694\uac00 \uc5c6\ub2e4","\ubd80\ub2f9\uc5fc\ub9e4\ub294 \ud2b9\uc218\uad00\uacc4\uc778\uc5d0\uac8c\ub9cc \uc801\uc6a9\ub418\ub294 \uac1c\ub150\uc774\ub2e4","\ubd80\ub2f9\uc9c0\uc6d0\ud589\uc704\ub294 \uc624\uc9c1 \uac00\uaca9\uc5d0 \uad00\ud55c \ud589\uc704\ub9cc\uc744 \uaddc\uc81c\ud55c\ub2e4","\ubd80\ub2f9\uc5fc\ub9e4\ub294 \uc790\uae08\uc9c0\uc6d0 \ud589\uc704\ub9cc\uc744 \uc758\ubbf8\ud55c\ub2e4"],t.s)
