B.bzt=new A.a("gen_kh_prehist_3","korean_history","\uc120\uc0ac\xb7\uace0\ub300","\uad6c\uc11d\uae30\xb7\uc2e0\uc11d\uae30\uc2dc\ub300","\uc2e0\uc11d\uae30\uc2dc\ub300\uc5d0 \ucc98\uc74c \ub098\ud0c0\ub09c \uc0ac\ud68c \ubaa8\uc2b5\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aw6,0,"\uc2e0\uc11d\uae30\uc2dc\ub300\uc5d0\ub294 \ub18d\uacbd\uacfc \ubaa9\ucd95\uc774 \uc2dc\uc791\ub418\uba74\uc11c \uc815\ucc29 \uc0dd\ud65c\uc774 \uac00\ub2a5\ud574\uc84c\uace0, \uc528\uc871\uc744 \ub2e8\uc704\ub85c \ud55c \ud3c9\ub4f1\ud55c \uacf5\ub3d9\uccb4 \uc0ac\ud68c\uac00 \ud615\uc131\ub418\uc5c8\ub2e4. \uacc4\uae09 \ubd84\ud654\uc640 \uc815\ubcf5 \uc804\uc7c1, \uc655\uad8c \uad6d\uac00\uc758 \uc131\ub9bd\uc740 \uccad\ub3d9\uae30\uc2dc\ub300 \uc774\ud6c4\uc5d0 \ub098\ud0c0\ub09c\ub2e4.",B.ba5,B.bex,null)
B.bbL=s(["\uc2b4\ubca0\ucc0c\ub974\uac1c\ub294 \ucc3d\uc758 \uc790\ub8e8\uc5d0 \uaf42\uc544 \uc0ac\ub0e5 \ub3c4\uad6c\ub85c \uc0ac\uc6a9\ud558\uc600\ub2e4","\uc8fc\uba39\ub3c4\ub07c\ub294 \uc0ac\ub0e5\uacfc \uc870\ub9ac \ub4f1 \uc5ec\ub7ec \uc6a9\ub3c4\ub85c \uc4f0\uc778 \ub5c0\uc11d\uae30\uc774\ub2e4","\ucc0d\uac1c\ub294 \ub3cc\uc758 \ud55c\ucabd \uba74\uc744 \ub5bc\uc5b4 \ub0b4\uc5b4 \ub9cc\ub4e0 \ub5c0\uc11d\uae30\uc774\ub2e4","\uac70\ud478\uc9d1\uc744 \uc774\uc6a9\ud558\uc5ec \ub3c4\uad6c\ub97c \ub300\ub7c9\uc73c\ub85c \uc8fc\uc870\ud558\uc600\ub2e4","\ub5c0\uc11d\uae30\ub294 \ub3cc\uc744 \uae68\ub728\ub9ac\uac70\ub098 \ub5bc\uc5b4 \ub0b4\uc5b4 \ub9cc\ub4e0 \ub3c4\uad6c\uc774\ub2e4"],t.s)
B.a9G=s(["\uac70\ud478\uc9d1\uc744 \uc774\uc6a9\ud558\uc5ec \ub3c4\uad6c\ub97c \ub300\ub7c9\uc73c\ub85c \uc8fc\uc870\ud558\uc600\ub2e4"],t.s)
B.aZ7=s(["\uad6c\uc11d\uae30\uc2dc\ub300 \ub3c4\uad6c\uc758 \ud2b9\uc9d5"],t.s)
B.bsO=new A.a("gen_kh_prehist_4","korean_history","\uc120\uc0ac\xb7\uace0\ub300","\uad6c\uc11d\uae30\xb7\uc2e0\uc11d\uae30\uc2dc\ub300","\uad6c\uc11d\uae30\uc2dc\ub300 \ub3c4\uad6c\uc5d0 \ub300\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.bbL,3,"\uac70\ud478\uc9d1\uc744 \uc774\uc6a9\ud55c \ub3c4\uad6c \uc8fc\uc870\ub294 \uccad\ub3d9\uae30\xb7\ucca0\uae30\uc2dc\ub300\uc758 \uae08\uc18d \uac00\uacf5 \ubc29\uc2dd\uc774\ub2e4. \uad6c\uc11d\uae30\uc2dc\ub300\uc5d0\ub294 \ub3cc\uc744 \uae68\ub728\ub9ac\uac70\ub098 \ub5bc\uc5b4 \ub0b4\uc5b4 \ub9cc\ub4e0 \ub5c0\uc11d\uae30(\uc8fc\uba39\ub3c4\ub07c\xb7\ucc0d\uac1c\xb7\uc2b4\ubca0\ucc0c\ub974\uac1c \ub4f1)\ub97c \uc0ac\uc6a9\ud558\uc600\ub2e4.",B.a9G,B.aZ7,null)
B.aSH=s(["\uac15\uac00\ub098 \ubc14\ub2f7\uac00\uc5d0 \uc6c0\uc9d1\uc744 \uc9d3\uace0 \uc815\ucc29\ud558\uc5ec \ub18d\uacbd\uacfc \uc5b4\ub85c\ub97c \ubcd1\ud589\ud558\uc600\ub2e4","\uc774\ub3d9 \uc0dd\ud65c\uc5d0 \uc720\ub9ac\ud558\ub3c4\ub85d \uac00\ubcbc\uc6b4 \ucc9c\ub9c9 \ud615\ud0dc\uc758 \uc9d1\uc744 \uc8fc\ub85c \uc0ac\uc6a9\ud558\uc600\ub2e4","\uc6b0\uacbd\uc774 \ub110\ub9ac \ubcf4\uae09\ub418\uc5b4 \ub18d\uc5c5 \uc0dd\uc0b0\ub825\uc774 \ud06c\uac8c \ud5a5\uc0c1\ub418\uc5c8\ub2e4","\ubcbc\ub18d\uc0ac\uac00 \uc804\uad6d\uc801\uc73c\ub85c \ud655\ub300\ub418\uc5b4 \uc789\uc5ec \uc0dd\uc0b0\ubb3c\uc774 \ucd95\uc801\ub418\uc5c8\ub2e4","\ucca0\uc81c \ub18d\uae30\uad6c \ubcf4\uae09\uc73c\ub85c \uac1c\uac04\uc774 \ud65c\ubc1c\ud574\uc838 \uacbd\uc9c0\uac00 \ud655\ub300\ub418\uc5c8\ub2e4"],t.s)
B.a9Y=s(["\uac15\uac00\ub098 \ubc14\ub2f7\uac00\uc5d0 \uc6c0\uc9d1\uc744 \uc9d3\uace0 \uc815\ucc29\ud558\uc5ec \ub18d\uacbd\uacfc \uc5b4\ub85c\ub97c \ubcd1\ud589\ud558\uc600\ub2e4"],t.s)
B.a53=s(["\uc2e0\uc11d\uae30\uc2dc\ub300 \uc8fc\uac70\xb7\uacbd\uc81c \uc0dd\ud65c"],t.s)
B.bnl=new A.a("gen_kh_prehist_5","korean_history","\uc120\uc0ac\xb7\uace0\ub300","\uad6c\uc11d\uae30\xb7\uc2e0\uc11d\uae30\uc2dc\ub300","\uc2e0\uc11d\uae30\uc2dc\ub300\uc758 \uc8fc\uac70\xb7\uacbd\uc81c \uc0dd\ud65c\uc5d0 \ub300\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aSH,0,"\uc2e0\uc11d\uae30\uc2dc\ub300 \uc0ac\ub78c\ub4e4\uc740 \uac15\uac00\ub098 \ubc14\ub2f7\uac00\uc5d0 \uc6c0\uc9d1\uc744 \uc9d3\uace0 \uc815\ucc29 \uc0dd\ud65c\uc744 \ud558\uba70 \ub18d\uacbd\uacfc \ubaa9\ucd95\xb7\uc5b4\ub85c\ub97c \ubcd1\ud589\ud558\uc600\ub2e4. \uc6b0\uacbd \ubcf4\uae09\uacfc \ubcbc\ub18d\uc0ac \ud655\ub300, \ucca0\uc81c \ub18d\uae30\uad6c \ubcf4\uae09\uc740 \ud6e8\uc52c \ud6c4\ub300(\ucca0\uae30~\uc0bc\uad6d\uc2dc\ub300 \uc774\ud6c4)\uc758 \uc77c\uc774\ub2e4.",B.a9Y,B.a53,null)
B.aFc=s(["\uace1\uc2dd\uc744 \uc800\uc7a5\xb7\uc870\ub9ac\ud558\uace0 \uc2e4\uc744 \ubf51\uc544 \uc637\uac10\uc744 \uc9dc\ub294 \ub4f1 \uc815\ucc29 \uc0dd\ud65c\uc774 \ubc1c\uc804\ud558\uc600\ub2e4","\uccad\ub3d9 \ubb34\uae30\ub97c \ud65c\uc6a9\ud55c \uc815\ubcf5 \uc804\uc7c1\uc73c\ub85c \uacc4\uae09 \ubd84\ud654\uac00 \ucd09\uc9c4\ub418\uc5c8\ub2e4","\ud55c\uacfc\uc758 \uad50\uc5ed\uc744 \ud1b5\ud574 \uba85\ub3c4\uc804 \ub4f1 \uc911\uad6d \ud654\ud3d0\uac00 \uc720\uc785\ub418\uc5c8\ub2e4","\uace0\uc778\ub3cc \uac74\ub9bd\uc744 \ud1b5\ud574 \uc9c0\ubc30\uce35\uc758 \uad8c\uc704\ub97c \uacfc\uc2dc\ud558\uc600\ub2e4","\ubd88\uad50\uc640 \uc720\uad50 \uc0ac\uc0c1\uc774 \uc218\uc6a9\ub418\uc5b4 \ud1b5\uce58 \uc774\ub150\uc73c\ub85c \ud65c\uc6a9\ub418\uc5c8\ub2e4"],t.s)
B.bd2=s(["\uace1\uc2dd\uc744 \uc800\uc7a5\xb7\uc870\ub9ac\ud558\uace0 \uc2e4\uc744 \ubf51\uc544 \uc637\uac10\uc744 \uc9dc\ub294 \ub4f1 \uc815\ucc29 \uc0dd\ud65c\uc774 \ubc1c\uc804\ud558\uc600\ub2e4"],t.s)
B.az6=s(["\uc2e0\uc11d\uae30\uc2dc\ub300 \ub300\ud45c \uc720\ubb3c\uacfc \uc0dd\ud65c\uc0c1"],t.s)
B.bwO=new A.a("gen_kh_prehist_6","korean_history","\uc120\uc0ac\xb7\uace0\ub300","\uad6c\uc11d\uae30\xb7\uc2e0\uc11d\uae30\uc2dc\ub300",'\ub2e4\uc74c \uc720\ubb3c\uc744 \ud1b5\ud574 \uc54c \uc218 \uc788\ub294 \uc2dc\ub300\uc0c1\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?\n\n"\ube57\uc0b4\ubb34\ub2ac \ud1a0\uae30, \uac00\ub77d\ubc14\ud034, \uac08\ub3cc\uacfc \uac08\ud310"',B.aFc,0,"\ube57\uc0b4\ubb34\ub2ac \ud1a0\uae30(\uc800\uc7a5\xb7\uc870\ub9ac), \uac00\ub77d\ubc14\ud034(\uc2e4 \ubf51\uae30), \uac08\ub3cc\uacfc \uac08\ud310(\uace1\uc2dd \uac00\uacf5)\uc740 \ubaa8\ub450 \uc2e0\uc11d\uae30\uc2dc\ub300\uc758 \uc815\ucc29 \uc0dd\ud65c\uacfc \ucd08\uae30 \ub18d\uacbd\uc744 \ubcf4\uc5ec\uc8fc\ub294 \uc720\ubb3c\uc774\ub2e4. \uccad\ub3d9 \ubb34\uae30\xb7\uacc4\uae09 \ubd84\ud654\xb7\uace0\uc778\ub3cc\uc740 \uccad\ub3d9\uae30\uc2dc\ub300, \uc911\uad6d \ud654\ud3d0 \uc720\uc785\uc740 \ucca0\uae30\uc2dc\ub300, \ubd88\uad50\xb7\uc720\uad50 \uc218\uc6a9\uc740 \uc0bc\uad6d\uc2dc\ub300 \uc774\ud6c4\uc758 \ud2b9\uc9d5\uc774\ub2e4.",B.bd2,B.az6,null)
B.bfS=s(["\ub18d\uc5c5 \uc0dd\uc0b0\ub825\uc774 \ub298\uc5b4\ub098\uba74\uc11c \uc0ac\uc720 \uc7ac\uc0b0\uacfc \uacc4\uae09\uc774 \ubc1c\uc0dd\ud558\uc600\ub2e4","\uc528\uc871\uc744 \ub2e8\uc704\ub85c \ud55c \ud3c9\ub4f1\ud55c \uacf5\ub3d9\uccb4 \uc0dd\ud65c\uc774 \uc720\uc9c0\ub418\uc5c8\ub2e4","\uc911\uad6d \ud654\ud3d0\uc778 \ubc18\ub7c9\uc804\uacfc \uba85\ub3c4\uc804\uc774 \ud65c\ubc1c\ud788 \uc720\ud1b5\ub418\uc5c8\ub2e4","\ucca0\uc81c \ubb34\uae30\uac00 \ubcf4\uae09\ub418\uc5b4 \uc815\ubcf5 \uc804\uc7c1\uc774 \ubcf8\uaca9\ud654\ub418\uc5c8\ub2e4","\ud55c\uc790\uac00 \uc804\ub798\ub418\uc5b4 \uc9c0\ubc30\uce35\uc758 \ubb38\uc790 \uc0dd\ud65c\uc774 \uc2dc\uc791\ub418\uc5c8\ub2e4"],t.s)
B.aNH=s(["\ub18d\uc5c5 \uc0dd\uc0b0\ub825\uc774 \ub298\uc5b4\ub098\uba74\uc11c \uc0ac\uc720 \uc7ac\uc0b0\uacfc \uacc4\uae09\uc774 \ubc1c\uc0dd\ud558\uc600\ub2e4"],t.s)
B.Wj=s(["\uccad\ub3d9\uae30\uc2dc\ub300 \uc0ac\ud68c \ubcc0\ud654"],t.s)
B.bO0=new A.a("gen_kh_prehist_7","korean_history","\uc120\uc0ac\xb7\uace0\ub300","\uccad\ub3d9\uae30\xb7\ucca0\uae30\uc2dc\ub300",'\ub2e4\uc74c \uc720\ubb3c\uc774 \ucc98\uc74c \ub4f1\uc7a5\ud55c \uc2dc\ub300\uc758 \uc0ac\ud68c \ubaa8\uc2b5\uc73c\ub85c \uc633\uc740 \uac83\uc740?\n\n"\ube44\ud30c\ud615 \ub3d9\uac80, \ubc18\ub2ec \ub3cc\uce7c, \ubbfc\ubb34\ub2ac \ud1a0\uae30"',B.bfS,0,"\ube44\ud30c\ud615 \ub3d9\uac80\xb7\ubc18\ub2ec \ub3cc\uce7c\xb7\ubbfc\ubb34\ub2ac \ud1a0\uae30\ub294 \uccad\ub3d9\uae30\uc2dc\ub300\uc758 \ub300\ud45c \uc720\ubb3c\uc774\ub2e4. \uccad\ub3d9\uae30\uc2dc\ub300\uc5d0\ub294 \ub18d\uc5c5 \uc0dd\uc0b0\ub825 \uc99d\ub300\ub85c \uc789\uc5ec \uc0dd\uc0b0\ubb3c\uc774 \uc0dd\uae30\uba74\uc11c \uc0ac\uc720 \uc7ac\uc0b0 \uac1c\ub150\uacfc \uacc4\uae09\uc774 \ubc1c\uc0dd\ud558\uc600\uace0, \uc774\ub294 \uace0\uc778\ub3cc \ub4f1 \uc9c0\ubc30\uce35 \ubb34\ub364\uc744 \ud1b5\ud574\uc11c\ub3c4 \ud655\uc778\ub41c\ub2e4. \uc911\uad6d \ud654\ud3d0 \uc720\ud1b5\uacfc \ucca0\uc81c \ubb34\uae30 \ubcf4\uae09\uc740 \ucca0\uae30\uc2dc\ub300\uc758 \ud2b9\uc9d5\uc774\ub2e4.",B.aNH,B.Wj,null)
B.aZP=s(["\uc911\uad6d\uacfc\uc758 \uad50\uc5ed\uc73c\ub85c \uba85\ub3c4\uc804, \ubc18\ub7c9\uc804 \ub4f1\uc758 \ud654\ud3d0\uac00 \uad6d\ub0b4\uc5d0 \uc720\uc785\ub418\uc5c8\ub2e4","\uac00\ub77d\ubc14\ud034\ub97c \uc774\uc6a9\ud574 \ucc98\uc74c\uc73c\ub85c \uc637\uac10\uc744 \uc9dc\uae30 \uc2dc\uc791\ud558\uc600\ub2e4","\uac70\uce5c\ubb34\ub2ac \uac70\uc6b8\uc774 \uc9c0\ubc30\uce35\uc758 \uc758\ub840 \ub3c4\uad6c\ub85c \ucc98\uc74c \uc0ac\uc6a9\ub418\uc5c8\ub2e4","\uace0\uc778\ub3cc\uc774 \ucc98\uc74c \uac74\ub9bd\ub418\uc5b4 \uc9c0\ubc30\uce35\uc758 \uad8c\uc704\ub97c \ub098\ud0c0\ub0b4\uc5c8\ub2e4","\uc8fc\uba39\ub3c4\ub07c \ub4f1 \ub5c0\uc11d\uae30\uac00 \uc0ac\ub0e5\uc758 \uc8fc\ub41c \ub3c4\uad6c\ub85c \uc0ac\uc6a9\ub418\uc5c8\ub2e4"],t.s)
B.b3N=s(["\uc911\uad6d\uacfc\uc758 \uad50\uc5ed\uc73c\ub85c \uba85\ub3c4\uc804, \ubc18\ub7c9\uc804 \ub4f1\uc758 \ud654\ud3d0\uac00 \uad6d\ub0b4\uc5d0 \uc720\uc785\ub418\uc5c8\ub2e4"],t.s)
