B.bDU=new A.a("gen_kh_prehist_8","korean_history","\uc120\uc0ac\xb7\uace0\ub300","\uccad\ub3d9\uae30\xb7\ucca0\uae30\uc2dc\ub300","\ucca0\uae30\uc2dc\ub300\uc758 \ubaa8\uc2b5\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aZP,0,"\ucca0\uae30\uc2dc\ub300\uc5d0\ub294 \uc911\uad6d\uacfc\uc758 \uad50\ub958\uac00 \ud65c\ubc1c\ud574\uc9c0\uba74\uc11c \uba85\ub3c4\uc804\xb7\ubc18\ub7c9\uc804 \ub4f1 \uc911\uad6d \ud654\ud3d0\uac00 \uc720\uc785\ub418\uc5b4 \ub2f9\uc2dc \uc911\uad6d\uacfc\uc758 \uad50\uc5ed \uad00\uacc4\ub97c \ubcf4\uc5ec\uc900\ub2e4. \uac00\ub77d\ubc14\ud034\ub294 \uc2e0\uc11d\uae30, \uac70\uce5c\ubb34\ub2ac \uac70\uc6b8\uacfc \uace0\uc778\ub3cc\uc740 \uccad\ub3d9\uae30, \ub5c0\uc11d\uae30\ub294 \uad6c\uc11d\uae30\uc2dc\ub300\uc758 \ud2b9\uc9d5\uc774\ub2e4.",B.b3N,B.aZ6,null)
B.b8b=s([u.iD,"\uc528\uc871 \uacf5\ub3d9\uccb4\uac00 \ud568\uaed8 \uc0ac\uc6a9\ud55c \ud3c9\ub4f1\ud55c \uacf5\ub3d9 \ubb34\ub364\uc774\ub2e4","\ubd88\uad50\uc758 \uc804\ub798\uc640 \ud568\uaed8 \ub9cc\ub4e4\uc5b4\uc9c0\uae30 \uc2dc\uc791\ud55c \ubb34\ub364 \uc591\uc2dd\uc774\ub2e4","\uc8fc\ub85c \uc774\ub3d9 \uc0dd\ud65c\uc744 \ud558\ub358 \uad6c\uc11d\uae30\uc778\ub4e4\uc774 \uc0ac\uc6a9\ud55c \uc784\uc2dc \ub9e4\uc7a5 \uc2dc\uc124\uc774\ub2e4","\uc911\uad6d\uc758 \uc601\ud5a5\uc744 \ubc1b\uc544 \uc0bc\uad6d\uc2dc\ub300\uc5d0 \ucc98\uc74c \ub4f1\uc7a5\ud55c \ubb34\ub364 \uc591\uc2dd\uc774\ub2e4"],t.s)
