B.bBm=new A.a("gen_kh_prehist_9","korean_history","\uc120\uc0ac\xb7\uace0\ub300","\uccad\ub3d9\uae30\xb7\ucca0\uae30\uc2dc\ub300","\uccad\ub3d9\uae30\uc2dc\ub300 \uace0\uc778\ub3cc\uc5d0 \ub300\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.b8b,0,"\uace0\uc778\ub3cc\uc740 \uac70\ub300\ud55c \ub36e\uac1c\ub3cc\uc744 \uc62e\uae30\uace0 \uc138\uc6b0\ub294 \ub370 \ub9ce\uc740 \ub178\ub3d9\ub825\uc774 \ud544\uc694\ud588\uae30 \ub54c\ubb38\uc5d0, \uc774\ub97c \uc8fc\ub3c4\ud560 \uc218 \uc788\uc5c8\ub358 \uc9c0\ubc30\uce35\uc758 \uad8c\ub825\uacfc \uccad\ub3d9\uae30\uc2dc\ub300 \uacc4\uae09 \uc0ac\ud68c\uc758 \uc131\ub9bd\uc744 \ubcf4\uc5ec\uc8fc\ub294 \ub300\ud45c\uc801 \uc720\uc801\uc774\ub2e4.",B.aTz,B.b9E,null)
B.bac=s(["\ubc18\ub2ec \ub3cc\uce7c\ub85c \ubcbc \uc774\uc0ad\uc744 \uc790\ub974\ub294 \ub4f1 \ubcbc\ub18d\uc0ac\uac00 \ubcf8\uaca9\uc801\uc73c\ub85c \ud655\uc0b0\ub418\uc5c8\ub2e4","\ubf08\ubc14\ub298\uacfc \uac00\ub77d\ubc14\ud034\ub97c \uc774\uc6a9\ud574 \ucc98\uc74c\uc73c\ub85c \uc637\uac10\uc744 \uc9dc\uae30 \uc2dc\uc791\ud558\uc600\ub2e4","\ucca0\uc81c \ub18d\uae30\uad6c \ubcf4\uae09\uc73c\ub85c \uae4a\uc774\uac08\uc774\uac00 \uac00\ub2a5\ud574\uc838 \uc0dd\uc0b0\ub825\uc774 \uae09\uc99d\ud558\uc600\ub2e4","\uc6b0\uacbd\uc774 \ub110\ub9ac \ubcf4\uae09\ub418\uc5b4 \uc18c\ub97c \uc774\uc6a9\ud55c \ub18d\uc0ac\uac00 \uc77c\ubc18\ud654\ub418\uc5c8\ub2e4","\uc911\uad6d \ud654\ud3d0\ub97c \ub9e4\uac1c\ub85c \ud55c \uad50\uc5ed\uc774 \uacbd\uc81c\uc758 \uc911\uc2ec\uc744 \uc774\ub8e8\uc5c8\ub2e4"],t.s)
B.aU5=s(["\ubc18\ub2ec \ub3cc\uce7c\ub85c \ubcbc \uc774\uc0ad\uc744 \uc790\ub974\ub294 \ub4f1 \ubcbc\ub18d\uc0ac\uac00 \ubcf8\uaca9\uc801\uc73c\ub85c \ud655\uc0b0\ub418\uc5c8\ub2e4"],t.s)
B.b3y=s(["\uccad\ub3d9\uae30\uc2dc\ub300 \ub18d\uacbd\uc758 \ubc1c\ub2ec"],t.s)
B.bJv=new A.a("gen_kh_prehist_10","korean_history","\uc120\uc0ac\xb7\uace0\ub300","\uccad\ub3d9\uae30\xb7\ucca0\uae30\uc2dc\ub300","\uccad\ub3d9\uae30\uc2dc\ub300\uc758 \uacbd\uc81c \uc0dd\ud65c\uc5d0 \ub300\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.bac,0,"\uccad\ub3d9\uae30\uc2dc\ub300\uc5d0\ub294 \ubc18\ub2ec \ub3cc\uce7c\uacfc \uac19\uc740 \ub18d\uae30\uad6c\ub97c \uc774\uc6a9\ud574 \ubcbc\ub18d\uc0ac\uac00 \ud655\uc0b0\ub418\uba70 \uc789\uc5ec \uc0dd\uc0b0\ubb3c\uc774 \ub298\uc5b4\ub0ac\ub2e4. \ubf08\ubc14\ub298\xb7\uac00\ub77d\ubc14\ud034\ub294 \uc2e0\uc11d\uae30, \ucca0\uc81c \ub18d\uae30\uad6c\xb7\uc6b0\uacbd \ubcf4\uae09\uc740 \ucca0\uae30\uc2dc\ub300 \uc774\ud6c4, \uc911\uad6d \ud654\ud3d0 \uad50\uc5ed\uc740 \ucca0\uae30\uc2dc\ub300\uc758 \ud2b9\uc9d5\uc774\ub2e4.",B.aU5,B.b3y,null)
B.aFy=s([u.c8,"\ub5c0\uc11d\uae30 \uc911\uc2ec\uc758 \ub3c4\uad6c \uccb4\uacc4\uac00 \uac04\uc11d\uae30 \uc911\uc2ec\uc73c\ub85c \uc804\ud658\ub418\uc5c8\ub2e4","\ubb34\ub9ac\ub97c \uc774\ub8ec \uc774\ub3d9 \uc0dd\ud65c\uc5d0\uc11c \uc815\ucc29 \uc0dd\ud65c\ub85c \ucc98\uc74c \uc804\ud658\ub418\uc5c8\ub2e4","\uad70\uc7a5 \uad6d\uac00\uac00 \ucc98\uc74c\uc73c\ub85c \ub4f1\uc7a5\ud558\uc5ec \uacc4\uae09 \uc0ac\ud68c\uac00 \uc131\ub9bd\ub418\uc5c8\ub2e4","\ud1a0\ud14c\ubbf8\uc998\xb7\uc560\ub2c8\ubbf8\uc998 \ub4f1 \uc6d0\uc2dc \uc2e0\uc559\uc774 \ucc98\uc74c\uc73c\ub85c \ub098\ud0c0\ub0ac\ub2e4"],t.s)
B.bbc=s([u.c8],t.s)
B.abF=s(["\uccad\ub3d9\uae30 \ubb38\ud654\uc758 \ub3c5\uc790\uc801 \ubc1c\uc804"],t.s)
B.bGj=new A.a("gen_kh_prehist_11","korean_history","\uc120\uc0ac\xb7\uace0\ub300","\uccad\ub3d9\uae30\xb7\ucca0\uae30\uc2dc\ub300","\uccad\ub3d9\uae30\uc2dc\ub300\uc5d0\uc11c \ucca0\uae30\uc2dc\ub300\ub85c \ub118\uc5b4\uac00\uba70 \ub098\ud0c0\ub09c \ubcc0\ud654\ub85c \uc633\uc740 \uac83\uc740?",B.aFy,0,"\ucca0\uae30\uc2dc\ub300\uc5d0\ub294 \uc138\ud615 \ub3d9\uac80\uacfc \uac70\ud478\uc9d1(\uc794\ubb34\ub2ac \uac70\uc6b8 \ub4f1)\uc744 \ud1b5\ud574 \ub3c5\uc790\uc801\uc778 \uccad\ub3d9\uae30 \ubb38\ud654\uac00 \ub354\uc6b1 \ubc1c\uc804\ud558\ub294 \ud55c\ud3b8, \ucca0\uc81c \ubb34\uae30\xb7\ub18d\uae30\uad6c\uac00 \ubcf4\uae09\ub418\uc5c8\ub2e4. \ub5c0\uc11d\uae30\u2192\uac04\uc11d\uae30 \uc804\ud658\uc740 \uad6c\uc11d\uae30\u2192\uc2e0\uc11d\uae30, \uc815\ucc29 \uc0dd\ud65c \uc2dc\uc791\uc740 \uc2e0\uc11d\uae30, \uad70\uc7a5 \uad6d\uac00 \ub4f1\uc7a5\uc740 \uccad\ub3d9\uae30\uc2dc\ub300\uc758 \ubcc0\ud654\uc774\ub2e4.",B.bbc,B.abF,null)
B.aQC=s(["\uc911\uad6d\uacfc\uc758 \uad50\ub958\uac00 \ud65c\ubc1c\ud574\uc9c0\uba70 \ud55c\uc790\uc640 \ud654\ud3d0 \ub4f1 \uc120\uc9c4 \ubb38\ubb3c\uc774 \uc720\uc785\ub418\uc5c8\ub2e4","\uace0\uc778\ub3cc\uc774 \ucc98\uc74c\uc73c\ub85c \ub9cc\ub4e4\uc5b4\uc838 \uc9c0\ubc30\uce35\uc758 \uad8c\uc704\ub97c \uc0c1\uc9d5\ud558\uc600\ub2e4","\ube57\uc0b4\ubb34\ub2ac \ud1a0\uae30\ub97c \uc774\uc6a9\ud574 \uace1\uc2dd\uc744 \uc800\uc7a5\ud558\ub294 \uc0dd\ud65c\uc774 \uc2dc\uc791\ub418\uc5c8\ub2e4","\uc8fc\uba39\ub3c4\ub07c\ub97c \uc774\uc6a9\ud55c \uc0ac\ub0e5\uacfc \ucc44\uc9d1\uc774 \uacbd\uc81c\uc0dd\ud65c\uc758 \uc911\uc2ec\uc774\uc5c8\ub2e4","\ubc18\ub2ec \ub3cc\uce7c\uc744 \uc774\uc6a9\ud55c \ubcbc\ub18d\uc0ac\uac00 \ucc98\uc74c \uc2dc\uc791\ub418\uc5c8\ub2e4"],t.s)
B.b2_=s(["\uc911\uad6d\uacfc\uc758 \uad50\ub958\uac00 \ud65c\ubc1c\ud574\uc9c0\uba70 \ud55c\uc790\uc640 \ud654\ud3d0 \ub4f1 \uc120\uc9c4 \ubb38\ubb3c\uc774 \uc720\uc785\ub418\uc5c8\ub2e4"],t.s)
B.aia=s(["\ucca0\uae30\uc2dc\ub300 \ubb34\ub364 \uc591\uc2dd\uacfc \ub300\uc678 \uad50\ub958"],t.s)
B.bDr=new A.a("gen_kh_prehist_12","korean_history","\uc120\uc0ac\xb7\uace0\ub300","\uccad\ub3d9\uae30\xb7\ucca0\uae30\uc2dc\ub300",'\ub2e4\uc74c \ubb34\ub364 \uc591\uc2dd\uc774 \ub4f1\uc7a5\ud55c \uc2dc\ub300\uc5d0 \ub300\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?\n\n"\ucca0\uae30\uc2dc\ub300\uc5d0\ub294 \ub110\ubb34\ub364\uacfc \ub3c5\ubb34\ub364\uc774 \uc0c8\ub85c\uc6b4 \ubb34\ub364 \uc591\uc2dd\uc73c\ub85c \ub098\ud0c0\ub0ac\ub2e4."',B.aQC,0,"\ucca0\uae30\uc2dc\ub300\uc5d0\ub294 \ub110\ubb34\ub364\xb7\ub3c5\ubb34\ub364 \ub4f1 \uc0c8\ub85c\uc6b4 \ubb34\ub364 \uc591\uc2dd\uc774 \ub4f1\uc7a5\ud558\ub294 \ud55c\ud3b8, \uc911\uad6d\uacfc\uc758 \uad50\ub958\uac00 \ud65c\ubc1c\ud574\uc9c0\uba74\uc11c \ud55c\uc790\uc640 \uba85\ub3c4\uc804 \ub4f1\uc758 \ud654\ud3d0\uac00 \uc720\uc785\ub418\uc5c8\ub2e4. \uace0\uc778\ub3cc\uc740 \uccad\ub3d9\uae30, \ube57\uc0b4\ubb34\ub2ac \ud1a0\uae30\ub294 \uc2e0\uc11d\uae30, \uc8fc\uba39\ub3c4\ub07c\ub294 \uad6c\uc11d\uae30, \ubc18\ub2ec \ub3cc\uce7c\uc744 \uc774\uc6a9\ud55c \ubcbc\ub18d\uc0ac \uc2dc\uc791\uc740 \uccad\ub3d9\uae30\uc2dc\ub300\uc758 \ud2b9\uc9d5\uc774\ub2e4.",B.b2_,B.aia,null)
B.a7J=s([u.bP,"\ubaa8\ub4e0 \ubc94\uc8c4\uc790\ub97c \uc2e0\ubd84\uc5d0 \uad00\uacc4\uc5c6\uc774 \ub3d9\uc77c\ud558\uac8c \ucc98\ubc8c\ud558\ub294 \ud3c9\ub4f1 \uc0ac\ud68c\uc758 \uc6d0\ub9ac\ub97c \ub2f4\uace0 \uc788\ub2e4","\ubd88\uad50\uc758 \uacc4\uc728\uc5d0 \ub530\ub77c \uc0b4\uc0dd\uacfc \ub3c4\ub451\uc9c8\uc744 \uc5c4\uaca9\ud788 \uae08\uc9c0\ud55c \uc885\uad50\uc801 \uaddc\ubc94\uc774\ub2e4","\uc911\uad6d \ud55c\ub098\ub77c\uc758 \uc728\ub839\uc744 \uadf8\ub300\ub85c \uc218\uc6a9\ud558\uc5ec \uc81c\uc815\ud55c \uc131\ubb38 \ubc95\uc804\uc774\ub2e4","\ud654\ubc31 \ud68c\uc758\uc758 \ub9cc\uc7a5\uc77c\uce58\uc81c\ub97c \uba85\ubb38\ud654\ud55c \ud569\uc758 \uaddc\ubc94\uc774\ub2e4"],t.s)
B.b5X=s([u.bP],t.s)
B.b2w=s(["8\uc870\ubc95\uc758 \ub0b4\uc6a9\uacfc \uc758\ubbf8"],t.s)
B.bPe=new A.a("gen_kh_prehist_13","korean_history","\uc120\uc0ac\xb7\uace0\ub300","\uace0\uc870\uc120","\uace0\uc870\uc120\uc758 \uc0ac\ud68c \ubaa8\uc2b5\uc744 \ubcf4\uc5ec\uc8fc\ub294 8\uc870\ubc95\uc5d0 \ub300\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.a7J,0,"\uace0\uc870\uc120\uc758 8\uc870\ubc95 \uc911 \uc804\ud558\ub294 3\uac1c \uc870\ud56d\uc5d0\ub294 \uc0ac\ub78c\uc744 \uc8fd\uc778 \uc790\ub294 \uc989\uc2dc \uc0ac\ud615\uc5d0 \ucc98\ud558\uace0, \ub0a8\uc5d0\uac8c \uc0c1\ud574\ub97c \uc785\ud78c \uc790\ub294 \uace1\uc2dd\uc73c\ub85c \ubc30\uc0c1\ud558\uba70, \ub3c4\ub451\uc9c8\ud55c \uc790\ub294 \ub178\ube44\ub85c \uc0bc\ub294\ub2e4\ub294 \ub0b4\uc6a9\uc774 \uc788\uc5b4 \uc0dd\uba85\xb7\uc0ac\uc720 \uc7ac\uc0b0 \ubcf4\ud638\uc640 \ub178\ube44(\uacc4\uae09)\uc758 \uc874\uc7ac\ub97c \uc54c \uc218 \uc788\ub2e4.",B.b5X,B.b2w,null)
B.aRI=s(["\uc704\ub9cc\uc774 \ubb34\ub9ac\ub97c \uc774\ub04c\uace0 \uace0\uc870\uc120\uc5d0 \ub9dd\uba85\ud558\uc5ec \uc900\uc655\uc758 \uc2e0\uc784\uc744 \uc5bb\uc5c8\ub2e4","\ub2e8\uad70\uc655\uac80\uc774 \uc544\uc0ac\ub2ec\uc5d0 \ub3c4\uc74d\ud558\uc5ec \uace0\uc870\uc120\uc744 \uac74\uad6d\ud558\uc600\ub2e4","\uc6b0\uac70\uc655\uc774 \uc9c4\ubc88\uacfc \uc784\ub454\uc744 \ubcf5\uc18d\uc2dc\ucf1c \uc138\ub825\uc744 \ud655\uc7a5\ud558\uc600\ub2e4","\ud55c \ubb34\uc81c\uac00 \uace0\uc870\uc120\uc744 \uce68\uacf5\ud558\uc5ec \uc655\uac80\uc131\uc744 \ud568\ub77d\uc2dc\ucf30\ub2e4","\uc744\ud30c\uc18c\uac00 \ub4f1\uc6a9\ub418\uc5b4 \uc9c4\ub300\ubc95\uc744 \uc2e4\uc2dc\ud558\uc600\ub2e4"],t.s)
