B.bHf=new A.a("gen_kh_js1_21","korean_history","\uc870\uc120\uc804\uae30","\ub300\uc678\uad00\uacc4\uc640 \uc784\uc9c4\uc65c\ub780","\uc784\uc9c4\uc65c\ub780 \uc911 \uc870\uc120\uc758 \ub300\uc751\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aNn,0,"\uc784\uc9c4\uc65c\ub780 \uc911\uc5d0\ub294 \uacfd\uc7ac\uc6b0\xb7\uc870\ud5cc \ub4f1\uc774 \uc774\ub044\ub294 \uc758\ubcd1\uc774 \uac01\uc9c0\uc5d0\uc11c \ubd09\uae30\ud558\uc5ec \ud5a5\ud1a0 \uc9c0\ub9ac\uc5d0 \uc775\uc219\ud55c \uc774\uc810\uc744 \uc0b4\ub824 \uc65c\uad70\uc5d0 \ub9de\uc130\uc73c\uba70, \uc774\ub294 \uad00\uad70\uc758 \uc5f4\uc138\ub97c \ubcf4\uc644\ud558\ub294 \ub370 \ud06c\uac8c \uae30\uc5ec\ud558\uc600\ub2e4. \uc870\uc120\uc740 \uba85\uc758 \uc6d0\uad70\uc744 \uc9c0\uc6d0\ubc1b\uc558\uc73c\uba70, \uc0bc\ubcc4\ucd08\xb7\ubcc4\ubb34\ubc18\xb7\uac15\ud654\ub3c4 \ucc9c\ub3c4\ub294 \uac01\uac01 \uace0\ub824 \uc2dc\ub300 \ubabd\uace8\xb7\uc5ec\uc9c4 \uad00\ub828 \uc0ac\uac74\uc774\ub2e4.",B.aZI,B.a1g,null)
B.b_u=s(["\ud3ec\uc218\xb7\uc0b4\uc218\xb7\uc0ac\uc218\uc758 \uc0bc\uc218\ubcd1\uc73c\ub85c \uad6c\uc131\ub41c \ud6c8\ub828\ub3c4\uac10\uc744 \uc124\uce58\ud558\uc600\ub2e4","\ubcc4\ubb34\ubc18\uc744 \ud3b8\uc131\ud558\uc5ec \uc5ec\uc9c4 \uc815\ubc8c\uc744 \uc900\ube44\ud558\uc600\ub2e4","2\uad70 6\uc704 \uccb4\uc81c\uc758 \uc911\uc559\uad70\uc744 \ucc98\uc74c\uc73c\ub85c \uc870\uc9c1\ud558\uc600\ub2e4","\uc0bc\ubcc4\ucd08\ub97c \ucc3d\uc124\ud558\uc5ec \uc655\uc2e4 \uce5c\uc704 \ubd80\ub300\ub85c \uc0bc\uc558\ub2e4","5\uad70\uc601 \ub300\uc2e0 5\uc704 \uccb4\uc81c\ub85c \ub418\ub3cc\uc544\uac14\ub2e4"],t.s)
B.U8=s(["\ud3ec\uc218\xb7\uc0b4\uc218\xb7\uc0ac\uc218\uc758 \uc0bc\uc218\ubcd1\uc73c\ub85c \uad6c\uc131\ub41c \ud6c8\ub828\ub3c4\uac10\uc744 \uc124\uce58\ud558\uc600\ub2e4"],t.s)
