B.bGE=new A.a("gen_kh_js2_22","korean_history","\uc870\uc120\ud6c4\uae30","\uc2e4\ud559\xb7\uc11c\ud559\uacfc \uc11c\ubbfc \ubb38\ud654","\ucd5c\uc81c\uc6b0\uac00 \ucc3d\uc2dc\ud55c \ub3d9\ud559\uc5d0 \ub300\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.bbv,0,"\ub3d9\ud559\uc740 \ucd5c\uc81c\uc6b0\uac00 \uc720\uad50\xb7\ubd88\uad50\xb7\ub3c4\uad50(\uc120)\uc758 \uc0ac\uc0c1\uc744 \uc808\ucda9\ud558\uace0 \uc0ac\ub78c\uc774 \uace7 \ud558\ub298\uc774\ub77c\ub294 \uc778\ub0b4\ucc9c \uc0ac\uc0c1\uc744 \ub0b4\uc138\uc6cc \ucc3d\uc2dc\ud55c \ubbfc\uc871 \uc885\uad50\ub85c, \uc11c\ud559(\ucc9c\uc8fc\uad50)\uc758 \ud655\uc0b0\uc5d0 \ub300\uc751\ud558\ub294 \uc131\uaca9\uc744 \uac00\uc9c0\uace0 \uc788\uc5c8\uc73c\uba70, \uc774\ud6c4 \uad50\uc870 \uc2e0\uc6d0 \uc6b4\ub3d9\uacfc \ub3d9\ud559 \ub18d\ubbfc \uc6b4\ub3d9\uc73c\ub85c \uc774\uc5b4\uc84c\ub2e4.",B.bc0,B.u8,null)
B.Re=s(["\ud55c\uae00 \uc18c\uc124\uacfc \ud310\uc18c\ub9ac, \ud0c8\ucda4 \ub4f1\uc774 \uc720\ud589\ud558\uba70 \uc11c\ubbfc\ub4e4\uc758 \uc0dd\ud65c \uac10\uc815\uc744 \ud45c\ud604\ud558\uc600\ub2e4","\ud55c\ubb38\ud559\uacfc \uc131\ub9ac\ud559 \uc911\uc2ec\uc758 \uc591\ubc18 \ubb38\ud654\ub9cc\uc774 \ubc1c\ub2ec\ud558\uc600\ub2e4","\uace0\ub824\uccad\uc790\uc640 \uac19\uc740 \uadc0\uc871\uc801 \uc608\uc220\ud488\uc774 \ub110\ub9ac \uc720\ud589\ud558\uc600\ub2e4","\uae08\uc18d \ud65c\uc790\ub97c \uc774\uc6a9\ud55c \ubd88\uacbd \uc778\uc1c4\uac00 \ubb38\ud654\uc758 \uc911\uc2ec\uc744 \uc774\ub8e8\uc5c8\ub2e4","\uc11c\uc6d0\uacfc \ud5a5\uc57d\uc744 \ud1b5\ud55c \uc0ac\ub9bc\uc758 \ud5a5\ucd0c \uc9c0\ubc30 \ubb38\ud654\uac00 \uc0c8\ub86d\uac8c \ub098\ud0c0\ub0ac\ub2e4"],t.s)
