B.bKi=new A.a("gen_cl_juridicalact_4","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c","\ubc95\ub960\ud589\uc704\uc758 \uc758\uc758\uc640 \uc885\ub958","\ubc95\ub960\ud589\uc704\uc758 \ubaa9\uc801(\ub0b4\uc6a9)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740? (\ub2e4\ud23c\uc774 \uc788\uc73c\uba74 \ud310\ub840\uc5d0 \ub530\ub984)",B.ahZ,0,"\ubc95\ub960\ud589\uc704\uc758 \ubaa9\uc801\uc740 \ubc95\ub960\ud589\uc704 \ub2f9\uc2dc\uc5d0 \ubc18\ub4dc\uc2dc \ud655\uc815\ub418\uc5b4 \uc788\uc744 \ud544\uc694\ub294 \uc5c6\uace0, \uc774\ud589\uae30\uae4c\uc9c0 \ud655\uc815\ud560 \uc218 \uc788\ub294 \ud45c\uc900\uc774 \uc815\ud574\uc838 \uc788\uc73c\uba74 \ucda9\ubd84\ud558\ub2e4(\ud655\uc815\uac00\ub2a5\uc131). \uc6d0\uc2dc\uc801 \ubd88\ub2a5\uc778 \uae09\ubd80\ub97c \ubaa9\uc801\uc73c\ub85c \ud558\ub294 \ubc95\ub960\ud589\uc704\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \ubb34\ud6a8\uc774\uba70, \uc120\ub7c9\ud55c \ud48d\uc18d \uae30\ud0c0 \uc0ac\ud68c\uc9c8\uc11c\uc5d0 \uc704\ubc18\ud558\ub294 \ubc95\ub960\ud589\uc704\ub3c4 \ub2f9\uc0ac\uc790\uc758 \ub3d9\uc758\uc640 \ubb34\uad00\ud558\uac8c \ubb34\ud6a8\uc774\ub2e4.",B.au_,B.aNN,null)
B.aDE=s([u.sb,"\uc218\uc0ac\uae30\uad00\uc5d0\uc11c \ucc38\uace0\uc778\uc73c\ub85c\uc11c \ud5c8\uc704 \uc9c4\uc220\uc758 \ub300\uac00\ub85c \uae08\uc804\uc744 \ubc1b\uae30\ub85c \ud55c \uc57d\uc815\uc740 \ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704\ub85c \ubb34\ud6a8\uc774\ub2e4","\ub3c4\ubc15\uc790\uae08\uc5d0 \uc81c\uacf5\ud560 \ubaa9\uc801\uc73c\ub85c \uc18c\ube44\ub300\ucc28\uacc4\uc57d\uc744 \uccb4\uacb0\ud55c \uacbd\uc6b0 \uc774\ub294 \ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704\ub85c \ubb34\ud6a8\uc774\ub2e4","\ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704\uc5d0 \ud574\ub2f9\ud558\ub294\uc9c0\ub294 \ubc95\ub960\ud589\uc704 \uc131\ub9bd \ub2f9\uc2dc\ub97c \uae30\uc900\uc73c\ub85c \ud310\ub2e8\ud55c\ub2e4","\ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704\ub85c \uc778\ud574 \uae09\ubd80\ud55c \uac83\uc740 \ubd88\ubc95\uc6d0\uc778\uae09\uc5ec\ub85c \ubc18\ud658\uc744 \uccad\uad6c\ud560 \uc218 \uc5c6\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub2e4"],t.s)
