B.bQZ=new A.a("gen_cl_juridicalact_6","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c","\ubc95\ub960\ud589\uc704\uc758 \uc758\uc758\uc640 \uc885\ub958","\ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704(\ubbfc\ubc95 \uc81c104\uc870)\uc758 \uc131\ub9bd\uc694\uac74\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740? (\ub2e4\ud23c\uc774 \uc788\uc73c\uba74 \ud310\ub840\uc5d0 \ub530\ub984)",B.ZP,0,"\ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704\uac00 \uc131\ub9bd\ud558\ub824\uba74 \uae09\ubd80\uc640 \ubc18\ub300\uae09\ubd80 \uc0ac\uc774\uc758 \ud604\uc800\ud55c \ubd88\uade0\ud615(\uac1d\uad00\uc801 \uc694\uac74)\uacfc \ud53c\ud574\uc790\uc758 \uad81\ubc15\xb7\uacbd\uc194\xb7\ubb34\uacbd\ud5d8 \ubc0f \uc0c1\ub300\ubc29\uc758 \ud3ed\ub9ac\uc758\uc0ac(\uc8fc\uad00\uc801 \uc694\uac74)\uac00 \ubaa8\ub450 \uac16\ucd94\uc5b4\uc838\uc57c \ud55c\ub2e4. \ud604\uc800\ud55c \ubd88\uade0\ud615\uc774 \uc5c6\ub2e4\uba74 \uc6d0\uce59\uc801\uc73c\ub85c \ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704\uac00 \uc131\ub9bd\ud558\uc9c0 \uc54a\ub294\ub2e4.",B.a10,B.ahS,null)
B.aF2=s([u.qo,"\ud45c\uc758\uc790\uac00 \uc9c4\uc758 \uc544\ub2d8\uc744 \uc54c\uace0 \ud55c \uc758\uc0ac\ud45c\uc2dc\ub294 \ud56d\uc0c1 \ubb34\ud6a8\uc774\ub2e4","\uc0c1\ub300\ubc29\uc774 \ud45c\uc758\uc790\uc758 \uc9c4\uc758 \uc544\ub2d8\uc744 \uc54c\uc558\uac70\ub098 \uc54c \uc218 \uc788\uc5c8\uc744 \uacbd\uc6b0\uc5d0\ub3c4 \uadf8 \uc758\uc0ac\ud45c\uc2dc\ub294 \uc720\ud6a8\ud558\ub2e4","\ube44\uc9c4\uc758\ud45c\uc2dc\ub294 \uc0c1\ub300\ubc29 \uc5c6\ub294 \ub2e8\ub3c5\ud589\uc704\uc5d0\ub3c4 \uadf8\ub300\ub85c \uc801\uc6a9\ub41c\ub2e4","\ube44\uc9c4\uc758\ud45c\uc2dc\uc758 \ubb34\ud6a8\ub294 \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c\ub3c4 \ub300\ud56d\ud560 \uc218 \uc788\ub2e4"],t.s)
