B.byw=new A.a("gen_cl_juridicalact_7","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c","\uc9c4\uc758 \uc544\ub2cc \uc758\uc0ac\ud45c\uc2dc\xb7\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc","\ube44\uc9c4\uc758\ud45c\uc2dc(\uc9c4\uc758 \uc544\ub2cc \uc758\uc0ac\ud45c\uc2dc)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740? (\ub2e4\ud23c\uc774 \uc788\uc73c\uba74 \ud310\ub840\uc5d0 \ub530\ub984)",B.aF2,0,"\ube44\uc9c4\uc758\ud45c\uc2dc\ub294 \ud45c\uc2dc\ub41c \ub300\ub85c \ud6a8\ub825\uc774 \ubc1c\uc0dd\ud558\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub098, \uc0c1\ub300\ubc29\uc774 \ud45c\uc758\uc790\uc758 \uc9c4\uc758 \uc544\ub2d8\uc744 \uc54c\uc558\uac70\ub098 \uc54c \uc218 \uc788\uc5c8\uc744 \uacbd\uc6b0\uc5d0\ub294 \uc608\uc678\uc801\uc73c\ub85c \ubb34\ud6a8\uac00 \ub41c\ub2e4. \ub2e4\ub9cc \uc774\ub7ec\ud55c \ubb34\ud6a8\ub294 \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c \ub300\ud56d\ud558\uc9c0 \ubabb\ud55c\ub2e4.",B.aQj,B.Xl,null)
B.a0_=s([u.xW,"\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\ub294 \uc0c1\ub300\ubc29\uc758 \ub3d9\uc758 \uc5c6\uc774 \ud45c\uc758\uc790 \ub2e8\ub3c5\uc73c\ub85c\ub3c4 \uc131\ub9bd\ud560 \uc218 \uc788\ub2e4","\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\uc758 \ubb34\ud6a8\ub294 \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c\ub3c4 \ub300\ud56d\ud560 \uc218 \uc788\ub2e4","\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\uc5d0 \uc758\ud55c \ucc44\ubb34\ub97c \ubcf4\uc99d\ud55c \uc790\ub294 \ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\uc758 \ubb34\ud6a8\ub97c \uc8fc\uc7a5\ud560 \uc218 \uc5c6\ub2e4","\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\ub294 \ucc29\uc624\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\uc640 \ub3d9\uc77c\ud558\uac8c \ucde8\uae09\ub41c\ub2e4"],t.s)
