B.afW=s(["\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\uc640 \uc804\ub4dd\uc790(\uc81c3\uc790) \ubcf4\ud638"],t.s)
B.bKf=new A.a("gen_cl_juridicalact_12","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c","\uc9c4\uc758 \uc544\ub2cc \uc758\uc0ac\ud45c\uc2dc\xb7\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc","\u7532\uacfc \u4e59\uc774 \ud1b5\uc815\ud558\uc5ec \u7532 \uc18c\uc720 \ubd80\ub3d9\uc0b0\uc744 \u4e59\uc5d0\uac8c \ud5c8\uc704\ub85c \ub9e4\ub3c4\ud55c \uac83\ucc98\ub7fc \ub4f1\uae30\ub97c \ub9c8\ucce4\ub294\ub370, \u4e59\uc774 \uc774\ub97c \u4e19\uc5d0\uac8c \ub9e4\ub3c4\ud558\uace0 \u4e19 \uba85\uc758\ub85c \ub4f1\uae30\ub97c \uc774\uc804\ud55c \uc0ac\uc548\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740? (\ub2e4\ud23c\uc774 \uc788\uc73c\uba74 \ud310\ub840\uc5d0 \ub530\ub984, \u4e19\uc740 \ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc \uc0ac\uc2e4\uc744 \ubab0\ub790\uc74c)",B.a85,0,"\u7532\uacfc \u4e59 \uc0ac\uc774\uc758 \ub9e4\ub9e4\ub294 \ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\ub85c \ubb34\ud6a8\uc774\uc9c0\ub9cc, \uadf8 \ubb34\ud6a8\ub294 \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c \ub300\ud56d\ud560 \uc218 \uc5c6\ub2e4. \u4e19\uc774 \ud5c8\uc704\ud45c\uc2dc \uc0ac\uc2e4\uc744 \ubaa8\ub978 \uc120\uc758\uc758 \uc81c3\uc790\ub77c\uba74 \u7532\uc740 \u4e19\uc5d0 \ub300\ud558\uc5ec \ubb34\ud6a8\ub97c \uc8fc\uc7a5\ud558\uc5ec \uc18c\uc720\uad8c\uc744 \ub418\ucc3e\uc744 \uc218 \uc5c6\ub2e4.",B.atM,B.afW,null)
B.b0J=s([u.vC,"\ucc29\uc624\uac00 \ud45c\uc758\uc790\uc758 \uc911\ub300\ud55c \uacfc\uc2e4\ub85c \uc778\ud55c \uac83\uc774\ub354\ub77c\ub3c4 \uc5b8\uc81c\ub098 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4","\ucc29\uc624\ub85c \uc778\ud55c \uc758\uc0ac\ud45c\uc2dc\uc758 \ucde8\uc18c\ub294 \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c\ub3c4 \ub300\ud56d\ud560 \uc218 \uc788\ub2e4","\ub3d9\uae30\uc758 \ucc29\uc624\ub294 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ubc95\ub960\ud589\uc704 \ucde8\uc18c \uc0ac\uc720\uac00 \ub420 \uc218 \uc5c6\ub2e4","\ucc29\uc624\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\ub294 \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \ub2f9\uc5f0 \ubb34\ud6a8\uc774\ub2e4"],t.s)
