B.bEK=new A.a("gen_cl_juridicalact_13","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c","\ucc29\uc624\xb7\uc0ac\uae30\xb7\uac15\ubc15\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc","\ucc29\uc624\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc(\ubbfc\ubc95 \uc81c109\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740? (\ub2e4\ud23c\uc774 \uc788\uc73c\uba74 \ud310\ub840\uc5d0 \ub530\ub984)",B.b0J,0,"\ubc95\ub960\ud589\uc704 \ub0b4\uc6a9\uc758 \uc911\uc694\ubd80\ubd84\uc5d0 \ucc29\uc624\uac00 \uc788\uc73c\uba74 \ud45c\uc758\uc790\ub294 \uadf8 \uc758\uc0ac\ud45c\uc2dc\ub97c \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \ud45c\uc758\uc790\uc5d0\uac8c \uc911\ub300\ud55c \uacfc\uc2e4\uc774 \uc788\ub294 \uacbd\uc6b0\uc5d0\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \ucde8\uc18c\ud560 \uc218 \uc5c6\uace0, \ucde8\uc18c\uc758 \ud6a8\uacfc\ub294 \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c \ub300\ud56d\ud560 \uc218 \uc5c6\ub2e4. \ub3d9\uae30\uc758 \ucc29\uc624\ub3c4 \uadf8 \ub3d9\uae30\uac00 \uc0c1\ub300\ubc29\uc5d0\uac8c \ud45c\uc2dc\ub418\uc5b4 \ubc95\ub960\ud589\uc704\uc758 \ub0b4\uc6a9\uc774 \ub41c \uacbd\uc6b0\uc5d0\ub294 \ucde8\uc18c \uc0ac\uc720\uac00 \ub420 \uc218 \uc788\ub2e4.",B.aEp,B.ajv,null)
B.YY=s([u.m_,"\ud1a0\uc9c0\ub9e4\ub9e4\uc5d0\uc11c \uc2dc\uac00\uc5d0 \uad00\ud55c \ucc29\uc624\ub294 \ud56d\uc0c1 \uc911\uc694\ubd80\ubd84\uc758 \ucc29\uc624\uc5d0 \ud574\ub2f9\ud55c\ub2e4","\uc911\uc694\ubd80\ubd84\uc758 \ucc29\uc624 \uc5ec\ubd80\ub294 \ud45c\uc758\uc790\uc758 \uc8fc\uad00\uc801 \uc0ac\uc815\ub9cc\uc744 \uae30\uc900\uc73c\ub85c \ud310\ub2e8\ud55c\ub2e4","\uc911\uc694\ubd80\ubd84\uc758 \ucc29\uc624\ub294 \ubc95\ub960\ud589\uc704\uc758 \ub3d9\uae30\uc5d0 \uad00\ud55c \ucc29\uc624\ub97c \uc81c\uc678\ud558\uace0\ub294 \uc778\uc815\ub420 \uc218 \uc5c6\ub2e4","\uc911\uc694\ubd80\ubd84\uc758 \ucc29\uc624\ub294 \uc0c1\ub300\ubc29\uc758 \uc778\uc2dd \uc5ec\ubd80\uc640 \uad00\uacc4\uc5c6\uc774 \ud56d\uc0c1 \ub3d9\uc77c\ud558\uac8c \ud310\ub2e8\ub41c\ub2e4"],t.s)
