B.bIM=new A.a("gen_cl_antisocial_4","civil_law","\ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704",null,"\ub3c4\ubc15\uc790\uae08\uc73c\ub85c \uc0ac\uc6a9\ud560 \uac83\uc744 \uc54c\uba74\uc11c \uae08\uc804\uc744 \ub300\uc5ec\ud55c \uc18c\ube44\ub300\ucc28\uacc4\uc57d\uc758 \ud6a8\ub825\uc740?",B.ac_,1,"\ub300\uc5ec\uc778\uc774 \ucc28\uc6a9\uae08\uc774 \ub3c4\ubc15\uc790\uae08\uc73c\ub85c \uc0ac\uc6a9\ub420 \uac83\uc784\uc744 \uc54c\uba74\uc11c\ub3c4 \uae08\uc804\uc744 \ub300\uc5ec\ud55c \uacbd\uc6b0, \uadf8 \uc18c\ube44\ub300\ucc28\uacc4\uc57d\uc740 \ub3d9\uae30\uc758 \ubd88\ubc95\uc774 \uc0c1\ub300\ubc29(\ucc28\uc6a9\uc778)\uc5d0\uac8c \uc54c\ub824\uc9c4 \uacbd\uc6b0\uc5d0 \ud574\ub2f9\ud558\uc5ec \ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704\ub85c\uc11c \ubb34\ud6a8\uc774\ub2e4.",B.ax4,B.QC,null)
