B.aPe=s(["\ubd80\ucca9\uad00\uacc4 \uc790\uccb4\uac00 \ubb34\ud6a8\uc774\ubbc0\ub85c \uc591\uc721\ube44 \uc57d\uc815\ub3c4 \ub2f9\uc5f0 \ubb34\ud6a8\uc774\ub2e4","\uc790\ub140 \uc591\uc721\ube44 \uc9c0\uae09 \uc57d\uc815 \uc790\uccb4\ub294 \uc720\ud6a8\ud560 \uc218 \uc788\ub2e4","\uc591\uc721\ube44 \uc57d\uc815\uc740 \ucde8\uc18c\uc0ac\uc720\uc5d0 \ud574\ub2f9\ud55c\ub2e4","\ubd80\ucca9\uad00\uacc4\uac00 \uc885\ub8cc\ub418\uc5b4\uc57c\ub9cc \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4"],t.s)
B.bdv=s(["\uc790\ub140\uc758 \uc591\uc721\ube44\ub97c \uc9c0\uae09\ud558\uae30\ub85c \ud55c \uc57d\uc815\uc740 \uc790\ub140\uc758 \ubcf5\ub9ac\ub97c \uc704\ud55c \uac83\uc73c\ub85c\uc11c \uadf8 \uc790\uccb4\ub85c \ubc18\uc0ac\ud68c\uc9c8\uc11c\uc5d0 \ud574\ub2f9\ud55c\ub2e4\uace0 \ubcfc \uc218 \uc5c6\uc5b4 \uc720\ud6a8"],t.s)
