B.Se=s(["\ub3d9\uae30\uc758 \ubd88\ubc95\uc744 \uc784\ub300\uc778\uc774 \uc778\uc2dd\ud55c \uacbd\uc6b0\uc5d0 \ud574\ub2f9\ud558\uc5ec \ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704\ub85c\uc11c \ubb34\ud6a8\uac00 \ub420 \uc218 \uc788\ub2e4"],t.s)
