B.b6I=s(["\uacc4\uc57d \ub2f9\uc0ac\uc790\uc5d0\uac8c\ub9cc \uc8fc\uc7a5\ud560 \uc218 \uc788\ub2e4","\uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c\ub294 \ub300\ud56d\ud560 \uc218 \uc5c6\ub2e4","\uc808\ub300\uc801 \ubb34\ud6a8\ub85c\uc11c \uc120\uc758\uc758 \uc81c3\uc790\ub97c \ud3ec\ud568\ud558\uc5ec \ub204\uad6c\uc5d0\uac8c\ub098 \uc8fc\uc7a5\ud560 \uc218 \uc788\ub2e4","\ub4f1\uae30\ub97c \ub9c8\uce5c \uc81c3\uc790\uc5d0\uac8c\ub294 \ub300\ud56d\ud560 \uc218 \uc5c6\ub2e4"],t.s)
B.b8C=s(["\uc808\ub300\uc801 \ubb34\ud6a8\uc774\ubbc0\ub85c","\uc120\uc758\uc758 \uc81c3\uc790\uc5d0 \ub300\ud55c \uad00\uacc4\uc5d0\uc11c\ub3c4 \uadf8 \ubb34\ud6a8\ub97c \uc8fc\uc7a5\ud560 \uc218 \uc788\ub2e4"],t.s)
