B.bpc=new A.a("gen_cl_antisocial_27","civil_law","\ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704",null,"\ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704\ub85c\uc11c \ubb34\ud6a8\uc778 \ucc44\uad8c\uc744 \ub2f4\ubcf4\ud558\uae30 \uc704\ud558\uc5ec \uc124\uc815\ub41c \uc800\ub2f9\uad8c\uc124\uc815\uacc4\uc57d\uc758 \ud6a8\ub825\uc740?",B.b_W,1,"\ub2f4\ubcf4\ubb3c\uad8c\uc740 \ud53c\ub2f4\ubcf4\ucc44\uad8c\uc5d0 \ub300\ud55c \ubd80\uc885\uc131\uc744 \uac00\uc9c0\ubbc0\ub85c, \ud53c\ub2f4\ubcf4\ucc44\uad8c \ubc1c\uc0dd\uc758 \uc6d0\uc778\uc774 \ub41c \ubc95\ub960\ud589\uc704 \uc790\uccb4\uac00 \ubc18\uc0ac\ud68c\uc9c8\uc11c\ub85c \ubb34\ud6a8\ub77c\uba74 \uc774\ub97c \ub2f4\ubcf4\ud558\uae30 \uc704\ud574 \uc124\uc815\ub41c \uc800\ub2f9\uad8c\uc124\uc815\uacc4\uc57d \uc5ed\uc2dc \ubb34\ud6a8\uac00 \ub41c\ub2e4.",B.b2G,B.azr,null)
B.a4J=s(["\uacbd\uc5c5\uae08\uc9c0\uc57d\uc815\uc740 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \uc720\ud6a8\ud558\ub2e4","\uae30\uac04\xb7\uc9c0\uc5ed\xb7\uc5c5\uc885 \ub4f1\uc758 \uc81c\ud55c\uc774 \ud569\ub9ac\uc801 \ubc94\uc704\ub97c \ud604\uc800\ud788 \ucd08\uacfc\ud558\uc5ec \uadfc\ub85c\uc790 \ub4f1\uc758 \uc0dd\uc874\uacfc \uc9c1\uc5c5\uc120\ud0dd\uc758 \uc790\uc720\ub97c \uacfc\ub3c4\ud558\uac8c \uc81c\uc57d\ud558\ub294 \uacbd\uc6b0 \ubc18\uc0ac\ud68c\uc9c8\uc11c \ud589\uc704\ub85c\uc11c \ubb34\ud6a8\uac00 \ub420 \uc218 \uc788\ub2e4","\uacbd\uc5c5\uae08\uc9c0\uc57d\uc815\uc740 \ud615\uc0ac\ucc98\ubc8c \ub300\uc0c1\uc77c \ubfd0 \uc0ac\ubc95\uc0c1 \ud6a8\ub825\uacfc\ub294 \ubb34\uad00\ud558\ub2e4","\uacbd\uc5c5\uae08\uc9c0\uc57d\uc815\uc740 \ub4f1\uae30\ud558\uc5ec\uc57c\ub9cc \ud6a8\ub825\uc774 \uc788\ub2e4"],t.s)
B.aJg=s(["\ud569\ub9ac\uc801 \ud55c\ub3c4\ub97c \ud604\uc800\ud788 \ucd08\uacfc\ud558\uc5ec","\uc0ac\ud68c\uc9c8\uc11c\uc5d0 \ubc18\ud558\uc5ec \ubb34\ud6a8\ub85c \ud310\ub2e8\ub420 \uc218 \uc788\ub2e4"],t.s)
B.b4R=s(["\uacbd\uc5c5\uae08\uc9c0\uc57d\uc815 \ubb34\ud6a8"],t.s)
B.bwR=new A.a("gen_cl_antisocial_28","civil_law","\ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704",null,"\uc9c0\ub098\uce58\uac8c \uc7a5\uae30\uac04 \ub610\ub294 \uc804\uba74\uc801\uc73c\ub85c \uc9c1\uc5c5\uc120\ud0dd\uc758 \uc790\uc720\ub97c \uc81c\ud55c\ud558\ub294 \uacbd\uc5c5\uae08\uc9c0\uc57d\uc815\uc758 \ud6a8\ub825\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.a4J,1,"\uacbd\uc5c5\uae08\uc9c0\uc57d\uc815\uc740 \uc601\uc5c5\uc0c1 \uc774\uc775 \ubcf4\ud638\ub97c \uc704\ud574 \uc6d0\uce59\uc801\uc73c\ub85c \ud5c8\uc6a9\ub418\uc9c0\ub9cc, \uadf8 \uae30\uac04\xb7\uc9c0\uc5ed\xb7\ub300\uc0c1 \uc5c5\ubb34\uc758 \ubc94\uc704\uac00 \ud569\ub9ac\uc801 \ud55c\ub3c4\ub97c \ud604\uc800\ud788 \ucd08\uacfc\ud558\uc5ec \uc0c1\ub300\ubc29\uc758 \uc9c1\uc5c5\uc120\ud0dd\uc758 \uc790\uc720\uc640 \uc0dd\uc874\uc744 \uacfc\ub3c4\ud558\uac8c \uc81c\uc57d\ud558\ub294 \uc815\ub3c4\uc5d0 \uc774\ub974\uba74 \uc120\ub7c9\ud55c \ud48d\uc18d \uae30\ud0c0 \uc0ac\ud68c\uc9c8\uc11c\uc5d0 \ubc18\ud558\uc5ec \ubb34\ud6a8\ub85c \ud310\ub2e8\ub420 \uc218 \uc788\ub2e4.",B.aJg,B.b4R,null)
B.amz=s(["\ubc95\ub960\ud589\uc704\uc758 \ub0b4\uc6a9","\ubc95\ub960\ud589\uc704\uac00 \uc774\ub8e8\uc5b4\uc9c0\uac8c \ub41c \ub3d9\uae30 \ubc0f \uacbd\uc704","\ubc95\ub960\ud589\uc704\ub85c \uc778\ud574 \uc2e4\ud604\ub418\ub294 \ud6a8\uacfc","\ubc95\ub960\ud589\uc704 \ub2f9\uc0ac\uc790\uc758 \uc7ac\uc0b0\uc138 \ub0a9\ubd80 \uc5ec\ubd80"],t.s)
B.aWK=s(["\ubc95\ub960\ud589\uc704\uc758 \ub0b4\uc6a9, \uadf8 \uc131\ub9bd \uacfc\uc815\uc5d0\uc11c\uc758 \ubd88\ubc95\uc801 \ubc29\ubc95\uc758 \uc0ac\uc6a9 \uc5ec\ubd80, \ub3d9\uae30, \ubaa9\uc801, \uc2e4\ud604\ub418\ub294 \ud6a8\uacfc \ub4f1\uc744 \uc885\ud569\uc801\uc73c\ub85c \uace0\ub824"],t.s)
B.avm=s(["\ud310\ub2e8 \uace0\ub824\uc694\uc18c"],t.s)
B.boc=new A.a("gen_cl_antisocial_29","civil_law","\ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704",null,"\ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704\uc778\uc9c0 \uc5ec\ubd80\ub97c \ud310\ub2e8\ud560 \ub54c \uace0\ub824\ud558\ub294 \uc694\uc18c\ub85c \uac00\uc7a5 \uac70\ub9ac\uac00 \uba3c \uac83\uc740?",B.amz,3,"\ud310\ub840\ub294 \ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704 \ud574\ub2f9 \uc5ec\ubd80\ub97c \ud310\ub2e8\ud560 \ub54c \ubc95\ub960\ud589\uc704\uc758 \ub0b4\uc6a9, \uadf8 \uc131\ub9bd \uacfc\uc815\uc5d0\uc11c\uc758 \ubd88\ubc95\uc801 \ubc29\ubc95\uc758 \uc0ac\uc6a9 \uc5ec\ubd80, \ub3d9\uae30, \ubaa9\uc801, \uc2e4\ud604\ub418\ub294 \ud6a8\uacfc \ub4f1\uc744 \uc885\ud569\uc801\uc73c\ub85c \uace0\ub824\ud55c\ub2e4. \ub2f9\uc0ac\uc790\uc758 \uc138\uae08 \ub0a9\ubd80 \uc5ec\ubd80\uc640 \uac19\uc740 \uc0ac\uc815\uc740 \uc774\uc640 \ubb34\uad00\ud55c \uc694\uc18c\uc774\ub2e4.",B.aWK,B.avm,null)
B.b30=s(["\ub300\ubb3c\ubcc0\uc81c\uc608\uc57d\uc740 \ud615\uc2dd\uc774 \uac16\ucd94\uc5b4\uc9c4 \uc774\uc0c1 \ud56d\uc0c1 \uc720\ud6a8\ud558\ub2e4","\ucc44\ubb34\uc561\uacfc \ub2f4\ubcf4\ubaa9\uc801\ubb3c \uac00\uc561\uc758 \ud604\uc800\ud55c \ubd88\uade0\ud615\uc774 \ud3ed\ub9ac\uc801\uc73c\ub85c \uc545\uc6a9\ub418\ub294 \uacbd\uc6b0 \ubc18\uc0ac\ud68c\uc9c8\uc11c \ub0b4\uc9c0 \ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704\ub85c \ubb34\ud6a8\uac00 \ub420 \uc218 \uc788\ub2e4","\ub4f1\uae30\uac00 \uc774\uc804\ub418\uba74 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ud6a8\ub825\uc744 \ub2e4\ud234 \uc218 \uc5c6\ub2e4","\ub300\ubb3c\ubcc0\uc81c\uc608\uc57d\uc740 \ucc44\ubb34\uc790\uc5d0\uac8c\ub9cc \ubd88\ub9ac\ud558\uba74 \ub2f9\uc5f0\ud788 \ucde8\uc18c\uc0ac\uc720\uac00 \ub41c\ub2e4"],t.s)
B.VG=s(["\ucc44\uad8c\uc790\uac00 \ubd80\ub2f9\ud55c \ud3ed\ub9ac\ub97c \ucde8\ud558\ub294 \uc218\ub2e8\uc73c\ub85c \uc545\uc6a9\ub418\ub294 \uacbd\uc6b0","\ubb34\ud6a8\ub85c \ud310\ub2e8\ub420 \uc218 \uc788\ub2e4"],t.s)
B.amH=s(["\ub300\ubb3c\ubcc0\uc81c\uc608\uc57d\uacfc \ud3ed\ub9ac"],t.s)
B.buH=new A.a("gen_cl_antisocial_30","civil_law","\ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704",null,"\ub300\ubb3c\ubcc0\uc81c\uc608\uc57d \uc790\uccb4\ub294 \uc720\ud6a8\ud558\ub354\ub77c\ub3c4, \uadf8 \uc608\uc57d\uc774 \ucc44\uad8c\uc790\uc758 \ud3ed\ub9ac \uc218\ub2e8\uc73c\ub85c \uc545\uc6a9\ub418\uc5b4 \ucc44\ubb34\uc561\uc5d0 \ube44\ud574 \ud604\uc800\ud788 \uace0\uac00\uc758 \ubd80\ub3d9\uc0b0\uc744 \ucde8\ub4dd\ud558\uac8c \ud558\ub294 \uacbd\uc6b0\uc758 \ubc95\uc801 \ud3c9\uac00\ub85c \uc633\uc740 \uac83\uc740?",B.b30,1,"\ub300\ubb3c\ubcc0\uc81c\uc608\uc57d \uc790\uccb4\ub294 \ub2f4\ubcf4 \ubaa9\uc801\uc758 \uc720\ud6a8\ud55c \uacc4\uc57d\ud615\uc2dd\uc774\uc9c0\ub9cc, \ucc44\ubb34\uc561\uc5d0 \ube44\ud558\uc5ec \ud604\uc800\ud788 \uace0\uac00\uc778 \ubaa9\uc801\ubb3c\uc744 \uc774\uc804\ubc1b\ub3c4\ub85d \ud558\uc5ec \ucc44\uad8c\uc790\uac00 \ubd80\ub2f9\ud55c \ud3ed\ub9ac\ub97c \ucde8\ud558\ub294 \uc218\ub2e8\uc73c\ub85c \uc545\uc6a9\ub418\ub294 \uacbd\uc6b0\uc5d0\ub294 \uc81c103\uc870 \ub610\ub294 \uc81c104\uc870 \uc704\ubc18\uc73c\ub85c \uadf8 \uc608\uc57d(\ub610\ub294 \uadf8\uc5d0 \ub530\ub978 \uc774\uc804\uc758 \ud6a8\ub825)\uc774 \ubb34\ud6a8\ub85c \ud310\ub2e8\ub420 \uc218 \uc788\ub2e4.",B.VG,B.amH,null)
B.b9B=s(["\ub300\ub9ac\uc778\uc774 \ub300\ub9ac\uad8c\uc758 \ubc94\uc704 \ub0b4\uc5d0\uc11c \ubcf8\uc778\uc744 \uc704\ud55c \uac83\uc784\uc744 \ud45c\uc2dc\ud558\uace0 \ud55c \uc758\uc0ac\ud45c\uc2dc\ub294 \uc9c1\uc811 \ubcf8\uc778\uc5d0\uac8c \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4","\ub300\ub9ac\ud589\uc704\uc758 \ud6a8\uacfc\ub294 \uc5b8\uc81c\ub098 \ub300\ub9ac\uc778\uc5d0\uac8c \uba3c\uc800 \uadc0\uc18d\ub41c \ud6c4 \ubcf8\uc778\uc5d0\uac8c \uc774\uc804\ub41c\ub2e4","\ub300\ub9ac\ud589\uc704\ub294 \ub300\ub9ac\uc778\uacfc \ubcf8\uc778\uc774 \ud568\uaed8 \uc11c\uba85\ud558\uc5ec\uc57c \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4","\ub300\ub9ac\ud589\uc704\uc758 \ud6a8\uacfc\ub294 \uc0c1\ub300\ubc29\uc758 \ub3d9\uc758\uac00 \uc788\uc5b4\uc57c \ubcf8\uc778\uc5d0\uac8c \uadc0\uc18d\ub41c\ub2e4"],t.s)
B.b5P=s(["\ub300\ub9ac\uc778\uc774 \uadf8 \uad8c\ud55c \ub0b4\uc5d0\uc11c \ubcf8\uc778\uc744 \uc704\ud55c \uac83\uc784\uc744 \ud45c\uc2dc\ud558\uace0 \ud55c \uc758\uc0ac\ud45c\uc2dc\ub294 \uc9c1\uc811 \ubcf8\uc778\uc5d0 \ub300\ud558\uc5ec \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4"],t.s)
B.b6G=s(["\ub300\ub9ac\uc758 \ud6a8\uacfc\uadc0\uc18d"],t.s)
B.bHC=new A.a("gen_cl_agency_1","civil_law","\ub300\ub9ac\ud589\uc704",null,"\ub300\ub9ac\ud589\uc704\uc758 \ud6a8\uacfc\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.b9B,0,"\ubbfc\ubc95 \uc81c114\uc870 \uc81c1\ud56d\uc5d0 \ub530\ub77c \ub300\ub9ac\uc778\uc774 \uadf8 \uad8c\ud55c \ub0b4\uc5d0\uc11c \ubcf8\uc778\uc744 \uc704\ud55c \uac83\uc784\uc744 \ud45c\uc2dc\ud558\uace0 \ud55c \uc758\uc0ac\ud45c\uc2dc\ub294 \uc9c1\uc811 \ubcf8\uc778\uc5d0 \ub300\ud558\uc5ec \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4. \ub300\ub9ac\ud589\uc704\uc758 \ud6a8\uacfc\ub294 \ub300\ub9ac\uc778\uc744 \uac70\uce58\uc9c0 \uc54a\uace0 \ucc98\uc74c\ubd80\ud130 \ubcf8\uc778\uc5d0\uac8c \uc9c1\uc811 \uadc0\uc18d\ub41c\ub2e4.",B.b5P,B.b6G,null)
B.b6x=s(["\ud56d\uc0c1 \ubcf8\uc778\uc5d0\uac8c \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4","\uc790\uae30\ub97c \uc704\ud55c \uac83\uc73c\ub85c \ubcf4\uc544 \uc6d0\uce59\uc801\uc73c\ub85c \ub300\ub9ac\uc778 \uc790\uc2e0\uc5d0\uac8c \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4","\ud56d\uc0c1 \ubb34\ud6a8\uc774\ub2e4","\uc0c1\ub300\ubc29\uc774 \uc774\ub97c \ucde8\uc18c\ud560 \uc218 \uc788\uc744 \ubfd0\uc774\ub2e4"],t.s)
B.aF9=s(["\ub300\ub9ac\uc778\uc774 \ubcf8\uc778\uc744 \uc704\ud55c \uac83\uc784\uc744 \ud45c\uc2dc\ud558\uc9c0 \uc544\ub2c8\ud55c \ub54c\uc5d0\ub294 \uadf8 \uc758\uc0ac\ud45c\uc2dc\ub294 \uc790\uae30\ub97c \uc704\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4"],t.s)
B.b3Q=s(["\ud604\uba85\uc8fc\uc758"],t.s)
B.bJl=new A.a("gen_cl_agency_2","civil_law","\ub300\ub9ac\ud589\uc704",null,"\ub300\ub9ac\uc778\uc774 \ubcf8\uc778\uc744 \uc704\ud55c \uac83\uc784\uc744 \ud45c\uc2dc\ud558\uc9c0 \uc544\ub2c8\ud558\uace0 \uc758\uc0ac\ud45c\uc2dc\ub97c \ud55c \uacbd\uc6b0(\ud604\uba85\ud558\uc9c0 \uc54a\uc740 \uacbd\uc6b0)\uc758 \ud6a8\uacfc\ub294?",B.b6x,1,"\ubbfc\ubc95 \uc81c115\uc870 \ubcf8\ubb38\uc740 \ub300\ub9ac\uc778\uc774 \ubcf8\uc778\uc744 \uc704\ud55c \uac83\uc784\uc744 \ud45c\uc2dc\ud558\uc9c0 \uc544\ub2c8\ud55c \ub54c\uc5d0\ub294 \uadf8 \uc758\uc0ac\ud45c\uc2dc\ub294 \uc790\uae30\ub97c \uc704\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ub2e4\ub9cc \ub2e8\uc11c\uc5d0 \ub530\ub77c \uc0c1\ub300\ubc29\uc774 \ub300\ub9ac\uc778\uc73c\ub85c\uc11c \ud55c \uac83\uc784\uc744 \uc54c\uc558\uac70\ub098 \uc54c \uc218 \uc788\uc5c8\uc744 \ub54c\uc5d0\ub294 \uc81c114\uc870\uac00 \uc900\uc6a9\ub418\uc5b4 \ubcf8\uc778\uc5d0\uac8c \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4.",B.aF9,B.b3Q,null)
B.aWN=s(["\ubcf8\uc778\uc744 \ud45c\uc900\uc73c\ub85c \ud310\ub2e8\ud55c\ub2e4","\ub300\ub9ac\uc778\uc744 \ud45c\uc900\uc73c\ub85c \ud310\ub2e8\ud55c\ub2e4","\uc0c1\ub300\ubc29\uc744 \ud45c\uc900\uc73c\ub85c \ud310\ub2e8\ud55c\ub2e4","\ubcf8\uc778\uacfc \ub300\ub9ac\uc778 \uc911 \uc720\ub9ac\ud55c \ucabd\uc744 \uc120\ud0dd\ud558\uc5ec \ud310\ub2e8\ud55c\ub2e4"],t.s)
B.apr=s(["\uadf8 \uc0ac\uc2e4\uc758 \uc720\ubb34\ub294 \ub300\ub9ac\uc778\uc744 \ud45c\uc900\uc73c\ub85c \ud558\uc5ec \uacb0\uc815\ud55c\ub2e4"],t.s)
B.SQ=s(["\ub300\ub9ac\ud589\uc704 \ud558\uc790\uc758 \ud310\ub2e8\uae30\uc900"],t.s)
B.bx1=new A.a("gen_cl_agency_3","civil_law","\ub300\ub9ac\ud589\uc704",null,"\ub300\ub9ac\ud589\uc704\uc758 \ud558\uc790(\uc758\uc0ac\uc758 \ud760\uacb0, \uc0ac\uae30\xb7\uac15\ubc15, \ud2b9\uc815 \uc0ac\uc815\uc5d0 \ub300\ud55c \uc545\uc758\xb7\uacfc\uc2e4 \ub4f1) \uc720\ubb34\ub294 \ub204\uad6c\ub97c \ud45c\uc900\uc73c\ub85c \ud310\ub2e8\ud558\ub294\uac00?",B.aWN,1,"\ubbfc\ubc95 \uc81c116\uc870 \uc81c1\ud56d\uc5d0 \ub530\ub77c \uc758\uc0ac\ud45c\uc2dc\uc758 \ud6a8\ub825\uc774 \uc758\uc0ac\uc758 \ud760\uacb0, \uc0ac\uae30\xb7\uac15\ubc15 \ub610\ub294 \uc5b4\ub290 \uc0ac\uc815\uc744 \uc54c\uc558\uac70\ub098 \uacfc\uc2e4\ub85c \uc54c\uc9c0 \ubabb\ud55c \uac83\uc73c\ub85c \uc778\ud558\uc5ec \uc601\ud5a5\uc744 \ubc1b\uc744 \uacbd\uc6b0\uc5d0 \uadf8 \uc0ac\uc2e4\uc758 \uc720\ubb34\ub294 \ub300\ub9ac\uc778\uc744 \ud45c\uc900\uc73c\ub85c \ud558\uc5ec \uacb0\uc815\ud55c\ub2e4. \uc2e4\uc81c\ub85c \uc758\uc0ac\ud45c\uc2dc\ub97c \ud558\ub294 \uac83\uc740 \ub300\ub9ac\uc778\uc774\uae30 \ub54c\ubb38\uc774\ub2e4.",B.apr,B.SQ,null)
B.asx=s(["\ub300\ub9ac\uc778\uc740 \ubc18\ub4dc\uc2dc \ud589\uc704\ub2a5\ub825\uc790\uc774\uc5b4\uc57c \ud55c\ub2e4","\ub300\ub9ac\uc778\uc740 \ud589\uc704\ub2a5\ub825\uc790\uc784\uc744 \uc694\ud558\uc9c0 \uc54a\uc73c\uba70, \uc81c\ud55c\ub2a5\ub825\uc790\ub3c4 \ub300\ub9ac\uc778\uc774 \ub420 \uc218 \uc788\ub2e4","\ub300\ub9ac\uc778\uc774 \ubbf8\uc131\ub144\uc790\uc778 \uacbd\uc6b0 \uadf8 \ub300\ub9ac\ud589\uc704\ub294 \ud56d\uc0c1 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4","\ub300\ub9ac\uc778\uc740 \ubc18\ub4dc\uc2dc \uc131\ub144\uc790\uc774\uc5b4\uc57c \ud55c\ub2e4"],t.s)
B.tG=s(["\ub300\ub9ac\uc778\uc740 \ud589\uc704\ub2a5\ub825\uc790\uc784\uc744 \uc694\ud558\uc9c0 \uc544\ub2c8\ud55c\ub2e4"],t.s)
B.a59=s(["\ub300\ub9ac\uc778\uc758 \ud589\uc704\ub2a5\ub825 \ubd88\uc694"],t.s)
B.bCQ=new A.a("gen_cl_agency_4","civil_law","\ub300\ub9ac\ud589\uc704",null,"\ub300\ub9ac\uc778\uc758 \ub2a5\ub825\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.asx,1,"\ubbfc\ubc95 \uc81c117\uc870\ub294 \ub300\ub9ac\uc778\uc740 \ud589\uc704\ub2a5\ub825\uc790\uc784\uc744 \uc694\ud558\uc9c0 \uc544\ub2c8\ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc774\ub294 \ub300\ub9ac\ud589\uc704\uc758 \ubc95\ub960\ud6a8\uacfc\uac00 \ubcf8\uc778\uc5d0\uac8c \uadc0\uc18d\ub418\uc5b4 \ub300\ub9ac\uc778 \uc790\uc2e0\uc740 \ubd88\uc774\uc775\uc744 \uc785\uc9c0 \uc54a\uae30 \ub54c\ubb38\uc774\uba70, \ub530\ub77c\uc11c \uc81c\ud55c\ub2a5\ub825\uc790\ub3c4 \uc720\ud6a8\ud558\uac8c \ub300\ub9ac\uc778\uc774 \ub420 \uc218 \uc788\ub2e4.",B.tG,B.a59,null)
B.aEl=s(["\ubcf4\uc874\ud589\uc704 \ubc0f \ub300\ub9ac\uc758 \ubaa9\uc801\uc778 \ubb3c\uac74\uc774\ub098 \uad8c\ub9ac\uc758 \uc131\uc9c8\uc744 \ubcc0\ud558\uc9c0 \uc54a\ub294 \ubc94\uc704\uc758 \uc774\uc6a9\xb7\uac1c\ub7c9\ud589\uc704","\ub300\ub9ac\uc758 \ubaa9\uc801\ubb3c\uc744 \ucc98\ubd84\ud558\ub294 \ud589\uc704","\ub300\ub9ac\uc758 \ubaa9\uc801\ubb3c\uc758 \uc131\uc9c8\uc744 \ubcc0\uacbd\ud558\ub294 \ud589\uc704","\uc81c\ud55c \uc5c6\uc774 \ubaa8\ub4e0 \ucc98\ubd84\ud589\uc704"],t.s)
B.b7O=s(["\ubcf4\uc874\ud589\uc704\uc640","\ub300\ub9ac\uc758 \ubaa9\uc801\uc778 \ubb3c\uac74\uc774\ub098 \uad8c\ub9ac\uc758 \uc131\uc9c8\uc744 \ubcc0\ud558\uc9c0 \uc544\ub2c8\ud558\ub294 \ubc94\uc704\uc5d0\uc11c \uadf8 \uc774\uc6a9 \ub610\ub294 \uac1c\ub7c9\ud558\ub294 \ud589\uc704\ub9cc\uc744 \ud560 \uc218 \uc788\ub2e4"],t.s)
B.ayO=s(["\uad8c\ud55c\uc744 \uc815\ud558\uc9c0 \uc544\ub2c8\ud55c \ub300\ub9ac\uc778\uc758 \uad8c\ud55c\ubc94\uc704"],t.s)
B.bP8=new A.a("gen_cl_agency_5","civil_law","\ub300\ub9ac\ud589\uc704",null,"\uad8c\ud55c\uc744 \uc815\ud558\uc9c0 \uc544\ub2c8\ud55c \ub300\ub9ac\uc778\uc774 \ud560 \uc218 \uc788\ub294 \ud589\uc704\ub85c \uc633\uc740 \uac83\uc740?",B.aEl,0,"\ubbfc\ubc95 \uc81c118\uc870\uc5d0 \ub530\ub77c \uad8c\ud55c\uc744 \uc815\ud558\uc9c0 \uc544\ub2c8\ud55c \ub300\ub9ac\uc778\uc740 \u2460 \ubcf4\uc874\ud589\uc704\uc640 \u2461 \ub300\ub9ac\uc758 \ubaa9\uc801\uc778 \ubb3c\uac74\uc774\ub098 \uad8c\ub9ac\uc758 \uc131\uc9c8\uc744 \ubcc0\ud558\uc9c0 \uc544\ub2c8\ud558\ub294 \ubc94\uc704\uc5d0\uc11c \uadf8 \uc774\uc6a9 \ub610\ub294 \uac1c\ub7c9\ud558\ub294 \ud589\uc704\ub9cc\uc744 \ud560 \uc218 \uc788\ub2e4. \ucc98\ubd84\ud589\uc704\ub098 \uc131\uc9c8\uc744 \ubcc0\uacbd\ud558\ub294 \ud589\uc704\ub294 \ud560 \uc218 \uc5c6\ub2e4.",B.b7O,B.ayO,null)
B.aK0=s(["\ubc95\ub960 \ub610\ub294 \uc218\uad8c\ud589\uc704\uc5d0 \ub2e4\ub978 \uc815\ud568\uc774 \uc5c6\uc73c\uba74 \uac01\uc790\uac00 \ubcf8\uc778\uc744 \ub300\ub9ac\ud55c\ub2e4","\ubc18\ub4dc\uc2dc \uc804\uc6d0\uc774 \uacf5\ub3d9\uc73c\ub85c\ub9cc \ub300\ub9ac\ud560 \uc218 \uc788\ub2e4","\ub2e4\uc218\uacb0\ub85c \ub300\ub9ac\ud589\uc704 \uc5ec\ubd80\ub97c \uacb0\uc815\ud55c\ub2e4","\uc5f0\uc7a5\uc790\uac00 \ub300\ud45c\ub85c \ub300\ub9ac\ud55c\ub2e4"],t.s)
B.a8U=s(["\ub300\ub9ac\uc778\uc774 \uc218\uc778\uc778 \ub54c\uc5d0\ub294 \ubc95\ub960 \ub610\ub294 \uc218\uad8c\ud589\uc704\uc5d0 \ub2e4\ub978 \uc815\ud568\uc774 \uc5c6\uc73c\uba74 \uac01\uc790\uac00 \ubcf8\uc778\uc744 \ub300\ub9ac\ud55c\ub2e4"],t.s)
B.bgA=s(["\uac01\uc790\ub300\ub9ac\uc758 \uc6d0\uce59"],t.s)
B.bKZ=new A.a("gen_cl_agency_6","civil_law","\ub300\ub9ac\ud589\uc704",null,"\ub300\ub9ac\uc778\uc774 \uc218\uc778(\u6578\u4eba)\uc778 \uacbd\uc6b0 \ub300\ub9ac \ubc29\uc2dd\uc5d0 \uad00\ud55c \uc6d0\uce59\uc740?",B.aK0,0,"\ubbfc\ubc95 \uc81c119\uc870\ub294 \ub300\ub9ac\uc778\uc774 \uc218\uc778\uc778 \ub54c\uc5d0\ub294 \ubc95\ub960 \ub610\ub294 \uc218\uad8c\ud589\uc704\uc5d0 \ub2e4\ub978 \uc815\ud568\uc774 \uc5c6\uc73c\uba74 \uac01\uc790\uac00 \ubcf8\uc778\uc744 \ub300\ub9ac\ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4(\uac01\uc790\ub300\ub9ac\uc758 \uc6d0\uce59). \uacf5\ub3d9\ub300\ub9ac\ub85c \ud558\ub824\uba74 \ubc95\ub960\uc758 \uaddc\uc815\uc774\ub098 \uc218\uad8c\ud589\uc704\uc5d0\uc11c \ubcc4\ub3c4\ub85c \uc815\ud558\uc5ec\uc57c \ud55c\ub2e4.",B.a8U,B.bgA,null)
B.b05=s(["\uc5b8\uc81c\ub4e0\uc9c0 \uc790\uc720\ub86d\uac8c \uc120\uc784\ud560 \uc218 \uc788\ub2e4","\ubcf8\uc778\uc758 \uc2b9\ub099\uc774 \uc788\uac70\ub098 \ubd80\ub4dd\uc774\ud55c \uc0ac\uc720\uac00 \uc788\ub294 \ub54c\uc5d0 \ud55c\ud558\uc5ec \uc120\uc784\ud560 \uc218 \uc788\ub2e4","\ub300\ub9ac\uc778\uc774 \ud544\uc694\ud558\ub2e4\uace0 \ud310\ub2e8\ud558\uba74 \ud56d\uc0c1 \uc120\uc784\ud560 \uc218 \uc788\ub2e4","\ubcf5\ub300\ub9ac\uc778\uc740 \ubc95\uc815\ub300\ub9ac\uc778\ub9cc \uc120\uc784\ud560 \uc218 \uc788\ub2e4"],t.s)
B.afU=s(["\uc784\uc758\ub300\ub9ac\uc778\uc740 \ubcf8\uc778\uc758 \uc2b9\ub099\uc774 \uc788\uac70\ub098 \ubd80\ub4dd\uc774\ud55c \uc0ac\uc720\uac00 \uc788\ub294 \ub54c\uac00 \uc544\ub2c8\uba74 \ubcf5\ub300\ub9ac\uc778\uc744 \uc120\uc784\ud558\uc9c0 \ubabb\ud55c\ub2e4"],t.s)
B.Ua=s(["\uc784\uc758\ub300\ub9ac\uc778\uc758 \ubcf5\uc784\uad8c \uc81c\ud55c"],t.s)
B.buu=new A.a("gen_cl_agency_7","civil_law","\ub300\ub9ac\ud589\uc704",null,"\uc784\uc758\ub300\ub9ac\uc778\uc774 \ubcf5\ub300\ub9ac\uc778\uc744 \uc120\uc784\ud560 \uc218 \uc788\ub294 \uacbd\uc6b0\ub85c \uc633\uc740 \uac83\uc740?",B.b05,1,"\ubbfc\ubc95 \uc81c120\uc870\uc5d0 \ub530\ub77c \uc784\uc758\ub300\ub9ac\uc778\uc740 \ubcf8\uc778\uc758 \uc2b9\ub099\uc774 \uc788\uac70\ub098 \ubd80\ub4dd\uc774\ud55c \uc0ac\uc720\uac00 \uc788\ub294 \ub54c\uac00 \uc544\ub2c8\uba74 \ubcf5\ub300\ub9ac\uc778\uc744 \uc120\uc784\ud558\uc9c0 \ubabb\ud55c\ub2e4. \uc784\uc758\ub300\ub9ac\ub294 \ubcf8\uc778\uc758 \uc2e0\ub8b0\uc5d0 \uae30\ucd08\ud558\ubbc0\ub85c \ubcf5\uc784\uad8c\uc774 \uc6d0\uce59\uc801\uc73c\ub85c \uc81c\ud55c\ub41c\ub2e4.",B.afU,B.Ua,null)
B.b8a=s(["\ubc95\uc815\ub300\ub9ac\uc778\uc740 \ubcf5\ub300\ub9ac\uc778\uc744 \uc120\uc784\ud560 \uc218 \uc5c6\ub2e4","\ubc95\uc815\ub300\ub9ac\uc778\uc740 \uadf8 \ucc45\uc784\uc73c\ub85c \uc5b8\uc81c\ub4e0\uc9c0 \ubcf5\ub300\ub9ac\uc778\uc744 \uc120\uc784\ud560 \uc218 \uc788\ub2e4","\ubc95\uc815\ub300\ub9ac\uc778\uc740 \ubcf8\uc778\uc758 \ub3d9\uc758\ub97c \ubc1b\uc544\uc57c\ub9cc \ubcf5\ub300\ub9ac\uc778\uc744 \uc120\uc784\ud560 \uc218 \uc788\ub2e4","\ubc95\uc815\ub300\ub9ac\uc778\uc740 \ubd80\ub4dd\uc774\ud55c \uc0ac\uc720\uac00 \uc788\uc744 \ub54c\uc5d0\ub9cc \ubcf5\ub300\ub9ac\uc778\uc744 \uc120\uc784\ud560 \uc218 \uc788\ub2e4"],t.s)
B.b8F=s(["\ubc95\uc815\ub300\ub9ac\uc778\uc740 \uadf8 \ucc45\uc784\uc73c\ub85c \ubcf5\ub300\ub9ac\uc778\uc744 \uc120\uc784\ud560 \uc218 \uc788\ub2e4"],t.s)
B.am3=s(["\ubc95\uc815\ub300\ub9ac\uc778\uc758 \ubcf5\uc784\uad8c"],t.s)
B.bBq=new A.a("gen_cl_agency_8","civil_law","\ub300\ub9ac\ud589\uc704",null,"\ubc95\uc815\ub300\ub9ac\uc778\uc758 \ubcf5\uc784\uad8c\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.b8a,1,"\ubbfc\ubc95 \uc81c122\uc870 \ubcf8\ubb38\uc5d0 \ub530\ub77c \ubc95\uc815\ub300\ub9ac\uc778\uc740 \uadf8 \ucc45\uc784\uc73c\ub85c \ubcf5\ub300\ub9ac\uc778\uc744 \uc120\uc784\ud560 \uc218 \uc788\ub2e4. \ubc95\uc815\ub300\ub9ac\ub294 \ubcf8\uc778\uc758 \uac1c\uc778\uc801 \uc2e0\ub8b0\uc640 \ubb34\uad00\ud558\uac8c \ubc95\ub960\uc758 \uaddc\uc815\uc73c\ub85c \ubc1c\uc0dd\ud558\ubbc0\ub85c, \uc784\uc758\ub300\ub9ac\uc640 \ub2ec\ub9ac \ubcf5\uc784\uad8c\uc774 \ud3ed\ub113\uac8c \uc778\uc815\ub418\ub294 \ub300\uc2e0 \uc120\uc784\uac10\ub3c5\uc5d0 \uad00\ud55c \ucc45\uc784\uc774 \ubb34\uac81\ub2e4.",B.b8F,B.am3,null)
B.Ur=s(["\ubcf5\ub300\ub9ac\uc778\uc740 \ub300\ub9ac\uc778\uc758 \ub300\ub9ac\uc778\uc77c \ubfd0 \ubcf8\uc778\uc758 \ub300\ub9ac\uc778\uc740 \uc544\ub2c8\ub2e4","\ubcf5\ub300\ub9ac\uc778\uc740 \ubcf8\uc778\uc758 \ub300\ub9ac\uc778\uc774\uba70, \ub300\ub9ac\uc778\uacfc \ub3d9\uc77c\ud55c \uad8c\ub9ac\uc758\ubb34\ub97c \uac00\uc9c4\ub2e4","\ubcf5\ub300\ub9ac\uc778\uc740 \ub300\ub9ac\uc778\uc758 \uc774\ud589\ubcf4\uc870\uc790\uc5d0 \ubd88\uacfc\ud558\ub2e4","\ubcf5\ub300\ub9ac\uc778\uc758 \ud589\uc704\uc758 \ud6a8\uacfc\ub294 \ub300\ub9ac\uc778\uc5d0\uac8c \uadc0\uc18d\ub41c\ub2e4"],t.s)
B.a33=s(["\ubcf5\ub300\ub9ac\uc778\uc740 \uadf8 \uad8c\ud55c \ub0b4\uc5d0\uc11c \ubcf8\uc778\uc744 \ub300\ub9ac\ud558\uba70, \ub300\ub9ac\uc778\uacfc \ub3d9\uc77c\ud55c \uad8c\ub9ac\uc758\ubb34\uac00 \uc788\ub2e4"],t.s)
B.beL=s(["\ubcf5\ub300\ub9ac\uc778\uc758 \uc9c0\uc704"],t.s)
B.btZ=new A.a("gen_cl_agency_9","civil_law","\ub300\ub9ac\ud589\uc704",null,"\ubcf5\ub300\ub9ac\uc778\uc758 \ubc95\uc801 \uc9c0\uc704\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.Ur,1,"\ubbfc\ubc95 \uc81c123\uc870\uc5d0 \ub530\ub77c \ubcf5\ub300\ub9ac\uc778\uc740 \uadf8 \uad8c\ud55c \ub0b4\uc5d0\uc11c \ubcf8\uc778\uc744 \ub300\ub9ac\ud558\uba70, \ub300\ub9ac\uc778\uacfc \ub3d9\uc77c\ud55c \uad8c\ub9ac\uc758\ubb34\uac00 \uc788\ub2e4. \ubcf5\ub300\ub9ac\uc778\uc740 \ub300\ub9ac\uc778\uc774 \uc120\uc784\ud558\uc600\uc744 \ubfd0 \uc5b4\ub514\uae4c\uc9c0\ub098 \ubcf8\uc778\uc758 \ub300\ub9ac\uc778\uc774\ubbc0\ub85c, \uadf8 \ub300\ub9ac\ud589\uc704\uc758 \ud6a8\uacfc\ub294 \uc9c1\uc811 \ubcf8\uc778\uc5d0\uac8c \uadc0\uc18d\ub41c\ub2e4.",B.a33,B.beL,null)
B.aLi=s(["\ub300\ub9ac\uad8c\uacfc \ubb34\uad00\ud558\uac8c \uc874\uc18d\ud55c\ub2e4","\uc6d0\uce59\uc801\uc73c\ub85c \ud568\uaed8 \uc18c\uba78\ud55c\ub2e4","\ubcf8\uc778\uc758 \uc0c8\ub85c\uc6b4 \uc2b9\ub099\uc774 \uc788\uc5b4\uc57c \uc18c\uba78\ud55c\ub2e4","\ubcf5\ub300\ub9ac\uc778\uc774 \uc0ac\uc784\ud574\uc57c\ub9cc \uc18c\uba78\ud55c\ub2e4"],t.s)
B.aWl=s(["\ubcf5\ub300\ub9ac\uad8c\uc740 \ub300\ub9ac\uc778\uc758 \ub300\ub9ac\uad8c\uc744 \uae30\ucd08\ub85c \ubc1c\uc0dd\ud558\ub294 \uac83\uc774\ubbc0\ub85c \ubd80\uc885\uc131\uc744 \uac00\uc9c4\ub2e4"],t.s)
B.a5y=s(["\ubcf5\ub300\ub9ac\uad8c\uc758 \ubd80\uc885\uc131"],t.s)
B.bFT=new A.a("gen_cl_agency_10","civil_law","\ub300\ub9ac\ud589\uc704",null,"\ub300\ub9ac\uc778\uc758 \ub300\ub9ac\uad8c\uc774 \uc18c\uba78\ud55c \uacbd\uc6b0, \uadf8 \ub300\ub9ac\uc778\uc774 \uc120\uc784\ud55c \ubcf5\ub300\ub9ac\uc778\uc758 \ubcf5\ub300\ub9ac\uad8c\uc740?",B.aLi,1,"\ubcf5\ub300\ub9ac\uad8c\uc740 \ub300\ub9ac\uc778\uc758 \ub300\ub9ac\uad8c\uc744 \uae30\ucd08\ub85c \ubc1c\uc0dd\ud558\ub294 \uac83\uc774\ubbc0\ub85c \ubd80\uc885\uc131\uc744 \uac00\uc9c4\ub2e4. \ub530\ub77c\uc11c \ub300\ub9ac\uc778\uc758 \ub300\ub9ac\uad8c\uc774 \uc18c\uba78\ud558\uba74 \uadf8\uc5d0 \uae30\ucd08\ud55c \ubcf5\ub300\ub9ac\uc778\uc758 \ubcf5\ub300\ub9ac\uad8c\ub3c4 \uc6d0\uce59\uc801\uc73c\ub85c \ud568\uaed8 \uc18c\uba78\ud55c\ub2e4.",B.aWl,B.a5y,null)
B.afo=s(["\uc790\uae30\uacc4\uc57d\uc774\ub780 \ub300\ub9ac\uc778\uc774 \ub300\ub9ac\ud589\uc704\ub97c \ud558\uba74\uc11c \uc0c1\ub300\ubc29\uc73c\ub85c\uc11c \uc790\uae30 \uc790\uc2e0\uacfc \uacc4\uc57d\uc744 \uccb4\uacb0\ud558\ub294 \uac83\uc744 \ub9d0\ud55c\ub2e4","\uc30d\ubc29\ub300\ub9ac\ub780 \ub3d9\uc77c\uc778\uc774 \ud558\ub098\uc758 \ubc95\ub960\ud589\uc704\uc5d0\uc11c \ub2f9\uc0ac\uc790 \uc30d\ubc29\uc744 \ub300\ub9ac\ud558\ub294 \uac83\uc744 \ub9d0\ud55c\ub2e4","\uc790\uae30\uacc4\uc57d\uacfc \uc30d\ubc29\ub300\ub9ac\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \uae08\uc9c0\ub418\ub098, \ubcf8\uc778\uc758 \ud5c8\ub77d\uc774 \uc788\uac70\ub098 \ub2e8\uc21c\ud55c \ucc44\ubb34\uc758 \uc774\ud589\uc778 \uacbd\uc6b0\uc5d0\ub294 \ud5c8\uc6a9\ub41c\ub2e4","\uc790\uae30\uacc4\uc57d\xb7\uc30d\ubc29\ub300\ub9ac\ub85c \uc774\ub8e8\uc5b4\uc9c4 \ud589\uc704\ub294 \uc608\uc678 \uc5c6\uc774 \ud655\uc815\uc801\uc73c\ub85c \ubb34\ud6a8\uc774\ub2e4"],t.s)
B.bi0=s(["\uc774\ub97c \uc704\ubc18\ud55c \uc790\uae30\uacc4\uc57d\xb7\uc30d\ubc29\ub300\ub9ac\ub294 \ubb34\ud6a8\uac00 \uc544\ub2c8\ub77c \ubb34\uad8c\ub300\ub9ac \ud589\uc704\ub85c \ub2e4\ub8e8\uc5b4\uc9c0\ubbc0\ub85c"],t.s)
B.akk=s(["\uc790\uae30\uacc4\uc57d\xb7\uc30d\ubc29\ub300\ub9ac"],t.s)
B.bq6=new A.a("gen_cl_agency_11","civil_law","\ub300\ub9ac\ud589\uc704",null,"\uc790\uae30\uacc4\uc57d\xb7\uc30d\ubc29\ub300\ub9ac\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.afo,3,'\ubbfc\ubc95 \uc81c124\uc870\ub294 \uc790\uae30\uacc4\uc57d\uacfc \uc30d\ubc29\ub300\ub9ac\ub97c \uc6d0\uce59\uc801\uc73c\ub85c \uae08\uc9c0\ud558\uba74\uc11c\ub3c4, \ubcf8\uc778\uc758 \ud5c8\ub77d\uc774 \uc788\uac70\ub098 \ucc44\ubb34\uc758 \uc774\ud589\uc778 \uacbd\uc6b0\uc5d0\ub294 \uc608\uc678\uc801\uc73c\ub85c \ud5c8\uc6a9\ud55c\ub2e4. \uc774\ub97c \uc704\ubc18\ud55c \uc790\uae30\uacc4\uc57d\xb7\uc30d\ubc29\ub300\ub9ac\ub294 \ubb34\ud6a8\uac00 \uc544\ub2c8\ub77c \ubb34\uad8c\ub300\ub9ac \ud589\uc704\ub85c \ub2e4\ub8e8\uc5b4\uc9c0\ubbc0\ub85c, "\uc608\uc678 \uc5c6\uc774 \ud655\uc815\uc801\uc73c\ub85c \ubb34\ud6a8"\ub77c\ub294 \uc124\uba85\uc740 \uc633\uc9c0 \uc54a\ub2e4.',B.bi0,B.akk,null)
B.amk=s(["\ub300\ub9ac\uad8c\uc758 \ubc94\uc704 \ub0b4\uc774\ubbc0\ub85c \ud56d\uc0c1 \ubcf8\uc778\uc5d0\uac8c \ud6a8\ub825\uc774 \uc788\ub2e4","\uc0c1\ub300\ubc29\uc774 \ub300\ub9ac\uc778\uc758 \ubc30\uc784\uc801 \uc758\ub3c4\ub97c \uc54c\uc558\uac70\ub098 \uc54c \uc218 \uc788\uc5c8\ub358 \uacbd\uc6b0\uc5d0\ub294 \ubcf8\uc778\uc5d0\uac8c \ud6a8\ub825\uc774 \uc5c6\ub2e4\uace0 \ubcfc \uc218 \uc788\ub2e4","\ub300\ub9ac\uad8c \ub0a8\uc6a9\uc740 \uc5b8\uc81c\ub098 \ubb34\ud6a8\uc774\uba70 \ubcf8\uc778\uc5d0\uac8c \ud6a8\ub825\uc774 \uc5c6\ub2e4","\ub300\ub9ac\uad8c \ub0a8\uc6a9\uc740 \ud615\uc0ac\ucc98\ubc8c \ub300\uc0c1\uc77c \ubfd0 \uc0ac\ubc95\uc0c1 \ud6a8\ub825\uacfc\ub294 \ubb34\uad00\ud558\ub2e4"],t.s)
B.aAM=s(["\uc0c1\ub300\ubc29\uc774 \ub300\ub9ac\uc778\uc758 \uc9c4\uc758(\ubc30\uc784\uc801 \uc758\ub3c4)\ub97c \uc54c\uc558\uac70\ub098 \uc54c \uc218 \uc788\uc5c8\uc744 \ub54c\uc5d0\ub294","\ubcf8\uc778\uc5d0\uac8c \uadf8 \ud6a8\ub825\uc774 \ubbf8\uce58\uc9c0 \uc54a\ub294\ub2e4\uace0 \ubcf8\ub2e4"],t.s)
B.aiz=s(["\ub300\ub9ac\uad8c \ub0a8\uc6a9"],t.s)
B.bCL=new A.a("gen_cl_agency_12","civil_law","\ub300\ub9ac\ud589\uc704",null,"\ub300\ub9ac\uc778\uc774 \ub300\ub9ac\uad8c\uc758 \ubc94\uc704 \ub0b4\uc5d0\uc11c \ud589\uc704\ud558\uc600\uc73c\ub098 \uc624\ub85c\uc9c0 \uc790\uae30 \ub610\ub294 \uc81c3\uc790\uc758 \uc774\uc775\uc744 \ub3c4\ubaa8\ud560 \ubaa9\uc801\uc73c\ub85c \ub300\ub9ac\ud589\uc704\ub97c \ud55c \uacbd\uc6b0(\ub300\ub9ac\uad8c \ub0a8\uc6a9)\uc758 \ud6a8\uacfc\ub294?",B.amk,1,"\ub300\ub9ac\uad8c \ub0a8\uc6a9\uc758 \uacbd\uc6b0 \ud615\uc2dd\uc801\uc73c\ub85c\ub294 \ub300\ub9ac\uad8c \ubc94\uc704 \ub0b4\uc758 \ud589\uc704\uc774\uc9c0\ub9cc, \ud310\ub840\ub294 \uc0c1\ub300\ubc29\uc774 \ub300\ub9ac\uc778\uc758 \uc9c4\uc758(\ubc30\uc784\uc801 \uc758\ub3c4)\ub97c \uc54c\uc558\uac70\ub098 \uc54c \uc218 \uc788\uc5c8\uc744 \ub54c\uc5d0\ub294 \ube44\uc9c4\uc758\ud45c\uc2dc\uc5d0 \uad00\ud55c \uc81c107\uc870 \uc81c1\ud56d \ub2e8\uc11c\ub97c \uc720\ucd94\uc801\uc6a9\ud558\uc5ec \ubcf8\uc778\uc5d0\uac8c \uadf8 \ud6a8\ub825\uc774 \ubbf8\uce58\uc9c0 \uc54a\ub294\ub2e4\uace0 \ubcf8\ub2e4.",B.aAM,B.aiz,null)
B.b5W=s(["\ubcf8\uc778\uc758 \uc0ac\ub9dd","\ub300\ub9ac\uc778\uc758 \uc0ac\ub9dd","\ub300\ub9ac\uc778\uc758 \uc131\ub144\ud6c4\uacac\uc758 \uac1c\uc2dc \ub610\ub294 \ud30c\uc0b0","\ubcf8\uc778\uc758 \uc131\ub144\ud6c4\uacac \uac1c\uc2dc"],t.s)
B.aX2=s(["\ub300\ub9ac\uad8c\uc758 \uacf5\ud1b5 \uc18c\uba78\uc0ac\uc720\ub85c \ubcf8\uc778\uc758 \uc0ac\ub9dd, \ub300\ub9ac\uc778\uc758 \uc0ac\ub9dd\xb7\uc131\ub144\ud6c4\uacac\uc758 \uac1c\uc2dc \ub610\ub294 \ud30c\uc0b0\uc744 \uaddc\uc815\ud55c\ub2e4"],t.s)
B.alD=s(["\ub300\ub9ac\uad8c \uacf5\ud1b5 \uc18c\uba78\uc0ac\uc720"],t.s)
B.bA2=new A.a("gen_cl_agency_13","civil_law","\ub300\ub9ac\ud589\uc704",null,"\ub300\ub9ac\uad8c\uc758 \uacf5\ud1b5 \uc18c\uba78\uc0ac\uc720\uc5d0 \ud574\ub2f9\ud558\uc9c0 \uc54a\ub294 \uac83\uc740?",B.b5W,3,"\ubbfc\ubc95 \uc81c127\uc870\ub294 \ub300\ub9ac\uad8c\uc758 \uacf5\ud1b5 \uc18c\uba78\uc0ac\uc720\ub85c \ubcf8\uc778\uc758 \uc0ac\ub9dd, \ub300\ub9ac\uc778\uc758 \uc0ac\ub9dd\xb7\uc131\ub144\ud6c4\uacac\uc758 \uac1c\uc2dc \ub610\ub294 \ud30c\uc0b0\uc744 \uaddc\uc815\ud55c\ub2e4. \ubcf8\uc778\uc5d0 \ub300\ud55c \uc131\ub144\ud6c4\uacac \uac1c\uc2dc\ub294 \uc774 \uc870\ubb38\uc758 \uc18c\uba78\uc0ac\uc720\uc5d0 \ud3ec\ud568\ub418\uc9c0 \uc54a\ub294\ub2e4.",B.aX2,B.alD,null)
B.b7n=s(["\ub300\ub9ac\uc778\uc758 \uc0ac\ub9dd","\uc6d0\uc778\ub41c \ubc95\ub960\uad00\uacc4\uc758 \uc885\ub8cc \ub610\ub294 \ubcf8\uc778\uc758 \uc218\uad8c\ud589\uc704 \ucca0\ud68c","\ubcf8\uc778\uc758 \uc0ac\ub9dd","\ub300\ub9ac\uc778\uc758 \ud30c\uc0b0"],t.s)
B.aDa=s(["\uc784\uc758\ub300\ub9ac\uad8c\uc740 \uc81c128\uc870\uc5d0 \ub530\ub77c \uadf8 \uc6d0\uc778\ub41c \ubc95\ub960\uad00\uacc4(\uc704\uc784\uacc4\uc57d \ub4f1)\uc758 \uc885\ub8cc\ub85c \uc18c\uba78\ud558\uba70","\ubcf8\uc778\uc774 \uc218\uad8c\ud589\uc704\ub97c \ucca0\ud68c\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \uc18c\uba78\ud55c\ub2e4"],t.s)
