B.bIf=new A.a("gen_cl_intent_11","civil_law","\uc758\uc0ac\ud45c\uc2dc",null,"\ucc29\uc624\ub85c \uc778\ud55c \ucde8\uc18c\uac00 \uc81c\ud55c\ub418\ub294 \uacbd\uc6b0\ub85c \uc633\uc740 \uac83\uc740?",B.aa0,0,"\ubbfc\ubc95 \uc81c109\uc870 \uc81c1\ud56d \ub2e8\uc11c\uc5d0 \ub530\ub77c \ucc29\uc624\uac00 \ud45c\uc758\uc790\uc758 \uc911\ub300\ud55c \uacfc\uc2e4\ub85c \uc778\ud55c \ub54c\uc5d0\ub294 \ucde8\uc18c\ud558\uc9c0 \ubabb\ud55c\ub2e4. \ud45c\uc758\uc790 \uc2a4\uc2a4\ub85c \ud604\uc800\ud55c \ubd80\uc8fc\uc758\ub85c \ucc29\uc624\ub97c \uc77c\uc73c\ud0a8 \uacbd\uc6b0\uc5d0\ub294 \ucde8\uc18c\uad8c\uc744 \uc81c\ud55c\ud558\uc5ec \uc0c1\ub300\ubc29\uc744 \ubcf4\ud638\ud558\ub824\ub294 \ucde8\uc9c0\uc774\ub2e4.",B.b9W,B.aMG,null)
