B.bNe=new A.a("gen_cl_intent_19","civil_law","\uc758\uc0ac\ud45c\uc2dc",null,"\ud45c\uc758\uc790\uc5d0\uac8c \uc911\ub300\ud55c \uacfc\uc2e4\uc774 \uc788\ub354\ub77c\ub3c4 \uc0c1\ub300\ubc29\uc774 \ud45c\uc758\uc790\uc758 \ucc29\uc624\ub97c \uc54c\uace0 \uc774\ub97c \uc774\uc6a9\ud55c \uacbd\uc6b0, \ucc29\uc624\ucde8\uc18c\uac00 \ud5c8\uc6a9\ub418\ub294\uc9c0\uc5d0 \uad00\ud55c \ud310\ub840\uc758 \ud0dc\ub3c4\ub294?",B.ahF,1,"\ud310\ub840\ub294 \ud45c\uc758\uc790\uc5d0\uac8c \uc911\ub300\ud55c \uacfc\uc2e4\uc774 \uc788\ub294 \uacbd\uc6b0\ub77c\ub3c4, \uc0c1\ub300\ubc29\uc774 \ud45c\uc758\uc790\uc758 \ucc29\uc624\ub97c \uc54c\uba74\uc11c \uc774\ub97c \uc774\uc6a9\ud55c \ub54c\uc5d0\ub294 \uc2e0\uc758\uce59\uc5d0 \ubc18\ud558\ubbc0\ub85c \ud45c\uc758\uc790\uc758 \ucc29\uc624\ucde8\uc18c\ub97c \uc778\uc815\ud560 \uc218 \uc788\ub2e4\uace0 \ubcf8\ub2e4.",B.b0T,B.aXm,null)
B.aNJ=s(["\uae30\ub9dd\ud589\uc704\uc758 \uc874\uc7ac","\uae30\ub9dd\ud589\uc704\ub85c \uc778\ud55c \ucc29\uc624\uc758 \ubc1c\uc0dd","\ucc29\uc624\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc","\uae30\ub9dd\ud589\uc704\uac00 \ubc18\ub4dc\uc2dc \uc11c\uba74\uc73c\ub85c \uc774\ub8e8\uc5b4\uc84c\uc744 \uac83"],t.s)
B.ano=s(["\uae30\ub9dd\ud589\uc704\uac00 \ubc18\ub4dc\uc2dc \uc11c\uba74\uc73c\ub85c \uc774\ub8e8\uc5b4\uc838\uc57c \ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4"],t.s)
B.aH5=s(["\uc0ac\uae30\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc \uc694\uac74"],t.s)
B.bFW=new A.a("gen_cl_intent_20","civil_law","\uc758\uc0ac\ud45c\uc2dc",null,"\uc0ac\uae30\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc(\uc81c110\uc870 \uc81c1\ud56d)\uc758 \uc131\ub9bd\uc694\uac74\uc774 \uc544\ub2cc \uac83\uc740?",B.aNJ,3,"\uc0ac\uae30\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\uac00 \uc131\ub9bd\ud558\ub824\uba74 \u2460 \uae30\ub9dd\ud589\uc704, \u2461 \uadf8\ub85c \uc778\ud55c \ucc29\uc624\uc758 \ubc1c\uc0dd, \u2462 \uadf8 \ucc29\uc624\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc, \u2463 \uae30\ub9dd\ud589\uc704\uc758 \uc704\ubc95\uc131\uc774 \uc694\uad6c\ub41c\ub2e4. \uae30\ub9dd\ud589\uc704\uac00 \ubc18\ub4dc\uc2dc \uc11c\uba74\uc73c\ub85c \uc774\ub8e8\uc5b4\uc838\uc57c \ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4.",B.ano,B.aH5,null)
B.asA=s(["\uac15\ubc15\uc758 \uc815\ub3c4\uac00 \uadf9\uc2ec\ud558\uc5ec \ud45c\uc758\uc790\uc758 \uc758\uc0ac\uacb0\uc815\uc758 \uc790\uc720\ub97c \uc644\uc804\ud788 \ubc15\ud0c8\ud55c \uacbd\uc6b0","\ub2e8\uc21c\ud788 \uac81\uc744 \uba39\uc740 \uc815\ub3c4\uc5d0 \ubd88\uacfc\ud55c \uacbd\uc6b0","\uac15\ubc15\uc744 \ud589\ud55c \uc790\uac00 \uc81c3\uc790\uc778 \uacbd\uc6b0","\uac15\ubc15 \ud6c4 \uc0c1\ub2f9 \uae30\uac04\uc774 \uc9c0\ub09c \uacbd\uc6b0"],t.s)
B.biR=s(["\uac15\ubc15\uc758 \uc815\ub3c4\uac00 \uadf9\uc2ec\ud558\uc5ec \ud45c\uc758\uc790\uac00 \uc758\uc0ac\uacb0\uc815\uc758 \uc790\uc720\ub97c \uc644\uc804\ud788 \ubc15\ud0c8\ub2f9\ud55c \uc0c1\ud0dc\uc5d0\uc11c \uc774\ub8e8\uc5b4\uc9c4 \uc758\uc0ac\ud45c\uc2dc\ub294 \uc758\uc0ac\ud45c\uc2dc \uc790\uccb4\uac00 \uc874\uc7ac\ud558\uc9c0 \uc54a\ub294 \uac83\uc73c\ub85c \ubcf4\uc544 \ubb34\ud6a8\ub77c\ub294 \uac83\uc774 \ud310\ub840\uc758 \ud0dc\ub3c4\uc774\ub2e4"],t.s)
B.bad=s(["\uadf9\uc2ec\ud55c \uac15\ubc15\uacfc \ubb34\ud6a8"],t.s)
B.bDO=new A.a("gen_cl_intent_21","civil_law","\uc758\uc0ac\ud45c\uc2dc",null,"\uac15\ubc15\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\uac00 \ubb34\ud6a8(\ucde8\uc18c\uac00 \uc544\ub2cc \uc808\ub300\uc801 \ubb34\ud6a8)\ub85c \ub418\ub294 \uacbd\uc6b0\ub294?",B.asA,0,"\ud1b5\uc0c1\uc758 \uac15\ubc15\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\ub294 \uc81c110\uc870\uc5d0 \ub530\ub77c \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ub370 \uadf8\uce58\uc9c0\ub9cc, \uac15\ubc15\uc758 \uc815\ub3c4\uac00 \uadf9\uc2ec\ud558\uc5ec \ud45c\uc758\uc790\uac00 \uc758\uc0ac\uacb0\uc815\uc758 \uc790\uc720\ub97c \uc644\uc804\ud788 \ubc15\ud0c8\ub2f9\ud55c \uc0c1\ud0dc\uc5d0\uc11c \uc774\ub8e8\uc5b4\uc9c4 \uc758\uc0ac\ud45c\uc2dc\ub294 \uc758\uc0ac\ud45c\uc2dc \uc790\uccb4\uac00 \uc874\uc7ac\ud558\uc9c0 \uc54a\ub294 \uac83\uc73c\ub85c \ubcf4\uc544 \ubb34\ud6a8\ub77c\ub294 \uac83\uc774 \ud310\ub840\uc758 \ud0dc\ub3c4\uc774\ub2e4.",B.biR,B.bad,null)
B.a9d=s(["\uc0c1\ub300\ubc29\uc758 \uc778\uc2dd \uc5ec\ubd80\uc640 \ubb34\uad00\ud558\uac8c \ud56d\uc0c1 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4","\uc0c1\ub300\ubc29\uc774 \uadf8 \uc0ac\uc2e4\uc744 \uc54c\uc558\uac70\ub098 \uc54c \uc218 \uc788\uc5c8\uc744 \uacbd\uc6b0\uc5d0 \ud55c\ud558\uc5ec \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4","\uc81c3\uc790\uac00 \ucc98\ubc8c\ubc1b\uc740 \uacbd\uc6b0\uc5d0\ub9cc \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4","\uc81c3\uc790\uc758 \uc0ac\uae30\xb7\uac15\ubc15\uc73c\ub85c\ub294 \ucde8\uc18c\ud560 \uc218 \uc5c6\uace0 \uc190\ud574\ubc30\uc0c1\ub9cc \uccad\uad6c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.aum=s(["\uc0c1\ub300\ubc29\uc774 \uadf8 \uc0ac\uc2e4\uc744 \uc54c\uc558\uac70\ub098 \uc54c \uc218 \uc788\uc5c8\uc744 \uacbd\uc6b0\uc5d0 \ud55c\ud558\uc5ec \uadf8 \uc758\uc0ac\ud45c\uc2dc\ub97c \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.Z5=s(["\uc81c3\uc790\uc758 \uc0ac\uae30\xb7\uac15\ubc15"],t.s)
B.bMY=new A.a("gen_cl_intent_22","civil_law","\uc758\uc0ac\ud45c\uc2dc",null,"\uc0c1\ub300\ubc29 \uc788\ub294 \uc758\uc0ac\ud45c\uc2dc\uc5d0 \uad00\ud558\uc5ec \uc81c3\uc790\uac00 \uc0ac\uae30\ub098 \uac15\ubc15\uc744 \ud589\ud55c \uacbd\uc6b0, \ud45c\uc758\uc790\uac00 \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \uc694\uac74\uc740?",B.a9d,1,"\ubbfc\ubc95 \uc81c110\uc870 \uc81c2\ud56d\uc5d0 \ub530\ub77c \uc0c1\ub300\ubc29 \uc788\ub294 \uc758\uc0ac\ud45c\uc2dc\uc5d0 \uad00\ud558\uc5ec \uc81c3\uc790\uac00 \uc0ac\uae30\ub098 \uac15\ubc15\uc744 \ud589\ud55c \uacbd\uc6b0\uc5d0\ub294, \uc0c1\ub300\ubc29\uc774 \uadf8 \uc0ac\uc2e4\uc744 \uc54c\uc558\uac70\ub098 \uc54c \uc218 \uc788\uc5c8\uc744 \uacbd\uc6b0\uc5d0 \ud55c\ud558\uc5ec \uadf8 \uc758\uc0ac\ud45c\uc2dc\ub97c \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4.",B.aum,B.Z5,null)
B.aiI=s(["\uc545\uc758\uc758 \uc0c1\ub300\ubc29","\uc120\uc758\uc758 \uc81c3\uc790","\uae30\ub9dd\ud589\uc704\ub97c \ud55c \uc81c3\uc790","\ud45c\uc758\uc790\uc758 \ub300\ub9ac\uc778"],t.s)
B.a5m=s(["\uc0ac\uae30\ub098 \uac15\ubc15\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\uc758 \ucde8\uc18c\ub294 \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c \ub300\ud56d\ud558\uc9c0 \ubabb\ud55c\ub2e4"],t.s)
B.at5=s(["\uc0ac\uae30\xb7\uac15\ubc15\ucde8\uc18c\uc640 \uc81c3\uc790 \ubcf4\ud638"],t.s)
B.brm=new A.a("gen_cl_intent_23","civil_law","\uc758\uc0ac\ud45c\uc2dc",null,"\uc0ac\uae30\xb7\uac15\ubc15\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\uc758 \ucde8\uc18c\ub294 \ub204\uad6c\uc5d0\uac8c \ub300\ud56d\ud558\uc9c0 \ubabb\ud558\ub294\uac00?",B.aiI,1,"\ubbfc\ubc95 \uc81c110\uc870 \uc81c3\ud56d\uc5d0 \ub530\ub77c \uc0ac\uae30\ub098 \uac15\ubc15\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\uc758 \ucde8\uc18c\ub294 \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c \ub300\ud56d\ud558\uc9c0 \ubabb\ud55c\ub2e4. \ucc29\uc624\xb7\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\uc640 \ub9c8\ucc2c\uac00\uc9c0\ub85c \uac70\ub798\uc758 \uc548\uc804\uc744 \uc704\ud55c \uc120\uc758\uc758 \uc81c3\uc790 \ubcf4\ud638 \uaddc\uc815\uc774\ub2e4.",B.a5m,B.at5,null)
B.b25=s(["\ucde8\uc18c\uad8c\uc744 \ud589\uc0ac\ud558\uba74 \uc190\ud574\ubc30\uc0c1\uccad\uad6c\uad8c\uc740 \uc18c\uba78\ud55c\ub2e4","\ucde8\uc18c\uad8c \ud589\uc0ac\uc640\ub294 \ubcc4\uac1c\ub85c \ubd88\ubc95\ud589\uc704\uc5d0 \uae30\ud55c \uc190\ud574\ubc30\uc0c1\uccad\uad6c\ub3c4 \uac00\ub2a5\ud558\ub2e4","\uc190\ud574\ubc30\uc0c1\uccad\uad6c\ub9cc \uac00\ub2a5\ud558\uace0 \ucde8\uc18c\ub294 \ud560 \uc218 \uc5c6\ub2e4","\ucde8\uc18c\uc640 \uc190\ud574\ubc30\uc0c1\uccad\uad6c\ub294 \ub3d9\uc2dc\uc5d0 \ud560 \uc218 \uc5c6\uace0 \uc591\uc790\ud0dd\uc77c\ud558\uc5ec\uc57c \ud55c\ub2e4"],t.s)
B.a7F=s(["\uae30\ub9dd\ud589\uc704\uac00 \ubd88\ubc95\ud589\uc704\uc758 \uc694\uac74\uc744 \ucda9\uc871\ud558\ub294 \uacbd\uc6b0 \ud45c\uc758\uc790\ub294 \uc774\ub97c \uc774\uc720\ub85c \ud55c \uc190\ud574\ubc30\uc0c1\uccad\uad6c\uad8c\ub3c4 \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4\uace0 \ubcf8\ub2e4"],t.s)
B.ap3=s(["\uc0ac\uae30\ucde8\uc18c\uc640 \ubd88\ubc95\ud589\uc704\ucc45\uc784\uc758 \uacbd\ud569"],t.s)
B.bud=new A.a("gen_cl_intent_24","civil_law","\uc758\uc0ac\ud45c\uc2dc",null,"\uc0ac\uae30\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\ub97c \ucde8\uc18c\ud55c \uacbd\uc6b0, \ud45c\uc758\uc790\uac00 \ubcc4\ub3c4\ub85c \ubd88\ubc95\ud589\uc704\uc5d0 \uae30\ud55c \uc190\ud574\ubc30\uc0c1\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub294\uc9c0\uc5d0 \uad00\ud55c \ud310\ub840\uc758 \ud0dc\ub3c4\ub294?",B.b25,1,"\ud310\ub840\ub294 \uc0ac\uae30\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\uc758 \ucde8\uc18c\uad8c \ud589\uc0ac\uc640\ub294 \ubcc4\uac1c\ub85c, \uae30\ub9dd\ud589\uc704\uac00 \ubd88\ubc95\ud589\uc704\uc758 \uc694\uac74\uc744 \ucda9\uc871\ud558\ub294 \uacbd\uc6b0 \ud45c\uc758\uc790\ub294 \uc774\ub97c \uc774\uc720\ub85c \ud55c \uc190\ud574\ubc30\uc0c1\uccad\uad6c\uad8c\ub3c4 \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4\uace0 \ubcf8\ub2e4.",B.a7F,B.ap3,null)
B.aAy=s(["\uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ubb35\ube44\ub294 \uae30\ub9dd\ud589\uc704\uac00 \ub418\uc9c0 \uc54a\ub294\ub2e4","\uc2e0\uc758\uce59\uc0c1 \uace0\uc9c0\uc758\ubb34\uac00 \uc778\uc815\ub418\ub294 \uacbd\uc6b0\uc5d0\ub294 \ubb35\ube44\ub3c4 \uae30\ub9dd\ud589\uc704\uc5d0 \ud574\ub2f9\ud560 \uc218 \uc788\ub2e4","\uc0c1\ub300\ubc29\uc774 \uc2a4\uc2a4\ub85c \ud655\uc778\ud558\uc9c0 \uc54a\uc740 \uc774\uc0c1 \ubb35\ube44\ub294 \ud56d\uc0c1 \uc815\ub2f9\ud558\ub2e4","\ubb35\ube44\ub294 \uacc4\uc57d \uccb4\uacb0 \ud6c4\uc5d0\ub9cc \ubb38\uc81c\uac00 \ub420 \uc218 \uc788\ub2e4"],t.s)
B.acf=s(["\uac70\ub798\uad00\uacc4\uc5d0 \uc788\uc5b4 \uc2e0\uc758\uc131\uc2e4\uc758 \uc6d0\uce59\uc0c1 \uc0c1\ub300\ubc29\uc5d0\uac8c \uc5b4\ub5a4 \uc0ac\uc815\uc744 \uace0\uc9c0\ud560 \uc758\ubb34\uac00 \uc778\uc815\ub418\ub294 \uacbd\uc6b0","\uc774\ub97c \uace0\uc9c0\ud558\uc9c0 \uc54a\uace0 \uce68\ubb35\ud558\ub294 \uac83\ub3c4 \ubd80\uc791\uc704\uc5d0 \uc758\ud55c \uae30\ub9dd\ud589\uc704\uac00 \ub420 \uc218 \uc788\ub2e4\uace0 \ubcf8\ub2e4"],t.s)
B.bfY=s(["\ubb35\ube44\uc640 \uae30\ub9dd\ud589\uc704"],t.s)
B.btb=new A.a("gen_cl_intent_25","civil_law","\uc758\uc0ac\ud45c\uc2dc",null,"\uacc4\uc57d \uccb4\uacb0 \uc2dc \ubaa9\uc801\ubb3c\uc5d0 \uad00\ud55c \uc911\uc694\ud55c \uc0ac\uc2e4\uc744 \uc54c\uba74\uc11c\ub3c4 \uc54c\ub9ac\uc9c0 \uc54a\uc740 \uac83(\ubb35\ube44)\uc774 \uae30\ub9dd\ud589\uc704\uc5d0 \ud574\ub2f9\ud560 \uc218 \uc788\ub294 \uacbd\uc6b0\ub294?",B.aAy,1,"\ud310\ub840\ub294 \uac70\ub798\uad00\uacc4\uc5d0 \uc788\uc5b4 \uc2e0\uc758\uc131\uc2e4\uc758 \uc6d0\uce59\uc0c1 \uc0c1\ub300\ubc29\uc5d0\uac8c \uc5b4\ub5a4 \uc0ac\uc815\uc744 \uace0\uc9c0\ud560 \uc758\ubb34\uac00 \uc778\uc815\ub418\ub294 \uacbd\uc6b0, \uc774\ub97c \uace0\uc9c0\ud558\uc9c0 \uc54a\uace0 \uce68\ubb35\ud558\ub294 \uac83\ub3c4 \ubd80\uc791\uc704\uc5d0 \uc758\ud55c \uae30\ub9dd\ud589\uc704\uac00 \ub420 \uc218 \uc788\ub2e4\uace0 \ubcf8\ub2e4.",B.acf,B.bfY,null)
B.a__=s(["\ucd94\uc778\ud560 \uc218 \uc788\ub294 \ub0a0\ub85c\ubd80\ud130 3\ub144, \ubc95\ub960\ud589\uc704\ub97c \ud55c \ub0a0\ub85c\ubd80\ud130 10\ub144 \ub0b4\uc5d0 \ud589\uc0ac\ud558\uc5ec\uc57c \ud55c\ub2e4","\ucde8\uc18c\uad8c\uc740 \uae30\uac04\uc758 \uc81c\ud55c \uc5c6\uc774 \uc5b8\uc81c\ub4e0\uc9c0 \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4","\ubc95\ub960\ud589\uc704\ub97c \ud55c \ub0a0\ub85c\ubd80\ud130 1\ub144 \ub0b4\uc5d0\ub9cc \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4","\uc0c1\ub300\ubc29\uc774 \ub3d9\uc758\ud558\ub294 \ud55c \uae30\uac04 \uc81c\ud55c\uc774 \uc5c6\ub2e4"],t.s)
B.afw=s(["\ucde8\uc18c\uad8c\uc740 \ucd94\uc778\ud560 \uc218 \uc788\ub294 \ub0a0\ub85c\ubd80\ud130 3\ub144 \ub0b4, \ubc95\ub960\ud589\uc704\ub97c \ud55c \ub0a0\ub85c\ubd80\ud130 10\ub144 \ub0b4\uc5d0 \ud589\uc0ac\ud558\uc5ec\uc57c \ud558\uba70"],t.s)
B.bc9=s(["\ucde8\uc18c\uad8c \ud589\uc0ac\uae30\uac04(\uc81c\ucc99\uae30\uac04)"],t.s)
B.bQz=new A.a("gen_cl_intent_26","civil_law","\uc758\uc0ac\ud45c\uc2dc",null,"\ucc29\uc624, \uc0ac\uae30, \uac15\ubc15\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\uc758 \ucde8\uc18c\uad8c \ud589\uc0ac\uae30\uac04(\uc81c146\uc870)\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.a__,0,"\ubbfc\ubc95 \uc81c146\uc870\uc5d0 \ub530\ub77c \ucde8\uc18c\uad8c\uc740 \ucd94\uc778\ud560 \uc218 \uc788\ub294 \ub0a0\ub85c\ubd80\ud130 3\ub144 \ub0b4, \ubc95\ub960\ud589\uc704\ub97c \ud55c \ub0a0\ub85c\ubd80\ud130 10\ub144 \ub0b4\uc5d0 \ud589\uc0ac\ud558\uc5ec\uc57c \ud558\uba70, \uc774 \uae30\uac04\uc740 \uc81c\ucc99\uae30\uac04\uc73c\ub85c\uc11c \uadf8 \uae30\uac04\uc774 \uc9c0\ub098\uba74 \ucde8\uc18c\uad8c\uc774 \uc18c\uba78\ud55c\ub2e4.",B.afw,B.bc9,null)
B.asV=s(["\ube44\uc9c4\uc758\ud45c\uc2dc\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \uc720\ud6a8\ud558\ub2e4","\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\ub294 \ub2f9\uc0ac\uc790 \uac04\uc5d0 \ubb34\ud6a8\uc774\ub2e4","\ucc29\uc624\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\ub294 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4","\uc0ac\uae30\xb7\uac15\ubc15\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\ub294 \ud56d\uc0c1 \ub2f9\uc5f0\ubb34\ud6a8\uc774\ub2e4"],t.s)
B.aHz=s(["\ucc29\uc624\xb7\uc0ac\uae30\xb7\uac15\ubc15\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \ucde8\uc18c\uc0ac\uc720\uc774\ub2e4"],t.s)
B.U7=s(["\uc758\uc0ac\ud45c\uc2dc \ud558\uc790 \uc720\ud615 \ube44\uad50"],t.s)
B.bKF=new A.a("gen_cl_intent_27","civil_law","\uc758\uc0ac\ud45c\uc2dc",null,"\ube44\uc9c4\uc758\ud45c\uc2dc\xb7\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\xb7\ucc29\uc624\xb7\uc0ac\uae30\xb7\uac15\ubc15\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\uc758 \uc6d0\uce59\uc801 \ud6a8\uacfc\ub97c \ube44\uad50\ud55c \uac83\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.asV,3,'\ube44\uc9c4\uc758\ud45c\uc2dc\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \uc720\ud6a8(\uc608\uc678\uc801\uc73c\ub85c \ubb34\ud6a8), \ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\ub294 \ub2f9\uc0ac\uc790 \uac04 \ubb34\ud6a8, \ucc29\uc624\xb7\uc0ac\uae30\xb7\uac15\ubc15\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \ucde8\uc18c\uc0ac\uc720\uc774\ub2e4. \uc0ac\uae30\xb7\uac15\ubc15\uc740 \ucde8\uc18c\uc0ac\uc720\uc77c \ubfd0 \ub2f9\uc5f0\ubb34\ud6a8\ub294 \uc544\ub2c8\ubbc0\ub85c(\ub2e4\ub9cc \uac15\ubc15\uc774 \uadf9\uc2ec\ud558\uc5ec \uc758\uc0ac\uacb0\uc815\uc758 \uc790\uc720\ub97c \uc644\uc804\ud788 \ubc15\ud0c8\ud55c \uacbd\uc6b0\ub294 \uc608\uc678\uc801\uc73c\ub85c \ubb34\ud6a8), "\ud56d\uc0c1 \ub2f9\uc5f0\ubb34\ud6a8"\ub77c\ub294 \uc124\uba85\uc740 \uc633\uc9c0 \uc54a\ub2e4.',B.aHz,B.U7,null)
B.aMu=s(["\uadf8\ub7ec\ud55c \ud2b9\uc57d\uc740 \ubb34\ud6a8\uc774\ub2e4","\uc0ac\uc801\uc790\uce58\uc758 \uc6d0\uce59\uc0c1 \uc6d0\uce59\uc801\uc73c\ub85c \uc720\ud6a8\ud558\ub2e4","\ubc95\uc6d0\uc758 \ud5c8\uac00\ub97c \ubc1b\uc544\uc57c\ub9cc \uc720\ud6a8\ud558\ub2e4","\uc774\ub7ec\ud55c \ud2b9\uc57d\uc740 \ud56d\uc0c1 \ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704\uc5d0 \ud574\ub2f9\ud55c\ub2e4"],t.s)
B.aeY=s(["\ub2f9\uc0ac\uc790\uac00 \ud569\uc758\ub85c \ucc29\uc624\ucde8\uc18c\uad8c\uc744 \ubbf8\ub9ac \ubc30\uc81c\ud558\ub294 \ud2b9\uc57d\uc740 \uc0ac\uc801\uc790\uce58\uc758 \uc6d0\uce59\uc0c1 \uc6d0\uce59\uc801\uc73c\ub85c \uc720\ud6a8\ud558\ub2e4"],t.s)
B.amP=s(["\ucc29\uc624\ucde8\uc18c\uad8c \ubc30\uc81c\ud2b9\uc57d"],t.s)
B.bAO=new A.a("gen_cl_intent_28","civil_law","\uc758\uc0ac\ud45c\uc2dc",null,"\ub2f9\uc0ac\uc790\uac00 \ubbf8\ub9ac \ucc29\uc624\ub97c \uc774\uc720\ub85c \ud55c \ucde8\uc18c\uad8c\uc744 \ubc30\uc81c\ud558\uae30\ub85c \ud558\ub294 \ud2b9\uc57d\uc758 \ud6a8\ub825\uc740?",B.aMu,1,"\ucc29\uc624\ucde8\uc18c\uc5d0 \uad00\ud55c \ubbfc\ubc95 \uc81c109\uc870\ub294 \uc784\uc758\uaddc\uc815\uc73c\ub85c \uc774\ud574\ub418\ubbc0\ub85c, \ub2f9\uc0ac\uc790\uac00 \ud569\uc758\ub85c \ucc29\uc624\ucde8\uc18c\uad8c\uc744 \ubbf8\ub9ac \ubc30\uc81c\ud558\ub294 \ud2b9\uc57d\uc740 \uc0ac\uc801\uc790\uce58\uc758 \uc6d0\uce59\uc0c1 \uc6d0\uce59\uc801\uc73c\ub85c \uc720\ud6a8\ud558\ub2e4.",B.aeY,B.amP,null)
B.a3U=s(["\uc0c1\ub300\ubc29 \uc788\ub294 \uc758\uc0ac\ud45c\uc2dc\uc640 \ub9c8\ucc2c\uac00\uc9c0\ub85c \uc0c1\ub300\ubc29\uc758 \uc778\uc2dd \uc5ec\ubd80\uac00 \uc694\uad6c\ub41c\ub2e4","\uc0c1\ub300\ubc29\uc774 \uc5c6\uc73c\ubbc0\ub85c \uadf8 \uc778\uc2dd \uc5ec\ubd80\ub97c \uc694\uad6c\ud560 \uc218 \uc5c6\uc5b4 \ud45c\uc758\uc790\ub294 \uc5b8\uc81c\ub098 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4","\uc774 \uacbd\uc6b0 \ucde8\uc18c \uc790\uccb4\uac00 \ud5c8\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4","\uc81c3\uc790\uac00 \ucc98\ubc8c\ub41c \uacbd\uc6b0\uc5d0\ub9cc \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.aJd=s(["\uc0c1\ub300\ubc29 \uc5c6\ub294 \ub2e8\ub3c5\ud589\uc704\uc5d0 \uc81c3\uc790\uac00 \uc0ac\uae30\xb7\uac15\ubc15\uc744 \ud589\ud55c \uacbd\uc6b0\uc5d0\ub294 \uc774\ub7ec\ud55c \uc81c\ud55c \uc5c6\uc774 \ud45c\uc758\uc790\uac00 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.aR5=s(["\uc0c1\ub300\ubc29 \uc5c6\ub294 \ub2e8\ub3c5\ud589\uc704\uc640 \uc81c3\uc790\uc758 \uc0ac\uae30\xb7\uac15\ubc15"],t.s)
B.bpw=new A.a("gen_cl_intent_29","civil_law","\uc758\uc0ac\ud45c\uc2dc",null,"\uc0c1\ub300\ubc29 \uc5c6\ub294 \ub2e8\ub3c5\ud589\uc704(\uc608: \uc7ac\ub2e8\ubc95\uc778 \uc124\ub9bd\ud589\uc704)\uc5d0 \uad00\ud558\uc5ec \uc81c3\uc790\uac00 \uc0ac\uae30\xb7\uac15\ubc15\uc744 \ud589\ud55c \uacbd\uc6b0 \ucde8\uc18c \uc694\uac74\uc740?",B.a3U,1,'\ubbfc\ubc95 \uc81c110\uc870 \uc81c2\ud56d\uc758 "\uc0c1\ub300\ubc29\uc774 \uadf8 \uc0ac\uc2e4\uc744 \uc54c\uc558\uac70\ub098 \uc54c \uc218 \uc788\uc5c8\uc744 \uacbd\uc6b0"\ub77c\ub294 \uc81c\ud55c\uc740 \uc0c1\ub300\ubc29 \uc788\ub294 \uc758\uc0ac\ud45c\uc2dc\ub97c \uc804\uc81c\ub85c \ud55c \uac83\uc774\ubbc0\ub85c, \uc0c1\ub300\ubc29 \uc5c6\ub294 \ub2e8\ub3c5\ud589\uc704\uc5d0 \uc81c3\uc790\uac00 \uc0ac\uae30\xb7\uac15\ubc15\uc744 \ud589\ud55c \uacbd\uc6b0\uc5d0\ub294 \uc774\ub7ec\ud55c \uc81c\ud55c \uc5c6\uc774 \ud45c\uc758\uc790\uac00 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4.',B.aJd,B.aR5,null)
B.b3z=s(["\ud45c\uc758\uc790\uac00 \uc758\uc0ac\ud45c\uc2dc\ub97c \ubc1c\uc1a1\ud55c \ub54c \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4(\ubc1c\uc2e0\uc8fc\uc758)","\uadf8 \ud1b5\uc9c0\uac00 \uc0c1\ub300\ubc29\uc5d0\uac8c \ub3c4\ub2ec\ud55c \ub54c \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4(\ub3c4\ub2ec\uc8fc\uc758)","\uc0c1\ub300\ubc29\uc774 \uadf8 \ub0b4\uc6a9\uc744 \uc2e4\uc81c\ub85c \uc77d\uc740 \ub54c \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4","\uc758\uc0ac\ud45c\uc2dc\ub294 \uc791\uc131\ud55c \ub0a0\uc9dc\ub97c \uae30\uc900\uc73c\ub85c \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4"],t.s)
B.aZK=s(["\uc0c1\ub300\ubc29 \uc788\ub294 \uc758\uc0ac\ud45c\uc2dc\ub294 \uadf8 \ud1b5\uc9c0\uac00 \uc0c1\ub300\ubc29\uc5d0\uac8c \ub3c4\ub2ec\ud55c \ub54c\ub85c\ubd80\ud130 \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4(\ub3c4\ub2ec\uc8fc\uc758)"],t.s)
B.bdo=s(["\uc758\uc0ac\ud45c\uc2dc\uc758 \ud6a8\ub825\ubc1c\uc0dd\uc2dc\uae30"],t.s)
B.bG6=new A.a("gen_cl_intent_30","civil_law","\uc758\uc0ac\ud45c\uc2dc",null,"\uc0c1\ub300\ubc29 \uc788\ub294 \uc758\uc0ac\ud45c\uc2dc\uc758 \ud6a8\ub825\ubc1c\uc0dd\uc2dc\uae30(\uc81c111\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.b3z,1,"\ubbfc\ubc95 \uc81c111\uc870 \uc81c1\ud56d\uc5d0 \ub530\ub77c \uc0c1\ub300\ubc29 \uc788\ub294 \uc758\uc0ac\ud45c\uc2dc\ub294 \uadf8 \ud1b5\uc9c0\uac00 \uc0c1\ub300\ubc29\uc5d0\uac8c \ub3c4\ub2ec\ud55c \ub54c\ub85c\ubd80\ud130 \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4(\ub3c4\ub2ec\uc8fc\uc758). \ub610\ud55c \uac19\uc740 \uc870 \uc81c2\ud56d\uc5d0 \ub530\ub77c \ud45c\uc758\uc790\uac00 \ud1b5\uc9c0\ub97c \ubc1c\uc1a1\ud55c \ud6c4 \uc0ac\ub9dd\ud558\uac70\ub098 \uc81c\ud55c\ub2a5\ub825\uc790\uac00 \ub418\uc5b4\ub3c4 \uc758\uc0ac\ud45c\uc2dc\uc758 \ud6a8\ub825\uc5d0 \uc601\ud5a5\uc744 \ubbf8\uce58\uc9c0 \uc544\ub2c8\ud55c\ub2e4.",B.aZK,B.bdo,null)
B.anm=s(["\uae09\ubd80\uc640 \ubc18\ub300\uae09\ubd80 \uc0ac\uc774\uc5d0 \ubd88\uade0\ud615\uc774 \uc870\uae08\uc774\ub77c\ub3c4 \uc788\uc73c\uba74 \uc131\ub9bd\ud55c\ub2e4","\ub2f9\uc0ac\uc790 \uc77c\ubc29\uc758 \uad81\ubc15\xb7\uacbd\uc194 \ub610\ub294 \ubb34\uacbd\ud5d8\uc744 \uc774\uc6a9\ud558\uc5ec \ud604\uc800\ud558\uac8c \uacf5\uc815\uc744 \uc783\uc740 \ubc95\ub960\ud589\uc704\uc77c \uac83","\uacc4\uc57d\uc11c\uac00 \uc791\uc131\ub418\uc9c0 \uc54a\uc740 \uad6c\ub450 \uacc4\uc57d\uc77c \uac83","\uacc4\uc57d\uae08\uc774 \uc9c0\uae09\ub418\uc9c0 \uc54a\uc558\uc744 \uac83"],t.s)
B.apV=s(["\ub2f9\uc0ac\uc790 \uc77c\ubc29\uc758 \uad81\ubc15, \uacbd\uc194 \ub610\ub294 \ubb34\uacbd\ud5d8\uc73c\ub85c \uc778\ud558\uc5ec \ud604\uc800\ud558\uac8c \uacf5\uc815\uc744 \uc783\uc740 \ubc95\ub960\ud589\uc704\ub294 \ubb34\ud6a8\ub85c \ud55c\ub2e4"],t.s)
B.an9=s(["\uc81c104\uc870 \uc694\uac74 \uac1c\uad00"],t.s)
B.bxk=new A.a("gen_cl_unfair_1","civil_law","\ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704",null,"\ubbfc\ubc95 \uc81c104\uc870\uac00 \uc815\ud558\ub294 \ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704\uc758 \uc694\uac74\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.anm,1,"\ubbfc\ubc95 \uc81c104\uc870\ub294 \ub2f9\uc0ac\uc790 \uc77c\ubc29\uc758 \uad81\ubc15, \uacbd\uc194 \ub610\ub294 \ubb34\uacbd\ud5d8\uc73c\ub85c \uc778\ud558\uc5ec \ud604\uc800\ud558\uac8c \uacf5\uc815\uc744 \uc783\uc740 \ubc95\ub960\ud589\uc704\ub294 \ubb34\ud6a8\ub85c \ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ub2e8\uc21c\ud55c \ubd88\uade0\ud615\ub9cc\uc73c\ub85c\ub294 \ubd80\uc871\ud558\uace0 \uad81\ubc15\xb7\uacbd\uc194\xb7\ubb34\uacbd\ud5d8\uc774\ub77c\ub294 \uc8fc\uad00\uc801 \uc694\uac74\uacfc \ud604\uc800\ud55c \ubd88\uacf5\uc815\uc774\ub77c\ub294 \uac1d\uad00\uc801 \uc694\uac74\uc774 \ud568\uaed8 \uc694\uad6c\ub41c\ub2e4.",B.apV,B.an9,null)
B.asb=s(["\uacbd\uc81c\uc801 \uc5b4\ub824\uc6c0\ub9cc\uc744 \uc758\ubbf8\ud558\uace0 \uc815\uc2e0\uc801 \uc5b4\ub824\uc6c0\uc740 \ud3ec\ud568\ub418\uc9c0 \uc54a\ub294\ub2e4","\uacbd\uc81c\uc801 \uad81\ubc15\ubfd0 \uc544\ub2c8\ub77c \uc815\uc2e0\uc801\xb7\uc2ec\ub9ac\uc801 \uad81\ubc15\ub3c4 \ud3ec\ud568\ud558\ub294 \uac1c\ub150\uc774\ub2e4","\ubc18\ub4dc\uc2dc \ud30c\uc0b0 \uc0c1\ud0dc\uc5d0 \uc774\ub978 \uacbd\uc6b0\ub9cc\uc744 \uc758\ubbf8\ud55c\ub2e4","\ubbf8\uc131\ub144\uc790\uc778 \uacbd\uc6b0\uc5d0\ub9cc \uc778\uc815\ub418\ub294 \uac1c\ub150\uc774\ub2e4"],t.s)
B.a4F=s(["\uad81\ubc15\uc774\ub780 \uae09\ubc15\ud55c \uace4\uad81\uc744 \uc758\ubbf8\ud558\uba70, \uacbd\uc81c\uc801 \uc6d0\uc778\uc5d0 \uae30\uc778\ud558\ub294 \uac83\ubfd0\ub9cc \uc544\ub2c8\ub77c \uc815\uc2e0\uc801 \ub610\ub294 \uc2ec\ub9ac\uc801 \uc6d0\uc778\uc5d0 \uae30\uc778\ud558\ub294 \uac83\ub3c4 \ud3ec\ud568\ud558\ub294 \uac1c\ub150\uc73c\ub85c \ub113\uac8c \ud574\uc11d\ub41c\ub2e4"],t.s)
B.be3=s(["\uad81\ubc15\uc758 \uc758\ubbf8"],t.s)
B.bp8=new A.a("gen_cl_unfair_2","civil_law","\ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704",null,'\ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704\uc758 \uc694\uac74\uc778 "\uad81\ubc15"\uc758 \uc758\ubbf8\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?',B.asb,1,"\ud310\ub840\uc0c1 \uad81\ubc15\uc774\ub780 \uae09\ubc15\ud55c \uace4\uad81\uc744 \uc758\ubbf8\ud558\uba70, \uacbd\uc81c\uc801 \uc6d0\uc778\uc5d0 \uae30\uc778\ud558\ub294 \uac83\ubfd0\ub9cc \uc544\ub2c8\ub77c \uc815\uc2e0\uc801 \ub610\ub294 \uc2ec\ub9ac\uc801 \uc6d0\uc778\uc5d0 \uae30\uc778\ud558\ub294 \uac83\ub3c4 \ud3ec\ud568\ud558\ub294 \uac1c\ub150\uc73c\ub85c \ub113\uac8c \ud574\uc11d\ub41c\ub2e4.",B.a4F,B.be3,null)
B.aJo=s(["\uc758\uc0ac\ub97c \uacb0\uc815\ud560 \ub54c \ubcf4\ud1b5\uc778\uc5d0\uac8c \uc694\uad6c\ub418\ub294 \uc2e0\uc911\uc131\uc744 \uac16\ucd94\uc9c0 \ubabb\ud55c \uc0c1\ud0dc\ub97c \ub9d0\ud55c\ub2e4","\ubc18\ub4dc\uc2dc \ubbf8\uc131\ub144\uc790\uc5d0\uac8c\ub9cc \uc778\uc815\ub418\ub294 \uc0c1\ud0dc\ub97c \ub9d0\ud55c\ub2e4","\uac70\ub798 \uacbd\ud5d8\uc774 \uc804\ud600 \uc5c6\ub294 \uc0c1\ud0dc\ub97c \ub9d0\ud55c\ub2e4","\uacc4\uc57d\uc11c\ub97c \uc77d\uc9c0 \uc54a\uace0 \uc11c\uba85\ud55c \ubaa8\ub4e0 \uacbd\uc6b0\ub97c \ub9d0\ud55c\ub2e4"],t.s)
B.Yo=s(["\uacbd\uc194\uc774\ub780 \uc758\uc0ac\ub97c \uacb0\uc815\ud568\uc5d0 \uc788\uc5b4 \ubcf4\ud1b5\uc778\uc5d0\uac8c \uc694\uad6c\ub418\ub294 \uc815\ub3c4\uc758 \uc2e0\uc911\ud55c \uace0\ub824\ub97c \ud558\uc9c0 \uc544\ub2c8\ud55c \uc2ec\ub9ac\uc0c1\ud0dc\ub97c \ub9d0\ud55c\ub2e4"],t.s)
B.Yt=s(["\uacbd\uc194\uc758 \uc758\ubbf8"],t.s)
B.bRs=new A.a("gen_cl_unfair_3","civil_law","\ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704",null,'\ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704\uc758 \uc694\uac74\uc778 "\uacbd\uc194"\uc758 \uc758\ubbf8\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?',B.aJo,0,"\uacbd\uc194\uc774\ub780 \uc758\uc0ac\ub97c \uacb0\uc815\ud568\uc5d0 \uc788\uc5b4 \ubcf4\ud1b5\uc778\uc5d0\uac8c \uc694\uad6c\ub418\ub294 \uc815\ub3c4\uc758 \uc2e0\uc911\ud55c \uace0\ub824\ub97c \ud558\uc9c0 \uc544\ub2c8\ud55c \uc2ec\ub9ac\uc0c1\ud0dc\ub97c \ub9d0\ud55c\ub2e4. \uc774\ub294 \ubb34\uacbd\ud5d8\uacfc \uad6c\ubcc4\ub418\ub294 \ubcc4\uac1c\uc758 \ub3c5\ub9bd\uc801 \uc694\uac74\uc774\ub2e4.",B.Yo,B.Yt,null)
B.a71=s(["\ud2b9\uc815 \uac70\ub798\ubd84\uc57c\uc5d0\uc11c\uc758 \uacbd\ud5d8\ubd80\uc871\ub9cc\uc744 \uc758\ubbf8\ud55c\ub2e4","\uac70\ub798\uc77c\ubc18\uc5d0 \ub300\ud55c \uacbd\ud5d8\ubd80\uc871\uc744 \uc758\ubbf8\ud558\uba70 \ud2b9\uc815 \ubd84\uc57c\uc5d0 \uad6d\ud55c\ub418\uc9c0 \uc54a\ub294\ub2e4","\ud559\ub825\uc774 \ub0ae\uc740 \uac83\uc744 \uc758\ubbf8\ud55c\ub2e4","\uc5f0\ub839\uc774 \uc5b4\ub9b0 \uac83\ub9cc\uc744 \uc758\ubbf8\ud55c\ub2e4"],t.s)
B.aea=s(["\ubb34\uacbd\ud5d8\uc774\ub780 \uc5b4\ub290 \ud2b9\uc815\uc601\uc5ed\uc5d0\uc11c\uc758 \uacbd\ud5d8\ubd80\uc871\uc774 \uc544\ub2c8\ub77c \uac70\ub798\uc77c\ubc18\uc5d0 \ub300\ud55c \uacbd\ud5d8\ubd80\uc871\uc744 \uc758\ubbf8\ud55c\ub2e4"],t.s)
B.a3B=s(["\ubb34\uacbd\ud5d8\uc758 \uc758\ubbf8"],t.s)
B.bxB=new A.a("gen_cl_unfair_4","civil_law","\ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704",null,'\ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704\uc758 \uc694\uac74\uc778 "\ubb34\uacbd\ud5d8"\uc758 \uc758\ubbf8\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?',B.a71,1,"\ud310\ub840\uc0c1 \ubb34\uacbd\ud5d8\uc774\ub780 \uc5b4\ub290 \ud2b9\uc815\uc601\uc5ed\uc5d0\uc11c\uc758 \uacbd\ud5d8\ubd80\uc871\uc774 \uc544\ub2c8\ub77c \uac70\ub798\uc77c\ubc18\uc5d0 \ub300\ud55c \uacbd\ud5d8\ubd80\uc871\uc744 \uc758\ubbf8\ud55c\ub2e4. \uc989 \ud574\ub2f9 \uac70\ub798 \ubd84\uc57c\uc5d0 \ub300\ud55c \uc9c0\uc2dd\uc774 \uc788\ub354\ub77c\ub3c4 \uac70\ub798 \uacbd\ud5d8 \uc804\ubc18\uc774 \ubd80\uc871\ud558\uba74 \ubb34\uacbd\ud5d8 \uc694\uac74\uc774 \uc778\uc815\ub420 \uc218 \uc788\ub2e4.",B.aea,B.a3B,null)
B.b58=s(["\uc138 \uac00\uc9c0 \uc694\uac74\uc744 \ubaa8\ub450 \uac16\ucd94\uc5b4\uc57c\ub9cc \uc131\ub9bd\ud55c\ub2e4","\uc138 \uac00\uc9c0 \uc911 \uc5b4\ub290 \ud558\ub098\ub9cc \uac16\ucd94\uc5b4\ub3c4 \ucda9\uc871\ub418\ub294 \ud0dd\uc77c\uc801 \uc694\uac74\uc774\ub2e4","\uad81\ubc15\ub9cc \uc788\uc73c\uba74 \ub098\uba38\uc9c0\ub294 \uc694\uad6c\ub418\uc9c0 \uc54a\ub294\ub2e4","\uacbd\uc194\uacfc \ubb34\uacbd\ud5d8\ub9cc \uc788\uc73c\uba74 \uad81\ubc15\uc740 \uc694\uad6c\ub418\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.aRw=s(["\uad81\ubc15\xb7\uacbd\uc194\xb7\ubb34\uacbd\ud5d8\uc740 \uadf8 \ubaa8\ub450\uac00 \uad6c\ube44\ub418\uc5b4\uc57c \ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub77c, \uadf8\uc911 \uc77c\ubd80\ub9cc \uac16\ucd94\uc5b4\uc838\ub3c4 \ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704\uc758 \uc694\uac74\uc73c\ub85c \ucda9\ubd84\ud558\ub2e4\uace0 \ubcf8\ub2e4"],t.s)
B.UE=s(["\uc694\uac74\uc758 \ud0dd\uc77c\uc801 \uc131\uaca9"],t.s)
B.bRV=new A.a("gen_cl_unfair_5","civil_law","\ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704",null,"\ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704\uac00 \uc131\ub9bd\ud558\uae30 \uc704\ud574 \uad81\ubc15\xb7\uacbd\uc194\xb7\ubb34\uacbd\ud5d8\uc744 \ubaa8\ub450 \uac16\ucd94\uc5b4\uc57c \ud558\ub294\uc9c0\uc5d0 \uad00\ud55c \ud310\ub840\uc758 \ud0dc\ub3c4\ub294?",B.b58,1,"\ud310\ub840\ub294 \uad81\ubc15\xb7\uacbd\uc194\xb7\ubb34\uacbd\ud5d8\uc740 \uadf8 \ubaa8\ub450\uac00 \uad6c\ube44\ub418\uc5b4\uc57c \ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub77c, \uadf8\uc911 \uc77c\ubd80\ub9cc \uac16\ucd94\uc5b4\uc838\ub3c4 \ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704\uc758 \uc694\uac74\uc73c\ub85c \ucda9\ubd84\ud558\ub2e4\uace0 \ubcf8\ub2e4. \uc989 \ud0dd\uc77c\uc801 \uc694\uac74\uc73c\ub85c \uc774\ud574\ub41c\ub2e4.",B.aRw,B.UE,null)
B.UV=s(["\ubc95\ub960\ud589\uc704 \ub2f9\uc2dc\ub97c \uae30\uc900\uc73c\ub85c \ud310\ub2e8\ud55c\ub2e4","\uc774\ud589\uc774 \uc644\ub8cc\ub41c \ub54c\ub97c \uae30\uc900\uc73c\ub85c \ud310\ub2e8\ud55c\ub2e4","\ubd84\uc7c1\uc774 \uc18c\uc1a1\uc73c\ub85c \uc81c\uae30\ub41c \ub54c\ub97c \uae30\uc900\uc73c\ub85c \ud310\ub2e8\ud55c\ub2e4","\ubaa9\uc801\ubb3c\uc758 \uc2dc\uac00\uac00 \uac00\uc7a5 \ub192\uc558\ub358 \ub54c\ub97c \uae30\uc900\uc73c\ub85c \ud310\ub2e8\ud55c\ub2e4"],t.s)
B.aO4=s(["\uae09\ubd80\uc640 \ubc18\ub300\uae09\ubd80 \uc0ac\uc774\uc5d0 \ud604\uc800\ud55c \ubd88\uade0\ud615\uc774 \uc788\ub294\uc9c0 \uc5ec\ubd80\ub294 \ubc95\ub960\ud589\uc704\uac00 \uc774\ub8e8\uc5b4\uc9c4 \ub2f9\uc2dc\ub97c \uae30\uc900\uc73c\ub85c \ud310\ub2e8\ud558\uc5ec\uc57c \ud55c\ub2e4\uace0 \ubcf8\ub2e4"],t.s)
B.b8f=s(["\ud604\uc800\ud55c \ubd88\uade0\ud615\uc758 \ud310\ub2e8\uc2dc\uc810"],t.s)
B.bOb=new A.a("gen_cl_unfair_6","civil_law","\ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704",null,'\uae09\ubd80\uc640 \ubc18\ub300\uae09\ubd80 \uc0ac\uc774\uc758 "\ud604\uc800\ud55c \ubd88\uade0\ud615" \uc5ec\ubd80\ub294 \uc5b4\ub290 \uc2dc\uc810\uc744 \uae30\uc900\uc73c\ub85c \ud310\ub2e8\ud558\ub294\uac00?',B.UV,0,"\ud310\ub840\ub294 \uae09\ubd80\uc640 \ubc18\ub300\uae09\ubd80 \uc0ac\uc774\uc5d0 \ud604\uc800\ud55c \ubd88\uade0\ud615\uc774 \uc788\ub294\uc9c0 \uc5ec\ubd80\ub294 \ubc95\ub960\ud589\uc704\uac00 \uc774\ub8e8\uc5b4\uc9c4 \ub2f9\uc2dc\ub97c \uae30\uc900\uc73c\ub85c \ud310\ub2e8\ud558\uc5ec\uc57c \ud55c\ub2e4\uace0 \ubcf8\ub2e4. \uc0ac\ud6c4\uc758 \uac00\uaca9 \ubcc0\ub3d9\uc740 \ud310\ub2e8\uc758 \uae30\ucd08\uac00 \ub418\uc9c0 \uc54a\ub294\ub2e4.",B.aO4,B.b8f,null)
B.azt=s(["\uc0c1\ub300\ubc29\uc758 \uad81\ubc15 \ub4f1 \uc0ac\uc815\uc744 \ub2e8\uc21c\ud788 \uc54c\uace0 \uc788\uc5c8\ub2e4\ub294 \uac83\ub9cc\uc73c\ub85c \ucda9\ubd84\ud558\ub2e4","\uc0c1\ub300\ubc29\uc758 \uad81\ubc15\xb7\uacbd\uc194\xb7\ubb34\uacbd\ud5d8 \ub4f1\uc758 \uc0ac\uc815\uc744 \uc54c\uace0 \uc774\ub97c \uc774\uc6a9\ud558\ub824\ub294 \uc758\uc0ac\uae4c\uc9c0 \uc788\uc5b4\uc57c \ud55c\ub2e4","\ud3ed\ub9ac\ud589\uc704\uc790\uc5d0\uac8c \ud615\uc0ac\uc0c1 \uace0\uc758\uac00 \uc788\uc5b4\uc57c \ud55c\ub2e4","\ud3ed\ub9ac\ud589\uc704\uc790\uac00 \uacc4\uc57d\uc11c\ub97c \uc9c1\uc811 \uc791\uc131\ud558\uc600\uc5b4\uc57c \ud55c\ub2e4"],t.s)
B.am_=s(["\uc0c1\ub300\ubc29\uc758 \uad81\ubc15\xb7\uacbd\uc194\xb7\ubb34\uacbd\ud5d8 \ub4f1\uc758 \uc0ac\uc815\uc744 \ub2e8\uc21c\ud788 \uc778\uc2dd\ud558\ub294 \uac83\ub9cc\uc73c\ub85c\ub294 \ubd80\uc871\ud558\uace0","\uc774\ub97c \uc54c\uba74\uc11c \uc774\uc6a9\ud558\ub824\ub294 \uc758\uc0ac(\ud3ed\ub9ac\ud589\uc704\uc758 \uc545\uc758)\uae4c\uc9c0 \uc788\uc5b4\uc57c \ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704\uac00 \uc131\ub9bd\ud55c\ub2e4\uace0 \ubcf8\ub2e4"],t.s)
B.aKF=s(["\ud3ed\ub9ac\ud589\uc704\uc790\uc758 \uc774\uc6a9\uc758\uc0ac"],t.s)
B.bzj=new A.a("gen_cl_unfair_7","civil_law","\ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704",null,'\ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704\uac00 \uc131\ub9bd\ud558\uae30 \uc704\ud55c "\ud3ed\ub9ac\ud589\uc704\uc790\uc758 \uc545\uc758"\ub780 \ubb34\uc5c7\uc744 \uc758\ubbf8\ud558\ub294\uac00?',B.azt,1,"\ud310\ub840\ub294 \uc0c1\ub300\ubc29\uc758 \uad81\ubc15\xb7\uacbd\uc194\xb7\ubb34\uacbd\ud5d8 \ub4f1\uc758 \uc0ac\uc815\uc744 \ub2e8\uc21c\ud788 \uc778\uc2dd\ud558\ub294 \uac83\ub9cc\uc73c\ub85c\ub294 \ubd80\uc871\ud558\uace0, \uc774\ub97c \uc54c\uba74\uc11c \uc774\uc6a9\ud558\ub824\ub294 \uc758\uc0ac(\ud3ed\ub9ac\ud589\uc704\uc758 \uc545\uc758)\uae4c\uc9c0 \uc788\uc5b4\uc57c \ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704\uac00 \uc131\ub9bd\ud55c\ub2e4\uace0 \ubcf8\ub2e4.",B.am_,B.aKF,null)
B.aiV=s(["\ubb34\ud6a8\ub97c \uc8fc\uc7a5\ud558\ub294 \uc790\uac00 \uad81\ubc15\xb7\uacbd\uc194\xb7\ubb34\uacbd\ud5d8, \ud604\uc800\ud55c \ubd88\uade0\ud615, \ud3ed\ub9ac\ud589\uc704\uc790\uc758 \uc545\uc758\ub97c \ubaa8\ub450 \uc8fc\uc7a5\xb7\uc99d\uba85\ud558\uc5ec\uc57c \ud55c\ub2e4","\uc0c1\ub300\ubc29(\ud3ed\ub9ac\ud589\uc704\uc790\ub85c \uc9c0\ubaa9\ub41c \uc790)\uc774 \uc790\uc2e0\uc758 \uc120\uc758\ub97c \uc99d\uba85\ud558\uc5ec\uc57c \ud55c\ub2e4","\ubc95\uc6d0\uc774 \uc9c1\uad8c\uc73c\ub85c \uc870\uc0ac\ud558\uc5ec \ud310\ub2e8\ud55c\ub2e4","\uacc4\uc57d\uc11c \uc791\uc131\uc790\uac00 \uc99d\uba85\ucc45\uc784\uc744 \uc9c4\ub2e4"],t.s)
B.ahI=s(["\ubb34\ud6a8\ub97c \uc8fc\uc7a5\ud558\ub294 \uc790\uac00 \uad81\ubc15\xb7\uacbd\uc194\xb7\ubb34\uacbd\ud5d8 \ub4f1\uc758 \uc0ac\uc815, \uae09\ubd80\uc640 \ubc18\ub300\uae09\ubd80\uc758 \ud604\uc800\ud55c \ubd88\uade0\ud615, \uadf8\ub9ac\uace0 \uc0c1\ub300\ubc29\uc758 \ud3ed\ub9ac\ud589\uc704\uc5d0 \ub300\ud55c \uc545\uc758(\uc774\uc6a9\uc758\uc0ac)\ub97c \ubaa8\ub450 \uc8fc\uc7a5\xb7\uc99d\uba85\ud558\uc5ec\uc57c \ud55c\ub2e4\uace0 \ubcf8\ub2e4"],t.s)
