B.bcE=s(["\ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704\uc758 \ud6a8\uacfc"],t.s)
B.bIF=new A.a("gen_cl_unfair_12","civil_law","\ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704",null,"\ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704\uc5d0 \ud574\ub2f9\ud558\ub294 \uac83\uc73c\ub85c \uc778\uc815\ub41c \uacbd\uc6b0\uc758 \ud6a8\uacfc\ub294?",B.bda,1,"\ubbfc\ubc95 \uc81c104\uc870\ub294 \uadf8 \uc694\uac74\uc744 \ucda9\uc871\ud55c \ubc95\ub960\ud589\uc704\ub97c \ubb34\ud6a8\ub85c \ud55c\ub2e4\uace0 \uba85\uc2dc\ud558\uace0 \uc788\ub2e4. \ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704(\uc81c103\uc870)\uc640 \ub9c8\ucc2c\uac00\uc9c0\ub85c \ucde8\uc18c\uac00 \uc544\ub2c8\ub77c \ucc98\uc74c\ubd80\ud130 \ud6a8\ub825\uc774 \uc5c6\ub294 \ubb34\ud6a8\uc774\ub2e4.",B.beA,B.bcE,null)
B.aA_=s(["\ucd94\uc778\ud558\uba74 \uc18c\uae09\ud558\uc5ec \uc720\ud6a8\ub85c \ub41c\ub2e4","\ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704\uc640 \ub9c8\ucc2c\uac00\uc9c0\ub85c \ubb34\ud6a8\ud589\uc704\uc758 \ucd94\uc778 \ubc95\ub9ac(\uc81c139\uc870)\uac00 \uc801\uc6a9\ub418\uc9c0 \uc54a\uc544 \ucd94\uc778\ud574\ub3c4 \uc720\ud6a8\ub85c \ub418\uc9c0 \uc54a\ub294\ub2e4","\ucd94\uc778 \uc2dc\uc810\ubd80\ud130 \uc7a5\ub798\ub97c \ud5a5\ud558\uc5ec \uc720\ud6a8\ub85c \ub41c\ub2e4","\uc0c1\ub300\ubc29\uc774 \ub3d9\uc758\ud558\uba74 \uc720\ud6a8\ub85c \uc804\ud658\ub41c\ub2e4"],t.s)
