B.bRX=new A.a("gen_cl_cond_10","civil_law","\uc870\uac74\uacfc \uae30\ud55c",null,"\uc870\uac74\uc774 \ubc95\ub960\ud589\uc704 \ub2f9\uc2dc \uc774\ubbf8 \uc131\ucde8\ud55c \uac83\uc778 \uacbd\uc6b0(\uae30\uc131\uc870\uac74, \uc81c151\uc870 \uc81c2\ud56d)\uc758 \ud6a8\uacfc\ub85c \uc633\uc740 \uac83\uc740?",B.Su,0,"\ubbfc\ubc95 \uc81c151\uc870 \uc81c2\ud56d\uc5d0 \ub530\ub77c \uc870\uac74\uc774 \ubc95\ub960\ud589\uc704\uc758 \ub2f9\uc2dc \uc774\ubbf8 \uc131\ucde8\ud55c \uac83\uc778 \uacbd\uc6b0\uc5d0\ub294, \uadf8 \uc870\uac74\uc774 \uc815\uc9c0\uc870\uac74\uc774\uba74 \uc870\uac74 \uc5c6\ub294 \ubc95\ub960\ud589\uc704\ub85c \ud558\uace0 \ud574\uc81c\uc870\uac74\uc774\uba74 \uadf8 \ubc95\ub960\ud589\uc704\ub294 \ubb34\ud6a8\ub85c \ud55c\ub2e4.",B.a_9,B.bcx,null)
B.Wm=s(["\uc815\uc9c0\uc870\uac74\uc774\uba74 \uadf8 \ubc95\ub960\ud589\uc704\ub294 \ubb34\ud6a8\ub85c \ub418\uace0, \ud574\uc81c\uc870\uac74\uc774\uba74 \uc870\uac74 \uc5c6\ub294 \ubc95\ub960\ud589\uc704\ub85c \ub41c\ub2e4","\uc815\uc9c0\uc870\uac74\uc774\ub4e0 \ud574\uc81c\uc870\uac74\uc774\ub4e0 \ud56d\uc0c1 \uc720\ud6a8\ud558\ub2e4","\uc815\uc9c0\uc870\uac74\uc774\uba74 \uc870\uac74 \uc5c6\ub294 \ubc95\ub960\ud589\uc704, \ud574\uc81c\uc870\uac74\uc774\uba74 \ubb34\ud6a8\ub85c \ub41c\ub2e4","\ubd88\ub2a5\uc870\uac74\uc740 \uae30\uc131\uc870\uac74\uacfc \ub3d9\uc77c\ud558\uac8c \ucde8\uae09\ub418\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc810\uc5d0\uc11c \ucc28\uc774\uac00 \uc5c6\ub2e4"],t.s)
B.amn=s(["\uadf8 \uc870\uac74\uc774 \uc815\uc9c0\uc870\uac74\uc774\uba74 \uadf8 \ubc95\ub960\ud589\uc704\ub294 \ubb34\ud6a8\ub85c \ud558\uace0 \ud574\uc81c\uc870\uac74\uc774\uba74 \uc870\uac74 \uc5c6\ub294 \ubc95\ub960\ud589\uc704\ub85c \ud55c\ub2e4"],t.s)
