B.bxr=new A.a("gen_cl_revoc_3","civil_law","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704",null,"\ucde8\uc18c\uc758 \ud6a8\uacfc\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aJB,0,"\ubbfc\ubc95 \uc81c141\uc870\uc5d0 \ub530\ub77c \ucde8\uc18c\ub41c \ubc95\ub960\ud589\uc704\ub294 \ucc98\uc74c\ubd80\ud130 \ubb34\ud6a8\uc778 \uac83\uc73c\ub85c \ubcf8\ub2e4(\uc18c\uae09\uc801 \ubb34\ud6a8). \ub530\ub77c\uc11c \uc774\ubbf8 \uc774\ud589\ub41c \uac83\uc774 \uc788\ub2e4\uba74 \ubd80\ub2f9\uc774\ub4dd\uc73c\ub85c \ubc18\ud658\ud574\uc57c \ud558\uba70, \uc81c\ud55c\ub2a5\ub825\uc790\ub294 \uadf8 \ubc1b\uc740 \uc774\uc775\uc774 \ud604\uc874\ud558\ub294 \ud55c\ub3c4\uc5d0\uc11c\ub9cc \ubc18\ud658\uc758\ubb34\ub97c \uc9c4\ub2e4.",B.b4Z,B.a6b,null)
B.aqR=s(["\ubc1b\uc740 \uc774\uc775 \uc804\ubd80\ub97c \ubc18\ud658\ud574\uc57c \ud55c\ub2e4","\ubc1b\uc740 \uc774\uc775\uc774 \ud604\uc874\ud558\ub294 \ud55c\ub3c4\uc5d0\uc11c\ub9cc \ubc18\ud658\ud558\uba74 \ub41c\ub2e4","\uc774\uc775\uc758 \ud604\uc874 \uc5ec\ubd80\uc640 \uad00\uacc4\uc5c6\uc774 \ubc18\ud658\uc758\ubb34\uac00 \uc5c6\ub2e4","\ubc95\uc815\ub300\ub9ac\uc778\uc774 \ub300\uc2e0 \uc804\ubd80 \ubc18\ud658\ud574\uc57c \ud55c\ub2e4"],t.s)
B.aWo=s(["\ubc1b\uc740 \uc774\uc775\uc774 \ud604\uc874\ud558\ub294 \ud55c\ub3c4\uc5d0\uc11c\ub9cc \ubc18\ud658\ud560 \ucc45\uc784\uc744 \uc9c4\ub2e4"],t.s)
B.aWa=s(["\uc81c\ud55c\ub2a5\ub825\uc790\uc758 \ubc18\ud658\uc758\ubb34 \ubc94\uc704"],t.s)
B.bEt=new A.a("gen_cl_revoc_4","civil_law","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704",null,"\uc81c\ud55c\ub2a5\ub825\uc790\uac00 \ucde8\uc18c\ud55c \uacbd\uc6b0, \ubc18\ud658\uc758\ubb34\uc758 \ubc94\uc704\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aqR,1,"\ubbfc\ubc95 \uc81c141\uc870 \ub2e8\uc11c\ub294 \uc81c\ud55c\ub2a5\ub825\uc790\ub97c \ubcf4\ud638\ud558\uae30 \uc704\ud574, \uc81c\ud55c\ub2a5\ub825\uc790\ub294 \uadf8 \ud589\uc704\ub85c \ubc1b\uc740 \uc774\uc775\uc774 \ud604\uc874\ud558\ub294 \ud55c\ub3c4\uc5d0\uc11c\ub9cc \ubc18\ud658\ud560 \ucc45\uc784\uc744 \uc9c4\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc774\ubbf8 \uc18c\ube44\ud574\ubc84\ub9b0 \ubd80\ubd84\uae4c\uc9c0 \ubc18\ud658\ud558\uac8c \ud558\uba74 \uc81c\ud55c\ub2a5\ub825\uc790 \ubcf4\ud638 \ucde8\uc9c0\uac00 \ubb34\uc0c9\ud574\uc9c0\uae30 \ub54c\ubb38\uc774\ub2e4.",B.aWo,B.aWa,null)
B.acH=s(["\ucd94\uc778\ud560 \uc218 \uc788\ub294 \ub0a0\ubd80\ud130 3\ub144, \ubc95\ub960\ud589\uc704\ub97c \ud55c \ub0a0\ubd80\ud130 10\ub144 \ub0b4\uc5d0 \ud589\uc0ac\ud558\uc5ec\uc57c \ud55c\ub2e4","\ucde8\uc18c\uad8c\uc740 \ud589\uc0ac\uae30\uac04\uc758 \uc81c\ud55c\uc774 \uc5c6\ub2e4","\ubc95\ub960\ud589\uc704\ub97c \ud55c \ub0a0\ubd80\ud130 5\ub144 \ub0b4\uc5d0\ub9cc \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4","\ucd94\uc778\ud560 \uc218 \uc788\ub294 \ub0a0\ubd80\ud130 1\ub144 \ub0b4\uc5d0\ub9cc \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4"],t.s)
B.Uh=s(["\ucd94\uc778\ud560 \uc218 \uc788\ub294 \ub0a0\ubd80\ud130 3\ub144, \ubc95\ub960\ud589\uc704\ub97c \ud55c \ub0a0\ubd80\ud130 10\ub144"],t.s)
B.a1N=s(["\ucde8\uc18c\uad8c\uc758 \ub2e8\uae30\uc18c\uba78(\uc81c146\uc870)"],t.s)
B.bsX=new A.a("gen_cl_revoc_5","civil_law","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704",null,"\ucde8\uc18c\uad8c\uc758 \ud589\uc0ac\uae30\uac04\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.acH,0,"\ubbfc\ubc95 \uc81c146\uc870\ub294 \ucde8\uc18c\uad8c\uc744 \ucd94\uc778\ud560 \uc218 \uc788\ub294 \ub0a0\ubd80\ud130 3\ub144 \ub0b4, \ubc95\ub960\ud589\uc704\ub97c \ud55c \ub0a0\ubd80\ud130 10\ub144 \ub0b4\uc5d0 \ud589\uc0ac\ud558\uc5ec\uc57c \ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ub450 \uae30\uac04 \uc911 \uc5b4\ub290 \ud558\ub098\ub77c\ub3c4 \uba3c\uc800 \ub9cc\ub8cc\ub418\uba74 \ucde8\uc18c\uad8c\uc740 \uc18c\uba78\ud55c\ub2e4.",B.Uh,B.a1N,null)
B.aDV=s(["\ucd94\uc778\uc774 \uc788\uc73c\uba74 \uadf8 \ud6c4\uc5d0\ub294 \ucde8\uc18c\ud558\uc9c0 \ubabb\ud55c\ub2e4","\ucd94\uc778\uc740 \ucde8\uc18c\uad8c\uc790\uac00 \ucde8\uc18c\uc6d0\uc778\uc774 \uc885\ub8cc\ub41c \ud6c4\uc5d0 \ud558\uc5ec\uc57c \ud6a8\ub825\uc774 \uc788\ub2e4","\ubc95\uc815\ub300\ub9ac\uc778\uc774\ub098 \uc131\ub144\ud6c4\uacac\uc778\uc740 \ucde8\uc18c\uc6d0\uc778\uc774 \uc885\ub8cc\ub418\uae30 \uc804\uc5d0\ub3c4 \ucd94\uc778\ud560 \uc218 \uc788\ub2e4","\ucd94\uc778\uc740 \uc0c8\ub85c\uc6b4 \ubc95\ub960\ud589\uc704\ub97c \ub2e4\uc2dc \ud558\ub294 \uac83\uc774\ubbc0\ub85c \uc6d0\ub798 \ud589\uc704\uc640 \ubb34\uad00\ud558\ub2e4"],t.s)
B.aHL=s(["\uae30\uc874 \ubc95\ub960\ud589\uc704\ub97c \uadf8\ub300\ub85c \uc720\ud6a8\ud558\uac8c \ud655\uc815\uc2dc\ud0a4\ub294 \uac83"],t.s)
B.aNk=s(["\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ud589\uc704\uc758 \ucd94\uc778(\uc81c143\xb7144\uc870)"],t.s)
B.bno=new A.a("gen_cl_revoc_6","civil_law","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704",null,"\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\uc758 \ucd94\uc778\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aDV,3,"\ucd94\uc778\uc740 \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ud589\uc704\ub97c \ud655\uc815\uc801\uc73c\ub85c \uc720\ud6a8\ud558\uac8c \ub9cc\ub4dc\ub294 \ucde8\uc18c\uad8c\uc790\uc758 \uc758\uc0ac\ud45c\uc2dc\ub85c\uc11c, \uc0c8\ub85c\uc6b4 \ubc95\ub960\ud589\uc704\ub97c \ucc3d\uc124\ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uae30\uc874 \ubc95\ub960\ud589\uc704\ub97c \uadf8\ub300\ub85c \uc720\ud6a8\ud558\uac8c \ud655\uc815\uc2dc\ud0a4\ub294 \uac83\uc774\ub2e4. \ucd94\uc778\uc774 \uc788\uc73c\uba74 \ub2e4\uc2dc \ucde8\uc18c\ud560 \uc218 \uc5c6\ub2e4(\uc81c143\uc870). \uc6d0\uce59\uc801\uc73c\ub85c \ucde8\uc18c\uc758 \uc6d0\uc778\uc774 \uc885\ub8cc\ub41c \ud6c4\uc5d0 \ud558\uc5ec\uc57c \ud558\uba70(\uc81c144\uc870 \uc81c1\ud56d), \ub2e4\ub9cc \ubc95\uc815\ub300\ub9ac\uc778\xb7\uc131\ub144\ud6c4\uacac\uc778\uc740 \uadf8 \uc804\uc5d0\ub3c4 \ucd94\uc778\ud560 \uc218 \uc788\ub2e4(\uc81c144\uc870 \uc81c2\ud56d).",B.aHL,B.aNk,null)
B.aqV=s(["\ucde8\uc18c\uad8c\uc790\uac00 \uc774\uc758\ub97c \ubcf4\ub958\ud558\uc9c0 \uc54a\uace0 \uc77c\uc815\ud55c \ud589\uc704\ub97c \ud558\uba74 \ucd94\uc778\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4","\ubc95\uc815\ucd94\uc778\uc740 \uba85\uc2dc\uc801\uc778 \ucd94\uc778\uc758 \uc758\uc0ac\ud45c\uc2dc\uac00 \uc788\uc5b4\uc57c\ub9cc \uc131\ub9bd\ud55c\ub2e4","\ubc95\uc815\ucd94\uc778 \uc0ac\uc720\uac00 \uc788\uc5b4\ub3c4 \uc5b8\uc81c\ub4e0\uc9c0 \ub2e4\uc2dc \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4","\ubc95\uc815\ucd94\uc778\uc740 \uc81c\ud55c\ub2a5\ub825\uc790\uc5d0\uac8c\ub9cc \uc801\uc6a9\ub41c\ub2e4"],t.s)
B.b3O=s(["\uc774\uc758\ub97c \ubcf4\ub958\ud558\uc9c0 \uc54a\uace0 \uc77c\uc815\ud55c \ud589\uc704\ub97c \ud558\uba74 \ucd94\uc778\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4"],t.s)
B.aak=s(["\ubc95\uc815\ucd94\uc778(\uc81c145\uc870)"],t.s)
B.bAN=new A.a("gen_cl_revoc_7","civil_law","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704",null,"\ubc95\uc815\ucd94\uc778(\uc81c145\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aqV,0,"\ubbfc\ubc95 \uc81c145\uc870\ub294 \ucde8\uc18c\uad8c\uc790\uac00 \uc774\uc758\ub97c \ubcf4\ub958\ud558\uc9c0 \uc54a\uace0 \uc804\ubd80\ub098 \uc77c\ubd80\uc758 \uc774\ud589, \uc774\ud589\uc758 \uccad\uad6c, \uacbd\uac1c, \ub2f4\ubcf4\uc758 \uc81c\uacf5, \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ud589\uc704\ub85c \ucde8\ub4dd\ud55c \uad8c\ub9ac\uc758 \uc804\ubd80\ub098 \uc77c\ubd80\uc758 \uc591\ub3c4, \uac15\uc81c\uc9d1\ud589 \ub4f1\uc758 \ud589\uc704\ub97c \ud55c \ub54c\uc5d0\ub294 \ucd94\uc778\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc774\ub294 \uba85\uc2dc\uc801 \uc758\uc0ac\ud45c\uc2dc \uc5c6\uc774\ub3c4 \uc77c\uc815\ud55c \ud589\uc704\ub85c\ubd80\ud130 \ucd94\uc778\uc758 \uc758\uc0ac\ub97c \ubc95\ub960\uc0c1 \ucd94\uc815(\uac04\uc8fc)\ud558\ub294 \uc81c\ub3c4\uc774\ub2e4.",B.b3O,B.aak,null)
B.SC=s(["\uc804\ubd80\ub098 \uc77c\ubd80\uc758 \uc774\ud589","\uc774\ud589\uc758 \uccad\uad6c","\ucde8\uc18c\uad8c \uc788\uc74c\uc744 \uc8fc\uc7a5\ud558\uba70 \uc774\uc758\ub97c \uc81c\uae30\ud558\ub294 \ud589\uc704","\ub2f4\ubcf4\uc758 \uc81c\uacf5"],t.s)
B.a2y=s(["\uc774\uc758\ub97c \ubcf4\ub958\ud558\uc9c0 \uc54a\uace0"],t.s)
B.Wk=s(["\ubc95\uc815\ucd94\uc778 \uc0ac\uc720(\uc81c145\uc870)"],t.s)
B.bzq=new A.a("gen_cl_revoc_8","civil_law","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704",null,"\ubc95\uc815\ucd94\uc778 \uc0ac\uc720\uc5d0 \ud574\ub2f9\ud558\uc9c0 \uc54a\ub294 \uac83\uc740?",B.SC,2,'\ubc95\uc815\ucd94\uc778\uc740 \ucde8\uc18c\uad8c\uc790\uac00 "\uc774\uc758\ub97c \ubcf4\ub958\ud558\uc9c0 \uc54a\uace0" \uc77c\uc815\ud55c \ud589\uc704\ub97c \ud55c \uacbd\uc6b0\uc5d0 \uc131\ub9bd\ud55c\ub2e4. \uc624\ud788\ub824 \ucde8\uc18c\uad8c\uc774 \uc788\uc74c\uc744 \uc8fc\uc7a5\ud558\uba70 \uc774\uc758\ub97c \uc81c\uae30\ud558\ub294 \ud589\uc704\ub294 \ucd94\uc778\uc758 \uc758\uc0ac\uc640 \uc815\ubc18\ub300\uc774\ubbc0\ub85c \ubc95\uc815\ucd94\uc778 \uc0ac\uc720\uac00 \ub420 \uc218 \uc5c6\ub2e4. \uc804\ubd80\xb7\uc77c\ubd80\uc758 \uc774\ud589, \uc774\ud589\uc758 \uccad\uad6c, \uacbd\uac1c, \ub2f4\ubcf4\uc758 \uc81c\uacf5, \uad8c\ub9ac\uc758 \uc591\ub3c4, \uac15\uc81c\uc9d1\ud589\uc740 \ubaa8\ub450 \ubc95\uc815\ucd94\uc778 \uc0ac\uc720\uc774\ub2e4.',B.a2y,B.Wk,null)
B.a1f=s(["\uc0c1\ub300\ubc29\uc774 \uc788\ub294 \ubc95\ub960\ud589\uc704\uc758 \ucde8\uc18c\ub294 \uadf8 \uc0c1\ub300\ubc29\uc5d0 \ub300\ud55c \uc758\uc0ac\ud45c\uc2dc\ub85c \ud55c\ub2e4","\ucde8\uc18c\ub294 \ubc18\ub4dc\uc2dc \ubc95\uc6d0\uc758 \ud310\uacb0\uc744 \ud1b5\ud574\uc11c\ub9cc \ud560 \uc218 \uc788\ub2e4","\ucde8\uc18c\ub294 \uad00\uacf5\uc11c\uc5d0 \uc2e0\uace0\ud574\uc57c\ub9cc \ud6a8\ub825\uc774 \ubc1c\uc0dd\ud55c\ub2e4","\ucde8\uc18c\uc758 \uc758\uc0ac\ud45c\uc2dc\ub294 \uc11c\uba74\uc73c\ub85c\ub9cc \uac00\ub2a5\ud558\ub2e4"],t.s)
B.acn=s(["\uadf8 \uc0c1\ub300\ubc29\uc5d0 \ub300\ud55c \uc758\uc0ac\ud45c\uc2dc\ub85c \ud55c\ub2e4"],t.s)
B.ar5=s(["\ucde8\uc18c\uc758 \uc0c1\ub300\ubc29(\uc81c142\uc870)"],t.s)
B.bwC=new A.a("gen_cl_revoc_9","civil_law","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704",null,"\ucde8\uc18c\uc758 \uc0c1\ub300\ubc29\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.a1f,0,"\ubbfc\ubc95 \uc81c142\uc870\uc5d0 \ub530\ub77c \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\uc758 \uc0c1\ub300\ubc29\uc774 \ud655\uc815\ub418\uc5b4 \uc788\ub294 \uacbd\uc6b0, \uadf8 \ucde8\uc18c\ub294 \uc0c1\ub300\ubc29\uc5d0 \ub300\ud55c \uc758\uc0ac\ud45c\uc2dc\ub85c \ud558\uba74 \ub41c\ub2e4. \ucde8\uc18c\uad8c\uc740 \ud615\uc131\uad8c\uc73c\ub85c\uc11c \ud2b9\ubcc4\ud55c \uc808\ucc28\ub098 \ubc95\uc6d0\uc758 \ud310\uacb0\uc744 \uc694\ud558\uc9c0 \uc54a\uace0, \ubc29\uc2dd\uc758 \uc81c\ud55c\ub3c4 \uc5c6\ub2e4.",B.acn,B.ar5,null)
B.aLl=s(["\ud615\uc131\uad8c","\uccad\uad6c\uad8c","\ud56d\ubcc0\uad8c","\ubb3c\uad8c\uc801 \uccad\uad6c\uad8c"],t.s)
B.ahk=s(["\ucde8\uc18c\uad8c\uc790\uc758 \uc77c\ubc29\uc801 \uc758\uc0ac\ud45c\uc2dc\ub9cc\uc73c\ub85c \ubc95\ub960\ud589\uc704\uc758 \ud6a8\ub825\uc744 \uc18c\uae09\uc801\uc73c\ub85c \uc18c\uba78\uc2dc\ud0a4\ub294"],t.s)
B.ajL=s(["\ucde8\uc18c\uad8c\uc758 \ubc95\uc801 \uc131\uc9c8"],t.s)
B.bp6=new A.a("gen_cl_revoc_10","civil_law","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704",null,"\ucde8\uc18c\uad8c\uc758 \ubc95\uc801 \uc131\uc9c8\ub85c \uc633\uc740 \uac83\uc740?",B.aLl,0,"\ucde8\uc18c\uad8c\uc740 \ucde8\uc18c\uad8c\uc790\uc758 \uc77c\ubc29\uc801 \uc758\uc0ac\ud45c\uc2dc\ub9cc\uc73c\ub85c \ubc95\ub960\ud589\uc704\uc758 \ud6a8\ub825\uc744 \uc18c\uae09\uc801\uc73c\ub85c \uc18c\uba78\uc2dc\ud0a4\ub294 \uad8c\ub9ac\ub85c\uc11c, \uc0c1\ub300\ubc29\uc758 \uc2b9\ub099\uc774\ub098 \ubc95\uc6d0\uc758 \ud310\uacb0\uc744 \uc694\ud558\uc9c0 \uc54a\ub294 \ub300\ud45c\uc801\uc778 \ud615\uc131\uad8c\uc774\ub2e4.",B.ahk,B.ajL,null)
B.agr=s(["\ucde8\uc18c\ub294 \ucde8\uc18c\uad8c\uc790\ub9cc \uc8fc\uc7a5\ud560 \uc218 \uc788\uc73c\ub098, \ubb34\ud6a8\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \ub204\uad6c\ub098 \uc8fc\uc7a5\ud560 \uc218 \uc788\ub2e4","\ucde8\uc18c\ub294 \ud589\uc0ac\uae30\uac04\uc758 \uc81c\ud55c\uc774 \uc788\uc73c\ub098, \ubb34\ud6a8\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \uae30\uac04 \uc81c\ud55c\uc774 \uc5c6\ub2e4","\ucde8\uc18c\ub294 \ucde8\uc18c \uc804\uae4c\uc9c0 \uc720\ud6a8\uc774\ub098, \ubb34\ud6a8\ub294 \ucc98\uc74c\ubd80\ud130 \ud6a8\ub825\uc774 \uc5c6\ub2e4","\ucde8\uc18c\uc640 \ubb34\ud6a8 \ubaa8\ub450 \ubc95\ub960\ud589\uc704 \uc131\ub9bd \ud6c4 \uc0c1\ub2f9 \uae30\uac04\uc774 \uc9c0\ub098\uba74 \ubc18\ub4dc\uc2dc \uc720\ud6a8\ub85c \uc804\ud658\ub41c\ub2e4"],t.s)
B.aDx=s(['"\uc720\ud6a8\ub85c \uc804\ud658"\ub418\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uadf8 \uc0c1\ud0dc(\uc720\ud6a8)\ub85c \ud655\uc815\ub418\ub294 \uac83'],t.s)
B.W1=s(["\ucde8\uc18c\uc640 \ubb34\ud6a8\uc758 \ube44\uad50"],t.s)
B.bt5=new A.a("gen_cl_revoc_11","civil_law","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704",null,"\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\uc640 \ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\ub97c \ube44\uad50\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.agr,3,'\ucde8\uc18c\uad8c\uc740 \uc81c146\uc870\uc5d0 \ub530\ub77c \uc77c\uc815 \uae30\uac04\uc774 \uc9c0\ub098\uba74 \uc18c\uba78\ud558\uc5ec \ub354 \uc774\uc0c1 \ucde8\uc18c\ud560 \uc218 \uc5c6\uac8c \ub418\uc9c0\ub9cc, \uc774\ub294 "\uc720\ud6a8\ub85c \uc804\ud658"\ub418\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uadf8 \uc0c1\ud0dc(\uc720\ud6a8)\ub85c \ud655\uc815\ub418\ub294 \uac83\uc774\ub2e4. \ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\ub294 \uc2dc\uac04\uc774 \uc9c0\ub098\ub3c4 \uc720\ud6a8\ub85c \uc804\ud658\ub418\uc9c0 \uc54a\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ubbc0\ub85c, "\ubc18\ub4dc\uc2dc \uc720\ud6a8\ub85c \uc804\ud658\ub41c\ub2e4"\ub294 \uc124\uba85\uc740 \uc633\uc9c0 \uc54a\ub2e4.',B.aDx,B.W1,null)
B.axx=s(["\ubc95\ub960\ud589\uc704 \ub0b4\uc6a9\uc758 \uc911\uc694\ubd80\ubd84\uc5d0 \ucc29\uc624\uac00 \uc788\uc73c\uba74 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4","\ucc29\uc624\uac00 \uc788\uc73c\uba74 \ud56d\uc0c1 \ubb34\ud6a8\uc774\ub2e4","\ud45c\uc758\uc790\uc5d0\uac8c \uc911\ub300\ud55c \uacfc\uc2e4\uc774 \uc788\uc5b4\ub3c4 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4","\ucc29\uc624\ub85c \uc778\ud55c \ucde8\uc18c\ub294 \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c\ub3c4 \ub300\ud56d\ud560 \uc218 \uc788\ub2e4"],t.s)
B.aQo=s(["\ubc95\ub960\ud589\uc704 \ub0b4\uc6a9\uc758 \uc911\uc694\ubd80\ubd84\uc5d0 \ucc29\uc624\uac00 \uc788\ub294 \ub54c\uc5d0\ub294 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.ays=s(["\ucc29\uc624\uc5d0 \uc758\ud55c \ucde8\uc18c(\uc81c109\uc870)"],t.s)
B.bpS=new A.a("gen_cl_revoc_12","civil_law","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704",null,"\ucc29\uc624(\uc81c109\uc870)\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\uc758 \ucde8\uc18c\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.axx,0,"\ubbfc\ubc95 \uc81c109\uc870\ub294 \ubc95\ub960\ud589\uc704 \ub0b4\uc6a9\uc758 \uc911\uc694\ubd80\ubd84\uc5d0 \ucc29\uc624\uac00 \uc788\ub294 \ub54c\uc5d0\ub294 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud558\ub418, \ud45c\uc758\uc790\uc5d0\uac8c \uc911\ub300\ud55c \uacfc\uc2e4\uc774 \uc788\ub294 \uacbd\uc6b0\uc5d0\ub294 \ucde8\uc18c\ud558\uc9c0 \ubabb\ud558\ub3c4\ub85d \ud558\uc5ec \uc0c1\ub300\ubc29\uc758 \uc2e0\ub8b0\ub97c \ud568\uaed8 \ubcf4\ud638\ud55c\ub2e4. \ucc29\uc624\ub85c \uc778\ud55c \ucde8\uc18c\ub294 \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c \ub300\ud56d\ud558\uc9c0 \ubabb\ud55c\ub2e4.",B.aQo,B.ays,null)
B.agM=s(["\uae30\ub9dd\uc774\ub098 \ud574\uc545\uc758 \uace0\uc9c0\ub85c \uc778\ud55c \uc758\uc0ac\ud45c\uc2dc\ub294 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4","\uc81c3\uc790\uc758 \uc0ac\uae30\xb7\uac15\ubc15\uc758 \uacbd\uc6b0 \uc0c1\ub300\ubc29\uc774 \uadf8 \uc0ac\uc2e4\uc744 \uc54c\uc558\uac70\ub098 \uc54c \uc218 \uc788\uc5c8\uc744 \ub54c\uc5d0\ub9cc \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4","\uc0ac\uae30\xb7\uac15\ubc15\uc73c\ub85c \uc778\ud55c \ucde8\uc18c\ub294 \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c\ub3c4 \ub300\ud56d\ud560 \uc218 \uc788\ub2e4","\uc0ac\uae30\xb7\uac15\ubc15\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\ub3c4 \uc77c\ub2e8\uc740 \uc720\ud6a8\ud55c \ubc95\ub960\ud589\uc704\ub85c \ucde8\uae09\ub41c\ub2e4"],t.s)
B.avc=s(["\uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c \ub300\ud56d\ud558\uc9c0 \ubabb\ud55c\ub2e4"],t.s)
B.avp=s(["\uc0ac\uae30\xb7\uac15\ubc15\uc5d0 \uc758\ud55c \ucde8\uc18c(\uc81c110\uc870)"],t.s)
B.bCR=new A.a("gen_cl_revoc_13","civil_law","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704",null,"\uc0ac\uae30\xb7\uac15\ubc15(\uc81c110\uc870)\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\uc758 \ucde8\uc18c\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.agM,2,"\ubbfc\ubc95 \uc81c110\uc870 \uc81c3\ud56d\uc5d0 \ub530\ub77c \uc0ac\uae30\xb7\uac15\ubc15\uc73c\ub85c \uc778\ud55c \uc758\uc0ac\ud45c\uc2dc\uc758 \ucde8\uc18c\ub294 \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c \ub300\ud56d\ud558\uc9c0 \ubabb\ud55c\ub2e4. \ube44\uc9c4\uc758\ud45c\uc2dc\xb7\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\xb7\ucc29\uc624\xb7\uc0ac\uae30\uac15\ubc15\uc5d0 \uc758\ud55c \ubb34\ud6a8\xb7\ucde8\uc18c\ub294 \ubaa8\ub450 \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c \ub300\ud56d\ud560 \uc218 \uc5c6\ub2e4\ub294 \uacf5\ud1b5\uc810\uc744 \uac00\uc9c4\ub2e4.",B.avc,B.avp,null)
B.biT=s(["\uc81c\ud55c\ub2a5\ub825\uc790 \ubcf8\uc778\ub3c4 \ub2e8\ub3c5\uc73c\ub85c \ucde8\uc18c\uad8c\uc744 \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4","\uc81c\ud55c\ub2a5\ub825\uc790\ub294 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758 \uc5c6\uc774\ub294 \ucde8\uc18c\uad8c\ub3c4 \ud589\uc0ac\ud560 \uc218 \uc5c6\ub2e4","\ucde8\uc18c\uad8c \ud589\uc0ac\ub294 \ubc95\uc815\ub300\ub9ac\uc778\ub9cc \ud560 \uc218 \uc788\ub2e4","\uc81c\ud55c\ub2a5\ub825\uc790\uc758 \ucde8\uc18c\uad8c\uc740 \uc131\ub144\uc774 \ub420 \ub54c\uae4c\uc9c0 \ud589\uc0ac\ud560 \uc218 \uc5c6\ub2e4"],t.s)
B.aqO=s(["\uc81c\ud55c\ub2a5\ub825\uc790\ub294 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758 \uc5c6\uc774\ub3c4 \ub2e8\ub3c5\uc73c\ub85c \ucde8\uc18c\uad8c\uc744 \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4"],t.s)
B.aYI=s(["\uc81c\ud55c\ub2a5\ub825\uc790\uc758 \ucde8\uc18c\uad8c \ub2e8\ub3c5 \ud589\uc0ac"],t.s)
B.bJ3=new A.a("gen_cl_revoc_14","civil_law","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704",null,"\uc81c\ud55c\ub2a5\ub825\uc790\uc758 \ubc95\ub960\ud589\uc704 \ucde8\uc18c\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.biT,0,'\ubc95\ub960\ud589\uc704\ub97c \ucde8\uc18c\ud558\ub294 \uac83\uc740 \uc81c\ud55c\ub2a5\ub825\uc790\uc5d0\uac8c \ubd88\ub9ac\ud558\uc9c0 \uc54a\uace0 \uc624\ud788\ub824 \uadf8\ub97c \ubcf4\ud638\ud558\ub294 \ud589\uc704\uc774\ubbc0\ub85c, \uc81c\ud55c\ub2a5\ub825\uc790\ub294 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758 \uc5c6\uc774\ub3c4 \ub2e8\ub3c5\uc73c\ub85c \ucde8\uc18c\uad8c\uc744 \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4. \uc774\ub294 \uc81c\ud55c\ub2a5\ub825\uc790\uac00 \uc6d0\uce59\uc801\uc73c\ub85c \ub2e8\ub3c5\uc73c\ub85c \ud560 \uc218 \uc5c6\ub294 "\ubc95\ub960\ud589\uc704"\uc640 \uad6c\ubcc4\ub418\ub294 \ucde8\uc18c\uad8c\uc758 \ud2b9\uc218\uc131\uc774\ub2e4.',B.aqO,B.aYI,null)
B.aqj=s(["\uc6d0\uce59\uc801\uc73c\ub85c \ub2f9\uc0ac\uc790 \uc0ac\uc774\ubfd0 \uc544\ub2c8\ub77c \uc18c\uae09\ud558\uc5ec \ucc98\uc74c\ubd80\ud130 \ud6a8\ub825\uc774 \uc5c6\uc5c8\ub358 \uac83\uc73c\ub85c \ucde8\uae09\ub41c\ub2e4","\ucde8\uc18c\ud55c \ub0a0 \uc774\ud6c4\ubd80\ud130\ub9cc \ud6a8\ub825\uc744 \uc783\ub294\ub2e4","\ucde8\uc18c\ub97c \uc8fc\uc7a5\ud55c \ub2f9\uc0ac\uc790\uc5d0\uac8c\ub9cc \ud6a8\ub825\uc774 \uc5c6\uace0 \uc0c1\ub300\ubc29\uc5d0\uac8c\ub294 \uc720\ud6a8\ud558\ub2e4","\ubc95\uc6d0\uc758 \ud655\uc778 \ud310\uacb0\uc774 \uc788\uc5b4\uc57c\ub9cc \uc18c\uae09\ud6a8\uac00 \ubc1c\uc0dd\ud55c\ub2e4"],t.s)
B.an5=s(["\ucc98\uc74c\ubd80\ud130 \ubb34\ud6a8\uc600\ub358 \uac83\uc73c\ub85c \uc18c\uae09\ud558\uc5ec \ud6a8\ub825\uc744 \uc783\ub294\ub2e4"],t.s)
B.brN=new A.a("gen_cl_revoc_15","civil_law","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704",null,"\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\uac00 \ucde8\uc18c\ub418\uba74 \uadf8 \ud6a8\uacfc\uac00 \ubbf8\uce58\ub294 \ubc94\uc704\ub294?",B.aqj,0,"\ucde8\uc18c\uad8c \ud589\uc0ac\ub85c \ubc95\ub960\ud589\uc704\uac00 \ucde8\uc18c\ub418\uba74 \uc81c141\uc870\uc5d0 \ub530\ub77c \ucc98\uc74c\ubd80\ud130 \ubb34\ud6a8\uc600\ub358 \uac83\uc73c\ub85c \uc18c\uae09\ud558\uc5ec \ud6a8\ub825\uc744 \uc783\ub294\ub2e4. \uc774\ub294 \ucde8\uc18c\uad8c\uc790\uc758 \ub2e8\ub3c5 \uc758\uc0ac\ud45c\uc2dc\ub85c \ubc1c\uc0dd\ud558\ub294 \ud6a8\uacfc\uc774\uba70, \ubc95\uc6d0\uc758 \ud655\uc778 \ud310\uacb0\uc744 \uc694\uac74\uc73c\ub85c \ud558\uc9c0 \uc54a\ub294\ub2e4.",B.an5,B.rp,null)
B.b5D=s(["\ucde8\uc18c\uad8c\uc774 \uc18c\uba78\ud558\uc5ec \ub354 \uc774\uc0c1 \ucde8\uc18c\ud560 \uc218 \uc5c6\ub2e4","\ub450 \uae30\uac04\uc774 \ubaa8\ub450 \ub9cc\ub8cc\ub418\uc5b4\uc57c\ub9cc \ucde8\uc18c\uad8c\uc774 \uc18c\uba78\ud55c\ub2e4","\uae30\uac04\uc774 \ub9cc\ub8cc\ub418\uc5b4\ub3c4 \ubc95\uc6d0\uc5d0 \uc2e0\uccad\ud558\uba74 \uc5f0\uc7a5\ud560 \uc218 \uc788\ub2e4","\uae30\uac04 \ub9cc\ub8cc\uc640 \ubb34\uad00\ud558\uac8c \ucde8\uc18c\uad8c\uc740 \uc601\uad6c\ud788 \uc874\uc18d\ud55c\ub2e4"],t.s)
B.b94=s(["\uc5b4\ub290 \ud558\ub098\ub77c\ub3c4 \uba3c\uc800 \ub3c4\ub2ec\ud558\uba74 \ucde8\uc18c\uad8c\uc740 \uc18c\uba78\ud55c\ub2e4"],t.s)
B.bae=s(["\ucde8\uc18c\uad8c \ud589\uc0ac\uae30\uac04\uc758 \uc774\uc911 \uc81c\ud55c"],t.s)
B.bvE=new A.a("gen_cl_revoc_16","civil_law","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704",null,"\ucde8\uc18c\uad8c \ud589\uc0ac\uae30\uac04(\uc81c146\uc870)\uc758 \ub450 \uae30\uac04 \uc911 \ud558\ub098\ub77c\ub3c4 \ub9cc\ub8cc\ub418\uba74 \uc5b4\ub5bb\uac8c \ub418\ub294\uac00?",B.b5D,0,"\ucd94\uc778\ud560 \uc218 \uc788\ub294 \ub0a0\ubd80\ud130 3\ub144, \ubc95\ub960\ud589\uc704\ub97c \ud55c \ub0a0\ubd80\ud130 10\ub144\uc758 \ub450 \uae30\uac04 \uc911 \uc5b4\ub290 \ud558\ub098\ub77c\ub3c4 \uba3c\uc800 \ub3c4\ub2ec\ud558\uba74 \ucde8\uc18c\uad8c\uc740 \uc18c\uba78\ud55c\ub2e4. \ub450 \uae30\uac04\uc740 \uac01\uac01 \ub3c5\ub9bd\uc801\uc778 \uc18c\uba78 \uc694\uac74\uc774\uba70 \ubaa8\ub450 \ub9cc\ub8cc\ub420 \uac83\uc744 \uc694\uad6c\ud558\uc9c0 \uc54a\ub294\ub2e4.",B.b94,B.bae,null)
B.b7Y=s(["\ubc95\uc815\ub300\ub9ac\uc778\xb7\uc131\ub144\ud6c4\uacac\uc778","\ucc29\uc624\ub85c \uc758\uc0ac\ud45c\uc2dc\ub97c \ud55c \ubcf8\uc778","\uc0ac\uae30\ub97c \ub2f9\ud55c \ubcf8\uc778","\uac15\ubc15\uc744 \ub2f9\ud55c \ubcf8\uc778"],t.s)
B.bhk=s(["\ucde8\uc18c\uc758 \uc6d0\uc778\uc774 \uc885\ub8cc\ub418\uae30 \uc804\uc5d0\ub3c4 \ucd94\uc778\ud560 \uc218 \uc788\ub2e4"],t.s)
B.ayV=s(["\ubc95\uc815\ub300\ub9ac\uc778\xb7\uc131\ub144\ud6c4\uacac\uc778\uc758 \ucd94\uc778(\uc81c144\uc870 \uc81c2\ud56d)"],t.s)
B.bAq=new A.a("gen_cl_revoc_17","civil_law","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704",null,"\ucde8\uc18c\uc6d0\uc778\uc774 \uc885\ub8cc\ub418\uae30 \uc804\uc5d0\ub3c4 \ucd94\uc778\ud560 \uc218 \uc788\ub294 \uc790\ub294?",B.b7Y,0,"\ubbfc\ubc95 \uc81c144\uc870 \uc81c2\ud56d\uc740 \ubc95\uc815\ub300\ub9ac\uc778 \ub610\ub294 \uc131\ub144\ud6c4\uacac\uc778\uc740 \ucde8\uc18c\uc758 \uc6d0\uc778\uc774 \uc885\ub8cc\ub418\uae30 \uc804\uc5d0\ub3c4 \ucd94\uc778\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc774\ub294 \uc2a4\uc2a4\ub85c \ucde8\uc18c\uc6d0\uc778 \uc0c1\ud0dc\uc5d0 \uc788\ub294 \ubcf8\uc778\uacfc \ub2ec\ub9ac, \ubc95\uc815\ub300\ub9ac\uc778\xb7\uc131\ub144\ud6c4\uacac\uc778\uc740 \ucc98\uc74c\ubd80\ud130 \ub3c5\ub9bd\uc801\uc778 \ud310\ub2e8\ub2a5\ub825\uc744 \uac00\uc9c0\uace0 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4.",B.bhk,B.ayV,null)
B.ai0=s(["\ubc95\ub960\uad00\uacc4\ub97c \uc870\uc18d\ud788 \ud655\uc815\uc2dc\ucf1c \uc0c1\ub300\ubc29\uc758 \ubd88\uc548\uc815\ud55c \uc9c0\uc704\ub97c \ud574\uc18c\ud558\uae30 \uc704\ud568\uc774\ub2e4","\ucde8\uc18c\uad8c\uc790\uc758 \ucde8\uc18c\uad8c\uc744 \ubc15\ud0c8\ud558\uae30 \uc704\ud568\uc774\ub2e4","\uc81c\ud55c\ub2a5\ub825\uc790\ub97c \ucc98\ubc8c\ud558\uae30 \uc704\ud568\uc774\ub2e4","\ubc95\uc815\ub300\ub9ac\uc778\uc758 \ucc45\uc784\uc744 \uac00\uc911\ud558\uae30 \uc704\ud568\uc774\ub2e4"],t.s)
B.b3q=s(["\ubc95\ub960\uad00\uacc4\ub97c \uc870\uc18d\ud788 \ud655\uc815\uc2dc\ucf1c \uc0c1\ub300\ubc29\uc758 \ubd88\uc548\uc815\ud55c \uc9c0\uc704\ub97c \ud574\uc18c"],t.s)
B.b78=s(["\uc0c1\ub300\ubc29\uc758 \ud655\ub2f5\ucd09\uad6c\uad8c \ucde8\uc9c0"],t.s)
B.bpg=new A.a("gen_cl_revoc_18","civil_law","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704",null,"\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\uc5d0\uc11c \uc0c1\ub300\ubc29\uc774 \ud655\ub2f5\uc744 \ucd09\uad6c\ud560 \uc218 \uc788\ub294 \uc81c\ub3c4\uc758 \ucde8\uc9c0\ub294?",B.ai0,0,"\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\ub294 \ucde8\uc18c\ub418\uae30 \uc804\uae4c\uc9c0 \uc720\ub3d9\uc801\uc778 \uc0c1\ud0dc\uc5d0 \uc788\uc5b4 \uc0c1\ub300\ubc29\uc758 \uc9c0\uc704\uac00 \ubd88\uc548\uc815\ud558\ub2e4. \uc774\uc5d0 \uc0c1\ub300\ubc29\uc740 \ucde8\uc18c\uad8c\uc790\uc5d0\uac8c \uc77c\uc815 \uae30\uac04 \ub0b4 \ucde8\uc18c\ud560 \uac83\uc778\uc9c0 \ucd94\uc778\ud560 \uac83\uc778\uc9c0 \ud655\ub2f5\uc744 \uc694\uad6c(\ucd09\uad6c)\ud560 \uc218 \uc788\ub294 \uad8c\ub9ac\ub97c \uc778\uc815\ud558\uc5ec, \ubc95\ub960\uad00\uacc4\ub97c \uc870\uc18d\ud788 \ud655\uc815\uc2dc\ud0ac \uc218 \uc788\ub3c4\ub85d \ud55c\ub2e4.",B.b3q,B.b78,null)
B.b0X=s(["\ucd94\uc778\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4","\ucde8\uc18c\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4","\ubb34\ud6a8\ub85c \ud655\uc815\ub41c\ub2e4","\ubc95\ub960\ud589\uc704\uac00 \ucc98\uc74c\ubd80\ud130 \uc5c6\uc5c8\ub358 \uac83\uc73c\ub85c \ub41c\ub2e4"],t.s)
B.aIX=s(["\uadf8 \uae30\uac04 \ub0b4\uc5d0 \ud655\ub2f5\uc744 \ubc1c\ud558\uc9c0 \uc54a\uc73c\uba74 \uadf8 \ud589\uc704\ub97c \ucd94\uc778\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4"],t.s)
B.b2k=s(["\ud655\ub2f5\ucd09\uad6c\uc5d0 \ub300\ud55c \ubb34\uc751\ub2f5\uc758 \ud6a8\uacfc(\uc81c15\uc870)"],t.s)
B.bJI=new A.a("gen_cl_revoc_19","civil_law","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704",null,"\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\uc5d0\uc11c \uc0c1\ub300\ubc29\uc774 \ud655\ub2f5\ucd09\uad6c\ub97c \ud558\uc600\ub294\ub370\ub3c4 \ucde8\uc18c\uad8c\uc790\uac00 \uadf8 \uae30\uac04 \ub0b4\uc5d0 \ud655\ub2f5\uc744 \ubc1c\ud558\uc9c0 \uc54a\uc740 \uacbd\uc6b0 \uc6d0\uce59\uc801\uc778 \ud6a8\uacfc\ub294?",B.b0X,0,"\ubbfc\ubc95 \uc81c15\uc870\ub294 \uc81c\ud55c\ub2a5\ub825\uc790\uc758 \uc0c1\ub300\ubc29\uc774 \ud655\ub2f5\uc744 \ucd09\uad6c\ud558\uc600\uc74c\uc5d0\ub3c4 \uadf8 \uae30\uac04 \ub0b4\uc5d0 \ucde8\uc18c\uad8c\uc790(\ub610\ub294 \ubc95\uc815\ub300\ub9ac\uc778)\uac00 \ud655\ub2f5\uc744 \ubc1c\ud558\uc9c0 \uc54a\uc73c\uba74 \uadf8 \ud589\uc704\ub97c \ucd94\uc778\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc774\ub294 \ubc95\ub960\uad00\uacc4\ub97c \uc870\uc18d\ud788 \ud655\uc815\uc2dc\ucf1c \uc0c1\ub300\ubc29\uc744 \ubcf4\ud638\ud558\uae30 \uc704\ud55c \uaddc\uc815\uc774\ub2e4.",B.aIX,B.b2k,null)
B.aqS=s(["\ucde8\uc18c\uad8c\uc790\uac00 \uc5ec\ub7ff\uc778 \uacbd\uc6b0 \uadf8\uc911 1\uc778\ub9cc \ucde8\uc18c\ud574\ub3c4 \ubc95\ub960\ud589\uc704 \uc804\uccb4\uac00 \ucde8\uc18c\ub41c\ub2e4","\ucde8\uc18c\ub294 \uc870\uac74\uc744 \ubd99\uc5ec\uc11c \ud560 \uc218 \uc5c6\ub2e4","\ucde8\uc18c\uad8c\uc790\uac00 \ucd94\uc778\ud558\uba74 \ub2e4\uc2dc\ub294 \ucde8\uc18c\ud560 \uc218 \uc5c6\ub2e4","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\uc778\uc9c0 \uc5ec\ubd80\ub294 \ubc95\uc6d0\uc758 \ud310\ub2e8 \uc5c6\uc774\ub3c4 \ucde8\uc18c\uad8c\uc790\uac00 \uc2a4\uc2a4\ub85c \uc54c \uc218 \uc788\uc5b4\uc57c \ud55c\ub2e4"],t.s)
B.aop=s(['\ucde8\uc18c\uad8c\uc790\uac00 "\uc2a4\uc2a4\ub85c \uc54c \uc218 \uc788\uc5b4\uc57c \ud55c\ub2e4"\ub294 \uac83\uc740 \ucde8\uc18c \uc81c\ub3c4\uc758 \uc694\uac74\uc774 \uc544\ub2c8\ub77c'],t.s)
B.avR=s(["\ucde8\uc18c \uc81c\ub3c4 \uc885\ud569"],t.s)
B.bJX=new A.a("gen_cl_revoc_20","civil_law","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704",null,"\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\uc5d0 \uad00\ud55c \ub2e4\uc74c \uc124\uba85 \uc911 \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aqS,3,'\ucde8\uc18c\uad8c\uc790 1\uc778\uc758 \ucde8\uc18c\ub85c \ubc95\ub960\ud589\uc704 \uc804\uccb4\uc758 \ud6a8\ub825\uc774 \uc18c\uae09\ud558\uc5ec \uc18c\uba78\ud558\uace0, \ucde8\uc18c\ub294 \ud615\uc131\uad8c \ud589\uc0ac\uc774\ubbc0\ub85c \uc6d0\uce59\uc801\uc73c\ub85c \uc870\uac74\uc744 \ubd99\uc77c \uc218 \uc5c6\uc73c\uba70, \ucd94\uc778 \ud6c4\uc5d0\ub294 \ub2e4\uc2dc \ucde8\uc18c\ud560 \uc218 \uc5c6\ub2e4\ub294 \uc810\uc740 \ubaa8\ub450 \uc633\ub2e4. \ub2e4\ub9cc \uc5b4\ub5a4 \ubc95\ub960\ud589\uc704\uac00 \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \uc0ac\uc720(\uc81c\ud55c\ub2a5\ub825, \ucc29\uc624, \uc0ac\uae30\xb7\uac15\ubc15 \ub4f1)\uc5d0 \ud574\ub2f9\ud558\ub294\uc9c0\ub294 \ubc95\ub960\uc5d0 \ub530\ub77c \uc815\ud574\uc9c0\ub294 \uac83\uc73c\ub85c, \ucde8\uc18c\uad8c\uc790\uac00 "\uc2a4\uc2a4\ub85c \uc54c \uc218 \uc788\uc5b4\uc57c \ud55c\ub2e4"\ub294 \uac83\uc740 \ucde8\uc18c \uc81c\ub3c4\uc758 \uc694\uac74\uc774 \uc544\ub2c8\ub77c \ubd80\uc801\uc808\ud55c \uc124\uba85\uc774\ub2e4.',B.aop,B.avR,null)
B.Vb=s(["\ucde8\uc18c\uad8c\uc790\ub85c\ubd80\ud130 \uadf8 \ubc95\ub960\uc0c1 \uc9c0\uc704\ub97c \ud3ec\uad04\uc801\uc73c\ub85c \uc2b9\uacc4\ud55c \uc0c1\uc18d\uc778","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\uc640 \ubb34\uad00\ud55c \uc81c3\uc790","\ubc95\ub960\ud589\uc704 \uc0c1\ub300\ubc29\uc758 \ucc44\uad8c\uc790","\ub2e8\uc21c\ud788 \ubc95\ub960\ud589\uc704 \ud604\uc7a5\uc744 \ubaa9\uaca9\ud55c \uc790"],t.s)
B.aP_=s(["\ucde8\uc18c\uad8c\uc790\ub85c\ubd80\ud130 \uadf8 \ubc95\ub960\uc0c1 \uc9c0\uc704\ub97c \ud3ec\uad04\uc801\uc73c\ub85c \uc2b9\uacc4\ud55c"],t.s)
B.ZV=s(["\ucde8\uc18c\uad8c\uc790\uc758 \uc2b9\uacc4\uc778"],t.s)
B.bQP=new A.a("gen_cl_revoc_21","civil_law","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704",null,"\ucde8\uc18c\uad8c\uc790\uc758 \uc2b9\uacc4\uc778\uc774 \ucde8\uc18c\uad8c\uc744 \ud589\uc0ac\ud560 \uc218 \uc788\ub294 \uacbd\uc6b0\ub85c \uc633\uc740 \uac83\uc740?",B.Vb,0,'\ubbfc\ubc95 \uc81c140\uc870\uc758 "\uc2b9\uacc4\uc778"\uc740 \ucde8\uc18c\uad8c\uc790\uc758 \uc9c0\uc704\ub97c \ud3ec\uad04\uc801\uc73c\ub85c \ub610\ub294 \ud2b9\uc815\uc801\uc73c\ub85c \uc2b9\uacc4\ud55c \uc790(\uc608: \uc0c1\uc18d\uc778)\ub97c \uc758\ubbf8\ud55c\ub2e4. \ucde8\uc18c\uad8c\uc740 \ucde8\uc18c\uad8c\uc790\uc758 \uc9c0\uc704\uc5d0 \ubd80\uc218\ud558\ub294 \uad8c\ub9ac\uc774\ubbc0\ub85c, \uadf8 \uc9c0\uc704\ub97c \uc2b9\uacc4\ud55c \uc790\ub3c4 \ud568\uaed8 \ucde8\uc18c\uad8c\uc744 \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4.',B.aP_,B.ZV,null)
B.bef=s(["\ucde8\uc18c\ub294 \ud615\uc131\uad8c \ud589\uc0ac\ub85c\uc11c \uc77c\ub2e8 \ud6a8\ub825\uc774 \ubc1c\uc0dd\ud558\uba74 \ucca0\ud68c\ud560 \uc218 \uc5c6\ub2e4","\uc0c1\ub300\ubc29\uc758 \ub3d9\uc758\uac00 \uc788\uc73c\uba74 \uc5b8\uc81c\ub4e0\uc9c0 \ucca0\ud68c\ud560 \uc218 \uc788\ub2e4","\ucde8\uc18c\ud55c \ub0a0\ubd80\ud130 1\ub144 \ub0b4\uc5d0\ub294 \uc790\uc720\ub86d\uac8c \ucca0\ud68c\ud560 \uc218 \uc788\ub2e4","\ubc95\uc6d0\uc758 \ud5c8\uac00\ub97c \ubc1b\uc73c\uba74 \ucca0\ud68c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.b5E=s(["\uc77c\ub2e8 \ud6a8\ub825\uc774 \ubc1c\uc0dd\ud558\uba74 \ucca0\ud68c\ud560 \uc218 \uc5c6\ub2e4"],t.s)
B.aRF=s(["\ucde8\uc18c\uc758 \ubd88\uac00\ucca0\ud68c\uc131"],t.s)
B.btN=new A.a("gen_cl_revoc_22","civil_law","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704",null,"\ucde8\uc18c\uad8c\uc744 \ud589\uc0ac\ud55c \ud6c4, \ucde8\uc18c\uad8c\uc790\uac00 \ub2e4\uc2dc \uadf8 \ucde8\uc18c\ub97c \ucca0\ud68c\ud560 \uc218 \uc788\ub294\uac00?",B.bef,0,"\ucde8\uc18c\ub294 \ud615\uc131\uad8c\uc758 \ud589\uc0ac\ub85c\uc11c \uc0c1\ub300\ubc29\uc5d0 \ub300\ud55c \uc758\uc0ac\ud45c\uc2dc\uac00 \ub3c4\ub2ec\ud558\uba74 \uc989\uc2dc \ud6a8\ub825\uc774 \ubc1c\uc0dd\ud558\uba70, \uadf8 \ud6c4\uc5d0\ub294 \ucde8\uc18c\uad8c\uc790\uac00 \uc784\uc758\ub85c \uc774\ub97c \ucca0\ud68c\ud560 \uc218 \uc5c6\ub2e4. \ub2e4\ub9cc \ub2f9\uc0ac\uc790\ub4e4\uc774 \uc0c8\ub85c\uc6b4 \uacc4\uc57d(\uc7ac\uacc4\uc57d)\uc744 \ud1b5\ud574 \uc0ac\uc2e4\uc0c1 \uc6d0\ub798\ub300\ub85c \ub418\ub3cc\ub9ac\ub294 \uac83\uc740 \ubcc4\uac1c\uc758 \ubb38\uc81c\uc774\ub2e4.",B.b5E,B.aRF,null)
B.Zd=s(["\ubbfc\ubc95 \uc81c110\uc870\uc758 \uc0ac\uae30\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\ub85c\uc11c \uacc4\uc57d\uc744 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4","\uacc4\uc57d\uc740 \ucc98\uc74c\ubd80\ud130 \ub2f9\uc5f0\ud788 \ubb34\ud6a8\uc774\ubbc0\ub85c \ubcc4\ub3c4\uc758 \uc870\uce58\uac00 \ud544\uc694 \uc5c6\ub2e4","\uac00\ub9f9\ubcf8\ubd80\ub9cc\uc774 \uacc4\uc57d\uc758 \ud6a8\ub825\uc744 \ub2e4\ud234 \uc218 \uc788\ub2e4","\ucde8\uc18c\uad8c \ud589\uc0ac\uae30\uac04\uc758 \uc81c\ud55c \uc5c6\uc774 \uc5b8\uc81c\ub4e0\uc9c0 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.aw0=s(["\ubbfc\ubc95 \uc81c110\uc870\uc758 \uc0ac\uae30\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\ub85c\uc11c \uacc4\uc57d\uc744 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.a9a=s(["\uc0ac\uae30\uc5d0 \uc758\ud55c \ucde8\uc18c\uc758 \uc2e4\ubb34 \uc801\uc6a9"],t.s)
B.bpn=new A.a("gen_cl_revoc_23","civil_law","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704",null,"\uac00\ub9f9\uacc4\uc57d \uccb4\uacb0 \uacfc\uc815\uc5d0\uc11c \uac00\ub9f9\ubcf8\ubd80\uc758 \uae30\ub9dd\uc73c\ub85c \uac00\ub9f9\uc810\uc8fc\uac00 \uacc4\uc57d\uc744 \uccb4\uacb0\ud55c \uacbd\uc6b0, \uac00\ub9f9\uc810\uc8fc\uac00 \ucde8\ud560 \uc218 \uc788\ub294 \uc870\uce58\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.Zd,0,"\uac00\ub9f9\ubcf8\ubd80\uc758 \uae30\ub9dd\ud589\uc704\ub85c \uac00\ub9f9\uc810\uc8fc\uac00 \ucc29\uc624\uc5d0 \ube60\uc838 \uacc4\uc57d\uc744 \uccb4\uacb0\ud558\uc600\ub2e4\uba74, \uc774\ub294 \ubbfc\ubc95 \uc81c110\uc870\uc758 \uc0ac\uae30\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\uc5d0 \ud574\ub2f9\ud558\uc5ec \uac00\ub9f9\uc810\uc8fc(\ud53c\uae30\ub9dd\uc790)\uac00 \ucde8\uc18c\uad8c\uc744 \ud589\uc0ac\ud558\uc5ec \uacc4\uc57d\uc744 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \ucde8\uc18c\uad8c \ud589\uc0ac\uae30\uac04(\uc81c146\uc870)\uc758 \uc81c\ud55c\uc740 \uadf8\ub300\ub85c \uc801\uc6a9\ub41c\ub2e4.",B.aw0,B.a9a,null)
B.aZp=s(["\ubb34\uad8c\ub300\ub9ac\ud589\uc704\ub294 \ubcf8\uc778\uc758 \ucd94\uc778\uc774 \uc5c6\uc73c\uba74 \uc6d0\uce59\uc801\uc73c\ub85c \ubcf8\uc778\uc5d0\uac8c \ud6a8\ub825\uc774 \uc5c6\ub294 \uc720\ub3d9\uc801 \uc0c1\ud0dc\uc774\ub098, \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\ub294 \ucde8\uc18c \uc804\uae4c\uc9c0\ub294 \uc644\uc804\ud788 \uc720\ud6a8\ud558\ub2e4","\ub450 \uc81c\ub3c4 \ubaa8\ub450 \ucc98\uc74c\ubd80\ud130 \ub2f9\uc5f0\ud788 \ubb34\ud6a8\uc774\ub2e4","\ubb34\uad8c\ub300\ub9ac\ud589\uc704\ub294 \ucde8\uc18c\uad8c\uc790\uac00 \uc874\uc7ac\ud558\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc810\uc5d0\uc11c \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\uc640 \ub3d9\uc77c\ud558\ub2e4","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\ub3c4 \ubcf8\uc778\uc758 \ucd94\uc778\uc774 \uc788\uc5b4\uc57c\ub9cc \uc720\ud6a8\ud574\uc9c4\ub2e4"],t.s)
B.b0n=s(["\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\ub294 \ucde8\uc18c \uc804\uae4c\uc9c0\ub294 \uc644\uc804\ud788 \uc720\ud6a8\ud558\ub2e4"],t.s)
B.ao_=s(["\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ud589\uc704\uc640 \ubb34\uad8c\ub300\ub9ac\uc758 \ube44\uad50"],t.s)
B.bv4=new A.a("gen_cl_revoc_24","civil_law","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704",null,"\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\uc640 \ubb34\uad8c\ub300\ub9ac\ud589\uc704\ub97c \ube44\uad50\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aZp,0,"\ubb34\uad8c\ub300\ub9ac\ud589\uc704\ub294 \ubcf8\uc778\uc5d0 \ub300\ud558\uc5ec \ud6a8\ub825\uc774 \ubc1c\uc0dd\ud560\uc9c0 \uc5ec\ubd80\uac00 \ud655\uc815\ub418\uc9c0 \uc54a\uc740 \uc720\ub3d9\uc801 \ubb34\ud6a8 \uc0c1\ud0dc\uc5d0 \uc788\ub2e4\uac00, \ubcf8\uc778\uc758 \ucd94\uc778\uc73c\ub85c \uc18c\uae09\ud558\uc5ec \uc720\ud6a8\uac00 \ub418\uac70\ub098 \ucd94\uc778 \uac70\uc808\ub85c \ud655\uc815\uc801 \ubb34\ud6a8\uac00 \ub41c\ub2e4. \ubc18\uba74 \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\ub294 \uc560\ucd08\uc5d0 \uc644\uc804\ud788 \uc720\ud6a8\ud55c \uac83\uc73c\ub85c \ucde8\uae09\ub418\ub2e4\uac00, \ucde8\uc18c\uad8c\uc790\uc758 \ucde8\uc18c\uac00 \uc788\uc5b4\uc57c \ube44\ub85c\uc18c \ubb34\ud6a8\uac00 \ub41c\ub2e4\ub294 \uc810\uc5d0\uc11c \uc720\ub3d9\uc801 \uc9c0\uc704\uc758 \ucd9c\ubc1c\uc810\uc774 \ub2e4\ub974\ub2e4.",B.b0n,B.ao_,null)
B.b4T=s(["\ucde8\uc18c\uc758 \uc6d0\uc778\uc774 \uc18c\uba78\ub418\uc5b4 \ucd94\uc778\uc774 \uac00\ub2a5\ud558\uac8c \ub41c \ub0a0","\ubc95\ub960\ud589\uc704\ub97c \uccb4\uacb0\ud55c \ub0a0","\ubc95\uc815\ub300\ub9ac\uc778\uc774 \uc9c0\uc815\ub41c \ub0a0","\ucde8\uc18c\uad8c\uc790\uac00 \uc0ac\ub9dd\ud55c \ub0a0"],t.s)
B.akp=s(["\ucde8\uc18c\uc758 \uc6d0\uc778\uc774 \uc18c\uba78\ub418\uc5b4 \ucd94\uc778\uc774 \uac00\ub2a5\ud558\uac8c \ub41c \ub0a0"],t.s)
B.b1h=s(['"\ucd94\uc778\ud560 \uc218 \uc788\ub294 \ub0a0"\uc758 \uc758\ubbf8'],t.s)
B.bvu=new A.a("gen_cl_revoc_25","civil_law","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704",null,'\ucde8\uc18c\uad8c \ud589\uc0ac\uae30\uac04(\uc81c146\uc870)\uc758 \uae30\uc0b0\uc810\uc778 "\ucd94\uc778\ud560 \uc218 \uc788\ub294 \ub0a0"\uc758 \uc758\ubbf8\ub85c \uc633\uc740 \uac83\uc740?',B.b4T,0,'"\ucd94\uc778\ud560 \uc218 \uc788\ub294 \ub0a0"\uc774\ub780 \ucde8\uc18c\uc758 \uc6d0\uc778(\uc81c\ud55c\ub2a5\ub825, \ucc29\uc624, \uc0ac\uae30\xb7\uac15\ubc15 \ub4f1)\uc774 \uc885\ub8cc\ub418\uc5b4 \ucde8\uc18c\uad8c\uc790\uac00 \uc720\ud6a8\ud558\uac8c \ucd94\uc778\ud560 \uc218 \uc788\uac8c \ub41c \ub0a0\uc744 \uc758\ubbf8\ud55c\ub2e4. \uc608\ucee8\ub300 \uc81c\ud55c\ub2a5\ub825\uc790\uac00 \uc131\ub144\uc774 \ub41c \ub0a0, \uc0ac\uae30\xb7\uac15\ubc15 \uc0c1\ud0dc\uc5d0\uc11c \ubc97\uc5b4\ub09c \ub0a0 \ub4f1\uc774 \uc774\uc5d0 \ud574\ub2f9\ud55c\ub2e4.',B.akp,B.b1h,null)
B.aM1=s(["\ucde8\uc18c\uac00 \uc788\uae30 \uc804\uc5d0\ub294 \uadf8 \ubc95\ub960\ud589\uc704\uac00 \uc720\ud6a8\ud558\ubbc0\ub85c \uc81c3\uc790\ub85c\uc758 \ucc98\ubd84\ub3c4 \uc6d0\uce59\uc801\uc73c\ub85c \uc720\ud6a8\ud558\ub2e4","\uc5b8\uc81c\ub098 \uc81c3\uc790\uc758 \ucde8\ub4dd\uc740 \ubb34\ud6a8\uc774\ub2e4","\uc81c3\uc790\ub294 \ud56d\uc0c1 \uc18c\uc720\uad8c\uc744 \ucde8\ub4dd\ud558\uc9c0 \ubabb\ud55c\ub2e4","\ucde8\uc18c\uad8c\uc790\uc758 \uc0ac\uc804 \ub3d9\uc758\uac00 \uc5c6\uc73c\uba74 \ucc98\ubd84 \uc790\uccb4\uac00 \ubd88\uac00\ub2a5\ud558\ub2e4"],t.s)
B.ag3=s(["\ucde8\uc18c\ub418\uae30 \uc804\uae4c\uc9c0 \uc644\uc804\ud788 \uc720\ud6a8\ud558\ubbc0\ub85c, \uadf8 \uc720\ud6a8\ud55c \ubc95\ub960\ud589\uc704\ub97c \uae30\ucd08\ub85c \ud55c \uc81c3\uc790\ub85c\uc758 \ucc98\ubd84\ub3c4 \uc6d0\uce59\uc801\uc73c\ub85c \uc720\ud6a8"],t.s)
B.bbR=s(["\ucde8\uc18c \uc804 \ucc98\ubd84\ud589\uc704\uc758 \ud6a8\ub825"],t.s)
B.bJy=new A.a("gen_cl_revoc_26","civil_law","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704",null,"\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\uac00 \ucde8\uc18c\ub418\uc9c0 \uc54a\uc740 \uc0c1\ud0dc\uc5d0\uc11c \uadf8 \ubc95\ub960\ud589\uc704\uc758 \ubaa9\uc801\ubb3c\uc774 \uc81c3\uc790\uc5d0\uac8c \ucc98\ubd84\ub41c \uacbd\uc6b0 \uc6d0\uce59\uc801\uc778 \uacb0\uacfc\ub294?",B.aM1,0,"\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\ub294 \ucde8\uc18c\ub418\uae30 \uc804\uae4c\uc9c0 \uc644\uc804\ud788 \uc720\ud6a8\ud558\ubbc0\ub85c, \uadf8 \uc720\ud6a8\ud55c \ubc95\ub960\ud589\uc704\ub97c \uae30\ucd08\ub85c \ud55c \uc81c3\uc790\ub85c\uc758 \ucc98\ubd84\ub3c4 \uc6d0\uce59\uc801\uc73c\ub85c \uc720\ud6a8\ud558\ub2e4. \uc774\ud6c4 \ucde8\uc18c\uac00 \uc774\ub8e8\uc5b4\uc9c0\uba74 \uc18c\uae09\ud558\uc5ec \ubb34\ud6a8\uac00 \ub418\uc9c0\ub9cc, \uac70\ub798 \uc548\uc804\uc744 \uc704\ud574 \ubcc4\ub3c4\ub85c \uc120\uc758\uc758 \uc81c3\uc790 \ubcf4\ud638\uac00 \ubb38\uc81c\ub418\ub294 \uacbd\uc6b0(\uc608: \uc0ac\uae30\xb7\uac15\ubc15\xb7\ucc29\uc624\uc758 \uacbd\uc6b0 \uc81c3\uc790 \ub300\ud56d\ubd88\uac00 \uaddc\uc815)\uac00 \uc788\ub2e4.",B.ag3,B.bbR,null)
B.a2J=s(["\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ud589\uc704\ub85c \ucde8\ub4dd\ud55c \uad8c\ub9ac\uc758 \uc804\ubd80\ub098 \uc77c\ubd80\uc758 \uc591\ub3c4","\uc774\uc758\ub97c \ubcf4\ub958\ud55c \uc774\ud589","\uac15\uc81c\uc9d1\ud589\uc758 \uc815\uc9c0","\ucde8\uc18c\uad8c\uc758 \ud3ec\uae30 \uc120\uc5b8"],t.s)
B.Qz=s(["\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ud589\uc704\ub85c \ucde8\ub4dd\ud55c \uad8c\ub9ac\uc758 \uc804\ubd80\ub098 \uc77c\ubd80\ub97c \uc591\ub3c4\ud558\ub294 \uac83\uc744 \ubc95\uc815\ucd94\uc778 \uc0ac\uc720\ub85c \uba85\uc2dc\ud55c\ub2e4"],t.s)
B.aBw=s(["\ubc95\uc815\ucd94\uc778 \uc0ac\uc720 \u2014 \uad8c\ub9ac\uc758 \uc591\ub3c4"],t.s)
B.bpm=new A.a("gen_cl_revoc_27","civil_law","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704",null,"\ucde8\uc18c\uad8c\uc790\uac00 \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\ub85c \ucde8\ub4dd\ud55c \uad8c\ub9ac\ub97c \uc81c3\uc790\uc5d0\uac8c \uc591\ub3c4\ud55c \uacbd\uc6b0, \uc774\ub294 \uc5b4\ub5a4 \ubc95\uc815\ucd94\uc778 \uc0ac\uc720\uc5d0 \ud574\ub2f9\ud558\ub294\uac00?",B.a2J,0,"\ubbfc\ubc95 \uc81c145\uc870 \uc81c5\ud638\ub294 \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ud589\uc704\ub85c \ucde8\ub4dd\ud55c \uad8c\ub9ac\uc758 \uc804\ubd80\ub098 \uc77c\ubd80\ub97c \uc591\ub3c4\ud558\ub294 \uac83\uc744 \ubc95\uc815\ucd94\uc778 \uc0ac\uc720\ub85c \uba85\uc2dc\ud55c\ub2e4. \ucde8\uc18c\uad8c\uc790\uac00 \uc774\uc758\ub97c \ubcf4\ub958\ud558\uc9c0 \uc54a\uace0 \uc774\ub7ec\ud55c \ucc98\ubd84\ud589\uc704\ub97c \ud558\uc600\ub2e4\uba74, \uadf8 \ubc95\ub960\ud589\uc704\ub97c \uc720\ud6a8\ud55c \uac83\uc73c\ub85c \uc804\uc81c\ud558\uace0 \ud589\ub3d9\ud55c \uac83\uc774\ubbc0\ub85c \ucd94\uc778\ud55c \uac83\uc73c\ub85c \uac04\uc8fc\ub41c\ub2e4.",B.Qz,B.aBw,null)
B.aS8=s(["\ucde8\uc18c\uc6d0\uc778\uc774 \uc5ec\ub7ec \uac1c \uacbd\ud569\ud560 \uc218 \uc788\ub2e4(\uc608: \uc81c\ud55c\ub2a5\ub825\uacfc \uc0ac\uae30\uac00 \ub3d9\uc2dc\uc5d0 \ubb38\uc81c\ub418\ub294 \uacbd\uc6b0)","\ucde8\uc18c\uc6d0\uc778\uc740 \ubc18\ub4dc\uc2dc \ud55c \uac00\uc9c0\ub9cc \uc874\uc7ac\ud560 \uc218 \uc788\ub2e4","\ucde8\uc18c\uc6d0\uc778\uc774 \uacbd\ud569\ud558\uba74 \ubc95\ub960\ud589\uc704\ub294 \uc790\ub3d9\uc73c\ub85c \ubb34\ud6a8\uac00 \ub41c\ub2e4","\ucde8\uc18c\uc6d0\uc778\uc758 \uacbd\ud569\uc740 \ubbfc\ubc95\uc0c1 \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.aIq=s(["\ucde8\uc18c\uc6d0\uc778\uc774 \uc5ec\ub7ec \uac1c \uacbd\ud569\ud560 \uc218 \uc788\ub2e4"],t.s)
B.aRK=s(["\ucde8\uc18c\uc6d0\uc778\uc758 \uacbd\ud569"],t.s)
B.bEb=new A.a("gen_cl_revoc_28","civil_law","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704",null,"\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\uc5d0 \uad00\ud55c \ub2e4\uc74c \uc124\uba85 \uc911 \uc633\uc740 \uac83\uc740?",B.aS8,0,"\ud558\ub098\uc758 \ubc95\ub960\ud589\uc704\uc5d0 \uc81c\ud55c\ub2a5\ub825, \ucc29\uc624, \uc0ac\uae30\xb7\uac15\ubc15 \ub4f1 \uc5ec\ub7ec \ucde8\uc18c\uc6d0\uc778\uc774 \ub3d9\uc2dc\uc5d0 \uc874\uc7ac\ud560 \uc218 \uc788\uc73c\uba70, \uc774 \uacbd\uc6b0 \ucde8\uc18c\uad8c\uc790\ub294 \uc5b4\ub290 \ucde8\uc18c\uc6d0\uc778\uc744 \uadfc\uac70\ub85c \ud558\ub4e0 \ucde8\uc18c\uad8c\uc744 \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4. \uac01 \ucde8\uc18c\uc6d0\uc778\ub9c8\ub2e4 \ucde8\uc18c\uad8c\uc790\xb7\ud589\uc0ac\uae30\uac04 \ub4f1\uc774 \ub2e4\ub974\uac8c \uc801\uc6a9\ub420 \uc218 \uc788\uc5b4 \uc2e4\ubb34\uc0c1 \uc720\ub9ac\ud55c \uadfc\uac70\ub97c \uc120\ud0dd\ud560 \uc218 \uc788\ub2e4.",B.aIq,B.aRK,null)
B.a7p=s(["\ucde8\uc18c\uad8c\uc790\uac00 \ucd94\uc778\ud558\uba74 \uadf8 \ubc95\ub960\ud589\uc704\ub294 \ucc98\uc74c\ubd80\ud130 \uc720\ud6a8\ud588\ub358 \uac83\uc73c\ub85c \ud655\uc815\ub41c\ub2e4","\ucde8\uc18c\uad8c\uc758 \ud589\uc0ac\uae30\uac04\uc774 \uc9c0\ub098\uba74 \uadf8 \ubc95\ub960\ud589\uc704\ub294 \ud655\uc815\uc801\uc73c\ub85c \uc720\ud6a8\uac00 \ub41c\ub2e4","\ucde8\uc18c\uad8c\uc740 \ucc44\uad8c\uc790\ub300\uc704\uad8c\uc758 \ub300\uc0c1\uc774 \ub420 \uc218 \uc5c6\ub2e4","\ucde8\uc18c\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \ubc29\uc2dd\uc5d0 \ud2b9\ubcc4\ud55c \uc81c\ud55c\uc774 \uc5c6\ub2e4"],t.s)
B.a9g=s(["\ucde8\uc18c\uad8c\uc740 \uc7ac\uc0b0\uad8c\uc801 \uc131\uc9c8\uc744 \uac00\uc9c0\ub294 \uacbd\uc6b0 \ucc44\uad8c\uc790\ub300\uc704\uad8c\uc758 \ub300\uc0c1\uc774 \ub420 \uc218 \uc788\ub2e4"],t.s)
B.b1A=s(["\ucde8\uc18c\uad8c\uacfc \ucc44\uad8c\uc790\ub300\uc704\uad8c"],t.s)
B.bt6=new A.a("gen_cl_revoc_29","civil_law","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704",null,"\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704 \uc804\ubc18\uc5d0 \uad00\ud55c \ub2e4\uc74c \uc124\uba85 \uc911 \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.a7p,2,'\ucd94\uc778\xb7\ud589\uc0ac\uae30\uac04 \ub9cc\ub8cc\ub85c \ubc95\ub960\ud589\uc704\uac00 \ud655\uc815\uc801\uc73c\ub85c \uc720\ud6a8\ud574\uc9c4\ub2e4\ub294 \uc810, \ucde8\uc18c\uc5d0 \ud2b9\ubcc4\ud55c \ubc29\uc2dd \uc81c\ud55c\uc774 \uc5c6\ub2e4\ub294 \uc810\uc740 \ubaa8\ub450 \uc633\ub2e4. \ubc18\uba74 \ucde8\uc18c\uad8c\uc740 \uc7ac\uc0b0\uad8c\uc801 \uc131\uc9c8\uc744 \uac00\uc9c0\ub294 \uacbd\uc6b0 \ucc44\uad8c\uc790\ub300\uc704\uad8c\uc758 \ub300\uc0c1\uc774 \ub420 \uc218 \uc788\ub2e4\ub294 \uac83\uc774 \ud1b5\uc124\uc801 \uc774\ud574\uc774\ubbc0\ub85c, "\ub300\uc0c1\uc774 \ub420 \uc218 \uc5c6\ub2e4"\ub294 \uc124\uba85\uc740 \uc633\uc9c0 \uc54a\ub2e4.',B.a9g,B.b1A,null)
B.b1j=s(["\ucde8\uc18c\uad8c\uc790 1\uc778\uc774 \ucde8\uc18c\ud558\uba74 \ubc95\ub960\ud589\uc704 \uc804\uccb4\uac00 \uc18c\uae09\ud558\uc5ec \ubb34\ud6a8\uac00 \ub41c\ub2e4","\ubc95\uc815\ucd94\uc778\uc740 \ucde8\uc18c\uad8c\uc790\uc758 \uba85\uc2dc\uc801 \uc758\uc0ac\ud45c\uc2dc \uc5c6\uc774\ub3c4 \uc77c\uc815\ud55c \ud589\uc704\ub9cc\uc73c\ub85c \uc131\ub9bd\ud560 \uc218 \uc788\ub2e4","\ucde8\uc18c\uad8c\uc758 \ud589\uc0ac\uae30\uac04\uc740 \ub2f9\uc0ac\uc790\uc758 \ud569\uc758\ub85c \uc784\uc758\ub85c \uc5f0\uc7a5\ud560 \uc218 \uc788\ub2e4","\uc81c\ud55c\ub2a5\ub825\uc744 \uc774\uc720\ub85c \ud55c \ucde8\uc18c\ub294 \uc0c1\ub300\ubc29\uc758 \uc120\uc758\xb7\uc545\uc758\ub97c \ubd88\ubb38\ud558\uace0 \ud560 \uc218 \uc788\ub2e4"],t.s)
B.a0c=s(["\ub2f9\uc0ac\uc790\uc758 \ud569\uc758\ub85c \uc784\uc758\ub85c \uc5f0\uc7a5\ud560 \uc218 \uc5c6\ub294 \uac15\ud589\uaddc\uc815"],t.s)
B.a72=s(["\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704 \uc885\ud569"],t.s)
B.bxO=new A.a("gen_cl_revoc_30","civil_law","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704",null,"\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704 \uc885\ud569 \uc815\ub9ac \uc911 \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.b1j,2,"\ucde8\uc18c\uad8c\uc758 \ud589\uc0ac\uae30\uac04(\uc81c146\uc870)\uc740 \ubc95\ub960\uad00\uacc4\uc758 \uc870\uc18d\ud55c \ud655\uc815\uc744 \uc704\ud55c \ubc95\uc815\uae30\uac04\uc73c\ub85c\uc11c, \ub2f9\uc0ac\uc790\uc758 \ud569\uc758\ub85c \uc784\uc758\ub85c \uc5f0\uc7a5\ud560 \uc218 \uc5c6\ub294 \uac15\ud589\uaddc\uc815\uc73c\ub85c \uc774\ud574\ub41c\ub2e4. \ucde8\uc18c\uad8c\uc790 1\uc778\uc758 \ucde8\uc18c\ub85c \uc804\uccb4\uac00 \uc18c\uae09 \ubb34\ud6a8\ub41c\ub2e4\ub294 \uc810, \ubc95\uc815\ucd94\uc778\uc774 \uba85\uc2dc\uc801 \uc758\uc0ac\ud45c\uc2dc \uc5c6\uc774 \uc131\ub9bd\ud560 \uc218 \uc788\ub2e4\ub294 \uc810, \uc81c\ud55c\ub2a5\ub825\uc744 \uc774\uc720\ub85c \ud55c \ucde8\uc18c\ub294 \uc0c1\ub300\ubc29\uc758 \uc120\uc758\xb7\uc545\uc758\ub97c \ubd88\ubb38\ud55c\ub2e4\ub294 \uc810\uc740 \ubaa8\ub450 \uc633\ub2e4.",B.a0c,B.a72,null)
B.a6z=s(["\ubc95\ub960\ud589\uc704\uac00 \uc131\ub9bd \ub2f9\uc2dc\ubd80\ud130 \ub2f9\uc5f0\ud788 \ud6a8\ub825\uc774 \uc5c6\ub2e4","\ucde8\uc18c\uad8c\uc790\uac00 \ucde8\uc18c\ud574\uc57c\ub9cc \ud6a8\ub825\uc744 \uc783\ub294\ub2e4","\ubb34\ud6a8\ub294 \uc77c\uc815 \uae30\uac04\uc774 \uc9c0\ub098\uba74 \ub2f9\uc5f0\ud788 \uc720\ud6a8\ub85c \uc804\ud658\ub41c\ub2e4","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\ub294 \ud2b9\uc815\uc778\ub9cc \uc8fc\uc7a5\ud560 \uc218 \uc788\ub2e4"],t.s)
B.b_m=s(["\uc131\ub9bd \ub2f9\uc2dc\ubd80\ud130 \ub2f9\uc5f0\ud788 \ud6a8\ub825\uc774 \uc5c6\ub2e4"],t.s)
B.a3f=s(["\ubb34\ud6a8\uc758 \uc758\uc758"],t.s)
B.bsK=new A.a("gen_cl_void_1","civil_law","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704",null,"\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.a6z,0,"\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\ub294 \ubcc4\ub3c4\uc758 \uc758\uc0ac\ud45c\uc2dc\ub098 \uc808\ucc28 \uc5c6\uc774 \uc131\ub9bd \ub2f9\uc2dc\ubd80\ud130 \ub2f9\uc5f0\ud788 \ubc95\ub960\ud6a8\uacfc\uac00 \ubc1c\uc0dd\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc774\ub294 \uc77c\ub2e8 \uc720\ud6a8\ud558\uac8c \uc131\ub9bd\ud558\uc5ec \ucde8\uc18c\ub418\uae30 \uc804\uae4c\uc9c0 \ud6a8\ub825\uc744 \uc720\uc9c0\ud558\ub294 \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\uc640 \uadfc\ubcf8\uc801\uc73c\ub85c \ub2e4\ub974\ub2e4.",B.b_m,B.a3f,null)
B.b8e=s(["\ud2b9\ubcc4\ud55c \uc0ac\uc815\uc774 \uc5c6\ub294 \ud55c \ub204\uad6c\ub4e0\uc9c0 \uc774\ud574\uad00\uacc4\uac00 \uc788\uc73c\uba74 \ubb34\ud6a8\ub97c \uc8fc\uc7a5\ud560 \uc218 \uc788\ub2e4","\uc624\uc9c1 \ubc95\ub960\ud589\uc704\uc758 \ub2f9\uc0ac\uc790\ub9cc \uc8fc\uc7a5\ud560 \uc218 \uc788\ub2e4","\uc624\uc9c1 \ubc95\uc815\ub300\ub9ac\uc778\ub9cc \uc8fc\uc7a5\ud560 \uc218 \uc788\ub2e4","\uac80\uc0ac\ub9cc \ubb34\ud6a8\ub97c \uc8fc\uc7a5\ud560 \uc218 \uc788\ub2e4"],t.s)
B.aDF=s(["\ub204\uad6c\ub4e0\uc9c0 \uc774\ud574\uad00\uacc4\uac00 \uc788\uc73c\uba74 \ubb34\ud6a8\ub97c \uc8fc\uc7a5\ud560 \uc218 \uc788\ub2e4"],t.s)
B.ake=s(["\ubb34\ud6a8 \uc8fc\uc7a5\uad8c\uc790\uc758 \ubc94\uc704"],t.s)
B.bth=new A.a("gen_cl_void_2","civil_law","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704",null,"\ubb34\ud6a8\ub97c \uc8fc\uc7a5\ud560 \uc218 \uc788\ub294 \uc790\uc758 \ubc94\uc704\ub85c \uc633\uc740 \uac83\uc740?",B.b8e,0,"\ucde8\uc18c\uad8c\uc740 \uc81c140\uc870\uac00 \uc815\ud55c \ucde8\uc18c\uad8c\uc790\ub9cc \ud589\uc0ac\ud560 \uc218 \uc788\ub294 \ubc18\uba74, \ubb34\ud6a8\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \ud2b9\uc815\ud55c \uc8fc\uc7a5\uad8c\uc790\uac00 \uc815\ud574\uc838 \uc788\uc9c0 \uc54a\uace0 \ubc95\ub960\uc0c1 \uc774\ud574\uad00\uacc4 \uc788\ub294 \uc790\ub77c\uba74 \ub204\uad6c\ub4e0\uc9c0 \uadf8 \ubb34\ud6a8\ub97c \uc8fc\uc7a5\ud560 \uc218 \uc788\ub2e4. \uc774\ub294 \ucde8\uc18c\uc640 \ubb34\ud6a8\uc758 \ub300\ud45c\uc801 \ucc28\uc774\uc810 \uc911 \ud558\ub098\uc774\ub2e4.",B.aDF,B.ake,null)
B.YI=s(["\ubb34\ud6a8 \uc8fc\uc7a5\uc740 \uc6d0\uce59\uc801\uc73c\ub85c \uae30\uac04\uc758 \uc81c\ud55c \uc5c6\uc774 \uc5b8\uc81c\ub4e0\uc9c0 \ud560 \uc218 \uc788\ub2e4","\ubb34\ud6a8 \uc8fc\uc7a5\ub3c4 \ucde8\uc18c\uad8c\uacfc \ub9c8\ucc2c\uac00\uc9c0\ub85c 3\ub144\xb710\ub144\uc758 \uae30\uac04 \uc81c\ud55c\uc744 \ubc1b\ub294\ub2e4","\ubb34\ud6a8 \uc8fc\uc7a5\uc740 \ubc18\ub4dc\uc2dc \uc18c\ub97c \uc81c\uae30\ud558\ub294 \ubc29\ubc95\uc73c\ub85c\ub9cc \ud560 \uc218 \uc788\ub2e4","\ubb34\ud6a8 \uc8fc\uc7a5\uc740 \ubc95\uc815\ub300\ub9ac\uc778\ub9cc \ud560 \uc218 \uc788\ub2e4"],t.s)
