B.by8=new A.a("gen_cl_void_3","civil_law","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704",null,"\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\uc758 \uc8fc\uc7a5\uc5d0 \uad00\ud558\uc5ec \ucde8\uc18c\uad8c\uacfc \ube44\uad50\ud588\uc744 \ub54c \uc633\uc740 \uac83\uc740?",B.YI,0,"\ucde8\uc18c\uad8c\uc740 \uc81c146\uc870\uc5d0 \ub530\ub77c \ucd94\uc778\ud560 \uc218 \uc788\ub294 \ub0a0\ubd80\ud130 3\ub144, \ubc95\ub960\ud589\uc704\ub97c \ud55c \ub0a0\ubd80\ud130 10\ub144\uc758 \uae30\uac04 \uc81c\ud55c\uc744 \ubc1b\uc544 \uc18c\uba78\ud558\uc9c0\ub9cc, \ubb34\ud6a8\ub294 \uadf8\ub7ec\ud55c \ud615\uc131\uad8c \ud589\uc0ac\uae30\uac04 \uc81c\ud55c\uc774 \uc5c6\uc5b4 \uc6d0\uce59\uc801\uc73c\ub85c \uc5b8\uc81c\ub4e0\uc9c0 \uadf8 \ubb34\ud6a8\ub97c \uc8fc\uc7a5\ud560 \uc218 \uc788\ub2e4.",B.aB0,B.aLW,null)
B.aZd=s(["\uac15\ud589\ubc95\uaddc \uc704\ubc18","\ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704(\uc81c103\uc870)","\ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704(\uc81c104\uc870)","\uc81c\ud55c\ub2a5\ub825\uc790\uc758 \ubc95\ub960\ud589\uc704"],t.s)
B.aM_=s(["\uc81c\ud55c\ub2a5\ub825\uc790\uc758 \ubc95\ub960\ud589\uc704\ub294 \ucc98\uc74c\ubd80\ud130 \ud6a8\ub825\uc774 \uc5c6\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\uc5d0 \ud574\ub2f9\ud55c\ub2e4"],t.s)
