B.b4C=s(["\uc77c\ubd80\ubb34\ud6a8 \uc608\uc678\uc758 \uc694\uac74"],t.s)
B.bMX=new A.a("gen_cl_void_8","civil_law","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704",null,"\uc77c\ubd80\ubb34\ud6a8\uc758 \uc608\uc678\ub85c\uc11c \ub098\uba38\uc9c0 \ubd80\ubd84\uc774 \uc720\ud6a8\uac00 \ub418\uae30 \uc704\ud55c \uc694\uac74\uc740?",B.a_E,0,"\uc81c137\uc870 \ub2e8\uc11c\uc5d0 \ub530\ub77c, \ubb34\ud6a8\uc778 \ubd80\ubd84\uc774 \uc5c6\uc5c8\ub354\ub77c\ub3c4 \ub2f9\uc0ac\uc790\uac00 \uadf8 \ubc95\ub960\ud589\uc704\ub97c \ud558\uc600\uc744 \uac83\uc774\ub77c\uace0 (\uac00\uc815\uc801\uc73c\ub85c) \uc778\uc815\ub418\ub294 \uacbd\uc6b0\uc5d0 \ud55c\ud574 \ub098\uba38\uc9c0 \ubd80\ubd84\uc774 \uc720\ud6a8\ub85c \ub0a8\ub294\ub2e4. \uc774\ub294 \ub2f9\uc0ac\uc790\uc758 \uc2e4\uc81c\xb7\uac00\uc815\uc801 \uc758\uc0ac\ub97c \uae30\uc900\uc73c\ub85c \ud310\ub2e8\ud558\ub294 \uac83\uc774\uba70, \ubb34\ud6a8 \ubd80\ubd84\uc758 \ube44\uc911\uc774\ub098 \ubcc4\ub3c4 \ud5c8\uac00\uc640\ub294 \ubb34\uad00\ud558\ub2e4.",B.auX,B.b4C,null)
B.aeO=s(["\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\uac00 \ub2e4\ub978 \ubc95\ub960\ud589\uc704\uc758 \uc694\uac74\uc744 \uac16\ucd94\uace0 \ub2f9\uc0ac\uc790\uac00 \uadf8 \ub2e4\ub978 \ud589\uc704\ub97c \uc758\ub3c4\ud558\uc600\uc744 \uac83\uc73c\ub85c \uc778\uc815\ub418\uba74 \uadf8 \ub2e4\ub978 \ubc95\ub960\ud589\uc704\ub85c\uc11c \ud6a8\ub825\uc744 \uac00\uc9c4\ub2e4","\ubb34\ud6a8\ud589\uc704\ub294 \uc5b4\ub5a4 \uacbd\uc6b0\uc5d0\ub3c4 \ub2e4\ub978 \ubc95\ub960\ud589\uc704\ub85c \uc804\ud658\ub420 \uc218 \uc5c6\ub2e4","\ubb34\ud6a8\ud589\uc704\uc758 \uc804\ud658\uc740 \ubc95\uc6d0\uc758 \uc9c1\uad8c\uc73c\ub85c\ub9cc \uc778\uc815\ub41c\ub2e4","\uc804\ud658\ub41c \ubc95\ub960\ud589\uc704\ub294 \uc6d0\ub798 \ud589\uc704\uc640 \ub3d9\uc77c\ud55c \ud6a8\ub825\uc744 \uac00\uc9c4\ub2e4"],t.s)
B.avN=s(["\ub2e4\ub978 \ubc95\ub960\ud589\uc704\ub85c\uc11c \ud6a8\ub825\uc744 \uac00\uc9c4\ub2e4"],t.s)
