B.btS=new A.a("gen_cl_void_10","civil_law","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704",null,"\ubb34\ud6a8\ud589\uc704\uc758 \ucd94\uc778(\uc81c139\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aSQ,0,'\ubbfc\ubc95 \uc81c139\uc870 \ubcf8\ubb38\uc740 \ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\ub294 \ub2f9\uc0ac\uc790\uac00 \uadf8 \ubb34\ud6a8\uc784\uc744 \uc54c\uace0 \ucd94\uc778\ud558\ub354\ub77c\ub3c4 \uc6d0\uce59\uc801\uc73c\ub85c \ud6a8\ub825\uc774 \uc0dd\uae30\uc9c0 \uc54a\ub294\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ub2e4\ub9cc \ub2e8\uc11c\uc5d0 \ub530\ub77c \ub2f9\uc0ac\uc790\uac00 \ubb34\ud6a8\uc784\uc744 "\uc54c\uace0" \ucd94\uc778\ud55c \ub54c\uc5d0\ub294 \uc0c8\ub85c\uc6b4 \ubc95\ub960\ud589\uc704\ub97c \ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4. \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ud589\uc704\uc758 \ucd94\uc778\uc774 \uc6d0\ub798 \ud589\uc704\ub97c \uadf8\ub300\ub85c \ud655\uc815\uc801\uc73c\ub85c \uc720\ud6a8\ud654\ud558\ub294 \uac83\uacfc\ub294 \uc131\uaca9\uc774 \ub2e4\ub974\ub2e4.',B.Zt,B.b43,null)
B.aT_=s(["\ub2f9\uc0ac\uc790\uac00 \uadf8 \ud589\uc704\uac00 \ubb34\ud6a8\uc784\uc744 \uc54c\uace0\uc11c \ucd94\uc778\ud558\uc5ec\uc57c \ud55c\ub2e4","\ub2f9\uc0ac\uc790\uac00 \ubb34\ud6a8\uc784\uc744 \ubaa8\ub974\uace0 \ucd94\uc778\ud574\ub3c4 \ubb34\ubc29\ud558\ub2e4","\ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758\uac00 \uc788\uc5b4\uc57c \ud55c\ub2e4","\ucd94\uc778 \ud6c4 3\ub144\uc774 \uacbd\uacfc\ud558\uc5ec\uc57c \ud55c\ub2e4"],t.s)
B.afh=s(["\ub2f9\uc0ac\uc790\uac00 \uadf8 \ud589\uc704\uac00 \ubb34\ud6a8\uc784\uc744 \uc54c\uace0\uc11c \ucd94\uc778\ud558\uc5ec\uc57c \ud55c\ub2e4"],t.s)
B.aAF=s(["\ubb34\ud6a8\ud589\uc704\uc758 \ucd94\uc778 \uc694\uac74"],t.s)
B.bIy=new A.a("gen_cl_void_11","civil_law","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704",null,"\ubb34\ud6a8\ud589\uc704\uc758 \ucd94\uc778\uc774 \uc0c8\ub85c\uc6b4 \ubc95\ub960\ud589\uc704\ub85c\uc11c \ud6a8\ub825\uc744 \uac00\uc9c0\uae30 \uc704\ud55c \uc694\uac74\uc740?",B.aT_,0,'\uc81c139\uc870 \ub2e8\uc11c\ub294 \ub2f9\uc0ac\uc790\uac00 \ubb34\ud6a8\uc784\uc744 "\uc54c\uace0" \ucd94\uc778\ud55c \uacbd\uc6b0\uc5d0 \ud55c\ud558\uc5ec \uadf8 \ucd94\uc778\uc744 \uc0c8\ub85c\uc6b4 \ubc95\ub960\ud589\uc704\ub85c \uc778\uc815\ud55c\ub2e4. \ubb34\ud6a8\uc784\uc744 \ubaa8\ub974\uace0 \ud55c \ucd94\uc778\uc740 \uc774\ub7ec\ud55c \ud6a8\ub825\uc774 \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4.',B.afh,B.aAF,null)
B.aEt=s(["\uacc4\uc57d \uc131\ub9bd \ub2f9\uc2dc\ubd80\ud130 \uc774\ud589\uc774 \ubd88\uac00\ub2a5\ud558\uc600\ub2e4\uba74 \uadf8 \uacc4\uc57d\uc740 \uc6d0\uce59\uc801\uc73c\ub85c \ubb34\ud6a8\uc774\ub2e4","\uc6d0\uc2dc\uc801 \ubd88\ub2a5\ub3c4 \ud6c4\ubc1c\uc801 \ubd88\ub2a5\uacfc \ub9c8\ucc2c\uac00\uc9c0\ub85c \ucc44\ubb34\ubd88\uc774\ud589\ucc45\uc784\uc774 \ubc1c\uc0dd\ud55c\ub2e4","\uc6d0\uc2dc\uc801 \ubd88\ub2a5\uc778 \uacc4\uc57d\uc740 \ud56d\uc0c1 \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\uc5d0 \ud574\ub2f9\ud55c\ub2e4","\uc6d0\uc2dc\uc801 \ubd88\ub2a5\uc740 \ubc95\ub960\ud589\uc704\uc758 \ud6a8\ub825\uc5d0 \uc601\ud5a5\uc744 \ubbf8\uce58\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.af0=s(["\uacc4\uc57d \uc131\ub9bd \ub2f9\uc2dc\ubd80\ud130 \uc774\ud589\uc774 \ubd88\uac00\ub2a5\ud558\uc600\ub2e4\uba74 \uadf8 \uacc4\uc57d\uc740 \uc6d0\uce59\uc801\uc73c\ub85c \ubb34\ud6a8\uc774\ub2e4"],t.s)
B.bdH=s(["\uc6d0\uc2dc\uc801 \ubd88\ub2a5\uacfc \ubb34\ud6a8"],t.s)
B.bnP=new A.a("gen_cl_void_12","civil_law","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704",null,"\uc6d0\uc2dc\uc801 \ubd88\ub2a5\uc778 \ubc95\ub960\ud589\uc704\uc758 \ud6a8\ub825\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aEt,0,"\ubc95\ub960\ud589\uc704(\uacc4\uc57d) \uc131\ub9bd \ub2f9\uc2dc\ubd80\ud130 \uadf8 \ubaa9\uc801\uc758 \uc774\ud589\uc774 \uac1d\uad00\uc801\uc73c\ub85c \ubd88\uac00\ub2a5\ud55c \uacbd\uc6b0(\uc6d0\uc2dc\uc801 \ubd88\ub2a5)\uc5d0\ub294 \uadf8 \ubc95\ub960\ud589\uc704\ub294 \ubb34\ud6a8\uc774\ub2e4. \uc774\ub294 \uacc4\uc57d \uc131\ub9bd \ud6c4\uc5d0 \uc774\ud589\uc774 \ubd88\uac00\ub2a5\ud574\uc9c0\ub294 \ud6c4\ubc1c\uc801 \ubd88\ub2a5(\uc774\ud589\ubd88\ub2a5, \ucc44\ubb34\ubd88\uc774\ud589\uc758 \ubb38\uc81c)\uacfc \uad6c\ubcc4\ub418\ub294 \ubcc4\ub3c4\uc758 \ubc95\ub9ac\uc774\ub2e4.",B.af0,B.bdH,null)
B.ajR=s([u.is,"\uac15\ud589\ubc95\uaddc\ub294 \ub2f9\uc0ac\uc790\uc758 \ud569\uc758\ub85c \uc5b8\uc81c\ub4e0\uc9c0 \uadf8 \uc801\uc6a9\uc744 \ubc30\uc81c\ud560 \uc218 \uc788\ub2e4","\uac15\ud589\ubc95\uaddc \uc704\ubc18\uc740 \ud56d\uc0c1 \ucde8\uc18c\uc0ac\uc720\uc5d0 \ubd88\uacfc\ud558\ub2e4","\uac15\ud589\ubc95\uaddc \uc704\ubc18 \uc5ec\ubd80\ub294 \ubc95\ub960\ud589\uc704\uc758 \ud6a8\ub825\uc5d0 \uc601\ud5a5\uc774 \uc5c6\ub2e4"],t.s)
B.b0o=s([u.is],t.s)
B.be0=s(["\uac15\ud589\ubc95\uaddc \uc704\ubc18\uc758 \ud6a8\ub825"],t.s)
B.bss=new A.a("gen_cl_void_13","civil_law","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704",null,"\uac15\ud589\ubc95\uaddc \uc704\ubc18\uc758 \ubc95\ub960\ud589\uc704\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.ajR,0,"\uac15\ud589\ubc95\uaddc(\uac15\ud589\uaddc\uc815)\ub294 \ub2f9\uc0ac\uc790\uc758 \uc758\uc0ac\ub85c \uadf8 \uc801\uc6a9\uc744 \ubc30\uc81c\ud560 \uc218 \uc5c6\ub294 \uaddc\uc815\uc73c\ub85c, \uc774\ub97c \uc704\ubc18\ud55c \ubc95\ub960\ud589\uc704\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \ubb34\ud6a8\uc774\ub2e4. \uc774\uc640 \ub2ec\ub9ac \ub2f9\uc0ac\uc790\uc758 \uc758\uc0ac\ub85c \uadf8 \uc801\uc6a9\uc744 \ubc30\uc81c\ud560 \uc218 \uc788\ub294 \uaddc\uc815\uc740 \uc784\uc758\ubc95\uaddc(\uc784\uc758\uaddc\uc815)\ub77c \ud558\uba70, \uc774\ub97c \uc704\ubc18\ud574\ub3c4 \ubc95\ub960\ud589\uc704\uc758 \ud6a8\ub825\uc5d0\ub294 \uc601\ud5a5\uc774 \uc5c6\ub2e4.",B.b0o,B.be0,null)
B.aR7=s(["\ud5c8\uac00\ub97c \ubc1b\uc73c\uba74 \uc18c\uae09\ud558\uc5ec \uc720\ud6a8\uac00 \ub418\uace0, \ubd88\ud5c8\uac00\uac00 \ud655\uc815\ub418\uba74 \ud655\uc815\uc801\uc73c\ub85c \ubb34\ud6a8\uac00 \ub418\ub294 \uc0c1\ud0dc\uc774\ub2e4","\ud5c8\uac00 \uc5ec\ubd80\uc640 \ubb34\uad00\ud558\uac8c \ud56d\uc0c1 \ud655\uc815\uc801\uc73c\ub85c \ubb34\ud6a8\uc774\ub2e4","\ud5c8\uac00\ub97c \ubc1b\uae30 \uc804\uc5d0\ub3c4 \uc644\uc804\ud788 \uc720\ud6a8\ud55c \ubc95\ub960\ud589\uc704\ub85c \ucde8\uae09\ub41c\ub2e4","\uc720\ub3d9\uc801 \ubb34\ud6a8\ub294 \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\uc640 \ub3d9\uc77c\ud55c \uac1c\ub150\uc774\ub2e4"],t.s)
B.avd=s(["\ud5c8\uac00\ub97c \ubc1b\uc73c\uba74 \uc18c\uae09\ud558\uc5ec \uc720\ud6a8\uac00 \ub418\uace0, \ubd88\ud5c8\uac00\uac00 \ud655\uc815\ub418\uba74 \ud655\uc815\uc801\uc73c\ub85c \ubb34\ud6a8\uac00 \ub418\ub294 \uc0c1\ud0dc"],t.s)
B.a7D=s(["\uc720\ub3d9\uc801 \ubb34\ud6a8"],t.s)
B.bvR=new A.a("gen_cl_void_14","civil_law","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704",null,"\uc720\ub3d9\uc801 \ubb34\ud6a8(\uc608: \ud1a0\uc9c0\uac70\ub798\ud5c8\uac00\uad6c\uc5ed \ub0b4 \ud5c8\uac00 \uc804 \ub9e4\ub9e4\uacc4\uc57d)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aR7,0,"\ud1a0\uc9c0\uac70\ub798\ud5c8\uac00\uad6c\uc5ed \ub0b4\uc5d0\uc11c \ud5c8\uac00\ub97c \ubc1b\uae30 \uc804\uc5d0 \uccb4\uacb0\ub41c \ub9e4\ub9e4\uacc4\uc57d\uc740 \ud310\ub840\uc0c1 \uc720\ub3d9\uc801 \ubb34\ud6a8\ub85c \ucde8\uae09\ub41c\ub2e4. \uad00\uccad\uc758 \ud5c8\uac00\ub97c \ubc1b\uc73c\uba74 \uacc4\uc57d\uccb4\uacb0 \uc2dc\ub85c \uc18c\uae09\ud558\uc5ec \uc720\ud6a8\ud55c \uacc4\uc57d\uc774 \ub418\uace0, \ubd88\ud5c8\uac00\uac00 \ud655\uc815\ub418\uac70\ub098 \ub2f9\uc0ac\uc790\uac00 \ud5c8\uac00\uc2e0\uccad\uc744 \ud558\uc9c0 \uc54a\uae30\ub85c \ud611\uc758\ud558\ub294 \ub4f1\uc758 \uc0ac\uc815\uc774 \uc788\uc73c\uba74 \ud655\uc815\uc801\uc73c\ub85c \ubb34\ud6a8\uac00 \ub41c\ub2e4.",B.avd,B.a7D,null)
B.a30=s(["\ubb34\ud6a8\ub294 \ud2b9\uc815 \uc8fc\uc7a5\uad8c\uc790\ub9cc \uc8fc\uc7a5\ud560 \uc218 \uc788\uace0, \ucde8\uc18c\ub294 \ub204\uad6c\ub4e0\uc9c0 \uc8fc\uc7a5\ud560 \uc218 \uc788\ub2e4","\ubb34\ud6a8\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \ucc98\uc74c\ubd80\ud130 \ud6a8\ub825\uc774 \uc5c6\uace0, \ucde8\uc18c\ub294 \ucde8\uc18c \uc804\uae4c\uc9c0 \uc720\ud6a8\ud558\ub2e4","\ubb34\ud6a8 \uc8fc\uc7a5\uc5d0\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \uae30\uac04 \uc81c\ud55c\uc774 \uc5c6\uc73c\ub098, \ucde8\uc18c\uad8c\uc5d0\ub294 \ud589\uc0ac\uae30\uac04 \uc81c\ud55c\uc774 \uc788\ub2e4","\ubb34\ud6a8\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \ucd94\uc778\ud574\ub3c4 \ud6a8\ub825\uc774 \uc0dd\uae30\uc9c0 \uc54a\uc73c\ub098, \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ud589\uc704\ub294 \ucd94\uc778\ud558\uba74 \ud655\uc815\uc801\uc73c\ub85c \uc720\ud6a8\uac00 \ub41c\ub2e4"],t.s)
B.awQ=s(["\ucde8\uc18c\ub294 \uc81c140\uc870\uac00 \uc815\ud55c \ud2b9\uc815 \ucde8\uc18c\uad8c\uc790\ub9cc \ud589\uc0ac\ud560 \uc218 \uc788\uace0, \ubb34\ud6a8\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \uc774\ud574\uad00\uacc4 \uc788\ub294 \uc790\ub77c\uba74 \ub204\uad6c\ub4e0\uc9c0 \uc8fc\uc7a5\ud560 \uc218 \uc788\ub2e4"],t.s)
B.aSJ=s(["\ubb34\ud6a8\uc640 \ucde8\uc18c\uc758 \uc885\ud569 \ube44\uad50"],t.s)
B.bHa=new A.a("gen_cl_void_15","civil_law","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704",null,"\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\uc640 \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\ub97c \ube44\uad50\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.a30,0,"\uc8fc\uc7a5\uad8c\uc790\uc5d0 \uad00\ud558\uc5ec\ub294 \uc624\ud788\ub824 \ubc18\ub300\ub85c, \ucde8\uc18c\ub294 \uc81c140\uc870\uac00 \uc815\ud55c \ud2b9\uc815 \ucde8\uc18c\uad8c\uc790\ub9cc \ud589\uc0ac\ud560 \uc218 \uc788\uace0, \ubb34\ud6a8\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \uc774\ud574\uad00\uacc4 \uc788\ub294 \uc790\ub77c\uba74 \ub204\uad6c\ub4e0\uc9c0 \uc8fc\uc7a5\ud560 \uc218 \uc788\ub2e4. \ub098\uba38\uc9c0 \ud6a8\ub825\ubc1c\uc0dd\uc2dc\uc810, \uae30\uac04 \uc81c\ud55c, \ucd94\uc778\uc758 \ud6a8\uacfc\uc5d0 \uad00\ud55c \uc124\uba85\uc740 \ubaa8\ub450 \uc633\ub2e4.",B.awQ,B.aSJ,null)
B.beG=s(["\ud53c\ud574\uc790 \uce21\uc758 \uad81\ubc15\xb7\uacbd\uc194\xb7\ubb34\uacbd\ud5d8 \uc911 \ud558\ub098","\uae09\ubd80\uc640 \ubc18\ub300\uae09\ubd80 \uc0ac\uc774\uc758 \ud604\uc800\ud55c \ubd88\uade0\ud615","\ud3ed\ub9ac\ud589\uc704\uc790\uc758 \uc774\uc6a9\uc758\uc0ac(\uc545\uc758)","\ud53c\ud574\uc790\uc5d0\uac8c \ubc95\uc815\ub300\ub9ac\uc778\uc774 \uc788\uc744 \uac83"],t.s)
B.QV=s(["\uad81\ubc15\xb7\uacbd\uc194\xb7\ubb34\uacbd\ud5d8 \uc911 \ud558\ub098, \uae09\ubd80\uc640 \ubc18\ub300\uae09\ubd80\uc758 \ud604\uc800\ud55c \ubd88\uade0\ud615, \ud3ed\ub9ac\ud589\uc704\uc790\uc758 \uc774\uc6a9\uc758\uc0ac(\uc545\uc758)\ub77c\ub294 \uc138 \uc694\uac74\uc774 \ubaa8\ub450 \ud544\uc694"],t.s)
