B.bGw=new A.a("gen_cl_void_18","civil_law","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704",null,"\ubd88\ubc95\uc6d0\uc778\uae09\uc5ec(\uc81c746\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aNF,0,"\ubbfc\ubc95 \uc81c746\uc870\ub294 \ubd88\ubc95\uc758 \uc6d0\uc778\uc73c\ub85c \uc7ac\uc0b0\uc744 \uae09\uc5ec\ud558\uac70\ub098 \ub178\ubb34\ub97c \uc81c\uacf5\ud55c \ub54c\uc5d0\ub294 \uadf8 \uc774\uc775\uc758 \ubc18\ud658\uc744 \uccad\uad6c\ud558\uc9c0 \ubabb\ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc774\ub294 \ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704(\uc81c103\uc870) \ub4f1\uc73c\ub85c \ubb34\ud6a8\uc778 \uacc4\uc57d\uc5d0 \uae30\ud574 \uc774\ubbf8 \uc774\ud589\uc774 \uc774\ub8e8\uc5b4\uc9c4 \uacbd\uc6b0, \ubb34\ud6a8\ub97c \uc774\uc720\ub85c \ud55c \ubd80\ub2f9\uc774\ub4dd\ubc18\ud658\uccad\uad6c\ub97c \uc81c\ud55c\ud558\uc5ec \uc2a4\uc2a4\ub85c \ubd88\ubc95\ud589\uc704\uc5d0 \uac00\ub2f4\ud55c \uc790\ub97c \ubcf4\ud638\ud558\uc9c0 \uc54a\uc73c\ub824\ub294 \ucde8\uc9c0\uc774\ub2e4.",B.TZ,B.aHf,null)
B.aFd=s(["\ud655\uc815\uc801\uc73c\ub85c \ubb34\ud6a8\uac00 \ub41c\ub2e4","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\ub85c \uc804\ud658\ub41c\ub2e4","\ubb34\uad8c\ub300\ub9ac\uc778\uc5d0\uac8c\ub9cc \uc720\ud6a8\ud558\ub2e4","\uc0c1\ub300\ubc29\uc774 \ub2e4\uc2dc \ucd94\uc778\uc744 \uc694\uad6c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.b_F=s(["\ud655\uc815\uc801\uc73c\ub85c \ubb34\ud6a8\uac00 \ub41c\ub2e4"],t.s)
