B.bt3=new A.a("gen_cl_void_19","civil_law","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704",null,"\ubb34\uad8c\ub300\ub9ac\ud589\uc704\uc5d0\uc11c \ubcf8\uc778\uc774 \ucd94\uc778\uc744 \uac70\uc808\ud55c \uacbd\uc6b0\uc758 \ud6a8\ub825\uc740?",B.aFd,0,"\ubb34\uad8c\ub300\ub9ac\ud589\uc704\ub294 \ubcf8\uc778\uc758 \ucd94\uc778\uc774 \uc788\uae30 \uc804\uae4c\uc9c0 \ubcf8\uc778\uc5d0 \ub300\ud574 \ud6a8\ub825\uc774 \ubc1c\uc0dd\ud560\uc9c0 \uc5ec\ubd80\uac00 \uc815\ud574\uc9c0\uc9c0 \uc54a\uc740 \uc720\ub3d9\uc801 \ubb34\ud6a8 \uc0c1\ud0dc\uc5d0 \uc788\ub2e4. \ubcf8\uc778\uc774 \ucd94\uc778\uc744 \uac70\uc808\ud558\uba74 \uadf8 \uc720\ub3d9\uc801 \uc0c1\ud0dc\uac00 \ud574\uc18c\ub418\uc5b4 \ud655\uc815\uc801\uc73c\ub85c \ubb34\ud6a8\uac00 \ub418\uba70, \uc774\ud6c4\uc5d0\ub294 \ub2e4\uc2dc \ucd94\uc778\ud558\uc5ec\ub3c4 \uc720\ud6a8\ub85c \ub418\uc9c0 \uc54a\ub294\ub2e4.",B.b_F,B.bgi,null)
B.aJN=s([u.ma,"\uc77c\ubd80 \uc870\ud56d\uc774 \ubb34\ud6a8\uc774\uba74 \uacc4\uc57d \uc804\uccb4\uac00 \ud56d\uc0c1 \ubb34\ud6a8\uc774\ub2e4","\uc77c\ubd80 \uc870\ud56d\uc758 \ubb34\ud6a8\ub294 \uacc4\uc57d \uc804\uccb4\uc758 \ud6a8\ub825\uc5d0 \uc544\ubb34\ub7f0 \uc601\ud5a5\uc744 \ubbf8\uce58\uc9c0 \uc54a\ub294\ub2e4","\uc77c\ubd80\ubb34\ud6a8\ub294 \uac00\ub9f9\uacc4\uc57d\uc5d0\ub294 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4"],t.s)
