B.bqN=new A.a("gen_cl_void_24","civil_law","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704",null,"\ubb34\ud6a8\ud589\uc704\uc758 \uc804\ud658(\uc81c138\uc870)\uacfc \uc77c\ubd80\ubb34\ud6a8(\uc81c137\uc870)\ub97c \ube44\uad50\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.b2q,0,"\uc77c\ubd80\ubb34\ud6a8(\uc81c137\uc870)\ub294 \ud558\ub098\uc758 \ubc95\ub960\ud589\uc704 \uc911 \uc77c\ubd80 \uc870\ud56d\xb7\ubd80\ubd84\ub9cc \ubb34\ud6a8\uc778 \uacbd\uc6b0 \ub098\uba38\uc9c0 \ubd80\ubd84\uc758 \ud6a8\ub825\uc744 \ub2e4\ub8e8\ub294 \uc81c\ub3c4\uc774\uace0, \ubb34\ud6a8\ud589\uc704\uc758 \uc804\ud658(\uc81c138\uc870)\uc740 \uc6d0\ub798 \uc758\ub3c4\ud55c \ubc95\ub960\ud589\uc704 \uc790\uccb4\ub294 \ubb34\ud6a8\uc774\uc9c0\ub9cc \ub2e4\ub978 \uc885\ub958\uc758 \ubc95\ub960\ud589\uc704 \uc694\uac74\uc744 \uac16\ucd98 \uacbd\uc6b0 \uadf8 \ub2e4\ub978 \ud589\uc704\ub85c\uc11c \ud6a8\ub825\uc744 \uc778\uc815\ud558\ub294 \uc81c\ub3c4\ub85c, \uc801\uc6a9 \uad6d\uba74\uc774 \uc11c\ub85c \ub2e4\ub974\ub2e4.",B.asu,B.aqv,null)
B.ape=s(["\uac15\ud589\uaddc\uc815 \uc704\ubc18\uc740 \ub2f9\uc0ac\uc790\uc758 \uc758\uc0ac\ub85c \uadf8 \ud558\uc790\ub97c \uce58\uc720\ud560 \uc218 \uc5c6\uc73c\ubbc0\ub85c \ucd94\uc778\uc73c\ub85c\ub3c4 \uc720\ud6a8\uac00 \ub418\uc9c0 \uc54a\ub294\ub2e4","\ub2f9\uc0ac\uc790\uac00 \ubb34\ud6a8\uc784\uc744 \uc54c\uace0 \ucd94\uc778\ud558\uba74 \ud56d\uc0c1 \uc18c\uae09\uc801\uc73c\ub85c \uc720\ud6a8\uac00 \ub41c\ub2e4","\uac15\ud589\uaddc\uc815 \uc704\ubc18 \uc5ec\ubd80\uc640 \ucd94\uc778\uc758 \ud6a8\ub825\uc740 \uc544\ubb34\ub7f0 \uad00\ub828\uc774 \uc5c6\ub2e4","\uac15\ud589\uaddc\uc815 \uc704\ubc18\uc774\ub77c\ub3c4 \uc2dc\uac04\uc774 \uc9c0\ub098\uba74 \uc790\ub3d9\uc73c\ub85c \uc720\ud6a8\uac00 \ub41c\ub2e4"],t.s)
