B.bE2=new A.a("gen_cl_void_25","civil_law","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704",null,"\uac15\ud589\uaddc\uc815 \uc704\ubc18\uc73c\ub85c \ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\ub294 \ubb34\ud6a8\ud589\uc704\uc758 \ucd94\uc778(\uc81c139\uc870)\uc73c\ub85c \uc720\ud6a8\ub85c \uc804\ud658\ub420 \uc218 \uc788\ub294\uac00?",B.ape,0,'\ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704\xb7\ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704\uc640 \uac19\uc774 \uac15\ud589\uaddc\uc815 \uc704\ubc18\uc73c\ub85c \ubb34\ud6a8\uc778 \uacbd\uc6b0, \uc774\ub294 \uacf5\uc775\uc801 \uc774\uc720\ub85c \ud6a8\ub825\uc744 \ubd80\uc778\ud558\ub294 \uac83\uc774\ubbc0\ub85c \ub2f9\uc0ac\uc790\uc758 \uc0ac\uc801 \uc758\uc0ac\ud45c\uc2dc(\ucd94\uc778)\ub85c \uadf8 \ud558\uc790\ub97c \uce58\uc720\ud558\uc5ec \uc720\ud6a8\ub85c \ub9cc\ub4e4 \uc218 \uc5c6\ub2e4. \uc81c139\uc870 \ub2e8\uc11c\uc758 "\uc0c8\ub85c\uc6b4 \ubc95\ub960\ud589\uc704"\ub85c\uc11c\uc758 \ucd94\uc778 \ud6a8\uacfc\ub3c4 \uac15\ud589\uaddc\uc815 \uc704\ubc18\uc774\ub77c\ub294 \ud558\uc790 \uc790\uccb4\ub97c \uc81c\uac70\ud574\uc8fc\uc9c0\ub294 \ubabb\ud55c\ub2e4.',B.aES,B.agD,null)
B.bcP=s(["\ubb34\ud6a8\ub294 \ub2f9\uc5f0\ud788 \ubc1c\uc0dd\ud558\ub294 \ud6a8\uacfc\uc774\uc9c0\ub9cc, \ub2e4\ud23c\uc774 \uc788\uc744 \ub54c \ubc95\ub960\uad00\uacc4\ub97c \uba85\ud655\ud788 \ud655\uc815\ud558\uae30 \uc704\ud574\uc11c\uc774\ub2e4","\ubb34\ud6a8\ub294 \ud655\uc778\ud310\uacb0\uc774 \uc788\uc5b4\uc57c\ub9cc \ube44\ub85c\uc18c \ubc1c\uc0dd\ud558\uae30 \ub54c\ubb38\uc774\ub2e4","\ud655\uc778\uc758 \uc18c\ub97c \uc81c\uae30\ud574\uc57c\ub9cc \ubb34\ud6a8\ub97c \uc8fc\uc7a5\ud560 \uc218 \uc788\ub294 \uc790\uaca9\uc774 \uc0dd\uae30\uae30 \ub54c\ubb38\uc774\ub2e4","\ubb34\ud6a8 \uc8fc\uc7a5\uc740 \ubc18\ub4dc\uc2dc \uc18c\uc1a1\uc744 \ud1b5\ud574\uc11c\ub9cc \ud560 \uc218 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4"],t.s)
B.ayI=s(["\ub2e4\ud23c\uc774 \uc788\uc744 \ub54c \ubc95\ub960\uad00\uacc4\ub97c \uba85\ud655\ud788 \ud655\uc815\ud558\uae30 \uc704\ud574\uc11c\uc774\ub2e4"],t.s)
