B.bOt=new A.a("gen_cl_void_26","civil_law","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704",null,"\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\uc640 \uad00\ub828\ud558\uc5ec \ud655\uc778\uc758 \uc18c\ub97c \uc81c\uae30\ud558\ub294 \uc2e4\ubb34\uc801 \uc774\uc720\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.bcP,0,"\ubb34\ud6a8\ub294 \ub2f9\uc5f0\ud788 \ubc1c\uc0dd\ud558\ub294 \ud6a8\uacfc\uc774\ubbc0\ub85c \uc18c\uc1a1\uc744 \uac70\uce58\uc9c0 \uc54a\uace0\ub3c4 \uc7ac\ud310 \uc678\uc5d0\uc11c \uc8fc\uc7a5\ud560 \uc218 \uc788\uc9c0\ub9cc, \ub2f9\uc0ac\uc790 \uc0ac\uc774\uc5d0 \ub2e4\ud23c\uc774 \uc788\uc744 \uacbd\uc6b0 \ubc95\ub960\uad00\uacc4\ub97c \uacf5\uc801\uc73c\ub85c \uba85\ud655\ud788 \ud655\uc815\ud558\uae30 \uc704\ud574 \ud655\uc778\uc758 \uc18c\ub97c \uc81c\uae30\ud558\ub294 \uac83\uc774 \uc2e4\ubb34\uc0c1 \uc720\uc6a9\ud558\ub2e4.",B.ayI,B.aJr,null)
