B.bDZ=new A.a("gen_cl_void_27","civil_law","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704",null,"\uac00\ub9f9\uacc4\uc57d\uc5d0\uc11c \uac00\ub9f9\ubcf8\ubd80\uac00 \uac00\ub9f9\uc810\uc8fc\uc758 \uad81\ubc15\ud55c \uc0ac\uc815\uc744 \uc774\uc6a9\ud558\uc5ec \uc2dc\uac00\ubcf4\ub2e4 \ud604\uc800\ud788 \ubd88\ub9ac\ud55c \uc870\uac74\uc73c\ub85c \uacc4\uc57d\uc744 \uccb4\uacb0\ud558\uac8c \ud55c \uacbd\uc6b0 \uc801\uc6a9\ub420 \uc218 \uc788\ub294 \ubb34\ud6a8 \uc0ac\uc720\ub294?",B.azx,0,"\uac00\ub9f9\uc810\uc8fc\uc758 \uad81\ubc15\ud55c \uc0ac\uc815\uc744 \uc774\uc6a9\ud574 \ud604\uc800\ud788 \ubd88\uacf5\uc815\ud55c \uc870\uac74(\ud604\uc800\ud55c \uae09\ubd80 \ubd88\uade0\ud615)\uc73c\ub85c \uacc4\uc57d\uc744 \uccb4\uacb0\uc2dc\ucf30\ub2e4\uba74, \ubbfc\ubc95 \uc81c104\uc870\uc758 \ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704\uc5d0 \ud574\ub2f9\ud558\uc5ec \uadf8 \uacc4\uc57d(\ub610\ub294 \ud574\ub2f9 \uc870\ud56d)\uc774 \ubb34\ud6a8\uac00 \ub420 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \uad81\ubc15\xb7\uacbd\uc194\xb7\ubb34\uacbd\ud5d8, \ud604\uc800\ud55c \ubd88\uade0\ud615, \uc774\uc6a9\uc758\uc0ac\ub77c\ub294 \uc138 \uc694\uac74\uc774 \ubaa8\ub450 \uc99d\uba85\ub418\uc5b4\uc57c \ud55c\ub2e4.",B.anI,B.agp,null)
B.aIT=s(["\ubb34\ud6a8\ub294 \ucde8\uc18c\uc640 \ub2ec\ub9ac \ud615\uc131\uad8c \ud589\uc0ac\ub97c \uc694\ud558\uc9c0 \uc54a\ub294\ub2e4","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\ub3c4 \uc774\ud589 \uc804\uc774\ub77c\uba74 \uc544\ubb34 \ubb38\uc81c\uac00 \ub418\uc9c0 \uc54a\uc73c\ubbc0\ub85c \ubcc4\ub3c4\ub85c \ub2e4\ud234 \ud544\uc694\uac00 \uc5c6\ub2e4","\ubb34\ud6a8\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \uc18c\uae09\ud6a8\ub97c \ubb38\uc81c \uc0bc\uc744 \ud544\uc694\uc870\ucc28 \uc5c6\uc774 \ucc98\uc74c\ubd80\ud130 \ud6a8\ub825\uc774 \uc5c6\ub2e4","\uc77c\ubd80\ubb34\ud6a8\xb7\uc804\ud658\xb7\ucd94\uc778\uc740 \ubaa8\ub450 \ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\uc758 \ud6a8\ub825\uc744 \uc870\uc815\ud558\ub294 \ubcc4\uac1c\uc758 \uc81c\ub3c4\uc774\ub2e4"],t.s)
B.a8C=s(["\uc0c1\ub300\ubc29\uc774 \ubb34\ud6a8\ub97c \uc778\uc815\ud558\uc9c0 \uc54a\uace0 \uc774\ud589\uc744 \uc694\uad6c\ud558\ub294 \uacbd\uc6b0\uac00 \uc788\uc744 \uc218 \uc788\uc73c\ubbc0\ub85c"],t.s)
