B.bw8=new A.a("gen_cl_void_30","civil_law","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704",null,"\ub2e4\uc74c \uc911 \ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc744 \ubaa8\ub450 \uace0\ub974\uba74? \u2460 \ubb34\ud6a8\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \uc18c\uae09\ud558\uc5ec \ub2e4\ud234 \ud544\uc694 \uc5c6\uc774 \ucc98\uc74c\ubd80\ud130 \ud6a8\ub825\uc774 \uc5c6\ub2e4 \u2461 \uc808\ub300\uc801 \ubb34\ud6a8\ub294 \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c\ub3c4 \ub300\ud56d\ud560 \uc218 \uc788\ub2e4 \u2462 \ubb34\ud6a8\ud589\uc704\uc758 \ucd94\uc778\uc740 \uc6d0\uce59\uc801\uc73c\ub85c \uc18c\uae09\uc801\uc73c\ub85c \uc720\ud6a8\ud654\ud558\ub294 \ud6a8\uacfc\ub97c \uac00\uc9c4\ub2e4 \u2463 \uac15\ud589\uaddc\uc815 \uc704\ubc18\uc758 \ubb34\ud6a8\ub294 \ub2f9\uc0ac\uc790\uc758 \ucd94\uc778\uc73c\ub85c \uce58\uc720\ub418\uc9c0 \uc54a\ub294\ub2e4",B.b_h,0,'\u2460\ubb34\ud6a8\ub294 \ucc98\uc74c\ubd80\ud130 \ud6a8\ub825\uc774 \uc5c6\ub294 \uac83\uc774 \uc6d0\uce59\uc774\uace0, \u2461\uac15\ud589\uaddc\uc815 \uc704\ubc18\uc5d0 \ub530\ub978 \uc808\ub300\uc801 \ubb34\ud6a8\ub294 \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c\ub3c4 \ub300\ud56d\ud560 \uc218 \uc788\uc73c\uba70, \u2463\uadf8\ub7ec\ud55c \uac15\ud589\uaddc\uc815 \uc704\ubc18\uc758 \ubb34\ud6a8\ub294 \ub2f9\uc0ac\uc790\uc758 \ucd94\uc778\uc73c\ub85c \uce58\uc720\ub418\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc124\uba85\uc740 \ubaa8\ub450 \uc633\ub2e4. \ub2e4\ub9cc \u2462\ubb34\ud6a8\ud589\uc704\uc758 \ucd94\uc778(\uc81c139\uc870)\uc740 \uc6d0\uce59\uc801\uc73c\ub85c \ud6a8\ub825\uc774 \uc5c6\uace0, \ub2f9\uc0ac\uc790\uac00 \ubb34\ud6a8\uc784\uc744 \uc54c\uace0 \ucd94\uc778\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \uae30\uc874 \ud589\uc704\ub97c \uc18c\uae09\uc801\uc73c\ub85c \uc720\ud6a8\ud654\ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub77c "\uc0c8\ub85c\uc6b4 \ubc95\ub960\ud589\uc704"\ub85c\uc11c \uadf8\ub54c\ubd80\ud130 \ud6a8\ub825\uc744 \uac00\uc9c0\ubbc0\ub85c \uc633\uc9c0 \uc54a\ub2e4.',B.aBo,B.WE,null)
B.a_2=s(["\ubbf8\uc131\ub144\uc790\ub294 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758\ub97c \uc5bb\uc5b4 \ubc95\ub960\ud589\uc704\ub97c \ud560 \uc218 \uc788\ub2e4","\ubbf8\uc131\ub144\uc790\ub294 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ub2e8\ub3c5\uc73c\ub85c \ubc95\ub960\ud589\uc704\ub97c \ud560 \uc218 \uc5c6\ub2e4","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704\ub294 \ud56d\uc0c1 \ubb34\ud6a8\uc774\ub2e4","\ubbf8\uc131\ub144\uc790\ub294 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758 \uc5c6\uc774\ub3c4 \ubaa8\ub4e0 \ubc95\ub960\ud589\uc704\ub97c \uc790\uc720\ub86d\uac8c \ud560 \uc218 \uc788\ub2e4"],t.s)
B.bcL=s(["\ubbf8\uc131\ub144\uc790\ub294 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758\ub97c \uc5bb\uc5b4 \ubc95\ub960\ud589\uc704\ub97c \ud560 \uc218 \uc788\ub2e4"],t.s)
B.af7=s(["\ubbf8\uc131\ub144\uc790 \ubc95\ub960\ud589\uc704\uc758 \uc6d0\uce59(\uc81c5\uc870 \uc81c1\ud56d)"],t.s)
B.byl=new A.a("gen_cl_minor_1","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704\uc5d0 \uad00\ud55c \uc6d0\uce59\uc801 \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.a_2,0,"\ubbfc\ubc95 \uc81c5\uc870 \uc81c1\ud56d\uc740 \ubbf8\uc131\ub144\uc790\uac00 \ubc95\ub960\ud589\uc704\ub97c \ud558\ub294 \ub370\uc5d0\ub294 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758\ub97c \uc5bb\uc5b4\uc57c \ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ub3d9\uc758\ub97c \uc5bb\uc73c\uba74 \ubbf8\uc131\ub144\uc790\ub3c4 \uc720\ud6a8\ud558\uac8c \ubc95\ub960\ud589\uc704\ub97c \ud560 \uc218 \uc788\ub2e4.",B.bcL,B.af7,null)
B.az8=s(["\ucde8\uc18c\ud560 \uc218 \uc788\ub2e4","\ubb34\ud6a8\uc774\ub2e4","\ud56d\uc0c1 \uc720\ud6a8\ud558\ub2e4","\ud6a8\ub825\uc774 \uc815\uc9c0\ub41c\ub2e4"],t.s)
B.a4Z=s(["\ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758 \uc5c6\uc774 \ubbf8\uc131\ub144\uc790\uac00 \ud55c \ubc95\ub960\ud589\uc704\ub294 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.bhv=s(["\ub3d9\uc758 \uc5c6\ub294 \ubbf8\uc131\ub144\uc790 \ud589\uc704\uc758 \ud6a8\ub825(\uc81c5\uc870 \uc81c2\ud56d)"],t.s)
B.bzc=new A.a("gen_cl_minor_2","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\ubbf8\uc131\ub144\uc790\uac00 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758 \uc5c6\uc774 \ud55c \ubc95\ub960\ud589\uc704\uc758 \ud6a8\ub825\uc740?",B.az8,0,"\ubbfc\ubc95 \uc81c5\uc870 \uc81c2\ud56d\uc5d0 \ub530\ub77c \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758 \uc5c6\uc774 \ubbf8\uc131\ub144\uc790\uac00 \ud55c \ubc95\ub960\ud589\uc704\ub294 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4. \ucc98\uc74c\ubd80\ud130 \ud6a8\ub825\uc774 \uc5c6\ub294 \ubb34\ud6a8\uac00 \uc544\ub2c8\ub77c, \ucde8\uc18c\uad8c\uc790\uac00 \ucde8\uc18c\ud558\uae30 \uc804\uae4c\uc9c0\ub294 \uc720\ud6a8\ud55c \uac83\uc73c\ub85c \ucde8\uae09\ub41c\ub2e4.",B.a4Z,B.bhv,null)
B.a4v=s(["\ub2e8\uc21c\ud788 \uad8c\ub9ac\ub9cc\uc744 \uc5bb\uac70\ub098 \uc758\ubb34\ub9cc\uc744 \uba74\ud558\ub294 \ud589\uc704","\ubd80\ub3d9\uc0b0\uc744 \ub9e4\uc218\ud558\ub294 \ud589\uc704","\uae08\uc804\uc744 \ub300\ucc28(\ube4c\ub9ac\ub294)\ud558\ub294 \ud589\uc704","\ud0c0\uc778\uc758 \ucc44\ubb34\ub97c \ubcf4\uc99d\ud558\ub294 \ud589\uc704"],t.s)
B.b3d=s(["\ub2e8\uc21c\ud788 \uad8c\ub9ac\ub9cc\uc744 \uc5bb\uac70\ub098 \uc758\ubb34\ub9cc\uc744 \uba74\ud558\ub294 \ud589\uc704"],t.s)
B.Y0=s(["\ub3d9\uc758\ub97c \uc694\ud558\uc9c0 \uc54a\ub294 \ud589\uc704(\uc81c5\uc870 \uc81c1\ud56d \ub2e8\uc11c)"],t.s)
B.bqy=new A.a("gen_cl_minor_3","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758 \uc5c6\uc774\ub3c4 \ubbf8\uc131\ub144\uc790\uac00 \ub2e8\ub3c5\uc73c\ub85c \uc720\ud6a8\ud558\uac8c \ud560 \uc218 \uc788\ub294 \ud589\uc704\ub294?",B.a4v,0,"\ubbfc\ubc95 \uc81c5\uc870 \uc81c1\ud56d \ub2e8\uc11c\ub294 \ub2e8\uc21c\ud788 \uad8c\ub9ac\ub9cc\uc744 \uc5bb\uac70\ub098 \uc758\ubb34\ub9cc\uc744 \uba74\ud558\ub294 \ud589\uc704\ub294 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758 \uc5c6\uc774\ub3c4 \ubbf8\uc131\ub144\uc790\uac00 \ub2e8\ub3c5\uc73c\ub85c \ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc608\ucee8\ub300 \ub2e8\uc21c \uc99d\uc5ec\ub97c \ubc1b\ub294 \ud589\uc704\uac00 \ub300\ud45c\uc801\uc774\ub2e4. \ubc18\uba74 \ubd80\ub3d9\uc0b0 \ub9e4\uc218, \uae08\uc804 \ub300\ucc28, \ubcf4\uc99d\ud589\uc704\ub294 \uc758\ubb34\ub97c \ubc1c\uc0dd\uc2dc\ud0a4\ubbc0\ub85c \ub3d9\uc758\uac00 \ud544\uc694\ud558\ub2e4.",B.b3d,B.Y0,null)
B.a3t=s(["\ubbf8\uc131\ub144\uc790\uac00 \uadf8 \uc7ac\uc0b0\uc5d0 \uad00\ud558\uc5ec\ub294 \uc790\uc720\ub86d\uac8c \ucc98\ubd84\ud560 \uc218 \uc788\ub2e4","\ucc98\ubd84\uc744 \ud5c8\ub77d\ubc1b\uc544\ub3c4 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \uac1c\ubcc4 \ub3d9\uc758\uac00 \ub9e4\ubc88 \ud544\uc694\ud558\ub2e4","\ucc98\ubd84\uc774 \ud5c8\ub77d\ub41c \uc7ac\uc0b0\uc774\ub77c\ub3c4 \ucc98\ubd84\ud589\uc704\ub294 \ud56d\uc0c1 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4","\ucc98\ubd84 \ud5c8\ub77d\uc740 \uc5b8\uc81c\ub098 \uc11c\uba74\uc73c\ub85c\ub9cc \uac00\ub2a5\ud558\ub2e4"],t.s)
B.b8N=s(["\uadf8 \ubc94\uc704 \ub0b4\uc5d0\uc11c \uc790\uc720\ub86d\uac8c \ucc98\ubd84\ud560 \uc218 \uc788\ub2e4"],t.s)
B.a1H=s(["\ucc98\ubd84\uc774 \ud5c8\ub77d\ub41c \uc7ac\uc0b0\uc758 \ucc98\ubd84(\uc81c6\uc870)"],t.s)
B.bNA=new A.a("gen_cl_minor_4","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\ubc95\uc815\ub300\ub9ac\uc778\uc774 \ubbf8\uc131\ub144\uc790\uc5d0\uac8c \ucc98\ubd84\uc744 \ud5c8\ub77d\ud55c \uc7ac\uc0b0\uc758 \ucc98\ubd84\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.a3t,0,"\ubbfc\ubc95 \uc81c6\uc870\ub294 \ubc95\uc815\ub300\ub9ac\uc778\uc774 \ubc94\uc704\ub97c \uc815\ud558\uc5ec \ucc98\ubd84\uc744 \ud5c8\ub77d\ud55c \uc7ac\uc0b0\uc5d0 \ub300\ud574\uc11c\ub294 \ubbf8\uc131\ub144\uc790\uac00 \uadf8 \ubc94\uc704 \ub0b4\uc5d0\uc11c \uc790\uc720\ub86d\uac8c \ucc98\ubd84\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc608\ucee8\ub300 \uc6a9\ub3c8\uc73c\ub85c \uc900 \ub3c8\uc744 \uc0ac\uc6a9\ud558\ub294 \uacbd\uc6b0\uac00 \ub300\ud45c\uc801\uc774\uba70, \uc774 \uacbd\uc6b0 \ub9e4\ubc88 \uac1c\ubcc4 \ub3d9\uc758\ub97c \ub2e4\uc2dc \ubc1b\uc744 \ud544\uc694\uac00 \uc5c6\ub2e4.",B.b8N,B.a1H,null)
B.Tu=s(["\uadf8 \uc601\uc5c5\uc5d0 \uad00\ud558\uc5ec\ub294 \uc131\ub144\uc790\uc640 \ub3d9\uc77c\ud55c \ud589\uc704\ub2a5\ub825\uc744 \uac00\uc9c4\ub2e4","\ud5c8\ub77d\ubc1b\uc740 \uc601\uc5c5\uc774\ub77c\ub3c4 \ub9e4 \uac70\ub798\ub9c8\ub2e4 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758\uac00 \ud544\uc694\ud558\ub2e4","\uc601\uc5c5\uc758 \ud5c8\ub77d\uc740 \ubbf8\uc131\ub144\uc790\uc758 \ud589\uc704\ub2a5\ub825\uc5d0 \uc544\ubb34\ub7f0 \uc601\ud5a5\uc744 \ubbf8\uce58\uc9c0 \uc54a\ub294\ub2e4","\uc601\uc5c5 \ud5c8\ub77d\uc740 \ucde8\uc18c\ud560 \uc218 \uc5c6\ub294 \ud655\uc815\uc801 \ud6a8\ub825\uc744 \uac00\uc9c4\ub2e4"],t.s)
B.aQZ=s(["\uadf8 \uc601\uc5c5\uc5d0 \uad00\ud558\uc5ec\ub294 \uc131\ub144\uc790\uc640 \ub3d9\uc77c\ud55c \ud589\uc704\ub2a5\ub825\uc744 \uac00\uc9c4\ub2e4"],t.s)
B.aV3=s(["\uc601\uc5c5\uc758 \ud5c8\ub77d\uacfc \ud589\uc704\ub2a5\ub825(\uc81c8\uc870)"],t.s)
B.bu6=new A.a("gen_cl_minor_5","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\ubc95\uc815\ub300\ub9ac\uc778\uc73c\ub85c\ubd80\ud130 \ud2b9\uc815 \uc601\uc5c5\uc744 \ud5c8\ub77d\ubc1b\uc740 \ubbf8\uc131\ub144\uc790\uc758 \uc9c0\uc704\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.Tu,0,"\ubbfc\ubc95 \uc81c8\uc870 \uc81c1\ud56d\uc740 \ubc95\uc815\ub300\ub9ac\uc778\uc73c\ub85c\ubd80\ud130 \ud2b9\uc815 \uc601\uc5c5\uc744 \ud5c8\ub77d\ubc1b\uc740 \ubbf8\uc131\ub144\uc790\ub294 \uadf8 \uc601\uc5c5\uc5d0 \uad00\ud558\uc5ec \uc131\ub144\uc790\uc640 \ub3d9\uc77c\ud55c \ud589\uc704\ub2a5\ub825\uc774 \uc788\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ub2e4\ub9cc \uc81c2\ud56d\uc5d0 \ub530\ub77c \ubc95\uc815\ub300\ub9ac\uc778\uc740 \uadf8 \uc601\uc5c5\uc5d0 \ubd80\uc801\ub2f9\ud568\uc774 \ubc1c\uacac\ub418\uba74 \uadf8 \ud5c8\ub77d\uc744 \ucde8\uc18c\ud558\uac70\ub098 \uc81c\ud55c\ud560 \uc218 \uc788\ub2e4.",B.aQZ,B.aV3,null)
B.a2E=s(["\ub300\ub9ac\ud589\uc704\uc758 \ud6a8\uacfc\ub294 \ubcf8\uc778\uc5d0\uac8c \uadc0\uc18d\ub418\ubbc0\ub85c \ub300\ub9ac\uc778\uc740 \ud589\uc704\ub2a5\ub825\uc744 \uc694\ud558\uc9c0 \uc54a\ub294\ub2e4","\ubbf8\uc131\ub144\uc790\ub294 \ub300\ub9ac\uc778\uc774 \ub420 \uc218 \uc5c6\ub2e4","\ubbf8\uc131\ub144\uc790\uac00 \ub300\ub9ac\uc778\uc73c\ub85c\uc11c \ud55c \ud589\uc704\ub294 \ud56d\uc0c1 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4","\ubbf8\uc131\ub144\uc790\uac00 \ub300\ub9ac\uc778\uc774 \ub418\ub824\uba74 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ubcc4\ub3c4 \ub3d9\uc758\uac00 \ud544\uc694\ud558\ub2e4"],t.s)
B.b8P=s(["\uc81c\ud55c\ub2a5\ub825\uc790\uc758 \ub300\ub9ac(\uc81c117\uc870)"],t.s)
B.bGK=new A.a("gen_cl_minor_6","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\ubbf8\uc131\ub144\uc790\uac00 \ub300\ub9ac\uc778\uc73c\ub85c\uc11c \ud55c \ubc95\ub960\ud589\uc704\uc758 \ud6a8\ub825\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.a2E,0,"\ubbfc\ubc95 \uc81c117\uc870\ub294 \ub300\ub9ac\uc778\uc740 \ud589\uc704\ub2a5\ub825\uc790\uc784\uc744 \uc694\ud558\uc9c0 \uc544\ub2c8\ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ub300\ub9ac\ud589\uc704\uc758 \ubc95\ub960\ud6a8\uacfc\ub294 \ub300\ub9ac\uc778\uc774 \uc544\ub2c8\ub77c \ubcf8\uc778\uc5d0\uac8c \uadc0\uc18d\ub418\ubbc0\ub85c, \ubbf8\uc131\ub144\uc790\ub3c4 \uc720\ud6a8\ud558\uac8c \ub300\ub9ac\uc778\uc774 \ub418\uc5b4 \ub300\ub9ac\ud589\uc704\ub97c \ud560 \uc218 \uc788\ub2e4.",B.tG,B.b8P,null)
B.a2W=s(["\ud63c\uc778\uc73c\ub85c \uc131\ub144\uc5d0 \uc774\ub978 \uac83\uc73c\ub85c \ubcf8\ub2e4(\uc131\ub144\uc758\uc81c)","\ud63c\uc778\ud574\ub3c4 \ubbf8\uc131\ub144\uc790\uc758 \ud589\uc704\ub2a5\ub825\uc5d0\ub294 \ubcc0\ud654\uac00 \uc5c6\ub2e4","\ud63c\uc778\ud55c \ubbf8\uc131\ub144\uc790\ub294 \uc5ec\uc804\ud788 \ubaa8\ub4e0 \ubc95\ub960\ud589\uc704\uc5d0 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758\uac00 \ud544\uc694\ud558\ub2e4","\ud63c\uc778\ud55c \ubbf8\uc131\ub144\uc790\ub294 \uc774\ud63c\ud558\uba74 \ub2e4\uc2dc \ubbf8\uc131\ub144\uc790 \uc9c0\uc704\ub85c \ubcf5\uadc0\ud560 \uc218 \uc5c6\ub2e4"],t.s)
B.Vf=s(["\ubbf8\uc131\ub144\uc790\uac00 \ud63c\uc778\uc744 \ud55c \ub54c\uc5d0\ub294 \uc131\ub144\uc790\ub85c \ubcf8\ub2e4"],t.s)
B.aj2=s(["\ud63c\uc778\uc5d0 \uc758\ud55c \uc131\ub144\uc758\uc81c(\uc81c826\uc870\uc7582)"],t.s)
B.bCs=new A.a("gen_cl_minor_7","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\ud63c\uc778\ud55c \ubbf8\uc131\ub144\uc790\uc758 \ud589\uc704\ub2a5\ub825\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.a2W,0,"\ubbfc\ubc95 \uc81c826\uc870\uc7582\ub294 \ubbf8\uc131\ub144\uc790\uac00 \ud63c\uc778\uc744 \ud55c \ub54c\uc5d0\ub294 \uc131\ub144\uc790\ub85c \ubcf8\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4(\uc131\ub144\uc758\uc81c). \uc774\uc5d0 \ub530\ub77c \ud63c\uc778\ud55c \ubbf8\uc131\ub144\uc790\ub294 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758 \uc5c6\uc774\ub3c4 \ub2e8\ub3c5\uc73c\ub85c \uc644\uc804\ud55c \ubc95\ub960\ud589\uc704\ub97c \ud560 \uc218 \uc788\uac8c \ub41c\ub2e4.",B.Vf,B.aj2,null)
B.bbw=s(["\ud615\uc0ac\ucc98\ubc8c\uad8c","\ub3d9\uc758\uad8c","\ub300\ub9ac\uad8c","\ucde8\uc18c\uad8c\xb7\ucd94\uc778\uad8c"],t.s)
B.a4_=s(["\ub3d9\uc758\uad8c(\uc81c5\uc870), \ub300\ub9ac\uad8c(\uc81c920\uc870 \ub4f1), \uadf8\ub9ac\uace0 \ub3d9\uc758 \uc5c6\uc774 \uc774\ub8e8\uc5b4\uc9c4 \ud589\uc704\uc5d0 \ub300\ud55c \ucde8\uc18c\uad8c\xb7\ucd94\uc778\uad8c"],t.s)
B.bbE=s(["\ubc95\uc815\ub300\ub9ac\uc778\uc758 \uad8c\ud55c \uc815\ub9ac"],t.s)
B.bof=new A.a("gen_cl_minor_8","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\ubc95\uc815\ub300\ub9ac\uc778\uc774 \ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704\uc5d0 \ub300\ud558\uc5ec \uac00\uc9c0\ub294 \uad8c\ud55c\uc5d0 \ud574\ub2f9\ud558\uc9c0 \uc54a\ub294 \uac83\uc740?",B.bbw,0,"\ubc95\uc815\ub300\ub9ac\uc778\uc740 \ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704\uc5d0 \ub300\ud574 \ub3d9\uc758\uad8c(\uc81c5\uc870), \ub300\ub9ac\uad8c(\uc81c920\uc870 \ub4f1), \uadf8\ub9ac\uace0 \ub3d9\uc758 \uc5c6\uc774 \uc774\ub8e8\uc5b4\uc9c4 \ud589\uc704\uc5d0 \ub300\ud55c \ucde8\uc18c\uad8c\xb7\ucd94\uc778\uad8c(\uc81c140\uc870, \uc81c143\uc870)\uc744 \uac00\uc9c4\ub2e4. \ud615\uc0ac\ucc98\ubc8c\uad8c\uc740 \ubbfc\ubc95\uc0c1 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \uad8c\ud55c\uc774 \uc544\ub2c8\ub2e4.",B.a4_,B.bbE,null)
B.abb=s(["\uc0c1\ub300\ubc29\uc740 \ubc95\uc815\ub300\ub9ac\uc778\uc5d0\uac8c \uc77c\uc815 \uae30\uac04 \ub0b4 \ucde8\uc18c \ub610\ub294 \ucd94\uc778 \uc5ec\ubd80\uc5d0 \ub300\ud55c \ud655\ub2f5\uc744 \ucd09\uad6c\ud560 \uc218 \uc788\ub2e4","\ud655\ub2f5\ucd09\uad6c\uad8c\uc740 \uc0c1\ub300\ubc29\uc774 \uc544\ub2c8\ub77c \uc81c\ud55c\ub2a5\ub825\uc790\ub9cc \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4","\ud655\ub2f5\ucd09\uad6c\uac00 \uc788\uc5b4\ub3c4 \ubc95\uc815\ub300\ub9ac\uc778\uc740 \uc751\ub2f5\ud560 \uc758\ubb34\uac00 \uc5c6\ub2e4","\ud655\ub2f5\ucd09\uad6c\uad8c\uc740 \ubbf8\uc131\ub144\uc790\uac00 \uc131\ub144\uc774 \ub418\uae30 \uc804\uc5d0\ub294 \ud589\uc0ac\ud560 \uc218 \uc5c6\ub2e4"],t.s)
B.aZ_=s(["\ubc95\uc815\ub300\ub9ac\uc778\uc5d0 \ub300\ud558\uc5ec 1\uac1c\uc6d4 \uc774\uc0c1\uc758 \uae30\uac04\uc744 \uc815\ud558\uc5ec \uadf8 \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ud589\uc704\ub97c \ucd94\uc778\ud560 \uac83\uc778\uc9c0 \uc5ec\ubd80\uc758 \ud655\ub2f5\uc744 \ucd09\uad6c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.a5w=s(["\ud655\ub2f5\ucd09\uad6c\uad8c(\uc81c15\uc870)"],t.s)
B.bEx=new A.a("gen_cl_minor_9","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\uc81c\ud55c\ub2a5\ub825\uc790\uc758 \uc0c1\ub300\ubc29\uc774 \uac00\uc9c0\ub294 \ud655\ub2f5\ucd09\uad6c\uad8c(\uc81c15\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.abb,0,"\ubbfc\ubc95 \uc81c15\uc870\ub294 \uc81c\ud55c\ub2a5\ub825\uc790\uc758 \uc0c1\ub300\ubc29\uc774 \ubc95\uc815\ub300\ub9ac\uc778\uc5d0 \ub300\ud558\uc5ec 1\uac1c\uc6d4 \uc774\uc0c1\uc758 \uae30\uac04\uc744 \uc815\ud558\uc5ec \uadf8 \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ud589\uc704\ub97c \ucd94\uc778\ud560 \uac83\uc778\uc9c0 \uc5ec\ubd80\uc758 \ud655\ub2f5\uc744 \ucd09\uad6c\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc774\ub294 \ubd88\uc548\uc815\ud55c \ubc95\ub960\uad00\uacc4\ub97c \uc870\uc18d\ud788 \ud655\uc815\uc2dc\ud0a4\uae30 \uc704\ud55c \uc0c1\ub300\ubc29 \ubcf4\ud638 \uc81c\ub3c4\uc774\ub2e4.",B.aZ_,B.a5w,null)
B.afI=s(["\uadf8 \ud589\uc704\ub97c \ucd94\uc778\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4","\uadf8 \ud589\uc704\ub97c \ucde8\uc18c\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4","\ubc95\ub960\ud589\uc704\ub294 \ucc98\uc74c\ubd80\ud130 \ubb34\ud6a8\ub85c \ud655\uc815\ub41c\ub2e4","\uc544\ubb34\ub7f0 \ud6a8\uacfc\uac00 \ubc1c\uc0dd\ud558\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.b4t=s(["\uadf8 \uae30\uac04 \ub0b4\uc5d0 \ud655\ub2f5\uc744 \ubc1c\ud558\uc9c0 \uc544\ub2c8\ud558\uba74 \uadf8 \ud589\uc704\ub97c \ucd94\uc778\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4"],t.s)
B.atP=s(["\ud655\ub2f5\ucd09\uad6c \ubb34\uc751\ub2f5\uc758 \ud6a8\uacfc"],t.s)
B.bJa=new A.a("gen_cl_minor_10","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\ud655\ub2f5\ucd09\uad6c\ub97c \ubc1b\uc740 \ubc95\uc815\ub300\ub9ac\uc778\uc774 \uadf8 \uae30\uac04 \ub0b4\uc5d0 \ud655\ub2f5\uc744 \ubc1c\ud558\uc9c0 \uc54a\uc740 \uacbd\uc6b0\uc758 \ud6a8\uacfc\ub294?",B.afI,0,"\ubbfc\ubc95 \uc81c15\uc870 \uc81c1\ud56d\uc5d0 \ub530\ub77c \ubc95\uc815\ub300\ub9ac\uc778\uc774 \ud655\ub2f5\ucd09\uad6c\ub97c \ubc1b\uace0\ub3c4 \uadf8 \uae30\uac04 \ub0b4\uc5d0 \ud655\ub2f5\uc744 \ubc1c\ud558\uc9c0 \uc544\ub2c8\ud558\uba74 \uadf8 \ud589\uc704\ub97c \ucd94\uc778\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4. \uc774\ub294 \ubc95\ub960\uad00\uacc4\ub97c \uc2e0\uc18d\ud788 \uc720\ud6a8\ub85c \ud655\uc815\uc2dc\ucf1c \uc0c1\ub300\ubc29\uc744 \ubcf4\ud638\ud558\uae30 \uc704\ud55c \uaddc\uc815\uc774\ub2e4.",B.b4t,B.atP,null)
B.akD=s(["\uc81c\ud55c\ub2a5\ub825\uc790\uc640 \ub9fa\uc740 \uacc4\uc57d\uc744 \uc120\uc758\uc758 \uc0c1\ub300\ubc29\uc774 \ucd94\uc778\uc774 \uc788\uae30 \uc804\uae4c\uc9c0 \ucca0\ud68c\ud560 \uc218 \uc788\ub2e4","\uc0c1\ub300\ubc29\uc740 \uc5b4\ub5a4 \uacbd\uc6b0\uc5d0\ub3c4 \uacc4\uc57d\uc744 \ucca0\ud68c\ud560 \uc218 \uc5c6\ub2e4","\ucca0\ud68c\uad8c\uc740 \uc0c1\ub300\ubc29\uc758 \uc120\uc758\xb7\uc545\uc758\ub97c \ubd88\ubb38\ud558\uace0 \uc778\uc815\ub41c\ub2e4","\ucca0\ud68c\uad8c\uc740 \ubbf8\uc131\ub144\uc790\uc5d0\uac8c\ub9cc \uc778\uc815\ub418\ub294 \uad8c\ub9ac\uc774\ub2e4"],t.s)
B.aKc=s(["\uc120\uc758\uc758 \uc0c1\ub300\ubc29\uc774 \ucd94\uc778\uc774 \uc788\uae30 \uc804\uae4c\uc9c0 \ucca0\ud68c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.adP=s(["\uc0c1\ub300\ubc29\uc758 \ucca0\ud68c\uad8c(\uc81c16\uc870)"],t.s)
B.bQv=new A.a("gen_cl_minor_11","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\uc0c1\ub300\ubc29\uc758 \ucca0\ud68c\uad8c(\uc81c16\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.akD,0,"\ubbfc\ubc95 \uc81c16\uc870 \uc81c1\ud56d\uc740 \uc81c\ud55c\ub2a5\ub825\uc790\uc640 \ub9fa\uc740 \uacc4\uc57d\uc740 \ucd94\uc778\uc774 \uc788\uae30 \uc804\uae4c\uc9c0 \uc0c1\ub300\ubc29\uc774 \uc774\ub97c \ucca0\ud68c\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud558\ub418, \uacc4\uc57d \ub2f9\uc2dc \uc81c\ud55c\ub2a5\ub825\uc790\uc784\uc744 \uc54c\uc558\uc744 \uacbd\uc6b0(\uc545\uc758\uc758 \uc0c1\ub300\ubc29)\uc5d0\ub294 \uc774\ub7ec\ud55c \ucca0\ud68c\uad8c\uc774 \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4.",B.aKc,B.adP,null)
B.b4z=s(["\uc81c\ud55c\ub2a5\ub825\uc790\uc758 \ub2e8\ub3c5\ud589\uc704","\uc81c\ud55c\ub2a5\ub825\uc790\uc640 \ub9fa\uc740 \uc30d\ubc29 \uacc4\uc57d","\ubc95\uc815\ub300\ub9ac\uc778\uc774 \ub3d9\uc758\ud55c \ud589\uc704","\uc601\uc5c5\uc774 \ud5c8\ub77d\ub41c \ubc94\uc704\uc758 \ud589\uc704"],t.s)
B.Y2=s(["\uc81c\ud55c\ub2a5\ub825\uc790\uc758 \ub2e8\ub3c5\ud589\uc704\uc5d0 \ub300\ud558\uc5ec\ub294 \uc120\uc758\uc758 \uc0c1\ub300\ubc29\uc774 \uc774\ub97c \uac70\uc808\ud560 \uc218 \uc788\ub2e4"],t.s)
B.UN=s(["\uc0c1\ub300\ubc29\uc758 \uac70\uc808\uad8c(\uc81c16\uc870 \uc81c2\ud56d)"],t.s)
B.bFZ=new A.a("gen_cl_minor_12","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\uc0c1\ub300\ubc29\uc758 \uac70\uc808\uad8c(\uc81c16\uc870 \uc81c2\ud56d)\uc774 \uc778\uc815\ub418\ub294 \uacbd\uc6b0\ub294?",B.b4z,0,"\ubbfc\ubc95 \uc81c16\uc870 \uc81c2\ud56d\uc740 \uc81c\ud55c\ub2a5\ub825\uc790\uc758 \ub2e8\ub3c5\ud589\uc704\uc5d0 \ub300\ud558\uc5ec\ub294 \uc120\uc758\uc758 \uc0c1\ub300\ubc29\uc774 \uc774\ub97c \uac70\uc808\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uacc4\uc57d\uacfc \ub2ec\ub9ac \ub2e8\ub3c5\ud589\uc704\ub294 \uc0c1\ub300\ubc29\uc758 \uc2b9\ub099 \uc5c6\uc774 \uc77c\ubc29\uc801\uc73c\ub85c \uc774\ub8e8\uc5b4\uc9c0\ubbc0\ub85c, \uadf8 \ud6a8\ub825\uc774 \ubd88\ud655\uc2e4\ud55c \uc0c1\ud0dc\uc5d0\uc11c \uc0c1\ub300\ubc29\uc744 \ubcf4\ud638\ud558\uae30 \uc704\ud574 \uac70\uc808\uad8c\uc744 \uc778\uc815\ud55c \uac83\uc774\ub2e4.",B.Y2,B.UN,null)
B.aPp=s(["\uc81c\ud55c\ub2a5\ub825\uc790\ub294 \uadf8 \ud589\uc704\ub97c \ucde8\uc18c\ud560 \uc218 \uc5c6\ub2e4","\ucde8\uc18c\uad8c \ud589\uc0ac\uae30\uac04\uc774 \uc624\ud788\ub824 \uc5f0\uc7a5\ub41c\ub2e4","\ubc95\uc815\ub300\ub9ac\uc778\uc758 \ucde8\uc18c\uad8c\ub9cc \uc778\uc815\ub418\uace0 \uc81c\ud55c\ub2a5\ub825\uc790 \ubcf8\uc778\uc758 \ucde8\uc18c\uad8c\uc740 \uc18c\uba78\ud558\uc9c0 \uc54a\ub294\ub2e4","\uc0c1\ub300\ubc29\uc758 \uc120\uc758\xb7\uc545\uc758\uc640 \uad00\uacc4\uc5c6\uc774 \ud56d\uc0c1 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.aCv=s(["\uc81c\ud55c\ub2a5\ub825\uc790\ub294 \uadf8 \ud589\uc704\ub97c \ucde8\uc18c\ud560 \uc218 \uc5c6\ub2e4"],t.s)
B.aMl=s(["\uc81c\ud55c\ub2a5\ub825\uc790\uc758 \uc18d\uc784\uc218\uc640 \ucde8\uc18c\uad8c \ubc30\uc81c(\uc81c17\uc870)"],t.s)
B.bwo=new A.a("gen_cl_minor_13","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\uc81c\ud55c\ub2a5\ub825\uc790\uc758 \uc18d\uc784\uc218(\uc81c17\uc870)\ub85c \uc0c1\ub300\ubc29\uc774 \ub2a5\ub825\uc790\ub85c \ubbff\uac8c \ub41c \uacbd\uc6b0\uc758 \ud6a8\uacfc\ub294?",B.aPp,0,"\ubbfc\ubc95 \uc81c17\uc870\ub294 \uc81c\ud55c\ub2a5\ub825\uc790\uac00 \uc18d\uc784\uc218\ub85c\uc368 \uc790\uae30\ub97c \ub2a5\ub825\uc790\ub85c \ubbff\uac8c \ud558\uac70\ub098 \ubbf8\uc131\ub144\uc790\xb7\ud53c\ud55c\uc815\ud6c4\uacac\uc778\uc774 \uc18d\uc784\uc218\ub85c\uc368 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758\uac00 \uc788\ub294 \uac83\uc73c\ub85c \ubbff\uac8c \ud55c \uacbd\uc6b0\uc5d0\ub294 \uadf8 \ud589\uc704\ub97c \ucde8\uc18c\ud560 \uc218 \uc5c6\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc774\ub294 \uc0c1\ub300\ubc29\uc744 \uae30\ub9dd\ud55c \uc81c\ud55c\ub2a5\ub825\uc790\ub97c \ub354 \uc774\uc0c1 \ubcf4\ud638\ud560 \ud544\uc694\uac00 \uc5c6\ub2e4\ub294 \ucde8\uc9c0\uc774\ub2e4.",B.aCv,B.aMl,null)
B.b20=s(["\uc801\uadf9\uc801\uc73c\ub85c \uc0c1\ub300\ubc29\uc744 \uc18d\uc774\ub824\ub294 \uc220\ucc45\uc744 \uc0ac\uc6a9\ud55c \uacbd\uc6b0\uc5d0 \ud55c\ud558\uc5ec \uc778\uc815\ub418\uace0, \ub2e8\uc21c\ud788 \uc131\ub144\uc790\ub77c\uace0 \ub9d0\ud55c \uac83\ub9cc\uc73c\ub85c\ub294 \ubd80\uc871\ud558\ub2e4\ub294 \ucde8\uc9c0\ub85c \uc5c4\uaca9\ud558\uac8c \ud574\uc11d\ub41c\ub2e4","\ubbf8\uc131\ub144\uc790\ub77c\ub294 \uc0ac\uc2e4\uc744 \ubc1d\ud788\uc9c0 \uc54a\uc740 \ubaa8\ub4e0 \uacbd\uc6b0\uc5d0 \uc18d\uc784\uc218\uac00 \uc778\uc815\ub41c\ub2e4","\uc18d\uc784\uc218 \uc5ec\ubd80\ub294 \ubb38\uc81c\ub418\uc9c0 \uc54a\uace0 \uacb0\uacfc\ub9cc \uc911\uc694\ud558\ub2e4","\uc18d\uc784\uc218\ub294 \ubc95\uc815\ub300\ub9ac\uc778\uc5d0\uac8c\ub9cc \uc801\uc6a9\ub418\ub294 \uac1c\ub150\uc774\ub2e4"],t.s)
B.avM=s(["\uc801\uadf9\uc801\uc73c\ub85c \uc0c1\ub300\ubc29\uc744 \uc18d\uc774\ub824\ub294 \uc220\ucc45\uc744 \uc0ac\uc6a9\ud55c \uacbd\uc6b0\uc5d0 \ud55c\ud558\uc5ec \uc778\uc815\ub418\uace0"],t.s)
B.b04=s(["\uc18d\uc784\uc218\uc758 \ud310\ub840\uc0c1 \ud574\uc11d"],t.s)
B.bFc=new A.a("gen_cl_minor_14","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,'\uc81c17\uc870\uc758 "\uc18d\uc784\uc218"\uc5d0 \uad00\ud55c \ud310\ub840\uc758 \ud0dc\ub3c4\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?',B.b20,0,'\ud310\ub840\ub294 \uc81c17\uc870\uc758 "\uc18d\uc784\uc218"\ub97c \uc81c\ud55c\ub2a5\ub825\uc790 \ubcf4\ud638\uc758 \uc608\uc678 \uaddc\uc815\uc774\ub77c\ub294 \uc810\uc5d0\uc11c \uc5c4\uaca9\ud558\uac8c \ud574\uc11d\ud558\uc5ec, \uc801\uadf9\uc801\uc73c\ub85c \uae30\ub9dd\uc218\ub2e8\uc744 \uc0ac\uc6a9\ud55c \uacbd\uc6b0\uc5d0 \ud55c\ud558\uc5ec \uc778\uc815\ud558\uace0, \ub2e8\uc21c\ud788 \uc790\uc2e0\uc774 \uc131\ub144\uc790\ub77c\uace0 \uc5b8\uae09\ud558\uac70\ub098 \uce68\ubb35\ud55c \uac83\ub9cc\uc73c\ub85c\ub294 \uc18d\uc784\uc218\uc5d0 \ud574\ub2f9\ud558\uc9c0 \uc54a\ub294\ub2e4\uace0 \ubcf8\ub2e4.',B.avM,B.b04,null)
B.bco=s([u.hz,"\ucde8\uc18c\uad8c \ud589\uc0ac\ub294 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758\uac00 \ud56d\uc0c1 \ud544\uc694\ud558\uae30 \ub54c\ubb38\uc774\ub2e4","\ucde8\uc18c\uad8c \ud589\uc0ac\ub294 \ubc95\ub960\ud589\uc704\uc5d0 \ud574\ub2f9\ud558\uc9c0 \uc54a\uae30 \ub54c\ubb38\uc5d0 \ub2a5\ub825\uc758 \ubb38\uc81c\uac00 \uc544\ub2c8\ub2e4","\ubbfc\ubc95\uc774 \uba85\uc2dc\uc801\uc73c\ub85c \uc608\uc678\ub97c \ub450\uc9c0 \uc54a\uc544 \ud574\uc11d\uc0c1 \uc778\uc815\ub420 \ubfd0\uc774\ub2e4"],t.s)
B.auG=s([u.hz],t.s)
B.asC=s(["\ubbf8\uc131\ub144\uc790\uc758 \ucde8\uc18c\uad8c \ub2e8\ub3c5 \ud589\uc0ac \uadfc\uac70"],t.s)
B.bLS=new A.a("gen_cl_minor_15","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\ubbf8\uc131\ub144\uc790 \ubcf8\uc778\uc774 \uc790\uc2e0\uc758 \ubc95\ub960\ud589\uc704\uc5d0 \ub300\ud55c \ucde8\uc18c\uad8c\uc744 \ub2e8\ub3c5\uc73c\ub85c \ud589\uc0ac\ud560 \uc218 \uc788\ub294 \uc774\uc720\ub294?",B.bco,0,"\ucde8\uc18c\ub294 \uc81c\ud55c\ub2a5\ub825\uc790\uc5d0\uac8c \ubd88\ub9ac\ud55c \ubc95\ub960\ud589\uc704\ub97c \ubb34\ud6a8\ud654\ud558\uc5ec \uadf8\ub97c \ubcf4\ud638\ud558\ub294 \ubc29\ud5a5\uc758 \ud589\uc704\uc774\ubbc0\ub85c, \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758\ub97c \uc694\uad6c\ud560 \uc774\uc720\uac00 \uc5c6\ub2e4. \uc774\uc5d0 \ub530\ub77c \ubbfc\ubc95 \uc81c140\uc870\ub294 \uc81c\ud55c\ub2a5\ub825\uc790\ub97c \ucde8\uc18c\uad8c\uc790\ub85c \uba85\uc2dc\ud558\uc5ec \ubcf8\uc778\uc774 \ub2e8\ub3c5\uc73c\ub85c \ucde8\uc18c\uad8c\uc744 \ud589\uc0ac\ud560 \uc218 \uc788\ub3c4\ub85d \ud55c\ub2e4.",B.auG,B.asC,null)
B.acB=s(["\ubc1b\uc740 \uc774\uc775\uc774 \ud604\uc874\ud558\ub294 \ud55c\ub3c4\uc5d0\uc11c\ub9cc \ubc18\ud658\ud558\uba74 \ub41c\ub2e4","\ubc1b\uc740 \uc774\uc775 \uc804\ubd80\ub97c \ubc18\ud658\ud558\uc5ec\uc57c \ud55c\ub2e4","\ubc18\ud658\uc758\ubb34\uac00 \uc804\ud600 \uc5c6\ub2e4","\ubc95\uc815\ub300\ub9ac\uc778\uc774 \ub300\uc2e0 \uc804\uc561\uc744 \ubc30\uc0c1\ud574\uc57c \ud55c\ub2e4"],t.s)
B.bh1=s(["\ubc1b\uc740 \uc774\uc775\uc774 \ud604\uc874\ud558\ub294 \ud55c\ub3c4\uc5d0\uc11c\ub9cc \ubc18\ud658\ud558\uba74 \ub41c\ub2e4"],t.s)
B.aVf=s(["\uc81c\ud55c\ub2a5\ub825\uc790\uc758 \ubc18\ud658\uc758\ubb34 \ubc94\uc704(\uc81c141\uc870 \ub2e8\uc11c)"],t.s)
B.bM_=new A.a("gen_cl_minor_16","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\ubbf8\uc131\ub144\uc790\uac00 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758 \uc5c6\uc774 \ub9e4\ub9e4\uacc4\uc57d\uc744 \uccb4\uacb0\ud55c \ud6c4 \uc774\ub97c \ucde8\uc18c\ud55c \uacbd\uc6b0, \ubbf8\uc131\ub144\uc790\uc758 \ubc18\ud658\uc758\ubb34 \ubc94\uc704\ub294?",B.acB,0,"\uc81c141\uc870 \ub2e8\uc11c\uc5d0 \ub530\ub77c \uc81c\ud55c\ub2a5\ub825\uc790\ub294 \uadf8 \ud589\uc704\ub85c \uc778\ud558\uc5ec \ubc1b\uc740 \uc774\uc775\uc774 \ud604\uc874\ud558\ub294 \ud55c\ub3c4\uc5d0\uc11c \ubc18\ud658\ud560 \ucc45\uc784\uc774 \uc788\ub2e4. \uc608\ucee8\ub300 \ub9e4\ub9e4\ub300\uae08\uc744 \ubc1b\uc544 \uc774\ubbf8 \uc18c\ube44\ud574\ubc84\ub838\ub2e4\uba74 \uadf8 \uc18c\ube44\ud55c \ubd80\ubd84\uc740 \ubc18\ud658\uc758\ubb34\uc5d0\uc11c \uc81c\uc678\ub420 \uc218 \uc788\ub2e4.",B.bh1,B.aVf,null)
B.aA3=s(["\ubbf8\uc131\ub144\uc790\ub294 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758\ub97c \uc5bb\uc73c\uba74 \uc720\ud6a8\ud558\uac8c \ubc95\ub960\ud589\uc704\ub97c \ud560 \uc218 \uc788\uc73c\ub098, \ud53c\uc131\ub144\ud6c4\uacac\uc778\uc758 \ud589\uc704\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \ub3d9\uc758 \uc5ec\ubd80\uc640 \ubb34\uad00\ud558\uac8c \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4","\ub450 \uc81c\ub3c4\uc758 \ud589\uc704\ub2a5\ub825 \uc81c\ud55c \ubc29\uc2dd\uc740 \uc644\uc804\ud788 \ub3d9\uc77c\ud558\ub2e4","\ud53c\uc131\ub144\ud6c4\uacac\uc778\ub3c4 \ubbf8\uc131\ub144\uc790\uc640 \ub3d9\uc77c\ud558\uac8c \ub3d9\uc758\ub97c \uc5bb\uc73c\uba74 \uc720\ud6a8\ud55c \ubc95\ub960\ud589\uc704\ub97c \ud560 \uc218 \uc788\ub2e4","\ubbf8\uc131\ub144\uc790\ub294 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758\ub85c\ub3c4 \ubc95\ub960\ud589\uc704\ub97c \ud560 \uc218 \uc5c6\ub2e4"],t.s)
B.ajn=s(["\ud53c\uc131\ub144\ud6c4\uacac\uc778\uc758 \ud589\uc704\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \ub3d9\uc758 \uc5ec\ubd80\uc640 \ubb34\uad00\ud558\uac8c \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.VD=s(["\ubbf8\uc131\ub144\uc790\uc640 \ud53c\uc131\ub144\ud6c4\uacac\uc778\uc758 \ud589\uc704\ub2a5\ub825 \ube44\uad50"],t.s)
B.bwy=new A.a("gen_cl_minor_17","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\ubbf8\uc131\ub144\uc790\uc640 \uc131\ub144\ud6c4\uacac\uc744 \ubc1b\ub294 \ud53c\uc131\ub144\ud6c4\uacac\uc778\uc758 \ud589\uc704\ub2a5\ub825\uc744 \ube44\uad50\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aA3,0,"\ubbf8\uc131\ub144\uc790\ub294 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758\ub97c \uc5bb\uc73c\uba74 \uc720\ud6a8\ud558\uac8c \ubc95\ub960\ud589\uc704\ub97c \ud560 \uc218 \uc788\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub098(\uc81c5\uc870), \ud53c\uc131\ub144\ud6c4\uacac\uc778\uc758 \ubc95\ub960\ud589\uc704\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \ub3d9\uc758 \uc5ec\ubd80\ub97c \ubd88\ubb38\ud558\uace0 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4(\uc81c10\uc870 \uc81c1\ud56d). \ub2e4\ub9cc \uac00\uc815\ubc95\uc6d0\uc774 \ucde8\uc18c\ud560 \uc218 \uc5c6\ub294 \ubc95\ub960\ud589\uc704\uc758 \ubc94\uc704\ub97c \uc815\ud560 \uc218 \uc788\ub2e4\ub294 \uc810\uc5d0\uc11c \ucc28\uc774\uac00 \uc788\ub2e4.",B.ajn,B.VD,null)
B.aNB=s(["\uc0c1\ub300\ubc29\uc740 \ucde8\uc18c\uad8c\uc790\uac00 \uc544\ub2c8\ubbc0\ub85c \ucde8\uc18c\ud560 \uc218 \uc5c6\ub2e4","\uc0c1\ub300\ubc29\ub3c4 \ucde8\uc18c\uad8c\uc790\ub85c\uc11c \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4","\uc0c1\ub300\ubc29\uc740 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ud5c8\ub77d\uc744 \ubc1b\uc73c\uba74 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4","\uc0c1\ub300\ubc29\uc740 \ubc95\uc6d0\uc758 \ud5c8\uac00\ub97c \ubc1b\uc544 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.a04=s(["\ubc95\ub960\ud589\uc704\uc758 \uc0c1\ub300\ubc29\uc740 \ucde8\uc18c\uad8c\uc790\uac00 \uc544\ub2c8\ub2e4"],t.s)
