B.bMv=new A.a("gen_cl_minor_18","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\ubbf8\uc131\ub144\uc790\uac00 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758 \uc5c6\uc774 \uccb4\uacb0\ud55c \ubc95\ub960\ud589\uc704\ub97c \uc0c1\ub300\ubc29\uc774 \ucde8\uc18c\ud560 \uc218 \uc788\ub294\uac00?",B.aNB,0,"\ubbfc\ubc95 \uc81c140\uc870\uac00 \uc815\ud55c \ucde8\uc18c\uad8c\uc790\ub294 \uc81c\ud55c\ub2a5\ub825\uc790 \ubcf8\uc778, \uadf8\uc758 \ub300\ub9ac\uc778 \ub610\ub294 \uc2b9\uacc4\uc778\uc5d0 \ud55c\uc815\ub418\uba70, \ubc95\ub960\ud589\uc704\uc758 \uc0c1\ub300\ubc29\uc740 \ucde8\uc18c\uad8c\uc790\uac00 \uc544\ub2c8\ub2e4. \uc0c1\ub300\ubc29\uc740 \ub300\uc2e0 \ud655\ub2f5\ucd09\uad6c\uad8c(\uc81c15\uc870), \ucca0\ud68c\uad8c\xb7\uac70\uc808\uad8c(\uc81c16\uc870) \ub4f1\uc744 \ud1b5\ud574 \uc790\uc2e0\uc758 \uc9c0\uc704\ub97c \ubcf4\ud638\ubc1b\uc744 \uc218 \uc788\ub2e4.",B.a04,B.aJv,null)
B.bh3=s(["\uc6d0\uce59\uc801\uc73c\ub85c \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758\ub97c \uc5bb\uc5b4\uc57c \uc720\ud6a8\ud558\uac8c \uadfc\ub85c\uacc4\uc57d\uc744 \uccb4\uacb0\ud560 \uc218 \uc788\ub2e4","\ubbf8\uc131\ub144\uc790\ub294 \uadfc\ub85c\uacc4\uc57d\uc744 \uccb4\uacb0\ud560 \uc218 \uc5c6\ub2e4","\ubc95\uc815\ub300\ub9ac\uc778\uc774 \ubbf8\uc131\ub144\uc790\ub97c \ub300\ub9ac\ud558\uc5ec \uadfc\ub85c\uacc4\uc57d\uc744 \uccb4\uacb0\ud558\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub2e4","\ubbf8\uc131\ub144\uc790\uc758 \uadfc\ub85c\uacc4\uc57d\uc5d0\ub294 \ubbfc\ubc95\uc774 \uc804\ud600 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.b1L=s(["\uc6d0\uce59\uc801\uc73c\ub85c \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758\ub97c \uc5bb\uc5b4\uc57c \uc720\ud6a8\ud558\uac8c \uadfc\ub85c\uacc4\uc57d\uc744 \uccb4\uacb0\ud560 \uc218 \uc788\ub2e4"],t.s)
B.b2O=s(["\ubbf8\uc131\ub144\uc790\uc758 \uadfc\ub85c\uacc4\uc57d"],t.s)
B.bAb=new A.a("gen_cl_minor_19","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\ubbf8\uc131\ub144\uc790\uac00 \uadfc\ub85c\uacc4\uc57d\uc744 \uccb4\uacb0\ud558\ub294 \uacbd\uc6b0\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.bh3,0,'\uadfc\ub85c\uacc4\uc57d\uc740 \ubbf8\uc131\ub144\uc790\uc5d0\uac8c \uc758\ubb34\ub97c \ubc1c\uc0dd\uc2dc\ud0a4\ub294 \ubc95\ub960\ud589\uc704\uc774\ubbc0\ub85c \uc6d0\uce59\uc801\uc73c\ub85c \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758\ub97c \uc5bb\uc5b4\uc57c \uc720\ud6a8\ud558\uac8c \uccb4\uacb0\ud560 \uc218 \uc788\ub2e4(\ubbfc\ubc95 \uc81c5\uc870). \ucc38\uace0\ub85c \uadfc\ub85c\uae30\uc900\ubc95\uc740 \ubcc4\ub3c4\ub85c \ubc95\uc815\ub300\ub9ac\uc778\uc774 \ubbf8\uc131\ub144\uc790\ub97c "\ub300\ub9ac"\ud558\uc5ec \uadfc\ub85c\uacc4\uc57d\uc744 \uccb4\uacb0\ud558\uc9c0 \ubabb\ud558\ub3c4\ub85d \ud558\ub294 \ud2b9\uce59(\uce5c\uad8c\uc790 \ub300\ub9ac\uacc4\uc57d \uae08\uc9c0)\uc744 \ub450\uace0 \uc788\uc73c\ub098, \uc774\ub294 \ubbfc\ubc95\uc0c1 \ub3d9\uc758 \uc694\uac74\uacfc\ub294 \ubcc4\uac1c\uc758 \ub178\ub3d9\ubc95\uc801 \ubcf4\ud638 \uaddc\uc815\uc774\ub2e4.',B.b1L,B.b2O,null)
B.aFX=s([u.am,"\uc99d\uc5ec\ub97c \ubc1b\ub294 \uac83\ub3c4 \uc758\ubb34\ub97c \uc218\ubc18\ud558\ubbc0\ub85c \ubc18\ub4dc\uc2dc \ub3d9\uc758\uac00 \ud544\uc694\ud558\ub2e4","\ubbf8\uc131\ub144\uc790\ub294 \uc5b4\ub5a0\ud55c \uc99d\uc5ec\ub3c4 \ubc1b\uc744 \uc218 \uc5c6\ub2e4","\uc99d\uc5ec\uacc4\uc57d\uc740 \ud56d\uc0c1 \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\uc774\ub2e4"],t.s)
B.anH=s([u.am],t.s)
B.bdE=s(["\ub2e8\uc21c \uc99d\uc5ec\uc640 \ub3d9\uc758 \ubd88\uc694 \uc6d0\uce59"],t.s)
B.bLL=new A.a("gen_cl_minor_20","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\ubbf8\uc131\ub144\uc790\uc5d0\uac8c \uc7ac\uc0b0\uc744 \ubb34\uc0c1\uc73c\ub85c \uc99d\uc5ec\ud558\ub294 \uacc4\uc57d\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aFX,0,"\ubd80\ub2f4 \uc5c6\ub294 \ub2e8\uc21c \uc99d\uc5ec\ub97c \ubc1b\ub294 \uac83\uc740 \ubbf8\uc131\ub144\uc790\uac00 \uad8c\ub9ac\ub9cc\uc744 \uc5bb\uace0 \uc758\ubb34\ub294 \uc9c0\uc9c0 \uc54a\ub294 \ud589\uc704\uc774\ubbc0\ub85c, \uc81c5\uc870 \uc81c1\ud56d \ub2e8\uc11c\uc5d0 \ub530\ub77c \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758 \uc5c6\uc774\ub3c4 \ubbf8\uc131\ub144\uc790\uac00 \ub2e8\ub3c5\uc73c\ub85c \uc720\ud6a8\ud558\uac8c \ubc1b\uc744 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \ubd80\ub2f4\ubd80 \uc99d\uc5ec(\uc758\ubb34\uac00 \uc218\ubc18\ub418\ub294 \uc99d\uc5ec)\ub294 \uc758\ubb34\ub3c4 \ubc1c\uc0dd\uc2dc\ud0a4\ubbc0\ub85c \ub3d9\uc758\uac00 \ud544\uc694\ud558\ub2e4.",B.anH,B.bdE,null)
B.awF=s(["\uc0c1\uc18d\uc740 \ucc44\ubb34\ub3c4 \ud568\uaed8 \uc2b9\uacc4\ub420 \uc218 \uc788\uc5b4 \uc6d0\uce59\uc801\uc73c\ub85c \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758(\ub610\ub294 \ub300\ub9ac)\uac00 \ud544\uc694\ud558\ub2e4","\uc0c1\uc18d\uc740 \ud56d\uc0c1 \uad8c\ub9ac\ub9cc\uc744 \uc5bb\ub294 \ud589\uc704\uc774\ubbc0\ub85c \ub3d9\uc758\uac00 \ud544\uc694 \uc5c6\ub2e4","\ubbf8\uc131\ub144\uc790\ub294 \uc0c1\uc18d\uc778\uc774 \ub420 \uc218 \uc5c6\ub2e4","\uc0c1\uc18d\uc758 \ub2e8\uc21c\uc2b9\uc778\uc740 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758\uc640 \ubb34\uad00\ud558\uac8c \ud56d\uc0c1 \uc720\ud6a8\ud558\ub2e4"],t.s)
B.b3j=s(["\ucc44\ubb34\ub3c4 \ud568\uaed8 \uc2b9\uacc4\ub420 \uc218 \uc788\uc5b4 \uc6d0\uce59\uc801\uc73c\ub85c \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758(\ub610\ub294 \ub300\ub9ac)\uac00 \ud544\uc694\ud558\ub2e4"],t.s)
B.b9r=s(["\uc0c1\uc18d\uc758 \ub2e8\uc21c\uc2b9\uc778\uacfc \ub3d9\uc758 \uc694\uac74"],t.s)
B.bKQ=new A.a("gen_cl_minor_21","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\ubbf8\uc131\ub144\uc790\uac00 \uc0c1\uc18d\uc744 \ub2e8\uc21c\uc2b9\uc778\ud558\ub294 \ud589\uc704\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.awF,0,"\uc0c1\uc18d\uc758 \ub2e8\uc21c\uc2b9\uc778\uc740 \uc801\uadf9\uc7ac\uc0b0\ubfd0 \uc544\ub2c8\ub77c \uc18c\uadf9\uc7ac\uc0b0(\ucc44\ubb34)\uae4c\uc9c0 \ud3ec\uad04\uc801\uc73c\ub85c \uc2b9\uacc4\ud558\ub294 \ud589\uc704\uc5ec\uc11c \ub2e8\uc21c\ud788 \uad8c\ub9ac\ub9cc\uc744 \uc5bb\ub294 \ud589\uc704\ub85c \ubcfc \uc218 \uc5c6\uc73c\ubbc0\ub85c, \uc6d0\uce59\uc801\uc73c\ub85c \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758\ub97c \uc5bb\uac70\ub098 \ubc95\uc815\ub300\ub9ac\uc778\uc774 \ub300\ub9ac\ud558\uc5ec\uc57c \ud55c\ub2e4(\uc2e4\ubb34\uc0c1 \ub300\ub9ac\uac00 \uc774\ub8e8\uc5b4\uc9c0\ub294 \uacbd\uc6b0\uac00 \ub9ce\ub2e4).",B.b3j,B.b9r,null)
B.Sk=s(["\uadf8 \uc601\uc5c5\uc5d0 \ubbf8\uc131\ub144\uc790\uac00 \uac10\ub2f9\ud560 \uc218 \uc5c6\ub294 \uc0ac\uc815\uc774 \ubc1c\uacac\ub41c \uacbd\uc6b0 \uc7a5\ub798\uc5d0 \ub300\ud558\uc5ec \ud5c8\ub77d\uc744 \ucde8\uc18c\ud558\uac70\ub098 \uc81c\ud55c\ud560 \uc218 \uc788\ub2e4","\uc601\uc5c5 \ud5c8\ub77d\uc740 \ud55c\ubc88 \ud558\uba74 \uc808\ub300\ub85c \ucde8\uc18c\ud560 \uc218 \uc5c6\ub2e4","\uc601\uc5c5 \ud5c8\ub77d\uc758 \ucde8\uc18c\ub294 \uc18c\uae09\ud558\uc5ec \uacfc\uac70\uc758 \uac70\ub798\ub3c4 \ubaa8\ub450 \ubb34\ud6a8\ub85c \ub9cc\ub4e0\ub2e4","\uc601\uc5c5 \ud5c8\ub77d\uc758 \ucde8\uc18c\ub294 \ubc95\uc6d0\uc758 \ud5c8\uac00\uac00 \uc788\uc5b4\uc57c\ub9cc \uac00\ub2a5\ud558\ub2e4"],t.s)
B.b1t=s(["\uc7a5\ub798\uc5d0 \ub300\ud558\uc5ec \ud5c8\ub77d\uc744 \ucde8\uc18c\ud558\uac70\ub098 \uc81c\ud55c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.adK=s(["\uc601\uc5c5\ud5c8\ub77d\uc758 \ucde8\uc18c\xb7\uc81c\ud55c(\uc81c8\uc870 \uc81c2\ud56d)"],t.s)
B.bG9=new A.a("gen_cl_minor_22","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\ubc95\uc815\ub300\ub9ac\uc778\uc774 \uc601\uc5c5\uc758 \ud5c8\ub77d\uc744 \ucde8\uc18c \ub610\ub294 \uc81c\ud55c\ud560 \uc218 \uc788\ub294 \uacbd\uc6b0(\uc81c8\uc870 \uc81c2\ud56d)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.Sk,0,"\ubbfc\ubc95 \uc81c8\uc870 \uc81c2\ud56d\uc740 \ubc95\uc815\ub300\ub9ac\uc778\uc774 \uc601\uc5c5\uc744 \ud5c8\ub77d\ud55c \ubbf8\uc131\ub144\uc790\uac00 \uadf8 \uc601\uc5c5\uc744 \uac10\ub2f9\ud560 \uc218 \uc5c6\ub294 \uacbd\uc6b0\uc5d0\ub294 \uc774\ub97c \ucde8\uc18c\ud558\uac70\ub098 \uc81c\ud55c\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc774 \ucde8\uc18c\xb7\uc81c\ud55c\uc740 \uc7a5\ub798\uc758 \uc601\uc5c5\ud589\uc704\uc5d0 \ub300\ud55c \uac83\uc73c\ub85c, \uc774\ubbf8 \uc720\ud6a8\ud558\uac8c \uc774\ub8e8\uc5b4\uc9c4 \uacfc\uac70 \uac70\ub798\uc758 \ud6a8\ub825\uc5d0\ub294 \uc601\ud5a5\uc744 \ubbf8\uce58\uc9c0 \uc54a\uc73c\uba70 \ubc95\uc6d0\uc758 \ud5c8\uac00\ub97c \uc694\uac74\uc73c\ub85c \ud558\uc9c0 \uc54a\ub294\ub2e4.",B.b1t,B.adK,null)
B.b8t=s(["\ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758\ub97c \uc5bb\uac70\ub098 \ubc95\uc815\ub300\ub9ac\uc778\uc774 \ub300\ub9ac\ud558\uc5ec \uacc4\uc57d\uc744 \uccb4\uacb0\ud574\uc57c \ud55c\ub2e4","\ubbf8\uc131\ub144\uc790\ub294 \ub098\uc774\uc640 \ubb34\uad00\ud558\uac8c \ub2e8\ub3c5\uc73c\ub85c \uc720\ud6a8\ud558\uac8c \uacc4\uc57d\uc744 \uccb4\uacb0\ud560 \uc218 \uc788\ub2e4","\uac00\ub9f9\uacc4\uc57d\uc740 \ub2e8\uc21c\ud788 \uad8c\ub9ac\ub9cc \uc5bb\ub294 \ud589\uc704\uc774\ubbc0\ub85c \ub3d9\uc758\uac00 \ud544\uc694 \uc5c6\ub2e4","\uac00\ub9f9\ubcf8\ubd80\uac00 \ubbf8\uc131\ub144\uc790\uc784\uc744 \uc54c\uc558\ub2e4\uba74 \uacc4\uc57d\uc740 \uc790\ub3d9\uc73c\ub85c \ubb34\ud6a8\uac00 \ub41c\ub2e4"],t.s)
B.a9p=s(["\ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758\ub97c \uc5bb\uac70\ub098 \ubc95\uc815\ub300\ub9ac\uc778\uc774 \ub300\ub9ac\ud558\uc5ec \uacc4\uc57d\uc744 \uccb4\uacb0\ud574\uc57c \ud55c\ub2e4"],t.s)
B.a98=s(["\ubbf8\uc131\ub144\uc790\uc758 \uac00\ub9f9\uacc4\uc57d \uccb4\uacb0 \uc2e4\ubb34"],t.s)
B.bMW=new A.a("gen_cl_minor_23","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\ubbf8\uc131\ub144\uc790\uac00 \uac00\ub9f9\uc810(\ud504\ub79c\ucc28\uc774\uc988) \ucc3d\uc5c5\uc744 \uc704\ud574 \uac00\ub9f9\uacc4\uc57d\uc744 \uccb4\uacb0\ud558\ub824\ub294 \uacbd\uc6b0 \ud544\uc694\ud55c \uc870\uce58\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.b8t,0,"\uac00\ub9f9\uacc4\uc57d\uc740 \uac00\ub9f9\uc810\uc8fc\uc5d0\uac8c \uac00\ub9f9\uae08 \uc9c0\uae09, \uc601\uc5c5\ud45c\uc9c0 \uc0ac\uc6a9\ub8cc \ub4f1 \uac01\uc885 \uc758\ubb34\ub97c \ubc1c\uc0dd\uc2dc\ud0a4\ub294 \ubc95\ub960\ud589\uc704\uc774\ubbc0\ub85c, \ubbf8\uc131\ub144\uc790\uac00 \uc774\ub97c \uccb4\uacb0\ud558\ub824\uba74 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758\ub97c \uc5bb\uac70\ub098 \ubc95\uc815\ub300\ub9ac\uc778\uc774 \ub300\ub9ac\ud558\uc5ec\uc57c \uc720\ud6a8\ud558\ub2e4. \ub3d9\uc758 \uc5c6\uc774 \uccb4\uacb0\ud558\uba74 \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\uac00 \ub420 \ubfd0 \ub2f9\uc5f0\ud788 \ubb34\ud6a8\uac00 \ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4.",B.a9p,B.a98,null)
B.aig=s(["\ubbf8\uc131\ub144\uc790\uac00 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758\ub97c \uc5bb\uc5b4 \ud55c \ubc95\ub960\ud589\uc704\ub294 \ucde8\uc18c\ud560 \uc218 \uc5c6\ub2e4","\ubbf8\uc131\ub144\uc790 \ubcf8\uc778\uc740 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758 \uc5c6\uc774\ub3c4 \uc790\uc2e0\uc758 \ubc95\ub960\ud589\uc704\uc5d0 \ub300\ud55c \ucde8\uc18c\uad8c\uc744 \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4","\ubc95\uc815\ub300\ub9ac\uc778\uc740 \ucde8\uc18c\uc6d0\uc778\uc774 \uc885\ub8cc\ub418\uae30 \uc804\uc5d0\ub3c4 \ucd94\uc778\ud560 \uc218 \uc788\ub2e4","\ubbf8\uc131\ub144\uc790\ub294 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \uc0ac\uc804 \ub3d9\uc758 \uc5c6\uc774 \uc720\ud6a8\ud55c \ubc95\ub960\ud589\uc704\ub97c \ud560 \uc218 \uc5c6\ub2e4"],t.s)
B.TQ=s(["\ubc95\uc815\ub300\ub9ac\uc778\uc758 \uc0ac\uc804 \ub3d9\uc758 \uc5c6\uc774\ub3c4 \ubbf8\uc131\ub144\uc790\uac00 \ub2e8\ub3c5\uc73c\ub85c \uc720\ud6a8\ud558\uac8c \ud560 \uc218 \uc788\uc73c\ubbc0\ub85c"],t.s)
B.aGD=s(["\ubbf8\uc131\ub144\uc790 \ud589\uc704\ub2a5\ub825 \uc608\uc678 \uc885\ud569"],t.s)
B.box=new A.a("gen_cl_minor_24","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704\uc5d0 \uad00\ud55c \ub2e4\uc74c \uc124\uba85 \uc911 \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aig,3,'\ub2e8\uc21c\ud788 \uad8c\ub9ac\ub9cc\uc744 \uc5bb\uac70\ub098 \uc758\ubb34\ub9cc\uc744 \uba74\ud558\ub294 \ud589\uc704(\uc81c5\uc870 \uc81c1\ud56d \ub2e8\uc11c), \ucc98\ubd84\uc774 \ud5c8\ub77d\ub41c \uc7ac\uc0b0\uc758 \ucc98\ubd84(\uc81c6\uc870), \ud5c8\ub77d\ub41c \uc601\uc5c5\uc5d0 \uad00\ud55c \ud589\uc704(\uc81c8\uc870) \ub4f1\uc740 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \uc0ac\uc804 \ub3d9\uc758 \uc5c6\uc774\ub3c4 \ubbf8\uc131\ub144\uc790\uac00 \ub2e8\ub3c5\uc73c\ub85c \uc720\ud6a8\ud558\uac8c \ud560 \uc218 \uc788\uc73c\ubbc0\ub85c, "\uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4" \ub3d9\uc758\uac00 \ud544\uc694\ud558\ub2e4\ub294 \uc124\uba85\uc740 \uc633\uc9c0 \uc54a\ub2e4.',B.TQ,B.aGD,null)
B.bfc=s(["\uc81c\ud55c\ub2a5\ub825\uc790 \ubcf8\uc778\uc5d0\uac8c \ud55c \ud655\ub2f5\ucd09\uad6c\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \uadf8 \uc790\uccb4\ub85c \ud6a8\ub825\uc774 \uc5c6\uace0 \ubc95\uc815\ub300\ub9ac\uc778\uc5d0\uac8c \ud558\uc5ec\uc57c \ud55c\ub2e4","\ubbf8\uc131\ub144\uc790 \ubcf8\uc778\uc5d0\uac8c \ucd09\uad6c\ud574\ub3c4 \ubc95\uc815\ub300\ub9ac\uc778\uc5d0\uac8c \ud55c \uac83\uacfc \ub3d9\uc77c\ud55c \ud6a8\ub825\uc774 \uc788\ub2e4","\ubbf8\uc131\ub144\uc790 \ubcf8\uc778\uc5d0\uac8c\ub9cc \ucd09\uad6c\ud574\uc57c \ud558\uace0 \ubc95\uc815\ub300\ub9ac\uc778\uc5d0\uac8c\ub294 \ud560 \uc218 \uc5c6\ub2e4","\ud655\ub2f5\ucd09\uad6c\ub294 \ub204\uad6c\uc5d0\uac8c \ud558\ub4e0 \ud6a8\ub825\uc5d0 \ucc28\uc774\uac00 \uc5c6\ub2e4"],t.s)
B.a9i=s(["\uc6d0\uce59\uc801\uc73c\ub85c \uadf8 \uc790\uccb4\ub85c \ud6a8\ub825\uc774 \uc5c6\uace0 \ubc95\uc815\ub300\ub9ac\uc778\uc5d0\uac8c \ud558\uc5ec\uc57c \ud55c\ub2e4"],t.s)
B.bhG=s(["\ud655\ub2f5\ucd09\uad6c\uc758 \uc0c1\ub300\ubc29"],t.s)
B.bwI=new A.a("gen_cl_minor_25","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\ubbf8\uc131\ub144\uc790\uac00 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758 \uc5c6\uc774 \uccb4\uacb0\ud55c \uacc4\uc57d\uc758 \uc0c1\ub300\ubc29\uc774 \ubbf8\uc131\ub144\uc790 \uce21\uc5d0 \ucde8\uc18c \uc5ec\ubd80\uc5d0 \ub300\ud55c \ud655\ub2f5\uc744 \ucd09\uad6c\ud558\uc600\uc73c\ub098 \ubbf8\uc131\ub144\uc790 \ubcf8\uc778\uc5d0\uac8c \ucd09\uad6c\ud55c \uacbd\uc6b0\uc758 \ud6a8\ub825\uc740?",B.bfc,0,"\ubbfc\ubc95 \uc81c15\uc870\uc758 \ud655\ub2f5\ucd09\uad6c\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \ubc95\uc815\ub300\ub9ac\uc778\uc5d0\uac8c \ud558\uc5ec\uc57c \ud558\uba70, \uc81c\ud55c\ub2a5\ub825\uc790 \ubcf8\uc778\uc5d0\uac8c \ud55c \ud655\ub2f5\ucd09\uad6c\ub294 \uadf8 \uc790\uccb4\ub85c\ub294 \ud6a8\ub825\uc774 \uc5c6\ub2e4(\ub2e4\ub9cc \uc81c\ud55c\ub2a5\ub825\uc790\uac00 \ub2a5\ub825\uc790\uac00 \ub41c \ud6c4\uc5d0 \ucd09\uad6c\ud558\uba74 \ubcf8\uc778\uc5d0\uac8c \ud655\ub2f5\ucd09\uad6c\ub97c \ud560 \uc218 \uc788\ub2e4). \uc774\ub294 \uc81c\ud55c\ub2a5\ub825\uc790 \ubcf8\uc778\uc774 \uc544\uc9c1 \uc644\uc804\ud55c \ud310\ub2e8\ub2a5\ub825\uc744 \uac16\ucd94\uc9c0 \ubabb\ud588\ub2e4\ub294 \uc810\uc744 \uace0\ub824\ud55c \uac83\uc774\ub2e4.",B.a9i,B.bhG,null)
B.bdY=s([u.rp,"\ubbf8\uc131\ub144\uc790\ub294 \uc131\ub144\uc774 \ub418\uae30 \uc804\uae4c\uc9c0\ub9cc \ucde8\uc18c\uad8c\uc744 \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4","\ubbf8\uc131\ub144\uc790\uc758 \ucde8\uc18c\uad8c\uc5d0\ub294 \uae30\uac04\uc758 \uc81c\ud55c\uc774 \uc804\ud600 \uc5c6\ub2e4","\ubc95\ub960\ud589\uc704\ub97c \ud55c \ub0a0\ubd80\ud130 1\ub144 \ub0b4\uc5d0\ub9cc \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4"],t.s)
B.a8S=s([u.rp],t.s)
B.auC=s(["\ubbf8\uc131\ub144\uc790 \ucde8\uc18c\uad8c\uc758 \ud589\uc0ac\uae30\uac04"],t.s)
B.bGo=new A.a("gen_cl_minor_26","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704 \ucde8\uc18c\uad8c\uc758 \ud589\uc0ac\uae30\uac04\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.bdY,0,"\ubbf8\uc131\ub144\uc790\uc758 \ucde8\uc18c\uad8c\ub3c4 \uc77c\ubc18\uc801\uc778 \ucde8\uc18c\uad8c \ud589\uc0ac\uae30\uac04(\uc81c146\uc870)\uc758 \uc801\uc6a9\uc744 \ubc1b\uc544, \ucd94\uc778\ud560 \uc218 \uc788\ub294 \ub0a0(\uc131\ub144\uc774 \ub41c \ub0a0 \ub4f1)\ubd80\ud130 3\ub144, \ubc95\ub960\ud589\uc704\ub97c \ud55c \ub0a0\ubd80\ud130 10\ub144 \uc911 \uba3c\uc800 \ub3c4\ub2ec\ud558\ub294 \uae30\uac04\uae4c\uc9c0 \ud589\uc0ac\ud558\uc5ec\uc57c \ud55c\ub2e4.",B.a8S,B.auC,null)
B.auy=s(["\ubc95\uc815\ucd94\uc778\uc774 \uc131\ub9bd\ud558\uc5ec \ub354 \uc774\uc0c1 \ucde8\uc18c\ud560 \uc218 \uc5c6\uac8c \ub41c\ub2e4","\uc5ec\uc804\ud788 \uc790\uc720\ub86d\uac8c \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4","\uadf8 \ud589\uc704\ub294 \ubb34\ud6a8\ub85c \ud655\uc815\ub41c\ub2e4","\ubc95\uc815\ub300\ub9ac\uc778\ub9cc \ucde8\uc18c\ud560 \uc218 \uc788\uac8c \ub41c\ub2e4"],t.s)
B.Xq=s(["\ubc95\uc815\ucd94\uc778\uc774 \uc131\ub9bd\ud558\uc5ec \ub354 \uc774\uc0c1 \ucde8\uc18c\ud560 \uc218 \uc5c6\uac8c \ub41c\ub2e4"],t.s)
B.a9L=s(["\ubbf8\uc131\ub144\uc790\uc640 \ubc95\uc815\ucd94\uc778\uc758 \uacb0\ud569 \uc0ac\ub840"],t.s)
B.bwe=new A.a("gen_cl_minor_27","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\ubbf8\uc131\ub144\uc790\uac00 \uc131\ub144\uc774 \ub41c \ud6c4 \uc790\uc2e0\uc774 \ubbf8\uc131\ub144\uc77c \ub54c \ud55c \ubc95\ub960\ud589\uc704\uc5d0 \ub300\ud574 \uc774\uc758 \uc5c6\uc774 \uadf8 \uc774\ud589\uc744 \uccad\uad6c\ud55c \uacbd\uc6b0\uc758 \ud6a8\uacfc\ub294?",B.auy,0,"\uc131\ub144\uc774 \ub41c \ubbf8\uc131\ub144\uc790(\ucde8\uc18c\uad8c\uc790)\uac00 \ucde8\uc18c\uc6d0\uc778 \uc885\ub8cc \ud6c4 \uc774\uc758\ub97c \ubcf4\ub958\ud558\uc9c0 \uc54a\uace0 \uc774\ud589\uc744 \uccad\uad6c\ud558\ub294 \ub4f1 \uc81c145\uc870\uac00 \uc815\ud55c \ud589\uc704\ub97c \ud558\uba74 \ubc95\uc815\ucd94\uc778\uc774 \uc131\ub9bd\ud558\uc5ec \uadf8 \ubc95\ub960\ud589\uc704\ub294 \ud655\uc815\uc801\uc73c\ub85c \uc720\ud6a8\ud574\uc9c0\uace0, \ub354 \uc774\uc0c1 \ucde8\uc18c\ud560 \uc218 \uc5c6\uac8c \ub41c\ub2e4.",B.Xq,B.a9L,null)
B.aVO=s([u.ga,"\ubbf8\uc131\ub144\uc790\uc758 \ub098\uc774\ub97c \ud655\uc778\ud560 \ud544\uc694\uac00 \uc5c6\ub2e4","\uacc4\uc57d\uc11c\uc5d0 \ucde8\uc18c\ud560 \uc218 \uc5c6\ub2e4\ub294 \ubb38\uad6c\ub9cc \ub123\uc73c\uba74 \ucda9\ubd84\ud558\ub2e4","\ubbf8\uc131\ub144\uc790 \ubcf8\uc778\uc758 \uad6c\ub450 \ud655\uc778\ub9cc\uc73c\ub85c \ucda9\ubd84\ud558\ub2e4"],t.s)
B.aXx=s([u.ga],t.s)
B.anz=s(["\ubbf8\uc131\ub144\uc790 \uac70\ub798 \uc0c1\ub300\ubc29\uc758 \uc2e4\ubb34 \ub300\uc751"],t.s)
B.bwZ=new A.a("gen_cl_minor_28","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\ubbf8\uc131\ub144\uc790\uc640 \uacc4\uc57d\uc744 \uccb4\uacb0\ud558\ub824\ub294 \uc0c1\ub300\ubc29\uc774 \uc2e4\ubb34\uc801\uc73c\ub85c \ucde8\ud574\uc57c \ud560 \uc870\uce58\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.aVO,0,"\ubbf8\uc131\ub144\uc790\uc640\uc758 \ubc95\ub960\ud589\uc704\ub294 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758\uac00 \uc5c6\uc73c\uba74 \ucde8\uc18c\ub420 \uc704\ud5d8\uc774 \uc788\uc73c\ubbc0\ub85c, \uc0c1\ub300\ubc29\uc740 \uc2e4\ubb34\uc801\uc73c\ub85c \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758\uc11c\ub97c \ud655\uc778\ud558\uac70\ub098 \ubc95\uc815\ub300\ub9ac\uc778\uc744 \uacc4\uc57d\uc5d0 \ud568\uaed8 \ucc38\uc5ec\uc2dc\ucf1c \uadf8 \ub3d9\uc758\ub97c \uba85\ud655\ud788 \ud655\ubcf4\ud558\ub294 \uac83\uc774 \uc548\uc804\ud558\ub2e4. \uacc4\uc57d\uc11c\uc5d0 \ucde8\uc18c\ub97c \uae08\uc9c0\ud558\ub294 \ubb38\uad6c\ub97c \ub123\uc5b4\ub3c4 \ubc95\uc815 \ucde8\uc18c\uad8c\uc744 \ubc30\uc81c\ud560 \uc218\ub294 \uc5c6\ub2e4.",B.aXx,B.anz,null)
B.Wl=s(["\ubbf8\uc131\ub144\uc790\uc758 \ubaa8\ub4e0 \ubc95\ub960\ud589\uc704\ub294 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \uc0ac\uc804 \ub3d9\uc758\uac00 \uc5c6\uc73c\uba74 \ubb34\ud6a8\uc774\ub2e4","\ubbf8\uc131\ub144\uc790 \ubcf8\uc778\uc740 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758 \uc5c6\uc774\ub3c4 \ucde8\uc18c\uad8c\uc744 \ub2e8\ub3c5\uc73c\ub85c \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4","\ucc98\ubd84\uc774 \ud5c8\ub77d\ub41c \uc7ac\uc0b0\uc758 \ucc98\ubd84, \ud5c8\ub77d\ub41c \uc601\uc5c5\uc5d0 \uad00\ud55c \ud589\uc704\ub294 \ub3d9\uc758 \uc5c6\uc774\ub3c4 \uc720\ud6a8\ud558\ub2e4","\ubbf8\uc131\ub144\uc790\uac00 \uc18d\uc784\uc218\ub85c \ub2a5\ub825\uc790\ub85c \ubbff\uac8c \ud55c \uacbd\uc6b0 \ucde8\uc18c\uad8c\uc774 \ubc30\uc81c\ub420 \uc218 \uc788\ub2e4"],t.s)
B.att=s(['\ubb34\ud6a8\uac00 \uc544\ub2c8\ub77c "\ucde8\uc18c\ud560 \uc218 \uc788\ub294" \ubc95\ub960\ud589\uc704\uc774\ub2e4'],t.s)
B.ar4=s(["\ubbf8\uc131\ub144\uc790 \ubc95\ub960\ud589\uc704 \uc885\ud569 \uc815\ub9ac"],t.s)
B.bva=new A.a("gen_cl_minor_29","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704 \uc885\ud569 \uc815\ub9ac \uc911 \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.Wl,0,'\ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758 \uc5c6\uc774 \ud55c \ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704\ub294 \ubb34\ud6a8\uac00 \uc544\ub2c8\ub77c "\ucde8\uc18c\ud560 \uc218 \uc788\ub294" \ubc95\ub960\ud589\uc704\uc774\ub2e4. \ucde8\uc18c\ub418\uae30 \uc804\uae4c\uc9c0\ub294 \uc720\ud6a8\ud55c \uac83\uc73c\ub85c \ucde8\uae09\ub418\ubbc0\ub85c, "\ub3d9\uc758\uac00 \uc5c6\uc73c\uba74 \ubb34\ud6a8\uc774\ub2e4"\ub77c\ub294 \uc124\uba85\uc740 \uc633\uc9c0 \uc54a\ub2e4. \ub098\uba38\uc9c0 \ucde8\uc18c\uad8c\uc758 \ub2e8\ub3c5 \ud589\uc0ac, \ub3d9\uc758\ub97c \uc694\ud558\uc9c0 \uc54a\ub294 \uc608\uc678 \ud589\uc704, \uc18d\uc784\uc218\uc5d0 \uc758\ud55c \ucde8\uc18c\uad8c \ubc30\uc81c\ub294 \ubaa8\ub450 \uc633\ub2e4.',B.att,B.ar4,null)
B.aJw=s(["\u2460, \u2461, \u2463","\u2460, \u2462","\u2461, \u2462, \u2463","\u2460, \u2461, \u2462, \u2463"],t.s)
B.acu=s(["\ub300\ub9ac\uc778\uc740 \ud589\uc704\ub2a5\ub825\uc744 \uc694\ud558\uc9c0 \uc54a\uc73c\ubbc0\ub85c(\uc81c117\uc870) \ubbf8\uc131\ub144\uc790\ub3c4 \ub300\ub9ac\uc778\uc774 \ub420 \uc218 \uc788\uc5b4"],t.s)
B.azU=s(["\ubbf8\uc131\ub144\uc790 \ubc95\ub960\ud589\uc704 \ucd1d\uc815\ub9ac"],t.s)
B.bpO=new A.a("gen_cl_minor_30","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\ub2e4\uc74c \uc911 \ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc744 \ubaa8\ub450 \uace0\ub974\uba74? \u2460 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758 \uc5c6\uc774 \ud55c \ud589\uc704\ub294 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4 \u2461 \ub2e8\uc21c\ud788 \uad8c\ub9ac\ub9cc \uc5bb\ub294 \ud589\uc704\ub294 \ub3d9\uc758\uac00 \ud544\uc694 \uc5c6\ub2e4 \u2462 \ubbf8\uc131\ub144\uc790\ub294 \ub300\ub9ac\uc778\uc774 \ub420 \uc218 \uc5c6\ub2e4 \u2463 \ud63c\uc778\ud55c \ubbf8\uc131\ub144\uc790\ub294 \uc131\ub144\uc790\ub85c \ubcf8\ub2e4",B.aJw,0,'\u2460\ub3d9\uc758 \uc5c6\ub294 \ud589\uc704\ub294 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4(\uc81c5\uc870 \uc81c2\ud56d), \u2461\ub2e8\uc21c\ud788 \uad8c\ub9ac\ub9cc \uc5bb\ub294 \ud589\uc704\ub294 \ub3d9\uc758\uac00 \ud544\uc694 \uc5c6\ub2e4(\uc81c5\uc870 \uc81c1\ud56d \ub2e8\uc11c), \u2463\ud63c\uc778\ud55c \ubbf8\uc131\ub144\uc790\ub294 \uc131\ub144\uc790\ub85c \ubcf8\ub2e4(\uc81c826\uc870\uc7582, \uc131\ub144\uc758\uc81c)\ub294 \ubaa8\ub450 \uc633\ub2e4. \ub2e4\ub9cc \u2462\ub300\ub9ac\uc778\uc740 \ud589\uc704\ub2a5\ub825\uc744 \uc694\ud558\uc9c0 \uc54a\uc73c\ubbc0\ub85c(\uc81c117\uc870) \ubbf8\uc131\ub144\uc790\ub3c4 \ub300\ub9ac\uc778\uc774 \ub420 \uc218 \uc788\uc5b4, "\ub300\ub9ac\uc778\uc774 \ub420 \uc218 \uc5c6\ub2e4"\ub294 \uc124\uba85\uc740 \uc633\uc9c0 \uc54a\ub2e4.',B.acu,B.azU,null)
B.alO=s(["\uc30d\ubb34\uacc4\uc57d\uc5d0\uc11c \ubc1c\uc0dd\ud55c \ub300\uac00\uc801 \ucc44\ubb34 \uc0ac\uc774\uc5d0 \uacac\ub828\uad00\uacc4\uac00 \uc788\uc5b4\uc57c \ud55c\ub2e4","\uc0c1\ub300\ubc29\uc758 \ucc44\ubb34\uac00 \uc774\ud589\uae30\uc5d0 \uc788\uc5b4\uc57c \ud55c\ub2e4","\uc0c1\ub300\ubc29\uc774 \uc790\uc2e0\uc758 \ucc44\ubb34\uc774\ud589 \ub610\ub294 \uc774\ud589\uc81c\uacf5\uc744 \ud558\uc9c0 \uc54a\uace0 \uc774\ud589\uc744 \uccad\uad6c\ud558\uc5ec\uc57c \ud55c\ub2e4","\ub2f9\uc0ac\uc790 \uc0ac\uc774\uc5d0 \ub3d9\uc2dc\uc774\ud589 \ud2b9\uc57d\uc774 \uc5c6\uc5b4\ub3c4 \ud3b8\ubb34\uacc4\uc57d\uc5d0\uc11c \ub2f9\uc5f0\ud788 \uc778\uc815\ub41c\ub2e4"],t.s)
B.aXH=s(["\ucc98\uc74c\ubd80\ud130 \ud55c\ucabd\ub9cc \ucc44\ubb34\ub97c \ubd80\ub2f4\ud558\ub294 \ud3b8\ubb34\uacc4\uc57d\uc5d0\ub294 \ub300\uac00\uad00\uacc4\uc5d0 \uc788\ub294 \ucc44\ubb34 \uc790\uccb4\uac00 \uc874\uc7ac\ud558\uc9c0 \uc54a\uc73c\ubbc0\ub85c \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \ubb38\uc81c\ub420 \uc5ec\uc9c0\uac00 \uc5c6\ub2e4"],t.s)
B.aL_=s(["\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c\uc758 \uc131\ub9bd\uc694\uac74 \u2014 \uc30d\ubb34\uacc4\uc57d"],t.s)
B.bNo=new A.a("gen_cl_concurrent_1","civil_law","\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c",null,"\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c(\ubbfc\ubc95 \uc81c536\uc870)\uc758 \uc131\ub9bd\uc694\uac74\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.alO,3,"\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc740 \ub9e4\ub9e4\xb7\uc784\ub300\ucc28\uc640 \uac19\uc774 \uc11c\ub85c \ub300\uac00\uc801 \uc758\ubbf8\ub97c \uac00\uc9c0\ub294 \ucc44\ubb34\uac00 \ubc1c\uc0dd\ud558\ub294 \uc30d\ubb34\uacc4\uc57d\uc5d0\uc11c \uc778\uc815\ub418\ub294 \uc81c\ub3c4\uc774\ub2e4. \ucc98\uc74c\ubd80\ud130 \ud55c\ucabd\ub9cc \ucc44\ubb34\ub97c \ubd80\ub2f4\ud558\ub294 \ud3b8\ubb34\uacc4\uc57d\uc5d0\ub294 \ub300\uac00\uad00\uacc4\uc5d0 \uc788\ub294 \ucc44\ubb34 \uc790\uccb4\uac00 \uc874\uc7ac\ud558\uc9c0 \uc54a\uc73c\ubbc0\ub85c \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \ubb38\uc81c\ub420 \uc5ec\uc9c0\uac00 \uc5c6\ub2e4.",B.aXH,B.aL_,null)
B.apB=s(["\uc30d\ubb34\uacc4\uc57d\uc5d0\uc11c \uc591 \ucc44\ubb34\uac00 \ub300\uac00\uc801 \uc758\ubbf8\ub97c \uac00\uc9c0\uace0 \uc11c\ub85c \uc774\ud589\uc0c1 \ub2f4\ubcf4\ub85c\uc11c \uae30\ub2a5\ud558\ub294 \uad00\uacc4\ub97c \ub9d0\ud55c\ub2e4","\ub450 \ucc44\ubb34\uac00 \uc6b0\uc5f0\ud788 \uac19\uc740 \ub0a0\uc9dc\uc5d0 \uc774\ud589\uae30\uac00 \ub3c4\ub798\ud558\ub294 \uac83\uc744 \uc758\ubbf8\ud55c\ub2e4","\uacac\ub828\uad00\uacc4\ub294 \ud3b8\ubb34\uacc4\uc57d\uc5d0\uc11c\ub9cc \uc778\uc815\ub418\ub294 \ud2b9\uc720\ud55c \uac1c\ub150\uc774\ub2e4","\uacac\ub828\uad00\uacc4\ub294 \ucc44\ubb34\uc758 \ubc1c\uc0dd\uc6d0\uc778\uc774 \uc11c\ub85c \ub2ec\ub77c\uc57c\ub9cc \uc778\uc815\ub41c\ub2e4"],t.s)
B.akb=s(["\uc30d\ubb34\uacc4\uc57d\uc5d0\uc11c \uc11c\ub85c \ub300\uac00\uc801 \uc758\ubbf8\ub97c \uac00\uc9c0\ub294 \ub450 \ucc44\ubb34\uac00 \uc774\ud589\uc0c1 \ub2f4\ubcf4\ub85c\uc11c \uae30\ub2a5\ud558\ub3c4\ub85d \uacb0\ud569\ub418\uc5b4 \uc788\ub294 \uad00\uacc4"],t.s)
B.RN=s(["\uacac\ub828\uad00\uacc4\uc758 \uc758\ubbf8"],t.s)
B.bQw=new A.a("gen_cl_concurrent_2","civil_law","\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c",null,'\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \uc778\uc815\ub418\uae30 \uc704\ud55c "\uacac\ub828\uad00\uacc4"\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?',B.apB,0,"\uacac\ub828\uad00\uacc4\ub294 \uc30d\ubb34\uacc4\uc57d\uc5d0\uc11c \uc11c\ub85c \ub300\uac00\uc801 \uc758\ubbf8\ub97c \uac00\uc9c0\ub294 \ub450 \ucc44\ubb34\uac00 \uc774\ud589\uc0c1 \ub2f4\ubcf4\ub85c\uc11c \uae30\ub2a5\ud558\ub3c4\ub85d \uacb0\ud569\ub418\uc5b4 \uc788\ub294 \uad00\uacc4\ub97c \ub9d0\ud558\uba70, \uc774 \uacac\ub828\uad00\uacc4\uac00 \uc788\uc5b4\uc57c \uc5b4\ub290 \ud55c\ucabd\uc774 \uc774\ud589\ud558\uc9c0 \uc54a\ub294 \ub3d9\uc548 \uc0c1\ub300\ubc29\ub3c4 \uc790\uc2e0\uc758 \ucc44\ubb34\uc774\ud589\uc744 \uac70\uc808\ud560 \uc218 \uc788\ub294 \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \uc778\uc815\ub41c\ub2e4.",B.akb,B.RN,null)
B.a5u=s(["\ub2f9\uc0ac\uc790 \uc77c\ubc29\uc774 \uba3c\uc800 \uc774\ud589\ud560 \uc758\ubb34\uac00 \uc788\ub294 \uacbd\uc6b0\uc5d0\ub3c4, \uc0c1\ub300\ubc29\uc758 \uc774\ud589\uc774 \uace4\ub780\ud560 \ud604\uc800\ud55c \uc0ac\uc720\uac00 \uc788\ub294 \ub54c\uc5d0\ub294 \uc790\uae30\uc758 \ucc44\ubb34\uc774\ud589\uc744 \uac70\uc808\ud560 \uc218 \uc788\ub2e4","\uba3c\uc800 \uc774\ud589\ud560 \uc758\ubb34\uac00 \uc788\ub294 \uc790\ub294 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \uc774\ud589\uc744 \uac70\uc808\ud560 \uc218 \uc5c6\ub2e4","\ubd88\uc548\uc758 \ud56d\ubcc0\uad8c\uc740 \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uacfc \uc804\ud600 \ubb34\uad00\ud55c \ubcc4\uac1c\uc758 \uc81c\ub3c4\uc774\ub2e4","\ubd88\uc548\uc758 \ud56d\ubcc0\uad8c\uc740 \uc30d\ubb34\uacc4\uc57d\uc774 \uc544\ub2cc \uacbd\uc6b0\uc5d0\ub3c4 \uc790\uc720\ub86d\uac8c \uc778\uc815\ub41c\ub2e4"],t.s)
B.aiC=s(["\uc0c1\ub300\ubc29\uc758 \uc7ac\uc0b0\uc0c1\ud0dc \uc545\ud654 \ub4f1\uc73c\ub85c \uadf8 \ubc18\ub300\uae09\ubd80\uc758 \uc774\ud589\uc774 \uace4\ub780\ud558\uac8c \ub420 \ud604\uc800\ud55c \uc0ac\uc720\uac00 \uc788\ub294 \ub54c\uc5d0\ub294, \uc790\uae30\uc758 \ucc44\ubb34\uc774\ud589\uc744 \uac70\uc808\ud560 \uc218 \uc788\ub2e4"],t.s)
B.aIe=s(["\ubd88\uc548\uc758 \ud56d\ubcc0\uad8c"],t.s)
B.bBy=new A.a("gen_cl_concurrent_3","civil_law","\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c",null,"\ubd88\uc548\uc758 \ud56d\ubcc0\uad8c(\ubbfc\ubc95 \uc81c536\uc870 \uc81c2\ud56d)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.a5u,0,"\ubbfc\ubc95 \uc81c536\uc870 \uc81c2\ud56d\uc740 \uc120\uc774\ud589\uc758\ubb34\uc790\ub77c\ub3c4 \uc0c1\ub300\ubc29\uc758 \uc7ac\uc0b0\uc0c1\ud0dc \uc545\ud654 \ub4f1\uc73c\ub85c \uadf8 \ubc18\ub300\uae09\ubd80\uc758 \uc774\ud589\uc774 \uace4\ub780\ud558\uac8c \ub420 \ud604\uc800\ud55c \uc0ac\uc720\uac00 \uc788\ub294 \ub54c\uc5d0\ub294, \uc790\uae30\uc758 \ucc44\ubb34\uc774\ud589\uc744 \uac70\uc808\ud560 \uc218 \uc788\ub3c4\ub85d \ud558\ub294 \ubd88\uc548\uc758 \ud56d\ubcc0\uad8c\uc744 \uaddc\uc815\ud558\uace0 \uc788\ub2e4. \uc774\ub294 \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc758 \ucde8\uc9c0\ub97c \uc120\uc774\ud589\uc758\ubb34\uc790\uc5d0\uac8c\uae4c\uc9c0 \ud655\uc7a5\ud55c \uac83\uc774\ub2e4.",B.aiC,B.aIe,null)
B.b54=s(["\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \uc874\uc7ac\ud558\ub294 \ud55c, \uc0c1\ub300\ubc29\uc774 \uc774\ud589\uc81c\uacf5\uc744 \ud558\uc9c0 \uc54a\ub294 \ub3d9\uc548\uc5d0\ub294 \uc774\ud589\uc9c0\uccb4\ucc45\uc784\uc744 \uc9c0\uc9c0 \uc54a\ub294\ub2e4","\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \uc788\uc5b4\ub3c4 \uc774\ud589\uae30\uac00 \uc9c0\ub098\uba74 \ubb34\uc870\uac74 \uc774\ud589\uc9c0\uccb4\ucc45\uc784\uc744 \uc9c4\ub2e4","\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc740 \uc774\ud589\uc9c0\uccb4\uc640 \uc544\ubb34\ub7f0 \uad00\ub828\uc774 \uc5c6\ub2e4","\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc740 \uc774\ud589\uc9c0\uccb4\ucc45\uc784\uc744 \uc0ac\ud6c4\uc5d0\ub9cc \uc18c\uae09\ud558\uc5ec \uc18c\uba78\uc2dc\ud0ac \ubfd0 \uc560\ucd08\uc5d0 \ubc1c\uc0dd \uc790\uccb4\ub97c \ub9c9\uc9c0\ub294 \ubabb\ud55c\ub2e4"],t.s)
B.aRh=s(["\uc0c1\ub300\ubc29\uc774 \uc790\uc2e0\uc758 \ucc44\ubb34\uc774\ud589\uc744 \uc81c\uacf5\ud558\uc9c0 \uc54a\ub294 \ud55c \uc790\uae30 \ucc44\ubb34\uc758 \uc774\ud589\uc744 \uac70\uc808\ud560 \uc815\ub2f9\ud55c \uad8c\ub9ac\uac00 \uc788\uc73c\ubbc0\ub85c, \uc774\ud589\uc9c0\uccb4\ucc45\uc784 \uc790\uccb4\uac00 \ubc1c\uc0dd\ud558\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.aBf=s(["\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c\uacfc \uc774\ud589\uc9c0\uccb4 \uc800\uc9c0\ud6a8\uacfc"],t.s)
B.bvn=new A.a("gen_cl_concurrent_4","civil_law","\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c",null,"\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \uc774\ud589\uc9c0\uccb4 \uc131\ub9bd\uc5d0 \ubbf8\uce58\ub294 \ud6a8\uacfc\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.b54,0,"\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc744 \uac00\uc9c4 \ucc44\ubb34\uc790\ub294 \uc0c1\ub300\ubc29\uc774 \uc790\uc2e0\uc758 \ucc44\ubb34\uc774\ud589\uc744 \uc81c\uacf5\ud558\uc9c0 \uc54a\ub294 \ud55c \uc790\uae30 \ucc44\ubb34\uc758 \uc774\ud589\uc744 \uac70\uc808\ud560 \uc815\ub2f9\ud55c \uad8c\ub9ac\uac00 \uc788\uc73c\ubbc0\ub85c, \uc774\ud589\uae30\uac00 \uc9c0\ub098\ub354\ub77c\ub3c4 \uc704\ubc95\ud558\uac8c \uc774\ud589\uc744 \uc9c0\uccb4\ud55c \uac83\uc73c\ub85c \ubcfc \uc218 \uc5c6\uc5b4 \uc774\ud589\uc9c0\uccb4\ucc45\uc784 \uc790\uccb4\uac00 \ubc1c\uc0dd\ud558\uc9c0 \uc54a\ub294\ub2e4.",B.aRh,B.aBf,null)
B.bhe=s(["\uc6d0\uace0\uc758 \ubc18\ub300\uae09\ubd80 \uc774\ud589\uacfc \uc0c1\ud658\uc73c\ub85c \ud53c\uace0\uc758 \uc774\ud589\uc744 \uba85\ud558\ub294 \uc0c1\ud658\uae09\ubd80\ud310\uacb0(\uc0c1\ud658\uc774\ud589\ud310\uacb0)\uc744 \ud55c\ub2e4","\uc6d0\uace0\uc758 \uccad\uad6c\ub97c \uc804\ubd80 \uae30\uac01\ud558\ub294 \ud310\uacb0\ub9cc\uc744 \ud558\uc5ec\uc57c \ud55c\ub2e4","\ud53c\uace0\uc758 \ud56d\ubcc0\uacfc \uad00\uacc4\uc5c6\uc774 \ubb34\uc870\uac74 \uc6d0\uace0 \uc2b9\uc18c\ud310\uacb0\uc744 \ud55c\ub2e4","\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uc774 \uc788\uc73c\uba74 \uc18c\uc1a1 \uc790\uccb4\ub97c \uac01\ud558\ud558\uc5ec\uc57c \ud55c\ub2e4"],t.s)
B.awL=s(["\uc6d0\uace0\uac00 \ubc18\ub300\uae09\ubd80\ub97c \uc774\ud589\ud568\uacfc \ub3d9\uc2dc\uc5d0 \ud53c\uace0\ub294 \uc774\ud589\ud558\ub77c\ub294 \ucde8\uc9c0\uc758 \uc0c1\ud658\uae09\ubd80\ud310\uacb0(\uc0c1\ud658\uc774\ud589\ud310\uacb0)\uc744 \ud558\ub294 \uac83\uc774 \ud310\ub840\uc758 \ud655\ub9bd\ub41c \ud0dc\ub3c4"],t.s)
B.a_S=s(["\uc0c1\ud658\uae09\ubd80\ud310\uacb0"],t.s)
B.bIH=new A.a("gen_cl_concurrent_5","civil_law","\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c",null,"\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \ubd99\uc740 \ucc44\ubb34\uc758 \uc774\ud589\uc744 \uc18c\uc1a1\uc0c1 \uccad\uad6c\ud558\ub294 \uacbd\uc6b0, \ubc95\uc6d0\uc774 \ub0b4\ub824\uc57c \ud560 \ud310\uacb0\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.bhe,0,'\ud53c\uace0\uac00 \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc744 \ud589\uc0ac\ud558\uba74, \ubc95\uc6d0\uc740 \uc6d0\uace0\uc758 \uccad\uad6c\ub97c \ub2e8\uc21c\ud788 \uae30\uac01\ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub77c "\uc6d0\uace0\uac00 \ubc18\ub300\uae09\ubd80\ub97c \uc774\ud589\ud568\uacfc \ub3d9\uc2dc\uc5d0 \ud53c\uace0\ub294 \uc774\ud589\ud558\ub77c"\ub294 \ucde8\uc9c0\uc758 \uc0c1\ud658\uae09\ubd80\ud310\uacb0(\uc0c1\ud658\uc774\ud589\ud310\uacb0)\uc744 \ud558\ub294 \uac83\uc774 \ud310\ub840\uc758 \ud655\ub9bd\ub41c \ud0dc\ub3c4\uc774\ub2e4.',B.awL,B.a_S,null)
B.aWj=s(["\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \ubd99\uc5b4 \uc788\ub294 \ucc44\uad8c\uc744 \uc790\ub3d9\ucc44\uad8c\uc73c\ub85c \ud558\uc5ec \uc0c1\uacc4\ud558\ub294 \uac83\uc740 \uc6d0\uce59\uc801\uc73c\ub85c \ud5c8\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4","\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \uc788\uc5b4\ub3c4 \uc0c1\uacc4\ub294 \uc544\ubb34\ub7f0 \uc81c\uc57d \uc5c6\uc774 \uc790\uc720\ub86d\ub2e4","\uc0c1\uacc4\ub294 \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uacfc \uc804\ud600 \ubb34\uad00\ud55c \uc81c\ub3c4\uc774\ub2e4","\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \uc788\ub294 \ucc44\ubb34\ub294 \uc0c1\uacc4\ub85c\ub9cc \uc18c\uba78\ub420 \uc218 \uc788\ub2e4"],t.s)
B.aDQ=s(["\ud56d\ubcc0\uad8c\uc744 \ud589\uc0ac\ud560 \uae30\ud68c\uc870\ucc28 \uac16\uc9c0 \ubabb\ud55c \ucc44 \uc77c\ubc29\uc801\uc73c\ub85c \ucc44\ubb34\ub97c \uc18c\uba78\ub2f9\ud558\ub294 \uacb0\uacfc\uac00 \ub418\uc5b4 \uc6d0\uce59\uc801\uc73c\ub85c \uc774\ub7ec\ud55c \uc0c1\uacc4\ub97c \ud5c8\uc6a9\ud558\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.ajs=s(["\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c\uacfc \uc0c1\uacc4 \uc81c\ud55c"],t.s)
B.buk=new A.a("gen_cl_concurrent_6","civil_law","\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c",null,"\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \uc0c1\uacc4(\u76f8\u8a08)\uc5d0 \ubbf8\uce58\ub294 \uc601\ud5a5\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aWj,0,"\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \ubd99\uc5b4 \uc788\ub294 \ucc44\uad8c\uc744 \uc790\ub3d9\ucc44\uad8c\uc73c\ub85c \ud558\uc5ec \uc0c1\ub300\ubc29\uc758 \ucc44\uad8c\uacfc \uc0c1\uacc4\ud558\ub294 \uac83\uc744 \ud5c8\uc6a9\ud558\uba74, \uc0c1\ub300\ubc29\uc740 \ud56d\ubcc0\uad8c\uc744 \ud589\uc0ac\ud560 \uae30\ud68c\uc870\ucc28 \uac16\uc9c0 \ubabb\ud55c \ucc44 \uc77c\ubc29\uc801\uc73c\ub85c \ucc44\ubb34\ub97c \uc18c\uba78\ub2f9\ud558\ub294 \uacb0\uacfc\uac00 \ub418\uc5b4 \ud56d\ubcc0\uad8c\uc758 \ucde8\uc9c0\uac00 \ubab0\uac01\ub418\ubbc0\ub85c, \ud310\ub840\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \uc774\ub7ec\ud55c \uc0c1\uacc4\ub97c \ud5c8\uc6a9\ud558\uc9c0 \uc54a\ub294\ub2e4.",B.aDQ,B.ajs,null)
B.b92=s(["\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc740 \uc30d\ubb34\uacc4\uc57d\uc758 \ub2f9\uc0ac\uc790 \uc0ac\uc774\uc5d0\uc11c\ub9cc \uc778\uc815\ub418\ub098, \uc720\uce58\uad8c\uc740 \ubb3c\uac74\uc5d0 \uad00\ud558\uc5ec \uc0dd\uae34 \ucc44\uad8c\uc774\uba74 \uacc4\uc57d\uad00\uacc4 \uc5c6\uc774\ub3c4 \uc131\ub9bd\ud560 \uc218 \uc788\ub2e4","\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc740 \ucc44\uad8c\uc801 \ud6a8\ub825\ub9cc \uc788\uc73c\ub098, \uc720\uce58\uad8c\uc740 \ubb3c\uad8c\uc73c\ub85c\uc11c \uc81c3\uc790\uc5d0\uac8c\ub3c4 \ub300\ud56d\ud560 \uc218 \uc788\ub2e4","\uc720\uce58\uad8c\uc740 \ubaa9\uc801\ubb3c\uc744 \uc720\uce58\ud560 \uad8c\ub9ac\uc774\ub098, \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc740 \uc790\uc2e0\uc758 \ucc44\ubb34\uc774\ud589 \uc790\uccb4\ub97c \uac70\uc808\ud560 \uad8c\ub9ac\uc774\ub2e4","\ub450 \uad8c\ub9ac\ub294 \uacb0\ucf54 \ud558\ub098\uc758 \uc0ac\uc548\uc5d0\uc11c \ub3d9\uc2dc\uc5d0 \ubb38\uc81c\ub420 \uc218 \uc5c6\ub294 \uc644\uc804\ud788 \ubc30\ud0c0\uc801\uc778 \uad8c\ub9ac\uc774\ub2e4"],t.s)
B.af9=s(["\uc2e4\uc81c \uc0ac\uc548\uc5d0\uc11c\ub294 \uc694\uac74\uc774 \uacb9\uccd0 \ub450 \uad8c\ub9ac\uac00 \ud568\uaed8 \ubb38\uc81c\ub418\uac70\ub098 \uacbd\ud569\uc801\uc73c\ub85c \uc8fc\uc7a5\ub420 \uc218 \uc788\ub2e4"],t.s)
B.aTv=s(["\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c\uacfc \uc720\uce58\uad8c\uc758 \ube44\uad50"],t.s)
B.bCp=new A.a("gen_cl_concurrent_7","civil_law","\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c",null,"\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uacfc \uc720\uce58\uad8c\uc758 \ucc28\uc774\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.b92,3,'\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uacfc \uc720\uce58\uad8c\uc740 \uc131\ub9bd \uadfc\uac70\uc640 \ud6a8\ub825 \ubc94\uc704\uac00 \ub2e4\ub978 \ubcc4\uac1c\uc758 \uad8c\ub9ac\uc774\uc9c0\ub9cc, \uc2e4\uc81c \uc0ac\uc548(\uc608: \ub9e4\ub9e4\ubaa9\uc801\ubb3c \uc778\ub3c4\uc640 \ub300\uae08\uc9c0\uae09)\uc5d0\uc11c\ub294 \uc694\uac74\uc774 \uacb9\uccd0 \ub450 \uad8c\ub9ac\uac00 \ud568\uaed8 \ubb38\uc81c\ub418\uac70\ub098 \uacbd\ud569\uc801\uc73c\ub85c \uc8fc\uc7a5\ub420 \uc218 \uc788\ub2e4. "\uacb0\ucf54 \ub3d9\uc2dc\uc5d0 \ubb38\uc81c\ub420 \uc218 \uc5c6\ub2e4"\ub294 \uc124\uba85\uc740 \uc633\uc9c0 \uc54a\ub2e4.',B.af9,B.aTv,null)
B.bhW=s(["\ud2b9\uc57d\uc774\ub098 \ub2e4\ub978 \uc0ac\uc815\uc774 \uc5c6\ub294 \ud55c \ub450 \ucc44\ubb34\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uc5d0 \uc788\ub2e4","\ub9e4\ub3c4\uc778\uc758 \uc778\ub3c4\uc758\ubb34\uac00 \ud56d\uc0c1 \uba3c\uc800 \uc774\ud589\ub418\uc5b4\uc57c \ud558\ub294 \uc120\uc774\ud589\uc758\ubb34\uc774\ub2e4","\ub9e4\uc218\uc778\uc758 \ub300\uae08\uc9c0\uae09\uc758\ubb34\uac00 \ud56d\uc0c1 \uba3c\uc800 \uc774\ud589\ub418\uc5b4\uc57c \ud558\ub294 \uc120\uc774\ud589\uc758\ubb34\uc774\ub2e4","\ub450 \ucc44\ubb34\ub294 \uc11c\ub85c \uc544\ubb34\ub7f0 \uad00\ub828\uc774 \uc5c6\ub294 \ub3c5\ub9bd\uc801\uc778 \ucc44\ubb34\uc774\ub2e4"],t.s)
B.b8H=s(["\ud2b9\uc57d\uc774\ub098 \uad00\uc2b5 \ub4f1 \ub2e4\ub978 \uc0ac\uc815\uc774 \uc5c6\ub294 \ud55c \uc6d0\uce59\uc801\uc73c\ub85c \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uc5d0 \uc788\ub2e4"],t.s)
B.a6m=s(["\ub9e4\ub9e4\uacc4\uc57d\uacfc \ub3d9\uc2dc\uc774\ud589\uad00\uacc4"],t.s)
B.bQQ=new A.a("gen_cl_concurrent_8","civil_law","\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c",null,"\ub9e4\ub9e4\uacc4\uc57d\uc5d0\uc11c \ubaa9\uc801\ubb3c \uc778\ub3c4\uc758\ubb34\uc640 \ub300\uae08\uc9c0\uae09\uc758\ubb34\uc758 \uad00\uacc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.bhW,0,"\ub9e4\ub9e4\uacc4\uc57d\uc5d0\uc11c \ub9e4\ub3c4\uc778\uc758 \ubaa9\uc801\ubb3c \uc778\ub3c4\uc758\ubb34\uc640 \ub9e4\uc218\uc778\uc758 \ub300\uae08\uc9c0\uae09\uc758\ubb34\ub294 \uc11c\ub85c \ub300\uac00\uad00\uacc4\uc5d0 \uc788\ub294 \uc30d\ubb34\uacc4\uc57d\uc0c1 \ucc44\ubb34\ub85c\uc11c, \ud2b9\uc57d\uc774\ub098 \uad00\uc2b5 \ub4f1 \ub2e4\ub978 \uc0ac\uc815\uc774 \uc5c6\ub294 \ud55c \uc6d0\uce59\uc801\uc73c\ub85c \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uc5d0 \uc788\ub2e4.",B.b8H,B.a6m,null)
B.b3D=s(["\ub450 \uc758\ubb34\ub294 \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uc5d0 \uc788\ub2e4\uace0 \ubcf8\ub2e4","\uc784\ucc28\uc778\uc758 \ubaa9\uc801\ubb3c\ubc18\ud658\uc758\ubb34\uac00 \ud56d\uc0c1 \uba3c\uc800 \uc774\ud589\ub418\uc5b4\uc57c \ud55c\ub2e4\uace0 \ubcf8\ub2e4","\uc784\ub300\uc778\uc758 \ubcf4\uc99d\uae08\ubc18\ud658\uc758\ubb34\uac00 \ud56d\uc0c1 \uba3c\uc800 \uc774\ud589\ub418\uc5b4\uc57c \ud55c\ub2e4\uace0 \ubcf8\ub2e4","\ub450 \uc758\ubb34\ub294 \uc11c\ub85c \uc544\ubb34\ub7f0 \uad00\uacc4\uac00 \uc5c6\ub2e4\uace0 \ubcf8\ub2e4"],t.s)
B.S7=s(["\uc784\ucc28\uc778\uc758 \ubaa9\uc801\ubb3c\ubc18\ud658\uc758\ubb34\uc640 \uc784\ub300\uc778\uc758 \ubcf4\uc99d\uae08\ubc18\ud658\uc758\ubb34\ub294 \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uc5d0 \uc788\ub2e4\uace0 \ubcf8\ub2e4"],t.s)
B.ayW=s(["\uc784\ub300\ucc28 \uc885\ub8cc \uc2dc \ub3d9\uc2dc\uc774\ud589\uad00\uacc4"],t.s)
B.bNk=new A.a("gen_cl_concurrent_9","civil_law","\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c",null,"\uc784\ub300\ucc28\uacc4\uc57d \uc885\ub8cc \uc2dc \uc784\ucc28\uc778\uc758 \ubaa9\uc801\ubb3c\ubc18\ud658\uc758\ubb34\uc640 \uc784\ub300\uc778\uc758 \ubcf4\uc99d\uae08\ubc18\ud658\uc758\ubb34\uc758 \uad00\uacc4\uc5d0 \uad00\ud55c \ud310\ub840\uc758 \uc785\uc7a5\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.b3D,0,"\ud310\ub840\ub294 \uc784\ub300\ucc28 \uc885\ub8cc \uc2dc \uc784\ucc28\uc778\uc758 \ubaa9\uc801\ubb3c\ubc18\ud658\uc758\ubb34\uc640 \uc784\ub300\uc778\uc758 \ubcf4\uc99d\uae08\ubc18\ud658\uc758\ubb34(\uc5f0\uccb4\ucc28\uc784 \ub4f1 \uacf5\uc81c \ud6c4)\ub294 \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uc5d0 \uc788\ub2e4\uace0 \ubcf4\uc544, \uc784\ucc28\uc778\uc740 \ubcf4\uc99d\uae08\uc744 \ubc18\ud658\ubc1b\uc744 \ub54c\uae4c\uc9c0 \ubaa9\uc801\ubb3c\ubc18\ud658\uc744 \uac70\uc808\ud560 \uc218 \uc788\ub2e4\ub294 \uc785\uc7a5\uc744 \ucde8\ud558\uace0 \uc788\ub2e4.",B.S7,B.ayW,null)
B.aEr=s(["\ud2b9\uc57d\uc774 \uc5c6\ub294 \ud55c \ubaa9\uc801\ubb3c \uc778\ub3c4\uc640 \ubcf4\uc218\uc9c0\uae09\uc740 \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uc5d0 \uc788\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub2e4","\uc218\uae09\uc778\uc740 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ubcf4\uc218\ub97c \uba3c\uc800 \ubc1b\uc544\uc57c\ub9cc \uc778\ub3c4\uc758\ubb34\ub97c \ubd80\ub2f4\ud55c\ub2e4","\ub3c4\uae09\uc778\uc740 \ubaa9\uc801\ubb3c\uc744 \uba3c\uc800 \uc778\ub3c4\ubc1b\uc740 \ud6c4\uc5d0\ub9cc \ubcf4\uc218\uc9c0\uae09\uc758\ubb34\uac00 \ubc1c\uc0dd\ud55c\ub2e4","\ub3c4\uae09\uacc4\uc57d\uc5d0\ub294 \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c \uaddc\uc815\uc774 \uc804\ud600 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.aM0=s(["\uc644\uc131\ubb3c\uc758 \uc778\ub3c4\uc640 \ubcf4\uc218\uc758 \uc9c0\uae09\uc740 \uc11c\ub85c \ub300\uac00\uad00\uacc4\uc5d0 \uc788\ub294 \ucc44\ubb34\uc774\ubbc0\ub85c, \ud2b9\uc57d\uc774 \uc5c6\ub294 \ud55c \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uc5d0 \uc788\ub294 \uac83\uc774 \uc6d0\uce59"],t.s)
B.Xs=s(["\ub3c4\uae09\uacc4\uc57d\uacfc \ub3d9\uc2dc\uc774\ud589\uad00\uacc4"],t.s)
B.bRz=new A.a("gen_cl_concurrent_10","civil_law","\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c",null,"\ub3c4\uae09\uacc4\uc57d\uc5d0\uc11c \uc644\uc131\ub41c \ubaa9\uc801\ubb3c\uc758 \uc778\ub3c4\uc758\ubb34\uc640 \ubcf4\uc218(\u5831\u916c)\uc9c0\uae09\uc758\ubb34\uc758 \uad00\uacc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aEr,0,"\ub3c4\uae09\uacc4\uc57d\uc5d0\uc11c \uc644\uc131\ubb3c\uc758 \uc778\ub3c4\uc640 \ubcf4\uc218\uc758 \uc9c0\uae09\uc740 \uc11c\ub85c \ub300\uac00\uad00\uacc4\uc5d0 \uc788\ub294 \ucc44\ubb34\uc774\ubbc0\ub85c, \ud2b9\uc57d\uc774 \uc5c6\ub294 \ud55c \ubbfc\ubc95 \uc81c665\uc870 \ub4f1\uc758 \ucde8\uc9c0\uc5d0 \ube44\ucd94\uc5b4 \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uc5d0 \uc788\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub2e4.",B.aM0,B.Xs,null)
B.auZ=s(["\uacc4\uc57d\ud574\uc81c\ub85c \uc778\ud55c \ub2f9\uc0ac\uc790 \uc30d\ubc29\uc758 \uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\ub294 \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uc5d0 \uc788\ub2e4","\ud574\uc81c\uc790\uc758 \uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\ub9cc \uc778\uc815\ub418\uace0 \uc0c1\ub300\ubc29\uc758 \uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\ub294 \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4","\uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\ub294 \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c \uaddc\uc815\uc774 \uc900\uc6a9\ub418\uc9c0 \uc54a\ub294 \uc601\uc5ed\uc774\ub2e4","\uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\ub294 \ud56d\uc0c1 \uc120\uc774\ud589\uc758\ubb34\ub85c\ub9cc \ucde8\uae09\ub41c\ub2e4"],t.s)
B.abe=s(["\ubbfc\ubc95 \uc81c549\uc870\ub294 \uacc4\uc57d\ud574\uc81c\ub85c \uc778\ud55c \ub2f9\uc0ac\uc790 \uc30d\ubc29\uc758 \uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\uc5d0 \uad00\ud558\uc5ec \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc5d0 \uad00\ud55c \uc81c536\uc870\ub97c \uc900\uc6a9"],t.s)
B.a4M=s(["\uacc4\uc57d\ud574\uc81c\uc640 \uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\uc758 \ub3d9\uc2dc\uc774\ud589\uad00\uacc4","\uc81c549\uc870"],t.s)
B.bFe=new A.a("gen_cl_concurrent_11","civil_law","\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c",null,"\uacc4\uc57d\ud574\uc81c \uc2dc \ub2f9\uc0ac\uc790 \uc30d\ubc29\uc758 \uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\uc758 \uad00\uacc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.auZ,0,"\ubbfc\ubc95 \uc81c549\uc870\ub294 \uacc4\uc57d\ud574\uc81c\ub85c \uc778\ud55c \ub2f9\uc0ac\uc790 \uc30d\ubc29\uc758 \uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\uc5d0 \uad00\ud558\uc5ec \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc5d0 \uad00\ud55c \uc81c536\uc870\ub97c \uc900\uc6a9\ud558\ub3c4\ub85d \uaddc\uc815\ud558\uace0 \uc788\uc73c\ubbc0\ub85c, \ud574\uc81c\ub85c \uc778\ud55c \uc30d\ubc29\uc758 \uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\ub294 \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uc5d0 \uc788\ub2e4.",B.abe,B.a4M,null)
B.QE=s(["\ud56d\ubcc0\uad8c\uc774 \uc788\ub2e4\ub294 \uc0ac\uc815\ub9cc\uc73c\ub85c \ub2f9\uc5f0\ud788 \uc774\ud589\uc9c0\uccb4\ucc45\uc784\uc774 \uc870\uac01\ub418\ub294 \uac83\uc740 \uc544\ub2c8\uace0, \uc18c\uc1a1\uc0c1 \uc774\ub97c \uc8fc\uc7a5\xb7\ud589\uc0ac\ud558\uc5ec\uc57c \uadf8 \ud6a8\uacfc\ub97c \ubc1b\uc744 \uc218 \uc788\ub2e4\ub294 \uac83\uc774 \ub2e4\uc218\uc758 \uacac\ud574\uc774\ub2e4","\ud56d\ubcc0\uad8c\uc744 \uc8fc\uc7a5\ud558\uc9c0 \uc54a\uc544\ub3c4 \ubc95\uc6d0\uc740 \ubc18\ub4dc\uc2dc \uc9c1\uad8c\uc73c\ub85c \uadf8 \ud589\uc0ac\uc758 \ud6a8\uacfc\uae4c\uc9c0 \uc778\uc815\ud574\uc8fc\uc5b4\uc57c \ud55c\ub2e4","\ud56d\ubcc0\uad8c\uc740 \uc874\uc7ac\ub9cc\uc73c\ub85c \uc790\ub3d9\uc73c\ub85c \ucc44\ubb34 \uc790\uccb4\ub97c \uc18c\uba78\uc2dc\ud0a8\ub2e4","\ud56d\ubcc0\uad8c\uc758 \uc6d0\uc6a9 \uc5ec\ubd80\ub294 \uc774\ud589\uc9c0\uccb4\ucc45\uc784 \ud310\ub2e8\uacfc \uc804\ud600 \ubb34\uad00\ud558\ub2e4"],t.s)
B.aWM=s(["\uc2e4\uc81c\ub85c \uc774\ud589\uac70\uc808\uc774\ub77c\ub294 \ud6a8\uacfc\ub97c \uc628\uc804\ud788 \ubc1b\uc73c\ub824\uba74 \ucc44\ubb34\uc790\uac00 \uc774\ub97c \ud589\uc0ac(\uc6d0\uc6a9)\ud558\ub294 \uac83\uc774 \ud544\uc694\ud558\ub2e4\ub294 \uac83\uc774 \ub2e4\uc218 \uacac\ud574"],t.s)
B.aex=s(["\ud56d\ubcc0\uad8c\uc758 \uc6d0\uc6a9\uacfc \ud589\uc0ac"],t.s)
B.bEa=new A.a("gen_cl_concurrent_12","civil_law","\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c",null,"\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc744 \uc6d0\uc6a9(\uc8fc\uc7a5)\ud558\uc9c0 \uc54a\uace0 \uc788\ub294 \ucc44\ubb34\uc790\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.QE,0,'\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc740 \uc774\ub978\ubc14 "\uad8c\ub9ac\ud56d\ubcc0"\uc73c\ub85c\uc11c, \uadf8 \uc874\uc7ac \uc790\uccb4\ub294 \ubc95\uc6d0\uc774 \uc9c1\uad8c\uc73c\ub85c \uace0\ub824\ud560 \uc218 \uc788\ub294 \uc0ac\ud56d\uc774\ub77c\ub3c4, \uc2e4\uc81c\ub85c \uc774\ud589\uac70\uc808\uc774\ub77c\ub294 \ud6a8\uacfc\ub97c \uc628\uc804\ud788 \ubc1b\uc73c\ub824\uba74 \ucc44\ubb34\uc790\uac00 \uc774\ub97c \ud589\uc0ac(\uc6d0\uc6a9)\ud558\ub294 \uac83\uc774 \ud544\uc694\ud558\ub2e4\ub294 \uac83\uc774 \ub2e4\uc218 \uacac\ud574\uc774\ub2e4.',B.aWM,B.aex,null)
B.azm=s(["\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \ubd99\uc5b4 \uc788\uc5b4\ub3c4 \uadf8 \ucc44\uad8c \uc790\uccb4\uc758 \uc18c\uba78\uc2dc\ud6a8\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \uc9c4\ud589\ud55c\ub2e4","\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \uc788\uc73c\uba74 \uc18c\uba78\uc2dc\ud6a8\uac00 \uc601\uad6c\ud788 \uc815\uc9c0\ub41c\ub2e4","\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc740 \uc18c\uba78\uc2dc\ud6a8\uc640 \uc544\ubb34\ub7f0 \uad00\ub828\uc774 \uc5c6\uc5b4 \ub17c\uc758\ud560 \uc2e4\uc775\uc774 \uc5c6\ub2e4","\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \ubd99\uc740 \ucc44\uad8c\uc740 \uc18c\uba78\uc2dc\ud6a8\uc5d0 \uac78\ub9ac\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.aIU=s(["\ucc44\uad8c \uc790\uccb4\uc758 \uc18c\uba78\uc2dc\ud6a8 \uc9c4\ud589\uc744 \ub9c9\ub294 \ud6a8\ub825\uc740 \uc5c6\ub2e4\ub294 \uac83\uc774 \ud310\ub840\uc758 \uc785\uc7a5"],t.s)
B.a02=s(["\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c\uacfc \uc18c\uba78\uc2dc\ud6a8"],t.s)
B.bCz=new A.a("gen_cl_concurrent_13","civil_law","\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c",null,"\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \uc18c\uba78\uc2dc\ud6a8 \uc9c4\ud589\uc5d0 \ubbf8\uce58\ub294 \uc601\ud5a5\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.azm,0,"\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc740 \uc0c1\ub300\ubc29\uc758 \uc774\ud589\uccad\uad6c\uc5d0 \ub300\ud574 \uc790\uae30 \ucc44\ubb34\uc758 \uc774\ud589\uc744 \uac70\uc808\ud560 \uc218 \uc788\ub294 \uc5f0\uae30\uc801 \ud56d\ubcc0\uad8c\uc5d0 \ubd88\uacfc\ud560 \ubfd0, \ucc44\uad8c \uc790\uccb4\uc758 \uc18c\uba78\uc2dc\ud6a8 \uc9c4\ud589\uc744 \ub9c9\ub294 \ud6a8\ub825\uc740 \uc5c6\ub2e4\ub294 \uac83\uc774 \ud310\ub840\uc758 \uc785\uc7a5\uc774\ub2e4.",B.aIU,B.a02,null)
B.aI3=s(["\ub2f9\uc0ac\uc790 \uc77c\ubc29\uc774 \uba3c\uc800 \uc774\ud589\ud558\uae30\ub85c \ud2b9\uc57d\ud55c \uacbd\uc6b0, \uadf8 \uc120\uc774\ud589\uc758\ubb34\uc790\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc744 \ud589\uc0ac\ud560 \uc218 \uc5c6\ub2e4","\uc120\uc774\ud589\uc758\ubb34\uac00 \uc788\uc5b4\ub3c4 \ud56d\uc0c1 \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc744 \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4","\uc120\uc774\ud589 \ud2b9\uc57d\uc740 \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc5d0 \uc5b4\ub5a0\ud55c \uc601\ud5a5\ub3c4 \uc8fc\uc9c0 \uc54a\ub294\ub2e4","\uc120\uc774\ud589\uc758\ubb34\uc790\ub294 \ubd88\uc548\uc758 \ud56d\ubcc0\uad8c\ub3c4 \uc808\ub300\ub85c \ud589\uc0ac\ud560 \uc218 \uc5c6\ub2e4"],t.s)
B.b7L=s(["\uc120\uc774\ud589\uc758\ubb34\uc790\ub294 \uc790\uc2e0\uc758 \uc774\ud589\uae30\uac00 \ub3c4\ub798\ud558\uba74 \uc6d0\uce59\uc801\uc73c\ub85c \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc744 \ud589\uc0ac\ud560 \uc218 \uc5c6\ub2e4"],t.s)
B.aKV=s(["\uc120\uc774\ud589\uc758\ubb34\uc640 \ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c\uc758 \uad00\uacc4"],t.s)
B.bRt=new A.a("gen_cl_concurrent_14","civil_law","\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c",null,"\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uacfc \uc120\uc774\ud589\uc758\ubb34\uc758 \uad00\uacc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aI3,0,"\ub2f9\uc0ac\uc790\uac00 \ud2b9\uc57d\uc73c\ub85c \ud55c\ucabd\uc774 \uba3c\uc800 \uc774\ud589\ud558\uae30\ub85c \uc815\ud55c \uacbd\uc6b0, \uadf8 \uc120\uc774\ud589\uc758\ubb34\uc790\ub294 \uc790\uc2e0\uc758 \uc774\ud589\uae30\uac00 \ub3c4\ub798\ud558\uba74 \uc6d0\uce59\uc801\uc73c\ub85c \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc744 \ud589\uc0ac\ud560 \uc218 \uc5c6\ub2e4. \ub2e4\ub9cc \uc0c1\ub300\ubc29\uc758 \uc774\ud589\uc774 \ud604\uc800\ud788 \uace4\ub780\ud574\uc9c8 \uc0ac\uc720\uac00 \uc788\ub294 \uacbd\uc6b0\uc5d0\ub294 \uc608\uc678\uc801\uc73c\ub85c \ubd88\uc548\uc758 \ud56d\ubcc0\uad8c(\uc81c536\uc870 \uc81c2\ud56d)\uc744 \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4.",B.b7L,B.aKV,null)
B.aZQ=s(["\uc11c\ub85c \ubcc4\uac1c\uc758 \uacc4\uc57d\uc5d0\uc11c \uc6b0\uc5f0\ud788 \ubc1c\uc0dd\ud55c \uad00\ub828 \uc5c6\ub294 \ucc44\ubb34 \uc0ac\uc774","\ub9e4\ub9e4\uacc4\uc57d\uc5d0\uc11c \ub9e4\ub3c4\uc778\uc758 \uc18c\uc720\uad8c\uc774\uc804\ub4f1\uae30\uc758\ubb34\uc640 \ub9e4\uc218\uc778\uc758 \ub300\uae08\uc9c0\uae09\uc758\ubb34 \uc0ac\uc774","\uc30d\ubb34\uacc4\uc57d\uc5d0\uc11c \ud558\uc790\ub2f4\ubcf4\ub85c \uc778\ud55c \uc190\ud574\ubc30\uc0c1\uc758\ubb34\uc640 \uc794\ub300\uae08\uc9c0\uae09\uc758\ubb34 \uc0ac\uc774(\uad6c\uccb4\uc801 \uc0ac\uc548\uc5d0 \ub530\ub77c \uc778\uc815\ub420 \uc218 \uc788\uc74c)","\ub3c4\uae09\uacc4\uc57d\uc5d0\uc11c \uc644\uc131\ubb3c\uc778\ub3c4\uc758\ubb34\uc640 \ubcf4\uc218\uc9c0\uae09\uc758\ubb34 \uc0ac\uc774"],t.s)
B.amK=s(["\uc11c\ub85c \ub2e4\ub978 \ubcc4\uac1c\uc758 \uacc4\uc57d\uc5d0\uc11c \uac01\uac01 \ubc1c\uc0dd\ud55c, \ub300\uac00\uad00\uacc4 \uc5c6\ub294 \ucc44\ubb34 \uc0ac\uc774\uc5d0\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \uacac\ub828\uad00\uacc4\uac00 \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.aih=s(["\uacac\ub828\uad00\uacc4\uac00 \ubd80\uc815\ub418\ub294 \uacbd\uc6b0"],t.s)
B.bJL=new A.a("gen_cl_concurrent_15","civil_law","\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c",null,"\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc744 \ubc1c\uc0dd\uc2dc\ud0a4\ub294 \uacac\ub828\uad00\uacc4\uac00 \uc778\uc815\ub418\uae30 \uc5b4\ub824\uc6b4 \uacbd\uc6b0\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aZQ,0,"\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc740 \ud558\ub098\uc758 \uc30d\ubb34\uacc4\uc57d\uc5d0\uc11c \ubc1c\uc0dd\ud55c \ub300\uac00\uc801 \ucc44\ubb34 \uc0ac\uc774\uc758 \uacac\ub828\uad00\uacc4\ub97c \uc804\uc81c\ub85c \ud55c\ub2e4. \uc11c\ub85c \ub2e4\ub978 \ubcc4\uac1c\uc758 \uacc4\uc57d\uc5d0\uc11c \uac01\uac01 \ubc1c\uc0dd\ud55c, \ub300\uac00\uad00\uacc4 \uc5c6\ub294 \ucc44\ubb34 \uc0ac\uc774\uc5d0\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \uacac\ub828\uad00\uacc4\uac00 \uc778\uc815\ub418\uc9c0 \uc54a\uc544 \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\ub3c4 \uc131\ub9bd\ud558\uae30 \uc5b4\ub835\ub2e4.",B.amK,B.aih,null)
B.b46=s(["\uacc4\uc57d\ud574\uc81c\ub85c \uc778\ud55c \uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34(\uc81c549\uc870)\uc5d0 \uc900\uc6a9\ub41c\ub2e4","\ub3c4\uae09\uc778\uc758 \ud558\uc790\ub2f4\ubcf4\ucc45\uc784\uc5d0 \ub530\ub978 \uc190\ud574\ubc30\uc0c1\uccad\uad6c\uc640 \ubcf4\uc218\uc9c0\uae09 \uc0ac\uc774\uc5d0 \uc778\uc815\ub420 \uc218 \uc788\ub2e4","\ubd80\ub2f9\uc774\ub4dd\ubc18\ud658\uc758\ubb34 \uc0c1\ud638\uac04\uc5d0\ub294 \uadf8 \uc2e4\uc9c8\uc774 \uc30d\ubb34\uacc4\uc57d\uc801 \uacac\ub828\uad00\uacc4\uc5d0 \uc788\ub2e4\uba74 \uc900\uc6a9\ub420 \uc218 \uc788\ub2e4","\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc740 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ub2e4\ub978 \ubc95\ub960\uad00\uacc4\uc5d0 \uc900\uc6a9\ub418\uac70\ub098 \uc720\ucd94\uc801\uc6a9\ub420 \uc218 \uc5c6\ub2e4"],t.s)
B.a1j=s(["\uc2e4\uc9c8\uc801\uc73c\ub85c \ub300\uac00\uad00\uacc4\uc5d0 \uc788\ub2e4\uace0 \ubcfc \uc218 \uc788\ub294 \ubc95\ub960\uad00\uacc4\uc5d0 \uc720\ucd94\uc801\uc6a9\ub418\ub294 \uc0ac\ub840\ub4e4\uc774 \uc778\uc815\ub41c\ub2e4"],t.s)
B.Z1=s(["\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c \uaddc\uc815\uc758 \uc900\uc6a9\xb7\uc720\ucd94\uc801\uc6a9"],t.s)
B.bLk=new A.a("gen_cl_concurrent_16","civil_law","\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c",null,"\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc5d0 \uad00\ud55c \ubbfc\ubc95 \uaddc\uc815\uc758 \uc900\uc6a9\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.b46,3,'\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c \uaddc\uc815(\uc81c536\uc870)\uc740 \uacc4\uc57d\ud574\uc81c\ub85c \uc778\ud55c \uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34(\uc81c549\uc870)\uc5d0 \uba85\ubb38\uc73c\ub85c \uc900\uc6a9\ub418\uba70, \uadf8 \ubc16\uc5d0\ub3c4 \uc2e4\uc9c8\uc801\uc73c\ub85c \ub300\uac00\uad00\uacc4\uc5d0 \uc788\ub2e4\uace0 \ubcfc \uc218 \uc788\ub294 \ubc95\ub960\uad00\uacc4(\ubd80\ub2f9\uc774\ub4dd\ubc18\ud658 \uc0c1\ud638\uac04 \ub4f1)\uc5d0 \uc720\ucd94\uc801\uc6a9\ub418\ub294 \uc0ac\ub840\ub4e4\uc774 \uc778\uc815\ub41c\ub2e4. "\uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \uc900\uc6a9\xb7\uc720\ucd94\uc801\uc6a9\ub420 \uc218 \uc5c6\ub2e4"\ub294 \uc124\uba85\uc740 \uc633\uc9c0 \uc54a\ub2e4.',B.a1j,B.Z1,null)
B.aHr=s(["\uc0c1\ub300\ubc29\uc774 \uc790\uc2e0\uc758 \ucc44\ubb34\ub97c \uc774\ud589\ud558\uc9c0 \uc54a\uc73c\uba74 \uc774\ucabd\ub3c4 \uc774\ud589\uc744 \uac70\uc808\ud560 \uc218 \uc788\uac8c \ud568\uc73c\ub85c\uc368, \uc0ac\uc2e4\uc0c1 \uc0c1\ub300\ubc29\uc758 \uc774\ud589\uc744 \uc2ec\ub9ac\uc801\xb7\uacbd\uc81c\uc801\uc73c\ub85c \uc555\ubc15\ud558\uc5ec \uc774\ud589\uc744 \ud655\ubcf4\ud558\ub294 \uae30\ub2a5\uc744 \ud55c\ub2e4","\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc740 \ub2f4\ubcf4\ub85c\uc11c\uc758 \uae30\ub2a5\uc744 \uc804\ud600 \uac00\uc9c0\uc9c0 \uc54a\ub294\ub2e4","\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc740 \uc624\uc9c1 \uc18c\uc1a1\uc808\ucc28\uc5d0\uc11c\ub9cc \uc758\ubbf8\ub97c \uac00\uc9c8 \ubfd0 \uc2e4\uccb4\ubc95\uc0c1 \ud6a8\ub825\uc774 \uc5c6\ub2e4","\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc740 \ubb3c\uad8c\uacfc \ub3d9\uc77c\ud55c \uc6b0\uc120\ubcc0\uc81c\uc801 \ud6a8\ub825\uc744 \uac00\uc9c4\ub2e4"],t.s)
B.ahp=s(["\uc11c\ub85c \ub300\uac00\uad00\uacc4\uc5d0 \uc788\ub294 \ucc44\ubb34\ub97c \uc774\ud589\ud558\uc9c0 \uc54a\uc73c\uba74 \uc0c1\ub300\ubc29\ub3c4 \uc774\ud589\uc744 \uac70\uc808\ud560 \uc218 \uc788\uac8c \ud568\uc73c\ub85c\uc368 \uc0ac\uc2e4\uc0c1 \uc774\ud589\uc744 \ud655\ubcf4\ud558\ub294 \ub2f4\ubcf4\uc801 \uae30\ub2a5"],t.s)
B.T0=s(["\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c\uc758 \ub2f4\ubcf4\uc801 \uae30\ub2a5"],t.s)
B.bo2=new A.a("gen_cl_concurrent_17","civil_law","\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c",null,"\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \ub2f4\ubcf4\ub85c\uc11c \uac16\ub294 \uae30\ub2a5\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aHr,0,"\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc740 \ubcc4\ub3c4\uc758 \ub2f4\ubcf4(\ubb3c\uc801 \ub2f4\ubcf4\xb7\uc778\uc801 \ub2f4\ubcf4)\ub97c \uc124\uc815\ud558\uc9c0 \uc54a\uace0\ub3c4, \uc11c\ub85c \ub300\uac00\uad00\uacc4\uc5d0 \uc788\ub294 \ucc44\ubb34\ub97c \uc774\ud589\ud558\uc9c0 \uc54a\uc73c\uba74 \uc0c1\ub300\ubc29\ub3c4 \uc774\ud589\uc744 \uac70\uc808\ud560 \uc218 \uc788\uac8c \ud568\uc73c\ub85c\uc368 \uc0ac\uc2e4\uc0c1 \uc774\ud589\uc744 \ud655\ubcf4\ud558\ub294 \ub2f4\ubcf4\uc801 \uae30\ub2a5\uc744 \uc218\ud589\ud55c\ub2e4.",B.ahp,B.T0,null)
B.awl=s(["\uc720\uce58\uad8c\uc740 \ubaa9\uc801\ubb3c\uc5d0 \ub300\ud574 \uc81c3\uc790\uc5d0\uac8c\ub3c4 \uc8fc\uc7a5\ud560 \uc218 \uc788\ub294 \ubb3c\uad8c\uc774\uc9c0\ub9cc, \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc740 \uacc4\uc57d\uc0c1\ub300\ubc29\uc5d0\uac8c\ub9cc \uc8fc\uc7a5\ud560 \uc218 \uc788\ub294 \ucc44\uad8c\uc801 \ud56d\ubcc0\uad8c\uc774\ub2e4","\ub450 \uad8c\ub9ac\ub294 \ud56d\uc0c1 \ub3d9\uc77c\ud55c \uc694\uac74\uacfc \ud6a8\uacfc\ub97c \uac00\uc9c0\ubbc0\ub85c \uad6c\ubcc4\ud560 \uc2e4\uc775\uc774 \uc5c6\ub2e4","\uc720\uce58\uad8c\uc740 \uc30d\ubb34\uacc4\uc57d\uc5d0\uc11c\ub9cc \uc131\ub9bd\ud558\uace0, \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc740 \ubaa8\ub4e0 \ucc44\uad8c\uad00\uacc4\uc5d0\uc11c \uc131\ub9bd\ud55c\ub2e4","\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc740 \ubb3c\uad8c\uc774\uace0, \uc720\uce58\uad8c\uc740 \ucc44\uad8c\uc774\ub2e4"],t.s)
B.aL9=s(["\uc720\uce58\uad8c\uc740 \ubb3c\uad8c\uc73c\ub85c\uc11c \uc81c3\uc790\uc5d0\uac8c\ub3c4 \uc8fc\uc7a5\ud560 \uc218 \uc788\ub294 \ub300\uc138\uc801 \ud6a8\ub825\uc774 \uc788\uc9c0\ub9cc, \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc740 \uacc4\uc57d\uc758 \uc0c1\ub300\ubc29\uc5d0 \ub300\ud574\uc11c\ub9cc \uc8fc\uc7a5\ud560 \uc218 \uc788\ub294 \ucc44\uad8c\uc801 \ud56d\ubcc0\uad8c"],t.s)
B.R0=s(["\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c\uacfc \uc720\uce58\uad8c\uc758 \ud6a8\ub825\ubc94\uc704 \ucc28\uc774"],t.s)
B.bpR=new A.a("gen_cl_concurrent_18","civil_law","\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c",null,"\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uacfc \uc720\uce58\uad8c\uc774 \ud568\uaed8 \uc131\ub9bd\ud560 \uc218 \uc788\ub294 \uc0ac\uc548\uc5d0\uc11c \ub098\ud0c0\ub098\ub294 \ucc28\uc774\uc810\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.awl,0,"\uc720\uce58\uad8c\uc740 \ubb3c\uad8c\uc73c\ub85c\uc11c \ubaa9\uc801\ubb3c\uc758 \uc18c\uc720\uc790\uac00 \ubc14\ub00c\ub354\ub77c\ub3c4(\uc81c3\uc790\uc5d0\uac8c\ub3c4) \uc8fc\uc7a5\ud560 \uc218 \uc788\ub294 \ub300\uc138\uc801 \ud6a8\ub825\uc774 \uc788\uc9c0\ub9cc, \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc740 \uacc4\uc57d\uc758 \uc0c1\ub300\ubc29\uc5d0 \ub300\ud574\uc11c\ub9cc \uc8fc\uc7a5\ud560 \uc218 \uc788\ub294 \ucc44\uad8c\uc801 \ud56d\ubcc0\uad8c\uc5d0 \uadf8\uce5c\ub2e4\ub294 \uc810\uc5d0\uc11c \ud6a8\ub825 \ubc94\uc704\uac00 \ub2e4\ub974\ub2e4.",B.aL9,B.R0,null)
B.aVQ=s(["\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uacfc \uc704\ud5d8\ubd80\ub2f4\uc740 \ubaa8\ub450 \uc30d\ubb34\uacc4\uc57d\uc758 \uacac\ub828\uc131\uc5d0\uc11c \ud30c\uc0dd\ub41c \uc11c\ub85c \ub2e4\ub978 \ubb38\uc81c\ub97c \ub2e4\ub8ec\ub2e4","\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uacfc \uc704\ud5d8\ubd80\ub2f4\uc740 \uc644\uc804\ud788 \ub3d9\uc77c\ud55c \uc81c\ub3c4\uc774\ub2e4","\uc704\ud5d8\ubd80\ub2f4\uc740 \ud3b8\ubb34\uacc4\uc57d\uc5d0\uc11c\ub9cc \ubb38\uc81c\ub418\ub294 \uac1c\ub150\uc774\ub2e4","\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \uc778\uc815\ub418\uba74 \uc704\ud5d8\ubd80\ub2f4 \ubb38\uc81c\ub294 \uc544\uc608 \ubc1c\uc0dd\ud558\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.axT=s(["\uc804\uc790\ub294 \uc774\ud589\uc758 \uc21c\uc11c\xb7\uac70\uc808\uc744, \ud6c4\uc790\ub294 \uc774\ud589\ubd88\ub2a5 \uc2dc \ubc18\ub300\ucc44\ubb34\uc758 \uc18c\uba78 \uc5ec\ubd80\ub97c \ub2e4\ub8e8\ub294 \uc11c\ub85c \uad6c\ubcc4\ub418\ub294 \ubcc4\uac1c\uc758 \ubb38\uc81c"],t.s)
B.biX=s(["\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c\uacfc \uc704\ud5d8\ubd80\ub2f4\uc758 \uad6c\ubcc4"],t.s)
B.bGq=new A.a("gen_cl_concurrent_19","civil_law","\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c",null,"\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc744 \ud589\uc0ac\ud55c \ucc44\ubb34\uc790\uac00 \ubd80\ub2f4\ud558\ub294 \uc704\ud5d8\ubd80\ub2f4 \ubb38\uc81c\uc640\uc758 \uad00\uacc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.aVQ,0,'\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c(\uc774\ud589\uc0c1 \uacac\ub828\uc131)\uacfc \uc704\ud5d8\ubd80\ub2f4(\uc874\uc18d\uc0c1 \uacac\ub828\uc131, \ud6c4\ubc1c\uc801 \uc774\ud589\ubd88\ub2a5 \uc2dc \ubc18\ub300\uae09\ubd80\uc758 \uc6b4\uba85)\uc740 \ubaa8\ub450 \uc30d\ubb34\uacc4\uc57d\uc758 \uacac\ub828\uc131\uc5d0\uc11c \ube44\ub86f\ub418\uc9c0\ub9cc, \uc804\uc790\ub294 "\uc774\ud589\uc758 \uc21c\uc11c\xb7\uac70\uc808"\uc744, \ud6c4\uc790\ub294 "\uc774\ud589\ubd88\ub2a5 \uc2dc \ubc18\ub300\ucc44\ubb34\uc758 \uc18c\uba78 \uc5ec\ubd80"\ub97c \ub2e4\ub8e8\ub294 \uc11c\ub85c \uad6c\ubcc4\ub418\ub294 \ubcc4\uac1c\uc758 \ubb38\uc81c\uc774\ub2e4.',B.axT,B.biX,null)
B.bbn=s(["\ud2b9\uc57d\uc774\ub098 \uad00\uc2b5\uc774 \uc5c6\ub294 \ud55c \ub450 \uc758\ubb34\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uc5d0 \uc788\ub2e4\uace0 \ubcf8\ub2e4","\ub4f1\uae30\uc758\ubb34\ub294 \ud56d\uc0c1 \ub300\uae08\uc644\ub0a9 \ud6c4\uc5d0\ub9cc \uc774\ud589\ud558\uba74 \ub41c\ub2e4","\uc794\ub300\uae08\uc9c0\uae09\uc758\ubb34\ub294 \ub4f1\uae30\uc774\uc804 \ud6c4 \uc0c1\ub2f9\ud55c \uae30\uac04\uc774 \uc9c0\ub098\uc57c \ubc1c\uc0dd\ud55c\ub2e4","\ub450 \uc758\ubb34\ub294 \uc11c\ub85c \uc544\ubb34\ub7f0 \uacac\ub828\uad00\uacc4\uac00 \uc5c6\ub2e4"],t.s)
B.TR=s(["\ub9e4\ub3c4\uc778\uc758 \uc18c\uc720\uad8c\uc774\uc804\ub4f1\uae30\uc5d0 \ud544\uc694\ud55c \uc11c\ub958 \uad50\ubd80\uc758\ubb34\uc640 \ub9e4\uc218\uc778\uc758 \uc794\ub300\uae08\uc9c0\uae09\uc758\ubb34\ub294 \ud2b9\uc57d\uc774\ub098 \ub2e4\ub978 \uad00\uc2b5\uc774 \uc5c6\ub294 \ud55c \uc6d0\uce59\uc801\uc73c\ub85c \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uc5d0 \uc788\ub2e4"],t.s)
B.bgR=s(["\ubd80\ub3d9\uc0b0 \ub9e4\ub9e4\uc640 \ub3d9\uc2dc\uc774\ud589\uad00\uacc4"],t.s)
B.bsI=new A.a("gen_cl_concurrent_20","civil_law","\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c",null,"\ubd80\ub3d9\uc0b0 \ub9e4\ub9e4\uc5d0\uc11c \ub9e4\ub3c4\uc778\uc758 \uc18c\uc720\uad8c\uc774\uc804\ub4f1\uae30\uc758\ubb34\uc640 \ub9e4\uc218\uc778\uc758 \uc794\ub300\uae08\uc9c0\uae09\uc758\ubb34\uc758 \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.bbn,0,"\ubd80\ub3d9\uc0b0 \ub9e4\ub9e4\uc5d0\uc11c \ub9e4\ub3c4\uc778\uc758 \uc18c\uc720\uad8c\uc774\uc804\ub4f1\uae30\uc5d0 \ud544\uc694\ud55c \uc11c\ub958 \uad50\ubd80\uc758\ubb34\uc640 \ub9e4\uc218\uc778\uc758 \uc794\ub300\uae08\uc9c0\uae09\uc758\ubb34\ub294 \uc11c\ub85c \ub300\uac00\uad00\uacc4\uc5d0 \uc788\ub294 \uc30d\ubb34\uacc4\uc57d\uc0c1 \ucc44\ubb34\ub85c\uc11c, \ud2b9\uc57d\uc774\ub098 \ub2e4\ub978 \uad00\uc2b5\uc774 \uc5c6\ub294 \ud55c \uc6d0\uce59\uc801\uc73c\ub85c \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uc5d0 \uc788\ub2e4\uace0 \ubcf8\ub2e4.",B.TR,B.bgR,null)
B.aTC=s(["\uc0c1\ub300\ubc29\uc774 \uc790\uc2e0\uc758 \ucc44\ubb34\ub97c \uc774\ud589\ud558\uac70\ub098 \uc774\ud589\uc81c\uacf5\uc744 \ud560 \ub54c\uae4c\uc9c0 \uc790\uae30 \ucc44\ubb34\uc758 \uc774\ud589\uc744 \uac70\uc808\ud560 \uc218 \uc788\ub2e4","\uc774\ud589\uc744 \uac70\uc808\ud560 \uc218 \uc5c6\uace0 \ubb34\uc870\uac74 \uba3c\uc800 \uc774\ud589\ud558\uc5ec\uc57c \ud55c\ub2e4","\ud56d\ubcc0\uad8c\uc744 \ud589\uc0ac\ud558\uba74 \ucc44\ubb34 \uc790\uccb4\uac00 \uc18c\uae09\ud558\uc5ec \uc18c\uba78\ud55c\ub2e4","\ud56d\ubcc0\uad8c\uc744 \ud589\uc0ac\ud558\uba74 \uc0c1\ub300\ubc29\uc758 \ucc44\uad8c\ub3c4 \ud568\uaed8 \uc18c\uba78\ud55c\ub2e4"],t.s)
B.a0E=s(["\ud56d\ubcc0\uad8c \ud589\uc0ac\ub294 \ucc44\ubb34\ub97c \uc18c\uba78\uc2dc\ud0a4\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uc774\ud589\uc744 \uc77c\uc2dc\uc801\uc73c\ub85c \uc800\uc9c0\ud558\ub294 \uc5f0\uae30\uc801 \ud6a8\uacfc\ub9cc\uc744 \uac00\uc9c4\ub2e4"],t.s)
B.aCg=s(["\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c \ud589\uc0ac\uc758 \ud6a8\uacfc(\uc5f0\uae30\uc801 \ud56d\ubcc0)"],t.s)
B.bxi=new A.a("gen_cl_concurrent_21","civil_law","\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c",null,"\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \uc788\ub294 \ucc44\ubb34\uc790\uac00 \ucc44\uad8c\uc790\ub85c\ubd80\ud130 \uc774\ud589\uccad\uad6c\ub97c \ubc1b\uc558\uc744 \ub54c \ucde8\ud560 \uc218 \uc788\ub294 \uc870\uce58\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.aTC,0,"\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc744 \uac00\uc9c4 \ucc44\ubb34\uc790\ub294 \uc0c1\ub300\ubc29\uc774 \uc790\uc2e0\uc758 \ucc44\ubb34\ub97c \uc774\ud589\ud558\uac70\ub098 \uc801\uc5b4\ub3c4 \uc774\ud589\uc81c\uacf5\uc744 \ud560 \ub54c\uae4c\uc9c0, \uc790\uae30 \ucc44\ubb34\uc758 \uc774\ud589\uc744 \uc815\ub2f9\ud558\uac8c \uac70\uc808\ud560 \uc218 \uc788\ub2e4. \ud56d\ubcc0\uad8c \ud589\uc0ac\ub294 \ucc44\ubb34\ub97c \uc18c\uba78\uc2dc\ud0a4\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uc774\ud589\uc744 \uc77c\uc2dc\uc801\uc73c\ub85c \uc800\uc9c0\ud558\ub294 \uc5f0\uae30\uc801 \ud6a8\uacfc\ub9cc\uc744 \uac00\uc9c4\ub2e4.",B.a0E,B.aCg,null)
B.Z6=s(["\ucc44\ubb34\uc758 \ub0b4\uc6a9\uc5d0 \uc887\uc740 \uc774\ud589\uc81c\uacf5\uc774 \uc544\ub2cc \uadf9\ud788 \uc77c\ubd80\ub9cc\uc758 \uc774\ud589\uc81c\uacf5\uc73c\ub85c\ub294 \uc0c1\ub300\ubc29\uc758 \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc744 \uc18c\uba78\uc2dc\ud0a4\uc9c0 \ubabb\ud558\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub2e4","\uc544\uc8fc \uc870\uae08\uc774\ub77c\ub3c4 \uc774\ud589\uc744 \uc81c\uacf5\ud558\uba74 \uc0c1\ub300\ubc29\uc740 \ub354 \uc774\uc0c1 \ud56d\ubcc0\uad8c\uc744 \ud589\uc0ac\ud560 \uc218 \uc5c6\ub2e4","\uc77c\ubd80\uc774\ud589\uc81c\uacf5\uc740 \ud56d\ubcc0\uad8c\uc758 \uc131\ub9bd \uc5ec\ubd80\uc640 \uc804\ud600 \uad00\uacc4\uac00 \uc5c6\ub2e4","\uc77c\ubd80\uc774\ud589\uc81c\uacf5\uc774 \uc788\uc73c\uba74 \uc0c1\ub300\ubc29\uc758 \ucc44\ubb34 \uc804\uc561\uc774 \uc18c\uba78\ud55c\ub2e4"],t.s)
B.bhm=s(["\uadf9\ud788 \uc77c\ubd80\ub9cc\uc758 \uc774\ud589\uc81c\uacf5\uc5d0 \uadf8\uce5c \uacbd\uc6b0\uc5d0\ub294, \uc0c1\ub300\ubc29\uc774 \uc5ec\uc804\ud788 \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc744 \ud589\uc0ac\ud558\uc5ec \uc790\uc2e0\uc758 \ucc44\ubb34 \uc804\ubd80\uc758 \uc774\ud589\uc744 \uac70\uc808\ud560 \uc218 \uc788\ub2e4"],t.s)
B.asQ=s(["\uc77c\ubd80\uc774\ud589\uc81c\uacf5\uacfc \ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c"],t.s)
B.bPo=new A.a("gen_cl_concurrent_22","civil_law","\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c",null,'\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uacfc \uad00\ub828\ud558\uc5ec "\uc77c\ubd80\uc774\ud589\uc81c\uacf5"\uc5d0 \uad00\ud55c \ud310\ub840\uc758 \uc785\uc7a5\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?',B.Z6,0,"\ud310\ub840\ub294 \ucc44\ubb34 \ub0b4\uc6a9\uc5d0 \uc887\uc740 \uc644\uc804\ud55c \uc774\ud589\uc81c\uacf5\uc774 \uc544\ub2c8\ub77c \uadf9\ud788 \uc77c\ubd80\ub9cc\uc758 \uc774\ud589\uc81c\uacf5\uc5d0 \uadf8\uce5c \uacbd\uc6b0\uc5d0\ub294, \uc0c1\ub300\ubc29\uc774 \uc5ec\uc804\ud788 \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc744 \ud589\uc0ac\ud558\uc5ec \uc790\uc2e0\uc758 \ucc44\ubb34 \uc804\ubd80\uc758 \uc774\ud589\uc744 \uac70\uc808\ud560 \uc218 \uc788\ub2e4\uace0 \ubcf4\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub2e4.",B.bhm,B.asQ,null)
B.amv=s(["\uc774\ud589\uc81c\uacf5\uc744 \uc911\ub2e8\ud558\uba74 \uc0c1\ub300\ubc29\uc758 \uc774\ud589\uc9c0\uccb4\ucc45\uc784\uc740 \uc18c\uba78\ud558\uace0, \ub2e4\uc2dc \uc0c1\ub300\ubc29\uc774 \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc744 \uc8fc\uc7a5\ud560 \uc218 \uc788\uac8c \ub418\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub2e4","\ud55c\ubc88 \uc774\ud589\uc81c\uacf5\uc744 \ud558\uba74 \uadf8 \uc774\ud6c4\ub85c\ub294 \uc601\uad6c\ud788 \uc0c1\ub300\ubc29\uc774 \ud56d\ubcc0\uad8c\uc744 \ud589\uc0ac\ud560 \uc218 \uc5c6\ub2e4","\uc774\ud589\uc81c\uacf5\uc758 \uc911\ub2e8\uc740 \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uacfc \uc544\ubb34\ub7f0 \uad00\ub828\uc774 \uc5c6\ub2e4","\uc774\ud589\uc81c\uacf5\uc744 \uc911\ub2e8\ud574\ub3c4 \uc0c1\ub300\ubc29\uc740 \uc5ec\uc804\ud788 \uc544\ubb34\ub7f0 \uad8c\ub9ac\ub97c \ud589\uc0ac\ud560 \uc218 \uc5c6\ub2e4"],t.s)
B.aO2=s(["\uc774\ud589\uc81c\uacf5\uc744 \uc911\ub2e8\ud558\uba74 \uc0c1\ub300\ubc29\uc758 \uc774\ud589\uc9c0\uccb4\ucc45\uc784\uc740 \uc18c\uba78\ud558\uace0, \ub2e4\uc2dc \uc0c1\ub300\ubc29\uc774 \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc744 \uc8fc\uc7a5\ud560 \uc218 \uc788\uac8c \ub418\ub294 \uac83\uc774 \uc6d0\uce59"],t.s)
B.aKJ=s(["\uc774\ud589\uc81c\uacf5\uc758 \uacc4\uc18d\uc131\uacfc \ud56d\ubcc0\uad8c\uc758 \ubd80\ud65c"],t.s)
B.byZ=new A.a("gen_cl_concurrent_23","civil_law","\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c",null,"\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \uc778\uc815\ub418\ub294 \ucc44\ubb34\uc790\uac00 \uc774\ud589\uc81c\uacf5\uc744 \ud558\uc600\ub2e4\uac00 \uc774\ub97c \uc911\ub2e8\ud55c \uacbd\uc6b0\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.amv,0,"\ud310\ub840\ub294 \uc774\ud589\uc81c\uacf5\uc774 \uacc4\uc18d\ub418\uc5b4\uc57c \uc0c1\ub300\ubc29\uc758 \uc774\ud589\uc9c0\uccb4\ucc45\uc784\uc774 \uc720\uc9c0\ub41c\ub2e4\uace0 \ubcf4\uc544, \uc77c\ub2e8 \uc774\ud589\uc81c\uacf5\uc744 \ud558\uc600\ub354\ub77c\ub3c4 \uc774\ud6c4 \uadf8 \uc81c\uacf5\uc744 \uc911\ub2e8\ud558\uba74 \uc0c1\ub300\ubc29\uc740 \ub2e4\uc2dc \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc744 \uc8fc\uc7a5\ud558\uc5ec \uc790\uc2e0\uc758 \ucc44\ubb34\uc774\ud589\uc744 \uac70\uc808\ud560 \uc218 \uc788\ub2e4\uace0 \ubcf8\ub2e4.",B.aO2,B.aKJ,null)
B.aK_=s(["\ud574\uc81c\ub97c \uc704\ud55c \ucd5c\uace0\ub97c \ud558\ub824\ub294 \ucc44\uad8c\uc790\ub294 \uc790\uc2e0\ub3c4 \uc774\ud589 \ub610\ub294 \uc774\ud589\uc81c\uacf5\uc744 \ud558\uc5ec \uc0c1\ub300\ubc29\uc758 \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc744 \uc18c\uba78\uc2dc\ucf1c\uc57c \ud558\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub2e4","\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \uc788\uc5b4\ub3c4 \ucc44\uad8c\uc790\ub294 \uc790\uc2e0\uc758 \uc774\ud589 \uc5c6\uc774 \uc5b8\uc81c\ub4e0 \uc790\uc720\ub86d\uac8c \ud574\uc81c\ud560 \uc218 \uc788\ub2e4","\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uacfc \uacc4\uc57d\ud574\uc81c\uc758 \ucd5c\uace0\ub294 \uc11c\ub85c \uc544\ubb34\ub7f0 \uad00\uacc4\uac00 \uc5c6\ub2e4","\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \uc788\uc73c\uba74 \uacc4\uc57d\ud574\uc81c \uc790\uccb4\uac00 \ubd88\uac00\ub2a5\ud558\ub2e4"],t.s)
B.aT7=s(["\uc790\uc2e0\ub3c4 \uc774\ud589 \ub610\ub294 \uc774\ud589\uc81c\uacf5\uc744 \ud558\uc5ec \uc0c1\ub300\ubc29\uc758 \ud56d\ubcc0\uad8c\uc744 \uc18c\uba78\uc2dc\ucf1c\uc57c\ub9cc \uc801\ubc95\ud558\uac8c \uc774\ud589\uc9c0\uccb4\ub97c \uc774\uc720\ub85c \ud55c \ud574\uc81c\uad8c\uc744 \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4"],t.s)
B.aYz=s(["\uacc4\uc57d\ud574\uc81c \uc2dc \uc774\ud589\uc81c\uacf5\uc758 \ud544\uc694\uc131"],t.s)
B.bH9=new A.a("gen_cl_concurrent_24","civil_law","\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c",null,"\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uacfc \ucd5c\uace0(\u50ac\u544a) \uc5c6\ub294 \ud574\uc81c \uc0ac\uc774\uc758 \uad00\uacc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aK_,0,"\uc30d\ubb34\uacc4\uc57d\uc758 \ud574\uc81c\ub97c \uc704\ud574 \ucd5c\uace0\ub97c \ud558\ub294 \ucc44\uad8c\uc790\ub294, \uc0c1\ub300\ubc29\uc774 \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc744 \uac00\uc9c0\uace0 \uc788\ub294 \uacbd\uc6b0 \uc790\uc2e0\ub3c4 \uc774\ud589 \ub610\ub294 \uc774\ud589\uc81c\uacf5\uc744 \ud558\uc5ec \uc0c1\ub300\ubc29\uc758 \ud56d\ubcc0\uad8c\uc744 \uc18c\uba78\uc2dc\ucf1c\uc57c\ub9cc \uc801\ubc95\ud558\uac8c \uc774\ud589\uc9c0\uccb4\ub97c \uc774\uc720\ub85c \ud55c \ud574\uc81c\uad8c\uc744 \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4\ub294 \uac83\uc774 \ud310\ub840\uc758 \uc785\uc7a5\uc774\ub2e4.",B.aT7,B.aYz,null)
B.U_=s(["\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c \uc790\uccb4\uac00 \uc774\ud589\uc9c0\ub97c \uc815\ud558\ub294 \uae30\uc900\uc740 \uc544\ub2c8\uba70, \uc774\ud589\uc9c0\ub294 \uacc4\uc57d \ub0b4\uc6a9\uc774\ub098 \ubc95\ub960\uaddc\uc815\uc5d0 \ub530\ub77c \ubcc4\ub3c4\ub85c \uc815\ud574\uc9c4\ub2e4","\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \uc788\uc73c\uba74 \uc774\ud589\uc9c0\ub294 \ud56d\uc0c1 \ucc44\uad8c\uc790\uc758 \uc8fc\uc18c\uc9c0\ub85c \uace0\uc815\ub41c\ub2e4","\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \uc788\uc73c\uba74 \uc774\ud589\uc9c0 \uac1c\ub150 \uc790\uccb4\uac00 \uc18c\uba78\ud55c\ub2e4","\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc740 \uc774\ud589\uc9c0\ub97c \ucc44\ubb34\uc790\uc758 \uc8fc\uc18c\uc9c0\ub85c \uac15\uc81c\ub85c \ubcc0\uacbd\uc2dc\ud0a8\ub2e4"],t.s)
B.be7=s(["\uc774\ud589\uc9c0\ub294 \ub2f9\uc0ac\uc790\uc758 \ud2b9\uc57d, \ucc44\ubb34\uc758 \uc131\uc9c8, \ubc95\ub960 \uaddc\uc815\uc5d0 \ub530\ub77c \uc815\ud574\uc9c0\ub294 \uac83\uc774\uc9c0, \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \uc774\ud589\uc9c0 \uc790\uccb4\ub97c \uacb0\uc815\uc9d3\ub294 \uae30\uc900\uc774 \ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4"],t.s)
B.a1T=s(["\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c\uacfc \uc774\ud589\uc9c0\uc758 \uad00\uacc4"],t.s)
B.bGf=new A.a("gen_cl_concurrent_25","civil_law","\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c",null,"\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \uc778\uc815\ub418\ub294 \ucc44\ubb34\uc758 \uc774\ud589\uc9c0\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.U_,0,"\uc774\ud589\uc9c0(\uc774\ud589\uc7a5\uc18c)\ub294 \ub2f9\uc0ac\uc790\uc758 \ud2b9\uc57d, \ucc44\ubb34\uc758 \uc131\uc9c8, \ubc95\ub960 \uaddc\uc815(\uc9c0\ucc38\ucc44\ubb34\xb7\ucd94\uc2ec\ucc44\ubb34 \uc6d0\uce59 \ub4f1)\uc5d0 \ub530\ub77c \uc815\ud574\uc9c0\ub294 \uac83\uc774\uc9c0, \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \uc774\ud589\uc9c0 \uc790\uccb4\ub97c \uacb0\uc815\uc9d3\ub294 \uae30\uc900\uc774 \ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4.",B.be7,B.a1T,null)
B.aQM=s(["\uacf5\ub3d9\ub9e4\ub3c4\uc778 \uc911 \uc77c\ubd80\ub9cc \uc774\ud589\uc81c\uacf5\uc744 \ud55c \uacbd\uc6b0, \ub9e4\uc218\uc778\uc740 \uc804\uccb4 \uc774\ud589\uc774 \uac16\ucd94\uc5b4\uc9c0\uc9c0 \uc54a\uc558\ub2e4\uba74 \ud56d\ubcc0\uad8c\uc744 \ud589\uc0ac\ud560 \uc218 \uc788\ub294 \uacbd\uc6b0\uac00 \ub9ce\ub2e4","\uacf5\ub3d9\ub9e4\ub3c4\uc778 \uc911 \ud55c \uba85\ub9cc \uc774\ud589\uc81c\uacf5\uc744 \ud558\uba74 \ub9e4\uc218\uc778\uc740 \ud56d\ubcc0\uad8c\uc744 \uc808\ub300 \ud589\uc0ac\ud560 \uc218 \uc5c6\ub2e4","\ub2e4\uc218\ub2f9\uc0ac\uc790 \uad00\uacc4\uc5d0\uc11c\ub294 \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \uc131\ub9bd\ud560 \uc5ec\uc9c0\uac00 \uc804\ud600 \uc5c6\ub2e4","\uacf5\ub3d9\ub9e4\ub3c4\uc778 \uac01\uc790\uc758 \uc774\ud589 \uc5ec\ubd80\ub294 \uc11c\ub85c \uc644\uc804\ud788 \ubb34\uad00\ud558\uac8c \ucde8\uae09\ub41c\ub2e4"],t.s)
B.Wb=s(["\uae09\ubd80 \uc804\uccb4\uac00 \uc644\uc804\ud788 \uc81c\uacf5\ub41c \uac83\uc73c\ub85c \ubcf4\uae30 \uc5b4\ub824\uc6cc, \ub9e4\uc218\uc778\uc740 \uc5ec\uc804\ud788 \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc744 \ud589\uc0ac\ud560 \uc218 \uc788\ub294 \uacbd\uc6b0\uac00 \ub9ce\ub2e4"],t.s)
B.bcA=s(["\ub2e4\uc218\ub2f9\uc0ac\uc790 \uad00\uacc4\uc5d0\uc11c\uc758 \ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c"],t.s)
B.bzn=new A.a("gen_cl_concurrent_26","civil_law","\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c",null,"\uc218\uc778\uc758 \ub2f9\uc0ac\uc790\uac00 \uad00\ub828\ub41c \ub2e4\uc218\ub2f9\uc0ac\uc790 \ucc44\uad8c\uad00\uacc4\uc5d0\uc11c \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \ubb38\uc81c\ub418\ub294 \uacbd\uc6b0\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aQM,0,"\uacc4\uc57d\uc758 \uae09\ubd80\uac00 \uc804\uccb4\ub85c\uc11c \ud558\ub098\ub85c \ud30c\uc545\ub418\ub294 \uacbd\uc6b0, \uacf5\ub3d9\ub9e4\ub3c4\uc778 \uc911 \uc77c\ubd80\ub9cc \uc774\ud589\uc744 \uc81c\uacf5\ud558\uace0 \ub098\uba38\uc9c0\ub294 \uc774\ud589\ud558\uc9c0 \uc54a\uc558\ub2e4\uba74 \uae09\ubd80 \uc804\uccb4\uac00 \uc644\uc804\ud788 \uc81c\uacf5\ub41c \uac83\uc73c\ub85c \ubcf4\uae30 \uc5b4\ub824\uc6cc, \ub9e4\uc218\uc778\uc740 \uc5ec\uc804\ud788 \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc744 \ud589\uc0ac\ud560 \uc218 \uc788\ub294 \uacbd\uc6b0\uac00 \ub9ce\ub2e4.",B.Wb,B.bcA,null)
B.ajo=s(["\ucc44\ubb34\uc790\ub294 \uc591\uc218\uc778\uc5d0 \ub300\ud574\uc11c\ub3c4 \uc6d0\ub798 \uc591\ub3c4\uc778\uc5d0\uac8c \uc8fc\uc7a5\ud560 \uc218 \uc788\uc5c8\ub358 \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc744 \uadf8\ub300\ub85c \uc8fc\uc7a5\ud560 \uc218 \uc788\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub2e4","\ucc44\uad8c\uc591\ub3c4\uac00 \uc788\uc73c\uba74 \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc740 \ub2f9\uc5f0\ud788 \uc18c\uba78\ud55c\ub2e4","\ucc44\ubb34\uc790\ub294 \uc591\uc218\uc778\uc5d0\uac8c\ub294 \uc5b4\ub5a0\ud55c \ud56d\ubcc0\ub3c4 \uc8fc\uc7a5\ud560 \uc218 \uc5c6\ub2e4","\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc740 \ucc44\uad8c\uc591\ub3c4\uc640 \ud568\uaed8 \uc790\ub3d9\uc73c\ub85c \uc18c\uba78\ub41c \uac83\uc73c\ub85c \ucde8\uae09\ub41c\ub2e4"],t.s)
B.aBz=s(["\ucc44\ubb34\uc790\ub294 \uc6d0\ub798 \uc591\ub3c4\uc778\uc5d0\uac8c \uc8fc\uc7a5\ud560 \uc218 \uc788\uc5c8\ub358 \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc744 \uc591\uc218\uc778\uc5d0\uac8c\ub3c4 \uadf8\ub300\ub85c \uc8fc\uc7a5\ud560 \uc218 \uc788\ub2e4"],t.s)
B.ayu=s(["\ucc44\uad8c\uc591\ub3c4\uc640 \ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c\uc758 \ub300\ud56d\ub825"],t.s)
B.bB9=new A.a("gen_cl_concurrent_27","civil_law","\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c",null,"\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \ubd99\uc740 \ucc44\uad8c\uc744 \uc591\uc218\ud55c \ucc44\uad8c\uc591\uc218\uc778\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.ajo,0,"\ucc44\uad8c\uc591\ub3c4\uac00 \uc788\ub354\ub77c\ub3c4 \ucc44\ubb34\uc790\uc758 \uc9c0\uc704\ub098 \ud56d\ubcc0\uad8c\uc740 \uc6d0\uce59\uc801\uc73c\ub85c \uc601\ud5a5\uc744 \ubc1b\uc9c0 \uc54a\uc73c\ubbc0\ub85c, \ucc44\ubb34\uc790\ub294 \uc6d0\ub798 \uc591\ub3c4\uc778(\uc6d0\ucc44\uad8c\uc790)\uc5d0\uac8c \uc8fc\uc7a5\ud560 \uc218 \uc788\uc5c8\ub358 \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc744 \uc591\uc218\uc778\uc5d0\uac8c\ub3c4 \uadf8\ub300\ub85c \uc8fc\uc7a5\ud560 \uc218 \uc788\ub2e4.",B.aBz,B.ayu,null)
B.acM=s(["\uc774\ud589\uc0c1 \uacac\ub828\uc131\uc740 \uc11c\ub85c \ub300\uac00\uad00\uacc4\uc5d0 \uc788\ub294 \ucc44\ubb34\uac00 \ub3d9\uc2dc\uc5d0 \uc774\ud589\ub418\uc5b4\uc57c \ud568\uc744 \ub73b\ud558\uba70, \uc774\uac83\uc774 \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc758 \uc774\ub860\uc801 \uadfc\uac70\uac00 \ub41c\ub2e4","\uc774\ud589\uc0c1 \uacac\ub828\uc131\uc740 \ud6c4\ubc1c\uc801 \uc774\ud589\ubd88\ub2a5 \uc2dc \ubc18\ub300\uae09\ubd80\uc758 \uc6b4\uba85\uc744 \uc815\ud558\ub294 \ubb38\uc81c\uc774\ub2e4(\uc774\ub294 \uc874\uc18d\uc0c1 \uacac\ub828\uc131\uc5d0 \ud574\ub2f9\ud568)","\uc774\ud589\uc0c1 \uacac\ub828\uc131\uc740 \uacc4\uc57d \uc131\ub9bd \uc790\uccb4\uc758 \uacac\ub828\uc131\uc744 \uc758\ubbf8\ud55c\ub2e4(\uc774\ub294 \uc131\ub9bd\uc0c1 \uacac\ub828\uc131\uc5d0 \ud574\ub2f9\ud568)","\uc774\ud589\uc0c1 \uacac\ub828\uc131\uc740 \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uacfc \ubb34\uad00\ud55c \uac1c\ub150\uc774\ub2e4"],t.s)
B.a8s=s(["\uc774\ud589\uc0c1 \uacac\ub828\uc131\uc740 \ub300\uac00\uad00\uacc4\uc5d0 \uc788\ub294 \ucc44\ubb34\ub97c \uc11c\ub85c \ub3d9\uc2dc\uc5d0 \uc774\ud589\ud558\uc5ec\uc57c \ud55c\ub2e4\ub294 \uac83\uc73c\ub85c, \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c \uc81c\ub3c4\uc758 \uc774\ub860\uc801 \uadfc\uac70\uac00 \ub41c\ub2e4"],t.s)
B.a5R=s(["\uc30d\ubb34\uacc4\uc57d \uacac\ub828\uc131\uc758 \uc138 \uce21\uba74 \u2014 \uc774\ud589\uc0c1 \uacac\ub828\uc131"],t.s)
B.bQ3=new A.a("gen_cl_concurrent_28","civil_law","\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c",null,'\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uacfc \uad00\ub828\ud558\uc5ec "\uc30d\ubb34\uacc4\uc57d\uc758 \uacac\ub828\uc131"\uc774 \uac16\ub294 \uc138 \uac00\uc9c0 \uce21\uba74 \uc911 \uc774\ud589\uc0c1 \uacac\ub828\uc131\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?',B.acM,0,"\uc30d\ubb34\uacc4\uc57d\uc758 \uacac\ub828\uc131\uc740 \uc131\ub9bd\uc0c1 \uacac\ub828\uc131, \uc774\ud589\uc0c1 \uacac\ub828\uc131, \uc874\uc18d\uc0c1 \uacac\ub828\uc131 \uc138 \uce21\uba74\uc73c\ub85c \uc124\uba85\ub418\ub294\ub370, \uc774 \uc911 \uc774\ud589\uc0c1 \uacac\ub828\uc131\uc740 \ub300\uac00\uad00\uacc4\uc5d0 \uc788\ub294 \ucc44\ubb34\ub97c \uc11c\ub85c \ub3d9\uc2dc\uc5d0 \uc774\ud589\ud558\uc5ec\uc57c \ud55c\ub2e4\ub294 \uac83\uc73c\ub85c, \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c \uc81c\ub3c4\uc758 \uc774\ub860\uc801 \uadfc\uac70\uac00 \ub41c\ub2e4.",B.a8s,B.a5R,null)
B.aYA=s(["\ud2b9\uc57d\uc774 \uc5c6\ub294 \ud55c \uc11c\ub85c \ub300\uac00\uad00\uacc4\uc5d0 \uc788\ub294 \ucc44\ubb34\ub85c\uc11c \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uac00 \ubb38\uc81c\ub420 \uc218 \uc788\ub2e4","\uac00\ub9f9\ubcf8\ubd80\uc758 \uc758\ubb34\ub9cc \uc874\uc7ac\ud558\uace0 \uac00\ub9f9\uc810\uc758 \ub300\uae08\uc9c0\uae09\uc758\ubb34\ub294 \uc560\ucd08\uc5d0 \ubc1c\uc0dd\ud558\uc9c0 \uc54a\ub294\ub2e4","\uac00\ub9f9\uacc4\uc57d\uc5d0\ub294 \uc30d\ubb34\uacc4\uc57d\uc758 \ubc95\ub9ac\uac00 \uc804\ud600 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4","\ubb3c\ud488\uacf5\uae09\uc758\ubb34\uc640 \ub300\uae08\uc9c0\uae09\uc758\ubb34\ub294 \ud56d\uc0c1 \uc644\uc804\ud788 \ubb34\uad00\ud55c \ubcc4\uac1c\uc758 \uacc4\uc57d\uc73c\ub85c \ucde8\uae09\ub41c\ub2e4"],t.s)
B.aIL=s(["\ubb3c\ud488 \uacf5\uae09\uc774\ub77c\ub294 \uae09\ubd80\uc640 \uadf8 \ub300\uac00\uc778 \ub300\uae08\uc9c0\uae09\uc774 \uc11c\ub85c \uacb0\ud569\ub41c \uc30d\ubb34\uacc4\uc57d\uc801 \uc694\uc18c\ub97c \ud3ec\ud568\ud558\ubbc0\ub85c, \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uac00 \ubb38\uc81c\ub420 \uc218 \uc788\ub2e4"],t.s)
B.aMo=s(["\uac00\ub9f9\uacc4\uc57d\uacfc \ub3d9\uc2dc\uc774\ud589\uad00\uacc4"],t.s)
B.bzV=new A.a("gen_cl_concurrent_29","civil_law","\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c",null,"\uac00\ub9f9\uacc4\uc57d(\ud504\ub79c\ucc28\uc774\uc988 \uacc4\uc57d)\uc5d0\uc11c \uac00\ub9f9\ubcf8\ubd80\uc758 \ubb3c\ud488\uacf5\uae09\uc758\ubb34\uc640 \uac00\ub9f9\uc810\uc758 \ubb3c\ud488\ub300\uae08\uc9c0\uae09\uc758\ubb34\uc758 \uad00\uacc4\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.aYA,0,"\uac00\ub9f9\uacc4\uc57d\ub3c4 \uc2e4\uc9c8\uc801\uc73c\ub85c \ubb3c\ud488 \uacf5\uae09\uc774\ub77c\ub294 \uae09\ubd80\uc640 \uadf8 \ub300\uac00\uc778 \ub300\uae08\uc9c0\uae09\uc774 \uc11c\ub85c \uacb0\ud569\ub41c \uc30d\ubb34\uacc4\uc57d\uc801 \uc694\uc18c\ub97c \ud3ec\ud568\ud558\ubbc0\ub85c, \ud2b9\uc57d\uc774 \uc5c6\ub294 \ud55c \ubb3c\ud488\uacf5\uae09\uc758\ubb34\uc640 \ub300\uae08\uc9c0\uae09\uc758\ubb34 \uc0ac\uc774\uc5d0 \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uac00 \ubb38\uc81c\ub420 \uc218 \uc788\ub2e4.",B.aIL,B.aMo,null)
B.aSL=s(["\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc740 \uc30d\ubb34\uacc4\uc57d\uc5d0\uc11c \ub300\uac00\uad00\uacc4 \uc788\ub294 \ucc44\ubb34 \uc0ac\uc774\uc5d0 \uc778\uc815\ub418\ub294 \uc5f0\uae30\uc801 \ud56d\ubcc0\uad8c\uc774\ub2e4","\ud56d\ubcc0\uad8c\uc774 \uc788\uc73c\uba74 \uc774\ud589\uc9c0\uccb4\ucc45\uc784\uc774 \ubc1c\uc0dd\ud558\uc9c0 \uc54a\uace0, \uc18c\uc1a1\uc5d0\uc11c\ub294 \uc0c1\ud658\uae09\ubd80\ud310\uacb0\uc774 \ub0b4\ub824\uc9c4\ub2e4","\ud56d\ubcc0\uad8c\uc774 \ubd99\uc740 \ucc44\uad8c\uc744 \uc790\ub3d9\ucc44\uad8c\uc73c\ub85c \ud558\ub294 \uc0c1\uacc4\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \ud5c8\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4","\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc740 \ucc44\uad8c\uc758 \uc18c\uba78\uc2dc\ud6a8 \uc9c4\ud589\uc744 \ud56d\uc0c1 \uc815\uc9c0\uc2dc\ud0a8\ub2e4"],t.s)
B.a5r=s(["\ucc44\uad8c \uc790\uccb4\uc758 \uc18c\uba78\uc2dc\ud6a8 \uc9c4\ud589\uc744 \uc815\uc9c0\uc2dc\ud0a4\ub294 \ud6a8\ub825\uc740 \uc5c6\ub2e4\ub294 \uac83\uc774 \ud310\ub840\uc758 \uc785\uc7a5"],t.s)
B.b9_=s(["\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c \uc885\ud569\uc815\ub9ac"],t.s)
B.bBH=new A.a("gen_cl_concurrent_30","civil_law","\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c",null,"\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc5d0 \uad00\ud55c \uc885\ud569\uc801\uc778 \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aSL,3,"\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc740 \uc5f0\uae30\uc801 \ud56d\ubcc0\uad8c\uc73c\ub85c\uc11c \uc774\ud589\uc9c0\uccb4\ucc45\uc784 \uc800\uc9c0, \uc0c1\ud658\uae09\ubd80\ud310\uacb0, \uc0c1\uacc4 \uc81c\ud55c \ub4f1\uc758 \ud6a8\uacfc\ub97c \uac00\uc9c0\uc9c0\ub9cc, \ucc44\uad8c \uc790\uccb4\uc758 \uc18c\uba78\uc2dc\ud6a8 \uc9c4\ud589\uc744 \uc815\uc9c0\uc2dc\ud0a4\ub294 \ud6a8\ub825\uc740 \uc5c6\ub2e4\ub294 \uac83\uc774 \ud310\ub840\uc758 \uc785\uc7a5\uc774\ubbc0\ub85c \ud574\ub2f9 \uc124\uba85\uc740 \uc633\uc9c0 \uc54a\ub2e4.",B.a5r,B.b9_,null)
B.b5H=s(["\uad8c\ub9ac\uc790\uac00 \uad8c\ub9ac\uc758 \uc874\uc7ac\ub97c \ud604\uc2e4\uc801\uc73c\ub85c \uc548 \ub0a0\ubd80\ud130 \uae30\uc0b0\ud55c\ub2e4","\uad8c\ub9ac\ub97c \ud589\uc0ac\ud560 \uc218 \uc788\ub294 \ub54c(\ubc95\ub960\uc0c1 \uc7a5\uc560\uac00 \uc5c6\uc5b4\uc9c4 \ub54c)\ubd80\ud130 \uae30\uc0b0\ud55c\ub2e4","\ucc44\uad8c\uc774 \uc131\ub9bd\ud55c \ub0a0\ubd80\ud130 \ud56d\uc0c1 \uae30\uc0b0\ud55c\ub2e4","\uc774\ud589\uc9c0\uccb4\uac00 \ubc1c\uc0dd\ud55c \ub0a0\ubd80\ud130\ub9cc \uae30\uc0b0\ud55c\ub2e4"],t.s)
B.a6h=s(["\uad8c\ub9ac \ud589\uc0ac\uc5d0 \ubc95\ub960\uc0c1 \uc7a5\uc560\uac00 \uc5c6\uc5b4\uc9c4 \ub54c"],t.s)
B.a_V=s(["\uc18c\uba78\uc2dc\ud6a8 \uae30\uc0b0\uc810"],t.s)
B.byp=new A.a("gen_cl_limitation_1","civil_law","\uc18c\uba78\uc2dc\ud6a8",null,"\uc18c\uba78\uc2dc\ud6a8\uc758 \uae30\uc0b0\uc810\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.b5H,1,'\ubbfc\ubc95 \uc81c166\uc870\uc758 "\uad8c\ub9ac\ub97c \ud589\uc0ac\ud560 \uc218 \uc788\ub294 \ub54c"\ub780 \uad8c\ub9ac \ud589\uc0ac\uc5d0 \ubc95\ub960\uc0c1 \uc7a5\uc560\uac00 \uc5c6\uc5b4\uc9c4 \ub54c\ub97c \uc758\ubbf8\ud558\uba70, \uad8c\ub9ac\uc790\uac00 \uc0ac\uc2e4\uc0c1 \uad8c\ub9ac\uc758 \uc874\uc7ac\ub97c \ubab0\ub790\ub2e4\ub294 \uc0ac\uc815\ub9cc\uc73c\ub85c\ub294 \uae30\uc0b0\uc810\uc774 \ub2a6\ucdb0\uc9c0\uc9c0 \uc54a\ub294\ub2e4.',B.a6h,B.a_V,null)
B.age=s(["\ubbfc\uc0ac\ucc44\uad8c\uc758 \uc18c\uba78\uc2dc\ud6a8 \uae30\uac04\uc740 \uc6d0\uce59\uc801\uc73c\ub85c 10\ub144\uc774\ub2e4","\uc0c1\ud589\uc704\ub85c \uc778\ud55c \ucc44\uad8c\uc758 \uc18c\uba78\uc2dc\ud6a8 \uae30\uac04\uc740 \uc6d0\uce59\uc801\uc73c\ub85c 5\ub144\uc774\ub2e4","\uc18c\uc720\uad8c\uc740 \uc18c\uba78\uc2dc\ud6a8\uc5d0 \uac78\ub9ac\uc9c0 \uc54a\ub294\ub2e4","\uc774\uc790\xb7\ubd80\uc591\ub8cc \ub4f1 1\ub144 \uc774\ub0b4\uc758 \uc815\uae30\uae08 \ucc44\uad8c\ub3c4 \uc77c\ubc18\uc6d0\uce59\uc5d0 \ub530\ub77c 10\ub144\uc758 \uc2dc\ud6a8\uac00 \uc801\uc6a9\ub41c\ub2e4"],t.s)
B.aU6=s(["\uc81c163\uc870\uc5d0 \ub530\ub77c 3\ub144\uc758 \ub2e8\uae30\uc18c\uba78\uc2dc\ud6a8\uac00 \uc801\uc6a9"],t.s)
B.aDY=s(["\ucc44\uad8c \uc18c\uba78\uc2dc\ud6a8 \uae30\uac04","\ub2e8\uae30\uc18c\uba78\uc2dc\ud6a8"],t.s)
B.bDW=new A.a("gen_cl_limitation_2","civil_law","\uc18c\uba78\uc2dc\ud6a8",null,"\ucc44\uad8c\uc758 \uc18c\uba78\uc2dc\ud6a8 \uae30\uac04\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.age,3,"\uc774\uc790\xb7\ubd80\uc591\ub8cc\xb7\uae09\ub8cc \ub4f1 1\ub144 \uc774\ub0b4\uc758 \uc815\uae30\ub85c \uc9c0\uae09\ub418\ub294 \ucc44\uad8c\uc740 \uc81c163\uc870\uc5d0 \ub530\ub77c 3\ub144\uc758 \ub2e8\uae30\uc18c\uba78\uc2dc\ud6a8\uac00 \uc801\uc6a9\ub418\uba70, \uc77c\ubc18 \ucc44\uad8c\uacfc \uac19\uc774 10\ub144\uc774 \uc801\uc6a9\ub418\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4.",B.aU6,B.aDY,null)
B.arS=s(["\uccad\uad6c","\uc555\ub958\xb7\uac00\uc555\ub958\xb7\uac00\ucc98\ubd84","\uc2b9\uc778","\uc2dc\ud6a8\uae30\uac04 \uc911\uc758 \ub2e8\uc21c\ud55c \uad8c\ub9ac\ubd88\ud589\uc0ac"],t.s)
B.aRk=s(["\uccad\uad6c, \uc555\ub958\xb7\uac00\uc555\ub958\xb7\uac00\ucc98\ubd84, \uc2b9\uc778 3\uac00\uc9c0"],t.s)
B.aC3=s(["\uc18c\uba78\uc2dc\ud6a8 \uc911\ub2e8\uc0ac\uc720"],t.s)
B.bIr=new A.a("gen_cl_limitation_3","civil_law","\uc18c\uba78\uc2dc\ud6a8",null,"\uc18c\uba78\uc2dc\ud6a8\uc758 \uc911\ub2e8 \uc0ac\uc720(\ubbfc\ubc95 \uc81c168\uc870)\uc5d0 \ud574\ub2f9\ud558\uc9c0 \uc54a\ub294 \uac83\uc740?",B.arS,3,"\uc18c\uba78\uc2dc\ud6a8\uc758 \uc911\ub2e8 \uc0ac\uc720\ub294 \uccad\uad6c, \uc555\ub958\xb7\uac00\uc555\ub958\xb7\uac00\ucc98\ubd84, \uc2b9\uc778 3\uac00\uc9c0\uc774\ub2e4. \ub2e8\uc21c\ud788 \uad8c\ub9ac\ub97c \ud589\uc0ac\ud558\uc9c0 \uc54a\ub294 \uc0c1\ud0dc\ub294 \uc624\ud788\ub824 \uc2dc\ud6a8 \uc9c4\ud589\uc758 \uc804\uc81c\uc77c \ubfd0 \uc911\ub2e8 \uc0ac\uc720\uac00 \ub420 \uc218 \uc5c6\ub2e4.",B.aRk,B.aC3,null)
B.aqs=s(["\uc911\ub2e8\uc740 \uadf8\ub54c\uae4c\uc9c0 \uacbd\uacfc\ud55c \uc2dc\ud6a8\uae30\uac04\uc744 \uadf8\ub300\ub85c \uc720\uc9c0\ud55c \ucc44 \uc9c4\ud589\uc744 \uba48\ucd94\ub294 \uac83\uc774\ub2e4","\uc911\ub2e8 \uc0ac\uc720\uac00 \uc885\ub8cc\ub418\uba74 \uc2dc\ud6a8\uae30\uac04\uc740 \ucc98\uc74c\ubd80\ud130 \ub2e4\uc2dc \uc9c4\ud589\ub41c\ub2e4","\uc815\uc9c0\ub294 \uacbd\uacfc\ud55c \uc2dc\ud6a8\uae30\uac04\uc744 \ubb34\ud6a8\ub85c \ud558\uace0 \ucc98\uc74c\ubd80\ud130 \ub2e4\uc2dc \uacc4\uc0b0\ud558\ub294 \uc81c\ub3c4\uc774\ub2e4","\uc911\ub2e8\uacfc \uc815\uc9c0\ub294 \ubc95\uc801 \ud6a8\uacfc\uac00 \ub3d9\uc77c\ud558\uc5ec \uad6c\ubcc4\ud560 \uc2e4\uc775\uc774 \uc5c6\ub2e4"],t.s)
B.asY=s(["\uc911\ub2e8\uc0ac\uc720 \uc885\ub8cc \ud6c4 \uc2dc\ud6a8\uae30\uac04\uc774 \ucc98\uc74c\ubd80\ud130 \uc0c8\ub85c \uc9c4\ud589"],t.s)
B.aY_=s(["\uc18c\uba78\uc2dc\ud6a8 \uc911\ub2e8\uacfc \uc815\uc9c0\uc758 \ucc28\uc774"],t.s)
B.bK3=new A.a("gen_cl_limitation_4","civil_law","\uc18c\uba78\uc2dc\ud6a8",null,"\uc18c\uba78\uc2dc\ud6a8\uc758 \uc911\ub2e8\uacfc \uc815\uc9c0\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aqs,1,"\uc2dc\ud6a8\uc758 \uc911\ub2e8\uc740 \uadf8\ub54c\uae4c\uc9c0 \uc9c4\ud589\ub41c \uc2dc\ud6a8\uae30\uac04\uc758 \ud6a8\ub825\uc744 \uc18c\uba78\uc2dc\ud0a4\uace0 \uc911\ub2e8\uc0ac\uc720 \uc885\ub8cc \ud6c4 \uc2dc\ud6a8\uae30\uac04\uc774 \ucc98\uc74c\ubd80\ud130 \uc0c8\ub85c \uc9c4\ud589\ub418\ub294 \uac83\uc774\uace0, \uc815\uc9c0\ub294 \uc774\ubbf8 \uacbd\uacfc\ud55c \uae30\uac04\uc744 \uc720\uc9c0\ud55c \ucc44 \uc77c\uc815 \uae30\uac04\ub9cc \uc2dc\ud6a8\uc644\uc131\uc744 \uc720\uc608\ud558\ub294 \uac83\uc774\ub77c\ub294 \uc810\uc5d0\uc11c \ub2e4\ub974\ub2e4.",B.asY,B.aY_,null)
B.a5N=s(["\ucc44\ubb34\uc790\uac00 \uc2dc\ud6a8\uc774\uc775\uc744 \ubbf8\ub9ac \ud3ec\uae30\ud558\ub294 \uc758\uc0ac\ud45c\uc2dc\uc774\uae30 \ub54c\ubb38\uc774\ub2e4","\ucc44\ubb34\uc790\uac00 \ucc44\uad8c\uc758 \uc874\uc7ac\ub97c \uc778\uc815\ud558\ub294 \ucde8\uc9c0\uc758 \uad00\ub150\uc758 \ud1b5\uc9c0\uc774\uae30 \ub54c\ubb38\uc774\ub2e4","\ucc44\uad8c\uc790\uac00 \uc0c8\ub85c\uc6b4 \uacc4\uc57d\uc744 \uccb4\uacb0\ud55c \uac83\uc73c\ub85c \ubcf4\uae30 \ub54c\ubb38\uc774\ub2e4","\uc2b9\uc778\uc740 \ubc95\uc6d0\uc758 \uc7ac\ud310\uc744 \uac70\uccd0\uc57c\ub9cc \ud6a8\ub825\uc774 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4"],t.s)
B.ark=s(["\ucc44\uad8c\uc774 \uc874\uc7ac\ud568\uc744 \uc778\uc2dd\ud558\uace0 \uc788\ub2e4\ub294 \uac83\uc744 \ud45c\uc2dc\ud558\ub294 \uad00\ub150\uc758 \ud1b5\uc9c0"],t.s)
B.anU=s(["\uc2b9\uc778\uc758 \uc758\ubbf8"],t.s)
B.bye=new A.a("gen_cl_limitation_5","civil_law","\uc18c\uba78\uc2dc\ud6a8",null,'\ucc44\ubb34\uc758 "\uc2b9\uc778"\uc774 \uc18c\uba78\uc2dc\ud6a8 \uc911\ub2e8 \uc0ac\uc720\uac00 \ub418\ub294 \uc774\uc720\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?',B.a5N,1,"\uc2b9\uc778\uc740 \ucc44\ubb34\uc790\uac00 \ucc44\uad8c\uc790\uc5d0 \ub300\ud574 \uadf8 \ucc44\uad8c\uc774 \uc874\uc7ac\ud568\uc744 \uc778\uc2dd\ud558\uace0 \uc788\ub2e4\ub294 \uac83\uc744 \ud45c\uc2dc\ud558\ub294 \uad00\ub150\uc758 \ud1b5\uc9c0\ub85c\uc11c, \uc77c\ubd80 \ubcc0\uc81c\ub098 \uc774\uc790 \uc9c0\uae09\ub3c4 \uc2b9\uc778\uc5d0 \ud574\ub2f9\ud560 \uc218 \uc788\ub2e4.",B.ark,B.anU,null)
B.a7y=s(["\uc18c\uba78\uc2dc\ud6a8\uac00 \uc644\uc131\ub41c \ub54c\ubd80\ud130 \uc7a5\ub798\ub97c \ud5a5\ud574\uc11c\ub9cc \uad8c\ub9ac\uac00 \uc18c\uba78\ud55c\ub2e4","\uc18c\uba78\uc2dc\ud6a8\uc758 \ud6a8\ub825\uc740 \uae30\uc0b0\uc77c\ub85c \uc18c\uae09\ud558\uc5ec \ubc1c\uc0dd\ud55c\ub2e4","\uc18c\uba78\uc2dc\ud6a8\uac00 \uc644\uc131\ub418\uba74 \ubc95\uc6d0\uc758 \uc9c1\uad8c \ud310\ub2e8 \uc5c6\uc774\ub294 \ud6a8\ub825\uc774 \ubc1c\uc0dd\ud558\uc9c0 \uc54a\ub294\ub2e4","\uc18c\uba78\uc2dc\ud6a8 \uc644\uc131 \ud6c4\uc5d0\ub3c4 \ucc44\ubb34\uc790\ub294 \uc5b8\uc81c\ub4e0\uc9c0 \uc790\uc720\ub86d\uac8c \uc2dc\ud6a8\uc774\uc775\uc744 \ubbf8\ub9ac \ud3ec\uae30\ud560 \uc218 \uc788\ub2e4"],t.s)
B.b52=s(["\uadf8 \uae30\uc0b0\uc77c\uc5d0 \uc18c\uae09\ud558\uc5ec \ubc1c\uc0dd"],t.s)
B.amW=s(["\uc18c\uba78\uc2dc\ud6a8 \uc644\uc131\uc758 \uc18c\uae09\ud6a8"],t.s)
B.bIu=new A.a("gen_cl_limitation_6","civil_law","\uc18c\uba78\uc2dc\ud6a8",null,"\uc18c\uba78\uc2dc\ud6a8 \uc644\uc131\uc758 \ud6a8\ub825\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.a7y,1,"\ubbfc\ubc95 \uc81c167\uc870\uc5d0 \ub530\ub77c \uc18c\uba78\uc2dc\ud6a8\uc758 \ud6a8\ub825\uc740 \uadf8 \uae30\uc0b0\uc77c\uc5d0 \uc18c\uae09\ud558\uc5ec \ubc1c\uc0dd\ud558\ubbc0\ub85c, \uc644\uc131 \uc2dc\uc810\uc774 \uc544\ub2c8\ub77c \ucc98\uc74c\ubd80\ud130 \uad8c\ub9ac\uac00 \uc874\uc7ac\ud558\uc9c0 \uc54a\uc558\ub358 \uac83\uc73c\ub85c \ucde8\uae09\ub41c\ub2e4.",B.b52,B.amW,null)
B.aoK=s(["\uc2dc\ud6a8\uc644\uc131 \ud6c4\uc758 \ud3ec\uae30\ub294 \uc720\ud6a8\ud558\ub2e4","\uc2dc\ud6a8\uc644\uc131 \uc804\uc5d0 \ubbf8\ub9ac \uc2dc\ud6a8\uc774\uc775\uc744 \ud3ec\uae30\ud558\ub294 \ud2b9\uc57d\uc740 \ubb34\ud6a8\uc774\ub2e4","\uc2dc\ud6a8\uc644\uc131 \uc804 \ud3ec\uae30\ub97c \ud5c8\uc6a9\ud558\uc9c0 \uc54a\ub294 \uc774\uc720\ub294 \ucc44\ubb34\uc790\uc5d0\uac8c \ubd88\ub9ac\ud55c \uc0ac\uc804 \ud3ec\uae30\ub97c \ub9c9\uae30 \uc704\ud568\uc774\ub2e4","\uc2dc\ud6a8\uc644\uc131 \uc804\uc774\ub77c\ub3c4 \ub2f9\uc0ac\uc790 \uac04 \ud569\uc758\ub9cc \uc788\uc73c\uba74 \uc790\uc720\ub86d\uac8c \ud3ec\uae30\ud560 \uc218 \uc788\ub2e4"],t.s)
B.ahN=s(["\uc18c\uba78\uc2dc\ud6a8\uc758 \uc774\uc775\uc740 \ubbf8\ub9ac(\uc2dc\ud6a8\uc644\uc131 \uc804\uc5d0) \ud3ec\uae30\ud558\uc9c0 \ubabb\ud55c\ub2e4"],t.s)
B.atf=s(["\uc2dc\ud6a8\uc774\uc775\uc758 \ud3ec\uae30"],t.s)
B.bzB=new A.a("gen_cl_limitation_7","civil_law","\uc18c\uba78\uc2dc\ud6a8",null,"\uc2dc\ud6a8\uc774\uc775\uc758 \ud3ec\uae30\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aoK,3,"\ubbfc\ubc95 \uc81c184\uc870 \uc81c1\ud56d\uc740 \uc18c\uba78\uc2dc\ud6a8\uc758 \uc774\uc775\uc740 \ubbf8\ub9ac(\uc2dc\ud6a8\uc644\uc131 \uc804\uc5d0) \ud3ec\uae30\ud558\uc9c0 \ubabb\ud55c\ub2e4\uace0 \uaddc\uc815\ud558\uace0 \uc788\uc73c\uba70, \uc774\ub294 \uacbd\uc81c\uc801 \uc57d\uc790\uc778 \ucc44\ubb34\uc790\uac00 \ucc44\uad8c\uc790\uc758 \uc555\ubc15\uc73c\ub85c \ubd88\ub9ac\ud558\uac8c \uc2dc\ud6a8\uc774\uc775\uc744 \ud3ec\uae30\ud558\ub294 \uac83\uc744 \ubc29\uc9c0\ud558\uae30 \uc704\ud55c \uac15\ud589\uaddc\uc815\uc774\ub2e4.",B.ahN,B.atf,null)
B.aK1=s(["\uc81c\ucc99\uae30\uac04\uc5d0\ub294 \uc911\ub2e8\xb7\uc815\uc9c0 \uc81c\ub3c4\uac00 \uc6d0\uce59\uc801\uc73c\ub85c \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4","\uc81c\ucc99\uae30\uac04\uc774 \ub3c4\uacfc\ud558\uba74 \uad8c\ub9ac\uac00 \uc7a5\ub798\ub97c \ud5a5\ud574 \uc18c\uba78\ud558\ub294 \uac83\uc774 \uc6d0\uce59\uc774\uace0 \uc18c\uae09\ud6a8\uac00 \uc5c6\ub2e4","\uc18c\uba78\uc2dc\ud6a8\ub294 \ub2f9\uc0ac\uc790\uc758 \uc6d0\uc6a9\uc774 \uc5c6\uc5b4\ub3c4 \ubc95\uc6d0\uc774 \ubc18\ub4dc\uc2dc \uc9c1\uad8c\uc73c\ub85c \uace0\ub824\ud574\uc57c \ud55c\ub2e4","\uc81c\ucc99\uae30\uac04\uc774 \uc801\uc6a9\ub418\ub294 \uad8c\ub9ac\ub294 \uc8fc\ub85c \ud615\uc131\uad8c(\ucde8\uc18c\uad8c\xb7\ud574\uc81c\uad8c \ub4f1)\uc774\ub2e4"],t.s)
B.aCt=s(["\ub2f9\uc0ac\uc790\uac00 \uc774\ub97c \uc8fc\uc7a5(\uc6d0\uc6a9)\ud558\uc5ec\uc57c \ubc95\uc6d0\uc774 \uc774\ub97c \uc7ac\ud310\uc758 \uae30\ucd08\ub85c \uc0bc\uc744 \uc218 \uc788\ub2e4"],t.s)
B.av_=s(["\uc18c\uba78\uc2dc\ud6a8\uc640 \uc81c\ucc99\uae30\uac04\uc758 \uad6c\ubd84"],t.s)
B.bIp=new A.a("gen_cl_limitation_8","civil_law","\uc18c\uba78\uc2dc\ud6a8",null,"\uc18c\uba78\uc2dc\ud6a8\uc640 \uc81c\ucc99\uae30\uac04\uc758 \ucc28\uc774\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aK1,2,"\uc18c\uba78\uc2dc\ud6a8\uc758 \uc644\uc131 \uc5ec\ubd80\ub294 \ubcc0\ub860\uc8fc\uc758 \uc6d0\uce59\uc0c1 \ub2f9\uc0ac\uc790\uac00 \uc774\ub97c \uc8fc\uc7a5(\uc6d0\uc6a9)\ud558\uc5ec\uc57c \ubc95\uc6d0\uc774 \uc774\ub97c \uc7ac\ud310\uc758 \uae30\ucd08\ub85c \uc0bc\uc744 \uc218 \uc788\ub2e4\ub294 \uac83\uc774 \ud1b5\uc124\xb7\ud310\ub840\uc774\uba70, \ubc95\uc6d0\uc774 \ub2f9\uc5f0\ud788 \uc9c1\uad8c\uc73c\ub85c \uace0\ub824\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4.",B.aCt,B.av_,null)
B.a0s=s(["\ucc44\uad8c\uc790\uac00 \uc2dc\ud6a8\uc644\uc131 \uc9c1\uc804 \uad8c\ub9ac\ub97c \ud589\uc0ac\ud558\uae30 \uace4\ub780\ud55c \ud2b9\ubcc4\ud55c \uc0ac\uc815\uc774 \uc788\uc744 \ub54c \uc77c\uc815 \uae30\uac04 \uc2dc\ud6a8\uc644\uc131\uc744 \uc720\uc608\ud558\uae30 \uc704\ud568\uc774\ub2e4","\ucc44\ubb34\uc790\uc758 \uc7ac\uc0b0\uc0c1\ud0dc\uac00 \uc545\ud654\ub418\uc5c8\uc744 \ub54c \ucc44\uad8c\uc790\ub97c \ubcf4\ud638\ud558\uae30 \uc704\ud55c \ub2f4\ubcf4 \uc81c\ub3c4\uc774\ub2e4","\uc18c\uba78\uc2dc\ud6a8 \uae30\uac04 \uc790\uccb4\ub97c \uc601\uad6c\uc801\uc73c\ub85c \uc5f0\uc7a5\ud558\uae30 \uc704\ud568\uc774\ub2e4","\ubc95\uc6d0\uc758 \uc7ac\ud310 \uc9c0\uc5f0\uc73c\ub85c \uc778\ud55c \ubd88\uc774\uc775\uc744 \ucc44\ubb34\uc790\uc5d0\uac8c \uc804\uac00\ud558\uae30 \uc704\ud568\uc774\ub2e4"],t.s)
B.VR=s(["\uad8c\ub9ac\ud589\uc0ac\uac00 \uace4\ub780\ud55c \ud2b9\ubcc4\ud55c \uc0ac\uc815\uc774 \uc788\ub294 \uacbd\uc6b0","\uadf8 \uc0ac\uc720\uac00 \uc18c\uba78\ud55c \ud6c4 \uc77c\uc815 \uae30\uac04 \uc2dc\ud6a8\uc644\uc131\uc744 \uc720\uc608"],t.s)
B.akd=s(["\uc18c\uba78\uc2dc\ud6a8 \uc815\uc9c0\uc758 \ucde8\uc9c0"],t.s)
B.bH2=new A.a("gen_cl_limitation_9","civil_law","\uc18c\uba78\uc2dc\ud6a8",null,"\uc18c\uba78\uc2dc\ud6a8 \uc815\uc9c0 \uc81c\ub3c4\uc758 \ucde8\uc9c0\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.a0s,0,"\uc81c179\uc870~182\uc870\uc758 \uc815\uc9c0 \uc81c\ub3c4\ub294 \uc2dc\ud6a8\uc644\uc131\uc774 \uc784\ubc15\ud55c \uc2dc\uc810\uc5d0 \uc81c\ud55c\ub2a5\ub825\uc790, \uc0c1\uc18d\uc7ac\uc0b0, \ubd80\ubd80\uac04 \uad8c\ub9ac \ub4f1 \uad8c\ub9ac\ud589\uc0ac\uac00 \uace4\ub780\ud55c \ud2b9\ubcc4\ud55c \uc0ac\uc815\uc774 \uc788\ub294 \uacbd\uc6b0, \uadf8 \uc0ac\uc720\uac00 \uc18c\uba78\ud55c \ud6c4 \uc77c\uc815 \uae30\uac04 \uc2dc\ud6a8\uc644\uc131\uc744 \uc720\uc608\ud574 \uad8c\ub9ac\uc790\ub97c \ubcf4\ud638\ud558\uae30 \uc704\ud55c \uac83\uc774\ub2e4.",B.VR,B.akd,null)
B.aki=s(["\uc18c\ub97c \uc81c\uae30\ud55c \ub54c","\uc7ac\ud310\uc774 \ud655\uc815\ub41c \ub54c","\ud53c\uace0\uc5d0\uac8c \uc18c\uc7a5\uc774 \uc1a1\ub2ec\ub41c \ub54c","\ubcc0\ub860\uc774 \uc885\uacb0\ub41c \ub54c"],t.s)
B.bdy=s(["\uc7ac\ud310\uc774 \ud655\uc815\ub41c \ub54c\ub85c\ubd80\ud130 \uc0c8\ub85c\uc774 \uc9c4\ud589"],t.s)
B.ame=s(["\uc7ac\ud310\uc0c1 \uccad\uad6c\uc640 \uc2dc\ud6a8 \uc7ac\uc9c4\ud589"],t.s)
B.bpA=new A.a("gen_cl_limitation_10","civil_law","\uc18c\uba78\uc2dc\ud6a8",null,"\uc7ac\ud310\uc0c1 \uccad\uad6c\ub85c \uc18c\uba78\uc2dc\ud6a8\uac00 \uc911\ub2e8\ub41c \uacbd\uc6b0, \uc0c8\ub85c\uc6b4 \uc2dc\ud6a8\uae30\uac04\uc758 \uc9c4\ud589 \uc2dc\uc810\uc740?",B.aki,1,"\uc7ac\ud310\uc0c1\uc758 \uccad\uad6c\ub85c \uc778\ud574 \uc911\ub2e8\ub41c \uc2dc\ud6a8\ub294 \uc7ac\ud310\uc774 \ud655\uc815\ub41c \ub54c\ub85c\ubd80\ud130 \uc0c8\ub85c\uc774 \uc9c4\ud589\ud55c\ub2e4(\ubbfc\ubc95 \uc81c178\uc870 \uc81c2\ud56d). \uc18c \uc81c\uae30 \uc2dc\uc810\uc774 \uc544\ub2c8\ub77c \uc7ac\ud310 \ud655\uc815 \uc2dc\uc810\uc774 \uc0c8\ub85c\uc6b4 \uae30\uc0b0\uc810\uc774 \ub41c\ub2e4\ub294 \uc810\uc5d0 \uc8fc\uc758\ud574\uc57c \ud55c\ub2e4.",B.bdy,B.ame,null)
B.bg7=s(["\uc774\ud589\uc9c0\uccb4\ub294 \uc774\ud589\uc774 \uac00\ub2a5\ud568\uc5d0\ub3c4 \uc774\ud589\uae30\uc5d0 \uc774\ud589\ud558\uc9c0 \uc54a\ub294 \uac83\uc774\ub2e4","\uc774\ud589\ubd88\ub2a5\uc740 \ucc44\ubb34 \uc131\ub9bd \ud6c4 \uc774\ud589\uc774 \ubd88\uac00\ub2a5\ud558\uac8c \ub41c \uac83\uc774\ub2e4","\ubd88\uc644\uc804\uc774\ud589\uc740 \uc774\ud589\uc744 \ud558\uc600\uc73c\ub098 \uadf8 \ub0b4\uc6a9\uc774 \ucc44\ubb34 \ub0b4\uc6a9\uc5d0 \uc887\uc740 \uac83\uc774 \uc544\ub2cc \uacbd\uc6b0\uc774\ub2e4","\uc774\ud589\uc9c0\uccb4\xb7\uc774\ud589\ubd88\ub2a5\xb7\ubd88\uc644\uc804\uc774\ud589\uc740 \ubaa8\ub450 \ucc44\ubb34\uc790\uc758 \uadc0\ucc45\uc0ac\uc720\ub97c \uc694\uac74\uc73c\ub85c \ud558\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.aFk=s(["\uc6d0\uce59\uc801\uc73c\ub85c \ucc44\ubb34\uc790\uc758 \uadc0\ucc45\uc0ac\uc720(\uace0\uc758\xb7\uacfc\uc2e4)\ub97c \uc694\uac74\uc73c\ub85c \ud558\ub294 \ucc44\ubb34\ubd88\uc774\ud589 \uc720\ud615"],t.s)
B.aJu=s(["\ucc44\ubb34\ubd88\uc774\ud589 3\uc720\ud615"],t.s)
B.bD7=new A.a("gen_cl_nonperformance_1","civil_law","\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1",null,"\ucc44\ubb34\ubd88\uc774\ud589\uc758 \uc720\ud615\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.bg7,3,"\uc774\ud589\uc9c0\uccb4\xb7\uc774\ud589\ubd88\ub2a5\xb7\ubd88\uc644\uc804\uc774\ud589 \ubaa8\ub450 \uc6d0\uce59\uc801\uc73c\ub85c \ucc44\ubb34\uc790\uc758 \uadc0\ucc45\uc0ac\uc720(\uace0\uc758\xb7\uacfc\uc2e4)\ub97c \uc694\uac74\uc73c\ub85c \ud558\ub294 \ucc44\ubb34\ubd88\uc774\ud589 \uc720\ud615\uc774\uba70, \uadc0\ucc45\uc0ac\uc720\uac00 \uc5c6\ub294 \uae09\ubd80\ubd88\ub2a5\uc740 \uc704\ud5d8\ubd80\ub2f4\uc758 \ubb38\uc81c\ub85c \ubcc4\ub3c4\ub85c \ucc98\ub9ac\ub41c\ub2e4.",B.aFk,B.aJu,null)
B.as6=s(["\uc774\ud589\uc9c0\uccb4\ub97c \uc774\uc720\ub85c \ud574\uc81c\ud558\ub824\uba74 \uc6d0\uce59\uc801\uc73c\ub85c \uc0c1\ub2f9\ud55c \uae30\uac04\uc744 \uc815\ud55c \ucd5c\uace0\uac00 \ud544\uc694\ud558\ub2e4","\uc774\ud589\ubd88\ub2a5\uc744 \uc774\uc720\ub85c \ud574\uc81c\ud558\ub824\uba74 \ubc18\ub4dc\uc2dc \uc0c1\ub2f9\ud55c \uae30\uac04\uc744 \uc815\ud55c \ucd5c\uace0\uac00 \ud544\uc694\ud558\ub2e4","\uc774\ud589\uc9c0\uccb4\uc640 \uc774\ud589\ubd88\ub2a5 \ubaa8\ub450 \ucd5c\uace0 \uc5c6\uc774\ub294 \ud574\uc81c\ud560 \uc218 \uc5c6\ub2e4","\uc774\ud589\ubd88\ub2a5\uc774 \ub418\uc5b4\ub3c4 \ucc44\ubb34\uc790\ub294 \uc5ec\uc804\ud788 \uc774\ud589\uc744 \uac15\uc81c\ub2f9\ud560 \uc218 \uc788\uc5b4 \ud574\uc81c\uac00 \ubd88\ud544\uc694\ud558\ub2e4"],t.s)
B.bgO=s(["\uc774\ud589\ubd88\ub2a5(\uc81c546\uc870)\uc740 \uc774\ud589 \uc790\uccb4\uac00 \ubd88\uac00\ub2a5\ud558\ubbc0\ub85c \ucd5c\uace0 \uc5c6\uc774 \uc989\uc2dc \ud574\uc81c"],t.s)
B.ai_=s(["\uc774\ud589\uc9c0\uccb4\xb7\uc774\ud589\ubd88\ub2a5\uacfc \ud574\uc81c\uc694\uac74"],t.s)
B.bAw=new A.a("gen_cl_nonperformance_2","civil_law","\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1",null,"\uc774\ud589\uc9c0\uccb4\uc640 \uc774\ud589\ubd88\ub2a5\uc744 \uc774\uc720\ub85c \ud55c \uacc4\uc57d\ud574\uc81c\ub97c \ube44\uad50\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.as6,0,"\uc774\ud589\uc9c0\uccb4\ub85c \uc778\ud55c \ud574\uc81c(\uc81c544\uc870)\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \uc0c1\ub2f9\uae30\uac04\uc744 \uc815\ud55c \ucd5c\uace0\uac00 \ud544\uc694\ud558\uc9c0\ub9cc, \uc774\ud589\ubd88\ub2a5(\uc81c546\uc870)\uc740 \uc774\ud589 \uc790\uccb4\uac00 \ubd88\uac00\ub2a5\ud558\ubbc0\ub85c \ucd5c\uace0 \uc5c6\uc774 \uc989\uc2dc \ud574\uc81c\ud560 \uc218 \uc788\ub2e4.",B.bgO,B.ai_,null)
B.R2=s(["\ucc44\ubb34\ubd88\uc774\ud589 \ucc45\uc784(\uc804\ubcf4\ubc30\uc0c1)\uc774 \ubb38\uc81c\ub41c\ub2e4","\uc704\ud5d8\ubd80\ub2f4\uc758 \ubb38\uc81c\ub85c \ucc98\ub9ac\ub41c\ub2e4","\ubd88\uc644\uc804\uc774\ud589\uc73c\ub85c \ucc98\ub9ac\ub41c\ub2e4","\uc5b8\uc81c\ub098 \uacc4\uc57d\uc774 \uc790\ub3d9\uc73c\ub85c \ubb34\ud6a8\uac00 \ub41c\ub2e4"],t.s)
B.V8=s(["\ucc44\ubb34\ubd88\uc774\ud589\uc774 \uc544\ub2c8\ub77c \ubbfc\ubc95 \uc81c537\xb7538\uc870\uc758 \uc704\ud5d8\ubd80\ub2f4 \ubb38\uc81c\ub85c \ub2e4\ub8e8\uc5b4\uc9c4\ub2e4"],t.s)
B.aqw=s(["\uc704\ud5d8\ubd80\ub2f4\uacfc \ucc44\ubb34\ubd88\uc774\ud589\uc758 \uad6c\ubd84"],t.s)
B.bJo=new A.a("gen_cl_nonperformance_3","civil_law","\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1",null,"\ucc44\ubb34\uc790\uc5d0\uac8c \uadc0\ucc45\uc0ac\uc720 \uc5c6\uc774 \ucc44\ubb34\uc758 \uc774\ud589\uc774 \ubd88\uac00\ub2a5\ud558\uac8c \ub41c \uacbd\uc6b0\uc758 \ubc95\ub960\uad00\uacc4\ub294?",B.R2,1,"\ucc44\ubb34\uc790\uc758 \uadc0\ucc45\uc0ac\uc720 \uc5c6\uc774 \uc774\ud589\uc774 \ubd88\uac00\ub2a5\ud558\uac8c \ub41c \uacbd\uc6b0\ub294 \ucc44\ubb34\ubd88\uc774\ud589\uc774 \uc544\ub2c8\ub77c \ubbfc\ubc95 \uc81c537\xb7538\uc870\uc758 \uc704\ud5d8\ubd80\ub2f4 \ubb38\uc81c\ub85c \ub2e4\ub8e8\uc5b4\uc9c0\uba70, \uc6d0\uce59\uc801\uc73c\ub85c \ucc44\ubb34\uc790\ub294 \ubc18\ub300\uae09\ubd80\ub97c \uccad\uad6c\ud560 \uc218 \uc5c6\ub2e4(\ucc44\ubb34\uc790\uc704\ud5d8\ubd80\ub2f4\uc8fc\uc758).",B.V8,B.aqw,null)
B.bcj=s(["\ud1b5\uc0c1\uc190\ud574\uc640 \ud2b9\ubcc4\uc190\ud574 \ubaa8\ub450 \uc544\ubb34\ub7f0 \uc81c\ud55c \uc5c6\uc774 \ubc30\uc0c1\ubc1b\uc744 \uc218 \uc788\ub2e4","\ud1b5\uc0c1\uc190\ud574\ub294 \ub2f9\uc5f0\ud788 \ubc30\uc0c1\ubc1b\uc744 \uc218 \uc788\uace0, \ud2b9\ubcc4\uc190\ud574\ub294 \ucc44\ubb34\uc790\uac00 \uadf8 \uc0ac\uc815\uc744 \uc54c\uc558\uac70\ub098 \uc54c \uc218 \uc788\uc5c8\uc744 \ub54c\uc5d0\ub9cc \ubc30\uc0c1\ubc1b\uc744 \uc218 \uc788\ub2e4","\ud2b9\ubcc4\uc190\ud574\ub294 \ucc44\ubb34\uc790\uc758 \uc778\uc2dd \uc5ec\ubd80\uc640 \ubb34\uad00\ud558\uac8c \ud56d\uc0c1 \ubc30\uc0c1\ubc1b\uc744 \uc218 \uc788\ub2e4","\ud1b5\uc0c1\uc190\ud574\ub294 \ucc44\uad8c\uc790\uac00 \uadf8 \uc0ac\uc815\uc744 \uc99d\uba85\ud574\uc57c\ub9cc \ubc30\uc0c1\ubc1b\uc744 \uc218 \uc788\ub2e4"],t.s)
B.ajz=s(["\ud2b9\ubcc4\uc190\ud574\ub294 \ucc44\ubb34\uc790\uac00 \uadf8 \uc0ac\uc815\uc744 \uc54c\uc558\uac70\ub098 \uc54c \uc218 \uc788\uc5c8\uc744 \ub54c\uc5d0\ub9cc \ubc30\uc0c1\ubc1b\uc744 \uc218 \uc788\ub2e4"],t.s)
B.akH=s(["\ud1b5\uc0c1\uc190\ud574\uc640 \ud2b9\ubcc4\uc190\ud574"],t.s)
B.bMh=new A.a("gen_cl_nonperformance_4","civil_law","\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1",null,"\uc190\ud574\ubc30\uc0c1\uc758 \ubc94\uc704(\ubbfc\ubc95 \uc81c393\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.bcj,1,"\uc81c393\uc870\ub294 \ud1b5\uc0c1\uc190\ud574\ub294 \ub2f9\uc5f0\ud788 \ubc30\uc0c1\ubc94\uc704\uc5d0 \ud3ec\ud568\uc2dc\ud0a4\ub418, \ud2b9\ubcc4\ud55c \uc0ac\uc815\uc73c\ub85c \uc778\ud55c \uc190\ud574(\ud2b9\ubcc4\uc190\ud574)\ub294 \ucc44\ubb34\uc790\uac00 \uadf8 \uc0ac\uc815\uc744 \uc54c\uc558\uac70\ub098 \uc54c \uc218 \uc788\uc5c8\uc744 \ub54c\uc5d0 \ud55c\ud558\uc5ec \ubc30\uc0c1\ucc45\uc784\uc744 \uc9c0\ub3c4\ub85d \uaddc\uc815\ud558\uace0 \uc788\ub2e4.",B.ajz,B.akH,null)
B.aDt=s(["\ub2f9\uc0ac\uc790\ub294 \ucc44\ubb34\ubd88\uc774\ud589\uc5d0 \ub300\ud55c \uc190\ud574\ubc30\uc0c1\uc561\uc744 \ubbf8\ub9ac \uc57d\uc815\ud560 \uc218 \uc788\ub2e4","\ubc30\uc0c1\uc561 \uc608\uc815\uc774 \uc788\uc73c\uba74 \ucc44\uad8c\uc790\ub294 \uc2e4\uc81c \uc190\ud574\uc561\uc744 \uc99d\uba85\ud560 \ud544\uc694 \uc5c6\uc774 \uc608\uc815\uc561\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4","\uc608\uc815\ub41c \ubc30\uc0c1\uc561\uc774 \ubd80\ub2f9\ud788 \uacfc\ub2e4\ud55c \uacbd\uc6b0 \ubc95\uc6d0\uc740 \uc774\ub97c \uac10\uc561\ud560 \uc218 \uc5c6\ub2e4","\uc190\ud574\ubc30\uc0c1\uc561\uc758 \uc608\uc815\uc740 \uc774\ud589\uc758 \uccad\uad6c\ub098 \uacc4\uc57d\uc758 \ud574\uc81c\uc5d0 \uc601\ud5a5\uc744 \ubbf8\uce58\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.alN=s(["\ubd80\ub2f9\ud788 \uacfc\ub2e4\ud55c \uacbd\uc6b0 \ubc95\uc6d0\uc774 \uc801\ub2f9\ud788 \uac10\uc561\ud560 \uc218 \uc788\ub2e4"],t.s)
B.bAL=new A.a("gen_cl_nonperformance_5","civil_law","\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1",null,"\uc190\ud574\ubc30\uc0c1\uc561\uc758 \uc608\uc815(\ubbfc\ubc95 \uc81c398\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aDt,2,"\ubbfc\ubc95 \uc81c398\uc870 \uc81c2\ud56d\uc740 \uc190\ud574\ubc30\uc0c1 \uc608\uc815\uc561\uc774 \ubd80\ub2f9\ud788 \uacfc\ub2e4\ud55c \uacbd\uc6b0 \ubc95\uc6d0\uc774 \uc801\ub2f9\ud788 \uac10\uc561\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud558\uace0 \uc788\uc5b4, \uac10\uc561\ud560 \uc218 \uc5c6\ub2e4\ub294 \uc124\uba85\uc740 \uc633\uc9c0 \uc54a\ub2e4.",B.alN,B.tO,null)
B.b_e=s(["\ucc44\uad8c\uc790\uc5d0\uac8c \uacfc\uc2e4\uc774 \uc788\uc5b4\ub3c4 \ubc95\uc6d0\uc740 \uc774\ub97c \ucc38\uc791\ud560 \uc758\ubb34\uac00 \uc5c6\ub2e4","\ucc44\ubb34\ubd88\uc774\ud589\uc5d0 \uad00\ud558\uc5ec \ucc44\uad8c\uc790\uc5d0\uac8c \uacfc\uc2e4\uc774 \uc788\uc73c\uba74 \ubc95\uc6d0\uc740 \uc190\ud574\ubc30\uc0c1\uc758 \ucc45\uc784 \ubc0f \uadf8 \uae08\uc561\uc744 \uc815\ud560 \ub54c \uc774\ub97c \ubc18\ub4dc\uc2dc \ucc38\uc791\ud558\uc5ec\uc57c \ud55c\ub2e4","\uacfc\uc2e4\uc0c1\uacc4\ub294 \ub2f9\uc0ac\uc790\uac00 \ubcc4\ub3c4\ub85c \uc8fc\uc7a5\ud558\uc9c0 \uc54a\uc73c\uba74 \ubc95\uc6d0\uc774 \uace0\ub824\ud560 \uc218 \uc5c6\ub2e4","\uacfc\uc2e4\uc0c1\uacc4\ub294 \uae08\uc804\ucc44\ubb34\ubd88\uc774\ud589\uc5d0\ub294 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.aif=s(["\ubc95\uc6d0\uc774 \uc190\ud574\ubc30\uc0c1\uc758 \ucc45\uc784 \ubc0f \uadf8 \uae08\uc561\uc744 \uc815\ud568\uc5d0 \uc788\uc5b4 \uc774\ub97c \ucc38\uc791\ud558\uc5ec\uc57c \ud55c\ub2e4"],t.s)
B.aQ8=s(["\uacfc\uc2e4\uc0c1\uacc4"],t.s)
B.bQi=new A.a("gen_cl_nonperformance_6","civil_law","\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1",null,"\uacfc\uc2e4\uc0c1\uacc4(\ubbfc\ubc95 \uc81c396\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.b_e,1,"\uc81c396\uc870\ub294 \ucc44\ubb34\ubd88\uc774\ud589\uc5d0 \uad00\ud558\uc5ec \ucc44\uad8c\uc790\uc5d0\uac8c \uacfc\uc2e4\uc774 \uc788\ub294 \ub54c \ubc95\uc6d0\uc774 \uc190\ud574\ubc30\uc0c1\uc758 \ucc45\uc784 \ubc0f \uadf8 \uae08\uc561\uc744 \uc815\ud568\uc5d0 \uc788\uc5b4 \uc774\ub97c \ucc38\uc791\ud558\uc5ec\uc57c \ud55c\ub2e4\uace0 \uaddc\uc815\ud558\uba70, \ud310\ub840\ub294 \uc774\ub97c \ubc95\uc6d0\uc758 \uc9c1\uad8c \uace0\ub824 \uc0ac\ud56d\uc73c\ub85c \ubcf8\ub2e4.",B.aif,B.aQ8,null)
B.S6=s(["\ucc44\uad8c\uc790\ub294 \uc190\ud574\uc758 \ubc1c\uc0dd \ubc0f \uadf8 \uc561\uc218\ub97c \uc99d\uba85\ud558\uc9c0 \uc54a\uace0\ub3c4 \ubc95\uc815\uc774\uc728\uc5d0 \ub530\ub978 \uc190\ud574\ubc30\uc0c1\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4","\uc57d\uc815\uc774\uc728\uc774 \ubc95\uc815\uc774\uc728\ubcf4\ub2e4 \ub192\uc73c\uba74 \uc57d\uc815\uc774\uc728\uc5d0 \ub530\ub978\ub2e4","\ucc44\ubb34\uc790\ub294 \uacfc\uc2e4\uc5c6\uc74c\uc744 \ud56d\ubcc0\ud558\uc9c0 \ubabb\ud55c\ub2e4","\ucc44\ubb34\uc790\ub294 \ubd88\uac00\ud56d\ub825\uc744 \uc774\uc720\ub85c \uc190\ud574\ubc30\uc0c1\ucc45\uc784\uc744 \uba74\ud560 \uc218 \uc788\ub2e4"],t.s)
B.aT2=s(["\ucc44\ubb34\uc790\uac00 \ubd88\uac00\ud56d\ub825\uc744 \ud56d\ubcc0\uc73c\ub85c \uc8fc\uc7a5\ud558\uc9c0 \ubabb\ud558\uba70"],t.s)
B.bdK=s(["\uae08\uc804\ucc44\ubb34\ubd88\uc774\ud589 \ud2b9\uce59"],t.s)
B.bFt=new A.a("gen_cl_nonperformance_7","civil_law","\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1",null,"\uae08\uc804\ucc44\ubb34\ubd88\uc774\ud589\uc5d0 \uad00\ud55c \ud2b9\uce59(\ubbfc\ubc95 \uc81c397\uc870)\uc758 \ub0b4\uc6a9\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.S6,3,"\uae08\uc804\ucc44\ubb34\ubd88\uc774\ud589\uc5d0 \ub300\ud574\uc11c\ub294 \ud2b9\uce59\uc0c1 \ucc44\ubb34\uc790\uac00 \ubd88\uac00\ud56d\ub825\uc744 \ud56d\ubcc0\uc73c\ub85c \uc8fc\uc7a5\ud558\uc9c0 \ubabb\ud558\uba70(\uc81c397\uc870 \uc81c2\ud56d), \uacfc\uc2e4 \uc5c6\uc74c\uc744 \uc774\uc720\ub85c\ub3c4 \uba74\ucc45\ub418\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc810\uc5d0\uc11c \uc77c\ubc18 \ucc44\ubb34\ubd88\uc774\ud589\uacfc \ub2e4\ub974\ub2e4.",B.aT2,B.bdK,null)
B.asc=s(["\uc804\ubcf4\ubc30\uc0c1\uc740 \uc774\ud589\uc9c0\uccb4 \uc911 \uc9c0\uc5f0\uc73c\ub85c \ubc1c\uc0dd\ud55c \uc190\ud574\ub9cc\uc744 \uc758\ubbf8\ud55c\ub2e4","\uc804\ubcf4\ubc30\uc0c1\uc740 \ubcf8\ub798\uc758 \uae09\ubd80\uc5d0 \uac08\uc74c\ud558\ub294 \uc190\ud574\ubc30\uc0c1\uc744 \ub9d0\ud55c\ub2e4","\uc804\ubcf4\ubc30\uc0c1\uc740 \ucc44\uad8c\uc790\uc758 \uadc0\ucc45\uc0ac\uc720\uac00 \uc788\uc5b4\uc57c\ub9cc \uccad\uad6c\ud560 \uc218 \uc788\ub2e4","\uc804\ubcf4\ubc30\uc0c1\uc740 \uc774\ud589\uc774 \uac00\ub2a5\ud55c \uacbd\uc6b0\uc5d0\ub9cc \uc778\uc815\ub41c\ub2e4"],t.s)
B.afC=s(["\ubcf8\ub798\uc758 \uae09\ubd80\uc5d0 \uac08\uc74c\ud558\ub294 \uc190\ud574\ubc30\uc0c1"],t.s)
B.bdD=s(["\uc804\ubcf4\ubc30\uc0c1\uc758 \uc758\ubbf8"],t.s)
B.bO4=new A.a("gen_cl_nonperformance_8","civil_law","\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1",null,"\uc774\ud589\ubd88\ub2a5\uc73c\ub85c \uc778\ud55c \uc804\ubcf4\ubc30\uc0c1\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.asc,1,"\uc804\ubcf4\ubc30\uc0c1\uc740 \ubcf8\ub798\uc758 \uc774\ud589\uc5d0 \uac08\uc74c\ud558\uc5ec \uadf8 \uc774\ud589\uc774\uc775\uc744 \uae08\uc804\uc73c\ub85c \ubc30\uc0c1\ud558\ub294 \uac83\uc73c\ub85c, \uc774\ud589\uc774 \ubd88\uac00\ub2a5\ud558\uac8c \ub41c \uacbd\uc6b0(\uc774\ud589\ubd88\ub2a5) \ucc44\uad8c\uc790\uac00 \uccad\uad6c\ud560 \uc218 \uc788\ub294 \uc190\ud574\ubc30\uc0c1\uc758 \ud615\ud0dc\uc774\ub2e4.",B.afC,B.bdD,null)
B.a0A=s(["\uc774\ud589\uae30\uc758 \ub3c4\ub798","\uc774\ud589\uc774 \uac00\ub2a5\ud560 \uac83","\ucc44\ubb34\uc790\uc758 \uadc0\ucc45\uc0ac\uc720","\ucc44\uad8c\uc790\uc758 \ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c \ud3ec\uae30"],t.s)
B.asH=s(["\uc774\ud589\uae30 \ub3c4\ub798, \uc774\ud589 \uac00\ub2a5, \ucc44\ubb34\uc790\uc758 \uadc0\ucc45\uc0ac\uc720, \uc774\ud589\ud558\uc9c0 \uc54a\ub294 \uac83\uc774 \uc704\ubc95\ud560 \uac83"],t.s)
B.bbl=s(["\uc774\ud589\uc9c0\uccb4 \uc131\ub9bd\uc694\uac74"],t.s)
B.bw2=new A.a("gen_cl_nonperformance_9","civil_law","\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1",null,"\uc774\ud589\uc9c0\uccb4 \uc131\ub9bd\uc694\uac74\uc5d0 \ud574\ub2f9\ud558\uc9c0 \uc54a\ub294 \uac83\uc740?",B.a0A,3,"\uc774\ud589\uc9c0\uccb4\uac00 \uc131\ub9bd\ud558\ub824\uba74 \uc774\ud589\uae30 \ub3c4\ub798, \uc774\ud589 \uac00\ub2a5, \ucc44\ubb34\uc790\uc758 \uadc0\ucc45\uc0ac\uc720, \uc774\ud589\ud558\uc9c0 \uc54a\ub294 \uac83\uc774 \uc704\ubc95\ud560 \uac83(\ud56d\ubcc0\uad8c \ubd80\uc874\uc7ac)\uc774 \ud544\uc694\ud558\ub2e4. \ucc44\uad8c\uc790\uc758 \ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c \ud3ec\uae30\ub294 \uc131\ub9bd\uc694\uac74\uc774 \uc544\ub2c8\uba70, \uc624\ud788\ub824 \ucc44\ubb34\uc790\uc5d0\uac8c \ud56d\ubcc0\uad8c\uc774 \uc788\uc73c\uba74 \uc774\ud589\uc9c0\uccb4\uac00 \uc131\ub9bd\ud558\uc9c0 \uc54a\ub294\ub2e4.",B.asH,B.bbl,null)
B.aon=s(["\ubd88\uc644\uc804\uc774\ud589\uc740 \uc774\ud589 \uc790\uccb4\uac00 \uc804\ud600 \uc5c6\uc5c8\ub358 \uacbd\uc6b0\ub97c \ub9d0\ud55c\ub2e4","\ubd88\uc644\uc804\uc774\ud589\uc740 \uc774\ud589\uc774 \uc788\uc5c8\uc73c\ub098 \uadf8 \ub0b4\uc6a9\uc774 \ucc44\ubb34 \ub0b4\uc6a9\uc5d0 \uc887\uc740 \uc644\uc804\ud55c \uc774\ud589\uc774 \uc544\ub2cc \uacbd\uc6b0\ub97c \ub9d0\ud55c\ub2e4","\ubd88\uc644\uc804\uc774\ud589\uc740 \ucd94\uc644\uc774 \uac00\ub2a5\ud558\ub354\ub77c\ub3c4 \ud56d\uc0c1 \uacc4\uc57d\uc744 \ud574\uc81c\ud574\uc57c \ud55c\ub2e4","\ubd88\uc644\uc804\uc774\ud589\uc740 \uc190\ud574\ubc30\uc0c1\ucc45\uc784\uc774 \ubc1c\uc0dd\ud558\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.Un=s(["\uc774\ud589\uc774 \uc788\uc5c8\uc73c\ub098 \uadf8 \ub0b4\uc6a9\uc774 \ucc44\ubb34 \ub0b4\uc6a9\uc5d0 \uc887\uc740 \uc644\uc804\ud55c \uc774\ud589\uc774 \uc544\ub2cc \uacbd\uc6b0"],t.s)
B.aNe=s(["\ubd88\uc644\uc804\uc774\ud589\uc758 \uc758\ubbf8"],t.s)
B.buS=new A.a("gen_cl_nonperformance_10","civil_law","\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1",null,"\ubd88\uc644\uc804\uc774\ud589\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aon,1,"\ubd88\uc644\uc804\uc774\ud589\uc740 \ucc44\ubb34\uc790\uac00 \uc774\ud589\ud589\uc704\ub97c \ud558\uc600\uc73c\ub098 \uadf8 \uc774\ud589\uc774 \ucc44\ubb34\uc758 \ub0b4\uc6a9\uc5d0 \uc887\uc740 \uc644\uc804\ud55c \uc774\ud589\uc774 \uc544\ub2cc \uacbd\uc6b0\ub85c, \ucd94\uc644\uc774 \uac00\ub2a5\ud558\uba74 \ucd94\uc644\uccad\uad6c\uad8c\uc774, \ucd94\uc644\uc774 \ubd88\uac00\ub2a5\ud558\uac70\ub098 \ud655\ub300\uc190\ud574\uac00 \ubc1c\uc0dd\ud558\uba74 \uc190\ud574\ubc30\uc0c1\xb7\ud574\uc81c \ub4f1\uc774 \ubb38\uc81c\ub41c\ub2e4.",B.Un,B.aNe,null)
B.aBy=s(["\uc190\ud574\ubc30\uc0c1\uccad\uad6c\uad8c\uc740 \ucc44\ubb34\ubd88\uc774\ud589\uacfc \ubb34\uad00\ud558\uac8c \ub3c5\ub9bd\ub41c \ubcc4\ub3c4\uc758 \uad8c\ub9ac\uc774\ubbc0\ub85c \uc18c\uba78\uc2dc\ud6a8\uac00 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4","\uc190\ud574\ubc30\uc0c1\uccad\uad6c\uad8c\ub3c4 \uc6d0\uce59\uc801\uc73c\ub85c \uc18c\uba78\uc2dc\ud6a8\uc758 \uc801\uc6a9\uc744 \ubc1b\ub294 \ucc44\uad8c\uc774\ub2e4","\uc190\ud574\ubc30\uc0c1\uccad\uad6c\uad8c\uc740 \uc5b8\uc81c\ub098 \uc6d0\ucc44\uad8c\uacfc \ubcc4\uac1c\ub85c 20\ub144\uc758 \uc2dc\ud6a8\uac00 \uc801\uc6a9\ub41c\ub2e4","\uc190\ud574\ubc30\uc0c1\uccad\uad6c\uad8c\uc740 \uc81c\ucc99\uae30\uac04\uc758 \uc801\uc6a9\uc744 \ubc1b\uc544 \uc18c\uba78\uc2dc\ud6a8\uc640 \ubb34\uad00\ud558\ub2e4"],t.s)
B.aQ1=s(["\ud558\ub098\uc758 \ucc44\uad8c\uc73c\ub85c\uc11c \uc6d0\uce59\uc801\uc73c\ub85c \uc18c\uba78\uc2dc\ud6a8\uc758 \uc801\uc6a9\uc744 \ubc1b\uc73c\uba70"],t.s)
B.aJJ=s(["\uc190\ud574\ubc30\uc0c1\uccad\uad6c\uad8c\uacfc \uc18c\uba78\uc2dc\ud6a8"],t.s)
B.bGX=new A.a("gen_cl_nonperformance_11","civil_law","\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1",null,"\ucc44\ubb34\ubd88\uc774\ud589\uc73c\ub85c \uc778\ud55c \uc190\ud574\ubc30\uc0c1\uccad\uad6c\uad8c\uc758 \uc18c\uba78\uc2dc\ud6a8\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aBy,1,"\ucc44\ubb34\ubd88\uc774\ud589\uc73c\ub85c \uc778\ud55c \uc190\ud574\ubc30\uc0c1\uccad\uad6c\uad8c\ub3c4 \ud558\ub098\uc758 \ucc44\uad8c\uc73c\ub85c\uc11c \uc6d0\uce59\uc801\uc73c\ub85c \uc18c\uba78\uc2dc\ud6a8\uc758 \uc801\uc6a9\uc744 \ubc1b\uc73c\uba70, \ud1b5\uc0c1 \uc6d0\ucc44\uad8c\uc758 \uc131\uc9c8\uc5d0 \ub530\ub978 \uc2dc\ud6a8\uae30\uac04\uc774 \uc900\uc6a9\ub41c\ub2e4.",B.aQ1,B.aJJ,null)
B.akn=s(["\uc774\ud589\uc9c0\uccb4\ub294 \ucd5c\uace0 \ud6c4 \ud574\uc81c, \uc774\ud589\ubd88\ub2a5\uc740 \ucd5c\uace0 \uc5c6\uc774 \ud574\uc81c\ud560 \uc218 \uc788\ub2e4","\uc190\ud574\ubc30\uc0c1\uc758 \ubc94\uc704\ub294 \ud1b5\uc0c1\uc190\ud574\ub97c \uae30\ubcf8\uc73c\ub85c \ud558\uace0 \ud2b9\ubcc4\uc190\ud574\ub294 \uc608\uacac\uac00\ub2a5\uc131\uc744 \uc694\uac74\uc73c\ub85c \ud55c\ub2e4","\uae08\uc804\ucc44\ubb34\ubd88\uc774\ud589\uc740 \ucc44\ubb34\uc790\uc758 \ubd88\uac00\ud56d\ub825 \ud56d\ubcc0\uc774 \ud5c8\uc6a9\ub418\uc9c0 \uc54a\ub294 \ud2b9\uce59\uc774 \uc788\ub2e4","\ucc44\uad8c\uc790\uc758 \uacfc\uc2e4\uc740 \ubc95\uc6d0\uc758 \uc7ac\ub7c9\uc73c\ub85c \ucc38\uc791\ud560 \uc218\ub3c4, \ud558\uc9c0 \uc54a\uc744 \uc218\ub3c4 \uc788\ub2e4"],t.s)
B.TP=s(["\ubc95\uc6d0\uc774 \uc190\ud574\ubc30\uc0c1\uc758 \ucc45\uc784\uacfc \ubc94\uc704\ub97c \uc815\ud560 \ub54c \ubc18\ub4dc\uc2dc \ucc38\uc791\ud558\uc5ec\uc57c \ud558\ub294 \uc758\ubb34 \uc0ac\ud56d"],t.s)
B.b2U=s(["\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1 \uc885\ud569\uc815\ub9ac"],t.s)
B.bvz=new A.a("gen_cl_nonperformance_12","civil_law","\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1",null,"\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1\uc5d0 \uad00\ud55c \uc885\ud569\uc801\uc778 \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.akn,3,"\uacfc\uc2e4\uc0c1\uacc4(\uc81c396\uc870)\ub294 \ucc44\uad8c\uc790\uc5d0\uac8c \uacfc\uc2e4\uc774 \uc788\ub294 \uacbd\uc6b0 \ubc95\uc6d0\uc774 \uc190\ud574\ubc30\uc0c1\uc758 \ucc45\uc784\uacfc \ubc94\uc704\ub97c \uc815\ud560 \ub54c \ubc18\ub4dc\uc2dc \ucc38\uc791\ud558\uc5ec\uc57c \ud558\ub294 \uc758\ubb34 \uc0ac\ud56d\uc774\uc9c0, \ubc95\uc6d0\uc758 \uc784\uc758\uc801 \uc7ac\ub7c9 \uc0ac\ud56d\uc774 \uc544\ub2c8\ub2e4.",B.TP,B.b2U,null)
B.azd=s(["\uc774\ud589\ubcf4\uc870\uc790\uc758 \uace0\uc758\xb7\uacfc\uc2e4\uc740 \ucc44\ubb34\uc790 \ubcf8\uc778\uc758 \uace0\uc758\xb7\uacfc\uc2e4\uacfc \ubb34\uad00\ud558\ub2e4","\ucc44\ubb34\uc790\ub294 \uc774\ud589\ubcf4\uc870\uc790\uc758 \uace0\uc758\xb7\uacfc\uc2e4\uc5d0 \ub300\ud558\uc5ec\ub3c4 \uc790\uae30\uc758 \uace0\uc758\xb7\uacfc\uc2e4\uacfc \ub9c8\ucc2c\uac00\uc9c0\ub85c \ucc45\uc784\uc744 \uc9c4\ub2e4","\uc774\ud589\ubcf4\uc870\uc790\ub97c \uc0ac\uc6a9\ud558\uba74 \ucc44\ubb34\uc790\uc758 \ucc45\uc784\uc774 \uc624\ud788\ub824 \uba74\uc81c\ub41c\ub2e4","\uc774\ud589\ubcf4\uc870\uc790\uc5d0 \uad00\ud55c \ucc45\uc784\uc740 \uc0c1\ud589\uc704\uc5d0\ub9cc \uc801\uc6a9\ub41c\ub2e4"],t.s)
B.aTW=s(["\uc774\ud589\ubcf4\uc870\uc790\uc758 \uace0\uc758\xb7\uacfc\uc2e4\uc740 \ucc44\ubb34\uc790 \uc790\uc2e0\uc758 \uace0\uc758\xb7\uacfc\uc2e4\ub85c \ubcf8\ub2e4"],t.s)
B.aNl=s(["\uc774\ud589\ubcf4\uc870\uc790\uc758 \uace0\uc758\xb7\uacfc\uc2e4"],t.s)
B.boP=new A.a("gen_cl_nonperformance_13","civil_law","\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1",null,"\uc774\ud589\ubcf4\uc870\uc790\uc758 \uace0\uc758\xb7\uacfc\uc2e4(\ubbfc\ubc95 \uc81c391\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.azd,1,"\ubbfc\ubc95 \uc81c391\uc870\ub294 \ucc44\ubb34\uc790\uc758 \ubc95\uc815\ub300\ub9ac\uc778\uc774\ub098 \uc774\ud589\ubcf4\uc870\uc790\uc758 \uace0\uc758\xb7\uacfc\uc2e4\uc740 \ucc44\ubb34\uc790 \uc790\uc2e0\uc758 \uace0\uc758\xb7\uacfc\uc2e4\ub85c \ubcf8\ub2e4\uace0 \uaddc\uc815\ud558\uc5ec, \ucc44\ubb34\uc790\uac00 \uc774\ud589\ubcf4\uc870\uc790\ub97c \uc0ac\uc6a9\ud574 \uc774\uc775\uc744 \uc5bb\ub294 \ub9cc\ud07c \uadf8 \uc704\ud5d8\ub3c4 \ud568\uaed8 \ubd80\ub2f4\ud558\ub3c4\ub85d \ud55c\ub2e4.",B.aTW,B.aNl,null)
B.aXy=s(["\ucc44\ubb34\uc790\uac00 \uc774\ud589\ubd88\ub2a5\uc744 \uc57c\uae30\ud55c \uc0ac\uc720\ub85c \ub300\uc0c1(\ub300\uccb4\uc774\uc775)\uc744 \ucde8\ub4dd\ud55c \uacbd\uc6b0, \ucc44\uad8c\uc790\uac00 \uadf8 \ub300\uc0c1\uc758 \uc774\uc804\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub294 \uad8c\ub9ac\uc774\ub2e4","\ub300\uc0c1\uccad\uad6c\uad8c\uc740 \uc774\ud589\uc9c0\uccb4\uc5d0\uc11c\ub9cc \uc778\uc815\ub41c\ub2e4","\ub300\uc0c1\uccad\uad6c\uad8c\uc740 \uba85\ubb38 \uaddc\uc815\uc774 \uc788\uc5b4 \ud559\uc124\uc0c1 \ub17c\ub780\uc758 \uc5ec\uc9c0\uac00 \uc5c6\ub2e4","\ub300\uc0c1\uccad\uad6c\uad8c\uc740 \ucc44\ubb34\uc790\uc5d0\uac8c\ub9cc \uc778\uc815\ub418\ub294 \uad8c\ub9ac\uc774\ub2e4"],t.s)
B.a_O=s(["\ucc44\ubb34\uc790\uac00 \ubaa9\uc801\ubb3c\uc5d0 \uac08\uc74c\ud558\ub294 \uc774\uc775(\ubcf4\ud5d8\uae08, \uc190\ud574\ubc30\uc0c1\uae08 \ub4f1)\uc744 \ucde8\ub4dd\ud55c \uacbd\uc6b0, \ucc44\uad8c\uc790\uac00 \ud615\ud3c9\uc758 \uad00\uc810\uc5d0\uc11c \uadf8 \ub300\uc0c1\uc758 \uc774\uc804\uc744 \uccad\uad6c"],t.s)
B.b37=s(["\ub300\uc0c1\uccad\uad6c\uad8c"],t.s)
B.bSm=new A.a("gen_cl_nonperformance_14","civil_law","\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1",null,"\ub300\uc0c1\uccad\uad6c\uad8c\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aXy,0,"\ub300\uc0c1\uccad\uad6c\uad8c\uc740 \uc774\ud589\ubd88\ub2a5\uc744 \ubc1c\uc0dd\uc2dc\ud0a8 \uac83\uacfc \ub3d9\uc77c\ud55c \uc6d0\uc778\uc73c\ub85c \ucc44\ubb34\uc790\uac00 \ubaa9\uc801\ubb3c\uc5d0 \uac08\uc74c\ud558\ub294 \uc774\uc775(\ubcf4\ud5d8\uae08, \uc190\ud574\ubc30\uc0c1\uae08 \ub4f1)\uc744 \ucde8\ub4dd\ud55c \uacbd\uc6b0, \ucc44\uad8c\uc790\uac00 \ud615\ud3c9\uc758 \uad00\uc810\uc5d0\uc11c \uadf8 \ub300\uc0c1\uc758 \uc774\uc804\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub294 \uad8c\ub9ac\ub85c \ud310\ub840\uac00 \uc778\uc815\ud55c\ub2e4.",B.a_O,B.b37,null)
B.bih=s(["\uacc4\uc57d \uc131\ub9bd \ub2f9\uc2dc \uc774\ubbf8 \uc6d0\uc2dc\uc801\uc73c\ub85c \ubd88\ub2a5\uc778 \uae09\ubd80\ub97c \ubaa9\uc801\uc73c\ub85c \ud55c \uacc4\uc57d\uc740 \uc6d0\uce59\uc801\uc73c\ub85c \ubb34\ud6a8\uc774\ub2e4","\uc6d0\uc2dc\uc801 \ubd88\ub2a5\uc740 \ud6c4\ubc1c\uc801 \ubd88\ub2a5\uacfc \uc644\uc804\ud788 \ub3d9\uc77c\ud558\uac8c \ucc44\ubb34\ubd88\uc774\ud589\uc73c\ub85c \ucc98\ub9ac\ub41c\ub2e4","\uc6d0\uc2dc\uc801 \ubd88\ub2a5\uc778 \uacc4\uc57d\uc740 \ud56d\uc0c1 \uc720\ud6a8\ud558\uba70 \uc774\ud589\uc744 \uac15\uc81c\ud560 \uc218 \uc788\ub2e4","\uacc4\uc57d\uccb4\uacb0\uc0c1\uc758 \uacfc\uc2e4\ucc45\uc784\uc740 \uacc4\uc57d\uc774 \uc720\ud6a8\ud55c \uacbd\uc6b0\uc5d0\ub9cc \ubb38\uc81c\ub41c\ub2e4"],t.s)
B.aN_=s(["\uacc4\uc57d \uc131\ub9bd \ub2f9\uc2dc\ubd80\ud130 \uae09\ubd80\uc758 \uc2e4\ud604\uc774 \ubd88\uac00\ub2a5\ud55c \uc6d0\uc2dc\uc801 \ubd88\ub2a5\uc758 \uacbd\uc6b0 \uadf8 \uacc4\uc57d\uc740 \uc6d0\uce59\uc801\uc73c\ub85c \ubb34\ud6a8"],t.s)
B.aPF=s(["\uc6d0\uc2dc\uc801 \ubd88\ub2a5\uacfc \uacc4\uc57d\uccb4\uacb0\uc0c1\uc758 \uacfc\uc2e4"],t.s)
B.bsv=new A.a("gen_cl_nonperformance_15","civil_law","\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1",null,"\uacc4\uc57d\uccb4\uacb0\uc0c1\uc758 \uacfc\uc2e4\ucc45\uc784(\uc6d0\uc2dc\uc801 \ubd88\ub2a5)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.bih,0,"\uacc4\uc57d \uc131\ub9bd \ub2f9\uc2dc\ubd80\ud130 \uae09\ubd80\uc758 \uc2e4\ud604\uc774 \ubd88\uac00\ub2a5\ud55c \uc6d0\uc2dc\uc801 \ubd88\ub2a5\uc758 \uacbd\uc6b0 \uadf8 \uacc4\uc57d\uc740 \uc6d0\uce59\uc801\uc73c\ub85c \ubb34\ud6a8\uc774\uba70, \uc774\ub54c \uc0c1\ub300\ubc29\uc744 \uc2e0\ub8b0\ud55c \ub2f9\uc0ac\uc790\ub294 \uacc4\uc57d\uccb4\uacb0\uc0c1\uc758 \uacfc\uc2e4\ucc45\uc784(\uc81c535\uc870)\uc5d0 \ub530\ub77c \uc2e0\ub8b0\uc774\uc775 \ubc30\uc0c1\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4.",B.aN_,B.aPF,null)
B.aEy=s(["\ub3d9\uc77c\ud55c \uc0ac\uc2e4\uad00\uacc4\uac00 \ucc44\ubb34\ubd88\uc774\ud589\uacfc \ubd88\ubc95\ud589\uc704\uc758 \uc694\uac74\uc744 \ubaa8\ub450 \ucda9\uc871\ud558\uba74 \uccad\uad6c\uad8c\uacbd\ud569\uc774 \uc778\uc815\ub418\ub294 \uac83\uc774 \ud1b5\uc124\xb7\ud310\ub840\uc774\ub2e4","\ucc44\ubb34\ubd88\uc774\ud589\ucc45\uc784\uc774 \uc131\ub9bd\ud558\uba74 \ubd88\ubc95\ud589\uc704\ucc45\uc784\uc740 \ub2f9\uc5f0\ud788 \ubc30\uc81c\ub41c\ub2e4","\ub450 \ucc45\uc784\uc740 \uc808\ub300 \ub3d9\uc2dc\uc5d0 \uc131\ub9bd\ud560 \uc218 \uc5c6\ub2e4","\ubd88\ubc95\ud589\uc704\ucc45\uc784\uc774 \uc131\ub9bd\ud558\uba74 \ucc44\ubb34\ubd88\uc774\ud589\ucc45\uc784\uc744 \ubb3c\uc744 \uc218 \uc5c6\ub2e4"],t.s)
B.b_S=s(["\ucc44\uad8c\uc790(\ud53c\ud574\uc790)\ub294 \ub450 \uccad\uad6c\uad8c \uc911 \uc5b4\ub290 \uac83\uc774\ub4e0 \uc120\ud0dd\uc801\uc73c\ub85c \ud589\uc0ac\ud560 \uc218 \uc788\ub294 \uccad\uad6c\uad8c\uacbd\ud569\uc744 \uc778\uc815"],t.s)
B.Z7=s(["\ucc44\ubb34\ubd88\uc774\ud589\uacfc \ubd88\ubc95\ud589\uc704\ucc45\uc784\uc758 \uacbd\ud569"],t.s)
B.bRC=new A.a("gen_cl_nonperformance_16","civil_law","\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1",null,"\ucc44\ubb34\ubd88\uc774\ud589\ucc45\uc784\uacfc \ubd88\ubc95\ud589\uc704\ucc45\uc784\uc758 \uacbd\ud569\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aEy,0,"\ud310\ub840\uc640 \ud1b5\uc124\uc740 \ub3d9\uc77c\ud55c \uc0ac\uc2e4\uad00\uacc4\uac00 \ucc44\ubb34\ubd88\uc774\ud589\ucc45\uc784\uacfc \ubd88\ubc95\ud589\uc704\ucc45\uc784\uc758 \uc694\uac74\uc744 \ubaa8\ub450 \ucda9\uc871\ud558\ub294 \uacbd\uc6b0, \ucc44\uad8c\uc790(\ud53c\ud574\uc790)\ub294 \ub450 \uccad\uad6c\uad8c \uc911 \uc5b4\ub290 \uac83\uc774\ub4e0 \uc120\ud0dd\uc801\uc73c\ub85c \ud589\uc0ac\ud560 \uc218 \uc788\ub294 \uccad\uad6c\uad8c\uacbd\ud569\uc744 \uc778\uc815\ud55c\ub2e4.",B.b_S,B.Z7,null)
B.aQe=s(['\uba85\uce6d\uc774 "\uc704\uc57d\uae08"\uc774\uba74 \ubb34\uc870\uac74 \uc704\uc57d\ubc8c\ub85c \ubcf8\ub2e4',"\uc190\ud574\ubc30\uc0c1\uc561\uc758 \uc608\uc815\uc740 \uc190\ud574\ubc30\uc0c1\uc758 \uc131\uaca9\uc744 \uac00\uc838 \ubc95\uc6d0\uc758 \uac10\uc561\uc774 \uac00\ub2a5\ud558\uc9c0\ub9cc, \uc704\uc57d\ubc8c\uc740 \uc81c\uc7ac\uc801 \uc131\uaca9\uc774 \uac15\ud574 \uc6d0\uce59\uc801\uc73c\ub85c \uac10\uc561 \ub300\uc0c1\uc774 \uc544\ub2c8\ub2e4(\ub2e4\ub9cc \uacfc\ub3c4\ud558\uba74 \uc77c\ubd80 \ubb34\ud6a8\ud654\ub420 \uc218 \uc788\ub2e4)","\uc704\uc57d\ubc8c\uc740 \ud56d\uc0c1 \uc190\ud574\ubc30\uc0c1\uc561\uc758 \uc608\uc815\ubcf4\ub2e4 \ubc95\uc801 \ud6a8\ub825\uc774 \uc57d\ud558\ub2e4","\uc190\ud574\ubc30\uc0c1\uc561\uc758 \uc608\uc815\uacfc \uc704\uc57d\ubc8c\uc740 \ubc95\uc801 \ud6a8\uacfc\uac00 \uc644\uc804\ud788 \ub3d9\uc77c\ud558\ub2e4"],t.s)
B.b70=s(["\uc704\uc57d\ubc8c\uc740 \uc81c\uc7ac\uc801 \uc131\uaca9\uc774 \uac15\ud574 \uc6d0\uce59\uc801\uc73c\ub85c \uac10\uc561 \ub300\uc0c1\uc774 \uc544\ub2c8\ub2e4"],t.s)
B.b9o=s(["\uc190\ud574\ubc30\uc0c1\uc561\uc758 \uc608\uc815\uacfc \uc704\uc57d\ubc8c\uc758 \uad6c\ubd84"],t.s)
B.btO=new A.a("gen_cl_nonperformance_17","civil_law","\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1",null,"\uc190\ud574\ubc30\uc0c1\uc561\uc758 \uc608\uc815\uacfc \uc704\uc57d\ubc8c\uc744 \uad6c\ubd84\ud558\ub294 \uae30\uc900\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aQe,1,"\uc190\ud574\ubc30\uc0c1\uc561\uc758 \uc608\uc815(\uc81c398\uc870)\uc740 \uc190\ud574\ubc30\uc0c1\uc758 \uc131\uc9c8\uc744 \uac00\uc9c0\ubbc0\ub85c \ubd80\ub2f9\ud788 \uacfc\ub2e4\ud558\uba74 \ubc95\uc6d0\uc774 \uac10\uc561\ud560 \uc218 \uc788\uc9c0\ub9cc, \uc704\uc57d\ubc8c\uc740 \ucc44\ubb34\uc774\ud589\uc744 \ud655\ubcf4\ud558\uae30 \uc704\ud55c \uc81c\uc7ac\uc758 \uc131\uaca9\uc774 \uac15\ud574 \uc6d0\uce59\uc801\uc73c\ub85c \uac10\uc561 \uaddc\uc815\uc774 \uc9c1\uc811 \uc801\uc6a9\ub418\uc9c0 \uc54a\uace0, \ub2e4\ub9cc \uc9c0\ub098\uce58\uac8c \uacfc\ub3c4\ud55c \uacbd\uc6b0 \uacf5\uc11c\uc591\uc18d \uc704\ubc18\uc73c\ub85c \uc77c\ubd80 \ubb34\ud6a8\uac00 \ub420 \uc218 \uc788\ub2e4.",B.b70,B.b9o,null)
B.aXj=s(["\ucc44\ubb34\ubd88\uc774\ud589\uc73c\ub85c \uc778\ud574 \ucc44\uad8c\uc790\uac00 \uc624\ud788\ub824 \uc774\uc775\uc744 \uc5bb\uc740 \uacbd\uc6b0, \uadf8 \uc774\uc775\uc744 \uc190\ud574\uc561\uc5d0\uc11c \uacf5\uc81c\ud558\ub294 \uac83\uc774\ub2e4","\uc190\uc775\uc0c1\uacc4\ub294 \ucc44\ubb34\uc790\uc758 \uc774\uc775\uc744 \ucc44\uad8c\uc790\uc5d0\uac8c \uc774\uc804\ud558\ub294 \uc81c\ub3c4\uc774\ub2e4","\uc190\uc775\uc0c1\uacc4\ub294 \uacfc\uc2e4\uc0c1\uacc4\uc640 \ub3d9\uc77c\ud55c \uac1c\ub150\uc774\ub2e4","\uc190\uc775\uc0c1\uacc4\ub294 \uc190\ud574\ubc30\uc0c1\uc561\uc744 \ud56d\uc0c1 \uc99d\uc561\uc2dc\ud0a4\ub294 \ubc29\ud5a5\uc73c\ub85c\ub9cc \uc791\uc6a9\ud55c\ub2e4"],t.s)
B.b2B=s(["\ucc44\uad8c\uc790(\ud53c\ud574\uc790)\uac00 \uc624\ud788\ub824 \uc774\uc775\uc744 \uc5bb\uc740 \uacbd\uc6b0, \uc190\ud574\ubc30\uc0c1\uc561\uc744 \uc0b0\uc815\ud560 \ub54c \uadf8 \uc774\uc775\uc744 \uacf5\uc81c"],t.s)
B.aC_=s(["\uc190\uc775\uc0c1\uacc4"],t.s)
B.bDc=new A.a("gen_cl_nonperformance_18","civil_law","\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1",null,"\uc190\uc775\uc0c1\uacc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aXj,0,"\uc190\uc775\uc0c1\uacc4\ub294 \ucc44\ubb34\ubd88\uc774\ud589\uc774\ub098 \uc190\ud574\ubc30\uc0c1 \uc6d0\uc778\uc774 \ub418\ub294 \uc0ac\uac74\uc73c\ub85c \uc778\ud574 \ucc44\uad8c\uc790(\ud53c\ud574\uc790)\uac00 \uc624\ud788\ub824 \uc774\uc775\uc744 \uc5bb\uc740 \uacbd\uc6b0, \uc190\ud574\ubc30\uc0c1\uc561\uc744 \uc0b0\uc815\ud560 \ub54c \uadf8 \uc774\uc775\uc744 \uacf5\uc81c\ud558\ub294 \uac83\uc73c\ub85c, \uc190\ud574\uc758 \uacf5\ud3c9\ud55c \ubd84\ub2f4\uc744 \uc704\ud55c \ubc95\ub9ac\uc774\ub2e4.",B.b2B,B.aC_,null)
B.aJ9=s([u.AS,"\uc190\ud574\ubc30\uc0c1\uc790\uc758 \ub300\uc704\ub294 \ucc44\uad8c\uc790\uac00 \uc77c\ubd80 \ubc30\uc0c1\ub9cc \ubc1b\uc740 \uacbd\uc6b0\uc5d0\ub3c4 \ud56d\uc0c1 \uc801\uc6a9\ub41c\ub2e4","\uc190\ud574\ubc30\uc0c1\uc790\uc758 \ub300\uc704\ub294 \ucc44\ubb34\uc790\uc758 \uad8c\ub9ac\ub97c \ucc44\uad8c\uc790\uc5d0\uac8c \uc774\uc804\ud558\ub294 \uc81c\ub3c4\uc774\ub2e4","\uc190\ud574\ubc30\uc0c1\uc790\uc758 \ub300\uc704\ub294 \ubd80\ub3d9\uc0b0\uc5d0\ub294 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.ac4=s([u.AS],t.s)
B.abd=s(["\uc190\ud574\ubc30\uc0c1\uc790\uc758 \ub300\uc704"],t.s)
B.bnE=new A.a("gen_cl_nonperformance_19","civil_law","\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1",null,"\uc190\ud574\ubc30\uc0c1\uc790\uc758 \ub300\uc704(\ubbfc\ubc95 \uc81c399\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aJ9,0,"\uc81c399\uc870\ub294 \ucc44\uad8c\uc790\uac00 \uc190\ud574\ubc30\uc0c1\uc73c\ub85c \uadf8 \ubb3c\uac74 \ub610\ub294 \uad8c\ub9ac\uc758 \uac00\uc561 \uc804\ubd80\ub97c \ubc1b\uc740 \ub54c \ucc44\ubb34\uc790\uac00 \uadf8 \ubb3c\uac74\uc774\ub098 \uad8c\ub9ac\uc5d0 \uad00\ud558\uc5ec \ucc44\uad8c\uc790\ub97c \ub300\uc704\ud55c\ub2e4\uace0 \uaddc\uc815\ud558\uc5ec, \ucc44\uad8c\uc790\uc758 \uc774\uc911\uc774\ub4dd\uc744 \ubc29\uc9c0\ud55c\ub2e4.",B.ac4,B.abd,null)
B.aqt=s(["\ucc44\uad8c\uc790\uac00 \uc815\ub2f9\ud55c \uc774\uc720 \uc5c6\uc774 \ubcc0\uc81c\uc758 \uc218\ub839\uc744 \uac70\ubd80\ud558\uac70\ub098 \uc218\ub839\ud560 \uc218 \uc5c6\ub294 \uacbd\uc6b0\ub97c \ub9d0\ud55c\ub2e4","\ucc44\uad8c\uc790\uc9c0\uccb4\ub294 \ucc44\ubb34\uc790\uc5d0\uac8c\ub9cc \ubc1c\uc0dd\ud560 \uc218 \uc788\ub294 \uac1c\ub150\uc774\ub2e4","\ucc44\uad8c\uc790\uc9c0\uccb4\uac00 \uc131\ub9bd\ud574\ub3c4 \ucc44\ubb34\uc790\uc758 \uc8fc\uc758\uc758\ubb34\ub294 \uc804\ud600 \uacbd\uac10\ub418\uc9c0 \uc54a\ub294\ub2e4","\ucc44\uad8c\uc790\uc9c0\uccb4\ub294 \uc774\ud589\uc9c0\uccb4\uc640 \uc644\uc804\ud788 \ub3d9\uc77c\ud55c \uac1c\ub150\uc774\ub2e4"],t.s)
B.ak0=s(["\ucc44\uad8c\uc790\uac00 \uc815\ub2f9\ud55c \uc774\uc720 \uc5c6\uc774 \uc774\ub97c \uc218\ub839\ud558\uc9c0 \uc54a\uac70\ub098 \uc218\ub839\ud560 \uc218 \uc5c6\ub294 \uacbd\uc6b0"],t.s)
B.alm=s(["\ucc44\uad8c\uc790\uc9c0\uccb4(\uc218\ub839\uc9c0\uccb4)"],t.s)
B.bzk=new A.a("gen_cl_nonperformance_20","civil_law","\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1",null,"\ucc44\uad8c\uc790\uc9c0\uccb4(\uc218\ub839\uc9c0\uccb4)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aqt,0,"\ucc44\uad8c\uc790\uc9c0\uccb4\ub294 \ucc44\ubb34\uc790\uac00 \ucc44\ubb34\uc758 \ub0b4\uc6a9\uc5d0 \uc887\uc740 \uc774\ud589\uc744 \uc81c\uacf5\ud558\uc600\uc74c\uc5d0\ub3c4 \ucc44\uad8c\uc790\uac00 \uc815\ub2f9\ud55c \uc774\uc720 \uc5c6\uc774 \uc774\ub97c \uc218\ub839\ud558\uc9c0 \uc54a\uac70\ub098 \uc218\ub839\ud560 \uc218 \uc5c6\ub294 \uacbd\uc6b0\ub97c \ub9d0\ud558\uba70, \uc774 \uacbd\uc6b0 \ucc44\ubb34\uc790\uc758 \uc8fc\uc758\uc758\ubb34\uac00 \uacbd\uac10\ub418\ub294 \ub4f1 \ud6a8\uacfc\uac00 \ubc1c\uc0dd\ud55c\ub2e4.",B.ak0,B.alm,null)
B.aCn=s(["\ubd80\uc218\uc801 \uc758\ubb34\ub97c \uc704\ubc18\ud558\uba74 \uacc4\uc57d\uc758 \ubcf8\uc9c8\uc801 \ubaa9\uc801 \ub2ec\uc131 \uc5ec\ubd80\uc640 \ubb34\uad00\ud558\uac8c \ud56d\uc0c1 \ud574\uc81c\ud560 \uc218 \uc788\ub2e4","\ubd80\uc218\uc801 \uc758\ubb34 \uc704\ubc18\ub9cc\uc73c\ub85c\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \ud574\uc81c\ud560 \uc218 \uc5c6\uace0, \uacc4\uc57d\uc758 \ubaa9\uc801 \ub2ec\uc131\uc5d0 \uc601\ud5a5\uc744 \uc8fc\ub294 \uc8fc\ub41c \uc758\ubb34 \uc704\ubc18\uc5d0 \uc774\ub974\ub7ec\uc57c \ud574\uc81c\uac00 \uac00\ub2a5\ud558\ub2e4","\ubd80\uc218\uc801 \uc758\ubb34\ub294 \uc560\ucd08\uc5d0 \ucc44\ubb34\ubd88\uc774\ud589 \ucc45\uc784\uc758 \ub300\uc0c1\uc774 \uc544\ub2c8\ub2e4","\ubd80\uc218\uc801 \uc758\ubb34 \uc704\ubc18\uc740 \uc5b8\uc81c\ub098 \uc190\ud574\ubc30\uc0c1 \uc5c6\uc774 \ud574\uc81c\ub9cc \uac00\ub2a5\ud558\ub2e4"],t.s)
B.b5c=s(["\uacc4\uc57d\uc758 \ubaa9\uc801\ub2ec\uc131\uc5d0 \ud544\uc694\ubd88\uac00\uacb0\ud55c \uc8fc\ub41c \ucc44\ubb34\uc758 \ubd88\uc774\ud589\uc5d0 \uc774\ub974\ub7ec\uc57c \ud574\uc81c\uad8c\uc774 \ubc1c\uc0dd\ud55c\ub2e4"],t.s)
B.aYZ=s(["\ubd80\uc218\uc801 \uc758\ubb34\uc640 \ud574\uc81c \uc81c\ud55c"],t.s)
B.bEp=new A.a("gen_cl_nonperformance_21","civil_law","\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1",null,"\ubd80\uc218\uc801 \uc758\ubb34 \uc704\ubc18\uacfc \uacc4\uc57d\ud574\uc81c\uc758 \uad00\uacc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aCn,1,"\ud310\ub840\ub294 \uacc4\uc57d\uc0c1 \uc758\ubb34 \uc911 \ubd80\uc218\uc801 \uc758\ubb34(\uc608: \ubd80\uc218\uc801\uc778 \uc548\ub0b4\xb7\ud611\uc870\uc758\ubb34 \ub4f1)\uc758 \uc704\ubc18\ub9cc\uc73c\ub85c\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \uacc4\uc57d\ud574\uc81c\ub97c \uc778\uc815\ud558\uc9c0 \uc54a\uace0, \uacc4\uc57d\uc758 \ubaa9\uc801\ub2ec\uc131\uc5d0 \ud544\uc694\ubd88\uac00\uacb0\ud55c \uc8fc\ub41c \ucc44\ubb34\uc758 \ubd88\uc774\ud589\uc5d0 \uc774\ub974\ub7ec\uc57c \ud574\uc81c\uad8c\uc774 \ubc1c\uc0dd\ud55c\ub2e4\uace0 \ubcf8\ub2e4.",B.b5c,B.aYZ,null)
B.aEV=s(["\ucc44\ubb34\uc790\uac00 \uc774\ud589\uae30 \uc804\uc5d0 \uc774\ud589\ud558\uc9c0 \uc54a\uc744 \uc758\uc0ac\ub97c \uba85\ubc31\ud788 \ud45c\uc2dc\ud55c \uacbd\uc6b0, \ud310\ub840\ub294 \uc774\ub97c \ub3c5\uc790\uc801 \ucc44\ubb34\ubd88\uc774\ud589 \uc720\ud615\uc73c\ub85c \uc778\uc815\ud574 \ucd5c\uace0 \uc5c6\uc774 \ud574\uc81c\xb7\uc190\ud574\ubc30\uc0c1\uc744 \ud5c8\uc6a9\ud55c\ub2e4","\uc774\ud589\uac70\uc808\uc740 \uc774\ud589\uc9c0\uccb4\uc758 \ud558\uc704 \uac1c\ub150\uc77c \ubfd0 \ubcc4\ub3c4\ub85c \ucde8\uae09\ub418\uc9c0 \uc54a\ub294\ub2e4","\uc774\ud589\uac70\uc808\uc740 \uc774\ud589\uae30\uac00 \ub3c4\ub798\ud55c \ud6c4\uc5d0\ub9cc \ubb38\uc81c\ub420 \uc218 \uc788\ub2e4","\uc774\ud589\uac70\uc808\uc774 \uc788\uc73c\uba74 \ucc44\uad8c\uc790\ub294 \ubc18\ub4dc\uc2dc \uc774\ud589\uae30\uae4c\uc9c0 \uae30\ub2e4\ub824\uc57c \ud55c\ub2e4"],t.s)
B.aN5=s(["\uc774\ud589\uae30 \ub3c4\ub798\ub098 \ucd5c\uace0\ub97c \uae30\ub2e4\ub9b4 \ud544\uc694 \uc5c6\uc774 \ucc44\uad8c\uc790\uac00 \ubc14\ub85c \uc190\ud574\ubc30\uc0c1\uc744 \uccad\uad6c\ud558\uac70\ub098 \uacc4\uc57d\uc744 \ud574\uc81c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.aV7=s(["\uc774\ud589\uac70\uc808\uc758 \ub3c5\uc790\uc801 \uc720\ud615\uc131"],t.s)
B.btM=new A.a("gen_cl_nonperformance_22","civil_law","\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1",null,"\uc774\ud589\uac70\uc808\uc774 \ub3c5\uc790\uc801\uc778 \ucc44\ubb34\ubd88\uc774\ud589 \uc720\ud615\uc73c\ub85c \uc778\uc815\ub418\ub294\uc9c0\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aEV,0,"\ud310\ub840\ub294 \ucc44\ubb34\uc790\uac00 \ubbf8\ub9ac \uc774\ud589\ud558\uc9c0 \uc54a\uc744 \uc758\uc0ac\ub97c \uba85\ubc31\ud558\uace0 \ud655\uc815\uc801\uc73c\ub85c \ud45c\uc2dc\ud55c \uacbd\uc6b0(\uc774\ud589\uac70\uc808) \uc774\ud589\uae30 \ub3c4\ub798\ub098 \ucd5c\uace0\ub97c \uae30\ub2e4\ub9b4 \ud544\uc694 \uc5c6\uc774 \ucc44\uad8c\uc790\uac00 \ubc14\ub85c \uc190\ud574\ubc30\uc0c1\uc744 \uccad\uad6c\ud558\uac70\ub098 \uacc4\uc57d\uc744 \ud574\uc81c\ud560 \uc218 \uc788\ub2e4\uace0 \ubcf8\ub2e4.",B.aN5,B.aV7,null)
B.aNM=s(["\ub2f9\uc0ac\uc790 \uc0ac\uc774\uc5d0 \ub2e4\ub978 \uc57d\uc815(\ucd08\uacfc\uc190\ud574 \ubc30\uc0c1 \ud2b9\uc57d \ub4f1)\uc774 \uc5c6\ub294 \ud55c \uc6d0\uce59\uc801\uc73c\ub85c \uc608\uc815\uc561\ub9cc \uccad\uad6c\ud560 \uc218 \uc788\uace0 \uc2e4\uc190\ud574\uac00 \ub354 \ud06c\ub2e4\ub294 \uc774\uc720\ub85c \ucd94\uac00 \uccad\uad6c\ud560 \uc218 \uc5c6\ub2e4","\ud56d\uc0c1 \uc2e4\uc190\ud574 \uc804\uc561\uc744 \uc790\uc720\ub86d\uac8c \ucd94\uac00\ub85c \uccad\uad6c\ud560 \uc218 \uc788\ub2e4","\uc190\ud574\ubc30\uc0c1\uc561\uc758 \uc608\uc815\uc774 \uc788\uc73c\uba74 \uc190\ud574\ubc30\uc0c1 \uc790\uccb4\ub97c \uc544\uc608 \uccad\uad6c\ud560 \uc218 \uc5c6\ub2e4","\uc608\uc815\uc561\uacfc \uc2e4\uc190\ud574\uc561 \uc911 \ub354 \uc801\uc740 \uae08\uc561\ub9cc \uccad\uad6c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.bhg=s(["\ud2b9\uc57d\uc774 \uc5c6\ub294 \ud55c \uc2e4\uc190\ud574\uac00 \ub354 \ud06c\ub2e4\ub294 \uc774\uc720\ub85c \ucd08\uacfc\ubd84\uc744 \ucd94\uac00\ub85c \uccad\uad6c\ud560 \uc218 \uc5c6\ub294 \uac83\uc774 \uc6d0\uce59"],t.s)
B.VA=s(["\uc190\ud574\ubc30\uc0c1\uc561 \uc608\uc815\uacfc \ucd08\uacfc\uc190\ud574"],t.s)
B.bE4=new A.a("gen_cl_nonperformance_23","civil_law","\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1",null,"\uc190\ud574\ubc30\uc0c1\uc561\uc758 \uc608\uc815\uc774 \uc788\ub294 \uacbd\uc6b0, \ucc44\uad8c\uc790\uac00 \uc608\uc815\uc561\uc744 \ucd08\uacfc\ud558\ub294 \uc2e4\uc81c \uc190\ud574\ub97c \uc99d\uba85\ud558\uc5ec \ucd94\uac00\ub85c \ubc30\uc0c1\ubc1b\uc744 \uc218 \uc788\ub294\uc9c0\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aNM,0,"\uc190\ud574\ubc30\uc0c1\uc561\uc758 \uc608\uc815\uc774 \uc788\ub294 \uacbd\uc6b0 \uc6d0\uce59\uc801\uc73c\ub85c \ucc44\uad8c\uc790\ub294 \uc2e4\uc81c \uc190\ud574\uc758 \ubc1c\uc0dd\uc774\ub098 \uadf8 \uc561\uc218\ub97c \uc99d\uba85\ud560 \ud544\uc694 \uc5c6\uc774 \uc608\uc815\uc561\ub9cc\uc744 \uccad\uad6c\ud560 \uc218 \uc788\uace0, \ud2b9\uc57d\uc774 \uc5c6\ub294 \ud55c \uc2e4\uc190\ud574\uac00 \ub354 \ud06c\ub2e4\ub294 \uc774\uc720\ub85c \ucd08\uacfc\ubd84\uc744 \ucd94\uac00\ub85c \uccad\uad6c\ud560 \uc218 \uc5c6\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub2e4.",B.bhg,B.VA,null)
B.aNb=s(["\ub2f9\uc0ac\uc790 \uc0ac\uc774\uc5d0 \uc57d\uc815\uc774\uc728\uc774 \uc5c6\uc73c\uba74 \ubc95\uc815\uc774\uc728\uc5d0 \ub530\ub77c \uc9c0\uc5f0\uc190\ud574\uae08\uc744 \uc0b0\uc815\ud55c\ub2e4","\uc9c0\uc5f0\uc190\ud574\uae08\uc740 \ud56d\uc0c1 \ubb34\uc774\uc790\ub85c \uacc4\uc0b0\ud55c\ub2e4","\uc9c0\uc5f0\uc190\ud574\uae08\uc740 \uc774\uc728\uacfc \ubb34\uad00\ud558\uac8c \uc815\uc561\uc73c\ub85c\ub9cc \uc0b0\uc815\ub41c\ub2e4","\uc9c0\uc5f0\uc190\ud574\uae08\uc740 \ubc18\ub4dc\uc2dc \uc18c\uc1a1\uc744 \uac70\uccd0\uc57c\ub9cc \ubc1c\uc0dd\ud55c\ub2e4"],t.s)
B.ZW=s(["\uc6d0\uce59\uc801\uc73c\ub85c \ubc95\uc815\uc774\uc728\uc5d0 \uc758\ud558\ub418, \ub2f9\uc0ac\uc790 \uc0ac\uc774\uc5d0 \uc774\ubcf4\ub2e4 \ub192\uc740 \uc57d\uc815\uc774\uc728\uc774 \uc788\uc73c\uba74 \uadf8 \uc57d\uc815\uc774\uc728\uc5d0 \ub530\ub77c \uc0b0\uc815"],t.s)
B.b9h=s(["\uae08\uc804\ucc44\ubb34 \uc9c0\uc5f0\uc190\ud574\uae08 \uc774\uc728"],t.s)
B.bul=new A.a("gen_cl_nonperformance_24","civil_law","\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1",null,"\uae08\uc804\ucc44\ubb34\uc758 \uc9c0\uc5f0\uc190\ud574\uae08 \uc774\uc728 \uc0b0\uc815\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aNb,0,"\uae08\uc804\ucc44\ubb34\ubd88\uc774\ud589\uc758 \uacbd\uc6b0 \uc190\ud574\ubc30\uc0c1\uc561\uc740 \uc6d0\uce59\uc801\uc73c\ub85c \ubc95\uc815\uc774\uc728\uc5d0 \uc758\ud558\ub418, \ub2f9\uc0ac\uc790 \uc0ac\uc774\uc5d0 \uc774\ubcf4\ub2e4 \ub192\uc740 \uc57d\uc815\uc774\uc728\uc774 \uc788\uc73c\uba74 \uadf8 \uc57d\uc815\uc774\uc728\uc5d0 \ub530\ub77c \uc0b0\uc815\ud55c\ub2e4(\uc81c397\uc870).",B.ZW,B.b9h,null)
B.bat=s(["\uc548\uc804\ubc30\ub824\uc758\ubb34\ub294 \uacc4\uc57d\uc758 \ubd80\uc218\uc801 \uc758\ubb34\ub85c\uc11c \uadf8 \uc704\ubc18\uc740 \ucc44\ubb34\ubd88\uc774\ud589\ucc45\uc784\uc758 \ubb38\uc81c\uac00 \ub420 \uc218 \uc788\ub2e4","\uc548\uc804\ubc30\ub824\uc758\ubb34\ub294 \ubd88\ubc95\ud589\uc704\ucc45\uc784\uc5d0\uc11c\ub9cc \ubb38\uc81c\ub418\uace0 \ucc44\ubb34\ubd88\uc774\ud589\uacfc\ub294 \ubb34\uad00\ud558\ub2e4","\uc548\uc804\ubc30\ub824\uc758\ubb34\ub294 \uba85\ubb38 \uaddc\uc815\uc774 \uc788\uc5b4\uc57c\ub9cc \uc778\uc815\ub41c\ub2e4","\uc548\uc804\ubc30\ub824\uc758\ubb34 \uc704\ubc18\uc740 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \uc190\ud574\ubc30\uc0c1\ucc45\uc784\uc744 \ubc1c\uc0dd\uc2dc\ud0a4\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.aot=s(["\uc2e0\uc758\uce59\uc0c1 \ubd80\uc218\uc801 \uc758\ubb34\ub85c \uc548\uc804\ubc30\ub824\uc758\ubb34\ub97c \uc778\uc815\ud558\uba70","\uc774\ub97c \uc704\ubc18\ud558\uc5ec \uc0c1\ub300\ubc29\uc5d0\uac8c \uc190\ud574\ub97c \uac00\ud55c \uacbd\uc6b0 \ucc44\ubb34\ubd88\uc774\ud589\ucc45\uc784\uc774 \uc131\ub9bd"],t.s)
B.b2S=s(["\uc548\uc804\ubc30\ub824\uc758\ubb34"],t.s)
B.bzN=new A.a("gen_cl_nonperformance_25","civil_law","\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1",null,"\uc548\uc804\ubc30\ub824\uc758\ubb34 \uc704\ubc18\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.bat,0,"\ud310\ub840\ub294 \uadfc\ub85c\uacc4\uc57d\uc774\ub098 \uc219\ubc15\uacc4\uc57d \ub4f1 \uc77c\uc815\ud55c \uacc4\uc18d\uc801 \uacc4\uc57d\uad00\uacc4\uc5d0\uc11c \uc2e0\uc758\uce59\uc0c1 \ubd80\uc218\uc801 \uc758\ubb34\ub85c \uc548\uc804\ubc30\ub824\uc758\ubb34\ub97c \uc778\uc815\ud558\uba70, \uc774\ub97c \uc704\ubc18\ud558\uc5ec \uc0c1\ub300\ubc29\uc5d0\uac8c \uc190\ud574\ub97c \uac00\ud55c \uacbd\uc6b0 \ucc44\ubb34\ubd88\uc774\ud589\ucc45\uc784\uc774 \uc131\ub9bd\ud560 \uc218 \uc788\ub2e4\uace0 \ubcf8\ub2e4.",B.aot,B.b2S,null)
B.a93=s(["\uc774\ud589\uc9c0\uccb4 \uc911\uc778 \ucc44\ubb34\uc790\ub294 \uadf8 \ubd88\ub2a5\uc5d0 \uad00\ud558\uc5ec \uc790\uae30\uc758 \uadc0\ucc45\uc0ac\uc720\uac00 \uc5c6\ub354\ub77c\ub3c4 \uc6d0\uce59\uc801\uc73c\ub85c \ucc45\uc784\uc744 \uba74\ud558\uc9c0 \ubabb\ud55c\ub2e4","\uc774\ud589\uc9c0\uccb4 \uc911\uc774\ub77c\ub3c4 \uadc0\ucc45\uc0ac\uc720\uac00 \uc5c6\uc73c\uba74 \ucc44\ubb34\uc790\ub294 \ud56d\uc0c1 \ucc45\uc784\uc744 \uba74\ud55c\ub2e4","\uc774\ud589\uc9c0\uccb4 \uc911 \ubc1c\uc0dd\ud55c \ud6c4\ubc1c\uc801 \ubd88\ub2a5\uc740 \uc5b8\uc81c\ub098 \uc704\ud5d8\ubd80\ub2f4 \ubb38\uc81c\ub85c\ub9cc \ucc98\ub9ac\ub41c\ub2e4","\uc774\ud589\uc9c0\uccb4 \uc911\uc778 \ucc44\ubb34\uc790\ub294 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \uc190\ud574\ubc30\uc0c1\ucc45\uc784\uc744 \uc9c0\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.SA=s(["\uadf8 \ubd88\ub2a5\uc5d0 \uad00\ud558\uc5ec \uc790\uae30\uc758 \uadc0\ucc45\uc0ac\uc720\uac00 \uc5c6\ub354\ub77c\ub3c4 \uc6d0\uce59\uc801\uc73c\ub85c \ucc45\uc784\uc744 \uba74\ud558\uc9c0 \ubabb\ud55c\ub2e4"],t.s)
B.a39=s(["\uc774\ud589\uc9c0\uccb4 \uc911\uc758 \ubd88\ub2a5\uacfc \ucc45\uc784"],t.s)
B.bsx=new A.a("gen_cl_nonperformance_26","civil_law","\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1",null,"\uc774\ud589\uc9c0\uccb4 \uc911\uc5d0 \ub2f9\uc0ac\uc790 \uc30d\ubc29\uc758 \uadc0\ucc45\uc0ac\uc720 \uc5c6\uc774 \uc774\ud589\uc774 \ubd88\ub2a5\ud558\uac8c \ub41c \uacbd\uc6b0\uc758 \ucc45\uc784\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.a93,0,"\uc774\ud589\uc9c0\uccb4\uc5d0 \ube60\uc9c4 \ucc44\ubb34\uc790\ub294 \uadf8 \ud6c4 \ubc1c\uc0dd\ud55c \uc774\ud589\ubd88\ub2a5\uc5d0 \uad00\ud558\uc5ec \uc790\uc2e0\uc5d0\uac8c \uadc0\ucc45\uc0ac\uc720\uac00 \uc5c6\uc74c\uc744 \uc99d\uba85\ud558\uc9c0 \ubabb\ud558\ub294 \ud55c \ucc45\uc784\uc744 \uba74\ud558\uc9c0 \ubabb\ud558\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub2e4(\uc774\ud589\uc9c0\uccb4 \uc911\uc758 \ubd88\ub2a5\uc5d0 \ub300\ud55c \ucc44\ubb34\uc790\uc758 \uac00\uc911\ub41c \ucc45\uc784).",B.SA,B.a39,null)
B.atL=s(["\uc774\ud589\uc774\uc775\uc740 \uacc4\uc57d\uc774 \uc81c\ub300\ub85c \uc774\ud589\ub418\uc5c8\ub354\ub77c\uba74 \uc5bb\uc5c8\uc744 \uc774\uc775\uc774\uace0, \uc2e0\ub8b0\uc774\uc775\uc740 \uacc4\uc57d\uc758 \uc720\ud6a8\ub97c \ubbff\uc5c8\uae30 \ub54c\ubb38\uc5d0 \uc9c0\ucd9c\ud55c \ube44\uc6a9 \ub4f1\uc758 \uc190\ud574\uc774\ub2e4","\uc774\ud589\uc774\uc775\uacfc \uc2e0\ub8b0\uc774\uc775\uc740 \uc644\uc804\ud788 \ub3d9\uc77c\ud55c \uac1c\ub150\uc774\ub2e4","\uc2e0\ub8b0\uc774\uc775\uc740 \ud56d\uc0c1 \uc774\ud589\uc774\uc775\ubcf4\ub2e4 \ud06c\ub2e4","\uc774\ud589\uc774\uc775\uc740 \uacc4\uc57d\uc774 \ubb34\ud6a8\uc778 \uacbd\uc6b0\uc5d0\ub9cc \ubb38\uc81c\ub41c\ub2e4"],t.s)
B.b7S=s(["\uc2e0\ub8b0\uc774\uc775\uc740 \uacc4\uc57d\uc758 \uc720\ud6a8\ub97c \ubbff\uc5c8\uae30 \ub54c\ubb38\uc5d0 \uc9c0\ucd9c\ud55c \ube44\uc6a9 \ub4f1\uc758 \uc190\ud574"],t.s)
B.bbZ=s(["\uc774\ud589\uc774\uc775\uacfc \uc2e0\ub8b0\uc774\uc775\uc758 \uad6c\ubd84"],t.s)
B.bnR=new A.a("gen_cl_nonperformance_27","civil_law","\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1",null,"\uc774\ud589\uc774\uc775\uacfc \uc2e0\ub8b0\uc774\uc775\uc758 \uad6c\ubd84\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.atL,0,"\uc774\ud589\uc774\uc775\uc740 \ucc44\ubb34\uac00 \uc81c\ub300\ub85c \uc774\ud589\ub418\uc5c8\ub354\ub77c\uba74 \ucc44\uad8c\uc790\uac00 \uc5bb\uc5c8\uc744 \uc774\uc775(\uc804\ubcf4\ubc30\uc0c1\uc758 \uae30\ubcf8 \ubc94\uc704)\uc744 \ub9d0\ud558\uace0, \uc2e0\ub8b0\uc774\uc775\uc740 \uacc4\uc57d\uc774 \uc720\ud6a8\ud558\ub2e4\uace0 \ubbff\uc74c\uc73c\ub85c\uc368 \uc9c0\ucd9c\ud55c \ube44\uc6a9 \ub4f1 \uadf8 \uc2e0\ub8b0\ub85c \uc778\ud55c \uc190\ud574\ub97c \ub9d0\ud558\uba70, \uacc4\uc57d\uccb4\uacb0\uc0c1 \uacfc\uc2e4\ucc45\uc784 \ub4f1\uc5d0\uc11c\ub294 \uc2e0\ub8b0\uc774\uc775 \ubc30\uc0c1\uc774 \ubb38\uc81c\ub41c\ub2e4.",B.b7S,B.bbZ,null)
B.acb=s(["\uc804\ubcf4\ubc30\uc0c1\uccad\uad6c\uad8c\ub3c4 \uc6d0\ub798 \ucc44\ubb34\uc640 \ub300\uac00\uad00\uacc4\uc5d0 \uc788\ub358 \ubc18\ub300\uae09\ubd80\uc640 \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uac00 \uc778\uc815\ub420 \uc218 \uc788\ub2e4","\uc804\ubcf4\ubc30\uc0c1\uccad\uad6c\uad8c\uc774 \uc131\ub9bd\ud558\uba74 \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\ub294 \ub2f9\uc5f0\ud788 \uc18c\uba78\ud55c\ub2e4","\uc804\ubcf4\ubc30\uc0c1\uccad\uad6c\uad8c\uc740 \ud56d\uc0c1 \uc120\uc774\ud589\ub418\uc5b4\uc57c \ud55c\ub2e4","\uc804\ubcf4\ubc30\uc0c1\uccad\uad6c\uad8c\uc5d0\ub294 \ub3d9\uc2dc\uc774\ud589 \uaddc\uc815\uc774 \uc808\ub300 \uc900\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.a2m=s(["\uadf8 \uc190\ud574\ubc30\uc0c1\ucc44\ubb34\ub294 \uc6d0\ub798 \ucc44\ubb34\uc640 \ub3d9\uc77c\uc131\uc744 \uc720\uc9c0\ud558\ub294 \uac83\uc73c\ub85c \ubcf4\uc544 \uc0c1\ub300\ubc29\uc758 \ubc18\ub300\uae09\ubd80\uc640 \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uac00 \uadf8\ub300\ub85c \uc720\uc9c0\ub420 \uc218 \uc788\ub2e4"],t.s)
B.aDw=s(["\uc804\ubcf4\ubc30\uc0c1\uccad\uad6c\uad8c\uacfc \ub3d9\uc2dc\uc774\ud589"],t.s)
B.bsL=new A.a("gen_cl_nonperformance_28","civil_law","\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1",null,"\ucc44\ubb34\ubd88\uc774\ud589\uc73c\ub85c \uc778\ud55c \uc190\ud574\ubc30\uc0c1\uccad\uad6c\uad8c\uacfc \ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c\uc758 \uad00\uacc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.acb,0,"\uc774\ud589\ubd88\ub2a5\uc73c\ub85c \ubcf8\ub798 \ucc44\ubb34\uac00 \uc804\ubcf4\ubc30\uc0c1\ucc44\ubb34\ub85c \uc804\ud658\ub418\uc5b4\ub3c4, \uadf8 \uc190\ud574\ubc30\uc0c1\ucc44\ubb34\ub294 \uc6d0\ub798 \ucc44\ubb34\uc640 \ub3d9\uc77c\uc131\uc744 \uc720\uc9c0\ud558\ub294 \uac83\uc73c\ub85c \ubcf4\uc544 \uc0c1\ub300\ubc29\uc758 \ubc18\ub300\uae09\ubd80\uc640 \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uac00 \uadf8\ub300\ub85c \uc720\uc9c0\ub420 \uc218 \uc788\ub2e4\ub294 \uac83\uc774 \ud310\ub840\uc758 \uc785\uc7a5\uc774\ub2e4.",B.a2m,B.aDw,null)
B.aTy=s(["\uae09\ubd80\ubaa9\uc801\ubb3c \uc790\uccb4\uc758 \ud558\uc790\ub97c \ub118\uc5b4 \ucc44\uad8c\uc790\uc758 \ub2e4\ub978 \ubc95\uc775(\uc0dd\uba85\xb7\uc2e0\uccb4\xb7\ub2e4\ub978 \uc7ac\uc0b0 \ub4f1)\uc5d0\uae4c\uc9c0 \uc190\ud574\uac00 \ud655\ub300\ub41c \uacbd\uc6b0\ub3c4 \ucc44\ubb34\ubd88\uc774\ud589\ucc45\uc784\uc758 \ub300\uc0c1\uc774 \ub420 \uc218 \uc788\ub2e4","\ud655\ub300\uc190\ud574\ub294 \ud56d\uc0c1 \ubd88\ubc95\ud589\uc704\ucc45\uc784\uc73c\ub85c\ub9cc \ud574\uacb0\ud574\uc57c \ud558\uace0 \ucc44\ubb34\ubd88\uc774\ud589\uacfc\ub294 \ubb34\uad00\ud558\ub2e4","\ud655\ub300\uc190\ud574\ub294 \uc190\ud574\ubc30\uc0c1\uc758 \ubc94\uc704\uc5d0\uc11c \uc81c\uc678\ub418\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub2e4","\ud655\ub300\uc190\ud574\ub294 \uae09\ubd80\ubaa9\uc801\ubb3c \uc790\uccb4\uc758 \ud558\uc790\uc640 \uad6c\ubcc4\ud560 \ud544\uc694\uac00 \uc5c6\ub2e4"],t.s)
B.aDb=s(["\ucc44\uad8c\uc790\uc758 \ub2e4\ub978 \ubc95\uc775(\uc0dd\uba85\xb7\uc2e0\uccb4\xb7\ub2e4\ub978 \uc7ac\uc0b0 \ub4f1)\uc5d0\uae4c\uc9c0 \uc190\ud574\uac00 \ud655\ub300\ub41c \uacbd\uc6b0\ub3c4 \ucc44\ubb34\ubd88\uc774\ud589\ucc45\uc784\uc758 \ub300\uc0c1\uc774 \ub420 \uc218 \uc788\ub2e4"],t.s)
B.azI=s(["\ubd88\uc644\uc804\uc774\ud589\uacfc \ud655\ub300\uc190\ud574"],t.s)
B.by6=new A.a("gen_cl_nonperformance_29","civil_law","\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1",null,"\ubd88\uc644\uc804\uc774\ud589\uc73c\ub85c \uc778\ud574 \ud655\ub300\uc190\ud574(\uc801\uadf9\uc801 \ucc44\uad8c\uce68\ud574)\uac00 \ubc1c\uc0dd\ud55c \uacbd\uc6b0\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aTy,0,"\ubd88\uc644\uc804\uc774\ud589\uc73c\ub85c \uae09\ubd80\ubaa9\uc801\ubb3c \uc790\uccb4\uc758 \ud558\uc790\ub97c \ub118\uc5b4 \ucc44\uad8c\uc790\uc758 \uc0dd\uba85\xb7\uc2e0\uccb4\xb7\ub2e4\ub978 \uc7ac\uc0b0\uc5d0\uae4c\uc9c0 \uc190\ud574\uac00 \ud655\ub300\ub41c \uacbd\uc6b0(\uc801\uadf9\uc801 \ucc44\uad8c\uce68\ud574)\uc5d0\ub3c4 \ucc44\ubb34\ubd88\uc774\ud589\ucc45\uc784\uc774 \uc778\uc815\ub420 \uc218 \uc788\uc73c\uba70, \ud1b5\uc0c1 \ubd88\ubc95\ud589\uc704\ucc45\uc784\uacfc \uacbd\ud569\ud558\ub294 \uacbd\uc6b0\uac00 \ub9ce\ub2e4.",B.aDb,B.azI,null)
B.aM8=s(["\uc774\ud589\ubcf4\uc870\uc790\uc758 \uace0\uc758\xb7\uacfc\uc2e4\uc740 \ucc44\ubb34\uc790 \uc790\uc2e0\uc758 \uace0\uc758\xb7\uacfc\uc2e4\ub85c \ucde8\uae09\ub41c\ub2e4","\uc774\ud589\uac70\uc808\uc774 \uba85\ubc31\ud55c \uacbd\uc6b0 \ucc44\uad8c\uc790\ub294 \uc774\ud589\uae30\ub97c \uae30\ub2e4\ub9ac\uc9c0 \uc54a\uace0 \ud574\uc81c\xb7\uc190\ud574\ubc30\uc0c1\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4","\uc190\ud574\ubc30\uc0c1\uc561\uc758 \uc608\uc815\uc774 \uc788\uc73c\uba74 \ucc44\uad8c\uc790\ub294 \uc2e4\uc190\ud574 \uc99d\uba85 \uc5c6\uc774 \uc608\uc815\uc561\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4","\uc190\uc775\uc0c1\uacc4\ub294 \ucc44\ubb34\uc790\uac00 \uc5bb\uc740 \uc774\uc775\uc744 \ucc44\uad8c\uc790\uc758 \uc190\ud574\uc561\uc5d0\uc11c \uacf5\uc81c\ud558\ub294 \uc81c\ub3c4\uc774\ub2e4"],t.s)
B.ak6=s(['"\ucc44\uad8c\uc790"\uac00 \ucc44\ubb34\ubd88\uc774\ud589 \ub4f1\uc758 \uc6d0\uc778\uc774 \ub41c \uc0ac\uac74\uc73c\ub85c \uc624\ud788\ub824 \uc774\uc775\uc744 \uc5bb\uc740 \uacbd\uc6b0 \uadf8 \uc774\uc775\uc744 \uc190\ud574\uc561\uc5d0\uc11c \uacf5\uc81c'],t.s)
B.b2V=s(["\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1 \uc2ec\ud654\uc815\ub9ac"],t.s)
B.bq9=new A.a("gen_cl_nonperformance_30","civil_law","\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1",null,"\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1\uc5d0 \uad00\ud55c \uc2ec\ud654 \uc0ac\ub840 \u2014 \ub2e4\uc74c \uc911 \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aM8,3,'\uc190\uc775\uc0c1\uacc4\ub294 "\ucc44\uad8c\uc790"\uac00 \ucc44\ubb34\ubd88\uc774\ud589 \ub4f1\uc758 \uc6d0\uc778\uc774 \ub41c \uc0ac\uac74\uc73c\ub85c \uc624\ud788\ub824 \uc774\uc775\uc744 \uc5bb\uc740 \uacbd\uc6b0 \uadf8 \uc774\uc775\uc744 \uc190\ud574\uc561\uc5d0\uc11c \uacf5\uc81c\ud558\ub294 \uc81c\ub3c4\uc774\uc9c0, \ucc44\ubb34\uc790\uac00 \uc5bb\uc740 \uc774\uc775\uc744 \uacf5\uc81c\ud558\ub294 \uac83\uc774 \uc544\ub2c8\ubbc0\ub85c \ud574\ub2f9 \uc124\uba85\uc740 \uc633\uc9c0 \uc54a\ub2e4.',B.ak6,B.b2V,null)
B.b5T=s(["\ud574\uc81c\ub294 \uc7a5\ub798\ud6a8\ub9cc \uc788\uace0, \ud574\uc9c0\ub294 \uc18c\uae09\ud6a8\uac00 \uc788\ub2e4","\ud574\uc81c\ub294 \uc77c\ud68c\uc801 \uacc4\uc57d\uc5d0, \ud574\uc9c0\ub294 \uacc4\uc18d\uc801 \uacc4\uc57d\uc5d0 \uc8fc\ub85c \uc801\uc6a9\ub418\uba70 \ud574\uc9c0\ub294 \uc18c\uae09\ud6a8\uac00 \uc5c6\ub2e4","\ud574\uc81c\uc640 \ud574\uc9c0\ub294 \ubc95\uc801 \ud6a8\uacfc\uac00 \uc644\uc804\ud788 \ub3d9\uc77c\ud558\ub2e4","\ud574\uc9c0\ub294 \ubc18\ub4dc\uc2dc \ubc95\uc6d0\uc758 \ud310\uacb0\uc5d0 \uc758\ud574\uc11c\ub9cc \uac00\ub2a5\ud558\ub2e4"],t.s)
B.aMN=s(["\ud574\uc9c0\ub294 \uc784\ub300\ucc28\xb7\uace0\uc6a9 \ub4f1 \uacc4\uc18d\uc801 \uacc4\uc57d\uad00\uacc4\ub97c \uc7a5\ub798\ub97c \ud5a5\ud574\uc11c\ub9cc \uc885\ub8cc\uc2dc\ud0a4\ub294 \uac83\uc73c\ub85c \uc18c\uae09\ud6a8\uac00 \uc5c6\ub2e4"],t.s)
B.ata=s(["\ud574\uc81c\uc640 \ud574\uc9c0\uc758 \uad6c\ubd84"],t.s)
B.bpF=new A.a("gen_cl_termination_1","civil_law","\uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0",null,"\uacc4\uc57d\uc758 \ud574\uc81c\uc640 \ud574\uc9c0\ub97c \ube44\uad50\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.b5T,1,"\ud574\uc81c\ub294 \ub9e4\ub9e4\uc640 \uac19\uc740 \uc77c\ud68c\uc801 \uacc4\uc57d\uc758 \ud6a8\ub825\uc744 \uc18c\uae09\uc801\uc73c\ub85c \uc18c\uba78\uc2dc\ud0a4\ub294 \uac83\uc774\uace0, \ud574\uc9c0\ub294 \uc784\ub300\ucc28\xb7\uace0\uc6a9 \ub4f1 \uacc4\uc18d\uc801 \uacc4\uc57d\uad00\uacc4\ub97c \uc7a5\ub798\ub97c \ud5a5\ud574\uc11c\ub9cc \uc885\ub8cc\uc2dc\ud0a4\ub294 \uac83\uc73c\ub85c \uc18c\uae09\ud6a8\uac00 \uc5c6\ub2e4\ub294 \uc810\uc774 \ud575\uc2ec \ucc28\uc774\ub2e4.",B.aMN,B.ata,null)
B.avh=s(["\ucc44\ubb34\uc790\uac00 \uc774\ud589\uae30\uc5d0 \uc774\ud589\uc744 \uc9c0\uccb4\ud558\uc600\uc744 \uac83","\ucc44\uad8c\uc790\uac00 \uc0c1\ub2f9\ud55c \uae30\uac04\uc744 \uc815\ud558\uc5ec \uc774\ud589\uc744 \ucd5c\uace0\ud558\uc600\uc744 \uac83","\uc815\ud55c \uae30\uac04 \ub0b4\uc5d0 \uc774\ud589\uc774 \uc5c6\uc5c8\uc744 \uac83","\ucc44\uad8c\uc790\uac00 \ubc18\ub4dc\uc2dc \ubc95\uc6d0\uc758 \ud5c8\uac00\ub97c \ubc1b\uc558\uc744 \uac83"],t.s)
B.aVM=s(["\ucc44\uad8c\uc790\uc758 \uc77c\ubc29\uc801 \uc758\uc0ac\ud45c\uc2dc\ub85c \uac00\ub2a5\ud558\uba70, \ubc95\uc6d0\uc758 \ud5c8\uac00\ub294 \uc694\uac74\uc774 \uc544\ub2c8\ub2e4"],t.s)
B.ai2=s(["\uc774\ud589\uc9c0\uccb4\uc640 \ubc95\uc815\ud574\uc81c \uc694\uac74"],t.s)
B.byo=new A.a("gen_cl_termination_2","civil_law","\uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0",null,"\uc774\ud589\uc9c0\uccb4\ub97c \uc774\uc720\ub85c \ud55c \ubc95\uc815\ud574\uc81c\uad8c \ud589\uc0ac\uc694\uac74\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.avh,3,"\uc774\ud589\uc9c0\uccb4\ub97c \uc774\uc720\ub85c \ud55c \ud574\uc81c(\uc81c544\uc870)\ub294 \uc0c1\ub2f9\uae30\uac04\uc744 \uc815\ud55c \ucd5c\uace0\uc640 \uadf8 \uae30\uac04 \ub0b4 \ubd88\uc774\ud589\ub9cc \uc788\uc73c\uba74 \ucc44\uad8c\uc790\uc758 \uc77c\ubc29\uc801 \uc758\uc0ac\ud45c\uc2dc\ub85c \uac00\ub2a5\ud558\uba70, \ubc95\uc6d0\uc758 \ud5c8\uac00\ub294 \uc694\uac74\uc774 \uc544\ub2c8\ub2e4.",B.aVM,B.ai2,null)
B.bea=s(["\ud574\uc81c\ub294 \ubc18\ub4dc\uc2dc \uc11c\uba74\uc73c\ub85c\ub9cc \ud560 \uc218 \uc788\ub2e4","\ud574\uc81c\ub294 \uc0c1\ub300\ubc29\uc5d0 \ub300\ud55c \uc758\uc0ac\ud45c\uc2dc\ub85c \ud558\uba70, \uc77c\ub2e8 \ud589\uc0ac\ud558\uba74 \ucca0\ud68c\ud558\uc9c0 \ubabb\ud55c\ub2e4","\ud574\uc81c\uc758 \uc758\uc0ac\ud45c\uc2dc\ub294 \uc870\uac74\uc744 \ubd99\uc5ec\uc11c\ub9cc \ud560 \uc218 \uc788\ub2e4","\ud574\uc81c\uad8c\uc744 \ud589\uc0ac\ud55c \ud6c4\uc5d0\ub3c4 \uc790\uc720\ub86d\uac8c \ub2e4\uc2dc \ucca0\ud68c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.abx=s(["\uadf8 \uc758\uc0ac\ud45c\uc2dc\ub294 \ucca0\ud68c\ud558\uc9c0 \ubabb\ud55c\ub2e4"],t.s)
B.bbH=s(["\ud574\uc81c\uad8c \ud589\uc0ac\uc758 \ubc29\ubc95"],t.s)
B.bDX=new A.a("gen_cl_termination_3","civil_law","\uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0",null,"\ud574\uc81c\uad8c\uc758 \ud589\uc0ac(\ubbfc\ubc95 \uc81c543\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.bea,1,"\ud574\uc81c\uad8c\uc740 \uc0c1\ub300\ubc29 \uc788\ub294 \ub2e8\ub3c5\ud589\uc704\ub85c\uc11c \uc0c1\ub300\ubc29\uc5d0 \ub300\ud55c \uc758\uc0ac\ud45c\uc2dc\ub85c \ud589\uc0ac\ud558\uba70, \ubbfc\ubc95 \uc81c543\uc870 \uc81c2\ud56d\uc5d0 \ub530\ub77c \uadf8 \uc758\uc0ac\ud45c\uc2dc\ub294 \ucca0\ud68c\ud558\uc9c0 \ubabb\ud55c\ub2e4.",B.abx,B.bbH,null)
B.bhV=s(["\uac01 \ub2f9\uc0ac\uc790\ub294 \uc0c1\ub300\ubc29\uc5d0\uac8c \ubc1b\uc740 \uae09\ubd80\ub97c \uc6d0\uc0c1\ud68c\ubcf5\ud560 \uc758\ubb34\ub97c \uc9c4\ub2e4","\uae08\uc804\uc744 \ubc18\ud658\ud560 \ub54c\uc5d0\ub294 \ubc1b\uc740 \ub0a0\ubd80\ud130 \uc774\uc790\ub97c \uac00\uc0b0\ud558\uc5ec\uc57c \ud55c\ub2e4","\ud574\uc81c \uc804\uc5d0 \uc774\ud574\uad00\uacc4\ub97c \ub9fa\uc740 \uc120\uc758\uc758 \uc81c3\uc790\uc758 \uad8c\ub9ac\ub294 \ud574\uc81c\ub85c \uce68\ud574\ub418\uc9c0 \uc54a\ub294\ub2e4","\uacc4\uc57d\uc744 \ud574\uc81c\ud558\uba74 \uc190\ud574\ubc30\uc0c1\uccad\uad6c\uad8c\ub3c4 \ud568\uaed8 \uc18c\uba78\ud55c\ub2e4"],t.s)
B.a7f=s(["\uacc4\uc57d\uc758 \ud574\uc81c\uac00 \uc190\ud574\ubc30\uc0c1\uccad\uad6c\uad8c\uc5d0 \uc601\ud5a5\uc744 \ubbf8\uce58\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.ana=s(["\ud574\uc81c\uc758 \ud6a8\uacfc \u2014 \uc6d0\uc0c1\ud68c\ubcf5\uacfc \uc190\ud574\ubc30\uc0c1"],t.s)
B.bws=new A.a("gen_cl_termination_4","civil_law","\uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0",null,"\uacc4\uc57d \ud574\uc81c\uc758 \ud6a8\uacfc(\ubbfc\ubc95 \uc81c548\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.bhV,3,"\ubbfc\ubc95 \uc81c551\uc870\ub294 \uacc4\uc57d\uc758 \ud574\uc81c\uac00 \uc190\ud574\ubc30\uc0c1\uccad\uad6c\uad8c\uc5d0 \uc601\ud5a5\uc744 \ubbf8\uce58\uc9c0 \uc54a\ub294\ub2e4\uace0 \uba85\uc2dc\ud558\uace0 \uc788\uc5b4, \ud574\uc81c \ud6c4\uc5d0\ub3c4 \ucc44\uad8c\uc790\ub294 \uc6d0\uc0c1\ud68c\ubcf5\uacfc \ubcc4\uac1c\ub85c \uc190\ud574\ubc30\uc0c1\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4.",B.a7f,B.ana,null)
B.a_z=s(["\uc30d\ubc29\uc758 \uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\ub294 \uc11c\ub85c \uc544\ubb34 \uad00\ub828 \uc5c6\uc774 \ub3c5\ub9bd\uc801\uc73c\ub85c \uc774\ud589\ud558\uba74 \ub41c\ub2e4","\uc30d\ubc29\uc758 \uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34 \uc0ac\uc774\uc5d0\ub294 \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uac00 \uc900\uc6a9\ub41c\ub2e4","\uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\ub294 \ubc18\ub4dc\uc2dc \ubc95\uc6d0\uc758 \ud310\uacb0\uc744 \uac70\uccd0\uc57c\ub9cc \uc774\ud589\ud560 \uc218 \uc788\ub2e4","\uae08\uc804 \uc774\uc678\uc758 \uae09\ubd80\ub294 \uc6d0\uc0c1\ud68c\ubcf5 \ub300\uc0c1\uc5d0\uc11c \uc81c\uc678\ub41c\ub2e4"],t.s)
B.bis=s(["\uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\uc5d0 \uad00\ud558\uc5ec \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c \uaddc\uc815\uc744 \uc900\uc6a9"],t.s)
B.Uy=s(["\uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\uc640 \ub3d9\uc2dc\uc774\ud589"],t.s)
B.bDh=new A.a("gen_cl_termination_5","civil_law","\uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0",null,"\ud574\uc81c\ub85c \uc778\ud55c \uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\uc640 \uad00\ub828\ud558\uc5ec \uc633\uc740 \uac83\uc740?",B.a_z,1,"\ubbfc\ubc95 \uc81c549\uc870\ub294 \uacc4\uc57d \ud574\uc81c\ub85c \uc778\ud55c \uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\uc5d0 \uad00\ud558\uc5ec \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c \uaddc\uc815\uc744 \uc900\uc6a9\ud558\ub3c4\ub85d \ud558\uace0 \uc788\uc5b4, \uac01 \ub2f9\uc0ac\uc790\uc758 \uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\ub294 \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uc5d0 \uc788\ub2e4.",B.bis,B.Uy,null)
B.bdq=s(["\ud574\uc81c \ud6c4\uc5d0 \uc0c8\ub85c \uc774\ud574\uad00\uacc4\ub97c \ub9fa\uc740 \uc790\ub9cc \ubcf4\ud638\ub41c\ub2e4","\ud574\uc81c \uc804\uc5d0 \ud574\uc81c \ub300\uc0c1 \ubaa9\uc801\ubb3c\uc5d0 \uad00\ud558\uc5ec \uc0c8\ub85c\uc6b4 \uc774\ud574\uad00\uacc4\ub97c \ub9fa\uc740 \uc120\uc758\uc758 \uc81c3\uc790\uac00 \ubcf4\ud638\ub41c\ub2e4","\uc545\uc758\uc758 \uc81c3\uc790\ub3c4 \uc544\ubb34\ub7f0 \uc81c\ud55c \uc5c6\uc774 \ubcf4\ud638\ub41c\ub2e4","\uc81c3\uc790\ub294 \ud56d\uc0c1 \ub4f1\uae30\uc640 \ubb34\uad00\ud558\uac8c \ubcf4\ud638\ub41c\ub2e4"],t.s)
B.aAu=s(["\ud574\uc81c\uc758 \uc758\uc0ac\ud45c\uc2dc\uac00 \uc788\uae30 \uc804\uc5d0 \ud574\uc81c \ub300\uc0c1\uc778 \uacc4\uc57d\uc744 \uae30\ucd08\ub85c \uc0c8\ub85c\uc6b4 \uad8c\ub9ac\ub97c \ucde8\ub4dd\ud55c \uc120\uc758\uc758 \uc790"],t.s)
B.amZ=s(["\ud574\uc81c\uc640 \uc81c3\uc790 \ubcf4\ud638"],t.s)
B.bE9=new A.a("gen_cl_termination_6","civil_law","\uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0",null,'\ud574\uc81c \uc2dc \ubcf4\ud638\ub418\ub294 "\uc81c3\uc790"\uc758 \ubc94\uc704\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?',B.bdq,1,"\ubbfc\ubc95 \uc81c548\uc870 \uc81c1\ud56d \ub2e8\uc11c\uc758 \uc81c3\uc790\ub294 \ud574\uc81c\uc758 \uc758\uc0ac\ud45c\uc2dc\uac00 \uc788\uae30 \uc804\uc5d0 \ud574\uc81c \ub300\uc0c1\uc778 \uacc4\uc57d\uc744 \uae30\ucd08\ub85c \uc0c8\ub85c\uc6b4 \uad8c\ub9ac\ub97c \ucde8\ub4dd\ud55c \uc120\uc758\uc758 \uc790\ub97c \uc758\ubbf8\ud558\uba70, \ud574\uc81c \ud6c4\uc758 \uc774\ud574\uad00\uacc4\uc778\uc740 \uc6d0\uce59\uc801\uc73c\ub85c \uc774 \uc870\ud56d\uc758 \ubcf4\ud638 \ub300\uc0c1\uc774 \uc544\ub2c8\ub2e4.",B.aAu,B.amZ,null)
B.aRc=s(["\ud569\uc758\ud574\uc81c\ub3c4 \ubc95\uc815\ud574\uc81c\uc640 \ub9c8\ucc2c\uac00\uc9c0\ub85c \ub2f9\uc5f0\ud788 \uc774\uc790 \uac00\uc0b0\xb7\uc190\ud574\ubc30\uc0c1 \uaddc\uc815\uc774 \uc801\uc6a9\ub41c\ub2e4","\ud569\uc758\ud574\uc81c\ub294 \ub2f9\uc0ac\uc790 \uc30d\ubc29\uc758 \ud569\uc758\ub85c \uacc4\uc57d\uad00\uacc4\ub97c \uc885\ub8cc\uc2dc\ud0a4\ub294 \uac83\uc73c\ub85c, \uadf8 \ud6a8\uacfc\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \ub2f9\uc0ac\uc790\uc758 \uc57d\uc815 \ub0b4\uc6a9\uc5d0 \ub530\ub978\ub2e4","\ud569\uc758\ud574\uc81c\ub294 \ubc18\ub4dc\uc2dc \ubc95\uc815\ud574\uc81c \uc0ac\uc720\uac00 \uc788\uc5b4\uc57c\ub9cc \uac00\ub2a5\ud558\ub2e4","\ud569\uc758\ud574\uc81c\ub294 \ubc95\uc6d0\uc758 \ud655\uc778 \ud310\uacb0\uc774 \uc788\uc5b4\uc57c \ud6a8\ub825\uc774 \ubc1c\uc0dd\ud55c\ub2e4"],t.s)
B.b9Z=s(["\uadf8 \ud6a8\uacfc\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \ub2f9\uc0ac\uc790\uc758 \uc57d\uc815 \ub0b4\uc6a9\uc5d0 \ub530\ub978\ub2e4"],t.s)
B.a_M=s(["\ud569\uc758\ud574\uc81c\uc640 \ubc95\uc815\ud574\uc81c\uc758 \ucc28\uc774"],t.s)
B.boJ=new A.a("gen_cl_termination_7","civil_law","\uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0",null,"\ud569\uc758\ud574\uc81c(\ud574\uc81c\uacc4\uc57d)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aRc,1,"\ud569\uc758\ud574\uc81c\ub294 \ub2f9\uc0ac\uc790 \uc30d\ubc29\uc758 \uc0c8\ub85c\uc6b4 \ud569\uc758(\uacc4\uc57d)\ub85c \uae30\uc874 \uacc4\uc57d\uc744 \uc5c6\ub358 \uac83\uc73c\ub85c \ud558\ub294 \uac83\uc73c\ub85c, \ubc95\uc815\ud574\uc81c\uc640 \ub2ec\ub9ac \uc6d0\uc0c1\ud68c\ubcf5 \uc2dc \uc774\uc790 \uac00\uc0b0\uc774\ub098 \uc190\ud574\ubc30\uc0c1\uc5d0 \uad00\ud55c \ubc95\uc815 \uaddc\uc815\uc774 \ub2f9\uc5f0\ud788 \uc801\uc6a9\ub418\uc9c0\ub294 \uc54a\uace0 \ub2f9\uc0ac\uc790\uc758 \uc57d\uc815\uc5d0 \ub530\ub978\ub2e4.",B.b9Z,B.a_M,null)
B.aUb=s(["\uc774\ud589\ubd88\ub2a5\uc778 \uacbd\uc6b0","\uc815\uae30\ud589\uc704\uc5d0\uc11c \uc815\ud574\uc9c4 \uc2dc\uae30\uc5d0 \uc774\ud589\ud558\uc9c0 \uc54a\uc740 \uacbd\uc6b0","\ucc44\ubb34\uc790\uac00 \ubbf8\ub9ac \uc774\ud589\ud558\uc9c0 \uc54a\uc744 \uc758\uc0ac\ub97c \uba85\ubc31\ud788 \ud45c\uc2dc\ud55c \uacbd\uc6b0","\ucc44\ubb34\uc790\uac00 \ub2e8\uc21c\ud788 \uc774\ud589\uc744 \ud558\ub8e8 \ub2a6\uac8c \ud55c \uacbd\uc6b0"],t.s)
B.b7D=s(["\ub2e8\uc21c\ud788 \ud558\ub8e8 \uc774\ud589\uc774 \ub2a6\uc740 \uac83\ub9cc\uc73c\ub85c\ub294 \uc6d0\uce59\uc801\uc778 \uc774\ud589\uc9c0\uccb4 \ud574\uc81c \uc808\ucc28(\ucd5c\uace0)\ub97c \uac70\uccd0\uc57c \ud55c\ub2e4"],t.s)
B.apu=s(["\ucd5c\uace0 \uc5c6\uc774 \ud574\uc81c \uac00\ub2a5\ud55c \uc608\uc678"],t.s)
B.bRY=new A.a("gen_cl_termination_8","civil_law","\uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0",null,"\ucd5c\uace0 \uc5c6\uc774 \uacc4\uc57d\uc744 \ud574\uc81c\ud560 \uc218 \uc788\ub294 \uacbd\uc6b0\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aUb,3,"\uc774\ud589\ubd88\ub2a5, \uc815\uae30\ud589\uc704(\uc81c545\uc870), \uc774\ud589\uac70\uc808\uc758 \uba85\ubc31\ud55c \ud45c\uc2dc \ub4f1\uc740 \ucd5c\uace0 \uc5c6\uc774 \uc989\uc2dc \ud574\uc81c\uac00 \uac00\ub2a5\ud55c \uc608\uc678 \uc0ac\uc720\uc774\uc9c0\ub9cc, \ub2e8\uc21c\ud788 \ud558\ub8e8 \uc774\ud589\uc774 \ub2a6\uc740 \uac83\ub9cc\uc73c\ub85c\ub294 \uc6d0\uce59\uc801\uc778 \uc774\ud589\uc9c0\uccb4 \ud574\uc81c \uc808\ucc28(\ucd5c\uace0)\ub97c \uac70\uccd0\uc57c \ud55c\ub2e4.",B.b7D,B.apu,null)
B.a0P=s(["\ud574\uc9c0\ub294 \uacc4\uc57d\uc758 \ud6a8\ub825\uc744 \uacc4\uc57d \uc131\ub9bd \uc2dc\ub85c \uc18c\uae09\ud558\uc5ec \uc18c\uba78\uc2dc\ud0a8\ub2e4","\ud574\uc9c0\ub294 \uc7a5\ub798\ub97c \ud5a5\ud574\uc11c\ub9cc \uacc4\uc57d\uc758 \ud6a8\ub825\uc744 \uc18c\uba78\uc2dc\ud0a8\ub2e4","\ud574\uc9c0\ub3c4 \ud574\uc81c\uc640 \ub9c8\ucc2c\uac00\uc9c0\ub85c \uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\ub97c \ubc1c\uc0dd\uc2dc\ud0a8\ub2e4","\ud574\uc9c0 \uc2dc\uc5d0\ub294 \uc190\ud574\ubc30\uc0c1\uc744 \uccad\uad6c\ud560 \uc218 \uc5c6\ub2e4"],t.s)
B.ayz=s(["\uacc4\uc18d\uc801 \uacc4\uc57d\uad00\uacc4\ub97c \uc7a5\ub798\ub97c \ud5a5\ud574\uc11c\ub9cc \uc18c\uba78\uc2dc\ud0a4\ub294 \uac83\uc73c\ub85c \uc18c\uae09\ud6a8\uac00 \uc5c6\uc73c\uba70"],t.s)
B.a4G=s(["\ud574\uc9c0\uc758 \ud6a8\uacfc \u2014 \uc7a5\ub798\ud6a8"],t.s)
B.bFs=new A.a("gen_cl_termination_9","civil_law","\uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0",null,"\ud574\uc9c0\uc758 \ud6a8\uacfc\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.a0P,1,"\ud574\uc9c0\ub294 \uacc4\uc18d\uc801 \uacc4\uc57d\uad00\uacc4\ub97c \uc7a5\ub798\ub97c \ud5a5\ud574\uc11c\ub9cc \uc18c\uba78\uc2dc\ud0a4\ub294 \uac83\uc73c\ub85c \uc18c\uae09\ud6a8\uac00 \uc5c6\uc73c\uba70, \uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34 \ub300\uc2e0 \uc774\ubbf8 \uc774\ud589\ub41c \ubd80\ubd84\uc740 \uc720\ud6a8\ud558\uac8c \uc720\uc9c0\ub41c \ucc44 \uc7a5\ub798 \ubd80\ubd84\ub9cc \uc885\ub8cc\ub41c\ub2e4. \uc190\ud574\ubc30\uc0c1\uccad\uad6c\uad8c\uc740 \ud574\uc9c0\uc5d0\ub3c4 \uc601\ud5a5\ubc1b\uc9c0 \uc54a\ub294\ub2e4(\uc81c551\uc870 \uc900\uc6a9).",B.ayz,B.a4G,null)
B.bdF=s(["\ud574\uc81c\uc870\uac74\uc740 \uc870\uac74 \uc131\ucde8\ub85c \ub2f9\uc5f0\ud788 \ud6a8\ub825\uc744 \uc783\uc9c0\ub9cc, \ud574\uc81c\uad8c \ud589\uc0ac\ub294 \uad8c\ub9ac\uc790\uc758 \uc758\uc0ac\ud45c\uc2dc\uac00 \uc788\uc5b4\uc57c \uacc4\uc57d\uc774 \uc18c\uba78\ud55c\ub2e4","\ud574\uc81c\uc870\uac74\uacfc \ud574\uc81c\uad8c \ud589\uc0ac\ub294 \ubc95\uc801 \uc131\uc9c8\uc774 \uc644\uc804\ud788 \ub3d9\uc77c\ud558\ub2e4","\ud574\uc81c\uc870\uac74\uc740 \ud56d\uc0c1 \uc758\uc0ac\ud45c\uc2dc\ub97c \uc694\ud558\uace0, \ud574\uc81c\uad8c\uc740 \uc870\uac74 \uc131\ucde8\ub9cc\uc73c\ub85c \ubc1c\uc0dd\ud55c\ub2e4","\ud574\uc81c\uc870\uac74\ubd80 \ubc95\ub960\ud589\uc704\ub294 \ud574\uc81c\uad8c \ud589\uc0ac\ub97c \ud1b5\ud574\uc11c\ub9cc \uc2e4\ud604\ub41c\ub2e4"],t.s)
B.aMX=s(["\uc870\uac74\uc774 \uc131\ucde8\ub418\uba74 \ub2f9\uc5f0\ud788(\ubcc4\ub3c4\uc758 \uc758\uc0ac\ud45c\uc2dc \uc5c6\uc774) \ud6a8\ub825\uc744 \uc783\uc9c0\ub9cc"],t.s)
B.a7k=s(["\ud574\uc81c\uc870\uac74\uacfc \ud574\uc81c\uad8c\uc758 \uad6c\ubd84"],t.s)
B.bEy=new A.a("gen_cl_termination_10","civil_law","\uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0",null,"\ud574\uc81c\uc870\uac74\uacfc \ud574\uc81c\uad8c \ud589\uc0ac\uc758 \ucc28\uc774\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.bdF,0,"\ud574\uc81c\uc870\uac74\uc774 \ubd99\uc740 \ubc95\ub960\ud589\uc704\ub294 \uc870\uac74\uc774 \uc131\ucde8\ub418\uba74 \ub2f9\uc5f0\ud788(\ubcc4\ub3c4\uc758 \uc758\uc0ac\ud45c\uc2dc \uc5c6\uc774) \ud6a8\ub825\uc744 \uc783\uc9c0\ub9cc, \ud574\uc81c\uad8c\uc740 \ud615\uc131\uad8c\uc73c\ub85c\uc11c \uad8c\ub9ac\uc790\uac00 \uc758\uc0ac\ud45c\uc2dc\ub97c \ud558\uc5ec\uc57c \ube44\ub85c\uc18c \uacc4\uc57d\uc758 \ud6a8\ub825\uc774 \uc18c\uba78\ud55c\ub2e4\ub294 \uc810\uc5d0\uc11c \uad6c\uc870\uc801\uc73c\ub85c \ub2e4\ub974\ub2e4.",B.aMX,B.a7k,null)
B.ao9=s(["\uacc4\uc57d\uc744 \ud574\uc81c\ud558\uba74 \uc190\ud574\ubc30\uc0c1\uccad\uad6c\uad8c\uc740 \ub2f9\uc5f0\ud788 \uc18c\uba78\ud55c\ub2e4","\ud574\uc81c\uc640 \uc190\ud574\ubc30\uc0c1\uccad\uad6c\ub294 \uc591\ub9bd\ud560 \uc218 \uc5c6\uc73c\ubbc0\ub85c \ub458 \uc911 \ud558\ub098\ub9cc \uc120\ud0dd\ud574\uc57c \ud55c\ub2e4","\ud574\uc81c\ud558\ub354\ub77c\ub3c4 \uc190\ud574\ubc30\uc0c1\uccad\uad6c\uad8c\uc740 \uc18c\uba78\ud558\uc9c0 \uc54a\uc544 \uc6d0\uc0c1\ud68c\ubcf5\uacfc \ud568\uaed8 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4","\uc190\ud574\ubc30\uc0c1\uc740 \ud574\uc81c \uc774\uc804\uc5d0\ub9cc \uccad\uad6c\ud560 \uc218 \uc788\uace0 \ud574\uc81c \ud6c4\uc5d0\ub294 \uccad\uad6c\ud560 \uc218 \uc5c6\ub2e4"],t.s)
B.a8m=s(["\ud574\uc81c\ub85c \uc778\ud55c \uc6d0\uc0c1\ud68c\ubcf5\uccad\uad6c\uad8c\uacfc \uc190\ud574\ubc30\uc0c1\uccad\uad6c\uad8c\uc744 \ud568\uaed8 \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4"],t.s)
B.ajV=s(["\ud574\uc81c\uc640 \uc190\ud574\ubc30\uc0c1\uc758 \ubcd1\uc874"],t.s)
B.bKS=new A.a("gen_cl_termination_11","civil_law","\uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0",null,"\uacc4\uc57d \ud574\uc81c\uc640 \uc190\ud574\ubc30\uc0c1\uc758 \uad00\uacc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.ao9,2,"\ubbfc\ubc95 \uc81c551\uc870\uc5d0 \ub530\ub77c \uacc4\uc57d\uc758 \ud574\uc81c\ub294 \uc190\ud574\ubc30\uc0c1\uccad\uad6c\uad8c \ud589\uc0ac\uc5d0 \uc601\ud5a5\uc744 \ubbf8\uce58\uc9c0 \uc54a\uc73c\ubbc0\ub85c, \ucc44\uad8c\uc790\ub294 \ud574\uc81c\ub85c \uc778\ud55c \uc6d0\uc0c1\ud68c\ubcf5\uccad\uad6c\uad8c\uacfc \uc190\ud574\ubc30\uc0c1\uccad\uad6c\uad8c\uc744 \ud568\uaed8 \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4.",B.a8m,B.ajV,null)
B.Sx=s(["\ud574\uc81c\ub294 \uc18c\uae09\ud6a8, \ud574\uc9c0\ub294 \uc7a5\ub798\ud6a8\ub97c \uac00\uc9c4\ub2e4\ub294 \uc810\uc5d0\uc11c \uad6c\ubcc4\ub41c\ub2e4","\uc774\ud589\ubd88\ub2a5\uc758 \uacbd\uc6b0 \ucd5c\uace0 \uc5c6\uc774 \uc989\uc2dc \ud574\uc81c\ud560 \uc218 \uc788\ub2e4","\ud574\uc81c\xb7\ud574\uc9c0 \ubaa8\ub450 \uc190\ud574\ubc30\uc0c1\uccad\uad6c\uad8c\uc5d0 \uc601\ud5a5\uc744 \ubbf8\uce58\uc9c0 \uc54a\ub294\ub2e4","\ud574\uc81c\uad8c \ud589\uc0ac \ud6c4\uc5d0\ub3c4 \ub2f9\uc0ac\uc790\ub294 \uc774\ub97c \uc790\uc720\ub86d\uac8c \ucca0\ud68c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.awr=s(["\uc77c\ub2e8 \ud589\uc0ac(\uc758\uc0ac\ud45c\uc2dc)\ud558\uba74 \ubbfc\ubc95 \uc81c543\uc870 \uc81c2\ud56d\uc5d0 \ub530\ub77c \ucca0\ud68c\ud558\uc9c0 \ubabb\ud558\ubbc0\ub85c"],t.s)
B.as8=s(["\uacc4\uc57d \ud574\uc81c\xb7\ud574\uc9c0 \uc885\ud569\uc815\ub9ac"],t.s)
B.bMr=new A.a("gen_cl_termination_12","civil_law","\uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0",null,"\uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0\uc5d0 \uad00\ud55c \uc885\ud569\uc801\uc778 \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.Sx,3,"\ud574\uc81c\uad8c\uc740 \uc77c\ub2e8 \ud589\uc0ac(\uc758\uc0ac\ud45c\uc2dc)\ud558\uba74 \ubbfc\ubc95 \uc81c543\uc870 \uc81c2\ud56d\uc5d0 \ub530\ub77c \ucca0\ud68c\ud558\uc9c0 \ubabb\ud558\ubbc0\ub85c, \ud574\uc81c\uad8c \ud589\uc0ac \ud6c4 \uc790\uc720\ub86d\uac8c \ucca0\ud68c\ud560 \uc218 \uc788\ub2e4\ub294 \uc124\uba85\uc740 \uc633\uc9c0 \uc54a\ub2e4.",B.awr,B.as8,null)
B.RD=s(["\ub2f9\uc0ac\uc790 \uac04 \ub2e4\ub978 \uc57d\uc815\uc774 \uc5c6\uc73c\uba74 \uacc4\uc57d\uae08\uc740 \ud574\uc57d\uae08\uc73c\ub85c \ucd94\uc815\ub418\uc5b4, \ub2f9\uc0ac\uc790 \uc77c\ubc29\uc774 \uc774\ud589\uc5d0 \ucc29\uc218\ud560 \ub54c\uae4c\uc9c0 \ub9e4\uc218\uc778\uc740 \uc774\ub97c \ud3ec\uae30\ud558\uace0 \ub9e4\ub3c4\uc778\uc740 \ubc30\uc561\uc744 \uc0c1\ud658\ud558\uc5ec \uacc4\uc57d\uc744 \ud574\uc81c\ud560 \uc218 \uc788\ub2e4","\uacc4\uc57d\uae08\uc740 \ud56d\uc0c1 \uc704\uc57d\ubc8c\ub85c\ub9cc \uae30\ub2a5\ud55c\ub2e4","\uacc4\uc57d\uae08\uc744 \uc9c0\uae09\ud558\uba74 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \uacc4\uc57d\uc744 \ud574\uc81c\ud560 \uc218 \uc5c6\ub2e4","\uacc4\uc57d\uae08\uc740 \uc190\ud574\ubc30\uc0c1\uc561\uc758 \uc608\uc815\uc73c\ub85c\ub9cc \ucd94\uc815\ub41c\ub2e4"],t.s)
B.acX=s(["\ub2f9\uc0ac\uc790 \uc77c\ubc29\uc774 \uc774\ud589\uc5d0 \ucc29\uc218\ud560 \ub54c\uae4c\uc9c0 \ub9e4\uc218\uc778\uc740 \uc774\ub97c \ud3ec\uae30\ud558\uace0 \ub9e4\ub3c4\uc778\uc740 \ubc30\uc561\uc744 \uc0c1\ud658\ud558\uc5ec \uacc4\uc57d\uc744 \ud574\uc81c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.avF=s(["\uacc4\uc57d\uae08\uacfc \ud574\uc57d\uae08 \ucd94\uc815"],t.s)
B.bNS=new A.a("gen_cl_termination_13","civil_law","\uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0",null,"\uacc4\uc57d\uae08(\ubbfc\ubc95 \uc81c565\uc870)\uc758 \ud574\uc57d\uae08 \ucd94\uc815\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.RD,0,"\ubbfc\ubc95 \uc81c565\uc870\ub294 \uacc4\uc57d\uae08\uc744 \ud574\uc57d\uae08\uc73c\ub85c \ucd94\uc815\ud558\uc5ec, \ub2f9\uc0ac\uc790 \uc77c\ubc29\uc774 \uc774\ud589\uc5d0 \ucc29\uc218\ud558\uae30 \uc804\uae4c\uc9c0 \uad50\ubd80\uc790\ub294 \uc774\ub97c \ud3ec\uae30\ud558\uace0 \uc218\ub839\uc790\ub294 \ubc30\uc561\uc744 \uc0c1\ud658\ud558\uc5ec \uc790\uc720\ub86d\uac8c \uacc4\uc57d\uc744 \ud574\uc81c\ud560 \uc218 \uc788\ub3c4\ub85d \ud55c\ub2e4.",B.acX,B.avF,null)
B.aOS=s(["\ub2f9\uc0ac\uc790 \uc77c\ubc29\uc774 \uc774\ud589\uc5d0 \ucc29\uc218\ud558\uae30 \uc804\uae4c\uc9c0\ub9cc \uac00\ub2a5\ud558\ub2e4","\uacc4\uc57d \uccb4\uacb0 \ud6c4 \uc5b8\uc81c\ub4e0\uc9c0 \uc790\uc720\ub86d\uac8c \uac00\ub2a5\ud558\ub2e4","\uc774\ud589\uc774 \uc644\uc804\ud788 \uc885\ub8cc\ub41c \ud6c4\uc5d0\ub3c4 \uac00\ub2a5\ud558\ub2e4","\ubc95\uc6d0\uc758 \ud5c8\uac00\ub97c \ubc1b\uc740 \uacbd\uc6b0\uc5d0\ub9cc \uac00\ub2a5\ud558\ub2e4"],t.s)
B.b5U=s(["\ub2f9\uc0ac\uc790 \uc77c\ubc29\uc774 \uc774\ud589\uc5d0 \ucc29\uc218\ud558\uae30 \uc804\uae4c\uc9c0\ub9cc \ud5c8\uc6a9"],t.s)
B.b_V=s(["\ud574\uc57d\uae08 \ud574\uc81c\uc758 \uc2dc\uae30\uc801 \ud55c\uacc4"],t.s)
B.buY=new A.a("gen_cl_termination_14","civil_law","\uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0",null,"\ud574\uc57d\uae08\uc5d0 \uc758\ud55c \ud574\uc81c\uac00 \uac00\ub2a5\ud55c \uc2dc\uae30\uc801 \ud55c\uacc4\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aOS,0,"\ud574\uc57d\uae08\uc5d0 \uc758\ud55c \ud574\uc81c\ub294 \ub2f9\uc0ac\uc790 \uc77c\ubc29\uc774 \uc774\ud589\uc5d0 \ucc29\uc218\ud558\uae30 \uc804\uae4c\uc9c0\ub9cc \ud5c8\uc6a9\ub418\uba70, \uc911\ub3c4\uae08 \uc9c0\uae09 \ub4f1 \uc774\ud589\uc5d0 \ucc29\uc218\ud55c \uc774\ud6c4\uc5d0\ub294 \uc0c1\ub300\ubc29\uc758 \uc2e0\ub8b0\ub97c \ubcf4\ud638\ud558\uae30 \uc704\ud574 \uc784\uc758\ub85c \ud574\uc57d\uae08 \ud574\uc81c\ub97c \ud560 \uc218 \uc5c6\ub2e4.",B.b5U,B.b_V,null)
B.ace=s(["\ub2f9\uc0ac\uc790\uc758 \uc77c\ubc29 \ub610\ub294 \uc0c1\ub300\ubc29\uc774 \uc218\uc778\uc778 \uacbd\uc6b0, \uacc4\uc57d\uc758 \ud574\uc81c\ub294 \uadf8 \uc804\uc6d0\uc73c\ub85c\ubd80\ud130 \ub610\ub294 \uc804\uc6d0\uc5d0 \ub300\ud558\uc5ec\ub9cc \ud560 \uc218 \uc788\ub2e4","\ub2f9\uc0ac\uc790\uac00 \uc218\uc778\uc774\uba74 \uac01\uc790 \uac1c\ubcc4\uc801\uc73c\ub85c \uc790\uc720\ub86d\uac8c \ud574\uc81c\ud560 \uc218 \uc788\ub2e4","\ud574\uc81c\uad8c\uc758 \ubd88\uac00\ubd84\uc131\uc740 \uacc4\uc57d\ud574\uc9c0\uc5d0\ub294 \uc804\ud600 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4","\ud574\uc81c\uad8c\uc758 \ubd88\uac00\ubd84\uc131\uc740 \ub2f9\uc0ac\uc790\uac00 1\uc778\uc778 \uacbd\uc6b0\uc5d0\ub9cc \uc801\uc6a9\ub41c\ub2e4"],t.s)
B.So=s(["\uadf8 \uc804\uc6d0\uc73c\ub85c\ubd80\ud130 \ub610\ub294 \uc804\uc6d0\uc5d0 \ub300\ud558\uc5ec\ub9cc \ud560 \uc218 \uc788\ub2e4"],t.s)
B.aKB=s(["\ud574\uc81c\uad8c\uc758 \ubd88\uac00\ubd84\uc131"],t.s)
B.bx2=new A.a("gen_cl_termination_15","civil_law","\uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0",null,"\ud574\uc81c\uad8c\uc758 \ubd88\uac00\ubd84\uc131(\ubbfc\ubc95 \uc81c547\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.ace,0,"\ubbfc\ubc95 \uc81c547\uc870\ub294 \ub2f9\uc0ac\uc790 \uc77c\ubc29 \ub610\ub294 \uc30d\ubc29\uc774 \uc218\uc778\uc778 \uacbd\uc6b0 \uacc4\uc57d\uc758 \ud574\uc81c\ub098 \ud574\uc9c0\ub294 \uadf8 \uc804\uc6d0\uc73c\ub85c\ubd80\ud130 \ub610\ub294 \uc804\uc6d0\uc5d0 \ub300\ud558\uc5ec \ud558\uc5ec\uc57c \ud55c\ub2e4\uace0 \uaddc\uc815\ud558\uc5ec, \ud574\uc81c\xb7\ud574\uc9c0\uc758 \ubd88\uac00\ubd84\uc131\uc744 \uc815\ud558\uace0 \uc788\ub2e4.",B.So,B.aKB,null)
B.auj=s(["\ud574\uc81c\uad8c\uc790\uac00 \uacc4\uc57d\uc758 \ubaa9\uc801\ubb3c\uc744 \uc790\uae30\uc758 \uace0\uc758\xb7\uacfc\uc2e4\ub85c \ud604\uc800\ud788 \ud6fc\uc190\ud55c \uacbd\uc6b0 \ud574\uc81c\uad8c\uc740 \uc18c\uba78\ud55c\ub2e4","\uc0c1\ub300\ubc29\uc758 \ucd5c\uace0\uc5d0\ub3c4 \ud574\uc81c \uc5ec\ubd80\uc758 \ud1b5\uc9c0\uac00 \uc5c6\uc73c\uba74 \ud574\uc81c\uad8c\uc774 \uc18c\uba78\ud560 \uc218 \uc788\ub2e4","\ud574\uc81c\uad8c\uc740 \uc18c\uba78\uc2dc\ud6a8\ub098 \uc81c\ucc99\uae30\uac04\uc758 \uc801\uc6a9\uc744 \uc804\ud600 \ubc1b\uc9c0 \uc54a\ub294\ub2e4","\ud574\uc81c\uad8c\uc790\uac00 \ubaa9\uc801\ubb3c\uc744 \uac00\uacf5\ud558\uc5ec \ub2e4\ub978 \uc885\ub958\uc758 \ubb3c\uac74\uc73c\ub85c \ubcc0\uacbd\ud55c \uacbd\uc6b0 \ud574\uc81c\uad8c\uc740 \uc18c\uba78\ud55c\ub2e4"],t.s)
B.bfX=s(["\ud574\uc81c\uad8c\uc740 \ud615\uc131\uad8c\uc73c\ub85c\uc11c \uc81c\ucc99\uae30\uac04(\ud589\uc0ac\uae30\uac04)\uc758 \uc801\uc6a9\uc744 \ubc1b\uc73c\uba70"],t.s)
B.Rh=s(["\ud574\uc81c\uad8c\uc758 \uc18c\uba78\uc0ac\uc720"],t.s)
B.bLK=new A.a("gen_cl_termination_16","civil_law","\uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0",null,"\ud574\uc81c\uad8c\uc758 \uc18c\uba78 \uc0ac\uc720\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.auj,2,"\ud574\uc81c\uad8c\uc740 \ud615\uc131\uad8c\uc73c\ub85c\uc11c \uc81c\ucc99\uae30\uac04(\ud589\uc0ac\uae30\uac04)\uc758 \uc801\uc6a9\uc744 \ubc1b\uc73c\uba70, \uadf8 \ubc16\uc5d0\ub3c4 \uc81c552\uc870(\uc0c1\ub300\ubc29\uc758 \ucd5c\uace0\uc5d0 \ub300\ud55c \ud655\ub2f5 \ud574\ud0dc)\ub098 \uc81c553\uc870(\ubaa9\uc801\ubb3c\uc758 \ud6fc\uc190\xb7\uac00\uacf5 \ub4f1)\uc5d0 \ub530\ub77c \uc18c\uba78\ud560 \uc218 \uc788\uc5b4, \uc804\ud600 \uc18c\uba78\ud558\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc124\uba85\uc740 \uc633\uc9c0 \uc54a\ub2e4.",B.bfX,B.Rh,null)
B.aq2=s(["\ubaa9\uc801\ubb3c\uc5d0 \ud558\uc790\uac00 \uc788\uc5b4 \uacc4\uc57d\uc758 \ubaa9\uc801\uc744 \ub2ec\uc131\ud560 \uc218 \uc5c6\ub294 \uacbd\uc6b0, \ub9e4\uc218\uc778\uc740 \uacc4\uc57d\uc744 \ud574\uc81c\ud560 \uc218 \uc788\ub2e4","\ud558\uc790\ub2f4\ubcf4\ucc45\uc784\uc5d0 \uae30\ud55c \ud574\uc81c\ub294 \ub9e4\ub3c4\uc778\uc758 \uadc0\ucc45\uc0ac\uc720\uac00 \ubc18\ub4dc\uc2dc \uc788\uc5b4\uc57c\ub9cc \uac00\ub2a5\ud558\ub2e4","\ud558\uc790\ub2f4\ubcf4\ucc45\uc784\uc740 \ucc44\ubb34\ubd88\uc774\ud589\ucc45\uc784\uacfc \uc644\uc804\ud788 \ub3d9\uc77c\ud55c \uc694\uac74\uc744 \uac00\uc9c4\ub2e4","\ud558\uc790\ub2f4\ubcf4\ucc45\uc784\uc5d0 \uae30\ud55c \ud574\uc81c\uad8c\uc5d0\ub294 \uc5b4\ub5a0\ud55c \ud589\uc0ac\uae30\uac04 \uc81c\ud55c\ub3c4 \uc5c6\ub2e4"],t.s)
B.b7I=s(["\uacc4\uc57d\uc758 \ubaa9\uc801\uc744 \ub2ec\uc131\ud560 \uc218 \uc5c6\ub294 \uacbd\uc6b0, \ub9e4\uc218\uc778\uc740 \uacc4\uc57d\uc744 \ud574\uc81c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.acS=s(["\ud558\uc790\ub2f4\ubcf4\ucc45\uc784\uacfc \ud574\uc81c"],t.s)
B.bqE=new A.a("gen_cl_termination_17","civil_law","\uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0",null,"\ub9e4\ub3c4\uc778\uc758 \ub2f4\ubcf4\ucc45\uc784(\ud558\uc790\ub2f4\ubcf4\ucc45\uc784)\uc5d0 \uae30\ud55c \ub9e4\uc218\uc778\uc758 \ud574\uc81c\uad8c\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aq2,0,"\ub9e4\ub9e4\ubaa9\uc801\ubb3c\uc5d0 \ud558\uc790\uac00 \uc788\uc5b4 \uacc4\uc57d\uc758 \ubaa9\uc801\uc744 \ub2ec\uc131\ud560 \uc218 \uc5c6\ub294 \uacbd\uc6b0 \ub9e4\uc218\uc778\uc740 \uacc4\uc57d\uc744 \ud574\uc81c\ud560 \uc218 \uc788\uc73c\uba70(\uc81c580\uc870, \uc81c575\uc870 \ub4f1), \ud558\uc790\ub2f4\ubcf4\ucc45\uc784\uc740 \ub9e4\ub3c4\uc778\uc758 \uadc0\ucc45\uc0ac\uc720\ub97c \uc694\uac74\uc73c\ub85c \ud558\uc9c0 \uc54a\ub294 \ubb34\uacfc\uc2e4\ucc45\uc784\uc801 \uc131\uaca9\uc744 \uac00\uc9c4\ub2e4\ub294 \uc810\uc5d0\uc11c \ucc44\ubb34\ubd88\uc774\ud589\ucc45\uc784\uacfc \uad6c\ubcc4\ub41c\ub2e4.",B.b7I,B.acS,null)
B.aG_=s(["\uacc4\uc57d \uc131\ub9bd\uc758 \uae30\ucd08\uac00 \ub41c \uc0ac\uc815\uc774 \ub2f9\uc0ac\uc790\uac00 \uc608\uacac\ud560 \uc218 \uc5c6\uc5c8\ub358 \ud604\uc800\ud55c \ubcc0\uacbd\uc73c\ub85c \uacc4\uc57d\uc744 \uc720\uc9c0\ud558\ub294 \uac83\uc774 \uc2e0\uc758\uce59\uc5d0 \ud604\uc800\ud788 \ubc18\ud558\ub294 \uacbd\uc6b0 \uc608\uc678\uc801\uc73c\ub85c \uc778\uc815\ub420 \uc218 \uc788\ub2e4","\uc0ac\uc815\ubcc0\uacbd\uc758 \uc6d0\uce59\uc740 \uba85\ubb38 \uaddc\uc815\uc774 \ud48d\ubd80\ud558\uc5ec \ub110\ub9ac \ud65c\uc6a9\ub418\ub294 \uc77c\ubc18\uc801 \ud574\uc81c\uc0ac\uc720\uc774\ub2e4","\uc0ac\uc815\ubcc0\uacbd\uc740 \ub2f9\uc0ac\uc790\uac00 \uc608\uacac \uac00\ub2a5\ud588\ub358 \ud1b5\uc0c1\uc801 \uc704\ud5d8\ub3c4 \ud3ec\ud568\ud55c\ub2e4","\uc0ac\uc815\ubcc0\uacbd\uc758 \uc6d0\uce59\uc740 \uacc4\uc18d\uc801 \uacc4\uc57d\uc5d0\ub294 \uc801\uc6a9\ub420 \uc218 \uc5c6\ub2e4"],t.s)
B.UQ=s(["\ub2f9\uc0ac\uc790\uac00 \uc608\uacac\ud560 \uc218 \uc5c6\uc5c8\ub358 \ud604\uc800\ud55c \ubcc0\uacbd\uc73c\ub85c \uacc4\uc57d\uc744 \uc720\uc9c0\ud558\ub294 \uac83\uc774 \uc2e0\uc758\uce59\uc5d0 \ud604\uc800\ud788 \ubc18\ud558\ub294 \uacbd\uc6b0 \uc608\uc678\uc801\uc73c\ub85c \uc778\uc815"],t.s)
B.b63=s(["\uc0ac\uc815\ubcc0\uacbd\uc758 \uc6d0\uce59"],t.s)
B.bKj=new A.a("gen_cl_termination_18","civil_law","\uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0",null,"\uc0ac\uc815\ubcc0\uacbd\uc758 \uc6d0\uce59\uc5d0 \uc758\ud55c \uacc4\uc57d\ud574\uc81c(\ud574\uc9c0)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aG_,0,"\ud310\ub840\ub294 \uc0ac\uc815\ubcc0\uacbd\uc73c\ub85c \uc778\ud55c \uacc4\uc57d\ud574\uc81c\xb7\ud574\uc9c0\ub97c \uc608\uc678\uc801\xb7\uc81c\ud55c\uc801\uc73c\ub85c\ub9cc \uc778\uc815\ud558\ub294\ub370, \uacc4\uc57d\uc758 \uae30\ucd08\uac00 \ub41c \uc0ac\uc815\uc774 \ub2f9\uc0ac\uc790\uac00 \uc608\uacac\ud560 \uc218 \uc5c6\uc5c8\ub358 \ud604\uc800\ud55c \ubcc0\uacbd\uc744 \uacaa\uc5b4 \uacc4\uc57d \ub0b4\uc6a9\ub300\ub85c \uad6c\uc18d\ub825\uc744 \uc778\uc815\ud558\ub294 \uac83\uc774 \uc2e0\uc758\uce59\uc5d0 \ud604\uc800\ud788 \ubc18\ud558\ub294 \uacbd\uc6b0\uc5d0 \ud55c\ud55c\ub2e4.",B.UQ,B.b63,null)
B.aMn=s(["\uc784\ucc28\uc778\uc758 \ucc28\uc784\uc5f0\uccb4\uc561\uc774 2\uae30\uc758 \ucc28\uc784\uc561\uc5d0 \ub2ec\ud558\uba74 \uc784\ub300\uc778\uc740 \uacc4\uc57d\uc744 \ud574\uc9c0\ud560 \uc218 \uc788\ub2e4(\ubbfc\ubc95 \uc81c640\uc870)","\uc784\ucc28\uc778\uc774 \ub2e8 1\ud68c\ub77c\ub3c4 \ucc28\uc784\uc744 \uc5f0\uccb4\ud558\uba74 \uc784\ub300\uc778\uc740 \uc989\uc2dc \ud574\uc9c0\ud560 \uc218 \uc788\ub2e4","\uc784\ub300\ucc28\uacc4\uc57d\uc740 \uc5b4\ub5a0\ud55c \uc0ac\uc720\ub85c\ub3c4 \uc911\ub3c4\uc5d0 \ud574\uc9c0\ud560 \uc218 \uc5c6\ub2e4","\uc784\ub300\uc778\uc740 \uc815\ub2f9\ud55c \uc0ac\uc720 \uc5c6\uc774\ub3c4 \uc5b8\uc81c\ub4e0\uc9c0 \uc784\ub300\ucc28\ub97c \ud574\uc9c0\ud560 \uc218 \uc788\ub2e4"],t.s)
B.aV4=s(["\ucc28\uc784\uc5f0\uccb4\uc561\uc774 2\uae30\uc758 \ucc28\uc784\uc561\uc5d0 \ub2ec\ud558\ub294 \ub54c \uc784\ub300\uc778\uc774 \uacc4\uc57d\uc744 \ud574\uc9c0\ud560 \uc218 \uc788\ub3c4\ub85d \uaddc\uc815"],t.s)
B.b8s=s(["\uc784\ub300\ucc28 \ud574\uc9c0\uc0ac\uc720(\ucc28\uc784\uc5f0\uccb4)"],t.s)
B.buh=new A.a("gen_cl_termination_19","civil_law","\uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0",null,"\uc784\ub300\ucc28\uacc4\uc57d\uc758 \ud574\uc9c0 \uc0ac\uc720\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aMn,0,"\ubbfc\ubc95 \uc81c640\uc870\ub294 \uac74\ubb3c \ub4f1\uc758 \uc784\ub300\ucc28\uc5d0\uc11c \uc784\ucc28\uc778\uc758 \ucc28\uc784\uc5f0\uccb4\uc561\uc774 2\uae30\uc758 \ucc28\uc784\uc561\uc5d0 \ub2ec\ud558\ub294 \ub54c \uc784\ub300\uc778\uc774 \uacc4\uc57d\uc744 \ud574\uc9c0\ud560 \uc218 \uc788\ub3c4\ub85d \uaddc\uc815\ud558\uc5ec, \uacc4\uc18d\uc801 \uacc4\uc57d\uc778 \uc784\ub300\ucc28\uc758 \ub300\ud45c\uc801 \ubc95\uc815\ud574\uc9c0 \uc0ac\uc720\ub97c \uc815\ud558\uace0 \uc788\ub2e4.",B.aV4,B.b8s,null)
B.awS=s(["\ub2f9\uc0ac\uc790 \uc0ac\uc774\uc5d0 \uc704\uc57d\uae08 \uc57d\uc815\uc774 \uc788\uc73c\uba74 \uc190\ud574\ubc30\uc0c1\uc561\uc758 \uc608\uc815\uc73c\ub85c \ucd94\uc815\ud55c\ub2e4","\uc704\uc57d\uae08\uc740 \ud56d\uc0c1 \uc704\uc57d\ubc8c\ub85c\ub9cc \ud574\uc11d\ub418\uc5b4\uc57c \ud55c\ub2e4","\uc704\uc57d\uae08 \uc57d\uc815\uc740 \uc544\ubb34\ub7f0 \ubc95\uc801 \ud6a8\ub825\uc744 \uac00\uc9c0\uc9c0 \ubabb\ud55c\ub2e4","\uc704\uc57d\uae08\uc740 \ubc18\ub4dc\uc2dc \ubc95\uc6d0\uc758 \uc2b9\uc778\uc744 \ubc1b\uc544\uc57c\ub9cc \uc720\ud6a8\ud558\ub2e4"],t.s)
B.aJh=s(["\uc704\uc57d\uae08\uc758 \uc57d\uc815\uc740 \uc190\ud574\ubc30\uc0c1\uc561\uc758 \uc608\uc815\uc73c\ub85c \ucd94\uc815"],t.s)
B.aAR=s(["\uc704\uc57d\uae08\uacfc \uc190\ud574\ubc30\uc0c1\uc561 \uc608\uc815\uc758 \ucd94\uc815"],t.s)
B.bFN=new A.a("gen_cl_termination_20","civil_law","\uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0",null,"\uc704\uc57d\uae08 \uc57d\uc815\uacfc \uc190\ud574\ubc30\uc0c1\uc561\uc758 \uc608\uc815 \ucd94\uc815(\ubbfc\ubc95 \uc81c398\uc870 \uc81c4\ud56d)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.awS,0,"\ubbfc\ubc95 \uc81c398\uc870 \uc81c4\ud56d\uc740 \uc704\uc57d\uae08\uc758 \uc57d\uc815\uc740 \uc190\ud574\ubc30\uc0c1\uc561\uc758 \uc608\uc815\uc73c\ub85c \ucd94\uc815\ud55c\ub2e4\uace0 \uaddc\uc815\ud558\ubbc0\ub85c, \ud2b9\ubcc4\ud788 \uc704\uc57d\ubc8c\ub85c \ubcfc \uc0ac\uc815\uc774 \uc5c6\ub294 \ud55c \uc704\uc57d\uae08\uc740 \uc190\ud574\ubc30\uc0c1\uc561\uc758 \uc608\uc815\uc73c\ub85c \ub2e4\ub8e8\uc5b4\uc838 \ubc95\uc6d0\uc758 \uac10\uc561 \ub300\uc0c1\uc774 \ub420 \uc218 \uc788\ub2e4.",B.aJh,B.aAR,null)
B.bi6=s(["\ud574\uc81c\uc758 \uc18c\uae09\ud6a8\ub85c \uc18c\uc720\uad8c\uc740 \ub4f1\uae30 \uc5c6\uc774\ub3c4 \ub2f9\uc5f0\ud788 \ub9e4\ub3c4\uc778\uc5d0\uac8c \ubcf5\uadc0\ud55c\ub2e4\ub294 \uac83\uc774 \ud310\ub840\uc758 \ud0dc\ub3c4\uc774\ub2e4(\ubb3c\uad8c\ud589\uc704\uc758 \uc720\uc778\uc131 \uc804\uc81c)","\ud574\uc81c\ub9cc\uc73c\ub85c\ub294 \uc18c\uc720\uad8c\uc774 \ubcf5\uadc0\ud558\uc9c0 \uc54a\uace0 \ubc18\ub4dc\uc2dc \ubcc4\ub3c4\uc758 \uc774\uc804\ub4f1\uae30\ub97c \ub9c8\uccd0\uc57c\ub9cc \ubcf5\uadc0\ud55c\ub2e4","\ud574\uc81c\ub418\uc5b4\ub3c4 \ub9e4\uc218\uc778\uc774 \uba85\uc758\ub97c \uadf8\ub300\ub85c \ubcf4\uc720\ud558\uba74 \uc18c\uc720\uad8c\ub3c4 \ub9e4\uc218\uc778\uc5d0\uac8c \ub0a8\ub294\ub2e4","\ud574\uc81c \uc2dc \uc18c\uc720\uad8c \ubcf5\uadc0 \uc5ec\ubd80\ub294 \ubc95\ub960\uc0c1 \uc804\ud600 \uc815\ud574\uc838 \uc788\uc9c0 \uc54a\ub2e4"],t.s)
B.a3R=s(["\ud574\uc81c\uc758 \uc18c\uae09\ud6a8\ub85c \uc18c\uc720\uad8c\uc740 \ub4f1\uae30 \uc5c6\uc774\ub3c4 \ub2f9\uc5f0\ud788 \ub9e4\ub3c4\uc778\uc5d0\uac8c \ubcf5\uadc0\ud55c\ub2e4"],t.s)
B.b_A=s(["\ud574\uc81c\uc640 \uc18c\uc720\uad8c\uc758 \ubcf5\uadc0(\ubb3c\uad8c\ud589\uc704\uc758 \uc720\uc778\uc131)"],t.s)
B.bzY=new A.a("gen_cl_termination_21","civil_law","\uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0",null,"\ubd80\ub3d9\uc0b0 \ub9e4\ub9e4\uacc4\uc57d\uc774 \ud574\uc81c\ub41c \uacbd\uc6b0 \uc18c\uc720\uad8c\uc758 \ubcf5\uadc0\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.bi6,0,"\ud310\ub840(\ubb3c\uad8c\ud589\uc704\uc758 \uc720\uc778\uc131\uc744 \uc804\uc81c)\ub294 \ub9e4\ub9e4\uacc4\uc57d\uc774 \ud574\uc81c\ub418\uba74 \uadf8 \uc18c\uae09\ud6a8\ub85c \uc778\ud574 \uc774\uc804\ub418\uc5c8\ub358 \uc18c\uc720\uad8c\uc774 \ub4f1\uae30 \uc5c6\uc774\ub3c4 \ub2f9\uc5f0\ud788 \ub9e4\ub3c4\uc778\uc5d0\uac8c \ubcf5\uadc0\ud55c\ub2e4\uace0 \ubcf4\uba70, \ub2e4\ub9cc \ub9e4\uc218\uc778 \uba85\uc758\uc758 \ub4f1\uae30\ub294 \ub9d0\uc18c\ub418\uc5b4\uc57c \ud560 \uc0c1\ud0dc\uc5d0 \uc788\ub294 \uac83\uc73c\ub85c \ucde8\uae09\ud55c\ub2e4.",B.a3R,B.b_A,null)
B.Zo=s(["\uae08\uc804 \uc774\uc678\uc5d0 \ubaa9\uc801\ubb3c\uc744 \uc0ac\uc6a9\ud558\uc5ec \uc5bb\uc740 \uc0ac\uc6a9\uc774\uc775\ub3c4 \uc6d0\uc0c1\ud68c\ubcf5\uc758 \ubc94\uc704\uc5d0 \ud3ec\ud568\ub418\uc5b4 \ubc18\ud658\ud558\uc5ec\uc57c \ud55c\ub2e4","\uc6d0\uc0c1\ud68c\ubcf5\uc740 \uc624\uc9c1 \uc6d0\ubb3c \ubc18\ud658\ub9cc\uc744 \uc758\ubbf8\ud558\uace0 \uc0ac\uc6a9\uc774\uc775\uc740 \uc804\ud600 \uace0\ub824\ub418\uc9c0 \uc54a\ub294\ub2e4","\uc6d0\uc0c1\ud68c\ubcf5 \uc2dc \uacfc\uc2e4(\u679c\u5be6)\uc740 \ubc18\ud658 \ub300\uc0c1\uc5d0\uc11c \uc81c\uc678\ub41c\ub2e4","\uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\ub294 \uae08\uc804\uc9c0\uae09\uc758\ubb34\uc5d0\ub9cc \ud55c\uc815\ub41c\ub2e4"],t.s)
B.aN1=s(["\ubaa9\uc801\ubb3c\uc744 \uc0ac\uc6a9\ud558\uc5ec \uc5bb\uc740 \uc0ac\uc6a9\uc774\uc775\ub3c4 \uc6d0\uc0c1\ud68c\ubcf5\uc758 \ubc94\uc704\uc5d0 \ud3ec\ud568\ub418\uc5b4 \ubc18\ud658\ud558\uc5ec\uc57c \ud55c\ub2e4"],t.s)
B.aZt=s(["\uc6d0\uc0c1\ud68c\ubcf5\uc758 \ubc94\uc704(\uc0ac\uc6a9\uc774\uc775 \ud3ec\ud568)"],t.s)
B.bpe=new A.a("gen_cl_termination_22","civil_law","\uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0",null,"\ud574\uc81c\ub85c \uc778\ud55c \uc6d0\uc0c1\ud68c\ubcf5\uc758 \ubc94\uc704\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.Zo,0,"\uacc4\uc57d \ud574\uc81c\ub85c \uc778\ud55c \uc6d0\uc0c1\ud68c\ubcf5\uc740 \uae09\ubd80\ubc1b\uc740 \uc6d0\ubb3c\ubfd0 \uc544\ub2c8\ub77c \uadf8 \ubaa9\uc801\ubb3c\uc744 \uc0ac\uc6a9\ud568\uc73c\ub85c\uc368 \uc5bb\uc740 \uc0ac\uc6a9\uc774\uc775\uc774\ub098 \uacfc\uc2e4\ub3c4 \ud568\uaed8 \ubc18\ud658\ud558\uc5ec\uc57c \ud558\ub294 \uac83\uc744 \ud3ec\ud568\ud55c\ub2e4\ub294 \uac83\uc774 \ud310\ub840\uc758 \ud0dc\ub3c4\uc774\ub2e4.",B.aN1,B.aZt,null)
B.aR2=s(["\ud574\uc9c0 \uc774\uc804\uc5d0 \uc774\ubbf8 \uc774\ud589\ub41c \ubd80\ubd84\uc740 \uc720\ud6a8\ud558\uac8c \uc720\uc9c0\ub418\uace0, \ud574\uc9c0\uc758 \ud6a8\ub825\uc740 \uc7a5\ub798 \ubd80\ubd84\uc5d0 \ub300\ud574\uc11c\ub9cc \ubc1c\uc0dd\ud55c\ub2e4","\ud574\uc9c0\ud558\uba74 \uc774\ubbf8 \uc774\ud589\ub41c \ubd80\ubd84\ub3c4 \uc804\ubd80 \ubb34\ud6a8\uac00 \ub418\uc5b4 \uc6d0\uc0c1\ud68c\ubcf5\ud574\uc57c \ud55c\ub2e4","\ud574\uc9c0\ub294 \ud574\uc81c\uc640 \ub9c8\ucc2c\uac00\uc9c0\ub85c \ucc98\uc74c\ubd80\ud130 \uacc4\uc57d\uc774 \uc5c6\uc5c8\ub358 \uac83\uc73c\ub85c \ucde8\uae09\ud55c\ub2e4","\ud574\uc9c0 \uc2dc \uc774\ubbf8 \uc9c0\uae09\ub41c \uc784\ub8cc \ub4f1\uc740 \ud56d\uc0c1 \uc804\uc561 \ubc18\ud658\ud574\uc57c \ud55c\ub2e4"],t.s)
B.aIO=s(["\ud574\uc9c0 \uc774\uc804\uc5d0 \uc774\ubbf8 \uc774\ud589\ub41c \ubd80\ubd84\uc740 \uc720\ud6a8\ud558\uac8c \uc720\uc9c0\ub418\uace0, \ud574\uc9c0\uc758 \ud6a8\ub825\uc740 \uc7a5\ub798 \ubd80\ubd84\uc5d0 \ub300\ud574\uc11c\ub9cc \ubc1c\uc0dd"],t.s)
B.arZ=s(["\ud574\uc9c0\uc758 \uc7a5\ub798\ud6a8\uc640 \uae30\uc874 \uc774\ud589\ubd80\ubd84"],t.s)
B.bqC=new A.a("gen_cl_termination_23","civil_law","\uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0",null,"\ud574\uc9c0\uc758 \uc7a5\ub798\ud6a8\uc640 \uc774\ubbf8 \uc774\ud589\ub41c \ubd80\ubd84\uc758 \ud6a8\ub825\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aR2,0,"\ud574\uc9c0\ub294 \uc18c\uae09\ud6a8\uac00 \uc5c6\uc5b4 \uadf8 \uc774\uc804\uc5d0 \uc774\ubbf8 \uc774\ud589\ub41c \ubd80\ubd84(\uc608: \uc774\ubbf8 \uacbd\uacfc\ud55c \uae30\uac04\uc758 \uc784\ub300\ucc28 \uc0ac\uc6a9\uad00\uacc4)\uc740 \uc720\ud6a8\ud558\uac8c \uc720\uc9c0\ub418\uace0, \ud574\uc9c0\uc758 \ud6a8\ub825\uc740 \uc7a5\ub798\ub97c \ud5a5\ud574\uc11c\ub9cc \ubc1c\uc0dd\ud55c\ub2e4\ub294 \uc810\uc774 \ud574\uc81c\uc640\uc758 \ud575\uc2ec \ucc28\uc774\uc774\ub2e4.",B.aIO,B.arZ,null)
B.aW6=s(["\ud574\uc81c\uc870\uac74\uc774 \ubd99\uc740 \ubc95\ub960\ud589\uc704\ub294 \uc870\uac74\uc774 \uc131\ucde8\ub418\uba74 \ubcc4\ub3c4\uc758 \uc758\uc0ac\ud45c\uc2dc \uc5c6\uc774 \ub2f9\uc5f0\ud788 \ud6a8\ub825\uc744 \uc783\uc9c0\ub9cc, \ud574\uc81c\uad8c\uc758 \ud589\uc0ac\ub294 \uad8c\ub9ac\uc790\uc758 \uc758\uc0ac\ud45c\uc2dc\uac00 \uc788\uc5b4\uc57c \ud6a8\ub825\uc774 \ubc1c\uc0dd\ud55c\ub2e4","\ud574\uc81c\uc870\uac74\uacfc \ud574\uc81c\uad8c \ud589\uc0ac\ub294 \ubaa8\ub450 \uc758\uc0ac\ud45c\uc2dc\ub97c \uc694\uac74\uc73c\ub85c \ud55c\ub2e4","\ud574\uc81c\uc870\uac74\uc740 \ud574\uc81c\uad8c\uc758 \uc77c\uc885\uc73c\ub85c \ud615\uc131\uad8c\uc5d0 \ud574\ub2f9\ud55c\ub2e4","\ud574\uc81c\uc870\uac74\ubd80 \ubc95\ub960\ud589\uc704\ub294 \uc870\uac74\uc774 \uc131\ucde8\ub418\uc5b4\ub3c4 \uacc4\uc57d\uc774 \uc18c\uba78\ud558\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.abn=s(["\uc870\uac74\uc774 \uc131\ucde8\ub418\uba74 \ubcc4\ub3c4\uc758 \uc758\uc0ac\ud45c\uc2dc \uc5c6\uc774 \ub2f9\uc5f0\ud788 \ud6a8\ub825\uc744 \uc783\uc9c0\ub9cc"],t.s)
B.a4A=s(["\ud574\uc81c\uc870\uac74\uacfc \ud574\uc81c\uad8c \ud589\uc0ac\uc758 \uad6c\uc870\uc801 \ucc28\uc774"],t.s)
B.bAR=new A.a("gen_cl_termination_24","civil_law","\uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0",null,"\ud574\uc81c\uc870\uac74\ubd80 \ubc95\ub960\ud589\uc704\uc640 \ud574\uc81c\uad8c \ud589\uc0ac\uc5d0 \ub530\ub978 \uacc4\uc57d\uc18c\uba78\uc744 \ube44\uad50\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aW6,0,"\ud574\uc81c\uc870\uac74\ubd80 \ubc95\ub960\ud589\uc704\ub294 \uc870\uac74 \uc131\ucde8\ub77c\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \ub2f9\uc5f0\ud788 \ud6a8\ub825\uc744 \uc0c1\uc2e4\ud558\ub294 \ubc18\uba74, \ud574\uc81c\uad8c\uc740 \ud615\uc131\uad8c\uc73c\ub85c\uc11c \uad8c\ub9ac\uc790\uc758 \ubcc4\ub3c4 \uc758\uc0ac\ud45c\uc2dc(\ud574\uc81c \uc758\uc0ac\ud45c\uc2dc)\uac00 \uc788\uc5b4\uc57c \ube44\ub85c\uc18c \uacc4\uc57d\uc758 \ud6a8\ub825\uc774 \uc18c\uba78\ud55c\ub2e4\ub294 \uc810\uc5d0\uc11c \uad6c\uc870\uc801\uc73c\ub85c \ub2e4\ub974\ub2e4.",B.abn,B.a4A,null)
B.aFq=s(["\ucc44\uad8c\uc790\uac00 \uc544\uc9c1 \ud574\uc81c \ub4f1 \ub300\uc751\uc870\uce58\ub97c \ucde8\ud558\uc9c0 \uc54a\uc740 \uc0c1\ud0dc\ub77c\uba74, \ucc44\ubb34\uc790\ub294 \uc774\ud589\uac70\uc808\uc758 \uc758\uc0ac\ub97c \ucca0\ud68c\ud558\uace0 \uc774\ud589\ud560 \uc218 \uc788\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub2e4","\ud55c\ubc88 \uc774\ud589\uac70\uc808 \uc758\uc0ac\ub97c \ud45c\uc2dc\ud558\uba74 \uc774\ud6c4\uc5d0\ub294 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \uc774\ud589\ud560 \uc218 \uc5c6\ub2e4","\uc774\ud589\uac70\uc808 \uc758\uc0ac\ud45c\uc2dc\ub294 \ucca0\ud68c\uac00 \uc804\ud600 \ud5c8\uc6a9\ub418\uc9c0 \uc54a\ub294 \ud615\uc131\uad8c\uc801 \uc758\uc0ac\ud45c\uc2dc\uc774\ub2e4","\uc774\ud589\uac70\uc808\uc758 \ucca0\ud68c\ub294 \ubc95\uc6d0\uc758 \ud5c8\uac00\ub97c \ubc1b\uc544\uc57c\ub9cc \uac00\ub2a5\ud558\ub2e4"],t.s)
B.aHI=s(["\ucc44\uad8c\uc790\uac00 \uc544\uc9c1 \ud574\uc81c \ub4f1 \ub300\uc751\uc870\uce58\ub97c \ucde8\ud558\uc9c0 \uc54a\uc740 \uc0c1\ud0dc\ub77c\uba74, \ucc44\ubb34\uc790\ub294 \uc774\ud589\uac70\uc808\uc758 \uc758\uc0ac\ub97c \ucca0\ud68c\ud558\uace0 \uc774\ud589\ud560 \uc218 \uc788\ub294 \uac83\uc774 \uc6d0\uce59"],t.s)
B.a9l=s(["\uc774\ud589\uac70\uc808 \uc758\uc0ac\uc758 \ucca0\ud68c \uac00\ub2a5\uc131"],t.s)
B.bnK=new A.a("gen_cl_termination_25","civil_law","\uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0",null,"\ucc44\ubb34\uc790\uac00 \uc774\ud589\uac70\uc808\uc758 \uc758\uc0ac\ub97c \ud45c\uc2dc\ud558\uc600\ub2e4\uac00 \uc774\ub97c \ub2e4\uc2dc \ubc88\ubcf5\ud558\uace0 \uc774\ud589\ud558\uaca0\ub2e4\ub294 \uc758\uc0ac\ub97c \ud45c\uc2dc\ud55c \uacbd\uc6b0\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aFq,0,"\uc774\ud589\uac70\uc808\uc740 \ud574\uc81c\uad8c\uacfc \ub2ec\ub9ac \uadf8 \uc790\uccb4\uac00 \ud615\uc131\uad8c \ud589\uc0ac\ub294 \uc544\ub2c8\ubbc0\ub85c, \uc0c1\ub300\ubc29\uc774 \uc774\ub97c \uc774\uc720\ub85c \ud574\uc81c \ub4f1 \uc870\uce58\ub97c \ucde8\ud558\uae30 \uc804\uc774\ub77c\uba74 \ucc44\ubb34\uc790\uac00 \uc774\ud589\uac70\uc808\uc758 \uc758\uc0ac\ub97c \ucca0\ud68c\ud558\uace0 \uc774\ud589\uc744 \uc81c\uacf5\ud558\ub294 \uac83\uc774 \uac00\ub2a5\ud558\ub2e4\uace0 \ubcf4\ub294 \uac83\uc774 \uc77c\ubc18\uc801\uc774\ub2e4.",B.aHI,B.a9l,null)
B.b0W=s(["\ud574\uc81c\uad8c\uc758 \ubd88\uac00\ubd84\uc131 \uaddc\uc815(\uc81c547\uc870)\uc774 \ud574\uc9c0\uc5d0\ub3c4 \uc900\uc6a9\ub418\uc5b4 \uc804\uc6d0\uc73c\ub85c\ubd80\ud130 \ub610\ub294 \uc804\uc6d0\uc5d0 \ub300\ud558\uc5ec \ud558\uc5ec\uc57c \ud55c\ub2e4","\ud574\uc9c0\ub294 \ud574\uc81c\uc640 \ub2ec\ub9ac \ub2f9\uc0ac\uc790 1\uc778\uc774 \ub2e8\ub3c5\uc73c\ub85c \uc790\uc720\ub86d\uac8c \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4","\ud574\uc9c0\uad8c\uc758 \ubd88\uac00\ubd84\uc131\uc740 \uc784\ub300\ucc28\uc5d0\ub294 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4","\ud574\uc9c0\uad8c \ud589\uc0ac\uc5d0\ub294 \uc5b4\ub5a0\ud55c \ubc29\uc2dd\uc758 \uc81c\ud55c\ub3c4 \uc5c6\uc5b4 \uac01\uc790 \uac1c\ubcc4\uc801\uc73c\ub85c \ud589\uc0ac\ud574\ub3c4 \ubb34\ubc29\ud558\ub2e4"],t.s)
B.beC=s(["\ud574\uc81c\uad8c\uc758 \ubd88\uac00\ubd84\uc131 \uaddc\uc815(\uc81c547\uc870)\uc774 \ud574\uc9c0\uc5d0\ub3c4 \uc900\uc6a9"],t.s)
B.b9p=s(["\ud574\uc9c0\uad8c\uc758 \ubd88\uac00\ubd84\uc131"],t.s)
B.bCN=new A.a("gen_cl_termination_26","civil_law","\uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0",null,"\ub2f9\uc0ac\uc790 \uc77c\ubc29 \ub610\ub294 \uc30d\ubc29\uc774 \uc218\uc778\uc778 \uacc4\uc57d\uc5d0\uc11c \ud574\uc9c0\uad8c \ud589\uc0ac\ubc29\ubc95\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.b0W,0,"\ubbfc\ubc95 \uc81c547\uc870\uc758 \ud574\uc81c\uad8c \ubd88\uac00\ubd84\uc131 \uaddc\uc815\uc740 \ud574\uc9c0\uc5d0\ub3c4 \uadf8\ub300\ub85c \uc900\uc6a9\ub418\ubbc0\ub85c, \ub2f9\uc0ac\uc790\uac00 \uc218\uc778\uc778 \uacc4\uc57d\uad00\uacc4\uc758 \ud574\uc9c0\ub3c4 \uc6d0\uce59\uc801\uc73c\ub85c \uc804\uc6d0\uc73c\ub85c\ubd80\ud130 \ub610\ub294 \uc804\uc6d0\uc5d0 \ub300\ud558\uc5ec \ud589\uc0ac\ud558\uc5ec\uc57c \ud55c\ub2e4.",B.beC,B.b9p,null)
B.ZC=s(["\uc81c3\uc790\uc758 \uc120\uc758\xb7\uc545\uc758\ub97c \ubd88\ubb38\ud558\uace0 \ubaa8\ub4e0 \uc81c3\uc790\uac00 \ubcf4\ud638\ub41c\ub2e4","\ud574\uc81c \uc804\uc5d0 \ubaa9\uc801\ubb3c\uc5d0 \uad00\ud558\uc5ec \uc0c8\ub85c\uc6b4 \ubc95\ub960\uc0c1 \uc774\ud574\uad00\uacc4\ub97c \ub9fa\uace0 \ub4f1\uae30\xb7\uc778\ub3c4 \ub4f1\uc744 \uac16\ucd98 \uc120\uc758\uc758 \uc81c3\uc790\ub9cc \ubcf4\ud638 \ub300\uc0c1\uc774 \ub41c\ub2e4","\uc81c3\uc790 \ubcf4\ud638 \uaddc\uc815\uc740 \ubd80\ub3d9\uc0b0\uc5d0\ub9cc \uc801\uc6a9\ub418\uace0 \ub3d9\uc0b0\uc5d0\ub294 \uc804\ud600 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4","\ud574\uc81c \ud6c4\uc5d0 \uc774\ud574\uad00\uacc4\ub97c \ub9fa\uc740 \uc790\ub3c4 \ub2f9\uc5f0\ud788 \ubcf4\ud638 \ub300\uc0c1\uc5d0 \ud3ec\ud568\ub41c\ub2e4"],t.s)
B.bd5=s(["\ud574\uc81c \uc804\uc5d0 \ubaa9\uc801\ubb3c\uc5d0 \uad00\ud558\uc5ec \uc0c8\ub85c\uc6b4 \ubc95\ub960\uc0c1 \uc774\ud574\uad00\uacc4\ub97c \ub9fa\uace0 \ub4f1\uae30\xb7\uc778\ub3c4 \ub4f1\uc744 \uac16\ucd98 \uc120\uc758\uc758 \uc81c3\uc790\ub9cc \ubcf4\ud638 \ub300\uc0c1"],t.s)
B.aW_=s(["\ud574\uc81c\uc640 \uc81c3\uc790 \ubcf4\ud638\uc758 \ubc94\uc704"],t.s)
B.bpd=new A.a("gen_cl_termination_27","civil_law","\uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0",null,"\uacc4\uc57d\ud574\uc81c\uc640 \uc81c3\uc790 \ubcf4\ud638\uc5d0 \uad00\ud55c \ud310\ub840\uc758 \ud0dc\ub3c4\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.ZC,1,"\ud310\ub840\ub294 \uc81c548\uc870 \uc81c1\ud56d \ub2e8\uc11c\uc758 \uc81c3\uc790\ub97c \ud574\uc81c\ub418\ub294 \uacc4\uc57d\uc744 \uae30\ucd08\ub85c \ud558\uc5ec \ud574\uc81c \uc804\uc5d0 \uc0c8\ub85c\uc6b4 \uad8c\ub9ac\ub97c \ucde8\ub4dd\ud558\uace0 \ub4f1\uae30\xb7\uc778\ub3c4 \ub4f1 \uc644\uc804\ud55c \uad8c\ub9ac\ub97c \uac16\ucd98 \uc120\uc758\uc758 \uc790\ub85c \uc81c\ud55c\uc801\uc73c\ub85c \ud574\uc11d\ud55c\ub2e4.",B.bd5,B.aW_,null)
B.aaR=s(["\uc6d0\uc0c1\ud68c\ubcf5\uccad\uad6c\uad8c\ub3c4 \ud558\ub098\uc758 \ucc44\uad8c\uc73c\ub85c\uc11c \uc6d0\uce59\uc801\uc73c\ub85c \uc18c\uba78\uc2dc\ud6a8\uc758 \uc801\uc6a9\uc744 \ubc1b\ub294\ub2e4","\uc6d0\uc0c1\ud68c\ubcf5\uccad\uad6c\uad8c\uc740 \ubb3c\uad8c\uc801 \uccad\uad6c\uad8c\uc774\ubbc0\ub85c \uc18c\uba78\uc2dc\ud6a8\uc5d0 \uac78\ub9ac\uc9c0 \uc54a\ub294\ub2e4","\uc6d0\uc0c1\ud68c\ubcf5\uccad\uad6c\uad8c\uc740 \ud574\uc81c\uc640 \ub3d9\uc2dc\uc5d0 \uc790\ub3d9\uc73c\ub85c \uc18c\uba78\ud55c\ub2e4","\uc6d0\uc0c1\ud68c\ubcf5\uccad\uad6c\uad8c\uc5d0\ub294 \uc5b4\ub5a0\ud55c \uc2dc\ud6a8 \uaddc\uc815\ub3c4 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.a3r=s(["\ubd80\ub2f9\uc774\ub4dd\ubc18\ud658\uccad\uad6c\uad8c\uc758 \uc131\uc9c8\uc744 \uac00\uc9c0\ub294 \ucc44\uad8c\uc801 \uccad\uad6c\uad8c\uc73c\ub85c, \uc6d0\uce59\uc801\uc73c\ub85c \uc77c\ubc18 \ucc44\uad8c\uc758 \uc18c\uba78\uc2dc\ud6a8\uc758 \uc801\uc6a9\uc744 \ubc1b\ub294\ub2e4"],t.s)
B.b55=s(["\uc6d0\uc0c1\ud68c\ubcf5\uccad\uad6c\uad8c\uacfc \uc18c\uba78\uc2dc\ud6a8"],t.s)
B.bwH=new A.a("gen_cl_termination_28","civil_law","\uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0",null,"\uacc4\uc57d\ud574\uc81c \ud6c4 \uc6d0\uc0c1\ud68c\ubcf5\uccad\uad6c\uad8c\uc758 \uc18c\uba78\uc2dc\ud6a8\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aaR,0,"\ud574\uc81c\ub85c \uc778\ud55c \uc6d0\uc0c1\ud68c\ubcf5\uccad\uad6c\uad8c\uc740 \ubd80\ub2f9\uc774\ub4dd\ubc18\ud658\uccad\uad6c\uad8c\uc758 \uc131\uc9c8\uc744 \uac00\uc9c0\ub294 \ucc44\uad8c\uc801 \uccad\uad6c\uad8c\uc73c\ub85c, \uc6d0\uce59\uc801\uc73c\ub85c \uc77c\ubc18 \ucc44\uad8c\uc758 \uc18c\uba78\uc2dc\ud6a8(10\ub144 \ub4f1)\uc758 \uc801\uc6a9\uc744 \ubc1b\ub294\ub2e4.",B.a3r,B.b55,null)
B.anP=s(["\uacc4\uc18d\uc801 \uacc4\uc57d\uc5d0\uc11c\ub294 \uc2e0\ub8b0\uad00\uacc4 \ud30c\uad34 \ub4f1 \uacc4\uc18d\uc801 \uacc4\uc57d\uad00\uacc4\uc5d0 \ud2b9\uc720\ud55c \ud574\uc9c0\uc0ac\uc720\uac00 \uc778\uc815\ub420 \uc218 \uc788\ub2e4","\uacc4\uc18d\uc801 \uacc4\uc57d\uacfc \uc77c\ud68c\uc801 \uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0 \uc694\uac74\uc740 \ud56d\uc0c1 \uc644\uc804\ud788 \ub3d9\uc77c\ud558\ub2e4","\uacc4\uc18d\uc801 \uacc4\uc57d\uc5d0\uc11c\ub294 \ucc44\ubb34\ubd88\uc774\ud589\uc774 \uc788\uc5b4\ub3c4 \ud574\uc9c0\uac00 \uc804\ud600 \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4","\uc77c\ud68c\uc801 \uacc4\uc57d\uc5d0\uc11c\ub294 \ucd5c\uace0 \uc5c6\uc774 \ud574\uc81c\ud558\ub294 \uacbd\uc6b0\uac00 \uc804\ud600 \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.aha=s(["\uc2e0\ub8b0\uad00\uacc4 \ud30c\uad34 \ub4f1 \uacc4\uc18d\uc801 \uacc4\uc57d\uad00\uacc4\uc5d0 \ud2b9\uc720\ud55c \ud574\uc9c0\uc0ac\uc720\uac00 \uc778\uc815\ub420 \uc218 \uc788\ub2e4"],t.s)
B.XQ=s(["\uacc4\uc18d\uc801 \uacc4\uc57d\uc758 \ud2b9\uc720\ud55c \ud574\uc9c0\uc0ac\uc720"],t.s)
B.bt8=new A.a("gen_cl_termination_29","civil_law","\uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0",null,"\uacc4\uc18d\uc801 \uacc4\uc57d\uc758 \ud574\uc9c0 \uc694\uac74\uacfc \uc77c\ud68c\uc801 \uacc4\uc57d\uc758 \ud574\uc81c \uc694\uac74\uc744 \ube44\uad50\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.anP,0,"\uc704\uc784\xb7\uc870\ud569\xb7\uc784\ub300\ucc28 \ub4f1 \uacc4\uc18d\uc801 \uacc4\uc57d\uad00\uacc4\uc5d0\uc11c\ub294 \uc77c\ubc18\uc801\uc778 \ucc44\ubb34\ubd88\uc774\ud589 \uc694\uac74 \uc678\uc5d0\ub3c4 \ub2f9\uc0ac\uc790 \uac04 \uc2e0\ub8b0\uad00\uacc4\uc758 \ud30c\uad34\uc640 \uac19\uc740 \uacc4\uc18d\uc801 \uacc4\uc57d \ud2b9\uc720\uc758 \uc0ac\uc815\uc744 \uc774\uc720\ub85c \ud55c \ud574\uc9c0\uac00 \ud310\ub840\uc0c1 \uc778\uc815\ub418\ub294 \uacbd\uc6b0\uac00 \uc788\ub2e4.",B.aha,B.XQ,null)
B.ayq=s(["\uacc4\uc57d\uae08\uc740 \ub2e4\ub978 \uc57d\uc815\uc774 \uc5c6\uc73c\uba74 \ud574\uc57d\uae08\uc73c\ub85c \ucd94\uc815\ub418\uc5b4 \uc774\ud589\ucc29\uc218 \uc804\uae4c\uc9c0 \ud574\uc81c\uae08 \uc5ed\ud560\uc744 \ud55c\ub2e4","\uc704\uc57d\uae08 \uc57d\uc815\uc740 \uc190\ud574\ubc30\uc0c1\uc561\uc758 \uc608\uc815\uc73c\ub85c \ucd94\uc815\ub41c\ub2e4","\ud574\uc81c\ub85c \uc778\ud55c \uc6d0\uc0c1\ud68c\ubcf5\uc5d0\ub294 \uc0ac\uc6a9\uc774\uc775 \ubc18\ud658\uc774 \ud3ec\ud568\ub418\uc9c0 \uc54a\ub294\ub2e4","\ud574\uc9c0\ub294 \uc774\ubbf8 \uc774\ud589\ub41c \ubd80\ubd84\uc758 \ud6a8\ub825\uc5d0 \uc601\ud5a5\uc744 \ubbf8\uce58\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.amp=s(["\ubaa9\uc801\ubb3c\uc758 \uc0ac\uc6a9\uc774\uc775\uc774\ub098 \uacfc\uc2e4\ub3c4 \ud3ec\ud568\uc2dc\ucf1c \ubc18\ud658\ud558\ub3c4\ub85d \ud558\ubbc0\ub85c"],t.s)
B.as9=s(["\uacc4\uc57d \ud574\uc81c\xb7\ud574\uc9c0 \uc2ec\ud654\uc815\ub9ac"],t.s)
B.bNW=new A.a("gen_cl_termination_30","civil_law","\uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0",null,"\uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0\uc5d0 \uad00\ud55c \uc2ec\ud654 \uc0ac\ub840 \u2014 \ub2e4\uc74c \uc911 \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.ayq,2,"\ud310\ub840\ub294 \uacc4\uc57d \ud574\uc81c\ub85c \uc778\ud55c \uc6d0\uc0c1\ud68c\ubcf5\uc758 \ubc94\uc704\uc5d0 \ubaa9\uc801\ubb3c\uc758 \uc0ac\uc6a9\uc774\uc775\uc774\ub098 \uacfc\uc2e4\ub3c4 \ud3ec\ud568\uc2dc\ucf1c \ubc18\ud658\ud558\ub3c4\ub85d \ud558\ubbc0\ub85c, \uc0ac\uc6a9\uc774\uc775 \ubc18\ud658\uc774 \ud3ec\ud568\ub418\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc124\uba85\uc740 \uc633\uc9c0 \uc54a\ub2e4.",B.amp,B.as9,null)
B.We=s(["\ub2e8\ub3c5\ud589\uc704\ub294 \uc0c1\ub300\ubc29\uc758 \uc2b9\ub099 \uc5c6\uc774 \ud589\uc704\uc790 \uc77c\ubc29\uc758 \uc758\uc0ac\ud45c\uc2dc\ub9cc\uc73c\ub85c \uc131\ub9bd\ud558\ub294 \ubc95\ub960\ud589\uc704\uc774\ub2e4.","\uacc4\uc57d\uc740 \uc11c\ub85c \ub300\ub9bd\ud558\ub294 \ub458 \uc774\uc0c1\uc758 \uc758\uc0ac\ud45c\uc2dc\uac00 \ud569\uce58\ub418\uc5b4 \uc131\ub9bd\ud558\ub294 \ubc95\ub960\ud589\uc704\uc774\ub2e4.","\ud569\ub3d9\ud589\uc704\ub294 \ubc29\ud5a5\uacfc \ub0b4\uc6a9\uc744 \uac19\uc774\ud558\ub294 \ub2e4\uc218 \ub2f9\uc0ac\uc790\uc758 \uc758\uc0ac\ud45c\uc2dc\uac00 \ud569\uce58\ub418\uc5b4 \uc131\ub9bd\ud558\ub294 \ubc95\ub960\ud589\uc704\uc774\ub2e4.","\uc720\uc99d\uacfc \uac19\uc740 \uc0c1\ub300\ubc29 \uc5c6\ub294 \ub2e8\ub3c5\ud589\uc704\ub294 \uc758\uc0ac\ud45c\uc2dc\uac00 \ub3c4\ub2ec\ud558\uc5ec\uc57c\ub9cc \ud6a8\ub825\uc774 \ubc1c\uc0dd\ud55c\ub2e4."],t.s)
B.a17=s(["\uc758\uc0ac\ud45c\uc2dc\uac00 \uc644\uc131\ub418\uba74 \uadf8 \uc790\uccb4\ub85c \ud6a8\ub825\uc774 \ubc1c\uc0dd\ud558\uace0 \ub3c4\ub2ec\uc744 \uc694\ud558\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.UF=s(["\ub2e8\ub3c5\ud589\uc704","\uc0c1\ub300\ubc29 \uc5c6\ub294 \ub2e8\ub3c5\ud589\uc704","\ud569\ub3d9\ud589\uc704"],t.s)
B.bLY=new A.a("gen_cl_juridicalact_25","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c",null,"\ubc95\ub960\ud589\uc704\uc758 \uc885\ub958\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.We,3,"\uc720\uc99d, \uc7ac\ub2e8\ubc95\uc778 \uc124\ub9bd\ud589\uc704\uc640 \uac19\uc740 \uc0c1\ub300\ubc29 \uc5c6\ub294 \ub2e8\ub3c5\ud589\uc704\ub294 \uc758\uc0ac\ud45c\uc2dc\uac00 \uc644\uc131\ub418\uba74 \uadf8 \uc790\uccb4\ub85c \ud6a8\ub825\uc774 \ubc1c\uc0dd\ud558\uace0 \ub3c4\ub2ec\uc744 \uc694\ud558\uc9c0 \uc54a\ub294\ub2e4. \ub2e8\ub3c5\ud589\uc704\xb7\uacc4\uc57d\xb7\ud569\ub3d9\ud589\uc704\uc758 \uad6c\ubd84\uc740 \uc758\uc0ac\ud45c\uc2dc\uc758 \ubc29\ud5a5\uacfc \uc218\uc5d0 \ub530\ub978 \uac83\uc774\ub2e4.",B.a17,B.UF,null)
B.Rm=s(["\ub9e4\ub9e4\uacc4\uc57d","\uc0ac\ub2e8\ubc95\uc778\uc758 \uc124\ub9bd\ud589\uc704","\ucc44\ubb34\uba74\uc81c","\uc720\uc99d"],t.s)
B.air=s(["\ub2e4\uc218 \uc124\ub9bd\uc790\uc758 \uc758\uc0ac\ud45c\uc2dc\uac00 \ub3d9\uc77c\ud55c \ubaa9\uc801\uc744 \ud5a5\ud574 \ubc29\ud5a5\uc744 \uac19\uc774\ud558\uc5ec \ud569\uce58\ub418\ub294 \ud569\ub3d9\ud589\uc704"],t.s)
B.Rk=s(["\ud569\ub3d9\ud589\uc704","\uc0ac\ub2e8\ubc95\uc778 \uc124\ub9bd\ud589\uc704"],t.s)
B.bni=new A.a("gen_cl_juridicalact_26","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c",null,"\ud569\ub3d9\ud589\uc704\uc5d0 \ud574\ub2f9\ud558\ub294 \uac83\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.Rm,1,"\uc0ac\ub2e8\ubc95\uc778 \uc124\ub9bd\ud589\uc704\ub294 \ub2e4\uc218 \uc124\ub9bd\uc790\uc758 \uc758\uc0ac\ud45c\uc2dc\uac00 \ub3d9\uc77c\ud55c \ubaa9\uc801\uc744 \ud5a5\ud574 \ubc29\ud5a5\uc744 \uac19\uc774\ud558\uc5ec \ud569\uce58\ub418\ub294 \ud569\ub3d9\ud589\uc704\uc758 \ub300\ud45c\uc801 \uc608\uc774\ub2e4. \ub9e4\ub9e4\ub294 \uacc4\uc57d, \ucc44\ubb34\uba74\uc81c\uc640 \uc720\uc99d\uc740 \ub2e8\ub3c5\ud589\uc704\uc5d0 \ud574\ub2f9\ud55c\ub2e4.",B.air,B.Rk,null)
B.b7i=s(["\ubc95\ub960\ud589\uc704\uc758 \ubaa9\uc801\uc740 \ubc95\ub960\ud589\uc704 \uc131\ub9bd \ub2f9\uc2dc \ud655\uc815\ub418\uc5b4 \uc788\uac70\ub098 \ud655\uc815\ud560 \uc218 \uc788\ub294 \ud45c\uc900\uc774 \uc788\uc5b4\uc57c \ud55c\ub2e4.","\ubc95\ub960\ud589\uc704\uc758 \ubaa9\uc801\uc740 \uc6d0\uc2dc\uc801\uc73c\ub85c \uc2e4\ud604\uc774 \uac00\ub2a5\ud55c \uac83\uc774\uc5b4\uc57c \ud558\uba70, \uc6d0\uc2dc\uc801 \ubd88\ub2a5\uc778 \uae09\ubd80\ub97c \ubaa9\uc801\uc73c\ub85c \ud55c \uacc4\uc57d\uc740 \ubb34\ud6a8\uc774\ub2e4.","\uac15\ud589\ubc95\uaddc\uc5d0 \uc704\ubc18\ub418\ub294 \ubc95\ub960\ud589\uc704\ub294 \uadf8 \ubaa9\uc801\uc758 \uc801\ubc95\uc131\uc774 \uc778\uc815\ub418\uc9c0 \uc54a\uc544 \ubb34\ud6a8\uc774\ub2e4.","\ubc95\ub960\ud589\uc704 \uc131\ub9bd \ub2f9\uc2dc\uc5d0\ub294 \ubaa9\uc801\uc744 \ud655\uc815\ud560 \uc218 \uc5c6\uc5c8\ub354\ub77c\ub3c4 \uc774\ud589\uae30\uae4c\uc9c0 \ud655\uc815\ub418\uba74 \uadf8 \ubc95\ub960\ud589\uc704\ub294 \ud56d\uc0c1 \uc720\ud6a8\ub85c \uc804\ud658\ub41c\ub2e4."],t.s)
B.aA7=s(["\ubaa9\uc801\uc758 \ud655\uc815 \uac00\ub2a5\uc131\uc740 \ubc95\ub960\ud589\uc704 \uc131\ub9bd \uc2dc\ub97c \uae30\uc900\uc73c\ub85c \ud310\ub2e8"],t.s)
B.adw=s(["\ud655\uc815\uc131","\uac00\ub2a5\uc131","\uc801\ubc95\uc131"],t.s)
B.bEs=new A.a("gen_cl_juridicalact_27","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c",null,"\ubc95\ub960\ud589\uc704\uc758 \ubaa9\uc801\uc774 \uac16\ucd94\uc5b4\uc57c \ud560 \uc694\uac74\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.b7i,3,"\ubc95\ub960\ud589\uc704\uc758 \ubaa9\uc801\uc740 \uc131\ub9bd \ub2f9\uc2dc \ud655\uc815\ub418\uc5b4 \uc788\uac70\ub098 \uc7a5\ub798 \ud655\uc815\ud560 \uc218 \uc788\ub294 \ud45c\uc900\uc774 \uc788\uc5b4\uc57c \ud558\uba70, \uc774\ub97c \uac16\ucd94\uc9c0 \ubabb\ud558\uba74 \uadf8 \ubc95\ub960\ud589\uc704\ub294 \ubb34\ud6a8\uc774\ub2e4. \ubaa9\uc801\uc758 \ud655\uc815 \uac00\ub2a5\uc131\uc740 \ubc95\ub960\ud589\uc704 \uc131\ub9bd \uc2dc\ub97c \uae30\uc900\uc73c\ub85c \ud310\ub2e8\ud558\ubbc0\ub85c, \uc0ac\ud6c4\uc5d0 \uc6b0\uc5f0\ud788 \ud655\uc815\ub418\uc5c8\ub2e4\ub294 \uc0ac\uc815\ub9cc\uc73c\ub85c \ub2f9\uc5f0\ud788 \uc720\ud6a8\ub85c \uc804\ud658\ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4.",B.aA7,B.adw,null)
B.a1P=s(["\ubc95\ub960\ud589\uc704\uac00 \uac15\ud589\ubc95\uaddc\uc5d0 \uc704\ubc18\ub418\uc9c0 \uc54a\uc73c\uba74 \uc0ac\ud68c\uc801 \ud0c0\ub2f9\uc131\uc740 \ubcc4\ub3c4\ub85c \ubb38\uc81c\ub418\uc9c0 \uc54a\ub294\ub2e4.","\ubc95\ub960\ud589\uc704\uc758 \ubaa9\uc801\uc774 \uac1c\ubcc4 \uac15\ud589\uaddc\uc815\uc5d0 \uc800\ucd09\ub418\uc9c0 \uc54a\ub354\ub77c\ub3c4 \uc120\ub7c9\ud55c \ud48d\uc18d \uae30\ud0c0 \uc0ac\ud68c\uc9c8\uc11c\uc5d0 \ubc18\ud558\uba74 \ubb34\ud6a8\uac00 \ub420 \uc218 \uc788\ub2e4.","\uc0ac\ud68c\uc801 \ud0c0\ub2f9\uc131 \ud310\ub2e8\uc740 \ubc95\ub960\ud589\uc704 \uc131\ub9bd \uc774\ud6c4\uc758 \uc0ac\uc815\ub9cc\uc744 \uae30\uc900\uc73c\ub85c \ud55c\ub2e4.","\uc0ac\ud68c\uc9c8\uc11c \uc704\ubc18 \uc5ec\ubd80\ub294 \ub2f9\uc0ac\uc790\uc758 \uc8fc\uad00\uc801 \ub3d9\uae30\uc640 \ubb34\uad00\ud558\uac8c \uc624\ub85c\uc9c0 \uae09\ubd80\uc758 \uac1d\uad00\uc801 \ub0b4\uc6a9\ub9cc\uc73c\ub85c \ud310\ub2e8\ud55c\ub2e4."],t.s)
B.aFu=s(["\uac1c\ubcc4 \uac15\ud589\uaddc\uc815\uc5d0 \uc800\ucd09\ub418\uc9c0 \uc54a\ub354\ub77c\ub3c4 \uadf8 \ub0b4\uc6a9\uc774\ub098 \uc870\uac74, \ub3d9\uae30 \ub4f1\uc774 \uc120\ub7c9\ud55c \ud48d\uc18d \uae30\ud0c0 \uc0ac\ud68c\uc9c8\uc11c\uc5d0 \ubc18\ud558\uba74 \ubbfc\ubc95 \uc81c103\uc870\uc5d0 \uc758\ud574 \ubb34\ud6a8\uac00 \ub420 \uc218 \uc788\ub2e4"],t.s)
B.anO=s(["\uc0ac\ud68c\uc801 \ud0c0\ub2f9\uc131","\uc81c103\uc870"],t.s)
B.by5=new A.a("gen_cl_juridicalact_28","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c",null,"\ubc95\ub960\ud589\uc704\uc758 \ubaa9\uc801\uc758 \uc0ac\ud68c\uc801 \ud0c0\ub2f9\uc131\uc5d0 \uad00\ud55c \ud310\ub840\uc758 \ud0dc\ub3c4\ub85c \uc633\uc740 \uac83\uc740?",B.a1P,1,"\ubc95\ub960\ud589\uc704\uac00 \uac1c\ubcc4 \uac15\ud589\uaddc\uc815\uc5d0 \uc800\ucd09\ub418\uc9c0 \uc54a\ub354\ub77c\ub3c4 \uadf8 \ub0b4\uc6a9\uc774\ub098 \uc870\uac74, \ub3d9\uae30 \ub4f1\uc774 \uc120\ub7c9\ud55c \ud48d\uc18d \uae30\ud0c0 \uc0ac\ud68c\uc9c8\uc11c\uc5d0 \ubc18\ud558\uba74 \ubbfc\ubc95 \uc81c103\uc870\uc5d0 \uc758\ud574 \ubb34\ud6a8\uac00 \ub420 \uc218 \uc788\ub2e4\ub294 \uac83\uc774 \ud310\ub840\uc758 \ud0dc\ub3c4\uc774\ub2e4. \ud310\ub2e8\uc740 \ubc95\ub960\ud589\uc704 \uc131\ub9bd \ub2f9\uc2dc\ub97c \uae30\uc900\uc73c\ub85c \ud558\uba70 \ub3d9\uae30\ub3c4 \uace0\ub824\ub41c\ub2e4.",B.aFu,B.anO,null)
B.R_=s(["\ud45c\uc2dc\ud589\uc704\uc758 \uac1d\uad00\uc801 \uc758\ubbf8\ub97c \uc0c1\ub300\ubc29\uc758 \uc2dc\uac01\uc5d0\uc11c \uaddc\ubc94\uc801\uc73c\ub85c \ud655\uc815\ud558\ub294 \ud574\uc11d\ubc29\ubc95\uc774\ub2e4.","\ub2f9\uc0ac\uc790 \uc30d\ubc29\uc774 \ud45c\uc2dc\ud589\uc704\uc758 \uc758\ubbf8\uc640 \ub2e4\ub974\uac8c \uc77c\uce58\ud558\uc5ec \uc774\ud574\ud55c \uacbd\uc6b0, \uadf8 \uc77c\uce58\ud558\ub294 \uc758\uc0ac\ub300\ub85c \ud6a8\ub825\uc744 \uc778\uc815\ud558\ub294 \ud574\uc11d\ubc29\ubc95\uc774\ub2e4.","\ubc95\ub960\ud589\uc704\uc5d0 \ud760\uacb0\uc774 \uc788\ub294 \uacbd\uc6b0 \ub2f9\uc0ac\uc790\uc758 \uac00\uc815\uc801 \uc758\uc0ac\ub97c \ud0d0\uad6c\ud558\uc5ec \ubcf4\ucda9\ud558\ub294 \ud574\uc11d\ubc29\ubc95\uc774\ub2e4.","\ud45c\uc2dc\ud589\uc704\uc640 \ub2e4\ub978 \ub0b4\uc2ec\uc758 \ud6a8\uacfc\uc758\uc0ac\ub97c \uc5b8\uc81c\ub098 \uc6b0\uc120\uc2dc\ucf1c \ubc95\ub960\ud6a8\uacfc\ub97c \uacb0\uc815\ud558\ub294 \ud574\uc11d\ubc29\ubc95\uc774\ub2e4."],t.s)
B.avH=s(["\ub2f9\uc0ac\uc790 \uc30d\ubc29\uc774 \uc2e4\uc81c\ub85c \uc77c\uce58\ud558\uc5ec \uc774\ud574\ud55c \uc758\uc0ac\uac00 \uc788\uc73c\uba74 \uadf8 \uc77c\uce58\ud558\ub294 \uc758\uc0ac\ub300\ub85c \ubc95\ub960\ud589\uc704\uc758 \ud6a8\ub825\uc744 \uc778\uc815\ud558\ub294 \ud574\uc11d\ubc29\ubc95"],t.s)
B.avG=s(["\uc790\uc5f0\uc801 \ud574\uc11d","\uc624\ud45c\uc2dc\ubb34\ud574"],t.s)
B.bEd=new A.a("gen_cl_juridicalact_29","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c",null,"\ubc95\ub960\ud589\uc704\uc758 \ud574\uc11d \ubc29\ubc95 \uc911 \uc790\uc5f0\uc801 \ud574\uc11d\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.R_,1,"\uc790\uc5f0\uc801 \ud574\uc11d\uc740 \ud45c\uc2dc\uc758 \ubb38\uc5b8\uc801 \uc758\ubbf8\uc5d0 \uad6c\uc560\ub418\uc9c0 \uc54a\uace0 \ub2f9\uc0ac\uc790 \uc30d\ubc29\uc774 \uc2e4\uc81c\ub85c \uc77c\uce58\ud558\uc5ec \uc774\ud574\ud55c \uc758\uc0ac\uac00 \uc788\uc73c\uba74 \uadf8 \uc77c\uce58\ud558\ub294 \uc758\uc0ac\ub300\ub85c \ubc95\ub960\ud589\uc704\uc758 \ud6a8\ub825\uc744 \uc778\uc815\ud558\ub294 \ud574\uc11d\ubc29\ubc95\uc73c\ub85c, \uc774\ub978\ubc14 \uc624\ud45c\uc2dc\ubb34\ud574(\u8aa4\u8868\u793a\u7121\u5bb3)\uc758 \uc6d0\uce59\uc774 \uc801\uc6a9\ub41c\ub2e4.",B.avH,B.avG,null)
B.bb7=s(["\ub2f9\uc0ac\uc790\uc758 \ub0b4\uc2ec\uc758 \uc758\uc0ac\uac00 \ubb34\uc5c7\uc774\ub4e0 \uad00\uacc4\uc5c6\uc774 \ud45c\uc2dc\ud589\uc704\uac00 \uac16\ub294 \uac1d\uad00\uc801 \uc758\ubbf8\ub97c \uc0c1\ub300\ubc29\uc758 \uc2dc\uac01\uc5d0\uc11c \ud569\ub9ac\uc801\uc73c\ub85c \ud574\uc11d\ud558\ub294 \ubc29\ubc95\uc774\ub2e4.","\uacc4\uc57d \uc131\ub9bd \uc774\ud6c4 \ubc1c\uc0dd\ud55c \uc0ac\uc815\ubcc0\uacbd\ub9cc\uc744 \uae30\ucd08\ub85c \uacc4\uc57d \ub0b4\uc6a9\uc744 \ud615\uc131\ud558\ub294 \ud574\uc11d\ubc29\ubc95\uc774\ub2e4.","\ubc95\ub960\ud589\uc704\uc5d0 \ud2c8\uc774 \uc788\ub294 \uacbd\uc6b0 \uc2e0\uc758\uce59\uacfc \uac70\ub798\uad00\ud589\uc5d0 \ube44\ucd94\uc5b4 \ub2f9\uc0ac\uc790\uc758 \uac00\uc815\uc801 \uc758\uc0ac\ub97c \ubcf4\ucda9\ud558\ub294 \ud574\uc11d\ubc29\ubc95\uc774\ub2e4.","\ub2f9\uc0ac\uc790 \uc30d\ubc29\uc774 \ud45c\uc2dc\uc640 \ub2e4\ub974\uac8c \uc77c\uce58\ud558\uc5ec \uc774\ud574\ud55c \uc758\uc0ac\ub97c \uadf8\ub300\ub85c \uc778\uc815\ud558\ub294 \ud574\uc11d\ubc29\ubc95\uc774\ub2e4."],t.s)
B.Yb=s(["\ud45c\uc2dc\ud589\uc704\uac00 \uac16\ub294 \uac1d\uad00\uc801 \uc758\ubbf8\ub97c, \uc0c1\ub300\ubc29\uc774 \ud569\ub9ac\uc801\uc73c\ub85c \uc774\ud574\ud588\uc744 \uc2dc\uac01\uc5d0\uc11c \ud655\uc815\ud558\ub294 \ud574\uc11d\ubc29\ubc95"],t.s)
B.b9a=s(["\uaddc\ubc94\uc801 \ud574\uc11d","\uc0c1\ub300\ubc29\uc758 \uc2e0\ub8b0 \ubcf4\ud638"],t.s)
B.bBM=new A.a("gen_cl_juridicalact_30","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c",null,"\ubc95\ub960\ud589\uc704\uc758 \ud574\uc11d \ubc29\ubc95 \uc911 \uaddc\ubc94\uc801 \ud574\uc11d\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.bb7,0,"\uaddc\ubc94\uc801 \ud574\uc11d\uc740 \ub2f9\uc0ac\uc790 \uc30d\ubc29\uc758 \uc758\uc0ac\uac00 \uc77c\uce58\ud558\uc9c0 \uc54a\uc744 \ub54c \ud45c\uc2dc\ud589\uc704\uac00 \uac16\ub294 \uac1d\uad00\uc801 \uc758\ubbf8\ub97c, \uc0c1\ub300\ubc29\uc774 \ud569\ub9ac\uc801\uc73c\ub85c \uc774\ud574\ud588\uc744 \uc2dc\uac01\uc5d0\uc11c \ud655\uc815\ud558\ub294 \ud574\uc11d\ubc29\ubc95\uc73c\ub85c, \ud45c\uc758\uc790\uc758 \uc9c4\uc758\ubcf4\ub2e4 \uc0c1\ub300\ubc29\uc758 \uc2e0\ub8b0 \ubcf4\ud638\uac00 \uc911\uc2dc\ub41c\ub2e4.",B.Yb,B.b9a,null)
B.af1=s(["\ubcf4\ucda9\uc801 \ud574\uc11d\uc740 \ubc95\ub960\ud589\uc704\uc5d0 \ud2c8\uc774 \uc788\uc5b4 \ub2f9\uc0ac\uc790\uac00 \uc815\ud558\uc9c0 \uc54a\uc740 \uc0ac\ud56d\uc744 \ubcf4\ucda9\ud558\ub294 \ud574\uc11d\ubc29\ubc95\uc774\ub2e4.","\ubcf4\ucda9\uc801 \ud574\uc11d\uc740 \uc790\uc5f0\uc801 \ud574\uc11d \ubc0f \uaddc\ubc94\uc801 \ud574\uc11d\uc744 \ud1b5\ud574 \ubc95\ub960\ud589\uc704\uc758 \ub0b4\uc6a9\uc774 \ud655\uc815\ub41c \uc774\ud6c4\uc5d0 \ube44\ub85c\uc18c \ubb38\uc81c\ub41c\ub2e4.","\ubcf4\ucda9\uc801 \ud574\uc11d\uc5d0\uc11c\ub294 \ub2f9\uc0ac\uc790\uc758 \uc2e4\uc81c \uc758\uc0ac\ub97c \ud655\uc778\ud560 \uc218 \uc5c6\ub354\ub77c\ub3c4 \uac00\uc815\uc801 \uc758\uc0ac\ub97c \uc784\uc758\ub85c \ubc30\uc81c\ud558\uace0 \ubc95\uc6d0\uc774 \uc0c8\ub85c\uc6b4 \uacc4\uc57d \ub0b4\uc6a9\uc744 \ucc3d\uc124\ud560 \uc218 \uc788\ub2e4.","\ubcf4\ucda9\uc801 \ud574\uc11d\uc740 \uc2e0\uc758\uc131\uc2e4\uc758 \uc6d0\uce59, \uad00\uc2b5, \uc784\uc758\uaddc\uc815 \ub4f1\uc744 \uae30\uc900\uc73c\ub85c \ub2f9\uc0ac\uc790\uc758 \uac00\uc815\uc801 \uc758\uc0ac\ub97c \ud0d0\uad6c\ud55c\ub2e4."],t.s)
B.ahK=s(["\ub2f9\uc0ac\uc790\ub77c\uba74 \uadf8\ub7ec\ud55c \uc0ac\uc815 \uc544\ub798\uc5d0\uc11c \uc815\ud558\uc600\uc744 \uac00\uc815\uc801 \uc758\uc0ac\ub97c \ud0d0\uad6c\ud558\uc5ec \ud760\uacb0\uc744 \uba54\uc6b0\ub294 \uac83"],t.s)
B.b5G=s(["\ubcf4\ucda9\uc801 \ud574\uc11d","\uac00\uc815\uc801 \uc758\uc0ac"],t.s)
B.bOc=new A.a("gen_cl_juridicalact_31","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c",null,"\ubc95\ub960\ud589\uc704 \ud574\uc11d \ubc29\ubc95 \uc911 \ubcf4\ucda9\uc801 \ud574\uc11d\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.af1,2,"\ubcf4\ucda9\uc801 \ud574\uc11d\uc740 \ubc95\ub960\ud589\uc704\uc5d0 \ud2c8\uc774 \uc788\ub294 \uacbd\uc6b0 \uc2e0\uc758\uce59, \uad00\uc2b5, \uc784\uc758\uaddc\uc815 \ub4f1\uc744 \uae30\uc900\uc73c\ub85c \ub2f9\uc0ac\uc790\ub77c\uba74 \uadf8\ub7ec\ud55c \uc0ac\uc815 \uc544\ub798\uc5d0\uc11c \uc815\ud558\uc600\uc744 \uac00\uc815\uc801 \uc758\uc0ac\ub97c \ud0d0\uad6c\ud558\uc5ec \ud760\uacb0\uc744 \uba54\uc6b0\ub294 \uac83\uc774\uc9c0, \ubc95\uc6d0\uc774 \ub2f9\uc0ac\uc790\uc758 \uac00\uc815\uc801 \uc758\uc0ac\uc640 \ubb34\uad00\ud558\uac8c \uc784\uc758\ub85c \uc0c8\ub85c\uc6b4 \uacc4\uc57d \ub0b4\uc6a9\uc744 \ucc3d\uc124\ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4.",B.ahK,B.b5G,null)
B.a9Q=s(["\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\ub294 \ub2f9\uc0ac\uc790\uac00 \uadf8 \ubb34\ud6a8\uc784\uc744 \uc54c\uace0 \ucd94\uc778\ud558\ub354\ub77c\ub3c4 \uc6d0\uce59\uc801\uc73c\ub85c \uc18c\uae09\ud558\uc5ec \uc720\ud6a8\ub85c \ub418\uc9c0 \uc54a\ub294\ub2e4.","\ubb34\ud6a8\ud589\uc704\ub97c \ucd94\uc778\ud55c \uacbd\uc6b0 \ub2f9\uc0ac\uc790\ub294 \uadf8 \ucd94\uc778 \uc2dc\uc810\ubd80\ud130 \uc0c8\ub85c\uc6b4 \ubc95\ub960\ud589\uc704\ub97c \ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4.","\uac15\ud589\ubc95\uaddc \uc704\ubc18\uc774\ub098 \ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704\uc640 \uac19\uc774 \uc808\ub300\uc801 \ubb34\ud6a8\uc0ac\uc720\uac00 \uc788\ub294 \uacbd\uc6b0\uc5d0\ub3c4 \ubb34\ud6a8\uc784\uc744 \uc54c\uace0 \ucd94\uc778\ud558\uba74 \uc5b8\uc81c\ub098 \uc18c\uae09\ud558\uc5ec \uc720\ud6a8\ub85c \ub41c\ub2e4.","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\uc758 \ucd94\uc778\uc740 \ubb34\ud6a8\uc6d0\uc778\uc774 \uc18c\uba78\ub41c \ud6c4\uc5d0 \ud558\uc5ec\uc57c \uadf8 \ud6a8\ub825\uc774 \uc778\uc815\ub420 \uc218 \uc788\ub2e4."],t.s)
B.a1G=s(["\uac15\ud589\ubc95\uaddc \uc704\ubc18\uc774\ub098 \ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704\uc640 \uac19\uc740 \uc808\ub300\uc801 \ubb34\ud6a8\uc0ac\uc720\uac00 \uc788\ub294 \uacbd\uc6b0\uc5d0\ub294 \ub2f9\uc0ac\uc790\uac00 \ubb34\ud6a8\uc784\uc744 \uc54c\uace0 \ucd94\uc778\ud558\ub354\ub77c\ub3c4 \uc720\ud6a8\ub85c \ub420 \uc218 \uc5c6\ub2e4"],t.s)
B.afA=s(["\uc81c139\uc870","\ubb34\ud6a8\ud589\uc704\uc758 \ucd94\uc778","\uc18c\uae09\ud6a8 \ubd80\uc815"],t.s)
B.bFE=new A.a("gen_cl_juridicalact_32","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c",null,"\ubbfc\ubc95 \uc81c139\uc870 \ubb34\ud6a8\ud589\uc704\uc758 \ucd94\uc778\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.a9Q,2,"\ubbfc\ubc95 \uc81c139\uc870\uc5d0 \ub530\ub77c \ubb34\ud6a8\ud589\uc704\ub97c \ucd94\uc778\ud558\ub354\ub77c\ub3c4 \uc6d0\uce59\uc801\uc73c\ub85c \uc18c\uae09\ud6a8\ub294 \uc778\uc815\ub418\uc9c0 \uc54a\uace0 \uadf8\ub54c\ubd80\ud130 \uc0c8\ub85c\uc6b4 \ubc95\ub960\ud589\uc704\ub97c \ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4. \ub2e4\ub9cc \uac15\ud589\ubc95\uaddc \uc704\ubc18\uc774\ub098 \ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704\uc640 \uac19\uc740 \uc808\ub300\uc801 \ubb34\ud6a8\uc0ac\uc720\uac00 \uc788\ub294 \uacbd\uc6b0\uc5d0\ub294 \ub2f9\uc0ac\uc790\uac00 \ubb34\ud6a8\uc784\uc744 \uc54c\uace0 \ucd94\uc778\ud558\ub354\ub77c\ub3c4 \uc720\ud6a8\ub85c \ub420 \uc218 \uc5c6\ub2e4\ub294 \uac83\uc774 \ud310\ub840\uc758 \ud0dc\ub3c4\uc774\ub2e4.",B.a1G,B.afA,null)
B.ag_=s(["\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\uac00 \ub2e4\ub978 \ubc95\ub960\ud589\uc704\uc758 \uc694\uac74\uc744 \uad6c\ube44\ud558\uace0 \ub2f9\uc0ac\uc790\uac00 \uadf8 \ubb34\ud6a8\ub97c \uc54c\uc558\ub354\ub77c\uba74 \ub2e4\ub978 \ubc95\ub960\ud589\uc704\ub97c \ud558\ub294 \uac83\uc744 \uc758\uc695\ud558\uc600\uc744 \uac83\uc73c\ub85c \uc778\uc815\ub418\ub294 \ub54c\uc5d0\ub294 \ub2e4\ub978 \ubc95\ub960\ud589\uc704\ub85c\uc11c \ud6a8\ub825\uc744 \uac00\uc9c4\ub2e4.","\ubb34\ud6a8\ud589\uc704\uc758 \uc804\ud658\uc740 \ub2f9\uc0ac\uc790\uc758 \uac00\uc815\uc801 \uc758\uc0ac\uc640 \uad00\uacc4\uc5c6\uc774 \ubc95\ub960\uc758 \uaddc\uc815\uc5d0 \uc758\ud574\uc11c\ub9cc \uc778\uc815\ub41c\ub2e4.","\ubb34\ud6a8\ud589\uc704\uc758 \uc804\ud658\uc774 \uc778\uc815\ub418\uba74 \uc6d0\ub798\uc758 \ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704 \uadf8\ub300\ub85c \uc18c\uae09\ud558\uc5ec \uc720\ud6a8\ub85c \ub41c\ub2e4.","\ubb34\ud6a8\ud589\uc704\uc758 \uc804\ud658\uc740 \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\uc5d0 \ud55c\ud558\uc5ec \uc801\uc6a9\ub41c\ub2e4."],t.s)
B.baF=s(["\ub2f9\uc0ac\uc790\uac00 \ubb34\ud6a8\ub97c \uc54c\uc558\ub2e4\uba74 \ub2e4\ub978 \ubc95\ub960\ud589\uc704\ub97c \ud558\ub294 \uac83\uc744 \uc758\uc695\ud558\uc600\uc73c\ub9ac\ub77c\uace0 \uc778\uc815\ub420 \ub54c\uc5d0\ub294 \uadf8 \ub2e4\ub978 \ubc95\ub960\ud589\uc704\ub85c\uc11c \ud6a8\ub825\uc744 \uac00\uc9c4\ub2e4"],t.s)
B.b9L=s(["\uc81c138\uc870","\ubb34\ud6a8\ud589\uc704\uc758 \uc804\ud658"],t.s)
B.bJO=new A.a("gen_cl_juridicalact_33","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c",null,"\ubbfc\ubc95 \uc81c138\uc870 \ubb34\ud6a8\ud589\uc704\uc758 \uc804\ud658\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.ag_,0,"\ubbfc\ubc95 \uc81c138\uc870\ub294 \ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\uac00 \ub2e4\ub978 \ubc95\ub960\ud589\uc704\uc758 \uc694\uac74\uc744 \uad6c\ube44\ud558\uace0, \ub2f9\uc0ac\uc790\uac00 \ubb34\ud6a8\ub97c \uc54c\uc558\ub2e4\uba74 \ub2e4\ub978 \ubc95\ub960\ud589\uc704\ub97c \ud558\ub294 \uac83\uc744 \uc758\uc695\ud558\uc600\uc73c\ub9ac\ub77c\uace0 \uc778\uc815\ub420 \ub54c\uc5d0\ub294 \uadf8 \ub2e4\ub978 \ubc95\ub960\ud589\uc704\ub85c\uc11c \ud6a8\ub825\uc744 \uac00\uc9c4\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ub300\ud45c\uc801 \uc608\ub85c \ube44\ubc00\uc99d\uc11c \ubc29\uc2dd\uc5d0 \ud760\uacb0\uc774 \uc788\ub294 \uc720\uc5b8\uc774 \uc790\ud544\uc99d\uc11c \uc694\uac74\uc744 \uac16\ucd98 \uacbd\uc6b0\ub97c \ub4e4 \uc218 \uc788\ub2e4.",B.baF,B.b9L,null)
B.Ws=s(["\uc81c\ud55c\ub2a5\ub825\uc790","\ucc29\uc624\ub85c \uc758\uc0ac\ud45c\uc2dc\ub97c \ud55c \uc790","\uc0ac\uae30 \ub610\ub294 \uac15\ubc15\uc5d0 \uc758\ud558\uc5ec \uc758\uc0ac\ud45c\uc2dc\ub97c \ud55c \uc790","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\ub85c \uc778\ud574 \ub2e8\uc21c\ud788 \ubc18\uc0ac\uc801 \uc774\uc775\uc744 \uc5bb\ub294 \uc81c3\uc790"],t.s)
B.bak=s(["\ub2e8\uc21c\ud788 \ucde8\uc18c\ub85c \uc778\ud574 \ubc18\uc0ac\uc801 \uc774\uc775\uc744 \uc5bb\ub294 \ub370 \ubd88\uacfc\ud55c \uc81c3\uc790\ub294 \ucde8\uc18c\uad8c\uc790\uc5d0 \ud3ec\ud568\ub418\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.Tz=s(["\uc81c140\uc870","\ucde8\uc18c\uad8c\uc790"],t.s)
B.bNG=new A.a("gen_cl_juridicalact_34","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c",null,"\ubbfc\ubc95 \uc81c140\uc870\uc5d0\uc11c \uc815\ud55c \ucde8\uc18c\uad8c\uc790\uc5d0 \ud574\ub2f9\ud558\uc9c0 \uc54a\ub294 \uc790\ub294?",B.Ws,3,"\ubbfc\ubc95 \uc81c140\uc870\ub294 \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\ub294 \uc81c\ud55c\ub2a5\ub825\uc790, \ucc29\uc624\ub85c \uc778\ud558\uac70\ub098 \uc0ac\uae30\xb7\uac15\ubc15\uc5d0 \uc758\ud558\uc5ec \uc758\uc0ac\ud45c\uc2dc\ub97c \ud55c \uc790, \uadf8 \ub300\ub9ac\uc778 \ub610\ub294 \uc2b9\uacc4\uc778\ub9cc\uc774 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ub2e8\uc21c\ud788 \ucde8\uc18c\ub85c \uc778\ud574 \ubc18\uc0ac\uc801 \uc774\uc775\uc744 \uc5bb\ub294 \ub370 \ubd88\uacfc\ud55c \uc81c3\uc790\ub294 \ucde8\uc18c\uad8c\uc790\uc5d0 \ud3ec\ud568\ub418\uc9c0 \uc54a\ub294\ub2e4.",B.bak,B.Tz,null)
B.aaz=s(["\ucde8\uc18c\ub41c \ubc95\ub960\ud589\uc704\ub294 \ucc98\uc74c\ubd80\ud130 \ubb34\ud6a8\uc778 \uac83\uc73c\ub85c \ubcf8\ub2e4.","\ucde8\uc18c\ub41c \ubc95\ub960\ud589\uc704\ub294 \ucde8\uc18c\ud55c \ub54c\ubd80\ud130 \uc7a5\ub798\ub97c \ud5a5\ud558\uc5ec \ud6a8\ub825\uc744 \uc783\ub294\ub2e4.","\ucde8\uc18c\ub41c \ubc95\ub960\ud589\uc704\ub294 \ucde8\uc18c\uad8c\uc790\uac00 \ub2e4\uc2dc \ucd94\uc778\ud558\uae30 \uc804\uae4c\uc9c0\ub294 \uc720\ub3d9\uc801\uc73c\ub85c \uc720\ud6a8\ud558\ub2e4.","\uc81c\ud55c\ub2a5\ub825\uc790\ub294 \ucde8\uc18c\ub85c \uc778\ud558\uc5ec \ubc1b\uc740 \uae09\ubd80 \uc804\ubd80\ub97c \ubc18\ud658\ud560 \uc758\ubb34\ub97c \ubd80\ub2f4\ud558\uba70 \ud604\uc874\uc774\uc775\uc73c\ub85c \uadf8 \ubc94\uc704\uac00 \ucd95\uc18c\ub418\uc9c0 \uc54a\ub294\ub2e4."],t.s)
B.aYk=s(["\ucde8\uc18c\ub41c \ubc95\ub960\ud589\uc704\ub294 \ucc98\uc74c\ubd80\ud130 \ubb34\ud6a8\uc778 \uac83\uc73c\ub85c \ubcf4\uc544 \uc18c\uae09\ud6a8\uac00 \uc778\uc815\ub41c\ub2e4"],t.s)
B.bc5=s(["\uc81c141\uc870","\ucde8\uc18c\uc758 \uc18c\uae09\ud6a8","\ud604\uc874\uc774\uc775"],t.s)
B.bCn=new A.a("gen_cl_juridicalact_35","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c",null,"\ubbfc\ubc95 \uc81c141\uc870 \ucde8\uc18c\uc758 \ud6a8\uacfc\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aaz,0,"\ubbfc\ubc95 \uc81c141\uc870 \ubcf8\ubb38\uc5d0 \ub530\ub77c \ucde8\uc18c\ub41c \ubc95\ub960\ud589\uc704\ub294 \ucc98\uc74c\ubd80\ud130 \ubb34\ud6a8\uc778 \uac83\uc73c\ub85c \ubcf4\uc544 \uc18c\uae09\ud6a8\uac00 \uc778\uc815\ub41c\ub2e4. \ub2e4\ub9cc \uac19\uc740 \uc870 \ub2e8\uc11c\uc5d0 \uc758\ud574 \uc81c\ud55c\ub2a5\ub825\uc790\ub294 \uadf8 \ud589\uc704\ub85c \uc778\ud558\uc5ec \ubc1b\uc740 \uc774\uc775\uc774 \ud604\uc874\ud558\ub294 \ud55c\ub3c4\uc5d0\uc11c \uc0c1\ud658\ud560 \ucc45\uc784\uc774 \uc788\ub2e4.",B.aYk,B.bc5,null)
B.a3d=s(["\ubc95\uc815\ucd94\uc778\uc774 \uc131\ub9bd\ud558\uae30 \uc704\ud574\uc11c\ub294 \ucde8\uc18c\uc758 \uc6d0\uc778\uc774 \uc885\ub8cc\ub41c \ud6c4\uc5d0 \uc77c\uc815\ud55c \uc0ac\uc720\uac00 \uc788\uc5b4\uc57c \ud55c\ub2e4.","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\uc5d0 \uad00\ud558\uc5ec \uc804\ubd80\ub098 \uc77c\ubd80\uc758 \uc774\ud589\uc774 \uc788\uc73c\uba74 \ubc95\uc815\ucd94\uc778 \uc0ac\uc720\uac00 \ub41c\ub2e4.","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ucc44\uad8c\uc5d0 \uad00\ud558\uc5ec \ub2f4\ubcf4\ub97c \uc81c\uacf5\ud558\uac70\ub098 \uc81c\uacf5\ubc1b\uc740 \uacbd\uc6b0\ub3c4 \ubc95\uc815\ucd94\uc778 \uc0ac\uc720\uc5d0 \ud574\ub2f9\ud55c\ub2e4.","\ubc95\uc815\ucd94\uc778\uc774 \uc778\uc815\ub418\ub294 \uacbd\uc6b0\uc5d0\ub3c4 \ucde8\uc18c\uad8c\uc790\uac00 \uc774\uc758\ub97c \ubcf4\ub958\ud558\uc9c0 \uc54a\uc558\ub2e4\uba74 \ucde8\uc18c\uad8c\uc744 \uc5ec\uc804\ud788 \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4."],t.s)
B.aEi=s(["\ubc95\uc815\ucd94\uc778\uc774 \uc131\ub9bd\ud558\uba74 \ucde8\uc18c\uad8c\uc740 \uc18c\uba78\ud558\uc5ec \ub354 \uc774\uc0c1 \ucde8\uc18c\uad8c\uc744 \ud589\uc0ac\ud560 \uc218 \uc5c6\ub2e4"],t.s)
B.bi_=s(["\uc81c145\uc870","\ubc95\uc815\ucd94\uc778"],t.s)
B.bpo=new A.a("gen_cl_juridicalact_36","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c",null,"\ubbfc\ubc95 \uc81c145\uc870 \ubc95\uc815\ucd94\uc778\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.a3d,3,"\ubbfc\ubc95 \uc81c145\uc870\ub294 \ucde8\uc18c\uc758 \uc6d0\uc778\uc774 \uc885\ub8cc\ub41c \ud6c4 \uc774\ud589, \uc774\ud589\uccad\uad6c, \uacbd\uac1c, \ub2f4\ubcf4\uc81c\uacf5, \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ud589\uc704\ub85c \ucde8\ub4dd\ud55c \uad8c\ub9ac\uc758 \uc804\ubd80\ub098 \uc77c\ubd80\uc758 \uc591\ub3c4, \uac15\uc81c\uc9d1\ud589 \ub4f1\uc758 \uc0ac\uc720\uac00 \uc788\uc73c\uba74 \uc774\uc758\ub97c \ubcf4\ub958\ud558\uc9c0 \uc544\ub2c8\ud55c \uc774\uc0c1 \ucd94\uc778\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ub530\ub77c\uc11c \ubc95\uc815\ucd94\uc778\uc774 \uc131\ub9bd\ud558\uba74 \ucde8\uc18c\uad8c\uc740 \uc18c\uba78\ud558\uc5ec \ub354 \uc774\uc0c1 \ucde8\uc18c\uad8c\uc744 \ud589\uc0ac\ud560 \uc218 \uc5c6\ub2e4.",B.aEi,B.bi_,null)
B.bez=s(["\ucde8\uc18c\uad8c\uc740 \ucd94\uc778\ud560 \uc218 \uc788\ub294 \ub0a0\ub85c\ubd80\ud130 3\ub144 \ub0b4, \ubc95\ub960\ud589\uc704\ub97c \ud55c \ub0a0\ub85c\ubd80\ud130 10\ub144 \ub0b4\uc5d0 \ud589\uc0ac\ud558\uc5ec\uc57c \ud55c\ub2e4.","\ucde8\uc18c\uad8c\uc740 \uc18c\uba78\uc2dc\ud6a8\uc758 \ub300\uc0c1\uc774 \ub420 \ubfd0 \uc81c\ucc99\uae30\uac04\uc758 \uc801\uc6a9\uc740 \ubc1b\uc9c0 \uc54a\ub294\ub2e4.","\ucde8\uc18c\uad8c\uc758 \ud589\uc0ac\uae30\uac04\uc740 \ub2f9\uc0ac\uc790\uc758 \ud569\uc758\ub85c \uc5b8\uc81c\ub4e0\uc9c0 \uc5f0\uc7a5\ud560 \uc218 \uc788\ub2e4.","\ucde8\uc18c\uad8c\uc740 \ubc95\ub960\ud589\uc704\ub97c \ud55c \ub0a0\ub85c\ubd80\ud130 3\ub144, \ucd94\uc778\ud560 \uc218 \uc788\ub294 \ub0a0\ub85c\ubd80\ud130 10\ub144 \ub0b4\uc5d0 \ud589\uc0ac\ud558\uba74 \ub41c\ub2e4."],t.s)
B.aSx=s(["\ucde8\uc18c\uad8c\uc740 \ucd94\uc778\ud560 \uc218 \uc788\ub294 \ub0a0\ub85c\ubd80\ud130 3\ub144 \ub0b4\uc5d0, \ubc95\ub960\ud589\uc704\ub97c \ud55c \ub0a0\ub85c\ubd80\ud130 10\ub144 \ub0b4\uc5d0 \ud589\uc0ac\ud558\uc5ec\uc57c \ud55c\ub2e4"],t.s)
B.a0p=s(["\uc81c146\uc870","\uc81c\ucc99\uae30\uac04"],t.s)
B.bO5=new A.a("gen_cl_juridicalact_37","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c",null,"\ubbfc\ubc95 \uc81c146\uc870 \ucde8\uc18c\uad8c\uc758 \uc81c\ucc99\uae30\uac04\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.bez,0,"\ubbfc\ubc95 \uc81c146\uc870\ub294 \ucde8\uc18c\uad8c\uc740 \ucd94\uc778\ud560 \uc218 \uc788\ub294 \ub0a0\ub85c\ubd80\ud130 3\ub144 \ub0b4\uc5d0, \ubc95\ub960\ud589\uc704\ub97c \ud55c \ub0a0\ub85c\ubd80\ud130 10\ub144 \ub0b4\uc5d0 \ud589\uc0ac\ud558\uc5ec\uc57c \ud55c\ub2e4\uace0 \uaddc\uc815\ud558\uba70, \uc774\ub294 \uc18c\uba78\uc2dc\ud6a8\uac00 \uc544\ub2cc \uc81c\ucc99\uae30\uac04\uc73c\ub85c \uc774\ud574\ub41c\ub2e4. \ub450 \uae30\uac04 \uc911 \uc5b4\ub290 \ud558\ub098\ub77c\ub3c4 \uba3c\uc800 \ub3c4\uacfc\ud558\uba74 \ucde8\uc18c\uad8c\uc740 \uc18c\uba78\ud55c\ub2e4.",B.aSx,B.a0p,null)
B.azJ=s(["\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\ub294 \ud2b9\uc815\uc778\uc758 \uc8fc\uc7a5\uc744 \uae30\ub2e4\ub9b4 \ud544\uc694 \uc5c6\uc774 \ub204\uad6c\ub4e0\uc9c0 \uadf8 \ubb34\ud6a8\ub97c \uc8fc\uc7a5\ud560 \uc218 \uc788\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub2e4.","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\ub294 \ucde8\uc18c\uad8c\uc790\uac00 \ucde8\uc18c\uad8c\uc744 \ud589\uc0ac\ud558\uae30 \uc804\uae4c\uc9c0\ub294 \uc720\ud6a8\ud55c \ubc95\ub960\ud589\uc704\ub85c \ucde8\uae09\ub41c\ub2e4.","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\ub294 \uc2dc\uac04\uc758 \uacbd\uacfc\uc5d0 \ub530\ub77c \ud6a8\ub825\uc774 \ud655\uc815\ub418\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ubbc0\ub85c \uc81c\ucc99\uae30\uac04\uc758 \uc801\uc6a9\uc744 \ubc1b\ub294\ub2e4.","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\ub294 \ucde8\uc18c\uad8c\uc790\uc758 \ucde8\uc18c\uc758 \uc758\uc0ac\ud45c\uc2dc\uac00 \uc788\uc5b4\uc57c \ube44\ub85c\uc18c \uc18c\uae09\ud558\uc5ec \ubb34\ud6a8\ub85c \ub41c\ub2e4."],t.s)
B.bhH=s(["\ubb34\ud6a8\ub294 \ucc98\uc74c\ubd80\ud130 \ubc95\ub960\ud6a8\uacfc\uac00 \ubc1c\uc0dd\ud558\uc9c0 \uc54a\ub294 \uac83\uc73c\ub85c \ud655\uc815\ub418\uc5b4 \uc788\uc5b4 \uc2dc\uac04\uc758 \uacbd\uacfc\ub098 \uc81c\ucc99\uae30\uac04\uc758 \ubb38\uc81c\uac00 \uc0dd\uae30\uc9c0 \uc54a\ub294 \ubc18\uba74, \ucde8\uc18c\uad8c\uc740 \ubbfc\ubc95 \uc81c146\uc870\uac00 \uc815\ud558\ub294 \uc81c\ucc99\uae30\uac04\uc758 \uc801\uc6a9\uc744 \ubc1b\ub294\ub2e4"],t.s)
B.acY=s(["\ubb34\ud6a8\uc640 \ucde8\uc18c\uc758 \uad6c\ubcc4","\uc81c\ucc99\uae30\uac04"],t.s)
B.bQX=new A.a("gen_cl_juridicalact_38","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c",null,"\ubb34\ud6a8\uc640 \ucde8\uc18c\uc758 \uad6c\ubcc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.azJ,2,"\ubb34\ud6a8\ub294 \ucc98\uc74c\ubd80\ud130 \ubc95\ub960\ud6a8\uacfc\uac00 \ubc1c\uc0dd\ud558\uc9c0 \uc54a\ub294 \uac83\uc73c\ub85c \ud655\uc815\ub418\uc5b4 \uc788\uc5b4 \uc2dc\uac04\uc758 \uacbd\uacfc\ub098 \uc81c\ucc99\uae30\uac04\uc758 \ubb38\uc81c\uac00 \uc0dd\uae30\uc9c0 \uc54a\ub294 \ubc18\uba74, \ucde8\uc18c\uad8c\uc740 \ubbfc\ubc95 \uc81c146\uc870\uac00 \uc815\ud558\ub294 \uc81c\ucc99\uae30\uac04\uc758 \uc801\uc6a9\uc744 \ubc1b\ub294\ub2e4. \ucde8\uc18c\ub294 \ucde8\uc18c\uad8c\uc790\uc758 \uc758\uc0ac\ud45c\uc2dc\ub85c \ube44\ub85c\uc18c \uc18c\uae09\uc801\uc73c\ub85c \ubb34\ud6a8\uac00 \ub41c\ub2e4\ub294 \uc810\uc5d0\uc11c \ubb34\ud6a8\uc640 \uad6c\ubcc4\ub41c\ub2e4.",B.bhH,B.acY,null)
B.asd=s(["\ubc95\ub960\ud589\uc704\uc758 \uc77c\ubd80\ubd84\uc774 \ubb34\ud6a8\uc778 \ub54c\uc5d0\ub294 \ud56d\uc0c1 \uadf8 \ubc95\ub960\ud589\uc704 \uc804\ubd80\uac00 \ubb34\ud6a8\ub85c \ub41c\ub2e4.","\ubc95\ub960\ud589\uc704\uc758 \uc77c\ubd80\ubd84\uc774 \ubb34\ud6a8\uc778 \uacbd\uc6b0 \uadf8 \ub098\uba38\uc9c0 \ubd80\ubd84\uc740 \ub2f9\uc0ac\uc790\uac00 \uadf8 \ubb34\ud6a8\ubd80\ubd84\uc774 \uc5c6\ub354\ub77c\ub3c4 \ubc95\ub960\ud589\uc704\ub97c \ud558\uc600\uc744 \uac83\uc774\ub77c\uace0 \uc778\uc815\ub420 \ub54c\uc5d0\ub294 \ub098\uba38\uc9c0 \ubd80\ubd84\ub9cc\uc73c\ub85c \uc720\ud6a8\ud558\ub2e4.","\ubc95\ub960\ud589\uc704\uc758 \uc77c\ubd80\ubb34\ud6a8\ub294 \uc5b8\uc81c\ub098 \uc804\ubd80\ubb34\ud6a8\ub85c \uc758\uc81c\ub418\uba70 \uc608\uc678\ub97c \uc778\uc815\ud558\uc9c0 \uc54a\ub294\ub2e4.","\ubc95\ub960\ud589\uc704\uc758 \uc77c\ubd80\ubb34\ud6a8 \ubc95\ub9ac\ub294 \uacc4\uc57d\uc5d0\ub9cc \uc801\uc6a9\ub418\uace0 \ub2e8\ub3c5\ud589\uc704\uc5d0\ub294 \uc801\uc6a9\ub420 \uc5ec\uc9c0\uac00 \uc5c6\ub2e4."],t.s)
B.aoe=s(["\uadf8 \ubb34\ud6a8\ubd80\ubd84\uc774 \uc5c6\ub354\ub77c\ub3c4 \ubc95\ub960\ud589\uc704\ub97c \ud558\uc600\uc744 \uac83\uc774\ub77c\uace0 \uc778\uc815\ub420 \ub54c\uc5d0\ub294 \ub098\uba38\uc9c0 \ubd80\ubd84\uc740 \ubb34\ud6a8\uac00 \ub418\uc9c0 \uc544\ub2c8\ud55c\ub2e4"],t.s)
B.RK=s(["\uc81c137\uc870","\uc77c\ubd80\ubb34\ud6a8"],t.s)
B.bOh=new A.a("gen_cl_juridicalact_39","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c",null,"\ubc95\ub960\ud589\uc704\uc758 \uc77c\ubd80\ubb34\ud6a8\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.asd,1,"\ubc95\ub960\ud589\uc704\uc758 \uc77c\ubd80\ubd84\uc774 \ubb34\ud6a8\uc778 \ub54c\uc5d0\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \uc804\ubd80\ub97c \ubb34\ud6a8\ub85c \ud558\ub098, \uadf8 \ubb34\ud6a8\ubd80\ubd84\uc774 \uc5c6\ub354\ub77c\ub3c4 \ubc95\ub960\ud589\uc704\ub97c \ud558\uc600\uc744 \uac83\uc774\ub77c\uace0 \uc778\uc815\ub420 \ub54c\uc5d0\ub294 \ub098\uba38\uc9c0 \ubd80\ubd84\uc740 \ubb34\ud6a8\uac00 \ub418\uc9c0 \uc544\ub2c8\ud55c\ub2e4\ub294 \uac83\uc774 \ubbfc\ubc95 \uc81c137\uc870 \ubc0f \ud310\ub840\uc758 \ud0dc\ub3c4\uc774\ub2e4.",B.aoe,B.RK,null)
B.aEH=s(["\ud1a0\uc9c0\uac70\ub798\ud5c8\uac00\uad6c\uc5ed \ub0b4\uc758 \ud1a0\uc9c0\uc5d0 \uad00\ud55c \ub9e4\ub9e4\uacc4\uc57d\uc740 \ud5c8\uac00\ub97c \ubc1b\uae30 \uc804\uc5d0\ub294 \ucc44\uad8c\uc801 \ud6a8\ub825\ub3c4 \ubc1c\uc0dd\ud558\uc9c0 \uc54a\ub294 \uc720\ub3d9\uc801 \ubb34\ud6a8 \uc0c1\ud0dc\uc5d0 \uc788\ub2e4.","\uc720\ub3d9\uc801 \ubb34\ud6a8 \uc0c1\ud0dc\uc758 \uacc4\uc57d\uc740 \uad00\ud560\uad00\uccad\uc758 \ud5c8\uac00\ub97c \ubc1b\uc73c\uba74 \uc18c\uae09\ud558\uc5ec \uc720\ud6a8\ub85c \ud655\uc815\ub41c\ub2e4.","\uc720\ub3d9\uc801 \ubb34\ud6a8 \uc0c1\ud0dc\uc5d0\uc11c \ub2f9\uc0ac\uc790\ub294 \uc11c\ub85c \ud611\ub825\ud558\uc5ec \ud5c8\uac00\uc2e0\uccad\uc808\ucc28\uc5d0 \ud611\ub825\ud560 \uc758\ubb34\ub97c \ubd80\ub2f4\ud55c\ub2e4.","\ud5c8\uac00\ub97c \ubc30\uc81c\ud558\uac70\ub098 \uc7a0\ud0c8\ud560 \ubaa9\uc801\uc73c\ub85c \uccb4\uacb0\ub41c \uacc4\uc57d\uc740 \ucc98\uc74c\ubd80\ud130 \ud655\uc815\uc801\uc73c\ub85c \ubb34\ud6a8\uc774\ub2e4."],t.s)
B.aRi=s(["\uc644\uc804\ud55c \ubb34\ud6a8\ub294 \uc544\ub2c8\uace0 \ud5c8\uac00\ub97c \ubc1b\uc73c\uba74 \uc18c\uae09\ud558\uc5ec \uc720\ud6a8\ub85c \ub418\ub294 \uc720\ub3d9\uc801 \ubb34\ud6a8 \uc0c1\ud0dc\uc5d0 \uc788\ub2e4"],t.s)
B.arn=s(["\uc720\ub3d9\uc801 \ubb34\ud6a8","\ud1a0\uc9c0\uac70\ub798\ud5c8\uac00"],t.s)
B.bHt=new A.a("gen_cl_juridicalact_40","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c",null,"\uc720\ub3d9\uc801 \ubb34\ud6a8\uc5d0 \uad00\ud55c \ud310\ub840\uc758 \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aEH,0,"\ud310\ub840\ub294 \ud1a0\uc9c0\uac70\ub798\ud5c8\uac00\uad6c\uc5ed \ub0b4 \ud1a0\uc9c0\uc5d0 \uad00\ud55c \ub9e4\ub9e4\uacc4\uc57d\uc774 \ud5c8\uac00\ub97c \ubc1b\uae30 \uc804\uc5d0\ub294 \ubb3c\uad8c\uc801 \ud6a8\ub825\ubfd0 \uc544\ub2c8\ub77c \ucc44\uad8c\uc801 \ud6a8\ub825\ub3c4 \ubc1c\uc0dd\ud558\uc9c0 \uc54a\uc9c0\ub9cc, \uc644\uc804\ud55c \ubb34\ud6a8\ub294 \uc544\ub2c8\uace0 \ud5c8\uac00\ub97c \ubc1b\uc73c\uba74 \uc18c\uae09\ud558\uc5ec \uc720\ud6a8\ub85c \ub418\ub294 \uc720\ub3d9\uc801 \ubb34\ud6a8 \uc0c1\ud0dc\uc5d0 \uc788\ub2e4\uace0 \ubcf8\ub2e4. \uc774 \uc0c1\ud0dc\uc5d0\uc11c \ub2f9\uc0ac\uc790\ub294 \ud5c8\uac00\uc2e0\uccad\uc808\ucc28\uc5d0 \ud611\ub825\ud560 \uc758\ubb34\ub97c \ubd80\ub2f4\ud558\uba70, \ud5c8\uac00\ub97c \ubc30\uc81c\xb7\uc7a0\ud0c8\ud560 \ubaa9\uc801\uc758 \uacc4\uc57d\uc740 \ud655\uc815\uc801 \ubb34\ud6a8\uc774\ub2e4.",B.aRi,B.arn,null)
B.arO=s(["\ub300\ub9ac\uc778\uc774 \ub300\ub9ac\uad8c\uc758 \ubc94\uc704 \ub0b4\uc5d0\uc11c \ubcf8\uc778\uc744 \uc704\ud55c \uac83\uc784\uc744 \ud45c\uc2dc\ud558\uace0 \ud55c \uc758\uc0ac\ud45c\uc2dc\ub294 \uc9c1\uc811 \ubcf8\uc778\uc5d0\uac8c \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4.","\ub300\ub9ac\ub294 \ubc95\ub960\ud589\uc704\ubfd0\ub9cc \uc544\ub2c8\ub77c \uc0ac\uc2e4\ud589\uc704\uc640 \ubd88\ubc95\ud589\uc704\uc5d0\ub3c4 \ub110\ub9ac \uc778\uc815\ub41c\ub2e4.","\ub300\ub9ac\uc778\uc740 \ud589\uc704\ub2a5\ub825\uc790\uc784\uc744 \uc694\ud558\uc9c0 \uc544\ub2c8\ud55c\ub2e4.","\ub300\ub9ac\uc5d0\ub294 \ubc95\ub960\ud589\uc704\uc758 \ud6a8\uacfc\ub97c \ubcf8\uc778\uc5d0\uac8c \uadc0\uc18d\uc2dc\ud0a4\ub294 \uac83\uc744 \ubaa9\uc801\uc73c\ub85c \ud558\ub294 \ubc95\uc815\ub300\ub9ac\uc640 \uc784\uc758\ub300\ub9ac\uac00 \uc788\ub2e4."],t.s)
B.aph=s(["\ub300\ub9ac\ub294 \uc758\uc0ac\ud45c\uc2dc(\ubc95\ub960\ud589\uc704)\ub97c \ub300\uc0c1\uc73c\ub85c \ud558\ub294 \uc81c\ub3c4\uc774\uba70, \uc0ac\uc2e4\ud589\uc704\ub098 \ubd88\ubc95\ud589\uc704\uc5d0\ub294 \ub300\ub9ac\uac00 \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4(\ubbfc\ubc95 \uc81c114\uc870)"],t.s)
B.b1N=s(["\ub300\ub9ac\uc758 \uc758\uc758","\ud604\uba85\uc8fc\uc758","\ub300\ub9ac\uc778\uc758 \ud589\uc704\ub2a5\ub825"],t.s)
B.bvf=new A.a("gen_cl_agency2_1","civil_law","\ub300\ub9ac",null,"\ub300\ub9ac\uc81c\ub3c4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.arO,1,"\ub300\ub9ac\ub294 \uc758\uc0ac\ud45c\uc2dc(\ubc95\ub960\ud589\uc704)\ub97c \ub300\uc0c1\uc73c\ub85c \ud558\ub294 \uc81c\ub3c4\uc774\uba70, \uc0ac\uc2e4\ud589\uc704\ub098 \ubd88\ubc95\ud589\uc704\uc5d0\ub294 \ub300\ub9ac\uac00 \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4(\ubbfc\ubc95 \uc81c114\uc870). \ub300\ub9ac\uc778\uc758 \ud589\uc704\ub2a5\ub825\uc740 \uc694\uac74\uc774 \uc544\ub2c8\uba70(\ubbfc\ubc95 \uc81c117\uc870), \ub300\ub9ac\ub294 \ubc1c\uc0dd\uc6d0\uc778\uc5d0 \ub530\ub77c \ubc95\uc815\ub300\ub9ac\uc640 \uc784\uc758\ub300\ub9ac\ub85c \ub098\ub25c\ub2e4.",B.aph,B.b1N,null)
B.ail=s(["\ud56d\uc0c1 \ub300\ub9ac\uc778 \uc790\uc2e0\uc744 \uc704\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4.","\ud56d\uc0c1 \ubb34\ud6a8\uc774\ub2e4.","\uc0c1\ub300\ubc29\uc774 \ub300\ub9ac\uc778\uc73c\ub85c\uc11c \ud55c \uac83\uc784\uc744 \uc54c\uc558\uac70\ub098 \uc54c \uc218 \uc788\uc5c8\uc744 \ub54c\uc5d0\ub294 \ubcf8\uc778\uc5d0\uac8c \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4.","\ubcf8\uc778\uc758 \ucd94\uc778\uc774 \uc788\uc5b4\uc57c\ub9cc \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4."],t.s)
B.aJY=s(["\uc0c1\ub300\ubc29\uc774 \ub300\ub9ac\uc778\uc73c\ub85c\uc11c \ud55c \uac83\uc784\uc744 \uc54c\uc558\uac70\ub098 \uc54c \uc218 \uc788\uc5c8\uc744 \ub54c\uc5d0\ub294 \ubcf8\uc778\uc5d0\uac8c \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4"],t.s)
B.b3s=s(["\ud604\uba85\uc8fc\uc758","\uc81c115\uc870","\uc0c1\ub300\ubc29\uc758 \uc545\uc758\xb7\uacfc\uc2e4"],t.s)
B.bOE=new A.a("gen_cl_agency2_2","civil_law","\ub300\ub9ac",null,"\ub300\ub9ac\uc778\uc774 \ubcf8\uc778\uc744 \uc704\ud55c \uac83\uc784\uc744 \ud45c\uc2dc\ud558\uc9c0 \uc544\ub2c8\ud55c \uc758\uc0ac\ud45c\uc2dc\uc758 \ud6a8\ub825\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.ail,2,"\ubbfc\ubc95 \uc81c115\uc870\uc5d0 \ub530\ub974\uba74 \ub300\ub9ac\uc778\uc774 \ud604\uba85\ud558\uc9c0 \uc54a\uc740 \uc758\uc0ac\ud45c\uc2dc\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \ub300\ub9ac\uc778 \uc790\uc2e0\uc744 \uc704\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4. \ub2e4\ub9cc \uc0c1\ub300\ubc29\uc774 \ub300\ub9ac\uc778\uc73c\ub85c\uc11c \ud55c \uac83\uc784\uc744 \uc54c\uc558\uac70\ub098 \uc54c \uc218 \uc788\uc5c8\uc744 \ub54c\uc5d0\ub294 \ubcf8\uc778\uc5d0\uac8c \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4.",B.aJY,B.b3s,null)
B.aSb=s(["\ubcf4\uc874\ud589\uc704","\ub300\ub9ac\uc758 \ubaa9\uc801\uc778 \ubb3c\uac74\uc774\ub098 \uad8c\ub9ac\uc758 \uc131\uc9c8\uc744 \ubcc0\uacbd\ud558\uc9c0 \uc544\ub2c8\ud558\ub294 \ubc94\uc704\uc5d0\uc11c\uc758 \uc774\uc6a9\ud589\uc704","\ub300\ub9ac\uc758 \ubaa9\uc801\uc778 \ubb3c\uac74\uc774\ub098 \uad8c\ub9ac\uc758 \uc131\uc9c8\uc744 \ubcc0\uacbd\ud558\uc9c0 \uc544\ub2c8\ud558\ub294 \ubc94\uc704\uc5d0\uc11c\uc758 \uac1c\ub7c9\ud589\uc704","\ubb3c\uac74\uc744 \ucc98\ubd84\ud558\ub294 \ud589\uc704"],t.s)
B.aJX=s(["\uad8c\ud55c\uc744 \uc815\ud558\uc9c0 \uc544\ub2c8\ud55c \ub300\ub9ac\uc778\uc740 \ubcf4\uc874\ud589\uc704\uc640 \ub300\ub9ac\uc758 \ubaa9\uc801\ubb3c\uc758 \uc131\uc9c8\uc744 \ubcc0\uacbd\ud558\uc9c0 \uc54a\ub294 \ubc94\uc704 \ub0b4\uc5d0\uc11c\uc758 \uc774\uc6a9\xb7\uac1c\ub7c9\ud589\uc704\ub9cc\uc744 \ud560 \uc218 \uc788\ub2e4"],t.s)
B.ayl=s(["\uc81c118\uc870","\uad8c\ud55c\uc744 \uc815\ud558\uc9c0 \uc54a\uc740 \ub300\ub9ac\uc778","\ubcf4\uc874\xb7\uc774\uc6a9\xb7\uac1c\ub7c9\ud589\uc704"],t.s)
B.bPP=new A.a("gen_cl_agency2_3","civil_law","\ub300\ub9ac",null,"\ub300\ub9ac\uad8c\uc758 \ubc94\uc704\uac00 \uc815\ud558\uc5ec\uc9c0\uc9c0 \uc544\ub2c8\ud55c \uacbd\uc6b0 \ub300\ub9ac\uc778\uc774 \ud560 \uc218 \uc788\ub294 \ud589\uc704\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aSb,3,"\ubbfc\ubc95 \uc81c118\uc870\ub294 \uad8c\ud55c\uc744 \uc815\ud558\uc9c0 \uc544\ub2c8\ud55c \ub300\ub9ac\uc778\uc740 \ubcf4\uc874\ud589\uc704\uc640 \ub300\ub9ac\uc758 \ubaa9\uc801\ubb3c\uc758 \uc131\uc9c8\uc744 \ubcc0\uacbd\ud558\uc9c0 \uc54a\ub294 \ubc94\uc704 \ub0b4\uc5d0\uc11c\uc758 \uc774\uc6a9\xb7\uac1c\ub7c9\ud589\uc704\ub9cc\uc744 \ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ucc98\ubd84\ud589\uc704\ub294 \uc131\uc9c8\uc744 \ubcc0\uacbd\ud558\ub294 \ud589\uc704\ub85c\uc11c \uc774\uc5d0 \ud3ec\ud568\ub418\uc9c0 \uc54a\ub294\ub2e4.",B.aJX,B.ayl,null)
B.aI1=s(["\ub300\ub9ac\uc778\uc740 \ubcf8\uc778\uc758 \ud5c8\ub77d\uc774 \uc5c6\uc73c\uba74 \ubcf8\uc778\uc744 \uc704\ud558\uc5ec \uc790\uae30\uc640 \ubc95\ub960\ud589\uc704\ub97c \ud558\uc9c0 \ubabb\ud55c\ub2e4.","\ub300\ub9ac\uc778\uc740 \ubcf8\uc778\uc758 \ud5c8\ub77d\uc774 \uc5c6\uc73c\uba74 \ub3d9\uc77c\ud55c \ubc95\ub960\ud589\uc704\uc5d0 \uad00\ud558\uc5ec \ub2f9\uc0ac\uc790 \uc30d\ubc29\uc744 \ub300\ub9ac\ud558\uc9c0 \ubabb\ud55c\ub2e4.","\ucc44\ubb34\uc758 \uc774\ud589\uc740 \ubcf8\uc778\uc758 \ud5c8\ub77d\uc774 \uc5c6\uc5b4\ub3c4 \uc790\uae30\uacc4\uc57d\uc774\ub098 \uc30d\ubc29\ub300\ub9ac\uac00 \ud5c8\uc6a9\ub41c\ub2e4.","\uc790\uae30\uacc4\uc57d\xb7\uc30d\ubc29\ub300\ub9ac \uae08\uc9c0\uc5d0 \uc704\ubc18\ud55c \ud589\uc704\ub294 \uc5b8\uc81c\ub098 \uc808\ub300\uc801\uc73c\ub85c \ubb34\ud6a8\uc774\ub2e4."],t.s)
B.atX=s(["\uc774\uc5d0 \uc704\ubc18\ud55c \ud589\uc704\ub294 \ubb34\uad8c\ub300\ub9ac\ud589\uc704\ub85c\uc11c \ubcf8\uc778\uc774 \ucd94\uc778\ud558\uba74 \uc720\ud6a8\ub85c \ub420 \uc218 \uc788\uc73c\ubbc0\ub85c \uc808\ub300\uc801 \ubb34\ud6a8\uac00 \uc544\ub2c8\ub2e4"],t.s)
B.a6x=s(["\uc81c124\uc870","\uc790\uae30\uacc4\uc57d\xb7\uc30d\ubc29\ub300\ub9ac","\ubb34\uad8c\ub300\ub9ac\ub85c\uc11c \ucd94\uc778 \uac00\ub2a5"],t.s)
B.bPk=new A.a("gen_cl_agency2_4","civil_law","\ub300\ub9ac",null,"\uc790\uae30\uacc4\uc57d\uacfc \uc30d\ubc29\ub300\ub9ac\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aI1,3,"\ubbfc\ubc95 \uc81c124\uc870\ub294 \ubcf8\uc778\uc758 \ud5c8\ub77d\uc774 \uc5c6\ub294 \uc790\uae30\uacc4\uc57d\xb7\uc30d\ubc29\ub300\ub9ac\ub97c \uc6d0\uce59\uc801\uc73c\ub85c \uae08\uc9c0\ud558\ub418, \ucc44\ubb34\uc758 \uc774\ud589\uc740 \uc608\uc678\ub85c \ud5c8\uc6a9\ud55c\ub2e4. \uc774\uc5d0 \uc704\ubc18\ud55c \ud589\uc704\ub294 \ubb34\uad8c\ub300\ub9ac\ud589\uc704\ub85c\uc11c \ubcf8\uc778\uc774 \ucd94\uc778\ud558\uba74 \uc720\ud6a8\ub85c \ub420 \uc218 \uc788\uc73c\ubbc0\ub85c \uc808\ub300\uc801 \ubb34\ud6a8\uac00 \uc544\ub2c8\ub2e4.",B.atX,B.a6x,null)
B.Wu=s(["\uc758\uc0ac\ud45c\uc2dc\uc758 \ud6a8\ub825\uc774 \uc758\uc0ac\uc758 \ud760\uacb0, \uc0ac\uae30, \uac15\ubc15 \ub610\ub294 \uc5b4\ub290 \uc0ac\uc815\uc744 \uc54c\uc558\uac70\ub098 \uacfc\uc2e4\ub85c \uc54c\uc9c0 \ubabb\ud55c \uac83\uc73c\ub85c \uc601\ud5a5\uc744 \ubc1b\uc744 \uacbd\uc6b0, \uadf8 \uc0ac\uc2e4\uc758 \uc720\ubb34\ub294 \ubcf8\uc778\uc744 \ud45c\uc900\uc73c\ub85c \ud558\uc5ec \uacb0\uc815\ud55c\ub2e4.","\uc758\uc0ac\ud45c\uc2dc\uc758 \ud6a8\ub825\uc774 \uc758\uc0ac\uc758 \ud760\uacb0, \uc0ac\uae30, \uac15\ubc15 \ub610\ub294 \uc5b4\ub290 \uc0ac\uc815\uc744 \uc54c\uc558\uac70\ub098 \uacfc\uc2e4\ub85c \uc54c\uc9c0 \ubabb\ud55c \uac83\uc73c\ub85c \uc601\ud5a5\uc744 \ubc1b\uc744 \uacbd\uc6b0, \uadf8 \uc0ac\uc2e4\uc758 \uc720\ubb34\ub294 \ub300\ub9ac\uc778\uc744 \ud45c\uc900\uc73c\ub85c \ud558\uc5ec \uacb0\uc815\ud55c\ub2e4.","\ud2b9\uc815\ud55c \ubc95\ub960\ud589\uc704\ub97c \uc704\uc784\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ub300\ub9ac\uc778\uc774 \ubcf8\uc778\uc758 \uc9c0\uc2dc\uc5d0 \uc887\uc544 \ud589\uc704\ud55c \ub54c\uc5d0\ub294 \ubcf8\uc778\uc740 \uc790\uae30\uac00 \uc54c\uace0 \uc788\ub294 \uc0ac\uc815\uc5d0 \uad00\ud558\uc5ec \ub300\ub9ac\uc778\uc758 \ubd80\uc9c0\ub97c \uc8fc\uc7a5\ud558\uc9c0 \ubabb\ud55c\ub2e4.","\ub300\ub9ac\uc778\uc774 \uc0ac\uae30\ub97c \ub2f9\ud55c \uacbd\uc6b0 \uadf8 \ud6a8\uacfc\ub294 \ubcf8\uc778\uc5d0\uac8c \ubbf8\uce58\uc9c0 \uc544\ub2c8\ud55c\ub2e4."],t.s)
B.b5i=s(["\uac19\uc740 \uc870 \uc81c2\ud56d\uc5d0 \ub530\ub77c \ud2b9\uc815\ud55c \ubc95\ub960\ud589\uc704\ub97c \uc704\uc784\ud55c \uacbd\uc6b0 \ubcf8\uc778\uc758 \uc9c0\uc2dc\uc5d0 \uc887\uc544 \ud589\uc704\ud55c \ub300\ub9ac\uc778\uc758 \ubd80\uc9c0\ub97c \ubcf8\uc778\uc740 \uc54c\uace0 \uc788\uc5c8\ub358 \uc0ac\uc815\uc5d0 \uad00\ud558\uc5ec \uc8fc\uc7a5\ud560 \uc218 \uc5c6\ub2e4"],t.s)
B.a9n=s(["\uc81c116\uc870","\ub300\ub9ac\ud589\uc704\uc758 \ud558\uc790","\ud310\ub2e8 \uae30\uc900\uc740 \ub300\ub9ac\uc778"],t.s)
B.bsb=new A.a("gen_cl_agency2_5","civil_law","\ub300\ub9ac",null,"\ub300\ub9ac\ud589\uc704\uc758 \ud558\uc790\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.Wu,2,"\ubbfc\ubc95 \uc81c116\uc870 \uc81c1\ud56d\uc740 \uc758\uc0ac\uc758 \ud760\uacb0\uc774\ub098 \uc0ac\uae30\xb7\uac15\ubc15, \ub610\ub294 \uc5b4\ub5a4 \uc0ac\uc815\uc758 \uc9c0\xb7\ubd80\uc9c0 \ubc0f \uacfc\uc2e4 \uc720\ubb34\ub294 \ub300\ub9ac\uc778\uc744 \ud45c\uc900\uc73c\ub85c \ud310\ub2e8\ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ub2e4\ub9cc \uac19\uc740 \uc870 \uc81c2\ud56d\uc5d0 \ub530\ub77c \ud2b9\uc815\ud55c \ubc95\ub960\ud589\uc704\ub97c \uc704\uc784\ud55c \uacbd\uc6b0 \ubcf8\uc778\uc758 \uc9c0\uc2dc\uc5d0 \uc887\uc544 \ud589\uc704\ud55c \ub300\ub9ac\uc778\uc758 \ubd80\uc9c0\ub97c \ubcf8\uc778\uc740 \uc54c\uace0 \uc788\uc5c8\ub358 \uc0ac\uc815\uc5d0 \uad00\ud558\uc5ec \uc8fc\uc7a5\ud560 \uc218 \uc5c6\ub2e4.",B.b5i,B.a9n,null)
B.apK=s(["\ub300\ub9ac\uc778\uc740 \ubc18\ub4dc\uc2dc \ud589\uc704\ub2a5\ub825\uc790\uc774\uc5b4\uc57c \ud55c\ub2e4.","\ub300\ub9ac\ud589\uc704\uc758 \ud558\uc790\ub85c \uc778\ud55c \ucde8\uc18c\uac00\ub2a5\uc131 \ub54c\ubb38\uc5d0 \uc81c\ud55c\ub2a5\ub825\uc790\ub294 \ub300\ub9ac\uc778\uc774 \ub420 \uc218 \uc5c6\ub2e4.","\ub300\ub9ac\uc778\uc774 \uc81c\ud55c\ub2a5\ub825\uc790\uc778 \uacbd\uc6b0 \ubcf8\uc778\uc740 \uadf8 \ub300\ub9ac\ud589\uc704\ub97c \ub2a5\ub825\uc758 \uc81c\ud55c\uc744 \uc774\uc720\ub85c \ucde8\uc18c\ud558\uc9c0 \ubabb\ud55c\ub2e4.","\ub300\ub9ac\uc778\uc774 \uc81c\ud55c\ub2a5\ub825\uc790\uc778 \uacbd\uc6b0 \uadf8 \ub300\ub9ac\ud589\uc704\ub294 \ubb34\ud6a8\uc774\ub2e4."],t.s)
B.bdf=s(["\ub300\ub9ac\uc778\uc774 \uc81c\ud55c\ub2a5\ub825\uc790\ub77c \ud558\ub354\ub77c\ub3c4 \ubcf8\uc778\uc740 \uadf8 \ub300\ub9ac\ud589\uc704\ub97c \ub300\ub9ac\uc778\uc758 \ud589\uc704\ub2a5\ub825 \uc81c\ud55c\uc744 \uc774\uc720\ub85c \ucde8\uc18c\ud560 \uc218 \uc5c6\ub2e4"],t.s)
B.bhL=s(["\uc81c117\uc870","\ub300\ub9ac\uc778\uc758 \ud589\uc704\ub2a5\ub825 \ubd88\uc694"],t.s)
B.bKn=new A.a("gen_cl_agency2_6","civil_law","\ub300\ub9ac",null,"\ub300\ub9ac\uc778\uc758 \ud589\uc704\ub2a5\ub825\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.apK,2,"\ubbfc\ubc95 \uc81c117\uc870\ub294 \ub300\ub9ac\uc778\uc774 \ud589\uc704\ub2a5\ub825\uc790\uc784\uc744 \uc694\ud558\uc9c0 \uc544\ub2c8\ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ub530\ub77c\uc11c \ub300\ub9ac\uc778\uc774 \uc81c\ud55c\ub2a5\ub825\uc790\ub77c \ud558\ub354\ub77c\ub3c4 \ubcf8\uc778\uc740 \uadf8 \ub300\ub9ac\ud589\uc704\ub97c \ub300\ub9ac\uc778\uc758 \ud589\uc704\ub2a5\ub825 \uc81c\ud55c\uc744 \uc774\uc720\ub85c \ucde8\uc18c\ud560 \uc218 \uc5c6\ub2e4.",B.bdf,B.bhL,null)
B.b6U=s(["\ubcf5\ub300\ub9ac\uc778\uc740 \ub300\ub9ac\uc778\uc774 \uadf8 \uad8c\ud55c \ub0b4\uc758 \ud589\uc704\ub97c \ud558\uac8c \ud558\uae30 \uc704\ud558\uc5ec \ub300\ub9ac\uc778 \uc790\uc2e0\uc758 \uc774\ub984\uc73c\ub85c \uc120\uc784\ud55c \ubcf8\uc778\uc758 \ub300\ub9ac\uc778\uc774\ub2e4.","\uc784\uc758\ub300\ub9ac\uc778\uc740 \ubcf8\uc778\uc758 \uc2b9\ub099\uc774 \uc788\uac70\ub098 \ubd80\ub4dd\uc774\ud55c \uc0ac\uc720\uac00 \uc788\ub294 \ub54c\uac00 \uc544\ub2c8\uba74 \ubcf5\ub300\ub9ac\uc778\uc744 \uc120\uc784\ud558\uc9c0 \ubabb\ud55c\ub2e4.","\ubc95\uc815\ub300\ub9ac\uc778\uc740 \uadf8 \ucc45\uc784\uc73c\ub85c \ubcf5\ub300\ub9ac\uc778\uc744 \uc120\uc784\ud560 \uc218 \uc788\uc73c\ub098, \ubd80\ub4dd\uc774\ud55c \uc0ac\uc720\ub85c \uc120\uc784\ud55c \ub54c\uc5d0\ub294 \uc120\uc784\uac10\ub3c5\uc5d0 \uad00\ud55c \ucc45\uc784\ub9cc\uc774 \uc788\ub2e4.","\ubcf5\ub300\ub9ac\uc778\uc758 \ub300\ub9ac\uad8c\uc740 \ub300\ub9ac\uc778\uc758 \ub300\ub9ac\uad8c\uacfc \ubcc4\uac1c\ub85c \uc874\uc7ac\ud558\uba70 \ub300\ub9ac\uc778\uc758 \ub300\ub9ac\uad8c\uc774 \uc18c\uba78\ud558\uc5ec\ub3c4 \ubcf5\ub300\ub9ac\uad8c\uc740 \uc18c\uba78\ud558\uc9c0 \uc54a\ub294\ub2e4."],t.s)
B.bai=s(["\uadf8 \ubcf5\ub300\ub9ac\uad8c\uc740 \ub300\ub9ac\uc778\uc758 \ub300\ub9ac\uad8c\uc744 \uae30\ucd08\ub85c \ud55c\ub2e4. \ub530\ub77c\uc11c \ub300\ub9ac\uc778\uc758 \ub300\ub9ac\uad8c\uc774 \uc18c\uba78\ud558\uba74 \ubcf5\ub300\ub9ac\uad8c\ub3c4 \ud568\uaed8 \uc18c\uba78\ud55c\ub2e4"],t.s)
