B.bFR=new A.a("gen_cl_prescription_7","civil_law","\uc18c\uba78\uc2dc\ud6a8",null,"\uc18c\uba78\uc2dc\ud6a8\uc758 \uc911\ub2e8\uc0ac\uc720\uc5d0 \ud574\ub2f9\ud558\uc9c0 \uc54a\ub294 \uac83\uc740?",B.aiy,3,"\ubbfc\ubc95 \uc81c168\uc870\ub294 \uc18c\uba78\uc2dc\ud6a8\uc758 \uc911\ub2e8\uc0ac\uc720\ub85c \uccad\uad6c, \uc555\ub958 \ub610\ub294 \uac00\uc555\ub958\xb7\uac00\ucc98\ubd84, \uc2b9\uc778\uc744 \uaddc\uc815\ud55c\ub2e4. \ucc44\ubb34\uc790\uc758 \uc0ac\ub9dd\uc740 \uc0c1\uc18d\uc5d0 \uc758\ud574 \ucc44\ubb34\uac00 \uc2b9\uacc4\ub420 \ubfd0 \uc18c\uba78\uc2dc\ud6a8 \uc911\ub2e8\uc0ac\uc720\uc5d0 \ud574\ub2f9\ud558\uc9c0 \uc54a\ub294\ub2e4.",B.UM,B.bgM,null)
B.aGc=s(["\uc7ac\ud310\uc0c1\uc758 \uccad\uad6c\ub294 \uc18c\uba78\uc2dc\ud6a8 \uc911\ub2e8\uc758 \ud6a8\ub825\uc774 \uc788\ub2e4.","\uc7ac\ud310\uc0c1\uc758 \uccad\uad6c\ub97c \ud558\uc600\uc73c\ub098 \uc18c\uac00 \uac01\ud558 \ub610\ub294 \ucde8\ud558\ub41c \uacbd\uc6b0, \uadf8\ub54c\ub85c\ubd80\ud130 6\uc6d4 \ub0b4\uc5d0 \uc7ac\ud310\uc0c1 \uccad\uad6c \ub4f1\uc744 \ud558\uc9c0 \uc54a\uc73c\uba74 \uc2dc\ud6a8\uc911\ub2e8\uc758 \ud6a8\ub825\uc774 \uc5c6\ub2e4.","\ucd5c\uace0\ub294 \uadf8 \uc790\uccb4\ub9cc\uc73c\ub85c \ud655\uc815\uc801\uc778 \uc2dc\ud6a8\uc911\ub2e8\uc758 \ud6a8\ub825\uc774 \uc788\uace0 \ubcc4\ub3c4\uc758 \ud6c4\uc18d\uc870\uce58\ub294 \ud544\uc694\ud558\uc9c0 \uc54a\ub2e4.","\ud30c\uc0b0\uc808\ucc28\ucc38\uac00\ub294 \uc7ac\ud310\uc0c1 \uccad\uad6c\uc5d0 \uc900\ud558\uc5ec \uc2dc\ud6a8\uc911\ub2e8\uc758 \ud6a8\ub825\uc774 \uc788\ub2e4."],t.s)
B.a9Z=s(["\ucd5c\uace0 \ud6c4 6\uc6d4 \uc774\ub0b4\uc5d0 \uc7ac\ud310\uc0c1\uc758 \uccad\uad6c, \ud30c\uc0b0\uc808\ucc28\ucc38\uac00, \ud654\ud574\ub97c \uc704\ud55c \uc18c\ud658, \uc555\ub958 \ub610\ub294 \uac00\uc555\ub958\xb7\uac00\ucc98\ubd84\uc744 \ud558\uc5ec\uc57c"],t.s)
B.aev=s(["\ucd5c\uace0","\ubbfc\ubc95 \uc81c174\uc870","\ubcf4\uc644\uc870\uce58 \ud544\uc694"],t.s)
B.bzv=new A.a("gen_cl_prescription_8","civil_law","\uc18c\uba78\uc2dc\ud6a8",null,'\uc18c\uba78\uc2dc\ud6a8 \uc911\ub2e8\uc0ac\uc720\uc778 "\uccad\uad6c"\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?',B.aGc,2,"\ucd5c\uace0\ub294 \uadf8\uac83\ub9cc\uc73c\ub85c\ub294 \uc2dc\ud6a8\uc911\ub2e8\uc758 \ud6a8\ub825\uc774 \ud655\uc815\ub418\uc9c0 \uc54a\uace0, \ucd5c\uace0 \ud6c4 6\uc6d4 \uc774\ub0b4\uc5d0 \uc7ac\ud310\uc0c1\uc758 \uccad\uad6c, \ud30c\uc0b0\uc808\ucc28\ucc38\uac00, \ud654\ud574\ub97c \uc704\ud55c \uc18c\ud658, \uc555\ub958 \ub610\ub294 \uac00\uc555\ub958\xb7\uac00\ucc98\ubd84\uc744 \ud558\uc5ec\uc57c \ube44\ub85c\uc18c \uc2dc\ud6a8\uc911\ub2e8\uc758 \ud6a8\ub825\uc774 \ud655\uc815\ub41c\ub2e4(\ubbfc\ubc95 \uc81c174\uc870).",B.a9Z,B.aev,null)
B.ag2=s(["\uc2b9\uc778\uc740 \uc0c1\ub300\ubc29\uc758 \uad8c\ub9ac\uac00 \uc874\uc7ac\ud568\uc744 \uc778\uc2dd\ud558\ub294 \ud45c\uc2dc\ub85c\uc11c \ucc98\ubd84\ub2a5\ub825\uc774\ub098 \ucc98\ubd84\uad8c\ud55c \uc788\uc74c\uc744 \uc694\ud558\uc9c0 \uc54a\ub294\ub2e4.","\uc2b9\uc778\uc740 \ubc18\ub4dc\uc2dc \uc11c\uba74\uc5d0 \uc758\ud558\uc5ec\uc57c \ud558\uba70 \uad6c\ub450\uc5d0 \uc758\ud55c \uc2b9\uc778\uc740 \ud6a8\ub825\uc774 \uc5c6\ub2e4.","\uc2b9\uc778\uc740 \uc2dc\ud6a8\uc644\uc131 \ud6c4\uc5d0\ub9cc \uac00\ub2a5\ud558\uace0 \uc2dc\ud6a8\uc644\uc131 \uc804\uc5d0\ub294 \ud560 \uc218 \uc5c6\ub2e4.","\uc77c\ubd80\ubcc0\uc81c\ub294 \ucc44\ubb34 \uc804\uccb4\uc5d0 \ub300\ud55c \uc2b9\uc778\uc73c\ub85c \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4."],t.s)
B.aRl=s(["\uc2b9\uc778\uc740 \uc0c1\ub300\ubc29\uc758 \uad8c\ub9ac\uc5d0 \uad00\ud55c \ucc98\ubd84\uc758 \ub2a5\ub825\uc774\ub098 \uad8c\ud55c \uc788\uc74c\uc744 \uc694\ud558\uc9c0 \uc544\ub2c8\ud55c\ub2e4"],t.s)
B.aZe=s(["\uc2b9\uc778","\ubbfc\ubc95 \uc81c177\uc870","\ucc98\ubd84\ub2a5\ub825 \ubd88\uc694"],t.s)
B.bps=new A.a("gen_cl_prescription_9","civil_law","\uc18c\uba78\uc2dc\ud6a8",null,'\uc18c\uba78\uc2dc\ud6a8 \uc911\ub2e8\uc0ac\uc720\uc778 "\uc2b9\uc778"\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?',B.ag2,0,"\ubbfc\ubc95 \uc81c177\uc870\uc5d0 \ub530\ub77c \uc2b9\uc778\uc740 \uc0c1\ub300\ubc29\uc758 \uad8c\ub9ac\uc5d0 \uad00\ud55c \ucc98\ubd84\uc758 \ub2a5\ub825\uc774\ub098 \uad8c\ud55c \uc788\uc74c\uc744 \uc694\ud558\uc9c0 \uc544\ub2c8\ud55c\ub2e4. \uc2b9\uc778\uc758 \ubc29\uc2dd\uc5d0\ub294 \uc81c\ud55c\uc774 \uc5c6\uc5b4 \ubb35\uc2dc\uc801 \uc2b9\uc778\ub3c4 \uac00\ub2a5\ud558\uba70, \ucc44\ubb34\uc758 \uc77c\ubd80\ubcc0\uc81c\ub294 \ud1b5\uc0c1 \ucc44\ubb34 \uc804\uccb4\uc5d0 \ub300\ud55c \uc2b9\uc778\uc73c\ub85c \uc778\uc815\ub41c\ub2e4.",B.aRl,B.aZe,null)
B.ak9=s(["\uc555\ub958, \uac00\uc555\ub958 \ubc0f \uac00\ucc98\ubd84\uc740 \uc2dc\ud6a8\uc911\ub2e8\uc758 \ud6a8\ub825\uc774 \uc788\ub2e4.","\uc555\ub958, \uac00\uc555\ub958 \ubc0f \uac00\ucc98\ubd84\uc774 \uad8c\ub9ac\uc790\uc758 \uccad\uad6c\uc5d0 \uc758\ud558\uc5ec \ucde8\uc18c\ub41c \ub54c\uc5d0\ub294 \uc2dc\ud6a8\uc911\ub2e8\uc758 \ud6a8\ub825\uc774 \uc5c6\ub2e4.","\uc555\ub958, \uac00\uc555\ub958 \ubc0f \uac00\ucc98\ubd84\uc744 \ubc95\ub960\uc758 \uaddc\uc815\uc5d0 \ub530\ub974\uc9c0 \uc544\ub2c8\ud568\uc73c\ub85c \uc778\ud558\uc5ec \ucde8\uc18c\ub41c \ub54c\uc5d0\ub3c4 \uc2dc\ud6a8\uc911\ub2e8\uc758 \ud6a8\ub825\uc774 \uc788\ub2e4.","\uc555\ub958, \uac00\uc555\ub958 \ubc0f \uac00\ucc98\ubd84\uc740 \uc2dc\ud6a8\uc758 \uc774\uc775\uc744 \ubc1b\uc744 \uc790\uc5d0 \ub300\ud558\uc5ec \ud558\uc9c0 \uc544\ub2c8\ud55c \uacbd\uc6b0, \uc774\ub97c \ud1b5\uc9c0\ud55c \ud6c4\uac00 \uc544\ub2c8\uba74 \uc2dc\ud6a8\uc911\ub2e8\uc758 \ud6a8\ub825\uc774 \uc5c6\ub2e4."],t.s)
B.b0E=s(["\ubc95\ub960\uc758 \uaddc\uc815\uc5d0 \ub530\ub974\uc9c0 \uc544\ub2c8\ud568\uc73c\ub85c \uc778\ud558\uc5ec \ucde8\uc18c\ub41c \ub54c\uc5d0\ub294 \uc2dc\ud6a8\uc911\ub2e8\uc758 \ud6a8\ub825\uc774 \uc5c6\ub2e4"],t.s)
B.axM=s(["\uc555\ub958\xb7\uac00\uc555\ub958\xb7\uac00\ucc98\ubd84","\ubbfc\ubc95 \uc81c175\uc870","\ucde8\uc18c\uc2dc \ud6a8\ub825\uc5c6\uc74c"],t.s)
B.bDR=new A.a("gen_cl_prescription_10","civil_law","\uc18c\uba78\uc2dc\ud6a8",null,"\uc555\ub958, \uac00\uc555\ub958 \ubc0f \uac00\ucc98\ubd84\uc5d0 \uc758\ud55c \uc18c\uba78\uc2dc\ud6a8 \uc911\ub2e8\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.ak9,2,"\ubbfc\ubc95 \uc81c175\uc870\uc5d0 \ub530\ub77c \uc555\ub958, \uac00\uc555\ub958 \ubc0f \uac00\ucc98\ubd84\uc740 \uad8c\ub9ac\uc790\uc758 \uccad\uad6c\uc5d0 \uc758\ud558\uc5ec \ub610\ub294 \ubc95\ub960\uc758 \uaddc\uc815\uc5d0 \ub530\ub974\uc9c0 \uc544\ub2c8\ud568\uc73c\ub85c \uc778\ud558\uc5ec \ucde8\uc18c\ub41c \ub54c\uc5d0\ub294 \uc2dc\ud6a8\uc911\ub2e8\uc758 \ud6a8\ub825\uc774 \uc5c6\ub2e4. \ub610\ud55c \uc81c176\uc870\uc5d0 \ub530\ub77c \uc2dc\ud6a8\uc774\uc775\uc744 \ubc1b\uc744 \uc790\uc5d0 \ub300\ud558\uc5ec \ud558\uc9c0 \uc54a\uc740 \uacbd\uc6b0 \ud1b5\uc9c0 \ud6c4\uc5d0\uc57c \uc911\ub2e8\uc758 \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4.",B.b0E,B.axM,null)
B.amy=s(["\uc2dc\ud6a8\uac00 \uc911\ub2e8\ub41c \ub54c\uc5d0\ub294 \uc911\ub2e8\uae4c\uc9c0 \uacbd\uacfc\ud55c \uc2dc\ud6a8\uae30\uac04\uc740 \uc774\ub97c \uc0b0\uc785\ud558\uace0 \uadf8 \uc774\ud6c4\ubd80\ud130\ub294 \uc0c8\ub85c\uc774 \uc9c4\ud589\ud558\uc9c0 \uc54a\ub294\ub2e4.","\uc2dc\ud6a8\uac00 \uc911\ub2e8\ub41c \ub54c\uc5d0\ub294 \uc911\ub2e8\uc0ac\uc720 \uc885\ub8cc \uc2dc\ubd80\ud130 \uc0c8\ub85c\uc774 \uc2dc\ud6a8\uae30\uac04\uc774 \uc9c4\ud589\ud55c\ub2e4.","\uc2dc\ud6a8\uc911\ub2e8\uc758 \ud6a8\ub825\uc740 \uc6d0\uce59\uc801\uc73c\ub85c \ub2f9\uc0ac\uc790 \ubc0f \uadf8 \uc2b9\uacc4\uc778 \uc774\uc678\uc758 \uc81c3\uc790\uc5d0\uac8c\ub3c4 \ubbf8\uce5c\ub2e4.","\uc7ac\ud310\uc0c1 \uccad\uad6c\ub85c \uc778\ud55c \uc2dc\ud6a8\uc911\ub2e8\uc758 \ud6a8\ub825\uc740 \uc18c\ub97c \uc81c\uae30\ud55c \ub54c\uac00 \uc544\ub2c8\ub77c \ud310\uacb0\uc774 \ud655\uc815\ub41c \ub54c \ubc1c\uc0dd\ud55c\ub2e4."],t.s)
B.b3A=s(["\uc911\ub2e8\uc0ac\uc720\uac00 \uc885\ub8cc\ud55c \ub54c\ubd80\ud130 \uc0c8\ub85c\uc774 \uc2dc\ud6a8\uae30\uac04\uc774 \uc9c4\ud589\ud55c\ub2e4"],t.s)
