B.bNf=new A.a("gen_cl_prescription_11","civil_law","\uc18c\uba78\uc2dc\ud6a8",null,"\uc18c\uba78\uc2dc\ud6a8 \uc911\ub2e8\uc758 \ud6a8\ub825\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.amy,1,"\ubbfc\ubc95 \uc81c178\uc870 \uc81c1\ud56d\uc5d0 \ub530\ub77c \uc2dc\ud6a8\uac00 \uc911\ub2e8\ub41c \ub54c\uc5d0\ub294 \uc911\ub2e8\uae4c\uc9c0 \uacbd\uacfc\ud55c \uc2dc\ud6a8\uae30\uac04\uc740 \uc0b0\uc785\ud558\uc9c0 \uc544\ub2c8\ud558\uace0 \uc911\ub2e8\uc0ac\uc720\uac00 \uc885\ub8cc\ud55c \ub54c\ubd80\ud130 \uc0c8\ub85c\uc774 \uc2dc\ud6a8\uae30\uac04\uc774 \uc9c4\ud589\ud55c\ub2e4. \uc2dc\ud6a8\uc911\ub2e8\uc758 \ud6a8\ub825\uc740 \uc6d0\uce59\uc801\uc73c\ub85c \ub2f9\uc0ac\uc790 \ubc0f \uadf8 \uc2b9\uacc4\uc778 \uc0ac\uc774\uc5d0\ub9cc \ud6a8\ub825\uc774 \uc788\ub2e4(\ubbfc\ubc95 \uc81c169\uc870).",B.b3A,B.a43,null)
B.acL=s(["\uc2dc\ud6a8\uc758 \uc815\uc9c0\ub294 \uc2dc\ud6a8\uc644\uc131 \uc9c1\uc804 \uc77c\uc815\ud55c \uc0ac\uc720\uac00 \uc788\ub294 \uacbd\uc6b0 \uc2dc\ud6a8\uc758 \uc644\uc131\uc744 \uc77c\uc815 \uae30\uac04 \uc720\uc608\ud558\ub294 \uc81c\ub3c4\uc774\ub2e4.","\uc7ac\uc0b0\uad00\ub9ac\uc778\uc774 \uc5c6\ub294 \ubb34\ub2a5\ub825\uc790\uc758 \uc7ac\uc0b0\uc5d0 \uad00\ud55c \uad8c\ub9ac\ub294 \uadf8\uac00 \ub2a5\ub825\uc790\uac00 \ub418\uac70\ub098 \ubc95\uc815\ub300\ub9ac\uc778\uc774 \ucde8\uc784\ud55c \ub54c\ub85c\ubd80\ud130 6\uc6d4 \ub0b4\uc5d0\ub294 \uc2dc\ud6a8\uac00 \uc644\uc131\ud558\uc9c0 \uc544\ub2c8\ud55c\ub2e4.","\ucc9c\uc7ac \uae30\ud0c0 \uc0ac\ubcc0\uc73c\ub85c \uc778\ud558\uc5ec \uc2dc\ud6a8\ub97c \uc911\ub2e8\ud560 \uc218 \uc5c6\uc744 \ub54c\uc5d0\ub294 \uadf8 \uc0ac\uc720\uac00 \uc885\ub8cc\ud55c \ub54c\ub85c\ubd80\ud130 1\uc6d4 \ub0b4\uc5d0\ub294 \uc2dc\ud6a8\uac00 \uc644\uc131\ud558\uc9c0 \uc544\ub2c8\ud55c\ub2e4.","\uc2dc\ud6a8\uac00 \uc815\uc9c0\ub418\uba74 \uc774\ubbf8 \uc9c4\ud589\ud55c \uc2dc\ud6a8\uae30\uac04\uc758 \ud6a8\ub825\uc774 \uc18c\uae09\ud558\uc5ec \uc18c\uba78\ud55c\ub2e4."],t.s)
B.baM=s(["\uc774\ubbf8 \uc9c4\ud589\ud55c \uc2dc\ud6a8\uae30\uac04\uc740 \uadf8\ub300\ub85c \uc720\uc9c0\ub418\uace0 \ub2e4\ub9cc \uc644\uc131\uc774 \uc720\uc608\ub420 \ubfd0\uc774\ub2e4"],t.s)
B.ZU=s(["\uc18c\uba78\uc2dc\ud6a8 \uc815\uc9c0","\uc911\ub2e8\uacfc \uad6c\ubcc4","\ubbfc\ubc95 \uc81c179\uc870~182\uc870"],t.s)
B.bO8=new A.a("gen_cl_prescription_12","civil_law","\uc18c\uba78\uc2dc\ud6a8",null,"\uc18c\uba78\uc2dc\ud6a8\uc758 \uc815\uc9c0\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.acL,3,"\uc18c\uba78\uc2dc\ud6a8\uc758 \uc815\uc9c0\ub294 \uc2dc\ud6a8\uc644\uc131 \uc9c1\uc804\uc5d0 \uad8c\ub9ac\uc790\ub97c \ubcf4\ud638\ud560 \ud544\uc694\uac00 \uc788\ub294 \uc0ac\uc720\uac00 \ubc1c\uc0dd\ud55c \uacbd\uc6b0 \uc77c\uc815 \uae30\uac04 \uc2dc\ud6a8\uc758 \uc644\uc131\uc744 \uc720\uc608\ud558\ub294 \uc81c\ub3c4\ub85c\uc11c, \uc911\ub2e8\uacfc \ub2ec\ub9ac \uc774\ubbf8 \uc9c4\ud589\ud55c \uc2dc\ud6a8\uae30\uac04\uc740 \uadf8\ub300\ub85c \uc720\uc9c0\ub418\uace0 \ub2e4\ub9cc \uc644\uc131\uc774 \uc720\uc608\ub420 \ubfd0\uc774\ub2e4(\ubbfc\ubc95 \uc81c179\uc870 \ub0b4\uc9c0 \uc81c182\uc870).",B.baM,B.ZU,null)
B.aol=s(["\ubd80\ubd80\uc758 \uc77c\ubc29\uc774 \ud0c0\ubc29\uc5d0 \ub300\ud558\uc5ec \uac00\uc9c0\ub294 \uad8c\ub9ac\ub294 \ud63c\uc778\uad00\uacc4\uc758 \uc885\ub8cc\ud55c \ub54c\ub85c\ubd80\ud130 6\uc6d4 \ub0b4\uc5d0\ub294 \uc2dc\ud6a8\uac00 \uc644\uc131\ud558\uc9c0 \uc544\ub2c8\ud55c\ub2e4.","\ubd80\ubd80 \uc0ac\uc774\uc758 \uad8c\ub9ac\ub294 \ud63c\uc778 \uc911\uc5d0\ub3c4 \uc2dc\ud6a8\uac00 \uc815\uc9c0 \uc5c6\uc774 \uc9c4\ud589\ud55c\ub2e4.","\ubd80\ubd80 \uc0ac\uc774\uc758 \uad8c\ub9ac\ub294 \ud63c\uc778\uad00\uacc4 \uc885\ub8cc \ud6c4 1\ub144 \ub0b4\uc5d0\ub294 \uc2dc\ud6a8\uac00 \uc644\uc131\ud558\uc9c0 \uc544\ub2c8\ud55c\ub2e4.","\ubd80\ubd80 \uc0ac\uc774\uc758 \uad8c\ub9ac\uc5d0\ub294 \uc18c\uba78\uc2dc\ud6a8\uc758 \uc815\uc9c0 \uaddc\uc815\uc774 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4."],t.s)
B.a5F=s(["\ud63c\uc778\uad00\uacc4\uac00 \uc885\ub8cc\ud55c \ub54c\ub85c\ubd80\ud130 6\uc6d4 \ub0b4\uc5d0\ub294 \uc2dc\ud6a8\uac00 \uc644\uc131\ud558\uc9c0 \uc544\ub2c8\ud55c\ub2e4"],t.s)
B.VS=s(["\ubbfc\ubc95 \uc81c180\uc870","\ubd80\ubd80\uac04 \uad8c\ub9ac","\uc2dc\ud6a8\uc815\uc9c0"],t.s)
B.bRv=new A.a("gen_cl_prescription_13","civil_law","\uc18c\uba78\uc2dc\ud6a8",null,"\ubd80\ubd80 \uc0ac\uc774\uc758 \uad8c\ub9ac\uc5d0 \uad00\ud55c \uc18c\uba78\uc2dc\ud6a8 \uc815\uc9c0\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aol,0,"\ubbfc\ubc95 \uc81c180\uc870 \uc81c2\ud56d\uc740 \ubd80\ubd80\uc758 \uc77c\ubc29\uc774 \ud0c0\ubc29\uc5d0 \ub300\ud558\uc5ec \uac00\uc9c0\ub294 \uad8c\ub9ac\ub294 \ud63c\uc778\uad00\uacc4\uac00 \uc885\ub8cc\ud55c \ub54c\ub85c\ubd80\ud130 6\uc6d4 \ub0b4\uc5d0\ub294 \uc2dc\ud6a8\uac00 \uc644\uc131\ud558\uc9c0 \uc544\ub2c8\ud55c\ub2e4\uace0 \uaddc\uc815\ud558\uc5ec, \ud63c\uc778 \uc911 \uad8c\ub9ac\ud589\uc0ac\uc758 \uc5b4\ub824\uc6c0\uc744 \uace0\ub824\ud55c \uc2dc\ud6a8\uc815\uc9c0 \uc81c\ub3c4\ub97c \ub450\uace0 \uc788\ub2e4.",B.a5F,B.VS,null)
B.aEF=s(["\uc18c\uba78\uc2dc\ud6a8\uac00 \uc644\uc131\ud558\uba74 \uad8c\ub9ac\ub294 \ub2f9\uc5f0\ud788 \uc18c\uba78\ud558\uace0, \ub2f9\uc0ac\uc790\uc758 \uc6d0\uc6a9\uc774 \uc5c6\uc5b4\ub3c4 \ubc95\uc6d0\uc774 \uc774\ub97c \uc9c1\uad8c\uc73c\ub85c \uace0\ub824\ud560 \uc218 \uc788\ub2e4.","\uc18c\uba78\uc2dc\ud6a8\uac00 \uc644\uc131\ud558\ub354\ub77c\ub3c4 \uad8c\ub9ac\ub294 \uc18c\uba78\ud558\uc9c0 \uc54a\uace0 \ub2e4\ub9cc \ucc44\ubb34\uc790\uc5d0\uac8c \uc774\ud589\uac70\uc808\uc758 \ud56d\ubcc0\uad8c\uc774 \ubc1c\uc0dd\ud560 \ubfd0\uc774\ub2e4.","\uc18c\uba78\uc2dc\ud6a8\uac00 \uc644\uc131\ud558\uba74 \ucc44\uad8c\uc790\uac00 \uc2dc\ud6a8\uc774\uc775\uc744 \ud3ec\uae30\ud574\uc57c\ub9cc \uad8c\ub9ac\uac00 \uc18c\uba78\ud55c\ub2e4.","\uc18c\uba78\uc2dc\ud6a8\uac00 \uc644\uc131\ud558\ub354\ub77c\ub3c4 \ub2f9\uc0ac\uc790\uac00 \uc774\ub97c \uc6d0\uc6a9\ud558\uc9c0 \uc54a\uc73c\uba74 \ubc95\uc6d0\uc740 \uc774\ub97c \uace0\ub824\ud560 \uc218 \uc5c6\ub2e4\ub294 \uacac\ud574\ub294 \uc0c1\ub300\uc801 \uc18c\uba78\uc124\uc774\ub2e4."],t.s)
B.b7z=s(["\uad8c\ub9ac\uac00 \ub2f9\uc0ac\uc790\uc758 \uc6d0\uc6a9 \uc5c6\uc774\ub3c4 \ubc95\ub960\uc0c1 \ub2f9\uc5f0\ud788 \uc18c\uba78\ud55c\ub2e4\ub294 \uacac\ud574\ub85c"],t.s)
B.b41=s(["\uc808\ub300\uc801 \uc18c\uba78\uc124","\uc0c1\ub300\uc801 \uc18c\uba78\uc124","\uc2dc\ud6a8\uc644\uc131 \ud6a8\uacfc"],t.s)
B.bGP=new A.a("gen_cl_prescription_14","civil_law","\uc18c\uba78\uc2dc\ud6a8",null,"\uc18c\uba78\uc2dc\ud6a8 \uc644\uc131\uc758 \ud6a8\uacfc\uc5d0 \uad00\ud55c \uc808\ub300\uc801 \uc18c\uba78\uc124\uc758 \ub0b4\uc6a9\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aEF,0,"\uc808\ub300\uc801 \uc18c\uba78\uc124\uc740 \uc18c\uba78\uc2dc\ud6a8\uae30\uac04\uc774 \ub9cc\ub8cc\ud558\uba74 \uad8c\ub9ac\uac00 \ub2f9\uc0ac\uc790\uc758 \uc6d0\uc6a9 \uc5c6\uc774\ub3c4 \ubc95\ub960\uc0c1 \ub2f9\uc5f0\ud788 \uc18c\uba78\ud55c\ub2e4\ub294 \uacac\ud574\ub85c, \ud310\ub840\uc758 \uae30\ubcf8\uc785\uc7a5\uc73c\ub85c \uc774\ud574\ub41c\ub2e4. \uc774\uc5d0 \ubc18\ud574 \uc0c1\ub300\uc801 \uc18c\uba78\uc124\uc740 \uc2dc\ud6a8\uc644\uc131\uc73c\ub85c \uad8c\ub9ac\uac00 \uc18c\uba78\ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \ucc44\ubb34\uc790\uc5d0\uac8c \uc2dc\ud6a8\uc6d0\uc6a9\uad8c\uc774 \ubc1c\uc0dd\ud560 \ubfd0\uc774\ub77c\uace0 \ubcf8\ub2e4.",B.b7z,B.b41,null)
B.aXg=s(["\uc18c\uba78\uc2dc\ud6a8\ub294 \uadf8 \uae30\uc0b0\uc77c\uc5d0 \uc18c\uae09\ud558\uc5ec \ud6a8\ub825\uc774 \uc788\ub2e4.","\uc18c\uba78\uc2dc\ud6a8\ub294 \uc2dc\ud6a8\uc644\uc131 \uc2dc\ubd80\ud130 \uc7a5\ub798\ub97c \ud5a5\ud558\uc5ec\ub9cc \ud6a8\ub825\uc774 \uc788\ub2e4.","\uc18c\uba78\uc2dc\ud6a8\uc758 \uc644\uc131\uc740 \uc18c\ub97c \uc81c\uae30\ud55c \ub54c\ubd80\ud130 \ud6a8\ub825\uc774 \uc788\ub2e4.","\uc18c\uba78\uc2dc\ud6a8\uc758 \uc18c\uae09\ud6a8\ub294 \ubc95\uc6d0\uc758 \uc7ac\ub7c9\uc5d0 \ub530\ub77c \uc778\uc815 \uc5ec\ubd80\uac00 \ub2ec\ub77c\uc9c4\ub2e4."],t.s)
B.aCD=s(["\uc18c\uba78\uc2dc\ud6a8\ub294 \uadf8 \uae30\uc0b0\uc77c\uc5d0 \uc18c\uae09\ud558\uc5ec \ud6a8\ub825\uc774 \uc788\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4"],t.s)
B.av4=s(["\uc18c\uae09\ud6a8","\ubbfc\ubc95 \uc81c167\uc870"],t.s)
B.bQ_=new A.a("gen_cl_prescription_15","civil_law","\uc18c\uba78\uc2dc\ud6a8",null,"\uc18c\uba78\uc2dc\ud6a8\uc758 \uc18c\uae09\ud6a8\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aXg,0,"\ubbfc\ubc95 \uc81c167\uc870\ub294 \uc18c\uba78\uc2dc\ud6a8\ub294 \uadf8 \uae30\uc0b0\uc77c\uc5d0 \uc18c\uae09\ud558\uc5ec \ud6a8\ub825\uc774 \uc788\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc774\uc5d0 \ub530\ub77c \uc2dc\ud6a8\uac00 \uc644\uc131\ub418\uba74 \uad8c\ub9ac\ub294 \ucc98\uc74c\ubd80\ud130 \uc874\uc7ac\ud558\uc9c0 \uc54a\uc558\ub358 \uac83\uacfc \uac19\uc740 \ud6a8\uacfc\uac00 \ubc1c\uc0dd\ud558\uba70, \uc774\ub294 \uc9c0\uc5f0\uc190\ud574\uae08 \ub4f1 \ubd80\uc218\uc801 \ubc95\ub960\uad00\uacc4\uc5d0\ub3c4 \uc601\ud5a5\uc744 \ubbf8\uce5c\ub2e4.",B.aCD,B.av4,null)
B.Sn=s(["\uc18c\uba78\uc2dc\ud6a8\uc758 \uc774\uc775\uc740 \ubbf8\ub9ac \ud3ec\uae30\ud558\uc9c0 \ubabb\ud55c\ub2e4.","\uc18c\uba78\uc2dc\ud6a8 \uc644\uc131 \ud6c4\uc758 \uc2dc\ud6a8\uc774\uc775 \ud3ec\uae30\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \uc720\ud6a8\ud558\ub2e4.","\uc18c\uba78\uc2dc\ud6a8\uc774\uc775\uc758 \ud3ec\uae30\ub294 \uc0c1\ub300\uc801 \ud6a8\ub825\ub9cc \uc788\uc5b4 \ub2e4\ub978 \uacf5\ub3d9\ucc44\ubb34\uc790\uc5d0\uac8c\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \ud6a8\ub825\uc774 \uc5c6\ub2e4.","\uc18c\uba78\uc2dc\ud6a8\uc644\uc131 \uc804\uc5d0 \ub2f9\uc0ac\uc790\uc758 \uc57d\uc815\uc73c\ub85c \uc2dc\ud6a8\uc774\uc775\uc744 \ud3ec\uae30\ud558\ub294 \ud2b9\uc57d\ub3c4 \uc720\ud6a8\ud558\ub2e4."],t.s)
B.aAX=s(["\uc18c\uba78\uc2dc\ud6a8\uc758 \uc774\uc775\uc740 \ubbf8\ub9ac \ud3ec\uae30\ud558\uc9c0 \ubabb\ud55c\ub2e4\uace0 \uaddc\uc815\ud558\uc5ec \uc2dc\ud6a8\uc644\uc131 \uc804\uc758 \ud3ec\uae30\ud2b9\uc57d\uc740 \ubb34\ud6a8\uc774\ub2e4"],t.s)
B.b2Y=s(["\uc2dc\ud6a8\uc774\uc775 \ud3ec\uae30","\ubbfc\ubc95 \uc81c184\uc870","\uc0ac\uc804\ud3ec\uae30 \uae08\uc9c0"],t.s)
B.bnT=new A.a("gen_cl_prescription_16","civil_law","\uc18c\uba78\uc2dc\ud6a8",null,"\uc18c\uba78\uc2dc\ud6a8\uc774\uc775\uc758 \ud3ec\uae30\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.Sn,3,"\ubbfc\ubc95 \uc81c184\uc870 \uc81c1\ud56d\uc740 \uc18c\uba78\uc2dc\ud6a8\uc758 \uc774\uc775\uc740 \ubbf8\ub9ac \ud3ec\uae30\ud558\uc9c0 \ubabb\ud55c\ub2e4\uace0 \uaddc\uc815\ud558\uc5ec \uc2dc\ud6a8\uc644\uc131 \uc804\uc758 \ud3ec\uae30\ud2b9\uc57d\uc740 \ubb34\ud6a8\uc774\ub2e4. \ubc18\uba74 \uc2dc\ud6a8\uc644\uc131 \ud6c4\uc758 \ud3ec\uae30\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \uc720\ud6a8\ud558\uba70, \uadf8 \ud6a8\ub825\uc740 \ud3ec\uae30\ud55c \ub2f9\uc0ac\uc790\uc5d0\uac8c\ub9cc \ubbf8\uce58\ub294 \uc0c1\ub300\ud6a8\ub97c \uac00\uc9c4\ub2e4.",B.aAX,B.b2Y,null)
B.agy=s(["\ucc44\ubb34\uc790\uac00 \uc18c\uba78\uc2dc\ud6a8\uc644\uc131 \uc0ac\uc2e4\uc744 \ubaa8\ub974\uace0 \ucc44\ubb34\ub97c \uc2b9\uc778\ud558\uc600\ub2e4\uba74 \uc2dc\ud6a8\uc774\uc775 \ud3ec\uae30\uc758 \ud6a8\ub825\uc774 \uc5c6\ub2e4.","\ucc44\ubb34\uc790\uac00 \uc18c\uba78\uc2dc\ud6a8\uc644\uc131 \ud6c4 \ucc44\ubb34\ub97c \uc2b9\uc778\ud55c \uacbd\uc6b0, \uc2dc\ud6a8\uc644\uc131 \uc0ac\uc2e4\uc744 \uc54c\uc558\ub294\uc9c0 \uc5ec\ubd80\uc640 \uad00\uacc4\uc5c6\uc774 \uc2dc\ud6a8\uc774\uc775\uc744 \ud3ec\uae30\ud55c \uac83\uc73c\ub85c \ucd94\uc815\ub41c\ub2e4.","\ucc44\ubb34\uc790\uc758 \uc77c\ubd80\ubcc0\uc81c\ub294 \uc2dc\ud6a8\uc774\uc775 \ud3ec\uae30\uc640 \ubb34\uad00\ud558\uba70 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \uc2b9\uc778\uc73c\ub85c \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4.","\uc2dc\ud6a8\uc644\uc131 \ud6c4\uc758 \uc2b9\uc778\uc740 \uc5b8\uc81c\ub098 \ubb34\ud6a8\uc774\uba70 \ucc44\uad8c\uc790\ub294 \uc774\ub97c \uc6d0\uc6a9\ud560 \uc218 \uc5c6\ub2e4."],t.s)
B.aqi=s(["\uc2dc\ud6a8\uc644\uc131 \uc0ac\uc2e4\uc744 \uc54c\uace0 \ud55c \uac83\uc73c\ub85c \ucd94\uc815\ud558\uc5ec \uc2dc\ud6a8\uc774\uc775\uc744 \ud3ec\uae30\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4"],t.s)
B.biN=s(["\uc2dc\ud6a8\uc644\uc131 \ud6c4 \uc2b9\uc778","\ud310\ub840","\ud3ec\uae30 \ucd94\uc815"],t.s)
B.bAf=new A.a("gen_cl_prescription_17","civil_law","\uc18c\uba78\uc2dc\ud6a8",null,"\uc18c\uba78\uc2dc\ud6a8\uc644\uc131 \ud6c4 \ucc44\ubb34\uc790\uac00 \ucc44\ubb34\ub97c \uc2b9\uc778\ud558\uac70\ub098 \uc77c\ubd80\ubcc0\uc81c\ub97c \ud55c \uacbd\uc6b0\uc5d0 \uad00\ud55c \ud310\ub840\uc758 \ud0dc\ub3c4\ub85c \uc633\uc740 \uac83\uc740?",B.agy,1,"\ud310\ub840\ub294 \ucc44\ubb34\uc790\uac00 \uc18c\uba78\uc2dc\ud6a8\uc644\uc131 \ud6c4 \ucc44\ubb34\ub97c \uc2b9\uc778\ud558\uac70\ub098 \uc77c\ubd80\ubcc0\uc81c\ub97c \ud55c \uacbd\uc6b0, \uc2dc\ud6a8\uc644\uc131 \uc0ac\uc2e4\uc744 \uc54c\uace0 \ud55c \uac83\uc73c\ub85c \ucd94\uc815\ud558\uc5ec \uc2dc\ud6a8\uc774\uc775\uc744 \ud3ec\uae30\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4. \uc774\ub294 \ucc44\ubb34\uc790\uc758 \uc2e0\ub8b0\ub97c \ubcf4\ud638\ud558\uace0 \ubc95\ub960\uad00\uacc4\uc758 \uc548\uc815\uc744 \ub3c4\ubaa8\ud558\uae30 \uc704\ud568\uc774\ub2e4.",B.aqi,B.biN,null)
B.aHb=s(["\uc81c\ucc99\uae30\uac04\uc740 \uadf8 \uae30\uac04\uc758 \uacbd\uacfc\ub85c \uad8c\ub9ac\uac00 \ub2f9\uc5f0\ud788 \uc18c\uba78\ud558\ub098 \uc911\ub2e8\uc774 \uc778\uc815\ub418\uc9c0 \uc54a\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub2e4.","\uc18c\uba78\uc2dc\ud6a8\ub294 \uc911\ub2e8\xb7\uc815\uc9c0 \uc81c\ub3c4\uac00 \uc778\uc815\ub418\ub098 \uc81c\ucc99\uae30\uac04\uc740 \uc6d0\uce59\uc801\uc73c\ub85c \uc774\ub7ec\ud55c \uc81c\ub3c4\uac00 \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4.","\uc81c\ucc99\uae30\uac04\uc774 \ub3c4\uacfc\ub41c \uad8c\ub9ac\ub77c\ub3c4 \ub2f9\uc0ac\uc790\uac00 \uc774\ub97c \uc8fc\uc7a5\ud558\uc9c0 \uc54a\uc73c\uba74 \ubc95\uc6d0\uc740 \uc774\ub97c \uace0\ub824\ud560 \uc218 \uc5c6\ub2e4.","\uc81c\ucc99\uae30\uac04\uc774 \uc801\uc6a9\ub418\ub294 \uad8c\ub9ac\ub85c\ub294 \ucde8\uc18c\uad8c, \ud574\uc81c\uad8c \ub4f1 \ud615\uc131\uad8c\uc774 \ub300\ud45c\uc801\uc774\ub2e4."],t.s)
B.a0x=s(["\ub2f9\uc0ac\uc790\uc758 \uc8fc\uc7a5\uc774 \uc5c6\uc5b4\ub3c4 \ubc95\uc6d0\uc774 \uc9c1\uad8c\uc73c\ub85c \uace0\ub824\ud558\uc5ec\uc57c \ud55c\ub2e4\ub294 \uac83\uc774 \ud1b5\uc124\xb7\ud310\ub840\uc774\ub2e4"],t.s)
B.aL3=s(["\uc81c\ucc99\uae30\uac04","\uc18c\uba78\uc2dc\ud6a8 \uad6c\ubcc4","\uc9c1\uad8c\uc870\uc0ac"],t.s)
B.bRL=new A.a("gen_cl_prescription_18","civil_law","\uc18c\uba78\uc2dc\ud6a8",null,"\uc81c\ucc99\uae30\uac04\uacfc \uc18c\uba78\uc2dc\ud6a8\uc758 \uad6c\ubcc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aHb,2,"\uc81c\ucc99\uae30\uac04\uc740 \uadf8 \uc131\uc9c8\uc0c1 \ubc95\ub960\uad00\uacc4\ub97c \uc870\uc18d\ud788 \ud655\uc815\ud560 \ud544\uc694\uc5d0\uc11c \uc778\uc815\ub418\ub294 \uac83\uc73c\ub85c, \ub2f9\uc0ac\uc790\uc758 \uc8fc\uc7a5\uc774 \uc5c6\uc5b4\ub3c4 \ubc95\uc6d0\uc774 \uc9c1\uad8c\uc73c\ub85c \uace0\ub824\ud558\uc5ec\uc57c \ud55c\ub2e4\ub294 \uac83\uc774 \ud1b5\uc124\xb7\ud310\ub840\uc774\ub2e4. \ubc18\uba74 \uc18c\uba78\uc2dc\ud6a8\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \ub2f9\uc0ac\uc790\uc758 \uc6d0\uc6a9\uc774 \uc788\uc5b4\uc57c \ubc95\uc6d0\uc774 \uace0\ub824\ud560 \uc218 \uc788\ub2e4.",B.a0x,B.aL3,null)
B.RR=s(["\uc81c\ucc99\uae30\uac04\uc5d0\ub3c4 \uc18c\uba78\uc2dc\ud6a8\uc640 \ub9c8\ucc2c\uac00\uc9c0\ub85c \uc911\ub2e8\uc0ac\uc720\uc778 \uccad\uad6c, \uc555\ub958\xb7\uac00\uc555\ub958, \uc2b9\uc778\uc774 \uadf8\ub300\ub85c \uc801\uc6a9\ub41c\ub2e4.","\uc81c\ucc99\uae30\uac04\uc774 \uc801\uc6a9\ub418\ub294 \uad8c\ub9ac\uc5d0 \uad00\ud55c \uc18c\ub294 \uadf8 \uae30\uac04 \ub0b4\uc5d0 \uc7ac\ud310\uc0c1 \ud589\uc0ac\ub418\uc5b4\uc57c \ud558\ub294 \uacbd\uc6b0\uac00 \ub9ce\ub2e4\ub294 \uac83\uc774 \ud310\ub840\uc758 \uc785\uc7a5\uc774\ub2e4.","\uc18c\uba78\uc2dc\ud6a8\uae30\uac04\uc740 \ubc95\ub960\ud589\uc704\uc5d0 \uc758\ud558\uc5ec \uc774\ub97c \ubc30\uc81c, \uc5f0\uc7a5 \ub610\ub294 \uac00\uc911\ud560 \uc218 \uc788\ub2e4.","\uc81c\ucc99\uae30\uac04\uc740 \uc18c\uae09\ud6a8\uac00 \uc788\uc5b4 \uae30\uc0b0\uc77c\ub85c \uc18c\uae09\ud558\uc5ec \uad8c\ub9ac\uac00 \uc18c\uba78\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4."],t.s)
B.aLC=s(["\uadf8 \uae30\uac04 \ub0b4\uc5d0 \uc7ac\ud310\uc0c1 \uccad\uad6c\uac00 \uc774\ub8e8\uc5b4\uc838\uc57c \ud55c\ub2e4\uace0 \ubcf4\ub294 \uacbd\uc6b0\uac00 \ub9ce\ub2e4\ub294 \uc785\uc7a5\uc744 \ucde8\ud55c\ub2e4"],t.s)
B.aU0=s(["\uc81c\ucc99\uae30\uac04","\uc7ac\ud310\uc0c1 \ud589\uc0ac","\ubbfc\ubc95 \uc81c184\uc870 \uc81c2\ud56d"],t.s)
B.bK8=new A.a("gen_cl_prescription_19","civil_law","\uc18c\uba78\uc2dc\ud6a8",null,"\uc81c\ucc99\uae30\uac04\uacfc \uc18c\uba78\uc2dc\ud6a8\uc758 \ucc28\uc774\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.RR,1,"\ud310\ub840\ub294 \uc81c\ucc99\uae30\uac04\uc774 \uc801\uc6a9\ub418\ub294 \uad8c\ub9ac, \ud2b9\ud788 \ud615\uc131\uad8c\uc758 \ud589\uc0ac\uc5d0 \uad00\ud558\uc5ec\ub294 \uadf8 \uae30\uac04 \ub0b4\uc5d0 \uc7ac\ud310\uc0c1 \uccad\uad6c\uac00 \uc774\ub8e8\uc5b4\uc838\uc57c \ud55c\ub2e4\uace0 \ubcf4\ub294 \uacbd\uc6b0\uac00 \ub9ce\ub2e4\ub294 \uc785\uc7a5\uc744 \ucde8\ud55c\ub2e4. \ubc18\uba74 \uc18c\uba78\uc2dc\ud6a8\uae30\uac04\uc740 \ubc95\ub960\ud589\uc704\ub85c \uc774\ub97c \ub2e8\ucd95 \ub610\ub294 \uacbd\uac10\ud560 \uc218 \uc788\uc73c\ub098 \ubc30\uc81c\xb7\uc5f0\uc7a5\xb7\uac00\uc911\uc740 \ud560 \uc218 \uc5c6\ub2e4(\ubbfc\ubc95 \uc81c184\uc870 \uc81c2\ud56d).",B.aLC,B.aU0,null)
B.b3l=s(['\ubc95\uc870\ubb38\uc5d0\uc11c "\uc2dc\ud6a8\ub85c \uc778\ud558\uc5ec" \uc18c\uba78\ud55c\ub2e4\uace0 \uaddc\uc815\ud55c \uacbd\uc6b0\uc5d0\ub294 \uc77c\ubc18\uc801\uc73c\ub85c \uc18c\uba78\uc2dc\ud6a8\ub85c \ud574\uc11d\ud55c\ub2e4.','\ubc95\uc870\ubb38\uc5d0\uc11c \ub2e8\uc21c\ud788 "\uadf8 \uae30\uac04 \ub0b4\uc5d0 \ud589\uc0ac\ud558\uc5ec\uc57c \ud55c\ub2e4"\uace0 \uaddc\uc815\ud55c \uacbd\uc6b0\uc5d0\ub294 \uc81c\ucc99\uae30\uac04\uc73c\ub85c \ud574\uc11d\ud558\ub294 \uac83\uc774 \uc77c\ubc18\uc801\uc774\ub2e4.',"\uc18c\uba78\uc2dc\ud6a8\uc640 \uc81c\ucc99\uae30\uac04\uc758 \uad6c\ubcc4\uc740 \uc2e4\uc775\uc774 \uc5c6\uc73c\ubbc0\ub85c \uc5b4\ub290 \ucabd\uc73c\ub85c \ud574\uc11d\ud558\ub354\ub77c\ub3c4 \ubc95\ub960\ud6a8\uacfc\uc5d0 \ucc28\uc774\uac00 \uc5c6\ub2e4.","\ud615\uc131\uad8c\uc5d0\ub294 \ud1b5\uc0c1 \uc81c\ucc99\uae30\uac04\uc774 \uc801\uc6a9\ub418\uace0, \uccad\uad6c\uad8c\uc5d0\ub294 \ud1b5\uc0c1 \uc18c\uba78\uc2dc\ud6a8\uac00 \uc801\uc6a9\ub41c\ub2e4."],t.s)
B.aXd=s(["\uad6c\ubcc4\uc758 \uc2e4\uc775\uc774 \ud06c\ub2e4"],t.s)
B.Ux=s(["\uc81c\ucc99\uae30\uac04\uacfc \uc18c\uba78\uc2dc\ud6a8 \uad6c\ubcc4\uc2e4\uc775","\ud615\uc131\uad8c\xb7\uccad\uad6c\uad8c"],t.s)
B.bqg=new A.a("gen_cl_prescription_20","civil_law","\uc18c\uba78\uc2dc\ud6a8",null,"\uc18c\uba78\uc2dc\ud6a8\uc640 \uc81c\ucc99\uae30\uac04\uc744 \uad6c\ubcc4\ud558\ub294 \uc2e4\uc775 \ubc0f \ud310\ubcc4\uae30\uc900\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.b3l,2,'\uc18c\uba78\uc2dc\ud6a8\uc640 \uc81c\ucc99\uae30\uac04\uc740 \uc911\ub2e8\xb7\uc815\uc9c0\uc758 \uc778\uc815 \uc5ec\ubd80, \uc18c\uae09\ud6a8 \uc720\ubb34, \uc9c1\uad8c\uc870\uc0ac \uc5ec\ubd80, \ud3ec\uae30 \uac00\ub2a5 \uc5ec\ubd80 \ub4f1\uc5d0\uc11c \ubc95\ub960\ud6a8\uacfc\uac00 \ud06c\uac8c \ub2e4\ub974\ubbc0\ub85c \uad6c\ubcc4\uc758 \uc2e4\uc775\uc774 \ud06c\ub2e4. \ubc95\ubb38\uc0c1 "\uc2dc\ud6a8\ub85c \uc778\ud558\uc5ec"\ub77c\ub294 \ud45c\ud604\uc774 \uc788\uc73c\uba74 \uc18c\uba78\uc2dc\ud6a8\ub85c, \ub2e8\uc21c\ud788 \uae30\uac04 \ub0b4 \ud589\uc0ac\ub97c \uc694\uad6c\ud558\uba74 \uc81c\ucc99\uae30\uac04\uc73c\ub85c \ud574\uc11d\ud558\ub294 \uac83\uc774 \uc77c\ubc18\uc801\uc774\ub2e4.',B.aXd,B.Ux,null)
B.b4L=s(["\ud0c0\uc778\uc758 \ubb3c\uac74 \ub610\ub294 \uc720\uac00\uc99d\uad8c\uc744 \uc810\uc720\ud558\uace0 \uc788\uc5b4\uc57c \ud55c\ub2e4.","\uadf8 \ubb3c\uac74\uc5d0 \uad00\ud558\uc5ec \uc0dd\uae34 \ucc44\uad8c\uc774 \uc874\uc7ac\ud558\uc5ec\uc57c \ud55c\ub2e4.","\ucc44\uad8c\uc774 \ubcc0\uc81c\uae30\uc5d0 \uc788\uc5b4\uc57c \ud55c\ub2e4.","\uc810\uc720\uac00 \ubd88\ubc95\ud589\uc704\ub85c \uc778\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \uc720\uce58\uad8c\uc774 \uc131\ub9bd\ud55c\ub2e4."],t.s)
B.bej=s(["\uc810\uc720\uac00 \ubd88\ubc95\ud589\uc704\ub85c \uc778\ud558\uc5ec \uac1c\uc2dc\ub41c \uacbd\uc6b0\uc5d0\ub294 \uc720\uce58\uad8c\uc774 \uc131\ub9bd\ud558\uc9c0 \uc544\ub2c8\ud55c\ub2e4(\uc81c320\uc870 \uc81c2\ud56d)."],t.s)
B.aEo=s(["\uc720\uce58\uad8c \uc131\ub9bd\uc694\uac74","\ubd88\ubc95\uc810\uc720 \ubc30\uc81c"],t.s)
B.bN0=new A.a("gen_cl_security_1","civil_law","\ub2f4\ubcf4\ubb3c\uad8c(\uc720\uce58\uad8c\xb7\uc800\ub2f9\uad8c)",null,"\uc720\uce58\uad8c\uc758 \uc131\ub9bd\uc694\uac74\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.b4L,3,"\ubbfc\ubc95 \uc81c320\uc870\uc5d0 \ub530\ub77c \uc720\uce58\uad8c\uc740 \ud0c0\uc778\uc758 \ubb3c\uac74\uc744 \uc810\uc720\ud55c \uc790\uac00 \uadf8 \ubb3c\uac74\uc5d0 \uad00\ud558\uc5ec \uc0dd\uae34 \ucc44\uad8c\uc744 \uac00\uc9c0\uace0 \ubcc0\uc81c\uae30\uac00 \ub3c4\ub798\ud55c \uacbd\uc6b0 \uc131\ub9bd\ud55c\ub2e4. \ub2e4\ub9cc \uc810\uc720\uac00 \ubd88\ubc95\ud589\uc704\ub85c \uc778\ud558\uc5ec \uac1c\uc2dc\ub41c \uacbd\uc6b0\uc5d0\ub294 \uc720\uce58\uad8c\uc774 \uc131\ub9bd\ud558\uc9c0 \uc544\ub2c8\ud55c\ub2e4(\uc81c320\uc870 \uc81c2\ud56d).",B.bej,B.aEo,null)
B.aFg=s(["\uacac\ub828\uad00\uacc4\ub294 \ucc44\uad8c\uc758 \ubc1c\uc0dd \uc6d0\uc778\uacfc \ubb34\uad00\ud558\uac8c \uc778\uc815\ub41c\ub2e4.","\ubb3c\uac74\uc5d0 \uad00\ud558\uc5ec \uc0dd\uae34 \uc190\ud574\ubc30\uc0c1\ucc44\uad8c\ub3c4 \uacac\ub828\uad00\uacc4\uac00 \uc778\uc815\ub420 \uc218 \uc788\ub2e4.","\ubb3c\uac74\uc758 \ub9e4\ub9e4\ub300\uae08\ucc44\uad8c\uc740 \ud56d\uc0c1 \uacac\ub828\uad00\uacc4\uac00 \uc778\uc815\ub41c\ub2e4.","\uacac\ub828\uad00\uacc4\ub294 \ub2f9\uc0ac\uc790\uc758 \uc57d\uc815\uc73c\ub85c\ub9cc \ucc3d\uc124\ub41c\ub2e4."],t.s)
B.aVm=s(["\ubb3c\uac74\uc5d0 \uad00\ud558\uc5ec \uc0dd\uae34 \uc190\ud574\ubc30\uc0c1\ucc44\uad8c\ub3c4 \uacac\ub828\uad00\uacc4\uac00 \uc778\uc815\ub420 \uc218 \uc788\ub2e4."],t.s)
B.a0I=s(["\uacac\ub828\uad00\uacc4","\uc720\uce58\uad8c \uc131\ub9bd\uc694\uac74"],t.s)
B.boO=new A.a("gen_cl_security_2","civil_law","\ub2f4\ubcf4\ubb3c\uad8c(\uc720\uce58\uad8c\xb7\uc800\ub2f9\uad8c)",null,"\uc720\uce58\uad8c \uc131\ub9bd\uc694\uac74 \uc911 \ucc44\uad8c\uacfc \ubb3c\uac74 \uc0ac\uc774\uc758 \uacac\ub828\uad00\uacc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aFg,1,"\uacac\ub828\uad00\uacc4\ub294 \ucc44\uad8c\uc774 \ubaa9\uc801\ubb3c \uc790\uccb4\ub85c\ubd80\ud130 \ubc1c\uc0dd\ud558\uac70\ub098 \ubaa9\uc801\ubb3c\uc758 \ubc18\ud658\uccad\uad6c\uad8c\uacfc \ub3d9\uc77c\ud55c \ubc95\ub960\uad00\uacc4 \ub610\ub294 \uc0dd\ud65c\uad00\uacc4\uc5d0\uc11c \ubc1c\uc0dd\ud55c \uacbd\uc6b0\uc5d0 \uc778\uc815\ub41c\ub2e4. \uc608\ucee8\ub300 \ubb3c\uac74\uc5d0 \uad00\ud558\uc5ec \uc0dd\uae34 \uc190\ud574\ubc30\uc0c1\ucc44\uad8c\ub3c4 \uacac\ub828\uad00\uacc4\uac00 \uc778\uc815\ub420 \uc218 \uc788\ub2e4. \ud310\ub840\ub294 \uc774\ub97c \uac1c\ubcc4\uc801\uc73c\ub85c \ud310\ub2e8\ud55c\ub2e4.",B.aVm,B.a0I,null)
B.aNh=s(["\uc720\uce58\uad8c\uc790\ub294 \ucc44\uad8c \uc804\ubd80\uc758 \ubcc0\uc81c\ub97c \ubc1b\uc744 \ub54c\uae4c\uc9c0 \uc720\uce58\ubb3c \uc804\ubd80\uc5d0 \ub300\ud558\uc5ec \uadf8 \uad8c\ub9ac\ub97c \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4.","\ucc44\uad8c\uc758 \uc77c\ubd80 \ubcc0\uc81c\uac00 \uc788\uc73c\uba74 \uadf8 \ube44\uc728\ub9cc\ud07c \uc720\uce58\ubb3c\uc758 \uc77c\ubd80\ub97c \ubc18\ud658\ud558\uc5ec\uc57c \ud55c\ub2e4.","\uc720\uce58\ubb3c\uc774 \ubd84\ud560 \uac00\ub2a5\ud55c \uacbd\uc6b0\uc5d0\ub294 \ubd88\uac00\ubd84\uc131\uc774 \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4.","\ubd88\uac00\ubd84\uc131\uc740 \ub2f9\uc0ac\uc790\uc758 \ud2b9\uc57d\uc73c\ub85c \ubc30\uc81c\ud560 \uc218 \uc5c6\ub2e4."],t.s)
B.b8n=s(["\uc720\uce58\uad8c\uc790\ub294 \ucc44\uad8c \uc804\ubd80\uc758 \ubcc0\uc81c\ub97c \ubc1b\uc744 \ub54c\uae4c\uc9c0 \uc720\uce58\ubb3c \uc804\ubd80\uc5d0 \ub300\ud558\uc5ec \uadf8 \uad8c\ub9ac\ub97c \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4\uace0 \uc815\ud55c\ub2e4."],t.s)
