B.Zg=s(["\uc9c0\uc5ed\uad8c\uc740 \uc77c\uc815\ud55c \ubaa9\uc801\uc744 \uc704\ud558\uc5ec \ud0c0\uc778\uc758 \ud1a0\uc9c0\ub97c \uc790\uae30 \ud1a0\uc9c0\uc758 \ud3b8\uc775\uc5d0 \uc774\uc6a9\ud558\ub294 \ubb3c\uad8c\uc774\ub2e4","\uc9c0\uc5ed\uad8c\uc740 \uc694\uc5ed\uc9c0 \uc18c\uc720\uc790 \uac1c\uc778\ub9cc\uc744 \uc704\ud55c \uc778\uc801 \uad8c\ub9ac\uc774\ub2e4","\uc9c0\uc5ed\uad8c\uc740 \ucc44\uad8c\uc774\ubbc0\ub85c \ub4f1\uae30\ud560 \uc218 \uc5c6\ub2e4","\uc9c0\uc5ed\uad8c\uc740 \ubc18\ub4dc\uc2dc \uc720\uc0c1\uc73c\ub85c\ub9cc \uc124\uc815\ud560 \uc218 \uc788\ub2e4"],t.s)
B.aTr=s(["\uc77c\uc815\ud55c \ubaa9\uc801\uc744 \uc704\ud558\uc5ec \ud0c0\uc778\uc758 \ud1a0\uc9c0\ub97c \uc790\uae30 \ud1a0\uc9c0\uc758 \ud3b8\uc775\uc5d0 \uc774\uc6a9\ud558\ub294 \uad8c\ub9ac\ub85c \uc815\uc758\ud55c\ub2e4"],t.s)
