B.brJ=new A.a("gen_cl_usufruct_16","civil_law","\uc6a9\uc775\ubb3c\uad8c(\uc9c0\uc0c1\uad8c)",null,"\uc9c0\uc5ed\uad8c\uc5d0 \uae30\ud55c \ubc29\ud574\uc81c\uac70 \ubc0f \ubc29\ud574\uc608\ubc29\uccad\uad6c\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aPG,1,"\ubbfc\ubc95 \uc81c301\uc870\ub294 \uc9c0\uc5ed\uad8c\uc5d0 \uc81c214\uc870\ub97c \uc900\uc6a9\ud558\uc5ec \ubc29\ud574\uc81c\uac70\uccad\uad6c\uad8c\uacfc \ubc29\ud574\uc608\ubc29\uccad\uad6c\uad8c\uc744 \uc778\uc815\ud558\ub098, \uc9c0\uc5ed\uad8c\uc740 \uc2b9\uc5ed\uc9c0\ub97c \uc810\uc720\ud558\ub294 \uad8c\ub9ac\uac00 \uc544\ub2c8\ubbc0\ub85c \ubaa9\uc801\ubb3c\ubc18\ud658\uccad\uad6c\uad8c\uc5d0 \uad00\ud55c \uaddc\uc815\uc740 \uc900\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4.",B.aez,B.aoh,null)
B.aNy=s(["\uc804\uc138\uad8c\uc740 \uc804\uc138\uae08\uc744 \uc9c0\uae09\ud558\uace0 \ud0c0\uc778\uc758 \ubd80\ub3d9\uc0b0\uc744 \uc810\uc720\ud558\uc5ec \uadf8 \ubd80\ub3d9\uc0b0\uc758 \uc6a9\ub3c4\uc5d0 \uc887\uc544 \uc0ac\uc6a9\xb7\uc218\uc775\ud558\ub294 \uad8c\ub9ac\uc774\ub2e4","\uc804\uc138\uad8c\uc758 \uc874\uc18d\uae30\uac04\uc740 10\ub144\uc744 \ub118\uc9c0 \ubabb\ud55c\ub2e4","\uac74\ubb3c\uc5d0 \ub300\ud55c \uc804\uc138\uad8c\uc758 \ucd5c\ub2e8\uc874\uc18d\uae30\uac04\uc740 1\ub144\uc774\ub2e4","\uc804\uc138\uad8c\uc758 \uc874\uc18d\uae30\uac04\uc740 \ub2f9\uc0ac\uc790\uac00 \uc544\ubb34\ub9ac \uc9e7\uac8c \uc815\ud558\uc5ec\ub3c4 \uadf8 \uc57d\uc815\uc774 \uadf8\ub300\ub85c \uc720\ud6a8\ud558\ub2e4"],t.s)
