B.bBl=new A.a("gen_cl_usufruct_20","civil_law","\uc6a9\uc775\ubb3c\uad8c(\uc9c0\uc0c1\uad8c)",null,"\uc804\uc138\uad8c\uc758 \uc874\uc18d\uae30\uac04 \ub9cc\ub8cc \uc2dc \ubc95\uc815\uac31\uc2e0(\ubb35\uc2dc\uc758 \uac31\uc2e0)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.auO,0,"\ubbfc\ubc95 \uc81c312\uc870 \uc81c4\ud56d\uc740 \uac74\ubb3c\uc804\uc138\uad8c\uc5d0\uc11c \uc804\uc138\uad8c\uc124\uc815\uc790\uac00 \uc874\uc18d\uae30\uac04 \ub9cc\ub8cc \uc804 6\uc6d4\ubd80\ud130 1\uc6d4\uae4c\uc9c0 \uc0ac\uc774\uc5d0 \uac31\uc2e0\uac70\uc808 \ub610\ub294 \uc870\uac74\ubcc0\uacbd\uc758 \ud1b5\uc9c0\ub97c \ud558\uc9c0 \uc544\ub2c8\ud558\uba74 \uadf8 \uae30\uac04\uc774 \ub9cc\ub8cc\ub41c \ub54c\uc5d0 \uc804 \uc804\uc138\uad8c\uacfc \ub3d9\uc77c\ud55c \uc870\uac74\uc73c\ub85c \ub2e4\uc2dc \uc804\uc138\uad8c\uc744 \uc124\uc815\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4\uace0 \uaddc\uc815\ud558\uba70, \uc774 \uacbd\uc6b0 \uadf8 \uc874\uc18d\uae30\uac04\uc740 \uc815\ud568\uc774 \uc5c6\ub294 \uac83\uc73c\ub85c \ubcf8\ub2e4.",B.a_k,B.aQG,null)
B.aPZ=s(["\ubc95\ub960 \u2192 \uad00\uc2b5\ubc95 \u2192 \uc870\ub9ac","\uad00\uc2b5\ubc95 \u2192 \ubc95\ub960 \u2192 \uc870\ub9ac","\uc870\ub9ac \u2192 \ubc95\ub960 \u2192 \uad00\uc2b5\ubc95","\ubc95\ub960 \u2192 \uc870\ub9ac \u2192 \uad00\uc2b5\ubc95"],t.s)
B.amX=s(["\ubbfc\uc0ac\uc5d0 \uad00\ud558\uc5ec \ubc95\ub960\uc5d0 \uaddc\uc815\uc774 \uc5c6\uc73c\uba74 \uad00\uc2b5\ubc95\uc5d0 \uc758\ud558\uace0 \uad00\uc2b5\ubc95\uc774 \uc5c6\uc73c\uba74 \uc870\ub9ac\uc5d0 \uc758\ud55c\ub2e4"],t.s)
