B.bqj=new A.a("gen_cl_source_2","civil_law","\ubbfc\ubc95\uc758 \ubc95\uc6d0(\u6cd5\u6e90)",null,"\uad00\uc2b5\ubc95\uc774 \uc131\ub9bd\ud558\uae30 \uc704\ud55c \uc694\uac74\uc73c\ub85c \ud310\ub840\uac00 \uc694\uad6c\ud558\ub294 \uac83\uc740?",B.a0q,0,"\ud310\ub840\ub294 \uad00\uc2b5\ubc95\uc774 \uc131\ub9bd\ud558\ub824\uba74 \uc5b4\ub5a4 \uc0ac\ud56d\uc5d0 \uad00\ud55c \uc0ac\ud68c\uc758 \uad00\ud589\uc774 \uacc4\uc18d\uc801\uc73c\ub85c \ubc18\ubcf5\ub418\uace0, \uadf8 \uad00\ud589\uc774 \ubc95\uc801 \uaddc\ubc94\uc73c\ub85c\uc11c \uad6d\ubbfc\uc758 \ubc95\uc801 \ud655\uc2e0\uc744 \uc5bb\uc5b4 \uac15\ud589\ub418\uae30\uc5d0 \uc774\ub978 \uac83\uc774\uc5b4\uc57c \ud55c\ub2e4\uace0 \ubcf8\ub2e4. \ub2e8\uc21c\ud55c \uad00\ud589\ub9cc\uc73c\ub85c\ub294 \ubd80\uc871\ud558\uace0 \ubc95\uc801 \ud655\uc2e0\uc774\ub77c\ub294 \uc694\uac74\uc774 \uac16\ucd94\uc5b4\uc838\uc57c \uad00\uc2b5\ubc95\uc73c\ub85c \uc778\uc815\ub41c\ub2e4.",B.aKl,B.a3C,null)
B.aST=s(["\uad00\uc2b5\ubc95\uc740 \ubc95\uc801 \ud655\uc2e0\uc744 \uc5bb\uc5b4 \ubc95\uc6d0\uc73c\ub85c\uc11c \ud6a8\ub825\uc744 \uac16\uc9c0\ub9cc, \uc0ac\uc2e4\uc778 \uad00\uc2b5\uc740 \ubc95\uc801 \ud655\uc2e0\uc5d0 \uc774\ub974\uc9c0 \ubabb\ud55c \uad00\ud589\uc73c\ub85c \ubc95\ub960\ud589\uc704 \ud574\uc11d\uc758 \uae30\uc900\uc774 \ub420 \ubfd0\uc774\ub2e4","\uc0ac\uc2e4\uc778 \uad00\uc2b5\uc740 \uad00\uc2b5\ubc95\ubcf4\ub2e4 \uc0c1\uc704\uc758 \ud6a8\ub825\uc744 \uac00\uc9c4\ub2e4","\uad00\uc2b5\ubc95\uacfc \uc0ac\uc2e4\uc778 \uad00\uc2b5\uc740 \ub3d9\uc77c\ud55c \uac1c\ub150\uc73c\ub85c \uad6c\ubcc4\ud560 \uc2e4\uc775\uc774 \uc5c6\ub2e4","\uc0ac\uc2e4\uc778 \uad00\uc2b5\uc740 \ubc95\uc6d0(\u6cd5\u9662)\uc758 \uc7ac\ud310\uc5d0 \uc758\ud574\uc11c\ub9cc \uc131\ub9bd\ud55c\ub2e4"],t.s)
