B.bKA=new A.a("gen_cl_source_4","civil_law","\ubbfc\ubc95\uc758 \ubc95\uc6d0(\u6cd5\u6e90)",null,"\uc2e0\uc758\uc131\uc2e4\uc758 \uc6d0\uce59\uc744 \uaddc\uc815\ud55c \ubbfc\ubc95 \uc870\ubb38\uc740?",B.a7_,0,'\ubbfc\ubc95 \uc81c2\uc870 \uc81c1\ud56d\uc740 "\uad8c\ub9ac\uc758 \ud589\uc0ac\uc640 \uc758\ubb34\uc758 \uc774\ud589\uc740 \uc2e0\uc758\uc5d0 \uc887\uc544 \uc131\uc2e4\ud788 \ud558\uc5ec\uc57c \ud55c\ub2e4"\uace0 \uaddc\uc815\ud558\uc5ec \uc2e0\uc758\uc131\uc2e4\uc758 \uc6d0\uce59\uc744 \uba85\ubb38\ud654\ud558\uace0 \uc788\ub2e4. \uc774\ub294 \ubbfc\ubc95 \uc804\ubc18\uc744 \uc9c0\ubc30\ud558\ub294 \ub300\uc6d0\uce59\uc73c\ub85c \uacc4\uc57d \ud574\uc11d \ubc0f \uad8c\ub9ac \ud589\uc0ac\uc758 \ud55c\uacc4\ub97c \uc124\uc815\ud55c\ub2e4.',B.aNV,B.bb4,null)
