B.bMG=new A.a("gen_cl_contractgen_20","civil_law","\uacc4\uc57d\ucd1d\ub860(\uc131\ub9bd\xb7\ub3d9\uc2dc\uc774\ud589\xb7\ud574\uc81c \ub4f1)",null,"\ud574\uc81c\uc640 \uc190\ud574\ubc30\uc0c1\uc758 \uad00\uacc4(\ubbfc\ubc95 \uc81c551\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.b0A,0,"\ubbfc\ubc95 \uc81c551\uc870\ub294 \uacc4\uc57d\ud574\uc81c\uad8c\uc758 \ud589\uc0ac\ub294 \uc190\ud574\ubc30\uc0c1\uc758 \uccad\uad6c\uc5d0 \uc601\ud5a5\uc744 \ubbf8\uce58\uc9c0 \uc544\ub2c8\ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc989 \ucc44\ubb34\ubd88\uc774\ud589\uc744 \uc774\uc720\ub85c \uacc4\uc57d\uc744 \ud574\uc81c\ud558\uba74\uc11c \ub3d9\uc2dc\uc5d0 \uadf8\ub85c \uc778\ud55c \uc190\ud574\ubc30\uc0c1\ub3c4 \uccad\uad6c\ud560 \uc218 \uc788\uc73c\uba70, \ub450 \uad8c\ub9ac\ub294 \uc591\ub9bd \uac00\ub2a5\ud558\ub2e4.",B.aeJ,B.awD,null)
B.aLF=s(["\ub2f9\uc0ac\uc790 \uc77c\ubc29\uc774 \uadf8 \ucc44\ubb34\ub97c \uc774\ud589\ud558\uc9c0 \uc544\ub2c8\ud558\ub294 \ub54c\uc5d0\ub294 \uc0c1\ub300\ubc29\uc740 \uc0c1\ub2f9\ud55c \uae30\uac04\uc744 \uc815\ud558\uc5ec \uc774\ud589\uc744 \ucd5c\uace0\ud558\uace0 \uadf8 \uae30\uac04 \ub0b4\uc5d0 \uc774\ud589\ud558\uc9c0 \uc544\ub2c8\ud55c \ub54c\uc5d0 \uacc4\uc57d\uc744 \ud574\uc81c\ud560 \uc218 \uc788\ub2e4","\ucc44\ubb34\uc790\uac00 \ubbf8\ub9ac \uc774\ud589\ud558\uc9c0 \uc544\ub2c8\ud560 \uc758\uc0ac\ub97c \ud45c\uc2dc\ud55c \uacbd\uc6b0\uc5d0\ub294 \ucd5c\uace0\ub97c \uc694\ud558\uc9c0 \uc544\ub2c8\ud55c\ub2e4","\uc815\uae30\ud589\uc704\uc758 \uacbd\uc6b0\uc5d0\ub3c4 \ubc18\ub4dc\uc2dc \ucd5c\uace0\ub97c \ud558\uc5ec\uc57c \uacc4\uc57d\uc744 \ud574\uc81c\ud560 \uc218 \uc788\ub2e4","\ucd5c\uace0\uae30\uac04\uc744 \uc815\ud558\uc9c0 \uc544\ub2c8\ud558\uace0 \ucd5c\uace0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ucd5c\uace0 \ud6c4 \uc0c1\ub2f9\ud55c \uae30\uac04\uc774 \uacbd\uacfc\ud558\uba74 \ud574\uc81c\ud560 \uc218 \uc788\ub2e4\ub294 \uac83\uc774 \ud310\ub840\uc774\ub2e4"],t.s)
