B.bIV=new A.a("gen_cl_realright_5","civil_law","\ubb3c\uad8c\ubcc0\ub3d9\xb7\uc810\uc720\xb7\ucd1d\uc720",null,"\ub4f1\uae30\uc758 \ucd94\uc815\ub825\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.b18,3,"\ub4f1\uae30\uc758 \ucd94\uc815\ub825\uc740 \ub4f1\uae30\uba85\uc758\uc790\uac00 \uc801\ubc95\ud55c \ub4f1\uae30\uc6d0\uc778\uc5d0 \uc758\ud558\uc5ec \ubb3c\uad8c\uc744 \ucde8\ub4dd\ud55c \uac83\uc73c\ub85c \ucd94\uc815\ub418\ub294 \ud6a8\ub825\uc744 \uc758\ubbf8\ud558\ub098, \uc774\ub294 \ubc95\ub960\uc0c1 \ucd94\uc815\uc5d0 \ubd88\uacfc\ud558\uc5ec \ubc18\uc99d\uc5d0 \uc758\ud574 \ubc88\ubcf5\ub420 \uc218 \uc788\ub2e4. \ub4f1\uae30\ubd80\uc0c1 \uc804 \uc18c\uc720\uba85\uc758\uc778\uc774 \uc0ac\ub9dd\uc790\ub85c \uae30\uc7ac\ub418\ub294 \ub4f1 \ud2b9\ubcc4\ud55c \uc0ac\uc815\uc774 \uc788\uc73c\uba74 \ucd94\uc815\ub825\uc774 \uae68\uc9c4\ub2e4.",B.aBi,B.bfO,null)
B.aTe=s(["\ub3d9\uc0b0\uc5d0 \uad00\ud55c \ubb3c\uad8c\uc758 \uc591\ub3c4\ub294 \uadf8 \ub3d9\uc0b0\uc744 \uc778\ub3c4\ud558\uc5ec\uc57c \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4.","\ub3d9\uc0b0\ubb3c\uad8c\uc758 \uc591\ub3c4\ub294 \ub2f9\uc0ac\uc790\uc758 \ud569\uc758\ub9cc\uc73c\ub85c \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4.","\ub3d9\uc0b0\ubb3c\uad8c\uc758 \uc591\ub3c4\ub294 \ub4f1\uae30\ud558\uc5ec\uc57c \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4.","\ub3d9\uc0b0\ubb3c\uad8c\uc758 \uc591\ub3c4\ub294 \uacf5\uc2dc\ucd5c\uace0\ub97c \uac70\uccd0\uc57c \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4."],t.s)
B.au3=s(["\uadf8 \ub3d9\uc0b0\uc744 \uc778\ub3c4\ud558\uc5ec\uc57c \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4"],t.s)
B.bhP=s(["\uc81c188\uc870","\uc778\ub3c4"],t.s)
B.bOg=new A.a("gen_cl_realright_6","civil_law","\ubb3c\uad8c\ubcc0\ub3d9\xb7\uc810\uc720\xb7\ucd1d\uc720",null,"\ub3d9\uc0b0\ubb3c\uad8c \uc591\ub3c4\uc758 \ud6a8\ub825\uc694\uac74\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aTe,0,"\ubbfc\ubc95 \uc81c188\uc870 \uc81c1\ud56d\uc740 \ub3d9\uc0b0\uc5d0 \uad00\ud55c \ubb3c\uad8c\uc758 \uc591\ub3c4\ub294 \uadf8 \ub3d9\uc0b0\uc744 \uc778\ub3c4\ud558\uc5ec\uc57c \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ubd80\ub3d9\uc0b0\uc774 \ub4f1\uae30\ub97c \uacf5\uc2dc\ubc29\ubc95\uc73c\ub85c \ud558\ub294 \uac83\uacfc \ub2ec\ub9ac \ub3d9\uc0b0\uc740 \uc778\ub3c4\uac00 \ubb3c\uad8c\ubcc0\ub3d9\uc758 \uc131\ub9bd\uc694\uac74\uc774 \ub41c\ub2e4.",B.au3,B.bhP,null)
B.a5h=s(["\uc591\uc218\uc778\uc774 \uc774\ubbf8 \uadf8 \ub3d9\uc0b0\uc744 \uc810\uc720\ud55c \ub54c\uc5d0\ub294 \ub2f9\uc0ac\uc790\uc758 \uc758\uc0ac\ud45c\uc2dc\ub9cc\uc73c\ub85c \uc778\ub3c4\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4.","\uac04\uc774\uc778\ub3c4\ub294 \ubaa9\uc801\ubb3c\ubc18\ud658\uccad\uad6c\uad8c\uc758 \uc591\ub3c4\ub97c \ud1b5\ud574\uc11c\ub9cc \uac00\ub2a5\ud558\ub2e4.","\uac04\uc774\uc778\ub3c4\ub294 \ubd80\ub3d9\uc0b0 \ubb3c\uad8c\ubcc0\ub3d9\uc5d0\ub9cc \uc801\uc6a9\ub41c\ub2e4.","\uac04\uc774\uc778\ub3c4\ub294 \ubc18\ub4dc\uc2dc \ud604\uc2e4\uc758 \uc778\ub3c4\ub97c \uc218\ubc18\ud558\uc5ec\uc57c \ud55c\ub2e4."],t.s)
B.aBe=s(["\uc591\uc218\uc778\uc774 \uc774\ubbf8 \uadf8 \ub3d9\uc0b0\uc744 \uc810\uc720\ud55c \ub54c\uc5d0\ub294 \ub2f9\uc0ac\uc790\uc758 \uc758\uc0ac\ud45c\uc2dc\ub9cc\uc73c\ub85c \uc778\ub3c4\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4"],t.s)
B.b0G=s(["\uac04\uc774\uc778\ub3c4","\uc81c188\uc870 \uc81c2\ud56d"],t.s)
B.bsd=new A.a("gen_cl_realright_7","civil_law","\ubb3c\uad8c\ubcc0\ub3d9\xb7\uc810\uc720\xb7\ucd1d\uc720",null,"\uac04\uc774\uc778\ub3c4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.a5h,0,"\ubbfc\ubc95 \uc81c188\uc870 \uc81c2\ud56d\uc740 \uc591\uc218\uc778\uc774 \uc774\ubbf8 \uadf8 \ub3d9\uc0b0\uc744 \uc810\uc720\ud55c \ub54c\uc5d0\ub294 \ub2f9\uc0ac\uc790\uc758 \uc758\uc0ac\ud45c\uc2dc\ub9cc\uc73c\ub85c \uc778\ub3c4\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4\uace0 \uaddc\uc815\ud558\uc5ec \uac04\uc774\uc778\ub3c4\ub97c \uc778\uc815\ud55c\ub2e4. \uc774\ub294 \ud604\uc2e4\uc758 \uc778\ub3c4 \uc5c6\uc774\ub3c4 \uc758\uc0ac\ud45c\uc2dc\ub9cc\uc73c\ub85c \uc778\ub3c4\uc758 \ud6a8\ub825\uc744 \uc778\uc815\ud558\ub294 \uad00\ub150\uc801 \uc778\ub3c4 \ubc29\uc2dd\uc774\ub2e4.",B.aBe,B.b0G,null)
B.RZ=s(["\ub2f9\uc0ac\uc790\uc758 \uacc4\uc57d\uc73c\ub85c \uc591\ub3c4\uc778\uc774 \uadf8 \ub3d9\uc0b0\uc758 \uc810\uc720\ub97c \uacc4\uc18d\ud558\ub294 \uacbd\uc6b0 \uc591\uc218\uc778\uc774 \uc778\ub3c4\ubc1b\uc740 \uac83\uc73c\ub85c \ubcf8\ub2e4.","\uc810\uc720\uac1c\uc815\uc740 \uc120\uc758\ucde8\ub4dd\uc758 \uc694\uac74\uc778 \uc778\ub3c4\ub85c \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4\ub294 \uac83\uc774 \ud310\ub840\uc774\ub2e4.","\uc810\uc720\uac1c\uc815\uc740 \ubd80\ub3d9\uc0b0\uc5d0\ub9cc \uc801\uc6a9\ub418\ub294 \uc778\ub3c4\ubc29\uc2dd\uc774\ub2e4.","\uc810\uc720\uac1c\uc815\uc740 \ud604\uc2e4\uc758 \uc778\ub3c4\uc640 \ub3d9\uc77c\ud55c \uacf5\uc2dc\ud6a8\uacfc\ub97c \uac16\ub294\ub2e4."],t.s)
B.bdP=s(["\uc810\uc720\uac1c\uc815\uc5d0 \uc758\ud55c \uc810\uc720\ucde8\ub4dd\ub9cc\uc73c\ub85c\ub294 \uc81c249\uc870\uc758 \uc778\ub3c4 \uc694\uac74\uc744 \ucda9\uc871\ud558\uc9c0 \ubabb\ud55c\ub2e4"],t.s)
B.b0c=s(["\uc810\uc720\uac1c\uc815","\uc120\uc758\ucde8\ub4dd\uacfc\uc758 \uad00\uacc4"],t.s)
B.bFU=new A.a("gen_cl_realright_8","civil_law","\ubb3c\uad8c\ubcc0\ub3d9\xb7\uc810\uc720\xb7\ucd1d\uc720",null,"\uc810\uc720\uac1c\uc815\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.RZ,1,"\ubbfc\ubc95 \uc81c189\uc870\ub294 \uc810\uc720\uac1c\uc815\uc5d0 \uad00\ud558\uc5ec \ub2f9\uc0ac\uc790\uc758 \uacc4\uc57d\uc73c\ub85c \uc591\ub3c4\uc778\uc774 \uadf8 \ub3d9\uc0b0\uc758 \uc810\uc720\ub97c \uacc4\uc18d\ud558\ub294 \uacbd\uc6b0 \uc591\uc218\uc778\uc774 \uc778\ub3c4\ubc1b\uc740 \uac83\uc73c\ub85c \ubcf8\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ub2e4\ub9cc \ud310\ub840\ub294 \uc120\uc758\ucde8\ub4dd\uc5d0 \uc788\uc5b4\uc11c\ub294 \uc810\uc720\uac1c\uc815\uc5d0 \uc758\ud55c \uc810\uc720\ucde8\ub4dd\ub9cc\uc73c\ub85c\ub294 \uc81c249\uc870\uc758 \uc778\ub3c4 \uc694\uac74\uc744 \ucda9\uc871\ud558\uc9c0 \ubabb\ud55c\ub2e4\uace0 \ubcf8\ub2e4.",B.bdP,B.b0c,null)
B.aMw=s(["\uc81c3\uc790\uac00 \uc810\uc720\ud558\uace0 \uc788\ub294 \ub3d9\uc0b0\uc5d0 \uad00\ud55c \ubb3c\uad8c\uc744 \uc591\ub3c4\ud558\ub294 \uacbd\uc6b0 \uc591\ub3c4\uc778\uc774 \uadf8 \uc81c3\uc790\uc5d0 \ub300\ud55c \ubc18\ud658\uccad\uad6c\uad8c\uc744 \uc591\uc218\uc778\uc5d0\uac8c \uc591\ub3c4\ud568\uc73c\ub85c\uc368 \ub3d9\uc0b0\uc744 \uc778\ub3c4\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4.","\ubaa9\uc801\ubb3c\ubc18\ud658\uccad\uad6c\uad8c\uc758 \uc591\ub3c4\ub294 \ub4f1\uae30\ub97c \uac16\ucd94\uc5b4\uc57c \uc778\ub3c4\uc758 \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4.","\ubaa9\uc801\ubb3c\ubc18\ud658\uccad\uad6c\uad8c\uc758 \uc591\ub3c4\ub294 \ubd80\ub3d9\uc0b0\uc5d0\ub9cc \uc801\uc6a9\ub41c\ub2e4.","\ubaa9\uc801\ubb3c\ubc18\ud658\uccad\uad6c\uad8c\uc758 \uc591\ub3c4\ub294 \ubc18\ub4dc\uc2dc \uc81c3\uc790\uc758 \ub3d9\uc758\ub97c \uc5bb\uc5b4\uc57c \ud55c\ub2e4."],t.s)
B.XO=s(["\uadf8 \uc81c3\uc790\uc5d0 \ub300\ud55c \ubc18\ud658\uccad\uad6c\uad8c\uc744 \uc591\uc218\uc778\uc5d0\uac8c \uc591\ub3c4\ud568\uc73c\ub85c\uc368 \ub3d9\uc0b0\uc744 \uc778\ub3c4\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4"],t.s)
B.alH=s(["\ubaa9\uc801\ubb3c\ubc18\ud658\uccad\uad6c\uad8c\uc758 \uc591\ub3c4","\uc81c190\uc870"],t.s)
B.bMe=new A.a("gen_cl_realright_9","civil_law","\ubb3c\uad8c\ubcc0\ub3d9\xb7\uc810\uc720\xb7\ucd1d\uc720",null,"\ubaa9\uc801\ubb3c\ubc18\ud658\uccad\uad6c\uad8c\uc758 \uc591\ub3c4\uc5d0 \uc758\ud55c \uc778\ub3c4(\ubbfc\ubc95 \uc81c190\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aMw,0,"\ubbfc\ubc95 \uc81c190\uc870\ub294 \uc81c3\uc790\uac00 \uc810\uc720\ud558\uace0 \uc788\ub294 \ub3d9\uc0b0\uc5d0 \uad00\ud55c \ubb3c\uad8c\uc744 \uc591\ub3c4\ud558\ub294 \uacbd\uc6b0\uc5d0 \uc591\ub3c4\uc778\uc774 \uadf8 \uc81c3\uc790\uc5d0 \ub300\ud55c \ubc18\ud658\uccad\uad6c\uad8c\uc744 \uc591\uc218\uc778\uc5d0\uac8c \uc591\ub3c4\ud568\uc73c\ub85c\uc368 \ub3d9\uc0b0\uc744 \uc778\ub3c4\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc774\ub97c \ubaa9\uc801\ubb3c\ubc18\ud658\uccad\uad6c\uad8c\uc758 \uc591\ub3c4, \ub610\ub294 \uc9c0\uc2dc\uc5d0 \uc758\ud55c \uc778\ub3c4\ub77c\uace0 \ud55c\ub2e4.",B.XO,B.alH,null)
B.aSl=s(["\ubaa9\uc801\ubb3c\uc774 \ub3d9\uc0b0\uc77c \uac83","\uc591\ub3c4\uc778\uc5d0\uac8c \ucc98\ubd84\uad8c\ud55c\uc774 \uc5c6\uc744 \uac83","\uc591\uc218\uc778\uc774 \ud3c9\uc628\xb7\uacf5\uc5f0\ud558\uac8c \uc120\uc758\uc774\uba70 \uacfc\uc2e4 \uc5c6\uc774 \uadf8 \ub3d9\uc0b0\uc758 \uc810\uc720\ub97c \ucde8\ub4dd\ud560 \uac83","\uc591\uc218\uc778\uc774 \uc810\uc720\uac1c\uc815\uc758 \ubc29\ubc95\uc73c\ub85c \uc810\uc720\ub97c \ucde8\ub4dd\ud558\uc600\uc744 \uac83"],t.s)
B.a4w=s(["\uc810\uc720\uac1c\uc815\uc5d0 \uc758\ud55c \uc810\uc720\ucde8\ub4dd\uc740 \uc120\uc758\ucde8\ub4dd\uc758 \uc694\uac74\uc778 \uc810\uc720\ucde8\ub4dd\uc5d0 \ud574\ub2f9\ud558\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.avL=s(["\uc120\uc758\ucde8\ub4dd","\uc81c249\uc870"],t.s)
B.bp1=new A.a("gen_cl_realright_10","civil_law","\ubb3c\uad8c\ubcc0\ub3d9\xb7\uc810\uc720\xb7\ucd1d\uc720",null,"\uc120\uc758\ucde8\ub4dd\uc5d0 \uad00\ud55c \ubbfc\ubc95 \uc81c249\uc870\uc758 \uc694\uac74\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aSl,3,"\ubbfc\ubc95 \uc81c249\uc870\ub294 \ud3c9\uc628\xb7\uacf5\uc5f0\ud558\uac8c \uc120\uc758\uc774\uba70 \uacfc\uc2e4 \uc5c6\uc774 \ub3d9\uc0b0\uc744 \uc591\uc218\ud55c \uc790\ub294 \uc591\ub3c4\uc778\uc774 \uc815\ub2f9\ud55c \uc18c\uc720\uc790\uac00 \uc544\ub2cc \uacbd\uc6b0\uc5d0\ub3c4 \uc989\uc2dc \uadf8 \ub3d9\uc0b0\uc758 \uc18c\uc720\uad8c\uc744 \ucde8\ub4dd\ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ud310\ub840\ub294 \uc810\uc720\uac1c\uc815\uc5d0 \uc758\ud55c \uc810\uc720\ucde8\ub4dd\uc740 \uc120\uc758\ucde8\ub4dd\uc758 \uc694\uac74\uc778 \uc810\uc720\ucde8\ub4dd\uc5d0 \ud574\ub2f9\ud558\uc9c0 \uc54a\ub294\ub2e4\uace0 \ubcf8\ub2e4.",B.a4w,B.avL,null)
B.b90=s(["\uc810\uc720\ubb3c\uc774 \ub3c4\ud488\uc774\ub098 \uc720\uc2e4\ubb3c\uc778 \uacbd\uc6b0 \ud53c\ud574\uc790 \ub610\ub294 \uc720\uc2e4\uc790\ub294 \ub3c4\ub09c \ub610\ub294 \uc720\uc2e4\ud55c \ub0a0\ub85c\ubd80\ud130 2\ub144 \ub0b4\uc5d0 \uadf8 \ubb3c\uac74\uc758 \ubc18\ud658\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4.","\ub3c4\ud488\xb7\uc720\uc2e4\ubb3c\uc758 \uacbd\uc6b0\uc5d0\ub3c4 \uc120\uc758\ucde8\ub4dd\uc790\ub294 \ubc18\ud658\uccad\uad6c\ub97c \uc804\ud600 \uac70\ubd80\ud560 \uc218 \uc5c6\ub2e4.","\ub3c4\ud488\xb7\uc720\uc2e4\ubb3c\uc5d0 \ub300\ud574\uc11c\ub294 \uc120\uc758\ucde8\ub4dd\uc774 \uc131\ub9bd\ud560 \uc5ec\uc9c0\uac00 \uc804\ud600 \uc5c6\ub2e4.","\ubc18\ud658\uccad\uad6c\uad8c\uc758 \ud589\uc0ac\uae30\uac04\uc740 \ub3c4\ub09c \ub610\ub294 \uc720\uc2e4\uc77c\ub85c\ubd80\ud130 10\ub144\uc774\ub2e4."],t.s)
B.aGQ=s(["\ub3c4\ub09c \ub610\ub294 \uc720\uc2e4\ud55c \ub0a0\ub85c\ubd80\ud130 2\ub144 \ub0b4\uc5d0 \uadf8 \ubb3c\uac74\uc758 \ubc18\ud658\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.axp=s(["\uc81c250\uc870","\ub3c4\ud488\xb7\uc720\uc2e4\ubb3c \ud2b9\uce59"],t.s)
B.bzH=new A.a("gen_cl_realright_11","civil_law","\ubb3c\uad8c\ubcc0\ub3d9\xb7\uc810\uc720\xb7\ucd1d\uc720",null,"\ub3c4\ud488 \ubc0f \uc720\uc2e4\ubb3c\uc5d0 \uad00\ud55c \uc120\uc758\ucde8\ub4dd\uc758 \ud2b9\uce59(\ubbfc\ubc95 \uc81c250\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.b90,0,"\ubbfc\ubc95 \uc81c250\uc870\ub294 \uc810\uc720\ubb3c\uc774 \ub3c4\ud488\uc774\ub098 \uc720\uc2e4\ubb3c\uc778 \ub54c\uc5d0\ub294 \ud53c\ud574\uc790 \ub610\ub294 \uc720\uc2e4\uc790\ub294 \ub3c4\ub09c \ub610\ub294 \uc720\uc2e4\ud55c \ub0a0\ub85c\ubd80\ud130 2\ub144 \ub0b4\uc5d0 \uadf8 \ubb3c\uac74\uc758 \ubc18\ud658\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc774\ub294 \uc6d0\uc18c\uc720\uc790 \ubcf4\ud638\ub97c \uc704\ud574 \uc120\uc758\ucde8\ub4dd\uc758 \ud6a8\ub825\uc744 \uc77c\uc815 \uae30\uac04 \uc81c\ud55c\ud558\ub294 \ud2b9\uce59\uc774\ub2e4.",B.aGQ,B.axp,null)
B.a7l=s(["\uac00\uc0ac\uc0c1, \uc601\uc5c5\uc0c1 \uae30\ud0c0 \uc720\uc0ac\ud55c \uad00\uacc4\uc5d0 \uc758\ud558\uc5ec \ud0c0\uc778\uc758 \uc9c0\uc2dc\ub97c \ubc1b\uc544 \ubb3c\uac74\uc5d0 \ub300\ud55c \uc0ac\uc2e4\uc0c1\uc758 \uc9c0\ubc30\ub97c \ud558\ub294 \uc790\ub294 \uc810\uc720\uc790\uac00 \uc544\ub2c8\ub2e4.","\uc810\uc720\ubcf4\uc870\uc790\ub3c4 \ub3c5\ub9bd\ud558\uc5ec \uc810\uc720\uad8c\uc744 \uac00\uc9c0\uba70 \uc810\uc720\ubcf4\ud638\uccad\uad6c\uad8c\uc744 \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4.","\uc810\uc720\ubcf4\uc870\uc790\ub294 \uc810\uc720\ub9e4\uac1c\uad00\uacc4\uc758 \uc9c1\uc811\uc810\uc720\uc790\uc5d0 \ud574\ub2f9\ud55c\ub2e4.","\uc810\uc720\ubcf4\uc870\uc790\ub294 \uc18c\uc720\uc758 \uc758\uc0ac\ub85c \ubb3c\uac74\uc744 \uc810\uc720\ud558\ub294 \uc790\ub97c \ub9d0\ud55c\ub2e4."],t.s)
B.ack=s(["\ud0c0\uc778\uc758 \uc9c0\uc2dc\ub97c \ubc1b\uc544 \ubb3c\uac74\uc5d0 \ub300\ud55c \uc0ac\uc2e4\uc0c1\uc758 \uc9c0\ubc30\ub97c \ud558\ub294 \uc790, \uc989 \uc810\uc720\ubcf4\uc870\uc790\ub294 \uc810\uc720\uc790\uac00 \uc544\ub2c8\ub77c\uace0 \uaddc\uc815\ud55c\ub2e4"],t.s)
B.aCc=s(["\uc810\uc720\ubcf4\uc870\uc790","\uc81c195\uc870"],t.s)
B.bEA=new A.a("gen_cl_realright_12","civil_law","\ubb3c\uad8c\ubcc0\ub3d9\xb7\uc810\uc720\xb7\ucd1d\uc720",null,"\uc810\uc720\ubcf4\uc870\uc790\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.a7l,0,"\ubbfc\ubc95 \uc81c195\uc870\ub294 \uac00\uc0ac\uc0c1, \uc601\uc5c5\uc0c1 \uae30\ud0c0 \uc720\uc0ac\ud55c \uad00\uacc4\uc5d0 \uc758\ud558\uc5ec \ud0c0\uc778\uc758 \uc9c0\uc2dc\ub97c \ubc1b\uc544 \ubb3c\uac74\uc5d0 \ub300\ud55c \uc0ac\uc2e4\uc0c1\uc758 \uc9c0\ubc30\ub97c \ud558\ub294 \uc790, \uc989 \uc810\uc720\ubcf4\uc870\uc790\ub294 \uc810\uc720\uc790\uac00 \uc544\ub2c8\ub77c\uace0 \uaddc\uc815\ud55c\ub2e4. \uc810\uc720\ubcf4\uc870\uc790\ub294 \ub3c5\ub9bd\ud55c \uc810\uc720\uad8c\uc774 \uc5c6\uc73c\ubbc0\ub85c \uc810\uc720\ubcf4\ud638\uccad\uad6c\uad8c\uc744 \ud589\uc0ac\ud560 \uc218 \uc5c6\ub2e4.",B.ack,B.aCc,null)
B.aEz=s(["\uc810\uc720\uc790\uc758 \uc2b9\uacc4\uc778\uc740 \uc790\uae30\uc758 \uc810\uc720\ub9cc\uc744 \uc8fc\uc7a5\ud558\uac70\ub098 \uc790\uae30\uc758 \uc810\uc720\uc640 \uc804 \uc810\uc720\uc790\uc758 \uc810\uc720\ub97c \uc544\uc6b8\ub7ec \uc8fc\uc7a5\ud560 \uc218 \uc788\ub2e4.","\uc810\uc720\uc758 \uc2b9\uacc4\ub294 \ud56d\uc0c1 \uc804 \uc810\uc720\uc790\uc758 \ud558\uc790\uae4c\uc9c0 \ud568\uaed8 \uc2b9\uacc4\ub41c\ub2e4.","\uc810\uc720\uc790\uc758 \uc2b9\uacc4\uc778\uc740 \uc804 \uc810\uc720\uc790\uc758 \uc810\uc720\ub9cc\uc744 \uc8fc\uc7a5\ud558\uc5ec\uc57c \ud55c\ub2e4.","\uc810\uc720\uc758 \uc2b9\uacc4\uc5d0\ub294 \ubc18\ub4dc\uc2dc \ub4f1\uae30\uac00 \uc218\ubc18\ub418\uc5b4\uc57c \ud55c\ub2e4."],t.s)
B.Y6=s(["\uc790\uae30\uc758 \uc810\uc720\ub9cc\uc744 \uc8fc\uc7a5\ud558\uac70\ub098 \uc790\uae30\uc758 \uc810\uc720\uc640 \uc804 \uc810\uc720\uc790\uc758 \uc810\uc720\ub97c \uc544\uc6b8\ub7ec \uc8fc\uc7a5\ud560 \uc218 \uc788\ub2e4"],t.s)
B.aTH=s(["\uc810\uc720\uc758 \uc2b9\uacc4","\uc81c199\uc870"],t.s)
B.bQY=new A.a("gen_cl_realright_13","civil_law","\ubb3c\uad8c\ubcc0\ub3d9\xb7\uc810\uc720\xb7\ucd1d\uc720",null,"\uc810\uc720\uc758 \uc2b9\uacc4\uc640 \uad00\ub828\ud558\uc5ec \ubbfc\ubc95 \uc81c199\uc870\uc758 \ub0b4\uc6a9\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aEz,0,"\ubbfc\ubc95 \uc81c199\uc870\ub294 \uc810\uc720\uc790\uc758 \uc2b9\uacc4\uc778\uc740 \uc790\uae30\uc758 \uc810\uc720\ub9cc\uc744 \uc8fc\uc7a5\ud558\uac70\ub098 \uc790\uae30\uc758 \uc810\uc720\uc640 \uc804 \uc810\uc720\uc790\uc758 \uc810\uc720\ub97c \uc544\uc6b8\ub7ec \uc8fc\uc7a5\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ub2e4\ub9cc \uc804 \uc810\uc720\uc790\uc758 \uc810\uc720\ub97c \uc544\uc6b8\ub7ec \uc8fc\uc7a5\ud558\ub294 \uacbd\uc6b0\uc5d0\ub294 \uadf8 \ud558\uc790\ub3c4 \ud568\uaed8 \uc2b9\uacc4\ud55c\ub2e4.",B.Y6,B.aTH,null)
B.ach=s(["\uc120\uc758\uc758 \uc810\uc720\uc790\ub294 \uc810\uc720\ubb3c\uc758 \uacfc\uc2e4\uc744 \ucde8\ub4dd\ud55c\ub2e4.","\uc120\uc758\uc758 \uc810\uc720\uc790\ub294 \ud56d\uc0c1 \uacfc\uc2e4\uc744 \ubc18\ud658\ud558\uc5ec\uc57c \ud55c\ub2e4.","\uc545\uc758\uc758 \uc810\uc720\uc790\ub9cc \uacfc\uc2e4\ucde8\ub4dd\uad8c\uc744 \uac00\uc9c4\ub2e4.","\uc120\uc758\uc758 \uc810\uc720\uc790\ub294 \uacfc\uc2e4\ucde8\ub4dd\uad8c\uc744 \uac00\uc9c0\uc9c0 \ubabb\ud55c\ub2e4."],t.s)
B.b_4=s(["\uc120\uc758\uc758 \uc810\uc720\uc790\ub294 \uc810\uc720\ubb3c\uc758 \uacfc\uc2e4\uc744 \ucde8\ub4dd\ud55c\ub2e4"],t.s)
B.ajd=s(["\uc81c201\uc870","\uc120\uc758\uc810\uc720\uc790\uc758 \uacfc\uc2e4\ucde8\ub4dd"],t.s)
B.bNO=new A.a("gen_cl_realright_14","civil_law","\ubb3c\uad8c\ubcc0\ub3d9\xb7\uc810\uc720\xb7\ucd1d\uc720",null,"\uc810\uc720\uc790\uc640 \ud68c\ubcf5\uc790\uc758 \uad00\uacc4\uc5d0\uc11c \uc120\uc758\uc758 \uc810\uc720\uc790\uc5d0 \uad00\ud55c \ubbfc\ubc95 \uc81c201\uc870\uc758 \ub0b4\uc6a9\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.ach,0,"\ubbfc\ubc95 \uc81c201\uc870 \uc81c1\ud56d\uc740 \uc120\uc758\uc758 \uc810\uc720\uc790\ub294 \uc810\uc720\ubb3c\uc758 \uacfc\uc2e4\uc744 \ucde8\ub4dd\ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ubc18\uba74 \uc545\uc758\uc758 \uc810\uc720\uc790\ub294 \uc218\ucde8\ud55c \uacfc\uc2e4\uc744 \ubc18\ud658\ud558\uc5ec\uc57c \ud558\uace0 \uc18c\ube44\ud558\uc600\uac70\ub098 \uacfc\uc2e4\ub85c \uc778\ud558\uc5ec \ud6fc\uc190 \ub610\ub294 \uc218\ucde8\ud558\uc9c0 \ubabb\ud55c \uacbd\uc6b0\uc5d0\ub294 \uadf8 \ub300\uac00\ub97c \ubcf4\uc0c1\ud558\uc5ec\uc57c \ud55c\ub2e4.",B.b_4,B.ajd,null)
B.b5C=s(["\uc120\uc758\uc758 \uc810\uc720\uc790\ub85c\uc11c \uc18c\uc720\uc758 \uc758\uc0ac\uac00 \uc5c6\ub294 \uc790\ub294 \uc774\uc775\uc774 \ud604\uc874\ud558\ub294 \ud55c\ub3c4\uc5d0\uc11c \ubc30\uc0c1\ucc45\uc784\uc744 \uc9c4\ub2e4.","\uc810\uc720\uc790\ub294 \uc810\uc720\ubb3c\uc758 \uba78\uc2e4\xb7\ud6fc\uc190\uc5d0 \ub300\ud558\uc5ec \uc5b8\uc81c\ub098 \uc804 \uc190\ud574\ub97c \ubc30\uc0c1\ud558\uc5ec\uc57c \ud55c\ub2e4.","\uc545\uc758\uc758 \uc810\uc720\uc790\ub294 \uc190\ud574\ubc30\uc0c1\ucc45\uc784\uc744 \uc804\ud600 \uc9c0\uc9c0 \uc54a\ub294\ub2e4.","\uc810\uc720\ubb3c\uc758 \uba78\uc2e4\xb7\ud6fc\uc190\uc5d0 \ub300\ud574\uc11c\ub294 \ud68c\ubcf5\uc790\ub9cc\uc774 \ucc45\uc784\uc744 \uc9c4\ub2e4."],t.s)
B.aqU=s(["\uc120\uc758\uc758 \uc810\uc720\uc790\ub85c\uc11c \uc18c\uc720\uc758 \uc758\uc0ac\uac00 \uc5c6\ub294 \uc790\ub294 \uc774\uc775\uc774 \ud604\uc874\ud558\ub294 \ud55c\ub3c4\uc5d0\uc11c \ubc30\uc0c1\ucc45\uc784\uc744 \uc9c4\ub2e4"],t.s)
B.a5b=s(["\uc81c202\uc870","\uc810\uc720\ubb3c \uba78\uc2e4\xb7\ud6fc\uc190"],t.s)
B.bGs=new A.a("gen_cl_realright_15","civil_law","\ubb3c\uad8c\ubcc0\ub3d9\xb7\uc810\uc720\xb7\ucd1d\uc720",null,"\uc810\uc720\ubb3c\uc758 \uba78\uc2e4\xb7\ud6fc\uc190\uc5d0 \uad00\ud55c \ubbfc\ubc95 \uc81c202\uc870\uc758 \ub0b4\uc6a9\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.b5C,0,"\ubbfc\ubc95 \uc81c202\uc870\ub294 \uc810\uc720\uc790\uc758 \ucc45\uc784 \uc788\ub294 \uc0ac\uc720\ub85c \uc810\uc720\ubb3c\uc774 \uba78\uc2e4 \ub610\ub294 \ud6fc\uc190\ub41c \ub54c\uc5d0\ub294 \uc545\uc758\uc758 \uc810\uc720\uc790\ub294 \uadf8 \uc190\ud574\uc758 \uc804\ubd80\ub97c \ubc30\uc0c1\ud558\uc5ec\uc57c \ud558\ub098, \uc120\uc758\uc758 \uc810\uc720\uc790\ub85c\uc11c \uc18c\uc720\uc758 \uc758\uc0ac\uac00 \uc5c6\ub294 \uc790\ub294 \uc774\uc775\uc774 \ud604\uc874\ud558\ub294 \ud55c\ub3c4\uc5d0\uc11c \ubc30\uc0c1\ucc45\uc784\uc744 \uc9c4\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4.",B.aqU,B.a5b,null)
B.b15=s(["\uc810\uc720\uc790\uac00 \uc810\uc720\ubb3c\uc744 \ubc18\ud658\ud560 \ub54c\uc5d0\ub294 \ud68c\ubcf5\uc790\uc5d0 \ub300\ud558\uc5ec \uadf8 \ubb3c\uac74\uc744 \ubcf4\uc874\ud558\uae30 \uc704\ud558\uc5ec \uc9c0\ucd9c\ud55c \ud544\uc694\ube44\uc758 \uc0c1\ud658\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4.","\uc810\uc720\uc790\uac00 \uc720\uc775\ube44\ub97c \uc9c0\ucd9c\ud55c \uacbd\uc6b0 \uadf8 \uac00\uc561\uc758 \uc99d\uac00\uac00 \ud604\uc874\ud55c \ub54c\uc5d0 \ud55c\ud558\uc5ec \uc0c1\ud658\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4.","\uc545\uc758\uc758 \uc810\uc720\uc790\ub294 \ud1b5\uc0c1\uc758 \ud544\uc694\ube44\ub97c \uccad\uad6c\ud558\uc9c0 \ubabb\ud55c\ub2e4.","\uc720\uc775\ube44\uc0c1\ud658\uccad\uad6c\uc758 \uacbd\uc6b0 \ubc95\uc6d0\uc740 \ud68c\ubcf5\uc790\uc758 \uccad\uad6c\uc5d0 \uc758\ud558\uc5ec \uc0c1\ub2f9\ud55c \uae30\uac04\uc744 \ud5c8\uc5ec\ud560 \uc218 \uc788\ub2e4."],t.s)
B.alo=s(["\uacfc\uc2e4\uc744 \ucde8\ub4dd\ud55c \uacbd\uc6b0\uc5d0\ub294 \ud1b5\uc0c1\uc758 \ud544\uc694\ube44\ub294 \uccad\uad6c\ud558\uc9c0 \ubabb\ud55c\ub2e4"],t.s)
B.aoS=s(["\uc81c203\uc870","\ud544\uc694\ube44\xb7\uc720\uc775\ube44\uc0c1\ud658\uccad\uad6c\uad8c"],t.s)
B.bqR=new A.a("gen_cl_realright_16","civil_law","\ubb3c\uad8c\ubcc0\ub3d9\xb7\uc810\uc720\xb7\ucd1d\uc720",null,"\uc810\uc720\uc790\uc758 \uc0c1\ud658\uccad\uad6c\uad8c\uc5d0 \uad00\ud55c \ubbfc\ubc95 \uc81c203\uc870\uc758 \ub0b4\uc6a9\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.b15,2,"\ubbfc\ubc95 \uc81c203\uc870\ub294 \uc810\uc720\uc790\uac00 \uc810\uc720\ubb3c\uc744 \ubc18\ud658\ud560 \ub54c \ud544\uc694\ube44\uc640 \uc720\uc775\ube44\uc758 \uc0c1\ud658\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud558\uba70, \ub2e4\ub9cc \uacfc\uc2e4\uc744 \ucde8\ub4dd\ud55c \uacbd\uc6b0\uc5d0\ub294 \ud1b5\uc0c1\uc758 \ud544\uc694\ube44\ub294 \uccad\uad6c\ud558\uc9c0 \ubabb\ud55c\ub2e4. \uc774\ub294 \uc810\uc720\uc790\uc758 \uc120\uc758\xb7\uc545\uc758\ub97c \ubd88\ubb38\ud558\uace0 \uc801\uc6a9\ub418\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uacfc\uc2e4\ucde8\ub4dd \uc5ec\ubd80\uc5d0 \uc5f0\ub3d9\ub41c\ub2e4.",B.alo,B.aoS,null)
B.bip=s(["\uc810\uc720\uc790\uac00 \uc810\uc720\uc758 \uce68\ud0c8\uc744 \ub2f9\ud55c \ub54c\uc5d0\ub294 \uadf8 \ubb3c\uac74\uc758 \ubc18\ud658 \ubc0f \uc190\ud574\uc758 \ubc30\uc0c1\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4.","\uc810\uc720\ubb3c\ubc18\ud658\uccad\uad6c\uad8c\uc740 \uce68\ud0c8\uc790\uc758 \ud2b9\ubcc4\uc2b9\uacc4\uc778\uc5d0\uac8c\ub294 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ud589\uc0ac\ud560 \uc218 \uc5c6\ub2e4.","\uc810\uc720\ubb3c\ubc18\ud658\uccad\uad6c\uad8c\uc740 \uc810\uc720\uc758 \uce68\ud0c8\uc774 \uc5c6\uc5b4\ub3c4 \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4.","\uc810\uc720\ubb3c\ubc18\ud658\uccad\uad6c\uad8c\uc758 \ud589\uc0ac\uae30\uac04\uc5d0\ub294 \uc81c\ud55c\uc774 \uc5c6\ub2e4."],t.s)
B.aU_=s(["\uc810\uc720\uc758 \uce68\ud0c8\uc744 \ub2f9\ud55c \ub54c\uc5d0\ub294 \uadf8 \ubb3c\uac74\uc758 \ubc18\ud658 \ubc0f \uc190\ud574\uc758 \ubc30\uc0c1\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.aSW=s(["\uc81c204\uc870","\uc810\uc720\ubb3c\ubc18\ud658\uccad\uad6c\uad8c"],t.s)
B.bSc=new A.a("gen_cl_realright_17","civil_law","\ubb3c\uad8c\ubcc0\ub3d9\xb7\uc810\uc720\xb7\ucd1d\uc720",null,"\uc810\uc720\ubcf4\ud638\uccad\uad6c\uad8c \uc911 \uc810\uc720\ubb3c\ubc18\ud658\uccad\uad6c\uad8c\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.bip,0,"\ubbfc\ubc95 \uc81c204\uc870\ub294 \uc810\uc720\uc790\uac00 \uc810\uc720\uc758 \uce68\ud0c8\uc744 \ub2f9\ud55c \ub54c\uc5d0\ub294 \uadf8 \ubb3c\uac74\uc758 \ubc18\ud658 \ubc0f \uc190\ud574\uc758 \ubc30\uc0c1\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ub2e4\ub9cc \uce68\ud0c8\uc790\uc758 \ud2b9\ubcc4\uc2b9\uacc4\uc778\uc774 \uc545\uc758\uc778 \ub54c\uc5d0\ub294 \uadf8 \uc790\uc5d0 \ub300\ud558\uc5ec\ub3c4 \ubc18\ud658\uccad\uad6c\uad8c\uc744 \ud589\uc0ac\ud560 \uc218 \uc788\uace0, \uc774 \uccad\uad6c\uad8c\uc740 \uce68\ud0c8\uc744 \ub2f9\ud55c \ub0a0\ub85c\ubd80\ud130 1\ub144 \ub0b4\uc5d0 \ud589\uc0ac\ud558\uc5ec\uc57c \ud55c\ub2e4.",B.aU_,B.aSW,null)
B.aeQ=s(["\uc810\uc720\uc790\uac00 \uc810\uc720\uc758 \ubc29\ud574\ub97c \ubc1b\uc740 \ub54c\uc5d0\ub294 \uadf8 \ubc29\ud574\uc758 \uc81c\uac70 \ubc0f \uc190\ud574\ubc30\uc0c1\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4.","\uc810\uc720\ubb3c\ubc29\ud574\uc81c\uac70\uccad\uad6c\uad8c\uc740 \uc810\uc720\uc758 \uce68\ud0c8\uc774 \uc788\uc5b4\uc57c\ub9cc \uc778\uc815\ub41c\ub2e4.","\ubc29\ud574\uc608\ubc29\uccad\uad6c\uad8c\uc740 \uc190\ud574\ubc30\uc0c1\uc758 \ub2f4\ubcf4\ub97c \uccad\uad6c\ud560 \uc218 \uc5c6\ub2e4.","\uc810\uc720\ubb3c\ubc29\ud574\uc81c\uac70\uccad\uad6c\uad8c\uc740 \ubc29\ud574\uac00 \uc885\ub8cc\ub41c \ud6c4\uc5d0\ub9cc \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4."],t.s)
B.ah_=s(["\uc810\uc720\uc758 \ubc29\ud574\ub97c \ubc1b\uc740 \ub54c\uc5d0\ub294 \uadf8 \ubc29\ud574\uc758 \uc81c\uac70 \ubc0f \uc190\ud574\ubc30\uc0c1\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4"],t.s)
