B.bPn=new A.a("gen_cl_realright_18","civil_law","\ubb3c\uad8c\ubcc0\ub3d9\xb7\uc810\uc720\xb7\ucd1d\uc720",null,"\uc810\uc720\ubcf4\ud638\uccad\uad6c\uad8c \uc911 \uc810\uc720\ubb3c\ubc29\ud574\uc81c\uac70\uccad\uad6c\uad8c \ubc0f \ubc29\ud574\uc608\ubc29\uccad\uad6c\uad8c\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aeQ,0,"\ubbfc\ubc95 \uc81c205\uc870\ub294 \uc810\uc720\uc790\uac00 \uc810\uc720\uc758 \ubc29\ud574\ub97c \ubc1b\uc740 \ub54c\uc5d0\ub294 \uadf8 \ubc29\ud574\uc758 \uc81c\uac70 \ubc0f \uc190\ud574\ubc30\uc0c1\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud558\uace0, \uc81c206\uc870\ub294 \uc810\uc720\uc758 \ubc29\ud574\ub97c \ubc1b\uc744 \uc5fc\ub824\uac00 \uc788\ub294 \ub54c\uc5d0 \ubc29\ud574\uc758 \uc608\ubc29 \ub610\ub294 \uc190\ud574\ubc30\uc0c1\uc758 \ub2f4\ubcf4\ub97c \uccad\uad6c\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4.",B.ah_,B.a87,null)
B.baV=s(["20\ub144\uac04 \uc18c\uc720\uc758 \uc758\uc0ac\ub85c \ud3c9\uc628\xb7\uacf5\uc5f0\ud558\uac8c \ubd80\ub3d9\uc0b0\uc744 \uc810\uc720\ud55c \uc790\ub294 \ub4f1\uae30\ud568\uc73c\ub85c\uc368 \uadf8 \uc18c\uc720\uad8c\uc744 \ucde8\ub4dd\ud55c\ub2e4.","20\ub144\uac04 \uc810\uc720\ud558\uba74 \ub4f1\uae30 \uc5c6\uc774\ub3c4 \uace7\ubc14\ub85c \uc18c\uc720\uad8c\uc744 \ucde8\ub4dd\ud55c\ub2e4.","10\ub144\uac04 \uc810\uc720\ud558\uba74 \ub4f1\uae30 \uc5c6\uc774 \uc18c\uc720\uad8c\uc744 \ucde8\ub4dd\ud55c\ub2e4.","\ucde8\ub4dd\uc2dc\ud6a8\uc5d0\ub294 \uc18c\uc720\uc758 \uc758\uc0ac\uac00 \uc694\uad6c\ub418\uc9c0 \uc54a\ub294\ub2e4."],t.s)
B.a6w=s(["\ub4f1\uae30\ud568\uc73c\ub85c\uc368 \uadf8 \uc18c\uc720\uad8c\uc744 \ucde8\ub4dd\ud55c\ub2e4"],t.s)
B.b4G=s(["\uc81c245\uc870 \uc81c1\ud56d","\uc810\uc720\ucde8\ub4dd\uc2dc\ud6a8"],t.s)
B.bwX=new A.a("gen_cl_realright_19","civil_law","\ubb3c\uad8c\ubcc0\ub3d9\xb7\uc810\uc720\xb7\ucd1d\uc720",null,"\ubd80\ub3d9\uc0b0 \uc18c\uc720\uad8c\uc758 \ucde8\ub4dd\uc2dc\ud6a8(\ubbfc\ubc95 \uc81c245\uc870 \uc81c1\ud56d)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.baV,0,"\ubbfc\ubc95 \uc81c245\uc870 \uc81c1\ud56d\uc740 20\ub144\uac04 \uc18c\uc720\uc758 \uc758\uc0ac\ub85c \ud3c9\uc628\xb7\uacf5\uc5f0\ud558\uac8c \ubd80\ub3d9\uc0b0\uc744 \uc810\uc720\ud558\ub294 \uc790\ub294 \ub4f1\uae30\ud568\uc73c\ub85c\uc368 \uadf8 \uc18c\uc720\uad8c\uc744 \ucde8\ub4dd\ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc774\ub294 \uc810\uc720\ucde8\ub4dd\uc2dc\ud6a8\ub85c\uc11c \uc2dc\ud6a8\uc644\uc131\ub9cc\uc73c\ub85c \ubc14\ub85c \uc18c\uc720\uad8c\uc744 \ucde8\ub4dd\ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \ub4f1\uae30\ub97c \ud558\uc5ec\uc57c \uc18c\uc720\uad8c\uc744 \ucde8\ub4dd\ud55c\ub2e4\ub294 \uc810\uc774 \ud2b9\uc9d5\uc774\ub2e4.",B.a6w,B.b4G,null)
B.a7R=s(["\ubd80\ub3d9\uc0b0\uc758 \uc18c\uc720\uc790\ub85c \ub4f1\uae30\ud55c \uc790\uac00 10\ub144\uac04 \uc18c\uc720\uc758 \uc758\uc0ac\ub85c \ud3c9\uc628\xb7\uacf5\uc5f0\ud558\uac8c \uc120\uc758\uc774\uba70 \uacfc\uc2e4 \uc5c6\uc774 \uadf8 \ubd80\ub3d9\uc0b0\uc744 \uc810\uc720\ud55c \ub54c\uc5d0 \uc18c\uc720\uad8c\uc744 \ucde8\ub4dd\ud55c\ub2e4.","\ub4f1\uae30\ubd80\ucde8\ub4dd\uc2dc\ud6a8\ub294 \ub4f1\uae30 \uc5c6\uc774\ub3c4 \uc644\uc131\ub420 \uc218 \uc788\ub2e4.","\ub4f1\uae30\ubd80\ucde8\ub4dd\uc2dc\ud6a8\uc758 \uc810\uc720\uae30\uac04\uc740 20\ub144\uc774\ub2e4.","\ub4f1\uae30\ubd80\ucde8\ub4dd\uc2dc\ud6a8\uc5d0\ub294 \uc120\uc758\xb7\ubb34\uacfc\uc2e4\uc774 \uc694\uad6c\ub418\uc9c0 \uc54a\ub294\ub2e4."],t.s)
B.b74=s(["10\ub144\uac04 \uc18c\uc720\uc758 \uc758\uc0ac\ub85c \ud3c9\uc628\xb7\uacf5\uc5f0\ud558\uac8c \uc120\uc758\uc774\uba70 \uacfc\uc2e4 \uc5c6\uc774 \uadf8 \ubd80\ub3d9\uc0b0\uc744 \uc810\uc720\ud55c \ub54c\uc5d0\ub294 \uc18c\uc720\uad8c\uc744 \ucde8\ub4dd\ud55c\ub2e4"],t.s)
