B.bRD=new A.a("gen_cl_realright_20","civil_law","\ubb3c\uad8c\ubcc0\ub3d9\xb7\uc810\uc720\xb7\ucd1d\uc720",null,"\ub4f1\uae30\ubd80\ucde8\ub4dd\uc2dc\ud6a8(\ubbfc\ubc95 \uc81c245\uc870 \uc81c2\ud56d)\uc758 \uc694\uac74\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.a7R,0,"\ubbfc\ubc95 \uc81c245\uc870 \uc81c2\ud56d\uc740 \ubd80\ub3d9\uc0b0\uc758 \uc18c\uc720\uc790\ub85c \ub4f1\uae30\ud55c \uc790\uac00 10\ub144\uac04 \uc18c\uc720\uc758 \uc758\uc0ac\ub85c \ud3c9\uc628\xb7\uacf5\uc5f0\ud558\uac8c \uc120\uc758\uc774\uba70 \uacfc\uc2e4 \uc5c6\uc774 \uadf8 \ubd80\ub3d9\uc0b0\uc744 \uc810\uc720\ud55c \ub54c\uc5d0\ub294 \uc18c\uc720\uad8c\uc744 \ucde8\ub4dd\ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc810\uc720\ucde8\ub4dd\uc2dc\ud6a8\uc640 \ub2ec\ub9ac \ub4f1\uae30\uc758 \uc874\uc7ac\ub97c \uc804\uc81c\ub85c \ud558\uace0 \uc810\uc720\uae30\uac04\ub3c4 10\ub144\uc73c\ub85c \ub2e8\ucd95\ub41c\ub2e4.",B.b74,B.b8h,null)
B.asj=s(["10\ub144\uac04 \uc18c\uc720\uc758 \uc758\uc0ac\ub85c \ud3c9\uc628\xb7\uacf5\uc5f0\ud558\uac8c \ub3d9\uc0b0\uc744 \uc810\uc720\ud55c \uc790\ub294 \uadf8 \uc18c\uc720\uad8c\uc744 \ucde8\ub4dd\ud55c\ub2e4.","\uc810\uc720\uc758 \uac1c\uc2dc\uc5d0 \uc120\uc758\uc774\uba70 \uacfc\uc2e4 \uc5c6\ub294 \ub54c\uc5d0\ub294 5\ub144\uc758 \uc810\uc720\ub85c \uc18c\uc720\uad8c\uc744 \ucde8\ub4dd\ud55c\ub2e4.","\ub3d9\uc0b0\uc758 \ucde8\ub4dd\uc2dc\ud6a8 \uae30\uac04\uc740 \ubd80\ub3d9\uc0b0\uacfc \ub3d9\uc77c\ud558\uac8c 20\ub144\uc774\ub2e4.","\ub3d9\uc0b0\uc5d0\ub294 \ucde8\ub4dd\uc2dc\ud6a8\uac00 \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4."],t.s)
B.aYq=s(["\uc810\uc720\uc758 \uac1c\uc2dc\uc5d0 \uc120\uc758\uc774\uba70 \uacfc\uc2e4 \uc5c6\ub294 \ub54c\uc5d0\ub294 5\ub144\uc744 \uacbd\uacfc\ud568\uc73c\ub85c\uc368 \uc18c\uc720\uad8c\uc744 \ucde8\ub4dd\ud55c\ub2e4"],t.s)
B.a_0=s(["\uc81c246\uc870","\ub3d9\uc0b0 \ucde8\ub4dd\uc2dc\ud6a8"],t.s)
B.bLx=new A.a("gen_cl_realright_21","civil_law","\ubb3c\uad8c\ubcc0\ub3d9\xb7\uc810\uc720\xb7\ucd1d\uc720",null,"\ub3d9\uc0b0\uc758 \ucde8\ub4dd\uc2dc\ud6a8(\ubbfc\ubc95 \uc81c246\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.asj,1,"\ubbfc\ubc95 \uc81c246\uc870 \uc81c1\ud56d\uc740 10\ub144\uac04 \uc18c\uc720\uc758 \uc758\uc0ac\ub85c \ud3c9\uc628\xb7\uacf5\uc5f0\ud558\uac8c \ub3d9\uc0b0\uc744 \uc810\uc720\ud55c \uc790\ub294 \uadf8 \uc18c\uc720\uad8c\uc744 \ucde8\ub4dd\ud55c\ub2e4\uace0 \uaddc\uc815\ud558\uace0, \uc81c2\ud56d\uc740 \uc810\uc720\uc758 \uac1c\uc2dc\uc5d0 \uc120\uc758\uc774\uba70 \uacfc\uc2e4 \uc5c6\ub294 \ub54c\uc5d0\ub294 5\ub144\uc744 \uacbd\uacfc\ud568\uc73c\ub85c\uc368 \uc18c\uc720\uad8c\uc744 \ucde8\ub4dd\ud55c\ub2e4\uace0 \uc815\ud55c\ub2e4.",B.aYq,B.a_0,null)
B.bhr=s(["\ubd80\ub3d9\uc0b0\uc758 \uc18c\uc720\uc790\ub294 \uadf8 \ubd80\ub3d9\uc0b0\uc5d0 \ubd80\ud569\ud55c \ubb3c\uac74\uc758 \uc18c\uc720\uad8c\uc744 \ucde8\ub4dd\ud558\ub098, \ud0c0\uc778\uc758 \uad8c\uc6d0\uc5d0 \uc758\ud558\uc5ec \ubd80\uc18d\ub41c \uac83\uc740 \uadf8\ub7ec\ud558\uc9c0 \uc544\ub2c8\ud558\ub2e4.","\ubd80\ub3d9\uc0b0\uc5d0 \ubd80\ud569\ub41c \ubb3c\uac74\uc740 \uc5b8\uc81c\ub098 \ubd80\ud569\uc790\uc758 \uc18c\uc720\ub85c \ub0a8\ub294\ub2e4.","\ubd80\ud569\uc740 \ub3d9\uc0b0 \uc0c1\ud638\uac04\uc5d0\ub9cc \uc778\uc815\ub418\ub294 \uc81c\ub3c4\uc774\ub2e4.","\ud0c0\uc778\uc774 \uc815\ub2f9\ud55c \uad8c\uc6d0 \uc5c6\uc774 \ubd80\uc18d\uc2dc\ud0a8 \ubb3c\uac74\ub3c4 \ud56d\uc0c1 \ubd80\uc18d\uc2dc\ud0a8 \uc790\uc758 \uc18c\uc720\ub85c \ub0a8\ub294\ub2e4."],t.s)
B.aW9=s(["\ud0c0\uc778\uc758 \uad8c\uc6d0\uc5d0 \uc758\ud558\uc5ec \ubd80\uc18d\ub41c \uac83\uc740 \uadf8\ub7ec\ud558\uc9c0 \uc544\ub2c8\ud558\ub2e4"],t.s)
B.bg3=s(["\uc81c256\uc870","\ubd80\ub3d9\uc0b0\uc758 \ubd80\ud569"],t.s)
B.byE=new A.a("gen_cl_realright_22","civil_law","\ubb3c\uad8c\ubcc0\ub3d9\xb7\uc810\uc720\xb7\ucd1d\uc720",null,"\ubd80\ub3d9\uc0b0\uc758 \ubd80\ud569(\ubbfc\ubc95 \uc81c256\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.bhr,0,"\ubbfc\ubc95 \uc81c256\uc870\ub294 \ubd80\ub3d9\uc0b0\uc758 \uc18c\uc720\uc790\ub294 \uadf8 \ubd80\ub3d9\uc0b0\uc5d0 \ubd80\ud569\ud55c \ubb3c\uac74\uc758 \uc18c\uc720\uad8c\uc744 \ucde8\ub4dd\ud55c\ub2e4\uace0 \uaddc\uc815\ud558\ub418, \ud0c0\uc778\uc758 \uad8c\uc6d0\uc5d0 \uc758\ud558\uc5ec \ubd80\uc18d\ub41c \uac83\uc740 \uadf8\ub7ec\ud558\uc9c0 \uc544\ub2c8\ud558\ub2e4\ub294 \ub2e8\uc11c\ub97c \ub450\uace0 \uc788\ub2e4. \uc774\ub294 \uc815\ub2f9\ud55c \uad8c\uc6d0 \uc788\ub294 \ubd80\uc18d\ubb3c\uc5d0 \ub300\ud574\uc11c\ub294 \uc6d0\ub798 \uc18c\uc720\uc790\uc758 \uc18c\uc720\uad8c\uc744 \uc778\uc815\ud558\uae30 \uc704\ud568\uc774\ub2e4.",B.aW9,B.bg3,null)
B.aMK=s(["\ub3d9\uc0b0\uacfc \ub3d9\uc0b0\uc774 \ubd80\ud569\ud558\uc5ec \ud6fc\uc190\ud558\uc9c0 \uc544\ub2c8\ud558\uba74 \ubd84\ub9ac\ud560 \uc218 \uc5c6\uac70\ub098 \ubd84\ub9ac\uc5d0 \uacfc\ub2e4\ud55c \ube44\uc6a9\uc744 \uc694\ud560 \uacbd\uc6b0 \uadf8 \ud569\uc131\ubb3c\uc758 \uc18c\uc720\uad8c\uc740 \uc8fc\ub41c \ub3d9\uc0b0\uc758 \uc18c\uc720\uc790\uc5d0\uac8c \uc18d\ud55c\ub2e4.","\ub3d9\uc0b0\uac04\uc758 \ubd80\ud569\uc740 \uc5b8\uc81c\ub098 \uac01 \ub3d9\uc0b0 \uc18c\uc720\uc790\uc758 \uacf5\uc720\ub85c \ub41c\ub2e4.","\ub3d9\uc0b0\uac04\uc758 \ubd80\ud569\uc5d0\ub294 \uc8fc\uc885\uc744 \uad6c\ubcc4\ud558\uc9c0 \uc54a\ub294\ub2e4.","\ub3d9\uc0b0\uac04\uc758 \ubd80\ud569\uc740 \uc778\uc815\ub418\uc9c0 \uc54a\uc73c\uba70 \ubd80\ub3d9\uc0b0\uc5d0\ub9cc \uc801\uc6a9\ub41c\ub2e4."],t.s)
B.abL=s(["\uadf8 \ud569\uc131\ubb3c\uc758 \uc18c\uc720\uad8c\uc740 \uc8fc\ub41c \ub3d9\uc0b0\uc758 \uc18c\uc720\uc790\uc5d0\uac8c \uc18d\ud558\uace0"],t.s)
B.bhu=s(["\uc81c257\uc870","\ub3d9\uc0b0\uac04\uc758 \ubd80\ud569"],t.s)
B.bvv=new A.a("gen_cl_realright_23","civil_law","\ubb3c\uad8c\ubcc0\ub3d9\xb7\uc810\uc720\xb7\ucd1d\uc720",null,"\ub3d9\uc0b0\uac04\uc758 \ubd80\ud569(\ubbfc\ubc95 \uc81c257\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aMK,0,"\ubbfc\ubc95 \uc81c257\uc870\ub294 \ub3d9\uc0b0\uacfc \ub3d9\uc0b0\uc774 \ubd80\ud569\ud558\uc5ec \ud6fc\uc190\ud558\uc9c0 \uc544\ub2c8\ud558\uba74 \ubd84\ub9ac\ud560 \uc218 \uc5c6\uac70\ub098 \uadf8 \ubd84\ub9ac\uc5d0 \uacfc\ub2e4\ud55c \ube44\uc6a9\uc744 \uc694\ud560 \uacbd\uc6b0 \uadf8 \ud569\uc131\ubb3c\uc758 \uc18c\uc720\uad8c\uc740 \uc8fc\ub41c \ub3d9\uc0b0\uc758 \uc18c\uc720\uc790\uc5d0\uac8c \uc18d\ud558\uace0, \uc8fc\uc885\uc744 \uad6c\ubcc4\ud560 \uc218 \uc5c6\ub294 \ub54c\uc5d0\ub294 \ubd80\ud569 \ub2f9\uc2dc\uc758 \uac00\uc561\uc758 \ube44\uc728\ub85c \ud569\uc131\ubb3c\uc744 \uacf5\uc720\ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4.",B.abL,B.bhu,null)
B.aPt=s(["\uc18c\uc720\uc790\ub97c \ub2ec\ub9ac\ud558\ub294 \uace1\ubb3c\uc774 \ud63c\ud654\ub418\uc5b4 \uc2dd\ubcc4\ud560 \uc218 \uc5c6\uac8c \ub41c \uacbd\uc6b0\uc5d0\ub294 \ub3d9\uc0b0\uac04\uc758 \ubd80\ud569\uc5d0 \uad00\ud55c \uaddc\uc815\uc744 \uc900\uc6a9\ud55c\ub2e4.","\ud63c\ud654\ub294 \ub3d9\uc0b0\uc758 \ubd80\ud569\uacfc \uc804\ud600 \ubcc4\uac1c\uc758 \ub3c5\ub9bd\ub41c \uaddc\uc728\uc744 \ubc1b\ub294\ub2e4.","\ud63c\ud654\ub41c \ubb3c\uac74\uc740 \ud56d\uc0c1 \ucd5c\ucd08 \uc18c\uc720\uc790\uc5d0\uac8c \ubc18\ud658\ub41c\ub2e4.","\ud63c\ud654\uc5d0\ub294 \ubd80\ud569 \uaddc\uc815\uc774 \uc900\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4."],t.s)
B.aud=s(["\ub3d9\uc0b0\uac04\uc758 \ubd80\ud569\uc5d0 \uad00\ud55c \uc81c257\uc870\uc758 \uaddc\uc815\uc744 \uc900\uc6a9\ud55c\ub2e4"],t.s)
B.b93=s(["\uc81c258\uc870","\ud63c\ud654"],t.s)
B.brV=new A.a("gen_cl_realright_24","civil_law","\ubb3c\uad8c\ubcc0\ub3d9\xb7\uc810\uc720\xb7\ucd1d\uc720",null,"\ud63c\ud654(\ubbfc\ubc95 \uc81c258\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aPt,0,"\ubbfc\ubc95 \uc81c258\uc870\ub294 \uc18c\uc720\uc790\ub97c \ub2ec\ub9ac\ud558\ub294 \uace1\ubb3c, \uae08\uc804 \uae30\ud0c0 \ubb3c\uac74\uc774 \ud63c\ud654\ub418\uc5b4 \uc2dd\ubcc4\ud560 \uc218 \uc5c6\uac8c \ub41c \ub54c\uc5d0\ub294 \ub3d9\uc0b0\uac04\uc758 \ubd80\ud569\uc5d0 \uad00\ud55c \uc81c257\uc870\uc758 \uaddc\uc815\uc744 \uc900\uc6a9\ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc774\ub294 \uc720\uccb4\ubb3c\uc774 \uc11e\uc5ec \uac1c\ubcc4\uc131\uc744 \uc783\ub294 \ud63c\ud654\uc758 \uacbd\uc6b0\uc5d0\ub3c4 \ubd80\ud569\uc758 \ubc95\ub9ac\ub97c \uc801\uc6a9\ud558\uae30 \uc704\ud568\uc774\ub2e4.",B.aud,B.b93,null)
B.a_4=s(["\ud0c0\uc778\uc758 \ub3d9\uc0b0\uc5d0 \uac00\uacf5\ud55c \ub54c\uc5d0\ub294 \uadf8 \ubb3c\uac74\uc758 \uc18c\uc720\uad8c\uc740 \uc6d0\uc7ac\ub8cc\uc758 \uc18c\uc720\uc790\uc5d0\uac8c \uc18d\ud558\ub098, \uac00\uacf5\uc73c\ub85c \uc778\ud55c \uac00\uc561\uc758 \uc99d\uac00\uac00 \uc6d0\uc7ac\ub8cc \uac00\uc561\uc744 \ud604\uc800\ud788 \ucd08\uacfc\ud55c \ub54c\uc5d0\ub294 \uac00\uacf5\uc790\uc758 \uc18c\uc720\ub85c \ud55c\ub2e4.","\uac00\uacf5\ubb3c\uc758 \uc18c\uc720\uad8c\uc740 \uc5b8\uc81c\ub098 \uac00\uacf5\uc790\uc5d0\uac8c \uadc0\uc18d\ub41c\ub2e4.","\uac00\uacf5\ubb3c\uc758 \uc18c\uc720\uad8c\uc740 \ud56d\uc0c1 \uc6d0\uc7ac\ub8cc \uc18c\uc720\uc790\uc5d0\uac8c\ub9cc \uadc0\uc18d\ub41c\ub2e4.","\uac00\uacf5\uc5d0\ub294 \uc6d0\uc7ac\ub8cc \uac00\uc561\uacfc \uac00\uacf5\uac00\uc561\uc758 \ube44\uad50\uac00 \ud544\uc694\ud558\uc9c0 \uc54a\ub2e4."],t.s)
B.aX7=s(["\uac00\uacf5\uc73c\ub85c \uc778\ud55c \uac00\uc561\uc758 \uc99d\uac00\uac00 \uc6d0\uc7ac\ub8cc\uc758 \uac00\uc561\uc744 \ud604\uc800\ud788 \ucd08\uacfc\ud55c \ub54c\uc5d0\ub294 \uac00\uacf5\uc790\uc758 \uc18c\uc720\ub85c \ud55c\ub2e4"],t.s)
B.axF=s(["\uc81c259\uc870","\uac00\uacf5"],t.s)
B.bLE=new A.a("gen_cl_realright_25","civil_law","\ubb3c\uad8c\ubcc0\ub3d9\xb7\uc810\uc720\xb7\ucd1d\uc720",null,"\uac00\uacf5(\ubbfc\ubc95 \uc81c259\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.a_4,0,"\ubbfc\ubc95 \uc81c259\uc870 \uc81c1\ud56d\uc740 \ud0c0\uc778\uc758 \ub3d9\uc0b0\uc5d0 \uac00\uacf5\ud55c \ub54c\uc5d0\ub294 \uadf8 \ubb3c\uac74\uc758 \uc18c\uc720\uad8c\uc740 \uc6d0\uc7ac\ub8cc\uc758 \uc18c\uc720\uc790\uc5d0\uac8c \uc18d\ud55c\ub2e4\uace0 \ud558\uba74\uc11c, \uac00\uacf5\uc73c\ub85c \uc778\ud55c \uac00\uc561\uc758 \uc99d\uac00\uac00 \uc6d0\uc7ac\ub8cc\uc758 \uac00\uc561\uc744 \ud604\uc800\ud788 \ucd08\uacfc\ud55c \ub54c\uc5d0\ub294 \uac00\uacf5\uc790\uc758 \uc18c\uc720\ub85c \ud55c\ub2e4\ub294 \uc608\uc678\ub97c \uaddc\uc815\ud55c\ub2e4.",B.aX7,B.axF,null)
B.ahA=s(["\uacf5\uc720\uc790\ub294 \uadf8 \uc9c0\ubd84\uc744 \uc790\uc720\ub85c\uc774 \ucc98\ubd84\ud560 \uc218 \uc788\uace0 \uacf5\uc720\ubb3c \uc804\ubd80\ub97c \uc9c0\ubd84\uc758 \ube44\uc728\ub85c \uc0ac\uc6a9, \uc218\uc775\ud560 \uc218 \uc788\ub2e4.","\uacf5\uc720\ubb3c\uc758 \ucc98\ubd84\xb7\ubcc0\uacbd\uc740 \uac01 \uacf5\uc720\uc790\uac00 \ub2e8\ub3c5\uc73c\ub85c \ud560 \uc218 \uc788\ub2e4.","\uacf5\uc720\uc790\ub294 \uc9c0\ubd84\uc744 \ucc98\ubd84\ud560 \ub54c \ub2e4\ub978 \uacf5\uc720\uc790 \uc804\uc6d0\uc758 \ub3d9\uc758\ub97c \uc5bb\uc5b4\uc57c \ud55c\ub2e4.","\uacf5\uc720\ubb3c\uc758 \ubcf4\uc874\ud589\uc704\ub294 \uacf5\uc720\uc790 \uc804\uc6d0\uc758 \ub3d9\uc758\uac00 \uc788\uc5b4\uc57c \uac00\ub2a5\ud558\ub2e4."],t.s)
B.b6L=s(["\uacf5\uc720\uc790\ub294 \uadf8 \uc9c0\ubd84\uc744 \ucc98\ubd84\ud560 \uc218 \uc788\uace0 \uacf5\uc720\ubb3c \uc804\ubd80\ub97c \uc9c0\ubd84\uc758 \ube44\uc728\ub85c \uc0ac\uc6a9, \uc218\uc775\ud560 \uc218 \uc788\ub2e4"],t.s)
B.aeT=s(["\uc81c263\uc870","\uacf5\uc720"],t.s)
B.bKM=new A.a("gen_cl_realright_26","civil_law","\ubb3c\uad8c\ubcc0\ub3d9\xb7\uc810\uc720\xb7\ucd1d\uc720",null,"\uacf5\uc720\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.ahA,0,"\ubbfc\ubc95 \uc81c263\uc870\ub294 \uacf5\uc720\uc790\ub294 \uadf8 \uc9c0\ubd84\uc744 \ucc98\ubd84\ud560 \uc218 \uc788\uace0 \uacf5\uc720\ubb3c \uc804\ubd80\ub97c \uc9c0\ubd84\uc758 \ube44\uc728\ub85c \uc0ac\uc6a9, \uc218\uc775\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ub2e4\ub9cc \uacf5\uc720\ubb3c\uc758 \ucc98\ubd84\xb7\ubcc0\uacbd\uc5d0\ub294 \uc81c264\uc870\uc5d0 \ub530\ub77c \ub2e4\ub978 \uacf5\uc720\uc790 \uc804\uc6d0\uc758 \ub3d9\uc758\uac00 \ud544\uc694\ud558\uace0, \ubcf4\uc874\ud589\uc704\ub294 \uc81c265\uc870 \ub2e8\uc11c\uc5d0 \ub530\ub77c \uac01 \uacf5\uc720\uc790\uac00 \ub2e8\ub3c5\uc73c\ub85c \ud560 \uc218 \uc788\ub2e4.",B.b6L,B.aeT,null)
B.aUe=s(["\ud569\uc720\ubb3c\uc744 \ucc98\ubd84 \ub610\ub294 \ubcc0\uacbd\ud568\uc5d0\ub294 \ud569\uc720\uc790 \uc804\uc6d0\uc758 \ub3d9\uc758\uac00 \uc788\uc5b4\uc57c \ud558\uba70, \ud569\uc720\uc790\ub294 \uc804\uc6d0\uc758 \ub3d9\uc758 \uc5c6\uc774 \uadf8 \uc9c0\ubd84\uc744 \ucc98\ubd84\ud558\uc9c0 \ubabb\ud55c\ub2e4.","\ud569\uc720\uc790\ub294 \uc9c0\ubd84\uc744 \uc790\uc720\ub86d\uac8c \ucc98\ubd84\ud558\uace0 \ubd84\ud560\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4.","\ud569\uc720\ub294 \uacf5\uc720\uc640 \ub3d9\uc77c\ud55c \ubc95\ub960\uad00\uacc4\ub85c\uc11c \uc9c0\ubd84\ucc98\ubd84\uc758 \uc790\uc720\uac00 \uc778\uc815\ub41c\ub2e4.","\ud569\uc720\ubb3c\uc758 \ucc98\ubd84\uc5d0\ub294 \ud569\uc720\uc790 \uacfc\ubc18\uc218\uc758 \ub3d9\uc758\ub9cc \uc788\uc73c\uba74 \ub41c\ub2e4."],t.s)
B.aOG=s(["\ud569\uc720\uc790\ub294 \uc804\uc6d0\uc758 \ub3d9\uc758 \uc5c6\uc774\ub294 \uadf8 \uc9c0\ubd84\uc744 \ucc98\ubd84\ud558\uc9c0 \ubabb\ud558\uba70"],t.s)
B.a89=s(["\uc81c272\uc870","\ud569\uc720"],t.s)
B.bu7=new A.a("gen_cl_realright_27","civil_law","\ubb3c\uad8c\ubcc0\ub3d9\xb7\uc810\uc720\xb7\ucd1d\uc720",null,"\ud569\uc720\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aUe,0,"\ubbfc\ubc95 \uc81c272\uc870\uc640 \uc81c273\uc870\ub294 \ud569\uc720\ubb3c\uc744 \ucc98\ubd84 \ub610\ub294 \ubcc0\uacbd\ud568\uc5d0\ub294 \ud569\uc720\uc790 \uc804\uc6d0\uc758 \ub3d9\uc758\uac00 \uc788\uc5b4\uc57c \ud558\uace0, \ud569\uc720\uc790\ub294 \uc804\uc6d0\uc758 \ub3d9\uc758 \uc5c6\uc774\ub294 \uadf8 \uc9c0\ubd84\uc744 \ucc98\ubd84\ud558\uc9c0 \ubabb\ud558\uba70 \ud569\uc720\ubb3c\uc758 \ubd84\ud560\uc744 \uccad\uad6c\ud558\uc9c0 \ubabb\ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc774\ub294 \uc870\ud569\uccb4\ub85c\uc11c\uc758 \ub2e8\uccb4\uc801 \uad6c\uc18d\uc744 \ubc18\uc601\ud55c\ub2e4.",B.aOG,B.a89,null)
B.aB1=s(["\ubc95\uc778\uc774 \uc544\ub2cc \uc0ac\ub2e8\uc758 \uc0ac\uc6d0\uc774 \uc9d1\ud569\uccb4\ub85c\uc11c \ubb3c\uac74\uc744 \uc18c\uc720\ud558\ub294 \ub54c\uc5d0\ub294 \ucd1d\uc720\ub85c \ud558\uba70, \ucd1d\uc720\ubb3c\uc758 \uad00\ub9ac \ubc0f \ucc98\ubd84\uc740 \uc0ac\uc6d0\ucd1d\ud68c\uc758 \uacb0\uc758\uc5d0 \uc758\ud55c\ub2e4.","\ucd1d\uc720\ub294 \uc9c0\ubd84\uad8c\uc774 \uc778\uc815\ub418\ub294 \uacf5\ub3d9\uc18c\uc720 \ud615\ud0dc\uc774\ub2e4.","\ucd1d\uc720\ubb3c\uc5d0 \ub300\ud574\uc11c\ub294 \uac01 \uad6c\uc131\uc6d0\uc774 \ubd84\ud560\uccad\uad6c\uad8c\uc744 \uac00\uc9c4\ub2e4.","\ucd1d\uc720\ub294 \uc870\ud569\uc758 \uc18c\uc720\ud615\ud0dc\ub85c\uc11c \ud569\uc720\uc640 \ub3d9\uc77c\ud558\ub2e4."],t.s)
B.als=s(["\ucd1d\uc720\ubb3c\uc758 \uad00\ub9ac \ubc0f \ucc98\ubd84\uc740 \uc0ac\uc6d0\ucd1d\ud68c\uc758 \uacb0\uc758\uc5d0 \uc758\ud55c\ub2e4"],t.s)
B.a3i=s(["\uc81c275\uc870","\ucd1d\uc720"],t.s)
B.bxm=new A.a("gen_cl_realright_28","civil_law","\ubb3c\uad8c\ubcc0\ub3d9\xb7\uc810\uc720\xb7\ucd1d\uc720",null,"\ucd1d\uc720\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aB1,0,"\ubbfc\ubc95 \uc81c275\uc870\ub294 \ubc95\uc778\uc774 \uc544\ub2cc \uc0ac\ub2e8\uc758 \uc0ac\uc6d0\uc774 \uc9d1\ud569\uccb4\ub85c\uc11c \ubb3c\uac74\uc744 \uc18c\uc720\ud558\ub294 \ub54c\uc5d0\ub294 \ucd1d\uc720\ub85c \ud55c\ub2e4\uace0 \uaddc\uc815\ud558\uace0, \uc81c276\uc870\ub294 \ucd1d\uc720\ubb3c\uc758 \uad00\ub9ac \ubc0f \ucc98\ubd84\uc740 \uc0ac\uc6d0\ucd1d\ud68c\uc758 \uacb0\uc758\uc5d0 \uc758\ud55c\ub2e4\uace0 \uc815\ud55c\ub2e4. \ucd1d\uc720\uc5d0\ub294 \uc9c0\ubd84\uc774 \uc778\uc815\ub418\uc9c0 \uc54a\uace0 \ubd84\ud560\uccad\uad6c\ub3c4 \ud5c8\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4.",B.als,B.a3i,null)
B.a7I=s(["\uacf5\uc720\uc790\ub294 \uacf5\uc720\ubb3c\uc758 \ubd84\ud560\uc744 \uccad\uad6c\ud560 \uc218 \uc788\uc73c\ub098, 5\ub144 \ub0b4\uc758 \uae30\uac04\uc73c\ub85c \ubd84\ud560\ud558\uc9c0 \uc544\ub2c8\ud560 \uac83\uc744 \uc57d\uc815\ud560 \uc218 \uc788\ub2e4.","\uacf5\uc720\ubb3c\ubd84\ud560\uccad\uad6c\uad8c\uc740 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \uc81c\ud55c\ub418\uc9c0 \uc54a\ub294\ub2e4.","\uacf5\uc720\uc790\ub294 \ubd84\ud560\uae08\uc9c0\uc758 \uc57d\uc815\uc744 \ud560 \uc218 \uc5c6\ub2e4.","\uacf5\uc720\ubb3c\ubd84\ud560\uccad\uad6c\uad8c\uc740 \ucd1d\uc720\ubb3c\uc5d0\ub3c4 \ub3d9\uc77c\ud558\uac8c \uc778\uc815\ub41c\ub2e4."],t.s)
B.aiv=s(["5\ub144 \ub0b4\uc758 \uae30\uac04\uc73c\ub85c \ubd84\ud560\ud558\uc9c0 \uc544\ub2c8\ud560 \uac83\uc744 \uc57d\uc815\ud560 \uc218 \uc788\ub2e4"],t.s)
B.aWY=s(["\uc81c268\uc870","\uacf5\uc720\ubb3c\ubd84\ud560\uccad\uad6c\uad8c"],t.s)
B.bDl=new A.a("gen_cl_realright_29","civil_law","\ubb3c\uad8c\ubcc0\ub3d9\xb7\uc810\uc720\xb7\ucd1d\uc720",null,"\uacf5\uc720\ubb3c\ubd84\ud560\uccad\uad6c\uad8c\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.a7I,0,"\ubbfc\ubc95 \uc81c268\uc870 \uc81c1\ud56d\uc740 \uacf5\uc720\uc790\ub294 \uacf5\uc720\ubb3c\uc758 \ubd84\ud560\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4\uace0 \ud558\uba74\uc11c\ub3c4, 5\ub144 \ub0b4\uc758 \uae30\uac04\uc73c\ub85c \ubd84\ud560\ud558\uc9c0 \uc544\ub2c8\ud560 \uac83\uc744 \uc57d\uc815\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc774\ub7ec\ud55c \ubd84\ud560\uae08\uc9c0\ud2b9\uc57d\uc740 \uac31\uc2e0\ud560 \uc218 \uc788\uc73c\ub098 \uadf8 \uae30\uac04\uc740 \uac31\uc2e0\ud55c \ub0a0\ub85c\ubd80\ud130 5\ub144\uc744 \ub118\uc9c0 \ubabb\ud55c\ub2e4.",B.aiv,B.aWY,null)
B.a7K=s(["\uc18c\uc720\uc758 \uc758\uc0ac\ub85c \ud558\ub294 \uc810\uc720\ub97c \uc790\uc8fc\uc810\uc720\ub77c \ud558\uace0, \uadf8\ub807\uc9c0 \uc54a\uc740 \uc810\uc720\ub97c \ud0c0\uc8fc\uc810\uc720\ub77c \ud558\uba70 \ucde8\ub4dd\uc2dc\ud6a8\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \uc790\uc8fc\uc810\uc720\ub97c \uc694\uac74\uc73c\ub85c \ud55c\ub2e4.","\uc790\uc8fc\uc810\uc720\uc640 \ud0c0\uc8fc\uc810\uc720\uc758 \uad6c\ubcc4\uc740 \ucde8\ub4dd\uc2dc\ud6a8\uc640 \ubb34\uad00\ud558\ub2e4.","\ud0c0\uc8fc\uc810\uc720\ub3c4 \uc18c\uc720\uc758 \uc758\uc0ac\uac00 \uc788\ub294 \uc810\uc720\ub85c\uc11c \uc790\uc8fc\uc810\uc720\uc640 \ub3d9\uc77c\ud558\uac8c \ucde8\uae09\ub41c\ub2e4.","\uc810\uc720\uc790\uc758 \uc810\uc720\ub294 \uc5b8\uc81c\ub098 \ud0c0\uc8fc\uc810\uc720\ub85c \ucd94\uc815\ub41c\ub2e4."],t.s)
B.b4X=s(["\ubbfc\ubc95 \uc81c245\uc870\uc758 \ucde8\ub4dd\uc2dc\ud6a8\ub294 \uc790\uc8fc\uc810\uc720\ub97c \uc694\uac74\uc73c\ub85c \ud55c\ub2e4"],t.s)
B.b4F=s(["\uc790\uc8fc\uc810\uc720","\uc81c197\uc870 \ucd94\uc815"],t.s)
B.bHG=new A.a("gen_cl_realright_30","civil_law","\ubb3c\uad8c\ubcc0\ub3d9\xb7\uc810\uc720\xb7\ucd1d\uc720",null,"\uc810\uc720\uc758 \ud0dc\uc591 \uc911 \uc790\uc8fc\uc810\uc720\uc640 \ud0c0\uc8fc\uc810\uc720\uc758 \uad6c\ubcc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.a7K,0,"\uc18c\uc720\uc758 \uc758\uc0ac\ub85c \ud558\ub294 \uc810\uc720\ub97c \uc790\uc8fc\uc810\uc720, \uadf8\ub7ec\ud558\uc9c0 \uc544\ub2c8\ud55c \uc810\uc720\ub97c \ud0c0\uc8fc\uc810\uc720\ub77c \ud558\uba70, \ubbfc\ubc95 \uc81c245\uc870\uc758 \ucde8\ub4dd\uc2dc\ud6a8\ub294 \uc790\uc8fc\uc810\uc720\ub97c \uc694\uac74\uc73c\ub85c \ud55c\ub2e4. \ubbfc\ubc95 \uc81c197\uc870 \uc81c1\ud56d\uc5d0 \ub530\ub77c \uc810\uc720\uc790\ub294 \uc18c\uc720\uc758 \uc758\uc0ac\ub85c \uc810\uc720\ud55c \uac83\uc73c\ub85c \ucd94\uc815\ub41c\ub2e4.",B.b4X,B.b4F,null)
B.axl=s(["\ub9e4\ub9e4\ub294 \uc694\ubb3c\uacc4\uc57d\uc774\ubbc0\ub85c \ubaa9\uc801\ubb3c\uc758 \uc778\ub3c4\uac00 \uc788\uc5b4\uc57c \uc131\ub9bd\ud55c\ub2e4.","\ub9e4\ub9e4\ub294 \ub2f9\uc0ac\uc790 \uc77c\ubc29\uc774 \uc7ac\uc0b0\uad8c\uc744 \uc0c1\ub300\ubc29\uc5d0\uac8c \uc774\uc804\ud560 \uac83\uc744 \uc57d\uc815\ud558\uace0 \uc0c1\ub300\ubc29\uc774 \ub300\uae08\uc744 \uc9c0\uae09\ud560 \uac83\uc744 \uc57d\uc815\ud568\uc73c\ub85c\uc368 \uc131\ub9bd\ud558\ub294 \ub099\uc131\xb7\ubd88\uc694\uc2dd\uacc4\uc57d\uc774\ub2e4.","\ub9e4\ub9e4\ub294 \uc11c\uba74\uc73c\ub85c \uc791\uc131\ud558\uc9c0 \uc54a\uc73c\uba74 \ud6a8\ub825\uc774 \uc5c6\ub2e4.","\ub9e4\ub9e4\ub294 \ubc18\ub4dc\uc2dc \ubaa9\uc801\ubb3c\uc758 \uc18c\uc720\uad8c\uc774\uc804\ub4f1\uae30\ub97c \ub9c8\uccd0\uc57c \uc131\ub9bd\ud55c\ub2e4."],t.s)
B.aL6=s(["\ub2f9\uc0ac\uc790 \uc77c\ubc29\uc774 \uc7ac\uc0b0\uad8c\uc744 \uc0c1\ub300\ubc29\uc5d0\uac8c \uc774\uc804\ud560 \uac83\uc744 \uc57d\uc815\ud558\uace0 \uc0c1\ub300\ubc29\uc774 \uadf8 \ub300\uae08\uc744 \uc9c0\uae09\ud560 \uac83\uc744 \uc57d\uc815\ud568\uc73c\ub85c\uc368 \uc131\ub9bd\ud558\ub294 \ub099\uc131\xb7\ubd88\uc694\uc2dd\xb7\uc720\uc0c1\xb7\uc30d\ubb34\uacc4\uc57d\uc774\ub2e4"],t.s)
B.asK=s(["\ub9e4\ub9e4\uc758 \uc131\ub9bd","\ub099\uc131\uacc4\uc57d","\uc81c563\uc870"],t.s)
B.boz=new A.a("gen_cl_typedcontract_1","civil_law","\uc804\ud615\uacc4\uc57d \uac01\ub860(\ub9e4\ub9e4\xb7\uc784\ub300\ucc28\xb7\ub3c4\uae09 \ub4f1)",null,"\ub9e4\ub9e4\uc758 \uc131\ub9bd\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.axl,1,"\ubbfc\ubc95 \uc81c563\uc870\uc5d0 \ub530\ub77c \ub9e4\ub9e4\ub294 \ub2f9\uc0ac\uc790 \uc77c\ubc29\uc774 \uc7ac\uc0b0\uad8c\uc744 \uc0c1\ub300\ubc29\uc5d0\uac8c \uc774\uc804\ud560 \uac83\uc744 \uc57d\uc815\ud558\uace0 \uc0c1\ub300\ubc29\uc774 \uadf8 \ub300\uae08\uc744 \uc9c0\uae09\ud560 \uac83\uc744 \uc57d\uc815\ud568\uc73c\ub85c\uc368 \uc131\ub9bd\ud558\ub294 \ub099\uc131\xb7\ubd88\uc694\uc2dd\xb7\uc720\uc0c1\xb7\uc30d\ubb34\uacc4\uc57d\uc774\ub2e4. \ubaa9\uc801\ubb3c\uc758 \uc778\ub3c4\ub098 \ub4f1\uae30\ub294 \uc774\ud589\uc758 \ubb38\uc81c\uc77c \ubfd0 \uc131\ub9bd\uc694\uac74\uc774 \uc544\ub2c8\ub2e4.",B.aL6,B.asK,null)
B.afZ=s(["\uacc4\uc57d\uae08\uc740 \ud574\uc57d\uae08\uc73c\ub85c \ucd94\uc815\ub41c\ub2e4.","\ub9e4\uc218\uc778\uc774 \uacc4\uc57d\uae08\uc744 \uc9c0\uae09\ud55c \uacbd\uc6b0 \ub9e4\uc218\uc778\uc740 \uc774\ub97c \ud3ec\uae30\ud558\uace0 \uacc4\uc57d\uc744 \ud574\uc81c\ud560 \uc218 \uc788\ub2e4.","\ub9e4\ub3c4\uc778\uc740 \uacc4\uc57d\uae08\uc758 \ubc30\uc561\uc744 \uc0c1\ud658\ud558\uace0 \uacc4\uc57d\uc744 \ud574\uc81c\ud560 \uc218 \uc788\ub2e4.","\ub2f9\uc0ac\uc790 \uc77c\ubc29\uc774 \uc774\ud589\uc5d0 \ucc29\uc218\ud55c \ud6c4\uc5d0\ub3c4 \uc0c1\ub300\ubc29\uc740 \uc5b8\uc81c\ub098 \uacc4\uc57d\uae08\uc5d0 \uc758\ud55c \ud574\uc81c\ub97c \ud560 \uc218 \uc788\ub2e4."],t.s)
B.anf=s(["\ub2f9\uc0ac\uc790 \uc77c\ubc29\uc774 \uc774\ud589\uc5d0 \ucc29\uc218\ud558\uae30 \uc804\uae4c\uc9c0\ub9cc \uacc4\uc57d\uae08\uc5d0 \uc758\ud55c \ud574\uc81c\uac00 \uac00\ub2a5\ud558\ub2e4"],t.s)
B.ac6=s(["\uacc4\uc57d\uae08","\ud574\uc57d\uae08","\uc774\ud589\uc758 \ucc29\uc218"],t.s)
B.bnY=new A.a("gen_cl_typedcontract_2","civil_law","\uc804\ud615\uacc4\uc57d \uac01\ub860(\ub9e4\ub9e4\xb7\uc784\ub300\ucc28\xb7\ub3c4\uae09 \ub4f1)",null,"\uacc4\uc57d\uae08\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.afZ,3,"\ubbfc\ubc95 \uc81c565\uc870\uc5d0 \uc758\ud558\uba74 \ub2f9\uc0ac\uc790 \uc77c\ubc29\uc774 \uc774\ud589\uc5d0 \ucc29\uc218\ud558\uae30 \uc804\uae4c\uc9c0\ub9cc \uacc4\uc57d\uae08\uc5d0 \uc758\ud55c \ud574\uc81c\uac00 \uac00\ub2a5\ud558\ub2e4. \ub2f9\uc0ac\uc790 \uc77c\ubc29\uc774 \uc774\ubbf8 \uc774\ud589\uc5d0 \ucc29\uc218\ud55c \uacbd\uc6b0\uc5d0\ub294 \uc0c1\ub300\ubc29\ub3c4 \ub354 \uc774\uc0c1 \uacc4\uc57d\uae08 \ud574\uc81c\ub97c \ud560 \uc218 \uc5c6\ub2e4\ub294 \uac83\uc774 \ud310\ub840\uc758 \ud0dc\ub3c4\uc774\ub2e4.",B.anf,B.ac6,null)
B.aUS=s(["\ud2b9\uc815\ubb3c\ub9e4\ub9e4\uc5d0\uc11c \ubaa9\uc801\ubb3c\uc5d0 \ud558\uc790\uac00 \uc788\ub294 \uacbd\uc6b0 \uc120\uc758\xb7\ubb34\uacfc\uc2e4\uc778 \ub9e4\uc218\uc778\uc740 \uacc4\uc57d\ubaa9\uc801\uc744 \ub2ec\uc131\ud560 \uc218 \uc5c6\ub294 \ub54c\uc5d0 \ud55c\ud558\uc5ec \uacc4\uc57d\uc744 \ud574\uc81c\ud560 \uc218 \uc788\ub2e4.","\ud558\uc790\ub2f4\ubcf4\ucc45\uc784\uc740 \ub9e4\ub3c4\uc778\uc758 \uace0\uc758\xb7\uacfc\uc2e4\uc744 \uc694\uac74\uc73c\ub85c \ud55c\ub2e4.","\ud558\uc790\ub2f4\ubcf4\ucc45\uc784\uc5d0 \uae30\ud55c \uad8c\ub9ac\ub294 \ud558\uc790\ub97c \ubc1c\uacac\ud55c \ub0a0\ub85c\ubd80\ud130 10\ub144 \ub0b4\uc5d0 \ud589\uc0ac\ud558\uc5ec\uc57c \ud55c\ub2e4.","\uc885\ub958\ub9e4\ub9e4\uc758 \uacbd\uc6b0\uc5d0\ub294 \ud558\uc790\ub2f4\ubcf4\ucc45\uc784\uc774 \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4."],t.s)
B.a2p=s(["\uacc4\uc57d\uc758 \ubaa9\uc801\uc744 \ub2ec\uc131\ud560 \uc218 \uc5c6\ub294 \ub54c\uc5d0\ub294 \ud574\uc81c\uad8c\ub3c4 \uc778\uc815\ud55c\ub2e4"],t.s)
B.Ys=s(["\ud558\uc790\ub2f4\ubcf4\ucc45\uc784","\ubb34\uacfc\uc2e4\ucc45\uc784","\uc81c580\uc870"],t.s)
B.bs1=new A.a("gen_cl_typedcontract_3","civil_law","\uc804\ud615\uacc4\uc57d \uac01\ub860(\ub9e4\ub9e4\xb7\uc784\ub300\ucc28\xb7\ub3c4\uae09 \ub4f1)",null,"\ub9e4\ub3c4\uc778\uc758 \ub2f4\ubcf4\ucc45\uc784(\ud558\uc790\ub2f4\ubcf4\ucc45\uc784)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aUS,0,"\ubbfc\ubc95 \uc81c580\uc870\ub294 \ub9e4\ub9e4\ubaa9\uc801\ubb3c\uc5d0 \ud558\uc790\uac00 \uc788\ub294 \uacbd\uc6b0 \uc120\uc758\xb7\ubb34\uacfc\uc2e4\uc758 \ub9e4\uc218\uc778\uc5d0\uac8c \uc190\ud574\ubc30\uc0c1\uccad\uad6c\uad8c\uc744 \uc778\uc815\ud558\uace0, \uacc4\uc57d\uc758 \ubaa9\uc801\uc744 \ub2ec\uc131\ud560 \uc218 \uc5c6\ub294 \ub54c\uc5d0\ub294 \ud574\uc81c\uad8c\ub3c4 \uc778\uc815\ud55c\ub2e4. \ud558\uc790\ub2f4\ubcf4\ucc45\uc784\uc740 \ubb34\uacfc\uc2e4\ucc45\uc784\uc73c\ub85c \ub9e4\ub3c4\uc778\uc758 \uace0\uc758\xb7\uacfc\uc2e4\uc744 \uc694\ud558\uc9c0 \uc54a\uc73c\uba70, \uad8c\ub9ac\ud589\uc0ac\uae30\uac04\uc740 \ud558\uc790\ub97c \uc548 \ub0a0\ub85c\ubd80\ud130 6\uac1c\uc6d4\uc774\ub2e4.",B.a2p,B.Ys,null)
B.asD=s(["\ud658\ub9e4\uae30\uac04\uc740 \ubd80\ub3d9\uc0b0\uc758 \uacbd\uc6b0 5\ub144, \ub3d9\uc0b0\uc758 \uacbd\uc6b0 3\ub144\uc744 \ub118\uc9c0 \ubabb\ud55c\ub2e4.","\ud658\ub9e4\ud2b9\uc57d\uc740 \ub9e4\ub9e4\uacc4\uc57d\uacfc \ub3d9\uc2dc\uc5d0 \ud558\uc5ec\uc57c \ud55c\ub2e4.","\ud658\ub9e4\uae30\uac04\uc744 \uc815\ud55c \ub54c\uc5d0\ub294 \uadf8 \ud6c4 \ub2e4\uc2dc \uc774\ub97c \uc5f0\uc7a5\ud558\uc9c0 \ubabb\ud55c\ub2e4.","\ud658\ub9e4\uad8c\uc740 \ub4f1\uae30 \uc5c6\uc774\ub3c4 \uc5b8\uc81c\ub098 \uc81c3\uc790\uc5d0\uac8c \ub300\ud56d\ud560 \uc218 \uc788\ub2e4."],t.s)
B.aw7=s(["\ub9e4\ub9e4\ub4f1\uae30\uc640 \ub3d9\uc2dc\uc5d0 \ud658\ub9e4\uad8c\uc758 \ubcf4\ub958\ub97c \ub4f1\uae30\ud55c \ub54c\uc5d0 \ud55c\ud558\uc5ec \uc81c3\uc790\uc5d0 \ub300\ud558\uc5ec \ud6a8\ub825\uc774 \uc788\ub2e4\uace0 \uaddc\uc815\ud558\ubbc0\ub85c"],t.s)
B.b6g=s(["\ud658\ub9e4","\ud658\ub9e4\uae30\uac04","\uc81c591\uc870\xb7\uc81c592\uc870"],t.s)
B.bQN=new A.a("gen_cl_typedcontract_4","civil_law","\uc804\ud615\uacc4\uc57d \uac01\ub860(\ub9e4\ub9e4\xb7\uc784\ub300\ucc28\xb7\ub3c4\uae09 \ub4f1)",null,"\ud658\ub9e4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.asD,3,"\ubbfc\ubc95 \uc81c591\uc870\ub294 \ud658\ub9e4\uae30\uac04\uc744 \ubd80\ub3d9\uc0b0 5\ub144, \ub3d9\uc0b0 3\ub144\uc744 \ub118\uc9c0 \ubabb\ud558\ub3c4\ub85d \ud558\uace0, \ud55c\ubc88 \uc815\ud55c \uae30\uac04\uc740 \ub2e4\uc2dc \uc5f0\uc7a5\ud558\uc9c0 \ubabb\ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc81c592\uc870\ub294 \ub9e4\ub9e4\ub4f1\uae30\uc640 \ub3d9\uc2dc\uc5d0 \ud658\ub9e4\uad8c\uc758 \ubcf4\ub958\ub97c \ub4f1\uae30\ud55c \ub54c\uc5d0 \ud55c\ud558\uc5ec \uc81c3\uc790\uc5d0 \ub300\ud558\uc5ec \ud6a8\ub825\uc774 \uc788\ub2e4\uace0 \uaddc\uc815\ud558\ubbc0\ub85c, \ud658\ub9e4\uad8c\uc744 \uc81c3\uc790\uc5d0\uac8c \ub300\ud56d\ud558\ub824\uba74 \ub4f1\uae30\uac00 \ud544\uc694\ud558\ub2e4.",B.aw7,B.b6g,null)
B.aX3=s(["\uc11c\uba74\uc5d0 \uc758\ud558\uc9c0 \uc54a\uc740 \uc99d\uc5ec\ub294 \uac01 \ub2f9\uc0ac\uc790\uac00 \uc774\ub97c \ud574\uc81c\ud560 \uc218 \uc788\ub2e4.","\uc11c\uba74\uc5d0 \uc758\ud558\uc9c0 \uc54a\uc740 \uc99d\uc5ec\ub77c\ub3c4 \uc77c\ub2e8 \uc774\ud589\ud55c \ubd80\ubd84\uc5d0 \ub300\ud558\uc5ec\ub294 \ud574\uc81c\uc758 \uc601\ud5a5\uc774 \ubbf8\uce58\uc9c0 \uc54a\ub294\ub2e4.","\uc11c\uba74\uc5d0 \uc758\ud558\uc9c0 \uc54a\uc740 \uc99d\uc5ec\ub294 \ubb34\ud6a8\uc774\ub2e4.","\uc11c\uba74\uc5d0 \uc758\ud558\uc9c0 \uc54a\uc740 \uc99d\uc5ec\ub294 \uc99d\uc5ec\uc790\ub9cc \ud574\uc81c\ud560 \uc218 \uc788\uace0 \uc218\uc99d\uc790\ub294 \ud574\uc81c\ud560 \uc218 \uc5c6\ub2e4."],t.s)
B.a4S=s(["\uc774\ubbf8 \uc774\ud589\ud55c \ubd80\ubd84\uc5d0 \ub300\ud558\uc5ec\ub294 \ud574\uc81c\uc758 \uc601\ud5a5\uc774 \ubbf8\uce58\uc9c0 \uc544\ub2c8\ud55c\ub2e4"],t.s)
B.aWJ=s(["\uc11c\uba74\uc5d0 \uc758\ud558\uc9c0 \uc54a\uc740 \uc99d\uc5ec","\ud574\uc81c\uc758 \uc18c\uae09\ud6a8 \uc81c\ud55c","\uc81c555\uc870"],t.s)
B.bIa=new A.a("gen_cl_typedcontract_5","civil_law","\uc804\ud615\uacc4\uc57d \uac01\ub860(\ub9e4\ub9e4\xb7\uc784\ub300\ucc28\xb7\ub3c4\uae09 \ub4f1)",null,"\uc11c\uba74\uc5d0 \uc758\ud558\uc9c0 \uc54a\uc740 \uc99d\uc5ec\uc758 \ud574\uc81c\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aX3,1,"\ubbfc\ubc95 \uc81c555\uc870\ub294 \uc99d\uc5ec\uc758 \uc758\uc0ac\uac00 \uc11c\uba74\uc73c\ub85c \ud45c\uc2dc\ub418\uc9c0 \uc544\ub2c8\ud55c \uacbd\uc6b0 \uac01 \ub2f9\uc0ac\uc790\uac00 \uc774\ub97c \ud574\uc81c\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud558\uace0, \uc81c558\uc870\ub294 \uc774\ubbf8 \uc774\ud589\ud55c \ubd80\ubd84\uc5d0 \ub300\ud558\uc5ec\ub294 \ud574\uc81c\uc758 \uc601\ud5a5\uc774 \ubbf8\uce58\uc9c0 \uc544\ub2c8\ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc989 \ud574\uc81c\ub294 \uc7a5\ub798\uc5d0 \ub300\ud574\uc11c\ub9cc \ud6a8\ub825\uc774 \uc788\ub2e4.",B.a4S,B.aWJ,null)
B.acd=s(["\uc218\uc99d\uc790\uac00 \uc99d\uc5ec\uc790\uc5d0 \ub300\ud558\uc5ec \ubc94\uc8c4\ud589\uc704\ub97c \ud55c \ub54c \uc99d\uc5ec\uc790\ub294 \uc99d\uc5ec\ub97c \ud574\uc81c\ud560 \uc218 \uc788\ub2e4.","\uc218\uc99d\uc790\uac00 \uc99d\uc5ec\uc790\uc5d0 \ub300\ud558\uc5ec \ubd80\uc591\uc758\ubb34\ub97c \uc774\ud589\ud558\uc9c0 \uc544\ub2c8\ud55c \ub54c \uc99d\uc5ec\ub97c \ud574\uc81c\ud560 \uc218 \uc788\ub2e4.","\ud574\uc81c\uad8c\uc740 \ud574\uc81c\uc6d0\uc778\uc774 \uc788\uc74c\uc744 \uc548 \ub0a0\ub85c\ubd80\ud130 6\uc6d4\uc744 \uacbd\uacfc\ud558\uac70\ub098 \uc99d\uc5ec\uc790\uac00 \uc218\uc99d\uc790\uc5d0\uac8c \uc6a9\uc11c\uc758 \uc758\uc0ac\ub97c \ud45c\uc2dc\ud55c \ub54c \uc18c\uba78\ud55c\ub2e4.","\ub9dd\uc740\ud589\uc704\ub85c \uc778\ud55c \ud574\uc81c\ub294 \uc774\ubbf8 \uc774\ud589\ud55c \ubd80\ubd84\uc5d0 \ub300\ud558\uc5ec\ub3c4 \uc18c\uae09\ud558\uc5ec \ubc18\ud658\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4."],t.s)
B.bcX=s(["\uc774\ubbf8 \uc774\ud589\ud55c \ubd80\ubd84\uc5d0\ub294 \ud574\uc81c\uc758 \ud6a8\ub825\uc774 \ubbf8\uce58\uc9c0 \uc54a\uc73c\ubbc0\ub85c \uc18c\uae09\ud558\uc5ec \ubc18\ud658\uc744 \uccad\uad6c\ud560 \uc218 \uc5c6\ub2e4"],t.s)
B.ami=s(["\ub9dd\uc740\ud589\uc704","\uc99d\uc5ec\ud574\uc81c","\uc81c556\uc870"],t.s)
B.bP_=new A.a("gen_cl_typedcontract_6","civil_law","\uc804\ud615\uacc4\uc57d \uac01\ub860(\ub9e4\ub9e4\xb7\uc784\ub300\ucc28\xb7\ub3c4\uae09 \ub4f1)",null,"\ubc30\uc740\ud589\uc704(\ub9dd\uc740\ud589\uc704)\ub85c \uc778\ud55c \uc99d\uc5ec\uc758 \ud574\uc81c\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.acd,3,"\ubbfc\ubc95 \uc81c556\uc870, \uc81c557\uc870\uc5d0 \ub530\ub77c \uc218\uc99d\uc790\uc758 \ubc94\uc8c4\ud589\uc704\ub098 \ubd80\uc591\uc758\ubb34 \ubd88\uc774\ud589\uc774 \uc788\uc73c\uba74 \uc99d\uc5ec\uc790\ub294 \uc99d\uc5ec\ub97c \ud574\uc81c\ud560 \uc218 \uc788\uace0, \uc81c556\uc870 \uc81c2\ud56d\uc740 \ud574\uc81c\uc6d0\uc778\uc744 \uc548 \ub0a0\ub85c\ubd80\ud130 6\uc6d4 \uacbd\uacfc \ub610\ub294 \uc6a9\uc11c\uc758 \uc758\uc0ac\ud45c\uc2dc\ub85c \ud574\uc81c\uad8c\uc774 \uc18c\uba78\ud568\uc744 \uaddc\uc815\ud55c\ub2e4. \ub2e4\ub9cc \uc81c558\uc870\uc5d0 \uc758\ud574 \uc774\ubbf8 \uc774\ud589\ud55c \ubd80\ubd84\uc5d0\ub294 \ud574\uc81c\uc758 \ud6a8\ub825\uc774 \ubbf8\uce58\uc9c0 \uc54a\uc73c\ubbc0\ub85c \uc18c\uae09\ud558\uc5ec \ubc18\ud658\uc744 \uccad\uad6c\ud560 \uc218 \uc5c6\ub2e4.",B.bcX,B.ami,null)
B.aMj=s(["\uc784\ucc28\uc778\uc774 \ubaa9\uc801\ubb3c\uc758 \ubcf4\uc874\uc5d0 \ud544\uc694\ube44\ub97c \uc9c0\ucd9c\ud55c \ub54c\uc5d0\ub294 \uc784\ub300\uc778\uc5d0\uac8c \uadf8 \uc0c1\ud658\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4.","\uc784\ucc28\uc778\uc774 \uc9c0\ucd9c\ud55c \uc720\uc775\ube44\ub294 \uc784\ub300\ucc28 \uc885\ub8cc \uc989\uc2dc \uccad\uad6c\ud558\uc5ec\uc57c \ud558\uba70 \uc784\ub300\uc778\uc758 \uc120\ud0dd\uad8c\uc740 \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4.","\ud544\uc694\ube44\uc0c1\ud658\uccad\uad6c\uad8c\uc740 \uc784\ub300\ucc28 \uc885\ub8cc \ud6c4\uc5d0\ub9cc \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4.","\uc720\uc775\ube44\uc0c1\ud658\uccad\uad6c\uad8c\uc740 \uc784\ub300\uc778\uc774 \ubaa9\uc801\ubb3c\uc744 \ubc18\ud658\ubc1b\uae30 \uc804\uc5d0\ub294 \ubc1c\uc0dd\ud558\uc9c0 \uc54a\ub294\ub2e4.","\ube44\uc6a9\uc0c1\ud658\uccad\uad6c\uad8c\uc740 \uc784\ucc28\uc778\uc758 \uadc0\ucc45\uc0ac\uc720\ub85c \ubaa9\uc801\ubb3c\uc774 \uba78\uc2e4\ub41c \uacbd\uc6b0\uc5d0\ub3c4 \uc778\uc815\ub41c\ub2e4."],t.s)
B.XL=s(["\uc784\ucc28\uc778\uc774 \uc784\ucc28\ubb3c\uc758 \ubcf4\uc874\uc5d0 \uad00\ud55c \ud544\uc694\ube44\ub97c \uc9c0\ucd9c\ud55c \ub54c\uc5d0\ub294 \uc784\ub300\uc778\uc5d0\uac8c \uadf8 \uc0c1\ud658\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.Yg=s(["\ube44\uc6a9\uc0c1\ud658\uccad\uad6c\uad8c","\ud544\uc694\ube44","\uc81c626\uc870"],t.s)
B.brw=new A.a("gen_cl_typedcontract_7","civil_law","\uc804\ud615\uacc4\uc57d \uac01\ub860(\ub9e4\ub9e4\xb7\uc784\ub300\ucc28\xb7\ub3c4\uae09 \ub4f1)",null,"\uc784\ucc28\uc778\uc758 \ube44\uc6a9\uc0c1\ud658\uccad\uad6c\uad8c\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aMj,0,"\ubbfc\ubc95 \uc81c626\uc870 \uc81c1\ud56d\uc740 \uc784\ucc28\uc778\uc774 \uc784\ucc28\ubb3c\uc758 \ubcf4\uc874\uc5d0 \uad00\ud55c \ud544\uc694\ube44\ub97c \uc9c0\ucd9c\ud55c \ub54c\uc5d0\ub294 \uc784\ub300\uc778\uc5d0\uac8c \uadf8 \uc0c1\ud658\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ud544\uc694\ube44\ub294 \uc9c0\ucd9c \uc989\uc2dc \uccad\uad6c\ud560 \uc218 \uc788\uace0, \uc720\uc775\ube44\ub294 \uc784\ub300\ucc28 \uc885\ub8cc\uc2dc\uc5d0 \uadf8 \uac00\uc561\uc758 \uc99d\uac00\uac00 \ud604\uc874\ud55c \uacbd\uc6b0 \uc784\ub300\uc778\uc758 \uc120\ud0dd\uc5d0 \uc887\uc544 \uc9c0\ucd9c\uc561\uc774\ub098 \uc99d\uac00\uc561\uc758 \uc0c1\ud658\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4.",B.XL,B.Yg,null)
B.a7G=s(["\uac74\ubb3c\uc758 \uc784\ucc28\uc778\uc774 \uc784\ub300\uc778\uc758 \ub3d9\uc758\ub97c \uc5bb\uc5b4 \ubd80\uc18d\uc2dc\ud0a8 \ubb3c\uac74\uc774 \uc788\ub294 \ub54c \uc784\ub300\ucc28 \uc885\ub8cc\uc2dc \uc784\ub300\uc778\uc5d0\uac8c \ub9e4\uc218\uccad\uad6c\ub97c \ud560 \uc218 \uc788\ub2e4.","\ubd80\uc18d\ubb3c\ub9e4\uc218\uccad\uad6c\uad8c\uc5d0 \uad00\ud55c \uaddc\uc815\uc740 \ud3b8\uba74\uc801 \uac15\ud589\uaddc\uc815\uc73c\ub85c\uc11c \uc784\ucc28\uc778\uc5d0\uac8c \ubd88\ub9ac\ud55c \uc57d\uc815\uc740 \ubb34\ud6a8\uc774\ub2e4.","\uc784\ucc28\uc778\uc758 \ucc44\ubb34\ubd88\uc774\ud589\uc73c\ub85c \uc778\ud558\uc5ec \uc784\ub300\ucc28\uac00 \ud574\uc9c0\ub41c \uacbd\uc6b0\uc5d0\ub3c4 \ubd80\uc18d\ubb3c\ub9e4\uc218\uccad\uad6c\uad8c\uc774 \uc778\uc815\ub41c\ub2e4.","\ubd80\uc18d\ubb3c\ub9e4\uc218\uccad\uad6c\uad8c\uc740 \ud615\uc131\uad8c\uc73c\ub85c\uc11c \uc784\ucc28\uc778\uc758 \uccad\uad6c\ub9cc\uc73c\ub85c \ub9e4\ub9e4\uacc4\uc57d\uc774 \uc131\ub9bd\ud55c \uac83\uacfc \uac19\uc740 \ud6a8\uacfc\uac00 \ubc1c\uc0dd\ud55c\ub2e4."],t.s)
B.b_K=s(["\uc784\ucc28\uc778\uc758 \ucc44\ubb34\ubd88\uc774\ud589\uc744 \uc774\uc720\ub85c \uc784\ub300\ucc28\uac00 \ud574\uc9c0\ub41c \uacbd\uc6b0\uc5d0\ub294 \ubd80\uc18d\ubb3c\ub9e4\uc218\uccad\uad6c\uad8c\uc774 \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.ag1=s(["\ubd80\uc18d\ubb3c\ub9e4\uc218\uccad\uad6c\uad8c","\ud615\uc131\uad8c","\uc81c646\uc870"],t.s)
B.bHz=new A.a("gen_cl_typedcontract_8","civil_law","\uc804\ud615\uacc4\uc57d \uac01\ub860(\ub9e4\ub9e4\xb7\uc784\ub300\ucc28\xb7\ub3c4\uae09 \ub4f1)",null,"\uac74\ubb3c\uc784\ucc28\uc778\uc758 \ubd80\uc18d\ubb3c\ub9e4\uc218\uccad\uad6c\uad8c\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.a7G,2,"\ubbfc\ubc95 \uc81c646\uc870, \uc81c652\uc870\uc5d0 \ub530\ub77c \ubd80\uc18d\ubb3c\ub9e4\uc218\uccad\uad6c\uad8c\uc740 \ud3b8\uba74\uc801 \uac15\ud589\uaddc\uc815\uc774\uba70 \ud615\uc131\uad8c\uc73c\ub85c\uc11c\uc758 \uc131\uc9c8\uc744 \uac00\uc9c4\ub2e4. \uadf8\ub7ec\ub098 \ud310\ub840\ub294 \uc784\ucc28\uc778\uc758 \ucc44\ubb34\ubd88\uc774\ud589\uc744 \uc774\uc720\ub85c \uc784\ub300\ucc28\uac00 \ud574\uc9c0\ub41c \uacbd\uc6b0\uc5d0\ub294 \ubd80\uc18d\ubb3c\ub9e4\uc218\uccad\uad6c\uad8c\uc774 \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4\uace0 \ubcf8\ub2e4.",B.b_K,B.ag1,null)
B.ahd=s(["\uc784\ucc28\uc778\uc740 \uc784\ub300\uc778\uc758 \ub3d9\uc758 \uc5c6\uc774\ub3c4 \uc790\uc720\ub85c\uc774 \uc784\ucc28\ubb3c\uc744 \uc804\ub300\ud560 \uc218 \uc788\ub2e4.","\uc784\ucc28\uc778\uc774 \uc784\ub300\uc778\uc758 \ub3d9\uc758 \uc5c6\uc774 \uc81c3\uc790\uc5d0\uac8c \uc784\ucc28\ubb3c\uc744 \uc804\ub300\ud55c \uacbd\uc6b0 \uc784\ub300\uc778\uc740 \uc6d0\uce59\uc801\uc73c\ub85c \uacc4\uc57d\uc744 \ud574\uc9c0\ud560 \uc218 \uc788\ub2e4.","\uc784\ub300\uc778\uc758 \ub3d9\uc758\ub97c \uc5bb\uc740 \uc804\ub300\ucc28\uc758 \uacbd\uc6b0 \uc804\ucc28\uc778\uc740 \uc784\ub300\uc778\uc5d0 \ub300\ud558\uc5ec \uc9c1\uc811 \uc758\ubb34\ub97c \ubd80\ub2f4\ud558\uc9c0 \uc54a\ub294\ub2e4.","\ubb34\ub2e8\uc804\ub300\uc758 \uacbd\uc6b0\uc5d0\ub3c4 \uadf8 \uc804\ub300\uac00 \uc784\ub300\uc778\uc5d0 \ub300\ud55c \ubc30\uc2e0\uc801 \ud589\uc704\ub77c\uace0 \uc778\uc815\ub418\uc9c0 \uc54a\ub294 \ud2b9\ubcc4\ud55c \uc0ac\uc815\uc774 \uc788\uc73c\uba74 \ud574\uc9c0\ud560 \uc218 \uc5c6\ub2e4\ub294 \uac83\uc774 \ud310\ub840\uc774\ub2e4."],t.s)
B.b6c=s(["\uc784\ub300\uc778\uc5d0 \ub300\ud55c \ubc30\uc2e0\uc801 \ud589\uc704\ub77c\uace0 \ud560 \uc218 \uc5c6\ub294 \ud2b9\ubcc4\ud55c \uc0ac\uc815\uc774 \uc788\ub294 \uacbd\uc6b0\uc5d0\ub294 \ud574\uc9c0\uad8c\uc774 \uc81c\ud55c\ub41c\ub2e4"],t.s)
B.a7n=s(["\ubb34\ub2e8\uc804\ub300","\ubc30\uc2e0\ud589\uc704\uc774\ub860","\uc81c629\uc870"],t.s)
B.bCg=new A.a("gen_cl_typedcontract_9","civil_law","\uc804\ud615\uacc4\uc57d \uac01\ub860(\ub9e4\ub9e4\xb7\uc784\ub300\ucc28\xb7\ub3c4\uae09 \ub4f1)",null,"\uc784\ucc28\uad8c\uc758 \uc591\ub3c4\uc640 \uc804\ub300\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.ahd,3,"\ubbfc\ubc95 \uc81c629\uc870\ub294 \uc784\ucc28\uc778\uc774 \uc784\ub300\uc778\uc758 \ub3d9\uc758 \uc5c6\uc774 \uc784\ucc28\uad8c\uc744 \uc591\ub3c4\ud558\uac70\ub098 \uc784\ucc28\ubb3c\uc744 \uc804\ub300\ud558\uc9c0 \ubabb\ud558\uba70, \uc774\uc5d0 \uc704\ubc18\ud55c \ub54c\uc5d0\ub294 \uc784\ub300\uc778\uc774 \uacc4\uc57d\uc744 \ud574\uc9c0\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ub2e4\ub9cc \ud310\ub840\ub294 \ubb34\ub2e8\uc804\ub300\ub77c\ub3c4 \uc784\ub300\uc778\uc5d0 \ub300\ud55c \ubc30\uc2e0\uc801 \ud589\uc704\ub77c\uace0 \ud560 \uc218 \uc5c6\ub294 \ud2b9\ubcc4\ud55c \uc0ac\uc815\uc774 \uc788\ub294 \uacbd\uc6b0\uc5d0\ub294 \ud574\uc9c0\uad8c\uc774 \uc81c\ud55c\ub41c\ub2e4\uace0 \ubcf8\ub2e4. \ub3d9\uc758\ub97c \uc5bb\uc740 \uc804\ub300\ucc28\uc758 \uacbd\uc6b0 \uc804\ucc28\uc778\uc740 \uc81c630\uc870\uc5d0 \uc758\ud574 \uc784\ub300\uc778\uc5d0 \ub300\ud558\uc5ec \uc9c1\uc811 \uc758\ubb34\ub97c \ubd80\ub2f4\ud55c\ub2e4.",B.b6c,B.a7n,null)
B.b6j=s(["\ubcf4\uc99d\uae08\uc740 \uc784\ub300\ucc28 \uc885\ub8cc\uc640 \ub3d9\uc2dc\uc5d0 \ubcc4\ub3c4\uc758 \uacf5\uc81c \uc5c6\uc774 \uadf8\ub300\ub85c \ubc18\ud658\ub418\uc5b4\uc57c \ud55c\ub2e4.","\uc784\ub300\ucc28 \uc885\ub8cc \ud6c4 \ubaa9\uc801\ubb3c\uc774 \ubc18\ud658\ub420 \ub54c\uae4c\uc9c0 \ubc1c\uc0dd\ud55c \uc784\ucc28\uc778\uc758 \uc5f0\uccb4\ucc28\uc784 \ub4f1 \uc190\ud574\ubc30\uc0c1\ucc44\ubb34\ub294 \ubcc4\ub3c4\uc758 \uc758\uc0ac\ud45c\uc2dc \uc5c6\uc774 \ubcf4\uc99d\uae08\uc5d0\uc11c \ub2f9\uc5f0\ud788 \uacf5\uc81c\ub41c\ub2e4.","\ubcf4\uc99d\uae08\uacc4\uc57d\uc740 \uc784\ub300\ucc28\uacc4\uc57d\uacfc \ubcc4\uac1c\ub85c \ubc18\ub4dc\uc2dc \uc11c\uba74\uc73c\ub85c \uccb4\uacb0\ub418\uc5b4\uc57c \uc720\ud6a8\ud558\ub2e4.","\uc784\ucc28\uc778\uc740 \ubcf4\uc99d\uae08\uc758 \uc874\uc7ac\ub97c \uc774\uc720\ub85c \ucc28\uc784\uc9c0\uae09\uc758\ubb34\ub97c \uac70\uc808\ud560 \uc218 \uc788\ub2e4."],t.s)
B.b8K=s(["\ubcc4\ub3c4\uc758 \uc0c1\uacc4 \uc758\uc0ac\ud45c\uc2dc \uc5c6\uc774 \ubcf4\uc99d\uae08\uc5d0\uc11c \ub2f9\uc5f0\ud788 \uacf5\uc81c\ub41c\ub2e4"],t.s)
B.bft=s(["\uc784\ub300\ucc28\ubcf4\uc99d\uae08","\ub2f9\uc5f0\uacf5\uc81c","\uc5f0\uccb4\ucc28\uc784"],t.s)
B.bEg=new A.a("gen_cl_typedcontract_10","civil_law","\uc804\ud615\uacc4\uc57d \uac01\ub860(\ub9e4\ub9e4\xb7\uc784\ub300\ucc28\xb7\ub3c4\uae09 \ub4f1)",null,"\uc784\ub300\ucc28\ubcf4\uc99d\uae08\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.b6j,1,"\ud310\ub840\uc5d0 \ub530\ub974\uba74 \uc784\ub300\ucc28\ubcf4\uc99d\uae08\uc740 \uc784\ub300\ucc28 \uc874\uc18d \uc911\uc758 \uc5f0\uccb4\ucc28\uc784\ubfd0\ub9cc \uc544\ub2c8\ub77c \ubaa9\uc801\ubb3c \ubc18\ud658\uc2dc\uae4c\uc9c0 \ubc1c\uc0dd\ud558\ub294 \uc190\ud574\ubc30\uc0c1\ucc44\uad8c \ub4f1 \uc784\ub300\ucc28\uad00\uacc4\uc5d0\uc11c \ubc1c\uc0dd\ud558\ub294 \uc784\ucc28\uc778\uc758 \ubaa8\ub4e0 \ucc44\ubb34\ub97c \ub2f4\ubcf4\ud558\uba70, \uc784\ub300\ucc28 \uc885\ub8cc \ud6c4 \ubaa9\uc801\ubb3c\uc774 \ubc18\ud658\ub428\uacfc \ub3d9\uc2dc\uc5d0 \ubcc4\ub3c4\uc758 \uc0c1\uacc4 \uc758\uc0ac\ud45c\uc2dc \uc5c6\uc774 \ubcf4\uc99d\uae08\uc5d0\uc11c \ub2f9\uc5f0\ud788 \uacf5\uc81c\ub41c\ub2e4.",B.b8K,B.bft,null)
B.aSa=s(["\uc644\uc131\ub41c \ubaa9\uc801\ubb3c\uc5d0 \ud558\uc790\uac00 \uc788\ub294 \uacbd\uc6b0 \ub3c4\uae09\uc778\uc740 \uc218\uae09\uc778\uc5d0 \ub300\ud558\uc5ec \uc0c1\ub2f9\ud55c \uae30\uac04\uc744 \uc815\ud558\uc5ec \uadf8 \ud558\uc790\uc758 \ubcf4\uc218\ub97c \uccad\uad6c\ud560 \uc218 \uc788\ub2e4.","\ud558\uc790\uac00 \uc911\uc694\ud558\uc9c0 \uc544\ub2c8\ud558\uace0 \uadf8 \ubcf4\uc218\uc5d0 \uacfc\ub2e4\ud55c \ube44\uc6a9\uc744 \uc694\ud560 \uacbd\uc6b0\uc5d0\ub3c4 \ub3c4\uae09\uc778\uc740 \ud558\uc790\ubcf4\uc218\ub97c \uccad\uad6c\ud560 \uc218 \uc788\ub2e4.","\uac74\ubb3c \uae30\ud0c0 \ud1a0\uc9c0\uc758 \uacf5\uc791\ubb3c\uc5d0 \ub300\ud558\uc5ec\ub294 \ud558\uc790\ub85c \uc778\ud574 \uacc4\uc57d\uc758 \ubaa9\uc801\uc744 \ub2ec\uc131\ud560 \uc218 \uc5c6\ub354\ub77c\ub3c4 \ub3c4\uae09\uc778\uc740 \uacc4\uc57d\uc744 \ud574\uc81c\ud560 \uc218 \uc5c6\ub2e4.","\uc218\uae09\uc778\uc758 \ub2f4\ubcf4\ucc45\uc784\uc740 \ub3c4\uae09\uc778\uc758 \uace0\uc758\xb7\uacfc\uc2e4\uc774 \uc788\uc5b4\uc57c \ubc1c\uc0dd\ud55c\ub2e4."],t.s)
B.aMT=s(["\ub3c4\uae09\uc778\uc740 \uc218\uae09\uc778\uc5d0 \ub300\ud558\uc5ec \uc0c1\ub2f9\ud55c \uae30\uac04\uc744 \uc815\ud558\uc5ec \uadf8 \ud558\uc790\uc758 \ubcf4\uc218\ub97c \uccad\uad6c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.ax5=s(["\uc218\uae09\uc778\uc758 \ub2f4\ubcf4\ucc45\uc784","\ud558\uc790\ubcf4\uc218\uccad\uad6c\uad8c","\uc81c667\uc870"],t.s)
B.bQF=new A.a("gen_cl_typedcontract_11","civil_law","\uc804\ud615\uacc4\uc57d \uac01\ub860(\ub9e4\ub9e4\xb7\uc784\ub300\ucc28\xb7\ub3c4\uae09 \ub4f1)",null,"\ub3c4\uae09\uc778\uc758 \ud558\uc790\ubcf4\uc218\uccad\uad6c\uad8c\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aSa,0,"\ubbfc\ubc95 \uc81c667\uc870 \uc81c1\ud56d\uc740 \uc644\uc131\ub41c \ubaa9\uc801\ubb3c \ub610\ub294 \uc644\uc131 \uc804\uc758 \uc131\ucde8\ub41c \ubd80\ubd84\uc5d0 \ud558\uc790\uac00 \uc788\ub294 \ub54c\uc5d0\ub294 \ub3c4\uae09\uc778\uc740 \uc218\uae09\uc778\uc5d0 \ub300\ud558\uc5ec \uc0c1\ub2f9\ud55c \uae30\uac04\uc744 \uc815\ud558\uc5ec \uadf8 \ud558\uc790\uc758 \ubcf4\uc218\ub97c \uccad\uad6c\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ub2e4\ub9cc \ud558\uc790\uac00 \uc911\uc694\ud558\uc9c0 \uc544\ub2c8\ud558\uba74\uc11c \uadf8 \ubcf4\uc218\uc5d0 \uacfc\ub2e4\ud55c \ube44\uc6a9\uc744 \uc694\ud560 \ub54c\uc5d0\ub294 \ubcf4\uc218\ub97c \uccad\uad6c\ud558\uc9c0 \ubabb\ud55c\ub2e4. \ub610\ud55c \uc81c668\uc870 \ub2e8\uc11c\uc5d0 \ub530\ub77c \uac74\ubb3c \uae30\ud0c0 \ud1a0\uc9c0\uc758 \uacf5\uc791\ubb3c\uc5d0 \ub300\ud558\uc5ec\ub294 \uacc4\uc57d\uc744 \ud574\uc81c\ud558\uc9c0 \ubabb\ud55c\ub2e4.",B.aMT,B.ax5,null)
B.bb8=s(["\uc218\uae09\uc778\uc774 \uc790\uae30\uc758 \uc7ac\ub8cc\uc640 \ub178\ub825\uc73c\ub85c \uac74\ubb3c\uc744 \uc644\uc131\ud55c \uacbd\uc6b0 \ud2b9\uc57d\uc774 \uc5c6\ub294 \ud55c \uc644\uc131\uacfc \ub3d9\uc2dc\uc5d0 \uc18c\uc720\uad8c\uc740 \ub3c4\uae09\uc778\uc5d0\uac8c \uc6d0\uc2dc\uc801\uc73c\ub85c \uadc0\uc18d\ud55c\ub2e4.","\uc218\uae09\uc778\uc774 \uc790\uae30\uc758 \uc7ac\ub8cc\ub97c \ub300\ubd80\ubd84 \uc81c\uacf5\ud558\uc5ec \uac74\ubb3c\uc744 \uc644\uc131\ud55c \uacbd\uc6b0 \ud2b9\uc57d\uc774 \uc5c6\ub294 \ud55c \uc644\uc131\uac74\ubb3c\uc758 \uc18c\uc720\uad8c\uc740 \uc6d0\uc2dc\uc801\uc73c\ub85c \uc218\uae09\uc778\uc5d0\uac8c \uadc0\uc18d\ud558\uace0 \uc774\ud6c4 \uc778\ub3c4\uc5d0 \uc758\ud558\uc5ec \ub3c4\uae09\uc778\uc5d0\uac8c \uc774\uc804\ub41c\ub2e4.","\uac74\ubb3c\uc2e0\ucd95\ub3c4\uae09\uacc4\uc57d\uc5d0\uc11c\ub294 \uc7ac\ub8cc\uc758 \uc81c\uacf5\uc790\uc640 \uad00\uacc4\uc5c6\uc774 \uc5b8\uc81c\ub098 \ub3c4\uae09\uc778\uc774 \uc6d0\uc2dc\ucde8\ub4dd\uc790\uac00 \ub41c\ub2e4.","\uc218\uae09\uc778\uc774 \uc7ac\ub8cc\ub97c \uc81c\uacf5\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ub3c4\uae09\uc778 \uba85\uc758\ub85c \ubcf4\uc874\ub4f1\uae30\uac00 \uacbd\ub8cc\ub418\uba74 \uadf8 \ub4f1\uae30\ub294 \ud56d\uc0c1 \ubb34\ud6a8\uc774\ub2e4."],t.s)
B.b8i=s(["\uc644\uc131\ub41c \uac74\ubb3c\uc758 \uc18c\uc720\uad8c\uc740 \uc6d0\uc2dc\uc801\uc73c\ub85c \uc218\uae09\uc778\uc5d0\uac8c \uadc0\uc18d\ud558\uace0 \uc774\ud6c4 \uc778\ub3c4\uc5d0 \uc758\ud558\uc5ec \ub3c4\uae09\uc778\uc5d0\uac8c \uc774\uc804\ub41c\ub2e4"],t.s)
B.aof=s(["\ub3c4\uae09","\uc644\uc131\ubb3c \uc18c\uc720\uad8c \uadc0\uc18d","\uc6d0\uc2dc\ucde8\ub4dd"],t.s)
B.bDs=new A.a("gen_cl_typedcontract_12","civil_law","\uc804\ud615\uacc4\uc57d \uac01\ub860(\ub9e4\ub9e4\xb7\uc784\ub300\ucc28\xb7\ub3c4\uae09 \ub4f1)",null,"\ub3c4\uae09\uc5d0\uc11c \uc644\uc131\ubb3c\uc758 \uc18c\uc720\uad8c \uadc0\uc18d\uc5d0 \uad00\ud55c \ud310\ub840\uc758 \ud0dc\ub3c4\ub85c \uc633\uc740 \uac83\uc740?",B.bb8,1,"\ud310\ub840\ub294 \uac74\ubb3c\uc2e0\ucd95\ub3c4\uae09\uacc4\uc57d\uc5d0\uc11c \uc218\uae09\uc778\uc774 \uc790\uae30\uc758 \ub178\ub825\uacfc \uc7ac\ub8cc\ub97c \ub4e4\uc5ec \uac74\ubb3c\uc744 \uc644\uc131\ud55c \uacbd\uc6b0, \ub3c4\uae09\uc778\uacfc \uc218\uae09\uc778 \uc0ac\uc774\uc5d0 \ub3c4\uae09\uc778 \uba85\uc758\ub85c \uac74\ucd95\ud5c8\uac00\ub97c \ubc1b\uc558\ub2e4\ub294 \ub4f1 \ud2b9\ubcc4\ud55c \uc57d\uc815\uc774 \uc5c6\ub294 \ud55c \uc644\uc131\ub41c \uac74\ubb3c\uc758 \uc18c\uc720\uad8c\uc740 \uc6d0\uc2dc\uc801\uc73c\ub85c \uc218\uae09\uc778\uc5d0\uac8c \uadc0\uc18d\ud558\uace0 \uc774\ud6c4 \uc778\ub3c4\uc5d0 \uc758\ud558\uc5ec \ub3c4\uae09\uc778\uc5d0\uac8c \uc774\uc804\ub41c\ub2e4\uace0 \ubcf8\ub2e4.",B.b8i,B.aof,null)
B.aJ5=s(["\uc218\uae09\uc778\uc774 \uc77c\uc744 \uc644\uc131\ud558\uae30 \uc804\uc5d0\ub294 \ub3c4\uae09\uc778\uc740 \uc5b8\uc81c\ub4e0\uc9c0 \uc190\ud574\ub97c \ubc30\uc0c1\ud558\uace0 \uacc4\uc57d\uc744 \ud574\uc81c\ud560 \uc218 \uc788\ub2e4.","\ub3c4\uae09\uc778\uc758 \uc784\uc758\ud574\uc81c\uad8c\uc740 \uc218\uae09\uc778\uc758 \uadc0\ucc45\uc0ac\uc720\uac00 \uc788\uc5b4\uc57c\ub9cc \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4.","\uc77c\uc774 \uc644\uc131\ub41c \ud6c4\uc5d0\ub294 \ub3c4\uae09\uc778\uc740 \uc190\ud574\ubc30\uc0c1 \uc5c6\uc774 \uacc4\uc57d\uc744 \ud574\uc81c\ud560 \uc218 \uc788\ub2e4.","\ub3c4\uae09\uc778\uc758 \uc784\uc758\ud574\uc81c\uad8c\uc740 \ud2b9\uc57d\uc73c\ub85c\ub3c4 \ubc30\uc81c\ud560 \uc218 \uc5c6\ub294 \uac15\ud589\uaddc\uc815\uc774\ub2e4."],t.s)
B.aBd=s(["\uc218\uae09\uc778\uc774 \uc77c\uc744 \uc644\uc131\ud558\uae30 \uc804\uc5d0\ub294 \ub3c4\uae09\uc778\uc740 \uc190\ud574\ub97c \ubc30\uc0c1\ud558\uace0 \uacc4\uc57d\uc744 \ud574\uc81c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.a63=s(["\ub3c4\uae09\uc778\uc758 \ud574\uc81c\uad8c","\uc784\uc758\ud574\uc81c","\uc81c673\uc870"],t.s)
B.bM9=new A.a("gen_cl_typedcontract_13","civil_law","\uc804\ud615\uacc4\uc57d \uac01\ub860(\ub9e4\ub9e4\xb7\uc784\ub300\ucc28\xb7\ub3c4\uae09 \ub4f1)",null,"\ub3c4\uae09\uc778\uc758 \uc784\uc758\ud574\uc81c\uad8c\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aJ5,0,"\ubbfc\ubc95 \uc81c673\uc870\ub294 \uc218\uae09\uc778\uc774 \uc77c\uc744 \uc644\uc131\ud558\uae30 \uc804\uc5d0\ub294 \ub3c4\uae09\uc778\uc740 \uc190\ud574\ub97c \ubc30\uc0c1\ud558\uace0 \uacc4\uc57d\uc744 \ud574\uc81c\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc774\ub294 \ub3c4\uae09\uc778\uc758 \ubb34\uacfc\uc2e4 \uc784\uc758\ud574\uc81c\uad8c\uc73c\ub85c\uc11c \uc218\uae09\uc778\uc758 \uadc0\ucc45\uc0ac\uc720\ub97c \uc694\uac74\uc73c\ub85c \ud558\uc9c0 \uc54a\uc73c\uba70 \uc784\uc758\uaddc\uc815\uc73c\ub85c\uc11c \ub2f9\uc0ac\uc790\uc758 \ud2b9\uc57d\uc73c\ub85c \ubc30\uc81c\ud560 \uc218 \uc788\ub2e4.",B.aBd,B.a63,null)
B.bdt=s(["\uc0ac\uc6a9\ub300\ucc28\ub294 \ub2f9\uc0ac\uc790 \uc77c\ubc29\uc774 \ubb34\uc0c1\uc73c\ub85c \uc0ac\uc6a9\xb7\uc218\uc775\ud558\uac8c \ud558\uae30 \uc704\ud558\uc5ec \ubaa9\uc801\ubb3c\uc744 \uc778\ub3c4\ud560 \uac83\uc744 \uc57d\uc815\ud558\uace0 \uc0c1\ub300\ubc29\uc774 \uc774\ub97c \uc0ac\uc6a9\xb7\uc218\uc775\ud55c \ud6c4 \ubc18\ud658\ud560 \uac83\uc744 \uc57d\uc815\ud568\uc73c\ub85c\uc368 \uc131\ub9bd\ud55c\ub2e4.","\uc0ac\uc6a9\ub300\ucc28\ub294 \uc720\uc0c1\uacc4\uc57d\uc774\ub2e4.","\ucc28\uc8fc\ub294 \ubaa9\uc801\ubb3c\uc758 \ud1b5\uc0c1\uc758 \ud544\uc694\ube44\ub3c4 \ub300\uc8fc\uc5d0\uac8c \uc0c1\ud658\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4.","\uc0ac\uc6a9\ub300\ucc28\ub294 \ucc28\uc8fc\uc758 \uc0ac\ub9dd\uc73c\ub85c\ub3c4 \uadf8 \ud6a8\ub825\uc744 \uc783\uc9c0 \uc54a\ub294\ub2e4."],t.s)
B.b4N=s(["\uc0c1\ub300\ubc29\uc5d0\uac8c \ubb34\uc0c1\uc73c\ub85c \uc0ac\uc6a9\xb7\uc218\uc775\ud558\uac8c \ud558\uae30 \uc704\ud558\uc5ec \ubaa9\uc801\ubb3c\uc744 \uc778\ub3c4\ud560 \uac83\uc744 \uc57d\uc815\ud558\uace0 \uc0c1\ub300\ubc29\uc740 \uc774\ub97c \uc0ac\uc6a9\xb7\uc218\uc775\ud55c \ud6c4 \uadf8 \ubb3c\uac74\uc744 \ubc18\ud658\ud560 \uac83\uc744 \uc57d\uc815\ud568\uc73c\ub85c\uc368 \uc131\ub9bd\ud558\ub294"],t.s)
B.aAv=s(["\uc0ac\uc6a9\ub300\ucc28","\ubb34\uc0c1\uacc4\uc57d","\uc81c609\uc870"],t.s)
B.byP=new A.a("gen_cl_typedcontract_14","civil_law","\uc804\ud615\uacc4\uc57d \uac01\ub860(\ub9e4\ub9e4\xb7\uc784\ub300\ucc28\xb7\ub3c4\uae09 \ub4f1)",null,"\uc0ac\uc6a9\ub300\ucc28\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.bdt,0,"\ubbfc\ubc95 \uc81c609\uc870\ub294 \uc0ac\uc6a9\ub300\ucc28\ub97c \ub2f9\uc0ac\uc790 \uc77c\ubc29\uc774 \uc0c1\ub300\ubc29\uc5d0\uac8c \ubb34\uc0c1\uc73c\ub85c \uc0ac\uc6a9\xb7\uc218\uc775\ud558\uac8c \ud558\uae30 \uc704\ud558\uc5ec \ubaa9\uc801\ubb3c\uc744 \uc778\ub3c4\ud560 \uac83\uc744 \uc57d\uc815\ud558\uace0 \uc0c1\ub300\ubc29\uc740 \uc774\ub97c \uc0ac\uc6a9\xb7\uc218\uc775\ud55c \ud6c4 \uadf8 \ubb3c\uac74\uc744 \ubc18\ud658\ud560 \uac83\uc744 \uc57d\uc815\ud568\uc73c\ub85c\uc368 \uc131\ub9bd\ud558\ub294 \ub099\uc131\xb7\ubb34\uc0c1\xb7\ud3b8\ubb34\uacc4\uc57d\uc73c\ub85c \uaddc\uc815\ud55c\ub2e4. \ucc28\uc8fc\ub294 \ud1b5\uc0c1\uc758 \ud544\uc694\ube44\ub97c \ubd80\ub2f4\ud558\uba70(\uc81c611\uc870), \ucc28\uc8fc\uc758 \uc0ac\ub9dd\uc2dc \uc0ac\uc6a9\ub300\ucc28\ub294 \uc885\ub8cc\ud55c\ub2e4(\uc81c614\uc870).",B.b4N,B.aAv,null)
B.ar3=s(["\uc18c\ube44\ub300\ucc28\ub294 \ub2f9\uc0ac\uc790 \uc77c\ubc29\uc774 \uae08\uc804 \uae30\ud0c0 \ub300\uccb4\ubb3c\uc758 \uc18c\uc720\uad8c\uc744 \uc0c1\ub300\ubc29\uc5d0\uac8c \uc774\uc804\ud560 \uac83\uc744 \uc57d\uc815\ud558\uace0 \uc0c1\ub300\ubc29\uc740 \uadf8\uc640 \uac19\uc740 \uc885\ub958\xb7\ud488\uc9c8\xb7\uc218\ub7c9\uc73c\ub85c \ubc18\ud658\ud560 \uac83\uc744 \uc57d\uc815\ud568\uc73c\ub85c\uc368 \uc131\ub9bd\ud55c\ub2e4.","\uc774\uc790\uc788\ub294 \uc18c\ube44\ub300\ucc28\uc758 \uacbd\uc6b0 \ub300\uc8fc\ub294 \ubaa9\uc801\ubb3c\uc758 \ud558\uc790\uc5d0 \ub300\ud558\uc5ec \ub2f4\ubcf4\ucc45\uc784\uc744 \uc9c0\uc9c0 \uc54a\ub294\ub2e4.","\ub2f9\uc0ac\uc790\uac00 \uc774\uc790\uc758 \uc57d\uc815\uc744 \ud558\uc9c0 \uc54a\uc558\ub354\ub77c\ub3c4 \ub300\uc8fc\ub294 \ud56d\uc0c1 \ubc95\uc815\uc774\uc790\ub97c \uccad\uad6c\ud560 \uc218 \uc788\ub2e4.","\uc18c\ube44\ub300\ucc28\ub294 \ub2f9\uc0ac\uc790\uc758 \ud2b9\uc57d\uc774\ub098 \ubc18\ub300\uc57d\uc815\uc774 \uc5c6\ub294 \ud55c \ubb34\uc774\uc790\uac00 \uc6d0\uce59\uc774\ub2e4."],t.s)
B.aj9=s(["\uc774\uc790\ub294 \ud2b9\uc57d\uc774 \uc788\ub294 \uacbd\uc6b0\uc5d0\ub9cc \uccad\uad6c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.aEJ=s(["\uc18c\ube44\ub300\ucc28","\ubb34\uc774\uc790\uc6d0\uce59","\uc81c598\uc870"],t.s)
B.bp4=new A.a("gen_cl_typedcontract_15","civil_law","\uc804\ud615\uacc4\uc57d \uac01\ub860(\ub9e4\ub9e4\xb7\uc784\ub300\ucc28\xb7\ub3c4\uae09 \ub4f1)",null,"\uc18c\ube44\ub300\ucc28\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.ar3,2,"\ubbfc\ubc95 \uc81c598\uc870\ub294 \uc18c\ube44\ub300\ucc28\uc758 \uc131\ub9bd\uc744 \uaddc\uc815\ud558\uace0, \uc18c\ube44\ub300\ucc28\ub294 \ubb34\uc774\uc790\uac00 \uc6d0\uce59\uc774\uba70 \uc774\uc790\ub294 \ud2b9\uc57d\uc774 \uc788\ub294 \uacbd\uc6b0\uc5d0\ub9cc \uccad\uad6c\ud560 \uc218 \uc788\ub2e4. \uc774\uc790\uc788\ub294 \uc18c\ube44\ub300\ucc28\uc5d0\uc11c \ub300\uc8fc\ub294 \ub9e4\ub3c4\uc778\uacfc \uac19\uc740 \ub2f4\ubcf4\ucc45\uc784\uc744 \uc9c0\ubbc0\ub85c(\uc81c602\uc870), \ud2b9\uc57d \uc5c6\uc774 \ub300\uc8fc\uac00 \ud56d\uc0c1 \ubc95\uc815\uc774\uc790\ub97c \uccad\uad6c\ud560 \uc218 \uc788\ub2e4\ub294 \uac83\uc740 \uc633\uc9c0 \uc54a\ub2e4.",B.aj9,B.aEJ,null)
B.Z3=s(["\uc900\uc18c\ube44\ub300\ucc28\ub294 \uae08\uc804 \uae30\ud0c0 \ub300\uccb4\ubb3c\uc744 \uc9c0\uae09\ud560 \uc758\ubb34 \uc788\ub294 \uc790\uac00 \uadf8 \ubaa9\uc801\ubb3c\uc744 \uc18c\ube44\ub300\ucc28\uc758 \ubaa9\uc801\ubb3c\ub85c \ud560 \uac83\uc744 \uc57d\uc815\ud568\uc73c\ub85c\uc368 \uc131\ub9bd\ud55c\ub2e4.","\uc900\uc18c\ube44\ub300\ucc28\uac00 \uc131\ub9bd\ud558\uba74 \uad6c\ucc44\ubb34\ub294 \uc5b8\uc81c\ub098 \uc18c\uba78\ud558\uc9c0 \uc54a\uace0 \uc2e0\ucc44\ubb34\uc640 \ubcd1\uc874\ud55c\ub2e4.","\uc900\uc18c\ube44\ub300\ucc28\ub294 \uc694\ubb3c\uacc4\uc57d\uc73c\ub85c\uc11c \ubaa9\uc801\ubb3c\uc758 \ud604\uc2e4\uc801 \uc778\ub3c4\uac00 \uc788\uc5b4\uc57c \uc131\ub9bd\ud55c\ub2e4.","\uc900\uc18c\ube44\ub300\ucc28\uc758 \uc131\ub9bd\uc73c\ub85c \uad6c\ucc44\ubb34\uc5d0 \ubd99\uc5b4 \uc788\ub358 \ub2f4\ubcf4\ub294 \ub2f9\uc5f0\ud788 \uc18c\uba78\ud55c\ub2e4."],t.s)
B.arC=s(["\ub2f9\uc0ac\uc790\uac00 \uadf8 \ubaa9\uc801\ubb3c\uc744 \uc18c\ube44\ub300\ucc28\uc758 \ubaa9\uc801\uc73c\ub85c \ud560 \uac83\uc744 \uc57d\uc815\ud568\uc73c\ub85c\uc368 \uc900\uc18c\ube44\ub300\ucc28\uac00 \uc131\ub9bd\ud55c\ub2e4"],t.s)
B.Vs=s(["\uc900\uc18c\ube44\ub300\ucc28","\uacbd\uac1c\uc640\uc758 \uad6c\ubcc4","\uc81c605\uc870"],t.s)
B.bIP=new A.a("gen_cl_typedcontract_16","civil_law","\uc804\ud615\uacc4\uc57d \uac01\ub860(\ub9e4\ub9e4\xb7\uc784\ub300\ucc28\xb7\ub3c4\uae09 \ub4f1)",null,"\uc900\uc18c\ube44\ub300\ucc28\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.Z3,0,"\ubbfc\ubc95 \uc81c605\uc870\ub294 \ub2f9\uc0ac\uc790 \uc30d\ubc29\uc774 \uae08\uc804 \uae30\ud0c0 \ub300\uccb4\ubb3c\uc744 \uc9c0\uae09\ud560 \uc758\ubb34\uac00 \uc788\ub294 \uacbd\uc6b0\uc5d0 \ub2f9\uc0ac\uc790\uac00 \uadf8 \ubaa9\uc801\ubb3c\uc744 \uc18c\ube44\ub300\ucc28\uc758 \ubaa9\uc801\uc73c\ub85c \ud560 \uac83\uc744 \uc57d\uc815\ud568\uc73c\ub85c\uc368 \uc900\uc18c\ube44\ub300\ucc28\uac00 \uc131\ub9bd\ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc900\uc18c\ube44\ub300\ucc28\uac00 \uc131\ub9bd\ud558\uba74 \uc6d0\uce59\uc801\uc73c\ub85c \uad6c\ucc44\ubb34\ub294 \uc18c\uba78\ud558\uace0 \uc2e0\ucc44\ubb34\uac00 \uc131\ub9bd\ud558\uba70, \ub2f9\uc0ac\uc790\uc758 \uc758\uc0ac\uc5d0 \ub530\ub77c \uad6c\ucc44\ubb34\uc758 \ub2f4\ubcf4\ub098 \ud56d\ubcc0\uad8c\uc740 \uc2e0\ucc44\ubb34\uc5d0 \uc874\uc18d\uc2dc\ud0ac \uc218 \uc788\ub2e4.",B.arC,B.Vs,null)
B.atV=s(["\uc218\uc784\uc778\uc740 \uc704\uc784\uc758 \ubcf8\uc9c0\uc5d0 \ub530\ub77c \uc120\ub7c9\ud55c \uad00\ub9ac\uc790\uc758 \uc8fc\uc758\ub85c\uc368 \uc704\uc784\uc0ac\ubb34\ub97c \ucc98\ub9ac\ud558\uc5ec\uc57c \ud55c\ub2e4.","\uc704\uc784\uc740 \uc720\uc0c1\uacc4\uc57d\uc774 \uc6d0\uce59\uc774\ubbc0\ub85c \ud2b9\uc57d\uc774 \uc5c6\uc5b4\ub3c4 \ubcf4\uc218\ub97c \uccad\uad6c\ud560 \uc218 \uc788\ub2e4.","\uc218\uc784\uc778\uc740 \ud2b9\ubcc4\ud55c \uc0ac\uc815\uc774 \uc5c6\ub294 \ud55c \uc704\uc784\uc778\uc758 \uc2b9\ub099 \uc5c6\uc774\ub3c4 \uc790\uc720\ub85c\uc774 \ubcf5\uc784\ud560 \uc218 \uc788\ub2e4.","\uc704\uc784\uacc4\uc57d\uc740 \uc11c\uba74\uc73c\ub85c \uccb4\uacb0\ud558\uc9c0 \uc54a\uc73c\uba74 \ubb34\ud6a8\uc774\ub2e4."],t.s)
B.b5r=s(["\uc218\uc784\uc778\uc774 \uc704\uc784\uc758 \ubcf8\uc9c0\uc5d0 \ub530\ub77c \uc120\ub7c9\ud55c \uad00\ub9ac\uc790\uc758 \uc8fc\uc758\ub85c\uc368 \uc704\uc784\uc0ac\ubb34\ub97c \ucc98\ub9ac\ud558\uc5ec\uc57c \ud55c\ub2e4"],t.s)
B.b6a=s(["\uc704\uc784","\uc120\uad00\uc8fc\uc758\uc758\ubb34","\uc81c681\uc870"],t.s)
B.bCS=new A.a("gen_cl_typedcontract_17","civil_law","\uc804\ud615\uacc4\uc57d \uac01\ub860(\ub9e4\ub9e4\xb7\uc784\ub300\ucc28\xb7\ub3c4\uae09 \ub4f1)",null,"\uc704\uc784\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.atV,0,"\ubbfc\ubc95 \uc81c681\uc870\ub294 \uc218\uc784\uc778\uc774 \uc704\uc784\uc758 \ubcf8\uc9c0\uc5d0 \ub530\ub77c \uc120\ub7c9\ud55c \uad00\ub9ac\uc790\uc758 \uc8fc\uc758\ub85c\uc368 \uc704\uc784\uc0ac\ubb34\ub97c \ucc98\ub9ac\ud558\uc5ec\uc57c \ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc704\uc784\uc740 \uc6d0\uce59\uc801\uc73c\ub85c \ubb34\uc0c1\uacc4\uc57d\uc774\uba70 \ud2b9\uc57d\uc774 \uc788\uc5b4\uc57c \ubcf4\uc218\ub97c \uccad\uad6c\ud560 \uc218 \uc788\ub2e4(\uc81c686\uc870).",B.b5r,B.b6a,null)
B.a1O=s(["\uc704\uc784\uacc4\uc57d\uc740 \uac01 \ub2f9\uc0ac\uc790\uac00 \uc5b8\uc81c\ub4e0\uc9c0 \ud574\uc9c0\ud560 \uc218 \uc788\ub2e4.","\uc704\uc784\uc758 \ud574\uc9c0\ub294 \uc18c\uae09\ud6a8\ub97c \uac00\uc9c0\ubbc0\ub85c \uc774\ubbf8 \ucc98\ub9ac\ub41c \uc0ac\ubb34\uc5d0 \uc601\ud5a5\uc744 \ubbf8\uce5c\ub2e4.","\uc218\uc784\uc778\uc740 \ubd80\ub4dd\uc774\ud55c \uc0ac\uc720\uac00 \uc788\uc5b4\ub3c4 \uc704\uc784\uc778\uc758 \ub3d9\uc758 \uc5c6\uc774\ub294 \ud574\uc9c0\ud560 \uc218 \uc5c6\ub2e4.","\uc704\uc784\uc778\uc774 \ud30c\uc0b0\uc120\uace0\ub97c \ubc1b\uc544\ub3c4 \uc704\uc784\uc740 \uc885\ub8cc\ub418\uc9c0 \uc54a\ub294\ub2e4."],t.s)
B.app=s(["\uc704\uc784\uacc4\uc57d\uc740 \uac01 \ub2f9\uc0ac\uc790\uac00 \uc5b8\uc81c\ub4e0\uc9c0 \ud574\uc9c0\ud560 \uc218 \uc788\ub2e4"],t.s)
B.amN=s(["\uc704\uc784\uc758 \ud574\uc9c0","\uc784\uc758\ud574\uc9c0\uad8c","\uc81c689\uc870"],t.s)
B.bPZ=new A.a("gen_cl_typedcontract_18","civil_law","\uc804\ud615\uacc4\uc57d \uac01\ub860(\ub9e4\ub9e4\xb7\uc784\ub300\ucc28\xb7\ub3c4\uae09 \ub4f1)",null,"\uc704\uc784\uc758 \ud574\uc9c0\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.a1O,0,"\ubbfc\ubc95 \uc81c689\uc870 \uc81c1\ud56d\uc740 \uc704\uc784\uacc4\uc57d\uc740 \uac01 \ub2f9\uc0ac\uc790\uac00 \uc5b8\uc81c\ub4e0\uc9c0 \ud574\uc9c0\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ub2e4\ub9cc \uc0c1\ub300\ubc29\uc5d0\uac8c \ubd88\ub9ac\ud55c \uc2dc\uae30\uc5d0 \ud574\uc9c0\ud55c \ub54c\uc5d0\ub294 \ubd80\ub4dd\uc774\ud55c \uc0ac\uc720\uac00 \uc5c6\ub294 \ud55c \uc190\ud574\ub97c \ubc30\uc0c1\ud558\uc5ec\uc57c \ud55c\ub2e4. \uc704\uc784\uc740 \ub2f9\uc0ac\uc790 \uc77c\ubc29\uc758 \uc0ac\ub9dd, \ud30c\uc0b0 \ub610\ub294 \uc218\uc784\uc778\uc758 \uc131\ub144\ud6c4\uacac\uac1c\uc2dc\ub85c \uc885\ub8cc\ud55c\ub2e4(\uc81c690\uc870).",B.app,B.amN,null)
B.b6W=s(["\uc784\uce58\ub294 \ub2f9\uc0ac\uc790 \uc77c\ubc29\uc774 \uc0c1\ub300\ubc29\uc744 \uc704\ud558\uc5ec \uae08\uc804\uc774\ub098 \uc720\uac00\uc99d\uad8c \uae30\ud0c0 \ubb3c\uac74\uc758 \ubcf4\uad00\uc744 \uc704\ud0c1\ud558\uace0 \uc0c1\ub300\ubc29\uc774 \uc774\ub97c \uc2b9\ub099\ud568\uc73c\ub85c\uc368 \uc131\ub9bd\ud55c\ub2e4.","\uc784\uce58\ub294 \ud56d\uc0c1 \uc720\uc0c1\uacc4\uc57d\uc774\ub2e4.","\ubb34\uc0c1\uc218\uce58\uc778\uc740 \uc720\uc0c1\uc218\uce58\uc778\uacfc \ub3d9\uc77c\ud55c \uc8fc\uc758\uc758\ubb34\ub97c \ubd80\ub2f4\ud55c\ub2e4.","\uc218\uce58\uc778\uc740 \uc784\uce58\uc778\uc758 \ub3d9\uc758 \uc5c6\uc774\ub3c4 \uc784\uce58\ubb3c\uc744 \uc790\uc720\ub86d\uac8c \uc0ac\uc6a9\ud560 \uc218 \uc788\ub2e4."],t.s)
B.bdN=s(["\uc0c1\ub300\ubc29\uc5d0 \ub300\ud558\uc5ec \uae08\uc804\uc774\ub098 \uc720\uac00\uc99d\uad8c \uae30\ud0c0 \ubb3c\uac74\uc758 \ubcf4\uad00\uc744 \uc704\ud0c1\ud558\uace0 \uc0c1\ub300\ubc29\uc774 \uc774\ub97c \uc2b9\ub099\ud568\uc73c\ub85c\uc368 \uc131\ub9bd\ud558\ub294"],t.s)
B.aHK=s(["\uc784\uce58","\ubb34\uc0c1\uc218\uce58\uc778\uc758 \uc8fc\uc758\uc758\ubb34","\uc81c693\uc870"],t.s)
B.bz7=new A.a("gen_cl_typedcontract_19","civil_law","\uc804\ud615\uacc4\uc57d \uac01\ub860(\ub9e4\ub9e4\xb7\uc784\ub300\ucc28\xb7\ub3c4\uae09 \ub4f1)",null,"\uc784\uce58\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.b6W,0,"\ubbfc\ubc95 \uc81c693\uc870\ub294 \uc784\uce58\ub97c \ub2f9\uc0ac\uc790 \uc77c\ubc29\uc774 \uc0c1\ub300\ubc29\uc5d0 \ub300\ud558\uc5ec \uae08\uc804\uc774\ub098 \uc720\uac00\uc99d\uad8c \uae30\ud0c0 \ubb3c\uac74\uc758 \ubcf4\uad00\uc744 \uc704\ud0c1\ud558\uace0 \uc0c1\ub300\ubc29\uc774 \uc774\ub97c \uc2b9\ub099\ud568\uc73c\ub85c\uc368 \uc131\ub9bd\ud558\ub294 \ub099\uc131\uacc4\uc57d\uc73c\ub85c \uaddc\uc815\ud55c\ub2e4. \ubb34\uc0c1\uc218\uce58\uc778\uc740 \uc790\uae30 \uc7ac\uc0b0\uacfc \ub3d9\uc77c\ud55c \uc8fc\uc758\ub85c \ubcf4\uad00\ud558\uba74 \ub418\uace0(\uc81c695\uc870), \uc720\uc0c1\uc218\uce58\uc778\ubcf4\ub2e4 \ub0ae\uc740 \uc8fc\uc758\uc758\ubb34\ub97c \ubd80\ub2f4\ud55c\ub2e4.",B.bdN,B.aHK,null)
B.b27=s(["\uc870\ud569\uacc4\uc57d\uc740 2\uc778 \uc774\uc0c1\uc774 \uc0c1\ud638\ucd9c\uc790\ud558\uc5ec \uacf5\ub3d9\uc0ac\uc5c5\uc744 \uacbd\uc601\ud560 \uac83\uc744 \uc57d\uc815\ud568\uc73c\ub85c\uc368 \uc131\ub9bd\ud55c\ub2e4.","\uc870\ud569\uc758 \uc7ac\uc0b0\uc740 \uc870\ud569\uc6d0\uc758 \ub2e8\ub3c5\uc18c\uc720\uc5d0 \uc18d\ud55c\ub2e4.","\uc870\ud569\uc6d0\uc740 \uc5b8\uc81c\ub4e0\uc9c0 \uc790\uc720\ub85c\uc774 \uc9c0\ubd84\uc744 \uc81c3\uc790\uc5d0\uac8c \uc591\ub3c4\ud558\uc5ec \uc870\ud569\uad00\uacc4\uc5d0\uc11c \uc774\ud0c8\ud560 \uc218 \uc788\ub2e4.","\uc870\ud569\uc758 \uc5c5\ubb34\uc9d1\ud589\uc740 \uc870\ud569\uc6d0 \uc804\uc6d0\uc758 \ub3d9\uc758\uac00 \uc5c6\uc73c\uba74 \ud56d\uc0c1 \ubb34\ud6a8\uc774\ub2e4."],t.s)
B.b7b=s(["2\uc778 \uc774\uc0c1\uc774 \uc0c1\ud638\ucd9c\uc790\ud558\uc5ec \uacf5\ub3d9\uc0ac\uc5c5\uc744 \uacbd\uc601\ud560 \uac83\uc744 \uc57d\uc815\ud568\uc73c\ub85c\uc368 \uc131\ub9bd\ud558\ub294"],t.s)
B.bby=s(["\uc870\ud569\uacc4\uc57d","\ud569\uc720","\uc81c703\uc870"],t.s)
B.bF8=new A.a("gen_cl_typedcontract_20","civil_law","\uc804\ud615\uacc4\uc57d \uac01\ub860(\ub9e4\ub9e4\xb7\uc784\ub300\ucc28\xb7\ub3c4\uae09 \ub4f1)",null,"\uc870\ud569\uacc4\uc57d\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.b27,0,"\ubbfc\ubc95 \uc81c703\uc870\ub294 \uc870\ud569\uacc4\uc57d\uc744 2\uc778 \uc774\uc0c1\uc774 \uc0c1\ud638\ucd9c\uc790\ud558\uc5ec \uacf5\ub3d9\uc0ac\uc5c5\uc744 \uacbd\uc601\ud560 \uac83\uc744 \uc57d\uc815\ud568\uc73c\ub85c\uc368 \uc131\ub9bd\ud558\ub294 \uacc4\uc57d\uc73c\ub85c \uaddc\uc815\ud55c\ub2e4. \uc870\ud569\uc7ac\uc0b0\uc740 \uc870\ud569\uc6d0\uc758 \ud569\uc720\uc5d0 \uc18d\ud558\uba70(\uc81c704\uc870), \uc870\ud569\uc758 \ud1b5\uc0c1\uc0ac\ubb34\ub294 \uac01 \uc870\ud569\uc6d0\uc774 \ub2e8\ub3c5\uc73c\ub85c \uc9d1\ud589\ud560 \uc218 \uc788\ub2e4(\uc81c706\uc870).",B.b7b,B.bby,null)
B.alf=s(["\ud654\ud574\ub294 \ub2f9\uc0ac\uc790\uac00 \uc0c1\ud638 \uc591\ubcf4\ud558\uc5ec \ub2f9\uc0ac\uc790 \uac04\uc758 \ubd84\uc7c1\uc744 \uc885\uc9c0\ud560 \uac83\uc744 \uc57d\uc815\ud568\uc73c\ub85c\uc368 \uc131\ub9bd\ud55c\ub2e4.","\ud654\ud574\uacc4\uc57d\uc740 \ucc3d\uc124\uc801 \ud6a8\ub825\uc774 \uc5c6\uace0 \uc885\uc804\uc758 \ubc95\ub960\uad00\uacc4\ub97c \ud655\uc778\ud558\ub294 \ub370 \uadf8\uce5c\ub2e4.","\ud654\ud574\uacc4\uc57d\uc774 \uc131\ub9bd\ud558\uba74 \ucc29\uc624\ub97c \uc774\uc720\ub85c \ucde8\uc18c\ud558\ub294 \uac83\uc774 \ud56d\uc0c1 \ud5c8\uc6a9\ub41c\ub2e4.","\ud654\ud574\uacc4\uc57d\uc758 \ubaa9\uc801\uc778 \ubd84\uc7c1 \uc774\uc678\uc758 \uc0ac\ud56d\uc5d0 \ucc29\uc624\uac00 \uc788\ub294 \uacbd\uc6b0\uc5d0\ub3c4 \ucde8\uc18c\ud560 \uc218 \uc5c6\ub2e4."],t.s)
B.bdX=s(["\ub2f9\uc0ac\uc790\uac00 \uc11c\ub85c \uc591\ubcf4\ud558\uc5ec \ub2f9\uc0ac\uc790 \uac04\uc758 \ubd84\uc7c1\uc744 \uc885\uc9c0\ud560 \uac83\uc744 \uc57d\uc815\ud568\uc73c\ub85c\uc368 \uc131\ub9bd\ud558\ub294"],t.s)
B.a4t=s(["\ud654\ud574\uacc4\uc57d","\ucc3d\uc124\uc801 \ud6a8\ub825","\uc81c731\uc870"],t.s)
B.bIb=new A.a("gen_cl_typedcontract_21","civil_law","\uc804\ud615\uacc4\uc57d \uac01\ub860(\ub9e4\ub9e4\xb7\uc784\ub300\ucc28\xb7\ub3c4\uae09 \ub4f1)",null,"\ud654\ud574\uacc4\uc57d\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.alf,0,"\ubbfc\ubc95 \uc81c731\uc870\ub294 \ud654\ud574\ub97c \ub2f9\uc0ac\uc790\uac00 \uc11c\ub85c \uc591\ubcf4\ud558\uc5ec \ub2f9\uc0ac\uc790 \uac04\uc758 \ubd84\uc7c1\uc744 \uc885\uc9c0\ud560 \uac83\uc744 \uc57d\uc815\ud568\uc73c\ub85c\uc368 \uc131\ub9bd\ud558\ub294 \uacc4\uc57d\uc73c\ub85c \uaddc\uc815\ud55c\ub2e4. \ud654\ud574\uacc4\uc57d\uc740 \ucc3d\uc124\uc801 \ud6a8\ub825\uc744 \uac00\uc9c0\ubbc0\ub85c \uc6d0\uce59\uc801\uc73c\ub85c \ucc29\uc624\ub97c \uc774\uc720\ub85c \ucde8\uc18c\ud560 \uc218 \uc5c6\uc73c\ub098(\uc81c733\uc870 \ubcf8\ubb38), \ud654\ud574\uc758 \ubaa9\uc801\uc778 \ubd84\uc7c1 \uc774\uc678\uc758 \uc0ac\ud56d\uc5d0 \ucc29\uc624\uac00 \uc788\ub294 \uacbd\uc6b0\uc5d0\ub294 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4(\uc81c733\uc870 \ub2e8\uc11c).",B.bdX,B.a4t,null)
B.b6J=s(["\ub9e4\ub9e4\uc758 \uc77c\ubc29\uc608\uc57d\uc740 \uc0c1\ub300\ubc29\uc774 \ub9e4\ub9e4\ub97c \uc644\uacb0\ud560 \uc758\uc0ac\ub97c \ud45c\uc2dc\ud55c \ub54c\uc5d0 \ub9e4\ub9e4\uc758 \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4.","\ub9e4\ub9e4\uc608\uc57d\uc644\uacb0\uad8c\uc740 \ud615\uc131\uad8c\uc774 \uc544\ub2c8\ub77c \uccad\uad6c\uad8c\uc774\ub2e4.","\uc608\uc57d\uc644\uacb0\uad8c\uc758 \ud589\uc0ac\uae30\uac04\uc744 \uc57d\uc815\ud558\uc9c0 \uc54a\uc740 \uacbd\uc6b0 \uc608\uc57d\uc644\uacb0\uad8c\uc740 \uc18c\uba78\ud558\uc9c0 \uc54a\ub294\ub2e4.","\uc608\uc57d\uc644\uacb0\uad8c\uc740 \uc608\uc57d \uc131\ub9bd\uc77c\ub85c\ubd80\ud130 20\ub144\uc758 \uc81c\ucc99\uae30\uac04\uc5d0 \uac78\ub9b0\ub2e4."],t.s)
B.aeZ=s(["\uc0c1\ub300\ubc29\uc774 \ub9e4\ub9e4\ub97c \uc644\uacb0\ud560 \uc758\uc0ac\ub97c \ud45c\uc2dc\ud558\ub294 \ub54c\uc5d0 \ub9e4\ub9e4\uc758 \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4"],t.s)
B.bfk=s(["\ub9e4\ub9e4\uc758 \uc77c\ubc29\uc608\uc57d","\uc608\uc57d\uc644\uacb0\uad8c","\uc81c564\uc870"],t.s)
B.bxR=new A.a("gen_cl_typedcontract_22","civil_law","\uc804\ud615\uacc4\uc57d \uac01\ub860(\ub9e4\ub9e4\xb7\uc784\ub300\ucc28\xb7\ub3c4\uae09 \ub4f1)",null,"\ub9e4\ub9e4\uc758 \uc77c\ubc29\uc608\uc57d\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.b6J,0,"\ubbfc\ubc95 \uc81c564\uc870 \uc81c1\ud56d\uc740 \ub9e4\ub9e4\uc758 \uc77c\ubc29\uc608\uc57d\uc740 \uc0c1\ub300\ubc29\uc774 \ub9e4\ub9e4\ub97c \uc644\uacb0\ud560 \uc758\uc0ac\ub97c \ud45c\uc2dc\ud558\ub294 \ub54c\uc5d0 \ub9e4\ub9e4\uc758 \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc608\uc57d\uc644\uacb0\uad8c\uc740 \ud615\uc131\uad8c\uc73c\ub85c\uc11c \ud310\ub840\uc0c1 \uadf8 \ud589\uc0ac\uae30\uac04\uc744 \uc57d\uc815\ud558\uc9c0 \uc54a\uc740 \uacbd\uc6b0 \uc608\uc57d\uc774 \uc131\ub9bd\ud55c \ub54c\ub85c\ubd80\ud130 10\ub144\uc758 \uc81c\ucc99\uae30\uac04\uc5d0 \uac78\ub9b0\ub2e4.",B.aeZ,B.bfk,null)
B.aKj=s(["\ub9e4\ub9e4\uacc4\uc57d\uc5d0 \uad00\ud55c \ube44\uc6a9\uc740 \ub2f9\uc0ac\uc790 \uc30d\ubc29\uc774 \uade0\ubd84\ud558\uc5ec \ubd80\ub2f4\ud55c\ub2e4.","\ub9e4\ub9e4\uacc4\uc57d\uc5d0 \uad00\ud55c \ube44\uc6a9\uc740 \ud56d\uc0c1 \ub9e4\ub3c4\uc778\uc774 \uc804\ubd80 \ubd80\ub2f4\ud55c\ub2e4.","\ub9e4\ub9e4\uacc4\uc57d\uc5d0 \uad00\ud55c \ube44\uc6a9\uc740 \ud56d\uc0c1 \ub9e4\uc218\uc778\uc774 \uc804\ubd80 \ubd80\ub2f4\ud55c\ub2e4.","\ub9e4\ub9e4\uacc4\uc57d \ube44\uc6a9\uc740 \ubc95\ub960\uc5d0 \uaddc\uc815\uc774 \uc5c6\uc5b4 \ub2f9\uc0ac\uc790 \uac04 \ub2e4\ud23c\uc774 \uc788\uc73c\uba74 \ubc95\uc6d0\uc774 \uc7ac\ub7c9\uc73c\ub85c \uc815\ud55c\ub2e4."],t.s)
B.amu=s(["\ub9e4\ub9e4\uacc4\uc57d\uc5d0 \uad00\ud55c \ube44\uc6a9\uc740 \ub2f9\uc0ac\uc790 \uc30d\ubc29\uc774 \uade0\ubd84\ud558\uc5ec \ubd80\ub2f4\ud55c\ub2e4"],t.s)
B.bbs=s(["\ub9e4\ub9e4\uacc4\uc57d \ube44\uc6a9","\uade0\ubd84\ubd80\ub2f4","\uc81c566\uc870"],t.s)
B.bEw=new A.a("gen_cl_typedcontract_23","civil_law","\uc804\ud615\uacc4\uc57d \uac01\ub860(\ub9e4\ub9e4\xb7\uc784\ub300\ucc28\xb7\ub3c4\uae09 \ub4f1)",null,"\ub9e4\ub9e4\uacc4\uc57d \ube44\uc6a9\uc758 \ubd80\ub2f4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aKj,0,"\ubbfc\ubc95 \uc81c566\uc870\ub294 \ub9e4\ub9e4\uacc4\uc57d\uc5d0 \uad00\ud55c \ube44\uc6a9\uc740 \ub2f9\uc0ac\uc790 \uc30d\ubc29\uc774 \uade0\ubd84\ud558\uc5ec \ubd80\ub2f4\ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc774\ub294 \uc784\uc758\uaddc\uc815\uc774\ubbc0\ub85c \ub2f9\uc0ac\uc790\uc758 \ud2b9\uc57d\uc73c\ub85c \ub2ec\ub9ac \uc815\ud560 \uc218 \uc788\ub2e4.",B.amu,B.bbs,null)
B.b82=s(["\ub9e4\ub9e4\uc758 \ubaa9\uc801\uc774 \ub41c \uad8c\ub9ac\uac00 \ud0c0\uc778\uc5d0\uac8c \uc18d\ud55c \uacbd\uc6b0 \ub9e4\ub3c4\uc778\uc740 \uadf8 \uad8c\ub9ac\ub97c \ucde8\ub4dd\ud558\uc5ec \ub9e4\uc218\uc778\uc5d0\uac8c \uc774\uc804\ud558\uc5ec\uc57c \ud55c\ub2e4.","\ub9e4\ub3c4\uc778\uc774 \uadf8 \uad8c\ub9ac\ub97c \ucde8\ub4dd\ud558\uc5ec \uc774\uc804\ud560 \uc218 \uc5c6\ub294 \uacbd\uc6b0 \uc120\uc758\uc758 \ub9e4\uc218\uc778\ub9cc \uacc4\uc57d\uc744 \ud574\uc81c\ud560 \uc218 \uc788\uace0 \uc190\ud574\ubc30\uc0c1\uc740 \uccad\uad6c\ud560 \uc218 \uc5c6\ub2e4.","\uc545\uc758\uc758 \ub9e4\uc218\uc778\ub3c4 \uacc4\uc57d\ud574\uc81c\uc640 \uc190\ud574\ubc30\uc0c1\uc744 \ubaa8\ub450 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4.","\uc774 \uacbd\uc6b0 \ub9e4\ub3c4\uc778\uc758 \ub2f4\ubcf4\ucc45\uc784\uc740 \ub9e4\uc218\uc778\uc758 \uc120\uc758\xb7\uc545\uc758\ub97c \ubd88\ubb38\ud558\uace0 \ub3d9\uc77c\ud558\ub2e4."],t.s)
B.ay2=s(["\ub9e4\ub3c4\uc778\uc740 \uadf8 \uad8c\ub9ac\ub97c \ucde8\ub4dd\ud558\uc5ec \ub9e4\uc218\uc778\uc5d0\uac8c \uc774\uc804\ud560 \uc758\ubb34\uac00 \uc788\ub2e4"],t.s)
B.Zc=s(["\ud0c0\uc778\uad8c\ub9ac\ub9e4\ub9e4","\ub9e4\ub3c4\uc778\uc758 \ub2f4\ubcf4\ucc45\uc784","\uc81c569\uc870"],t.s)
B.bOv=new A.a("gen_cl_typedcontract_24","civil_law","\uc804\ud615\uacc4\uc57d \uac01\ub860(\ub9e4\ub9e4\xb7\uc784\ub300\ucc28\xb7\ub3c4\uae09 \ub4f1)",null,"\uad8c\ub9ac\uc758 \uc804\ubd80\uac00 \ud0c0\uc778\uc5d0\uac8c \uc18d\ud55c \uacbd\uc6b0 \ub9e4\ub3c4\uc778\uc758 \ub2f4\ubcf4\ucc45\uc784\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.b82,0,"\ubbfc\ubc95 \uc81c569\uc870\ub294 \ud0c0\uc778\uc758 \uad8c\ub9ac\ub97c \ub9e4\ub9e4\uc758 \ubaa9\uc801\uc73c\ub85c \ud55c \uacbd\uc6b0 \ub9e4\ub3c4\uc778\uc740 \uadf8 \uad8c\ub9ac\ub97c \ucde8\ub4dd\ud558\uc5ec \ub9e4\uc218\uc778\uc5d0\uac8c \uc774\uc804\ud560 \uc758\ubb34\uac00 \uc788\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc774\ub97c \uc774\uc804\ud560 \uc218 \uc5c6\ub294 \uacbd\uc6b0 \uc81c570\uc870\uc5d0 \ub530\ub77c \uc120\uc758\uc758 \ub9e4\uc218\uc778\uc740 \uacc4\uc57d\ud574\uc81c\uc640 \uc190\ud574\ubc30\uc0c1\uc744 \ubaa8\ub450 \uccad\uad6c\ud560 \uc218 \uc788\uace0, \uc545\uc758\uc758 \ub9e4\uc218\uc778\uc740 \uacc4\uc57d\ud574\uc81c\ub9cc \uac00\ub2a5\ud558\ub2e4.",B.ay2,B.Zc,null)
B.aNt=s(["\uc218\ub7c9\uc744 \uc9c0\uc815\ud55c \ub9e4\ub9e4\uc5d0\uc11c \ubaa9\uc801\ubb3c\uc758 \uc218\ub7c9\uc774 \ubd80\uc871\ud55c \uacbd\uc6b0 \uc120\uc758\uc758 \ub9e4\uc218\uc778\uc740 \ub300\uae08\uac10\uc561\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4.","\uc218\ub7c9\uc9c0\uc815\ub9e4\ub9e4\uc5d0\uc11c \uc218\ub7c9\ubd80\uc871\uc740 \uc545\uc758\uc758 \ub9e4\uc218\uc778\uc5d0\uac8c\ub3c4 \ub3d9\uc77c\ud558\uac8c \ub300\uae08\uac10\uc561\uccad\uad6c\uad8c\uc774 \uc778\uc815\ub41c\ub2e4.","\uc218\ub7c9\ubd80\uc871\uc758 \uacbd\uc6b0 \ub9e4\uc218\uc778\uc740 \uc120\uc758\xb7\uc545\uc758\ub97c \ubd88\ubb38\ud558\uace0 \uacc4\uc57d\uc744 \ud574\uc81c\ud560 \uc218 \uc788\ub2e4.","\uc218\ub7c9\uc744 \uc9c0\uc815\ud558\uc9c0 \uc54a\uc740 \ub9e4\ub9e4\uc5d0\uc11c\ub3c4 \uc218\ub7c9\ubd80\uc871\uc2dc \ub2f9\uc5f0\ud788 \ub2f4\ubcf4\ucc45\uc784\uc774 \ubc1c\uc0dd\ud55c\ub2e4."],t.s)
B.bf7=s(["\uc120\uc758\uc758 \ub9e4\uc218\uc778\uc774 \ub300\uae08\uac10\uc561, \uc190\ud574\ubc30\uc0c1, \uacc4\uc57d\ubaa9\uc801 \ub2ec\uc131 \ubd88\ub2a5\uc2dc \ud574\uc81c\ub97c \uccad\uad6c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.axS=s(["\uc218\ub7c9\uc9c0\uc815\ub9e4\ub9e4","\uc218\ub7c9\ubd80\uc871\ub2f4\ubcf4\ucc45\uc784","\uc81c574\uc870"],t.s)
B.boi=new A.a("gen_cl_typedcontract_25","civil_law","\uc804\ud615\uacc4\uc57d \uac01\ub860(\ub9e4\ub9e4\xb7\uc784\ub300\ucc28\xb7\ub3c4\uae09 \ub4f1)",null,"\uc218\ub7c9\ubd80\uc871\xb7\uc77c\ubd80\uba78\uc2e4\uc758 \uacbd\uc6b0 \ub9e4\ub3c4\uc778\uc758 \ub2f4\ubcf4\ucc45\uc784\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aNt,0,"\ubbfc\ubc95 \uc81c574\uc870\ub294 \uc218\ub7c9\uc744 \uc9c0\uc815\ud55c \ub9e4\ub9e4\uc5d0\uc11c \uc218\ub7c9\uc774 \ubd80\uc871\ud558\uac70\ub098 \uc77c\ubd80\uac00 \uba78\uc2e4\ub41c \uacbd\uc6b0 \uc81c572\uc870\ub97c \uc900\uc6a9\ud558\uc5ec \uc120\uc758\uc758 \ub9e4\uc218\uc778\uc774 \ub300\uae08\uac10\uc561, \uc190\ud574\ubc30\uc0c1, \uacc4\uc57d\ubaa9\uc801 \ub2ec\uc131 \ubd88\ub2a5\uc2dc \ud574\uc81c\ub97c \uccad\uad6c\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc774\ub294 \uc120\uc758\uc758 \ub9e4\uc218\uc778\uc5d0\uac8c\ub9cc \uc778\uc815\ub418\uba70, \uc545\uc758\uc758 \ub9e4\uc218\uc778\uc5d0\uac8c\ub294 \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4.",B.bf7,B.axS,null)
B.aEY=s(["\uacbd\ub9e4\uc758 \ubaa9\uc801\ubb3c\uc5d0 \ubb3c\uac74\uc758 \ud558\uc790\uac00 \uc788\ub294 \uacbd\uc6b0\uc5d0\ub294 \ub9e4\ub3c4\uc778\uc758 \ub2f4\ubcf4\ucc45\uc784\uc5d0 \uad00\ud55c \uaddc\uc815\uc774 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4.","\uacbd\ub9e4\uc5d0\uc11c \uad8c\ub9ac\uc758 \ud558\uc790\uac00 \uc788\ub294 \uacbd\uc6b0\uc5d0\ub3c4 \ub2f4\ubcf4\ucc45\uc784\uc774 \uc804\ud600 \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4.","\uacbd\ub9e4\uc758 \uacbd\uc6b0 \ucc44\ubb34\uc790\uc758 \uc790\ub825\uc774 \uc5c6\uc73c\uba74 \ub9e4\uc218\uc778\uc740 \ud56d\uc0c1 \uad6d\uac00\uc5d0 \uc190\ud574\ubc30\uc0c1\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4.","\uacbd\ub9e4\uc5d0\uc11c\ub294 \uad8c\ub9ac\uc758 \ud558\uc790\uc640 \ubb3c\uac74\uc758 \ud558\uc790 \ubaa8\ub450 \ub2f4\ubcf4\ucc45\uc784\uc774 \ub3d9\uc77c\ud558\uac8c \uc778\uc815\ub41c\ub2e4."],t.s)
B.bb3=s(["\uacbd\ub9e4\uc758 \uacbd\uc6b0 \ubb3c\uac74\uc758 \ud558\uc790\uc5d0 \ub300\ud558\uc5ec\ub294 \ub9e4\ub3c4\uc778\uc758 \ub2f4\ubcf4\ucc45\uc784 \uaddc\uc815\uc774 \uc801\uc6a9\ub418\uc9c0 \uc54a\uc73c\ub098"],t.s)
B.aA1=s(["\uacbd\ub9e4\uc758 \ub2f4\ubcf4\ucc45\uc784","\ubb3c\uac74\uc758 \ud558\uc790 \ubc30\uc81c","\uc81c580\uc870"],t.s)
B.bLU=new A.a("gen_cl_typedcontract_26","civil_law","\uc804\ud615\uacc4\uc57d \uac01\ub860(\ub9e4\ub9e4\xb7\uc784\ub300\ucc28\xb7\ub3c4\uae09 \ub4f1)",null,"\uacbd\ub9e4\uc5d0\uc11c\uc758 \ub2f4\ubcf4\ucc45\uc784\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aEY,0,"\ubbfc\ubc95 \uc81c580\uc870 \uc81c2\ud56d \ubc0f \uc81c578\uc870\uc5d0 \ub530\ub77c \uacbd\ub9e4\uc758 \uacbd\uc6b0 \ubb3c\uac74\uc758 \ud558\uc790\uc5d0 \ub300\ud558\uc5ec\ub294 \ub9e4\ub3c4\uc778\uc758 \ub2f4\ubcf4\ucc45\uc784 \uaddc\uc815\uc774 \uc801\uc6a9\ub418\uc9c0 \uc54a\uc73c\ub098, \uad8c\ub9ac\uc758 \ud558\uc790\uc5d0 \ub300\ud558\uc5ec\ub294 \ucc44\ubb34\uc790\ub098 \ubc30\ub2f9\ubc1b\uc740 \ucc44\uad8c\uc790\ub97c \uc0c1\ub300\ub85c \ub2f4\ubcf4\ucc45\uc784\uc744 \ubb3c\uc744 \uc218 \uc788\ub2e4.",B.bb3,B.aA1,null)
B.aQ5=s(["\uc784\ub300\ucc28\uae30\uac04\uc744 \uc57d\uc815\ud558\uc9c0 \uc54a\uc740 \uacbd\uc6b0 \ub2f9\uc0ac\uc790\ub294 \uc5b8\uc81c\ub4e0\uc9c0 \ud574\uc9c0\ub97c \ud1b5\uace0\ud560 \uc218 \uc788\ub2e4.","\uc784\ub300\ucc28\ub294 \uadf8 \uae30\uac04\uc758 \uc57d\uc815 \uc720\ubb34\uc640 \uad00\uacc4\uc5c6\uc774 \uc5b8\uc81c\ub098 \uac31\uc2e0\ud560 \uc218 \uc5c6\ub2e4.","\uc784\ub300\uc778\uc774 \ud574\uc9c0\ud1b5\uace0\ub97c \ud55c \uacbd\uc6b0 \ubd80\ub3d9\uc0b0\uc5d0 \ub300\ud558\uc5ec\ub294 \ud1b5\uace0 \uc989\uc2dc \ud6a8\ub825\uc774 \ubc1c\uc0dd\ud55c\ub2e4.","\uae30\uac04\uc758 \uc57d\uc815\uc774 \uc5c6\ub294 \uc784\ub300\ucc28\uc5d0\uc11c \uc784\ucc28\uc778\uc774 \ud574\uc9c0\ud1b5\uace0\ub97c \ud558\uba74 \uc989\uc2dc \ud6a8\ub825\uc774 \ubc1c\uc0dd\ud55c\ub2e4."],t.s)
B.a7e=s(["\ub2f9\uc0ac\uc790\ub294 \uc5b8\uc81c\ub4e0\uc9c0 \uacc4\uc57d\ud574\uc9c0\uc758 \ud1b5\uace0\ub97c \ud560 \uc218 \uc788\ub2e4"],t.s)
B.aLD=s(["\uc784\ub300\ucc28 \uc874\uc18d\uae30\uac04","\ud574\uc9c0\ud1b5\uace0","\uc81c635\uc870"],t.s)
B.bS5=new A.a("gen_cl_typedcontract_27","civil_law","\uc804\ud615\uacc4\uc57d \uac01\ub860(\ub9e4\ub9e4\xb7\uc784\ub300\ucc28\xb7\ub3c4\uae09 \ub4f1)",null,"\uc784\ub300\ucc28\uc758 \uc874\uc18d\uae30\uac04\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aQ5,0,"\ubbfc\ubc95 \uc81c635\uc870\ub294 \uc784\ub300\ucc28\uae30\uac04\uc758 \uc57d\uc815\uc774 \uc5c6\ub294 \uacbd\uc6b0 \ub2f9\uc0ac\uc790\ub294 \uc5b8\uc81c\ub4e0\uc9c0 \uacc4\uc57d\ud574\uc9c0\uc758 \ud1b5\uace0\ub97c \ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ub2e4\ub9cc \uc0c1\ub300\ubc29\uc774 \ud1b5\uace0\ub97c \ubc1b\uc740 \ub0a0\ub85c\ubd80\ud130 \ubd80\ub3d9\uc0b0\uc740 \uc784\ub300\uc778\uc774 \ud574\uc9c0\ud1b5\uace0\ud55c \uacbd\uc6b0 6\uc6d4, \uc784\ucc28\uc778\uc774 \ud1b5\uace0\ud55c \uacbd\uc6b0 1\uc6d4\uc774 \uacbd\uacfc\ud558\uba74 \ud574\uc9c0\uc758 \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4.",B.a7e,B.aLD,null)
B.apA=s(["\uc784\ucc28\ubb3c\uc758 \uc77c\ubd80\uac00 \uc784\ucc28\uc778\uc758 \uacfc\uc2e4 \uc5c6\uc774 \uba78\uc2e4\ub418\uc5b4 \uc0ac\uc6a9\xb7\uc218\uc775\ud560 \uc218 \uc5c6\ub294 \uacbd\uc6b0 \uc784\ucc28\uc778\uc740 \uadf8 \ubd80\ubd84\uc758 \ube44\uc728\uc5d0 \uc758\ud55c \ucc28\uc784\uc758 \uac10\uc561\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4.","\uc784\ucc28\ubb3c\uc758 \uc77c\ubd80 \uba78\uc2e4\uc774 \uc784\ucc28\uc778\uc758 \uacfc\uc2e4\ub85c \uc778\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \uc784\ucc28\uc778\uc740 \ucc28\uc784\uac10\uc561\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4.","\uc784\ucc28\ubb3c\uc758 \uc77c\ubd80\uac00 \uba78\uc2e4\ub41c \uacbd\uc6b0 \uadf8 \uc794\uc874\ubd80\ubd84\ub9cc\uc73c\ub85c \uc784\ub300\ucc28 \ubaa9\uc801\uc744 \ub2ec\uc131\ud560 \uc218 \uc5c6\uc5b4\ub3c4 \uc784\ucc28\uc778\uc740 \uacc4\uc57d\uc744 \ud574\uc9c0\ud560 \uc218 \uc5c6\ub2e4.","\ucc28\uc784\uac10\uc561\uccad\uad6c\uad8c\uc740 \ud615\uc131\uad8c\uc774 \uc544\ub2c8\ub77c \ub2f9\uc0ac\uc790\uc758 \ud569\uc758\uac00 \uc788\uc5b4\uc57c \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4."],t.s)
B.b2I=s(["\uc784\ucc28\uc778\uc740 \uadf8 \ubd80\ubd84\uc758 \ube44\uc728\uc5d0 \uc758\ud55c \ucc28\uc784\uc758 \uac10\uc561\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.aQR=s(["\ucc28\uc784\uac10\uc561\uccad\uad6c\uad8c","\uc77c\ubd80\uba78\uc2e4","\uc81c627\uc870"],t.s)
B.byC=new A.a("gen_cl_typedcontract_28","civil_law","\uc804\ud615\uacc4\uc57d \uac01\ub860(\ub9e4\ub9e4\xb7\uc784\ub300\ucc28\xb7\ub3c4\uae09 \ub4f1)",null,"\uc784\ucc28\uc778\uc758 \ucc28\uc784\uac10\uc561\uccad\uad6c\uad8c\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.apA,0,"\ubbfc\ubc95 \uc81c627\uc870 \uc81c1\ud56d\uc740 \uc784\ucc28\ubb3c\uc758 \uc77c\ubd80\uac00 \uc784\ucc28\uc778\uc758 \uacfc\uc2e4 \uc5c6\uc774 \uba78\uc2e4 \uae30\ud0c0 \uc0ac\uc720\ub85c \uc0ac\uc6a9\xb7\uc218\uc775\ud560 \uc218 \uc5c6\ub294 \uacbd\uc6b0 \uc784\ucc28\uc778\uc740 \uadf8 \ubd80\ubd84\uc758 \ube44\uc728\uc5d0 \uc758\ud55c \ucc28\uc784\uc758 \uac10\uc561\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uac19\uc740 \uc870 \uc81c2\ud56d\uc740 \uadf8 \uc794\uc874\ubd80\ubd84\ub9cc\uc73c\ub85c \uc784\ub300\ucc28 \ubaa9\uc801\uc744 \ub2ec\uc131\ud560 \uc218 \uc5c6\ub294 \ub54c\uc5d0\ub294 \uc784\ucc28\uc778\uc774 \uacc4\uc57d\uc744 \ud574\uc9c0\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4.",B.b2I,B.aQR,null)
B.abq=s(["\uc784\ub300\uc778\uc740 \ubaa9\uc801\ubb3c\uc744 \uc0ac\uc6a9\xb7\uc218\uc775\uc5d0 \ud544\uc694\ud55c \uc0c1\ud0dc\ub97c \uc720\uc9c0\ud560 \uc758\ubb34\ub97c \ubd80\ub2f4\ud55c\ub2e4.","\uc784\ub300\uc778\uc758 \uc218\uc120\uc758\ubb34\ub294 \ud2b9\uc57d\uc73c\ub85c \uc644\uc804\ud788 \ubc30\uc81c\ud560 \uc218 \uc5c6\ub294 \uac15\ud589\uaddc\uc815\uc774\ub2e4.","\uc784\ucc28\uc778\uc758 \ud1b5\uc0c1\uc758 \uad00\ub9ac\uc5d0 \uc18d\ud558\ub294 \uc0ac\uc18c\ud55c \uc218\uc120\uae4c\uc9c0\ub3c4 \ubc18\ub4dc\uc2dc \uc784\ub300\uc778\uc774 \ubd80\ub2f4\ud558\uc5ec\uc57c \ud55c\ub2e4.","\uc784\ub300\uc778\uc740 \ubaa9\uc801\ubb3c\uc758 \ud30c\uc190 \uc815\ub3c4\uc640 \ubb34\uad00\ud558\uac8c \uc218\uc120\uc758\ubb34\ub97c \ubd80\ub2f4\ud558\uc9c0 \uc54a\ub294\ub2e4."],t.s)
B.ayg=s(["\uadf8 \uc0ac\uc6a9\xb7\uc218\uc775\uc5d0 \ud544\uc694\ud55c \uc0c1\ud0dc\ub97c \uc720\uc9c0\ud558\uac8c \ud560 \uc758\ubb34\ub97c \ubd80\ub2f4\ud55c\ub2e4"],t.s)
B.adv=s(["\uc784\ub300\uc778\uc758 \uc218\uc120\uc758\ubb34","\uc81c623\uc870","\uc0ac\uc18c\ud55c \ud30c\uc190"],t.s)
B.bwG=new A.a("gen_cl_typedcontract_29","civil_law","\uc804\ud615\uacc4\uc57d \uac01\ub860(\ub9e4\ub9e4\xb7\uc784\ub300\ucc28\xb7\ub3c4\uae09 \ub4f1)",null,"\uc784\ub300\uc778\uc758 \uc218\uc120\uc758\ubb34\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.abq,0,"\ubbfc\ubc95 \uc81c623\uc870\ub294 \uc784\ub300\uc778\uc774 \ubaa9\uc801\ubb3c\uc744 \uc784\ucc28\uc778\uc5d0\uac8c \uc778\ub3c4\ud558\uace0 \uacc4\uc57d\uc874\uc18d \uc911 \uadf8 \uc0ac\uc6a9\xb7\uc218\uc775\uc5d0 \ud544\uc694\ud55c \uc0c1\ud0dc\ub97c \uc720\uc9c0\ud558\uac8c \ud560 \uc758\ubb34\ub97c \ubd80\ub2f4\ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ub2e4\ub9cc \ud310\ub840\ub294 \uc784\ucc28\uc778\uc774 \ubcc4\ub2e4\ub978 \ub178\ub825\uc774\ub098 \ube44\uc6a9\uc744 \ub4e4\uc774\uc9c0 \uc54a\uace0 \uc190\uc27d\uac8c \uace0\uce60 \uc218 \uc788\ub294 \uc815\ub3c4\uc758 \uc0ac\uc18c\ud55c \ud30c\uc190\uc740 \uc784\ucc28\uc778\uc774 \uc2a4\uc2a4\ub85c \uc774\ub97c \uc218\uc120\ud558\uc5ec \uc0ac\uc6a9\ud558\uc5ec\uc57c \ud55c\ub2e4\uace0 \ubcf8\ub2e4.",B.ayg,B.adv,null)
B.apl=s(["\uac74\ubb3c \uae30\ud0c0 \uacf5\uc791\ubb3c\uc758 \uc18c\uc720\ub97c \ubaa9\uc801\uc73c\ub85c \ud55c \ud1a0\uc9c0\uc784\ub300\ucc28\uae30\uac04\uc774 \ub9cc\ub8cc\ud55c \uacbd\uc6b0 \uc784\ucc28\uc778\uc774 \uacc4\uc57d\uac31\uc2e0\uc744 \uccad\uad6c\ud558\uc600\uc73c\ub098 \uc784\ub300\uc778\uc774 \uac70\uc808\ud55c \ub54c\uc5d0\ub294 \uc784\ucc28\uc778\uc740 \uc0c1\ub2f9\ud55c \uac00\uc561\uc73c\ub85c \uc9c0\uc0c1\ubb3c\uc758 \ub9e4\uc218\ub97c \uccad\uad6c\ud560 \uc218 \uc788\ub2e4.","\uc9c0\uc0c1\ubb3c\ub9e4\uc218\uccad\uad6c\uad8c\uc740 \uc784\ucc28\uc778\uc758 \ucc44\ubb34\ubd88\uc774\ud589\uc73c\ub85c \uacc4\uc57d\uc774 \ud574\uc9c0\ub41c \uacbd\uc6b0\uc5d0\ub3c4 \uc778\uc815\ub41c\ub2e4.","\uc9c0\uc0c1\ubb3c\ub9e4\uc218\uccad\uad6c\uad8c\uc740 \uc784\ub300\uc778\ub9cc \ud589\uc0ac\ud560 \uc218 \uc788\ub294 \uad8c\ub9ac\uc774\ub2e4.","\uc9c0\uc0c1\ubb3c\ub9e4\uc218\uccad\uad6c\uad8c\uc744 \ubc30\uc81c\ud558\ub294 \ud2b9\uc57d\uc740 \uc784\ucc28\uc778\uc5d0\uac8c \ubd88\ub9ac\ud558\ub354\ub77c\ub3c4 \ud56d\uc0c1 \uc720\ud6a8\ud558\ub2e4."],t.s)
B.aUz=s(["\uc784\ucc28\uc778\uc740 \uc0c1\ub2f9\ud55c \uac00\uc561\uc73c\ub85c \uc9c0\uc0c1\ubb3c\uc758 \ub9e4\uc218\ub97c \uccad\uad6c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.aIQ=s(["\uc9c0\uc0c1\ubb3c\ub9e4\uc218\uccad\uad6c\uad8c","\ud3b8\uba74\uc801 \uac15\ud589\uaddc\uc815","\uc81c643\uc870"],t.s)
B.bpp=new A.a("gen_cl_typedcontract_30","civil_law","\uc804\ud615\uacc4\uc57d \uac01\ub860(\ub9e4\ub9e4\xb7\uc784\ub300\ucc28\xb7\ub3c4\uae09 \ub4f1)",null,"\ud1a0\uc9c0\uc784\ucc28\uc778\uc758 \uc9c0\uc0c1\ubb3c\ub9e4\uc218\uccad\uad6c\uad8c\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.apl,0,"\ubbfc\ubc95 \uc81c643\uc870, \uc81c283\uc870\uc5d0 \ub530\ub77c \uac74\ubb3c \uae30\ud0c0 \uacf5\uc791\ubb3c\uc758 \uc18c\uc720\ub97c \ubaa9\uc801\uc73c\ub85c \ud55c \ud1a0\uc9c0\uc784\ub300\ucc28\uae30\uac04\uc774 \ub9cc\ub8cc\ud558\uace0 \uac31\uc2e0\uc774 \ub418\uc9c0 \uc544\ub2c8\ud55c \uacbd\uc6b0 \uc784\ucc28\uc778\uc740 \uc0c1\ub2f9\ud55c \uac00\uc561\uc73c\ub85c \uc9c0\uc0c1\ubb3c\uc758 \ub9e4\uc218\ub97c \uccad\uad6c\ud560 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \ud310\ub840\uc0c1 \uc784\ucc28\uc778\uc758 \ucc44\ubb34\ubd88\uc774\ud589\uc73c\ub85c \uacc4\uc57d\uc774 \ud574\uc9c0\ub41c \uacbd\uc6b0\uc5d0\ub294 \uc774 \uad8c\ub9ac\uac00 \uc778\uc815\ub418\uc9c0 \uc54a\uc73c\uba70, \uc774 \uaddc\uc815\uc740 \ud3b8\uba74\uc801 \uac15\ud589\uaddc\uc815\uc774\ub2e4.",B.aUz,B.aIQ,null)
B.b76=s(["\ubcf4\uc218\ub294 \uc644\uc131\ub41c \ubaa9\uc801\ubb3c\uc758 \uc778\ub3c4\uc640 \ub3d9\uc2dc\uc5d0 \uc9c0\uae09\ud558\uc5ec\uc57c \ud55c\ub2e4.","\ubaa9\uc801\ubb3c\uc758 \uc778\ub3c4\ub97c \uc694\ud558\uc9c0 \uc54a\ub294 \ub3c4\uae09\uc5d0\uc11c\ub3c4 \ubcf4\uc218\ub294 \uc644\uc131 \uc804\uc5d0 \ubbf8\ub9ac \uc9c0\uae09\ud558\uc5ec\uc57c \ud55c\ub2e4.","\uc218\uae09\uc778\uc740 \ubaa9\uc801\ubb3c\uc744 \uc644\uc131\ud558\uae30 \uc804\uc774\ub77c\ub3c4 \ud56d\uc0c1 \ubcf4\uc218\ub97c \uc120\uccad\uad6c\ud560 \uc218 \uc788\ub2e4.","\ub3c4\uae09\uc758 \ubcf4\uc218\uc9c0\uae09\uc2dc\uae30\ub294 \ud56d\uc0c1 \ub3c4\uae09\uc778\uc758 \uc784\uc758\ub85c \uc815\ud55c\ub2e4."],t.s)
B.am5=s(["\ubcf4\uc218\ub294 \ubaa9\uc801\ubb3c\uc758 \uc778\ub3c4\uc640 \ub3d9\uc2dc\uc5d0 \uc9c0\uae09\ud558\uc5ec\uc57c \ud55c\ub2e4"],t.s)
B.aEE=s(["\ub3c4\uae09 \ubcf4\uc218\uc9c0\uae09","\ub3d9\uc2dc\uc774\ud589\uad00\uacc4","\uc81c665\uc870"],t.s)
B.bCD=new A.a("gen_cl_typedcontract_31","civil_law","\uc804\ud615\uacc4\uc57d \uac01\ub860(\ub9e4\ub9e4\xb7\uc784\ub300\ucc28\xb7\ub3c4\uae09 \ub4f1)",null,"\uc218\uae09\uc778\uc758 \uc644\uc131\ubb3c\uc778\ub3c4\uc640 \ub3d9\uc2dc\uc774\ud589\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.b76,0,"\ubbfc\ubc95 \uc81c665\uc870 \uc81c1\ud56d\uc740 \ubcf4\uc218\ub294 \ubaa9\uc801\ubb3c\uc758 \uc778\ub3c4\uc640 \ub3d9\uc2dc\uc5d0 \uc9c0\uae09\ud558\uc5ec\uc57c \ud55c\ub2e4\uace0 \uaddc\uc815\ud558\uba70, \ubaa9\uc801\ubb3c\uc758 \uc778\ub3c4\ub97c \uc694\ud558\uc9c0 \uc544\ub2c8\ud558\ub294 \uacbd\uc6b0\uc5d0\ub294 \uc77c\uc744 \uc644\uc131\ud55c \ud6c4 \uc9c0\uccb4 \uc5c6\uc774 \uc9c0\uae09\ud558\uc5ec\uc57c \ud55c\ub2e4. \uc774\ub294 \ub3c4\uae09\uc778\uc758 \ubcf4\uc218\uc9c0\uae09\uc758\ubb34\uc640 \uc218\uae09\uc778\uc758 \uc778\ub3c4\uc758\ubb34\uac00 \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uc5d0 \uc788\uc74c\uc744 \uc758\ubbf8\ud55c\ub2e4.",B.am5,B.aEE,null)
B.biq=s(["\ubaa9\uc801\ubb3c\uc758 \ud558\uc790\uac00 \ub3c4\uae09\uc778\uc774 \uc81c\uacf5\ud55c \uc7ac\ub8cc\uc758 \uc131\uc9c8\ub85c \uc778\ud558\uc5ec \uc0dd\uae34 \uacbd\uc6b0 \uc6d0\uce59\uc801\uc73c\ub85c \uc218\uae09\uc778\uc740 \ub2f4\ubcf4\ucc45\uc784\uc744 \uc9c0\uc9c0 \uc54a\ub294\ub2e4.","\uc218\uae09\uc778\uc774 \uadf8 \uc7ac\ub8cc \ub610\ub294 \uc9c0\uc2dc\uc758 \ubd80\uc801\ub2f9\ud568\uc744 \uc54c\uace0\ub3c4 \uace0\uc9c0\ud558\uc9c0 \uc544\ub2c8\ud55c \ub54c\uc5d0\ub3c4 \uc218\uae09\uc778\uc740 \uba74\ucc45\ub41c\ub2e4.","\ub3c4\uae09\uc778\uc774 \uc9c0\uc2dc\ud55c \uc7ac\ub8cc\uc758 \ud558\uc790\ub85c \uc778\ud55c \uc190\ud574\ub294 \ud56d\uc0c1 \ub3c4\uae09\uc778\uc774 \uc804\ubd80 \ubd80\ub2f4\ud558\uace0 \uc608\uc678\uac00 \uc5c6\ub2e4.","\uc7ac\ub8cc\uc758 \uc131\uc9c8\ub85c \uc778\ud55c \ud558\uc790\ub294 \ub3c4\uae09\uc778\uc758 \uc9c0\uc2dc \uc5ec\ubd80\uc640 \ubb34\uad00\ud558\uac8c \uc218\uae09\uc778\uc774 \ud56d\uc0c1 \ucc45\uc784\uc9c4\ub2e4."],t.s)
B.agv=s(["\ub3c4\uae09\uc778\uc774 \uc81c\uacf5\ud55c \uc7ac\ub8cc\uc758 \uc131\uc9c8 \ub610\ub294 \ub3c4\uae09\uc778\uc758 \uc9c0\uc2dc\uc5d0 \uae30\uc778\ud55c \ub54c\uc5d0\ub294 \uc218\uae09\uc778\uc740 \ub2f4\ubcf4\ucc45\uc784\uc744 \uc9c0\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.aFH=s(["\uc218\uae09\uc778 \ub2f4\ubcf4\ucc45\uc784 \uba74\uc81c","\uc7ac\ub8cc\uc758 \ud558\uc790","\uc81c669\uc870"],t.s)
B.bt1=new A.a("gen_cl_typedcontract_32","civil_law","\uc804\ud615\uacc4\uc57d \uac01\ub860(\ub9e4\ub9e4\xb7\uc784\ub300\ucc28\xb7\ub3c4\uae09 \ub4f1)",null,"\uc218\uae09\uc778\uc758 \ub2f4\ubcf4\ucc45\uc784 \uba74\uc81c\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.biq,0,"\ubbfc\ubc95 \uc81c669\uc870\ub294 \ubaa9\uc801\ubb3c\uc758 \ud558\uc790\uac00 \ub3c4\uae09\uc778\uc774 \uc81c\uacf5\ud55c \uc7ac\ub8cc\uc758 \uc131\uc9c8 \ub610\ub294 \ub3c4\uae09\uc778\uc758 \uc9c0\uc2dc\uc5d0 \uae30\uc778\ud55c \ub54c\uc5d0\ub294 \uc218\uae09\uc778\uc740 \ub2f4\ubcf4\ucc45\uc784\uc744 \uc9c0\uc9c0 \uc54a\ub294\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ub2e4\ub9cc \uc218\uae09\uc778\uc774 \uadf8 \uc7ac\ub8cc\ub098 \uc9c0\uc2dc\uc758 \ubd80\uc801\ub2f9\ud568\uc744 \uc54c\uace0\ub3c4 \ub3c4\uae09\uc778\uc5d0\uac8c \uace0\uc9c0\ud558\uc9c0 \uc544\ub2c8\ud55c \ub54c\uc5d0\ub294 \uadf8\ub7ec\ud558\uc9c0 \uc544\ub2c8\ud558\uc5ec \ucc45\uc784\uc744 \uc9c4\ub2e4.",B.agv,B.aFH,null)
B.ah2=s(["\ub3c4\uae09\uc778\uc774 \ud30c\uc0b0\uc120\uace0\ub97c \ubc1b\uc740 \uacbd\uc6b0 \uc218\uae09\uc778 \ub610\ub294 \ud30c\uc0b0\uad00\uc7ac\uc778\uc740 \uacc4\uc57d\uc744 \ud574\uc81c\ud560 \uc218 \uc788\ub2e4.","\ub3c4\uae09\uc778\uc774 \ud30c\uc0b0\uc120\uace0\ub97c \ubc1b\uc740 \uacbd\uc6b0 \ub3c4\uae09\uacc4\uc57d\uc740 \uc790\ub3d9\uc73c\ub85c \uc885\ub8cc\ub418\uc9c0 \uc54a\uace0 \uadf8\ub300\ub85c \uc874\uc18d\ud55c\ub2e4.","\ub3c4\uae09\uc778\uc758 \ud30c\uc0b0\uc2dc \uc218\uae09\uc778\uc740 \ud574\uc81c\uad8c\uc744 \ud589\uc0ac\ud560 \uc218 \uc5c6\uace0 \ud30c\uc0b0\uad00\uc7ac\uc778\ub9cc \ud574\uc81c\uad8c\uc744 \uac16\ub294\ub2e4.","\ub3c4\uae09\uc778\uc758 \ud30c\uc0b0\uc740 \ub3c4\uae09\uacc4\uc57d\uc758 \ud6a8\ub825\uc5d0 \uc544\ubb34\ub7f0 \uc601\ud5a5\uc744 \ubbf8\uce58\uc9c0 \uc54a\ub294\ub2e4."],t.s)
B.aZ8=s(["\ub3c4\uae09\uc778\uc774 \ud30c\uc0b0\uc120\uace0\ub97c \ubc1b\uc740 \ub54c\uc5d0\ub294 \uc218\uae09\uc778 \ub610\ub294 \ud30c\uc0b0\uad00\uc7ac\uc778\uc740 \uacc4\uc57d\uc744 \ud574\uc81c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.aAo=s(["\ub3c4\uae09\uc778\uc758 \ud30c\uc0b0","\ud574\uc81c\uad8c","\uc81c674\uc870"],t.s)
B.bB7=new A.a("gen_cl_typedcontract_33","civil_law","\uc804\ud615\uacc4\uc57d \uac01\ub860(\ub9e4\ub9e4\xb7\uc784\ub300\ucc28\xb7\ub3c4\uae09 \ub4f1)",null,"\ub3c4\uae09\uc778\uc758 \ud30c\uc0b0\uacfc \uc218\uae09\uc778\uc758 \uacc4\uc57d\ud574\uc81c\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.ah2,0,"\ubbfc\ubc95 \uc81c674\uc870 \uc81c1\ud56d\uc740 \ub3c4\uae09\uc778\uc774 \ud30c\uc0b0\uc120\uace0\ub97c \ubc1b\uc740 \ub54c\uc5d0\ub294 \uc218\uae09\uc778 \ub610\ub294 \ud30c\uc0b0\uad00\uc7ac\uc778\uc740 \uacc4\uc57d\uc744 \ud574\uc81c\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc774 \uacbd\uc6b0 \uc218\uae09\uc778\uc740 \uc77c\uc758 \uc644\uc131\ub41c \ubd80\ubd84\uc5d0 \ub300\ud55c \ubcf4\uc218 \ubc0f \uadf8 \uc911\uc5d0 \ud3ec\ud568\ub418\uc9c0 \uc544\ub2c8\ud55c \ube44\uc6a9\uc5d0 \ub300\ud558\uc5ec \ud30c\uc0b0\uc7ac\ub2e8\uc758 \ubc30\ub2f9\uc5d0 \uac00\uc785\ud560 \uc218 \uc788\ub2e4.",B.aZ8,B.aAo,null)
B.a3s=s(["\ucc28\uc8fc\uac00 \uacc4\uc57d \ub610\ub294 \ubaa9\uc801\ubb3c\uc758 \uc131\uc9c8\uc5d0 \uc758\ud558\uc5ec \uc815\ud558\uc5ec\uc9c4 \uc6a9\ubc95\uc5d0 \uc704\ubc18\ud558\uc5ec \uc774\ub97c \uc0ac\uc6a9\xb7\uc218\uc775\ud55c \ub54c \ub300\uc8fc\ub294 \uacc4\uc57d\uc744 \ud574\uc9c0\ud560 \uc218 \uc788\ub2e4.","\ucc28\uc8fc\ub294 \ub300\uc8fc\uc758 \uc2b9\ub099 \uc5c6\uc774 \uc81c3\uc790\uc5d0\uac8c \ucc28\uc6a9\ubb3c\uc744 \uc0ac\uc6a9\xb7\uc218\uc775\ud558\uac8c \ud558\uc9c0 \ubabb\ud558\uba70 \uc704\ubc18\uc2dc \ub300\uc8fc\ub294 \ud574\uc9c0\ud560 \uc218 \uc788\ub2e4.","\uc0ac\uc6a9\ub300\ucc28\ub294 \ucc28\uc8fc\uc758 \uc0ac\ub9dd\uc73c\ub85c \uc885\ub8cc\ud558\uc9c0 \uc54a\uace0 \uc0c1\uc18d\uc778\uc5d0\uac8c \uc2b9\uacc4\ub41c\ub2e4.","\ub2f9\uc0ac\uc790\uac00 \uc0ac\uc6a9\ub300\ucc28\uc758 \uc874\uc18d\uae30\uac04\uc744 \uc815\ud558\uc9c0 \uc54a\uc740 \uacbd\uc6b0 \uc0ac\uc6a9\xb7\uc218\uc775\uc5d0 \uc871\ud55c \uae30\uac04\uc774 \uacbd\uacfc\ud558\uba74 \ub300\uc8fc\ub294 \ud574\uc9c0\ud560 \uc218 \uc788\ub2e4."],t.s)
B.adY=s(["\uc81c614\uc870\ub294 \ucc28\uc8fc\uc758 \uc0ac\ub9dd\uc73c\ub85c \uc0ac\uc6a9\ub300\ucc28\uac00 \uc885\ub8cc\ud55c\ub2e4\uace0 \uaddc\uc815\ud558\ubbc0\ub85c"],t.s)
B.aQu=s(["\uc0ac\uc6a9\ub300\ucc28\uc758 \uc885\ub8cc","\ucc28\uc8fc\uc758 \uc0ac\ub9dd","\uc81c614\uc870"],t.s)
B.bFq=new A.a("gen_cl_typedcontract_34","civil_law","\uc804\ud615\uacc4\uc57d \uac01\ub860(\ub9e4\ub9e4\xb7\uc784\ub300\ucc28\xb7\ub3c4\uae09 \ub4f1)",null,"\uc0ac\uc6a9\ub300\ucc28\uc758 \ud574\uc9c0\uc0ac\uc720\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.a3s,2,"\ubbfc\ubc95 \uc81c610\uc870\ub294 \ucc28\uc8fc\uc758 \ubb34\ub2e8\uc804\ub300\ub97c \uae08\uc9c0\ud558\uace0 \uc704\ubc18\uc2dc \ub300\uc8fc\uac00 \ud574\uc9c0\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud558\uba70, \uc81c613\uc870\ub294 \uc874\uc18d\uae30\uac04\uc744 \uc815\ud558\uc9c0 \uc54a\uc740 \uacbd\uc6b0 \ubaa9\uc801\uc5d0 \ub530\ub978 \uc0ac\uc6a9\xb7\uc218\uc775\uc774 \uc885\ub8cc\ud558\uac70\ub098 \uadf8\uc5d0 \uc871\ud55c \uae30\uac04\uc774 \uacbd\uacfc\ud558\uba74 \ub300\uc8fc\uac00 \ud574\uc9c0\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uadf8\ub7ec\ub098 \uc81c614\uc870\ub294 \ucc28\uc8fc\uc758 \uc0ac\ub9dd\uc73c\ub85c \uc0ac\uc6a9\ub300\ucc28\uac00 \uc885\ub8cc\ud55c\ub2e4\uace0 \uaddc\uc815\ud558\ubbc0\ub85c \uc0c1\uc18d\uc778\uc5d0\uac8c \uc2b9\uacc4\ub41c\ub2e4\ub294 \uc11c\uc220\uc740 \uc633\uc9c0 \uc54a\ub2e4.",B.adY,B.aQu,null)
B.b1m=s(["\ub300\uc8fc\uac00 \ubaa9\uc801\ubb3c\uc744 \uc778\ub3c4\ud558\uae30 \uc804\uc5d0\ub294 \ub2f9\uc0ac\uc790\ub294 \uc5b8\uc81c\ub4e0\uc9c0 \uacc4\uc57d\uc744 \ud574\uc81c\ud560 \uc218 \uc788\ub2e4.","\ubb34\uc774\uc790 \uc18c\ube44\ub300\ucc28\uc758 \uacbd\uc6b0 \ubaa9\uc801\ubb3c \uc778\ub3c4 \uc804 \ud574\uc81c\ub85c \uc778\ud55c \uc190\ud574\ubc30\uc0c1\ucc45\uc784\uc740 \ubc1c\uc0dd\ud558\uc9c0 \uc54a\ub294\ub2e4.","\ub300\uc8fc\uac00 \ud30c\uc0b0\uc120\uace0\ub97c \ubc1b\uc544\ub3c4 \uc544\uc9c1 \ubaa9\uc801\ubb3c\uc744 \uc778\ub3c4\ud558\uc9c0 \uc54a\uc740 \uc18c\ube44\ub300\ucc28\uc758 \ud6a8\ub825\uc5d0\ub294 \uc601\ud5a5\uc774 \uc5c6\ub2e4.","\uc18c\ube44\ub300\ucc28\ub294 \ub099\uc131\uacc4\uc57d\uc774\ubbc0\ub85c \ubaa9\uc801\ubb3c \uc778\ub3c4 \uc804\uc774\ub77c\ub3c4 \ud574\uc81c\ub294 \ud5c8\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4."],t.s)
B.b0R=s(["\ubb34\uc774\uc790 \uc18c\ube44\ub300\ucc28\uc758 \ub2f9\uc0ac\uc790\ub294 \ubaa9\uc801\ubb3c\uc758 \uc778\ub3c4 \uc804\uc5d0\ub294 \uc5b8\uc81c\ub4e0\uc9c0 \uacc4\uc57d\uc744 \ud574\uc81c\ud560 \uc218 \uc788\uace0"],t.s)
B.Ts=s(["\uc18c\ube44\ub300\ucc28\uc758 \ud574\uc81c","\ubb34\uc774\uc790 \uc18c\ube44\ub300\ucc28","\uc81c601\uc870"],t.s)
B.btV=new A.a("gen_cl_typedcontract_35","civil_law","\uc804\ud615\uacc4\uc57d \uac01\ub860(\ub9e4\ub9e4\xb7\uc784\ub300\ucc28\xb7\ub3c4\uae09 \ub4f1)",null,"\uc18c\ube44\ub300\ucc28\uc758 \ud574\uc81c\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.b1m,1,"\ubbfc\ubc95 \uc81c601\uc870\ub294 \ubb34\uc774\uc790 \uc18c\ube44\ub300\ucc28\uc758 \ub2f9\uc0ac\uc790\ub294 \ubaa9\uc801\ubb3c\uc758 \uc778\ub3c4 \uc804\uc5d0\ub294 \uc5b8\uc81c\ub4e0\uc9c0 \uacc4\uc57d\uc744 \ud574\uc81c\ud560 \uc218 \uc788\uace0, \ub2e4\ub9cc \uc0c1\ub300\ubc29\uc5d0\uac8c \uc190\ud574\uac00 \uc788\ub294 \ub54c\uc5d0\ub294 \uc774\ub97c \ubc30\uc0c1\ud558\uc5ec\uc57c \ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ubb34\uc774\uc790 \uc18c\ube44\ub300\ucc28\uc758 \uacbd\uc6b0 \ud1b5\uc0c1 \uc190\ud574\uac00 \uc5c6\uc73c\ubbc0\ub85c \ubc30\uc0c1\ucc45\uc784\uc774 \ubc1c\uc0dd\ud558\uc9c0 \uc54a\ub294 \uac83\uc774 \uc77c\ubc18\uc801\uc774\ub2e4. \ub610\ud55c \uc81c599\uc870\uc5d0 \ub530\ub77c \ub300\uc8fc\uac00 \ubaa9\uc801\ubb3c\uc744 \uc778\ub3c4\ud558\uae30 \uc804\uc5d0 \ud30c\uc0b0\uc120\uace0\ub97c \ubc1b\uc73c\uba74 \uc18c\ube44\ub300\ucc28\ub294 \ud6a8\ub825\uc744 \uc783\ub294\ub2e4.",B.b0R,B.Ts,null)
B.a6Z=s(["\uc704\uc784\uc0ac\ubb34\uc758 \ucc98\ub9ac\uc5d0 \ube44\uc6a9\uc744 \uc694\ud558\ub294 \ub54c\uc5d0\ub294 \uc704\uc784\uc778\uc740 \uc218\uc784\uc778\uc758 \uccad\uad6c\uc5d0 \uc758\ud558\uc5ec \uc774\ub97c \uc120\uae09\ud558\uc5ec\uc57c \ud55c\ub2e4.","\uc218\uc784\uc778\uc758 \ubcf4\uc218\ub294 \ud2b9\uc57d\uc774 \uc5c6\uc5b4\ub3c4 \uc704\uc784\uc0ac\ubb34 \ucc29\uc218\uc640 \ub3d9\uc2dc\uc5d0 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4.","\uc704\uc784\uc778\uc740 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ube44\uc6a9\uc744 \uc120\uae09\ud560 \uc758\ubb34\ub97c \ubd80\ub2f4\ud558\uc9c0 \uc54a\ub294\ub2e4.","\ubcf4\uc218 \uc788\ub294 \uc704\uc784\uc5d0\uc11c \ubcf4\uc218\ub294 \ud2b9\uc57d\uc774 \uc5c6\ub294 \ud55c \uc704\uc784\uc0ac\ubb34\uc758 \ucc98\ub9ac \uc804\uc5d0 \uc9c0\uae09\ud558\uc5ec\uc57c \ud55c\ub2e4."],t.s)
B.bbY=s(["\uc704\uc784\uc778\uc740 \uc218\uc784\uc778\uc758 \uccad\uad6c\uc5d0 \uc758\ud558\uc5ec \uc774\ub97c \uc120\uae09\ud558\uc5ec\uc57c \ud55c\ub2e4"],t.s)
B.Zp=s(["\uc704\uc784\uc778\uc758 \ube44\uc6a9\uc120\uae09\uc758\ubb34","\uc81c687\uc870","\ubcf4\uc218\ud6c4\uae09\uc6d0\uce59"],t.s)
B.bB4=new A.a("gen_cl_typedcontract_36","civil_law","\uc804\ud615\uacc4\uc57d \uac01\ub860(\ub9e4\ub9e4\xb7\uc784\ub300\ucc28\xb7\ub3c4\uae09 \ub4f1)",null,"\uc704\uc784\uc778\uc758 \ube44\uc6a9\uc120\uae09\uc758\ubb34 \ubc0f \ubcf4\uc218\uc9c0\uae09\uc2dc\uae30\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.a6Z,0,"\ubbfc\ubc95 \uc81c687\uc870\ub294 \uc704\uc784\uc0ac\ubb34\uc758 \ucc98\ub9ac\uc5d0 \ube44\uc6a9\uc744 \uc694\ud558\ub294 \ub54c\uc5d0\ub294 \uc704\uc784\uc778\uc740 \uc218\uc784\uc778\uc758 \uccad\uad6c\uc5d0 \uc758\ud558\uc5ec \uc774\ub97c \uc120\uae09\ud558\uc5ec\uc57c \ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ud55c\ud3b8 \uc81c686\uc870 \uc81c2\ud56d\uc5d0 \ub530\ub77c \ubcf4\uc218\ub294 \ud2b9\uc57d\uc774 \uc5c6\ub294 \ud55c \uc704\uc784\uc0ac\ubb34\ub97c \uc644\ub8cc\ud55c \ud6c4\uac00 \uc544\ub2c8\uba74 \uc774\ub97c \uccad\uad6c\ud558\uc9c0 \ubabb\ud558\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub2e4.",B.bbY,B.Zp,null)
B.anV=s(["\uc218\uc784\uc778\uc740 \uc704\uc784\uc0ac\ubb34\uc758 \ucc98\ub9ac\ub85c \uc778\ud558\uc5ec \ubc1b\uc740 \uae08\uc804 \uae30\ud0c0\uc758 \ubb3c\uac74 \ubc0f \uadf8 \uc218\ucde8\ud55c \uacfc\uc2e4\uc744 \uc704\uc784\uc778\uc5d0\uac8c \uc778\ub3c4\ud558\uc5ec\uc57c \ud55c\ub2e4.","\uc218\uc784\uc778\uc774 \uc704\uc784\uc0ac\ubb34 \ucc98\ub9ac\ub85c \ucde8\ub4dd\ud55c \ubb3c\uac74\uc740 \uc218\uc784\uc778 \uc790\uc2e0\uc758 \uc7ac\uc0b0\uc774 \ub418\ubbc0\ub85c \uc778\ub3c4\uc758\ubb34\uac00 \uc5c6\ub2e4.","\uc218\uc784\uc778\uc774 \uc704\uc784\uc778\uc744 \uc704\ud558\uc5ec \uc790\uae30\uba85\uc758\ub85c \ucde8\ub4dd\ud55c \uad8c\ub9ac\ub294 \uc704\uc784\uc778\uc5d0\uac8c \uc774\uc804\ud560 \ud544\uc694\uac00 \uc5c6\ub2e4.","\uc218\uc784\uc778\uc758 \ucde8\ub4dd\ubb3c \uc778\ub3c4\uc758\ubb34\ub294 \ud2b9\uc57d\uc774 \uc788\uc5b4\uc57c\ub9cc \ubc1c\uc0dd\ud558\ub294 \uc784\uc758\uc801 \uc758\ubb34\uc774\ub2e4."],t.s)
B.bit=s(["\uc218\uc784\uc778\uc740 \uc704\uc784\uc0ac\ubb34\uc758 \ucc98\ub9ac\ub85c \ubc1b\uc740 \uae08\uc804 \uae30\ud0c0\uc758 \ubb3c\uac74 \ubc0f \uadf8 \uc218\ucde8\ud55c \uacfc\uc2e4\uc744 \uc704\uc784\uc778\uc5d0\uac8c \uc778\ub3c4\ud558\uc5ec\uc57c \ud55c\ub2e4"],t.s)
B.ads=s(["\uc218\uc784\uc778\uc758 \ucde8\ub4dd\ubb3c\uc778\ub3c4\uc758\ubb34","\uc81c684\uc870","\uad8c\ub9ac\uc774\uc804\uc758\ubb34"],t.s)
B.btp=new A.a("gen_cl_typedcontract_37","civil_law","\uc804\ud615\uacc4\uc57d \uac01\ub860(\ub9e4\ub9e4\xb7\uc784\ub300\ucc28\xb7\ub3c4\uae09 \ub4f1)",null,"\uc218\uc784\uc778\uc758 \ucde8\ub4dd\ubb3c \uc778\ub3c4\uc758\ubb34\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.anV,0,"\ubbfc\ubc95 \uc81c684\uc870 \uc81c1\ud56d\uc740 \uc218\uc784\uc778\uc740 \uc704\uc784\uc0ac\ubb34\uc758 \ucc98\ub9ac\ub85c \ubc1b\uc740 \uae08\uc804 \uae30\ud0c0\uc758 \ubb3c\uac74 \ubc0f \uadf8 \uc218\ucde8\ud55c \uacfc\uc2e4\uc744 \uc704\uc784\uc778\uc5d0\uac8c \uc778\ub3c4\ud558\uc5ec\uc57c \ud55c\ub2e4\uace0 \uaddc\uc815\ud558\uace0, \uc81c2\ud56d\uc740 \uc218\uc784\uc778\uc774 \uc704\uc784\uc778\uc744 \uc704\ud558\uc5ec \uc790\uae30\uba85\uc758\ub85c \ucde8\ub4dd\ud55c \uad8c\ub9ac\ub294 \uc704\uc784\uc778\uc5d0\uac8c \uc774\uc804\ud558\uc5ec\uc57c \ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4.",B.bit,B.ads,null)
B.bhU=s(["\uc784\uce58\uae30\uac04\uc758 \uc57d\uc815\uc774 \uc5c6\ub294 \ub54c\uc5d0\ub294 \uac01 \ub2f9\uc0ac\uc790\ub294 \uc5b8\uc81c\ub4e0\uc9c0 \uacc4\uc57d\uc744 \ud574\uc9c0\ud560 \uc218 \uc788\ub2e4.","\uc784\uce58\uae30\uac04\uc744 \uc57d\uc815\ud55c \uacbd\uc6b0 \uc218\uce58\uc778\uc740 \ubd80\ub4dd\uc774\ud55c \uc0ac\uc720\uac00 \uc788\uc5b4\ub3c4 \uae30\uac04\ub9cc\ub8cc \uc804\uc5d0 \ud574\uc9c0\ud560 \uc218 \uc5c6\ub2e4.","\uc784\uce58\ubb3c\uc758 \ubc18\ud658\uc740 \uadf8 \ubb3c\uac74\uc744 \uc218\ub839\ud55c \uc7a5\uc18c\uac00 \uc544\ub2cc \uc784\uce58\uc778\uc758 \uc8fc\uc18c\uc9c0\uc5d0\uc11c\ub9cc \ud558\uc5ec\uc57c \ud55c\ub2e4.","\uc784\uce58\uc778\uc740 \ubd80\ub4dd\uc774\ud55c \uc0ac\uc720\uac00 \uc788\ub354\ub77c\ub3c4 \uc784\uce58\uae30\uac04 \ub9cc\ub8cc \uc804\uc5d0 \ubc18\ud658\uc744 \uccad\uad6c\ud560 \uc218 \uc5c6\ub2e4."],t.s)
B.aCf=s(["\uae30\uac04\uc758 \uc57d\uc815\uc774 \uc5c6\ub294 \ub54c\uc5d0\ub294 \uac01 \ub2f9\uc0ac\uc790\uac00 \uc5b8\uc81c\ub4e0\uc9c0 \uacc4\uc57d\uc744 \ud574\uc9c0\ud560 \uc218 \uc788\ub2e4"],t.s)
B.baD=s(["\uc784\uce58\uc758 \ud574\uc9c0","\uc81c699\uc870","\uae30\uac04\uc57d\uc815 \uc5c6\ub294 \uc784\uce58"],t.s)
B.bJb=new A.a("gen_cl_typedcontract_38","civil_law","\uc804\ud615\uacc4\uc57d \uac01\ub860(\ub9e4\ub9e4\xb7\uc784\ub300\ucc28\xb7\ub3c4\uae09 \ub4f1)",null,"\uc784\uce58\uc758 \uc885\ub8cc \ubc0f \ubc18\ud658\uc7a5\uc18c\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.bhU,0,"\ubbfc\ubc95 \uc81c698\uc870\ub294 \uc784\uce58\uae30\uac04\uc758 \uc57d\uc815\uc774 \uc788\ub294 \ub54c\uc5d0\ub3c4 \ubd80\ub4dd\uc774\ud55c \uc0ac\uc720 \uc788\ub294 \ub54c\uc5d0\ub294 \uc218\uce58\uc778\uc774 \uacc4\uc57d\uc744 \ud574\uc9c0\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud558\uace0, \uc81c699\uc870\ub294 \uae30\uac04\uc758 \uc57d\uc815\uc774 \uc5c6\ub294 \ub54c\uc5d0\ub294 \uac01 \ub2f9\uc0ac\uc790\uac00 \uc5b8\uc81c\ub4e0\uc9c0 \uacc4\uc57d\uc744 \ud574\uc9c0\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ub610\ud55c \uc784\uce58\uc778\uc740 \uc81c698\uc870 \ub2e8\uc11c \ubc0f \uc81c702\uc870\uc5d0 \ub530\ub77c \uae30\uac04 \uc57d\uc815\uc774 \uc788\uc5b4\ub3c4 \uc5b8\uc81c\ub4e0\uc9c0 \ubc18\ud658\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub2e4.",B.aCf,B.baD,null)
B.aJb=s(["\uc218\uce58\uc778\uc774 \uc784\uce58\ubb3c\uc744 \uc18c\ube44\ud560 \uc218 \uc788\uace0 \uadf8\uc640 \uc885\ub958\xb7\ud488\uc9c8\xb7\uc218\ub7c9\uc774 \uac19\uc740 \ubb3c\uac74\uc744 \ubc18\ud658\ud558\uae30\ub85c \uc57d\uc815\ud55c \uacbd\uc6b0 \uc18c\ube44\ub300\ucc28\uc5d0 \uad00\ud55c \uaddc\uc815\uc744 \uc900\uc6a9\ud55c\ub2e4.","\uc18c\ube44\uc784\uce58\uc758 \uacbd\uc6b0 \uc5b8\uc81c\ub098 \uc784\uce58\uc5d0 \uad00\ud55c \uaddc\uc815\ub9cc \uc801\uc6a9\ub418\uace0 \uc18c\ube44\ub300\ucc28\uaddc\uc815\uc740 \uc804\ud600 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4.","\uc18c\ube44\uc784\uce58\ub294 \uc784\uce58\uc778\uc758 \uc774\uc775\uc744 \uc704\ud55c \uac83\uc774\ubbc0\ub85c \ubc18\ud658\uc2dc\uae30\uc758 \uc57d\uc815\uc774 \uc788\uc5b4\ub3c4 \uc784\uce58\uc778\uc740 \uc5b8\uc81c\ub4e0\uc9c0 \ubc18\ud658\uc744 \uccad\uad6c\ud558\uc9c0 \ubabb\ud55c\ub2e4.","\uc18c\ube44\uc784\uce58\uc5d0\uc11c\ub294 \uc218\uce58\uc778\uc774 \ubaa9\uc801\ubb3c\uc758 \uc18c\uc720\uad8c\uc744 \ucde8\ub4dd\ud558\uc9c0 \uc54a\ub294\ub2e4."],t.s)
B.bcT=s(["\uadf8 \uc784\uce58\ubb3c\uc758 \uc18c\uc720\uad8c\uc774 \uc218\uce58\uc778\uc5d0\uac8c \uc774\uc804\ub418\uba70 \uc18c\ube44\ub300\ucc28\uc5d0 \uad00\ud55c \uaddc\uc815\uc744 \uc900\uc6a9\ud55c\ub2e4"],t.s)
B.aEe=s(["\uc18c\ube44\uc784\uce58","\uc81c702\uc870","\uc18c\ube44\ub300\ucc28\uaddc\uc815 \uc900\uc6a9"],t.s)
B.bse=new A.a("gen_cl_typedcontract_39","civil_law","\uc804\ud615\uacc4\uc57d \uac01\ub860(\ub9e4\ub9e4\xb7\uc784\ub300\ucc28\xb7\ub3c4\uae09 \ub4f1)",null,"\ud63c\ud569\uc784\uce58(\uc18c\ube44\uc784\uce58)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aJb,0,"\ubbfc\ubc95 \uc81c702\uc870\ub294 \uc218\uce58\uc778\uc774 \uc784\uce58\ubb3c\uc744 \uc18c\ube44\ud560 \uc218 \uc788\ub294 \uacbd\uc6b0 \uadf8 \uc784\uce58\ubb3c\uc758 \uc18c\uc720\uad8c\uc774 \uc218\uce58\uc778\uc5d0\uac8c \uc774\uc804\ub418\uba70 \uc18c\ube44\ub300\ucc28\uc5d0 \uad00\ud55c \uaddc\uc815\uc744 \uc900\uc6a9\ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4(\uc18c\ube44\uc784\uce58). \ub2e4\ub9cc \ubc18\ud658\uc2dc\uae30\uc758 \uc57d\uc815\uc774 \uc788\ub294 \uacbd\uc6b0\uc5d0\ub3c4 \uc784\uce58\uc778\uc740 \uc5b8\uc81c\ub4e0\uc9c0 \ubc18\ud658\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4\ub294 \uc810\uc5d0\uc11c \uc21c\uc218\ud55c \uc18c\ube44\ub300\ucc28\uc640 \ucc28\uc774\uac00 \uc788\ub2e4.",B.bcT,B.aEe,null)
B.TI=s(["\ub2f9\uc0ac\uc790\uac00 \uc190\uc775\ubd84\ubc30\uc758 \ube44\uc728\uc744 \uc815\ud558\uc9c0 \uc544\ub2c8\ud55c \ub54c\uc5d0\ub294 \uac01 \uc870\ud569\uc6d0\uc758 \ucd9c\uc790\uac00\uc561\uc5d0 \ube44\ub840\ud558\uc5ec \uc774\ub97c \uc815\ud55c\ub2e4.","\uc774\uc775 \ub610\ub294 \uc190\uc2e4\uc5d0 \ub300\ud558\uc5ec \ubd84\ubc30\ube44\uc728\uc744 \uc815\ud55c \ub54c\uc5d0\ub294 \uadf8 \ube44\uc728\uc740 \uc774\uc775\uc5d0\ub294 \uc801\uc6a9\ub418\ub098 \uc190\uc2e4\uc5d0\ub294 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4.","\uc870\ud569\uc6d0 \uc911 1\uc778\uc774 \uc190\uc775\ubd84\ubc30\ube44\uc728\uc744 \uc815\ud558\uc9c0 \uc54a\uc740 \uacbd\uc6b0 \uade0\ub4f1\ud558\uac8c \ubd84\ubc30\ud574\uc57c \ud558\uba70 \ucd9c\uc790\uac00\uc561\uc740 \uace0\ub824\ud558\uc9c0 \uc54a\ub294\ub2e4.","\uc190\uc775\ubd84\ubc30\ube44\uc728\uc740 \uc870\ud569\uacc4\uc57d \uccb4\uacb0 \ud6c4\uc5d0\ub294 \uc808\ub300 \ubcc0\uacbd\ud560 \uc218 \uc5c6\ub2e4."],t.s)
B.aN4=s(["\ub2f9\uc0ac\uc790\uac00 \uc190\uc775\ubd84\ubc30\uc758 \ube44\uc728\uc744 \uc815\ud558\uc9c0 \uc544\ub2c8\ud55c \ub54c\uc5d0\ub294 \uac01 \uc870\ud569\uc6d0\uc758 \ucd9c\uc790\uac00\uc561\uc5d0 \ube44\ub840\ud558\uc5ec \uc774\ub97c \uc815\ud55c\ub2e4"],t.s)
B.b4y=s(["\uc870\ud569\uc758 \uc190\uc775\ubd84\ubc30","\uc81c711\uc870","\ucd9c\uc790\uac00\uc561\ube44\ub840"],t.s)
B.bDy=new A.a("gen_cl_typedcontract_40","civil_law","\uc804\ud615\uacc4\uc57d \uac01\ub860(\ub9e4\ub9e4\xb7\uc784\ub300\ucc28\xb7\ub3c4\uae09 \ub4f1)",null,"\uc870\ud569\uc6d0\uc758 \uc190\uc775\ubd84\ubc30\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.TI,0,"\ubbfc\ubc95 \uc81c711\uc870 \uc81c1\ud56d\uc740 \ub2f9\uc0ac\uc790\uac00 \uc190\uc775\ubd84\ubc30\uc758 \ube44\uc728\uc744 \uc815\ud558\uc9c0 \uc544\ub2c8\ud55c \ub54c\uc5d0\ub294 \uac01 \uc870\ud569\uc6d0\uc758 \ucd9c\uc790\uac00\uc561\uc5d0 \ube44\ub840\ud558\uc5ec \uc774\ub97c \uc815\ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc81c2\ud56d\uc740 \uc774\uc775 \ub610\ub294 \uc190\uc2e4\uc5d0 \uad00\ud558\uc5ec\ub9cc \ubd84\ubc30\ube44\uc728\uc744 \uc815\ud55c \ub54c\uc5d0\ub294 \uadf8 \ube44\uc728\uc740 \uc774\uc775\uacfc \uc190\uc2e4\uc5d0 \uacf5\ud1b5\ub41c \uac83\uc73c\ub85c \ucd94\uc815\ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4.",B.aN4,B.b4y,null)
B.aMJ=s(["\uc870\ud569\uacc4\uc57d\uc73c\ub85c \uc870\ud569\uc758 \uc874\uc18d\uae30\uac04\uc744 \uc815\ud558\uc9c0 \uc544\ub2c8\ud55c \ub54c\uc5d0\ub294 \uac01 \uc870\ud569\uc6d0\uc740 \uc5b8\uc81c\ub4e0\uc9c0 \ud0c8\ud1f4\ud560 \uc218 \uc788\ub2e4.","\uc870\ud569\uc6d0\uc740 \ubd80\ub4dd\uc774\ud55c \uc0ac\uc720\uac00 \uc788\uc5b4\ub3c4 \uc874\uc18d\uae30\uac04\uc758 \uc57d\uc815\uc774 \uc788\uc73c\uba74 \ud0c8\ud1f4\ud560 \uc218 \uc5c6\ub2e4.","\uc870\ud569\uc6d0\uc774 \uc0ac\ub9dd\ud558\uba74 \uadf8 \uc0c1\uc18d\uc778\uc774 \ub2f9\uc5f0\ud788 \uc870\ud569\uc6d0\uc758 \uc9c0\uc704\ub97c \uc2b9\uacc4\ud55c\ub2e4.","\uc870\ud569\uc6d0\uc758 \ud0c8\ud1f4\ub294 \ub2e4\ub978 \uc870\ud569\uc6d0 \uc804\uc6d0\uc758 \ub3d9\uc758\uac00 \uc5c6\uc73c\uba74 \uc808\ub300 \ud6a8\ub825\uc774 \uc5c6\ub2e4."],t.s)
B.aAr=s(["\uac01 \uc870\ud569\uc6d0\uc740 \uc5b8\uc81c\ub4e0\uc9c0 \ud0c8\ud1f4\ud560 \uc218 \uc788\ub2e4"],t.s)
B.afE=s(["\uc870\ud569\uc6d0\uc758 \ud0c8\ud1f4","\uc81c716\uc870","\uc784\uc758\ud0c8\ud1f4"],t.s)
B.bAt=new A.a("gen_cl_typedcontract_41","civil_law","\uc804\ud615\uacc4\uc57d \uac01\ub860(\ub9e4\ub9e4\xb7\uc784\ub300\ucc28\xb7\ub3c4\uae09 \ub4f1)",null,"\uc870\ud569\uc6d0\uc758 \ud0c8\ud1f4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aMJ,0,"\ubbfc\ubc95 \uc81c716\uc870 \uc81c1\ud56d\uc740 \uc870\ud569\uc758 \uc874\uc18d\uae30\uac04\uc744 \uc815\ud558\uc9c0 \uc544\ub2c8\ud558\uac70\ub098 \uc870\ud569\uc6d0\uc758 \uc885\uc2e0\uae4c\uc9c0 \uc874\uc18d\ud560 \uac83\uc744 \uc815\ud55c \ub54c\uc5d0\ub294 \uac01 \uc870\ud569\uc6d0\uc740 \uc5b8\uc81c\ub4e0\uc9c0 \ud0c8\ud1f4\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ub2e4\ub9cc \ubd80\ub4dd\uc774\ud55c \uc0ac\uc720\uac00 \uc788\ub294 \ub54c\uc5d0\ub294 \uc874\uc18d\uae30\uac04\uc758 \uc57d\uc815\uc774 \uc788\ub294 \uacbd\uc6b0\uc5d0\ub3c4 \uac01 \uc870\ud569\uc6d0\uc740 \ud0c8\ud1f4\ud560 \uc218 \uc788\ub2e4(\uc81c2\ud56d).",B.aAr,B.afE,null)
B.aze=s(["\uc784\ucc28\uc778\uc740 \uc784\ub300\ucc28 \uc885\ub8cc\uc2dc \ubaa9\uc801\ubb3c\uc744 \uc6d0\uc0c1\uc5d0 \ud68c\ubcf5\ud558\uc5ec \ubc18\ud658\ud560 \uc758\ubb34\ub97c \ubd80\ub2f4\ud55c\ub2e4.","\uc784\ucc28\uc778\uc758 \uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\ub294 \uc784\ub300\uc778\uc758 \ubaa9\uc801\ubb3c\ubc18\ud658\uccad\uad6c\uad8c\uacfc \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uc5d0 \uc788\uc9c0 \uc54a\ub2e4.","\uc784\ucc28\uc778\uc740 \uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\ub97c \ubd80\ub2f4\ud558\uc9c0 \uc54a\uc73c\uba70 \uc774\ub294 \uc784\ub300\uc778\uc758 \uc758\ubb34\uc774\ub2e4.","\ubd80\uc18d\ubb3c\ub9e4\uc218\uccad\uad6c\uad8c\uc774 \ud589\uc0ac\ub418\uba74 \uadf8 \ubd80\ubd84\uc5d0 \ub300\ud574\uc11c\ub3c4 \uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\uac00 \uadf8\ub300\ub85c \uc874\uc18d\ud55c\ub2e4."],t.s)
B.alu=s(["\uc784\ucc28\uc778\uc740 \uc784\ub300\ucc28 \uc885\ub8cc\uc2dc \ubaa9\uc801\ubb3c\uc744 \uc6d0\uc0c1\uc5d0 \ud68c\ubcf5\ud558\uc5ec \ubc18\ud658\ud560 \uc758\ubb34\ub97c \ubd80\ub2f4"],t.s)
B.aIH=s(["\uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34","\ub3d9\uc2dc\uc774\ud589\uad00\uacc4","\uc81c654\uc870"],t.s)
B.by0=new A.a("gen_cl_typedcontract_42","civil_law","\uc804\ud615\uacc4\uc57d \uac01\ub860(\ub9e4\ub9e4\xb7\uc784\ub300\ucc28\xb7\ub3c4\uae09 \ub4f1)",null,"\uc784\ub300\ucc28\uc5d0\uc11c \uc784\ucc28\uc778\uc758 \uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aze,0,"\ubbfc\ubc95 \uc81c654\uc870\uac00 \uc900\uc6a9\ud558\ub294 \uc81c615\uc870 \ub4f1\uc5d0 \ub530\ub77c \uc784\ucc28\uc778\uc740 \uc784\ub300\ucc28 \uc885\ub8cc\uc2dc \ubaa9\uc801\ubb3c\uc744 \uc6d0\uc0c1\uc5d0 \ud68c\ubcf5\ud558\uc5ec \ubc18\ud658\ud560 \uc758\ubb34\ub97c \ubd80\ub2f4\ud558\uba70, \uc774\ub294 \uc784\ub300\uc778\uc758 \ubaa9\uc801\ubb3c\ubc18\ud658\uccad\uad6c\uad8c \ub0b4\uc9c0 \uc190\ud574\ubc30\uc0c1\uccad\uad6c\uad8c\uacfc \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uc5d0 \uc788\ub2e4. \ub2e4\ub9cc \ubd80\uc18d\ubb3c\ub9e4\uc218\uccad\uad6c\uad8c\uc774 \uc801\ubc95\ud558\uac8c \ud589\uc0ac\ub41c \ubd80\ubd84\uc5d0 \ub300\ud558\uc5ec\ub294 \ub9e4\ub9e4\uc758 \ud6a8\uacfc\uac00 \ubc1c\uc0dd\ud558\ubbc0\ub85c \uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\uac00 \uc18c\uba78\ud55c\ub2e4.",B.alu,B.aIH,null)
B.ajl=s(["\uc784\ucc28\uc8fc\ud0dd\uc774 \uc591\ub3c4\ub418\uc5b4 \uc784\ub300\uc778 \uc9c0\uc704\uac00 \uc2b9\uacc4\ub41c \uacbd\uc6b0 \ud2b9\ubcc4\ud55c \uc0ac\uc815\uc774 \uc5c6\ub294 \ud55c \uc591\uc218\uc778\uc774 \ubcf4\uc99d\uae08\ubc18\ud658\ucc44\ubb34\ub97c \uc2b9\uacc4\ud55c\ub2e4.","\uc784\ub300\uc778 \uc9c0\uc704\uc758 \uc2b9\uacc4\uc5d0\ub294 \uc784\ucc28\uc778\uc758 \ub3d9\uc758\uac00 \ubc18\ub4dc\uc2dc \ud544\uc694\ud558\ub2e4.","\uc784\ub300\uc8fc\ud0dd \uc591\ub3c4\uc2dc \ubcf4\uc99d\uae08\ubc18\ud658\ucc44\ubb34\ub294 \uc591\ub3c4\uc778\uc774 \uacc4\uc18d \ubd80\ub2f4\ud558\uace0 \uc591\uc218\uc778\uc740 \ucc45\uc784\uc9c0\uc9c0 \uc54a\ub294\ub2e4.","\ubcf4\uc99d\uae08\ubc18\ud658\ucc44\ubb34\ub294 \uc784\ub300\uc778 \uc9c0\uc704 \uc2b9\uacc4\uc640 \ubb34\uad00\ud558\uac8c \ud56d\uc0c1 \ubcc4\ub3c4\uc758 \ucc44\ubb34\uc778\uc218\uc808\ucc28\uac00 \ud544\uc694\ud558\ub2e4."],t.s)
B.a8D=s(["\uc591\uc218\uc778\uc740 \uc784\ub300\uc778\uc758 \uc9c0\uc704\ub97c \uc2b9\uacc4\ud558\uace0, \uadf8\uc5d0 \ub530\ub77c \uc784\ub300\ucc28\ubcf4\uc99d\uae08 \ubc18\ud658\ucc44\ubb34\ub3c4 \ubcc4\ub3c4\uc758 \ucc44\ubb34\uc778\uc218\uc808\ucc28 \uc5c6\uc774 \uc591\uc218\uc778\uc5d0\uac8c \uc774\uc804"],t.s)
B.aGZ=s(["\uc784\ub300\uc778 \uc9c0\uc704 \uc2b9\uacc4","\ubcf4\uc99d\uae08\ubc18\ud658\ucc44\ubb34","\uc8fc\ud0dd\uc784\ub300\ucc28\ubcf4\ud638\ubc95"],t.s)
B.bH6=new A.a("gen_cl_typedcontract_43","civil_law","\uc804\ud615\uacc4\uc57d \uac01\ub860(\ub9e4\ub9e4\xb7\uc784\ub300\ucc28\xb7\ub3c4\uae09 \ub4f1)",null,"\uc804\uc138\uad8c\uacfc \uad6c\ubcc4\ub418\ub294 \uc784\ub300\ucc28\ubcf4\uc99d\uae08\ubc18\ud658\uccad\uad6c\uad8c\uc5d0 \uad00\ud55c \ud310\ub840\uc758 \ud0dc\ub3c4\ub85c \uc633\uc740 \uac83\uc740?",B.ajl,0,"\uc8fc\ud0dd\uc784\ub300\ucc28\ubcf4\ud638\ubc95 \ubc0f \ubbfc\ubc95\uc0c1 \ud310\ub840\uc5d0 \ub530\ub974\uba74 \ub300\ud56d\ub825\uc744 \uac16\ucd98 \uc784\ucc28\uc8fc\ud0dd\uc774 \uc591\ub3c4\ub41c \uacbd\uc6b0 \uc591\uc218\uc778\uc740 \uc784\ub300\uc778\uc758 \uc9c0\uc704\ub97c \uc2b9\uacc4\ud558\uace0, \uadf8\uc5d0 \ub530\ub77c \uc784\ub300\ucc28\ubcf4\uc99d\uae08 \ubc18\ud658\ucc44\ubb34\ub3c4 \ubcc4\ub3c4\uc758 \ucc44\ubb34\uc778\uc218\uc808\ucc28 \uc5c6\uc774 \uc591\uc218\uc778\uc5d0\uac8c \uc774\uc804\ub418\uba70 \uc591\ub3c4\uc778\uc740 \uc6d0\uce59\uc801\uc73c\ub85c \uadf8 \ucc44\ubb34\ub97c \uba74\ud55c\ub2e4.",B.a8D,B.aGZ,null)
B.UR=s(["\uc218\uae09\uc778\uc758 \ub2f4\ubcf4\ucc45\uc784\uc5d0 \uad00\ud55c \uad8c\ub9ac\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \ubaa9\uc801\ubb3c\uc758 \uc778\ub3c4\ub97c \ubc1b\uc740 \ub0a0\ub85c\ubd80\ud130 1\ub144 \ub0b4\uc5d0 \ud589\uc0ac\ud558\uc5ec\uc57c \ud55c\ub2e4.","\ud1a0\uc9c0, \uac74\ubb3c \uae30\ud0c0 \uacf5\uc791\ubb3c\uc758 \uc218\uae09\uc778\uc740 \uadf8 \uc874\uc18d\uae30\uac04\uc5d0 \uad00\uacc4\uc5c6\uc774 \ud56d\uc0c1 1\ub144\uc758 \ub2f4\ubcf4\ucc45\uc784\ub9cc \ubd80\ub2f4\ud55c\ub2e4.","\uc11d\uc870, \uc11d\ud68c\uc870, \uc5f0\uc640\uc870 \ub4f1 \uacac\uace0\ud55c \uac74\ubb3c\uc758 \ud558\uc790\ub2f4\ubcf4\ucc45\uc784\uae30\uac04\uc740 5\ub144\uc774\ub2e4.","\uc218\uae09\uc778\uc758 \ub2f4\ubcf4\ucc45\uc784 \uc874\uc18d\uae30\uac04\uc740 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ub2f9\uc0ac\uc790 \ud2b9\uc57d\uc73c\ub85c \uc5f0\uc7a5\ud560 \uc218 \uc5c6\ub2e4."],t.s)
B.aje=s(["\uc218\uae09\uc778\uc758 \ub2f4\ubcf4\ucc45\uc784\uc5d0 \uad00\ud55c \uad8c\ub9ac\ub294 \ubaa9\uc801\ubb3c\uc758 \uc778\ub3c4\ub97c \ubc1b\uc740 \ub0a0 \ub610\ub294 \uc77c\uc758 \uc885\ub8cc\ud55c \ub0a0\ub85c\ubd80\ud130 1\ub144 \ub0b4\uc5d0 \ud589\uc0ac\ud558\uc5ec\uc57c \ud55c\ub2e4"],t.s)
B.ay7=s(["\uc218\uae09\uc778 \ub2f4\ubcf4\ucc45\uc784 \uc874\uc18d\uae30\uac04","\uc81c670\uc870","\uacf5\uc791\ubb3c\uc758 \ud2b9\ub840"],t.s)
B.byT=new A.a("gen_cl_typedcontract_44","civil_law","\uc804\ud615\uacc4\uc57d \uac01\ub860(\ub9e4\ub9e4\xb7\uc784\ub300\ucc28\xb7\ub3c4\uae09 \ub4f1)",null,"\ub3c4\uae09\uc5d0\uc11c \ud558\uc790\ub2f4\ubcf4\ucc45\uc784\uc758 \uc874\uc18d\uae30\uac04\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.UR,0,"\ubbfc\ubc95 \uc81c670\uc870 \uc81c1\ud56d\uc740 \uc218\uae09\uc778\uc758 \ub2f4\ubcf4\ucc45\uc784\uc5d0 \uad00\ud55c \uad8c\ub9ac\ub294 \ubaa9\uc801\ubb3c\uc758 \uc778\ub3c4\ub97c \ubc1b\uc740 \ub0a0 \ub610\ub294 \uc77c\uc758 \uc885\ub8cc\ud55c \ub0a0\ub85c\ubd80\ud130 1\ub144 \ub0b4\uc5d0 \ud589\uc0ac\ud558\uc5ec\uc57c \ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ub2e4\ub9cc \uc81c671\uc870\uc5d0 \ub530\ub77c \ud1a0\uc9c0, \uac74\ubb3c \uae30\ud0c0 \uacf5\uc791\ubb3c\uc758 \uc218\uae09\uc778\uc740 \ubaa9\uc801\ubb3c\uc758 \uc778\ub3c4 \ud6c4 5\ub144\uac04, \uc11d\uc870\xb7\uc11d\ud68c\uc870\xb7\uc5f0\uc640\uc870\xb7\uae08\uc18d \uae30\ud0c0 \uc774\uc640 \uc720\uc0ac\ud55c \uc7ac\ub8cc\ub85c \uc870\uc131\ub41c \uac83\uc740 10\ub144\uac04 \ub2f4\ubcf4\ucc45\uc784\uc744 \uc9c4\ub2e4.",B.aje,B.ay7,null)
B.aOT=s(["\uc99d\uc5ec\uacc4\uc57d \ud6c4 \uc99d\uc5ec\uc790\uc758 \uc7ac\uc0b0\uc0c1\ud0dc\uac00 \ud604\uc800\ud788 \ubcc0\uacbd\ub418\uace0 \uc774\ud589\uc774 \uc99d\uc5ec\uc790\uc758 \uc0dd\uacc4\uc5d0 \uc911\ub300\ud55c \uc601\ud5a5\uc744 \ubbf8\uce60 \uacbd\uc6b0 \uc99d\uc5ec\uc790\ub294 \uc99d\uc5ec\ub97c \ud574\uc81c\ud560 \uc218 \uc788\ub2e4.","\uc99d\uc5ec\uc790\uc758 \uc7ac\uc0b0\uc0c1\ud0dc \ubcc0\uacbd\uc740 \uc99d\uc5ec\uacc4\uc57d\uc758 \ud6a8\ub825\uc5d0 \uc5b4\ub5a0\ud55c \uc601\ud5a5\ub3c4 \ubbf8\uce58\uc9c0 \uc54a\ub294\ub2e4.","\uc7ac\uc0b0\uc0c1\ud0dc \ubcc0\uacbd\uc73c\ub85c \uc778\ud55c \ud574\uc81c\ub294 \uc774\ubbf8 \uc774\ud589\ud55c \ubd80\ubd84\uc5d0\ub3c4 \uc18c\uae09\ud558\uc5ec \ubc18\ud658\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4.","\uc7ac\uc0b0\uc0c1\ud0dc \ubcc0\uacbd\uc73c\ub85c \uc778\ud55c \ud574\uc81c\uad8c\uc740 \uc218\uc99d\uc790\uc5d0\uac8c\ub9cc \uc778\uc815\ub41c\ub2e4."],t.s)
B.azb=s(["\uc99d\uc5ec\uc790\uc758 \uc7ac\uc0b0\uc0c1\ud0dc\uac00 \ud604\uc800\ud788 \ubcc0\uacbd\ub418\uace0 \uadf8 \uc774\ud589\uc73c\ub85c \uc778\ud558\uc5ec \uc0dd\uacc4\uc5d0 \uc911\ub300\ud55c \uc601\ud5a5\uc744 \ubbf8\uce60 \uacbd\uc6b0\uc5d0\ub294 \uc99d\uc5ec\uc790\ub294 \uc99d\uc5ec\ub97c \ud574\uc81c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.a3o=s(["\uc7ac\uc0b0\uc0c1\ud0dc \ubcc0\uacbd","\uc99d\uc5ec\ud574\uc81c","\uc81c557\uc870"],t.s)
B.bFX=new A.a("gen_cl_typedcontract_45","civil_law","\uc804\ud615\uacc4\uc57d \uac01\ub860(\ub9e4\ub9e4\xb7\uc784\ub300\ucc28\xb7\ub3c4\uae09 \ub4f1)",null,"\uc99d\uc5ec\uc790\uc758 \uc7ac\uc0b0\uc0c1\ud0dc \ubcc0\uacbd\uacfc \uc99d\uc5ec\uc758 \ud574\uc81c\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aOT,0,"\ubbfc\ubc95 \uc81c557\uc870\ub294 \uc99d\uc5ec\uacc4\uc57d \ud6c4 \uc99d\uc5ec\uc790\uc758 \uc7ac\uc0b0\uc0c1\ud0dc\uac00 \ud604\uc800\ud788 \ubcc0\uacbd\ub418\uace0 \uadf8 \uc774\ud589\uc73c\ub85c \uc778\ud558\uc5ec \uc0dd\uacc4\uc5d0 \uc911\ub300\ud55c \uc601\ud5a5\uc744 \ubbf8\uce60 \uacbd\uc6b0\uc5d0\ub294 \uc99d\uc5ec\uc790\ub294 \uc99d\uc5ec\ub97c \ud574\uc81c\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ub2e4\ub9cc \uc81c558\uc870\uc5d0 \ub530\ub77c \uc774\ubbf8 \uc774\ud589\ud55c \ubd80\ubd84\uc5d0\ub294 \ud574\uc81c\uc758 \ud6a8\ub825\uc774 \ubbf8\uce58\uc9c0 \uc54a\ub294\ub2e4.",B.azb,B.a3o,null)
B.aJH=s(["\uc0c1\ub300\ubd80\ub2f4 \uc788\ub294 \uc99d\uc5ec\uc5d0 \ub300\ud558\uc5ec\ub294 \uc99d\uc5ec\uc790\ub294 \uadf8 \ubd80\ub2f4\uc758 \ud55c\ub3c4\uc5d0\uc11c \ub9e4\ub3c4\uc778\uacfc \uac19\uc740 \ub2f4\ubcf4\ucc45\uc784\uc774 \uc788\ub2e4.","\ubd80\ub2f4\ubd80\uc99d\uc5ec\ub294 \ud56d\uc0c1 \uc30d\ubb34\uacc4\uc57d\uc758 \uc131\uc9c8\uc744 \uc644\uc804\ud788 \uac00\uc9c0\ubbc0\ub85c \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uac00 \uc804\uba74\uc801\uc73c\ub85c \uc801\uc6a9\ub41c\ub2e4.","\ubd80\ub2f4\ubd80\uc99d\uc5ec\uc5d0\uc11c \uc218\uc99d\uc790\uac00 \ubd80\ub2f4\uc744 \uc774\ud589\ud558\uc9c0 \uc54a\uc544\ub3c4 \uc99d\uc5ec\uc790\ub294 \uc774\ub97c \uc774\uc720\ub85c \ud574\uc81c\ud560 \uc218 \uc5c6\ub2e4.","\ubd80\ub2f4\ubd80\uc99d\uc5ec\ub294 \uc11c\uba74\uc5d0 \uc758\ud558\uc9c0 \uc54a\uc740 \uacbd\uc6b0\uc5d0\ub3c4 \ud574\uc81c\uac00 \uc804\ud600 \ud5c8\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4."],t.s)
B.YZ=s(["\uc99d\uc5ec\uc790\uac00 \uadf8 \ubd80\ub2f4\uc758 \ud55c\ub3c4\uc5d0\uc11c \ub9e4\ub3c4\uc778\uacfc \uac19\uc740 \ub2f4\ubcf4\ucc45\uc784\uc774 \uc788\ub2e4"],t.s)
B.as_=s(["\ubd80\ub2f4\ubd80\uc99d\uc5ec","\uc81c559\uc870","\uc30d\ubb34\uacc4\uc57d\uaddc\uc815 \uc900\uc6a9"],t.s)
B.bB8=new A.a("gen_cl_typedcontract_46","civil_law","\uc804\ud615\uacc4\uc57d \uac01\ub860(\ub9e4\ub9e4\xb7\uc784\ub300\ucc28\xb7\ub3c4\uae09 \ub4f1)",null,"\ubd80\ub2f4\ubd80\uc99d\uc5ec\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aJH,0,"\ubbfc\ubc95 \uc81c559\uc870 \uc81c2\ud56d\uc740 \uc0c1\ub300\ubd80\ub2f4 \uc788\ub294 \uc99d\uc5ec\uc5d0 \ub300\ud558\uc5ec\ub294 \uc99d\uc5ec\uc790\uac00 \uadf8 \ubd80\ub2f4\uc758 \ud55c\ub3c4\uc5d0\uc11c \ub9e4\ub3c4\uc778\uacfc \uac19\uc740 \ub2f4\ubcf4\ucc45\uc784\uc774 \uc788\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ub610\ud55c \ud310\ub840\ub294 \ubd80\ub2f4\ubd80\uc99d\uc5ec\uc758 \uacbd\uc6b0 \uc30d\ubb34\uacc4\uc57d\uc5d0 \uad00\ud55c \uaddc\uc815\uc774 \uc900\uc6a9\ub418\ubbc0\ub85c \uc218\uc99d\uc790\uac00 \ubd80\ub2f4\uc744 \uc774\ud589\ud558\uc9c0 \uc54a\uc73c\uba74 \uc99d\uc5ec\uc790\ub294 \ucc44\ubb34\ubd88\uc774\ud589\uc744 \uc774\uc720\ub85c \uacc4\uc57d\uc744 \ud574\uc81c\ud560 \uc218 \uc788\ub2e4\uace0 \ubcf8\ub2e4.",B.YZ,B.as_,null)
B.RJ=s(["\ub9e4\ub9e4\uacc4\uc57d\uc774 \uc788\uc740 \ud6c4\uc5d0\ub3c4 \uc778\ub3c4\ud558\uc9c0 \uc544\ub2c8\ud55c \ubaa9\uc801\ubb3c\ub85c\ubd80\ud130 \uc0dd\uae34 \uacfc\uc2e4\uc740 \ub9e4\ub3c4\uc778\uc5d0\uac8c \uc18d\ud55c\ub2e4.","\ub9e4\uc218\uc778\uc774 \ubaa9\uc801\ubb3c\uc744 \uc778\ub3c4\ubc1b\uc9c0 \uc54a\uc740 \uacbd\uc6b0\uc5d0\ub3c4 \ub300\uae08\uc744 \uc9c0\uae09\ud558\uc600\ub2e4\uba74 \uacfc\uc2e4\uc740 \ub9e4\ub3c4\uc778\uc5d0\uac8c \uadc0\uc18d\ud55c\ub2e4.","\ub9e4\uc218\uc778\uc740 \ubaa9\uc801\ubb3c\uc744 \uc778\ub3c4\ubc1b\uc740 \ub0a0 \uc774\ud6c4\uc758 \ub300\uae08\uc5d0 \ub300\ud574\uc11c\ub9cc \uc774\uc790\ub97c \uc9c0\uae09\ud560 \uc758\ubb34\uac00 \uc788\uace0 \uc778\ub3c4 \uc804\uc5d0\ub294 \uc774\uc790\ub97c \uc9c0\uae09\ud560 \ud544\uc694\uac00 \uc5c6\ub2e4.","\ubaa9\uc801\ubb3c\uc758 \uacfc\uc2e4 \uadc0\uc18d\uacfc \ub300\uae08\uc774\uc790 \ubb38\uc81c\ub294 \uad00\ub828\uc774 \uc5c6\ub2e4."],t.s)
B.QU=s(["\uc778\ub3c4\ud558\uc9c0 \uc544\ub2c8\ud55c \ubaa9\uc801\ubb3c\ub85c\ubd80\ud130 \uc0dd\uae34 \uacfc\uc2e4\uc740 \ub9e4\ub3c4\uc778\uc5d0\uac8c \uc18d\ud558\uace0"],t.s)
B.aGB=s(["\uacfc\uc2e4\uc758 \uadc0\uc18d","\ub300\uae08\uc774\uc790","\uc81c587\uc870"],t.s)
B.bKo=new A.a("gen_cl_typedcontract_47","civil_law","\uc804\ud615\uacc4\uc57d \uac01\ub860(\ub9e4\ub9e4\xb7\uc784\ub300\ucc28\xb7\ub3c4\uae09 \ub4f1)",null,"\ub9e4\ub9e4\ubaa9\uc801\ubb3c\uc758 \uacfc\uc2e4\uadc0\uc18d\uacfc \ub300\uae08\uc774\uc790\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.RJ,0,"\ubbfc\ubc95 \uc81c587\uc870\ub294 \ub9e4\ub9e4\uacc4\uc57d\uc774 \uc788\uc740 \ud6c4\uc5d0\ub3c4 \uc778\ub3c4\ud558\uc9c0 \uc544\ub2c8\ud55c \ubaa9\uc801\ubb3c\ub85c\ubd80\ud130 \uc0dd\uae34 \uacfc\uc2e4\uc740 \ub9e4\ub3c4\uc778\uc5d0\uac8c \uc18d\ud558\uace0, \ub9e4\uc218\uc778\uc740 \ubaa9\uc801\ubb3c\uc758 \uc778\ub3c4\ub97c \ubc1b\uc740 \ub0a0\ub85c\ubd80\ud130 \ub300\uae08\uc758 \uc774\uc790\ub97c \uc9c0\uae09\ud560 \uc758\ubb34\uac00 \uc788\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc774\ub294 \uacfc\uc2e4\uc218\ucde8\uc640 \ub300\uae08\uc774\uc790 \uc9c0\uae09\uc758\ubb34\ub97c \ub300\uc751\uc2dc\ucf1c \ud615\ud3c9\uc744 \ub3c4\ubaa8\ud55c \uac83\uc774\ub2e4.",B.QU,B.aGB,null)
B.UJ=s(["\ubd80\uc18d\ubb3c\ub9e4\uc218\uccad\uad6c\uad8c\uc740 \uac74\ubb3c \uae30\ud0c0 \uacf5\uc791\ubb3c\uc758 \uc784\ub300\ucc28\uc5d0\uc11c \uac74\ubb3c \uc0ac\uc6a9\uc758 \ud3b8\uc775\uc744 \uc704\ud574 \ubd80\uc18d\ub41c \ubb3c\uac74\uc5d0 \ub300\ud558\uc5ec \uc778\uc815\ub41c\ub2e4.","\ubd80\uc18d\ubb3c\ub9e4\uc218\uccad\uad6c\uad8c\uc740 \ud1a0\uc9c0\uc784\ub300\ucc28\uc5d0\uc11c \uc9c0\uc0c1\uac74\ubb3c\uc5d0 \ub300\ud558\uc5ec \uc778\uc815\ub418\ub294 \uad8c\ub9ac\uc640 \ub3d9\uc77c\ud55c \uc81c\ub3c4\uc774\ub2e4.","\ubd80\uc18d\ubb3c\ub9e4\uc218\uccad\uad6c\uad8c\uc740 \uc784\ucc28\uc778\uc774 \uc124\uce58\ud55c \ubaa8\ub4e0 \ubb3c\uac74\uc5d0 \ub300\ud558\uc5ec \uc608\uc678 \uc5c6\uc774 \uc778\uc815\ub41c\ub2e4.","\ubd80\uc18d\ubb3c\ub9e4\uc218\uccad\uad6c\uad8c\uc740 \uc624\ub85c\uc9c0 \uc784\ub300\uc778\uc758 \uc18c\uc720\uc5d0 \uc18d\ud558\ub294 \ubb3c\uac74\uc5d0 \ub300\ud574\uc11c\ub9cc \uc778\uc815\ub41c\ub2e4."],t.s)
B.aZM=s(["\uac74\ubb3c \uae30\ud0c0 \uacf5\uc791\ubb3c\uc758 \uc784\ub300\ucc28\uc5d0 \uc788\uc5b4\uc11c \uc784\ucc28\uc778\uc774 \uc784\ub300\uc778\uc758 \ub3d9\uc758\ub97c \uc5bb\uc5b4 \uadf8 \uac74\ubb3c\uc5d0 \ubd80\uc18d\uc2dc\ud0a8 \ubb3c\uac74\uc774 \uc788\ub294 \ub54c"],t.s)
B.ZA=s(["\ubd80\uc18d\ubb3c\ub9e4\uc218\uccad\uad6c\uad8c","\uac74\ubb3c\uc0ac\uc6a9\uc758 \ud3b8\uc775","\uc81c646\uc870"],t.s)
B.bGl=new A.a("gen_cl_typedcontract_48","civil_law","\uc804\ud615\uacc4\uc57d \uac01\ub860(\ub9e4\ub9e4\xb7\uc784\ub300\ucc28\xb7\ub3c4\uae09 \ub4f1)",null,"\uc784\ucc28\uc778\uc758 \uc9c0\uc0c1\ubb3c\ub9e4\uc218\uccad\uad6c\uad8c\uacfc \uad6c\ubcc4\ub418\ub294 \ubd80\uc18d\ubb3c\ub9e4\uc218\uccad\uad6c\uad8c\uc758 \uc801\uc6a9\ubc94\uc704\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.UJ,0,"\ubbfc\ubc95 \uc81c646\uc870\ub294 \uac74\ubb3c \uae30\ud0c0 \uacf5\uc791\ubb3c\uc758 \uc784\ub300\ucc28\uc5d0 \uc788\uc5b4\uc11c \uc784\ucc28\uc778\uc774 \uc784\ub300\uc778\uc758 \ub3d9\uc758\ub97c \uc5bb\uc5b4 \uadf8 \uac74\ubb3c\uc5d0 \ubd80\uc18d\uc2dc\ud0a8 \ubb3c\uac74\uc774 \uc788\ub294 \ub54c \uc784\ub300\ucc28 \uc885\ub8cc\uc2dc \uc784\ub300\uc778\uc5d0 \ub300\ud558\uc5ec \uadf8 \ubd80\uc18d\ubb3c\uc758 \ub9e4\uc218\ub97c \uccad\uad6c\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc774\ub294 \uac74\ubb3c\uc0ac\uc6a9\uc758 \uac1d\uad00\uc801 \ud3b8\uc775\uc5d0 \uc81c\uacf5\ub418\ub294 \ubb3c\uac74\uc5d0 \ud55c\ud558\uc5ec \uc778\uc815\ub418\uba70, \ud1a0\uc9c0\uc784\ucc28\uc778\uc758 \uc9c0\uc0c1\ubb3c\ub9e4\uc218\uccad\uad6c\uad8c(\uc81c643\uc870)\uacfc\ub294 \ubcc4\uac1c\uc758 \uc81c\ub3c4\uc774\ub2e4.",B.aZM,B.ZA,null)
B.awZ=s(["\uc704\uc784\uc885\ub8cc\uc758 \uacbd\uc6b0\uc5d0 \uae09\ubc15\ud55c \uc0ac\uc815\uc774 \uc788\ub294 \ub54c\uc5d0\ub294 \uc218\uc784\uc778\uc740 \uc704\uc784\uc778\uc774 \uadf8 \uc0ac\ubb34\ub97c \ucc98\ub9ac\ud560 \uc218 \uc788\uc744 \ub54c\uae4c\uc9c0 \uadf8 \uc0ac\ubb34\uc758 \ucc98\ub9ac\ub97c \uacc4\uc18d\ud558\uc5ec\uc57c \ud55c\ub2e4.","\uc704\uc784\uc774 \uc885\ub8cc\ub418\uba74 \uc218\uc784\uc778\uc740 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \uc0ac\ubb34\ucc98\ub9ac\ub97c \uc989\uc2dc \uc911\ub2e8\ud558\uc5ec\uc57c \ud55c\ub2e4.","\uc704\uc784\uc885\ub8cc \ud6c4\uc758 \uae34\uae09\ucc98\ub9ac\uc758\ubb34\ub294 \uc704\uc784\uc778\uc5d0\uac8c\ub9cc \uc801\uc6a9\ub418\ub294 \uc758\ubb34\uc774\ub2e4.","\uc704\uc784\uc885\ub8cc\uc2dc \uae34\uae09\ucc98\ub9ac\uc758\ubb34\ub294 \ud2b9\uc57d\uc774 \uc788\ub294 \uacbd\uc6b0\uc5d0\ub9cc \ubc1c\uc0dd\ud55c\ub2e4."],t.s)
B.ae5=s(["\uc704\uc784\uc885\ub8cc\uc758 \uacbd\uc6b0\uc5d0 \uae09\ubc15\ud55c \uc0ac\uc815\uc774 \uc788\ub294 \ub54c\uc5d0\ub294 \uc218\uc784\uc778"],t.s)
