B.bPb=new A.a("gen_cl_typedcontract_49","civil_law","\uc804\ud615\uacc4\uc57d \uac01\ub860(\ub9e4\ub9e4\xb7\uc784\ub300\ucc28\xb7\ub3c4\uae09 \ub4f1)",null,"\uc704\uc784\uc758 \uc885\ub8cc\uc2dc \uae34\uae09\ucc98\ub9ac\uc758\ubb34\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.awZ,0,"\ubbfc\ubc95 \uc81c691\uc870\ub294 \uc704\uc784\uc885\ub8cc\uc758 \uacbd\uc6b0\uc5d0 \uae09\ubc15\ud55c \uc0ac\uc815\uc774 \uc788\ub294 \ub54c\uc5d0\ub294 \uc218\uc784\uc778 \uadf8 \uc0c1\uc18d\uc778\uc774\ub098 \ubc95\uc815\ub300\ub9ac\uc778\uc740 \uc704\uc784\uc778, \uadf8 \uc0c1\uc18d\uc778\uc774\ub098 \ubc95\uc815\ub300\ub9ac\uc778\uc774 \uc704\uc784\uc0ac\ubb34\ub97c \ucc98\ub9ac\ud560 \uc218 \uc788\uc744 \ub54c\uae4c\uc9c0 \uadf8 \uc0ac\ubb34\uc758 \ucc98\ub9ac\ub97c \uacc4\uc18d\ud558\uc5ec\uc57c \ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc774\ub294 \uc704\uc784\uad00\uacc4 \uc885\ub8cc \ud6c4\uc5d0\ub3c4 \uc0ac\ubb34\ucc98\ub9ac\uc758 \uacf5\ubc31\uc744 \ub9c9\uae30 \uc704\ud55c \ubc95\uc815\uc758\ubb34\uc774\ub2e4.",B.ae5,B.YO,null)
