B.bBa=new A.a("gen_ba_inventory_14","business_admin","\ud68c\uacc4","\uc7ac\uace0\uc790\uc0b0 \ud3c9\uac00\uc640 \ub9e4\ucd9c\uc6d0\uac00","(\uc8fc)\uac00\ub9f9\uc758 \uae30\ub9d0\uc7ac\uace0\uc790\uc0b0 \ucde8\ub4dd\uc6d0\uac00\ub294 100,000\uc6d0\uc774\uace0 \uc21c\uc2e4\ud604\uac00\ub2a5\uac00\uce58\ub294 85,000\uc6d0\uc774\ub2e4. \uc800\uac00\ubc95\uc744 \uc801\uc6a9\ud560 \uacbd\uc6b0 \uc778\uc2dd\ud560 \uc7ac\uace0\uc790\uc0b0\ud3c9\uac00\uc190\uc2e4\uc740?",B.aUL,2,"\uc800\uac00\ubc95\uc740 \ucde8\ub4dd\uc6d0\uac00\uc640 \uc21c\uc2e4\ud604\uac00\ub2a5\uac00\uce58 \uc911 \ub0ae\uc740 \uae08\uc561\uc73c\ub85c \uc7ac\uace0\uc790\uc0b0\uc744 \ud3c9\uac00\ud558\ubbc0\ub85c, \uc21c\uc2e4\ud604\uac00\ub2a5\uac00\uce58(85,000\uc6d0)\uac00 \ucde8\ub4dd\uc6d0\uac00(100,000\uc6d0)\ubcf4\ub2e4 \ub0ae\uc740 \ucc28\uc561\uc778 100,000 \u2212 85,000 = 15,000\uc6d0\uc744 \uc7ac\uace0\uc790\uc0b0\ud3c9\uac00\uc190\uc2e4\ub85c \uc778\uc2dd\ud55c\ub2e4.",B.bij,B.avk,null)
B.afc=s(["\uc120\uc801\uc9c0\uc778\ub3c4\uc870\uac74(FOB shipping point)\uc778 \uacbd\uc6b0 \uc120\uc801 \uc2dc\uc810\uc5d0 \uc18c\uc720\uad8c\uc774 \ub9e4\uc785\uc790\uc5d0\uac8c \uc774\uc804\ub418\uc5b4 \ub9e4\uc785\uc790\uc758 \uc7ac\uace0\uc790\uc0b0\uc5d0 \ud3ec\ud568\ub41c\ub2e4","\ub3c4\ucc29\uc9c0\uc778\ub3c4\uc870\uac74(FOB destination)\uc778 \uacbd\uc6b0\uc5d0\ub3c4 \uc120\uc801\uacfc \ub3d9\uc2dc\uc5d0 \ub9e4\uc785\uc790\uc758 \uc7ac\uace0\uc790\uc0b0\uc5d0 \ud3ec\ud568\ub41c\ub2e4","\ubbf8\ucc29\uc0c1\ud488\uc740 \uc6b4\uc1a1 \uc911\uc774\ubbc0\ub85c \uc5b4\ub5a4 \uacbd\uc6b0\uc5d0\ub3c4 \uc7ac\uace0\uc790\uc0b0\uc5d0 \ud3ec\ud568\ub418\uc9c0 \uc54a\ub294\ub2e4","\ubbf8\ucc29\uc0c1\ud488\uc758 \uc18c\uc720\uad8c \uadc0\uc18d\uc740 \ud56d\uc0c1 \ud310\ub9e4\uc790\uc5d0\uac8c \uc788\ub2e4\uace0 \ubcf8\ub2e4"],t.s)
B.aox=s(["\uc120\uc801\uc9c0\uc778\ub3c4\uc870\uac74\uc5d0\uc11c\ub294 \uc0c1\ud488\uc774 \uc120\uc801\ub41c \uc2dc\uc810\uc5d0 \uc18c\uc720\uad8c\uc774 \ub9e4\uc785\uc790\uc5d0\uac8c \uc774\uc804\ub418\ubbc0\ub85c, \uc6b4\uc1a1 \uc911\uc774\ub354\ub77c\ub3c4 \ub9e4\uc785\uc790\uc758 \uc7ac\uace0\uc790\uc0b0\uc5d0 \ud3ec\ud568"],t.s)
