B.btf=new A.a("gen_ba_ppe_21","business_admin","\ud68c\uacc4","\uc720\ud615\uc790\uc0b0\uacfc \uac10\uac00\uc0c1\uac01","\uc720\ud615\uc790\uc0b0 \uac10\uac00\uc0c1\uac01\uc758 \ubaa9\uc801\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.Rl,0,"\uac10\uac00\uc0c1\uac01\uc740 \uc790\uc0b0\uc758 \uc2dc\uac00\ub97c \ud3c9\uac00\ud558\ub294 \uc808\ucc28\uac00 \uc544\ub2c8\ub77c, \uc720\ud615\uc790\uc0b0\uc758 \ucde8\ub4dd\uc6d0\uac00\ub97c \uadf8 \uc790\uc0b0\uc774 \uacbd\uc81c\uc801\ud6a8\uc775\uc744 \uc81c\uacf5\ud558\ub294 \uae30\uac04\uc778 \ub0b4\uc6a9\uc5f0\uc218\uc5d0 \uac78\uccd0 \uccb4\uacc4\uc801\uc774\uace0 \ud569\ub9ac\uc801\uc778 \ubc29\ubc95\uc73c\ub85c \ube44\uc6a9\uc73c\ub85c \ubc30\ubd84\ud558\ub294 \uc6d0\uac00\ubc30\ubd84 \uc808\ucc28\uc774\ub2e4.",B.aK6,B.aOQ,null)
B.aWD=s(["\uc77c\uad04 \ucde8\ub4dd\uac00\uc561\uc744 \ud1a0\uc9c0\uc640 \uac74\ubb3c \uac01\uac01\uc758 \uc0c1\ub300\uc801 \uacf5\uc815\uac00\uce58 \ube44\uc728\uc5d0 \ub530\ub77c \ubc30\ubd84\ud55c\ub2e4","\uc77c\uad04 \ucde8\ub4dd\uac00\uc561 \uc804\ubd80\ub97c \ud1a0\uc9c0\uc758 \ucde8\ub4dd\uc6d0\uac00\ub85c\ub9cc \uc778\uc2dd\ud55c\ub2e4","\uc77c\uad04 \ucde8\ub4dd\uac00\uc561 \uc804\ubd80\ub97c \uac74\ubb3c\uc758 \ucde8\ub4dd\uc6d0\uac00\ub85c\ub9cc \uc778\uc2dd\ud55c\ub2e4","\ud1a0\uc9c0\uc640 \uac74\ubb3c\uc744 \uc77c\uad04 \ucde8\ub4dd\ud55c \uacbd\uc6b0 \ud68c\uacc4\ucc98\ub9ac \ubc29\ubc95\uc5d0 \uad00\ud55c \ubcc4\ub3c4 \uaddc\uc815\uc740 \uc5c6\ub2e4"],t.s)
