B.bdi=s(["\uae30\uc5c5\ud615 VMS\ub294 \ud55c \ud68c\uc0ac\uac00 \uc720\ud1b5\uacbd\ub85c\uc758 \uc5ec\ub7ec \ub2e8\uacc4\ub97c \uc18c\uc720\xb7\uc6b4\uc601\ud55c\ub2e4","\uacc4\uc57d\ud615 VMS\ub294 \ub3c5\ub9bd\uc801\uc778 \uacbd\ub85c\uad6c\uc131\uc6d0\ub4e4\uc774 \uacc4\uc57d\uc744 \ud1b5\ud574 \ud1b5\ud569\ub41c \ud504\ub85c\uadf8\ub7a8\uc744 \uc6b4\uc601\ud558\uba70, \ud504\ub79c\ucc28\uc774\uc988 \uc2dc\uc2a4\ud15c\uc774 \ub300\ud45c\uc801\uc774\ub2e4","\uad00\ub9ac\ud615 VMS\ub294 \uc18c\uc720\uad8c\uc774\ub098 \uacc4\uc57d\uad00\uacc4 \uc5c6\uc774 \ud2b9\uc815 \uad6c\uc131\uc6d0\uc758 \uaddc\ubaa8\ub098 \ud798\uc5d0 \uc758\ud574 \uc870\uc815\uc774 \uc774\ub8e8\uc5b4\uc9c4\ub2e4","VMS\ub294 \uc804\ud1b5\uc801 \uc720\ud1b5\uacbd\ub85c\uc5d0 \ube44\ud574 \uacbd\ub85c\uad6c\uc131\uc6d0 \uac04\uc758 \uac08\ub4f1\uacfc \ube44\ud6a8\uc728\uc774 \ud56d\uc0c1 \ub354 \ud06c\uac8c \ub098\ud0c0\ub09c\ub2e4"],t.s)
B.aY5=s(["\ub3c5\ub9bd\uc801\uc778 \uacbd\ub85c\uad6c\uc131\uc6d0 \uac04\uc758 \uac08\ub4f1\uc774 \ud06c\uace0 \ube44\ud6a8\uc728\uc801\uc778 \uc804\ud1b5\uc801 \uc720\ud1b5\uacbd\ub85c\uc758 \ub2e8\uc810\uc744 \ubcf4\uc644\ud558\uae30 \uc704\ud574 \ub4f1\uc7a5\ud55c \ud615\ud0dc"],t.s)
B.aRB=s(["\uc218\uc9c1\uc801 \ub9c8\ucf00\ud305\uc2dc\uc2a4\ud15c(VMS)"],t.s)
B.bJg=new A.a("gen_ba_mkt_channel_2","business_admin","\ub9c8\ucf00\ud305","\uc720\ud1b5\uacbd\ub85c\uc640 \ucd09\uc9c4\uc804\ub7b5","\uc218\uc9c1\uc801 \ub9c8\ucf00\ud305\uc2dc\uc2a4\ud15c(vertical marketing system: VMS)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.bdi,3,'VMS\ub294 \uc0dd\uc0b0\uc790\xb7\ub3c4\ub9e4\uc0c1\xb7\uc18c\ub9e4\uc0c1\uc744 \ud558\ub098\uc758 \ud1b5\ud569\ub41c \uc2dc\uc2a4\ud15c\uc73c\ub85c \uc6b4\uc601\ud574 \uacbd\ub85c \uc804\uccb4\ub97c \uc804\ubb38\uc801\uc73c\ub85c \uad00\ub9ac\ud568\uc73c\ub85c\uc368, \uc624\ud788\ub824 \ub3c5\ub9bd\uc801\uc778 \uacbd\ub85c\uad6c\uc131\uc6d0 \uac04\uc758 \uac08\ub4f1\uc774 \ud06c\uace0 \ube44\ud6a8\uc728\uc801\uc778 \uc804\ud1b5\uc801 \uc720\ud1b5\uacbd\ub85c\uc758 \ub2e8\uc810\uc744 \ubcf4\uc644\ud558\uae30 \uc704\ud574 \ub4f1\uc7a5\ud55c \ud615\ud0dc\uc774\ub2e4. "\uac08\ub4f1\uacfc \ube44\ud6a8\uc728\uc774 \ud56d\uc0c1 \ub354 \ud06c\ub2e4"\ub294 \uc124\uba85\uc740 \uc633\uc9c0 \uc54a\ub2e4.',B.aY5,B.aRB,null)
B.bfH=s(["\ud478\uc2dc\uc804\ub7b5\uc740 \uc81c\uc870\uc5c5\uc790\uac00 \uc720\ud1b5\uc5c5\uc790\ub97c \ub300\uc0c1\uc73c\ub85c \uc778\uc801\ud310\ub9e4\xb7\ud310\ub9e4\ucd09\uc9c4\uc744 \uc9d1\uc911\ud558\ub294 \uc804\ub7b5\uc774\ub2e4","\ud480\uc804\ub7b5\uc740 \uad11\uace0 \ub4f1\uc744 \ud1b5\ud574 \ucd5c\uc885\uc18c\ube44\uc790\uc758 \uc218\uc694\ub97c \uc790\uadf9\ud574 \uc18c\ube44\uc790\uac00 \uc9c1\uc811 \uc720\ud1b5\uc5c5\uc790\uc5d0\uac8c \uc81c\ud488\uc744 \ucc3e\ub3c4\ub85d \uc720\ub3c4\ud558\ub294 \uc804\ub7b5\uc774\ub2e4","\ud478\uc2dc\uc804\ub7b5\uc740 \uc8fc\ub85c \ube0c\ub79c\ub4dc \ucda9\uc131\ub3c4\uac00 \ub0ae\uace0 \ub9e4\uc7a5 \ub0b4 \uad6c\ub9e4\uacb0\uc815\uc774 \ub9ce\uc740 \uc81c\ud488\uc5d0 \uc801\ud569\ud558\ub2e4","\ud480\uc804\ub7b5\uacfc \ud478\uc2dc\uc804\ub7b5\uc740 \ub3d9\uc2dc\uc5d0 \ud568\uaed8 \uc0ac\uc6a9\ud560 \uc218 \uc5c6\ub2e4"],t.s)
B.awV=s(["\uc18c\ube44\uc790 \ub300\uc0c1 \uad11\uace0(\ud480\uc804\ub7b5)\uc640 \uc720\ud1b5\uc5c5\uc790 \ub300\uc0c1 \ud310\ucd09(\ud478\uc2dc\uc804\ub7b5)\uc744 \ud568\uaed8 \ubcd1\ud589\ud558\ub294 \uac83\uc774 \uc77c\ubc18\uc801\uc774\uba70, \ub450 \uc804\ub7b5\uc740 \uc0c1\ud638 \ubc30\ud0c0\uc801\uc774\uc9c0 \uc54a\ub2e4"],t.s)
