B.bRq=new A.a("gen_ba_mkt_channel_18","business_admin","\ub9c8\ucf00\ud305","\uc720\ud1b5\uacbd\ub85c\uc640 \ucd09\uc9c4\uc804\ub7b5","\uc720\ud1b5\uc5c5\uc790(\uc911\uac04\uc0c1) \ud310\ucd09\uc218\ub2e8\uc5d0 \ud574\ub2f9\ud558\ub294 \uac83\uc740?",B.aPY,0,"\uc911\uac04\uc0c1 \uacf5\uc81c\ub294 \uc81c\uc870\uc5c5\uccb4\uac00 \uc720\ud1b5\uc5c5\uc790(\uc911\uac04\uc0c1)\uc5d0\uac8c \uc9c4\uc5f4\xb7\uad11\uace0 \ud611\uc870 \ub4f1\uc5d0 \ub300\ud55c \ub300\uac00\ub85c \uc81c\uacf5\ud558\ub294 \ub300\ud45c\uc801\uc778 \uc720\ud1b5\uc5c5\uc790 \ud310\ucd09\uc218\ub2e8\uc774\ub2e4. \ucfe0\ud3f0, \ub9ac\ubca0\uc774\ud2b8, \uc0d8\ud50c\uc740 \ubaa8\ub450 \ucd5c\uc885\uc18c\ube44\uc790\ub97c \ub300\uc0c1\uc73c\ub85c \ud558\ub294 \uc18c\ube44\uc790 \ud310\ucd09\uc218\ub2e8\uc774\ub2e4.",B.aRE,B.aTb,null)
