B.bwE=new A.a("gen_trap_cl_1","civil_law","\ud568\uc815 \ud53c\ud558\uae30",null,"\u7532\uc774 \u4e59\uc5d0\uac8c \uc0ac\uae30\ub97c \ub2f9\ud574 \ubd80\ub3d9\uc0b0\uc744 \ub9e4\ub3c4\ud55c \ud6c4, \u4e59\uc774 \uc774\ub97c \uc120\uc758\uc758 \u4e19\uc5d0\uac8c \uc804\ub9e4\ud558\uc5ec \ub4f1\uae30\uae4c\uc9c0 \ub9c8\uccd0\uc900 \uacbd\uc6b0\uc640, \u7532\uacfc \u4e59\uc758 \uacc4\uc57d\uc774 \ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\uc600\ub358 \uacbd\uc6b0\ub97c \ube44\uad50\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aBZ,0,'\uc0ac\uae30\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\uc758 \ucde8\uc18c(\uc81c110\uc870)\uc640 \ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\uc758 \ubb34\ud6a8(\uc81c108\uc870)\ub294 \uc131\ub9bd \uadfc\uac70\ub294 \ub2e4\ub974\uc9c0\ub9cc, \ub458 \ub2e4 "\uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c \ub300\ud56d\ud558\uc9c0 \ubabb\ud55c\ub2e4"\ub294 \uacb0\ub860\uc774 \ub3d9\uc77c\ud558\ub2e4. \uc774 \uacf5\ud1b5\uc810\uc740 \uc758\uc0ac\ud45c\uc2dc \ud760\uacb0 \uc720\ud615(\ube44\uc9c4\uc758\ud45c\uc2dc\xb7\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\xb7\ucc29\uc624\xb7\uc0ac\uae30\uac15\ubc15) \uc804\uccb4\ub97c \uad00\ud1b5\ud558\ub294 \ud575\uc2ec \ud3ec\uc778\ud2b8\ub2e4.',B.aYR,B.aSZ,null)
B.aKf=s([u.in,"\uc774\ud589\uc9c0\uccb4\uc640 \uc774\ud589\ubd88\ub2a5 \ubaa8\ub450 \ucd5c\uace0 \uc5c6\uc774 \ud574\uc81c\ud560 \uc218 \uc5c6\ub2e4","\uc774\ud589\ubd88\ub2a5\uc774 \ub418\uba74 \ud574\uc81c\uac00 \uc544\ub2c8\ub77c \ubc18\ub4dc\uc2dc \uc190\ud574\ubc30\uc0c1\ub9cc \uccad\uad6c\ud560 \uc218 \uc788\ub2e4","\uc774\ud589\uc9c0\uccb4\ub294 \ucd5c\uace0 \uc5c6\uc774, \uc774\ud589\ubd88\ub2a5\uc740 \ucd5c\uace0 \ud6c4\uc5d0\ub9cc \ud574\uc81c\ud560 \uc218 \uc788\ub2e4"],t.s)
