B.bRK=new A.a("gen_trap_cl_2","civil_law","\ud568\uc815 \ud53c\ud558\uae30",null,"\ub9e4\ub9e4\uacc4\uc57d\uc758 \ub9e4\ub3c4\uc778\uc774 \uc774\ud589\uc9c0\uccb4\uc5d0 \ube60\uc9c4 \uacbd\uc6b0\uc640 \uc774\ud589\ubd88\ub2a5\uc5d0 \ube60\uc9c4 \uacbd\uc6b0, \ub9e4\uc218\uc778\uc774 \uacc4\uc57d\uc744 \ud574\uc81c\ud558\uae30 \uc704\ud55c \uc808\ucc28\ub97c \ube44\uad50\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aKf,0,"\uc774\ud589\uc9c0\uccb4\ub85c \uc778\ud55c \ud574\uc81c(\uc81c544\uc870)\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \uc0c1\ub2f9\uae30\uac04\uc744 \uc815\ud55c \ucd5c\uace0\uac00 \ud544\uc694\ud558\uc9c0\ub9cc, \uc774\ud589\ubd88\ub2a5(\uc81c546\uc870)\uc740 \uc774\ud589 \uc790\uccb4\uac00 \ubd88\uac00\ub2a5\ud574 \ucd5c\uace0\ub97c \ud558\ub294 \uac83\uc774 \ubb34\uc758\ubbf8\ud558\ubbc0\ub85c \ucd5c\uace0 \uc5c6\uc774 \uc989\uc2dc \ud574\uc81c\ud560 \uc218 \uc788\ub2e4\ub294 \uac83\uc774 \uacc4\uc57d\ucd1d\ub860\uc758 \ud575\uc2ec \ub300\ube44 \ud3ec\uc778\ud2b8\ub2e4.",B.aJP,B.aAZ,null)
B.b8o=s(["\u4e19\uc740 \u7532\uc5d0\uac8c \uc0c1\ub2f9\ud55c \uae30\uac04\uc744 \uc815\ud558\uc5ec \ucd94\uc778 \uc5ec\ubd80\uc758 \ud655\ub2f5\uc744 \ucd5c\uace0\ud560 \uc218 \uc788\ub2e4","\u4e19\uc740 \u7532\uc758 \ucd94\uc778\uc774 \uc788\uae30 \uc804\uae4c\uc9c0 \uacc4\uc57d\uc744 \ucca0\ud68c\ud560 \uc218 \uc788\ub2e4","\u4e19\uc740 \ub300\ub9ac\uad8c \uc5c6\uc74c\uc744 \uc54c\uc558\uc73c\ubbc0\ub85c \ucca0\ud68c\uad8c\uc744 \ud589\uc0ac\ud560 \uc218 \uc5c6\ub2e4","\u7532\uc774 \ucd94\uc778\uc744 \uac70\uc808\ud558\uba74 \uacc4\uc57d\uc740 \ud655\uc815\uc801\uc73c\ub85c \ubb34\ud6a8\uac00 \ub41c\ub2e4"],t.s)
B.XA=s(['\ucca0\ud68c\uad8c\uc740 \uacc4\uc57d \ub2f9\uc2dc \ub300\ub9ac\uad8c \uc5c6\uc74c\uc744 \uc54c\uc9c0 \ubabb\ud55c "\uc120\uc758"\uc758 \uc0c1\ub300\ubc29\uc5d0\uac8c\ub9cc \uc778\uc815'],t.s)
B.aDK=s(["\ubb34\uad8c\ub300\ub9ac \uc0c1\ub300\ubc29\uc758 \ucd5c\uace0\uad8c\uacfc \ucca0\ud68c\uad8c \uc694\uac74 \ucc28\uc774"],t.s)
B.by3=new A.a("gen_trap_cl_3","civil_law","\ud568\uc815 \ud53c\ud558\uae30",null,"\ubb34\uad8c\ub300\ub9ac\uc778 \u4e59\uc774 \ubcf8\uc778 \u7532\uc758 \uc774\ub984\uc73c\ub85c \u4e19\uacfc \uacc4\uc57d\uc744 \uccb4\uacb0\ud588\ub294\ub370, \u7532\uc774 \uc774\ub97c \ucd94\uc778\ud558\uc9c0 \uc54a\uace0 \uc788\ub294 \uc0c1\ud0dc\uc5d0\uc11c \u4e19\uc774 \uacc4\uc57d \ub2f9\uc2dc \u4e59\uc5d0\uac8c \ub300\ub9ac\uad8c\uc774 \uc5c6\ub2e4\ub294 \uc0ac\uc2e4\uc744 \ubab0\ub790\ub2e4\uba74, \u4e19\uc774 \ucde8\ud560 \uc218 \uc788\ub294 \uc870\uce58\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.b8o,2,'\ubb34\uad8c\ub300\ub9ac\uc758 \uc0c1\ub300\ubc29 \ubcf4\ud638 \uc911 \ucd5c\uace0\uad8c\uc740 \uc0c1\ub300\ubc29\uc758 \uc120\uc758\xb7\uc545\uc758\ub97c \ubd88\ubb38\ud558\uace0 \uc778\uc815\ub418\uc9c0\ub9cc, \ucca0\ud68c\uad8c\uc740 \uacc4\uc57d \ub2f9\uc2dc \ub300\ub9ac\uad8c \uc5c6\uc74c\uc744 \uc54c\uc9c0 \ubabb\ud55c "\uc120\uc758"\uc758 \uc0c1\ub300\ubc29\uc5d0\uac8c\ub9cc \uc778\uc815\ub41c\ub2e4. \ubb38\uc81c\uc5d0\uc11c \u4e19\uc740 \ub300\ub9ac\uad8c \uc5c6\uc74c\uc744 \ubab0\ub790\ub358 \uc120\uc758\uc758 \uc0c1\ub300\ubc29\uc774\ubbc0\ub85c \ucca0\ud68c\uad8c\uc744 \ud589\uc0ac\ud560 \uc218 \uc788\uc5b4, "\ud589\uc0ac\ud560 \uc218 \uc5c6\ub2e4"\ub294 \uc124\uba85\uc774 \uc633\uc9c0 \uc54a\ub2e4.',B.XA,B.aDK,null)
B.aAP=s(["\uc720\uce58\uad8c\uc740 \ub4f1\uae30 \uc5c6\uc774 \uc810\uc720\ub9cc\uc73c\ub85c \uc131\ub9bd\ud558\uc9c0\ub9cc, \uc800\ub2f9\uad8c\uc740 \ub4f1\uae30\uac00 \uc788\uc5b4\uc57c \uc131\ub9bd\ud55c\ub2e4","\uc720\uce58\uad8c\uc740 \ubc95\uc815\ub2f4\ubcf4\ubb3c\uad8c, \uc800\ub2f9\uad8c\uc740 \uc6d0\uce59\uc801\uc73c\ub85c \uc57d\uc815\ub2f4\ubcf4\ubb3c\uad8c\uc774\ub2e4","\uc720\uce58\uad8c\uacfc \uc800\ub2f9\uad8c \ubaa8\ub450 \ubaa9\uc801\ubb3c\uc5d0 \ub300\ud574 \uc6b0\uc120\ubcc0\uc81c\uad8c\uc744 \uc9c1\uc811 \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4\ub294 \uc810\uc5d0\uc11c \ub3d9\uc77c\ud558\ub2e4","\uc720\uce58\uad8c\uc740 \ucc44\uad8c\uacfc \ubaa9\uc801\ubb3c \uc0ac\uc774\uc758 \uacac\ub828\uad00\uacc4\ub97c \uc694\uac74\uc73c\ub85c \ud558\uc9c0\ub9cc, \uc800\ub2f9\uad8c\uc740 \uadf8\ub7ec\ud55c \uacac\ub828\uad00\uacc4\ub97c \uc694\uac74\uc73c\ub85c \ud558\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.a8i=s(["\uc800\ub2f9\uad8c\uc740 \uc6b0\uc120\ubcc0\uc81c\uad8c\uc744 \uac00\uc9c0\ub294 \ub2f4\ubcf4\ubb3c\uad8c\uc774\uc9c0\ub9cc, \uc720\uce58\uad8c\uc740 \uc6b0\uc120\ubcc0\uc81c\uad8c\uc774 \uc5c6\uace0"],t.s)
B.aQ4=s(["\uc720\uce58\uad8c\uacfc \uc800\ub2f9\uad8c\uc758 \uc6b0\uc120\ubcc0\uc81c\uad8c \uc720\ubb34 \ucc28\uc774"],t.s)
B.bRP=new A.a("gen_trap_cl_4","civil_law","\ud568\uc815 \ud53c\ud558\uae30",null,"\uc720\uce58\uad8c\uacfc \uc800\ub2f9\uad8c\uc744 \ube44\uad50\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aAP,2,'\uc800\ub2f9\uad8c\uc740 \uc6b0\uc120\ubcc0\uc81c\uad8c\uc744 \uac00\uc9c0\ub294 \ub2f4\ubcf4\ubb3c\uad8c\uc774\uc9c0\ub9cc, \uc720\uce58\uad8c\uc740 \uc6b0\uc120\ubcc0\uc81c\uad8c\uc774 \uc5c6\uace0 \ubaa9\uc801\ubb3c\uc744 \uc720\uce58(\uc810\uc720)\ud568\uc73c\ub85c\uc368 \uc0ac\uc2e4\uc0c1 \ubcc0\uc81c\ub97c \uac15\uc81c\ud558\ub294 \ud6a8\uacfc\ub9cc \uac00\uc9c4\ub2e4\ub294 \uc810\uc5d0\uc11c \uacb0\uc815\uc801\uc73c\ub85c \ub2e4\ub974\ub2e4. \ub530\ub77c\uc11c "\ub458 \ub2e4 \uc6b0\uc120\ubcc0\uc81c\uad8c\uc744 \uc9c1\uc811 \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4"\ub294 \uc124\uba85\uc740 \uc633\uc9c0 \uc54a\ub2e4.',B.a8i,B.aQ4,null)
B.Zb=s(["\uc644\uc131 \uc804 \uc2b9\uc778\uc740 \uc2dc\ud6a8\ub97c \uc911\ub2e8\uc2dc\ucf1c \uadf8\ub54c\ubd80\ud130 \uc0c8\ub85c \uc9c4\ud589\uc2dc\ud0a4\uace0, \uc644\uc131 \ud6c4 \ud3ec\uae30\ub294 \uc774\ubbf8 \uc644\uc131\ub41c \uc2dc\ud6a8\uc758 \ud6a8\ub825\uc744 \uc8fc\uc7a5\ud558\uc9c0 \uc54a\uaca0\ub2e4\ub294 \uc758\uc0ac\ud45c\uc2dc\ub77c\ub294 \uc810\uc5d0\uc11c \uc2dc\uc810\uacfc \ubc95\uc801 \uc131\uaca9\uc774 \ub2e4\ub974\ub2e4","\ub450 \uacbd\uc6b0 \ubaa8\ub450 \uc644\uc131 \uc804 \ubbf8\ub9ac \ud558\ub294 \ud3ec\uae30\uc640 \ub3d9\uc77c\ud55c \ud6a8\ub825\uc744 \uac00\uc9c4\ub2e4","\uc644\uc131 \uc804 \uc2b9\uc778\uc740 \ubb34\ud6a8\uc774\uace0, \uc644\uc131 \ud6c4 \ud3ec\uae30\ub9cc \uc720\ud6a8\ud558\ub2e4","\uc644\uc131 \uc804 \uc2b9\uc778\uacfc \uc644\uc131 \ud6c4 \ud3ec\uae30\ub294 \ubc95\uc801 \ud6a8\uacfc\uac00 \uc644\uc804\ud788 \ub3d9\uc77c\ud574 \uad6c\ubcc4\ud560 \uc2e4\uc775\uc774 \uc5c6\ub2e4"],t.s)
B.axJ=s(["\uc644\uc131 \uc804 \uc2b9\uc778\uc740 \uc2dc\ud6a8\ub97c \uc911\ub2e8\uc2dc\ucf1c \uadf8\ub54c\ubd80\ud130 \uc0c8\ub85c \uc9c4\ud589\uc2dc\ud0a4\uace0, \uc644\uc131 \ud6c4 \ud3ec\uae30\ub294 \uc774\ubbf8 \uc644\uc131\ub41c \uc2dc\ud6a8\uc758 \ud6a8\ub825\uc744 \uc8fc\uc7a5\ud558\uc9c0 \uc54a\uaca0\ub2e4\ub294 \uc758\uc0ac\ud45c\uc2dc"],t.s)
B.aOY=s(["\uc2dc\ud6a8 \uc911\ub2e8(\uc2b9\uc778)\uacfc \uc2dc\ud6a8\uc774\uc775 \ud3ec\uae30\uc758 \uad6c\ubcc4"],t.s)
B.bxs=new A.a("gen_trap_cl_5","civil_law","\ud568\uc815 \ud53c\ud558\uae30",null,"\uc18c\uba78\uc2dc\ud6a8 \uc644\uc131 \uc804 \ucc44\ubb34\uc790\uac00 \ucc44\ubb34\ub97c \uc2b9\uc778\ud55c \uacbd\uc6b0\uc640, \uc18c\uba78\uc2dc\ud6a8 \uc644\uc131 \ud6c4 \ucc44\ubb34\uc790\uac00 \uc2dc\ud6a8\uc774\uc775\uc744 \ud3ec\uae30\ud55c \uacbd\uc6b0\uc758 \ud6a8\uacfc\ub97c \ube44\uad50\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.Zb,0,"\uc644\uc131 \uc804 \uc2b9\uc778\uc740 \uc2dc\ud6a8\uc758 \uc911\ub2e8\uc0ac\uc720\ub85c\uc11c \uadf8\ub54c\uae4c\uc9c0 \uc9c4\ud589\ub41c \uc2dc\ud6a8\uae30\uac04\uc744 \uc18c\uba78\uc2dc\ud0a4\uace0 \uc0c8\ub85c \uc9c4\ud589\uc2dc\ud0a4\ub294 \ud6a8\uacfc\uac00 \uc788\ub294 \ubc18\uba74, \uc644\uc131 \ud6c4 \ud3ec\uae30\ub294 \uc774\ubbf8 \uc644\uc131\ub418\uc5b4 \ud655\uc815\uc801\uc73c\ub85c \ubc1c\uc0dd\ud55c \uc2dc\ud6a8\uc774\uc775\uc744 \uc0ac\ud6c4\uc801\uc73c\ub85c \ud3ec\uae30\ud558\ub294 \uc758\uc0ac\ud45c\uc2dc\ub77c\ub294 \uc810\uc5d0\uc11c \ubc1c\uc0dd \uc2dc\uc810\uacfc \ubc95\uc801 \uc131\uaca9\uc774 \ub2e4\ub974\ub2e4. \uc644\uc131 \uc804\uc5d0 \ubbf8\ub9ac \ud558\ub294 \ud3ec\uae30 \uc57d\uc815(\uc81c184\uc870)\uc740 \uc774 \ub458\uacfc \ub2ec\ub9ac \uc544\uc608 \ubb34\ud6a8\ub77c\ub294 \uc810\ub3c4 \ud568\uaed8 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4.",B.axJ,B.aOY,null)
B.ayk=s(["\uc784\ub300\ucc28 \ud574\uc9c0\ub294 \uc7a5\ub798\ud6a8\ub9cc \uc788\uc5b4 \uc774\ubbf8 \uacbd\uacfc\ud55c \uc0ac\uc6a9\uad00\uacc4\ub294 \uc720\ud6a8\ud558\uac8c \uc720\uc9c0\ub418\uc9c0\ub9cc, \ub9e4\ub9e4 \ud574\uc81c\ub294 \uc18c\uae09\ud6a8\uac00 \uc788\uc5b4 \uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\uac00 \ubc1c\uc0dd\ud55c\ub2e4\ub294 \uc810\uc5d0\uc11c \ud6a8\uacfc\uac00 \ub2e4\ub974\ub2e4","\ub450 \uacbd\uc6b0 \ubaa8\ub450 \uc18c\uae09\ud6a8\uac00 \uc788\uc5b4 \uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\uac00 \ubc1c\uc0dd\ud55c\ub2e4","\uc784\ub300\ucc28 \ud574\uc9c0\ub294 \ucd5c\uace0 \uc5c6\uc774 \ubd88\uac00\ub2a5\ud558\uace0, \ub9e4\ub9e4 \ud574\uc81c\ub294 \ucd5c\uace0 \uc5c6\uc774 \uac00\ub2a5\ud558\ub2e4","\uc784\ub300\ucc28 \ud574\uc9c0\uc640 \ub9e4\ub9e4 \ud574\uc81c\ub294 \uacc4\uc18d\uc801 \uacc4\uc57d\uc774\ub77c\ub294 \uacf5\ud1b5\uc810 \ub54c\ubb38\uc5d0 \ubc95\uc801 \ud6a8\uacfc\uac00 \ub3d9\uc77c\ud558\ub2e4"],t.s)
B.a7L=s(["\uc784\ub300\ucc28 \ud574\uc9c0\ub294 \uc7a5\ub798\ud6a8\ub9cc \uc788\uc5b4 \uc774\ubbf8 \uacbd\uacfc\ud55c \uc0ac\uc6a9\uad00\uacc4\ub294 \uc720\ud6a8\ud558\uac8c \uc720\uc9c0\ub418\uc9c0\ub9cc, \ub9e4\ub9e4 \ud574\uc81c\ub294 \uc18c\uae09\ud6a8\uac00 \uc788\uc5b4 \uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\uac00 \ubc1c\uc0dd"],t.s)
B.aME=s(["\ud574\uc9c0(\uc7a5\ub798\ud6a8)\uc640 \ud574\uc81c(\uc18c\uae09\ud6a8)\uc758 \ud6a8\uacfc \ucc28\uc774 \uc751\uc6a9"],t.s)
B.bG2=new A.a("gen_trap_cl_6","civil_law","\ud568\uc815 \ud53c\ud558\uae30",null,"\uc784\ub300\ucc28\uacc4\uc57d\uc5d0\uc11c \uc784\ucc28\uc778\uc758 \ucc28\uc784\uc5f0\uccb4\uac00 2\uae30\uc5d0 \ub2ec\ud574 \uc784\ub300\uc778\uc774 \ud574\uc9c0\uad8c\uc744 \ud589\uc0ac\ud558\ub294 \uacbd\uc6b0\uc640, \ub9e4\ub9e4\uacc4\uc57d\uc5d0\uc11c \ub9e4\uc218\uc778\uc758 \ub300\uae08\uc9c0\uae09 \uc9c0\uccb4\ub85c \ub9e4\ub3c4\uc778\uc774 \ud574\uc81c\uad8c\uc744 \ud589\uc0ac\ud558\ub294 \uacbd\uc6b0\ub97c \ube44\uad50\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.ayk,0,"\uc784\ub300\ucc28\uc640 \uac19\uc740 \uacc4\uc18d\uc801 \uacc4\uc57d\uc758 \ud574\uc9c0\ub294 \uc7a5\ub798\ub97c \ud5a5\ud574\uc11c\ub9cc \ud6a8\ub825\uc774 \ubc1c\uc0dd\ud574 \uc774\ubbf8 \uc774\ud589\ub41c \ubd80\ubd84(\uacbd\uacfc\ud55c \uc0ac\uc6a9\uad00\uacc4)\uc740 \uadf8\ub300\ub85c \uc720\ud6a8\ud558\uac8c \uc720\uc9c0\ub418\uc9c0\ub9cc, \ub9e4\ub9e4\uc640 \uac19\uc740 \uc77c\ud68c\uc801 \uacc4\uc57d\uc758 \ud574\uc81c\ub294 \uc18c\uae09\ud6a8\uac00 \uc788\uc5b4 \uac01 \ub2f9\uc0ac\uc790\uc5d0\uac8c \uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\uac00 \ubc1c\uc0dd\ud55c\ub2e4\ub294 \uc810\uc774 \ud574\uc81c\xb7\ud574\uc9c0 \uad6c\ubcc4\uc758 \ud575\uc2ec\uc774\ub2e4.",B.a7L,B.aME,null)
B.a5e=s(["\ub450 \uacbd\uc6b0 \ubaa8\ub450 \ubb34\ud6a8\uc774\uba70, \ubb34\ud6a8\ud589\uc704\uc758 \ucd94\uc778\uc73c\ub85c \uc720\ud6a8\ud558\uac8c \uc804\ud658\ub420 \uc218 \uc788\ub2e4","\uc81c103\uc870\ub294 \ubc95\ub960\ud589\uc704\uc758 \ub0b4\uc6a9\xb7\ub3d9\uae30\xb7\uc870\uac74 \ub4f1\uc774 \uc0ac\ud68c\uc9c8\uc11c\uc5d0 \ubc18\ud558\ub294 \uacbd\uc6b0\ub97c \uaddc\uc728\ud55c\ub2e4","\uc81c104\uc870\ub294 \uad81\ubc15\xb7\uacbd\uc194\xb7\ubb34\uacbd\ud5d8\uc744 \uc774\uc6a9\ud55c \ud604\uc800\ud788 \ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704\ub97c \uaddc\uc728\ud55c\ub2e4","\ub450 \uacbd\uc6b0 \ubaa8\ub450 \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c\ub3c4 \ub300\ud56d\ud560 \uc218 \uc788\ub294 \uc808\ub300\uc801 \ubb34\ud6a8\uc774\ub2e4"],t.s)
B.aDN=s(["\uac15\ud589\uaddc\uc815 \uc704\ubc18\uc5d0 \ud574\ub2f9\ud574 \ubb34\ud6a8\uc774\uba70, \uc774\ub7ec\ud55c \ubb34\ud6a8\ub294 \ucd94\uc778\ud558\ub354\ub77c\ub3c4 \uc720\ud6a8\ub85c \uc804\ud658\ub418\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.aMO=s(["\uc81c103\uc870\xb7\uc81c104\uc870 \ubb34\ud6a8\uc758 \ucd94\uc778 \ubd88\uac00 \uacf5\ud1b5\uc810"],t.s)
B.bHX=new A.a("gen_trap_cl_7","civil_law","\ud568\uc815 \ud53c\ud558\uae30",null,"\ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704(\uc81c103\uc870)\uc640 \ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704(\uc81c104\uc870)\ub97c \ube44\uad50\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.a5e,0,'\ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704\uc640 \ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704\ub294 \ubaa8\ub450 \uac15\ud589\uaddc\uc815 \uc704\ubc18\uc5d0 \ud574\ub2f9\ud574 \ubb34\ud6a8\uc774\uba70, \uc774\ub7ec\ud55c \ubb34\ud6a8\ub294 \ucd94\uc778\ud558\ub354\ub77c\ub3c4 \uc720\ud6a8\ub85c \uc804\ud658\ub418\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc810\uc774 \uacf5\ud1b5\uc801\uc774\ub2e4. \ub530\ub77c\uc11c "\ubb34\ud6a8\ud589\uc704\uc758 \ucd94\uc778\uc73c\ub85c \uc720\ud6a8\ud558\uac8c \uc804\ud658\ub420 \uc218 \uc788\ub2e4"\ub294 \uc124\uba85\uc740 \uc633\uc9c0 \uc54a\ub2e4.',B.aDN,B.aMO,null)
B.Ya=s([u.d6,"\uc9c0\uc0c1\uad8c\uacfc \uc784\ucc28\uad8c \ubaa8\ub450 \ubb3c\uad8c\uc774\ubbc0\ub85c \ubc95\uc801 \ud6a8\ub825\uc774 \ub3d9\uc77c\ud558\ub2e4","\uc9c0\uc0c1\uad8c\uc740 \uc9c0\ub8cc \uc57d\uc815\uc774 \ubc18\ub4dc\uc2dc \uc788\uc5b4\uc57c \uc131\ub9bd\ud558\ub294 \ubc18\uba74, \uc784\ucc28\uad8c\uc740 \ucc28\uc784 \uc57d\uc815\uc774 \uc5c6\uc5b4\ub3c4 \uc131\ub9bd\ud55c\ub2e4","\uc784\ucc28\uad8c\uc740 \ucd5c\ub2e8\uc874\uc18d\uae30\uac04\uc774 \ubc95\uc815\ub418\uc5b4 \uc788\uc73c\ub098 \uc9c0\uc0c1\uad8c\uc5d0\ub294 \ucd5c\ub2e8\uc874\uc18d\uae30\uac04 \uaddc\uc815\uc774 \uc5c6\ub2e4"],t.s)
B.b7j=s([u.d6],t.s)
B.atc=s(["\uc9c0\uc0c1\uad8c(\ubb3c\uad8c)\uacfc \uc784\ucc28\uad8c(\ucc44\uad8c)\uc758 \ub300\ud56d\ub825 \ucc28\uc774"],t.s)
B.bHs=new A.a("gen_trap_cl_8","civil_law","\ud568\uc815 \ud53c\ud558\uae30",null,"\uc9c0\uc0c1\uad8c\uacfc \uc784\ucc28\uad8c\uc744 \ube44\uad50\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.Ya,0,"\uc9c0\uc0c1\uad8c\uc740 \ubb3c\uad8c\uc73c\ub85c\uc11c \ub4f1\uae30\ub97c \ub9c8\uce58\uba74 \uadf8 \uc790\uccb4\ub85c \uc81c3\uc790\uc5d0\uac8c \ub300\ud56d\ud560 \uc218 \uc788\ub294 \ubc18\uba74, \uc784\ucc28\uad8c\uc740 \uc6d0\uce59\uc801\uc73c\ub85c \ucc44\uad8c\uc774\uc5b4\uc11c \ub4f1\uae30(\ub610\ub294 \ubcc4\ub3c4\uc758 \ub300\ud56d\ub825 \ucde8\ub4dd \uc694\uac74)\uac00 \uc5c6\uc73c\uba74 \uc81c3\uc790\uc5d0\uac8c \ub300\ud56d\ud560 \uc218 \uc5c6\ub2e4\ub294 \uc810\uc774 \ub450 \uad8c\ub9ac\uc758 \uadfc\ubcf8\uc801 \ucc28\uc774\uc774\ub2e4. \uc9c0\ub8cc\ub294 \uc9c0\uc0c1\uad8c\uc758 \uc131\ub9bd\uc694\uc18c\uac00 \uc544\ub2c8\ub77c\ub294 \uc810, \ucd5c\ub2e8\uc874\uc18d\uae30\uac04\uc740 \uc624\ud788\ub824 \uc9c0\uc0c1\uad8c\uc5d0 \ubc95\uc815\ub418\uc5b4 \uc788\ub2e4\ub294 \uc810\ub3c4 \ud568\uaed8 \uc720\uc758\ud574\uc57c \ud55c\ub2e4.",B.b7j,B.atc,null)
B.be9=s(["\ub3c4\uae09\uc758 \uc644\uc131\ubb3c \uc778\ub3c4\uc640 \ubcf4\uc218\uc9c0\uae09\uc740 \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uc5d0 \uc788\uace0, \uc218\uae09\uc778\uc758 \ud558\uc790\ub2f4\ubcf4\ucc45\uc784\uc5d0 \ub530\ub978 \ud558\uc790\ubcf4\uc218\xb7\uc190\ud574\ubc30\uc0c1\xb7\ud574\uc81c(\uac74\ubb3c \ub4f1\uc740 \ud574\uc81c \uc81c\ud55c)\ub3c4 \ub9e4\ub9e4\uc758 \ub2f4\ubcf4\ucc45\uc784\uacfc \uc720\uc0ac\ud55c \uad6c\uc870\ub85c \uaddc\uc728\ub41c\ub2e4","\ub3c4\uae09\uacc4\uc57d\uc5d0\ub294 \ub2f4\ubcf4\ucc45\uc784 \uaddc\uc815\uc774 \uc804\ud600 \uc5c6\ub2e4","\ub9e4\ub9e4\uc758 \ub2f4\ubcf4\ucc45\uc784\uc740 \ub9e4\ub3c4\uc778\uc758 \uace0\uc758\xb7\uacfc\uc2e4\uc774 \uc788\uc5b4\uc57c\ub9cc \uc778\uc815\ub41c\ub2e4",u.zW],t.s)
B.a3P=s([u.zW],t.s)
B.a2f=s(["\ub3c4\uae09 \ub2f4\ubcf4\ucc45\uc784\uacfc \ub9e4\ub9e4 \ub2f4\ubcf4\ucc45\uc784\uc758 \uad6c\uc870\uc801 \uc720\uc0ac\uc131 \ubc0f \uac74\ubb3c \ud574\uc81c \uc81c\ud55c \uc608\uc678"],t.s)
B.bC0=new A.a("gen_trap_cl_9","civil_law","\ud568\uc815 \ud53c\ud558\uae30",null,"\ub3c4\uae09\uacc4\uc57d\uc5d0\uc11c \uc218\uae09\uc778\uc758 \ud558\uc790\ub2f4\ubcf4\ucc45\uc784\uacfc, \ub9e4\ub9e4\uacc4\uc57d\uc5d0\uc11c \ub9e4\ub3c4\uc778\uc758 \ud558\uc790\ub2f4\ubcf4\ucc45\uc784\uc744 \ube44\uad50\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.be9,0,'\ub3c4\uae09\uacfc \ub9e4\ub9e4 \ubaa8\ub450 \uae09\ubd80\ubaa9\uc801\ubb3c\uc5d0 \ud558\uc790\uac00 \uc788\ub294 \uacbd\uc6b0 \ub2f4\ubcf4\ucc45\uc784(\ud558\uc790\ubcf4\uc218\xb7\uc190\ud574\ubc30\uc0c1\xb7\ud574\uc81c \ub4f1)\uc744 \uc778\uc815\ud558\ub294 \uc720\uc0ac\ud55c \uad6c\uc870\ub97c \uac00\uc9c0\uace0 \uc788\uc73c\ub098, \ub3c4\uae09\uc5d0\uc11c \uc644\uc131\ub41c \ubaa9\uc801\ubb3c\uc774 "\uac74\ubb3c \uae30\ud0c0 \ud1a0\uc9c0\uc758 \uacf5\uc791\ubb3c"\uc778 \uacbd\uc6b0\uc5d0\ub294 \uc0ac\ud68c\uacbd\uc81c\uc801 \uc190\uc2e4\uc744 \uace0\ub824\ud574 \ud558\uc790\ub97c \uc774\uc720\ub85c \ud55c \uacc4\uc57d\ud574\uc81c\uac00 \uc81c\ud55c\ub41c\ub2e4\ub294 \ud2b9\uce59\uc774 \uc788\ub2e4\ub294 \uc810\uc774 \uc911\uc694\ud55c \uc608\uc678\uc774\ub2e4.',B.a3P,B.a2f,null)
B.bfi=s([u.dn,"\ub9e4\uc218\uc778\uc740 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ub9e4\ub3c4\uc778\uc758 \uccad\uad6c\uc5d0 \uc751\ud574 \uba3c\uc800 \ub300\uae08\uc744 \uc9c0\uae09\ud574\uc57c \ud55c\ub2e4","\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc740 \ub9e4\ub3c4\uc778\uc5d0\uac8c\ub9cc \uc778\uc815\ub418\uace0 \ub9e4\uc218\uc778\uc5d0\uac8c\ub294 \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4","\ub9e4\uc218\uc778\uc774 \uc774\ud589\uc744 \uac70\uc808\ud558\uba74 \uc989\uc2dc \ub9e4\ub3c4\uc778\uc774 \uacc4\uc57d\uc744 \ud574\uc81c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.au4=s([u.dn],t.s)
B.bgw=s(["\ub9e4\ub9e4(\uc804\ud615\uacc4\uc57d)\uc640 \ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c(\uacc4\uc57d\ucd1d\ub860)\uc758 \uacb0\ud569 \uc801\uc6a9"],t.s)
B.bAY=new A.a("gen_trap_cl_10","civil_law","\ud568\uc815 \ud53c\ud558\uae30",null,"\uc804\ud615\uacc4\uc57d \uac01\ub860\uacfc \uacc4\uc57d\ucd1d\ub860\uc744 \ud568\uaed8 \uc751\uc6a9\ud55c \uc0ac\ub840 \u2014 \ub9e4\ub9e4\uacc4\uc57d\uc5d0\uc11c \ub9e4\ub3c4\uc778\uc774 \uc774\ud589\uc744 \uc81c\uacf5\ud558\uc9c0 \uc54a\uc740 \ucc44 \ub300\uae08\uc9c0\uae09\uc744 \uccad\uad6c\ud558\uc790 \ub9e4\uc218\uc778\uc774 \uc774\ud589\uc744 \uac70\uc808\ud55c \uacbd\uc6b0\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.bfi,0,"\ub9e4\ub9e4\uc640 \uac19\uc740 \uc30d\ubb34\uacc4\uc57d\uc5d0\uc11c\ub294 \ub300\uae08\uc9c0\uae09\uc758\ubb34\uc640 \ubaa9\uc801\ubb3c \uc774\uc804\uc758\ubb34\uac00 \ub300\uac00\uad00\uacc4\uc5d0 \uc788\uc73c\ubbc0\ub85c, \ub9e4\ub3c4\uc778\uc774 \uc790\uc2e0\uc758 \ucc44\ubb34\uc774\ud589\uc744 \uc81c\uacf5\ud558\uc9c0 \uc54a\uc740 \ucc44 \ub300\uae08\uc9c0\uae09\ub9cc \uccad\uad6c\ud558\uba74 \ub9e4\uc218\uc778\uc740 \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc744 \ud589\uc0ac\ud574 \uc774\ud589\uc744 \uac70\uc808\ud560 \uc218 \uc788\uace0, \uc774 \uacbd\uc6b0 \ub9e4\uc218\uc778\uc5d0\uac8c\ub294 \uc774\ud589\uc9c0\uccb4\ucc45\uc784\uc774 \ubc1c\uc0dd\ud558\uc9c0 \uc54a\ub294\ub2e4.",B.au4,B.bgw,null)
B.a7X=s(["A\uae30\uc5c5(\uc120\uc785\uc120\ucd9c\ubc95)\uc774 B\uae30\uc5c5(\ud6c4\uc785\uc120\ucd9c\ubc95)\ubcf4\ub2e4 \ub9e4\ucd9c\ucd1d\uc774\uc775\uacfc \ub2f9\uae30\uc21c\uc774\uc775\uc774 \ub354 \ud06c\uac8c \uacc4\uc0c1\ub41c\ub2e4","B\uae30\uc5c5\uc774 A\uae30\uc5c5\ubcf4\ub2e4 \ub9e4\ucd9c\ucd1d\uc774\uc775\uc774 \ub354 \ud06c\uac8c \uacc4\uc0c1\ub41c\ub2e4","\ubb3c\uac00\uc0c1\uc2b9 \uc2dc\uc5d0\ub294 \ud3c9\uac00\ubc29\ubc95\uacfc \ubb34\uad00\ud558\uac8c \ub9e4\ucd9c\ucd1d\uc774\uc775\uc774 \ud56d\uc0c1 \uac19\ub2e4","A\uae30\uc5c5\uc740 \ub9e4\ucd9c\uc6d0\uac00\uac00 \ub354 \ud06c\uac8c \uacc4\uc0c1\ub418\uc5b4 \uc774\uc775\uc774 \ub354 \ucee4\uc9c4\ub2e4"],t.s)
B.aK2=s(["\uc120\uc785\uc120\ucd9c\ubc95\uc740 \uc624\ub798\ub41c(\uc0c1\ub300\uc801\uc73c\ub85c \uc2fc) \uc6d0\uac00\uac00 \ub9e4\ucd9c\uc6d0\uac00\ub85c \uba3c\uc800 \ube60\uc838\ub098\uac00 \ub9e4\ucd9c\uc6d0\uac00\uac00 \uc791\uac8c, \uc774\uc775\uc774 \ud06c\uac8c \uacc4\uc0c1"],t.s)
B.aSK=s(["\uc7ac\uace0\uc790\uc0b0 \ud3c9\uac00\ubc29\ubc95\ubcc4 \ubb3c\uac00\uc0c1\uc2b9\uae30 \uc774\uc775 \ube44\uad50 \uc751\uc6a9"],t.s)
B.bzm=new A.a("gen_trap_ba_1","business_admin","\ud568\uc815 \ud53c\ud558\uae30",null,"\ubb3c\uac00\uac00 \uc9c0\uc18d\uc801\uc73c\ub85c \uc0c1\uc2b9\ud558\ub294 \uc0c1\ud669\uc5d0\uc11c A\uae30\uc5c5\uc740 \uc120\uc785\uc120\ucd9c\ubc95\uc744, B\uae30\uc5c5\uc740 \ud6c4\uc785\uc120\ucd9c\ubc95\uc744 \uc0ac\uc6a9\ud574 \ub3d9\uc77c\ud55c \uc7ac\uace0\ub97c \ud3c9\uac00\ud558\uace0 \uc788\ub2e4. \ub450 \uae30\uc5c5\uc758 \ub9e4\ucd9c\ucd1d\uc774\uc775\uacfc \ub2f9\uae30\uc21c\uc774\uc775\uc744 \ube44\uad50\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.a7X,0,"\ubb3c\uac00\uc0c1\uc2b9 \uc2dc \uc120\uc785\uc120\ucd9c\ubc95\uc740 \uc624\ub798\ub41c(\uc0c1\ub300\uc801\uc73c\ub85c \uc2fc) \uc6d0\uac00\uac00 \ub9e4\ucd9c\uc6d0\uac00\ub85c \uba3c\uc800 \ube60\uc838\ub098\uac00 \ub9e4\ucd9c\uc6d0\uac00\uac00 \uc791\uac8c, \uc774\uc775\uc774 \ud06c\uac8c \uacc4\uc0c1\ub418\ub294 \ubc18\uba74, \ud6c4\uc785\uc120\ucd9c\ubc95\uc740 \ucd5c\uadfc(\uc0c1\ub300\uc801\uc73c\ub85c \ube44\uc2fc) \uc6d0\uac00\uac00 \ub9e4\ucd9c\uc6d0\uac00\ub85c \uba3c\uc800 \ube60\uc838\ub098\uac00 \ub9e4\ucd9c\uc6d0\uac00\uac00 \ud06c\uac8c, \uc774\uc775\uc774 \uc791\uac8c \uacc4\uc0c1\ub41c\ub2e4. \ub530\ub77c\uc11c \uc120\uc785\uc120\ucd9c\ubc95\uc744 \uc4f0\ub294 A\uae30\uc5c5\uc758 \uc774\uc775\uc774 \ub354 \ud06c\uac8c \uacc4\uc0c1\ub41c\ub2e4.",B.aK2,B.aSK,null)
B.abP=s(["JIT\uc640 MRP \ubaa8\ub450 \ud6c4\uacf5\uc815\uc774 \ud544\uc694\ud55c \ub9cc\ud07c\ub9cc \uc804\uacf5\uc815\uc5d0 \uc694\uccad\ud558\ub294 \ud480(Pull) \ubc29\uc2dd\uc774\ub2e4","JIT\ub294 \uce78\ubc18\uc744 \ud65c\uc6a9\ud55c \ud480(Pull) \uc2dc\uc2a4\ud15c\uc73c\ub85c \ud544\uc694\ud55c \ub54c \ud544\uc694\ud55c \ub9cc\ud07c\ub9cc \uc0dd\uc0b0\ud55c\ub2e4","MRP\ub294 \uc644\uc81c\ud488 \uc0dd\uc0b0\uacc4\ud68d\uc744 \uae30\uc900\uc73c\ub85c \ud544\uc694\ud55c \uc6d0\uc790\uc7ac\xb7\ubd80\ud488\uc758 \uc18c\uc694\ub7c9\uc744 \uc5ed\uc0b0\ud558\ub294 \ud478\uc2dc(Push) \uc2dc\uc2a4\ud15c\uc774\ub2e4","JIT\ub294 \uc7ac\uace0 \ucd5c\uc18c\ud654\ub97c, MRP\ub294 \uacc4\ud68d\ub41c \uc18c\uc694\ub7c9\uc5d0 \ub530\ub978 \uc790\uc7ac \ud655\ubcf4\ub97c \uac01\uac01 \ud575\uc2ec \ubaa9\ud45c\ub85c \ud55c\ub2e4"],t.s)
B.ad5=s(["MRP\ub294 \uc644\uc81c\ud488 \uc0dd\uc0b0\uacc4\ud68d\uc744 \uba3c\uc800 \uc138\uc6b0\uace0 \uadf8\uc5d0 \ud544\uc694\ud55c \uc790\uc7ac \uc18c\uc694\ub7c9\uc744 \uc5ed\uc0b0\ud574 \ubbf8\ub9ac \uacf5\uae09\ud558\ub294 \ud478\uc2dc(Push) \ubc29\uc2dd"],t.s)
B.bbS=s(["JIT(\ud480)\uc640 MRP(\ud478\uc2dc)\uc758 \ubc29\ud5a5\uc131 \ucc28\uc774"],t.s)
B.bnQ=new A.a("gen_trap_ba_2","business_admin","\ud568\uc815 \ud53c\ud558\uae30",null,"JIT(\uc801\uc2dc\uc0dd\uc0b0)\uc640 MRP(\uc790\uc7ac\uc18c\uc694\uacc4\ud68d)\ub97c \ube44\uad50\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.abP,0,'JIT\ub294 \ud6c4\uacf5\uc815\uc758 \uc694\uccad\uc5d0 \ub530\ub77c \uc804\uacf5\uc815\uc774 \ud544\uc694\ud55c \ub9cc\ud07c\ub9cc \uc0dd\uc0b0\xb7\uacf5\uae09\ud558\ub294 \ud480(Pull) \ubc29\uc2dd\uc778 \ubc18\uba74, MRP\ub294 \uc644\uc81c\ud488 \uc0dd\uc0b0\uacc4\ud68d\uc744 \uba3c\uc800 \uc138\uc6b0\uace0 \uadf8\uc5d0 \ud544\uc694\ud55c \uc790\uc7ac \uc18c\uc694\ub7c9\uc744 \uc5ed\uc0b0\ud574 \ubbf8\ub9ac \uacf5\uae09\ud558\ub294 \ud478\uc2dc(Push) \ubc29\uc2dd\uc774\ub77c\ub294 \uc810\uc5d0\uc11c \uadfc\ubcf8\uc801\uc73c\ub85c \ub2e4\ub974\ub2e4. \ub530\ub77c\uc11c "\ub458 \ub2e4 \ud480 \ubc29\uc2dd"\uc774\ub77c\ub294 \uc124\uba85\uc740 \uc633\uc9c0 \uc54a\ub2e4.',B.ad5,B.bbS,null)
B.beM=s(["\ubd80\ucc44 \uc0ac\uc6a9\uc5d0 \ub530\ub978 \uc774\uc790\ube44\uc6a9\uc774 \uc138\uae08 \uacc4\uc0b0 \uc2dc \uc190\uae08\uc73c\ub85c \uc778\uc815\ub418\uc5b4 \uc808\uc138\ud6a8\uacfc(tax shield)\uac00 \ubc1c\uc0dd\ud558\uace0, \uc774\ub85c \uc778\ud574 \ubd80\ucc44 \uc0ac\uc6a9\uc774 \uae30\uc5c5\uac00\uce58\ub97c \ub192\uc77c \uc218 \uc788\uc74c\uc744 \ubc18\uc601\ud558\uae30 \uc704\ud574\uc11c\uc774\ub2e4","\uc644\uc804\uc790\ubcf8\uc2dc\uc7a5 \uac00\uc815\uc774 \ud56d\uc0c1 \ud604\uc2e4\uacfc \uc77c\uce58\ud558\uae30 \ub54c\ubb38\uc774\ub2e4","\uc8fc\uc2dd\ubc1c\ud589\ube44\uc6a9\uc774 \ubd80\ucc44\uc870\ub2ec\ube44\uc6a9\ubcf4\ub2e4 \ud56d\uc0c1 \ub0ae\uae30 \ub54c\ubb38\uc774\ub2e4","\ubc95\uc778\uc138\ub294 \uc790\ubcf8\uad6c\uc870\uc640 \ubb34\uad00\ud558\uac8c \uae30\uc5c5\uac00\uce58\uc5d0 \uc804\ud600 \uc601\ud5a5\uc744 \ubbf8\uce58\uc9c0 \uc54a\uae30 \ub54c\ubb38\uc774\ub2e4"],t.s)
B.aaw=s(["\ubd80\ucc44 \uc0ac\uc6a9\uc5d0 \ub530\ub978 \uc774\uc790\ube44\uc6a9\uc774 \uc138\uae08 \uacc4\uc0b0 \uc2dc \uc190\uae08\uc73c\ub85c \uc778\uc815\ub418\uc5b4 \uc808\uc138\ud6a8\uacfc(tax shield)\uac00 \ubc1c\uc0dd"],t.s)
B.a2D=s(["MM\uc774\ub860\uc758 \ubc95\uc778\uc138 \uace0\ub824 \uc218\uc815\uc774\ub860"],t.s)
B.bLy=new A.a("gen_trap_ba_3","business_admin","\ud568\uc815 \ud53c\ud558\uae30",null,"\uc790\ubcf8\uad6c\uc870\uc5d0 \uad00\ud55c MM\uc774\ub860(\ubb34\uad00\ub828\uc131 \uba85\uc81c)\uc774 \ubc95\uc778\uc138\ub97c \uace0\ub824\ud55c \uc218\uc815\uc774\ub860\uc73c\ub85c \ubc1c\uc804\ud55c \uc774\uc720\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.beM,0,"\uc644\uc804\uc790\ubcf8\uc2dc\uc7a5\uc744 \uac00\uc815\ud55c \ucd5c\ucd08 MM\uc774\ub860\uc740 \uc790\ubcf8\uad6c\uc870\uac00 \uae30\uc5c5\uac00\uce58\uc5d0 \ubb34\uad00\ud558\ub2e4\uace0 \ubcf4\uc558\uc9c0\ub9cc, \ud604\uc2e4\uc5d0\uc11c\ub294 \ubc95\uc778\uc138\uac00 \uc874\uc7ac\ud558\uace0 \ubd80\ucc44\uc758 \uc774\uc790\ube44\uc6a9\uc740 \uc190\uae08\uc73c\ub85c \uc778\uc815\ub418\uc5b4 \uc138\uae08\uc744 \uc904\uc5ec\uc8fc\ub294 \uc808\uc138\ud6a8\uacfc(tax shield)\ub97c \uac00\uc9c0\ubbc0\ub85c, \uc774\ub97c \ubc18\uc601\ud558\uba74 \ubd80\ucc44 \ube44\uc911\uc774 \ub192\uc744\uc218\ub85d \uc624\ud788\ub824 \uae30\uc5c5\uac00\uce58\uac00 \ub192\uc544\uc9c8 \uc218 \uc788\ub2e4\ub294 \uc218\uc815\uc774\ub860\uc73c\ub85c \ubc1c\uc804\ud558\uc600\ub2e4.",B.aaw,B.a2D,null)
B.a3J=s(["\ube44\uccb4\uacc4\uc801 \uc704\ud5d8(\uac1c\ubcc4\uae30\uc5c5 \uace0\uc720\uc704\ud5d8) \u2014 \uccb4\uacc4\uc801 \uc704\ud5d8(\uc2dc\uc7a5 \uc804\uccb4 \uc704\ud5d8)","\uccb4\uacc4\uc801 \uc704\ud5d8 \u2014 \ube44\uccb4\uacc4\uc801 \uc704\ud5d8","\ubca0\ud0c0 \u2014 \ud45c\uc900\ud3b8\ucc28","\ub450 \uc704\ud5d8 \ubaa8\ub450 \ubd84\uc0b0\ud22c\uc790\ub85c \uc644\uc804\ud788 \uc81c\uac70\ud560 \uc218 \uc788\ub2e4"],t.s)
B.ab6=s(["\uac1c\ubcc4\uae30\uc5c5 \uace0\uc720\uc758 \uc704\ud5d8(\ube44\uccb4\uacc4\uc801 \uc704\ud5d8)\uc740 \uc0c1\uc1c4\ub418\uc5b4 \uc81c\uac70\ud560 \uc218 \uc788\uc9c0\ub9cc, \uc2dc\uc7a5 \uc804\uccb4\uc5d0 \uacf5\ud1b5\uc73c\ub85c \uc601\ud5a5\uc744 \ubbf8\uce58\ub294 \uc704\ud5d8(\uccb4\uacc4\uc801 \uc704\ud5d8)\uc740 \uc544\ubb34\ub9ac \ubd84\uc0b0\ud22c\uc790\ub97c \ud574\ub3c4 \uc81c\uac70\ud560 \uc218 \uc5c6\ub2e4"],t.s)
B.ayv=s(["\uccb4\uacc4\uc801 \uc704\ud5d8\uacfc \ube44\uccb4\uacc4\uc801 \uc704\ud5d8\uc758 \ubd84\uc0b0\ud22c\uc790 \uc81c\uac70 \uac00\ub2a5\uc131"],t.s)
B.bxg=new A.a("gen_trap_ba_4","business_admin","\ud568\uc815 \ud53c\ud558\uae30",null,'\ud3ec\ud2b8\ud3f4\ub9ac\uc624 \uc774\ub860\uc5d0\uc11c "\ubd84\uc0b0\ud22c\uc790\ub85c \uc81c\uac70\ud560 \uc218 \uc788\ub294 \uc704\ud5d8"\uacfc "\uc81c\uac70\ud560 \uc218 \uc5c6\ub294 \uc704\ud5d8"\uc744 \uac01\uac01 \uc633\uac8c \uc9dd\uc9c0\uc740 \uac83\uc740?',B.a3J,0,"\uc11c\ub85c \uc0c1\uad00\uad00\uacc4\uac00 \ub0ae\uc740 \uc5ec\ub7ec \uc790\uc0b0\uc5d0 \ubd84\uc0b0\ud22c\uc790\ud558\uba74 \uac1c\ubcc4\uae30\uc5c5 \uace0\uc720\uc758 \uc704\ud5d8(\ube44\uccb4\uacc4\uc801 \uc704\ud5d8)\uc740 \uc0c1\uc1c4\ub418\uc5b4 \uc81c\uac70\ud560 \uc218 \uc788\uc9c0\ub9cc, \uc2dc\uc7a5 \uc804\uccb4\uc5d0 \uacf5\ud1b5\uc73c\ub85c \uc601\ud5a5\uc744 \ubbf8\uce58\ub294 \uc704\ud5d8(\uccb4\uacc4\uc801 \uc704\ud5d8)\uc740 \uc544\ubb34\ub9ac \ubd84\uc0b0\ud22c\uc790\ub97c \ud574\ub3c4 \uc81c\uac70\ud560 \uc218 \uc5c6\ub2e4. \uc774 \uccb4\uacc4\uc801 \uc704\ud5d8\uc758 \ud06c\uae30\ub97c \ub098\ud0c0\ub0b4\ub294 \uc9c0\ud45c\uac00 \ubca0\ud0c0(\u03b2)\uc774\ub2e4.",B.ab6,B.ayv,null)
B.azf=s([u.eI,"\uc784\uae08\uc740 \ub3d9\uae30\uc694\uc778\uc5d0 \ud574\ub2f9\ud558\ubbc0\ub85c \uc778\uc0c1\ub420\uc218\ub85d \ub9cc\uc871\ub3c4\uac00 \uacc4\uc18d \ube44\ub840\ud558\uc5ec \ub192\uc544\uc9c4\ub2e4","\ud5c8\uce20\ubc84\uadf8 \uc774\ub860\uc5d0\uc11c \uc704\uc0dd\uc694\uc778\uacfc \ub3d9\uae30\uc694\uc778\uc740 \uc11c\ub85c \uc644\uc804\ud788 \uac19\uc740 \ucd95 \uc704\uc5d0 \uc788\ub2e4","\uc784\uae08 \uc778\uc0c1\uc740 \ud56d\uc0c1 \uc131\ucde8\uac10\xb7\uc778\uc815\uacfc \ub3d9\uc77c\ud55c \ud6a8\uacfc\ub97c \ub0b8\ub2e4"],t.s)
