B.bFh=new A.a("gen_trap_ba_5","business_admin","\ud568\uc815 \ud53c\ud558\uae30",null,'\ud5c8\uce20\ubc84\uadf8\uc758 2\uc694\uc778\uc774\ub860\uc5d0\uc11c "\uc784\uae08 \uc778\uc0c1"\uc774 \ub3d9\uae30\ubd80\uc5ec\uc5d0 \ubbf8\uce58\ub294 \uc601\ud5a5\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?',B.azf,0,"\ud5c8\uce20\ubc84\uadf8\uc758 2\uc694\uc778\uc774\ub860\uc5d0\uc11c \uc784\uae08\xb7\uadfc\ubb34\ud658\uacbd \ub4f1\uc740 \uc704\uc0dd\uc694\uc778\uc73c\ub85c \ubd84\ub958\ub418\uc5b4, \uc774\uac83\uc774 \ubd80\uc871\ud558\uba74 \ubd88\ub9cc\uc871\uc744 \uc57c\uae30\ud558\uc9c0\ub9cc \ucda9\ubd84\ud788 \ucc44\uc6cc\uc9c4\ub2e4\uace0 \ud574\uc11c \uadf8 \uc790\uccb4\ub85c \uc801\uadf9\uc801\uc778 \ub9cc\uc871(\ub3d9\uae30\ubd80\uc5ec)\uc744 \ub9cc\ub4e4\uc5b4\ub0b4\uc9c0\ub294 \ubabb\ud55c\ub2e4. \uc131\ucde8\xb7\uc778\uc815 \ub4f1 \ub3d9\uae30\uc694\uc778\uacfc\ub294 \uc644\uc804\ud788 \ubcc4\uac1c\uc758 \ucd95\uc774\ub77c\ub294 \uc810\uc774 \uc774 \uc774\ub860\uc758 \ud575\uc2ec\uc774\ub2e4.",B.aUf,B.b7r,null)
B.atk=s(["STP(\uc2dc\uc7a5\uc138\ubd84\ud654\xb7\ud45c\uc801\uc2dc\uc7a5\uc120\uc815\xb7\ud3ec\uc9c0\uc154\ub2dd)\ub85c \ubaa9\ud45c \uace0\uac1d\uacfc \uc704\uce58\ub97c \uba3c\uc800 \uc815\ud55c \ub4a4, \uc774\ub97c \uc2e4\ud589\ud558\uae30 \uc704\ud55c \uad6c\uccb4\uc801 \uc218\ub2e8\uc73c\ub85c 4P(\uc81c\ud488\xb7\uac00\uaca9\xb7\uc720\ud1b5\xb7\ucd09\uc9c4) \uc804\ub7b5\uc744 \uc218\ub9bd\ud558\ub294 \uac83\uc774 \uc77c\ubc18\uc801 \uc21c\uc11c\uc774\ub2e4","4P\ub97c \uba3c\uc800 \uc2e4\ud589\ud55c \ub4a4 \uadf8 \uacb0\uacfc\uc5d0 \ub530\ub77c STP\ub97c \uc0ac\ud6c4\uc801\uc73c\ub85c \uacb0\uc815\ud55c\ub2e4","STP\uc640 4P\ub294 \uc11c\ub85c \uc644\uc804\ud788 \ubb34\uad00\ud55c \ubcc4\uac1c\uc758 \uc774\ub860\uc774\ub2e4","\ud3ec\uc9c0\uc154\ub2dd\uc740 4P \uc911 \uac00\uaca9\uc804\ub7b5\uc758 \ud558\uc704 \uac1c\ub150\uc774\ub2e4"],t.s)
B.a0l=s(["STP\ub85c \ubaa9\ud45c \uace0\uac1d\uacfc \uc704\uce58\ub97c \uba3c\uc800 \uc815\ud55c \ub4a4, \uc774\ub97c \uc2e4\ud589\ud558\uae30 \uc704\ud55c \uad6c\uccb4\uc801 \uc218\ub2e8\uc73c\ub85c 4P \uc804\ub7b5\uc744 \uc218\ub9bd\ud558\ub294 \uac83\uc774 \uc77c\ubc18\uc801 \uc21c\uc11c"],t.s)
B.aOd=s(["STP\uc640 4P\uc758 \uc804\ub7b5-\uc2e4\ud589 \uad00\uacc4"],t.s)
B.bEB=new A.a("gen_trap_ba_6","business_admin","\ud568\uc815 \ud53c\ud558\uae30",null,"STP \uc804\ub7b5\uacfc 4P \uc804\ub7b5\uc758 \uad00\uacc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.atk,0,'STP \uc804\ub7b5\uc740 "\ub204\uad6c\ub97c, \uc5b4\ub5a4 \uc704\uce58\ub85c" \uacf5\ub7b5\ud560\uc9c0\ub97c \uc815\ud558\ub294 \uc804\ub7b5\uc801 \ubc29\ud5a5 \uc124\uc815 \ub2e8\uacc4\uc774\uace0, 4P\ub294 \uadf8 \ubc29\ud5a5\uc744 \uc2e4\ud589\uc5d0 \uc62e\uae30\ub294 \uad6c\uccb4\uc801 \uc2e4\ud589 \uc218\ub2e8\uc774\ubbc0\ub85c, \ud1b5\uc0c1 STP\ub97c \uba3c\uc800 \uc218\ub9bd\ud55c \ud6c4 \uc774\uc5d0 \ub9de\ucdb0 4P \ubbf9\uc2a4\ub97c \uc124\uacc4\ud558\ub294 \uc21c\uc11c\ub85c \uc9c4\ud589\ub41c\ub2e4.',B.a0l,B.aOd,null)
B.a42=s([u.dX,"\uc790\uc0b0\uacfc \ube44\uc6a9 \ubaa8\ub450 \uacfc\ub300\uacc4\uc0c1\ub418\uc5b4 \ub2f9\uae30\uc21c\uc774\uc775\uc5d0\ub294 \uc601\ud5a5\uc774 \uc5c6\ub2e4","\uc790\ubcf8\uc801 \uc9c0\ucd9c\uc744 \uc218\uc775\uc801 \uc9c0\ucd9c\ub85c \ucc98\ub9ac\ud574\ub3c4 \uc7ac\ubb34\uc81c\ud45c\uc5d0\ub294 \uc544\ubb34 \uc601\ud5a5\uc774 \uc5c6\ub2e4","\uc790\uc0b0\uc774 \uacfc\ub300\uacc4\uc0c1\ub418\uace0 \ube44\uc6a9\uc774 \uacfc\uc18c\uacc4\uc0c1\ub418\uc5b4 \ub2f9\uae30\uc21c\uc774\uc775\uc774 \uacfc\ub300\uacc4\uc0c1\ub41c\ub2e4"],t.s)
B.aqB=s([u.dX],t.s)
B.aXp=s(["\uc790\ubcf8\uc801 \uc9c0\ucd9c\xb7\uc218\uc775\uc801 \uc9c0\ucd9c \uc624\ubd84\ub958\uc758 \uc7ac\ubb34\uc81c\ud45c \uc601\ud5a5"],t.s)
B.bOP=new A.a("gen_trap_ba_7","business_admin","\ud568\uc815 \ud53c\ud558\uae30",null,"\uc720\ud615\uc790\uc0b0 \ucde8\ub4dd \ud6c4 \ubc1c\uc0dd\ud55c \uc9c0\ucd9c\uc744 \uc790\ubcf8\uc801 \uc9c0\ucd9c\ub85c \ucc98\ub9ac\ud574\uc57c \ud568\uc5d0\ub3c4 \uc218\uc775\uc801 \uc9c0\ucd9c\ub85c \uc798\ubabb \ucc98\ub9ac\ud55c \uacbd\uc6b0, \uc7ac\ubb34\uc81c\ud45c\uc5d0 \ubbf8\uce58\ub294 \uc601\ud5a5\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.a42,0,"\uc6d0\ub798 \uc790\uc0b0\uc73c\ub85c \ucc98\ub9ac(\uc790\ubcf8\uc801 \uc9c0\ucd9c)\ud574\uc57c \ud560 \uc9c0\ucd9c\uc744 \ub2f9\uae30 \ube44\uc6a9(\uc218\uc775\uc801 \uc9c0\ucd9c)\uc73c\ub85c \uc798\ubabb \ucc98\ub9ac\ud558\uba74, \uadf8\ub9cc\ud07c \uc790\uc0b0\uc774 \uacfc\uc18c\uacc4\uc0c1\ub418\uace0 \ub2f9\uae30 \ube44\uc6a9\uc774 \uacfc\ub300\uacc4\uc0c1\ub418\uc5b4 \uacb0\uacfc\uc801\uc73c\ub85c \ub2f9\uae30\uc21c\uc774\uc775\uc774 \uacfc\uc18c\uacc4\uc0c1\ub418\ub294 \uc624\ub958\ub85c \uc774\uc5b4\uc9c4\ub2e4.",B.aqB,B.aXp,null)
B.Wz=s(["\ud504\ub79c\ucc28\uc774\uc988\ub294 \uacc4\uc57d\uc73c\ub85c \uacb0\ud569\ub418\ub294 \uacc4\uc57d\ud615 VMS\uc758 \ub300\ud45c \uc0ac\ub840\ub85c, \uc804\uc18d\uc801 \uc720\ud1b5 \uad6c\uc870\ub97c \ucde8\ud558\ub294 \uacbd\uc6b0\uac00 \ub9ce\ub2e4","\ud504\ub79c\ucc28\uc774\uc988\ub294 \ubcf8\uc0ac\uac00 \uc720\ud1b5\ub9dd\uc744 \uc9c1\uc811 \uc18c\uc720\ud558\ub294 \uae30\uc5c5\ud615 VMS\uc758 \ub300\ud45c \uc0ac\ub840\uc774\ub2e4","\ud504\ub79c\ucc28\uc774\uc988\ub294 \uc720\ud1b5\uacbd\ub85c \uad6c\uc131\uc6d0 \uac04 \ud798\uc758 \uc6b0\uc704\ub85c \ube44\uacf5\uc2dd \uc870\uc815\ub418\ub294 \uad00\ub9ac\ud615 VMS\uc5d0 \ud574\ub2f9\ud55c\ub2e4","\ud504\ub79c\ucc28\uc774\uc988\ub294 \uc218\uc9c1\uc801 \ub9c8\ucf00\ud305\uc2dc\uc2a4\ud15c\uc774 \uc544\ub2c8\ub77c \uc218\ud3c9\uc801 \ub9c8\ucf00\ud305\uc2dc\uc2a4\ud15c\uc758 \ub300\ud45c \uc0ac\ub840\uc774\ub2e4"],t.s)
B.ah9=s(["\ud504\ub79c\ucc28\uc774\uc988\ub294 \uacc4\uc57d\uc73c\ub85c \uacb0\ud569\ub418\ub294 \uacc4\uc57d\ud615 VMS\uc758 \ub300\ud45c \uc0ac\ub840"],t.s)
B.a2N=s(["\ud504\ub79c\ucc28\uc774\uc988\uc640 \uacc4\uc57d\ud615 VMS"],t.s)
B.bLj=new A.a("gen_trap_ba_8","business_admin","\ud568\uc815 \ud53c\ud558\uae30",null,"\ud504\ub79c\ucc28\uc774\uc988(\uac00\ub9f9\uc0ac\uc5c5)\ub97c \uc218\uc9c1\uc801 \ub9c8\ucf00\ud305\uc2dc\uc2a4\ud15c(VMS)\uc758 \uad00\uc810\uc5d0\uc11c \ubd84\ub958\ud558\uace0, \uadf8 \ud2b9\uc9d5\uc744 \uc124\uba85\ud55c \uac83\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.Wz,0,"\uc218\uc9c1\uc801 \ub9c8\ucf00\ud305\uc2dc\uc2a4\ud15c\uc740 \uae30\uc5c5\ud615(\ubcf8\uc0ac \uc9c1\uc811 \uc18c\uc720)\xb7\uacc4\uc57d\ud615(\uacc4\uc57d\uc73c\ub85c \uacb0\ud569, \ud504\ub79c\ucc28\uc774\uc988 \ub300\ud45c)\xb7\uad00\ub9ac\ud615(\ube44\uacf5\uc2dd\uc801 \ud798\uc758 \uc6b0\uc704)\uc73c\ub85c \uad6c\ubd84\ub418\ub294\ub370, \ud504\ub79c\ucc28\uc774\uc988\ub294 \uac00\ub9f9\uacc4\uc57d\uc774\ub77c\ub294 \uacc4\uc57d\uc73c\ub85c \ubcf8\uc0ac\uc640 \uac00\ub9f9\uc810\uc774 \uacb0\ud569\ub418\ub294 \uacc4\uc57d\ud615 VMS\uc758 \ub300\ud45c \uc0ac\ub840\uc774\uba70, \ud1b5\uc0c1 \uc804\uc18d\uc801 \uc720\ud1b5 \uad6c\uc870\ub97c \ucde8\ud558\ub294 \uacbd\uc6b0\uac00 \ub9ce\ub2e4.",B.ah9,B.a2N,null)
B.a9b=s(["ERP\ub294 \uc7ac\ubb34\xb7\uc0dd\uc0b0\xb7\uc778\uc0ac \ub4f1 \uc870\uc9c1 \ub0b4\ubd80 \uc790\uc6d0\xb7\ud504\ub85c\uc138\uc2a4\uc758 \ud1b5\ud569\uad00\ub9ac\uc5d0 \ucd08\uc810\uc744 \ub450\uace0, SCM\uc740 \uacf5\uae09\uc5c5\uccb4\ubd80\ud130 \uace0\uac1d\uae4c\uc9c0 \uc870\uc9c1 \uc678\ubd80\ub97c \uc544\uc6b0\ub974\ub294 \ubb3c\ub958\xb7\uc815\ubcf4 \ud750\ub984\uc758 \ud1b5\ud569\uad00\ub9ac\uc5d0 \ucd08\uc810\uc744 \ub454\ub2e4","ERP\uc640 SCM\uc740 \uc644\uc804\ud788 \ub3d9\uc77c\ud55c \ubc94\uc704\ub97c \ub2e4\ub8e8\ub294 \uc2dc\uc2a4\ud15c\uc774\ub77c \ud558\ub098\ub9cc \ub3c4\uc785\ud574\ub3c4 \ucda9\ubd84\ud558\ub2e4","SCM\uc740 \uc870\uc9c1 \ub0b4\ubd80 \uc790\uc6d0\uad00\ub9ac\uc5d0, ERP\ub294 \uacf5\uae09\uc5c5\uccb4\uc640\uc758 \uad00\uacc4\uad00\ub9ac\uc5d0 \ucd08\uc810\uc744 \ub454\ub2e4","ERP\ub294 \uace0\uac1d\uad00\uacc4\uad00\ub9ac(CRM)\uc758 \ud558\uc704 \uc2dc\uc2a4\ud15c\uc774\ub2e4"],t.s)
B.asq=s(["ERP\ub294 \uc7ac\ubb34\xb7\uc0dd\uc0b0\xb7\uc778\uc0ac \ub4f1 \uc870\uc9c1 \ub0b4\ubd80 \uc790\uc6d0\xb7\ud504\ub85c\uc138\uc2a4\uc758 \ud1b5\ud569\uad00\ub9ac\uc5d0 \ucd08\uc810\uc744 \ub450\uace0, SCM\uc740 \uacf5\uae09\uc5c5\uccb4\ubd80\ud130 \uace0\uac1d\uae4c\uc9c0 \uc870\uc9c1 \uc678\ubd80\ub97c \uc544\uc6b0\ub974\ub294 \ubb3c\ub958\xb7\uc815\ubcf4 \ud750\ub984\uc758 \ud1b5\ud569\uad00\ub9ac\uc5d0 \ucd08\uc810"],t.s)
