B.bHR=new A.a("gen_trap_kh_1","korean_history","\ud568\uc815 \ud53c\ud558\uae30",null,"\uace0\ub824 \uad11\uc885\uacfc \uc131\uc885\uc758 \uc815\ucc45\uc744 \uc11c\ub85c \ubc14\uafd4 \ud5f7\uac08\ub9ac\uae30 \uc26c\uc6b4\ub370, \ub2e4\uc74c \uc911 \uad11\uc885\uc758 \uc815\ucc45\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.a6s,0,'\ub178\ube44\uc548\uac80\ubc95\xb7\ub3c5\uc790 \uc5f0\ud638 \uc0ac\uc6a9\uc740 \uad11\uc885\uc758 \uc815\ucc45\uc774\ub2e4. 12\ubaa9 \uc124\uce58\xb7\uc9c0\ubc29\uad00 \ud30c\uacac\xb7\uc2dc\ubb34 28\uc870 \uc218\uc6a9\uc740 \uc131\uc885\uc758 \uc815\ucc45\uc73c\ub85c, \ub450 \uc655 \ubaa8\ub450 "\uc655\uad8c \uac15\ud654"\ub77c\ub294 \uacf5\ud1b5 \ubaa9\ud45c\ub97c \uac00\uc84c\ub2e4\ub294 \uc810\uc5d0\uc11c \uc815\ucc45\uc774 \uc790\uc8fc \ud5f7\uac08\ub9ac\uc9c0\ub9cc, \uad11\uc885\uc740 \ud638\uc871 \uc5b5\uc81c(\ub178\ube44\uc548\uac80\ubc95), \uc131\uc885\uc740 \uc720\uad50\uc801 \ud1b5\uce58 \uccb4\uc81c \uc815\ube44(12\ubaa9\xb7\uc9c0\ubc29\uad00)\ub77c\ub294 \ubc29\uc2dd\uc758 \ucc28\uc774\ub85c \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4.',B.b03,B.aD1,null)
